(80, 0, 'ab_minijoboffers', 1, '1.0.0', 2385, 244, 'Mini Job Offers', 'A simple module to mange and display job offers.\r\nEach single job offer is stored with jobtitle, date, jobdescription, tasks, demands and optional a footer.\r\nThe plugin supports mulitlanguage and can be configured via template.', 0, 0, 3, 1112769592, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:3:"cms";s:0:"";}}', 'Andre Bilsing', 'ab@t3werk.de', 'abilsing', 'ca2875aea1a6dd08271150b80db9c132', '', 't3werk', 1000000, 0, 0),
