(161, 0, 'af_css_select', 1, '0.1.0', 1482, 481, 'Advanced Page Stylesheet Selection', 'Allows to select stylesheets for your pages by adding stylesheet records to the page. You can specify media types etc. per stylesheet, add alternate stylesheets (relies on browsers style menu, no JS style switcher included) etc.', 1, 0, 2, 1139583593, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:3:"cms";s:0:"";}}', 'Andreas Ferber', 'af@chaos-agency.de', 'aferber', '17264f3919e3cd4f0d1b45a71df06dd3', 'Initial upload of new extension', '', 1000, 0, 0),
