(225, 0, 'ameos_fe_singleauth', 1, '1.0.0', 398, 397, 'Ameos FE single auth', 'ameos_fe_singleauth', 0, 0, 2, 1138713485, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";}}', 'Jrme Schneider', 'typo3dev@ameos.com', 'r.geyer', 'a5a86bcd3594df9209540cfb7f194157', 'First Upload', '', 1000000, 1, 0),
(226, 0, 'ameos_formidable', 1, '0.1.0', 7738, 129, 'Ameos Formidable', 'Ameos Form manager', 0, -1, 3, 1132851482, 'a:1:{s:7:"depends";a:5:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:3:"cms";s:0:"";s:11:"api_macmade";s:0:"";s:8:"cc_debug";s:0:"";}}', 'Jrme Schneider', 'typo3dev@ameos.com', 'r.geyer', '6bd88fd3ef1cba8e262b0c84006d9599', 'An XML driven API that allows developers to quickly and easily realize Front end Forms for their extensions.', '', 1000, 0, 0),
(227, 0, 'ameos_formidable', 1, '0.2.0', 7738, 157, 'Ameos Formidable', 'Form manager API', 0, -1, 3, 1135350845, 'a:1:{s:7:"depends";a:5:{s:5:"typo3";s:11:"0.0.2-0.0.2";s:3:"php";s:11:"0.0.2-0.0.2";s:3:"cms";s:0:"";s:11:"api_macmade";s:0:"";s:18:"rlmp_dateselectlib";s:0:"";}}', 'Jrme Schneider', 'typo3dev@ameos.com', 'r.geyer', '1c3f2445e36daa8736b2e515e3b6c04c', 'Implementation of the Actionlet concept ; allows FORMidable to execute several specific tasks ( sending mails ) with data\r\nImplementation of a DB validator that checks DB related conditions ( unicity, ... )\r\nModification du principe du validator : un ele', '', 2000, 0, 0),
(228, 0, 'ameos_formidable', 1, '0.3.0', 7738, 66, 'Ameos Formidable', 'Form manager API', 0, -1, 3, 1138979369, 'a:0:{}', 'Jrme Schneider', 'typo3dev@ameos.com', 'r.geyer', '5aa51e30d63b4fa69f747413d8e8730f', ' Its now possible to define /template/path and /addresses properties using an userobj callback\r\n /subject, /fromname and /replytoname properties are now localizable using LLL reference\r\n Added REDIRECT actionlet\r\n The main extension can now force FOR', '', 3000, 0, 0),
(229, 0, 'ameos_formidable', 1, '0.4.0', 7738, 440, 'Ameos Formidable', 'Form manager API', 0, -1, 3, 1139311115, 'a:1:{s:7:"depends";a:5:{s:5:"typo3";s:11:"0.0.3-0.0.3";s:3:"php";s:11:"0.0.3-0.0.3";s:3:"cms";s:0:"";s:11:"api_macmade";s:0:"";s:18:"rlmp_dateselectlib";s:0:"";}}', 'Jrme Schneider', 'typo3dev@ameos.com', 'r.geyer', 'e36911996fe6c6e0af29cee1b0db670f', '', '', 4000, 0, 0),
(230, 0, 'ameos_formidable', 1, '0.5.0', 7738, 647, 'Ameos Formidable', 'Framework for development of form-oriented applications\n Field validation\n One form/several tables\n Data creation / edition / searching / browsing\n And much more\n\n Now all you have to install is this extension and rlmp_dateselectlib\n\n SEE ameos_demo', 1, -1, 4, 1148316350, 'a:1:{s:7:"depends";a:4:{s:3:"cms";s:0:"";s:18:"rlmp_dateselectlib";s:0:"";s:3:"php";s:6:"3.0.0-";s:5:"typo3";s:6:"3.8.0-";}}', 'Jerome Schneider', 'typo3dev@ameos.com', 'r.geyer', '511ddda23867e8ea375a4a466c711fbd', 'Formidable changelog\n	NOTE : we STRONGLY RECOMMEND that you have a look at the demo extension ameos_demoformidable050\n	- complete rewrite of the data engine ; easier to use and to maintain\n	- all element are now part of main API ( nut custom elements ca', '', 5000, 0, 0),
(231, 0, 'ameos_formidable', 1, '0.6.0', 7738, 328, 'Ameos Formidable', 'Form-oriented API', 1, -1, 4, 1167426688, 'a:0:{}', 'Jerome Schneider', 'typo3dev@ameos.com', 'r.geyer', 'b4d1a2adb619629406d333e45230d0bc', 'Lots of new possibilities, improved debug functions.\nSupport is provided on mailing lists - typo3.projets.formidable at news.netfielders.de', '', 6000, 0, 0),
(232, 0, 'ameos_formidable', 1, '0.7.0', 7738, 1863, 'Ameos Formidable', 'Form-oriented API', 1, -1, 4, 1171385826, 'a:0:{}', 'Jerome Schneider', 'typo3dev@ameos.com', 'r.geyer', 'ec6e56b1f53e415234e42e52133f9709', '- many corrections\r\n- new javascript layout, compatible with IE7, Safari and Opera\r\n', '', 7000, 0, 0),
