INSERT INTO `tx_extensionmanager_domain_model_extension` (`uid`, `pid`, `extension_key`, `repository`, `version`, `alldownloadcounter`, `downloadcounter`, `title`, `description`, `state`, `review_state`, `category`, `last_updated`, `serialized_dependencies`, `author_name`, `author_email`, `ownerusername`, `md5hash`, `update_comment`, `authorcompany`, `integer_version`, `current_version`, `lastreviewedversion`) VALUES
(330, 0, 'ast_countdown', 1, '1.0.0', 3735, 848, 'Countdown', 'Provides a graphical countdown (output format: d:h:i:s) to a specific date. The date can be set by the Constant Editor easily and is transfered to a Javascript date object, so start counting the month beginning at 0 for january and so on!', 2, 0, 3, 1127112923, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:3:"cms";s:0:"";}}', 'Andre Steiling', 'steiling@pilotprojekt.com', 'commodore', '3bf39b18b3b0ad179dd574860afaacf0', 'Initial release, stable!', 'high StandArt, PILOTprojekt }', 1000000, 0, 0),
(331, 0, 'ast_countdown', 1, '1.0.1', 3735, 236, 'Countdown', 'Provides a graphical countdown (output format: d:h:i:s) to a specific date. The date can be set by the Constant-Editor easily and is transfered to a Javascript date object, so start counting the month beginning at 0 for january and so on! For example see', 2, 0, 3, 1146743892, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:3:"php";s:11:"4.3.0-4.4.2";s:5:"typo3";s:11:"3.7.0-4.0.0";}}', 'Andre Steiling', 'steiling@pilotprojekt.com', 'commodore', 'b9ed004c5c8e62051be56d3704650eed', 'Fixed a small bug, so you can now edit ALL Typoscript parameters by the Constant-Editor  cleaned up a little bit ...', 'high StandArt, PILOTprojekt }', 1000001, 0, 0),
(332, 0, 'ast_countdown', 1, '1.0.2', 3735, 342, 'Countdown', 'Provides a graphical countdown (output format: d:h:i:s) to a specific date. The date can be set by the Constant-Editor easily and is transfered to a Javascript date object, so start counting the month beginning at 0 for january and so on! For example see', 2, 0, 3, 1146828439, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:3:"php";s:11:"4.3.0-4.4.2";s:5:"typo3";s:11:"3.7.0-4.0.0";}}', 'Andre Steiling', 'steiling@pilotprojekt.com', 'commodore', '3268b588c5cc42fc58324394b04e2811', '', 'high StandArt, PILOTprojekt }', 1000002, 0, 0),
(333, 0, 'ast_countdown', 1, '1.1.0', 3735, 277, 'Countdown', 'Provides a graphical countdown (output format: d:h:i:s) to a specific date. The date can be set by the Constant-Editor easily and is transfered to a Javascript date object, so start counting the month beginning at 0 for january and so on! For example see', 2, 0, 3, 1154017741, 'a:0:{}', 'Andre Steiling', 'steiling@pilotprojekt.com', 'commodore', '7ac4fdcaf791187ff090d22180fb2782', 'Now there is support for three digits for the days! Simply use the Constant-Editor, you will find a new constant called "Day digit length" and READ the description ;-)', 'high StandArt, PILOTprojekt }', 1001000, 0, 0),
(334, 0, 'ast_countdown', 1, '1.2.0', 3735, 457, 'AST Countdown', 'Dispalys a graphical countdown to a given date. Output format is (d)dd:hh:ii:ss. You can select if you want to show rather two or three digits for the days.', 2, 0, 3, 1156270259, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:3:"php";s:11:"4.3.0-4.4.2";s:5:"typo3";s:11:"3.7.0-4.0.1";}}', 'Andre Steiling', 'steiling@pilotprojekt.com', 'commodore', 'e82c1dd4901b5311a5fc745b951eb86f', 'Added Flexforms support for the plugin configuration (Typoscript is still there) and a fast-written documentation.', 'high StandArt, PILOTprojekt }', 1002000, 0, 0),
(335, 0, 'ast_countdown', 1, '1.2.1', 3735, 277, 'AST Countdown', 'Dispalys a graphical countdown to a given date. Output format is (d)dd:hh:ii:ss. You can select if you want to show rather two or three digits for the days.', 2, 0, 3, 1169498664, 'a:0:{}', 'Andre Steiling', 'steiling@pilotprojekt.com', 'commodore', '746ce58d9e0242253b380792aa2a4c79', 'Bugfix: Now the counter computes the 24-hour format of an hour - CORRECTLY! Thx to Karl Hevera for reporting.', 'high StandArt, PILOTprojekt }', 1002001, 0, 0),
(336, 0, 'ast_countdown', 1, '1.2.2', 3735, 450, 'AST Countdown', 'Dispalys a graphical countdown to a given date. Output format is (d)dd:hh:ii:ss. You can select if you want to show rather two or three digits for the days.', 2, 0, 3, 1173782795, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:3:"php";s:11:"4.3.0-4.4.2";s:5:"typo3";s:11:"3.7.0-4.0.1";}}', 'Andre Steiling', 'steiling@pilotprojekt.com', 'commodore', 'ef7ffc22e0befbad0bc8da05b0568583', 'Bugfix: Month may did not work correctly, counter crashed by invaild javascript.', 'high StandArt, PILOTprojekt }', 1002002, 0, 0),
