(626, 0, 'perfectlightbox', 1, '2.2.1', 31341, 255, 'Perfect Lightbox2', 'Click-enlarge images with PROTACULOUS/LIGHTBOX or MOOTOOLS/SLIMBOX in Typo3. Single images, imagesets, presentation mode and slideshow supported. Options can be set for each content-element. No XCLASS, just typoscript. Valid html. Flexible configuration.', 2, 0, 3, 1193394514, 'a:0:{}', 'Benjamin Niediek', 'ben@channel-eight.de', 'niediek', '6be0b2e026ef5626a0454461447e861c', 'Added danish translation, captionsplit now works with dam_ttnews, updated manual', '', 2002001, 0, 0),
