(660, 0, 'wec_map', 1, '1.0.1', 8919, 241, 'WEC Map', 'Mapping extension that connects to geocoding databases and Google Maps API.', 2, -1, 3, 1171408904, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:6:"3.0.0-";s:5:"typo3";s:6:"3.8.0-";}}', 'Web-Empowered Church Team', 'map@webempoweredchurch.org', 'jbartels', 'e9813927c5eb3746fe1750a91383827b', '-[NEW] Add ability to set initial map type\r\n-[NEW] Address fields are now read from the TCA\r\n-[FIX] Some typos in localization\r\n-[FIX] Replace short open tag with full open tag\r\n-[FIX] Progress bar in Batch Geocoder now renders correctly', 'Foundation For Evangelism', 1000001, 0, 0),
(661, 0, 'wec_map', 1, '1.1.0', 8919, 249, 'WEC Map', 'Mapping extension that connects to geocoding databases and Google Maps API.', 2, -1, 3, 1173566935, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:6:"3.0.0-";s:5:"typo3";s:6:"3.8.0-";}}', 'Web-Empowered Church Team', 'map@webempoweredchurch.org', 'jbartels', '03b54877c2f9b2a750c73c9e07275744', '[NEW] Improved WEC Admin Geocode Admin including record filter, inline editing of records, sortable tables columns, speed improvements and overall design improvements, all using AJAX\r\n[NEW] API now supports tabs for marker info windows. See "Using the WEC', 'Foundation For Evangelism', 1001000, 0, 0),
(662, 0, 'wec_map', 1, '1.1.1', 8919, 236, 'WEC Map', 'Mapping extension that connects to geocoding databases and Google Maps API.', 2, -1, 3, 1174766604, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"3.0.0-0.0.0";s:5:"typo3";s:11:"3.8.0-0.0.0";}}', 'Web-Empowered Church Team', 'map@webempoweredchurch.org', 'jbartels', 'ada2e96e12fa654b8c51fe127bc0afd5', '[NEW] Add status indicator image when saving a cache record\r\n[FIX] Improve rendering of record table with long coordinates\r\n[FIX] Bug that caused the current cache records buttons to freeze\r\n', 'Foundation For Evangelism', 1001001, 0, 0),
(663, 0, 'wec_map', 1, '1.1.2', 8919, 275, 'WEC Map', 'Mapping extension that connects to geocoding databases and Google Maps API.', 2, -1, 3, 1174946877, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"3.0.0-0.0.0";s:5:"typo3";s:11:"3.8.0-0.0.0";}}', 'Web-Empowered Church Team', 'map@webempoweredchurch.org', 'jbartels', '3f70f0170a4181e521279a91dda0f151', '[FIX] Path error resulting in Prototype not being included properly in the BE\r\n[FIX] Extension can now be installed globally without errors', 'Foundation For Evangelism', 1001002, 0, 0),
(664, 0, 'wec_map', 1, '1.2.0', 8919, 306, 'WEC Map', 'Mapping extension that connects to geocoding databases and Google Maps API.', 2, -1, 3, 1181756566, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"3.0.0-0.0.0";s:5:"typo3";s:11:"3.8.0-0.0.0";}}', 'Web-Empowered Church Team', 'map@webempoweredchurch.org', 'jbartels', 'f64b6f21c26c7ffb752b9e69289a0f49', '[NEW] More than one map can now be put on one page.\r\n!!! To make this possible, the id of the containing div had to be made unique. That means if you used it in your CSS to style the map you will have to change it from the id &8220;map&8221; to the clas', 'Foundation For Evangelism', 1002000, 0, 0),
(665, 0, 'wec_map', 1, '1.3.0', 8919, 107, 'WEC Map', 'Mapping extension that connects to geocoding databases and Google Maps API.', 2, -1, 3, 1185474386, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"3.0.0-0.0.0";s:5:"typo3";s:11:"3.8.0-0.0.0";}}', 'Web-Empowered Church Team', 'map@webempoweredchurch.org', 'jbartels', 'b266f1f4d293f5f771592064d2d09663', '[NEW] Domain management for API keys so the extension can be used on multidomain setups.\r\n[NEW] Add map controls to the FE User Map in the BE.\r\n[NEW] Directions are now built into the map, complete with written driving directions.\r\n[NEW] Add method that a', 'Foundation For Evangelism', 1003000, 0, 0),
