(850, 0, 'cal', 1, '0.8.0', 40568, 95, 'Calendar Base', 'A calendar combining all the functions of the existing calendar extensions plus adding some new features. It is based on the ical standard', 0, -1, 3, 1139847686, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:3:"cms";s:0:"";}}', 'Mario Matzulla, Jeff Segars', 'mario@matzullas.de, jeff@webempoweredchurch.org', 'mario_matzulla', '070d718614ef84db74cd1a732cb1ce81', ' fixed bug with recurring events on list view\r\n added max_events for list view', '', 8000, 0, 0),
(851, 0, 'cal', 1, '0.8.1', 40568, 147, 'Calendar Base', 'A calendar combining all the functions of the existing calendar extensions plus adding some new features. It is based on the ical standard', 0, -1, 3, 1139898887, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:3:"cms";s:0:"";}}', 'Mario Matzulla, Jeff Segars', 'mario@matzullas.de, jeff@webempoweredchurch.org', 'mario_matzulla', '1a2f3fe2cd4a9582db3b656688153e69', ' merged missing finnish and dutch translations - sorry guys', '', 8001, 0, 0),
(852, 0, 'cal', 1, '0.8.2', 40568, 545, 'Calendar Base', 'A calendar combining all the functions of the existing calendar extensions plus adding some new features. It is based on the ical standard', 0, -1, 3, 1140271329, 'a:0:{}', 'Mario Matzulla, Jeff Segars', 'mario@matzullas.de, jeff@webempoweredchurch.org', 'mario_matzulla', '3a40dff8bd03de7a81d87a8c86eef94b', 'fixed the bug in the locallang.php file', '', 8002, 0, 0),
(853, 0, 'cal', 1, '0.16.0', 40568, 217, 'Calendar Base', 'A calendar combining all the functions of the existing calendar extensions plus adding some new features. It is based on the ical standard', 1, -1, 3, 1197923089, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"4.0.0-0.0.0";s:5:"typo3";s:12:"3.8.0-4.1.99";}}', 'Mario Matzulla, Jeff Segars', 'mario@matzullas.de, jeff@webempoweredchurch.org', 'mario_matzulla', '468e042117217546cc7706e8cf647768', ' Full localization of records.\n Added event attendees and basic scheduling.\n Converted all internal date handling to PEAR date.\n Converted date storage from UNIX timestamp to yyyymmdd.\n Added support for dates prior to 1970 and after 2030 with the tw', '', 16000, 0, 0),
(854, 0, 'cal', 1, '0.9.0', 40568, 1063, 'Calendar Base', 'A calendar combining all the functions of the existing calendar extensions plus adding some new features. It is based on the ical standard', 0, -1, 3, 1141245056, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:3:"php";s:6:"3.0.0-";s:5:"typo3";s:11:"3.8.0-4.0.0";}}', 'Mario Matzulla, Jeff Segars', 'mario@matzullas.de, jeff@webempoweredchurch.org', 'mario_matzulla', 'a6ade0e39b1fba180494fab910130ed1', 'Added support for category colors\nConfiguration of the different page ids is possible\nFrench translation (thx Jean-Michel Hubert)\nPlease report bugs/comments to t3-calendar newsgroup', '', 9000, 0, 0),
(855, 0, 'cal', 1, '0.10.0', 40568, 406, 'Calendar Base', 'A calendar combining all the functions of the existing calendar extensions plus adding some new features. It is based on the ical standard', 1, -1, 3, 1147070285, 'a:1:{s:7:"depends";a:5:{s:3:"cms";s:0:"";s:10:"tt_address";s:0:"";s:18:"rlmp_dateselectlib";s:0:"";s:3:"php";s:6:"3.0.0-";s:5:"typo3";s:11:"3.8.0-4.0.0";}}', 'Mario Matzulla, Jeff Segars', 'mario@matzullas.de, jeff@webempoweredchurch.org', 'mario_matzulla', '8eca53d9f22b9b469b24aa917fa001ae', 'Current features:\n- Based on the iCal standard\n- Import and export of ICS/iCal files and feeds\n- Recurring events and exceptions\n- Event monitoring and notification for frontend users.\n- Default Views: List, Day, Week, Month, Year, Organizer, Location\n- O', '', 10000, 0, 0),
(856, 0, 'cal', 1, '0.11.0', 40568, 764, 'Calendar Base', 'A calendar combining all the functions of the existing calendar extensions plus adding some new features. It is based on the ical standard', 1, -1, 3, 1147878156, 'a:1:{s:7:"depends";a:5:{s:3:"cms";s:0:"";s:10:"tt_address";s:0:"";s:18:"rlmp_dateselectlib";s:0:"";s:3:"php";s:6:"3.0.0-";s:5:"typo3";s:11:"3.8.0-4.0.0";}}', 'Mario Matzulla, Jeff Segars', 'mario@matzullas.de, jeff@webempoweredchurch.org', 'mario_matzulla', '13f3c260dc65820484e091f15aa5a11d', 'Several bugs fixed  new features added:- Events as link - Search - Login. More infos on typo3-calendar.org', '', 11000, 0, 0),
(857, 0, 'cal', 1, '0.12.0', 40568, 324, 'Calendar Base', 'A calendar combining all the functions of the existing calendar extensions plus adding some new features. It is based on the ical standard', 1, -1, 3, 1155196286, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:6:"3.0.0-";s:5:"typo3";s:11:"3.8.0-4.0.0";}}', 'Mario Matzulla, Jeff Segars', 'mario@matzullas.de, jeff@webempoweredchurch.org', 'mario_matzulla', '28ed5f646d9e0d35edc55edb62d7abbf', 'Please visite http://www.svn.webempoweredchurch.org:3000/calendar/ or http://typo3-calendar.org/ for details', '', 12000, 0, 0),
(858, 0, 'cal', 1, '0.12.1', 40568, 786, 'Calendar Base', 'A calendar combining all the functions of the existing calendar extensions plus adding some new features. It is based on the ical standard', 1, -1, 3, 1155244262, 'a:1:{s:7:"depends";a:3:{s:3:"php";s:6:"3.0.0-";s:5:"typo3";s:12:"3.8.0-4.0.99";s:18:"rlmp_dateselectlib";s:0:"";}}', 'Mario Matzulla, Jeff Segars', 'mario@matzullas.de, jeff@webempoweredchurch.org', 'mario_matzulla', 'd7ec20d58a7690e4fc459dc6d732b7d3', 'Please visit http://www.svn.webempoweredchurch.org:3000/calendar/ or http://typo3-calendar.org/ for details', '', 12001, 0, 0),
