(860, 0, 'cal', 1, '0.13.1', 40568, 992, 'Calendar Base', 'A calendar combining all the functions of the existing calendar extensions plus adding some new features. It is based on the ical standard', 1, -1, 3, 1158869010, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:6:"3.0.0-";s:5:"typo3";s:12:"3.8.0-4.0.99";}}', 'Mario Matzulla, Jeff Segars', 'mario@matzullas.de, jeff@webempoweredchurch.org', 'mario_matzulla', 'e814e4b3fcb4ac243108fd63f25d7ec2', 'Fixed bug that prevented events from showing.\nAdded security checks for piVars.', '', 13001, 0, 0),
