(922, 0, 'calendar', 1, '0.0.1', 16842, 38, 'Extended Calendar', 'A full-featured calendar, based on advCalendar', 0, 0, 3, 1084185660, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:3:"cms";s:0:"";}}', 'Alexander Langer, Juraj Benadik (GASTAN), Mads-Peter Brunn Jensen', 'alex@big.endian.de', 'doegi', 'a6f93abf68ba29900b97d1f10ec74ec1', 'First working version. Im uploading it already now otherwise my extension key will expire ;-)\r\n\r\n This is rather production ready except:\r\n- eventsview misses proper wraps  CSS\r\n- category select in the months view doesnt yet work\r\n- only views availa', '', 1, 0, 0),
(923, 0, 'calendar', 1, '0.1.0', 16842, 35, 'Extended Calendar', 'A full-featured calendar, based on advCalendar', 1, 0, 3, 1084291491, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:3:"cms";s:0:"";}}', 'Alexander Langer, Juraj Benadik (GASTAN), Mads-Peter Brunn Jensen', 'alex@big.endian.de', 'doegi', '9d4986b24e13890bbd3aa9f655d79881', 'Added "teaser", "organizer", "organizer_email", "url" and "image" fields to events, "image" field to the category.\r\n\r\nMonth/Day/Event view are now fully functional.\r\nHowever, Im going to change stuff a bit soon to make it possible to fetch per-event fiel', '', 1000, 0, 0),
(924, 0, 'calendar', 1, '0.2.0', 16842, 25, 'Extended Calendar', 'A full-featured calendar, based on advCalendar', 1, 0, 3, 1084299164, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:3:"cms";s:0:"";}}', 'Alexander Langer, Juraj Benadik (GASTAN), Mads-Peter Brunn Jensen', 'alex@big.endian.de', 'doegi', 'ed6a7023c00d885299dfb8f3fd8abce2', 'Fixed the category selection.\r\nNow possible to use event-stuff from every view, i.e. display teaser, or image, or whatever you want.\r\n', '', 2000, 0, 0),
(925, 0, 'calendar', 1, '0.3.0', 16842, 21, 'Extended Calendar', 'A full-featured calendar, based on advCalendar', 1, 0, 3, 1084304675, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:3:"cms";s:0:"";}}', 'Alexander Langer, Juraj Benadik (GASTAN), Mads-Peter Brunn Jensen', 'alex@big.endian.de', 'doegi', '09852f3388c47c3f7d4d37aa5c8adfe4', 'Added an "Upcoming Events" view, similar to LATEST display in tt_news. (the same as the mc_advcalendar_extended extension does).\r\nWorks nice.', '', 3000, 0, 0),
(926, 0, 'calendar', 1, '0.3.1', 16842, 99, 'Extended Calendar', 'A full-featured calendar, based on advCalendar', 1, 0, 3, 1084552033, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:3:"cms";s:0:"";}}', 'Alexander Langer, Juraj Benadik (GASTAN), Mads-Peter Brunn Jensen', 'alex@big.endian.de', 'doegi', '0711cd1cec72d3d0e3627496715d1b85', '', '', 3001, 0, 0);
