(927, 0, 'calendar', 1, '0.3.2', 16842, 51, 'Extended Calendar', 'A full-featured calendar, based on advCalendar', 1, 0, 3, 1084747172, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:3:"cms";s:0:"";}}', 'Alexander Langer, Juraj Benadik (GASTAN), Mads-Peter Brunn Jensen', 'alex@big.endian.de', 'doegi', '52dbb020a91e11ba8c49f86012dd8617', '', '', 3002, 0, 0),
(928, 0, 'calendar', 1, '0.4.0', 16842, 207, 'Extended Calendar', 'A full-featured calendar, based on advCalendar', 1, 0, 3, 1084792726, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"0.0.2-0.0.2";s:3:"php";s:11:"0.0.2-0.0.2";s:3:"cms";s:0:"";}}', 'Alexander Langer, Juraj Benadik (GASTAN), Mads-Peter Brunn Jensen', 'alex@big.endian.de', 'doegi', 'c4140d49366702bf307d235833e01bac', 'Add Week view - see notes.\r\n\r\nadd Overview view to other views, e.g. all events of the month listed at the months bottom. same for week.', '', 4000, 0, 0),
(929, 0, 'calendar', 1, '0.5.0', 16842, 87, 'Extended Calendar', 'A full-featured calendar.  ATTENTION UPGRADERS: the template file and typoscript code is not backwards-compatible!', 1, 0, 3, 1085566941, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"0.0.2-0.0.2";s:3:"php";s:11:"0.0.2-0.0.2";s:3:"cms";s:0:"";}}', 'Alexander Langer, Juraj Benadik (GASTAN), Mads-Peter Brunn Jensen', 'alex@big.endian.de', 'doegi', '4fc1782af4931002647c3a8825f9d3ac', 'Complete overhaul.  This baby is now so customizable, you wont believe it.\r\nHowever, that also means that the typoscript code and the template file are NOT backwards compatible!  Please pay attention when upgrading!', '', 5000, 0, 0),
(930, 0, 'calendar', 1, '0.5.1', 16842, 24, 'Extended Calendar', 'A full-featured calendar.  ATTENTION UPGRADERS: the template file and typoscript code is not backwards-compatible!', 1, 0, 3, 1085566952, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"0.0.2-0.0.2";s:3:"php";s:11:"0.0.2-0.0.2";s:3:"cms";s:0:"";}}', 'Alexander Langer, Juraj Benadik (GASTAN), Mads-Peter Brunn Jensen', 'alex@big.endian.de', 'doegi', '6c2362d59195520963bfbe9c28c7cbc4', '', '', 5001, 0, 0),
(931, 0, 'calendar', 1, '0.5.2', 16842, 24, 'Extended Calendar', 'A full-featured calendar.  ATTENTION UPGRADERS: the template file and typoscript code is not backwards-compatible!', 1, 0, 3, 1085567575, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"0.0.3-0.0.3";s:3:"php";s:11:"0.0.3-0.0.3";s:3:"cms";s:0:"";}}', 'Alexander Langer, Juraj Benadik (GASTAN), Mads-Peter Brunn Jensen', 'alex@big.endian.de', 'doegi', '8706af33340ee96f75fa2362782d85d8', 'small fix: allow organizer to be added on standard tables', '', 5002, 0, 0),
(932, 0, 'calendar', 1, '0.5.3', 16842, 1184, 'Extended Calendar', 'A full-featured calendar.  ATTENTION UPGRADERS: the template file and typoscript code is not backwards-compatible!', 1, 0, 3, 1085593457, 'a:0:{}', 'Alexander Langer, Juraj Benadik (GASTAN), Mads-Peter Brunn Jensen', 'alex@big.endian.de', 'doegi', 'df490fd97125b9dd95a36ed04127af75', 'Fix links of events, which didnt work when you had caching enabled.   Unfortunately, when using the UpcomingEvents feature together with PIDDisplayEvent, i.e. for the upcoming events on the startpage, we cant use caching.  This is because typo3s linkin', '', 5003, 0, 0),
(933, 0, 'calendar', 1, '0.5.4', 16842, 393, 'Extended Calendar', 'A full-featured calendar.  ATTENTION UPGRADERS: the template file and typoscript code is not backwards-compatible!', 1, 0, 3, 1099318889, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"0.0.4-0.0.4";s:3:"php";s:11:"0.0.4-0.0.4";s:3:"cms";s:0:"";}}', 'Alexander Langer, Juraj Benadik (GASTAN), Mads-Peter Brunn Jensen', 'alex@big.endian.de', 'doegi', '1dfb6d516eac8b11c33e66782e3e301e', 'Fix bug with "What to display" and add icon sets by Ingo Renner', '', 5004, 0, 0),
(934, 0, 'calendar', 1, '1.0.0', 16842, 249, 'Extended Calendar', 'A full-featured calendar.', 2, 0, 3, 1103137396, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"0.0.4-0.0.4";s:3:"php";s:11:"0.0.4-0.0.4";s:3:"cms";s:0:"";}}', 'Alexander Langer', 'alex@big.endian.de', 'doegi', '8515d86f4d2a72e7d2349d7859168741', 'Completely overhaul: - Fix some bad bugs with timezones - Add full support for recurring events, including exceptions - every view is only a TypoScript TEMPLATE now, which means you can do almost everything you want with it - Add support for cool realurl', '', 1000000, 0, 0),
(935, 0, 'calendar', 1, '1.0.1', 16842, 24, 'Extended Calendar', 'A full-featured calendar.', 2, 0, 3, 1103568833, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"0.0.4-0.0.4";s:3:"php";s:11:"0.0.4-0.0.4";s:3:"cms";s:0:"";}}', 'Alexander Langer', 'alex@big.endian.de', 'doegi', 'daaa055d25edfff60e8ad275d52e589d', 'Fix a display bug for non-CET timezones.', '', 1000001, 0, 0),
(936, 0, 'calendar', 1, '1.0.2', 16842, 245, 'Extended Calendar', 'A full-featured calendar.', 2, 0, 3, 1103579702, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"0.0.4-0.0.4";s:3:"php";s:11:"0.0.4-0.0.4";s:3:"cms";s:0:"";}}', 'Alexander Langer', 'alex@big.endian.de', 'doegi', '79e679004acae4ef44ba775ec8c73b70', 'fix a timezone display error for timezones other than CET.', '', 1000002, 0, 0),
(937, 0, 'calendar', 1, '1.0.3', 16842, 631, 'Extended Calendar', 'A full-featured calendar.', 2, 0, 3, 1104516106, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"3.7.1-3.7.1";s:3:"php";s:11:"4.1.1-4.1.1";s:3:"cms";s:0:"";}}', 'Alexander Langer', 'alex@big.endian.de', 'doegi', '6f8484462d221a94aa423eeffa8535b6', 'Fix template upload.  Fix "Upcoming View" which would loop forever if there are not enough events (you now need to specify max num of days to go into future).  Change Week-num to date() and to "W", as strftimes "%V" doesnt work in Windows.', '', 1000003, 0, 0),
(938, 0, 'calendar', 1, '1.0.4', 16842, 28, 'Extended Calendar', 'A full-featured calendar.', 2, 0, 3, 1106776409, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"3.7.1-3.7.1";s:3:"php";s:11:"4.1.1-4.1.1";s:3:"cms";s:0:"";}}', 'Alexander Langer', 'alex@big.endian.de', 'doegi', '46bda603627255a469d9a2e1f7fb6695', '- Add a new recurring events series type:  Every X. given weekday in a month, and evey last X. given weekday in a month, such as "every first monday in a month" or "every last friday". Thanks to Martin Klaus for this.  Fix a few bugs, e.g. in Upcoming vie', '', 1000004, 0, 0),
(939, 0, 'calendar', 1, '1.0.5', 16842, 35, 'Extended Calendar', 'A full-featured calendar.', 2, 0, 3, 1106822917, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"3.7.1-3.7.1";s:3:"php";s:11:"4.1.1-4.1.1";s:3:"cms";s:0:"";}}', 'Alexander Langer', 'alex@big.endian.de', 'doegi', '5459810ceab300feafc082491036ac81', '- Add a new recurring events series type: Every X. given weekday in a month, and evey last X. given weekday in a month, such as "every first monday in a month" or "every last friday". Thanks to Martin Klaus for this. Fix a few bugs, e.g. in Upcoming view', '', 1000005, 0, 0),
(940, 0, 'calendar', 1, '1.0.6', 16842, 45, 'Extended Calendar', 'A full-featured calendar.', 2, 0, 3, 1106827919, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"3.7.1-3.7.1";s:3:"php";s:11:"4.1.1-4.1.1";s:3:"cms";s:0:"";}}', 'Alexander Langer', 'alex@big.endian.de', 'doegi', '1d328172c591e82da7c717b01ab7bf94', 'Add a flag to FlexForms to set, if GET vars shall be ignored.  This is useful if you want to have e.g. a mini-month-view on every page of your site, but itll clutter up the view if the GET params are used for the event view etc.', '', 1000006, 0, 0),
(941, 0, 'calendar', 1, '1.1.0', 16842, 103, 'Extended Calendar', 'A full-featured calendar.', 2, 0, 3, 1106851932, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"3.7.1-3.7.1";s:3:"php";s:11:"4.1.1-4.1.1";s:3:"cms";s:0:"";}}', 'Alexander Langer', 'alex@big.endian.de', 'doegi', 'b08c0b1131c8fb42c87cb0582a34edf0', 'Add the ability to add arbitrary content to the calendar, such as tt_news News, perfectly rendered in the month-view/week/day view etc.  \r\n\r\nAll you need to do is to add a small PHP script that selects the objects in a given range, and "calendar" will the', '', 1001000, 0, 0),
(942, 0, 'calendar', 1, '1.1.1', 16842, 259, 'Extended Calendar', 'A full-featured calendar.', 2, 0, 3, 1106912808, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"3.7.1-3.7.1";s:3:"php";s:11:"4.1.1-4.1.1";s:3:"cms";s:0:"";}}', 'Alexander Langer', 'alex@big.endian.de', 'doegi', '6ece846946eea17cbc8dcbc00a59fc88', 'Fix a minor bug in the "event" and "upcoming" view introduced by last update.', '', 1001001, 0, 0),
(943, 0, 'calendar', 1, '1.1.2', 16842, 861, 'Extended Calendar', 'A full-featured calendar.', 2, 0, 3, 1107380228, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"3.7.1-3.7.1";s:3:"php";s:11:"4.1.1-4.1.1";s:3:"cms";s:0:"";}}', 'Alexander Langer', 'alex@big.endian.de', 'doegi', 'e7d6cf33fecb968e1acdf65a9dc0d820', 'Add Targetgroups.  Special thanks to Ingo Renner for the icon sets.\r\n\r\nFix a bug with weekly recurring events, where the start_date has a higher weekday number than the latest "On weekday" setting.\r\n\r\nFix a bug in the Upcoming view introducted with 1.1.', '', 1001002, 0, 0),
(944, 0, 'calendar', 1, '1.1.3', 16842, 12090, 'Extended Calendar', 'A full-featured calendar.', 2, 0, 3, 1110805305, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"3.7.2-3.7.2";s:3:"php";s:11:"4.1.2-4.1.2";s:3:"cms";s:0:"";}}', 'Alexander Langer', 'alex@big.endian.de', 'doegi', '3c1348f4e8536b4757b4403a48d6a273', 'Fix a common problem with weekly recurring events ("Must not be here").  Fix sorting of dates in the upcoming view.\r\nbr\r\nWARNING:  Events are 1 hour off on Mar 27 2005 due to DST.  Please use a workaround for now:  enter the event with 1 hour off in the', '', 1001003, 0, 0),
(945, 0, 'calendar', 1, '1.1.4', 16842, 110, 'Extended Calendar', 'A full-featured calendar.', 2, 0, 3, 1328370460, 'a:0:{}', 'Alexander Langer', 'alex@big.endian.de', 'doegi', 'c02687869bfe5119be016f2ea7aff203', 'Fix PHP deprecation errors and slightly overhaul the manual.\nThis version should be 100% compatible to the previous version and updates are generally considered safe.', '', 1001004, 1, 0),
(946, 0, 'calendar_adv', 1, '0.0.4', 605, 560, 'Eventos de calendario', 'Add calendar events (Aade eventos de calendario)', 0, 0, 3, 1120464792, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"0.0.2-0.0.2";s:3:"php";s:11:"0.0.2-0.0.2";s:3:"cms";s:0:"";}}', 'Gobernalia Global Net S.A', 'oscar.fernandez@grupobbva.com', 'afroweb', '25e0c2ec284d214176b2491dd4c2fae5', '', '', 4, 1, 0),
(947, 0, 'calendar_ext', 1, '0.0.6', 2300, 351, 'fe editable events for Extended Calendar', 'Provide a form, which fe-user can edit events of the extention calendar', 0, 0, 4, 1124980239, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:8:"calendar";s:0:"";}}', 'Herbert Roider', 'herbert.roider@utanet.at', 'bertl', '2cacb4ae91cb6b641197df167a12350b', '', '', 6, 0, 0),
(948, 0, 'calendar_ext', 1, '0.0.7', 2300, 19, 'fe editable events for Extended Calendar', 'Provide a form, which fe-user can edit events of the extention calendar', 0, 0, 4, 1138483380, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"0.0.2-0.0.2";s:3:"php";s:11:"0.0.2-0.0.2";s:8:"calendar";s:0:"";}}', 'Herbert Roider', 'herbert.roider@utanet.at', 'bertl', '993a176afa97113adbcbe1b66077ec9f', 'support for the jscalendar 1.0 is included.\r\nminor bugfixes.\r\nthis version is compatible to the previous.\r\nThe use of the jscalendar is optional, but it requires another template file. The example in the Tutorial describes the use of the jscalendar.', '', 7, 0, 0),
