(1415, 0, 'cmw_linklist', 1, '1.2.0', 10727, 431, 'CMW Linklist', 'This is a linklist plugin. Backend users can create categories and links, which are displayed afterwards. In addition to this frontend users have the possibility to propose new links. The layout can be changed via a template.\r\n\r\nFurthermore this extension', 2, 0, 3, 1099850809, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"0.0.2-0.0.2";s:3:"php";s:11:"0.0.2-0.0.2";s:3:"cms";s:0:"";}}', 'Sebastian Faulhaber', 's.faulhaber@web-sol.de', 'railmond', '0c157475674d3a9db7eafa9da001bafa', 'O Improvement: The plugin configuration is done via flexforms from now on:\r\nO Link Sorting....e.g. By label in ascending order.\r\nO Link teasing: You can enable link teasing in category view. Moreover you are able to specify the teaser text length.\r\nO Impr', ' services', 1002000, 0, 0),
(1416, 0, 'cmw_linklist', 1, '1.3.0', 10727, 335, 'CMW Linklist', 'This is a linklist plugin. Backend users can create categories and links, which are displayed afterwards. In addition to this frontend users have the possibility to propose new links. The layout can be changed via a template.\r\n\r\nFurthermore this extension', 2, 0, 3, 1102867598, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"0.0.2-0.0.2";s:3:"php";s:11:"0.0.2-0.0.2";s:3:"cms";s:0:"";}}', 'Sebastian Faulhaber', 's.faulhaber@web-sol.de', 'railmond', '079ece5d938df2fb394ec868b928215e', ' Improvement: You can now specify, if anonymous users (not logged in) may propose new links. This can be configured for every linklist plugin via flexform configuration.\r\n Improvement: Added french translation. Thanks to Myriam.', ' services', 1003000, 0, 0),
(1417, 0, 'cmw_linklist', 1, '1.4.0', 10727, 460, 'CMW Linklist', 'This is a linklist plugin. Backend users can create categories and links, which are displayed afterwards. In addition to this frontend users have the possibility to propose new links. The layout can be changed via a template.\r\n\r\nFurthermore this extension', 2, 0, 3, 1107700698, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"0.0.2-0.0.2";s:3:"php";s:11:"0.0.2-0.0.2";s:3:"cms";s:0:"";}}', 'Sebastian Faulhaber', 's.faulhaber@web-sol.de', 'railmond', '2b8f43fd8cab08a3dad97b22f9edde80', 'BUGFIX RELEASE: \r\n Improvement: Revised documentation.\r\n Bugfix: Hidden / deleted categories were still shown. (Thanks to Myriam)\r\n Bugfix: Links proposed by anonymous users were not shown. (Thanks to Kimmo Helle)', ' services', 1004000, 0, 0),
(1418, 0, 'cmw_linklist', 1, '1.4.1', 10727, 355, 'CMW Linklist', 'This is a linklist plugin. Backend users can create categories and links, which are displayed afterwards. In addition to this frontend users have the possibility to propose new links. The layout can be changed via a template.\r\n\r\nFurthermore this extension', 2, 0, 3, 1107700704, 'a:0:{}', 'Sebastian Faulhaber', 's.faulhaber@web-sol.de', 'railmond', 'ff9b65495bf5e213c063f3d332190ae1', '', ' services', 1004001, 0, 0),
(1419, 0, 'cmw_linklist', 1, '1.4.2', 10727, 577, 'CMW Linklist', ' Security fix - please upgrade to v1.4.2 or above! \r\n\r\nThis is a linklist plugin. Backend users can create categories and links, which are displayed afterwards. In addition to this frontend users have the possibility to propose new links. The layout', 2, 0, 3, 1109944609, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"0.0.3-0.0.3";s:3:"php";s:11:"0.0.3-0.0.3";s:3:"cms";s:0:"";}}', 'Sebastian Faulhaber', 's.faulhaber@web-sol.de', 'railmond', 'd5b7df0a0ac909d17ba7a3e31b170479', 'Fixed bug 857 - this fixes a security issue (SQL-injection).\r\nAll users of this extension are strongly advised to immediatly update this extension.', ' services', 1004002, 0, 0),
(1420, 0, 'cmw_linklist', 1, '1.5.0', 10727, 1588, 'CMW Linklist', ' Security fix - please upgrade to v1.5.0 or above! \r\n\r\nThis is a linklist plugin. Backend users can create categories and links, which are displayed afterwards. In addition to this frontend users have the possibility to propose new links. The layout', 2, 0, 3, 1109945430, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"0.0.4-0.0.4";s:3:"php";s:11:"0.0.4-0.0.4";s:3:"cms";s:0:"";}}', 'Sebastian Faulhaber', 's.faulhaber@web-sol.de', 'railmond', '648375e777a18c9ddd41822619d0a024', ' Security fix - important! ', ' services', 1005000, 0, 0),
(1421, 0, 'cmw_linklist', 1, '1.5.1', 10727, 4457, 'CMW Linklist', ' Security fix - please upgrade to v1.5.0 or above! \r\n\r\nThis is a linklist plugin. Backend users can create categories and links, which are displayed afterwards. In addition to this frontend users have the possibility to propose new links. The layout', 2, 0, 3, 1119181946, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"0.0.5-0.0.5";s:3:"php";s:11:"0.0.5-0.0.5";s:3:"cms";s:0:"";}}', 'Sebastian Faulhaber', 's.faulhaber@web-sol.de', 'railmond', '7fad5dda12525945a777da0f65fd357b', 'Improvement: Manual added again. (Sorry, that the extension lacked any documentation for such a long time, unfortunately the doc got lost, when the security fix was applied.)', ' services', 1005001, 1, 0),
(1422, 0, 'cm_jstickernews', 1, '0.0.1', 4273, 40, 'JS-Ticker newsfeed export', 'Export tt_news content as JS ticker, displays either inline or externally includeable, access protection of the ticker by valid FE user account', 1, 0, 3, 1051096693, 'a:1:{s:7:"depends";a:4:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:3:"cms";s:0:"";s:7:"tt_news";s:0:"";}}', 'Christoph Mller', 'chris@byters.de', 'cmoeller', '0d932f1807fac05851349a05201da008', 'first public version, should work as intended', '', 1, 0, 0);
