(1424, 0, 'cm_jstickernews', 1, '0.0.3', 4273, 3853, 'JS-Ticker newsfeed export', 'Export tt_news content as JS ticker, displays either inline or externally includeable, access protection of the ticker by valid FE user account. Now includes a function "make_ticker_inline" to be able to insert is as a subpart/marker.', 1, 0, 3, 1053412857, 'a:1:{s:7:"depends";a:4:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:3:"cms";s:0:"";s:7:"tt_news";s:0:"";}}', 'Christoph Mller', 'chris@byters.de', 'cmoeller', '0bcd4e0b528e474827f915376b1fc548', 'adds a new function make_ticker_inline to be able to display the ticker as marker/subpart', '', 3, 1, 0),
