(1433, 0, 'contactslist', 1, '0.3.0', 1279, 1060, 'Contacts List', 'Display a list of contacts, e.g. of sales offices. The list is searchable by ZIP code and by country.', 1, 0, 3, 1122899453, 'a:1:{s:7:"depends";a:4:{s:5:"typo3";s:11:"0.0.2-0.0.2";s:3:"php";s:11:"0.0.2-0.0.2";s:3:"cms";s:0:"";s:14:"sr_static_info";s:0:"";}}', 'Oliver Klee', 'typo3-coding@oliverklee.de', 'guenther', '656299d61e7f90f32949d0201f154af3', 'Improved manual and lots of improvements "under the hood": Code cleanup, refactoring, improved DB safety.', '', 3000, 0, 0),
(1434, 0, 'contactslist', 1, '0.4.0', 1279, 79, 'Contacts List', 'Display a list of contacts, e.g. of sales offices. The list is searchable by ZIP code and by country.', 1, 0, 3, 1208523141, 'a:1:{s:7:"depends";a:6:{s:3:"php";s:11:"5.1.0-0.0.0";s:5:"typo3";s:11:"4.0.0-0.0.0";s:3:"cms";s:0:"";s:18:"css_styled_content";s:0:"";s:5:"oelib";s:6:"0.4.0-";s:18:"static_info_tables";s:6:"2.0.2-";}}', 'Oliver Klee', 'typo3-coding@oliverklee.de', 'guenther', '66f26d176d367ef8012f8e3124bc1c07', 'One bug fix and lots of polish and clean-up. This version requires PHP 5.1 and TYPO3 4. Please read the upgrade notes before upgrading.', 'oliverklee.de', 4000, 0, 0),
(1435, 0, 'contactslist', 1, '0.5.0', 1279, 124, 'Contacts List', 'Display a list of contacts, e.g. of sales offices. The list is searchable by ZIP code and by country.', 1, 0, 3, 1229452648, 'a:1:{s:7:"depends";a:6:{s:3:"php";s:11:"5.1.0-0.0.0";s:5:"typo3";s:11:"4.0.0-0.0.0";s:3:"cms";s:0:"";s:18:"css_styled_content";s:0:"";s:5:"oelib";s:6:"0.4.3-";s:18:"static_info_tables";s:6:"2.0.2-";}}', 'Oliver Klee', 'typo3-coding@oliverklee.de', 'guenther', '1626e6b4c93ccdad482c1381ce2475f8', 'Bug-fix and cleanup release. Updating is recommended for all users.', 'oliverklee.de', 5000, 1, 0),
(1436, 0, 'contentwrapper', 1, '0.1.3', 2438, 716, 'Content Wrapper', 'wraps content elements for more layout options', 2, 0, 2, 1134128743, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:3:"cms";s:0:"";}}', 'Franz Ripfel', 'fr@abezet.de', 'abezet', 'd5c64782194792e96b8bc63589ce5d68', '', '', 1003, 0, 0),
(1437, 0, 'contentwrapper', 1, '0.2.0', 2438, 277, 'Content Wrapper', 'wraps content elements for more layout options', 2, 0, 2, 1158675737, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:3:"cms";s:0:"";}}', 'Franz Ripfel', 'fr@abezet.de', 'abezet', 'd2e7a515eec08621d965616573998f4a', 'move adding and configuration of dropdown options (from php) to TypoScript, therefore unexperienced users can adapt this more easily to their needs\n', '', 2000, 0, 0),
