(1440, 0, 'contentwrapper', 1, '0.3.1', 2438, 165, 'Content Wrapper', 'wraps content elements for more layout options', 2, 0, 2, 1280929750, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"4.3.0-0.0.0";s:3:"php";s:11:"3.0.0-0.0.0";s:3:"cms";s:0:"";}}', 'Franz Ripfel', 'fr@abezet.de', 'abezet', '7f6940cd257cbec618161cb4bebf2263', 'adapted for css_styled_content v4.3 or higher, raised constrained-depend to 4.3.0,\r\nchanging to a smarter way of wrapping content with 4.3', '', 3001, 1, 0),
(1441, 0, 'content_uneraser', 1, '0.2.0', 2899, 2264, 'Content UnEraser', 'Allows backend users to retrieve erased content from all the available tables present in the Typo3 database.', 2, 0, 1, 1118661545, 'a:1:{s:7:"depends";a:5:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:3:"cms";s:0:"";s:4:"lang";s:0:"";s:11:"api_macmade";s:0:"";}}', 'Jean-David Gadina', 'macmade@gadlab.net', 'abandoned_extensions', '080fc205f01b4de8f3f465be6fa0da76', 'Complete rewriting of the module.', 'macmade.net', 2000, 1, 0),
(1442, 0, 'convert2utf8', 1, '1.0.6', 6483, 6261, 'UTF8 Site Converter', 'This backend extension will convert all (or parts of) your Typo3 data from any current character set to UTF-8, which is the recommended character set for Typo3 internal data storage.', 1, 0, 1, 1094560419, 'a:1:{s:7:"depends";a:4:{s:5:"typo3";s:11:"3.6.4-0.0.4";s:3:"php";s:11:"4.3.4-0.0.4";s:12:"func_wizards";s:0:"";s:3:"cms";s:0:"";}}', 'Morten Egelund Rasmussen', 'mer@brunata.dk', 'silverjam', '93bcbd9e80f953f37a7fe29cbf851c36', '', '', 1000006, 1, 0),
(1443, 0, 'convertutf', 1, '0.0.1', 1753, 1754, 'Convert to utf-8', 'Charset conversion tool, converts database tables to utf-8. Makes sense especially for transferring content from exotical charsets, if forceCharsetutf-8 is set.', 3, 0, 1, 1083458676, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";}}', 'Andreas Schwarzkopf', 'schwarzkopf@artplan21.de', 'werner', '98a465171af61fc8e0e423af9c810648', '- initial upload (sure, many bugs and problems)', ' solutions GmbH', 1, 1, 0),
(1444, 0, 'cp_imagecrop', 1, '0.0.1', 1850, 1850, 'Image Cropper', 'Adds new menuitem in Filelist, allowing images to be easily cropped using the DHTML Image Cropping Interface by Michal van Ouwerkerk', 0, 0, 0, 1093726683, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:3:"cms";s:0:"";}}', 'Casper Poulsen', 'casper@edev.dk', 'casper', 'bf6602107b846e28694373fa4a1ca209', 'Proof of concept release - early stage, but working none the less. Dirty code, beware - need to figure some things out, both UI and TYPO3 extension programming stuff.', '', 1, 1, 0),
