(1488, 0, 'cron_csc_imgframes', 1, '0.1.1', 1763, 167, 'Image Frames for css-styled content', 'When using the css-styled content, the feature to add image frames in the "Image w/ text" and "Image" content elements is removed. This extention re-adds this feature.', 1, 0, 2, 1108555861, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"0.0.2-0.0.2";s:3:"php";s:11:"0.0.2-0.0.2";s:3:"cms";s:0:"";}}', 'Ernesto Baschny', 'ernst@cron-it.de', 'baschny', 'a2541c695aaf812682f5f1d8bb37a95c', 'Corrected manual, removed bogus file', 'cron IT GmbH - Germany', 1001, 0, 0),
(1489, 0, 'cron_csc_imgframes', 1, '0.1.2', 1763, 1571, 'Image Frames for css-styled content', 'When using the css-styled content, the feature to add image frames in the "Image w/ text" and "Image" content elements is removed. This extention re-adds this feature.', 1, 0, 2, 1117446207, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"0.0.2-0.0.2";s:3:"php";s:11:"0.0.2-0.0.2";s:3:"cms";s:0:"";}}', 'Ernesto Baschny', 'ernst@cron-it.de', 'baschny', '57b1563e59eeac7c542b0711c9f48075', 'Possibility to use alternate labels for imageborder and image_frames fields, because of misleading german translations in the core: "Bilderrahmen" instead of "Rahmen" (image_frames) and "Rand" instead of "Rahmen" (imageborder)', 'cron IT GmbH - Germany', 1002, 1, 0),
(1490, 0, 'cron_cssstyledimgtext', 1, '0.4.1', 7775, 6711, 'CSS styled IMGTEXT', 'CSS based implementation of the "Text with Image" and "Image" content types (from tt_content).', 1, 0, 2, 1129208463, 'a:1:{s:7:"depends";a:4:{s:5:"typo3";s:11:"0.0.2-0.0.2";s:3:"php";s:11:"0.0.2-0.0.2";s:3:"cms";s:0:"";s:18:"css_styled_content";s:0:"";}}', 'Ernesto Baschny', 'ernst@cron-it.de', 'baschny', '686c2117b511bd65de11ad2166e4f896', 'Fixed typo in the defaultRenderMethod constant (value a, should be dl) in 0.4.0 release . Ups!', 'cron IT GmbH', 4001, 1, 0),
