(1492, 0, 'cron_latin1cleaner', 1, '0.0.1', 601, 595, 'ISO-Latin-1 cleaning', 'Translates invalid characters (from the range 128-150) into proper HTML-entities.', 2, 0, 0, 1135106187, 'a:2:{s:7:"depends";a:3:{s:5:"typo3";s:13:"0.0.13-0.0.13";s:3:"php";s:13:"0.0.12-0.0.12";s:3:"cms";s:0:"";}s:9:"conflicts";a:2:{s:16:"qcom_htmlcleaner";s:0:"";s:17:"cron_rte_cleanenc";s:0:"";}}', 'Ernesto Baschny', 'ernst@cron-it.de', 'baschny', '4a9363073669780757eb781964fb847d', 'This obsoletes cron_rte_cleanenc, as this will apply to all output, not only RTE input. It provides the functionality that qcom_htmlcleaner has called clean_chars with the following differences: It will only translated characters that are not in the ISO', 'cron IT GmbH', 1, 1, 0),
(1493, 0, 'cron_printlink', 1, '0.1.0', 5825, 383, 'Print Link', 'This extention add an easy way of adding a link to the print version of your page. Its output can be customized with TypoScript and is internationalizable through locallang. A second plugin allows you to add a footer to your print page, telling the us', 1, 0, 3, 1123163149, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:3:"cms";s:0:"";}}', 'Ernesto Baschny', 'ernst@cron-it.de', 'baschny', '5688e0df209e82adfbbf64bf57d34fac', 'Initial release', 'cron IT GmbH', 1000, 0, 0),
