(1732, 0, 'cwt_press_center', 1, '1.5.6', 9348, 536, 'Press center', 'A complete press center, where news items and multimedia objects can be organized for the press.', 2, 0, 3, 1091876860, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"0.0.4-0.0.4";s:3:"php";s:11:"0.0.4-0.0.4";s:3:"cms";s:0:"";}}', 'Sebastian Krebs', 's.krebs@creativewebteam.com', 'sebkrebs', '03833ed9043264b6417b0118dbc35319', 'Merged translation. Added date format constant.', 'CreativeWebTeam', 1005006, 0, 0),
(1733, 0, 'cwt_press_center', 1, '1.6.0', 9348, 642, 'Press center', 'A complete press center, where news items and multimedia objects can be organized for the press. Includes statistic about downloaded files', 2, 0, 3, 1096883125, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:3:"cms";s:0:"";}}', 'Sebastian Krebs', 's.krebs@creativewebteam.com', 'sebkrebs', '30d724bd9caa4f038bb518f3327da1fa', 'Added a backend module for statistics. Some bugfixing in the newsitem plugin concerning the rendering of the newsitem text. It is now possible to show tables etc. Have a look at the manual espacially the changelog and the new backend statistics part. Than', 'CreativeWebTeam', 1006000, 0, 0),
(1734, 0, 'cwt_press_center', 1, '1.6.1', 9348, 2329, 'Press center', 'A complete press center, where news items and multimedia objects can be organized for the press. Includes statistic about downloaded files', 2, 0, 3, 1126534980, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"0.0.2-0.0.2";s:3:"php";s:11:"0.0.2-0.0.2";s:3:"cms";s:0:"";}}', 'Sebastian Krebs', 'support@creativewebteam.de', 'sebkrebs', 'cb2a6f7d6775a6e759395116f0366554', 'Bugfix of mediaobject counting in listview.', 'CreativeWebTeam', 1006001, 0, 0);
