(1736, 0, 'cwt_press_center', 1, '1.6.3', 9348, 3567, 'Press center', 'A complete press center, where news items and multimedia objects can be organized for the press. Includes statistic about downloaded files', 2, 0, 3, 1169549994, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:3:"php";s:6:"3.0.0-";s:5:"typo3";s:6:"3.5.0-";}}', 'Sebastian Krebs', 's.krebs@creativewebteam.com', 'sebkrebs', 'f5b4d9d55b8e8486914081f0b14b9fff', 'Fixed the mm relation selection for media objects in the single view. Thanks to Stefan Ristea.', 'CreativeWebTeam', 1006003, 1, 0),
(1737, 0, 'cwt_resetbepassword', 1, '1.0.0', 1855, 47, 'Reset backend password', 'Each backend user can reset his password. The user can enter his email or username. The password will be reset in the db and send per mail to the corresponding user. If the backend user has not entered an emailaddress, there is no chance to reset the pass', 2, -1, 0, 1083179921, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:3:"cms";s:0:"";}}', 'Sebastian Krebs', 's.krebs@creativewebteam.com', 'sebkrebs', '65d02eab3b392aa771733f7a03417b3f', 'First stable and public release', 'CreativeWebTeam', 1000000, 0, 0),
(1738, 0, 'cwt_resetbepassword', 1, '1.1.0', 1855, 1244, 'Reset backend password', 'Each backend user can reset his password. The user can enter his email or username. The password will be reset in the db and send per mail to the corresponding user. If the backend user has not entered an emailaddress, there is no chance to reset the pass', 2, -1, 0, 1126534999, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"0.0.2-0.0.2";s:3:"php";s:11:"0.0.2-0.0.2";s:3:"cms";s:0:"";}}', 'Sebastian Krebs', 'support@creativewebteam.de', 'sebkrebs', '82690db36f06400b5d04ede7320a3c2a', 'Feature added: Password reset creates an entry in the sys_log table.', 'CreativeWebTeam', 1001000, 0, 0),
(1739, 0, 'cwt_resetbepassword', 1, '1.2.0', 1855, 564, 'Reset backend password', 'Each backend user can reset his password. The user can enter his email or username. The password will be reset in the db and send per mail to the corresponding user. If the backend user has not entered an emailaddress, there is no chance to reset the pass', 2, -1, 0, 1144872340, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:3:"php";s:6:"3.0.0-";s:5:"typo3";s:6:"3.5.0-";}}', 'Sebastian Krebs', 's.krebs@creativewebteam.com', 'sebkrebs', '7bf32f602b1690c9648ef69806c72685', 'Now working for versions different from 3.5/3.6. Tested with 4.0.', 'CreativeWebTeam', 1002000, 1, 0),
(1740, 0, 'cwt_sisuite', 1, '1.0.0', 881, 879, 'Webinterface for System Installation Suite', 'The System Installation Suite (www.sisuite.org) is a set of tools used for managing a large amount of systems e.g. in clusters or enterprise networks. With the help of this webinterface it is possible to manage the images and servers with ease.', 2, 0, 3, 1126535073, 'a:0:{}', 'Sebastian Krebs', 'support@creativewebteam.de', 'sebkrebs', 'f3f45266994a33dfeef50d499d0ac433', 'First Release! Feedback is welcome!', 'CreativeWebTeam', 1000000, 1, 0),
(1741, 0, 'cwt_testserver_bookingsystem', 1, '1.0.1', 1028, 19, 'Testserver booking system', 'This extension gives you the possibillity to manage your testserver environment. Servers can be booked etc. Some systeminformation can be collected dynamically (only AIX and Linux(SuSE and RedHat tested!!!)).', 2, -1, 3, 1076693199, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:3:"cms";s:0:"";}}', 'Sebastian Krebs', 's.krebs@creativewebteam.com', 'sebkrebs', '95c78529ba387baa248401391c0f9020', '', '', 1000001, 0, 0),
(1742, 0, 'cwt_testserver_bookingsystem', 1, '1.1.0', 1028, 423, 'Testserver booking system', 'This extension gives you the possibillity to manage your testserver environment. Servers can be booked etc. Some systeminformation can be collected dynamically (only AIX and Linux(SuSE and RedHat tested!!!)).', 2, -1, 3, 1088683210, 'a:1:{s:7:"depends";a:4:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:3:"cms";s:0:"";s:7:"overlib";s:0:"";}}', 'Sebastian Krebs', 's.krebs@creativewebteam.com', 'sebkrebs', '9885285b008d375bf21fb18055ad11f1', 'Little bugfix in "booked systems" view. Status link did not lead to overview pid.', '', 1001000, 0, 0),
(1743, 0, 'cwt_testserver_bookingsystem', 1, '1.2.0', 1028, 531, 'Testserver booking system', 'This extension gives you the possibillity to manage your testserver environment. Servers can be booked etc. Some systeminformation can be collected dynamically (only AIX and Linux(SuSE and RedHat tested!!!)).', 2, -1, 3, 1126535040, 'a:1:{s:7:"depends";a:4:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:3:"cms";s:0:"";s:7:"overlib";s:0:"";}}', 'Sebastian Krebs', 'support@creativewebteam.de', 'sebkrebs', '0a54db41c2db3b9257fcb6e7a8198e19', 'Added some new system information fields. UPDATE if you plan to use cwt_sisuite!', 'CreativeWebTeam', 1002000, 1, 0),
