(1921, 0, 'danp_sv_cryptauth', 1, '0.1.2', 1013, 242, 'Crypt Auth Service', 'Authentification Service for TYPO 3.8. Encodes the entered Password with Md5 or Crypt before checking with the one stored in DB. \nAdditional checks for onlinetime etc included. Also a backend-modul for displaying failed feuser Login-logs in the backend.', 1, 0, 5, 1171583755, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:6:"3.0.0-";s:3:"php";s:6:"3.0.0-";}}', 'Daniel Ptzinger', '', 'danp', 'b2c288d5a8bea382395b7d65426f80eb', 'improve settings for cryptsalt...(e.g. auth against htpasswd entries possible)', 'Ptz Media', 1002, 0, 0),
(1922, 0, 'danp_sv_cryptauth', 1, '0.2.0', 1013, 226, 'Crypt Auth Service', 'Authentification Service for TYPO 3.8. Encodes the entered Password with Md5 or Crypt before checking with the one stored in DB. \nAdditional checks for onlinetime etc included. Also a backend-modul for displaying failed feuser Login-logs in the backend.', 1, 0, 5, 1196069442, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:11:"3.5.0-0.0.0";s:3:"php";s:11:"3.0.0-0.0.0";}}', 'Daniel Ptzinger', '', 'danp', 'bd2130e9f0fee5393b1aaa9d5d9a71d7', 'Add SSHA1 auth (for LDAP) and devlog to be able to check in BE why a user was not authentificated.', 'Ptz Media', 2000, 1, 0),
(1923, 0, 'datasources', 1, '1.0.0', 1914, 1877, 'Data Sources', 'Provides a common way for configuration of data sources. Acts as a library for other extensions and thus does not offer any functionality itself!', 1, 1, 4, 1105283837, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";}}', 'Robert Lemke', 'robert@typo3.org', 'robert', 'fb5a2096c243d4708004fbdd869eaf8b', '', 'robert lemke medienprojekte', 1000000, 1, 0),
(1924, 0, 'da_msg_board', 1, '0.0.6', 2366, 499, 'DA MessageBoard', 'Simple non-threading messageboard, for login-users, with possible linking to  userprofile if available. Also includes a moderator-module, for back-end moderation.', 1, 0, 3, 1055798114, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:3:"cms";s:0:"";}}', 'Christian Jul Jensen', 'julle@diku.dk', 'julle', 'cde77329ca6230279551a27a8210ae6b', '', '', 6, 0, 0),
