(1926, 0, 'da_newsletter_subscription', 1, '0.0.12', 30126, 53, 'Newsletter Subscription Module', 'A newsletter subscription module which allows you to create any number of categories and then allow frontend users to check off which categories they want to receive. From the backend you can download a CSV list of recipients for sending the mails in any', 0, 0, 3, 1044476564, 'a:0:{}', 'Kasper Skrhj', 'kasper@typo3.com', 'kasper', 'c23e7b3952735c1067d87b6bca2a3c63', '', 'Curby Soft Multimedia', 12, 0, 0),
(1927, 0, 'da_newsletter_subscription', 1, '1.0.0', 30126, 145, 'Newsletter Subscription Module', 'A newsletter subscription module which allows you to create any number of categories and then allow frontend users to check off which categories they want to receive. From the backend you can download a CSV list of recipients for sending the mails in any', 2, 0, 3, 1044481205, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:3:"cms";s:0:"";}}', 'Kasper Skrhj', 'kasper@typo3.com', 'kasper', 'efec591ebc59c47ab6dd468f4c895d9d', '', 'Curby Soft Multimedia', 1000000, 0, 0);
