(1929, 0, 'dbal', 1, '0.5.0', 3620, 870, 'Database Abstraction Layer', 'A database abstraction layer implementation for TYPO3 4.0.0 based on ADOdb and offering a lot of other features...', 1, 0, 0, 1140045108, 'a:1:{s:7:"depends";a:3:{s:5:"adodb";s:0:"";s:3:"php";s:0:"";s:5:"typo3";s:0:"";}}', 'Karsten Dambekalns', 'k.dambekalns@fishfarm.de', 'friendsoftypo3', '5c280c123d660cc24ff208718ed33b2b', 'First upload to TER. This is a system extension, so it is in TER for completeness only...', 'TYPO3 Association', 5000, 0, 0),
(1930, 0, 'dbal', 1, '0.9.0', 3620, 329, 'Database Abstraction Layer', 'A database abstraction layer implementation for TYPO3 4.0 based on ADOdb and offering a lot of other features...', 1, 0, 0, 1143325579, 'a:1:{s:7:"depends";a:3:{s:5:"adodb";s:7:"4.70.0-";s:3:"php";s:6:"4.1.0-";s:5:"typo3";s:6:"3.8.1-";}}', 'Karsten Dambekalns', 'k.dambekalns@fishfarm.de', 'friendsoftypo3', '2ccfd4842e58cf9915ffde8855b28475', 'Added enhancements for UNIQUE KEY handling, MSSQL compatibility, code cleanup, bugfixes.', 'TYPO3 Association', 9000, 0, 0),
(1931, 0, 'dbal', 1, '0.9.9', 3620, 1398, 'Database Abstraction Layer', 'A database abstraction layer implementation for TYPO3 4.0 based on ADOdb and offering a lot of other features...', 1, 0, 0, 1151741316, 'a:1:{s:7:"depends";a:3:{s:5:"adodb";s:7:"4.90.0-";s:3:"php";s:6:"4.1.0-";s:5:"typo3";s:6:"4.0.0-";}}', 'Karsten Dambekalns', 'k.dambekalns@fishfarm.de', 'friendsoftypo3', '68744ff3063e5c8ffb6297594de3fbdd', ' Implemented support for sysLog() on connection failure\r\n DBAL now honours the no_pconnect setting\r\n For handlers in native mode the setDBinit queries are executed upon connection\r\n The initial value for generated sequences can be configured per handl', 'TYPO3 Association', 9009, 0, 0),
(1932, 0, 'dbal', 1, '1.0.0', 3620, 1012, 'Database Abstraction Layer', 'A database abstraction layer implementation for TYPO3 4.0 based on ADOdb and offering a lot of other features...', 2, 0, 0, 1258727161, 'a:1:{s:7:"depends";a:3:{s:5:"adodb";s:6:"5.8.1-";s:3:"php";s:11:"5.2.0-0.0.0";s:5:"typo3";s:12:"4.3.0-4.3.99";}}', 'Xavier Perseguers', 'typo3@perseguers.ch', 'friendsoftypo3', '09c4b03dfc457ac81f36dd8f8e4447e6', 'DBAL finally reached state "stable". This extension is part of TYPO3 Core and is compatible with TYPO3 4.3. Backport to TYPO3 4.2 might work but is not supported.', '', 1000000, 0, 0),
(1933, 0, 'dbal', 1, '8.4.0', 3620, 0, 'Database Abstraction Layer', 'A database abstraction layer implementation for TYPO3 4.6 based on ADOdb and offering a lot of other features.', 2, 0, 0, 1472764563, 'a:1:{s:7:"depends";a:2:{s:5:"adodb";s:12:"8.4.0-8.9.99";s:5:"typo3";s:12:"8.4.0-8.9.99";}}', 'Friends of TYPO3', 'friendsof@typo3.org', 'friendsoftypo3', 'e3ea42b0977292a7b741e089dcde9bb5', 'Initial standalone version', '', 8004000, 0, 0),
(1934, 0, 'dbal', 1, '8.4.1', 3620, 0, 'Database Abstraction Layer', 'A database abstraction layer implementation for TYPO3 4.6 based on ADOdb and offering a lot of other features.', 2, 0, 0, 1511455203, 'a:1:{s:7:"depends";a:2:{s:5:"adodb";s:12:"8.4.0-8.9.99";s:5:"typo3";s:12:"8.4.0-8.9.99";}}', 'Friends of TYPO3', 'friendsof@typo3.org', 'friendsoftypo3', 'b91b5a6e243d1d28138fa0d361812320', ' Fix admin_get_tables query with native MySQL connection\n Fix extension installation in EM\n\nFor more information see ChangeLog.', '', 8004001, 1, 0),
(1935, 0, 'dbsync', 1, '0.1.0', 1331, 1331, 'DB Sync', 'A backend module which allows you to synchronize your Typo3 database with an external Typo3 database. It also allows you to synchronize two different table inside the same database.', 1, 0, 1, 1121350771, 'a:1:{s:7:"depends";a:5:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:3:"cms";s:0:"";s:4:"lang";s:0:"";s:11:"api_macmade";s:0:"";}}', 'Jean-David Gadina', 'macmade@gadlab.net', 'abandoned_extensions', '09e8f3ae4efc00cc882878feb5b737de', 'Please read carefully the manual before using this extension.', 'macmade.net', 1000, 1, 0),
(1936, 0, 'db_purge', 1, '0.0.1', 1262, 1262, 'Database Purge', 'Gives The ability to delete pages and their content according to information stored in the Pages Typo3 Table', 2, 0, 1, 1091651716, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:3:"cms";s:0:"";}}', 'Rgis TEDONE  - Aix en Provence', 'regis.tedone@free.fr', 'tedreg', '9b8ddaa8cb38ac61528b21800764ff14', '', '', 1, 1, 0),
