(1949, 0, 'defaultstatic_tmpl', 1, '0.0.1', 7740, 828, 'Default Static Templates', 'This extension contains all the default static templates that used to be included with Typo3 version 3.6 and earlier. They are now a fully separated extension but have the exact same functionalities, and are used in the exact same way as before.', 1, 0, 4, 1087128702, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";}}', 'Stephane Schitter', 'stephane.schitter@free.fr', 'shelob', '15e31c5ab6d1edf973dd58a0aae40017', 'Initial version', '', 1, 0, 0),
