(1951, 0, 'de_addbodyjscript', 1, '0.1.7', 6851, 4105, 'Body onEvents Javascript', 'Add  javascript calls to your body tags "onload", "onmouseover" and "onmouseup" handlers through this extension, and not hardcoded in your HTML or TYPO3 extensions', 2, 0, 2, 1126822212, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"0.0.2-0.0.2";s:3:"php";s:11:"0.0.2-0.0.2";s:3:"cms";s:0:"";}}', 'Carlos A. Chiari O.', 'ccho@dimension-e.net', 'ccho', '34fbc9499c21cc5d929b2f371260630f', '', 'Dimension-E', 1007, 1, 0),
(1952, 0, 'de_articles', 1, '0.2.2', 6345, 1021, 'Articles', 'Create an article page, with navigation system, on the fly using a .txt file and some images as source!', 1, 0, 2, 1126822183, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"0.0.2-0.0.2";s:3:"php";s:11:"0.0.2-0.0.2";s:3:"cms";s:0:"";}}', 'Carlos Chiari', 'ccho@dimension-e.net', 'ccho', 'c88b342bc3ccab508d21a385cff722c8', '', 'Dimension-e.net', 2002, 0, 0),
