(1955, 0, 'de_cleargif', 1, '1.0.2', 2328, 1602, 'Clear Gif', 'New pagecontent: Clear Gif. \r\n\r\nLets you insert a CLEAR GIF image and set its width and height.\r\n\r\nConfigure the maximum size each side can have at the constant editor. (600 pixels default).', 2, 0, 2, 1091508783, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:3:"cms";s:0:"";}}', 'Carlos A. Chiari O.', 'ccho@dimension-e.net', 'ccho', '368391311d6e436928caf8168a712eb0', '', 'Dimension-E', 1000002, 1, 0),
