(1959, 0, 'de_custom_tags', 1, '0.6.0', 4904, 85, 'Custom Tags', 'Add custom tags and shorthand to your site. (Implemented through the parseFunc function).', 1, 0, 2, 1147152995, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"3.8.0-4.0.0";s:3:"php";s:13:"4.3.10-4.3.10";s:3:"cms";s:0:"";}}', 'Carlos A. Chiari O.', 'ccho@dimension-e.net', 'ccho', 'ca91fc296e03a050eca01b2b8bd8b188', 'Updated for compatibility with TYPO3 4.0 and backwards.', 'Dimension-E', 6000, 0, 0),
