(2115, 0, 'dmaddredit', 1, '0.3.0', 1919, 35, ' direct mail', 'Frontend editing of the tt_address table in conjunction with direct mail, especially useful for independent address spaces in a page tree. E.g. several domains, each with a direct mail module and its own address sysfolder. Exports address list as csv file', 1, -1, 3, 1115894341, 'a:1:{s:7:"depends";a:4:{s:5:"typo3";s:11:"3.6.4-0.0.4";s:3:"php";s:11:"0.0.4-0.0.4";s:3:"cms";s:0:"";s:10:"tt_address";s:0:"";}}', 'Dieter Mayer', 'dieter_mayer@gmx.net', 'foxpower', 'fba31ab333345e9948682c7dfae41a05', '- New marker in the template: INTROTEXT\r\n- Template adapted \r\n- locallang.php adapted\r\n- Small bugfix in delete routine: after delting a record the list view is now shown correct (all highlighted and pagebrowser active)', '', 3000, 0, 0),
(2116, 0, 'dmaddredit', 1, '0.3.1', 1919, 31, ' direct mail', 'Frontend editing of the tt_address table in conjunction with direct mail, especially useful for independent address spaces in a page tree. E.g. several domains, each with a direct mail module and its own address sysfolder. Exports address list as csv file', 1, -1, 3, 1115894492, 'a:1:{s:7:"depends";a:4:{s:5:"typo3";s:11:"3.6.4-0.0.4";s:3:"php";s:11:"0.0.4-0.0.4";s:3:"cms";s:0:"";s:10:"tt_address";s:0:"";}}', 'Dieter Mayer', 'dieter_mayer@gmx.net', 'foxpower', '7b1b712ce637af0da4fc3f9d6ae66076', '', '', 3001, 0, 0),
(2117, 0, 'dmaddredit', 1, '0.3.2', 1919, 219, ' direct mail', 'Frontend editing of the tt_address table in conjunction with direct mail, especially useful for independent address spaces in a page tree. E.g. several domains, each with a direct mail module and its own address sysfolder. Exports address list as csv file', 1, -1, 3, 1116076888, 'a:1:{s:7:"depends";a:4:{s:5:"typo3";s:11:"3.6.5-0.0.5";s:3:"php";s:11:"0.0.5-0.0.5";s:3:"cms";s:0:"";s:10:"tt_address";s:0:"";}}', 'Dieter Mayer', 'dieter_mayer@gmx.net', 'foxpower', '9b5c4be8eec0cf350864ca18dce1ddf8', '- Added a status report screen for the delete function to inform the user that a record was successfully deleted.\r\n- Modified the function makeSuccess() to return a more detailed result string.\r\n- Forgot to upload manual, here it is again.', '', 3002, 0, 0);
INSERT INTO `tx_extensionmanager_domain_model_extension` (`uid`, `pid`, `extension_key`, `repository`, `version`, `alldownloadcounter`, `downloadcounter`, `title`, `description`, `state`, `review_state`, `category`, `last_updated`, `serialized_dependencies`, `author_name`, `author_email`, `ownerusername`, `md5hash`, `update_comment`, `authorcompany`, `integer_version`, `current_version`, `lastreviewedversion`) VALUES
(2118, 0, 'dmaddredit', 1, '0.3.3', 1919, 218, ' direct mail', 'Frontend editing of the tt_address table in conjunction with direct mail, especially useful for independent address spaces in a page tree. E.g. several domains, each with a direct mail module and its own address sysfolder. Exports address list as csv file', 1, -1, 3, 1116449883, 'a:1:{s:7:"depends";a:4:{s:5:"typo3";s:11:"3.6.5-0.0.5";s:3:"php";s:11:"0.0.5-0.0.5";s:3:"cms";s:0:"";s:10:"tt_address";s:0:"";}}', 'Dieter Mayer', 'dieter_mayer@gmx.net', 'foxpower', 'c27fc6101cdd6e7d544504f698c2bf9c', 'Fixed a small irritation in the search function. Now the extension searches in the fields name, email and description.', '', 3003, 0, 0),
(2119, 0, 'dmaddredit', 1, '0.3.4', 1919, 27, ' direct mail', 'Frontend editing of the tt_address table in conjunction with direct mail, especially useful for independent address spaces in a page tree. E.g. several domains, each with a direct mail module and its own address sysfolder. Exports address list as csv file', 1, -1, 3, 1116883506, 'a:1:{s:7:"depends";a:4:{s:5:"typo3";s:11:"3.6.5-0.0.5";s:3:"php";s:11:"0.0.5-0.0.5";s:3:"cms";s:0:"";s:10:"tt_address";s:0:"";}}', 'Dieter Mayer', 'dieter_mayer@gmx.net', 'foxpower', '97140666b4bec647c78b502f8a7630a8', '- New marker in the template, section SUCCESSVIEW: NEW - gives the user the possibility to generate a new record from the status box, saves one mouse click (no need to go back to the list view to generate a new record)\r\n- Fixed a silly error that', '', 3004, 0, 0),
(2120, 0, 'dmaddredit', 1, '0.3.5', 1919, 22, ' direct mail', 'Frontend editing of the tt_address table in conjunction with direct mail, especially useful for independent address spaces in a page tree. E.g. several domains, each with a direct mail module and its own address sysfolder. Exports address list as csv file', 1, -1, 3, 1117145855, 'a:1:{s:7:"depends";a:4:{s:5:"typo3";s:11:"3.6.5-0.0.5";s:3:"php";s:11:"0.0.5-0.0.5";s:3:"cms";s:0:"";s:10:"tt_address";s:0:"";}}', 'Dieter Mayer', 'dieter_mayer@gmx.net', 'foxpower', 'ca61a862c3a7f873b698f675540159c5', '- Another stupid error fixed: forgot to include class basicfilefunc . Picture uploading should work fine now.\r\n- Removed one excessed brace in the TS Setup, caused an error in the Setup Object Browser (thanks to Peter Bachmann for both notifications)', '', 3005, 0, 0),
(2121, 0, 'dmaddredit', 1, '0.4.0', 1919, 1348, ' direct mail', 'Frontend editing of the tt_address table in conjunction with direct mail, especially useful for independent address spaces in a page tree. E.g. several domains, each with a direct mail module and its own address sysfolder. Exports address list as csv file', 1, -1, 3, 1117620671, 'a:1:{s:7:"depends";a:4:{s:5:"typo3";s:11:"3.6.5-0.0.5";s:3:"php";s:11:"0.0.5-0.0.5";s:3:"cms";s:0:"";s:10:"tt_address";s:0:"";}}', 'Dieter Mayer', 'dieter_mayer@gmx.net', 'foxpower', '56254102dc4eb298fb4b54e1fe2a882e', '- Corrected a path in ext_typoscript_constants.txt\r\n- Added a hint in the tips section: spamprotect for tt_adress', '', 4000, 1, 0),
(2122, 0, 'dmc_geoip', 1, '1.0.0', 1450, 337, 'dmc GeoIP', 'determines the country of residence for a given IP', 2, 0, 2, 1114698999, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:3:"cms";s:0:"";}}', 'Dominique Stender', 'dst@dmc.de', 'saloon12yrd', '3ab4f5cc67323195cb50055ce5adebe1', 'determines the country of residence for a given IP and (optionally) makes sure the visitor is directed to the rootline intended for this country.', '', 1000000, 0, 0),
(2123, 0, 'dmc_geoip', 1, '1.0.1', 1450, 1074, 'dmc GeoIP', 'determines the country of residence for a given IP', 2, 0, 2, 1118304670, 'a:0:{}', 'Dominique Stender', 'dst@dmc.de', 'saloon12yrd', 'fb63fc271db45ef653ec893688208a74', 'Reimplemented Maxminds geoip library for better integration into the Typo3 environment. \r\n- All methods have been moved into a class\r\n- methods have been renamed to studlyCaps syntax\r\n- error handling has been improved. Its still not perfect though.', '', 1000001, 1, 0),
