(2347, 0, 'doc_tut_quickstart_de', 1, '0.0.3', 6520, 1276, 'Der Einstieg', 'Ein Einstieg fr die Arbeit mit TYPO3. Anhand einer Beispiel Website lernen Sie die grundlegenden Konzepte von TYPO3 und machen erste Erfahrungen. Nach diesem Tutorial werden Sie einen guten berblick ber TYPO3 und einen Einblick in dessen Komplexit', 2, 1, 8, 1070018323, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";}}', 'Transl: Robert Lemke / Orig: Kasper Skrhj', 'rl@robertlemke.de', 'docteam', '06dcabfa565d8253381783f4436d4bdd', 'Added links to video section.', 'Robert Lemke Medienprojekte', 3, 0, 0);
