(2353, 0, 'doc_tut_templselect', 1, '0.1.0', 51864, 41981, 'Modern Template Building, Part 1', 'This extension is a from-scratch tutorial about how to build a CMS-powered website with TYPO3 based on a HTML-template.', 2, 1, 8, 1072699871, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";}}', 'Kasper Skrhj', 'kasper@typo3.com', 'kasper', '7de075bbb8e0fd3903267dd5244a3c87', '', '', 1000, 1, 0),
(2354, 0, 'doc_tut_templselect2', 1, '0.0.1', 20860, 20476, 'Modern Template Building, Part 23', 'This is Part 2 and 3 of the tutorial "Modern Template Building" from the "doc_tut_templselect" extension. For developers on intermediate to expert level.', 2, 1, 8, 1071996189, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";}}', 'Kasper Skrhj', 'kasper@typo3.com', 'kasper', 'be03c0ce8e7e690c397a1b751dbcf8f4', '', 'Curby Soft Multimedia', 1, 1, 0),
