(2357, 0, 'doc_tut_templsell_fr', 1, '0.0.1', 1055, 1019, 'Modern Template Building 1re Partie', 'Pour ceux qui veulent se plonger srieusement dans la cration de templates avec Typo3. Cest sans doute le tutorial le plus important, qui vous aprendra  crer des gabarits avec un diteur HTML classique (Golive, DW Mx...) et  lintgrer dans TY', 2, 0, 8, 1092679558, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";}}', 'Typo3.fr', 'doc@typo3.fr', 'simba_za', '24e9892c561db705106a690dd08a967a', '', '', 1, 1, 0),
(2358, 0, 'doc_tut_templsel_de', 1, '0.0.2', 8594, 8263, 'Moderne Templateerstellung, Teil1', '(German translation of the MTB1-Tutorial by Kaspar Skaarhoj) Tutorial: eine Typo3 CMS-Website  basierend auf einem HTML-Template erstellen.', 2, 1, 8, 1097440346, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";}}', 'Leander Kirstein-Heine, Kay Stenschke', 'lkh@cnc-online.net, kay@stenschke.com', 'kaysten', 'f31f0aa575ff9a8aba062d9b35d7ca6c', '', '', 2, 1, 0),
(2359, 0, 'doc_tut_tmplbasic_fr', 1, '0.0.1', 612, 595, 'Gabarits Typo3 - Les bases - Documents traduit du', 'Pour ceux qui veulent dmarrer dans la cration de templates avec Typo3. Cest sans doute le tutorial le plus simple et efficace, qui vous apprendra  grer  travers typo3 des gabarits HTML.', 2, 0, 8, 1106773546, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";}}', 'Marlies Cohen', 'doc@typo3.fr', 'simba_za', '2cc7aa3bb0b67f04aa8ea3c59be9597e', 'Got manual in', '', 1, 1, 0),
(2360, 0, 'doc_tv_de', 1, '0.0.27', 8680, 8373, 'Template Voila Tutorial German -templavoila', 'Dieses Tutorial beschftigt sich mit der Installation und der Nutzung von der Erweiterung TemplateVoila anhand eines einfachen Beispiels und einer dazugehrigen Templatedatei. Typo3 v3.8 TV v0.4.0', 2, 0, 8, 1126215993, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";}}', 'Andreas Jonderko', 'anj2j@yahoo.de', 'anj4u', 'c99ed90ddcc76e0cd328a86798d08035', '', '', 27, 1, 0),
