(2372, 0, 'dropdown_list_menu', 1, '1.1.0', 3681, 128, 'Drop-down list menu', 'Creates a selector box with pages links like a typoscript JSmenu but enables to specify which field to show in the list. (eg : subtitle).', 2, 0, 2, 1123512169, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:3:"cms";s:0:"";}}', 'Bertrand Mure', 'bertrand.mure@worldonline.fr', 'bmebme', 'a1755524defb2a9401d5a1569f0f07cd', '', '', 1001000, 0, 0),
