(2374, 0, 'dropdown_list_menu', 1, '1.2.0', 3681, 475, 'Drop-down list menu', 'Creates a selector box with pages links like a typoscript JSmenu but enables to specify which pages field to show in the list. (eg : subtitle). Target pages can be shown in the same window or in a popup.', 2, 0, 2, 1129638281, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:3:"cms";s:0:"";}}', 'Bertrand Mure', 'bertrand.mure@worldonline.fr', 'bmebme', '3a419f92c8342882d2ab9d6f73c42dfa', '', '', 1002000, 0, 0),
(2375, 0, 'dropdown_list_menu', 1, '1.3.0', 3681, 916, 'Drop-down list menu', 'Creates a selector box with pages links like a typoscript JSmenu but enables to specify which pages field to show in the list. (eg : subtitle). Target pages can be shown in the same window or in a popup.', 2, 0, 2, 1138039300, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:3:"cms";s:0:"";}}', 'Bertrand Mure', 'bertrand.mure@worldonline.fr', 'bmebme', '1a626d05226ac4e9f6d3d4cffcc21ccf', '', '', 1003000, 0, 0),
(2376, 0, 'dropdown_list_menu', 1, '1.4.0', 3681, 1789, 'Drop-down list menu', 'Creates a selector box with pages links like a typoscript JSmenu but enables to specify which pages field to show in the list. (eg : subtitle). Target pages can be shown in the same window or in a popup.', 2, 0, 2, 1163838737, 'a:0:{}', 'Bertrand Mure', 'bertrand.mure@worldonline.fr', 'bmebme', 'b1a93527551e401bb6b149e91d415cda', 'Modifies database request to make it compatible with new API. Then now this extension requires Typo 3.6.0 or later. Adds the possibility to have recursion and to configure range of treelevels. Thanks to Ralph Brugger.', '', 1004000, 1, 0),
(2377, 0, 'dropdown_sitemap', 1, '1.1.2', 24424, 139, 'Drop-Down Site Map', 'The Drop-Down sitemap plugin adds a new kind of menu/sitemap to the Typo3 content elements. It uses HTML list elements, CSS and JavaScript to generate a drop-down map of the website, with the possibility to expand / collapse every section.', 2, 0, 2, 1118665836, 'a:1:{s:7:"depends";a:4:{s:5:"typo3";s:11:"0.0.2-0.0.2";s:3:"php";s:11:"0.0.2-0.0.2";s:3:"cms";s:0:"";s:4:"lang";s:0:"";}}', 'Jean-David Gadina', 'macmade@gadlab.net', 'abandoned_extensions', '7cd96c559089f2455c106f637a581739', '', 'macmade.net', 1001002, 0, 0),
