(2392, 0, 'dr_blob', 1, '1.4.1', 4772, 773, 'File list', 'Adds a frontend plugin named "filelist". That plugin contains files that are stored in the database instead of the filesystem to ensure a secure data storage.', 1, -1, 3, 1142959505, 'a:0:{}', 'Daniel Regelein', 'daniel.regelein@diehl-informatik.de', 'danielregelein', '988530492e4494d0c1acfd998467680b', 'Prepared the Extension for use with Typo3 4.0 and for the Extensions next major release. \r\n\r\nFixed the IE6 SSL Bug', 'DIEHL Informatik GmbH', 1004001, 0, 0),
(2393, 0, 'dr_blob', 1, '1.5.0', 4772, 165, 'File list', 'Adds a frontend plugin named "filelist". That plugin allows to generate a list of files that are stored in the database instead of the file system to ensure a secure data storage.', 1, -1, 3, 1176316855, 'a:0:{}', 'Daniel Regelein', 'daniel.regelein@diehl-informatik.de', 'danielregelein', 'd754f74ca37b01c5a4ff409669c0eba2', 'Bugfixed three bugs \r\nAdded two features \r\nAdded three small features \r\nImproved and beautified the code \r\nSee the Changelogfile- or the documentation for details', 'DIEHL Informatik GmbH', 1005000, 0, 0),
