(2395, 0, 'dr_blob', 1, '1.6.0', 4772, 259, 'File list', 'This plugin allows to generate a list of files that are stored in the database instead of the file system to ensure a secure data storage.', 2, -1, 3, 1181766355, 'a:0:{}', 'Daniel Regelein', 'daniel.regelein@diehl-informatik.de', 'danielregelein', 'fa4dcf9b648bc0d89c05f952862e18cd', 'Added categories. \r\nMade the search function configurable via TS.\r\nAdded Template marker for the field names.\r\nFor a complete list of changes have a look at the changelog', 'DIEHL Informatik GmbH', 1006000, 0, 0),
(2396, 0, 'dr_blob', 1, '1.6.1', 4772, 491, 'File list', 'This plugin allows to generate a list of files that are stored in the database instead of the file system to ensure a secure data storage.', 2, -1, 3, 1190756352, 'a:0:{}', 'Daniel Regelein', 'daniel.regelein@diehl-informatik.de', 'danielregelein', '137676ea00e4ee1d17eed9074634c93d', 'Fixed the fileicon-bug.\r\nThe fields filesize and email are now rendered using stdWrap\r\nAdded Sort-Header for filesize and filetype', 'DIEHL Informatik GmbH', 1006001, 0, 0),
(2397, 0, 'dr_blob', 1, '1.7.0', 4772, 390, 'File list', 'This plugin allows to generate a list of files that are stored in the database, or in a folder in- or outside the document root directory of typo3 to ensure a secure data storage.', 1, -1, 3, 1214161528, 'a:0:{}', 'Daniel Regelein', 'daniel.regelein@diehl-informatik.de', 'danielregelein', '5d7a8909919e6f02e200d00343c994fa', ' Files can now be stored either in the database or in the filesystem \r\n Added CSH for BE-Forms\r\n Outsourced non-default Language Labels\r\n Added a checksum field for a file\r\n see Changelog for other new features', 'DIEHL Informatik GmbH', 1007000, 0, 0),
