(2425, 0, 'dr_wiki', 1, '0.4.0', 10293, 1298, 'DR Wiki', 'Inserts an advanced Wiki to your page. Please see documentation for more details on DR Wiki.', 1, -1, 3, 1101249448, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"0.0.5-0.0.5";s:3:"php";s:11:"0.0.5-0.0.5";s:3:"cms";s:0:"";}}', 'Denis Royer', 'webadmin@myasterisk.de', 'droyer', 'd36c8d48317189870cf7a0b960644ade', 'Added better rendering of headers, including TOC for wiki-pages (mediawiki compliant markups). See Changelog for further details.', '', 4000, 0, 0),
(2426, 0, 'dr_wiki', 1, '0.5.0', 10293, 22, 'DR Wiki', 'Inserts an advanced Wiki to your page. Please see documentation for more details.', 1, -1, 3, 1128860966, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"0.0.5-0.0.5";s:3:"php";s:11:"0.0.5-0.0.5";s:3:"cms";s:0:"";}}', 'Denis Royer', 'webadmin@myasterisk.de', 'droyer', 'b06b62301181744d7400a7dffce1af03', 'Added a few new feature: Caching of rendered pages, toolbar for the editor, JS Code is now externalised. Furthermore some of the gremlins are history now...', '', 5000, 0, 0),
(2427, 0, 'dr_wiki', 1, '0.5.1', 10293, 37, 'DR Wiki', 'Inserts an advanced Wiki to your page. Please see documentation for more details.', 1, -1, 3, 1128972542, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"0.0.5-0.0.5";s:3:"php";s:11:"0.0.5-0.0.5";s:3:"cms";s:0:"";}}', 'Denis Royer', 'webadmin@myasterisk.de', 'droyer', '5261e4f84130bc003315974f48f434c2', 'Fixed a small bug in the discussion section\r\nAdded "REDIRECT [[Link]]"', '', 5001, 0, 0),
(2428, 0, 'dr_wiki', 1, '0.5.2', 10293, 46, 'DR Wiki', 'Inserts an advanced Wiki to your page. Please see documentation for more details.', 1, -1, 3, 1128976191, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"0.0.5-0.0.5";s:3:"php";s:11:"0.0.5-0.0.5";s:3:"cms";s:0:"";}}', 'Denis Royer', 'webadmin@myasterisk.de', 'droyer', '7cae397d4d44ad4fd4f4014a3665b371', 'Fixed a bug in the rendering of links and added support for multiple redirects. Finally, removed unused "cancelEdit" code from code.', '', 5002, 0, 0),
(2429, 0, 'dr_wiki', 1, '0.6.0', 10293, 36, 'DR Wiki', 'Inserts an advanced Wiki to your page. Please see documentation for more details.', 1, -1, 3, 1129156540, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"0.0.5-0.0.5";s:3:"php";s:11:"0.0.5-0.0.5";s:3:"cms";s:0:"";}}', 'Denis Royer', 'webadmin@myasterisk.de', 'droyer', 'f7055a4b445dd43e47983550b4840e5e', 'Added check for newer versions of a wiki-page that has been edited while another user saved his/her changes - got rid of the bug to explicitly set the startingpoint; now the actual page is used as default value - added some additional usability features (', '', 6000, 0, 0),
(2430, 0, 'dr_wiki', 1, '0.6.1', 10293, 52, 'DR Wiki', 'Inserts an advanced Wiki to your page. Please see documentation for more details.', 1, -1, 3, 1129193897, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"0.0.5-0.0.5";s:3:"php";s:11:"0.0.5-0.0.5";s:3:"cms";s:0:"";}}', 'Denis Royer', 'webadmin@myasterisk.de', 'droyer', 'f45c143981e62a0e89dbf97f9cd40d40', '[] Added check for newer versions of a wiki-page that has been edited while another user saved his/her changes - [] got rid of the bug to explicitly set the startingpoint; now the actual page is used as default value - [] Added some additional usabilit', '', 6001, 0, 0),
(2431, 0, 'dr_wiki', 1, '0.6.2', 10293, 102, 'DR Wiki', 'Inserts an advanced Wiki to your page. Please see documentation for more details.', 1, -1, 3, 1129535691, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"0.0.5-0.0.5";s:3:"php";s:11:"0.0.5-0.0.5";s:3:"cms";s:0:"";}}', 'Denis Royer', 'webadmin@myasterisk.de', 'droyer', 'b5ac5c4ad9a7119ef72e4ff7ae9d221a', 'Fixed: [] Got rid of the bug to explicitly set the Startingpoint of the Wiki; now the actual page is used as default value and Sys-Folders can be used as Startingpoint to store Wiki-pages (thx to Michael Vogel for reporting this bug).', '', 6002, 0, 0),
(2432, 0, 'dr_wiki', 1, '0.7.0', 10293, 170, 'DR Wiki', 'Inserts an advanced Wiki into your page. Please see documentation  or http://www.myasterisk.de for more details.', 1, -1, 3, 1173352164, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:3:"php";s:11:"3.0.0-0.0.0";s:5:"typo3";s:11:"3.5.0-0.0.0";}}', 'Denis Royer', 'info@indigi.de', 'droyer', 'b85b19c32097b73351511067f3bed515', 'added nowiki tags, cleaned up code, made the search plugin work again', '', 7000, 0, 0),
(2433, 0, 'dr_wiki', 1, '1.1.0', 10293, 194, 'DR Wiki', 'Inserts an advanced Wiki into your page. Please see documentation for more details.', 1, -1, 3, 1147604888, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:3:"php";s:6:"3.0.0-";s:5:"typo3";s:6:"3.5.0-";}}', 'Denis Royer', 'webadmin@myasterisk.de', 'droyer', '6a911cdb5910a073192d981dffbaea4f', '[] Added Templates for Wiki pages. [] Fixed some minor bugs on formatting of pages... further updates are coming soon :-)', '', 1001000, 0, 0),
(2434, 0, 'dr_wiki', 1, '0.7.1', 10293, 97, 'DR Wiki', 'Inserts an advanced Wiki into your page. Please see documentation for more details.', 1, -1, 3, 1130399051, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"0.0.5-0.0.5";s:3:"php";s:11:"0.0.5-0.0.5";s:3:"cms";s:0:"";}}', 'Denis Royer', 'webadmin@myasterisk.de', 'droyer', 'cdc3deccb80c8544a0a706fd8307a712', '[] Fixed a bug in the setting of the Startingpoint (Thx to Christian Welzel for noticing) [] Added FlexForm configuration for: TOC, Caching, etc. [] Added back-link for discussion (thx to Andr Deuker for the idea). [] Read-Only option for Wiki (Wiki-', '', 7001, 0, 0),
(2435, 0, 'dr_wiki', 1, '0.8.0', 10293, 43, 'DR Wiki', 'Inserts an advanced Wiki into your page. Please see documentation for more details.', 1, -1, 3, 1131367241, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"0.0.5-0.0.5";s:3:"php";s:11:"0.0.5-0.0.5";s:3:"cms";s:0:"";}}', 'Denis Royer', 'webadmin@myasterisk.de', 'droyer', '8a58c11747deb9fd0536e959d0b2b76f', '[] More configuration options added to FlexForm\r\n[] Added tooltips and shortcuts to wiki-page editor and toolbar\r\n[] Updated the extensions template\r\n[] General code cleanup, correction of bugs, and removal of unused functions\r\n[] Added enhanced int', '', 8000, 0, 0),
(2436, 0, 'dr_wiki', 1, '0.8.1', 10293, 27, 'DR Wiki', 'Inserts an advanced Wiki into your page. Please see documentation for more details.', 1, -1, 3, 1131461960, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"0.0.5-0.0.5";s:3:"php";s:11:"0.0.5-0.0.5";s:3:"cms";s:0:"";}}', 'Denis Royer', 'webadmin@myasterisk.de', 'droyer', '28c539e92876f9b517bcf2f25d0a38ad', '[] Solved an SQL Query issue, causing dr_wiki to produce error messages (thx to Friedemann Gehrt for reporting) [] More configuration options added to FlexForm [] Added tooltips and shortcuts to wiki-page editor and toolbar [] Updated the extensions', '', 8001, 0, 0),
(2437, 0, 'dr_wiki', 1, '0.9.0', 10293, 32, 'DR Wiki', 'Inserts an advanced Wiki to your page. Please see documentation for more details on DR Wiki. \r\n\r\nContributions and ideas are more than welcome! I especially need support for the not yet implemented features, the localisation, and the documentation of the', 1, -1, 3, 1131534017, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"0.0.5-0.0.5";s:3:"php";s:11:"0.0.5-0.0.5";s:3:"cms";s:0:"";}}', 'Denis Royer', 'webadmin@myasterisk.de', 'droyer', '9346e6e64993f1b8c0c6477952e3100b', '[] Added diff function for comparing old page versions to the most up-to-date version. [] Added redirect to login page option, if a non-logged-in user tries to edit a Wiki page (see FlexForm configuration) - Thx to Julian Hein (NETWAYS) for contributi', '', 9000, 0, 0),
(2438, 0, 'dr_wiki', 1, '0.9.1', 10293, 158, 'DR Wiki', 'Inserts an advanced Wiki to your page. Please see documentation for more details on DR Wiki. \r\n\r\nContributions and ideas are more than welcome! I especially need support for the not yet implemented features, the localisation, and the documentation of the', 2, -1, 3, 1133183959, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"0.0.5-0.0.5";s:3:"php";s:11:"0.0.5-0.0.5";s:3:"cms";s:0:"";}}', 'Denis Royer', 'webadmin@myasterisk.de', 'droyer', '175b33c6ea29a7e1dca35f62171a616a', '[] Removed a bug in the rendering of internal links if a : is present but no namespace is referenced (thx to Els Soenens for reporting). [] Added diff function for comparing old page versions to the most up-to-date version. [] Added redirect to logi', '', 9001, 0, 0),
(2439, 0, 'dr_wiki', 1, '1.0.0', 10293, 136, 'DR Wiki', 'Inserts an advanced Wiki to your page. Please see documentation for more details on DR Wiki. \r\n\r\nContributions and ideas are more than welcome! I especially need support for the not yet implemented features, the localisation, and the documentation of the', 2, -1, 3, 1133184297, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"0.0.5-0.0.5";s:3:"php";s:11:"0.0.5-0.0.5";s:3:"cms";s:0:"";}}', 'Denis Royer', 'webadmin@myasterisk.de', 'droyer', '721cd9962ed5c1ef43d65cf56f7ad48f', '[] Fixed another ":" issue with regard to the rendering of internal links\r\n[] Added template support for Wiki pages, introducing the namespace "Template" to store the templates (e.g. {{myTemplate}} references [[Template:myTemplate]])\r\n[] Added more var', '', 1000000, 0, 0);
INSERT INTO `tx_extensionmanager_domain_model_extension` (`uid`, `pid`, `extension_key`, `repository`, `version`, `alldownloadcounter`, `downloadcounter`, `title`, `description`, `state`, `review_state`, `category`, `last_updated`, `serialized_dependencies`, `author_name`, `author_email`, `ownerusername`, `md5hash`, `update_comment`, `authorcompany`, `integer_version`, `current_version`, `lastreviewedversion`) VALUES
(2440, 0, 'dr_wiki', 1, '1.0.1', 10293, 56, 'DR Wiki', 'Inserts an advanced Wiki into your page. Please see documentation for more details.', 1, -1, 3, 1133366224, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"0.0.5-0.0.5";s:3:"php";s:11:"0.0.5-0.0.5";s:3:"cms";s:0:"";}}', 'Denis Royer', 'webadmin@myasterisk.de', 'droyer', '9ba90776ee3fd221b1dd002906b5ac15', '[] Added page-template feature for new pages. This feature needs to be configurated in the FlexForm. [] Fixed another ":" issue with regard to the rendering of internal links [] Added template support for Wiki pages, introducing the namespace "Template', '', 1000001, 0, 0),
