(2677, 0, 'erotea_date2cal', 1, '0.1.0', 10177, 23, 'Date2Calendar', 'Extends TCA and replces date/datetime fields with a JS calendar. Neat! :)', 0, 0, 0, 1098416692, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:3:"cms";s:0:"";}}', 'Adrian Rotea', 'adirotea@yahoo.com', 'adirotea', '1046483a59b6147ee421ebe86bc18dba', '', '', 1000, 0, 0),
(2678, 0, 'erotea_date2cal', 1, '0.2.0', 10177, 24, 'Date2Calendar', 'Extends TCA and replces date/datetime fields with a JS calendar. Neat! :)', 0, 0, 0, 1098442721, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:3:"cms";s:0:"";}}', 'Adrian Rotea', 'adirotea@yahoo.com', 'adirotea', 'af09afbb5db73ae4e4005d145fb55bc0', 'Cleaned a bit!\r\n\r\nSolved a small bug with empty date fields.', '', 2000, 0, 0),
(2679, 0, 'erotea_date2cal', 1, '1.0.0', 10177, 112, 'Date2Calendar', 'Extends the TCE Forms enhancing all date/datetime input fields with a DHTML Calendar making the editing of the backend date (Start Date, End Date, New Until, etc) form fields easy. \r\n\r\nNeat feature Typo3 backend was lacking of.\r\n\r\nJust install the extensi', 1, 0, 0, 1098539286, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:3:"cms";s:0:"";}}', 'Adrian Rotea', 'adirotea@yahoo.com', 'adirotea', 'a6ffa1cb3eb557c381e7cf28842d9dea', 'Matured now :) \r\n\r\nDoesnt rely anymore on extending TCA Arrays but extends the TCE Forms directly.\r\n\r\nThis way all date/datetime fields are replaced. Also enhances the calendar with a time selector for datetime fields.\r\n\r\nI guess i can consider this stab', '', 1000000, 0, 0),
(2680, 0, 'erotea_date2cal', 1, '1.1.0', 10177, 1525, 'Date2Calendar', 'Extends TCA Forms and replces automaticaly the date/datetime fields with a JS calendar. Neat and easy to use! Just install it and will do everything by itself :)', 1, 0, 0, 1098712290, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:3:"cms";s:0:"";}}', 'Adrian Rotea', 'adirotea@yahoo.com', 'adirotea', 'fa4c827dc9d08ef8bd09ef45efcf5ffd', 'This release fixes a problem with non IE browsers:\r\non Firefox, Opera (and more probably) clicking the calendar image didnt triggered the calendar. \r\n', '', 1001000, 0, 0),
(2681, 0, 'erotea_date2cal', 1, '1.2.0', 10177, 7863, 'Date2Calendar', 'Extends TCA Forms and replces automaticaly the date/datetime fields with a JS calendar. Neat and easy to use! Just install it and will do everything by itself :)', 1, 0, 0, 1113843081, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"0.0.2-0.0.2";s:3:"php";s:11:"0.0.2-0.0.2";s:3:"cms";s:0:"";}}', 'Adrian Rotea', 'adirotea@yahoo.com', 'adirotea', 'fa8ef0f118ecd7d5ab9373da072c3153', 'Fixed bug not allowing the extension to be installed globally. Thanks to Christian Jul Jensen for notifying this and also for providing the fixes!', '', 1002000, 1, 0),
