(3076, 0, 'freesite', 1, '0.2.0', 1448, 9, 'Freesite', 'A module which automates the creation of a new standard template websites including a backend user, filemounts and dummy page set.', 1, 0, 1, 1234366124, 'a:0:{}', 'Stig Nrgaard Frch', 'stig@8620.dk', 'inshadow', '3af09ddae6b6a9b63eed8c1c06ecda33', 'Uid replacement markers shall now be place on the linie before instead of the end of the line.\r\nThis is done so that values will not be the uid  marker when displaying a dummy page.', '', 2000, 0, 0),
(3077, 0, 'freesite', 1, '0.2.1', 1448, 7, 'Freesite', 'A module which automates the creation of a new standard template websites including a backend user, filemounts and dummy page set.', 1, 0, 1, 1236762379, 'a:1:{s:7:"depends";a:4:{s:5:"typo3";s:11:"3.5.0-0.0.0";s:3:"php";s:11:"3.0.0-0.0.0";s:3:"cms";s:0:"";s:18:"tstemplate_ceditor";s:0:"";}}', 'Stig Nrgaard Frch', 'stig@8620.dk', 'inshadow', 'cd6b9655d179315f873f8e208dc084a7', 'Minor changes. Copy depth level can now be set. Disabling of alias field in rootpage possible.', '', 2001, 0, 0),
