(3090, 0, 'ftpbrowser', 1, '0.1.2', 5990, 4143, 'FTP Browser', 'A backend module to help you administrate your WebServer. Actually, it can browse your entire server, edit, create or delete files and folders, change permissions, upload and compress files, etc...', 1, -1, 1, 1118661626, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";}}', 'Jean-David Gadina', 'macmade@gadlab.net', 'abandoned_extensions', '1d6af128d3d1d57290efb8eff3aec329', '', 'macmade.net', 1002, 0, 0),
