(3092, 0, 'ftrs_products', 1, '0.1.0', 924, 18, 'Shop system (extended by ftrs)', 'An extension for the tt_products shop system.  Adds features for pageAsCategory display e.g.: Category display, display by category , some sorting strategies and additional discount settings.', 0, 0, 3, 1125273181, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:11:"tt_products";s:0:"";}}', 'Rick Gosselt', 'typo3@gosselt.net', 'futuros', '3aec9f3c9fd7dee6b5a8ce29227dafe7', 'first public release\r\n---\r\nmost features completed (not all eg. discount)\r\nneeds more testing\r\n---\r\nWARNING very alpha', '', 1000, 0, 0),
(3093, 0, 'ftrs_products', 1, '0.1.1', 924, 27, 'Shop system (extended by ftrs)', 'An extension for the tt_products shop system.  Adds features for pageAsCategory display e.g.: Category display, display by category , some sorting strategies and additional discount settings.', 0, 0, 3, 1125492033, 'a:0:{}', 'Rick Gosselt', 'typo3@gosselt.net', 'futuros', '5334de8c612e49c4ac0feccb4055c210', 'Added some documentation in the readme file\r\nReading this is recommended before usage because development is still very alpha.', '', 1001, 0, 0),
(3094, 0, 'ftrs_products', 1, '0.1.2', 924, 183, 'Shop system (extended by ftrs)', 'An extension for the tt_products shop system.  Adds features for pageAsCategory display e.g.: Category display, display by category , some sorting strategies and additional discount settings.\r\nAll configurable by TS.\r\n\r\nCheck the readme file!!', 0, 0, 3, 1125492462, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:11:"tt_products";s:0:"";}}', 'Rick G', 'typo3@futuros.nl', 'futuros', '620717682043bf6d9ec2139553d848b5', 'corrected sorting bug', 'Futuros Internet Solutions', 1002, 0, 0),
(3095, 0, 'ftrs_products', 1, '0.2.0', 924, 43, 'Shop system (extended by ftrs)', 'An extension for the tt_products shop system.  Adds features for pageAsCategory display e.g.: Category display, display by category , some sorting strategies and additional discount settings.', 0, 0, 3, 1126198917, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:11:"tt_products";s:0:"";}}', 'Rick Gosselt', 'typo3@gosselt.net', 'futuros', '052409bcc35b2a06497751c70bdc41a9', 'added subpages\r\nfixed some bugs\r\nadd listImage.limitImage\r\nadded (simple) example template\r\n---\r\nSee readme', '', 2000, 0, 0),
