(3097, 0, 'ftrs_subpagenav', 1, '0.1.0', 1037, 1037, 'Subpage navigation menu', 'This extension will create a menu of links to subpages at the same level as the current page.\r\nIt show pointers to the next and previous pages and a numbered list for the pages.\r\nExtension is based on gsi_pagenav', 0, 0, 3, 1113832651, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:3:"cms";s:0:"";}}', 'Futuros Internet Solutions', 'rick@futuros.nl', 'futuros', '7b672289fa116afb95a6f967425b64cb', 'first version', '', 1000, 1, 0),
