INSERT INTO `tx_extensionmanager_domain_model_extension` (`uid`, `pid`, `extension_key`, `repository`, `version`, `alldownloadcounter`, `downloadcounter`, `title`, `description`, `state`, `review_state`, `category`, `last_updated`, `serialized_dependencies`, `author_name`, `author_email`, `ownerusername`, `md5hash`, `update_comment`, `authorcompany`, `integer_version`, `current_version`, `lastreviewedversion`) VALUES
(3335, 0, 'hjm_winpopup', 1, '0.0.1', 1447, 15, 'Send winpop messages', 'Sends users windows popup-messages or if that fails e-mails (extends the newloginbox userlist)', 1, 0, 2, 1083768365, 'a:1:{s:7:"depends";a:5:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:3:"cms";s:0:"";s:11:"newloginbox";s:0:"";s:7:"eu_ldap";s:0:"";}}', 'Hans J. Martin', 'hans-jakob.martin@gmx.net', 'case', '41445a28cd9ec101fcd81b6ac5582725', 'Initial version. Makes use of LDAP (attr networkaddress) to get IP of client (eu_ldap needed). Uses smblient (unix) as of today (send me requests/solutions).  Also extends userlist to display image (if any).', '', 1, 0, 0),
(3336, 0, 'hjm_winpopup', 1, '0.1.0', 1447, 32, 'Send winpop messages', 'Sends users windows popup-messages or if that fails e-mails (extends the newloginbox userlist)', 1, 0, 2, 1083769797, 'a:1:{s:7:"depends";a:5:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:3:"cms";s:0:"";s:11:"newloginbox";s:0:"";s:7:"eu_ldap";s:0:"";}}', 'Hans J. Martin', 'hans-jakob.martin@gmx.net', 'case', '2e451eca1c3f0e0254a10c998f3937ab', 'Attribute for IP in LDAP is now set via conf', '', 1000, 0, 0),
(3337, 0, 'hjm_winpopup', 1, '0.2.0', 1447, 23, 'Send winpop messages', 'Sends users windows popup-messages or if that fails e-mails (extends the newloginbox userlist)', 1, 0, 2, 1083927540, 'a:1:{s:7:"depends";a:4:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:3:"cms";s:0:"";s:11:"newloginbox";s:0:"";}}', 'Hans J. Martin', 'hans-jakob.martin@gmx.net', 'case', 'c48a62b2a82195a546c37a1388c16f8a', 'No need for ldap anymore! Now uses netbios broadcast to find username. \r\n', '', 2000, 0, 0),
(3338, 0, 'hjm_winpopup', 1, '0.2.1', 1447, 27, 'Send winpop messages', 'Sends users windows popup-messages or if that fails e-mails (extends the newloginbox userlist)', 1, 0, 2, 1083933144, 'a:1:{s:7:"depends";a:4:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:3:"cms";s:0:"";s:11:"newloginbox";s:0:"";}}', 'Hans J. Martin', 'hans-jakob.martin@gmx.net', 'case', '6e1b8f3058e9d003fe4150a0b334678a', 'No need for ldap anymore! Now uses netbios broadcast to find username. \r\nExperimental support for windows. Please send me your feedback if it works for you!', '', 2001, 0, 0),
(3339, 0, 'hjm_winpopup', 1, '0.2.2', 1447, 30, 'Send winpop messages', 'Sends users windows popup-messages or if that fails e-mails (extends the newloginbox userlist)', 1, 0, 2, 1083945316, 'a:1:{s:7:"depends";a:4:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:3:"cms";s:0:"";s:11:"newloginbox";s:0:"";}}', 'Hans J. Martin', 'hans-jakob.martin@gmx.net', 'case', '3eec822f6ce166a40fbe670c9e524716', 'No need for ldap anymore! Now uses netbios broadcast to find username. Experimental support for windows. Please send me your feedback if it works for you! \r\nAdded ll-inclusing (rather dirty, but works..)', '', 2002, 0, 0),
(3340, 0, 'hjm_winpopup', 1, '0.2.3', 1447, 1320, 'Send winpop messages', 'Sends users windows popup-messages or if that fails e-mails (extends the newloginbox userlist)', 2, 0, 2, 1105428517, 'a:1:{s:7:"depends";a:4:{s:5:"typo3";s:11:"0.0.2-0.0.2";s:3:"php";s:11:"0.0.2-0.0.2";s:3:"cms";s:0:"";s:11:"newloginbox";s:0:"";}}', 'Hans J. Martin', 'hans-jakob.martin@gmx.net', 'case', '7eec84611dee258d8c70856284f08408', 'No need for ldap anymore! Now uses netbios broadcast to find username. Experimental support for windows. Please send me your feedback if it works for you! Added ll-inclusing (rather dirty, but works..)', '', 2003, 1, 0),
(3341, 0, 'hordefram', 1, '0.0.1', 1375, 1375, 'Horde Frame', 'Puts Horde inside TYPO3 Window', 0, 0, 1, 1064498363, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:3:"cms";s:0:"";}}', 'Thom Cherryhomes', 'thomas@customercd.com', 'thales', '2f5f79ad95cdbacb59bf4fb56f4c2678', 'Initial release.. .to fix, make patch to horde so that username and password can be properly passed, either as a custom login, or... \r\n\r\n', '', 1, 1, 0),
