(3550, 0, 'jk_poll', 1, '0.1.5', 9294, 16, 'Poll', 'A poll based on the extension quickpoll. A template-file can be used to define the output in the frontend. It is also possible to create a horiontal or vertical display of the percentage of users voted for an answer.', 1, -1, 3, 1119447054, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"0.0.2-0.0.2";s:3:"php";s:11:"0.0.2-0.0.2";s:3:"cms";s:0:"";}}', 'Johannes Krausmller', 'johannes@schosemail.de', 'moses123', 'b4f2c6b65dbe57930600da10cff3b5eb', '', '', 1005, 0, 0),
(3551, 0, 'jk_poll', 1, '0.2.0', 9294, 319, 'Poll', 'A poll based on the extension quickpoll. A template-file can be used to define the output in the frontend. It is also possible to create a horiontal or vertical display of the percentage of users voted for an answer.', 1, -1, 3, 1132299700, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"0.0.3-0.0.3";s:3:"php";s:11:"0.0.3-0.0.3";s:3:"cms";s:0:"";}}', 'Johannes Krausmller', 'johannes@schosemail.de', 'moses123', '7f72d6d0ef3267aeca3e520494b3247c', 'Added possibility to only allow fe users to vote for an answer.', '', 2000, 0, 0),
(3552, 0, 'jk_poll', 1, '0.3.0', 9294, 389, 'Poll', 'A poll based on the extension quickpoll. A template-file can be used to define the output in the frontend. It is also possible to create a horiontal or vertical display of the percentage of users voted for an answer.', 1, -1, 3, 1137484811, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"0.0.5-0.0.5";s:3:"php";s:11:"0.0.5-0.0.5";s:3:"cms";s:0:"";}}', 'Johannes Krausmller', 'johannes@schosemail.de', 'moses123', 'af10ce02312ddadba02ea9815ae37801', 'Added manual again.', '', 3000, 0, 0),
(3553, 0, 'jk_poll', 1, '0.3.1', 9294, 28, 'Poll', 'A poll based on the extension quickpoll. A template-file can be used to define the output in the frontend. It is also possible to create a horiontal or vertical display of the percentage of users voted for an answer.', 1, -1, 3, 1145379587, 'a:0:{}', 'Johannes Krausmller', 'johannes@schosemail.de', 'moses123', '0289c44712ace175edb880f967ed148b', 'Now it is possible to show the poll on every page with the help of some settings in the template. Ill update the manual soon.', '', 3001, 0, 0),
(3554, 0, 'jk_poll', 1, '0.3.2', 9294, 228, 'Poll', 'A poll based on the extension quickpoll. A template-file can be used to define the output in the frontend. It is also possible to create a horiontal or vertical display of the percentage of users voted for an answer.', 1, -1, 3, 1145393782, 'a:0:{}', 'Johannes Krausmller', 'johannes@schosemail.de', 'moses123', '6a2d42dfd2c38ca76e8500fb7f9947a2', 'Now it is possible to show the poll on every page with the help of some settings in the template. I will update the manual soon. The extension has also been tested with version 4.0.', '', 3002, 0, 0),
(3555, 0, 'jk_poll', 1, '0.3.3', 9294, 26, 'Poll', 'A poll based on the extension quickpoll. A template-file can be used to define the output in the frontend. It is also possible to create a horiontal or vertical display of the percentage of users voted for an answer.', 1, -1, 3, 1145807479, 'a:0:{}', 'Johannes Krausmller', 'johannes@schosemail.de', 'moses123', 'cda3b6d7f06e5431b6bec2754d773be3', 'Added locallang file for russian (thanks to Nickolas A. Shadrin). Added possibility to set cookiepath to / (plugin.tx_jkpoll_pi1.cookie_domainpath  1). Added possibility to use check for fe_user via tsconfig (plugin.tx_jkpoll_pi1.cookie_check_user  1)', '', 3003, 0, 0),
(3556, 0, 'jk_poll', 1, '0.3.4', 9294, 161, 'Poll', 'A poll based on the extension quickpoll. A template-file can be used to define the output in the frontend. It is also possible to create a horiontal or vertical display of the percentage of users voted for an answer.', 1, -1, 3, 1145900446, 'a:0:{}', 'Johannes Krausmller', 'johannes@schosemail.de', 'moses123', 'f8353075e9d8bb54d80c6413063c6681', 'Some small changes in the template. Added posibility for link to list of old polls (plugin.tx_jkpoll_pi1.list  1). Added some more options for tsconfig (plugin.tx_jkpoll_pi1.list_first  1, plugin.tx_jkpoll_pi1.list_limit  5).', '', 3004, 0, 0),
(3557, 0, 'jk_poll', 1, '0.3.5', 9294, 246, 'Poll', 'A poll based on the extension quickpoll. A template-file can be used to define the output in the frontend. It is also possible to create a horiontal or vertical display of the percentage of users voted for an answer.', 1, -1, 3, 1146081233, 'a:0:{}', 'Johannes Krausmller', 'johannes@schosemail.de', 'moses123', 'f0fc97fc5f2f5cffd27768d88bdcac86', 'Added possibility to define a time from which you can only see the result of a poll but not vote anymore.', '', 3005, 0, 0),
(3558, 0, 'jk_poll', 1, '0.3.6', 9294, 249, 'Poll', 'A poll based on the extension quickpoll. A template-file can be used to define the output in the frontend. It is also possible to create a horiontal or vertical display of the percentage of users voted for an answer.', 1, -1, 3, 1146595723, 'a:0:{}', 'Johannes Krausmller', 'johannes@schosemail.de', 'moses123', '1c1a8f2026065ce1fe8e0565ed42700d', 'Changed the template to get valid XHTML output.', '', 3006, 0, 0),
(3559, 0, 'jk_poll', 1, '0.5.1', 9294, 404, 'Poll', 'A poll based on the extension quickpoll. A template-file can be used to define the output in the frontend. It is also possible to create a horiontal or vertical display of the percentage of users voted for an answer.', 1, 0, 3, 1166649086, 'a:0:{}', 'Johannes Krausmller', 'johannes@schosemail.de', 'moses123', '2d50868629bcb3ff8eddf4c4996b1208', 'Fixed a small issue in the LIST view.', '', 5001, 0, 0),
(3560, 0, 'jk_poll', 1, '0.3.7', 9294, 66, 'Poll', 'A poll based on the extension quickpoll. A template-file can be used to define the output in the frontend. It is also possible to create a horiontal or vertical display of the percentage of users voted for an answer.', 1, -1, 3, 1158140374, 'a:0:{}', 'Johannes Krausmller', 'johannes@schosemail.de', 'moses123', '5694089453a649bde74a08a3314f6e7b', 'Updated finnish and spanish translation (thanks to Katja Lampela and Manuel Montoya).', '', 3007, 0, 0),
(3561, 0, 'jk_poll', 1, '0.3.8', 9294, 116, 'Poll', 'A poll based on the extension quickpoll. A template-file can be used to define the output in the frontend. It is also possible to create a horiontal or vertical display of the percentage of users voted for an answer.', 1, -1, 3, 1158783688, 'a:0:{}', 'Johannes Krausmller', 'johannes@schosemail.de', 'moses123', '8df51fce1ee414be62fd68eb6489a542', 'Fixed a bug in the IP-check.', '', 3008, 0, 0),
(3562, 0, 'jk_poll', 1, '0.4.0', 9294, 24, 'Poll', 'A poll based on the extension quickpoll. A template-file can be used to define the output in the frontend. It is also possible to create a horiontal or vertical display of the percentage of users voted for an answer.', 1, -1, 3, 1161445255, 'a:0:{}', 'Johannes Krausmller', 'johannes@schosemail.de', 'moses123', '9b291397d3799faf871924cc20e0ae7c', 'Added some options to the image defined in the poll (like options for content element image).\nAdded new type result, which shows the result of the last poll-record.\n', '', 4000, 0, 0),
(3563, 0, 'jk_poll', 1, '0.4.1', 9294, 95, 'Poll', 'A poll based on the extension quickpoll. A template-file can be used to define the output in the frontend. It is also possible to create a horiontal or vertical display of the percentage of users voted for an answer.', 1, 0, 3, 1162125088, 'a:0:{}', 'Johannes Krausmller', 'johannes@schosemail.de', 'moses123', 'c16d068d5920224ba6bb83dfe0b430cc', 'Added configuration for default color of the poll bars.\nAdded italian language (thanks to Claudio Strizzolo).', '', 4001, 0, 0),
(3564, 0, 'jk_poll', 1, '0.4.2', 9294, 340, 'Poll', 'A poll based on the extension quickpoll. A template-file can be used to define the output in the frontend. It is also possible to create a horiontal or vertical display of the percentage of users voted for an answer.', 1, 0, 3, 1162324569, 'a:0:{}', 'Johannes Krausmller', 'johannes@schosemail.de', 'moses123', '39954777698a8c8f3c78accb1613b809', 'Some minor changes.', '', 4002, 0, 0),
(3565, 0, 'jk_poll', 1, '0.5.0', 9294, 343, 'Poll', 'A poll based on the extension quickpoll. A template-file can be used to define the output in the frontend. It is also possible to create a horiontal or vertical display of the percentage of users voted for an answer.', 1, 0, 3, 1164748871, 'a:0:{}', 'Johannes Krausmller', 'johannes@schosemail.de', 'moses123', '8ee09dc45a7a91e9f58040988612760c', 'Security fixes for status reviewed.', '', 5000, 0, 0),
(3566, 0, 'jk_poll', 1, '0.5.2', 9294, 269, 'Poll', 'A poll based on the extension quickpoll. A template-file can be used to define the output in the frontend. It is also possible to create a horiontal or vertical display of the percentage of users voted for an answer.', 1, 0, 3, 1172008338, 'a:0:{}', 'Johannes Krausmller', 'johannes@schosemail.de', 'moses123', 'd27d12e65823f5364ce44daa38447971', 'Added feature to forward to a page after successful vote.\nAdded french translation (thanks to Grgory Duchesnes).\nSmall fix for the captcha-html output (thanks to Daniele Maffoli).', '', 5002, 0, 0),
(3567, 0, 'jk_poll', 1, '0.5.3', 9294, 466, 'Poll', 'A poll based on the extension quickpoll. A template-file can be used to define the output in the frontend. It is also possible to create a horiontal or vertical display of the percentage of users voted for an answer.', 1, 0, 3, 1173136527, 'a:0:{}', 'Johannes Krausmller', 'johannes@schosemail.de', 'moses123', '90356e60f288664274e0195edd4ea2c0', 'Fix bug in new feature foward to page.', '', 5003, 0, 0),
(3568, 0, 'jk_poll', 1, '0.5.4', 9294, 1200, 'Poll', 'A poll based on the extension quickpoll. A template-file can be used to define the output in the frontend. It is also possible to create a horiontal or vertical display of the percentage of users voted for an answer.', 1, 0, 3, 1177532282, 'a:0:{}', 'Johannes Krausmller', 'johannes@schosemail.de', 'moses123', '639c4c956d5033be85a71568a5681c88', 'Fixed bug when using TypoScript to configure the extension. Thanks to Nabil Chaoui.\nIn the last update a label for "votes" was added to the template file. When updating be sure that a translation for your language is available.', '', 5004, 0, 0),
(3569, 0, 'jk_poll', 1, '0.6.0', 9294, 572, 'Poll', 'A poll based on the extension quickpoll. A template-file can be used to define the output in the frontend. It is also possible to create a horiontal or vertical display of the percentage of users voted for an answer.', 1, 0, 3, 1203189244, 'a:0:{}', 'Johannes Krausmller', 'johannes@schosemail.de', 'moses123', 'dedd7b974cd04b93df4c36efda91a8df', 'Added support for multilanguage sites.\r\n\r\nCAUTION: When updating from an older version use the UPDATE in Ext Manager (see Manual).', '', 6000, 0, 0),
(3570, 0, 'jk_poll', 1, '0.5.5', 9294, 532, 'Poll', 'A poll based on the extension quickpoll. A template-file can be used to define the output in the frontend. It is also possible to create a horiontal or vertical display of the percentage of users voted for an answer.', 1, 0, 3, 1208005318, 'a:0:{}', 'Johannes Krausmller', 'johannes@schosemail.de', 'moses123', '74e10a069eb1a5f25c73b7b1bbeb0307', 'Corrected the sql code used for creating the tables needed.', '', 5005, 0, 0),
