(3574, 0, 'jk_poll', 1, '0.7.2', 9294, 537, 'Poll', 'A poll based on the extension quickpoll. A template-file can be used to define the output in the frontend. It is also possible to create a horiontal or vertical display of the percentage of users voted for an answer.', 1, 0, 3, 1250708531, 'a:0:{}', 'Johannes Krausmueller', 'johannes@schosemail.de', 'moses123', 'be65e70e12ffcf3295c0adf8d9edf184', 'Fixed bug in result view. Thanks to Jan Anne de Haan.', '', 7002, 0, 0),
(3575, 0, 'jk_poll', 1, '0.8.0', 9294, 42, 'Poll', 'A poll based on the extension quickpoll. A template-file can be used to define the output in the frontend. It is also possible to create a horiontal or vertical display of the percentage of users voted for an answer.', 1, 0, 3, 1284575531, 'a:0:{}', 'Johannes Krausmueller', 'johannes@krausmueller.de', 'moses123', '36cf6c118faba24b056c870282bad17c', 'Added some new features (see changelog in documentation) and bugfixing.', '', 8000, 0, 0),
