(3577, 0, 'jk_poll', 1, '0.8.2', 9294, 159, 'Poll', 'A poll based on the extension quickpoll. A template-file can be used to define the output in the frontend. It is also possible to create a horiontal or vertical display of the percentage of users voted for an answer.', 1, 0, 3, 1286739871, 'a:0:{}', 'Johannes Krausmueller', 'johannes@krausmueller.de', 'moses123', '0f9f6a7038361390e63d720ec0e8324b', 'Change in form-tag to be XHTML 1.0 Strict compatible (thanks to Gernot Leitgab for the hint).\r\nIncluded danish translation (thanks to Morten Nisker).', '', 8002, 0, 0),
(3578, 0, 'jk_poll', 1, '0.9.0', 9294, 135, 'Poll', 'A poll based on the extension quickpoll. A template-file can be used to define the output in the frontend. It is also possible to create a horiontal or vertical display of the percentage of users voted for an answer.', 1, 0, 3, 1290356823, 'a:0:{}', 'Johannes Krausmueller', 'johannes@krausmueller.de', 'moses123', 'fc73b88e910756fcb43eb735dfd42811', 'CAUTION: When upgrading from a version older than 0.9 and using flexform for configuration of the poll plugin, all settings are lost. Since the structure of the flexform changed you have to configure it again. Configuration via TypoScript is not affected.', '', 9000, 0, 0),
(3579, 0, 'jk_poll', 1, '0.9.1', 9294, 213, 'Poll', 'A poll based on the extension quickpoll. A template-file can be used to define the output in the frontend. It is also possible to create a horiontal or vertical display of the percentage of users voted for an answer.', 1, 0, 3, 1294439394, 'a:0:{}', 'Johannes Krausmueller', 'johannes@krausmueller.de', 'moses123', '6b678cf650174c9b0587817784903bf5', 'Restructured form for creating a new poll record.\r\nAdded marker VOTES_COUNT.\r\nSee changelog in manual for details.', '', 9001, 0, 0),
(3580, 0, 'jk_poll', 1, '0.9.2', 9294, 472, 'Poll', 'A poll based on the extension quickpoll. A template-file can be used to define the output in the frontend. It is also possible to create a horiontal or vertical display of the percentage of users voted for an answer.', 1, 0, 3, 1300738293, 'a:0:{}', 'Johannes Krausmueller', 'johannes@krausmueller.de', 'moses123', '4f566a73d8ba31a2858cdca230b0a163', 'Some minor bugfixes.\r\nAdded french translation (thanks to Hugo Laporte).', '', 9002, 0, 0),
(3581, 0, 'jk_poll', 1, '0.9.3', 9294, 174, 'Poll', 'A poll based on the extension quickpoll. A template-file can be used to define the output in the frontend. It is also possible to create a horiontal or vertical display of the percentage of users voted for an answer.', 1, 0, 3, 1323811508, 'a:0:{}', 'Johannes Krausmueller', 'johannes@krausmueller.de', 'moses123', 'f982b70b3d4cdfdcbb569d33214846f1', 'Fixed bug when configuring cookies with TypoScript (thanks to Hicham Souiba for pointing out). Changed extension from USER back to USER_INT (prevents caching).', '', 9003, 0, 0),
(3582, 0, 'jk_poll', 1, '0.9.4', 9294, 0, 'Poll', 'A poll based on the extension quickpoll. A template-file can be used to define the output in the frontend. It is also possible to create a horiontal or vertical display of the percentage of users voted for an answer.', 1, 0, 3, 1334858940, 'a:0:{}', 'Johannes Krausmueller', 'johannes@krausmueller.de', 'moses123', '2305ed9623604f9c92a128fda6d54820', 'Fixes a bug in CSS result view.', '', 9004, 0, 0),
(3583, 0, 'jk_poll', 1, '0.9.5', 9294, 0, 'Poll', 'A poll based on the extension quickpoll. A template-file can be used to define the output in the frontend. It is also possible to create a horiontal or vertical display of the percentage of users voted for an answer.', 1, 0, 3, 1346359836, 'a:0:{}', 'Johannes Krausmueller', 'johannes@krausmueller.de', 'moses123', '125ee744f15e359e860f80b0c326ff5b', 'Now shows correct answers in LIST view when using multiple languages (thanks to Daniel Sigrist).\n\nAdded feature to limit the amount of answers shown (e.g. only the top 3 answers most voted for).\n\nUpdated manual.', '', 9005, 0, 0),
