(3624, 0, 'joh_advbesearch', 1, '0.5.0', 2416, 71, 'Advanced DB Search', 'Search DB tables using a query wizard', 1, 0, 1, 1132688148, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:11:"0.0.6-0.0.6";s:3:"php";s:11:"0.0.6-0.0.6";}}', 'JoH', 'info@cybercraft.de', 'cybercraft', '23e3fa55cb2590aee0b7b432076ee2a1', 'Better performance due to reduced number of SELECT querys.\r\nIf a related table is used more than once during the SELECT the values are taken from a prefilled array instead.\r\n\r\nAdditional checkbox to enable formatted output of labels, strings and dates ins', '', 5000, 0, 0),
(3625, 0, 'joh_advbesearch', 1, '0.5.1', 2416, 18, 'Advanced DB Search', 'Search DB tables using a query wizard', 1, 0, 1, 1132964422, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:11:"0.0.6-0.0.6";s:3:"php";s:11:"0.0.6-0.0.6";}}', 'JoH', 'info@cybercraft.de', 'cybercraft', '29c68842e5b1f0edb34305f917a934db', 'Fixed a bug with table relations and selectboxes not correctly labelled when checking the "use formatted" checkbox and the field value is not an integer but alphanumeric.', '', 5001, 0, 0),
(3626, 0, 'joh_advbesearch', 1, '0.6.0', 2416, 37, 'Advanced DB Search', 'Search DB tables using a query wizard', 1, 0, 1, 1132973785, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:11:"0.0.7-0.0.7";s:3:"php";s:11:"0.0.7-0.0.7";}}', 'JoH', 'info@cybercraft.de', 'cybercraft', '0b3b84016a018336cf4e7818d836094b', 'Added a replacement class to make search queries available as actions in the user task center.\r\n\r\nThis will replace the original query-action based on the DB check extension.\r\n\r\nSimply create an action in the root of your website, then create a query and', '', 6000, 0, 0),
(3627, 0, 'joh_advbesearch', 1, '0.6.1', 2416, 27, 'Advanced DB Search', 'Search DB tables using a query wizard', 1, 0, 1, 1133113611, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:11:"0.0.7-0.0.7";s:3:"php";s:11:"0.0.7-0.0.7";}}', 'JoH', 'info@cybercraft.de', 'cybercraft', '73b8e75bd41e34601e3af8d09b6a7a99', 'Fixed a bug with missing function getTreeList for non admin users.\r\n\r\nChanged the "Save to action" behaviour so that only admin users can save to actions while non admin users can only save inside their session.\r\nThe actions in the Taskcenter will still b', '', 6001, 0, 0),
(3628, 0, 'joh_advbesearch', 1, '0.6.2', 2416, 26, 'Advanced DB Search', 'Search DB tables using a query wizard', 1, 0, 1, 1133223705, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:11:"0.0.8-0.0.8";s:3:"php";s:11:"0.0.8-0.0.8";}}', 'JoH', 'info@cybercraft.de', 'cybercraft', '8b9220a660d9b2a943e324598f495077', 'Fixed a bug with a surplus use of getPagePermsClause for non admin users.\r\nSelectboxes and results for DB relations will now be labelled correctly as long as the related record is inside the DB-mounts of the BE-user.\r\n', '', 6002, 0, 0),
(3629, 0, 'joh_advbesearch', 1, '0.6.3', 2416, 36, 'Advanced DB Search', 'Search DB tables using a query wizard', 1, 0, 1, 1133406454, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:11:"0.0.8-0.0.8";s:3:"php";s:11:"0.0.8-0.0.8";}}', 'JoH', 'info@cybercraft.de', 'cybercraft', '4d189f2c3d7b2efbe6befbec9d801328', 'Fixed a bug with selected values not marked as selected anymore.\r\n\r\nAdded DB-mounts in the taskcenter for result lists of non admin users.\r\n\r\nAdded the checkbox setting for labelled results to the edit query link in the taskcenter.\r\n\r\nRemoved some unneces', '', 6003, 0, 0),
(3630, 0, 'joh_advbesearch', 1, '0.7.0', 2416, 106, 'Advanced DB Search', 'Search DB tables using a query wizard', 1, 0, 1, 1134033025, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:11:"0.0.8-0.0.8";s:3:"php";s:11:"0.0.8-0.0.8";}}', 'JoH', 'info@cybercraft.de', 'cybercraft', 'ea4409f524de7e477ba82b0f538ab421', 'Added hooks processing to the queryMaker. \r\n\r\nAdded a first hook for additional Buttons in the result row display. This way the user can create additional Buttons like "create new related record" and have them prefilled with values taken from the result.\r', '', 7000, 0, 0),
(3631, 0, 'joh_advbesearch', 1, '0.7.1', 2416, 15, 'Advanced DB Search', 'Search DB tables using a query wizard', 1, 0, 1, 1135108546, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:11:"0.0.9-0.0.9";s:3:"php";s:11:"0.0.9-0.0.9";}}', 'JoH', 'info@cybercraft.de', 'cybercraft', 'ac35adebe1f2f021f6c5685cd6e0edb9', 'Fixed a bug with date fields displayed as datettimefields in querymaker and results\r\n\r\n', '', 7001, 0, 0),
(3632, 0, 'joh_advbesearch', 1, '0.8.0', 2416, 27, 'Advanced DB Search', 'Search DB tables using a query wizard', 1, 0, 1, 1135110858, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:11:"0.0.9-0.0.9";s:3:"php";s:11:"0.0.9-0.0.9";}}', 'JoH', 'info@cybercraft.de', 'cybercraft', 'e493618bfbeed0ad6c6c8eb215465f9d', 'Added support for the TCA ctrl "label_alt" so that entries in selectboxes are labelled correctly if the original label field is empty.', '', 8000, 0, 0),
(3633, 0, 'joh_advbesearch', 1, '0.8.1', 2416, 23, 'Advanced DB Search', 'Search DB tables using a query wizard', 1, 0, 1, 1135164211, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:13:"0.0.10-0.0.10";s:3:"php";s:13:"0.0.10-0.0.10";}}', 'JoH', 'info@cybercraft.de', 'cybercraft', '222d9730a6994323cc90dbe0444f8826', 'Fixed some bugs with datetime, time and date recognition.', '', 8001, 0, 0),
(3634, 0, 'joh_advbesearch', 1, '0.8.2', 2416, 18, 'Advanced DB Search', 'Search DB tables using a query wizard', 1, 0, 1, 1135206994, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:13:"0.0.11-0.0.11";s:3:"php";s:13:"0.0.11-0.0.11";}}', 'JoH', 'info@cybercraft.de', 'cybercraft', 'abd9c977bb3289ee5bc27ea9370fae1e', 'Added support for the TCA ctrl "label_alt" in result lists.\r\n\r\nAdded a checkbox to disable the use of original values in brackets as prefix for labelled results.', '', 8002, 0, 0),
(3635, 0, 'joh_advbesearch', 1, '0.8.3', 2416, 26, 'Advanced DB Search', 'Search DB tables using a query wizard', 1, 0, 1, 1135257607, 'a:0:{}', 'JoH', 'info@cybercraft.de', 'cybercraft', '6256ec1f2f21ca8f21398f43fa1b9c42', 'Fixed a a bug with the disable brackets checkbox that forced the user to refresh in order to remove the brackets.', '', 8003, 0, 0),
(3636, 0, 'joh_advbesearch', 1, '0.8.4', 2416, 45, 'Advanced DB Search', 'Search DB tables using a query wizard', 1, 0, 1, 1135293896, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:13:"0.0.12-0.0.12";s:3:"php";s:13:"0.0.12-0.0.12";}}', 'JoH', 'info@cybercraft.de', 'cybercraft', '1e4e02c36eefcf6c2d4ba3873cceec91', 'Inserted a checkbox to switch the sorting of options in selectboxes from value to label.\r\n\r\nReplaced while loops using foreach instead for better performance with long loops.\r\n', '', 8004, 0, 0),
(3637, 0, 'joh_advbesearch', 1, '0.8.5', 2416, 82, 'Advanced DB Search', 'Search DB tables using a query wizard', 1, 0, 1, 1136210542, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:13:"0.0.13-0.0.13";s:3:"php";s:13:"0.0.13-0.0.13";}}', 'JoH', 'info@cybercraft.de', 'cybercraft', '6895720d5691912267ee14cef8201e65', 'Fixed a bug with an infinite loop occurring when DB relation fields are related to more than one table.', '', 8005, 0, 0),
(3638, 0, 'joh_advbesearch', 1, '0.9.0', 2416, 83, 'Advanced DB Search', 'Search DB tables using a query wizard', 1, 0, 1, 1137545512, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:13:"0.0.14-0.0.14";s:3:"php";s:13:"0.0.14-0.0.14";}}', 'JoH', 'info@cybercraft.de', 'cybercraft', '902b2e2e8f944bab2538430c703f0aa3', 'Added another hook to insert stuff before the result table.\r\nAdded some buttons for browsing results by setting the limit and submitting the form via JacaScript.\r\nLabels of the result table are now displayed correctly when selecting "use formatted strings', '', 9000, 0, 0),
(3639, 0, 'joh_advbesearch', 1, '0.9.1', 2416, 261, 'Advanced DB Search', 'Search DB tables using a query wizard', 1, 0, 1, 1138406764, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:13:"0.0.15-0.0.15";s:3:"php";s:13:"0.0.15-0.0.15";}}', 'JoH', 'info@cybercraft.de', 'cybercraft', '7d892c8f8bcf95903afc66b17dfd7ac4', 'Added processed fieldnames as header for the CSV output.\r\nAdded User- and Group-TSconfig values to enable/disable parts of the form.\r\nSee changelog.', '', 9001, 0, 0),
(3640, 0, 'joh_advbesearch', 1, '0.10.0', 2416, 197, 'Advanced DB Search', 'Search DB tables using a query wizard', 1, 0, 1, 1141132639, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:6:"3.0.0-";s:5:"typo3";s:6:"3.5.0-";}}', 'JoH', 'info@cybercraft.de', 'cybercraft', '24bf9881a52fc9594ec6d5ac1386adaf', 'Fixed some minor bugs.\n\nAdded locallang settings to make the module aware of BE user language settings. (Thanx to Paolo Cojazzi)\n\nCurrently there are English, German and Italian settings available. Feel free to translate other languages and send me your t', '', 10000, 0, 0),
(3641, 0, 'joh_advbesearch', 1, '0.10.1', 2416, 233, 'Advanced DB Search', 'Search DB tables using a query wizard', 1, 0, 1, 1141168698, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:6:"3.0.0-";s:5:"typo3";s:6:"3.5.0-";}}', 'JoH', 'info@cybercraft.de', 'cybercraft', '096db43c8b242917b3b1fcc30a19558f', 'Added Danish translation. (Thanx to Peter Klein)', '', 10001, 0, 0),
(3642, 0, 'joh_advbesearch', 1, '0.11.0', 2416, 680, 'Advanced DB Search', 'Search DB tables using a query wizard', 1, 0, 1, 1141901504, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:6:"3.0.0-";s:5:"typo3";s:6:"3.5.0-";}}', 'JoH', 'info@cybercraft.de', 'cybercraft', '4e9bcdcec6921cba9ee42868192970fd', 'Attention! - You can use the undelete functions in TYPO3 versions  4.x only! - Older versions will show deleted recrods but you will not be able to undelete them at the moment!', '', 11000, 0, 0),
(3643, 0, 'joh_advbesearch', 1, '1.0.0', 2416, 261, 'Advanced DB Search', 'Search DB tables using a query wizard', 2, 0, 1, 1256661537, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"3.0.0-0.0.0";s:5:"typo3";s:11:"3.5.0-0.0.0";}}', 'JoH asenau', 'info@cybercraft.de', 'cybercraft', '46100e4e24199cf221b2ef26aa768e92', 'Reimplemented changes and security fixes from DBint.\r\nSince DBint is using functions introduced by advbesearch for a while now, advbesearch includes the necessary classes directly from t3lib again. This assures that future changes to these classes will af', '', 1000000, 1, 0),
