(3658, 0, 'jp_pageteaser', 1, '1.5.3', 9384, 40, 'Page Teaser', 'Teasing subpages on a page! Every subpage can be activated for teasing. Any information for teasing are entered on each subpage in the page header. Used for teasing are the page types standard, advanced, external url, shortcut and not in menu. I', 2, 0, 3, 1125642962, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"0.0.8-0.0.8";s:3:"php";s:11:"0.0.8-0.0.8";s:3:"cms";s:0:"";}}', 'Tobias Pinnekamp', 'mail@tpinne.de', 'tpinne', 'e3a184b7c78af21292795489231ac7b6', 'Changed the manual', '', 1005003, 0, 0),
(3659, 0, 'jp_pageteaser', 1, '1.5.4', 9384, 87, 'Page Teaser', 'Teasing subpages on a page! Every subpage can be activated for teasing. Any information for teasing are entered on each subpage in the page header. Used for teasing are the page types standard, advanced, external url, shortcut and not in menu. I', 2, 0, 3, 1125643038, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"0.0.8-0.0.8";s:3:"php";s:11:"0.0.8-0.0.8";s:3:"cms";s:0:"";}}', 'Tobias Pinnekamp', 'mail@tpinne.de', 'tpinne', 'a538d2e45ec82b0a8425949433d55247', '', '', 1005004, 0, 0),
(3660, 0, 'jp_pageteaser', 1, '1.5.5', 9384, 248, 'Page Teaser', 'Teasing subpages on a page! Every subpage can be activated for teasing. Any information for teasing are entered on each subpage in the page header. Used for teasing are the page types standard, advanced, external url, shortcut and not in menu. I', 2, 0, 3, 1126248393, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"0.0.9-0.0.9";s:3:"php";s:11:"0.0.9-0.0.9";s:3:"cms";s:0:"";}}', 'Tobias Pinnekamp', 'mail@tpinne.de', 'tpinne', 'b2dd615995e705e50ed771764a28f14d', 'Added Rollover functionality for the headline if it is rendered as image. How it works look into the documentation or in the "ext_typoscript_setup.txt"', '', 1005005, 0, 0),
(3661, 0, 'jp_pageteaser', 1, '1.5.6', 9384, 1843, 'Page Teaser', 'Teasing subpages on a page! Every subpage can be activated for teasing. Any information for teasing are entered on each subpage in the page header. Used for teasing are the page types standard, advanced, external url, shortcut and not in menu. I', 2, 0, 3, 1143030132, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:6:"3.0.0-";s:5:"typo3";s:6:"3.5.0-";}}', 'Tobias Pinnekamp', 'mail@tpinne.de', 'tpinne', '0ceab61fd0aa7266602f4d74b211aeef', 'Fixed a little bug which showed also the page in the teaser where the plugin is inserted, if this page is also activated for teasing in the page header', '', 1005006, 0, 0),
(3662, 0, 'jp_pageteaser', 1, '2.0.2', 9384, 66, 'Pageteaser', 'Teaser extension for pages. High configurable. Subpages of pages and selected pages directly can be teased. Content can automatically be grabbed from pages. Default values can be set on page creation. Used for teasing are the page types standard, advanced', 1, 0, 3, 1157120219, 'a:0:{}', 'Tobias Pinnekamp', 'typo3@tpinne.de', 'tpinne', '9c1c249a8dcea688b788b1993eadc056', '2.0.2: New sorttype, new typoscript options, bugfixes. \r\nBEFORE using/upgrading you should read the README.txt located in the details view. Incompatible to versions 1.x.x.', '', 2000002, 0, 0),
(3663, 0, 'jp_pageteaser', 1, '2.0.3', 9384, 148, 'Pageteaser', 'Teaser extension for pages. High configurable. Subpages of pages and selected pages directly can be teased. Content can automatically be grabbed from pages. Default values can be set on page creation. Update script included for upgrading older versions!', 1, 0, 3, 1157400584, 'a:0:{}', 'Tobias Pinnekamp', 'typo3@tpinne.de', 'tpinne', '7cb8a101a141bc45e8c09195dc4b9702', 'Bugfix with sort type default. BEFORE using/upgrading you should read the README.txt located in the details view. Incompatible to versions 1.x.x.', '', 2000003, 0, 0),
(3664, 0, 'jp_pageteaser', 1, '2.0.0', 9384, 104, 'Pageteaser', 'Teaser extension for pages. High configurable. Subpages of pages and selected pages directly can be teased. Used for teasing are the page types standard, advanced, external url, shortcut and not in menu.', 1, 0, 3, 1156922246, 'a:0:{}', 'Tobias Pinnekamp', 'typo3@tpinne.de', 'tpinne', '9eb2939934ef2759ae40c078a65ed1ef', 'BEFORE using you should read the README.txt located in the details view. MAJOR changes and incompatible to older versions and BETA. But with update script. NEW: Auto Content Grabbing, Pagebrowser, Defaultvalues, ...', '', 2000000, 0, 0),
(3665, 0, 'jp_pageteaser', 1, '2.0.1', 9384, 116, 'Pageteaser', 'Teaser extension for pages. High configurable. Subpages of pages and selected pages directly can be teased. Used for teasing are the page types standard, advanced, external url, shortcut and not in menu.', 1, 0, 3, 1157107512, 'a:0:{}', 'Tobias Pinnekamp', 'typo3@tpinne.de', 'tpinne', '91ca475bd30ded3c6ca0d98b87096986', 'BEFORE using you should read the README.txt located in the details view. MAJOR changes and incompatible to older versions. NEW: Auto Content Grabbing, Pagebrowser, Defaultvalues. 2.0.1 Bugfixes', '', 2000001, 0, 0),
(3666, 0, 'jp_pageteaser', 1, '2.0.4', 9384, 244, 'Pageteaser', 'Teaser extension for pages. High configurable. Subpages of pages and selected pages directly can be teased. Content can automatically be grabbed from pages. Default values can be set on page creation. Update script included for upgrading older versions!', 1, 0, 3, 1157540442, 'a:0:{}', 'Tobias Pinnekamp', 'typo3@tpinne.de', 'tpinne', 'bd07849255a1f8db86d2331c9f1fa1d0', 'Several bugfixes. Should work proper with non-templavoila environments now. Please send feedback if not.', '', 2000004, 0, 0),
(3667, 0, 'jp_pageteaser', 1, '2.0.5', 9384, 175, 'Pageteaser', 'Teaser extension for pages. High configurable. Subpages of pages and selected pages directly can be teased. Content can automatically be grabbed from pages. Default values can be set on page creation. Update script included for upgrading older versions!', 1, 0, 3, 1158567647, 'a:0:{}', 'Tobias Pinnekamp', 'typo3@tpinne.de', 'tpinne', '1c6a65d473dc863a941c5aaa67958b55', '- Changed ImageWidth Constant, because didnt work - added TS option for enabling/disabling auto content - Bugfixes to work with no content binding paradigm of TV', '', 2000005, 0, 0),
(3668, 0, 'jp_pageteaser', 1, '2.0.6', 9384, 16, 'Pageteaser', 'Teaser extension for pages. High configurable. Subpages of pages and selected pages directly can be teased. Content can automatically be grabbed from pages. Default values can be set on page creation. Update script included for upgrading older versions!', 1, 0, 3, 1158936223, 'a:0:{}', 'Tobias Pinnekamp', 'typo3@tpinne.de', 'tpinne', '8e2957474d0bba6a06e769702eaff122', 'Two new functions:\r\n- give every x list item an individual class, see TS Constants\r\n- start the with a specific item number, like tt_news to create more flexible layouts with seperate templates, see Flexform', '', 2000006, 0, 0),
(3669, 0, 'jp_pageteaser', 1, '2.1.0', 9384, 84, 'Pageteaser', 'Teaser extension for pages. High configurable. Subpages of pages and selected pages directly can be teased. Content can automatically be grabbed from pages. Default values can be set on page creation. Update script included for upgrading older versions!', 1, 0, 3, 1159008498, 'a:0:{}', 'Tobias Pinnekamp', 'typo3@tpinne.de', 'tpinne', '80cefa7a3e674a9d96176fe838a8dcbf', 'First version of manual (without users manual yet) added. See the changelog for changes made to version 2.0.6 which was only short time available!', '', 2001000, 0, 0),
(3670, 0, 'jp_pageteaser', 1, '2.1.1', 9384, 658, 'Pageteaser', 'Teaser extension for pages. High configurable. Subpages of pages and selected pages directly can be teased. Content can automatically be grabbed from pages. Default values can be set on page creation. Update script included for upgrading older versions!', 1, 0, 3, 1159215061, 'a:0:{}', 'Tobias Pinnekamp', 'typo3@tpinne.de', 'tpinne', 'c35556a82630aa902d0781cc826c4dc3', 'Manual completed with user manual. For the small rest look in the changelog.', '', 2001001, 0, 0),
(3671, 0, 'jp_pageteaser', 1, '2.1.2', 9384, 713, 'Pageteaser', 'Teaser extension for pages. High configurable. Subpages of pages and selected pages directly can be teased. Content can automatically be grabbed from pages. Default values can be set on page creation. Update script included for upgrading older versions!', 1, 0, 3, 1170938430, 'a:0:{}', 'Tobias Pinnekamp', 'typo3@tpinne.de', 'tpinne', '29d9a7c66754a1375540892ef1087ff5', 'Bugfix: If used on multilanguage sites there was an incorrect display of the records.', '', 2001002, 0, 0),
(3672, 0, 'jp_pageteaser', 1, '2.1.3', 9384, 143, 'Pageteaser', 'Teaser extension for pages. High configurable. Subpages of pages and selected pages directly can be teased. Content can automatically be grabbed from pages. Default values can be set on page creation. Update script included for upgrading older versions!', 1, 0, 3, 1183124677, 'a:0:{}', 'Tobias Pinnekamp', 'typo3@tpinne.de', 'tpinne', '132c1136172c36defe3b6ceea0ae9b74', 'Bugfix: This is a fix for the problem with direct_mail when creating a new newsletter page. This should be fixed. If there are still problems please contact me.', '', 2001003, 0, 0),
(3673, 0, 'jp_pageteaser', 1, '2.1.4', 9384, 63, 'Pageteaser', 'Teaser extension for pages. High configurable. Subpages of pages and selected pages directly can be teased. Content can automatically be grabbed from pages. Default values can be set on page creation. Update script included for upgrading older versions!', 1, 0, 3, 1185783924, 'a:0:{}', 'Tobias Pinnekamp', 'typo3@tpinne.de', 'tpinne', '07b818489b227e27809173ffec7b981b', 'Bugfix: After the fix for direct_mail there was a problem to create teaser records automatically on page creation. This is now fixed.', '', 2001004, 0, 0),
