(3763, 0, 'kb_cleanfiles', 1, '0.3.0', 4420, 1262, 'KB Clean Files', 'Cleans upload folders from unused files', 2, 0, 1, 1135858337, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"0.0.2-0.0.2";s:3:"php";s:11:"0.0.2-0.0.2";s:3:"cms";s:0:"";}}', 'Bernhard Kraft', 'kraftb@kraftb.at', 'ext_kb_cleanfiles', 'c44f58b22cdc136627fd52b063f561e9', 'Flexform Languages get respected.\r\n"Sections" in Flexforms get parsed now.\r\nFixed some issues with uninitalized arrays.', 'think-open', 3000, 0, 0),
