(3765, 0, 'kb_conttable', 1, '0.1.0', 4515, 56, 'KB Content Table', 'Contentelement for enhanced table editing and content element integration', 0, 0, 2, 1115067606, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"3.8.1-3.8.1";s:3:"php";s:12:"4.1.1-4.3.12";s:3:"cms";s:0:"";}}', 'Kraft Bernhard', 'kraftb@kraftb.at', 'kraftb', 'cc3fd4cea439e2b8a9bcb0f3a6638fb8', 'Completely rewritten !!!\r\n Now completely Flexform based.\r\n Configuration via 2D optionSplit\r\n Many other new features: see first documentation paragraph.\r\nRequires upcoming 3.8.0(beta3) for full functionality (or hook-patch in included diff file)', '', 1000, 0, 0),
(3766, 0, 'kb_conttable', 1, '0.1.1', 4515, 109, 'KB Content Table', 'Contentelement for enhanced table editing and content element integration', 0, 0, 2, 1115400298, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"3.8.1-3.8.1";s:3:"php";s:12:"4.1.1-4.3.12";s:3:"cms";s:0:"";}}', 'Kraft Bernhard', 'kraftb@kraftb.at', 'kraftb', 'e4fbd5464a2e6709251914bea7b4a34d', ' Completely rewritten - see first documenation paragraph for features \r\nUpdated manual (now includes screenshots directly - upload limit was raised :)\r\nAdded section regarding the ERROR: NEW4277ac44005ea error.', '', 1001, 0, 0),
(3767, 0, 'kb_conttable', 1, '0.1.2', 4515, 239, 'KB Content Table', 'Contentelement for enhanced table editing and content element integration', 0, 0, 2, 1115916175, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"3.8.1-3.8.1";s:3:"php";s:12:"4.1.1-4.3.12";s:3:"cms";s:0:"";}}', 'Kraft Bernhard', 'kraftb@kraftb.at', 'kraftb', 'e0fcdb81d822c402192661fae52c6c94', 'Included a workaround for a bug in T3 3.7.0 so now Templating should also work in this version if the included patch gets applied.', '', 1002, 0, 0),
(3768, 0, 'kb_conttable', 1, '0.1.3', 4515, 106, 'KB Content Table', 'Contentelement for enhanced table editing and content element integration', 0, 0, 2, 1119005140, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"3.8.2-3.8.2";s:3:"php";s:12:"4.1.2-4.3.13";s:3:"cms";s:0:"";}}', 'Kraft Bernhard', 'kraftb@kraftb.at', 'kraftb', '25bc73bea021da30fced302b73e09a11', 'Updated documentation', '', 1003, 0, 0);
