(3769, 0, 'kb_conttable', 1, '0.1.4', 4515, 63, 'KB Content Table', 'Contentelement for enhanced table editing and content element integration', 0, 0, 2, 1121014908, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"3.8.3-3.8.3";s:3:"php";s:12:"4.1.3-4.3.14";s:3:"cms";s:0:"";}}', 'Kraft Bernhard', 'kraftb@kraftb.at', 'kraftb', 'b5b25f2b6e6d47f63876b83e600c97d4', 'Fixed a bug which caused that the content element couldnt be copied or imported.\r\nIncluded German translations', '', 1004, 0, 0),
(3770, 0, 'kb_conttable', 1, '0.2.0', 4515, 113, 'KB Content Table', 'Contentelement for enhanced table editing and content element integration', 0, 0, 2, 1122138793, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"3.8.3-3.8.3";s:3:"php";s:12:"4.1.3-4.3.14";s:3:"cms";s:0:"";}}', 'Kraft Bernhard', 'kraftb@kraftb.at', 'kraftb', '8409ee5d3905dbc19a98f623fb4923c8', 'Introduced Fast-Mode which stores the cell properties in a serialized array. This increaseses speed but cell properties cant get edited from the T3 record editing screen anymore but rather from the table wizard. Also the RTE fields now only get inserte', '', 2000, 0, 0),
(3771, 0, 'kb_conttable', 1, '0.2.1', 4515, 425, 'KB Content Table', 'Contentelement for enhanced table editing and content element integration', 0, 0, 2, 1122643675, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"3.8.3-3.8.3";s:3:"php";s:12:"4.1.3-4.3.14";s:3:"cms";s:0:"";}}', 'Kraft Bernhard', 'kraftb@kraftb.at', 'kraftb', 'cb338b8ef5e6fe6fb7c9a1437a1ab54a', 'Fixed a bug which resulted in not being able to save RTE content.\r\nThis bug occured only when creating new tables with version 0.2.0 because of the change that the RTE editor is only included when needed.', '', 2001, 0, 0),
(3772, 0, 'kb_conttable', 1, '0.2.2', 4515, 60, 'KB Content Table', 'Contentelement for enhanced table editing and content element integration', 0, 0, 2, 1130479987, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"3.8.4-3.8.4";s:3:"php";s:12:"4.1.4-4.3.15";s:3:"cms";s:0:"";}}', 'Kraft Bernhard', 'kraftb@kraftb.at', 'kraftb', '89bfa355d024eee3348e437260449fa8', 'Fixed a small issue which caused locked fields to note be set/locked properly.', '', 2002, 0, 0),
(3773, 0, 'kb_conttable', 1, '0.2.3', 4515, 90, 'KB Content Table', 'Contentelement for enhanced table editing and content element integration', 0, 0, 2, 1131056261, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"3.8.5-3.8.5";s:3:"php";s:12:"4.1.5-4.3.16";s:3:"cms";s:0:"";}}', 'Kraft Bernhard', 'kraftb@kraftb.at', 'kraftb', '5a8fc1344b9e6b08b26fe68da838a89a', 'Fixed a problem which lead to not working locking.\r\nCompleted locking mechanism by adding fields for the last actions which werent lockable (Hide Cells, Move cells)', '', 2003, 0, 0),
(3774, 0, 'kb_conttable', 1, '0.2.4', 4515, 217, 'KB Content Table', 'Contentelement for enhanced table editing and content element integration', 0, 0, 2, 1132140468, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"3.8.5-3.8.5";s:3:"php";s:12:"4.1.5-4.3.16";s:3:"cms";s:0:"";}}', 'Kraft Bernhard', 'kraftb@kraftb.at', 'kraftb', 'f672f4ddeb6b4510c6597f99c3e3506d', 'Fixed 2 bugs with RTE mode', '', 2004, 0, 0),
(3775, 0, 'kb_conttable', 1, '0.2.5', 4515, 225, 'KB Content Table', 'Contentelement for enhanced table editing and content element integration', 0, 0, 2, 1136201197, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"3.8.5-3.8.5";s:3:"php";s:12:"4.1.5-4.3.16";s:3:"cms";s:0:"";}}', 'Kraft Bernhard', 'kraftb@kraftb.at', 'kraftb', '96aefc2bcdb0bf3af8ce509169605999', 'Implemented the Template Keep mode. This allows to save a template in such a way that when it gets used only the style definitions get copied to the actual table but not any information about the number of rows and their content: Content stays - Style', '', 2005, 0, 0),
(3776, 0, 'kb_conttable', 1, '0.2.6', 4515, 1819, 'KB Content Table', 'Contentelement for enhanced table editing and content element integration', 0, 0, 2, 1139861273, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"3.8.5-3.8.5";s:3:"php";s:12:"4.1.5-4.3.16";s:3:"cms";s:0:"";}}', 'Kraft Bernhard', 'kraftb@kraftb.at', 'kraftb', 'e250754c610985d600574203de9efdc2', 'Now works together with kb_pm_paste', '', 2006, 0, 0),
(3777, 0, 'kb_conttable', 1, '0.2.7', 4515, 5, 'KB Content Table', 'Contentelement for enhanced table editing and content element integration', 0, 0, 2, 1259404619, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"3.8.5-3.8.5";s:3:"php";s:12:"4.1.5-4.3.16";s:3:"cms";s:0:"";}}', 'Kraft Bernhard', 'kraftb@kraftb.at', 'kraftb', '7fe2baf7e0fce853565fc2a4008b6f26', 'Now works properly with TYPO3 versions 4.x (4.2 and 4.3 tested)', '', 2007, 0, 0),
(3778, 0, 'kb_conttable', 1, '0.2.8', 4515, 13, 'KB Content Table', 'Contentelement for enhanced table editing and content element integration', 2, 0, 2, 1259406895, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"3.8.5-3.8.5";s:3:"php";s:12:"4.1.5-4.3.16";s:3:"cms";s:0:"";}}', 'Kraft Bernhard', 'kraftb@kraftb.at', 'kraftb', 'a3591279c90132c08ec7623ea3493e84', ' Updated the extension to work with TYPO3 4.x versions (4.2 and 4.3 tested)\r\n Raised TER state from "alpha" to "stable"\r\n', '', 2008, 0, 0),
