(3991, 0, 'ldap_auth', 1, '0.2.0', 4711, 1447, 'LDAP Authentification Service', 'This extension provides a service for authentification against LDAP directories. It is based on the authentification service system established by the extension cc_sv_auth', 2, 0, 5, 1107330911, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"0.0.2-0.0.2";s:3:"php";s:11:"0.0.2-0.0.2";s:11:"ldap_server";s:0:"";}}', 'Daniel Thomas', 'dt@dpool.net', 'dt_dpool', '0784bd1524dc96ff793d85cbc8566ab2', 'This version makes use of the GLOBALS LDAP Object provided by ldap_server as of version 0.2.0. Some changes in the documentation.\r\n\r\nIMPORTANT: If you have updated the Ren Fritzs cc_sv_auth extension to version 1.1.0 you will need to update all the ldap', '', 2000, 0, 0),
(3992, 0, 'ldap_auth', 1, '0.2.1', 4711, 2690, 'LDAP Authentification Service', 'This extension provides a service for authentification against LDAP directories. It is based on the authentification service system established by the extension cc_sv_auth', 2, 0, 5, 1130851577, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"0.0.2-0.0.2";s:3:"php";s:11:"0.0.2-0.0.2";s:11:"ldap_server";s:0:"";}}', 'Daniel Thomas', 'dt@dpool.net', 'dt_dpool', 'd84337f3646ba2c2aac1b048562571ca', '- added support for logout in a single-sign-on scenario\r\n- better use of TYPO3 API.', '', 2001, 1, 0),
