(3994, 0, 'ldap_lib', 1, '0.0.2', 4173, 32, 'LDAP Library', 'This extension provides a class you can use in your own extensions for connecting and retrieving data from LDAP Sources.', 2, 0, 4, 1100529298, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";}}', 'Daniel Thomas', 'dt@dpool.net', 'dt_dpool', '171add5bd4676da807325356182aa955', '', '', 2, 0, 0),
(3995, 0, 'ldap_lib', 1, '0.1.0', 4173, 361, 'LDAP Library', 'This extension provides a class you can use in your own extensions for connecting and retrieving data from LDAP Sources.', 2, 0, 4, 1100560367, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:11:"0.0.2-0.0.2";s:3:"php";s:11:"0.0.2-0.0.2";}}', 'Daniel Thomas', 'dt@dpool.net', 'dt_dpool', '4b142c3e0f62b02714476a2c2f4670b5', '', '', 1000, 0, 0),
(3996, 0, 'ldap_lib', 1, '0.2.0', 4173, 3385, 'LDAP Library', 'This extension provides a class you can use in your own extensions for connecting and retrieving data from LDAP Sources.', 2, 0, 4, 1107330670, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:11:"0.0.3-0.0.3";s:3:"php";s:11:"0.0.3-0.0.3";}}', 'Daniel Thomas', 'dt@dpool.net', 'dt_dpool', '47fe8bd52e2f9e236b672dd62387d64d', 'No major changes. Goes along with the versioning of the other ldap_ extensions.', '', 2000, 1, 0),
(3997, 0, 'ldap_macmade', 1, '0.1.0', 1161, 1150, 'OpenLDAP / macmade.net', 'This extension allows you to import and authenticate Typo3 users (frontend & backend) from OpenLDAP servers. You can also synchronize the LDAP users with any other database table. All the mapping process is done visually, through flexforms.', 0, 0, 1, 1132670760, 'a:1:{s:7:"depends";a:6:{s:5:"typo3";s:11:"0.0.2-0.0.2";s:3:"php";s:11:"0.0.2-0.0.2";s:3:"cms";s:0:"";s:4:"lang";s:0:"";s:2:"sv";s:0:"";s:11:"api_macmade";s:0:"";}}', 'Jean-David Gadina', 'macmade@gadlab.net', 'abandoned_extensions', '6b4b1648d04484ce7aeaec00ad28da03', '', 'macmade.net', 1000, 1, 0),
(3998, 0, 'ldap_server', 1, '0.0.1', 4300, 25, 'LDAP Server Konfiguration', '', 1, 0, 4, 1099313381, 'a:1:{s:7:"depends";a:4:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:3:"cms";s:0:"";s:8:"ldap_lib";s:0:"";}}', 'Daniel Thomas', 'dt@dpool.net', 'dt_dpool', 'b6cec03c22c744b0d11a8f8449872786', '', '', 1, 0, 0),
(3999, 0, 'ldap_server', 1, '0.0.2', 4300, 19, 'LDAP Server Konfiguration', 'This extension provides a framework for extensions like ldap_auth and ldap_sync which need to connect to LDAP sources.', 1, 0, 4, 1100558780, 'a:1:{s:7:"depends";a:4:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:3:"cms";s:0:"";s:8:"ldap_lib";s:0:"";}}', 'Daniel Thomas', 'dt@dpool.net', 'dt_dpool', '7a257bcee69851828a13f207acbfdb91', '', '', 2, 0, 0),
(4000, 0, 'ldap_server', 1, '0.1.0', 4300, 380, 'LDAP Server Konfiguration', 'This extension provides a framework for extensions like ldap_auth and ldap_sync which need to connect to LDAP sources.', 2, 0, 4, 1100619666, 'a:0:{}', 'Daniel Thomas', 'dt@dpool.net', 'dt_dpool', '1700e7cee4a626580fe090de5be03f10', '', '', 1000, 0, 0),
(4001, 0, 'ldap_server', 1, '0.2.0', 4300, 1297, 'LDAP Server Konfiguration', 'This extension provides a framework for extensions like ldap_auth and ldap_sync which need to connect to LDAP sources.', 2, 0, 4, 1107332567, 'a:1:{s:7:"depends";a:4:{s:5:"typo3";s:11:"0.0.3-0.0.3";s:3:"php";s:11:"0.0.3-0.0.3";s:3:"cms";s:0:"";s:8:"ldap_lib";s:0:"";}}', 'Daniel Thomas', 'dt@dpool.net', 'dt_dpool', '30329e140c20c3ce11be94646f2a5548', '	Some minor changes in documentation and bugfixes in the code. The LDAP connection object is now instantiated as a GLOBALS object to be easily deployable in userfunctions. IMPORTANT: If you have updated the Ren Fritzs cc_sv_auth extension to version 1.1', '', 2000, 0, 0),
(4002, 0, 'ldap_server', 1, '0.2.1', 4300, 2579, 'LDAP Server Konfiguration', 'This extension provides a framework for extensions like ldap_auth and ldap_sync which need to connect to LDAP sources.', 2, 0, 4, 1130851489, 'a:1:{s:7:"depends";a:4:{s:5:"typo3";s:11:"0.0.3-0.0.3";s:3:"php";s:11:"0.0.3-0.0.3";s:3:"cms";s:0:"";s:8:"ldap_lib";s:0:"";}}', 'Daniel Thomas', 'dt@dpool.net', 'dt_dpool', '791a1d547bc17cae277ab13e3383f23a', '- Added some utitlity functions for easy groupmembership mapping.\r\n- better use of TYPO3 API by invoking user functions with t3lib_div::callUserFunction', '', 2001, 1, 0),
