(4004, 0, 'ldap_sync', 1, '0.0.2', 2859, 16, 'LDAP Synchronisation Module', 'This extension provides a backend module for synchronising data from LDAP directory based on the ldap_server extension.', 2, 0, 1, 1100560033, 'a:1:{s:7:"depends";a:4:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:3:"cms";s:0:"";s:11:"ldap_server";s:0:"";}}', 'Daniel Thomas', 'dt@dpool.net', 'dt_dpool', 'c1aaa3e37df0b5f2c149d111ccb0171f', '', '', 2, 0, 0),
(4005, 0, 'ldap_sync', 1, '0.1.0', 2859, 296, 'LDAP Synchronisation Module', 'This extension provides a backend module for synchronising data from LDAP directory based on the ldap_server extension.', 2, 0, 1, 1100560818, 'a:1:{s:7:"depends";a:4:{s:5:"typo3";s:11:"0.0.2-0.0.2";s:3:"php";s:11:"0.0.2-0.0.2";s:3:"cms";s:0:"";s:11:"ldap_server";s:0:"";}}', 'Daniel Thomas', 'dt@dpool.net', 'dt_dpool', 'bc3c98375703210a783e32234dbc1582', '', '', 1000, 0, 0),
(4006, 0, 'ldap_sync', 1, '0.2.0', 2859, 840, 'LDAP Synchronisation Module', 'This extension provides a backend module for synchronising data from LDAP directory based on the ldap_server extension.', 2, 0, 1, 1107330785, 'a:1:{s:7:"depends";a:4:{s:5:"typo3";s:11:"0.0.2-0.0.2";s:3:"php";s:11:"0.0.2-0.0.2";s:3:"cms";s:0:"";s:11:"ldap_server";s:0:"";}}', 'Daniel Thomas', 'dt@dpool.net', 'dt_dpool', 'd8b0d44b0531cba7fe7bc7f263eda6bb', 'This version makes use of the GLOBALS Object for LDAP connection provided by ldap_server as of version 0.2.0. Some minor bugfixes in function handleNotFound in tx_ldapsync.\r\n\r\nIMPORTANT: If you have updated the Ren Fritzs cc_sv_auth extension to version', '', 2000, 0, 0),
(4007, 0, 'ldap_sync', 1, '0.2.1', 2859, 1690, 'LDAP Synchronisation Module', 'This extension provides a backend module for synchronising data from LDAP directory based on the ldap_server extension.', 2, 0, 1, 1130851719, 'a:1:{s:7:"depends";a:4:{s:5:"typo3";s:11:"0.0.2-0.0.2";s:3:"php";s:11:"0.0.2-0.0.2";s:3:"cms";s:0:"";s:11:"ldap_server";s:0:"";}}', 'Daniel Thomas', 'dt@dpool.net', 'dt_dpool', '52d5cf9cd2ec655a622dddf011b68ec6', 'addressed small bug in record transfer', '', 2001, 1, 0),
