(4009, 0, 'lfeditor', 1, '1.0.2', 3968, 57, 'Language File Editor', 'This extension provides the backend user the possibility to modify extension language files.The extensions supports PHP and XML, conversion from XML to PHP and vice versa, splitting and merging of language files, workspaces (xll and original content), sea', 1, 0, 1, 1139094717, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:3:"cms";s:0:"";}}', 'Stefan Galinski', 'stefan.galinski@frm2.tum.de', 'sgalinsk', '33c311c98f4628f16987da70a50bb5b9', '', 'FRM-II', 1000002, 0, 0),
(4010, 0, 'lfeditor', 1, '1.0.3', 3968, 85, 'Language File Editor', 'This extension provides the backend user the possibility to modify extension language files.The extensions supports PHP and XML, conversion from XML to PHP and vice versa, splitting and merging of language files, workspaces (xll and original content), sea', 1, 0, 1, 1139228362, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:3:"cms";s:0:"";}}', 'Stefan Galinski', 'stefan.galinski@frm2.tum.de', 'sgalinsk', '553a5173a7653897bf63f49e380e4a5e', '', 'FRM-II', 1000003, 0, 0),
(4011, 0, 'lfeditor', 1, '1.1.0', 3968, 73, 'Language File Editor', 'This extension supports site admins and developers when modify extension language files. \r\nThe module features support of PHP and XML, conversion from XML to PHP and reverse, splitting and merging of language files, workspaces (XLL and original content),', 1, 0, 1, 1139700705, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"0.0.2-0.0.2";s:3:"php";s:11:"0.0.2-0.0.2";s:3:"cms";s:0:"";}}', 'Stefan Galinski', 'stefan.galinski@frm2.tum.de', 'sgalinsk', '97f75659be68b5fccd4f6f879b0256bd', 'some minor problems fixed, some little improvements, a major failure this backups and utf8 fixed (see changelog for details)', 'FRM-II', 1001000, 0, 0),
(4012, 0, 'lfeditor', 1, '1.1.1', 3968, 412, 'Language File Editor', 'This extension supports site admins and developers when modify extension language files. \r\nThe module features support of PHP and XML, conversion from XML to PHP and reverse, splitting and merging of language files, workspaces (XLL and original content),', 1, 0, 1, 1139853066, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"0.0.2-0.0.2";s:3:"php";s:11:"0.0.2-0.0.2";s:3:"cms";s:0:"";}}', 'Stefan Galinski', 'stefan.galinski@frm2.tum.de', 'sgalinsk', '4b74ca7f931d109996bcf8e1e5b71873', 'added some htmlspecialchars() to prevent translation of html entities; updated documentation', 'FRM-II', 1001001, 0, 0),
(4013, 0, 'lfeditor', 1, '2.0.0', 3968, 236, 'Language File Editor', 'This extension supports site admins and developers when modify extension language files.\nThe module features support of PHP and XML, conversion from XML to PHP and reverse, splitting and merging of language files, workspaces (XLL and original content), se', 2, 0, 1, 1148219736, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:6:"5.0.0-";s:5:"typo3";s:6:"3.8.0-";}}', 'Stefan Galinski', 'stefan.galinski@frm2.tum.de', 'sgalinsk', 'e9d14a2c40450f76ceaa7243c2b2c9a8', 'new mainstream release! See documentation for a detailed changelog...', '', 2000000, 0, 0),
(4014, 0, 'lfeditor', 1, '2.0.1', 3968, 305, 'Language File Editor', 'This extension supports site admins and developers when modify extension language files.\nThe module features support of PHP and XML, conversion from XML to PHP and reverse, splitting and merging of language files, workspaces (XLL and original content), se', 2, 0, 1, 1148322915, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:6:"5.0.0-";s:5:"typo3";s:6:"3.8.0-";}}', 'Stefan Galinski', 'stefan.galinski@frm2.tum.de', 'sgalinsk', '1585233cdf51e0ae65bb6334268278d4', '- fixed searching of loaded and unloaded extensions\r\n- minor cosmetical fix', '', 2000001, 0, 0),
(4015, 0, 'lfeditor', 1, '2.0.2', 3968, 346, 'Language File Editor', 'This extension supports site admins and developers when modify extension language files.\nThe module features support of PHP and XML, conversion from XML to PHP and reverse, splitting and merging of language files, workspaces (XLL and original content), se', 2, 0, 1, 1149703102, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:6:"5.0.0-";s:5:"typo3";s:6:"3.8.0-";}}', 'Stefan Galinski', 'stefan.galinski@frm2.tum.de', 'sgalinsk', 'acbeb9a8d55f60e145e3c5db499751f1', '- fixed major quoting bug(!!!)\r\n- fixed some session related problems in editing of language files\r\n- set default options of tinyMCE in fullscreen mode equal to normal mode', '', 2000002, 0, 0),
(4016, 0, 'lfeditor', 1, '2.5.0', 3968, 562, 'Language File Editor', 'This module serves several functions for editing of language files.\n					  Translators and extension authors are supported in equal measure.\n					  Following functions are implemented in this module:\n					   Formats: PHP and XML\n					   enhanced insert', 2, 0, 1, 1160681836, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:6:"5.0.0-";s:5:"typo3";s:6:"3.8.0-";}}', 'Stefan Galinski', 'stefan.galinski@frm2.tum.de', 'sgalinsk', '5f6d8708cbb51bbe47ac536c7cebc5d4', 'new mainstream release; please have a look at the manual; update is urgently advised!', '', 2005000, 0, 0),
(4017, 0, 'lfeditor', 1, '2.5.1', 3968, 334, 'Language File Editor', 'This module serves several functions for editing of language files.\n					  Translators, extension authors and simple users are supported with\n					  special functions for each of them.\n					  Following functions are implemented in this module:\n					   Fo', 2, 0, 1, 1173975982, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:6:"5.0.0-";s:5:"typo3";s:6:"3.8.0-";}}', 'Stefan Galinski', 'Stefan.Galinski@gmail.com', 'sgalinsk', 'b7bbe554815207b38bbc5e0cd3c2c5fb', 'added finnish translation (Thanks to Tapio Markula); updated css  english/german translations', '', 2005001, 0, 0),
(4018, 0, 'lfeditor', 1, '2.6.0', 3968, 369, 'Language File Editor', 'This module serves several functions for editing of language files.\n					  Translators, extension authors and simple users are supported with\n					  special functions for each of them.\n					  Following functions are implemented in this module:\n					   Fo', 2, 0, 1, 1178390783, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:6:"5.0.0-";s:5:"typo3";s:6:"3.8.0-";}}', 'Stefan Galinski', 'Stefan.Galinski@gmail.com', 'sgalinsk', '1527b0f24a1a032023c903a3dd5dd5f5', 'moved to user section (non-admins can access the module now)', '', 2006000, 0, 0),
(4019, 0, 'lfeditor', 1, '2.6.1', 3968, 83, 'Language File Editor', 'This module serves several functions for editing of language files.\n					  Translators, extension authors and simple users are supported with\n					  special functions for each of them.\n					  Following functions are implemented in this module:\n					   Fo', 2, 0, 1, 1189021674, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"5.0.0-0.0.0";s:5:"typo3";s:11:"3.8.0-0.0.0";}}', 'Stefan Galinski', 'Stefan.Galinski@gmail.com', 'sgalinsk', '801298910329c5d8621285dedbf8a87c', 'removed search related and css/tinymce configuration options; \r\nremoved undo/redo buttons of the tinymce mode;\r\nseveral small changes', '', 2006001, 0, 0),
(4020, 0, 'lfeditor', 1, '2.6.2', 3968, 817, 'Language File Editor', 'This module serves several functions for editing of language files.\n					  Translators, extension authors and simple users are supported with\n					  special functions for each of them.\n					  Following functions are implemented in this module:\n					   Fo', 2, 0, 1, 1190887374, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"5.0.0-0.0.0";s:5:"typo3";s:11:"3.8.0-0.0.0";}}', 'Stefan Galinski', 'Stefan.Galinski@gmail.com', 'sgalinsk', '864fb5327afff3cfdf878ae7a4b156b0', 'fixed problem with locallang file detection, fixed some php warnings', '', 2006002, 0, 0),
(4021, 0, 'lfeditor', 1, '2.7.0', 3968, 169, 'Language File Editor', 'This module serves several functions for editing of language files.\n					  Translators, extension authors and simple users are supported with\n					  special functions for each of them.\n					  Following functions are implemented in this module:\n					   Fo', 2, 0, 1, 1306168720, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:12:"5.2.0-5.3.99";s:5:"typo3";s:12:"4.3.0-4.6.99";}}', 'Stefan Galinski', 'Stefan.Galinski@gmail.com', 'sgalinsk', '4fbdd6c8569f8c34d47e6f5b23af3c77', 'Compatibility and Feature Release; An update is strongly recommended! TYPO3 4.3 is required as a minimum together with PHP 5.2', '', 2007000, 0, 0),
(4022, 0, 'lfeditor', 1, '2.8.0', 3968, 102, 'Language File Editor', 'This module serves several functions for editing of language files.\n					  Translators, extension authors and simple users are supported with\n					  special functions for each of them.\n					  Following functions are implemented in this module:\n					   Fo', 2, 0, 1, 1322149381, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:12:"5.2.0-5.3.99";s:5:"typo3";s:12:"4.3.0-4.6.99";}}', 'Stefan Galinski', 'Stefan.Galinski@gmail.com', 'sgalinsk', 'f756c03b330dc0b3a47ef9be95f192e9', 'XLIFF  TYPO3 4.6 support and some minor improvements; Changelog: http://bit.ly/rZJxTj', '', 2008000, 0, 0),
(4023, 0, 'lfeditor', 1, '2.9.0', 3968, 0, 'Language File Editor', 'This module serves several functions for editing of language files.\n					  Translators, extension authors and simple users are supported with\n					  special functions for each of them.\n					  Following functions are implemented in this module:\n					   Formats: PHP, XML and XLF\n					   enhanced insert types (textarea, enhanced textarea, wysiwig)\n					   conversion of formats into the other supported oned\n					   splitting and merging of language files\n					   workspaces (local (only for backend modules) and global)\n					   simple editing of constants and languages\n					   flexible search and view of constants and values\n					   meta information handling\n					   backups, recovering and diff view', 2, 0, 1, 1339959311, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:12:"5.2.0-5.3.99";s:5:"typo3";s:12:"4.5.5-4.7.99";}}', 'Stefan Galinski', 'Stefan.Galinski@gmail.com', 'sgalinsk', 'f419aba77ec2e56bf1d726101f6f28d1', 'TYPO3 4.7 compatibility, some bugfixes, usage of latest tinymce extension version if installed', '', 2009000, 0, 0),
(4024, 0, 'lfeditor', 1, '2.10.0', 3968, 0, 'Language File Editor', 'This module serves several functions for editing of language files.\n					  Translators, extension authors and simple users are supported with\n					  special functions for each of them.\n					  Following functions are implemented in this module:\n					   Formats: PHP, XML and XLF\n					   enhanced insert types (textarea, enhanced textarea, wysiwig)\n					   conversion of formats into the other supported oned\n					   splitting and merging of language files\n					   workspaces (local (only for backend modules) and global)\n					   simple editing of constants and languages\n					   flexible search and view of constants and values\n					   meta information handling\n					   backups, recovering and diff view', 2, 0, 1, 1371661807, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:12:"5.2.0-5.4.99";s:5:"typo3";s:12:"4.5.5-6.1.99";}}', 'Stefan Galinski', 'Stefan.Galinski@gmail.com', 'sgalinsk', '3e36cfcbf437f2ba3df3ef4e44a35157', 'TYPO3 6.x compatibility', '', 2010000, 0, 0),
