(4160, 0, 'ltg_googlesearch', 1, '0.2.1', 2134, 340, '[LTG] Google Search', 'Adds google search on your site using the google search API.\n\nExample can be found here: http://www.livetravelguides.com/search/\n\nWe are using this extention because the indexed search didnt give us the results on the right ranking. Google does a better', 1, 0, 3, 1146191438, 'a:1:{s:7:"depends";a:4:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:3:"cms";s:0:"";s:10:"eim2nusoap";s:0:"";}}', 'R. van Twisk', 'ries@livetravelguides.com', 'ries', '9d71ec08ae66d4886255ad61fba5cde5', ' - Trmplate default setting change. Buf solved', '', 2001, 0, 0),
(4161, 0, 'ltg_googlesearch', 1, '0.3.0', 2134, 450, '[LTG] Google Search API', 'Add a google search on your site using the google search API.\n\nExample can be found here: http://www.livetravelguides.com/search/\n\nWe are using this extention because the indexed search didnt give us the results on the right order. Google does a better j', 1, 0, 3, 1146274112, 'a:1:{s:7:"depends";a:4:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:3:"cms";s:0:"";s:10:"eim2nusoap";s:0:"";}}', 'R. van Twisk', 'ries@livetravelguides.com', 'ries', '15365c012235665ab5c31ba76b0d6390', 'Updated the documentation and solved a template bug. Should really work out of the box now.', 'L!VE Travel Guides Inc.', 3000, 0, 0);
INSERT INTO `tx_extensionmanager_domain_model_extension` (`uid`, `pid`, `extension_key`, `repository`, `version`, `alldownloadcounter`, `downloadcounter`, `title`, `description`, `state`, `review_state`, `category`, `last_updated`, `serialized_dependencies`, `author_name`, `author_email`, `ownerusername`, `md5hash`, `update_comment`, `authorcompany`, `integer_version`, `current_version`, `lastreviewedversion`) VALUES
(4162, 0, 'ltg_googlesearch', 1, '0.3.1', 2134, 660, '[LTG] Google Search API', 'Add a google search on your site using the google search API.\n\nExample can be found here: http://www.livetravelguides.com/search/\n\nWe are using this extention because the indexed search didnt give us the results on the right order. Google does a better j', 1, 0, 3, 1178541412, 'a:1:{s:7:"depends";a:4:{s:5:"typo3";s:11:"3.5.0-0.0.0";s:3:"php";s:11:"3.0.0-0.0.0";s:3:"cms";s:0:"";s:10:"eim2nusoap";s:0:"";}}', 'R. van Twisk', 'ries@livetravelguides.com', 'ries', 'd55b1195b908f3a6cb8d0c006ec13a48', '- Added gemran translations thanks to Herwig-Hakan Mader - RVT', 'L!VE Travel Guides Inc.', 3001, 1, 0),
(4163, 0, 'ltg_phpadsnew', 1, '0.3.2', 1076, 657, '[LTG] phpAdsNew', 'Provided a phpAdsNew interface for typo3.  With some more features and bug fixes. OO document added', 2, 0, 3, 1137431640, 'a:1:{s:7:"depends";a:4:{s:5:"typo3";s:11:"3.7.2-3.8.2";s:3:"php";s:11:"4.3.2-5.0.2";s:3:"cms";s:0:"";s:11:"api_macmade";s:0:"";}}', 'L!IVE Travel Guides (R. van Twisk)', 'ries@livetravelguides.com', 'ries', '08a23dec5de20ccd9068ae15fd2d9fcf', '- ltg_phpadsnew current prevents showing two of the same ads on the same page. At the current point this is not well tested yet. Will bump to 0.4.0 when this feature is stable. \r\nLet me know if there is a request for making this a setting.', 'L!VE Travel Inc.', 3002, 1, 0),
(4164, 0, 'ltg_rating', 1, '1.0.8', 980, 947, '[LTG] Rating', 'it does NOT provide a replacement for the old tt_rating extention. I did make it for www.livetravelguides.com since the tt_rating module didnt provide me with the right options. And this extention provides much more! Cookie protection and soon IP protect', 1, 0, 2, 1111416433, 'a:1:{s:7:"depends";a:5:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:3:"cms";s:0:"";s:11:"api_macmade";s:0:"";s:9:"cc_devlog";s:0:"";}}', 'R. van Twisk', 'ries@livetravelguides.com', 'maximo', '47001de69df90c64ff4bd9fda0eddb1f', '', 'Live Guides Inc.', 1000008, 1, 0),
(4165, 0, 'lumophpinclude', 1, '1.0.3', 9506, 856, 'LumoNet PHP Include', 'Includes local PHP scripts via eval() or external PHP script via HTTP. Provides options to transfer GET and POST variables to the included script and strip header and footer HTML parts.', 2, -1, 3, 1135347173, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";}}', 'Thomas Off, LumoNet oHG', 't.off@lumonet.de', 'retiolum', 'b69b21b64f785503a7cd603ecfdf24f9', '', 'LumoNet oHG', 1000003, 0, 0),
(4166, 0, 'lumophpinclude', 1, '1.1.0', 9506, 1737, 'LumoNet PHP Include', 'Includes local PHP scripts via eval() or external PHP script via HTTP. Provides options to transfer GET and POST variables to the included script and strip header and footer HTML parts.', 2, -1, 3, 1199444886, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"4.0.0-4.1.99";s:3:"php";s:12:"4.4.0-5.2.99";}}', 'Thomas Off', 'typo3@retiolum.de', 'retiolum', 'a15ee90b1f40b2967798128ba60f4962', 'Replaced the buggy inclusion of remote files via file_get_contents() by a real HTTP request (thereby dropping POST and COOKIE support temporarily)\r\nAdded possibility to rewrite the URLs of internal links and local resources', '', 1001000, 0, 0),
(4167, 0, 'lumophpinclude', 1, '1.1.1', 9506, 4163, 'LumoNet PHP Include', 'Includes local PHP scripts via eval() or external PHP script via HTTP. Provides options to transfer GET and POST variables to the included script and strip header and footer HTML parts.', 2, -1, 3, 1232309577, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"4.0.0-4.1.99";s:3:"php";s:12:"4.4.0-5.2.99";}}', 'Thomas Off', 'typo3@retiolum.de', 'retiolum', 'e35b5d6013d479c8f81a2d60c8bd8dcd', 'Fix some issue with inclusion of local files (thanks to Pascal Alich).', '', 1001001, 0, 0),
(4168, 0, 'lumophpinclude', 1, '1.2.0', 9506, 2750, 'LumoNet PHP Include', 'Includes local PHP scripts via eval() or external PHP script via HTTP. Provides options to transfer GET and POST variables to the included script and strip header and footer HTML parts.', 2, -1, 3, 1232310170, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"4.0.0-4.2.99";s:3:"php";s:12:"4.4.0-5.2.99";}}', 'Thomas Off', 'typo3@retiolum.de', 'retiolum', '1ffde759b0701857679242b61dceec8c', 'Fix some minor bugs, update EM conf file and increase version number to skip old (erroneous) uploads.', '', 1002000, 0, 0),
(4169, 0, 'lumophpinclude', 1, '1.2.1', 9506, 0, 'LumoNet PHP Include', 'Includes local PHP scripts via eval() or external PHP script via HTTP. Provides options to transfer GET and POST variables to the included script and strip header and footer HTML parts.', 2, 0, 3, 1402325576, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:12:"4.4.0-5.5.99";s:5:"typo3";s:12:"4.0.0-4.7.99";}}', 'Thomas Off', 'retiolum@googlemail.com', 'retiolum', 'e05885c0c2d81a7baa3e852e065bd36e', 'SECURITY FIX: Fix vulnerability to manipulate extension links and execute any arbitrary remote\r\nscript with the return of its (unfiltered) response because there isnt any validation of the requested URL (thanks to the T3 security team).', '', 1002001, 0, 0),
