(4363, 0, 'mhnotifychanger', 1, '1.1.0', 720, 203, 'Notify Changer', '', 2, 0, 0, 1158248574, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:6:"3.0.0-";s:3:"php";s:6:"3.0.0-";s:3:"cms";s:0:"";}}', 'Martin Holtz', 'post@martinholtz.de', 'maholtz', 'a03ed96315f102cf06633fd9684f0ba2', 'added ext_conf_template.txt, so you can change the notify emailaddress and the sender while installing this extension. Added short readme.txt too. Now there is no need to add $TYPO3_CONF_VARS[BE][notifyHeader] to the localconf.php anymore. But if it i', '', 1001000, 0, 0),
(4364, 0, 'mhnotifychanger', 1, '1.1.1', 720, 300, 'Notify Changer', 'Changes the sender in the notify mail you get, if you log in (you have to check "Notify me by email, when somebody logs in from my account:" in your account).', 2, 0, 0, 1161698084, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:6:"3.0.0-";s:3:"php";s:6:"3.0.0-";s:3:"cms";s:0:"";}}', 'Martin Holtz', 'typo3@martinholtz.de', 'maholtz', 'a451359e51bb77753b24ae7e0f9139b1', 'i only added the description', '', 1001001, 0, 0),
(4365, 0, 'mhnotifychanger', 1, '1.1.2', 720, 0, 'Notify Changer', 'Changes the sender in the notify mail you get, if you log in (you have to check "Notify me by email, when somebody logs in from my account:" in your account).', 5, 0, 0, 1346789052, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"3.5.0-0.0.0";s:3:"php";s:11:"3.0.0-0.0.0";s:3:"cms";s:0:"";}}', 'Martin Holtz', 'typo3@martinholtz.de', 'maholtz', 'fffe05c4b6cc3b7a8f3752e210f1cda7', 'This extension is obsolete. Use $TYPO3_CONF_VARS[MAIL][defaultMailFromAddress] and $TYPO3_CONF_VARS[MAIL][defaultMailFromName] instead.', '', 1001002, 1, 0),
