(4510, 0, 'ml_links', 1, '1.2.2', 2929, 0, 'Extended Links', '"Extended Links" lets you post-process generated links (file, mailto, internal and external) to enrich them with additional information such as a type icon (PDF, DOC, ...) for links to a file or a mailbox icon for mailto links. Last modification date or size of a file to download may easily be appended as well.', 2, 0, 2, 1394554766, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"4.5.0-6.2.99";}}', 'Xavier Perseguers', 'xavier@causal.ch', 'abandoned_extensions', '248cf0b3353901103a962348efad9aaf', 'Support for config.absRefPrefix and compatibility with TYPO3 6.x.', 'Causal Sarl', 1002002, 0, 0),
(4511, 0, 'ml_links', 1, '1.2.3', 2929, 0, 'Extended Links', '"Extended Links" lets you post-process generated links (file, mailto, internal and external) to enrich them with additional information such as a type icon (PDF, DOC, ...) for links to a file or a mailbox icon for mailto links. Last modification date or size of a file to download may easily be appended as well.', 2, 0, 2, 1394782791, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"4.5.0-6.2.99";}}', 'Xavier Perseguers', 'xavier@causal.ch', 'abandoned_extensions', 'f7f202bbddea0ae267efdc3dc510a3e6', 'Bugfix release. Internal links (and possibly others) in TYPO3 4.x were removed if the corresponding TypoScript configuration was not configured.', 'Causal Sarl', 1002003, 0, 0),
