(4587, 0, 'mth_feedit', 1, '0.1.0', 7018, 23, 'FrontEnd API', '', 0, 0, 2, 1136893842, 'a:0:{}', 'Morten Tranberg Hansen', 'mth@daimi.au.dk', 'daimi', '1afe2d7f95025a87a403da4750d0f645', 'First public release.\r\nThe extension is currently working, but the documentation is basic for now and will be improved within the next couple of month.', '', 1000, 0, 0),
(4588, 0, 'mth_feedit', 1, '0.1.1', 7018, 75, 'FrontEnd API', '', 0, 0, 2, 1136908634, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:3:"cms";s:0:"";}}', 'Morten Tranberg Hansen', 'mth@daimi.au.dk', 'daimi', '7a1398cf7de04724debb09e2899afb00', 'Error in documentation fixed.\r\nfields and show_fields properties should have create or edit infront of it, like:\r\ncreate.fields', '', 1001, 0, 0),
