(4590, 0, 'mth_feedit', 1, '0.1.3', 7018, 25, 'FrontEnd API', '', 0, 0, 2, 1141856032, 'a:0:{}', 'Morten Tranberg Hansen', 'mth@daimi.au.dk', 'daimi', '13e7a097024976f0c4f4dcf0df72543b', 'It is now possible to have tabs in the frontend form, just like in the backend.\r\nOther small correction mades (ex. it is possible to include callers piVars in the form).\r\nLet me know if you find som bugs.', '', 1003, 0, 0),
(4591, 0, 'mth_feedit', 1, '0.1.4', 7018, 12, 'FrontEnd API', '', 0, 0, 2, 1141904896, 'a:0:{}', 'Morten Tranberg Hansen', 'mth@daimi.au.dk', 'daimi', '21819cb2c2c2dc779066a793aa035da8', 'Bug fixed with disable of preview before submit.\r\nGerman languages added.', '', 1004, 0, 0),
(4592, 0, 'mth_feedit', 1, '0.1.5', 7018, 38, 'FrontEnd API', 'This is a Frontend API for editing TYPO3 records in the frontend like you do it in the backend. All you have to do is to define the table and witch fields of the table it is possible to edit in the frontend, and the mth_feedit will generate the form for y', 0, 0, 2, 1141988856, 'a:0:{}', 'Morten Tranberg Hansen', 'mth@daimi.au.dk', 'daimi', '6648d9f091f759dc0e606d194deb8534', 'Description of extension added.', '', 1005, 0, 0),
(4593, 0, 'mth_feedit', 1, '0.1.6', 7018, 222, 'FrontEnd API', 'This is a Frontend API for editing TYPO3 records in the frontend like you do it in the backend. All you have to do is to define the table and witch fields of the table it is possible to edit in the frontend, and the mth_feedit will generate the form for y', 1, 0, 2, 1142445165, 'a:0:{}', 'Morten Tranberg Hansen', 'mth@daimi.au.dk', 'daimi', 'be726c955f2672eee0c7a209e431a91f', 'Call to afterSave function in your plugin class added when data is saved.\r\nNow its also possible to override some of the template generating functions in mth_feedit from your plugin class.\r\nAll of this documented in the Coding Feature section in the docum', '', 1006, 0, 0),
(4594, 0, 'mth_feedit', 1, '0.1.7', 7018, 269, 'FrontEnd API', 'This is a Frontend API for editing TYPO3 records in the frontend like you do it in the backend. All you have to do is to define the table and witch fields of the table it is possible to edit in the frontend, and the mth_feedit will generate the form for y', 1, 0, 2, 1142504750, 'a:0:{}', 'Morten Tranberg Hansen', 'mth@daimi.au.dk', 'daimi', 'd8a89276bc3fd87b131fefead35abf85', 'Some bugs fixed. :)', '', 1007, 0, 0),
(4595, 0, 'mth_feedit', 1, '0.1.8', 7018, 278, 'FrontEnd API', 'This is a Frontend API for editing TYPO3 records in the frontend like you do it in the backend. All you have to do is to define the table and witch fields of the table it is possible to edit in the frontend, and the mth_feedit will generate the form for y', 1, 0, 2, 1143155263, 'a:0:{}', 'Morten Tranberg Hansen', 'mth@daimi.au.dk', 'daimi', 'b76e5ff853efbba9100b6cec1110f52b', 'Extra div tag added.', '', 1008, 0, 0),
(4596, 0, 'mth_feedit', 1, '0.1.9', 7018, 221, 'FrontEnd API', 'This is a Frontend API for editing TYPO3 records in the frontend like you do it in the backend. All you have to do is to define the table and witch fields of the table it is possible to edit in the frontend, and the mth_feedit will generate the form for y', 1, 0, 2, 1144159806, 'a:0:{}', 'Morten Tranberg Hansen', 'mth@daimi.au.dk', 'daimi', 'aa3d98a4f96ff291d392e093d7021468', 'small changes.', '', 1009, 0, 0),
