INSERT INTO `tx_extensionmanager_domain_model_extension` (`uid`, `pid`, `extension_key`, `repository`, `version`, `alldownloadcounter`, `downloadcounter`, `title`, `description`, `state`, `review_state`, `category`, `last_updated`, `serialized_dependencies`, `author_name`, `author_email`, `ownerusername`, `md5hash`, `update_comment`, `authorcompany`, `integer_version`, `current_version`, `lastreviewedversion`) VALUES
(4598, 0, 'mth_feedit', 1, '0.2.0', 7018, 224, 'FrontEnd API', 'This is a Frontend API for editing TYPO3 records in the frontend like you do it in the backend. All you have to do is to define the table and witch fields of the table it is possible to edit in the frontend, and the mth_feedit will generate the form for y', 1, 0, 2, 1144710301, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:3:"php";s:6:"3.0.0-";s:5:"typo3";s:6:"4.0.0-";}}', 'Morten Tranberg Hansen', 'mth@daimi.au.dk', 'daimi', '56a7307e8ea14200b12c35ba424cdd10', 'This is the TYPO3 4.0 version.\nIt now works with the new rtehtmlarea and then fixes bug: http://bugs.typo3.org/view.php?id2241 \nIt also fixes a minor bug with now as default value for date and datetime fields.', '', 2000, 0, 0),
(4599, 0, 'mth_feedit', 1, '0.2.1', 7018, 334, 'FrontEnd API', 'This is a Frontend API for editing TYPO3 records in the frontend like you do it in the backend. All you have to do is to define the table and witch fields of the table it is possible to edit in the frontend, and the mth_feedit will generate the form for y', 1, 0, 2, 1145214486, 'a:0:{}', 'Morten Tranberg Hansen', 'mth@daimi.au.dk', 'daimi', '8310216d46097e27ff469a287dea8ddf', 'Fix with select fields and foreign_table_where.', '', 2001, 0, 0),
(4600, 0, 'mth_feedit', 1, '0.2.2', 7018, 240, 'FrontEnd API', 'This is a Frontend API for editing TYPO3 records in the frontend like you do it in the backend. All you have to do is to define the table and witch fields of the table it is possible to edit in the frontend, and the mth_feedit will generate the form for y', 1, 0, 2, 1146578533, 'a:0:{}', 'Morten Tranberg Hansen', 'mth@daimi.au.dk', 'daimi', '1ee7a79a3699ca5a4c29b1e3d90e5e51', 'Bug fixed with possibility to override template methods in callers class in PHP5.\nAnd a javascript error causing the rte to not get loaded in frontend (sometimes).', '', 2002, 0, 0),
(4601, 0, 'mth_feedit', 1, '0.2.3', 7018, 220, 'FrontEnd API', 'This is a Frontend API for editing TYPO3 records in the frontend like you do it in the backend. All you have to do is to define the table and witch fields of the table it is possible to edit in the frontend, and the mth_feedit will generate the form for y', 1, 0, 2, 1147263723, 'a:0:{}', 'Morten Tranberg Hansen', 'mth@daimi.au.dk', 'daimi', '4b531e932b4973cae31f430f5e304434', 'Set to not being a shy extension.', '', 2003, 0, 0),
(4602, 0, 'mth_feedit', 1, '0.2.4', 7018, 225, 'FrontEnd API', 'This is a Frontend API for editing TYPO3 records in the frontend like you do it in the backend. All you have to do is to define the table and witch fields of the table it is possible to edit in the frontend, and the mth_feedit will generate the form for y', 1, 0, 2, 1148982184, 'a:0:{}', 'Morten Tranberg Hansen', 'mth@daimi.au.dk', 'daimi', '4c100bb32bf75e84cda14ec63a62abed', 'Default label for empty values in preview added (not saved in DB, only displayed on web and in emails)\r\nTyposcript option \r\ncreate.preview.dontDisplayEmptyFields and edit.preview.dontDisplayEmptyFields added. These removes the empty fields from preview di', '', 2004, 0, 0),
(4603, 0, 'mth_feedit', 1, '0.2.5', 7018, 257, 'FrontEnd API', 'This is a Frontend API for editing TYPO3 records in the frontend like you do it in the backend. All you have to do is to define the table and witch fields of the table it is possible to edit in the frontend, and the mth_feedit will generate the form for y', 1, 0, 2, 1149028066, 'a:0:{}', 'Morten Tranberg Hansen', 'mth@daimi.au.dk', 'daimi', '7c50f871e2507eaebb89de4a3b3605e5', 'Fixed so CSH now works in FE again! It seems like the TCA_DESCR was not loaded in frontend in TYPO3 4.0, like older versions of mth_feedit thought. See Documentation for how to get help icons in frontend.', '', 2005, 0, 0),
(4604, 0, 'mth_feedit', 1, '0.2.6', 7018, 223, 'FrontEnd API', 'This is a Frontend API for editing TYPO3 records in the frontend like you do it in the backend. All you have to do is to define the table and witch fields of the table it is possible to edit in the frontend, and the mth_feedit will generate the form for y', 1, 0, 2, 1149595476, 'a:0:{}', 'Morten Tranberg Hansen', 'mth@daimi.au.dk', 'daimi', 'e30f28722a6986ebef80b2caf5713b5d', 'Some css classes added. Thanks to Holger.', '', 2006, 0, 0),
(4605, 0, 'mth_feedit', 1, '0.2.7', 7018, 220, 'FrontEnd API', 'This is a Frontend API for editing TYPO3 records in the frontend like you do it in the backend. All you have to do is to define the table and witch fields of the table it is possible to edit in the frontend, and the mth_feedit will generate the form for y', 1, 0, 2, 1150139414, 'a:0:{}', 'Morten Tranberg Hansen', 'mth@daimi.au.dk', 'daimi', 'b9ebcce5b71f18b5b929472632eba6f3', 'Bug fix.. image upload now works again.', '', 2007, 0, 0),
(4606, 0, 'mth_feedit', 1, '0.2.8', 7018, 302, 'FrontEnd API', 'This is a Frontend API for editing TYPO3 records in the frontend like you do it in the backend. All you have to do is to define the table and witch fields of the table it is possible to edit in the frontend, and the mth_feedit will generate the form for y', 1, 0, 2, 1150201078, 'a:0:{}', 'Morten Tranberg Hansen', 'mth@daimi.au.dk', 'daimi', '723d6783a564e4b5273bfc0c65b0a5df', 'Bugfix with array_merge function.', '', 2008, 0, 0),
(4607, 0, 'mth_feedit', 1, '0.3.0', 7018, 211, 'FE Form Edit API', 'This is a Frontend API for editing TYPO3 records in the frontend like you do it in the backend. All you have to do is to define the table and witch fields of the table it is possible to edit in the frontend, and the mth_feedit will generate the form for y', 1, 0, 2, 1152706306, 'a:0:{}', 'Morten Tranberg Hansen', 'mth@daimi.au.dk', 'daimi', 'b2ebb243185f8fd9130257baa8a1823d', 'LANG object initialized with TSFE language if present, itemProcFunc now works with preview and last, but not least, icon is added. Thanks to Kasper Ligaard.', '', 3000, 0, 0),
(4608, 0, 'mth_feedit', 1, '0.4.0', 7018, 272, 'FE Form Edit API', 'This is a Frontend API for editing TYPO3 records in the frontend like you do it in the backend. All you have to do is to define the table and witch fields of the table it is possible to edit in the frontend, and the mth_feedit will generate the form for y', 1, 0, 2, 1154469451, 'a:0:{}', 'Morten Tranberg Hansen', 'mth@daimi.au.dk', 'daimi', 'c38b23cabf396e3062237de61b4a49d4', 'Problem with MM-relations and edit of records fixed. This makes editing of category relations in news_feedit work (again).', '', 4000, 0, 0),
(4609, 0, 'mth_feedit', 1, '0.4.1', 7018, 627, 'FE Form Edit API', 'This is a Frontend API for editing TYPO3 records in the frontend like you do it in the backend. All you have to do is to define the table and witch fields of the table it is possible to edit in the frontend, and the mth_feedit will generate the form for y', 1, 0, 2, 1155642812, 'a:0:{}', 'Morten Tranberg Hansen', 'mth@daimi.au.dk', 'daimi', 'b6dcab7f5120ba0fee1bcf04e9ef8614', 'Fix with a /div tag to much in genrated code, thx to Holger Sorg.', '', 4001, 0, 0),
(4610, 0, 'mth_feedit', 1, '0.4.2', 7018, 2146, 'FE Form Edit API', 'This is a Frontend API for editing TYPO3 records in the frontend like you do it in the backend. All you have to do is to define the table and witch fields of the table it is possible to edit in the frontend, and the mth_feedit will generate the form for y', 1, 0, 2, 1169592966, 'a:0:{}', ' Kasper Ligaard', 'ligaard@daimi.au.dk', 'daimi', '452ae0432a4f7c67cf7ec2dfbf396255', ' Italian translation added, thanks to Claudio Strizzolo\r\n Solved IE6 autofill problem\r\nSee Changelog', '', 4002, 1, 0),
