(4680, 0, 'dmmjobcontrol', 1, '1.3.0', 5755, 39, 'JobControl', 'Job database with search function', 2, -1, 3, 1184074516, 'a:0:{}', 'Kevin Renskers [DMM Development]', 'kevin@dauphin-mm.nl', 'abandoned_extensions', '6d6aa5cc0e24708c00f0bc97b3675c39', 'Added German translation and fixed a stupid spelling error (spelled dicipline everywhere).\n\nIMPORTANT: read the changelog for update instructions!', '', 1003000, 0, 0),
(4681, 0, 'dmmjobcontrol', 1, '1.4.0', 5755, 75, 'JobControl', 'Job database to show lists with jobs on your site, with a detailview and searchform. It is possible to show the most recent jobs and/or the searchform on all pages.', 2, -1, 3, 1184750863, 'a:0:{}', 'Kevin Renskers [DMM Development]', 'kevin@dauphin-mm.nl', 'abandoned_extensions', '87807d12e9ccfb48eeb6f6c7689930c1', 'Its now possible to search with keywords. Please read the changelog for all changes. If you are upgrading from version  1.2 read the changelog for upgrade instructions!', '', 1004000, 0, 0),
(4682, 0, 'dmmjobcontrol', 1, '1.5.0', 5755, 48, 'JobControl', 'Job database to show lists with jobs on your site, with a detailview and searchform. It is possible to show the most recent jobs and/or the searchform on all pages.', 2, -1, 3, 1187617923, 'a:0:{}', 'Kevin Renskers [DMM Development]', 'kevin@dauphin-mm.nl', 'abandoned_extensions', 'a56ea2c2d593f4ca6f59c65ab39eec2b', 'It is now possible to add your own fields to the extension, see documentation for more information.', '', 1005000, 0, 0),
(4683, 0, 'dmmjobcontrol', 1, '1.6.0', 5755, 35, 'JobControl', 'Job database to show lists with jobs on your site, with a detailview and searchform. It is possible to show the most recent jobs and/or the searchform on all pages.', 2, -1, 3, 1188315854, 'a:0:{}', 'Kevin Renskers [DMM Development]', 'kevin@dauphin-mm.nl', 'abandoned_extensions', 'fbfcd76d65dd3e9b861a8cdee33f6365', 'Added feature: paged lists ("Showing jobs 1 to 20 of 350"). For other changes see ChangeLog file.', '', 1006000, 0, 0),
(4684, 0, 'dmmjobcontrol', 1, '1.7.0', 5755, 24, 'JobControl', 'Job database to show (paginated) lists with jobs on your site, with a detailview and searchform. It is possible to show the most recent jobs and/or the searchform on all pages. Includes a form to apply for jobs online.', 2, -1, 3, 1188768793, 'a:0:{}', 'Kevin Renskers [DMM Development]', 'kevin@dauphin-mm.nl', 'abandoned_extensions', 'c84cad904b28140333f4f109395e3791', 'It is now possible to apply for jobs online, and a substitutePageTitle option was added. See changelog for other changes and manual for details. Oh, and can someone please provide me with correct German translations?', 'DMM Development', 1007000, 0, 0),
(4685, 0, 'dmmjobcontrol', 1, '1.8.0', 5755, 10, 'JobControl', 'Job database to show (paginated) lists with jobs on your site, with a detailview and searchform. It is possible to show the most recent jobs and/or the searchform on all pages. Includes a form to apply for jobs online.', 2, -1, 3, 1188809238, 'a:0:{}', 'Kevin Renskers [DMM Development]', 'kevin@dauphin-mm.nl', 'abandoned_extensions', '82aa5cb20e5f6917ff79932640341d9c', 'Bugfix: Critical PHP error was fixed, update now!', 'DMM Development', 1008000, 0, 0),
(4686, 0, 'dmmjobcontrol', 1, '1.8.1', 5755, 27, 'JobControl', 'Job database to show (paginated) lists with jobs on your site, with a detailview and searchform. It is possible to show the most recent jobs and/or the searchform on all pages. Includes a form to apply for jobs online.', 2, -1, 3, 1188819283, 'a:0:{}', 'Kevin Renskers [DMM Development]', 'kevin@dauphin-mm.nl', 'abandoned_extensions', 'ea5494b6508503c012e8dabcb48df6fd', 'Load sysfolders with jobs recursively. If you are using version 1.7.0, please update asap as there is a fatal php error in that version.', 'DMM Development', 1008001, 0, 0),
(4687, 0, 'dmmjobcontrol', 1, '1.8.2', 5755, 1583, 'JobControl', 'Job database to show (paginated) lists with jobs on your site, with a detailview and searchform. It is possible to show the most recent jobs and/or the searchform on all pages. Includes a form to apply for jobs online.', 2, -1, 3, 1188923664, 'a:0:{}', 'Kevin Renskers [DMM Development]', 'kevin@dauphin-mm.nl', 'abandoned_extensions', '249cbffcbd6700fd3f6a732198d670fa', 'The html email class now always gets loaded properly, which could be important if you want html emails from the apply form.', 'DMM Development', 1008002, 0, 0),
(4688, 0, 'dmmjobcontrol', 1, '1.8.3', 5755, 46, 'JobControl', 'Job database to show (paginated) lists with jobs on your site, with a detailview, search function and apply form. It is possible to show the most recent jobs and/or the searchform on all pages. Easy to setup and lots of options for advanced users.', 2, -1, 3, 1189120419, 'a:0:{}', 'Kevin Renskers [DMM Development]', 'kevin@dauphin-mm.nl', 'abandoned_extensions', '096bada1700b89a0db7d14fef382eaf8', 'All fields now can have a stdWrap configuration added to them, see manual.', 'DMM Development', 1008003, 0, 0),
