(4797, 0, 'newloginbox', 1, '3.0.0', 188517, 2842, 'New front end login box', 'This is an alternative to the good old login box. This version features a little more functionality, including success/error messages, cookie check, forgot password etc.', 2, 0, 3, 1158135422, 'a:0:{}', 'Kasper Skrhj', 'kasper@typo3.com', 'strada', '9a784f800402af7b4c5fe1844ee81958', '- Newloginbox is now template based (thanks to Brice Bernard)\n- Added support for permanent log-in (aka "Stay logged in") feature of the latest development version of the core. (For use of permalogin with TYPO3  4.1, use the extension "core_permalogin")', 'CURBY SOFT Multimedie', 3000000, 0, 0),
(4798, 0, 'newloginbox', 1, '3.0.1', 188517, 93569, 'New front end login box', 'This is an alternative to the good old login box. This version features a little more functionality, including success/error messages, cookie check, forgot password etc.', 2, 0, 3, 1161671841, 'a:0:{}', 'Kasper Skrhj', 'kasper@typo3.com', 'strada', '95ccc9ac30c7acdb68d1713711e7b898', 'Updated manual / Fixed bug 4265 : Page browser error / Added TS-variable storagePid (bug 1787) / Added TS-variable showForgotPassword (bug 1389) / Fixed bug 3197 : password-forgot-mails contains htmlencodings / see ChangeLog for details', 'CURBY SOFT Multimedie', 3000001, 0, 0),
(4799, 0, 'newloginbox', 1, '3.1.0', 188517, 18307, 'New front end login box', 'This is an alternative to the good old login box. This version features a little more functionality, including success/error messages, cookie check, forgot password etc.', 2, 0, 3, 1189353757, 'a:0:{}', 'Kasper Skrhj', 'kasper@typo3.com', 'strada', '5191608a14189476c264b1bd14fd506d', 'Language files converted from php to xml-files, therefore Typo3  4.0 is required! / New and enhanced labels for french / Fixed XHTML-issue with link-generation / User-groups to be displayed with user-listing now may be chosen / see Changelog for details', 'CURBY SOFT Multimedie', 3001000, 0, 0),
(4800, 0, 'newloginbox', 1, '3.1.1', 188517, 12146, 'New front end login box', 'This is an alternative to the good old login box. This version features a little more functionality, including success/error messages, cookie check, forgot password etc.', 5, 0, 3, 1212824547, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"3.5.0-4.1.99";}}', 'Stefan Strasser (formerly Kasper Skrhj)', 'strada@stradax.net', 'strada', '1b8d154ab055fc7830bffebca1fa5237', 'Marked as obsolete : deprecated since TYPO3 4.2 because its login-functionality is now integrated into the core as sysext felogin / the userlisting-plugin has been put into the extension feuserlisting // see manual for further explanation', '', 3001001, 1, 0),
(4801, 0, 'newloginbox_linkfactory', 1, '0.0.1', 1343, 1343, 'Newloginbox no GRSP', 'Multiple FE-user storage pids', 1, 0, 3, 1118829794, 'a:1:{s:7:"depends";a:4:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:3:"cms";s:0:"";s:11:"newloginbox";s:0:"";}}', 'Stefan Kreisberg', 'stefan@linkfactory.dk', 'strato', '371ec0a6424cef000eb3819698707371', 'Initial upload.', '', 1, 1, 0),
(4802, 0, 'newloginbox_tmplable', 1, '0.0.3', 3830, 91, 'Newloginbox with templates', 'XCLASSes newloginbox extension class adding templates support', 0, 0, 3, 1130879578, 'a:0:{}', 'Miroslav Monkevic', 'm@vektorius.lt', 'mironas', '17969b0b6eaf1aa893cafd0579abd18a', 'Minor bugfix', '', 3, 0, 0),
(4803, 0, 'newloginbox_tmplable', 1, '0.0.4', 3830, 725, 'Newloginbox with templates', 'XCLASSes newloginbox extension class adding templates support', 0, 0, 3, 1131363165, 'a:1:{s:7:"depends";a:4:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:3:"cms";s:0:"";s:11:"newloginbox";s:0:"";}}', 'Miroslav Monkevic', 'm@vektorius.lt', 'mironas', '8b80e7eeb885cab5d0ef75dbcde88813', 'Compatibility with kb_md5fepw added.\r\nInstaltion order should be: newloginbox - kb_md5fepw - newloginbox_tmplable.\r\nIf you installed kb_md5fepw after newloginbox_tmplable - uninstal newloginbox_tmplable then install it again (press green minus icon, the', '', 4, 0, 0),
(4804, 0, 'newloginbox_tmplable', 1, '0.0.5', 3830, 1260, 'Newloginbox with templates', 'XCLASSes newloginbox extension class adding templates support', 0, 0, 3, 1138609369, 'a:1:{s:7:"depends";a:4:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:3:"cms";s:0:"";s:11:"newloginbox";s:0:"";}}', 'Miroslav Monkevic', 'm@vektorius.lt', 'mironas', 'bfcbbc3163704a78bf154125c1c2caff', '"Login success" template introduced. More markers added to the "Logout template".\r\n\r\nYour custom template might need update after upgrading up to this version. Please chech "Logout form" and "Login success" template parts.', '', 5, 0, 0),
(4805, 0, 'newloginbox_tmplable', 1, '0.0.6', 3830, 1090, 'Newloginbox with templates', 'XCLASSes newloginbox extension class adding templates support', 0, 0, 3, 1157534407, 'a:0:{}', 'Miroslav Monkevic', 'm@vektorius.lt', 'mironas', '391f8ffe7e71fe157f221c92ac674d9f', 'Fixed bug dealing with displaying login_success template part 2 times to users with cookies turned off.', '', 6, 0, 0),
(4806, 0, 'newloginbox_tmplable', 1, '0.0.7', 3830, 559, 'Newloginbox with templates', 'XCLASSes newloginbox extension class adding templates support', 5, 0, 3, 1157705886, 'a:1:{s:7:"depends";a:4:{s:5:"typo3";s:6:"3.0.0-";s:3:"php";s:6:"3.0.0-";s:3:"cms";s:0:"";s:11:"newloginbox";s:0:"";}}', 'Miroslav Monkevic', 'm@vektorius.lt', 'mironas', 'c98ec382c74dab059306df564a1e3814', 'This extension is obsolete now. Try using newloginbox ver. 3.x', '', 7, 1, 0),
(4807, 0, 'newrecordwiz', 1, '0.1.0', 1137, 1137, 'New Record Wizard CSM', 'This extension adds an item in the Typo3 context sensitive menu which allows you to create pages, content, and database records directly from the menu. This way, you get exactly the same functionalities as in the wizard, without having to load it each tim', 2, 0, 0, 1126215326, 'a:1:{s:7:"depends";a:4:{s:5:"typo3";s:11:"0.0.2-0.0.2";s:3:"php";s:11:"0.0.2-0.0.2";s:3:"cms";s:0:"";s:4:"lang";s:0:"";}}', 'Jean-David Gadina', 'macmade@gadlab.net', 'abandoned_extensions', '09e6075b2619cd26154782dbd7352db3', '', 'macmade.net', 1000, 1, 0),
(4808, 0, 'eco_gal', 1, '0.6.0', 6179, 237, 'Ecodev: photo gallery express', 'This is a simple image gallery that uses Ajax technology with one big picture and a list of thumbnails below it. The slider shifts left or right as you click on thumbnails. Images are automatically resized. (http://quart-monde.ch/portraits.html)', 1, 0, 3, 1160391279, 'a:1:{s:7:"depends";a:3:{s:3:"php";s:6:"5.0.0-";s:9:"xtemplate";s:0:"";s:5:"typo3";s:6:"4.0.0-";}}', 'Fabien Udriot', 'fabien.udriot@ecodev.ch', 'fab1en', '3d8a71c8d81ac7a5688ca696806b71de', 'Major update ! Please reconfigure the plugin backend configuration. A lot of things have changed...', '', 6000, 0, 0),
(4809, 0, 'eco_gal', 1, '0.6.2', 6179, 637, 'Ecodev: photo gallery express', 'This is a simple image gallery that uses Ajax technology with one big picture and a list of thumbnails below it. The slider shifts left or right as you click on thumbnails. Images are automatically resized. (http://quart-monde.ch/portraits.html)', 1, 0, 3, 1166712511, 'a:1:{s:7:"depends";a:3:{s:3:"php";s:6:"5.0.0-";s:9:"xtemplate";s:0:"";s:5:"typo3";s:6:"4.0.0-";}}', 'Fabien Udriot', 'fabien.udriot@ecodev.ch', 'fab1en', 'feaa6687793dd1db4cf60a7985c44c40', 'Bug fixing !', '', 6002, 0, 0),
(4810, 0, 'eco_gal', 1, '0.1.0', 6179, 17, 'Ecodev: photo gallery express', 'This is a simple and fast Image gallery that uses Ajax technology with one big picture and a list of thumbnails below it. The slider shifts left or right as you click on a thumbnail. This gallery is well adapted for a multilanguage context. Each image can', 1, 0, 3, 1157002803, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:6:"5.0.0-";s:9:"xtemplate";s:0:"";}}', 'Fabien Udriot', 'fabien.udriot@ecodev.ch', 'fab1en', '01121f19fddb7bc3e2a7a79af0d85160', 'First release !', '', 1000, 0, 0),
(4811, 0, 'eco_gal', 1, '0.2.0', 6179, 10, 'Ecodev: photo gallery express', 'This is a simple image gallery that uses Ajax technology with one big picture and a list of thumbnails below it. The slider shifts left or right as you click on thumbnails. Images are automatically resized. It is well adapted for a multilanguage context.', 1, 0, 3, 1157035123, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:6:"5.0.0-";s:9:"xtemplate";s:0:"";}}', 'Fabien Udriot', 'fabien.udriot@ecodev.ch', 'fab1en', '1187e4019f7315d3c940296fb533c1fd', 'Add some features (gallery width configurable, multilanguage better support)', '', 2000, 0, 0),
