(5014, 0, 'n_mcmenu', 1, '0.0.2', 2860, 96, 'Multi-color menu', 'Adds overColor, outColor and actColor to you page headers and allows the menu to use this for page-specific rollover effects. Fields are inserted into the rootline so you can actually use them anywhere you want with the "slide" functionality', 2, 0, 2, 1066901207, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:3:"cms";s:0:"";}}', 'NePhie', 'typo3@nephie.org', 'nephie', 'c02f916ea7fc4fcf5090b60d42318cd0', 'added documentation', '', 2, 0, 0),
