(5190, 0, 'pb_amazon_search', 1, '1.1.0', 1019, 46, 'Amazon Search', 'You can search the Amazon database  for each Amazon Version that has a SOAP interface.\r\n\r\nYou can limit the search to a specific BrowseNode, a certain Topic (DVD, Books, Foreign Books etc), setup the amount of details Amazon should return.', 1, 0, 3, 1107249028, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"0.0.2-0.0.2";s:3:"php";s:11:"0.0.2-0.0.2";s:3:"cms";s:0:"";}}', 'Patrick Bauerochse', 'webmaster@gowh00t.de', 'fatfingerjoe', 'eed4d72d5afd2bb377892bb11f38f454', 'added the feature to let the user select how many (5 or 10) results should be shown on a page', '', 1001000, 0, 0),
(5191, 0, 'pb_amazon_search', 1, '1.1.1', 1019, 198, 'Amazon Search', 'You can search the Amazon database  for each Amazon Version that has a SOAP interface.\r\n\r\nYou can limit the search to a specific BrowseNode, a certain Topic (DVD, Books, Foreign Books etc), setup the amount of details Amazon should return.', 1, 0, 3, 1107345599, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"0.0.2-0.0.2";s:3:"php";s:11:"0.0.2-0.0.2";s:3:"cms";s:0:"";}}', 'Patrick Bauerochse', 'webmaster@gowh00t.de', 'fatfingerjoe', 'f47b1a2e3ce5c25a5cf8e98c54e565dd', 'i put some loops i often used in functions so the size of the script ist much smaller now', '', 1001001, 0, 0),
(5192, 0, 'pb_amazon_search', 1, '1.2.0', 1019, 751, 'Amazon Search', 'You can search the Amazon database  for each Amazon Version that has a SOAP interface.br /br /\r\nYou can limit the search to a specific BrowseNode, a certain Topic (DVD, Books, Foreign Books etc), setup the amount of details Amazon should return etc.b', 1, 0, 3, 1107514587, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"0.0.2-0.0.2";s:3:"php";s:11:"0.0.2-0.0.2";s:3:"cms";s:0:"";}}', 'Patrick Bauerochse', 'webmaster@gowh00t.de', 'fatfingerjoe', 'df6272670c60da7e887f60578f68a899', 'the outlook of the form is now customizable by editing the premade design template in ext_typoscript_setup.txt\r\n\r\nsimply modify the html code around the markers and have a total new design of your amazon search', '', 1002000, 1, 0),
