(5319, 0, 'photographic_library', 1, '1.8.0', 10344, 839, 'Photographic library', 'Manage and display photos associated with one or several topic(s)', 2, 0, 3, 1120644356, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"0.0.6-0.0.6";s:3:"php";s:11:"0.0.6-0.0.6";s:3:"cms";s:0:"";}}', 'Mathieu Vidal', 'mathaaus.typo3@club-internet.fr', 'mathaaus', 'ebf0f3799d416ed185ab95d2f6ad4c48', 'NEW:default values for title, description, copyright and keywords during import. COMING SOON:default value for topic and after for album.', '', 1008000, 0, 0),
(5320, 0, 'photographic_library', 1, '1.13.0', 10344, 498, 'Photographic library', 'Manage and display photos associated with one or several topic(s)', 2, 0, 3, 1123599399, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"0.0.6-0.0.6";s:3:"php";s:11:"0.0.6-0.0.6";s:3:"cms";s:0:"";}}', 'Mathieu Vidal', 'mathaaus.typo3@club-internet.fr', 'mathaaus', 'e290bff08614b94ef70962609025bbf9', 'Add constant to limit number of photos on the page with code LIST. Links for next and previous pages are at the end of the page', '', 1013000, 0, 0),
(5321, 0, 'photographic_library', 1, '2.0.0', 10344, 2764, 'Photographic library', 'Manage and display photos associated with one or several topic(s) and in an album or not. Allow to do search in a list of photos with a basic search engine. Display list of photos, topics, album, random photos. The single view come in the same page or in', 2, 0, 3, 1126688734, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"0.0.6-0.0.6";s:3:"php";s:11:"0.0.6-0.0.6";s:3:"cms";s:0:"";}}', 'Mathieu Vidal', 'mathaaus.typo3@club-internet.fr', 'mathaaus', '0a1d500571c3695f81e0310c6db215e0', 'Add constant to choose between same page and popup for single view. Add management of FE users comments on single view. Delete use of set_no_cache. Correct bug in build of table with code LIST in one column.', '', 2000000, 0, 0),
