(5415, 0, 'pil_mailform', 1, '1.1.0', 49265, 1192, 'TMailform', 'Template-based mailform that aims to give the developer the highest amount of design flexibility.', 2, -1, 3, 1135355389, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"0.0.2-0.0.2";s:3:"php";s:11:"0.0.2-0.0.2";s:3:"cms";s:0:"";}}', 'Tonni Aagesen', 'typo3@pil.dk', 'sbusch', '60ad98cbfdd4612d51734ae3c1c62284', 'This release is not dedicated to christmas, but the fact that days now are getting longer (at least in my part of the world).\r\n\r\nMost changes are issues reported by users of TMailform - Thank You for reporting theese.\r\n\r\n- WARNING: Changed subpart marker', 'pil.dk', 1001000, 0, 0),
(5416, 0, 'pil_mailform', 1, '2.0.0', 49265, 266, 'TMailform', 'Template-based mailform that aims to give the developer the highest amount of design flexibility.', 2, -1, 3, 1145526573, 'a:0:{}', 'Tonni Aagesen', 'typo3@pil.dk', 'sbusch', 'df84a069bee79e85a106a9483840c041', '- Changed field validation to make it more flexible using regular expressions, error message pr. field etc. See documentation.\r\n- Added possibility to attach files to the mail.\r\n- Added possibility to use TS/overwrite flexform values with TS. See pil_mail', 'pil.dk', 2000000, 0, 0),
(5417, 0, 'pil_mailform', 1, '2.0.1', 49265, 129, 'TMailform', 'Template-based mailform that aims to give the developer the highest amount of design flexibility.', 2, -1, 3, 1145884691, 'a:0:{}', 'Tonni Aagesen', 'typo3@pil.dk', 'sbusch', 'd79d3dbe64b11e597f11aa2bd0579ab6', 'Version 2.0.1\r\n- Fixed incorrect no template defined error.\r\n- Added utf-8 encoding detection of template file to avoid double encoding.', 'pil.dk', 2000001, 0, 0),
(5418, 0, 'pil_mailform', 1, '2.0.2', 49265, 293, 'TMailform', 'Template-based mailform that aims to give the developer the highest amount of design flexibility.', 2, -1, 3, 1145980597, 'a:0:{}', 'Tonni Aagesen', 'typo3@pil.dk', 'sbusch', '3f7bf81e7395138c744172f294d980bd', 'WARNING: The configuration of required fields has changed in 2.0.  See documentation. \r\n\r\nVersion 2.0.2 \r\n- Fixed typo in code causing Invalid argument supplied for foreach()... error. \r\n- Fixed typo in locallang.php file', 'pil.dk', 2000002, 0, 0),
(5419, 0, 'pil_mailform', 1, '2.0.3', 49265, 257, 'TMailform', 'Template-based mailform that aims to give the developer the highest amount of design flexibility.', 2, -1, 3, 1147174366, 'a:0:{}', 'Tonni Aagesen', 'typo3@pil.dk', 'sbusch', '2be92cbc26a7f9bf8f232e6f0fbef782', 'Version 2.0.3\r\n- multi_recipient is now validated against required values.\r\n- Disabled UTF-8 encoding detection as it seems to break some environments.', 'pil.dk', 2000003, 0, 0),
(5420, 0, 'pil_mailform', 1, '2.0.4', 49265, 336, 'TMailform', 'Template-based mailform that aims to give the developer the highest amount of design flexibility.', 2, -1, 3, 1150378825, 'a:0:{}', 'Tonni Aagesen', 'typo3@pil.dk', 'sbusch', 'cfc29010e7574e705fa4b28f2ebe1840', '2.0.4\r\n - checkbox/radio field types are not validated if not set, fixed\r\n - misc tweaks/cleanup', 'pil.dk', 2000004, 0, 0),
(5421, 0, 'pil_mailform', 1, '2.0.5', 49265, 482, 'TMailform', 'Template-based mailform that aims to give the developer the highest amount of design flexibility.', 2, -1, 3, 1154880812, 'a:0:{}', 'Tonni Aagesen', 'typo3@pil.dk', 'sbusch', '532b1ce9ffe3f84deb188973fcbb8bf9', 'Fixes bug causing the invalid email message to show when email is valid (HEADER_EMAIL_INVALID marker).', 'pil.dk', 2000005, 0, 0),
(5422, 0, 'pil_mailform', 1, '3.0.0', 49265, 339, 'TMailform', 'Template-based mailform that aims to give the developer the highest amount of design flexibility.', 2, -1, 3, 1158831901, 'a:0:{}', 'Tonni Aagesen', 'typo3@pil.dk', 'sbusch', '6d6a321cda5914717a43871f7845d889', 'Version 3.0.0\r\n  WARNING: Configuration changed for field default values. See documentation for details.\r\n  Made fe_user markers available for config field Default values. WARNING: marker format changed so the marker is prefixed with an undersco', 'pil.dk', 3000000, 0, 0),
(5423, 0, 'pil_mailform', 1, '3.0.1', 49265, 350, 'TMailform', 'Template-based mailform that aims to give the developer the highest amount of design flexibility.', 2, -1, 3, 1160477514, 'a:0:{}', 'Tonni Aagesen', 'typo3@pil.dk', 'sbusch', 'd3cdeb81049337a5b7bddd2dc7c95f26', 'Version 3.0.1\r\n - Added option to disclose recipient email address in user copy mail (http://bugs.typo3.org/view.php?id3620). See documentation.\r\n - Added possibility to use surname in mail headers (http://bugs.typo3.org/view.php?id4153). See documentat', 'pil.dk', 3000001, 0, 0),
