(5480, 0, 'pt_conference', 1, '0.3.1', 2378, 723, 'Conference Management', 'Extension with several frontend plugins for conference management and administration. Selected features: speaker management, paper submission, program committee rating, accepted talk and tutorials selection, talks/tutorial overviews, visitors registration', 1, 0, 3, 1122630963, 'a:1:{s:7:"depends";a:7:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:3:"cms";s:0:"";s:18:"static_info_tables";s:0:"";s:6:"pt_lib";s:0:"";s:10:"pt_payment";s:0:"";s:11:"pt_html2pdf";s:0:"";}}', 'Rainer Kuhn, Ursula Klinger', 't3extensions@punkt.de', 'sonic', 'c375691405561a4eae6e65a947f0bfa6', 'Code improvements /security improvements', 'punkt.de GmbH', 3001, 0, 0),
(5481, 0, 'pt_conference', 1, '0.4.0', 2378, 464, 'Conference Management', 'Extension with several frontend plugins for conference management and administration. Selected features: speaker management, paper submission, program committee rating, accepted talk and tutorials selection, talks/tutorial overviews, visitors registration', 1, 0, 3, 1154074331, 'a:0:{}', 'Rainer Kuhn, Ursula Klinger', 't3extensions@punkt.de', 'sonic', 'cd4831644d22538d1859b41249153bf7', '(See the manuals changelog for details:) - Attendee limitation for registration implemented (allows closing registration without disabling payment transactions) - Committee overview behavioural changes and improvements - Several minor improvements', 'punkt.de GmbH', 4000, 0, 0),
(5482, 0, 'pt_conference', 1, '0.5.0', 2378, 180, 'Conference Management', 'PHP4 extension - old, but still working ;-) - for conference management and administration. Selected features: speaker management, paper submission, program committee rating, talks overview, visitors registration, accounting admin interface, statistics.', 1, 0, 3, 1185556702, 'a:1:{s:7:"depends";a:7:{s:3:"cms";s:0:"";s:18:"static_info_tables";s:0:"";s:6:"pt_lib";s:6:"0.6.6-";s:11:"pt_html2pdf";s:6:"0.1.0-";s:13:"pt_euvatcheck";s:6:"0.0.7-";s:3:"php";s:11:"4.0.0-0.0.0";s:5:"typo3";s:11:"4.0.0-0.0.0";}}', 'Rainer Kuhn, Ursula Klinger', 't3extensions@punkt.de', 'sonic', 'aa62fb38f01d33440382b55eb90b6974', 'IMPORTANT: This version has new requirements (PHP5 server with XML-RPC for new dependency pt_euvatcheck, TYPO3 4.x) and the extensions TS template will not be added automatically to all pages anymore! Please refer to the manuals changelog for details.', 'punkt.de GmbH', 5000, 0, 0),
(5483, 0, 'pt_conference', 1, '0.5.1', 2378, 280, 'Conference Management', 'PHP4 extension - old, but still working ;-) - for conference management and administration. Selected features: speaker management, paper submission, program committee rating, talks overview, visitors registration, accounting admin interface, statistics.', 1, 0, 3, 1205752939, 'a:0:{}', 'Rainer Kuhn, Ursula Klinger', 't3extensions@punkt.de', 'sonic', 'ab21b682f508afffa668582c5a3c4806', 'Overhaul of credit card payment integration, removed Cardia  (pt_payment) as default since the company Cardia is no more and pt_payment extension is discontinued. Bugfix in admin accounting.', 'punkt.de GmbH', 5001, 1, 0),
