(5708, 0, 'rlmp_eventdb', 1, '0.3.0', 9409, 109, 'Event Database', 'An event database, how it is usually needed for touristical promotion. Contains frontend plugins for different output types including previews / reviews of the event.', 2, -1, 3, 1086439410, 'a:1:{s:7:"depends";a:6:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:3:"cms";s:0:"";s:10:"tt_address";s:0:"";s:7:"tt_news";s:0:"";s:18:"rlmp_dateselectlib";s:0:"";}}', 'Robert Lemke', 'rl@robertlemke.de', 'robert', '293861527780e923bfa36fdc11c8fdc4', 'Added manual, released to the public', 'robert lemke medienprojekte', 3000, 0, 0),
(5709, 0, 'rlmp_eventdb', 1, '0.3.1', 9409, 2092, 'Event Database', 'This frontend plugin handles an event database such as needed for tourist purposes', 2, -1, 3, 1086637147, 'a:1:{s:7:"depends";a:7:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:3:"cms";s:0:"";s:10:"tt_address";s:0:"";s:7:"tt_news";s:0:"";s:18:"rlmp_dateselectlib";s:0:"";s:7:"overlib";s:0:"";}}', 'Robert Lemke', 'rl@robertlemke.de', 'robert', '838156637bacb50441622e5861fc83fb', 'Added "overlib" extension to the dependencies in emconf.php', 'robert lemke medienprojekte', 3001, 0, 0),
(5710, 0, 'rlmp_eventdb', 1, '0.4.0', 9409, 192, 'Event Database', 'An event database, how it is usually needed for touristical promotion. Contains frontend plugins for different output types including previews / reviews of the event.', 1, -1, 3, 1105976324, 'a:1:{s:7:"depends";a:7:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:3:"cms";s:0:"";s:10:"tt_address";s:0:"";s:7:"tt_news";s:0:"";s:18:"rlmp_dateselectlib";s:0:"";s:7:"overlib";s:0:"";}}', 'Robert Lemke', 'robert@typo3.org', 'robert', '40a79effde9781601b71db886b136200', 'Fixed bug: Date in list view was wrong at some events and differed from the single view because of incorrect handling of daylight saving time and leap years. Note: This version might still be hard to use for you especially with newer versions of tt_news.', 'robert lemke medienprojekte', 4000, 0, 0),
