(5716, 0, 'rlmp_eventdb', 1, '1.0.4', 9409, 1954, 'Event Database', 'A full-featured event database with booking and payment support.', 2, -1, 3, 1129545182, 'a:1:{s:7:"depends";a:8:{s:5:"typo3";s:11:"3.7.2-0.0.2";s:3:"php";s:11:"4.3.2-0.0.2";s:3:"cms";s:0:"";s:7:"address";s:0:"";s:18:"rlmp_dateselectlib";s:0:"";s:7:"overlib";s:0:"";s:16:"frontendformslib";s:0:"";s:8:"moneylib";s:0:"";}}', 'Robert Lemke', 'robert@typo3.org', 'robert', '29c543aeb78189a42e16e8a9749e76d0', 'Fixed a bug caused the total sum in confirmation mails to be always zero.', 'robert lemke medienprojekte', 1000004, 0, 0),
