(5720, 0, 'rlmp_extdbauth', 1, '1.0.1', 1591, 212, 'Auth: External DB Authentication', 'Authenticates against an external database accessible via ADODB.', 2, 0, 5, 1122212650, 'a:1:{s:7:"depends";a:5:{s:5:"typo3";s:0:"";s:3:"php";s:11:"0.0.2-0.0.2";s:3:"cms";s:0:"";s:5:"adodb";s:0:"";s:11:"datasources";s:0:"";}}', 'Robert Lemke', 'robert@typo3.org', 'robert', '04749102d149fee867b09b0bf50770f7', 'Changed dependencies: Removed dependency from extension "cc_sv_auth" and raised required TYPO3 version to 3.8.0', 'robert lemke medienprojekte', 1000001, 0, 0),
