INSERT INTO `tx_extensionmanager_domain_model_extension` (`uid`, `pid`, `extension_key`, `repository`, `version`, `alldownloadcounter`, `downloadcounter`, `title`, `description`, `state`, `review_state`, `category`, `last_updated`, `serialized_dependencies`, `author_name`, `author_email`, `ownerusername`, `md5hash`, `update_comment`, `authorcompany`, `integer_version`, `current_version`, `lastreviewedversion`) VALUES
(5722, 0, 'rlmp_extensiondocs', 1, '0.2.0', 2290, 231, 'Extension manual viewer', 'Provides a backend module which displays the manuals of all locally available extensions. Of course that requires that you have downloaded the manual on beforehand ...', 2, 0, 1, 1127662484, 'a:1:{s:7:"depends";a:5:{s:5:"typo3";s:11:"0.0.2-0.0.2";s:3:"php";s:11:"0.0.2-0.0.2";s:3:"cms";s:0:"";s:4:"lang";s:0:"";s:14:"rlmp_officelib";s:0:"";}}', 'Robert Lemke', 'rl@robertlemke.de', 'robert', '33cc173b469e57d2c31ae988615d675e', 'First public release', 'robert lemke medienprojekte', 2000, 0, 0),
(5723, 0, 'rlmp_extensiondocs', 1, '0.3.0', 2290, 2044, 'Extension manual viewer', 'Provides a backend module which displays the manuals of all locally available extensions. Of course that requires that you have downloaded the manual on beforehand ...', 2, 0, 1, 1128369701, 'a:0:{}', 'Robert Lemke', 'rl@robertlemke.de', 'robert', '81fb04bcf6ffe3b6e1c917a0ca169e37', 'Added support for reading system- and global extensions. Thanks to Michael Stucki and all others who sent patches!', 'robert lemke medienprojekte', 3000, 1, 0),
(5724, 0, 'rlmp_filedevlog', 1, '0.1.0', 1038, 1031, 'File DevLog', 'Redirects messages sent via t3lib_div::devLog to ordinary (text) logfiles.', 2, 1, 4, 1127939461, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";}}', 'Robert Lemke', 'robert@typo3.org', 'andreaswolf', 'b8fcd448a844d0d81522b6436c8f2090', 'Initial upload', 'robert lemke medienprojekte', 1000, 1, 0),
(5725, 0, 'rlmp_flashdetection', 1, '1.0.2', 15129, 449, 'Flash (with XML and Detection)', 'This plugin provides a new record type "Flash" with advanced detection routines for most platforms and Flash versions. It features XML parameters as well as direct access from other extensions.', 1, 0, 3, 1068202729, 'a:1:{s:7:"depends";a:4:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:3:"cms";s:0:"";s:4:"lang";s:0:"";}}', 'Robert Lemke', 'rl@robertlemke.de', 'commodore', '10f9be230e3c89c5698b402ee1d26824', '', 'robert lemke medienprojekte', 1000002, 0, 0),
(5726, 0, 'rlmp_flashdetection', 1, '1.0.3', 15129, 6149, 'Flash (with XML and Detection)', 'This plugin provides a new record type "Flash" with advanced detection routines for most platforms and Flash versions. It features XML parameters as well as direct access from other extensions.', 2, 0, 3, 1071227366, 'a:0:{}', 'Robert Lemke', 'rl@robertlemke.de', 'commodore', '69b7aa41861584490c390f05fa02843e', '', 'robert lemke medienprojekte', 1000003, 0, 0),
(5727, 0, 'rlmp_flashdetection', 1, '1.1.0', 15129, 374, 'Flash (with XML and Detection)', 'This plugin provides a new record type "Flash" with advanced detection routines for most platforms and Flash versions. It features XML parameters as well as direct access from other extensions.', 2, 0, 3, 1156269182, 'a:1:{s:7:"depends";a:2:{s:3:"cms";s:0:"";s:4:"lang";s:0:"";}}', 'Andre Steiling', 'steiling@pilotprojekt.com', 'commodore', '998a8ef18354f29fb28e60892c462ae6', 'SPECIAL THANKS to Jose Antonio Guerra jaguerra@icti.es! Changes: Flash code detection now using "Adobe detection_kit", non upper version limit, most of JS code is included from an external file, IE patent problem solved.', 'high StandArt, PILOTprojekt }', 1001000, 0, 0),
(5728, 0, 'rlmp_flashdetection', 1, '1.1.1', 15129, 528, 'Flash (with XML and Detection)', 'This plugin provides a new record type "Flash" with advanced detection routines for most platforms and Flash versions. It features XML parameters as well as direct access from other extensions.', 2, 0, 3, 1157471807, 'a:1:{s:7:"depends";a:2:{s:3:"cms";s:0:"";s:4:"lang";s:0:"";}}', 'Andre Steiling', 'steiling@pilotprojekt.com', 'commodore', '4f4c7ff4cfaf7058a032115373eaa4a7', 'Only small changes in relation to DTD xHTML strict.', 'high StandArt, PILOTprojekt }', 1001001, 0, 0),
(5729, 0, 'rlmp_flashdetection', 1, '1.1.2', 15129, 354, 'Flash (with XML and Detection)', 'This plugin provides a new record type "Flash" with advanced detection routines for most platforms and Flash versions. It features XML parameters as well as direct access from other extensions.', 2, 0, 3, 1164369109, 'a:1:{s:7:"depends";a:2:{s:3:"cms";s:0:"";s:4:"lang";s:0:"";}}', 'Andre Steiling', 'steiling@pilotprojekt.com', 'commodore', 'a4970825498847e8e9de8b39ca043460', 'Changed db-field "loop" to "flashloop". Please be patient, many other corretions will be done soon! Thanks for your emails!', 'high StandArt, PILOTprojekt }', 1001002, 0, 0),
(5730, 0, 'rlmp_flashdetection', 1, '1.2.0', 15129, 424, 'AST Flash (Adobe Detection v1.5)', 'This plugin provides a new record type "Flash" with advanced detection routines for most platforms and Flash versions. It features XML parameters as well as direct access from other extensions.', 2, 0, 3, 1166565914, 'a:1:{s:7:"depends";a:2:{s:3:"cms";s:0:"";s:4:"lang";s:0:"";}}', 'Andre Steiling', 'steiling@pilotprojekt.com', 'commodore', 'ffd9ea35b50c47b91b20205a4b98ecab', 'The "Merry Christmas" Edition :) Thanks to your mails, all the changes are done, please see documentation-changelog for details!', 'high StandArt, PILOTprojekt }', 1002000, 0, 0),
(5731, 0, 'rlmp_flashdetection', 1, '1.2.1', 15129, 371, 'AST Flash (with Adobe Detection v1.5)', 'This plugin provides a new record type "Flash" with advanced detection routines for most platforms and Flash versions. It features XML parameters as well as direct access from other extensions.', 2, 0, 3, 1167319329, 'a:1:{s:7:"depends";a:2:{s:3:"cms";s:0:"";s:4:"lang";s:0:"";}}', 'Andre Steiling', 'steiling@pilotprojekt.com', 'commodore', '7c7f323e7abb293c93f9e5a2905273ca', '- Small fix: Max size for the flash movie file is now 10.000kb.', 'high StandArt, PILOTprojekt }', 1002001, 0, 0),
(5732, 0, 'rlmp_flashdetection', 1, '1.2.2', 15129, 236, 'AST Flash (with Adobe Detection v1.5)', 'This plugin provides a new record type "Flash" with advanced detection routines for most platforms and Flash versions. It features XML parameters as well as direct access from other extensions.', 2, 0, 3, 1173196280, 'a:1:{s:7:"depends";a:2:{s:3:"cms";s:0:"";s:4:"lang";s:0:"";}}', 'Andre Steiling', 'steiling@pilotprojekt.com', 'commodore', 'adf31b0adefc29abe0fcfcb6625f9904', 'Output is now wrapped by function pi_wrapInBaseClass().', 'high StandArt, PILOTprojekt }', 1002002, 0, 0),
(5733, 0, 'rlmp_flashdetection', 1, '1.2.3', 15129, 837, 'AST Flash (with Adobe Detection v1.5)', 'This plugin provides a new record type "Flash" with advanced detection routines for most platforms and Flash versions. It features XML parameters as well as direct access from other extensions.', 2, 0, 3, 1174309475, 'a:1:{s:7:"depends";a:2:{s:3:"cms";s:0:"";s:4:"lang";s:0:"";}}', 'Andre Steiling', 'steiling@pilotprojekt.com', 'commodore', 'b32a0c8b1d22da03a215e10c073a6d0c', 'Updated tables.sql to standard TYPO3 DB structure in order to use all types of "enableFields".', 'high StandArt, PILOTprojekt }', 1002003, 0, 0),
(5734, 0, 'rlmp_flashdetection', 1, '1.2.4', 15129, 262, 'AST Flash (with Adobe Detection v1.5)', 'This plugin provides a new record type "Flash" with advanced detection routines for most platforms and Flash versions. It features XML parameters as well as direct access from other extensions.', 2, 0, 3, 1187962143, 'a:1:{s:7:"depends";a:2:{s:3:"cms";s:0:"";s:4:"lang";s:0:"";}}', 'Andre Steiling', 'steiling@pilotprojekt.com', 'commodore', '7132df97b17eef824a38bf6adbc25f15', 'Fixed some bugs and added new features, see changelog in the documentation.', 'high StandArt, PILOTprojekt }', 1002004, 0, 0),
(5735, 0, 'rlmp_flashdetection', 1, '1.2.5', 15129, 1043, 'AST Flash (with Adobe Detection v1.5)', 'This plugin provides a new record type "Flash" with advanced detection routines for most platforms and Flash versions. It features XML parameters as well as direct access from other extensions.', 2, 0, 3, 1204813417, 'a:0:{}', 'Andre Steiling', 'steiling@elemente.ms', 'commodore', 'fd52d8c0b0a1d33ebe63c43fe983cd49', '', 'elemente websolutions', 1002005, 0, 0),
(5736, 0, 'rlmp_flashdetection', 1, '1.2.8', 15129, 378, 'AST Flash (with Adobe Detection v1.5)', 'This plugin provides a new record type "Flash" with advanced detection routines for most platforms and Flash versions. It features XML parameters as well as direct access from other extensions.', 2, 0, 3, 1206953188, 'a:0:{}', 'Andre Steiling', 'steiling@elemente.ms', 'commodore', '1d87aa4f449d6ba66355a770d7595382', 'Some bufixes and a new helpful feature - see changelog in documentation!', 'elemente websolutions', 1002008, 0, 0),
(5737, 0, 'rlmp_flashdetection', 1, '1.3.0', 15129, 709, 'AST Flash (with Adobe Detection v1.5)', 'This plugin provides a new record type "Flash" with advanced detection routines for most platforms and Flash versions. It features XML parameters as well as direct access from other extensions.', 2, 0, 3, 1211905105, 'a:0:{}', 'Andre Steiling', 'steiling@elemente.ms', 'commodore', '6ae6fb1aae6dd4c53a82deb2408ca9a3', 'Now you can choose if you want to use file references instead of copies - see doc!\nATTENTION: This feature is not yet tested well, so please be careful in productive environments and PLEASE send me feedback!', 'elemente websolutions', 1003000, 0, 0),
(5738, 0, 'rlmp_flashdetection', 1, '1.3.2', 15129, 35, 'AST Flash (Adobe Detection v1.6/1.5)', 'This plugin provides a new record type "Flash" with advanced detection routines for most platforms and Flash versions. It features XML parameters as well as direct access from other extensions.', 2, 0, 3, 1221566715, 'a:0:{}', 'Andre Steiling', 'steiling@elemente.ms', 'commodore', '30ba175eac865f035802960c55e5a3fc', 'Added percent values for w/h, stdWrap for conf.xmlfile and v1.6 of the detection routine, see documentation for details.', 'elemente websolutions', 1003002, 0, 0),
