(5740, 0, 'rlmp_flashdetection', 1, '1.3.4', 15129, 617, 'AST Flash (Adobe Detection v1.6/1.5)', 'This plugin provides a new record type "Flash" with advanced detection routines for most platforms and Flash versions. It features XML parameters as well as direct access from other extensions.', 2, 0, 3, 1221810588, 'a:0:{}', 'Andre Steiling', 'steiling@elemente.ms', 'commodore', '78dcffb169cbaf63543177c4e3c49532', '1.3.4: Fixed stdWrap "Bug".\r\n1.3.3: Fixed JS alert in FF/Opera.\r\n1.3.2: Added percent values for w/h, stdWrap for conf.xmlfile and v1.6 of the detection routine, see documentation for details.', 'elemente websolutions', 1003004, 0, 0),
(5741, 0, 'rlmp_flashdetection', 1, '1.3.6', 15129, 393, 'AST Flash (Adobe Detection v1.6/1.5)', 'This plugin provides a new record type "Flash" with advanced detection routines for most platforms and Flash versions. It features XML parameters as well as direct access from other extensions.', 2, 0, 3, 1240563822, 'a:0:{}', 'Andre Steiling', 'steiling@elemente.ms', 'commodore', 'db329b4727079815b743c1f1c48e6416', 'Latest features: "plugin.conf" is completely stdWrap enabled (by Martin Holtz), tables.sql optimization.', 'elemente websolutions', 1003006, 0, 0),
