(5744, 0, 'rlmp_flashdetection', 1, '1.3.9', 15129, 604, 'AST Flash (Adobe Detection v1.6/1.5)', 'This plugin provides a new record type "Flash" with advanced detection routines for most platforms and Flash versions. It features XML parameters as well as direct access from other extensions.', 2, 0, 3, 1259243414, 'a:0:{}', 'Andre Steiling', 'steiling@elemente.ms', 'commodore', '07ec1c071b47d4451037e888cd1a11ad', 'Add TypoScript condition to set different codeBase property to prevent IE security alerts while browsing a SSL encrypted site.', 'elemente websolutions', 1003009, 0, 0),
