(5908, 0, 'rte_chooser', 1, '0.0.3', 3497, 3239, 'Rich Text Editor - Chooser', 'Is more then own RTE loaded, this extension choose the best for your browser. Just experimental and not very good, but you need it for rte_pb_htmlarea. You need to update some files in your typo3 path.', 5, 0, 0, 1099856168, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";}}', 'Philipp Borgmann', 'philipp.borgmann@gmx.de', 'philippborgmann', '98d222156e62a328647e7bf57d5b3757', '', '', 3, 1, 0),
