(5911, 0, 'ttnews_feeder', 1, '2.2.14', 12421, 10, 'News Feeder', 'Flexible and powerful system to fetch  news from search engines or parsing static/dynamic pages and fill ttnews   table. A valid alternative to retrieve news from sites that have not RSS implemented. CRON feature implemented (v2.0)', 2, 0, 3, 1247051100, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"4.3.4-0.0.0";s:5:"typo3";s:11:"3.8.1-0.0.0";}}', 'Alex Tuveri', 'at@uniud.it', 'gilas', 'b152649fbcb05c47bb4a0b196a0ef13d', 'Minor bug fix: now URLs written into db are filtered using htmlspecialchars_decode  PHP function.', '', 2002014, 0, 0),
(5912, 0, 'ttnews_feeder', 1, '0.0.1', 12421, 221, 'ttnews_feeder', 'A system to feed automatically the table tt_news from various sites and search engines.', 1, 0, 3, 1161597336, 'a:1:{s:7:"depends";a:2:{s:7:"tt_news";s:0:"";s:3:"cms";s:0:"";}}', 'Alex Tuveri', 'at@uniud.it', 'gilas', '341fcda4da9a48aeabf781567a971a9c', 'No documentation - Partially on production mode, todos: CRON script, approval section, FE output to list sites/engine visited.', '', 1, 0, 0);
