(5917, 0, 'ttnews_feeder', 1, '0.8.5', 12421, 192, 'ttnews_feeder', 'A system to feed automatically the table tt_news from various sites and search engines.', 1, 0, 3, 1162223951, 'a:1:{s:7:"depends";a:2:{s:7:"tt_news";s:0:"";s:3:"cms";s:0:"";}}', 'Alex Tuveri', 'at@uniud.it', 'gilas', 'c903ead6d27e05836ca7635fc29fcefa', '', '', 8005, 0, 0),
(5918, 0, 'ttnews_feeder', 1, '0.8.6', 12421, 211, 'ttnews_feeder', 'A system to feed automatically the table tt_news from various sites and search engines.', 1, 0, 3, 1162278463, 'a:1:{s:7:"depends";a:2:{s:7:"tt_news";s:0:"";s:3:"cms";s:0:"";}}', 'Alex Tuveri', 'at@uniud.it', 'gilas', '9208afe03f60e3c22dd7e34c6b3a98ca', 'Manual ugraded; minor bug fix (cache not cleared after approval); security implementation.', '', 8006, 0, 0),
(5919, 0, 'ttnews_feeder', 1, '0.8.7', 12421, 255, 'ttnews_feeder', 'A hi-flexible system to feed automatically the table tt_news from search engines or static sites that have not RSS implemented.', 1, 0, 3, 1163269290, 'a:1:{s:7:"depends";a:2:{s:7:"tt_news";s:0:"";s:3:"cms";s:0:"";}}', 'Alex Tuveri', 'at@uniud.it', 'gilas', '89005a3deab629232f24ace8ca69fe12', 'Sites definition made easy, now you can load predefined sites from BE. Access to function for admin and not. Checkboxes to selec one or more sites to test or run in production mode.\nManual updated in english language, minor bug fixes.', '', 8007, 0, 0),
(5920, 0, 'ttnews_feeder', 1, '0.8.8', 12421, 214, 'ttnews_feeder', 'A hi-flexible system to feed automatically the table tt_news from search engines or static sites that have not RSS implemented.', 1, 0, 3, 1163535432, 'a:1:{s:7:"depends";a:2:{s:7:"tt_news";s:0:"";s:3:"cms";s:0:"";}}', 'Alex Tuveri', 'at@uniud.it', 'gilas', 'a30826a4682e2dfdf9f6f03c7d874b72', 'Doc mistake: TSConfig must be copied ONLY in root page. Improved menus.', '', 8008, 0, 0),
(5921, 0, 'ttnews_feeder', 1, '0.8.9', 12421, 178, 'ttnews_feeder', 'A hi-flexible system to feed automatically the table tt_news from search engines or static sites that have not RSS implemented.', 1, 0, 3, 1163695706, 'a:1:{s:7:"depends";a:2:{s:7:"tt_news";s:0:"";s:3:"cms";s:0:"";}}', 'Alex Tuveri', 'at@uniud.it', 'gilas', 'e4f1e0f8bd659ef9f00e6fa103236518', 'Bug Fixed: ext module conf will be read from the whole root-line.', '', 8009, 0, 0),
(5922, 0, 'ttnews_feeder', 1, '0.8.10', 12421, 306, 'ttnews_feeder', 'Hi-flexible system to feed automatically the table tt_news from search engines and/or static sites that have not RSS implemented.', 1, 0, 3, 1163709099, 'a:0:{}', 'Alex Tuveri', 'at@uniud.it', 'gilas', '1a06d73bfa639fbedf03642d60c21417', 'New field introduced: lastcheck to remember on manual check when the site was visited last time.', '', 8010, 0, 0),
(5923, 0, 'ttnews_feeder', 1, '1.0.0', 12421, 171, 'ttnews_feeder', 'Flexible and powerful system to fetch  news from search engines or parsing static/dynamic pages and fill ttnews   table. A valid alternative to retrieve news from sites that have not RSS implemented.', 2, 0, 3, 1163869401, 'a:0:{}', 'Alex Tuveri', 'at@uniud.it', 'gilas', '0478016904413222abc4b83199246cc5', 'Graphic changes; added new messages for functions; guide updated. Now NEWS.GOOGLE.COM is available as predefined site for immediate installation and working.', '', 1000000, 0, 0),
(5924, 0, 'ttnews_feeder', 1, '1.0.1', 12421, 62, 'ttnews_feeder', 'Flexible and powerful system to fetch  news from search engines or parsing static/dynamic pages and fill ttnews   table. A valid alternative to retrieve news from sites that have not RSS implemented.', 2, 0, 3, 1163921887, 'a:0:{}', 'Alex Tuveri', 'at@uniud.it', 'gilas', 'b812c02a72cab349a815b5b9a6c29643', '1) SITES PREDEFINED to run and fetch news immediately:\n news.google.it\n news.google.com\n yahoo.it news\n yahoo.com news\n\n2) GUIDE UPDATED - New features described, screenshot added.', '', 1000001, 0, 0),
(5925, 0, 'ttnews_feeder', 1, '1.0.2', 12421, 220, 'ttnews_feeder', 'Flexible and powerful system to fetch  news from search engines or parsing static/dynamic pages and fill ttnews   table. A valid alternative to retrieve news from sites that have not RSS implemented.', 2, 0, 3, 1163929254, 'a:0:{}', 'Alex Tuveri', 'at@uniud.it', 'gilas', 'c7954c2e787cccddd8894ec2b9c66335', 'PREDEFINED SITES to fetch news immediately:\nGoogle.it,Yahoo.it,Google.com,Yahoo.com\n\nUPDATE function WORKING FINE. If you upgraded from v. 1.0.1. please Update your sites.\n\nMANUAL updated with some example, improvements and screenshots.', '', 1000002, 0, 0),
(5926, 0, 'ttnews_feeder', 1, '1.0.3', 12421, 162, 'News Feeder', 'Flexible and powerful system to fetch  news from search engines or parsing static/dynamic pages and fill ttnews   table. A valid alternative to retrieve news from sites that have not RSS implemented.', 2, 0, 3, 1164019873, 'a:1:{s:7:"depends";a:2:{s:7:"tt_news";s:0:"";s:3:"cms";s:0:"";}}', 'Alex Tuveri', 'at@uniud.it', 'gilas', 'e9a3399a56d554e9c45f88cebab4c642', 'IMAGE SUPPORTED - on test mode nothing will be written, on production mode images will be stored on your server\nSITES PREDEFINED - news.google.it, news.google.com, yahoo news .it, yahoo news.com\nREMOVE function updated: now all images related to a news wi', '', 1000003, 0, 0),
(5927, 0, 'ttnews_feeder', 1, '1.0.4', 12421, 201, 'News Feeder', 'Flexible and powerful system to fetch  news from search engines or parsing static/dynamic pages and fill ttnews   table. A valid alternative to retrieve news from sites that have not RSS implemented.', 2, 0, 3, 1164097967, 'a:1:{s:7:"depends";a:2:{s:7:"tt_news";s:0:"";s:3:"cms";s:0:"";}}', 'Alex Tuveri', 'at@uniud.it', 'gilas', '920f5fba96efa9df194253da163dcf71', 'IMAGE download supported, MANUAL updated,\nDELETE old news corrected.', '', 1000004, 0, 0),
(5928, 0, 'ttnews_feeder', 1, '1.0.5', 12421, 5, 'News Feeder', 'Flexible and powerful system to fetch  news from search engines or parsing static/dynamic pages and fill ttnews   table. A valid alternative to retrieve news from sites that have not RSS implemented.', 2, 0, 3, 1164129243, 'a:1:{s:7:"depends";a:2:{s:7:"tt_news";s:0:"";s:3:"cms";s:0:"";}}', 'Alex Tuveri', 'at@uniud.it', 'gilas', 'e34dbd1594a28f2a9e0a48449f033d79', 'IMAGE download supported, MANUAL updated, DELETE old news corrected; counter adjusted..', '', 1000005, 0, 0),
(5929, 0, 'ttnews_feeder', 1, '1.0.6', 12421, 253, 'News Feeder', 'Flexible and powerful system to fetch  news from search engines or parsing static/dynamic pages and fill ttnews   table. A valid alternative to retrieve news from sites that have not RSS implemented.', 2, 0, 3, 1164316266, 'a:1:{s:7:"depends";a:2:{s:7:"tt_news";s:0:"";s:3:"cms";s:0:"";}}', 'Alex Tuveri', 'at@uniud.it', 'gilas', 'b87b9e6754431605f16be56dce5750b6', 'IMAGE download supported, MANUAL updated, DELETE old news corrected; engine counter modified.', '', 1000006, 0, 0),
