(6059, 0, 'rvt_adodb', 1, '0.2.4', 2272, 25, 'ADOdb Interface', 'Make a interface to ADOdb (for PHP programmers)', 0, 0, 4, 1187812886, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"4.0.0-0.0.0";s:3:"php";s:11:"4.3.0-5.1.9";s:5:"adodb";s:0:"";}}', 'R. van Twisk', 'ries@vantwisk.nl', 'ries', 'fbb862a81f2fc27df0d923b0dd87b778', 'Found a small bug when the hosts option was left blank, then ADOdb wanted to connect to a DB called apache - RVT', '', 2004, 0, 0),
