(6106, 0, 'sb_flexamples', 1, '0.0.1', 1011, 24, 'Flexform Examples', 'The target of this extension is to demonstrate the different types of Flexform fields.', 1, 0, 9, 1122838496, 'a:0:{}', 'Elmar Hinz', 'elmar.hinz@team-red.net', 'elmar.hinz', '23cf2ecb830c68ef84c229c5c38ee641', 'initial upload', '', 1, 0, 0),
(6107, 0, 'sb_flexamples', 1, '0.0.2', 1011, 987, 'Flexform Examples', 'The target of this extension is to demonstrate the different types of Flexform fields.\r\n\r\nExample from the book TYPO3 from Galileo Press: http://www.amazon.de/exec/obidos/ASIN/389842605X', 1, 0, 9, 1122925043, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:3:"cms";s:0:"";}}', 'Elmar Hinz', 'elmar.hinz@team-red.net', 'elmar.hinz', 'cab12d22a05c82704c46c22ba365488c', 'Fixed simple selection bug.', '', 2, 1, 0),
(6108, 0, 'sb_flexworld', 1, '0.0.1', 848, 32, 'Flexform "Hello World"', 'Tiny extension, that demonstrates how to get started with flexforms. You can enter a word and select a conversion to upper or lowercase. Conver output to FE.', 1, 0, 9, 1122816495, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:3:"cms";s:0:"";}}', 'Elmar Hinz', 'elmar.hinz@team-red.net', 'elmar.hinz', '3c688254822159476f865843d7453e02', 'Initial upload', '', 1, 0, 0),
