(6116, 0, 'security_formmail', 1, '1.0.0', 1383, 1334, 'Security update: Formmail issue', 'This extension fixes a problem with formmail elements. Works with TYPO3 3.6.x and 3.7.x. You will not need this patch on versions starting from 3.8.0.', 2, 0, 4, 1110204490, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"0.0.2-0.0.2";s:3:"php";s:11:"0.0.2-0.0.2";s:3:"cms";s:0:"";}}', 'Michael Stucki', 'michael@typo3.org', 'stucki', '4587948915f9b14a99d7b71ac36e38e8', 'Initial upload.', '', 1000000, 1, 0),
(6117, 0, 'seminars', 1, '0.4.0', 10760, 224, 'Seminar Manager', 'This extension allows you to create and manage a list of seminars, workshops, lectures and other events as an overview or as detailed descriptions. In addition, it allows frontend users to register for seminars.', 0, -1, 3, 1131493685, 'a:1:{s:7:"depends";a:5:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:3:"cms";s:0:"";s:18:"css_styled_content";s:0:"";s:16:"frontendformslib";s:0:"";}}', 'Oliver Klee', 'typo3-coding@oliverklee.de', 'oliklee', '6a70a847dcd516bb46c872c72225d641', 'Lots of polish, now that the online registration is implemented. Get it!', 'AStA Bonn', 4000, 0, 0);
INSERT INTO `tx_extensionmanager_domain_model_extension` (`uid`, `pid`, `extension_key`, `repository`, `version`, `alldownloadcounter`, `downloadcounter`, `title`, `description`, `state`, `review_state`, `category`, `last_updated`, `serialized_dependencies`, `author_name`, `author_email`, `ownerusername`, `md5hash`, `update_comment`, `authorcompany`, `integer_version`, `current_version`, `lastreviewedversion`) VALUES
(6118, 0, 'seminars', 1, '0.4.1', 10760, 257, 'Seminar Manager', 'This extension allows you to create and manage a list of seminars, workshops, lectures, theater performances and other events as an overview or as detailed descriptions. In addition, it allows front end users to register for these events.', 0, -1, 3, 1132832181, 'a:1:{s:7:"depends";a:5:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:3:"cms";s:0:"";s:18:"css_styled_content";s:0:"";s:16:"frontendformslib";s:0:"";}}', 'Oliver Klee', 'typo3-coding@oliverklee.de', 'oliklee', 'ba83b135afed0b68137b610d7f2f04c4', 'Added the following fields to the seminar records: special price, credit points, accreditation number. IMPORTANT: Please read the status notepad before updating to this version.', 'AStA Bonn', 4001, 0, 0),
(6119, 0, 'seminars', 1, '0.4.2', 10760, 161, 'Seminar Manager', 'This extension allows you to create and manage a list of seminars, workshops, lectures, theater performances and other events as an overview or as detailed descriptions. In addition, it allows front end users to register for these events.', 0, -1, 3, 1136382673, 'a:1:{s:7:"depends";a:5:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:3:"cms";s:0:"";s:18:"css_styled_content";s:0:"";s:16:"frontendformslib";s:0:"";}}', 'Oliver Klee', 'typo3-coding@oliverklee.de', 'oliklee', '25a4e58caef6f3bc1359675f2bdc5b55', 'New features: registration deadline, multiple-seat registrations, configurable time windows for the list view. Bugfix: the second flexforms sheet was non-functional.', 'AStA Bonn', 4002, 0, 0),
(6120, 0, 'seminars', 1, '0.4.3', 10760, 780, 'Seminar Manager', 'This extension allows you to create and manage a list of seminars, workshops, lectures, theater performances and other events as an overview or as detailed descriptions. In addition, it allows front end users to register for these events.', 0, -1, 3, 1136393765, 'a:1:{s:7:"depends";a:5:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:3:"cms";s:0:"";s:18:"css_styled_content";s:0:"";s:16:"frontendformslib";s:0:"";}}', 'Oliver Klee', 'typo3-coding@oliverklee.de', 'oliklee', 'd71e213a1de261044c4088124eb26452', '', 'AStA Bonn', 4003, 0, 0),
(6121, 0, 'seminars', 1, '0.4.4', 10760, 291, 'Seminar Manager', 'This extension allows you to create and manage a list of seminars, workshops, lectures, theater performances and other events as an overview or as detailed descriptions. In addition, it allows front end users to register for these events.', 0, -1, 3, 1153518467, 'a:1:{s:7:"depends";a:5:{s:3:"cms";s:0:"";s:18:"css_styled_content";s:0:"";s:16:"frontendformslib";s:0:"";s:3:"php";s:6:"4.0.0-";s:5:"typo3";s:6:"3.8.0-";}}', 'Oliver Klee', 'typo3-coding@oliverklee.de', 'oliklee', '08d6237cb7f0f68d7fdf12df2c5609ec', 'Many new features and a few bugfixes. Works with TYPO3 4.0.', 'oliverklee.de', 4004, 0, 0),
(6122, 0, 'seminars', 1, '0.4.5', 10760, 516, 'Seminar Manager', 'This extension allows you to create and manage a list of seminars, workshops, lectures, theater performances and other events as an overview or as detailed descriptions. In addition, it allows front end users to register for these events.', 0, -1, 3, 1154446962, 'a:1:{s:7:"depends";a:5:{s:3:"cms";s:0:"";s:18:"css_styled_content";s:0:"";s:16:"frontendformslib";s:0:"";s:3:"php";s:6:"4.0.0-";s:5:"typo3";s:6:"3.8.0-";}}', 'Oliver Klee', 'typo3-coding@oliverklee.de', 'oliklee', '702e5e2a5a95f09b2356129f846b6349', 'Added place and time to the list view. Made the registration page more configurable. Fixed a bug with multi-language sites.', 'oliverklee.de', 4005, 0, 0),
(6123, 0, 'seminars', 1, '0.4.6', 10760, 407, 'Seminar Manager', 'This extension allows you to create and manage a list of seminars, workshops, lectures, theater performances and other events as an overview or as detailed descriptions. In addition, it allows front end users to register for these events.', 0, -1, 3, 1158523173, 'a:1:{s:7:"depends";a:5:{s:3:"cms";s:0:"";s:18:"css_styled_content";s:0:"";s:16:"frontendformslib";s:0:"";s:3:"php";s:6:"4.0.0-";s:5:"typo3";s:6:"3.8.0-";}}', 'Oliver Klee', 'typo3-coding@oliverklee.de', 'oliklee', 'f52f5b43244bc4e6ed734764fe99c3dc', 'New Danish translation.\nFeature: Use different event types.\nSome FE polish.', 'oliverklee.de', 4006, 0, 0),
(6124, 0, 'seminars', 1, '0.4.7', 10760, 400, 'Seminar Manager', 'This extension allows you to create and manage a list of seminars, workshops, lectures, theater performances and other events as an overview or as detailed descriptions. In addition, it allows front end users to register for these events.', 0, -1, 3, 1163895851, 'a:0:{}', 'Oliver Klee', 'typo3-coding@oliverklee.de', 'oliklee', '9f0d950c0262c315944f4c71c6a9b640', 'New features: Automatic configuration checking, early bird prices, separation of topics and dates.\r\nBug fixes concerning Direct Mail, TYPO3 3.8.1 and the default sort order.', 'oliverklee.de', 4007, 0, 0),
(6125, 0, 'seminars', 1, '0.4.8', 10760, 386, 'Seminar Manager', 'This extension allows you to create and manage a list of seminars, workshops, lectures, theater performances and other events as an overview or as detailed descriptions. In addition, it allows front end users to register for these events.', 0, -1, 3, 1169215777, 'a:1:{s:7:"depends";a:5:{s:3:"cms";s:0:"";s:18:"css_styled_content";s:0:"";s:16:"frontendformslib";s:0:"";s:3:"php";s:6:"4.0.0-";s:5:"typo3";s:6:"3.8.0-";}}', 'Oliver Klee', 'typo3-coding@oliverklee.de', 'oliklee', 'd3ee4513e24deb6787ef87a834211b8b', 'This is a bug fix release: Tons of bug fixes and a few enhancements to the configuration check, but no new features.', 'oliverklee.de', 4008, 0, 0),
(6126, 0, 'seminars', 1, '0.4.9', 10760, 327, 'Seminar Manager', 'This extension allows you to create and manage a list of seminars, workshops, lectures, theater performances and other events as an overview or as detailed descriptions. In addition, it allows front end users to register for these events.', 0, -1, 3, 1173184776, 'a:1:{s:7:"depends";a:5:{s:3:"cms";s:0:"";s:18:"css_styled_content";s:0:"";s:16:"frontendformslib";s:0:"";s:3:"php";s:11:"4.0.0-0.0.0";s:5:"typo3";s:11:"3.7.0-0.0.0";}}', 'Oliver Klee', 'typo3-coding@oliverklee.de', 'oliklee', 'abef99c99b1bd817ded97e4a26efab1f', 'This is a bug-fix release; no new features have been added. Made this extension work with TYPO3 3.7.0-4.1.x.', 'oliverklee.de', 4009, 0, 0),
(6127, 0, 'seminars', 1, '0.4.10', 10760, 565, 'Seminar Manager', 'This extension allows you to create and manage a list of seminars, workshops, lectures, theater performances and other events as an overview or as detailed descriptions. In addition, it allows front end users to register for these events.', 0, -1, 3, 1174575599, 'a:1:{s:7:"depends";a:5:{s:3:"cms";s:0:"";s:18:"css_styled_content";s:0:"";s:16:"frontendformslib";s:0:"";s:3:"php";s:11:"4.0.0-0.0.0";s:5:"typo3";s:11:"3.7.0-0.0.0";}}', 'Oliver Klee', 'typo3-coding@oliverklee.de', 'oliklee', '54c88a847bbfc5aac3382690047fd782', 'This is a bug-fix release without any big new features. Made the BE a lot faster. Made the BE sort order configurable.', 'oliverklee.de', 4010, 0, 0),
