(6179, 0, 'sf_books', 1, '1.7.0', 2761, 86, 'Book Library', 'Managing lots of books is not easy without a great tool. The book library tries to help you keeping an overview your books and to search easily information about each book.', 2, 0, 4, 1310848860, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"4.5.0-0.0.0";s:3:"php";s:11:"5.0.0-0.0.0";s:3:"cms";s:0:"";}}', 'Sebastian Fischer', 'typo3@evoweb.de', 'sfischer', 'f8c4aec955e55dc022ba9dd5cba1ea54', 'Add category filter to list, configurable inside typoscript and in flexform, where flexform overrides settings from typoscript.', '', 1007000, 0, 0),
(6180, 0, 'sf_books', 1, '1.7.1', 2761, 0, 'Book Library', 'Managing lots of books is not easy without a great tool. The book library tries to help you keeping an overview your books and to search easily information about each book.', 2, 0, 4, 1365407798, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:12:"4.5.0-4.7.99";s:3:"php";s:11:"5.0.0-0.0.0";s:3:"cms";s:0:"";}}', 'Sebastian Fischer', 'typo3@evoweb.de', 'sfischer', 'c25e8c8e9b6987412634b3251fb5ddf9', 'Fix TYPO3 version compatability\r\nMove to other extension manager category', '', 1007001, 0, 0),
(6181, 0, 'sf_books', 1, '3.0.0', 2761, 0, 'Book Library', 'Managing lots of books is not easy without a good tool.\nThe book library tries to help you keeping an overview your\nbooks and to search easily information about each book.', 2, 0, 3, 1428831482, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:13:"6.2.0-7.99.99";}}', 'Sebastian Fischer', 'typo3@evoweb.de', 'sfischer', '5ff32091adcf0dbcb1a6641b9b795cd2', 'Updated the extension for 6.2.0\r\n\r\nPlease be aware to controll if the plugins are displayed after upgrading as the plugin list_type were modify to match 6.2 schema.', 'evoWeb', 3000000, 0, 0),
