(6478, 0, 'simpl_faq', 1, '1.0.0', 574, 73, 'Simpl FAQ', 'Simple FAQ, with all the options available in flexforms (like tt_news), so no tricky configuration.', 0, -1, 3, 1125495614, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:3:"cms";s:0:"";}}', 'Peter Wechtersbach', 'wechta@gmail.com', 'wechta', 'b3397e7d09f011cc8c6fd9383b843594', '', '', 1000000, 0, 0),
(6479, 0, 'simpl_faq', 1, '1.0.1', 574, 37, 'Simpl FAQ', 'Simple FAQ, with all the options available in flexforms (like tt_news), so no tricky configuration.', 1, -1, 3, 1127291062, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"0.0.2-0.0.2";s:3:"php";s:11:"0.0.2-0.0.2";s:3:"cms";s:0:"";}}', 'Peter Wechtersbach', 'wechta@gmail.com', 'wechta', '461ba2acfff5bac759ecf99356a2a6d2', 'added:\r\n- option to show questions and answers on same page\r\n- option to link question or answer to single view\r\n- croping of category title, question and answer', '', 1000001, 0, 0),
(6480, 0, 'simpl_faq', 1, '1.0.2', 574, 121, 'Simpl FAQ', 'Simple FAQ, with all the options available in flexforms (like tt_news), so no tricky configuration.', 1, -1, 3, 1128422779, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"0.0.2-0.0.2";s:3:"php";s:11:"0.0.2-0.0.2";s:3:"cms";s:0:"";}}', 'Peter Wechtersbach', 'wechta@gmail.com', 'wechta', 'fde84608159a694426d4172f161006be', 'a little change for realurl ext.', '', 1000002, 0, 0),
(6481, 0, 'simpl_faq', 1, '1.1.0', 574, 343, 'Simpl FAQ', 'Simple FAQ, with all the options available in flexforms (like tt_news), so no tricky configuration.', 1, -1, 3, 1132771694, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"0.0.2-0.0.2";s:3:"php";s:11:"0.0.2-0.0.2";s:3:"cms";s:0:"";}}', 'Peter Wechtersbach', 'wechta@gmail.com', 'wechta', '0a0794d143a1bfe4f79e577898602785', '- added new functions: \r\n Show categories in tree on same page (CATEGORY LIST) \r\n Show categories and faqs on same page (CATEGORY LIST)\r\n\r\nbut still no docs, so just try new funct and what happens, its nice ;)', '', 1001000, 1, 0),
(6482, 0, 'simulatebe', 1, '1.0.0', 6773, 5711, 'BE-login simulation for fe-users', 'Simulates BE-login for FE-users. With this extension you can grant frontend users backend user rights. This means that if a frontend user logs into the frontend and she has the proper rights the edit icons will be displayed allowing her to edit the conten', 2, 0, 2, 1139393851, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:3:"cms";s:0:"";}}', 'Mads Brunn', 'brunn@mail.dk', 'sommer', '6b1a2ad0799099ed6f7170b62b5a7ca2', '', '', 1000000, 0, 0),
(6483, 0, 'simulatebe', 1, '2.0.0', 6773, 370, 'BE-login simulation for fe-users', 'Simulates BE-login for FE-users. With this extension you can grant frontend users backend user rights. This means that if a frontend user logs into the frontend and she has the proper rights the edit icons will be displayed allowing her to edit the conten', 2, 0, 2, 1277734441, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"3.5.0-0.0.0";s:3:"php";s:11:"3.0.0-0.0.0";s:3:"cms";s:0:"";}}', 'Sonja Scholz', 'ss@cabag.ch', 'sommer', 'be228a417987d8dd3f3dc45aa04f78b9', 'New release with several bug fixes. Works fine with T3 4.3.2 and older T3 versions. New feature: New field in be_user tx_simulatebe_feuserusername to write the name of the related fe_user. simulatebe looks for the be_user with the current fe_user username', 'cab services ag', 2000000, 0, 0),
(6484, 0, 'simulatebe', 1, '2.0.1', 6773, 692, 'BE Login Simulation for FE Users', 'Simulates BE Login for FE Users. With this extension you can grant Frontend Users Backend User Rights. This means that, if a Frontend User logs into the Frontend and he has the proper rights, the Edit Icons will be displayed allowing him to edit the Conte', 2, 0, 2, 1296807928, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"3.5.0-0.0.0";s:3:"php";s:11:"3.0.0-0.0.0";s:3:"cms";s:0:"";}}', 'Sonja Scholz', 'ss@cabag.ch', 'sommer', 'c35facc3a6f12ef223b8da16c5aa1562', 'Bugfix release, which works now in TYPO3 4.5. For details please read the changelog.', 'cab services ag', 2000001, 0, 0),
(6485, 0, 'simulatebe', 1, '2.1.3', 6773, 0, 'BE Login Simulation for FE Users', 'Simulates BE Login for FE Users. With this extension you can grant Frontend Users Backend User Rights. This means that, if a Frontend User logs into the Frontend and he has the proper rights, the Edit Icons will be displayed allowing him to edit the Content.', 2, 0, 2, 1377592386, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"3.5.0-0.0.0";s:3:"php";s:11:"3.0.0-0.0.0";s:3:"cms";s:0:"";}}', 'Sonja Scholz', 'ss@cabag.ch', 'sommer', '7bccc7bd7f05934d04aa54c6529e97d2', 'Fixed automated logout of backend user and session timeout.', 'cab services ag', 2001003, 0, 0),
(6486, 0, 'simulatebe', 1, '2.1.4', 6773, 0, 'BE Login Simulation for FE Users', 'Simulates BE Login for FE Users. With this extension you can grant Frontend Users Backend User Rights. This means that, if a Frontend User logs into the Frontend and he has the proper rights, the Edit Icons will be displayed allowing him to edit the Content.', 2, 0, 2, 1377690257, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:12:"4.5.0-6.1.99";s:3:"php";s:11:"5.3.0-0.0.0";s:3:"cms";s:0:"";}}', 'Sonja Scholz, Jonas Felix, Tizian Schmidlin', 'ss@cabag.ch, jf@cabag.ch, st@cabag.ch', 'sommer', '9235ec841a5a49ac17a96763e7a4c7ba', '[MAINTENANCE] added TYPO3 dependency to match 4.5.0-6.1.99\r\n[MAINTENANCE] added authors Jonas Felix and Tizian Schmidlin', 'cab services ag', 2001004, 0, 0),
(6487, 0, 'simulatebe', 1, '2.2.1', 6773, 0, 'BE Login Simulation for FE Users', 'Simulates BE Login for FE Users. With this extension you can grant Frontend Users Backend User Rights. This means that, if a Frontend User logs into the Frontend and he has the proper rights, the Edit Icons will be displayed allowing him to edit the Content.', 2, 0, 2, 1399021326, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:12:"4.5.0-6.2.99";s:3:"php";s:11:"5.3.0-0.0.0";s:3:"cms";s:0:"";}}', 'Sonja Scholz, Jonas Felix, Tizian Schmidlin', 'ss@cabag.ch, jf@cabag.ch, st@cabag.ch', 'sommer', '2b75b1abd48561ecbe3eef360b7be105', 'added 6.2 compatibility\r\nmerged different branches', 'cab services ag', 2002001, 0, 0),
(6488, 0, 'simulatebe', 1, '2.3.0', 6773, 0, 'BE Login Simulation for FE Users', 'Simulates BE Login for FE Users. With this extension you can grant Frontend Users Backend User Rights. This means that, if a Frontend User logs into the Frontend and he has the proper rights, the Edit Icons will be displayed allowing him to edit the Content.', 2, 0, 2, 1460111528, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:13:"6.2.0-7.99.99";s:3:"php";s:11:"5.3.0-0.0.0";s:3:"cms";s:0:"";}}', 'Sonja Scholz, Jonas Felix, Tizian Schmidlin', 'ss@cabag.ch, jf@cabag.ch, st@cabag.ch', 'sommer', '12f72dfc24967fa013785a1bd76c40bf', 'Now compatible with TYPO3 6.2-7.6\r\nIf you need compatibility with TYPO3  6.2, please use earlier versions.\r\nThanks to Christopher Stelmaszy', 'cab services ag', 2003000, 0, 0),
(6489, 0, 'simulatebe', 1, '2.3.1', 6773, 0, 'BE Login Simulation for FE Users', 'Simulates BE Login for FE Users. With this extension you can grant Frontend Users Backend User Rights. This means that, if a Frontend User logs into the Frontend and he has the proper rights, the Edit Icons will be displayed allowing him to edit the Content.', 2, 0, 2, 1460357356, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:13:"6.2.0-7.99.99";s:3:"php";s:11:"5.3.0-0.0.0";s:3:"cms";s:0:"";}}', 'Sonja Scholz, Jonas Felix, Tizian Schmidlin', 'ss@cabag.ch, jf@cabag.ch, st@cabag.ch', 'sommer', 'baa7ba2a2afbb41a78e71b9db65cacef', 'Fixed a typo', 'cab services ag', 2003001, 1, 0);
