(6518, 0, 'skin360', 1, '1.0.0', 8403, 332, 'Demo skin for TYPO3 3.6.0', 'TYPO3 3.6.0 is skinnable in a far more extensive way than previous versions. This extensions shows how far you can go. It works only in Mozilla and Opera since PNGs with transparency is used (in MSIE it works but looks strange...)', 2, 0, 4, 1072555704, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";}}', 'Kasper Skrhj', 'kasper@typo3.com', 'kasper', 'd78ca11c1c1b67f7b673b051bb2dbab3', '', '', 1000000, 0, 0),
