(6520, 0, 'skincrystal', 1, '0.4.0', 8798, 3926, 'Crystal skin for TYPO3 3.6.0', 'This skin for TYPO 3.6.x uses the Crystal SVG 1.0 icons. (C) 2004 Copyright by Everaldo (http://www.everaldo.com)\nHe permitted me to use his icons in this skin. It is based on the skin360 from Kasper and isnt complete yet.\nFor having transparent Icons yo', 1, 1, 4, 1128740787, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:11:"0.0.3-0.0.3";s:3:"php";s:11:"0.0.3-0.0.3";}}', 'Felix Rommel', 'mail@felixrommel.de', 'felixr', '11a0e9fe361ee749ef8b9dec2049b42c', '', '', 4000, 1, 0),
