(6688, 0, 'so_gsearch', 1, '0.0.2', 523, 523, 'Simple Google Search', 'This extension adds a very simple Google search to your site. Type in your search string, select search mode (web or images) and hit the submit button. The results are shown in Google itself.', 1, 0, 3, 1115459302, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:3:"cms";s:0:"";}}', 'Onno Schuit', 'o.schuit@solin.nl', 'onnoschuit', '9e1728e18e851e39680a7219abd538d5', 'Added options to switch between searching Web and Images', '', 2, 1, 0),
(6689, 0, 'so_jpspan', 1, '0.0.1', 1656, 24, 'JPSpan', 'This extension just includes a current version of JPSpan, which provides tools to hook up PHP and Javascript, for the purpose of fetching data from PHP into a web page which has already loaded, without reloading the entire page (from: http://jpspan.', 0, 0, 0, 1118346370, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:3:"cms";s:0:"";}}', 'Onno Schuit', 'o.schuit@solin.nl', 'onnoschuit', '0ec3f1f95edf496be4f821e24e8777c1', '', '', 1, 0, 0),
