(6810, 0, 'sr_feuser_register', 1, '2.5.4', 101151, 1129, 'Frontend User Registration', 'A front end user self-registration variant of Kasper Skrhjs Front End User Admin extension.', 2, -1, 3, 1167391005, 'a:1:{s:7:"depends";a:4:{s:3:"cms";s:0:"";s:18:"static_info_tables";s:6:"2.0.0-";s:3:"php";s:6:"4.1.0-";s:5:"typo3";s:4:"4.0-";}}', 'Stanislas Rolland, Franz Holzinger', 'kontakt@fholzinger.com', 'stan', '8d7d60950466914e2e6a153dce2a1854', 'split pi1/locallang.xml into separate files for each language in l10n/pi1 to decrease the needed memory amount for each FE user.\nGet the texts for different languages by the Extension Manager Translation handling or download them manually form here http', 'Freelancer', 2005004, 0, 0),
(6811, 0, 'sr_feuser_register', 1, '2.5.5', 101151, 2932, 'Frontend User Registration', 'A front end user self-registration variant of Kasper Skrhjs Front End User Admin extension.', 2, -1, 3, 1171050218, 'a:1:{s:7:"depends";a:4:{s:3:"cms";s:0:"";s:18:"static_info_tables";s:6:"2.0.0-";s:3:"php";s:11:"4.1.0-0.0.0";s:5:"typo3";s:9:"4.0-0.0.0";}}', 'Stanislas Rolland, Franz Holzinger', 'kontakt@fholzinger.com', 'stan', '8d16647f97b36cc4514bc9e862f6dcdb', 'enable overrideValues setup with stdWrap function call - automatic password generation - captcha feature', 'Freelancer', 2005005, 0, 0),
(6812, 0, 'sr_feuser_register', 1, '2.5.6', 101151, 4402, 'Frontend User Registration', 'A front end user self-registration variant of Kasper Skrhjs Front End User Admin extension.', 1, -1, 3, 1186866107, 'a:1:{s:7:"depends";a:4:{s:3:"cms";s:0:"";s:18:"static_info_tables";s:6:"2.0.0-";s:3:"php";s:11:"4.1.0-0.0.0";s:5:"typo3";s:9:"4.0-0.0.0";}}', 'Stanislas Rolland, Franz Holzinger', 'kontakt@fholzinger.com', 'stan', 'bd29c4aa5ccb6f270bb78c2e01c79e93', 'use t3lib_htmlmail also for sending of plain text emails fix bugs with invite (see bug 5588 - a change in TYPO3 Core is needed) fix bug for hooks', 'Freelancer', 2005006, 0, 0),
(6813, 0, 'sr_feuser_register', 1, '2.5.7', 101151, 6548, 'Frontend User Registration', 'A front end user self-registration variant of Kasper Skrhjs Front End User Admin extension.', 1, -1, 3, 1189188308, 'a:1:{s:7:"depends";a:5:{s:3:"cms";s:0:"";s:10:"fh_library";s:6:"0.0.4-";s:18:"static_info_tables";s:6:"2.0.0-";s:3:"php";s:11:"4.1.0-0.0.0";s:5:"typo3";s:9:"4.0-0.0.0";}}', 'Stanislas Rolland / Franz Holzinger', 'kontakt@fholzinger.com', 'stan', 'db945b164a68d21d9952eb1aacab9a55', 'This works with sr_email_subscribe 1.2.0 Fix bugs with setfixed issues and saving of Direct Mail categories upon creation. renderCharset is partly used.', 'Freelancer', 2005007, 0, 0),
