(6994, 0, 'ss_dragdrop', 1, '0.0.1', 5216, 14, 'Pages Dragn Drop', 'Allows the backend user to move pages in the treeview through a simple drag and drop mouse action', 1, 0, 0, 1117590334, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";}}', 'Stephane Schitter', 'stephane@frozenkiwi.net', 'shelob', '6d1387c999040e0d813ce7b29019b21d', 'Initial Revision', '', 1, 0, 0),
(6995, 0, 'ss_dragdrop', 1, '0.1.0', 5216, 134, 'Pages Dragn Drop', 'Allows the backend user to move pages in the treeview through a simple drag and drop mouse action', 1, 0, 0, 1117635954, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";}}', 'Stephane Schitter', 'stephane@frozenkiwi.net', 'shelob', '93ff3c74e2c06f453cb56a19522048ff', 'Corrected a minor bug, bumbed version to the initial sub version level.', '', 1000, 0, 0),
(6996, 0, 'ss_dragdrop', 1, '0.2.0', 5216, 17, 'Pages Dragn Drop', 'Allows the backend user to move pages in the treeview through a simple drag and drop mouse action', 1, 0, 0, 1117759452, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:11:"0.0.2-0.0.2";s:3:"php";s:11:"0.0.2-0.0.2";}}', 'Stephane Schitter', 'stephane@frozenkiwi.net', 'shelob', '031594a91b2dc1452314b0591695ca08', 'Made the extension work with Internet Explorer, through a small update to the javascript code driving the drag & drop.', '', 2000, 0, 0),
(6997, 0, 'ss_dragdrop', 1, '0.3.0', 5216, 266, 'Pages Dragn Drop', 'Allows the backend user to move pages in the treeview through a simple drag and drop mouse action', 1, 0, 0, 1117760042, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:11:"0.0.2-0.0.2";s:3:"php";s:11:"0.0.2-0.0.2";}}', 'Stephane Schitter', 'stephane@frozenkiwi.net', 'shelob', '6400ef2c4a6da3c76a3b8c043b753727', 'Fixed a small issue where the pagetree would load twice, and therefore be somewhat more annoying to use.', '', 3000, 0, 0),
(6998, 0, 'ss_dragdrop', 1, '0.4.0', 5216, 104, 'Pages Dragn Drop', 'Allows the backend user to move pages in the treeview through a simple drag and drop mouse action', 1, 0, 0, 1119364386, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:11:"0.0.2-0.0.2";s:3:"php";s:11:"0.0.2-0.0.2";}}', 'Stephane Schitter', 'stephane@frozenkiwi.net', 'shelob', '7778c2cab03347ff476b400cef5d21c3', 'Added a menu to allow the users to choose the action to perform on a drop action. It is still possible to bypass the menu if the user prefers to have the previous behaviour. This is now configurable via Extension Manager settings or through User TSConfig.', '', 4000, 0, 0),
(6999, 0, 'ss_dragdrop', 1, '0.5.0', 5216, 46, 'Pages Dragn Drop', 'Allows the backend user to move pages in the treeview through a simple drag and drop mouse action', 1, 0, 0, 1119388110, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:11:"0.0.2-0.0.2";s:3:"php";s:11:"0.0.2-0.0.2";}}', 'Stephane Schitter', 'stephane@frozenkiwi.net', 'shelob', 'a7f4208684aaed02a3226982bfe1ddcb', 'Added visual feedback to indicate a drag and drop action is taking place. This is done through a small page icon following the mouse movement.', '', 5000, 0, 0),
(7000, 0, 'ss_dragdrop', 1, '0.6.0', 5216, 1900, 'Pages Dragn Drop', 'Allows the backend user to move pages in the treeview through a simple drag and drop mouse action', 1, 0, 0, 1136126924, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:11:"0.0.2-0.0.2";s:3:"php";s:11:"0.0.2-0.0.2";}}', 'Stephane Schitter', 'stephane@frozenkiwi.net', 'shelob', 'c12d5bd1fb3da5a5b6c333823c234464', 'Allow the dragged icon to match the icon of the page being moved (ie. for example the sysfolder icon, or hidden page icon, etc...) for increased visual feedback on the drag/drop action.', '', 6000, 0, 0),
(7001, 0, 'ss_dragdrop', 1, '0.6.1', 5216, 20, 'Pages Dragn Drop', 'Allows the backend user to move pages in the treeview through a simple drag and drop mouse action', 1, 0, 0, 1136126924, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:11:"0.0.2-0.0.2";s:3:"php";s:11:"0.0.2-0.0.2";}}', 'Stephane Schitter', 'stephane@frozenkiwi.net', 'shelob', '166f785c940cc13a66979fd1e627ebca', '', '', 6001, 0, 0),
(7002, 0, 'ss_dragdrop', 1, '0.7.0', 5216, 19, 'Pages Dragn Drop', 'Allows the backend user to move pages in the treeview through a simple drag and drop mouse action', 1, 0, 0, 1136148103, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:11:"0.0.3-0.0.3";s:3:"php";s:11:"0.0.3-0.0.3";}}', 'Stephane Schitter', 'stephane@frozenkiwi.net', 'shelob', '6a4181402827d80951aa567edf682399', 'Made the extension compatible with the new AJAX mode in Typo3 4.0-dev. Corrected small bugs. Small enhancement: When using the NON-MENU mode, the user can copy an entry (instead of moving it) by pressing the CTRL button at the same time he drags the mouse', '', 7000, 0, 0),
(7003, 0, 'ss_dragdrop', 1, '0.8.0', 5216, 81, 'Pages Dragn Drop', 'Allows the backend user to move pages in the treeview through a simple drag and drop mouse action', 1, 0, 0, 1136153048, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:11:"0.0.3-0.0.3";s:3:"php";s:11:"0.0.3-0.0.3";}}', 'Stephane Schitter', 'stephane@frozenkiwi.net', 'shelob', 'd426518cfa29a19d9362328bd4e5e2b2', 'Behave as a good citizen when the user does not want (or browser cannot provide) popup menus.', '', 8000, 0, 0);
INSERT INTO `tx_extensionmanager_domain_model_extension` (`uid`, `pid`, `extension_key`, `repository`, `version`, `alldownloadcounter`, `downloadcounter`, `title`, `description`, `state`, `review_state`, `category`, `last_updated`, `serialized_dependencies`, `author_name`, `author_email`, `ownerusername`, `md5hash`, `update_comment`, `authorcompany`, `integer_version`, `current_version`, `lastreviewedversion`) VALUES
(7004, 0, 'ss_dragdrop', 1, '0.9.0', 5216, 2585, 'Pages Dragn Drop', 'Allows the backend user to move pages in the treeview through a simple drag and drop mouse action', 2, 0, 0, 1137162744, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:11:"0.0.4-0.0.4";s:3:"php";s:11:"0.0.4-0.0.4";}}', 'Stephane Schitter', 'stephane@frozenkiwi.net', 'shelob', '178fdfb6e12ecb546c5af6b0d50c4bf7', 'Added a similar drag/drop functionality to the Filelist. Now directories can also be moved/copies through a mouse drag. If you disabled the display of the popup menu, be sure to try out pressing the CTRL key while you move the mouse...', '', 9000, 1, 0),
(7005, 0, 'ss_ldappasswd', 1, '0.0.1', 643, 23, 'LDAP Password Changer', 'Allows the insertion of a password modification box to the site. Will work well to allow a FE logged in user to change his own password through an LDAP query', 1, 0, 3, 1137162578, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:3:"cms";s:0:"";}}', 'Stephane Schitter', 'stephane@frozenkiwi.net', 'shelob', '285bd97b66e193439e9b85e58fc0fe01', 'Initial revision. Missing documentation at this time. Configure the extension through the template file (pi1/default.tmpl) and through Typoscript commands (see ext_typoscript_constants.txt)', '', 1, 0, 0),
(7006, 0, 'ss_ldappasswd', 1, '0.1.0', 643, 12, 'LDAP Password Changer', 'Allows the insertion of a password modification box to the site. Will work well to allow a FE logged in user to change his own password through an LDAP query', 1, 0, 3, 1137279629, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"0.0.2-0.0.2";s:3:"php";s:11:"0.0.2-0.0.2";s:3:"cms";s:0:"";}}', 'Stephane Schitter', 'stephane@frozenkiwi.net', 'shelob', '0f14efca802e588a0df09f548c6a9e22', 'Corrected a minor bug. First publicly released version. Documentation still needs to be done.', '', 1000, 0, 0),
(7007, 0, 'ss_ldappasswd', 1, '0.2.0', 643, 149, 'LDAP Password Changer', 'Allows the insertion of a password modification box to the site. Will work well to allow a FE logged in user to change his own password through an LDAP query', 1, 0, 3, 1137342251, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"0.0.2-0.0.2";s:3:"php";s:11:"0.0.2-0.0.2";s:3:"cms";s:0:"";}}', 'Stephane Schitter', 'stephane@frozenkiwi.net', 'shelob', '42b8987be5b54ab01b569ba47dfdf645', 'Documentation created.', '', 2000, 0, 0),
(7008, 0, 'ss_ldappasswd', 1, '0.3.0', 643, 263, 'LDAP Password Changer', 'Allows the insertion of a password modification box to the site. Will work well to allow a FE logged in user to change his own password through an LDAP query', 2, 0, 3, 1167166170, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:3:"php";s:6:"3.0.0-";s:5:"typo3";s:6:"3.5.0-";}}', 'Stephane Schitter', 'stephane@frozenkiwi.net', 'shelob', '46975b8e7c726a03ddc0c261960e146a', 'Improvements kindly provided by Thomas Meyer including the added possibility to set ldap server version, enabling SAMBA password to be modified as well, german localisation, javascript alert bug fixed.', '', 3000, 0, 0),
