(7215, 0, 'sys_workflows', 1, '1.0.4', 13434, 1488, 'UserTask Center, Tasks, Workflow', 'Workflow system based upon the To-Do list. It allows a straight line workflow with redirects, groups, reviewers and an editor for finalizing.', 2, 0, 1, 1072117648, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:9:"sys_todos";s:0:"";}}', 'Kasper Skrhj', 'kasper@typo3.com', 'just2b', '169b32a38945b5334e3c6781dac9615d', '', 'Curby Soft Multimedia', 1000004, 0, 0),
