(7296, 0, 'table', 1, '0.5.1', 21739, 0, 'Table Library', 'This containts a base class which you can use to make your extensions independant from any specific table. And it can be used to make multiple language support with a separate language overlay table.', 2, 0, 4, 1462888611, 'a:1:{s:7:"depends";a:3:{s:3:"php";s:12:"5.3.0-7.7.99";s:5:"typo3";s:12:"4.5.0-7.9.99";s:7:"div2007";s:11:"1.1.5-0.0.0";}}', 'Franz Holzinger', 'franz@ttproducts.de', 'franzholz', '79b33dc7dc2b970cbf236041a1f6d676', ' \nReady for PHP 7. pid_list  -1 is supported with tt_products 2.12.0. This enables the products of all pages.\n', 'jambage.com', 5001, 0, 0),
