(7299, 0, 'table', 1, '0.6.2', 21739, 0, 'Table Library', 'This containts a base class which you can use to make your extensions independant from any specific table. And it can be used to make multiple language support with a separate language overlay table.', 2, 0, 4, 1492167111, 'a:1:{s:7:"depends";a:3:{s:3:"php";s:13:"5.3.0-7.99.99";s:5:"typo3";s:13:"4.5.0-8.99.99";s:7:"div2007";s:11:"1.1.5-0.0.0";}}', 'Franz Holzinger', 'franz@ttproducts.de', 'franzholz', 'fa80ebc172ff0d1ff8304793aa1cf79c', '\nbugfix in composer.json\n', 'jambage.com', 6002, 1, 0),
(7300, 0, 'tableswithoutp', 1, '0.5.0', 1869, 1425, 'Content tables without P', 'This extension removes the P tag that by default encloses table cells.\r\nThis extension is intended to be used together with CSS_styled_content.', 1, 0, 2, 1128528518, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:18:"css_styled_content";s:0:"";}}', 'Oliver Klee', 'typo3-coding@oliverklee.de', 'oliklee', 'e0207cc08abfec1e71dd1aecccdf9cf7', 'Made it so that removing the P tags affects only single-line table cells. Now P tags with white space around them are removed, too.', 'AStA Bonn', 5000, 0, 0),
(7301, 0, 'tableswithoutp', 1, '1.0.0', 1869, 210, 'Content tables without P', 'This extension removes the P tag that by default encloses table cells.\nThis extension is intended to be used together with CSS_styled_content.', 5, 0, 2, 1183627566, 'a:2:{s:7:"depends";a:2:{s:3:"cms";s:0:"";s:5:"typo3";s:11:"3.5.0-3.9.9";}s:9:"conflicts";a:1:{s:5:"typo3";s:11:"4.0.0-0.0.0";}}', 'Oliver Klee', 'typo3-coding@oliverklee.de', 'oliklee', 'eff33a17459bd3b6603509c4dd753230', 'This extension now is obsolete as TYPO3 4.0 no longer uses paragraphs in tables.', 'oliverklee.de', 1000000, 1, 0),
