(7320, 0, 'tcdirectmail', 1, '0.4.0', 7011, 97, 'TypoConsult Directmail', 'Directmail extension with simple to setup and use mailer, and a very extensible recipient configuration.', 1, -1, 4, 1144376481, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:6:"4.4.0-";s:5:"typo3";s:6:"3.8.0-";}}', 'Daniel Schledermann', 'daniel@typoconsult.dk', 'daniel_schledermann', 'fd1f7f4be736df7a3821be15fb15cda8', '- Now linkclick-stats.\n- Fixed logging.\n- Clean-function for logdata.', 'TypoConsult A/S', 4000, 0, 0),
(7321, 0, 'tcdirectmail', 1, '1.0.0', 7011, 36, 'TC Directmail', 'Directmail extension with simple to setup and use mailer, and a very extensible recipient configuration.', 1, -1, 4, 1148844048, 'a:1:{s:7:"depends";a:3:{s:10:"tt_address";s:0:"";s:3:"php";s:6:"4.4.0-";s:5:"typo3";s:6:"3.8.0-";}}', 'Daniel Schledermann', 'daniel@typoconsult.dk', 'daniel_schledermann', '900595e1b7e3ba4c621ecfb9f001d94d', '- Major change in the receiver config with new OO-interface for creating new receiver-types. Please consult manual before upgrading.\n- Several bug fixes.\n- Addition of some german LLL.\n- New config possibilities on headers, path to php and lynx, sender ad', 'TypoConsult A/S', 1000000, 0, 0),
(7322, 0, 'tcdirectmail', 1, '1.0.1', 7011, 239, 'TC Directmail', 'Directmail extension with simple to setup and use mailer, and a very extensible recipient configuration.', 1, -1, 4, 1148895474, 'a:1:{s:7:"depends";a:3:{s:10:"tt_address";s:0:"";s:3:"php";s:6:"4.4.0-";s:5:"typo3";s:6:"3.8.0-";}}', 'Daniel Schledermann', 'daniel@typoconsult.dk', 'daniel_schledermann', '9e8d742d1ff340521bc50327c7f266e3', '- Disable 5. parameter in mail() if not in use.', 'TypoConsult A/S', 1000001, 0, 0),
(7323, 0, 'tcdirectmail', 1, '1.0.2', 7011, 220, 'TC Directmail', 'Directmail extension with simple to setup and use mailer, and a very extensible recipient configuration.', 1, -1, 4, 1149244209, 'a:1:{s:7:"depends";a:3:{s:10:"tt_address";s:0:"";s:3:"php";s:6:"4.4.0-";s:5:"typo3";s:6:"3.8.0-";}}', 'Daniel Schledermann', 'daniel@typoconsult.dk', 'daniel_schledermann', '1f90ec80654f4cd7c35925dce3ca0ecf', '- Systemstatus part moved to own module. Its more gentle on systems with php as cgi.\n- Plain text encoding now qouted printable\n- It is now possible to use multiple receivergroups for real receivers.', 'TypoConsult A/S', 1000002, 0, 0),
(7324, 0, 'tcdirectmail', 1, '1.1.0', 7011, 373, 'TC Directmail', 'Directmail extension with simple to setup and use mailer, and a very extensible recipient configuration.', 1, -1, 4, 1153620051, 'a:1:{s:7:"depends";a:3:{s:10:"tt_address";s:0:"";s:3:"php";s:6:"4.4.0-";s:5:"typo3";s:6:"3.8.0-";}}', 'Daniel Schledermann', 'daniel@typoconsult.dk', 'daniel_schledermann', 'e84bb653fd4aff563f102e40e1b52ae0', '- Statistics moved to separate extension.\n- Qouted printable encoding now via buildin function imap_8bit, if available.\n- Several small bug fixes.\n- LLL-files now in XML. Please provide translations in XML from now.', 'TypoConsult A/S', 1001000, 0, 0),
(7325, 0, 'tcdirectmail', 1, '1.1.1', 7011, 434, 'TC Directmail', 'Directmail extension with simple to setup and use mailer, and a very extensible recipient configuration.', 2, -1, 4, 1154561687, 'a:1:{s:7:"depends";a:3:{s:10:"tt_address";s:0:"";s:3:"php";s:6:"4.3.9-";s:5:"typo3";s:6:"3.8.0-";}}', 'Daniel Schledermann', 'daniel@typoconsult.dk', 'daniel_schledermann', 'a2f8abfa52e8665739f6a5ee8f7d9951', ' Some bugfixes.\n Charset aware now.\n Record count for less than 30 receivers.\n Ability to use from TYPO3 installed under subdirectory.\n Declared stable', 'TypoConsult A/S', 1001001, 0, 0),
(7326, 0, 'tcdirectmail', 1, '1.1.2', 7011, 291, 'TC Directmail', 'Directmail extension with simple to setup and use mailer, and a very extensible recipient configuration.', 2, -1, 4, 1157986261, 'a:1:{s:7:"depends";a:3:{s:10:"tt_address";s:0:"";s:3:"php";s:6:"4.3.9-";s:5:"typo3";s:6:"3.8.0-";}}', 'Daniel Schledermann', 'daniel@typoconsult.dk', 'daniel_schledermann', '9c8e53667d1ecf49c572e06f1bc94826', 'Lots af small bugfixes:\n- Improved performance i field replacer part.\n- Fixes for links with parameters\n- Two hooks have been added. One in creation of the mailer, and one before sending the mail.', 'TypoConsult A/S', 1001002, 0, 0),
(7327, 0, 'tcdirectmail', 1, '1.1.3', 7011, 519, 'TC Directmail', 'Directmail extension with simple to setup and use mailer, and a very extensible recipient configuration.', 2, -1, 4, 1160477748, 'a:1:{s:7:"depends";a:3:{s:10:"tt_address";s:0:"";s:3:"php";s:6:"4.3.9-";s:5:"typo3";s:6:"3.8.0-";}}', 'Daniel Schledermann', 'daniel@typoconsult.dk', 'daniel_schledermann', '1d7633054df657645e10c48cbd554b8e', '- New fields in the standard records types. authCode and tableName\n- Some minor bug fixes.\n- System module should no longer hang on windows.\n- New "smart" include system.\n- Ability to use tcdm-api from frontend, if the includesystem is used.', 'TypoConsult A/S', 1001003, 0, 0),
(7328, 0, 'tcdirectmail', 1, '1.2.0', 7011, 230, 'TC Directmail', 'Directmail extension with simple to setup and use mailer, and a very extensible recipient configuration.', 2, -1, 1, 1168643725, 'a:1:{s:7:"depends";a:3:{s:10:"tt_address";s:0:"";s:3:"php";s:6:"4.3.9-";s:5:"typo3";s:6:"3.8.0-";}}', 'Daniel Schledermann', 'daniel@typoconsult.dk', 'daniel_schledermann', '3944469a6b37fc5e9447d5e9d0824a0b', 'Bounce handler added.\nStats and preview functions included.\nKickstarter support included.\nNote to upgrades: database layout has changed.', 'TypoConsult A/S', 1002000, 0, 0),
(7329, 0, 'tcdirectmail', 1, '1.2.1', 7011, 1922, 'TC Directmail', 'Directmail extension with simple to setup and use mailer, and a very extensible recipient configuration.', 2, -1, 1, 1170520638, 'a:1:{s:7:"depends";a:3:{s:10:"tt_address";s:0:"";s:3:"php";s:6:"4.3.9-";s:5:"typo3";s:6:"3.8.0-";}}', 'Daniel Schledermann', 'daniel@typoconsult.dk', 'daniel_schledermann', 'a28b8c524bb4d769fb450a74ec2ff1f3', 'One bugfix. \nMIME boundary sometimes fails to be generated correctly. This can lead to corrupted mails. If you are using 1.2.0 please upgrade ASAP.', 'TypoConsult A/S', 1002001, 0, 0),
(7330, 0, 'tcdirectmail', 1, '2.0.0', 7011, 145, 'TC Directmail', 'Directmail extension with simple to setup and use mailer, and a very extensible recipient configuration.', 2, -1, 1, 1219704125, 'a:1:{s:7:"depends";a:3:{s:10:"tt_address";s:0:"";s:3:"php";s:11:"4.3.9-0.0.0";s:5:"typo3";s:11:"3.8.0-0.0.0";}}', 'Daniel Schledermann', 'daniel@schledermann.net', 'daniel_schledermann', '75d0cd1946bf41861729fc1c854f0df2', 'Lot of bugfixes.\n- An entirely new spoolsystem\n- Better conformance to TYPO3 coding standards,\n- Better conformance to mime/multipart.\n- Better charset handling.\n- Better detection of mime-types for attached files.\n- Improved user interface in backend.', 'Casalogic A/S', 2000000, 0, 0),
(7331, 0, 'tcdirectmail', 1, '2.0.1', 7011, 104, 'TC Directmail', 'Directmail extension with simple to setup and use mailer, and a very extensible recipient configuration.', 2, -1, 1, 1221510359, 'a:1:{s:7:"depends";a:3:{s:10:"tt_address";s:0:"";s:3:"php";s:11:"5.2.1-0.0.0";s:5:"typo3";s:11:"4.0.0-0.0.0";}}', 'Daniel Schledermann', 'info@tcdirectmail.dk', 'daniel_schledermann', '086343c0cd64b01a98135244f06b22c4', '- Improved rendering in gmail and hotmail\n- Fixed error in beenthere.php', 'Casalogic A/S', 2000001, 0, 0),
(7332, 0, 'tcdirectmail', 1, '2.0.2', 7011, 945, 'TC Directmail', 'Directmail extension with simple to setup and use mailer, and a very extensible recipient configuration.', 2, -1, 1, 1222805771, 'a:1:{s:7:"depends";a:3:{s:10:"tt_address";s:0:"";s:3:"php";s:11:"5.0.0-0.0.0";s:5:"typo3";s:11:"4.0.0-0.0.0";}}', 'Daniel Schledermann', 'info@tcdirectmail.dk', 'daniel_schledermann', '28936a71ec2387304f97083f2ceb5a5b', 'Corrected more display bugs. Now possible to select base64 or qoutedprint in html content.', 'Casalogic A/S', 2000002, 0, 0),
(7333, 0, 'tcdirectmail', 1, '3.0.0', 7011, 0, 'TC Directmail', 'Directmail extension with simple to setup and use mailer, and a very extensible recipient configuration.', 2, -1, 1, 1408546595, 'a:2:{s:7:"depends";a:2:{s:3:"php";s:12:"5.2.0-5.5.99";s:5:"typo3";s:12:"4.5.0-6.2.99";}s:8:"suggests";a:1:{s:9:"scheduler";s:6:"0.0.0-";}}', 'Daniel Schledermann, Jose Antonio Guerra', 'typo3@ds.schledermann.net', 'daniel_schledermann', 'a109b72bb396c592a70a25d8a6e0032d', 'First release in since 2008. This release contains a number of fixes to make it compatible with TYPO3 4.5 - 6.2. It also has greater compliance to TYPO3 APIs and integration with scheduler. Databaselayout is mostly unchanged.', 'Linkfactory A/S', 3000000, 0, 0),
