INSERT INTO `tx_extensionmanager_domain_model_extension` (`uid`, `pid`, `extension_key`, `repository`, `version`, `alldownloadcounter`, `downloadcounter`, `title`, `description`, `state`, `review_state`, `category`, `last_updated`, `serialized_dependencies`, `author_name`, `author_email`, `ownerusername`, `md5hash`, `update_comment`, `authorcompany`, `integer_version`, `current_version`, `lastreviewedversion`) VALUES
(7477, 0, 'th_mailformplus', 1, '3.4.0', 49181, 378, 'MailformPlus', 'advanced form-mailer (html template based forms)', 2, -1, 3, 1109694362, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"0.0.4-0.0.4";s:3:"php";s:11:"0.0.4-0.0.4";s:3:"cms";s:0:"";}}', 'Peter Luser', 'netdog@typoheads.com', 'typoheads', '4a68efb66058ab745e725cb3968a5db9', 'TypoScript: additional email header, fields that should NOT be saved into the log-table can be specified, dynamic inputfields can be defined in TS and are beeing replaced in the HTML-template; other updates: backend module: raw export added and th', '', 3004000, 0, 0),
(7478, 0, 'th_mailformplus', 1, '3.5.0', 49181, 1996, 'MailformPlus', 'advanced form-mailer (html template based forms)', 2, -1, 3, 1110571449, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"0.0.5-0.0.5";s:3:"php";s:11:"0.0.5-0.0.5";s:3:"cms";s:0:"";}}', 'Peter Luser', 'netdog@typoheads.com', 'typoheads', '94890e1fd1a61458a8546d17082d3763', '- default values for mailformplus element can be defined via TypoScript (setup);  - backendmodule: exported records are marked and not shown anymore in the list  easy selection of pages', '', 3005000, 0, 0),
(7479, 0, 'th_mailformplus', 1, '3.6.0', 49181, 72, 'MailformPlus', 'advanced form-mailer (html template based forms)', 2, -1, 3, 1118870845, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"0.0.6-0.0.6";s:3:"php";s:11:"0.0.6-0.0.6";s:3:"cms";s:0:"";}}', 'Peter Luser', 'netdog@typoheads.com', 'typoheads', '259be1341d8a765630bef5ba7c223565', 'tested with TYPO3 v. 3.8, bugfix: saving fields in DB and uploading files, TS: possibility to send additional email parameters, debug functionality (only for advanced users) fileupload: markers in emails show the link to the picture(s) (clickable), docume', '', 3006000, 0, 0),
(7480, 0, 'th_mailformplus', 1, '3.6.1', 49181, 2898, 'MailformPlus', 'advanced form-mailer (html template based forms)', 2, -1, 3, 1118904290, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"0.0.6-0.0.6";s:3:"php";s:11:"0.0.6-0.0.6";s:3:"cms";s:0:"";}}', 'Peter Luser', 'netdog@typoheads.com', 'typoheads', '4a1fa77db1b928d965dd04b50e1582a6', 'tested with TYPO3 v. 3.8, 100% compatible to older versions of TYPO3 and this extension, bugfix: saving fields in DB and uploading files, TS: possibility to send additional email parameters, debug functionality (only for advanced users) fileupload: marker', '', 3006001, 0, 0),
(7481, 0, 'th_mailformplus', 1, '3.7.0', 49181, 4685, 'MailformPlus', 'advanced form-mailer (html template based forms)', 2, -1, 3, 1129710420, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"0.0.6-0.0.6";s:3:"php";s:11:"0.0.6-0.0.6";s:3:"cms";s:0:"";}}', 'Peter Luser', 'netdog@typoheads.com', 'typoheads', 'ddfef19669270c07dd06037f2018b184', 'mail injection prevention, captcha support (ext: captcha), hook for post-processing, bugfixes (realurl, backend module date/time,...)', '', 3007000, 0, 0),
(7482, 0, 'th_mailformplus', 1, '3.8.0', 49181, 3756, 'MailformPlus', 'advanced form-mailer (html template based forms)', 2, -1, 3, 1145654293, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:3:"php";s:6:"3.0.0-";s:5:"typo3";s:6:"3.5.0-";}}', 'Peter Luser', 'netdog@typoheads.com', 'typoheads', '83ad45a60e39d80fada634b7670176f1', '- TYPO3 4.0 compatible\n- reference to template file possible\n- example form in "example_form/" dir\n- bugfix: log-table\n- bugfix: save_mode mail() 5th parameter\n- bugfix: PHP 4.4.2 header()\n- bugfix: export csv: fielddescriptions', '', 3008000, 0, 0),
(7483, 0, 'th_mailformplus', 1, '3.9.0', 49181, 4184, 'MailformPlus', 'advanced form-mailer (html template based forms)', 2, -1, 3, 1164214178, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:6:"3.0.0-";s:5:"typo3";s:6:"3.5.0-";}}', 'Peter Luser', 'netdog@typoheads.com', 'typoheads', '7e368ae8fdc4ed29386ec9de052fd157', 'multipage forms, server side error checks, HTML AND Plaintextmails, advanced file upload functionality, "print" template', '', 3009000, 0, 0),
(7484, 0, 'th_mailformplus', 1, '4.0.0', 49181, 2308, 'MailformPlus', 'advanced form-mailer (html template based forms)', 2, -1, 3, 1179337366, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"3.0.0-0.0.0";s:5:"typo3";s:11:"3.5.0-0.0.0";}}', 'Dev-Team Typoheads', 'dev@typoheads.at', 'typoheads', 'c38f50891bf53e1bc4ac0bba398bbc11', 'multilanguage support trough flexforms, spam protection, many new features (thx for your help/input everybody!) - see documentation for details', '', 4000000, 0, 0),
(7485, 0, 'th_mailformplus', 1, '4.0.2', 49181, 37, 'MailformPlus', 'advanced form-mailer (html template based forms)', 1, -1, 3, 1185539916, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"3.0.0-0.0.0";s:5:"typo3";s:11:"3.5.0-0.0.0";}}', 'Dev-Team Typoheads', 'dev@typoheads.at', 'typoheads', '43e739ed428f8a096dcb58cd713b9124', 'New Feature for fe listing of submitted data, new options for logging, some bugfixes (thx for the reports!)', '', 4000002, 0, 0),
(7486, 0, 'th_mailformplus', 1, '4.0.3', 49181, 4974, 'MailformPlus', 'advanced form-mailer (html template based forms)', 1, -1, 3, 1202746000, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"3.0.0-0.0.0";s:5:"typo3";s:11:"3.5.0-0.0.0";}}', 'Dev-Team Typoheads', 'dev@typoheads.at', 'typoheads', 'c14c9e5e7ca4326fe2b64e42aaed8b68', 'several bugfixes:linebreaks in HTML emails, realurl, errorUserFunc; hook for filling custom markers, security fixes (protection against XSS)', '', 4000003, 0, 0),
(7487, 0, 'th_mailformplus', 1, '4.0.4', 49181, 558, 'MailformPlus', 'advanced form-mailer (html template based forms)', 1, -1, 3, 1202746688, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"3.0.0-0.0.0";s:5:"typo3";s:11:"3.5.0-0.0.0";}}', 'Dev-Team Typoheads', 'dev@typoheads.at', 'typoheads', '23f8a3315de386dba16bbf3bdba22181', 'several bugfixes:linebreaks in HTML emails, realurl, errorUserFunc; hook for filling custom markers, security fixes (protection against XSS)', '', 4000004, 0, 0),
(7488, 0, 'th_mailformplus', 1, '4.0.5', 49181, 1367, 'MailformPlus', 'advanced form-mailer (html template based forms)', 1, -1, 3, 1203789587, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"3.0.0-0.0.0";s:5:"typo3";s:11:"3.5.0-0.0.0";}}', 'Dev-Team Typoheads', 'dev@typoheads.at', 'typoheads', '70412217a54894a54adbe721a8dced0d', 'bugfixed linebreaks in plain emails,predefine forms via TypoScript and insert them easily by choosing one of them from a dropdown shown in the plugin-element, UPDATE records instead of INSERT possible, added API-functions for authCode (short md5) generati', '', 4000005, 0, 0),
(7489, 0, 'th_mailformplus', 1, '4.0.6', 49181, 75, 'MailformPlus', 'advanced form-mailer (html template based forms)', 1, -1, 3, 1207740710, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"3.0.0-0.0.0";s:5:"typo3";s:11:"3.5.0-0.0.0";}}', 'Dev-Team Typoheads', 'dev@typoheads.at', 'typoheads', 'd9d286d3a9c6ecd8e5a95273cc203315', 'bugfixed initialization of $this-get_post, added some forgotten translations to locallang_db.xml, added functionality for postprocessing form data, moved loading of default values to include TS settings, added description for TS-option noDefaultErrorList', '', 4000006, 0, 0),
(7490, 0, 'th_mailformplus', 1, '4.0.7', 49181, 6610, 'MailformPlus', 'The swiss army knife for all kinds of mailforms, see manual for features.', 1, -1, 3, 1207839126, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"3.0.0-0.0.0";s:5:"typo3";s:11:"3.5.0-0.0.0";}}', 'Dev-Team Typoheads', 'dev@typoheads.at', 'typoheads', 'fdb0d739c215c32deca37da90510ddc7', 'New features e.g. saving in external DB like Oracle and some bugfixes.', '', 4000007, 0, 0),
