(7566, 0, 'tinyrte', 1, '1.3.0', 21105, 420, 'tinyRTE', 'RTE based on TinyMCE. Still under developement and in alpha state but usual. Hints to integrate a RTE in Typo3 learned from rtehtmlarea by Stanislas Rolland. Supported Browsers: Mozilla, MSIE, FireFox, Opera and Safari. Need a very nice graphic for this E', 1, 0, 0, 1132863600, 'a:2:{s:7:"depends";a:3:{s:5:"typo3";s:13:"3.6.15-0.0.16";s:3:"php";s:13:"0.0.16-0.0.16";s:3:"cms";s:0:"";}s:9:"conflicts";a:5:{s:11:"rtehtmlarea";s:0:"";s:15:"rte_pb_htmlarea";s:0:"";s:13:"sr_spellcheck";s:0:"";s:11:"rte_chooser";s:0:"";s:11:"sr_htmlarea";s:0:"";}}', 'Thomas Schulze', 'kontakt@outraxx.de', 'outraxx', 'a202c442b36d8dfd78c31a0fa426f997', 'Inlinepopups are now available for Dialogs. This is for user who have an popupblocker installed. Tested on IE6 and Firefox.', '[outraxX]', 1003000, 0, 0),
(7567, 0, 'tinyrte', 1, '1.4.0', 21105, 1228, 'tinyRTE', 'RTE based on TinyMCE. Still under developement and in alpha state but usual. Hints to integrate a RTE in Typo3 learned from rtehtmlarea by Stanislas Rolland. Supported Browsers: Mozilla, MSIE, FireFox, Opera and Safari. Need a very nice graphic for this E', 1, 0, 0, 1134233399, 'a:2:{s:7:"depends";a:3:{s:5:"typo3";s:13:"3.6.15-0.0.16";s:3:"php";s:13:"0.0.16-0.0.16";s:3:"cms";s:0:"";}s:9:"conflicts";a:5:{s:11:"rtehtmlarea";s:0:"";s:15:"rte_pb_htmlarea";s:0:"";s:13:"sr_spellcheck";s:0:"";s:11:"rte_chooser";s:0:"";s:11:"sr_htmlarea";s:0:"";}}', 'Thomas Schulze', 'kontakt@outraxx.de', 'outraxx', 'de31c42976edef2709ef44696418a10e', 'Includes now the nwe release 2.0.1 of tinymce.', '[outraxX]', 1004000, 0, 0),
(7568, 0, 'tinyrte', 1, '1.4.1', 21105, 826, 'tinyRTE', 'RTE based on TinyMCE. Still under developement and in alpha state but usual. Hints to integrate a RTE in Typo3 learned from rtehtmlarea by Stanislas Rolland. Supported Browsers: Mozilla, MSIE, FireFox, Opera and Safari. Need a very nice graphic for this E', 2, 0, 0, 1144436855, 'a:0:{}', 'Thomas Schulze', 'kontakt@outraxx.de', 'outraxx', 'bb00894dca87d967c034f4d29b365d7e', 'Bugfixed: Filelinks are now correct inserted.\r\n2 another Plugins for TinyMCE added: typo3link and typo3image. \r\nThis Extension is stable from now...', '[outraxX]', 1004001, 0, 0),
(7569, 0, 'tinyrte', 1, '1.5.0', 21105, 319, 'tinyRTE', 'RTE based on TinyMCE. Supported Browsers: Mozilla, MSIE, FireFox, Opera and Safari. Sorry, no inlinepopups available for Typo3 V4 yet.', 2, 0, 0, 1144658778, 'a:0:{}', 'Thomas Schulze', 'kontakt@outraxx.de', 'outraxx', '83a64fbeffe345e66d7360989b10d346', 'Fixed for Typo3 v4-Compatibility. Inlinepopups dont work in Typo3 v4 at this time. This will be fixed...', '[outraxX]', 1005000, 0, 0),
(7570, 0, 'tinyrte', 1, '1.5.1', 21105, 319, 'tinyRTE', 'RTE based on TinyMCE. Supported Browsers: Mozilla, MSIE, FireFox, Opera and Safari. Sorry, no inlinepopups available for Typo3 V4 yet.', 2, 0, 0, 1145101166, 'a:0:{}', 'Thomas Schulze', 'kontakt@outraxx.de', 'outraxx', '0ea7c37ad1b154323ffb3d4336b027c4', 'Configuration of available Buttons in BE-Groups,BE-User and TS-Config (at this time only "hideButtons" & "showButtons"). BE-User-Conf is adding to BE-Groups, TS-Config override both. Configuration in EM changed.', '[outraxX]', 1005001, 0, 0),
(7571, 0, 'tinyrte', 1, '1.5.2', 21105, 39, 'tinyRTE', 'RTE based on TinyMCE. Supported Browsers: Mozilla, MSIE, FireFox, Opera and Safari. Sorry, no inlinepopups available for Typo3 V4 yet.', 2, 0, 0, 1145201058, 'a:0:{}', 'Thomas Schulze', 'kontakt@outraxx.de', 'outraxx', 'd14f610d967094aab58fb390b192a5ca', 'BE-Admin has now all Buttons if no one is configured for him. If the Image-Button is clicked while an Image is selected in the editor, you can now change some properties (alt-tag, title, border etc.) or select a new image.', '[outraxX]', 1005002, 0, 0),
(7572, 0, 'tinyrte', 1, '1.5.3', 21105, 483, 'tinyRTE', 'RTE based on TinyMCE. Supported Browsers: Mozilla, MSIE, FireFox, Opera and Safari. Sorry, no inlinepopups available for Typo3 V4 yet.', 2, 0, 0, 1148666409, 'a:0:{}', 'Thomas Schulze', 'kontakt@outraxx.de', 'outraxx', '38ac6f93289a6e040a7046d84278f771', 'For Bugreport please use the form on http://www.outraxx.de/changelog/', '[outraxX]', 1005003, 0, 0),
(7573, 0, 'tinyrte', 1, '1.5.4', 21105, 765, 'tinyRTE', 'RTE based on TinyMCE. Supported Browsers: Mozilla, MSIE, FireFox, Opera and Safari. Sorry, no inlinepopups available for Typo3 V4 yet.', 2, 0, 0, 1148837117, 'a:0:{}', 'Thomas Schulze', 'kontakt@outraxx.de', 'outraxx', 'ec560e7d992490db04dd0c43eabc1457', 'Spellchecker now available (use Google). Please report Bugs @ http://www.outraxx.de/changelog/. Full featured in Typo3 below version 4.0.', '[outraxX]', 1005004, 0, 0),
