(7579, 0, 'tinyrte', 1, '1.5.10', 21105, 1459, 'tinyRTE', 'RTE based on TinyMCE. Supported Browsers: Mozilla, MSIE, FireFox, Opera and Safari.', 2, 0, 0, 1169766008, 'a:0:{}', 'Thomas Schulze', 'kontakt@outraxx.de', 'outraxx', '7282a81b9063993af2a80cb775aad07a', 'Bugfix for use inlinepopups with IE and File-/Imagebrowser. Now it works when you select an other tab to give an external URL for example.', '[outraxX]', 1005010, 0, 0),
