(7584, 0, 'tinyrte', 1, '1.6.4', 21105, 267, 'tinyRTE', 'RTE based on TinyMCE. Supported Browsers: Mozilla, MSIE, FireFox, Opera and Safari.', 2, 0, 0, 1178652745, 'a:0:{}', 'Thomas Schulze', 'kontakt@outraxx.de', 'outraxx', '92b0d2fd521114c78a1e10033acd8a05', 'Upload Images via Imagebrowser works now. Since this Version no FIXED preconfiguration. TSconfig-Parameter addParams added. See Manual for this.', '[outraxX]', 1006004, 0, 0),
