(7670, 0, 'tmpl_jovo_presentation', 1, '0.1.0', 659, 654, 'Presentation Slides', 'Make online presentation slides (like PowerPoint) out of a simple TYPO3 page tree. Includes backward- forward buttons (jovo_browse). Presentation automaticly fits to browser size, if JavaScript is enabled. You can customize the layout and colors with your', 1, 0, 6, 1135953446, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";}}', 'Johannes Vockeroth', 'jv525052@inf.tu-dresden.de', 'jokannes', '1a71a4a83f061f9eb13c0698c82c0ccd', 'Say Hello to my first public extension!', '', 1000, 1, 0),
(7671, 0, 'tmpl_urbannomad', 1, '0.1.0', 12297, 73, 'Urban Nomad Template', 'A highly flexible and easily configurable packaged template to be used as a starting point for new websites built with Typo3.', 1, 0, 6, 1118642985, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";}}', 'Ryan Off', 'ryan@gaiainternational.com', 'katoomba', 'a7ce302293dd18775e65484f798462e1', 'First version of template extension. Some work on the documentation, changing the default look, and constants still needs to be done. Slightly modified documentation.', 'Gaia International', 1000, 0, 0),
(7672, 0, 'tmpl_urbannomad', 1, '0.1.1', 12297, 14, 'Urban Nomad Template', 'A highly flexible and easily configurable packaged template to be used as a root level template for new websites built with Typo3.', 1, 0, 6, 1118681622, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";}}', 'Ryan Off', 'ryan@gaiainternational.com', 'katoomba', 'cf94044f0b5730cfa250a1341d182eef', 'Revised documentation (added screenshots). Icon change.', 'Gaia International', 1001, 0, 0),
(7673, 0, 'tmpl_urbannomad', 1, '0.1.2', 12297, 23, 'Urban Nomad Template', 'A highly flexible and easily configurable packaged template to be used as a root level template for new websites built with Typo3.', 1, 0, 6, 1118681733, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";}}', 'Ryan Off', 'ryan@gaiainternational.com', 'katoomba', '373771c9c8bedf19e34beb3114f3a0c1', '', 'Gaia International', 1002, 0, 0),
(7674, 0, 'tmpl_urbannomad', 1, '0.1.3', 12297, 190, 'Urban Nomad Template', 'A highly flexible and easily configurable packaged template to be used as a root level template for new websites built with Typo3.', 1, 0, 6, 1118681819, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";}}', 'Ryan Off', 'ryan@gaiainternational.com', 'katoomba', '52d0a53eaf78b79cb18e078cbe82a9bf', '', 'Gaia International', 1003, 0, 0),
(7675, 0, 'tmpl_urbannomad', 1, '0.1.4', 12297, 114, 'Urban Nomad Template', 'A highly flexible and easily configurable packaged template to be used as a root level template for new websites built with Typo3.', 1, 0, 6, 1119020771, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";}}', 'Ryan Off', 'ryan@gaiainternational.com', 'katoomba', '6cd80a8518d7b40ee0d4668672be9f85', '', 'Gaia International', 1004, 0, 0),
(7676, 0, 'tmpl_urbannomad', 1, '0.1.5', 12297, 1967, 'Urban Nomad Template', 'A highly flexible and easily configurable packaged template to be used as a root level template for new websites built with Typo3.', 1, 0, 6, 1119460106, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:11:"0.0.2-0.0.2";s:3:"php";s:11:"0.0.2-0.0.2";}}', 'Ryan Off', 'ryan@gaiainternational.com', 'katoomba', '68672a997fc871d4fe0d9517a998b1a2', 'Modified CSS styles. removed duplicate entries.', 'Gaia International', 1005, 0, 0),
(7677, 0, 'tmpl_urbannomad', 1, '0.1.6', 12297, 2344, 'Urban Nomad Template', 'A highly flexible and easily configurable packaged template to be used as a root level template for new websites built with Typo3.', 1, 0, 6, 1133808365, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:11:"0.0.3-0.0.3";s:3:"php";s:11:"0.0.3-0.0.3";}}', 'Ryan Off', 'ryan@gaiainternational.com', 'katoomba', 'ad1fb03048df507d12d5186a214f0333', 'A few minor bug fixes and color changes', 'Gaia International', 1006, 0, 0),
(7678, 0, 'tmpl_urbannomad', 1, '0.2.0', 12297, 7284, 'Urban Nomad Template', 'A highly flexible and easily configurable packaged template to be used as a root level template for new websites built with Typo3.', 1, 0, 6, 1172422583, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:6:"3.0.0-";s:5:"typo3";s:6:"3.5.0-";}}', 'Ryan Off', 'ryan@gaiainternational.com', 'katoomba', 'ef7fc72acdb0a74561b66408fce32aa3', 'Bug fixes to work with to Typo3 4.0.\nThese bug fixes should not affect working with Typo3 3.x. The majority of the bug fixes included changing the markers in the html file of the template. For example:\n BANNERLEFT \nwith:\n!-- BANNERLEFT start', 'Gaia International', 2000, 1, 0),
(7679, 0, 'tmsw_cleandb', 1, '2.0.0', 1076, 13, 'TMSW - CleanDB', 'Cleans out all deleted records from the DB - Work with DBAL', 0, -1, 1, 1135944299, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";}}', 'Mathon Nicolas', 'mathon@tmsw.fr', 'nmathon', 'f234e2132f0ecfecb52079e4b905affb', '', '', 2000000, 0, 0),
(7680, 0, 'tmsw_cleandb', 1, '2.0.1', 1076, 14, 'CleanDB - DBAL', 'Cleans out all deleted records from the DB - Works with DBAL', 2, -1, 1, 1135945166, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";}}', 'Mathon Nicolas', 'mathon@tmsw.fr', 'nmathon', '43246dc12b31da028b12966b9feb8e63', 'Wrong file uploaded.\r\nStill in alpha for a moment.', '', 2000001, 0, 0),
(7681, 0, 'tmsw_cleandb', 1, '2.0.2', 1076, 13, 'CleanDB - DBAL', 'Cleans out all deleted records from the DB - Works with DBAL', 0, -1, 1, 1135946084, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";}}', 'Mathon Nicolas', 'mathon@tmsw.fr', 'nmathon', 'ce3e8482ca308f1f2a8886af1ee024da', '', '', 2000002, 0, 0),
(7682, 0, 'tmsw_cleandb', 1, '2.1.0', 1076, 1036, 'CleanDB - DBAL', 'This extension cleans the deleted records form the Database. Its compatible with DBAL. Tested under PostgreSQL 7.\r\n\r\nExtension based on CleanDB from Mathias Schreiber and MK Wastebasket from Matthias Kall', 2, -1, 1, 1135950196, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";}}', 'Mathon Nicolas', 'mathon@tmsw.fr', 'nmathon', 'c018c74533e312ba3f6aa2b907efa162', 'Translation update', '', 2001000, 1, 0),
(7683, 0, 'tm_contentaccess', 1, '0.18.0', 10473, 338, 'Content Access and Extended Interface Control', 'Adds Restrict editing by non-Admins: for individual content elements. In addition this plugin adds new TypoScript configuration options and CSS classes for many core files of Typo3 in order to customize the BE interface and frontend editing interface. N', 1, 0, 0, 1139942419, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"3.8.1-4.0.1";s:3:"php";s:0:"";s:3:"cms";s:0:"";}}', 'Tapio Markula', 'tapio.markula@atwebteam.com', 'tmarkula', '430432f0baae441da210244404ecbebc', 'Really cool new implementations. In additional of older versions of tm_contentaccess, this plugin includes for example intgrated versions of gb_bedraganddrop, kb_pm_paste and zed_more_columns. Now the standard page module is extremely easy to use', 'www.atwebteam.com', 18000, 0, 0),
(7684, 0, 'tm_contentaccess', 1, '0.18.1', 10473, 299, 'Content Access and Extended Interface Control', 'Adds new access control features for individual content elements. In addition this plugin adds new TypoScript configuration options and CSS classes for many core files of Typo3 in order to customize the BE interface and frontend editing interface. Note. T', 1, 0, 0, 1142804239, 'a:0:{}', 'Tapio Markula', 'tapio.markula@atwebteam.com', 'tmarkula', 'b22b73dc850123aff8b82678f2d4e656', 'Button set have been made more consistent and new options for the layout of BE buttonsets and new buttons has been added. Added also new options for resrict editing by backend user groups/users. All have been explained in the manual.', 'www.atwebteam.com', 18001, 0, 0),
(7685, 0, 'tm_contentaccess', 1, '0.19.0', 10473, 353, 'Content Access and Extended Interface Control', 'Adds new access control features for individual content elements. In addition this plugin adds new TypoScript configuration options and CSS classes for many core files of Typo3 in order to customize the BE interface and frontend editing interface. Note. T', 1, 0, 0, 1145282861, 'a:0:{}', 'Tapio Markula', 'tapio.markula@atwebteam.com', 'tmarkula', 'c83bcc4b2e44f904c7dfdfc58bd4b4c4', 'Button set have been made more consistent and new options for the layout of BE buttonsets and new buttons has been added. Added also new options for resrict editing by backend user groups/users. Some level support also for TemplaVoila 0.4-1.0 (not as good', 'www.atwebteam.com', 19000, 0, 0),
(7686, 0, 'tm_contentaccess', 1, '0.19.1', 10473, 290, 'Content Access and Extended Interface Control', 'Adds new access control features for individual content elements. In addition this plugin adds new TypoScript configuration options and CSS classes for many core files of Typo3 in order to customize the BE interface and frontend editing interface. Note. T', 1, 0, 0, 1147458569, 'a:0:{}', 'Tapio Markula', 'tapio.markula@atwebteam.com', 'tmarkula', 'ea915975c62eac5482313a42fa6cd970', 'small bugfix', 'www.atwebteam.com', 19001, 0, 0),
(7687, 0, 'tm_contentaccess', 1, '0.19.2', 10473, 318, 'Content Access and Extended Interface Control', 'Adds new access control features for individual content elements. In addition this plugin adds new TypoScript configuration options and CSS classes for many core files of Typo3 in order to customize the BE interface and frontend editing interface. Note. T', 1, 0, 0, 1150435965, 'a:0:{}', 'Tapio Markula', 'tapio.markula@atwebteam.com', 'tmarkula', '75eeff354177fde8b850f7a804d42828', 'Made a compatibility update for skin_grey_2.\r\nIf skin_grey_2 has not updated, no need to update tm_contentaccess either.', 'www.atwebteam.com', 19002, 0, 0),
(7688, 0, 'tm_contentaccess', 1, '0.19.3', 10473, 219, 'Content Access and Extended Interface Control', 'Adds new access control features for individual content elements. In addition this plugin adds new TypoScript configuration options and CSS classes for many core files of Typo3 in order to customize the BE interface and frontend editing interface. Note. T', 1, 0, 0, 1150884144, 'a:0:{}', 'Tapio Markula', 'tapio.markula@atwebteam.com', 'tmarkula', 'b0a4a414bf191fd3df6d55d494903c1c', 'a tiny bug fix concerning icons', 'www.atwebteam.com', 19003, 0, 0),
