(7729, 0, 'tm_lunchmenu', 1, '0.1.0', 1853, 19, 'Cafeteria Menu System', 'System to store and display lunch/supper menus.', 1, 0, 3, 1092950409, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:3:"cms";s:0:"";}}', 'Tony Murray', 'tonymurray@fastmail.fm', 'murraytony', 'fe4c8c186456ed5c159e55aadddcf96f', 'First Version.\r\nPretty self explanatory.\r\nRight now it isnt very configureable as it was made to server a purpose, this will come later.', '', 1000, 0, 0),
(7730, 0, 'tm_lunchmenu', 1, '0.1.1', 1853, 32, 'Lunch Menu', 'Frontend entry and display of a cafeteria lunch menu.', 1, 0, 3, 1093376575, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:3:"cms";s:0:"";}}', 'Tony Murray', 'murraytony@yahoo.com', 'murraytony', '9bdc89e195142f9f5e694c075a75793b', 'Added icons.', '', 1001, 0, 0),
(7731, 0, 'tm_lunchmenu', 1, '0.2.0', 1853, 31, 'Cafeteria Menu System', 'System to store and display lunch/supper menus.', 1, 0, 3, 1097006761, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:3:"cms";s:0:"";}}', 'Tony Murray', 'tonymurray@fastmail.fm', 'murraytony', 'f817dec886f1c84dac4e40065e108a84', 'Now LL aware and configurable via the websites template. First draft of documentation and first public version.', '', 2000, 0, 0),
(7732, 0, 'tm_lunchmenu', 1, '0.2.3', 1853, 66, 'Cafeteria Menu System', 'System to store and display lunch/supper menus.', 1, 0, 3, 1097007784, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:3:"cms";s:0:"";}}', 'Tony Murray', 'tonymurray@fastmail.fm', 'murraytony', '5e8a9aa717c7dadc606357d72b199a8f', 'Fix Screenshot in Documentation.', '', 2003, 0, 0),
(7733, 0, 'tm_lunchmenu', 1, '0.3.0', 1853, 147, 'Cafeteria Menu System', 'System to store and display lunch/supper menus.', 1, 0, 3, 1097252142, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:3:"cms";s:0:"";}}', 'Tony Murray', 'tonymurray@fastmail.fm', 'murraytony', '4a68095477bd2c2d4af05cd4f85e1bc8', 'Variables from the template should now be properly imported. The links should now work when static page links are used.  Allow caching when there is no date variable (aka, just the menu for the current date).  Hide the link to todays menu when already vi', '', 3000, 0, 0),
(7734, 0, 'tm_lunchmenu', 1, '0.4.0', 1853, 217, 'Cafeteria Menu System', 'System to store and display lunch/supper menus.', 1, 0, 3, 1100040854, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:3:"cms";s:0:"";}}', 'Tony Murray', 'tonymurray@fastmail.fm', 'murraytony', '0a4eb7b135fc2adf708f41e25ae70c27', 'Made it very easy to add more meals and added Breakfast and Brunch. Put a few more variables in LL and added a partial translation. Send me others to get them into the package.  I redid the way the html template and javascript is laid out so you may need', '', 4000, 0, 0),
(7735, 0, 'tm_lunchmenu', 1, '0.4.3', 1853, 272, 'Cafeteria Menu System', 'System to store and display lunch/supper menus.', 1, 0, 3, 1101933487, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:3:"cms";s:0:"";}}', 'Tony Murray', 'tonymurray@fastmail.fm', 'murraytony', '91558a25558d239508d05fb2f554fc09', 'Fixed out of order meals, like 2,0,1. Add german translation. Fiddle with the documentation to make it smaller.', '', 4003, 0, 0),
(7736, 0, 'tm_lunchmenu', 1, '0.5.0', 1853, 1067, 'Cafeteria Menu System', 'System to store and display lunch/supper menus.', 1, 0, 3, 1110232876, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"3.6.2-0.0.2";s:3:"php";s:11:"4.0.2-0.0.2";s:3:"cms";s:0:"";}}', 'Tony Murray', 'tonymurray@fastmail.fm', 'murraytony', '3d75e476d8cc8f640368dd8d596a312f', 'Fixed using non built-in rtf menu template.\r\nNow more locale friendly (converted date() to strftime()), so please try again if you couldnt get it to fully output you local language before.', '', 5000, 1, 0),
(7737, 0, 'tpg_iepngfix', 1, '2.0.0', 2914, 409, 'PNG alpha channel fix for Internet Explorer 5.5', 'Fixes the problem of png alpha channels in Internet Explorer 5.5 by post-processing the page content  and replacing every alpha-channel png with a transparent spacer.png which is  then replaced on the client side through an ActiveX-based filter.', 1, 0, 4, 1098054998, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:3:"cms";s:0:"";}}', 'Thomas Murphy', 'murphy@thepanemgroup.com', 'thomasmurphy', '4acb309d34e17cfb44f26707affed5dd', 'Added documentation.', '', 2000000, 0, 0),
(7738, 0, 'tpg_iepngfix', 1, '3.0.0', 2914, 28, 'PNG alpha channel fix for IE5.5', 'A fix for the display of PNG alpha channel images in the Internet Explorer using PHP-processing of the page output and loading the images through a ActiveX-based Filter', 1, 0, 2, 1098055153, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:3:"cms";s:0:"";}}', 'Thomas Murphy', 'murphy@thepanemgroup.com', 'thomasmurphy', '86f6b13dcb908cebd7fbb2ababa98fef', '- now based on a hook in tslib_fe and not on the blinking javascript anymore!', '', 3000000, 0, 0),
(7739, 0, 'tpg_iepngfix', 1, '3.1.0', 2914, 466, 'PNG alpha channel fix for IE5.5', 'A fix for the display of PNG alpha channel images in the Internet Explorer using PHP-processing of the page output and loading the images through a ActiveX-based Filter', 1, 0, 2, 1098056809, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:3:"cms";s:0:"";}}', 'Thomas Murphy', 'murphy@thepanemgroup.com', 'thomasmurphy', 'f753d85094655906c03b80d5dd260615', '', '', 3001000, 0, 0);
