(7853, 0, 'tt_news', 1, '1.2.3', 329539, 3956, 'News', 'Website news with front page teasers and article handling inside.', 2, -1, 3, 1086855420, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:0:"";s:3:"php";s:11:"0.0.4-0.0.4";s:3:"cms";s:0:"";}}', 'Stig Nrgaard Jepsen', 'stig@8620.dk', 'rupi', 'b50225cb79ab3e692c1ce2f4abd9efd2', 'Major update. Flexforms added. Updater added for category table and CODE-filed(select_key) to FlexForms. Bugfix: When using the LIST method, would only display first page if number of newsitems exceeded limit.\r\nBugfix in 1.2.3: 2labeltexts were missing in', '', 1002003, 0, 0),
(7854, 0, 'tt_news', 1, '1.3.0', 329539, 3202, 'News', 'Website news with front page teasers and article handling inside.', 2, -1, 3, 1091301934, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"3.6.2-0.0.2";s:3:"php";s:11:"0.0.5-0.0.5";s:3:"cms";s:0:"";}}', 'Stig Nrgaard Jepsen', 'stig@8620.dk', 'rupi', '7c425eaa19be96dcdc23792a3d4cf3ec', 'Lots of bugs fixed and some new little smart features and more.\r\nVisit us at the typo3.projects.tt-news newsgroup.\r\nCredits goes out to Rupert Germann, who has given a lot of work in this lately.', '', 1003000, 0, 0),
(7855, 0, 'tt_news', 1, '1.4.1', 329539, 1817, 'News', 'Website news with front page teasers and article handling inside.', 2, -1, 3, 1091305720, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"3.6.2-0.0.2";s:3:"php";s:11:"0.0.5-0.0.5";s:3:"cms";s:0:"";}}', 'Rupert Germann', 'rupi@gmx.li', 'rupi', 'a86c73d9d6ca54026756e98cfe3a970a', '', '', 1004001, 0, 0),
(7856, 0, 'tt_news', 1, '1.5.3', 329539, 922, 'News', 'Website news with front page teasers and article handling inside.', 2, -1, 3, 1093447142, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"3.6.3-0.0.3";s:3:"php";s:11:"0.0.6-0.0.6";s:3:"cms";s:0:"";}}', 'Rupert Germann', 'rupi@gmx.li', 'rupi', 'cdbb938300ad1c12def0583efa21b211', '- new feature, excludeLatestFromList\r\n- merged in new translations\r\n- new section about Links in news in the manual.\r\n- fixed a small bug with the firstImageIsPreview mode: now the captions are displayed correctly\r\n- added some new TSvars and a db-f', '', 1005003, 0, 0),
(7857, 0, 'tt_news', 1, '1.6.3', 329539, 2823, 'News', 'Website news with front page teasers and article handling inside.', 2, -1, 3, 1095597294, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"3.6.4-0.0.4";s:3:"php";s:11:"0.0.7-0.0.7";s:3:"cms";s:0:"";}}', 'Rupert Germann', 'rupi@gmx.li', 'rupi', 'bb3ee506c3cac9d69f49af98e7ccc8b5', 'small change in the getRelatedCobj - requires changes in your TS-setup (see deafult setup for example). Fix for the "12hour" bug. New Section about "RTE" configuration in the manual.', '', 1006003, 0, 0);
