(8021, 0, 'newsletter', 1, '2.6.0', 36, 0, 'Newsletter', 'Send any pages as Newsletter and provide statistics on opened emails and clicked links.', 2, 0, 1, 1448936968, 'a:1:{s:7:"depends";a:4:{s:3:"cms";s:0:"";s:3:"php";s:11:"5.3.7-0.0.0";s:5:"typo3";s:13:"6.1.0-7.99.99";s:9:"scheduler";s:5:"6.1.0";}}', 'Ecodev', 'contact@ecodev.ch', 'ecodev', 'a905e2064a4ac15a490ce5afcfbfac26', 'Release version 2.6.0\n\nThis release brings compatibility with TYPO3 7.6, and a lot of new features that were made possible\nthanks to @marvin-martian who provided the basis for that. Many of these new features are described\nin details in the documentation.', 'Ecodev', 2006000, 0, 0),
(8022, 0, 'newsletter', 1, '2.6.1', 36, 0, 'Newsletter', 'Send any pages as Newsletter and provide statistics on opened emails and clicked links.', 2, 0, 1, 1455768250, 'a:1:{s:7:"depends";a:3:{s:3:"php";s:11:"5.3.7-0.0.0";s:5:"typo3";s:13:"6.1.0-7.99.99";s:9:"scheduler";s:5:"6.1.0";}}', 'Ecodev', 'contact@ecodev.ch', 'ecodev', '7b0ce41237e3e28f35fe88443ff902dd', 'Release version 2.6.1\n\nThis release improves a few things:\n\n Compatibility with multi-domains\n Use the User-Agent "TYPO3/7.6.0 Newsletter/2.6.1" for all HTTP requests\n Respect specified PID for RecipientList and BounceAccount', 'Ecodev', 2006001, 0, 0),
