(8024, 0, 'newsletter', 1, '3.0.1', 36, 0, 'Newsletter', 'Send any pages as Newsletter and provide statistics on opened emails and clicked links.', 2, 0, 1, 1468118733, 'a:1:{s:7:"depends";a:3:{s:3:"php";s:11:"5.6.0-0.0.0";s:5:"typo3";s:13:"6.2.0-8.99.99";s:9:"scheduler";s:5:"6.2.0";}}', 'Ecodev', 'contact@ecodev.ch', 'ecodev', '2f97a8187628239b081db836a6c22e29', 'Release version 3.0.1\n\nThis is a bugfix release, to solve a single bug:\n\n UTF-8 characters in newsletter content were mangled', 'Ecodev', 3000001, 0, 0),
(8025, 0, 'newsletter', 1, '3.0.2', 36, 0, 'Newsletter', 'Send any pages as Newsletter and provide statistics on opened emails and clicked links.', 2, 0, 1, 1468906047, 'a:1:{s:7:"depends";a:3:{s:3:"php";s:11:"5.6.0-0.0.0";s:5:"typo3";s:13:"6.2.0-8.99.99";s:9:"scheduler";s:5:"6.2.0";}}', 'Ecodev', 'contact@ecodev.ch', 'ecodev', '23cac5b860a205f14d34235f93e1bb55', 'Release version 3.0.2\n\nThis is a bugfix release, to solve a bug affecting all installation\nthat are NOT MariaDB 10. It would incorrectly generate auth_code\nleading to the impossibility of sending the same newsletter to the\nsame recipient more than once.', 'Ecodev', 3000002, 0, 0),
(8026, 0, 'newsletter', 1, '3.1.0', 36, 0, 'Newsletter', 'Send any pages as Newsletter and provide statistics on opened emails and clicked links.', 2, 0, 1, 1471432044, 'a:1:{s:7:"depends";a:3:{s:3:"php";s:11:"5.6.0-0.0.0";s:5:"typo3";s:13:"6.2.0-8.99.99";s:9:"scheduler";s:5:"6.2.0";}}', 'Ecodev', 'contact@ecodev.ch', 'ecodev', 'eedecb0f6f0190c6605b4800a87a1e3b', 'Release version 3.1.0\n\nThis minor release introduce a new parameter EmailInterface to the\nhook substituteMarkersHook.', 'Ecodev', 3001000, 0, 0),
(8027, 0, 'newsletter', 1, '3.2.0', 36, 0, 'Newsletter', 'Send any pages as Newsletter and provide statistics on opened emails and clicked links.', 2, 0, 1, 1490971758, 'a:1:{s:7:"depends";a:3:{s:3:"php";s:11:"5.6.0-0.0.0";s:5:"typo3";s:13:"6.2.0-8.99.99";s:9:"scheduler";s:5:"6.2.0";}}', 'Ecodev', 'contact@ecodev.ch', 'ecodev', '7cdd7854519bfed426ec4646f4bfc637', 'Release version 3.2.0\n\nThis versions cleans up the code and fixes a few bugs:\n\n Ability to override some Newsletter values from Recipient List data\n Definitive fix for broken RecipientList edition in backend\n Correct default language value (that could ', 'Ecodev', 3002000, 1, 0),
