(8029, 0, 'titelei', 1, '1.0.2', 0, 0, 'titelei', 'titelei is a tool for publishing content into epub on the fly. It integrates Grandts award winning epub library to typo3 ', 0, 0, 2, 1441705000, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.2.14-7.4.0";}}', 'Michael Schneider', 'Michael Schneider', '3imsinn', '261d5893ce6c08b550662072520bc21c', 'Description update', '', 1000002, 1, 0),
(8030, 0, 'external_import', 1, '2.5.1', 468, 0, 'External Data Import', 'Tool for importing data from external sources into the TYPO3 database, using an extended TCA syntax. Provides a BE module, a Scheduler task and an API.', 2, 0, 1, 1441698663, 'a:1:{s:7:"depends";a:4:{s:11:"svconnector";s:11:"2.0.0-0.0.0";s:7:"extbase";s:11:"1.3.0-0.0.0";s:5:"fluid";s:11:"1.3.0-0.0.0";s:5:"typo3";s:12:"4.5.0-6.2.99";}}', 'Francois Suter (Cobweb)', 'typo3@cobweb.ch', 'francois', '2e9e18401ce7502f4cd6799b945a2734', 'Hotfix: corrected wrong object being passed to new process parameters hook.', '', 2005001, 0, 0),
(8031, 0, 'external_import', 1, '0.5.0', 468, 10, 'External Data Import', 'This backend module can be used to import data from external sources into TYPO3 tables extended with special definitions in the TCA and connector services.', 0, 0, 1, 1209414429, 'a:0:{}', 'Francois Suter (Cobweb)', 'support@cobweb.ch', 'francois', '568e2f404df47b41d68c8cacfc261b1b', 'Early release ahead of T3DD08. Not complete but functional.', '', 5000, 0, 0),
(8032, 0, 'external_import', 1, '0.5.1', 468, 36, 'External Data Import', 'This backend module can be used to import data from external sources into TYPO3 tables extended with special definitions in the TCA and connector services.', 0, 0, 1, 1209462373, 'a:0:{}', 'Francois Suter (Cobweb)', 'support@cobweb.ch', 'francois', 'c6853548570bab6b8496ccb321299fc7', 'Added note about Gabriel version compatibility', '', 5001, 0, 0),
(8033, 0, 'external_import', 1, '0.6.0', 468, 14, 'External Data Import', 'This backend module can be used to import data from external sources into TYPO3 tables extended with special definitions in the TCA and connector services.', 0, 0, 1, 1216580332, 'a:0:{}', 'Francois Suter (Cobweb)', 'typo3@cobweb.ch', 'francois', '0fcefce742f1267a9f3dfc7b3a414cb9', 'Introduced use of TCEmain for proper data manipulation, cleaned up extended TCA syntax, added hook for pre-processing data before storage. ATTENTION: compatibility issues on update, please refer to manual!', '', 6000, 0, 0),
(8034, 0, 'external_import', 1, '0.6.1', 468, 6, 'External Data Import', 'This backend module can be used to import data from external sources into TYPO3 tables extended with special definitions in the TCA and connector services.', 0, 0, 1, 1217794367, 'a:0:{}', 'Francois Suter (Cobweb)', 'typo3@cobweb.ch', 'francois', 'a02533218675ecb7e2bbc4ff54829683', 'Added array data format handling, added user rights setup instructions in the manual.', '', 6001, 0, 0),
