(8036, 0, 'external_import', 1, '0.8.0', 468, 7, 'External Data Import', 'This backend module can be used to import data from external sources into TYPO3 tables extended with special definitions in the TCA and connector services.', 1, 0, 1, 1232296668, 'a:0:{}', 'Francois Suter (Cobweb)', 'typo3@cobweb.ch', 'francois', 'fc4a3516774219f4e515a6ebdf243dae', 'Major update (see ChangeLog). ATTENTION: compatibility break, read manual before upgrading.', '', 8000, 0, 0),
