(8312, 0, 'wec_connector', 1, '1.6.3', 3489, 166, 'WEC Prayer Connector', 'Connecting people with requests or needs or services such as prayer requests, job board, help board, need posting board, business directory, etc.', 2, 0, 3, 1179501971, 'a:0:{}', 'Web-Empowered Church Team', 'connector(at)webempoweredchurch.org', 'webempoweredchurch', '0244a44239c63663d8de86ea02b8c565', 'Can have a single view. Fixed image posting bug (if set to required). Fixed sort display order so uses smallint -- int (11) so if have many categories, it works better.', 'Foundation For Evangelism', 1006003, 0, 0),
(8313, 0, 'wec_connector', 1, '1.6.4', 3489, 54, 'WEC Prayer Connector', 'Connecting people with requests or needs or services such as prayer requests, job board, help board, need posting board, business directory, etc.', 2, 0, 3, 1184945841, 'a:0:{}', 'Web-Empowered Church Team', 'connector(at)webempoweredchurch.org', 'webempoweredchurch', 'c703e85b58a39c73d9b14853da74d58d', 'View the categories in Flexform main tab now works. Updated template for min-max width. Fixed page link problems. Updated error printing so correct HTML. Made XHTML compliant. Minor fixes/updates.', 'Foundation For Evangelism', 1006004, 0, 0),
(8314, 0, 'wec_connector', 1, '1.6.5', 3489, 38, 'WEC Prayer Connector', 'Connecting people with requests or needs or services such as prayer requests, job board, help board, need posting board, business directory, etc.', 2, 0, 3, 1189831829, 'a:0:{}', 'Web-Empowered Church Team', 'connector(at)webempoweredchurch.org', 'webempoweredchurch', '54054d13be6aac25a0918a6e57a8f515', 'Added hide button. Do not require email address for posts. Fix IE6 CSS for width. Removed most inline CSS in template and code. Fixed website_url.', 'Foundation For Evangelism', 1006005, 0, 0),
