(8343, 0, 'wec_devo', 1, '1.2.0', 1824, 78, 'WEC Devotional Journal', 'Scheduled & interactive content for devotions, sermons, bible studies, etc. Optional journal supported too.', 2, -1, 3, 1132346207, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"3.7.1-3.8.2";s:3:"php";s:11:"4.2.4-5.0.6";s:3:"cms";s:0:"";}}', 'Web-Empowered Church Team', 'devo@webempoweredchurch.org', 'webempoweredchurch', 'fa052332fdb447875f380e59fe6f03b9', 'Added videofile support.  \r\nAdded forceTextPaging and forceTextSize. \r\nFixed templates for left/right column when used in tables so they work in IE and Firefox. \r\nAdded date_offset feature. \r\nUpdated doco about configuring with WEC Discussion Forum. \r\nFix', 'Foundation For Evangelism', 1002000, 0, 0),
(8344, 0, 'wec_devo', 1, '1.3.0', 1824, 23, 'WEC Devotional Journal', 'Scheduled & interactive content for devotions, sermons, bible studies, etc. Optional journal supported too.', 2, -1, 3, 1136065463, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"3.7.1-3.8.2";s:3:"php";s:11:"4.2.4-5.0.6";s:3:"cms";s:0:"";}}', 'Web-Empowered Church Team', 'devo@webempoweredchurch.org', 'webempoweredchurch', '775a01eeaa48f21f67f6a7d696d8a6cc', 'Fixed date problem with calendar. Added monthly calendar popup. Made configurable date format. Fixed save journal check for changes issue with Firefox. Condensed paging & text size box.', 'Foundation For Evangelism', 1003000, 0, 0),
(8345, 0, 'wec_devo', 1, '1.3.1', 1824, 42, 'WEC Devotional Journal', 'Scheduled & interactive content for devotions, sermons, bible studies, etc. Optional journal supported too.', 2, -1, 3, 1136390052, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"3.7.1-3.8.2";s:3:"php";s:11:"4.2.4-5.0.6";s:3:"cms";s:0:"";}}', 'Web-Empowered Church Team', 'devo@webempoweredchurch.org', 'webempoweredchurch', '981bf2e84ab17fdb5f95f6de674daf8d', 'Removed all z-index references. Added monthly calendar to template.', 'Foundation For Evangelism', 1003001, 0, 0),
(8346, 0, 'wec_devo', 1, '1.4.0', 1824, 78, 'WEC Devotional Journal', 'Scheduled & interactive content for devotions, sermons, bible studies, etc. Optional journal supported too.', 2, -1, 3, 1138388376, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"3.7.1-3.8.2";s:3:"php";s:11:"4.2.4-5.0.6";s:3:"cms";s:0:"";}}', 'Web-Empowered Church Team', 'devo@webempoweredchurch.org', 'webempoweredchurch', '4d2e5f7ab0bc6e0f6cd8fab79f77d72e', 'Added Dutch translation. Fixed graphic tabs so works if use external CSS. Default Constants & template now work with WEC Templates better (less wide & better formatted). Added monthly calendar icon constant.', 'Foundation For Evangelism', 1004000, 0, 0);
