(8348, 0, 'wec_devo', 1, '1.5.1', 1824, 260, 'WEC Devotional Journal', 'Scheduled & interactive content for devotions, sermons, bible studies, etc. Optional journal supported too.', 2, 0, 3, 1143224201, 'a:0:{}', 'Web-Empowered Church Team', 'devo@webempoweredchurch.org', 'webempoweredchurch', '949a0755a1a02ca8f7efa759c7933178', 'Made XHTML compliant.', 'Foundation For Evangelism', 1005001, 0, 0),
