(8350, 0, 'wec_devo', 1, '1.6.0', 1824, 342, 'WEC Devotional Journal', 'Scheduled & interactive content for devotions, sermons, bible studies, etc. Optional journal supported too.', 2, 0, 3, 1165346206, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:3:"php";s:11:"4.2.3-5.2.1";s:5:"typo3";s:11:"3.7.0-4.0.9";}}', 'Web-Empowered Church Team', 'devo@webempoweredchurch.org', 'webempoweredchurch', 'b4ddb806209777a1f8b9d889497b3c41', 'Added scripture_ref as field. Can use IFrame to automatically generate scripture. Added robot support so will not index empty. Minor link and template bugs fixed.', 'Foundation For Evangelism', 1006000, 0, 0),
(8351, 0, 'wec_devo', 1, '1.7.0', 1824, 91, 'WEC Devotional Journal', 'Scheduled & interactive content for devotions, sermons, bible studies, etc. Optional journal supported too.', 2, 0, 3, 1207159468, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:3:"php";s:11:"4.2.3-5.4.0";s:5:"typo3";s:11:"3.7.0-4.3.9";}}', 'Web-Empowered Church Team', 'devo(at)webempoweredchurch.org', 'webempoweredchurch', '75e6b1546bccb3fc064113cd39b1c936', 'Upgraded Flexform (edit and save after install), updated to Static Templates (must add to ext template), new tab menu system, can customize printjournalfile, H4/H5 tags can be customized, and many minor fixes.', 'Foundation For Evangelism', 1007000, 0, 0),
(8352, 0, 'wec_devo', 1, '1.7.1', 1824, 7, 'WEC Devotional Journal', 'Scheduled & interactive content for devotions, sermons, bible studies, etc. Optional journal supported too.', 2, 0, 3, 1233081217, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:3:"php";s:11:"4.2.3-5.4.0";s:5:"typo3";s:11:"3.7.0-4.3.9";}}', 'Web-Empowered Church Team', 'devo(at)webempoweredchurch.org', 'webempoweredchurch', '31547676f2f4288e868ce67525191f87', 'Made XHTML compatible; fixed problem with deleting sections; sectionnone changed to all because more accurate. Chooses the default section in backend record. Graphic icons have cleared backgrounds. bg_htmlarea fixes.', 'Foundation For Evangelism', 1007001, 0, 0),
(8353, 0, 'wec_devo', 1, '1.7.2', 1824, 69, 'WEC Devotional Journal', 'Scheduled & interactive content for devotions, sermons, bible studies, etc. Optional journal supported too.', 2, 0, 3, 1233336933, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:3:"php";s:11:"4.2.3-5.4.0";s:5:"typo3";s:11:"3.7.0-4.3.9";}}', 'Web-Empowered Church Team', 'devo(at)webempoweredchurch.org', 'webempoweredchurch', 'c20e8363fefbfe0398ebea57ac12cf09', 'Fixed problem with including bg_htmlarea/RTE. Fixed problem with shorttag in new file. Updated CSS for tabs.', 'Christian Technology Ministries International Inc.', 1007002, 0, 0),
(8354, 0, 'wec_devo', 1, '1.7.3', 1824, 37, 'WEC Devotional Journal', 'Scheduled & interactive content for devotions, sermons, bible studies, etc. Optional journal supported too.', 2, 0, 3, 1268654194, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:3:"php";s:11:"4.2.3-5.4.0";s:5:"typo3";s:11:"3.7.0-4.3.9";}}', 'Web-Empowered Church Team', 'devteam(at)webempoweredchurch.org', 'webempoweredchurch', '2f8403114faf45786c1f933ddce5fbe2', 'Updated to new icon. Minor CSS fixes. All functions work with PHP 5.x.', 'Christian Technology Ministries International Inc.', 1007003, 0, 0),
(8355, 0, 'wec_devo', 1, '1.8.0', 1824, 34, 'WEC Devotional Journal', 'Scheduled & interactive content for devotions, sermons, bible studies, etc. Optional journal supported too.', 2, 0, 3, 1296787427, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:3:"php";s:11:"4.2.3-5.4.0";s:5:"typo3";s:11:"4.0.0-4.5.9";}}', 'Web-Empowered Church Team', 'devteam(at)webempoweredchurch.org', 'webempoweredchurch', 'da036c5238d7f6589fe83409aed43b1a', 'Updated look - templates & CSS. Supports different RTEs for journal (RTEenabled TS constant). Added RSS feed (include RSS template to activate). Allow journalOnObj and journalOffObj in Typoscript. If no journal used, then sidebar is removed.', 'Christian Technology Ministries International Inc.', 1008000, 0, 0),
