(8482, 0, 'xajax', 1, '0.1.0', 19653, 187, 'xaJax', 'The xajax 0.2 library. xajax is an open source PHP class library that allows you to easily create powerful, web-based, Ajax applications using HTML, CSS, JavaScript, and PHP.  \r\nApplications developed with xajax can asynchronously call server-side PHP fun', 0, 0, 4, 1142275946, 'a:0:{}', 'Elmar Hinz', 'elmar.hinz@team-red.net', 'xajax', 'c90d9a9fff37b41b948fac19d34db175', 'Some warnings eliminated.', 'Team Red', 1000, 0, 0),
(8483, 0, 'xajax', 1, '0.2.0', 19653, 272, 'xaJax', 'The xajax 0.2 library. xajax is an open source PHP class library that allows you to easily create powerful, web-based, Ajax applications using HTML, CSS, JavaScript, and PHP.  \r\nApplications developed with xajax can asynchronously call server-side PHP fun', 1, 0, 4, 1142276071, 'a:0:{}', 'Elmar Hinz', 'elmar.hinz@team-red.net', 'xajax', 'd51e571d6870e8e955985246e1ecc5e9', 'status change', 'Team Red', 2000, 0, 0),
(8484, 0, 'xajax', 1, '0.2.1', 19653, 263, 'xaJax', 'The xajax 0.2.1 library (stable). xajax is a PHP class library that allows you to easily create powerful, web-based, Ajax applications using HTML, CSS, JavaScript, and PHP.', 1, 0, 4, 1142592416, 'a:0:{}', 'Elmar Hinz', 'elmar.hinz@team-red.net', 'xajax', 'e43e2dde091040b049b59247c960e908', 'Update to version 0.2.1 of xajax. For changelog of xajax 0.2.1 see: http://wiki.xajaxproject.org/0.2.1_Release_Notes.\r\nATTENTION: renaming of Classes to TYPO3 standards:  xajax to tx_xajax,  xajaxResponse to tx_xajax_response. See Changelog.\r\n\r\n', 'Team Red', 2001, 0, 0),
(8485, 0, 'xajax', 1, '0.2.3', 19653, 519, 'xaJax', 'The xajax 0.2.3 library (stable). xajax is a PHP class library that allows you to easily create powerful, web-based, Ajax applications using HTML, CSS, JavaScript, and PHP.', 1, 0, 4, 1142863465, 'a:0:{}', 'Elmar Hinz', 'elmar.hinz@team-red.net', 'xajax', '85ceaa4303d00439ea8ded80fca79664', 'Update to version 0.2.3 of xajax. For changelog of xajax 0.2.3 see: http://wiki.xajaxproject.org/0.2.3_Release_Notes. ATTENTION: renaming of Classes to TYPO3 standards: xajax to tx_xajax, xajaxResponse to tx_xajax_response since 0.2.0. See Changelog.', 'Team Red', 2003, 0, 0),
(8486, 0, 'xajax', 1, '0.2.4', 19653, 4434, 'xaJax', 'The handy xajax 0.2.4 library: xajax is a PHP class library that allows you to easily create powerful, web-based, Ajax applications using HTML, CSS, JavaScript, and PHP. You find the documentation within its own extension with the key xajax_tutor.', 2, 0, 4, 1167263189, 'a:0:{}', 'Elmar Hinz, Jared White, J. Max Wilson', 'elmar.hinz@team-red.net', 'xajax', '0ae5df1df1331ca711b62cff0e0a0739', 'Just a small CDATA comment to make it work wit complex URI.', 'Team Red', 2004, 0, 0),
(8487, 0, 'xajax', 1, '0.2.5', 19653, 12990, 'xaJax', 'The handy xajax 0.2.4 library: xajax is a PHP class library that allows you to easily create powerful, web-based, Ajax applications using HTML, CSS, JavaScript, and PHP. You find the documentation within its own extension with the key xajax_tutor.', 2, 0, 4, 1189513623, 'a:0:{}', 'Elmar Hinz, Jared White, J. Max Wilson', 'elmar.hinz@team-red.net', 'xajax', 'fbe57a8d1751e33d483a1f2b51d5f2e8', 'see Changelog', 'Team Red', 2005, 0, 0),
(8488, 0, 'xajax', 1, '0.2.6', 19653, 982, 'xaJax', 'This is a 0.2.x version of the xajax library. This extension will not be migrated to 0.5.x because the API has changed and several extensions depend on this old API. To use the current API please have a look for another extension in TER. More documentatio', 2, 0, 4, 1322824568, 'a:0:{}', 'Elmar Hinz, Jared White, J. Max Wilson', 't3elmar@googelmail.com', 'xajax', '9d89602ef7321897f318dc038a74fb2e', 'Final release. No migration to 0.5.0 because the API has changed.', 'Freelancer', 2006, 1, 0),
