(8529, 0, 'xslite', 1, '1.0.0', 805, 539, 'XSLiTe - Lite XSL Transformer', 'This extension provides a simple new content type with two simple parameters: an external xml file and an external xslt file. The content is generated by transforming xml file through xsl. To work properly, this extension requires PHP with XSLT.', 2, 0, 3, 1133560619, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:0:"";s:3:"php";s:0:"";s:3:"cms";s:0:"";}}', 'Gianni Tommasi', 'gianni.tommasi@animare.it', 'jackthomas', '49f0bad715d77a447ce92c1118813b58', 'First upload', '', 1000000, 0, 0),
(8530, 0, 'xslite', 1, '1.1.0', 805, 26, 'XSLiTe - Lite XSL Transformer', 'This extension provides a simple new content type with two simple parameters: an external xml file and an external xslt file. The content is generated by transforming xml file through xsl. To work properly, this extension requires PHP with XSLT.', 2, 0, 3, 1194806692, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:3:"php";s:6:"3.0.0-";s:5:"typo3";s:6:"3.5.0-";}}', 'Gianni Tommasi', 'gianni.tommasi@animare.it', 'jackthomas', '0184e695548e4ec8da0abca5ae44a9de', 'New function: It manages xslpath and xmlpath variables as input in $_GET or $_POST array for more flexibility (ex: linking a page with more transformation options)', '', 1001000, 0, 0),
