(8780, 0, 'phpunit', 1, '3.2.18', 3363, 26, 'PHPUnit', 'TYPO3 unit testing UI based on PHPUnit ver. 3.2 by Sebastian Bergmann. Part of the ECT effort (Extension Coordination Team).', 1, -1, 1, 1208724790, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"5.2.1-0.0.0";s:5:"typo3";s:9:"4.1-0.0.0";}}', 'Kasper Ligaard', 'ligaard@systime.dk', 'oliklee', 'b8650a74e9f257ca1dcdd6078b08748c', ' Switched to xhtml-rendering. \r\n Fixed some typos, code-beautification. \r\nAll solved in patch from issue 8173, supplied from Oliver Klee.', 'GT3', 3002018, 0, 0),
(8781, 0, 'phpunit', 1, '3.2.19', 3363, 33, 'PHPUnit', 'TYPO3 unit testing UI based on PHPUnit ver. 3.2 by Sebastian Bergmann. Part of the ECT effort (Extension Coordination Team).', 1, -1, 1, 1209053577, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"5.2.1-0.0.0";s:5:"typo3";s:9:"4.1-0.0.0";}}', 'Kasper Ligaard', 'ligaard@systime.dk', 'oliklee', '596e16b365f907e32549d9da5d47311a', ' Added PHPUnit 3.2.19. \r\n- Removed PHPUnit 3.2.18.', 'GT3', 3002019, 0, 0),
