(8783, 0, 'phpunit', 1, '3.2.21', 3363, 23, 'PHPUnit', 'TYPO3 unit testing UI based on PHPUnit ver. 3.2 by Sebastian Bergmann. Part of the ECT effort (Extension Coordination Team).', 1, -1, 1, 1220907279, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"5.2.1-0.0.0";s:5:"typo3";s:9:"4.1-0.0.0";}}', 'Kasper Ligaard', 'kasperligaard@gmail.com', 'oliklee', '9a1fafbd39da50233a5fe3d30a4a7a76', ' Fixed bug where You could be stuck with Extension key NOT loaded [...]. \r\n Solved Forge issues 1316, 1317 and 1320. \r\n Thanks goes to Niels Pardon and Oliver Klee. \r\n(See NEWS file for details).', 'GT3', 3002021, 0, 0),
(8784, 0, 'phpunit', 1, '3.3.0', 3363, 26, 'PHPUnit', 'TYPO3 unit testing UI based on PHPUnit ver. 3.3 by Sebastian Bergmann. Part of the ECT effort (Extension Coordination Team).', 1, -1, 1, 1221768506, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"5.2.1-0.0.0";s:5:"typo3";s:9:"4.1-0.0.0";}}', 'Kasper Ligaard', 'kasperligaard@gmail.com', 'oliklee', 'fc874995ca5b83cdc7c2654899e953e5', ' Added PHPUnit 3.3.0.\r\n- Removed PHPUnit 3.2.21.', 'GT3', 3003000, 0, 0),
(8785, 0, 'phpunit', 1, '3.3.1', 3363, 23, 'PHPUnit', 'TYPO3 unit testing UI based on PHPUnit ver. 3.3 by Sebastian Bergmann. Part of the ECT effort (Extension Coordination Team).', 1, -1, 1, 1222238273, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"5.2.1-0.0.0";s:5:"typo3";s:9:"4.1-0.0.0";}}', 'Kasper Ligaard', 'kasperligaard@gmail.com', 'oliklee', '9574a5d0c974eafe5c4e49a2180c6793', ' Added PHPUnit 3.3.1. \r\n- Removed PHPUnit 3.3.0.', 'GT3', 3003001, 0, 0),
(8786, 0, 'phpunit', 1, '3.3.2', 3363, 26, 'PHPUnit', 'TYPO3 unit testing UI based on PHPUnit ver. 3.3 by Sebastian Bergmann. Part of the ECT effort (Extension Coordination Team).', 1, -1, 1, 1222544301, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"5.2.1-0.0.0";s:5:"typo3";s:9:"4.1-0.0.0";}}', 'Kasper Ligaard', 'kasperligaard@gmail.com', 'oliklee', '4ab683802740b040dd7c59e9962db1f7', ' Added links to forge.typo3.org.\r\n Add the colored bar even when executing single tests. Closes forge 1594. \r\n Javascript for experimental progress bar executed although the option is disabled. Closes forge 1595. \r\n Error when calling non-existing t', 'GT3', 3003002, 0, 0),
(8787, 0, 'phpunit', 1, '3.3.3', 3363, 51, 'PHPUnit', 'TYPO3 unit testing UI based on PHPUnit ver. 3.3 by Sebastian Bergmann. Part of the ECT effort (Extension Coordination Team).', 1, -1, 1, 1222890664, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"5.2.1-0.0.0";s:5:"typo3";s:9:"4.1-0.0.0";}}', 'Kasper Ligaard', 'kasperligaard@gmail.com', 'oliklee', 'ac77c7c1b8998dd9d707db9e69db57a6', ' Display the leaked memory after the tests. Closes forge 1627. Note that this measurement is only indicative; it will be tried out now, but is the utility is limited, then it will be removed or turned into an option.', 'GT3', 3003003, 0, 0),
(8788, 0, 'phpunit', 1, '3.3.4', 3363, 27, 'PHPUnit', 'TYPO3 unit testing UI based on PHPUnit ver. 3.3 by Sebastian Bergmann. Part of the ECT effort (Extension Coordination Team).', 1, -1, 1, 1224450966, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"5.2.3-0.0.0";s:5:"typo3";s:9:"4.2-0.0.0";}}', 'Kasper Ligaard', 'kasperligaard@gmail.com', 'oliklee', '3f4ca4d443a78ca800d7ef510a86e01d', ' Buttons to show/hide success, failure and errors. \r\n Button to turn code coverage collection on/off. \r\n Access keys for running tests. \r\nMany small changes and fixes, cf. the NEWS file.', 'GT3', 3003004, 0, 0),
(8789, 0, 'phpunit', 1, '3.3.5', 3363, 49, 'PHPUnit', 'TYPO3 unit testing UI based on PHPUnit ver. 3.3 by Sebastian Bergmann. Part of the ECT effort (Extension Coordination Team).', 1, -1, 1, 1224520522, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"5.2.3-0.0.0";s:5:"typo3";s:9:"4.2-0.0.0";}}', 'Kasper Ligaard', 'kasperligaard@gmail.com', 'oliklee', 'cde52bc9f4821b18184aaed5053b3d91', ' updated to PHPUnit 3.3.2. \r\n Fix forge 1698: Showing NEWS file from drop-down menu breaks with symlinks.', 'GT3', 3003005, 0, 0),
(8790, 0, 'phpunit', 1, '3.3.6', 3363, 30, 'PHPUnit', 'TYPO3 unit testing UI based on PHPUnit ver. 3.3 by Sebastian Bergmann. Part of the ECT effort (Extension Coordination Team).', 1, -1, 1, 1226327775, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"5.2.3-0.0.0";s:5:"typo3";s:9:"4.2-0.0.0";}}', 'Kasper Ligaard', 'kasperligaard@gmail.com', 'oliklee', 'b9e22a92bba453fc30cc5349b09c8511', ' Added PHPUnit 3.3.4. \r\n- Removed PHPUnit 3.3.2. \r\n Fix forge bug 1828\r\n(See NEWS file for details).', 'GT3', 3003006, 0, 0),
(8791, 0, 'phpunit', 1, '3.3.7', 3363, 35, 'PHPUnit', 'TYPO3 unit testing UI based on PHPUnit ver. 3.3 by Sebastian Bergmann. Part of the ECT effort (Extension Coordination Team).', 1, -1, 1, 1227774936, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"5.2.3-0.0.0";s:5:"typo3";s:9:"4.2-0.0.0";}}', 'Kasper Ligaard', 'kasperligaard@gmail.com', 'oliklee', 'bb8c0f03033b827f92e95ce99e8f219f', ' Added PHPUnit 3.3.5. \r\n- Removed PHPUnit 3.3.4.', 'GT3', 3003007, 0, 0),
(8792, 0, 'phpunit', 1, '3.3.8', 3363, 17, 'PHPUnit', 'TYPO3 unit testing UI based on PHPUnit ver. 3.3 by Sebastian Bergmann. Part of the ECT effort (Extension Coordination Team).', 1, -1, 1, 1235598882, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"5.2.3-0.0.0";s:5:"typo3";s:9:"4.2-0.0.0";}}', 'Kasper Ligaard', 'kasperligaard@gmail.com', 'oliklee', '9a918122c98bdbf68b0fb5026f9214e9', ' Fixes to work with upcoming TYPO3 4.3 release. \r\n Updated to PHPUnit 3.3.15. \r\n- Several other fixes, see NEWS file for changes.', 'GT3', 3003008, 0, 0),
(8793, 0, 'phpunit', 1, '3.3.9', 3363, 14, 'PHPUnit', 'TYPO3 unit testing UI based on PHPUnit ver. 3.3 by Sebastian Bergmann. Part of the ECT effort (Extension Coordination Team).', 1, -1, 1, 1236118521, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"5.2.3-0.0.0";s:5:"typo3";s:9:"4.2-0.0.0";}}', 'Kasper Ligaard', 'kasperligaard@gmail.com', 'oliklee', '16c8130d510e832888d3a025c5c21cf4', ' Test cases can now end in "TestCase". \r\n Unit tests in drop-down box sorted by classnames for improved overview. \r\n Fix background color of drop-down box. \r\n(See NEWS file for details)', 'GT3', 3003009, 0, 0),
(8794, 0, 'phpunit', 1, '3.3.10', 3363, 14, 'PHPUnit', 'TYPO3 unit testing UI based on PHPUnit ver. 3.3 by Sebastian Bergmann. Part of the ECT effort (Extension Coordination Team).', 1, -1, 1, 1236240816, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"5.2.3-0.0.0";s:5:"typo3";s:9:"4.2-0.0.0";}}', 'Kasper Ligaard', 'kasperligaard@gmail.com', 'oliklee', '2171cbc27cee765ca4de57118c4d1a49', ' Fix so test cases with uppercase letters in TestCase can be run.', 'GT3', 3003010, 0, 0),
(8795, 0, 'phpunit', 1, '3.3.11', 3363, 42, 'PHPUnit', 'TYPO3 unit testing UI based on PHPUnit ver. 3.3 by Sebastian Bergmann. Part of the ECT effort (Extension Coordination Team).', 1, -1, 1, 1236278958, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"5.2.3-0.0.0";s:5:"typo3";s:9:"4.2-0.0.0";}}', 'Kasper Ligaard', 'kasperligaard@gmail.com', 'oliklee', '1c3fb20219f0358fe8b3cc4af6f42121', ' Initialize content object (tslib_cObj) on demand, resolves issue 2767.', 'GT3', 3003011, 0, 0),
(8796, 0, 'phpunit', 1, '3.3.12', 3363, 84, 'PHPUnit', 'TYPO3 unit testing UI based on PHPUnit ver. 3.3 by Sebastian Bergmann. Part of the ECT effort (Extension Coordination Team).', 1, -1, 1, 1243114461, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"5.2.3-0.0.0";s:5:"typo3";s:9:"4.2-0.0.0";}}', 'Kasper Ligaard', 'kasperligaard@gmail.com', 'oliklee', 'd7122437c87b8b2186cc149417593d32', ' Run all tests of a test case. \r\n Show skipped tests and total assertions after a run. \r\nA big thanks goes to Michael Klapper. \r\n(See NEWS file for elaboration and details).', 'GT3', 3003012, 0, 0),
(8797, 0, 'phpunit', 1, '3.4.3', 3363, 73, 'PHPUnit', 'TYPO3 unit testing UI based on PHPUnit ver. 3.4 by Sebastian Bergmann. Part of the ECT effort (Extension Coordination Team).', 1, -1, 1, 1262708196, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"5.2.3-0.0.0";s:5:"typo3";s:11:"4.2.0-0.0.0";}}', 'Oliver Klee, Michael Klapper, Kasper Ligaard', 'typo3-coding@oliverklee.de', 'oliklee', '18109f5b71d30efb9454d9afd0fbe58c', 'Bug-fix release.', '', 3004003, 0, 0),
(8798, 0, 'phpunit', 1, '3.4.12', 3363, 218, 'PHPUnit', 'TYPO3 unit testing UI based on PHPUnit by Sebastian Bergmann.', 1, -1, 1, 1272360897, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"5.2.3-0.0.0";s:5:"typo3";s:11:"4.2.0-0.0.0";}}', 'Oliver Klee, Michael Klapper, Kasper Ligaard', 'typo3-coding@oliverklee.de', 'oliklee', '792c53e6f839188b4b6eca7a8184c60c', 'Bug-fix release. Now Test.php files and the Tests/ directory are properly supported.', '', 3004012, 0, 0),
(8799, 0, 'phpunit', 1, '3.5.6', 3363, 114, 'PHPUnit', 'TYPO3 unit testing UI based on PHPUnit by Sebastian Bergmann.', 1, -1, 1, 1293388677, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"5.2.3-0.0.0";s:5:"typo3";s:11:"4.3.0-0.0.0";}}', 'Oliver Klee, Michael Klapper, Kasper Ligaard', 'typo3-coding@oliverklee.de', 'oliklee', 'f3b3a41c1701a6d18845de20af1056d1', 'Updated to PHPUnit 3.5.x, added vfsStream, fixed tons of bugs. Now requires TYPO3  4.3.', '', 3005006, 0, 0),
