(9049, 0, 'caddy', 1, '7.5.7', 0, 0, 'Caddy - responsive Shopping Cart', 'http://typo3-caddy.de. Caddy is the TYPO3 responsive Shopping Cart. It is optimised for desktops, tablets and smartphones. Caddy is e-commerce for small budget and small-scale enterprises. You are welcome to install Caddy with one mouse-click - ready-to-use. See: TYPO3 Quick Shop. Caddy provides ready-to-use templates for both responsive frameworks: bootstrap and foundation. You can use caddy for your own needs with your own database and without Quick Shop. Manual at http://typo3-caddy.deEXT:caddy/doc/manual.pdf. ', 2, 0, 3, 1511567000, 'a:1:{s:7:"depends";a:3:{s:9:"powermail";s:7:"2.25.2-";s:8:"t3_tcpdf";s:0:"";s:5:"typo3";s:12:"6.2.0-7.6.99";}}', 'Dirk Wildt (Die Netzmacher)', 'http://wildt.at.die-netzmacher.de', 'dwildt', '7e4f283b9c665b6fb282fff05e300dab', 'FEATURE: Configurable text color. See Constant Editor. See category [CADDY - HTML - COLORS - ACCORDION]. BUGFIX: Variants (wt_cart style) missed. Missed: Configuration/FlexForms/Pi1/flexform4x.xml.', '', 7005007, 0, 0),
(9050, 0, 'caddy', 1, '7.6.0', 0, 0, 'Caddy - responsive Shopping Cart', 'http://typo3-caddy.de. Caddy is the TYPO3 responsive Shopping Cart. It is optimised for desktops, tablets and smartphones. Caddy is e-commerce for small budget and small-scale enterprises. You are welcome to install Caddy with one mouse-click - ready-to-use. See: TYPO3 Quick Shop. Caddy provides ready-to-use templates for both responsive frameworks: bootstrap and foundation. You can use caddy for your own needs with your own database and without Quick Shop. Manual at http://typo3-caddy.deEXT:caddy/doc/manual.pdf. ', 2, 0, 3, 1512163041, 'a:1:{s:7:"depends";a:3:{s:9:"powermail";s:7:"2.25.2-";s:8:"t3_tcpdf";s:6:"4.0.0-";s:5:"typo3";s:12:"6.2.0-7.6.99";}}', 'Dirk Wildt (Die Netzmacher)', 'http://wildt.at.die-netzmacher.de', 'dwildt', '34b9bb15aa8fd6eab8a137cffbe532a7', 'UPGRADE: t3_tcpdf 4.0, Powermail 4.3. YOU SHOULD include template Powermail 4.x! IMPROVEMENTS: Optimised CSS. Min and max for Caddy isnt supported any longer. BUGFIXES: Small bugfixes. DETAILS @ ChangeLog.', '', 7006000, 0, 0),
(9051, 0, 'caddy', 1, '7.6.1', 0, 0, 'Caddy - responsive Shopping Cart', 'http://typo3-caddy.de. Caddy is the TYPO3 responsive Shopping Cart. It is optimised for desktops, tablets and smartphones. Caddy is e-commerce for small budget and small-scale enterprises. You are welcome to install Caddy with one mouse-click - ready-to-use. See: TYPO3 Quick Shop. Caddy provides ready-to-use templates for both responsive frameworks: bootstrap and foundation. You can use caddy for your own needs with your own database and without Quick Shop. Manual at http://typo3-caddy.deEXT:caddy/doc/manual.pdf. ', 2, 0, 3, 1512236207, 'a:1:{s:7:"depends";a:3:{s:9:"powermail";s:7:"2.25.2-";s:8:"t3_tcpdf";s:6:"4.0.0-";s:5:"typo3";s:12:"6.2.0-7.6.99";}}', 'Dirk Wildt (Die Netzmacher)', 'http://wildt.at.die-netzmacher.de', 'dwildt', 'c3a394f8b73af27b4205f45521f1e7ea', 'UPGRADE for Powermail 4.x: fieldwraps got the additional CSS class "columns large-6". See Constant Editor of Powermail. Toogling delivery address is fixed. Details @ ChangeLog.', '', 7006001, 1, 0),
