(9129, 0, 'nbo_podcast', 1, '1.0.0', 4465, 313, 'Typo3 Podcast Extension', 'This extension adds podcast functionality to Typo3. Works together with fe_mp3player to play podcast in FrontEnd. Support for iTunes, images, export to xml file. With context sensitive help. Use utf-8 encoding in the backend ($TYPO3_CONF_VARS["BE"]["force', 2, 0, 3, 1144655518, 'a:0:{}', 'Noel Bossart', 'noel@jesus.ch', 'noelboss', 'ecf1f4bf234f0e7903d034f48b902026', 'Fixed bug where Typo3 4.0 caused xml-encryption to break. Fixed TTL and language bug. No known bugs: first stable release. USE UTF-8 ENDCODING in the backend to enshure encryptoion works correct: $TYPO3_CONF_VARS["BE"]["forceCharset"]', 'noelboss.ch', 1000000, 0, 0),
(9130, 0, 'nbo_podcast', 1, '2.0.0', 4465, 396, 'Typo3 Podcast Extension', 'This extension adds podcast functionality to Typo3. It also works with the extension fe_mp3player to play the podcast in the forntend. This Extenion can export the feed to an external xml file. Documentation see www.noelboss.ch/en/extensions/', 1, 0, 3, 1142046426, 'a:0:{}', 'Noel Bossart', 'noel@jesus.ch', 'noelboss', '2ae38c0a08767a0cff778bfd672b3cc1', 'Updated whole Extension! Changed architecture. NEW backend modul to easily create and delete Podcast feeds. Added content sensitive help. REMEOVED frontend player part. The extension fe_mp3player has now nbo_podcast support (THNX Jean!). Use this to play', 'noelboss.ch', 2000000, 0, 0),
(9131, 0, 'nbo_podcast', 1, '1.0.1', 4465, 221, 'Typo3 Podcast Extension', 'iTunes compatible Podcast-Extension for Typo3. Works seamlessly together with fe_mp3player to play Podcasts in the FE. Special features: images, block, explicit... Handy integrated in Typo3.', 2, 0, 3, 1153215740, 'a:0:{}', 'Noel Bossart', 'noel@jesus.ch', 'noelboss', '4d3af1371829bb9c328291b4dc60efc1', 'Fixed minor bugs in feed validation. Added important conf-flag "invert" (default  true) in the install-section! Now the last element in the flex-form will appear as the first in the xml. So you dont have to click a new element to the top of the list!', 'noelboss.ch', 1000001, 0, 0),
(9132, 0, 'nbo_podcast', 1, '1.0.2', 4465, 202, 'Typo3 Podcast Extension', 'iTunes compatible Podcast-Extension for Typo3. Works seamlessly together with fe_mp3player to play Podcasts in the FE. Special features: images, block, explicit... Handy integrated in Typo3.', 2, 0, 3, 1153238824, 'a:0:{}', 'Noel Bossart', 'noel@jesus.ch', 'noelboss', '206ce1261d2af4d3c48bdee0ee644f57', 'Fixed minor bugs in feed validation. Added important conf-flag "invert" (default true) in the install-section! Now the last element in the flex-form will appear as the first in the xml. So you dont have to click a new element to the top of the list!', 'noelboss.ch', 1000002, 0, 0),
(9133, 0, 'nbo_podcast', 1, '1.0.3', 4465, 226, 'Typo3 Podcast Extension', 'iTunes compatible Podcast-Extension for Typo3. Works seamlessly together with fe_mp3player to play Podcasts in the FE. Special features: images, block, explicit... Handy integrated in Typo3.', 2, 0, 3, 1153384783, 'a:0:{}', 'Noel Bossart', 'noel@jesus.ch', 'noelboss', '89f619af0cd4a28fa27e3c8b5219ecdb', 'Fixed minor bugs in feed validation. Added important conf-flag "invert" (default true) in the install-section! Now the last element in the flex-form will appear as the first in the xml. So you dont have to click a new element to the top of the list!', 'noelboss.ch', 1000003, 0, 0),
(9134, 0, 'nbo_podcast', 1, '1.1.0', 4465, 229, 'Typo3 Podcast Extension', 'iTunes compatible Podcast-Extension for Typo3. Works seamlessly together with fe_mp3player to play Podcasts in the FE. Special features: images, block, explicit... Handy integrated in Typo3.', 2, 0, 3, 1153729031, 'a:0:{}', 'Noel Bossart', 'noel@jesus.ch', 'noelboss', 'f13545fb3f06a5a04958acb5a46614b7', 'Fixed: No encoding problems anymore! Added: Support for formats other than mp3 now! Added: Keyword field for iTunes. Added: Support for custom export folders. Updated Manual.', 'noelboss.ch', 1001000, 0, 0),
(9135, 0, 'nbo_podcast', 1, '1.1.1', 4465, 164, 'Typo3 Podcast Extension', 'iTunes compatible Podcast-Extension for Typo3. Works seamlessly together with fe_mp3player to play Podcasts in the FE. Special features: images, block, explicit... Handy integrated in Typo3.', 2, 0, 3, 1153915668, 'a:0:{}', 'Noel Bossart', 'noel@jesus.ch', 'noelboss', '6235c49d153ab1e1520155d5c55f5a47', 'Fixed: No encoding problems anymore! Added: Support for formats other than mp3 now! Added: Keyword field for iTunes. Added: Support for custom export folders. Updated Manual.', 'noelboss.ch', 1001001, 0, 0),
(9136, 0, 'nbo_podcast', 1, '1.1.2', 4465, 320, 'Typo3 Podcast Extension', 'iTunes compatible Podcast-Extension for Typo3. Works seamlessly together with fe_mp3player to play Podcasts in the FE. Special features: images, block, explicit... Handy integrated in Typo3.', 2, 0, 3, 1153984369, 'a:1:{s:7:"depends";a:4:{s:3:"cms";s:0:"";s:4:"lang";s:0:"";s:3:"php";s:6:"3.0.0-";s:5:"typo3";s:6:"3.5.0-";}}', 'Noel Bossart', 'noel@jesus.ch', 'noelboss', 'b05091522ff3821fba382773527f0ba6', 'Fixed: No encoding problems anymore! Added: Support for formats other than mp3 now! Added: Keyword field for iTunes. Added: Support for custom export folders. Now compatible with Typo3  4.0', 'noelboss.ch', 1001002, 0, 0),
(9137, 0, 'nbo_podcast', 1, '1.1.3', 4465, 17, 'Typo3 Podcast Extension', 'iTunes compatible Podcast-Extension for Typo3. Works seamlessly together with fe_mp3player to play Podcasts in the FE. Special features: images, block, explicit... Handy integrated in Typo3.', 2, 0, 3, 1161594429, 'a:1:{s:7:"depends";a:4:{s:3:"cms";s:0:"";s:4:"lang";s:0:"";s:3:"php";s:6:"3.0.0-";s:5:"typo3";s:6:"3.5.0-";}}', 'Noel Bossart', 'noel@jesus.ch', 'noelboss', '1a8a17f89556e8dc5ce57a9bd8dee79a', 'Extended Tag is no capable of having values "Yes" "No" and "Clean". Clean allows Podcasts to be marked as convenient for children, meaning that no explicit language or adult content is included anywhere in the episodes, and a "clean" graphic will appear i', 'noelboss.ch', 1001003, 0, 0),
(9138, 0, 'nbo_podcast', 1, '1.1.4', 4465, 437, 'Typo3 Podcast Extension', 'iTunes compatible Podcast-Extension for Typo3. Works seamlessly together with fe_mp3player to play Podcasts in the FE. Special features: images, block, explicit... Handy integrated in Typo3.', 2, 0, 3, 1161594441, 'a:1:{s:7:"depends";a:4:{s:3:"cms";s:0:"";s:4:"lang";s:0:"";s:3:"php";s:6:"3.0.0-";s:5:"typo3";s:6:"3.5.0-";}}', 'Noel Bossart', 'noel@jesus.ch', 'noelboss', 'bfb8a1b87d8ce43a1111069ecb630c64', 'Explicit Tag is no capable of having values "Yes" "No" and "Clean". Clean allows Podcasts to be marked as convenient for children, meaning that no explicit language or adult content is included anywhere in the episodes, and a "clean" graphic will appear i', 'noelboss.ch', 1001004, 0, 0),
(9139, 0, 'nbo_podcast', 1, '1.1.5', 4465, 238, 'Typo3 Podcast Extension', 'iTunes compatible Podcast-Extension for Typo3. Works seamlessly together with fe_mp3player to play Podcasts in the FE. Special features: images, block, explicit... Handy integrated in Typo3.', 2, 0, 3, 1174902998, 'a:1:{s:7:"depends";a:4:{s:3:"cms";s:0:"";s:4:"lang";s:0:"";s:3:"php";s:11:"3.0.0-0.0.0";s:5:"typo3";s:11:"3.5.0-0.0.0";}}', 'Noel Bossart', 'noel@jesus.ch', 'noelboss', '5126e7213da326835c4a5b1422169b99', 'Minor Update, recommended. Fixes wrong filepath which caused missing length attribute in the enclosure-tag. Filesze is now determined correctly.', 'noelboss.ch', 1001005, 0, 0),
(9140, 0, 'nbo_podcast', 1, '1.1.6', 4465, 210, 'Typo3 Podcast Extension', 'iTunes compatible Podcast-Extension for Typo3. Works seamlessly together with fe_mp3player to play Podcasts in the FE. Special features: images, block, explicit... Handy integrated in Typo3.', 2, 0, 3, 1180940937, 'a:1:{s:7:"depends";a:4:{s:3:"cms";s:0:"";s:4:"lang";s:0:"";s:3:"php";s:12:"4.2.2-5.1.99";s:5:"typo3";s:11:"4.0.0-0.0.0";}}', 'Noel Bossart', 'noel@jesus.ch', 'noelboss', '488f3922eca1dad9f957dbd7720c0a26', 'Added language-field to Podcast-Records. Each Podcast can have its own languag-code now. Global Configuration in Ext. Manager still possible.', 'noelboss.ch', 1001006, 0, 0),
(9141, 0, 'nbo_podcast', 1, '1.1.7', 4465, 160, 'Typo3 Podcast Extension', 'iTunes compatible Podcast-Extension for Typo3. Works seamlessly together with fe_mp3player to play Podcasts in the FE. Special features: images, block, explicit... Handy integrated in Typo3.', 2, 0, 3, 1191831577, 'a:1:{s:7:"depends";a:4:{s:3:"cms";s:0:"";s:4:"lang";s:0:"";s:3:"php";s:12:"4.2.2-5.1.99";s:5:"typo3";s:11:"4.0.0-0.0.0";}}', 'Noel Bossart', 'noel@jesus.ch', 'noelboss', '4ccf5b525814676e943465b307fb0f49', 'This update is recommended for all users and improves \r\nthe handling of files and paths containing special-chairs and spaces.', 'noelboss.ch', 1001007, 0, 0),
(9142, 0, 'nbo_podcast', 1, '2.0.2', 4465, 557, 'Typo3 Podcast Extension', 'iTunes compatible Podcast-Extension for Typo3. Works together with fe_mp3player to play Podcasts in the FE with a flash-based player.', 2, 0, 3, 1200317659, 'a:1:{s:7:"depends";a:4:{s:3:"cms";s:0:"";s:4:"lang";s:0:"";s:3:"php";s:11:"4.2.2-0.0.0";s:5:"typo3";s:11:"4.0.0-0.0.0";}}', 'Noel Bossart', 'noel@jesus.ch', 'noelboss', 'adf4fc36697744c3d1ae00ebba8a1326', 'This update is recommended for all users and improves the backend as well as the feed. Rearranged backed and added channel-keywords. iTunes categories added. DB update required. Uploads directory required for channel image.', 'noelboss.ch', 2000002, 0, 0),
(9143, 0, 'nbo_podcast', 1, '2.0.3', 4465, 216, 'Typo3 Podcast Extension', 'iTunes compatible Podcast-Extension for Typo3. Works together with fe_mp3player to play Podcasts in the FE with a flash-based player.', 2, 0, 3, 1288191618, 'a:1:{s:7:"depends";a:5:{s:3:"cms";s:0:"";s:4:"lang";s:0:"";s:3:"php";s:11:"4.2.2-0.0.0";s:5:"typo3";s:11:"4.0.0-0.0.0";s:11:"api_macmade";s:5:"0.4.7";}}', 'Nol Bossart', 'n.company@me.com', 'noelboss', 'ac3bd77ec9a4566ec400f177368ee510', 'Testet with Typo3 4.4  Fixed document-root handling for Typo3 installations inside a sub-directory. Added support for files hosted on an external server. Changed category field to free-text. Updated manual.', 'noelboss.ch', 2000003, 1, 0),
