(9344, 0, 'wec_servant', 1, '0.9.1', 2445, 229, 'WEC Servant Connector', 'Connect people with ministry/service opportunities that you have. Can match by categories/skills/interests/dates. Especially built for churches and ministries, but can be useful for other organizations.', 1, 0, 3, 1143224084, 'a:0:{}', 'Web-Empowered Church Team', 'servant@webempoweredchurch.org', 'webempoweredchurch', '1ec6c94b437482a1f27d05338bbfc6a6', 'Made XHTML compliant.', '', 9001, 0, 0),
(9345, 0, 'wec_servant', 1, '0.9.2', 2445, 53, 'WEC Servant Connector', 'Connect people with ministry/service opportunities that you have. Can match by categories/skills/interests/dates. Especially built for churches and ministries, but can be useful for other organizations.', 1, 0, 3, 1143557141, 'a:0:{}', 'Web-Empowered Church Team', 'servant@webempoweredchurch.org', 'webempoweredchurch', '2500c5196eca6948ca5624f994e30266', 'Fixed bug with signing up. Added address, city, state, zip preloaded for logged in user.', '', 9002, 0, 0),
(9346, 0, 'wec_servant', 1, '0.9.3', 2445, 213, 'WEC Servant Connector', 'Connect people with ministry/service opportunities that you have. Can match by categories/skills/interests/dates. Especially built for churches and ministries, but can be useful for other organizations.', 1, 0, 3, 1148760779, 'a:0:{}', 'Web-Empowered Church Team', 'servant@webempoweredchurch.org', 'webempoweredchurch', '1180cb2e2de500f400e6842b04992f65', 'Added confirm to delete buttons on admin menu. Fixed minor CSS issues. Added Show All for Search by Ministry so can see all opportunities easily. Add select all/clear all for list of opportunities.', '', 9003, 0, 0),
(9347, 0, 'wec_servant', 1, '0.9.4', 2445, 240, 'WEC Servant Connector', 'Connect people with ministry/service opportunities that you have. Can match by categories/skills/interests/dates. Especially built for churches and ministries, but can be useful for other organizations.', 1, 0, 3, 1149696307, 'a:0:{}', 'Web-Empowered Church Team', 'servant@webempoweredchurch.org', 'webempoweredchurch', '9994336db810bb450c3544555b703487', 'Added ability to commit to a ministry (called Custom Ministry), if cannot find one that fits. Also, handle the notify better and fixed a bug with that if have multiple emails. Added header text in Flexform so you do not	have to edit the template.', '', 9004, 0, 0),
(9348, 0, 'wec_servant', 1, '0.9.5', 2445, 216, 'WEC Servant Connector', 'Connect people with ministry/service opportunities that you have. Can match by categories/skills/interests/dates. Especially built for churches and ministries, but can be useful for other organizations.', 1, 0, 3, 1153168775, 'a:0:{}', 'Web-Empowered Church Team', 'servant@webempoweredchurch.org', 'webempoweredchurch', 'dc940f317504c97508402afe1828c386', 'Allow ministry contacts to add a new opportunity. Allow admins 	to be only over a given ministry (see Administrator in Flexform), added stats tracking & system for admins. Added Danish translation (thanks Frederik M!);', '', 9005, 0, 0),
(9349, 0, 'wec_servant', 1, '0.9.6', 2445, 289, 'WEC Servant Connector', 'Connect people with ministry/service opportunities that you have. Can match by categories/skills/interests/dates. Especially built for churches and ministries, but can be useful for other organizations.', 1, 0, 3, 1159563033, 'a:0:{}', 'Web-Empowered Church Team', 'servant@webempoweredchurch.org', 'webempoweredchurch', '4d727313a084655bf6c7db02b93f2dac', 'Added print button for page capabililty. Also receive a signup confirmation  which can print. Fixed the email from so if set contact email will be used (handles spam filtering better).', '', 9006, 0, 0),
(9350, 0, 'wec_servant', 1, '1.0.0', 2445, 180, 'WEC Servant Matcher', 'Matches people with ministry and/or service opportunities that you have. Can match by categories, skills, interests, dates. Especially built for churches and ministries, but can be useful for other organizations.', 2, 0, 3, 1172094520, 'a:0:{}', 'Web-Empowered Church Team', 'servant@webempoweredchurch.org', 'webempoweredchurch', 'ddcea5c4aa0eb488c74f814d2cebb38b', 'Renamed from Servant Connector to Servant Matcher. Fixed problem with no contact for opportunity will go to admin email now. Allow newlines and HTML tags in descriptions and qualifications fields. Added optional FIND_BY_MINISTRIES which will', '', 1000000, 0, 0),
(9351, 0, 'wec_servant', 1, '1.0.1', 2445, 262, 'WEC Servant Matcher', 'Matches people with ministry and/or service opportunities that you have. Can match by categories, skills, interests, dates. Especially built for churches and ministries, but can be useful for other organizations.', 2, 0, 3, 1172174444, 'a:0:{}', 'Web-Empowered Church Team', 'servant@webempoweredchurch.org', 'webempoweredchurch', '240987c57cbe5fb81cd2a15ef1e06266', 'Fixed bug with radio button markers on signup form (could cause PHP error) and bug with filling in and validating values.', '', 1000001, 0, 0),
(9352, 0, 'wec_servant', 1, '1.0.2', 2445, 45, 'WEC Servant Matcher', 'Matches people with service/volunteer opportunities that you have. Can match by categories, skills, interests, dates, or priorities. Built for churches and ministries, but can be useful for other organizations.', 2, 0, 3, 1182349518, 'a:0:{}', 'Web-Empowered Church Team', 'servant(at)webempoweredchurch.org', 'webempoweredchurch', 'b2573e6597c95fd20013c1e9e3f8b452', 'Add a single view. Can pass in showskills_any or showskills_all as GET param to show given skills. Link to Staff Directory as option. Description, misc description, and qualifications are RTE fields in Backend. Only shows skills/interests that are associa', '', 1000002, 0, 0),
(9353, 0, 'wec_servant', 1, '1.0.3', 2445, 52, 'WEC Servant Matcher', 'Matches people with service/volunteer opportunities that you have. Can match by categories, skills, interests, dates, or priorities. Built for churches and ministries, but can be useful for other organizations.', 2, 0, 3, 1183748747, 'a:0:{}', 'Web-Empowered Church Team', 'servant(at)webempoweredchurch.org', 'webempoweredchurch', '671789b35db0a43af420ea6bc003c8a4', ' Fixed extra div in template and minor template issues. Fixed error reporting HTML formatting. Made XHTML compatible.', '', 1000003, 0, 0),
(9354, 0, 'wec_servant', 1, '1.0.4', 2445, 75, 'WEC Servant Matcher', 'Matches people with service/volunteer opportunities that you have. Can match by categories, skills, interests, dates, or priorities. Built for churches and ministries, but can be useful for other organizations.', 2, 0, 3, 1190146626, 'a:0:{}', 'Web-Empowered Church Team', 'servant(at)webempoweredchurch.org', 'webempoweredchurch', '80620d7ed89ecbf29a7a45951f2adccf', 'FIXED: send out notify_email, wiz_icon file missing, handle start/end times. UPDATED: template and CSS fixes for buttons, templates, centering.  Print Page prints directly. Removed most inline CSS from templates and code.', '', 1000004, 0, 0),
(9355, 0, 'wec_servant', 1, '1.1.0', 2445, 71, 'WEC Servant Matcher', 'Matches people with service/volunteer opportunities that you have. Can match by categories, skills, interests, dates, or priorities. Built for churches and ministries, but can be useful for other organizations.', 2, 0, 3, 1205870180, 'a:0:{}', 'Web-Empowered Church Team', 'servant(at)webempoweredchurch.org', 'webempoweredchurch', 'dafd75f68313914bf7a437d92e349253', 'Added Static templates (must add to ext template). Fixed problem with email / contact name. All getvars now are plugin-based.', '', 1001000, 0, 0),
(9356, 0, 'wec_servant', 1, '1.1.1', 2445, 77, 'WEC Servant Matcher', 'Matches people with service/volunteer opportunities that you have. Can match by categories, skills, interests, dates, or priorities. Built for churches and ministries, but can be useful for other organizations.', 2, 0, 3, 1214323844, 'a:1:{s:7:"depends";a:1:{s:3:"cms";s:0:"";}}', 'Web-Empowered Church Team', 'servant(at)webempoweredchurch.org', 'webempoweredchurch', '7bc08884c3f06229120428217b6a9c8a', 'Added option to allow to view all ministries or skills initially. Fixed strlen display issue. XHTML problems fixed. Ministries(fe_usergroups) now can be in multiple folders and only match if have opportunities that match.', '', 1001001, 0, 0),
(9357, 0, 'wec_servant', 1, '1.2.0', 2445, 91, 'WEC Servant Matcher', 'Matches people with service/volunteer opportunities that you have. Can match by categories, skills, interests, dates, or priorities. Built for churches and ministries, but can be useful for other organizations.', 2, 0, 3, 1225600458, 'a:1:{s:7:"depends";a:1:{s:3:"cms";s:0:"";}}', 'Web-Empowered Church Team', 'servant(at)webempoweredchurch.org', 'webempoweredchurch', 'b06e79c853c5ea5b89a23916ad206204', 'Support multiple languages in records. Can just show ministry opportunities (no matching) with viewMinistryOpps option. Fixed problem with matching any skills.  Fixed XHTML validation issues.', '', 1002000, 0, 0),
(9358, 0, 'wec_servant', 1, '2.0.0', 2445, 16, 'WEC Servant Matcher', 'Matches people with service opportunities that your organization may have. Can match by categories, skills, interests, dates, or priorities. Built for churches and ministries, but can be useful for other organizations.', 2, 0, 3, 1268654274, 'a:1:{s:7:"depends";a:1:{s:3:"cms";s:0:"";}}', 'Web-Empowered Church Team', 'devteam(at)webempoweredchurch.org', 'webempoweredchurch', '4614c039aec3b11a4610cad155f0fc8d', 'Updated templates and CSS to new and improved look with standard base CSS. Can use existing templates or upgrade to newer templates. Added support for versioning/workspaces. All functions are now PHP 5.x compatible.', '', 2000000, 0, 0),
(9359, 0, 'wec_servant', 1, '2.0.1', 2445, 105, 'WEC Servant Matcher', 'Matches people with service opportunities that your organization may have. Can match by categories, skills, interests, dates, or priorities. Built for churches and ministries, but can be useful for other organizations.', 2, 0, 3, 1279938263, 'a:1:{s:7:"depends";a:1:{s:3:"cms";s:0:"";}}', 'Web-Empowered Church Team', 'devteam(at)webempoweredchurch.org', 'webempoweredchurch', '3407e59ee4beb33d390fe471e82fbe6a', 'Updated and improved CSS; fixed so can set and view all ministryOpps; removed deprecated functions.', '', 2000001, 1, 0),
