(9509, 0, 'ffiframe', 1, '1.0.1', 3954, 480, 'Flexform based IFrame', 'Inserts an IFRAME to display content of another URL inside the page. Using flexform instead of extending table tt_content.', 2, 0, 3, 1143039634, 'a:0:{}', 'Peter Klein', 'peter@umloud.dk', 'pmk65', 'e5cec0faa58084907c7b45f552a94939', '', 'Umloud Untd', 1000001, 0, 0),
(9510, 0, 'ffiframe', 1, '1.1.0', 3954, 2302, 'Flexform based IFrame', 'Inserts an IFRAME to display content of another URL inside the page. Totally configurable using either flexform or typoscript. Includes option to resize the the iframe to match the height of the content.', 2, 0, 3, 1144448169, 'a:0:{}', 'Peter Klein', 'peter@umloud.dk', 'pmk65', 'fddf315b186c851d5a679a3d2584c12a', 'Frameborder parameter was set incorrectly, as default for an IFRAME is "frameborder1", but the plugin assumed that it was "frameborder0"\r\n\r\nURLs are now parsed through the typolink function, so now its possible to link to internal TYPO3 pages as well.\r\n', 'Umloud Untd', 1001000, 0, 0),
(9511, 0, 'ffiframe', 1, '2.0.1', 3954, 1172, 'Flexform based IFrame', 'Inserts an IFRAME to display content of another URL inside the page. Totally configurable using either flexform or typoscript. Includes option to resize the the iframe to match the height of the content.', 2, 0, 3, 1252837585, 'a:0:{}', 'Peter Klein, Andreas Otto', 'peter@umloud.dk, a.otto@sma.de', 'pmk65', '576d23b3eefb671fc882c6644f42f376', 'Support for appending GET parameters to the IFrame URL automatically.', 'Umloud Untd, SMA Solar Technology AG', 2000001, 1, 0),
