(9539, 0, 'addressgroups', 1, '1.0.0', 3102, 284, 'Groups / Categories for tt_address', 'Adds Groups / Categories to tt_address records with a treeview similar to that known from DAM and tt_news. Groups / Categories can be nested. In FE addresses can be displayed by selecting single records and by selecting categories in a plugin.', 2, 0, 3, 1143239237, 'a:0:{}', 'Ingo Renner', 'typo3@ingo-renner.com', 'flyguide', '1d5855800213b92cba3878a7b5385d14', 'initial upload', '', 1000000, 0, 0),
(9540, 0, 'addressgroups', 1, '1.1.0', 3102, 280, 'Groups / Categories for tt_address', 'Adds Groups / Categories to tt_address records with a treeview similar to that known from DAM and tt_news. Groups / Categories can be nested. In FE addresses can be displayed by selecting single records and by selecting categories in a plugin.', 2, 0, 3, 1144622940, 'a:0:{}', 'Ingo Renner', 'typo3@ingo-renner.com', 'flyguide', '9b1f2cf72f204172b8066f0451c7b898', 'added image rendering and recusive selection for pidList in TS', '', 1001000, 0, 0),
(9541, 0, 'addressgroups', 1, '1.2.0', 3102, 449, 'Groups / Categories for tt_address', 'Adds Groups / Categories to tt_address records with a treeview similar to that known from DAM and tt_news. Groups / Categories can be nested. In FE addresses can be displayed by selecting single records and by selecting categories in a plugin.', 2, 0, 3, 1145394927, 'a:0:{}', 'Ingo Renner', 'typo3@ingo-renner.com', 'flyguide', '36534a3eeafae4c8722e3dc5a2cb7745', 'added sorting, sorting is configurable by tt_address columns, descending and ascending. also added full stdWrap support for template markers', '', 1002000, 0, 0),
(9542, 0, 'addressgroups', 1, '1.3.0', 3102, 367, 'Groups for tt_address', 'Adds Groups to tt_address records with a treeview similar to that known from DAM and tt_news. Groups can be nested. In FE addresses can be displayed by selecting single records and by selecting groups in a plugin. Additionally the plugin supports multiple', 2, 0, 3, 1147101104, 'a:0:{}', 'Ingo Renner', 'typo3@ingo-renner.com', 'flyguide', '8dceffbc482275f5b7e20af1b4b408cc', 'added localizatio support for group titles', 'ingo-renner.com', 1003000, 0, 0),
