(9673, 0, 'register4cal', 1, '0.2.2', 806, 18, 'Registrations for calender events', 'Provides a registration form so that users can register for the events', 1, 0, 3, 1237484087, 'a:1:{s:7:"depends";a:1:{s:3:"cal";s:0:"";}}', 'Thomas Ernst', 'typo3@thernst.de', 'thernst', '81b809c0215d91e92de3b7a878081734', '- Bug: Timezone conversion must not be performed for allday-events\r\n- Status now "Beta" as extension runs well on my site.', '', 2002, 0, 0),
(9674, 0, 'register4cal', 1, '0.2.3', 806, 15, 'Registrations for calender events', 'Provides a registration form so that users can register for the events', 1, 0, 3, 1239216142, 'a:1:{s:7:"depends";a:1:{s:3:"cal";s:0:"";}}', 'Thomas Ernst', 'typo3@thernst.de', 'thernst', '61b1dee9cc9b6cec9e2048730e59b6db', 'Participant list was always empty unless displayed in admin mode\r\n\r\nRegistrations will now be deleted when the related event is being deleted in the backend', '', 2003, 0, 0),
(9675, 0, 'register4cal', 1, '0.2.4', 806, 17, 'Registrations for calender events', 'Provides a registration form so that users can register for the events', 1, 0, 3, 1239355995, 'a:1:{s:7:"depends";a:1:{s:3:"cal";s:0:"";}}', 'Thomas Ernst', 'typo3@thernst.de', 'thernst', 'a5915776530c64ce065bca73f0a0f774', 'Additional event fields can now be used in the frontend editing of the cal extension.', '', 2004, 0, 0),
(9676, 0, 'register4cal', 1, '0.2.6', 806, 20, 'Registrations for calender events', 'Provides a registration form so that users can register for the events', 1, 0, 3, 1240862126, 'a:1:{s:7:"depends";a:1:{s:3:"cal";s:0:"";}}', 'Thomas Ernst', 'typo3@thernst.de', 'thernst', 'bd953527511de202338592dae4d33bf5', 'Subversion repository now available via forge.typo3.org, rlmp_dateselectlib can now be used,\r\nFE-Editing: Fields "Start/End of registration period" should remain empty, if nothing has been entered. (Bug 3166)\r\n, \r\n', '', 2006, 0, 0),
(9677, 0, 'register4cal', 1, '0.3.0', 806, 21, 'Registrations for calender events', 'Enables a registration functionality which can be used in connection with the CAL extension. Registration form can be displayed with the CAL event display, list of registrations for user and organizer are displayable via plugins', 1, 0, 3, 1242362313, 'a:1:{s:7:"depends";a:1:{s:3:"cal";s:0:"";}}', 'Thomas Ernst', 'typo3@thernst.de', 'thernst', '7f4f83f012f93a9f783a5473c4db2a6f', 'Complete revision of extension. Substantial changes in templates, TypoScript, etc. (Feature 3190): All fields from user, registration and event tables can be used as markers.  Nearly unlimited markers can be configured via TypoScript. Marker layout now de', '', 3000, 0, 0),
(9678, 0, 'register4cal', 1, '0.3.1', 806, 20, 'Registrations for calender events', ' Adds a registration functionality to the CAL extension. The registration form can be displayed with the event display of the CAL extension. Lists of registrations for users and organizers can be displayed via plugins. Confirmation and notification emails', 1, 0, 3, 1243755639, 'a:1:{s:7:"depends";a:1:{s:3:"cal";s:0:"";}}', 'Thomas Ernst', 'typo3@thernst.de', 'thernst', 'd6a504e28f172d9fd1373c216336f650', 'Bug 3459: Display of registrations, even if no user was loged in, Bug 3438: No events in participants list caused errors, Feature 3168: Work together with extension onetimeaccount, Feature 3439: Markers for location and organizer fields', '', 3001, 0, 0),
(9679, 0, 'register4cal', 1, '0.3.2', 806, 27, 'Registrations for calender events', 'Adds a registration functionality to the CAL extension. The registration form can be displayed with the event display of the CAL extension. Lists of registrations for users and organizers can be displayed via plugins. Confirmation and notification emails', 1, 0, 3, 1244348594, 'a:1:{s:7:"depends";a:1:{s:3:"cal";s:0:"";}}', 'Thomas Ernst', 'typo3@thernst.de', 'thernst', 'c821b537709a9ab32b391f40a26709a3', 'Some debugging messages where left in coding. No functional changes.', '', 3002, 0, 0),
