(9839, 0, 'daimi_event', 1, '0.10.0', 4266, 198, 'Daimi Event Management', 'Manages events in the IT-City and related institutions. Build for closely related websites, to easy exchange events among them. Features includes: categories, registration, price categories (build on flexform to relate price categories to specific prices', 1, 0, 3, 1182957300, 'a:1:{s:7:"depends";a:4:{s:3:"cms";s:0:"";s:10:"mth_feedit";s:5:"0.2.4";s:3:"php";s:11:"5.1.1-0.0.0";s:5:"typo3";s:11:"4.0.0-0.0.0";}}', ' Kasper Ligaard', 'ligaard@daimi.au.dk', 'daimi', '72d4358885051c6c7f6a30761723ce14', ' EAN. \r\n Notes on participants. \r\n Human readable price category saved with participant.\r\n New Changelog format. \r\n(See Chancelog for elaboration).', 'Department of Computer Science - Daimi', 10000, 0, 0),
(9840, 0, 'daimi_event', 1, '0.10.1', 4266, 90, 'Daimi Event Management', 'Manages events in the IT-City and related institutions. Build for closely related websites, to easy exchange events among them. Features includes: categories, registration, price categories (build on flexform to relate price categories to specific prices ', 1, 0, 3, 1253014076, 'a:1:{s:7:"depends";a:4:{s:3:"cms";s:0:"";s:10:"mth_feedit";s:5:"0.2.4";s:3:"php";s:11:"5.1.1-0.0.0";s:5:"typo3";s:11:"4.0.0-0.0.0";}}', ' Kasper Ligaard', 'ligaard@daimi.au.dk', 'daimi', 'd18e3a67494b801db87510034b1c7897', '- Updated manual. \r\n- Fixed bug in listview, when there are more that 10 participants records.', 'Department of Computer Science - Daimi', 10001, 1, 0),
(9841, 0, 'shop_manager', 1, '1.0.7', 636, 0, 'Shop System Manager Module', 'Shop System (tt_products) management system. This is backend module with 2 sections. With "Catalog Items" you can manage shop categories and items pretty simple. "Categories Manager" is a useful order status manager with customers e-mail notification support.', 2, 0, 1, 1441559022, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:12:"5.2.0-5.5.99";s:5:"typo3";s:12:"4.1.0-6.2.99";}}', 'Semyon Vyskubov', 'sv@rv7.ru', 'semyonv', '9e2fc1ca34921bee2543b20c819f121b', 'TYPO3 version 6 ready (thanks to @mschulte63)', '', 1000007, 1, 0),
(9842, 0, 'shop_manager', 1, '0.1.0', 636, 260, 'Shop System Manager Module', 'Shop System (tt_products) management. Easy to use Catalog Items and Categories manager  Useful orders statuses manager with customers e-mail notifier.', 1, 0, 1, 1260052966, 'a:1:{s:7:"depends";a:1:{s:11:"tt_products";s:5:"2.6.1";}}', 'Semyon Vyskubov', 'sv@rv7.ru', 'semyonv', '0ab3f5cec93eb5642004a72f669edede', 'Initial beta-release', '', 1000, 0, 0),
(9843, 0, 'shop_manager', 1, '0.2.0', 636, 34, 'Shop System Manager Module', 'Shop System (tt_products) management. Easy to use Catalog Items and Categories manager  Useful orders statuses manager with customers e-mail notifier.', 1, 0, 1, 1287523748, 'a:1:{s:7:"depends";a:1:{s:11:"tt_products";s:5:"2.6.1";}}', 'Semyon Vyskubov', 'sv@rv7.ru', 'semyonv', 'b545e1ef0dff8344c99a526a4fa860c8', 'This version allows to set displaying records in Order Tracking function of module', '', 2000, 0, 0),
(9844, 0, 'shop_manager', 1, '0.3.0', 636, 264, 'Shop System Manager Module', 'Shop System (tt_products) management. Easy to use Catalog Items and Categories manager  Useful orders statuses manager with customers e-mail notifier.', 1, 0, 1, 1289395031, 'a:1:{s:7:"depends";a:1:{s:11:"tt_products";s:5:"2.6.1";}}', 'Semyon Vyskubov', 'sv@rv7.ru', 'semyonv', 'db5be2ccbe11012ec165d71019de1a38', 'Andrea Boselli made next extendings:\r\n\r\n1) Possibility to override the extension settings\r\nthrough the backend users TypoScript. Basically if you add a TSconfig like this one: mod.user_shopmanager.PIDstoreRoot  2\r\n\r\n2) PID of shop categories and shop ar', '', 3000, 0, 0),
