(10465, 0, 'mwimagemap', 1, '1.0.5', 9747, 245, 'MW Imagemap', 'create image maps', 1, 0, 1, 1147732025, 'a:0:{}', 'Paul Mehrer', 'typo3@metaways.de', 'mixkxel', '90b0f8dc88ea828e94eccf4199a208eb', 'possibility to add/edit additional parameters.\r\n"alt"-attribute is added automatically to an area in case no alt attribute was specified.\r\nnotification on unsaved changes.', '', 1000005, 0, 0),
(10466, 0, 'mwimagemap', 1, '1.0.6', 9747, 268, 'MW Imagemap', 'create image maps', 1, 0, 1, 1147790437, 'a:0:{}', 'Paul Mehrer', 'typo3@metaways.de', 'mixkxel', 'a497a41ecd9b738913620337310c6cdd', 'shy set to 0; path ajusted to Typo3 4.0; problems with non administrator backend users fixed', '', 1000006, 0, 0),
(10467, 0, 'mwimagemap', 1, '1.0.7', 9747, 133, 'MW Imagemap', 'create image maps', 1, 0, 1, 1149852215, 'a:0:{}', 'Paul Mehrer', 'typo3@metaways.de', 'mixkxel', '7a086598fccb7049fcdf51797f2eaa74', 'Moved from the web section to the file section for better user management by limiting access to file mounts.\r\n\r\nadded resizing rectangles and circles by dragging.\r\n\r\nadded moving areas by x and y offset.\r\n\r\nadded uploading new image for existing imagemap.', '', 1000007, 0, 0),
