(10476, 0, 'mwimagemap', 1, '1.0.16', 9747, 446, 'MW Imagemap', 'create image maps', 2, 0, 1, 1159290397, 'a:0:{}', 'Paul Mehrer', 'typo3@metaways.de', 'mixkxel', 'feed0860856549b0d2ecd9a6aa4d46db', 'Added Possibility to use images from the file repository.\r\nWhen used with the content types IMAGE and IMAGE WITH TEXT the related images are now inserted automatically.', '', 1000016, 0, 0),
(10477, 0, 'mwimagemap', 1, '1.0.17', 9747, 318, 'MW Imagemap', 'create image maps', 2, 0, 1, 1168882427, 'a:0:{}', 'Paul Mehrer', 'typo3@metaways.de', 'mixkxel', 'b40bebd2fc9aeaea77a47aef5446a1e6', 'XHTML-compatibility\r\nadded id attribute ( id/name  "map_UID" ) to the the map-tag\r\nadded alt attribute to img-tag if imagemap is applied as plugin', '', 1000017, 0, 0),
(10478, 0, 'mwimagemap', 1, '1.0.18', 9747, 312, 'MW Imagemap', 'create image maps', 2, 0, 1, 1171039945, 'a:0:{}', 'Paul Mehrer', 'typo3@metaways.de', 'mixkxel', '2e32c5af22f089a35006cea8068a76e4', 'Replaced php short open tag by "?php" in file "constants.php"', '', 1000018, 0, 0),
(10479, 0, 'mwimagemap', 1, '1.0.19', 9747, 241, 'MW Imagemap', 'create image maps', 2, 0, 1, 1175330370, 'a:0:{}', 'Paul Mehrer', 'typo3@metaways.de', 'mixkxel', '32f51ca8ea3ac8aace3dde9b866dc2f9', 'Imagemap names are now sorted alphabetically in the backend dropdown when used as a plugin (Thanks to Andreas Wolf for the hint).', '', 1000019, 0, 0),
(10480, 0, 'mwimagemap', 1, '1.0.20', 9747, 694, 'MW Imagemap', 'create image maps', 2, 0, 1, 1178640550, 'a:0:{}', 'Paul Mehrer', 'typo3@metaways.de', 'mixkxel', 'ed40b11bb253054bcb087fc18ccb52b4', 'backend: corrected path display\r\nbackend: generating alternative thumbnail-pngs (for php-versions with no gif-support)\r\nbackend: localization of the "Move"-Button', '', 1000020, 0, 0),
(10481, 0, 'mwimagemap', 1, '1.1.0', 9747, 55, 'MW Imagemap', 'create image maps', 1, 0, 1, 1194692502, 'a:0:{}', 'Michael Perlbach', 'typo3@metaways.de', 'mixkxel', '30b9ffccbf354a8e1293efa39050f1e3', 'Most important: area borders can now be shown at the frontend.\r\nFor a complete listof changes please refer to the manuals changelog.', '', 1001000, 0, 0),
(10482, 0, 'mwimagemap', 1, '1.1.1', 9747, 48, 'MW Imagemap', 'create image maps', 1, 0, 1, 1194907442, 'a:0:{}', 'Michael Perlbach', 'typo3@metaways.de', 'mixkxel', 'e742664c71e108307daa462ee46f09f9', 'Fixed Bug with mouseover effects with several imagemaps\r\nFixed incorrect queries in "ext_tables.sql"\r\nSome minor bugfixes\r\nImproved documentation', '', 1001001, 0, 0),
(10483, 0, 'mwimagemap', 1, '1.1.2', 9747, 48, 'MW Imagemap', 'create image maps', 1, 0, 1, 1195004202, 'a:0:{}', 'Michael Perlbach', 'typo3@metaways.de', 'mixkxel', '44181be5641275b071ffa97170f8970a', 'Removed debugging information from frontend output, improved documentation', '', 1001002, 0, 0),
