(10485, 0, 'mwimagemap', 1, '1.1.4', 9747, 121, 'MW Imagemap', 'create image maps', 1, 0, 1, 1196251632, 'a:0:{}', 'Michael Perlbach', 'typo3@metaways.de', 'mixkxel', 'd3cd1530946e38d1c367f27b6cb9f400', 'Fixed one allow_call_time_pass_reference-annoyance, Fixed error on not referenced DB object when deleting an imagemap, new icons ;-)', '', 1001004, 0, 0),
(10486, 0, 'mwimagemap', 1, '1.1.5', 9747, 62, 'MW Imagemap', 'create image maps', 1, 0, 1, 1197882496, 'a:0:{}', 'Michael Perlbach', 'typo3@metaways.de', 'mixkxel', 'e71e6359c0a88b7b3d5ed27bd367292f', 'Backend: adapted to graphicsmagick, \r\nFrontend: automatic switch from png-overlay to gif-overlay, \r\nBackend: onclick editing/adding points is now possible again for polygons.', '', 1001005, 0, 0),
