(10565, 0, 'dre_formmaker', 1, '0.0.1', 2435, 281, '[drecomm] Form Maker', 'Advanced form making extension to create forms over multiple pages with direct data processing, conditional adjustments, support for multiple instances of form fields, reusability of form parts and a diversity of options concerning final data processing.', 3, 0, 2, 1147509262, 'a:0:{}', 'Bas Hoonhout @ Drecomm BV', 'bas.hoonhout@drecomm.nl', 'bas_hoonhout', '32d919737a05732aa58bc51a1bd54a3e', '', 'Drecomm BV', 1, 0, 0),
(10566, 0, 'dre_formmaker', 1, '0.0.2', 2435, 228, '[drecomm] Form Maker', 'Advanced form making extension to create forms over multiple pages with direct data processing, conditional adjustments, support for multiple instances of form fields, reusability of form parts and a diversity of options concerning final data processing.', 3, 0, 2, 1147708691, 'a:0:{}', 'Bas Hoonhout @ Drecomm BV', 'bas.hoonhout@drecomm.nl', 'bas_hoonhout', '3e40202337c5c190cd6ee1d03b35fd2e', 'fixed a few minor bugs and added some comments to README.txt', 'Drecomm BV', 2, 0, 0),
(10567, 0, 'dre_formmaker', 1, '0.0.3', 2435, 527, '[drecomm] Form Maker', 'Advanced form making extension to create forms over multiple pages with direct data processing, conditional adjustments, support for multiple instances of form fields, reusability of form parts and a diversity of options concerning final data processing.', 2, 0, 2, 1162554768, 'a:0:{}', 'Bas Hoonhout @ Drecomm BV', 'bas.hoonhout@drecomm.nl', 'bas_hoonhout', '401c7e5b01945941c4939ae1fc777f17', 'Documentation has been added. Currently documentation is still in development.', 'Drecomm BV', 3, 0, 0),
(10568, 0, 'dre_formmaker', 1, '1.0.0', 2435, 1002, '[drecomm] Form Maker', 'Advanced form making extension to create forms over multiple pages with direct data processing, conditional adjustments, support for multiple instances of form fields, reusability of form parts and a diversity of options concerning final data processing.', 2, 0, 2, 1169563548, 'a:0:{}', 'Bas Hoonhout @ Drecomm BV', 'bas.hoonhout@drecomm.nl', 'bas_hoonhout', '943504a9779a77744d510e27020fd3dd', 'Added default fieldtype, javascript and function repository. Published javascript presets. Added dynamic output parameters. Added plain text output type. Fixed a few minor bugs.', 'Drecomm BV', 1000000, 0, 0),
(10569, 0, 'dre_formmaker', 1, '1.1.0', 2435, 397, '[Drecomm] Formmaker', 'Flexible formmaking framework to create advanced, higly reusable webforms. Formfields, javascripts and phpscripts can be stored in a centralised repository. Flexible output in e-mail, PDF, XML, HTML as well as output to external sources like SOAP and MySQ', 2, 0, 2, 1224172095, 'a:1:{s:7:"depends";a:1:{s:3:"cms";s:0:"";}}', 'Bas Hoonhout, Menne Kamminga @ Drecomm BV', 'm.kamminga@drecomm.nl', 'bas_hoonhout', '1b22545135dbb727ffdfefe464526124', ' Renewed datastructure of the formfields.\r\n Renewed expression wizard.\r\n Included sample form based on field library.\r\n Wizard to create static (summary) fields.\r\n Improved output options, like dynamic PDF file name.', 'Drecomm BV', 1001000, 1, 0),
(10570, 0, 'dre_coladm', 1, '0.0.1', 589, 28, '[drecomm] Column administration', 'Enables backend users to add, rename, remove and move page columns. The extension provides also in an easy implementation of created columns within TypoScript', 2, 0, 2, 1147530697, 'a:0:{}', 'Bas Hoonhout @ Drecomm BV', 'bas.hoonhout@drecomm.nl', 'bas_hoonhout', '49ee88e761bea008b0884abeeb983d1c', '', 'Drecomm BV', 1, 0, 0),
(10571, 0, 'dre_coladm', 1, '1.0.0', 589, 561, '[drecomm] Column administration', 'Enables backend users to add, rename, remove and move page columns. The extension provides also in an easy implementation of created columns within TypoScript', 2, 0, 2, 1147531217, 'a:0:{}', 'Bas Hoonhout @ Drecomm BV', 'bas.hoonhout@drecomm.nl', 'bas_hoonhout', '7d7f274be529bc96f4afcbbba8cab515', '', 'Drecomm BV', 1000000, 1, 0),
(10572, 0, 'dre_pt2xml', 1, '1.0.0', 766, 265, '[drecomm] Page tree to XML', 'Generates a XML structure based on a certain part of the Typo3 page tree structure. The layout of the XML structure is fully determined by the TypoScript configuration options.', 2, 0, 2, 1147536736, 'a:0:{}', 'Bas Hoonhout @ Drecomm BV', 'bas.hoonhout@drecomm.nl', 'bas_hoonhout', '3b99d597ce6ea8539ffcbbd4942ceb8e', '', 'Drecomm BV', 1000000, 0, 0),
(10573, 0, 'dre_pt2xml', 1, '1.0.1', 766, 413, '[drecomm] Page tree to XML', 'Generates a XML structure based on a certain part of the Typo3 page tree structure. The layout of the XML structure is fully determined by the TypoScript configuration options.', 2, 0, 2, 1147780588, 'a:0:{}', 'Bas Hoonhout @ Drecomm BV', 'bas.hoonhout@drecomm.nl', 'bas_hoonhout', '542eb721e9351275aedd8bc3feeace61', 'Documentation added', 'Drecomm BV', 1000001, 0, 0);
