(10584, 0, 'alt_forms_field_title', 1, '1.0.0', 825, 270, 'Alternative forms field titles', 'With this extension you can change the titles of the fields in the BE records on per page basis.', 1, 0, 0, 1147710046, 'a:0:{}', 'Stig Nrgaard Frch', 'stig@8620.dk', 'inshadow', 'bfaa40294d659c4e719e934aaddc8414', 'Initial upload', '', 1000000, 0, 0),
(10585, 0, 'alt_forms_field_title', 1, '1.0.1', 825, 432, 'Alternative Form-Field-Label via PageTS', 'With this extension you can change the labels of the fields in the BE records on per page basis.', 1, 0, 0, 1193945425, 'a:0:{}', 'Stig Nrgaard Frch', 'stig@8620.dk', 'inshadow', '77e315524173b19372b2724ee7fbc573', 'TYPO3 version dependency information added. This extension requires TYPO3 4.0', '', 1000001, 0, 0),
