(10944, 0, 'file_list', 1, '0.2.0', 2686, 27, 'File List', 'Adds a frontend plugin which shows a list of files in a specified directory (like apache).', 1, -1, 3, 1152003107, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:3:"4.0";s:3:"cms";s:0:"";}}', 'Moreno Feltscher', 'moreno@feltscher.ch', 'xperseguers', 'b9a04313d121990bfe848b14909fe429', '- added the documentation', '', 2000, 0, 0),
(10945, 0, 'file_list', 1, '0.2.1', 2686, 1264, 'File List', 'Adds a frontend plugin which shows a list of files in a specified directory (like apache).', 1, -1, 3, 1152004973, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:3:"4.0";s:3:"cms";s:0:"";}}', 'Moreno Feltscher', 'moreno@feltscher.ch', 'xperseguers', '8a5b3b3dbc23a9e015ba4ed9b074b0bc', '- added the documentation', '', 2001, 0, 0),
(10946, 0, 'file_list', 1, '1.0.0', 2686, 60, 'File List', 'This extension provides a frontend plugin which shows a list of files and folders in a specified directory on the file system (comparable to Apaches directory listing).', 2, 0, 3, 1263170713, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:11:"4.0.0-0.0.0";s:3:"cms";s:0:"";}}', 'Moreno Feltscher', 'moreno@luagsh.ch', 'xperseguers', '2accca8885f044ba3c727c22d7f86e48', 'Now stable. Rewritten from scratch to fix security issue and added many flexibility options. Users of v.0.2.1 should use the UPDATE! function in Extension Manager to upgrade their plugin configuration.', '', 1000000, 0, 0),
(10947, 0, 'file_list', 1, '1.0.1', 2686, 89, 'File List', 'This extension provides a frontend plugin which shows a list of files and folders in a specified directory on the file system (comparable to Apaches directory listing).', 2, 0, 3, 1263285275, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:11:"4.0.0-0.0.0";s:3:"cms";s:0:"";}}', 'Moreno Feltscher', 'moreno@luagsh.ch', 'xperseguers', 'f5131f18cd89658d99682755d676f123', 'Fixed bugs 5964, 5965, 5966. See ChangeLog for further details.\r\nPlease note: Users of v.0.2.1 should use the UPDATE! function in Extension Manager to upgrade their plugin configuration and should add again "File List static TS."', '', 1000001, 0, 0),
(10948, 0, 'file_list', 1, '1.0.2', 2686, 602, 'File List', 'This extension provides a frontend plugin which shows a list of files and folders in a specified directory on the file system (comparable to Apaches directory listing).', 2, 0, 3, 1264826481, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:11:"4.0.0-0.0.0";s:3:"cms";s:0:"";}}', 'Moreno Feltscher', 'moreno@luagsh.ch', 'xperseguers', 'fa4b90878fe737d6deb969cef2a99bba', 'Fixed bug 6214. See ChangeLog for further details. Please note: Users of v.0.2.1 should use the UPDATE! function in Extension Manager to upgrade their plugin configuration and should add again "File List static TS."', '', 1000002, 0, 0),
(10949, 0, 'file_list', 1, '1.1.0', 2686, 0, 'File List', 'This extension provides a frontend plugin which shows a list of files and folders in a specified directory on the file system (comparable to Apaches directory listing).', 2, 0, 3, 1411199959, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"4.5.0-6.2.99";s:3:"php";s:12:"5.3.3-5.5.99";}}', 'Moreno Feltscher and Xavier Perseguers', 'moreno@luagsh.ch', 'xperseguers', 'd845022538607448830ef936cb70929e', 'Compatibility with TYPO3 6.1 and 6.2.', '', 1001000, 0, 0),
(10950, 0, 'file_list', 1, '1.1.1', 2686, 0, 'File List', 'This extension provides a frontend plugin which shows a list of files and folders in a specified directory on the file system (comparable to Apaches directory listing).', 2, 0, 3, 1432620770, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"4.5.0-6.2.99";s:3:"php";s:12:"5.3.3-5.6.99";}}', 'Moreno Feltscher and Xavier Perseguers', 'moreno@luagsh.ch', 'xperseguers', 'd40cf3c97d90d8abe7dde405c14eb17d', 'Bug fix release. Update script fails in TYPO3 6.2.', '', 1001001, 0, 0),
(10951, 0, 'file_list', 1, '2.0.0', 2686, 0, 'File List', 'This extension provides a frontend plugin which shows a list of files and folders in a specified directory on the file system (comparable to Apache directory listing) or using more advanced FAL selectors (categories, collection of files, ...). This extension may also be used for creating image galleries. Default templates are Bootstrap-ready.', 2, 0, 3, 1452179871, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:13:"6.2.0-7.99.99";s:3:"php";s:12:"5.5.0-7.0.99";}}', 'Xavier Perseguers', 'xavier@causal.ch', 'xperseguers', '2e175afaf382c4a124338991ded772ac', 'Native FAL support with compatibility for TYPO3 6.2 LTS and 7 LTS.\nRebuilt from the ground up with Fluid-based templates.\nBe sure to read details on https://forge.typo3.org/projects/extension-file_list/wiki/FILE_LIST_200', 'Causal Srl', 2000000, 0, 0),
(10952, 0, 'file_list', 1, '2.0.1', 2686, 0, 'File List', 'This extension provides a frontend plugin which shows a list of files and folders in a specified directory on the file system (comparable to Apache directory listing) or using more advanced FAL selectors (categories, collection of files, ...). This extension may also be used for creating image galleries. Default templates are Bootstrap-ready.', 2, 0, 3, 1452271747, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:14:"6.2.16-7.99.99";s:3:"php";s:12:"5.5.0-7.0.99";}}', 'Xavier Perseguers', 'xavier@causal.ch', 'xperseguers', 'c782983a2af84219c09122782a7caba2', 'Better stability when upgrading from version 1.x.\nExample of an image gallery in documentation.\nDetails on https://forge.typo3.org/projects/extension-file_list/wiki/FILE_LIST_201', 'Causal Srl', 2000001, 0, 0),
(10953, 0, 'file_list', 1, '2.1.0', 2686, 0, 'File List', 'This extension provides a frontend plugin which shows a list of files and folders in a specified directory on the file system (comparable to Apache directory listing) or using more advanced FAL selectors (categories, collection of files, ...). This extension may also be used for creating image galleries. Default templates are Bootstrap-ready.', 2, 0, 3, 1454933009, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:14:"6.2.16-7.99.99";s:3:"php";s:12:"5.5.0-7.0.99";}}', 'Xavier Perseguers', 'xavier@causal.ch', 'xperseguers', '512d0555821c87bb965da488f7718ce9', 'ViewHelpers to filter and restrict the size of the list of files.\nDetails on https://forge.typo3.org/projects/extension-file_list/wiki/FILE_LIST_210', 'Causal Srl', 2001000, 0, 0),
(10954, 0, 'file_list', 1, '2.2.0', 2686, 0, 'File List', 'This extension provides a frontend plugin which shows a list of files and folders in a specified directory on the file system (comparable to Apache directory listing) or using more advanced FAL selectors (categories, collection of files, ...). This extension may also be used for creating image galleries. Default templates are Bootstrap-ready.', 2, 0, 3, 1478770511, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:14:"6.2.16-7.99.99";s:3:"php";s:12:"5.5.0-7.0.99";}}', 'Xavier Perseguers', 'xavier@causal.ch', 'xperseguers', 'f576fd241c73995d7abe3d8b74bf414c', 'Now sorting by FAL title and description as well.\r\nLegacy pi-based plugin has been removed. Use v2.1 to migrate older plugins if needed.\r\nDetails on https://forge.typo3.org/projects/extension-file_list/wiki/FILE_LIST_220', 'Causal Srl', 2002000, 0, 0),
(10955, 0, 'file_list', 1, '2.2.1', 2686, 0, 'File List', 'This extension provides a frontend plugin which shows a list of files and folders in a specified directory on the file system (comparable to Apache directory listing) or using more advanced FAL selectors (categories, collection of files, ...). This extension may also be used for creating image galleries. Default templates are Bootstrap-ready.', 2, 0, 3, 1493718366, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:13:"6.2.16-8.7.99";s:3:"php";s:12:"5.5.0-7.1.99";}}', 'Xavier Perseguers', 'xavier@causal.ch', 'xperseguers', '83836980489f337db784d73c66bbd329', 'Regular bug fix release mainly for TYPO3 v8.\r\nSupport for t3:// link scheme.\r\nDetails on https://forge.typo3.org/projects/extension-file_list/wiki/FILE_LIST_221', 'Causal Srl', 2002001, 0, 0),
(10956, 0, 'file_list', 1, '2.2.2', 2686, 0, 'File List', 'This extension provides a frontend plugin which shows a list of files and folders in a specified directory on the file system (comparable to Apache directory listing) or using more advanced FAL selectors (categories, collection of files, ...). This extension may also be used for creating image galleries. Default templates are Bootstrap-ready.', 2, 0, 3, 1494084687, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:13:"6.2.16-8.7.99";s:3:"php";s:12:"5.5.0-7.1.99";}}', 'Xavier Perseguers', 'xavier@causal.ch', 'xperseguers', 'da884578592594c556f38b991352dfaf', 'ThumbnailViewHelper compatibility for TYPO3 v8.\r\nDetails on https://forge.typo3.org/projects/extension-file_list/wiki/FILE_LIST_222', 'Causal Srl', 2002002, 1, 0),
