(11002, 0, 'fancycorners', 1, '1.0.8', 3862, 208, 'Fancy Corners', 'Create fancy corners with different shapes and colors based on GIFBUILDER and a Symbol font', 2, 0, 2, 1150452278, 'a:0:{}', 'JoH', 'info@cybercraft.de', 'cybercraft', '2d866831114bb25db200ad4f4fbf14e9', 'Removed some redundancies in the PHP code', 'cybercr@ft', 1000008, 0, 0),
(11003, 0, 'fancycorners', 1, '1.0.9', 3862, 218, 'Fancy Corners', 'Create fancy corners with different shapes and colors based on GIFBUILDER and a Symbol font', 2, 0, 2, 1150478491, 'a:0:{}', 'JoH', 'info@cybercraft.de', 'cybercraft', 'aa7fc5d70d4ac5ebb38262156fb4140a', 'Inserted &nbsp; into the span tags for the conrner elements\nadded overflow:hidden to keep the size of the corner elements regardless of the font size\nchanged the min-height hack for IE to make the CSS validate', 'cybercr@ft', 1000009, 0, 0),
(11004, 0, 'fancycorners', 1, '1.0.10', 3862, 207, 'Fancy Corners', 'Create fancy corners with different shapes and colors based on GIFBUILDER and a Symbol font', 2, 0, 2, 1150541939, 'a:0:{}', 'JoH', 'info@cybercraft.de', 'cybercraft', '414feb71b49abe3aefcf8143efc95f3f', 'Moved the externalizing of stylesheets from additionalheaderData to includeCSS.\nSo you will be able to override the default styles with your own stylesheet included in page.headerData', 'cybercr@ft', 1000010, 0, 0),
(11005, 0, 'fancycorners', 1, '1.0.11', 3862, 270, 'Fancy Corners', 'Create fancy corners with different shapes and colors based on GIFBUILDER and a Symbol font', 2, 0, 2, 1150585388, 'a:0:{}', 'JoH', 'info@cybercraft.de', 'cybercraft', 'fa97758d744741ba4bb4400b37ac4f8d', 'Removed &nbsp; again in favour of comments containing the element position to make sure the span tags are not removed by HTML cleaners without having to use real characters.\nStreamlined HTML and CSS output for better readability.', 'cybercr@ft', 1000011, 0, 0),
(11006, 0, 'fancycorners', 1, '1.1.0', 3862, 374, 'Fancy Corners', 'Create fancy corners with different shapes and colors based on GIFBUILDER and a Symbol font', 2, 0, 2, 1151073115, 'a:0:{}', 'JoH', 'info@cybercraft.de', 'cybercraft', '740afcd43be1264a16ca877d5d005001', 'Inserted a check for existing content, that disables the corners for empty elements.', 'cybercr@ft', 1001000, 0, 0),
(11007, 0, 'fancycorners', 1, '1.1.1', 3862, 425, 'Fancy Corners', 'Create fancy corners with different shapes and colors based on GIFBUILDER and a Symbol font', 2, 0, 2, 1153068858, 'a:0:{}', 'JoH', 'info@cybercraft.de', 'cybercraft', '04a26ed66127b513e01ad5855c25fd25', 'Fixed some bugs regarding array related error messages with PHP5.', 'cybercr@ft', 1001001, 0, 0),
(11008, 0, 'fancycorners', 1, '1.1.2', 3862, 350, 'Fancy Corners', 'Create fancy corners with different shapes and colors based on GIFBUILDER and a Symbol font', 2, 0, 2, 1176207796, 'a:0:{}', 'JoH', 'info@cybercraft.de', 'cybercraft', 'e4747f218176aaa6e609a3e46ce9f6c3', 'Fixed problems with wrong path settings for corner graphic URL.', 'cybercr@ft', 1001002, 0, 0),
(11009, 0, 'fancycorners', 1, '1.1.3', 3862, 255, 'Fancy Corners', 'Create fancy corners with different shapes and colors based on GIFBUILDER and a Symbol font', 2, 0, 2, 1209085342, 'a:0:{}', 'JoH', 'info@cybercraft.de', 'cybercraft', 'a83e050a4457bc18d5d93b5e4caf3d6c', 'Fixed problems with XCLASS of tce_forms and TYPO3  4.2.', 'cybercr@ft', 1001003, 0, 0),
(11010, 0, 'fancycorners', 1, '1.1.4', 3862, 58, 'Fancy Corners', 'Use the ICE flavor extension now to create fancy corners with different shapes and colors based on GIFBUILDER and a Symbol font', 5, 0, 2, 1272547223, 'a:0:{}', 'JoH', 'info@cybercraft.de', 'cybercraft', '09d5278ae5e71be588f9b4392837d1b2', 'This is the last version of this extension. Use ICE flavors if you still want to create shaped corners. Theyll work independently from the rest of the ICE pack as well.', 'cybercr@ft', 1001004, 1, 0),
