(11089, 0, 'aux_newsmailer', 1, '0.0.1', 3052, 252, 'Newsletter via news (tt_news)', '\nCreate newsletters based on news (tt_news). It has the following features:\n Compiles several news items into one newsletter.\n Prepared for automatic compilation and sending thru cronjobs.\n Schedule automatic compilation and sending daily, weekly, mont', 0, 0, 1, 1150731428, 'a:1:{s:7:"depends";a:2:{s:7:"tt_news";s:0:"";s:3:"cms";s:0:"";}}', 'Tim Wentzlau', 'tim.wentzlau@auxilior.com', 'auxtkw', '35257bbdcb12184c8053660534f66023', 'initial upload, dont use it yet', 'Auxilior Technology', 1, 0, 0),
