(11233, 0, 'templavoila_pagemod', 1, '0.0.1', 3721, 295, 'Improved Templavoila Page Module', 'This extension improves the templavoila page module. It will work like a combined page and list module: showing normal page module on normal pages, and list module on sys folders. It will also follow page shortcuts.', 0, 0, 0, 1152354952, 'a:0:{}', 'Morten Tranberg Hansen', 'mth@daimi.au.dk', 'daimi', '1edb90320f348d999e8eea7689e4b155', 'First upload. Check it out. This is a kind of a proposal for how the Page and List module in TYPO3 could work.', '', 1, 0, 0),
(11234, 0, 'templavoila_pagemod', 1, '0.0.2', 3721, 238, 'Improved Templavoila Page Module', 'This extension improves the templavoila page module. It will work like a combined page and list module: showing normal page module on normal pages, and list module on sys folders. It will also follow page shortcuts.', 1, 0, 0, 1152621800, 'a:0:{}', 'Morten Tranberg Hansen', 'mth@daimi.au.dk', 'daimi', '2b59e6b2ea58207fdebc11e26cfa4444', 'Bug fix. It was not possible to create new pages, using the wizard. Thanks to Gregor!', '', 2, 0, 0),
(11235, 0, 'templavoila_pagemod', 1, '0.0.3', 3721, 261, 'Improved Templavoila Page Module', 'This extension improves the templavoila page module. It will work like a combined page and list module: showing normal page module on normal pages, and list module on sys folders. It will also follow page shortcuts.', 1, 0, 0, 1152697236, 'a:0:{}', 'Morten Tranberg Hansen', 'mth@daimi.au.dk', 'daimi', '5e6d4fd6e37fa328660ffb2db1324c64', 'Languages and extension manager configurations added.', '', 3, 0, 0),
(11236, 0, 'templavoila_pagemod', 1, '0.1.0', 3721, 220, 'Improved Templavoila Page Module', 'This extension improves the templavoila page module. It will work like a combined page and list module: showing normal page module on normal pages, and list module on sys folders. It will also follow page shortcuts.', 1, 0, 0, 1153319723, 'a:0:{}', 'Morten Tranberg Hansen', 'mth@daimi.au.dk', 'daimi', '1e1f49fbe6f2a74f5a867bb9cdfc995d', 'Made depending on templavoila. If templavoila is installed after this extension, the old templavoila page module will NOT be hidden.', '', 1000, 0, 0),
(11237, 0, 'templavoila_pagemod', 1, '0.2.0', 3721, 111, 'Improved Templavoila Page Module', 'This extension improves the templavoila page module. It will work like a combined page and list module: showing normal page module on normal pages, and list module on sys folders. It will also follow page shortcuts.', 1, 0, 0, 1154449641, 'a:0:{}', 'Morten Tranberg Hansen', 'mth@daimi.au.dk', 'daimi', '4376a7dc4baf93476783dc98b21968d1', 'Bugfix with user access, before the extension was only usable by admins. Changes some links, so it the extension also works in subdirs (thanks to Noel).', '', 2000, 0, 0),
(11238, 0, 'templavoila_pagemod', 1, '0.2.1', 3721, 497, 'Improved Templavoila Page Module', 'This extension improves the templavoila page module. It will work like a combined page and list module: showing normal page module on normal pages, and list module on sys folders. It will also follow page shortcuts.', 1, 0, 0, 1154526835, 'a:0:{}', 'Morten Tranberg Hansen', 'mth@daimi.au.dk', 'daimi', '63f50bdfbc82064b2b5310b5532c9137', 'Now checks for right bank when follow shortcuts. This makes the highlight of the right page working again, when people have multiple mounts.', '', 2001, 0, 0),
(11239, 0, 'templavoila_pagemod', 1, '0.2.2', 3721, 2099, 'Improved Templavoila Page Module', 'This extension provides a combined page and list module: showing normal page module on normal pages, and list module on sys folders. It will also follow page shortcuts.', 2, 0, 0, 1169555616, 'a:0:{}', 'Morten Tranberg Hansen. Maintained by Kasper Ligaard', 'ligaard@daimi.au.dk', 'daimi', '94c6d5885a818b73e874545e220ff57d', 'Corrected error with path when Typo3 is installed outside the website root. Thanks to Jens Kster for reporting this and providing a fix.\r\nNew maintainer: Kasper Ligaard.', 'Computer Science Dept., University of Aarhus', 2002, 1, 0),
(11240, 0, 'auxdataviewer', 1, '0.0.1', 2568, 452, 'App DB builder', 'Easy creation of db appplications without the need to code extensions in PHP. Extents the kickstarter with sections where FE presentation can be defined (DB grids and input forms). It is possible to create master/slave DB grids and let them interact on th', 1, 0, 3, 1152549839, 'a:0:{}', 'Tim Wentzlau', 'tim.wentzlau@auxilior.com', 'auxtkw', '6ff425c68a8da3e47b7339fa567e0712', 'Initial upload to verify that manuals are processed correct.', 'Auxilior Technology', 1, 0, 0),
