(11578, 0, 'pm_tour', 1, '0.0.8', 1679, 152, 'Tour Extension', 'Upload you GPS Tour data as GPX File. Tracks, routes and waypoints are displayed using Google Maps. An altitude profile can be rendered with Google Charts.', 1, -1, 3, 1199393335, 'a:0:{}', 'Patrick Matusz, Markus Barchfeld', 'Markus.Barchfeld@gmx.de', 'mbarchfe', 'ed2e0f28916ab1cdf0b37bd1bad66812', 'render altitude profile with Google Charts', 'webdesign.matusz.ch, www.markusbarchfeld.de', 8, 0, 0),
(11579, 0, 'pm_tour', 1, '0.0.10', 1679, 25, 'Tour Extension', 'Upload you GPS Tour data as GPX File. Tracks, routes and waypoints are displayed using Google Maps. An altitude profile can be rendered with Google Charts.', 1, -1, 3, 1240345296, 'a:0:{}', 'Patrick Matusz, Markus Barchfeld', 'Markus.Barchfeld@gmx.de', 'mbarchfe', 'bb8eb71fb93b6b9fdfc900b04bba067d', '09-04-21 0.0.9 pm\n	 use google maps 2.s (stable version) to avoid rendering bugs\n	 display waypoints with default icon if there is no special icon defined, renamed allowedSymbols to symbolsWithIcon\n	 support images rendering with perfectlightbox\n	 add', 'webdesign.matusz.ch, www.markusbarchfeld.de', 10, 0, 0),
(11580, 0, 'pm_tour', 1, '0.0.11', 1679, 16, 'Tour Extension', 'Upload you GPS Tour data as GPX File. Tracks, routes and waypoints are displayed using Google Maps. An altitude profile can be rendered with Google Charts.', 1, -1, 3, 1247602047, 'a:0:{}', 'Patrick Matusz, Markus Barchfeld', 'Markus.Barchfeld@gmx.de', 'mbarchfe', '6496d7b5ffcce52631b3a6aeaf82c4bd', '     fixed map type\n     support layers, per default the user can enable the wikipedia.de and panoramio layer \n	 reverted to using the latest google maps version (as opposed to the stable version) for full layering support\n	 marker popup can display t', 'webdesign.matusz.ch, www.markusbarchfeld.de', 11, 0, 0),
