(11613, 0, 'daimi_skin', 1, '0.1.1', 1935, 234, 'Daimi Skin', 'Modified version of Typo3 4.0 default skin.', 2, 0, 4, 1155039832, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"4.3.0-5.9.0";s:5:"typo3";s:9:"3.9.0-4.0";}}', 'Kasper Ligaard Nielsen', 'ligaard@daimi.au.dk', 'daimi', 'd65bf5bdd4edd65922e7f46283e10a93', 'Corrected author: Removed text "The TYPO3 design team." from author-field.', '', 1001, 0, 0),
(11614, 0, 'daimi_skin', 1, '0.2.0', 1935, 238, 'Daimi Skin', 'Modified version of Typo3 4.0 default skin.', 2, 0, 4, 1155118823, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"4.3.0-5.9.0";s:5:"typo3";s:9:"3.9.0-4.0";}}', 'Kasper Ligaard Nielsen', 'ligaard@daimi.au.dk', 'daimi', '7ed91275fe73c303ecd4885afab0df4b', 'Added manual motivating why this skin is an improvement over the Typo3 4.0 default skin.', '', 2000, 0, 0),
(11615, 0, 'daimi_skin', 1, '0.2.1', 1935, 696, 'Daimi Skin', 'Modified version of Typo3 4.0 default skin.', 2, 0, 4, 1155566606, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"4.3.0-5.9.0";s:5:"typo3";s:6:"3.9.0-";}}', 'Kasper Ligaard Nielsen', 'ligaard@daimi.au.dk', 'daimi', 'e165fb2c5eec92e0c4fc616e6453c421', 'Corrected faulty depends criteria, so no wrong warning is presented anymore during installation.', '', 2001, 0, 0),
(11616, 0, 'daimi_skin', 1, '0.3.0', 1935, 207, 'Daimi Skin', 'Corrects easily fixable UI blunders in the default Typo3 4.0 skin. Only icons and stylesheets are changed.', 2, 0, 4, 1176839324, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"4.3.0-5.9.0";s:5:"typo3";s:11:"3.9.0-0.0.0";}}', 'Kasper Ligaard', 'ligaard@daimi.au.dk', 'daimi', '3b86c6a1569e5c0e6268025965b682a8', ' Version 0.3.0. \r\n Uses CSS-rule position: fixed; since IE7 now honours it. \r\n :hover effects on most buttons. \r\n Links are now blue. \r\n Icons in pagetree slightly seperated from page-title. \r\n(See Changelog for elaboration).', '', 3000, 0, 0),
(11617, 0, 'daimi_skin', 1, '0.3.1', 1935, 16, 'Daimi Skin', 'Corrects easily fixable UI blunders in the default Typo3 4.0 skin. Only icons and stylesheets are changed.', 2, 0, 4, 1177275244, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"4.3.0-5.9.0";s:5:"typo3";s:11:"3.9.0-0.0.0";}}', 'Kasper Ligaard', 'ligaard@daimi.au.dk', 'daimi', '8e72ce7d07843bf1942f5161d69b5a4b', ' Made almost black text into real black. \r\n Made th-elements have the same default size as td. \r\n(See Changelog for elaboration).', '', 3001, 0, 0),
(11618, 0, 'daimi_skin', 1, '0.3.2', 1935, 519, 'Daimi Skin', 'Corrects easily fixable UI blunders in the default Typo3 4.0 skin. Only icons and stylesheets are changed.', 2, 0, 4, 1177276039, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"4.3.0-5.9.0";s:5:"typo3";s:11:"3.9.0-0.0.0";}}', 'Kasper Ligaard', 'ligaard@daimi.au.dk', 'daimi', '321dad00248005e4301c07fcba10cd61', ' Made underline in module-menu.', '', 3002, 1, 0),
(11619, 0, 'eim2exifextract', 1, '1.0.0', 513, 513, 'metaExtract', 'Extracts exif data from images. The user can choose by typoscript configuration, which meta fields he wants to use, and which should be discarted. This can help avoiding indexing problems in DAM, when the meta-data exceeds the available storage space in t', 1, 0, 5, 1155060569, 'a:0:{}', 'Achim Eichhorn', 'AchimEichhorn@eim2.de', 'rincewind', 'f058105d30ccea202da350b6d5637ebe', 'this service is completely based on\nRene Fritzs tx_ccmetaexif_sv2, but solves\nsome problems I had with the original service.\nLook at the source code and the manual for further information!', '', 1000000, 1, 0),
