(11637, 0, 'wt_gallery', 1, '1.0.0', 19758, 296, 'WT Gallery', 'Gallery with separate Single- and Thumbnailview', 0, -1, 3, 1163599567, 'a:0:{}', 'Alex', 'alex@wunschtacho.de', 'abandoned_extensions', '3110fae2f74e62838328ad9cb20911e3', 'deactivated cache, thumbs will be created not scaled, some bugfixes - SPECIAL THANX TO ROLAND BEHME', '', 1000000, 0, 0),
(11638, 0, 'wt_gallery', 1, '1.0.1', 19758, 250, 'WT Gallery', 'Gallery with separate Single- and Thumbnailview', 0, -1, 3, 1163749837, 'a:0:{}', 'Alex', 'alex@wunschtacho.de', 'abandoned_extensions', '03e32a6078e5119de355ba4aab67ff85', 'EXIF can be shown', '', 1000001, 0, 0),
(11639, 0, 'wt_gallery', 1, '1.0.2', 19758, 19, 'WT Gallery', 'Gallery with separate Single- and Thumbnailview', 0, -1, 3, 1164007743, 'a:0:{}', 'Alex', 'alex@wunschtacho.de', 'abandoned_extensions', 'fe178b89a51919286ab6accf86d82d32', '- Dubletten im Cache-Ordner werden vermieden. \nFr den Dateinamen in den Cachefoldern wird ein md5-Hash aus dem ursprnglichen Bildnamen (inkl Pfad), der gewnschten Breite und dem eingestellten Seitenverhltnis generiert.\n\n- Im Single-View ka', '', 1000002, 0, 0),
(11640, 0, 'wt_gallery', 1, '1.0.3', 19758, 215, 'WT Gallery', 'Gallery with separate Single- and Thumbnailview', 0, -1, 3, 1164008243, 'a:0:{}', 'Alex', 'alex@wunschtacho.de', 'abandoned_extensions', '09614dab762c6b47d30b7ada2f62b7e8', 'You can use a watermark in the singleview, \n(See Changelog in manual for more informations)', '', 1000003, 0, 0),
