(11642, 0, 'wt_gallery', 1, '1.0.5', 19758, 364, 'WT Gallery', 'Gallery with separate Single- and Thumbnailview', 2, -1, 3, 1170344618, 'a:0:{}', 'Alex', 'alex@wunschtacho.de', 'abandoned_extensions', '72cea6491308da2ed90c8f36336fc947', 'Manual in english and german, some small changes in the standard html template', '', 1000005, 0, 0),
(11643, 0, 'wt_gallery', 1, '1.1.0', 19758, 318, 'WT Gallery', 'Easy gallery with separate single- and thumbnailview and crop function to have styled images (e.g. quadratic thumbnails)', 2, -1, 3, 1172147414, 'a:0:{}', 'Alexander Kellner (wunschtacho)', 'alex@wunschtacho.de', 'abandoned_extensions', '1dcb63bcc296d691fff90eb7cf5130e8', 'TypoScript can be used instead of flexform, small bugfixes and error warnings should help you to install the extension.', '', 1001000, 0, 0),
(11644, 0, 'wt_gallery', 1, '2.0.0', 19758, 281, 'WT Gallery', 'Easy gallery with separate single- and thumbnailview and crop function to have styled images (e.g. quadratic thumbnails), Subgalleries possible', 1, -1, 3, 1173362012, 'a:0:{}', 'Alexander Kellner (wunschtacho), Roland Behme', 'alex@wunschtacho.de', 'abandoned_extensions', '894dd8719ea09421ca8d97a87a212cb9', 'Subgalleries are supported, Cached files could be deleted, if they are too old, All configurations can be set by TypoScript, New caching system, New ERROR management and ERROR displays on the frontend to find errors, PHP Code cleaned', '', 2000000, 0, 0),
(11645, 0, 'wt_gallery', 1, '2.0.1', 19758, 256, 'WT Gallery', 'Easy gallery with separate single- and thumbnailview and crop function to have styled images (e.g. quadratic thumbnails), Subgalleries possible', 1, -1, 3, 1174151266, 'a:0:{}', 'Alexander Kellner (wunschtacho), Roland Behme', 'alex@wunschtacho.de', 'abandoned_extensions', 'e04bb5223a676610e2769b580d6b366c', 'Small bugfix in the comment function (show content of picture.txt to picture.jpg) - see changelog for all changes in version 2.0.0', '', 2000001, 0, 0),
(11646, 0, 'wt_gallery', 1, '2.0.2', 19758, 2455, 'WT Gallery', 'Easy gallery with separate single- and thumbnailview and crop function to have styled images (e.g. quadratic thumbnails), Subgalleries possible', 1, -1, 3, 1174557200, 'a:0:{}', 'Alexander Kellner (wunschtacho), Roland Behme', 'alex@wunschtacho.de', 'abandoned_extensions', 'c0d700f120c74dca11479154ff065b78', 'New feature: Sorting of categories (subgalleries) are possible now - see changelog for all changes in version 2.0.0', '', 2000002, 0, 0),
(11647, 0, 'wt_gallery', 1, '2.0.3', 19758, 268, 'WT Gallery', 'Easy gallery with separate single- and thumbnailview and with subgallery mode. A crop function enables styled images (e.g. quadratic thumbnails)', 2, -1, 3, 1175635093, 'a:0:{}', 'Alexander Kellner (wunschtacho)', 'alex@wunschtacho.de', 'abandoned_extensions', '8461eedfbdd03b53b0e5d680e79998cf', 'Small bugfix in the crop function to cut pictures in landscape format right (not too much). See changelog for all changes in wt_gallery version 2.', '', 2000003, 0, 0);
INSERT INTO `tx_extensionmanager_domain_model_extension` (`uid`, `pid`, `extension_key`, `repository`, `version`, `alldownloadcounter`, `downloadcounter`, `title`, `description`, `state`, `review_state`, `category`, `last_updated`, `serialized_dependencies`, `author_name`, `author_email`, `ownerusername`, `md5hash`, `update_comment`, `authorcompany`, `integer_version`, `current_version`, `lastreviewedversion`) VALUES
(11648, 0, 'wt_gallery', 1, '2.0.4', 19758, 312, 'WT Gallery', 'Easy gallery with separate single- and thumbnailview and with subgallery mode. A crop function enables styled images (e.g. quadratic thumbnails)', 2, -1, 3, 1176117777, 'a:0:{}', 'Alexander Kellner (wunschtacho)', 'alex@wunschtacho.de', 'abandoned_extensions', 'd3d198d3087457067bb513d1772cb295', 'New Wallpaper Feature: Show original picture by clicking on the single picture if wanted. See manual for viewing all changes in wt_gallery version 2', '', 2000004, 0, 0),
(11649, 0, 'wt_gallery', 1, '2.0.6', 19758, 384, 'WT Gallery', 'Easy gallery with separate single- and thumbnailview and with subgallery mode. A crop function enables styled images (e.g. quadratic thumbnails)', 2, -1, 3, 1176830933, 'a:0:{}', 'Alexander Kellner (wunschtacho)', 'alex@wunschtacho.de', 'abandoned_extensions', '7c7238f36b85dd323b3fb8b17a3d6e2b', 'New feature in list view: The current thumbnail gets a different stylesheet class to select the current picture with a special style. NOTE: See manual for all changes in wt_gallery version 2', '', 2000006, 0, 0),
(11650, 0, 'wt_gallery', 1, '2.2.0', 19758, 211, 'WT Gallery', 'Easy JPG gallery with separate single- and thumbnailview and with subgallery mode. A crop function enables styled images (e.g. quadratic thumbnails). Rounded Corners and filters like greyscale available.', 2, -1, 3, 1177838910, 'a:0:{}', 'Alexander Kellner (wunschtacho)', 'alex@wunschtacho.de', 'abandoned_extensions', 'a0f3adfed72921f6c0194fa5d4e46ff5', 'Special effects and filters (like rounded corners or greyscale)  Forward and Backward links below the single picture  You can manually delete all generated pictures  HTML Template change  EXIF bugfix  cleaned Flexform  New Manual  ---  see manual fo', '', 2002000, 0, 0),
(11651, 0, 'wt_gallery', 1, '2.2.1', 19758, 418, 'WT Gallery', 'Easy JPG gallery with separate single- and thumbnailview and with subgallery mode. A crop function enables styled images (e.g. quadratic thumbnails). Rounded Corners and filters like greyscale available.', 2, -1, 3, 1177933083, 'a:0:{}', 'Alexander Kellner (wunschtacho)', 'alex@wunschtacho.de', 'abandoned_extensions', '04e9ef212f15d6f9f02a0d25abf80506', 'Special effects and filters (like rounded corners or greyscale) Forward and Backward links below the single picture You can manually delete all generated pictures HTML Template change EXIF bugfix cleaned Flexform New Manual - V2 see manual', '', 2002001, 0, 0),
(11652, 0, 'wt_gallery', 1, '2.3.0', 19758, 226, 'WT Gallery', 'Easy gallery with separate single- and thumbnailview and with subgallery mode. A crop function enables styled images (e.g. quadratic thumbnails). Rounded Corners and filters like greyscale available.', 2, -1, 3, 1179146919, 'a:0:{}', 'Alexander Kellner (wunschtacho)', 'alex@wunschtacho.de', 'abandoned_extensions', '863f3f1259db71192900add79b792694', 'New Cache System, improved rounded corners, new classes, changed HTML Template, etc...', '', 2003000, 0, 0),
(11653, 0, 'wt_gallery', 1, '2.3.1', 19758, 300, 'WT Gallery', 'Easy gallery with separate single- and thumbnailview and with subgallery mode. A crop function enables styled images (e.g. quadratic thumbnails). Rounded Corners and filters like greyscale available.', 2, -1, 3, 1179257482, 'a:0:{}', 'Alexander Kellner (wunschtacho)', 'alex@wunschtacho.de', 'abandoned_extensions', 'b9e8de57bb188f49cec34c0a4358905c', 'Old GET variables from already delted pics (maybe indexed by google.de) lead to the first picture (no more error) / other invalid GET variables leads to an errormessage / Barrier-free Improvement / SingleView: Small bugfix in Show category link', '', 2003001, 0, 0),
(11654, 0, 'wt_gallery', 1, '2.3.2', 19758, 94, 'WT Gallery', 'Easy gallery with separate single- and thumbnailview and with subgallery mode. A crop function enables styled images (e.g. quadratic thumbnails). Rounded Corners and filters like greyscale available. Wallpaper- and Imagelightbox function added.', 2, -1, 3, 1179759130, 'a:0:{}', 'Alexander Kellner (wunschtacho)', 'alex@wunschtacho.de', 'abandoned_extensions', 'c298b4c9a8e3213aaee566f838befd93', 'Enabling kj_imagelightbox2 to work with wt_gallery. See all changes in the manual.', '', 2003002, 0, 0),
(11655, 0, 'wt_gallery', 1, '2.3.3', 19758, 80, 'WT Gallery', 'Easy gallery with separate single- and thumbnailview and with subgallery mode. A crop function enables styled images (e.g. quadratic thumbnails). Rounded Corners and filters like greyscale available. Wallpaper- and Imagelightbox function added.', 2, -1, 3, 1179846512, 'a:0:{}', 'Alexander Kellner (wunschtacho)', 'alex@wunschtacho.de', 'abandoned_extensions', '7cd4d9c6167c0f43ac975159cdc0ed19', 'Small bug in locallang.xml: back was used twice / see manual for all changes in version 2.3', '', 2003003, 0, 0),
(11656, 0, 'wt_gallery', 1, '2.4.0', 19758, 2910, 'WT Gallery', 'Easy gallery with separate single- and thumbnailview and with subgallery mode. A crop function enables styled images (e.g. quadratic thumbnails). Rounded Corners and filters like greyscale available. Wallpaper- and Imagelightbox function added.', 2, -1, 3, 1179928435, 'a:0:{}', 'Alexander Kellner (wunschtacho)', 'alex@wunschtacho.de', 'abandoned_extensions', '520992e61454767e4f4b015bab9174c3', 'Extension do not disables cache any more. Indexed_search and page caching are possible. Some small RealUrl bugs.', '', 2004000, 0, 0),
