(11816, 0, 'pmktextarea', 1, '0.1.0', 4620, 256, 'PMK Textarea Widget', 'Adds resizing, linenumbers, improved Tabkey handling and other neat features to standard textareas.', 1, 0, 0, 1156090651, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:6:"4.3.0-";s:5:"typo3";s:6:"3.9.9-";}}', 'Peter Klein', 'peter@umloud.dk', 'pmk65', '792236487d79ef3d28b957ce35d4c66e', 'First public release!', 'Umloud Untd', 1000, 0, 0),
(11817, 0, 'pmktextarea', 1, '0.1.1', 4620, 241, 'PMK Textarea Widget', 'Adds resizing, linenumbers, improved Tabkey handling and other neat features to standard textareas.', 1, 0, 0, 1156317710, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:6:"4.3.0-";s:5:"typo3";s:6:"3.9.9-";}}', 'Peter Klein', 'peter@umloud.dk', 'pmk65', '9744c60f01bfcb279c5eb16cace3f39f', 'Added fix for for the new TYPO3 skin  t3skin.\nt3skin has a bug, where it adds 2 CLASS definitions to textarea tags, which prevents this script from running correctly, as it uses the className defined in the 2nd CLASS definition, which is i', 'Umloud Untd', 1001, 0, 0),
(11818, 0, 'pmktextarea', 1, '0.1.2', 4620, 1171, 'PMK Textarea Widget', 'Adds resizing, linenumbers, improved Tabkey handling and other neat features to standard textareas.', 2, 0, 0, 1159377662, 'a:2:{s:7:"depends";a:2:{s:3:"php";s:6:"4.3.0-";s:5:"typo3";s:6:"3.9.9-";}s:9:"conflicts";a:1:{s:11:"skingreyman";s:6:"0.0.0-";}}', 'Peter Klein', 'peter@umloud.dk', 'pmk65', 'b9a7bbb397c4e4b31b44d386887bc116', 'Added a couple new config options: lockH, lockW & tabChar. lockH & lockW can be used to lock recizing of either Height or Width. tabChar is used to choose what to insert (either the normal Tabchar or X spaces), when the Tabkey is p', 'Umloud Untd', 1002, 0, 0),
(11819, 0, 'pmktextarea', 1, '0.2.0', 4620, 1241, 'PMK Textarea Widget', 'Adds resizing, linenumbers, improved Tabkey handling and other neat features to standard textareas.', 2, 0, 0, 1185484397, 'a:2:{s:7:"depends";a:2:{s:3:"php";s:11:"4.3.0-0.0.0";s:5:"typo3";s:11:"3.9.9-0.0.0";}s:9:"conflicts";a:1:{s:11:"skingreyman";s:6:"0.0.0-";}}', 'Peter Klein', 'peter@umloud.dk', 'pmk65', 'ec4f5ed2679271ef10f7ab8f3dc4b399', 'Mootools Compability Fix. Now works correctly on sites using the Mootools Javascript Framework.', 'Umloud Untd', 2000, 0, 0),
(11820, 0, 'pmktextarea', 1, '0.3.0', 4620, 1711, 'PMK Textarea Widget', 'Adds resizing, linenumbers, improved Tabkey handling and other neat features to standard textareas.', 2, 0, 0, 1207391005, 'a:2:{s:7:"depends";a:2:{s:3:"php";s:11:"4.3.0-0.0.0";s:5:"typo3";s:11:"3.9.9-0.0.0";}s:9:"conflicts";a:1:{s:11:"skingreyman";s:6:"0.0.0-";}}', 'Peter Klein', 'peter@umloud.dk', 'pmk65', '844e18af16d433491a0c39dfc6638e24', 'Now compatible with TYPO3 v4.2. - JavaScript has been updated so that the linenumber scrolling works in Mozilla again.', 'Umloud Untd', 3000, 1, 0),
(11821, 0, 'mp_em_forimages', 1, '0.0.1', 638, 181, 'em for images', 'Extends the tt_content types image and image with text configuration with the possibility to use em height and width. if you use this options the will be included after the normal width an height in the image-tag.', 0, 0, 2, 1156172906, 'a:0:{}', 'Matthias', 'mail@css-tutorials.de', 'lineman', 'b71397996cab83d20d5ffad5cf43ad21', 'this is the initial release and adds to all the images em-sizes with inlinestyles. read the readme.txt or meet http://www.css-tutorials.de/typo3tutorials/em-wertefrbilder.html for documentation (website only german)', '', 1, 0, 0);
