(11970, 0, 'hl_dam_gallery', 1, '0.1.0', 9080, 205, 'DAM Show Image', 'Displays a single image on a page together with meta data from the DAM backend. Extends the existing elements (image, text /w image) to a fully featured gallery.', 0, 0, 3, 1156797452, 'a:1:{s:7:"depends";a:4:{s:3:"cms";s:0:"";s:3:"dam";s:0:"";s:13:"dam_ttcontent";s:0:"";s:18:"css_styled_content";s:0:"";}}', 'Heiner Lamprecht', 'typo3@heiner-lamprecht.net', 'hlamprecht', 'e38f8ad9f141cd246d1a137eedbffd4f', '', '', 1000, 0, 0),
(11971, 0, 'hl_dam_gallery', 1, '0.2.0', 9080, 276, 'DAM Show Image', 'Displays a single image on a page together with meta data from the DAM backend. Extends the existing elements (image, text /w image) to a fully featured gallery.', 0, 0, 3, 1156943974, 'a:1:{s:7:"depends";a:4:{s:3:"cms";s:0:"";s:3:"dam";s:0:"";s:13:"dam_ttcontent";s:0:"";s:18:"css_styled_content";s:0:"";}}', 'Heiner Lamprecht', 'typo3@heiner-lamprecht.net', 'hlamprecht', 'b018535274352b20d2e462aed513492e', 'Fixed a bug in creating links for cached pages.  Added counting and displaying hits per image.  Enabled cropping of previews to non-square shapes.', '', 2000, 0, 0),
(11972, 0, 'hl_dam_gallery', 1, '0.3.0', 9080, 495, 'DAM Photo Gallery', 'FE plugin, that extends existing elements (image, text /w image) to a fully featured gallery.  Can also be used as a replacement for the showimage-popup window.', 1, 0, 3, 1160823908, 'a:1:{s:7:"depends";a:4:{s:3:"cms";s:0:"";s:3:"dam";s:0:"";s:13:"dam_ttcontent";s:0:"";s:18:"css_styled_content";s:0:"";}}', 'Heiner Lamprecht', 'typo3@heiner-lamprecht.net', 'hlamprecht', '8b6b94322cc0a61b948f5b9a19b94106', ' Added options to resize images in single view to a reasonable size and to create links for downloading the original image.\n fixed a bug in creating image tags in textpic-elements. Now correct tags are created, if the text itself contains images, which', '', 3000, 0, 0),
(11973, 0, 'hl_dam_gallery', 1, '0.4.0', 9080, 159, 'DAM Photo Gallery', 'FE plugin, that extends existing elements (image, text /w image) to a fully featured gallery.  Can also be used as a replacement for the showimage-popup window.', 1, 0, 3, 1165775002, 'a:1:{s:7:"depends";a:5:{s:3:"cms";s:0:"";s:3:"dam";s:0:"";s:13:"dam_ttcontent";s:0:"";s:18:"css_styled_content";s:0:"";s:9:"mmforeign";s:0:"";}}', 'Heiner Lamprecht', 'typo3@heiner-lamprecht.net', 'hlamprecht', 'd81d52b675b1a9d789058d5afe331833', 'Added support for HTML templates and for displaying a map showing the position of the image, using Google Maps. TS configuration can now be made with constant editor.', '', 4000, 0, 0),
(11974, 0, 'hl_dam_gallery', 1, '0.5.0', 9080, 300, 'DAM Photo Gallery', 'FE plugin, that extends existing elements (image, text /w image) to a fully featured gallery.  Can also be used as a replacement for the showimage-popup window.', 1, 0, 3, 1166734725, 'a:1:{s:7:"depends";a:5:{s:3:"cms";s:0:"";s:3:"dam";s:0:"";s:13:"dam_ttcontent";s:0:"";s:18:"css_styled_content";s:0:"";s:9:"mmforeign";s:0:"";}}', 'Heiner Lamprecht', 'typo3@heiner-lamprecht.net', 'hlamprecht', 'f482d30eaec41b356d96f0b68165e2a7', 'Integrated Lightbox2. Now it is possible to display the images in an animated overlay over the gallery view.', '', 5000, 0, 0),
