(12048, 0, 'dynbeedit', 1, '0.0.1', 943, 97, 'Dynamic Backend Editing', 'Edit related content (kind of "database relation") on one page using AJAX. This is called via userFunc from TCA. It allows to administrate more complex structures.', 0, 0, 0, 1157563137, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:6:"4.0.0-";s:3:"php";s:6:"5.0.0-";s:5:"xajax";s:0:"";}}', 'Oliver Hader', 'oh@inpublica.de', 'ohader', 'f534ad571fd790e2e5c2828aadb1b23a', 'Initial release (very alpha). Its by now just a proof-of-concept how to add data in a dynamic way and how to make sure, that embedded data only belongs to the embedding record.', '', 1, 0, 0),
(12049, 0, 'dynbeedit', 1, '0.0.2', 943, 254, 'Dynamic Backend Editing', 'Edit related content (kind of "database relation") on one page using AJAX. This is called via userFunc from TCA. It allows to administrate more complex structures.', 0, 0, 0, 1157625350, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:6:"4.0.0-";s:3:"php";s:6:"5.0.0-";s:5:"xajax";s:0:"";}}', 'Oliver Hader', 'oh@inpublica.de', 'ohader', '338c07b3428a205c080bf35416fd6364', 'BugFix on creating a new record that embeds data from a table', '', 2, 0, 0),
(12050, 0, 'dynbeedit', 1, '0.0.3', 943, 461, 'Dynamic Backend Editing', 'Edit related content (kind of "database relation") on one page using AJAX. This is called via userFunc from TCA. It allows to administrate more complex structures.', 0, 0, 0, 1160486878, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:6:"4.0.0-";s:3:"php";s:6:"5.0.0-";s:5:"xajax";s:0:"";}}', 'Oliver Hader', 'oh@inpublica.de', 'ohader', '485e1083a7fd1b4d311a1184b69deaca', 'Changed some encodings for AJAX data and some JavaScript debuggin. This project is now called "Inline-Relational-Record-Editing", see http://wiki.typo3.org/index.php/Inline_Relational_Record_Editing for more information.', '', 3, 0, 0),
(12051, 0, 'dynbeedit', 1, '0.0.4', 943, 131, 'Dynamic Backend Editing', 'This feature was integrated into TYPO3 4.1 as Inline Relational Record Editing (IRRE).', 5, 0, 0, 1172003586, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"4.0.0-0.0.0";s:3:"php";s:11:"5.0.0-0.0.0";s:5:"xajax";s:0:"";}}', 'Oliver Hader', 'oh@inpublica.de', 'ohader', '797b5349abcd937752a6677a680269b0', 'Marked extension as obsolete. DynBeEdit is called IRRE now and part of TYPO3 4.1!', '', 4, 1, 0),
