(12234, 0, 'timtab_sociable', 1, '1.0.0', 4298, 241, 'TIMTAB - social bookmark icons', 'this extension shows a line of small icons of social bookmark services. with this buttons an user can add your blogpost easy to the services. Please read the README.txt for a quick-install-guide, documentation follow later. Please report bugs, or new feat', 2, -1, 3, 1157748094, 'a:0:{}', 'Frank Ngler', 'typo3@naegler.net', 'neoblack', 'd44a49961a1f4702e6ce462a871b5f8c', 'inital release, Please report bugs, or new feature request at http://bugs.naegler.net', 'http://www.frank-naegler.de', 1000000, 0, 0),
