(12497, 0, 'csevents', 1, '0.0.1', 1986, 62, 'Event database', 'Database for recurring events', 3, 0, 3, 1159819869, 'a:0:{}', 'Christian Stdemann', 'typo3@christian-stuedemann.de', 'stuedemann', '40e9a1720b956559175f350f63a5e79c', 'This is just an experimental version. I strongly recommend NOT to use this initial version. Its uploaded just for testing. The programming is strongly specific for a very special solution and not (yet) configurable enough. If you really want to use this', '', 1, 0, 0),
(12498, 0, 'csevents', 1, '0.0.2', 1986, 232, 'Event database', 'Database for recurring events', 3, 0, 3, 1159829794, 'a:0:{}', 'Christian Stuedemann', 'typo3@christian-stuedemann.de', 'stuedemann', '4620b4a123a2d49769beb68fd40cb75c', 'Just some little changes, but I still recommend NOT to use this extension, cause its hardly in an experimental status.', '', 2, 0, 0),
(12499, 0, 'csevents', 1, '0.0.3', 1986, 199, 'Event database', 'Database for recurring events', 3, 0, 3, 1159873406, 'a:0:{}', 'Christian Stuedemann', 'typo3@christian-stuedemann.de', 'stuedemann', 'a8435d9136d2ac549a24d1ded384bcbe', 'Just another patch. I still strongly recommend NOT to use this experimental version, cause its hardly adopted to a very special solution.', '', 3, 0, 0),
(12500, 0, 'csevents', 1, '0.0.4', 1986, 184, 'Event database', 'Database for recurring events', 3, 0, 3, 1159890118, 'a:0:{}', 'Christian Stuedemann', 'typo3@christian-stuedemann.de', 'stuedemann', '1dd00597d1fc74c73aa25338483f609b', 'Just another patch. I still strongly recommend NOT to use this plugin, cause it is still hardly programmed for a very special solution.', '', 4, 0, 0),
(12501, 0, 'csevents', 1, '0.0.5', 1986, 207, 'Event database', 'Database for recurring events', 3, 0, 3, 1159897532, 'a:0:{}', 'Christian Stuedemann', 'typo3@christian-stuedemann.de', 'stuedemann', '326e78c7000bb289104c14dca422bb4a', 'Just another patch. I still strongly recommend NOT to use this experimental state of this plugin, because its strongly implemented to give a very specific solution. It will change to be more general...', '', 5, 0, 0),
(12502, 0, 'csevents', 1, '0.0.6', 1986, 81, 'Event database', 'Database for recurring events', 3, 0, 3, 1159908371, 'a:0:{}', 'Christian Stuedemann', 'typo3@christian-stuedemann.de', 'stuedemann', '53fcdd6bed9c5873be0eca72ab9d20a1', 'Just a patch. I strongly recommend NOT to use this plugin, cause it is quick&dirty implemented for a very special solution. I will bring up a better version later on.', '', 6, 0, 0),
(12503, 0, 'csevents', 1, '0.0.7', 1986, 226, 'Event database', 'Database for recurring events', 3, 0, 3, 1159909313, 'a:0:{}', 'Christian Stuedemann', 'typo3@christian-stuedemann.de', 'stuedemann', '9599da1741badbf5207240b6c3c72d17', 'Just a patch. I strongly recommend NOT to use this plugin, cause it is quick&dirty implemented for a very special solution. I will bring up a better version later on.', '', 7, 0, 0),
(12504, 0, 'csevents', 1, '0.0.8', 1986, 215, 'Event database', 'Database for recurring events', 3, 0, 3, 1160035189, 'a:0:{}', 'Christian Stuedemann', 'typo3@christian-stuedemann.de', 'stuedemann', 'ffc264c7f0809c3ea416e95bec061892', 'Patch: Mutter better, much more general in may cases, flexform, but I still strongly recommend NOT to use this plugin, because its a quick&dirty hack for a very special solution and it is not well documented yet.', '', 8, 0, 0),
(12505, 0, 'csevents', 1, '0.0.9', 1986, 90, 'Event database', 'Database for recurring events', 3, 0, 3, 1161204578, 'a:0:{}', 'Christian Stuedemann', 'typo3@christian-stuedemann.de', 'stuedemann', '9fabbb825f0677b60afc5133802c8b90', 'Its a much more general solution now, but I still recommend NOT to use this plugin until I have added a proper documentation. If you are interested in details, please contact me by e-mail.', '', 9, 0, 0),
(12506, 0, 'csevents', 1, '0.0.10', 1986, 238, 'Event database', 'Database for recurring events', 3, 0, 3, 1162417945, 'a:0:{}', 'Christian Stuedemann', 'typo3@christian-stuedemann.de', 'stuedemann', '665c898c8fe0dedf08e1bea51b9d5fa5', 'Its getting much more better. Who ever wants to try to use this, is invited to do so, but the documentation is not on a current and consistent state. Price categories are not implemented completly. Contact me, if you have questions! Remember: Its still', '', 10, 0, 0),
(12507, 0, 'csevents', 1, '0.0.11', 1986, 252, 'Event database', 'Database for recurring events', 3, 0, 3, 1176502836, 'a:0:{}', 'Christian Stuedemann', 'typo3@christian-stuedemann.de', 'stuedemann', '802550adaf2c36e13d8e0a7e70457be2', 'Just some smaller changes (e.g. sorting). Please note, that this is still an EXPERIMENTAL version for a very specific request / solution. Feel free to use and dont hesitate to ask me for documentation / support.', '', 11, 1, 0),
