(12583, 0, 'tagpack', 1, '0.9.0', 1209, 28, 'Tag Pack', 'All purpose tagging suite. Use tags for almost any allowed table without having to create new DB fields for each of them. Create multifunctional tag clouds using surf or filter mode together with time based settings, a tag breadcrumb menu and a searchbox', 1, 0, 4, 1239731366, 'a:0:{}', 'JoH asenau', 'jh@eqony.com', 'cybercraft', 'dfd6767c865e8b17646c0e7dc6ac872e', 'Functionality slightly modified to improve usability.\r\nDoubleclicking is now possible where users expect it and ENTER will submit the form while merging.\r\nCSS slightly changed as well.', '', 9000, 0, 0),
