(12959, 0, 'sk_webmail', 1, '0.0.1', 2220, 232, 'IMAP Webmail', 'Adds a imap-based webmailer to your FE', 3, 0, 3, 1164800034, 'a:0:{}', 'Sebastian Kuhn', 'sebastian@speerflug.de', 'revolvermann', 'ae1cd1ed808fc53c2ac905c98f6dbe9c', '', '', 1, 0, 0),
(12960, 0, 'sk_webmail', 1, '0.0.2', 2220, 273, 'IMAP Webmail', 'Adds a imap-based webmailer to your FE', 0, 0, 3, 1166100740, 'a:0:{}', 'Sebastian Kuhn', 'sebastian@speerflug.de', 'revolvermann', '09e2acf004497d328ff7699d6c2a6c49', '- Added attachment support (download attachment)\n\nIt is still more a "mailreader" than a webmailer, since it only lets you view mails. \nFunctionality will stay like this, until Ive rewritten the script to be compliant with the Typo3 standards.\n', '', 2, 0, 0),
(12961, 0, 'sk_webmail', 1, '0.0.3', 2220, 199, 'IMAP Webmail', 'Adds a imap-based webmailer to your FE', 0, 0, 3, 1167899857, 'a:0:{}', 'Sebastian Kuhn', 'sebastian@speerflug.de', 'revolvermann', '6aeeb39a0a5af3098459bdba7377af9c', '- Ive rewritten most of the code, to be compliant with the Typo3-API\n- Fixed some minor bugs.', '', 3, 0, 0),
(12962, 0, 'sk_webmail', 1, '0.0.4', 2220, 199, 'IMAP Webmail', 'Adds a imap-based webmailer to your FE', 0, 0, 3, 1167922732, 'a:0:{}', 'Sebastian Kuhn', 'sebastian@speerflug.de', 'revolvermann', '82484cdaf5da2579886d5651fd3e5747', 'You can now DELETE mails! ;)', '', 4, 0, 0),
(12963, 0, 'sk_webmail', 1, '0.0.5', 2220, 121, 'IMAP Webmail', 'Adds a imap-based webmailer to your FE', 0, 0, 3, 1168444107, 'a:0:{}', 'Sebastian Kuhn', 'sebastian@speerflug.de', 'revolvermann', 'dacdca74a26d19e3b40aceeb4cefb8e4', 'Getting better and better: You can now create new folders!\nA first, basic documentation will be included in the next upload.', '', 5, 0, 0),
(12964, 0, 'sk_webmail', 1, '0.1.0', 2220, 182, 'IMAP Webmail', 'Adds a imap-based webmailer to your FE', 0, 0, 3, 1168513485, 'a:0:{}', 'Sebastian Kuhn', 'sebastian@speerflug.de', 'revolvermann', '1f7f2775d1f3757d16087a18fcff5a51', 'Next one! I decided to make the first sub version increase, because of a new feature: This version has a fully operational folder management.', '', 1000, 0, 0),
(12965, 0, 'sk_webmail', 1, '0.1.1', 2220, 227, 'IMAP Webmail', 'Adds a imap-based webmailer to your FE', 0, 0, 3, 1168517961, 'a:0:{}', 'Sebastian Kuhn', 'sebastian@speerflug.de', 'revolvermann', 'b5d74973dbc961a4e082ce052a9aa4a6', '', '', 1001, 0, 0),
