(12991, 0, 'flatmgr', 1, '1.1.1', 5040, 229, 'Flat Manager', 'Vacation flat manager, shows the booking of vacation flats in a calendar', 1, -1, 3, 1178091721, 'a:0:{}', 'Joachim Ruhs', 'postmaster@joachim-ruhs.de', 'joachim_ruhs', '94b7422fa5f7ec19d9d61fd725729ee3', 'typoscript configuration added,\nsome source modifications - see changelog', '', 1001001, 0, 0),
(12992, 0, 'flatmgr', 1, '1.2.0', 5040, 26, 'Flat Manager', 'Vacation flat manager, shows the booking of vacation flats in a calendar, admin interface included', 1, -1, 3, 1179172069, 'a:0:{}', 'Joachim Ruhs', 'postmaster@joachim-ruhs.de', 'joachim_ruhs', '3f482718cbfc807344446672d537900b', 'rewritten to mvc-model, admin interface integrated, documentation modified', '', 1002000, 0, 0),
(12993, 0, 'flatmgr', 1, '1.2.1', 5040, 227, 'Flat Manager', 'Vacation flat manager, shows the booking of vacation flats in a calendar, admin interface included', 1, -1, 3, 1179223003, 'a:0:{}', 'Joachim Ruhs', 'postmaster@joachim-ruhs.de', 'joachim_ruhs', '1a081ee161229d7ee9d1411e9ffbd327', 'inserting flats and booking records can now be done easily with the admin interface, source rewritten to mvc-model, documentation modified', '', 1002001, 0, 0),
(12994, 0, 'flatmgr', 1, '1.2.2', 5040, 86, 'Flat Manager', 'Vacation flat manager, shows the booking of vacation flats in a calendar, admin interface included, depends now on rlmp_dateselectlib', 1, -1, 3, 1179400928, 'a:0:{}', 'Joachim Ruhs', 'postmaster@joachim-ruhs.de', 'joachim_ruhs', 'e93bb306aa05151622d589c51a61249d', 'minor layout changes in admin pages,\ndocumentation modified, go-back link inserted to the booking page', '', 1002002, 0, 0),
(12995, 0, 'flatmgr', 1, '1.3.0', 5040, 69, 'Flat Manager', 'Vacation flat manager, shows the booking of vacation flats in a calendar, admin interface included, depends on rlmp_dateselectlib', 1, -1, 3, 1180636004, 'a:0:{}', 'Joachim Ruhs', 'postmaster@joachim-ruhs.de', 'joachim_ruhs', '91ebf39d18136b4024076c7e5c44d52f', 'Availability check for flats included, source cleaning, improved admin frontend, ability to rename flats in the admin frontend with complete typo3 history - see manual.sxw', '', 1003000, 0, 0),
(12996, 0, 'flatmgr', 1, '1.3.1', 5040, 28, 'Flat Manager', 'Vacation flat manager, shows the booking of vacation flats in a calendar, admin interface included, depends on rlmp_dateselectlib', 1, -1, 3, 1180799342, 'a:0:{}', 'Joachim Ruhs', 'postmaster@joachim-ruhs.de', 'joachim_ruhs', '695f24b58bae4c7e324401182707819d', 'Small Bugfix: Link in availibility check is correct now and will be shown only if there is only one flatmgr calendar with monthsinglerow- or monthmultirow-display in the page tree. Thx Mr. Schreiber', '', 1003001, 0, 0),
(12997, 0, 'flatmgr', 1, '1.3.2', 5040, 28, 'Flat Manager', 'Vacation flat manager, shows the booking of vacation flats in a calendar, admin interface included, depends on rlmp_dateselectlib', 1, -1, 3, 1180809487, 'a:0:{}', 'Joachim Ruhs', 'postmaster@joachim-ruhs.de', 'joachim_ruhs', '5cc144492fa12c7fd7bb0b3fbfb80778', 'Availibilitycheck modified - the page to link to the booking calendar can now be inserted with flexform. If no pageid is set, then the current page is used for the link.', '', 1003002, 0, 0),
(12998, 0, 'flatmgr', 1, '1.4.0', 5040, 49, 'Flat Manager', 'Vacation flat manager, shows the booking of vacation flats in a calendar, admin interface included, depends on rlmp_dateselectlib', 1, -1, 3, 1180859759, 'a:0:{}', 'Joachim Ruhs', 'postmaster@joachim-ruhs.de', 'joachim_ruhs', 'f48750558c938811d71ce221f333148f', 'Availibilitycheck modified - the page to link to the booking calendar can now be inserted with flexform. If no pageid is given, then the current page is used for the link.', '', 1004000, 0, 0),
(12999, 0, 'flatmgr', 1, '1.5.0', 5040, 36, 'Flat Manager', 'Vacation flat manager, shows the booking of vacation flats in a calendar, admin interface included, depends on rlmp_dateselectlib', 1, -1, 3, 1181047612, 'a:0:{}', 'Joachim Ruhs', 'postmaster@joachim-ruhs.de', 'joachim_ruhs', 'ef0a064c31798c7bfc982f1ca63aee96', 'Availibility check modified, next possible time period for booking can now be shown, added field bookedby in table tx_flatmgr_book to assign a name to a booking, better error handling of incorrect user input', '', 1005000, 0, 0),
(13000, 0, 'flatmgr', 1, '1.5.1', 5040, 46, 'Flat Manager', 'Vacation flat manager, shows the booking of vacation flats in a calendar, admin interface included, depends on rlmp_dateselectlib', 1, -1, 3, 1181069375, 'a:0:{}', 'Joachim Ruhs', 'postmaster@joachim-ruhs.de', 'joachim_ruhs', '4576288dd33c78ac266d763692573b63', 'small changes in setup.txt (class calendarLegend inserted), booking is now done with arrival- and departure-date. This dates are shown in user frontend as 2 different triangles.', '', 1005001, 0, 0),
(13001, 0, 'flatmgr', 1, '1.6.0', 5040, 41, 'Flat Manager', 'Vacation flat manager, shows the booking of vacation flats in a calendar, admin interface included, depends on rlmp_dateselectlib', 1, -1, 3, 1181221338, 'a:0:{}', 'Joachim Ruhs', 'postmaster@joachim-ruhs.de', 'joachim_ruhs', 'bfde68239a8307a73732bd09060456d0', 'Availability check modified, now you can check external TYPO3 sites with flatmgr installed. Needs an external site flatmgr version 1.6.0, Departure date is shown now correct in availability check - bugfix - see manual.sxw', '', 1006000, 0, 0);
INSERT INTO `tx_extensionmanager_domain_model_extension` (`uid`, `pid`, `extension_key`, `repository`, `version`, `alldownloadcounter`, `downloadcounter`, `title`, `description`, `state`, `review_state`, `category`, `last_updated`, `serialized_dependencies`, `author_name`, `author_email`, `ownerusername`, `md5hash`, `update_comment`, `authorcompany`, `integer_version`, `current_version`, `lastreviewedversion`) VALUES
(13002, 0, 'flatmgr', 1, '1.6.2', 5040, 39, 'Flat Manager', 'Vacation flat manager, shows the booking of vacation flats in a calendar, admin interface included, depends on rlmp_dateselectlib', 1, -1, 3, 1181330403, 'a:0:{}', 'Joachim Ruhs', 'postmaster@joachim-ruhs.de', 'joachim_ruhs', '665ad23f8407ea1d8cabc7558c470a39', 'Important: If you update to this version please check the booking records - especially the departure date, added icon for bookerchanged days, possibility to show bookedbyfield as tooltip - see manual.sxw', '', 1006002, 0, 0),
(13003, 0, 'flatmgr', 1, '1.7.0', 5040, 41, 'Flat Manager', 'Vacation flat manager, shows the booking of vacation flats in a calendar, admin interface included, depends on rlmp_dateselectlib', 1, -1, 3, 1181506525, 'a:1:{s:7:"depends";a:2:{s:18:"rlmp_dateselectlib";s:6:"0.1.7-";s:5:"xajax";s:6:"0.2.4-";}}', 'Joachim Ruhs', 'postmaster@joachim-ruhs.de', 'joachim_ruhs', '4b430f7a7a15003083ed4e2494cefd07', 'Avalability check improved - now with XAJAX - use same versions of flatmgr local and external for the check, new layout of availability check results with legend. Small bugfixes.', '', 1007000, 0, 0),
(13004, 0, 'flatmgr', 1, '1.7.1', 5040, 45, 'Flat Manager', 'Vacation flat manager, shows the booking of vacation flats in a calendar, admin interface included, depends on rlmp_dateselectlib', 1, -1, 3, 1181643293, 'a:1:{s:7:"depends";a:2:{s:18:"rlmp_dateselectlib";s:5:"0.1.7";s:5:"xajax";s:5:"0.2.4";}}', 'Joachim Ruhs', 'postmaster@joachim-ruhs.de', 'joachim_ruhs', '1601d93599ff321afb26a1d7d8e7acda', 'Character encoding of XAJAX is automatically set to TS setup page.config.locale_all. Calendar view can now display start of a week with sundays (configurable in flexfoms). More see FAQ in manual.sxw\n', '', 1007001, 0, 0),
