(13408, 0, 'debug_mysql_db', 1, '0.1.100', 1345, 224, 'Debug Mysql DB', 'Extends t3lib_db (by xlcassing it) to show Errors and Debug-Messages. Usefull for viewing and debugging of sql-queries generated by our code. Shows Errormessages if they occur. Simply deinstall to remove all debug-output.', 0, 0, 4, 1169043252, 'a:0:{}', 'Stefan Geith', 'typo3dev2007@geithware.de', 'franzholz', '4e91028b1398871a9beae9adfdac257a', 'First TER Upload. exec_SELECTgetRows() and sql_fetch...() dont debug yet.', '', 1100, 0, 0),
(13409, 0, 'debug_mysql_db', 1, '0.1.101', 1345, 116, 'Debug Mysql DB', 'Extends t3lib_db (by xlcassing it) to show Errors and Debug-Messages. Usefull for viewing and debugging of sql-queries generated by our code. Shows Errormessages if they occur. Simply deinstall to remove all debug-output.', 0, 0, 4, 1170408965, 'a:0:{}', 'Stefan Geith', 'typo3dev2007@geithware.de', 'franzholz', 'f2182961be5e7fade02b0cb51697df7a', '', '', 1101, 0, 0),
(13410, 0, 'debug_mysql_db', 1, '0.1.102', 1345, 505, 'Debug Mysql DB', 'Extends t3lib_db (by xlcassing it) to show Errors and Debug-Messages. Usefull for viewing and debugging of sql-queries generated by our code. Shows Errormessages if they occur. Simply deinstall to remove all debug-output.', 0, 0, 4, 1171368074, 'a:0:{}', 'Stefan Geith', 'typo3dev2007@geithware.de', 'franzholz', '97088951becb0df8fb3d9fe84d279d25', 'Bugfix: Now Works with Typo3 3.8x also.', '', 1102, 0, 0),
(13411, 0, 'debug_mysql_db', 1, '0.2.0', 1345, 18, 'Debug Mysql DB', 'Extends t3lib_db (by xlcassing it) to show Errors and Debug-Messages. Usefull for viewing and debugging of sql-queries generated using its methods. Shows error messages if they occur. Simply deinstall to remove all debug-output.', 1, 0, 4, 1227796965, 'a:1:{s:7:"depends";a:1:{s:3:"php";s:11:"5.0.0-0.0.0";}}', 'Stefan Geith', 'typo3dev2008@geithware.de', 'franzholz', 'a59f7b74bcd7dec6115ae45ef79149fb', 'See changelog:\r\n fill in debug_backtrace always when BTRACE_SQL has been set\r\n use microtime(true); instead of time() to get the time in microseconds\r\n enter and display time in miliseconds\r\n do the time measurements always\r\n new feature OUTPUT: make', '', 2000, 0, 0),
(13412, 0, 'debug_mysql_db', 1, '0.2.1', 1345, 21, 'Debug Mysql DB', 'Extends t3lib_db (by xlcassing it) to show Errors and Debug-Messages. Usefull for viewing and debugging of sql-queries generated using its methods. Shows error messages if they occur. Simply deinstall to remove all debug-output.', 1, 0, 4, 1232102099, 'a:1:{s:7:"depends";a:1:{s:3:"php";s:11:"5.0.0-0.0.0";}}', 'Stefan Geith', 'typo3dev2008@geithware.de', 'franzholz', '73efcae2ee27cc8f055882fcc30797f5', 'Thanks to Franz Holzinger:\r\n allow Disable mysql errormessages \r\n fix bug 8728 \r\n fix bug not to show a PHP Warning', '', 2001, 0, 0),
(13413, 0, 'debug_mysql_db', 1, '0.2.2', 1345, 30, 'Debug Mysql DB', 'Extends t3lib_db (by xlcassing it) to show Errors and Debug-Messages. Usefull for viewing and debugging of sql-queries generated using its methods. Shows error messages if they occur. Simply deinstall to remove all debug-output.', 1, 0, 4, 1234166242, 'a:1:{s:7:"depends";a:1:{s:3:"php";s:11:"5.0.0-0.0.0";}}', 'Stefan Geith', 'typo3dev2008@geithware.de', 'franzholz', 'e9f41c2450e33b48867725f16820ac24', 'Added separator line to debug output for better readability.', '', 2002, 0, 0),
(13414, 0, 'debug_mysql_db', 1, '0.3.0', 1345, 49, 'Debug Mysql DB', 'Extends t3lib_db (by xclassing it) to show Errors and Debug-Messages. Usefull for viewing and debugging of sql-queries generated using its methods. Shows error messages if they occur. Simply deinstall to remove all debug-output.', 1, 0, 4, 1247818725, 'a:1:{s:7:"depends";a:1:{s:3:"php";s:11:"5.0.0-0.0.0";}}', 'Stefan Geith', 'typo3dev2009@geithware.de', 'franzholz', '03cd1c6f26be0928b401db96a4386b0d', 'Add all new methods of t3lib_DB from TYPO3 4.3 (Thanks to Franz Holzinger)', '', 3000, 0, 0),
(13415, 0, 'debug_mysql_db', 1, '0.3.2', 1345, 63, 'Debug Mysql DB', 'Extends t3lib_db (by xclassing it) to show Errors and Debug-Messages. Usefull for viewing and debugging of sql-queries generated using its methods. Shows error messages if they occur. Simply deinstall to remove all debug-output.', 1, 0, 4, 1259135537, 'a:1:{s:7:"depends";a:1:{s:3:"php";s:11:"5.0.0-0.0.0";}}', 'Stefan Geith', 'typo3dev2009@geithware.de', 'franzholz', 'aad1b0210f049ae03b207cb052b8b49b', 'Version 0.3.2\r\n add exclude table names which are normally system tables and the output is not wanted for the debugging of extensions;\r\n add the TCA option to show only those tables from which the $TCA has been loaded;\r\n fix bug where queries with tabl', '', 3002, 0, 0),
(13416, 0, 'debug_mysql_db', 1, '0.3.3', 1345, 27, 'Debug Mysql DB', 'Extends t3lib_db (by xclassing it) to show Errors and Debug-Messages. Usefull for viewing and debugging of sql-queries generated using its methods. Shows error messages if they occur. Simply deinstall to remove all debug-output.', 1, 0, 4, 1265786363, 'a:1:{s:7:"depends";a:1:{s:3:"php";s:11:"5.0.0-0.0.0";}}', 'Stefan Geith', 'typo3dev2010@geithware.de', 'franzholz', '8960ea7b5e28c3b39f188caf3bd52f32', 'Changed: do not debug disabled tables even in an error case (by Franz Holzinger)', '', 3003, 0, 0),
(13417, 0, 'debug_mysql_db', 1, '0.3.4', 1345, 34, 'Debug Mysql DB', 'Extends t3lib_db (by xclassing it) to show Errors and Debug-Messages. Usefull for viewing and debugging of sql-queries generated using its methods. Shows error messages if they occur. Simply deinstall to remove all debug-output.', 1, 0, 4, 1272874526, 'a:1:{s:7:"depends";a:1:{s:3:"php";s:11:"5.0.0-0.0.0";}}', 'Stefan Geith', 'typo3dev2010@geithware.de', 'franzholz', 'ba03bbe937fa8eaa688065150fb37615', 'Changed: do not call any code of debug_mysql_db if TYPO3_MODE is not FE or BE or ALL. This should speed it up. (by Franz Holzinger)', '', 3004, 0, 0),
(13418, 0, 'debug_mysql_db', 1, '0.3.6', 1345, 95, 'Debug Mysql DB', 'Extends t3lib_db (by xclassing it) to show Errors and Debug-Messages. Usefull for viewing and debugging of sql-queries generated using its methods. Shows error messages if they occur. Simply deinstall to remove all debug-output.', 1, 0, 4, 1286793414, 'a:1:{s:7:"depends";a:1:{s:3:"php";s:11:"5.0.0-0.0.0";}}', 'Stefan Geith', 'typo3dev2010@geithware.de', 'franzholz', '8e25f8317e66c5ab2895ad08cceba1d6', 'Fix bug in debugging not the tables from EXCLUDETABLES; Thanks to Franz Holzinger \r\n', '', 3006, 0, 0),
(13419, 0, 'debug_mysql_db', 1, '0.4.0', 1345, 45, 'Debug Mysql DB', 'Extends t3lib_db (by xclassing it) to show Errors and Debug-Messages. Usefull for viewing and debugging of sql-queries generated using its methods. Shows error messages if they occur. Simply deinstall to remove all debug-output.', 1, 0, 4, 1299056008, 'a:2:{s:7:"depends";a:1:{s:3:"php";s:11:"5.0.0-0.0.0";}s:9:"conflicts";a:1:{s:4:"dbal";s:11:"0.0.0-0.0.0";}}', 'Stefan Geith', 'typo3dev2010@geithware.de', 'franzholz', '9e2f28f26496561cae323583f82142c8', ' use the latest query in debug output if lastBuiltQuery is empty\r\n add conflict with the dbal extension\r\n fix bug: SQL ERROR has not been shown when an alias has been used\r\n Thanks to Franz Holzinger', '', 4000, 0, 0),
(13420, 0, 'debug_mysql_db', 1, '0.4.1', 1345, 118, 'Debug Mysql DB', 'Extends t3lib_db (by xclassing it) to show Errors and Debug-Messages. Usefull for viewing and debugging of sql-queries generated using its methods. Shows error messages if they occur. Simply deinstall to remove all debug-output.', 1, 0, 4, 1304329340, 'a:2:{s:7:"depends";a:1:{s:3:"php";s:11:"5.0.0-0.0.0";}s:9:"conflicts";a:1:{s:4:"dbal";s:11:"0.0.0-0.0.0";}}', 'Stefan Geith', 'typo3dev2010@geithware.de', 'franzholz', '77c37c22f0a4afb9b0f67f31ad4249d8', 'Bugfix: SQL ERROR has not been shown when an alias has been used in long queries (Thanks to F.Holzinger)\r\n', '', 4001, 0, 0),
(13421, 0, 'debug_mysql_db', 1, '0.4.2', 1345, 0, 'Debug Mysql DB', 'Extends t3lib_db (by xclassing it) to show Errors and Debug-Messages. Usefull for viewing and debugging of sql-queries generated using its methods. Shows error messages if they occur. Simply deinstall to remove all debug-output.', 1, 0, 4, 1339400650, 'a:2:{s:7:"depends";a:2:{s:3:"php";s:11:"5.0.0-0.0.0";s:5:"typo3";s:12:"4.3.0-4.7.99";}s:9:"conflicts";a:1:{s:4:"dbal";s:11:"0.0.0-0.0.0";}}', 'Stefan Geith', 'typo3dev2012@geithware.de', 'franzholz', 'de05cfbe33ec6dcd5a8fe8081e9c9d98', 'Now compatible with Typo3 up to 4.7', '', 4002, 0, 0);
INSERT INTO `tx_extensionmanager_domain_model_extension` (`uid`, `pid`, `extension_key`, `repository`, `version`, `alldownloadcounter`, `downloadcounter`, `title`, `description`, `state`, `review_state`, `category`, `last_updated`, `serialized_dependencies`, `author_name`, `author_email`, `ownerusername`, `md5hash`, `update_comment`, `authorcompany`, `integer_version`, `current_version`, `lastreviewedversion`) VALUES
(13422, 0, 'debug_mysql_db', 1, '0.4.5', 1345, 0, 'Debug Mysql DB', 'FOR TYPO3 4.x !! Last Version for Typo3 4.3-4.7 !! TYPO3 6.x see 0.5 !! For Extends t3lib_db (by xclassing it) to show Errors and Debug-Messages. Usefull for viewing and debugging of sql-queries generated using its methods. Shows error messages if they occur. Simply deinstall to remove all debug-output. ', 1, 0, 4, 1370435139, 'a:2:{s:7:"depends";a:2:{s:3:"php";s:11:"5.0.0-0.0.0";s:5:"typo3";s:12:"4.3.0-4.7.99";}s:9:"conflicts";a:1:{s:4:"dbal";s:11:"0.0.0-0.0.0";}}', 'Stefan Geith', 'typo3dev2012@geithware.de', 'franzholz', '6adcc29a0394ea2fcad199096438f8e4', 'FOR TYPO3 4.x !! Last Version for Typo3 4.3-4.7 !! (For TYPO3 CMS 6.x see Versions 0.5)', '', 4005, 0, 0),
(13423, 0, 'debug_mysql_db', 1, '0.5.0', 1345, 0, 'Debug Mysql DB', 'NEW Verson for TYPO3 6.x!!!! Extends t3lib_db (by xclassing it) to show Errors and Debug-Messages. Usefull for viewing and debugging of sql-queries generated using its methods. Shows error messages if they occur. Simply deinstall to remove all debug-output.', 2, 0, 4, 1370435550, 'a:2:{s:7:"depends";a:2:{s:3:"php";s:13:"5.2.5-5.4.999";s:5:"typo3";s:13:"6.0.0-6.0.999";}s:9:"conflicts";a:1:{s:4:"dbal";s:11:"0.0.0-0.0.0";}}', 'Stefan Geith', 'typo3dev2013@geithware.de', 'franzholz', '00d52e213e0494e7e145bdc60ff355f7', 'NEW Verson for TYPO3 6.x!!!! Extends TYPO3CMSCoreDatabaseDatabaseConnection (former t3lib_db) to show Errors and Debug-Messages. Usefull for viewing and debugging of sql-queries generated using its methods. Shows error messages if they occur. Si', '', 5000, 0, 0),
(13424, 0, 'debug_mysql_db', 1, '0.5.1', 1345, 0, 'Debug Mysql DB', 'Extends TYPO3CMSCoreDatabaseDatabaseConnection (former t3lib_db) to show Errors and Debug-Messages. Useful for viewing and debugging of sql-queries. Shows error messages if they occur. (For Typo3 V4.3-4.7 see versions 0.4.x)', 2, 0, 4, 1395735783, 'a:2:{s:7:"depends";a:2:{s:3:"php";s:13:"5.2.5-5.4.999";s:5:"typo3";s:13:"6.1.0-6.2.999";}s:9:"conflicts";a:1:{s:4:"dbal";s:11:"0.0.0-0.0.0";}}', 'Stefan Geith', 'typo3dev2013@geithware.de', 'franzholz', 'cda13acca454b8c10e4fcae6d3f0120b', 'New compatibility with Typo3 6.1-6.2; For Typo3 V4.3-4.7 see Versions 0.4.x', '', 5001, 0, 0),
(13425, 0, 'debug_mysql_db', 1, '0.5.2', 1345, 0, 'Debug Mysql DB', 'Extends TYPO3CMSCoreDatabaseDatabaseConnection (former t3lib_db) to show Errors and Debug-Messages. Useful for viewing and debugging of sql-queries. Shows error messages if they occur. (For Typo3 V4.3-4.7 see versions 0.4.x)', 2, 0, 4, 1395735852, 'a:2:{s:7:"depends";a:2:{s:3:"php";s:13:"5.2.5-5.4.999";s:5:"typo3";s:13:"6.1.0-6.2.999";}s:9:"conflicts";a:1:{s:4:"dbal";s:11:"0.0.0-0.0.0";}}', 'Stefan Geith', 'typo3dev2013@geithware.de', 'franzholz', '7c794542ffb96a4d8c4f85025ad43c89', 'New compatibility with Typo3 6.1-6.2; For Typo3 V4.3-4.7 see Versions 0.4.x', '', 5002, 0, 0),
