(13773, 0, 'wec_sermons', 1, '0.9.1', 949, 78, 'WEC Sermon Management System', 'Provides centralized management of online resources associated with a sermon', 1, 0, 3, 1179927696, 'a:1:{s:7:"depends";a:3:{s:3:"php";s:11:"4.3.0-0.0.0";s:7:"wec_api";s:11:"0.9.0-0.0.0";s:5:"typo3";s:11:"4.0.0-0.0.0";}}', 'Web-Empowered Church Team', 'sermon@webempoweredchurch.org', 'webempoweredchurch', '6144c38f5632fc12fe99a3f83631942d', 'Updated the rendering of the XML feed tag item_link, to clean [] and & characters from the output, replacing them with % encoded entities or html encoded entities. \n\nUpdated all RTE enabled fields with transformations to allow cron_rte_cleanenc to work', 'Foundation For Evangelism', 9001, 0, 0),
(13774, 0, 'wec_sermons', 1, '0.9.2', 949, 33, 'WEC Sermon Management System', 'Provides centralized management of online resources associated with a sermon', 1, 0, 3, 1184172261, 'a:1:{s:7:"depends";a:3:{s:3:"php";s:11:"4.3.0-0.0.0";s:7:"wec_api";s:11:"0.9.1-0.0.0";s:5:"typo3";s:11:"4.0.0-0.0.0";}}', 'Web-Empowered Church Team', 'sermon@webempoweredchurch.org', 'webempoweredchurch', 'b95100c2979a5bc81143a9bc57c762db', 'Bugfix - Changed hook parameters to pass-by-reference, after removing pass-by-reference at call time from tx_wecapi_list calls. This was causing the hooks to not pass information back such as channel_link fields. \n\nBugfix - Removed parseFunc stdWrap from', 'Foundation For Evangelism', 9002, 0, 0),
(13775, 0, 'wec_sermons', 1, '0.9.3', 949, 51, 'WEC Sermon Management System', 'Provides centralized management of online resources associated with a sermon', 1, 0, 3, 1185562328, 'a:1:{s:7:"depends";a:3:{s:3:"php";s:11:"4.3.0-0.0.0";s:7:"wec_api";s:11:"0.9.1-0.0.0";s:5:"typo3";s:11:"4.0.0-0.0.0";}}', 'Web-Empowered Church Team', 'sermon@webempoweredchurch.org', 'webempoweredchurch', '83be41ac38f02367b04ffcb9ef41390f', 'Numerous bugfixes, a few improvments and a few new features:\n\nBugfix - Corrected a mis-spelling in $startDate variable when calculating start date for plugin filter. Also added the check for n/n/n or n-n-n string formats\n\nBugfix - startDate and endDat', 'Foundation For Evangelism', 9003, 0, 0);
INSERT INTO `tx_extensionmanager_domain_model_extension` (`uid`, `pid`, `extension_key`, `repository`, `version`, `alldownloadcounter`, `downloadcounter`, `title`, `description`, `state`, `review_state`, `category`, `last_updated`, `serialized_dependencies`, `author_name`, `author_email`, `ownerusername`, `md5hash`, `update_comment`, `authorcompany`, `integer_version`, `current_version`, `lastreviewedversion`) VALUES
(13776, 0, 'wec_sermons', 1, '0.9.4', 949, 82, 'WEC Sermon Management System', 'Provides centralized management of online resources associated with a sermon', 1, 0, 3, 1190131068, 'a:1:{s:7:"depends";a:3:{s:3:"php";s:11:"4.3.0-0.0.0";s:7:"wec_api";s:11:"0.9.1-0.0.0";s:5:"typo3";s:11:"4.0.0-0.0.0";}}', 'Web-Empowered Church Team', 'sermon@webempoweredchurch.org', 'webempoweredchurch', '06c2993c1f926631e58968784a90b940', '- BUGFIX: Corrected bug causing only sermons from todays date to appear.\n\n- BUGFIX: Corrected numerous bugs around date() function processing associated with start and end dates\n\n- Bugfix: Corrected a bug where CURRENT display was not showing the sermon d', 'Foundation For Evangelism', 9004, 0, 0),
(13777, 0, 'wec_sermons', 1, '0.9.5', 949, 83, 'WEC Sermon Management System', 'Provides centralized management of online resources associated with a sermon', 1, 0, 3, 1199135443, 'a:1:{s:7:"depends";a:3:{s:3:"php";s:11:"4.3.0-0.0.0";s:7:"wec_api";s:11:"0.9.1-0.0.0";s:5:"typo3";s:11:"4.0.0-0.0.0";}}', 'Web-Empowered Church Team', 'sermon@webempoweredchurch.org', 'webempoweredchurch', '301791fcf8cec7ab1d7b6b344fc67999', '- fixed iTunes RSS bug where edits were changing the id\n\n- provided IRRE for sermon resources\n\n- provided a toggle for BibleGateway linkage (the constant disableBibleGateway)... makes eBible work more smoothly', 'Foundation For Evangelism', 9005, 0, 0),
(13778, 0, 'wec_sermons', 1, '0.10.0', 949, 84, 'WEC Sermon Management System', 'Provides centralized management of online resources associated with a sermon', 1, 0, 3, 1206878714, 'a:1:{s:7:"depends";a:4:{s:3:"php";s:11:"4.3.0-0.0.0";s:7:"wec_api";s:11:"0.9.1-0.0.0";s:5:"typo3";s:11:"4.1.6-0.0.0";s:15:"wec_flashplayer";s:11:"1.3.1-0.0.0";}}', 'Web-Empowered Church Team', 'sermon@webempoweredchurch.org', 'webempoweredchurch', '23204af1fd6fbea1c95e2b26a9e1a086', '- several inline record enhancements and bugfixes\n- new (normalized) database layout and corresponding update process\n- various minor enhancements/fixes', 'Foundation For Evangelism', 10000, 0, 0),
(13779, 0, 'wec_sermons', 1, '0.10.1', 949, 28, 'WEC Sermon Management System', 'Provides centralized management of online resources associated with a sermon', 1, 0, 3, 1212076911, 'a:1:{s:7:"depends";a:4:{s:3:"php";s:11:"4.3.0-0.0.0";s:7:"wec_api";s:11:"0.9.1-0.0.0";s:5:"typo3";s:11:"4.1.6-0.0.0";s:15:"wec_flashplayer";s:11:"1.3.1-0.0.0";}}', 'Web-Empowered Church Team', 'sermon@webempoweredchurch.org', 'webempoweredchurch', 'd24c183c8aabdde7858dc5ab768024a0', 'Improved HTML templates. Allow secondary metadata (sermons associated with a topic). Added support for YouTube resources. Other minor fixes and features.', 'Christian Technonlogy Ministries International Inc.', 10001, 0, 0),
(13780, 0, 'wec_sermons', 1, '0.10.2', 949, 244, 'WEC Sermon Management System', 'Provides centralized management of online resources associated with a sermon', 1, 0, 3, 1212177183, 'a:0:{}', 'Web-Empowered Church Team', 'sermon@webempoweredchurch.org', 'webempoweredchurch', '7950621f8502242369fcc09e4414d3b1', ' fixed a couple 0.10.1 bugs regarding resource_types (using the extension updater functionality now to produce new types)', 'Christian Technonlogy Ministries International Inc.', 10002, 1, 0),
(13781, 0, 'fl_bugtracker', 1, '0.0.2', 1181, 238, 'Bugtracker', 'Bugtracking with TYPO3 incl. Roadmap and Changelog for Programmversion', 3, 0, 3, 1172788182, 'a:0:{}', 'Tim Lochmueller', 'webmaster@fruit-lab.de', 'spyker', '9f4203f67aebc828225ac8f60d29a22d', 'First functionality. Raodmap & Changlog works Great. Reporting isnt work yet. Database Struktur works great. Interakt with FE Users.', 'fruit-lab.de', 2, 0, 0),
(13782, 0, 'fl_bugtracker', 1, '0.0.3', 1181, 264, 'Bugtracker', 'Bugtracking with TYPO3 incl. Roadmap and Changelog for Programmversion', 3, 0, 3, 1176305296, 'a:0:{}', 'Tim Lochmueller', 'webmaster@fruit-lab.de', 'spyker', '3dd030a38eb35ba0238641618c70c1d4', 'improve Database structure. USe IRRE for programmversions Update Flexforms. No additional outputs in the Fe-plugin.', 'fruit-lab.de', 3, 0, 0),
(13783, 0, 'fl_bugtracker', 1, '0.0.4', 1181, 40, 'Bugtracker', 'Bugtracking with TYPO3 incl. Roadmap, Changelog and Programms with Programmversion. Template based with same configuration possibilities. TYPO3 4.1 with IRRE is required.', 3, 0, 3, 1201963767, 'a:0:{}', 'Tim Lochmueller', 'webmaster@fruit-lab.de', 'spyker', '327d1d03c033133fee36e3d705c6d67c', 'First functions, simple add form and bug listing. database fixes. at the moment still experimental... i am looking for developer!', 'fruit-lab.de', 4, 0, 0),
(13784, 0, 'fl_bugtracker', 1, '0.0.5', 1181, 23, 'Bugtracker', 'Bugtracking with TYPO3 incl. Roadmap, Changelog and Programms with Programmversion. Template based with same configuration possibilities.', 3, 0, 3, 1202943022, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:5:"typo3";s:11:"4.0.0-0.0.0";s:3:"php";s:11:"4.1.0-0.0.0";}}', 'Tim Lochmueller', 'webmaster@fruit-lab.de', 'spyker', 'd62a11bc552b338a66d444e4d1e218e0', 'Fix Language Bugs in the FF; More Template Stuff like detail page, Hover effect, confirm page etc.; add a new Constant var; A few more functions than the extension goes alpha', 'fruit-lab.de', 5, 0, 0),
(13785, 0, 'fl_bugtracker', 1, '0.0.6', 1181, 30, 'Bugtracker', 'Bugtracking with TYPO3 incl. Roadmap, Changelog and Programms with Programmversion. Template based with same configuration possibilities.', 3, 0, 3, 1203029055, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:5:"typo3";s:11:"4.0.0-0.0.0";s:3:"php";s:11:"4.1.0-0.0.0";}}', 'Tim Lochmueller', 'webmaster@fruit-lab.de', 'spyker', '1dd6b9e0072c0820e37902ce5af3c1a9', 'Clean Up the class file, "add Bug" auto as New, Add new Bugtracker List Marker, Search Basics, Static Template Search Options, Fix a Bug', 'fruit-lab.de', 6, 0, 0),
