(13877, 0, 'menustop', 1, '0.0.1', 324, 296, 'Menu Stop', 'Allows to end main menu, sitemap and click path at each location. Each page can be the last visible or the first hidden one. To be configured in "page properties". It is an extended alternative to the page property checkbox "hide in menu".', 0, 0, 2, 1173444896, 'a:0:{}', 'Michael Sollmann', 'sollmann@dpi-berlin.net', 'michelfontaine', '4a40c8cbd3e9289995df9e800a403921', '', '', 1, 0, 0),
(13878, 0, 'menustop', 1, '0.0.2', 324, 28, 'Menu Stop', 'Allows to end main menu, sitemap and click path at each location. Each page can be the last visible or the first hidden one. To be configured in "page properties". It is an extended alternative to the page property checkbox "hide in menu".', 1, 0, 2, 1318945908, 'a:0:{}', 'Michael Sollmann', 'sollmann@dpi-berlin.net', 'michelfontaine', 'd36834f2f26a83dd9a01d4d77db53df5', 'changed locallang and switched state to "beta"', '', 2, 1, 0),
(13879, 0, 'bestfilecache', 1, '0.8.0', 1082, 147, 'Bennis Static File Cache', 'Another Static File Cache for TYPO3. It writes the cache for static pages to files so the Webserver does not need to activate mod_php.', 1, 0, 2, 1173399125, 'a:0:{}', 'Benjamin Mack', 'mack@xnos.org', 'benni', 'd1aeb1ddc292855729efab06067800f9', 'First public beta release. Includes a detailed manual.', 'xnos Internet Services', 8000, 0, 0),
(13880, 0, 'bestfilecache', 1, '0.8.1', 1082, 237, 'Bennis Static File Cache', 'Another Static File Cache for TYPO3. It writes the cache for static pages to files so the Webserver does not need to activate mod_php.', 1, 0, 2, 1173406545, 'a:2:{s:7:"depends";a:2:{s:5:"typo3";s:9:"4.1-0.0.0";s:7:"realurl";s:11:"1.1.0-0.0.0";}s:9:"conflicts";a:1:{s:19:"m1_google_analytics";s:11:"0.0.0-1.4.0";}}', 'Benjamin Mack', 'mack@xnos.org', 'benni', '96cd5441beaf20b2bd1128dae7daaa50', 'Added a discompatibility with extension "m1_google_analytics" for now. Updated manual', 'xnos Internet Services', 8001, 0, 0),
(13881, 0, 'bestfilecache', 1, '0.8.2', 1082, 167, 'Bennis Static File Cache', 'Another Static File Cache for TYPO3. It writes the cache for static pages to files so the Webserver does not need to activate mod_php.', 1, 0, 2, 1175518738, 'a:2:{s:7:"depends";a:2:{s:5:"typo3";s:9:"4.1-0.0.0";s:7:"realurl";s:11:"1.1.0-0.0.0";}s:9:"conflicts";a:1:{s:19:"m1_google_analytics";s:11:"0.0.0-1.4.0";}}', 'Benjamin Mack', 'mack@xnos.org', 'benni', '11507cb46e1c11f919be835dbdae4869', 'Fixed bug when unserializing configuration array', 'xnos Internet Services', 8002, 0, 0),
(13882, 0, 'bestfilecache', 1, '0.8.3', 1082, 193, 'Bennis Static File Cache', 'Another Static File Cache for TYPO3. It writes the cache for static pages to files so the Webserver does not need to activate mod_php.', 1, 0, 2, 1175607030, 'a:2:{s:7:"depends";a:1:{s:7:"realurl";s:11:"1.1.0-0.0.0";}s:9:"conflicts";a:1:{s:19:"m1_google_analytics";s:11:"0.0.0-1.4.0";}}', 'Benjamin Mack', 'bmack@xnos.org', 'benni', '38790640d0c7f233cbaeb40a470d5432', '  Removed TYPO3 4.1 dependency since the latest prototype javascript is included now\r\n  Handling configuration directives is different now and should work now', 'xnos Internet Services', 8003, 0, 0),
(13883, 0, 'bestfilecache', 1, '0.8.4', 1082, 338, 'Bennis Static File Cache', 'Another Static File Cache for TYPO3. It writes the cache for static pages to files so the Webserver does not need to activate mod_php.', 1, 0, 2, 1176725692, 'a:2:{s:7:"depends";a:1:{s:7:"realurl";s:11:"1.1.0-0.0.0";}s:9:"conflicts";a:1:{s:19:"m1_google_analytics";s:11:"0.0.0-1.4.0";}}', 'Benjamin Mack', 'bmack@xnos.org', 'benni', '465a6ec1fce8150f36c0d89286721836', 'Fixed bug that was not covered with the last release, caching from uploads-folder (default) works again', 'xnos Internet Services', 8004, 1, 0),
(13884, 0, 'nestedsets_pages', 1, '0.0.1', 133, 133, 'Nested Sets', 'Maintains a nested set on the pages table', 2, 0, 4, 1173628845, 'a:0:{}', 'R. van Twisk', 'ries@vantwisk.nl', 'ries', '260b5f19770e34180d224508f288d855', 'This extension add Celkos Neste Sets to the pagetree.\r\nWhenever a page is created/updated or deleted a new set is \r\napplied for the complete pagtree.', '', 1, 1, 0),
