(14039, 0, 'wec_staffdirectory', 1, '0.9.0', 3792, 229, 'WEC Staff Directory', 'Show listing of your staff in various ways. Can see single staff page which staff can edit. Supports many fields including photos, department, position, phone, email, cellphone, biography, etc.', 1, -1, 3, 1174511749, 'a:0:{}', 'Web-Empowered Church Team', 'staffdirectory(at)webempoweredchurch.org', 'webempoweredchurch', '116c7d1aff85f9c654037361d29ccea8', 'Initial version.', '', 9000, 0, 0),
(14040, 0, 'wec_staffdirectory', 1, '0.9.1', 3792, 215, 'WEC Staff Directory', 'Show listing of your staff in various ways. Can see single staff page which staff can edit. Supports many fields including photos, department, position, phone, email, cellphone, biography, etc.', 1, -1, 3, 1174924423, 'a:0:{}', 'Web-Empowered Church Team', 'staffdirectory(at)webempoweredchurch.org', 'webempoweredchurch', '483361f23e89aaa5cf1101706af71f74', 'Fixed bug with sort order. Added sort direction so could sort ascending/descending.', '', 9001, 0, 0),
(14041, 0, 'wec_staffdirectory', 1, '0.9.2', 3792, 188, 'WEC Staff Directory', 'Show listing of your staff in various ways. Can see single staff page which staff can edit. Supports many fields including photos, department, position, phone, email, cellphone, biography, etc.', 1, -1, 3, 1175545257, 'a:0:{}', 'Web-Empowered Church Team', 'staffdirectory(at)webempoweredchurch.org', 'webempoweredchurch', 'c17451217012efb743bb0c981aec284f', ' Fixed some fields so they save in edit form and display. Added title, address, country fields. Added secondary sorting fields for department. Updated staff_single template. Fixed issue with photos/pics always being generated.', '', 9002, 0, 0),
(14042, 0, 'wec_staffdirectory', 1, '0.9.3', 3792, 245, 'WEC Staff Directory', 'Show listings of your staff in various ways. Can see single staff page which staff can edit. Supports many fields including photos, department, position, phone, email, cellphone, biography, etc.', 1, -1, 3, 1175626283, 'a:0:{}', 'Web-Empowered Church Team', 'staffdirectory(at)webempoweredchurch.org', 'webempoweredchurch', '3f1ef70d6967845882cb063bc48b5183', 'Added alternate image path constant. Fixed "small photo" image display bug. Fixed admin editing capability.', '', 9003, 0, 0),
(14043, 0, 'wec_staffdirectory', 1, '0.9.4', 3792, 271, 'WEC Staff Directory', 'Show listings of your staff in various ways. Can see single staff page which staff can edit. Supports many fields including photos, department, position, phone, email, cellphone, biography, etc.', 1, -1, 3, 1178036823, 'a:0:{}', 'Web-Empowered Church Team', 'staffdirectory(at)webempoweredchurch.org', 'webempoweredchurch', '73176990342c489e4340414e312d1296', 'Fixed cancel on edit form. Fixed minor bugs with photo display handling. Added female blank image.', '', 9004, 0, 0),
(14044, 0, 'wec_staffdirectory', 1, '0.9.5', 3792, 147, 'WEC Staff Directory', 'Show listings of your staff in various ways. Can see single staff page which staff can edit. Supports many fields including photos, department, position, phone, email, cellphone, biography, etc.', 1, -1, 3, 1181325950, 'a:0:{}', 'Web-Empowered Church Team', 'staffdirectory(at)webempoweredchurch.org', 'webempoweredchurch', '5f0bb44b50110d4a45b9bfdf8c2d343d', 'Fixed bug when editing staff -- could lockup. Support if no ImageMagick/GraphicMagick installed, will set correct image height & width. Also\r\nwhen sort by first name the secondary field is last name.', '', 9005, 0, 0),
(14045, 0, 'wec_staffdirectory', 1, '1.0.0', 3792, 58, 'WEC Staff Directory', 'Show directory listing of your staff with single view. Supports configurable fields to display, photos/images, user-editing staff pages, and working with fe_users or separate records.', 1, -1, 3, 1187984226, 'a:0:{}', 'Web-Empowered Church Team', 'staffdirectory(at)webempoweredchurch.org', 'webempoweredchurch', 'f0935f48b02c03866cc894c73b8d1e79', 'ADDED: Support fe_users or Staff Info record - choose on install. Support multiple departments for staff. Also, thanks to Christian Boltz for: Search capability, admin by usergroup, and add & delete staff by admin. Updated template - pulled out all inline', '', 1000000, 0, 0),
(14046, 0, 'wec_staffdirectory', 1, '1.0.1', 3792, 87, 'WEC Staff Directory', 'Show directory listing of your staff with single view. Supports configurable fields to display, photos/images, user-editing staff pages, and working with fe_users or separate records.', 1, -1, 3, 1188591605, 'a:0:{}', 'Web-Empowered Church Team', 'staffdirectory(at)webempoweredchurch.org', 'webempoweredchurch', '2ef108843fb5c2a918df0149d8682331', 'ADDED: Add Staff in Frontend, added team and address2 fields. All fields for	editing/adding and more fields in list view. FIXED: wec_staffdirectory_in error, 	bad character in code, blank name in BE, delete staff working, and minor template updates.', '', 1000001, 0, 0),
(14047, 0, 'wec_staffdirectory', 1, '1.0.2', 3792, 108, 'WEC Staff Directory', 'Show directory listing of your staff with single view. Supports configurable fields to display, photos/images, user-editing staff pages, and working with fe_users or separate records.', 1, -1, 3, 1190234643, 'a:0:{}', 'Web-Empowered Church Team', 'staffdirectory(at)webempoweredchurch.org', 'webempoweredchurch', '3caa19b2ca2e2472d2e09324e86ffb7d', 'FIXED: saving all fields for add/edit staff whether using fe_user or staffdirectory_info. Add/Edit/Delete for staff non-admin. Bio/news fields editing works better. ADDED: Photos can now be cleared, TELEPHONE_OR_CELL marker, hook for extending markers', '', 1000002, 0, 0),
(14048, 0, 'wec_staffdirectory', 1, '1.0.3', 3792, 112, 'WEC Staff Directory', 'Show directory listing of your staff with single view. Supports configurable fields to display, photos/images, user-editing staff pages, and working with fe_users or separate records.', 1, -1, 3, 1193418874, 'a:0:{}', 'Web-Empowered Church Team', 'staffdirectory(at)webempoweredchurch.org', 'webempoweredchurch', '3a3fd21235d54f6af2c1abb94de85912', 'FIXED: basicfilefunc included (could cause error). ADDED: exclude set for fields (so can change permissions), added zone to fe_users, added Spanish \r\ntranslation (thanks Roman). Other minor fixes.', '', 1000003, 0, 0),
(14049, 0, 'wec_staffdirectory', 1, '1.1.0', 3792, 39, 'WEC Staff Directory', 'Shows directory listing of your staff with single view. Supports configurable fields to display, photos/images, user-editing staff pages, and working with fe_users or separate staff records.', 2, -1, 3, 1197471821, 'a:0:{}', 'Web-Empowered Church Team', 'staffdirectory(at)webempoweredchurch.org', 'webempoweredchurch', '53229d2d771b41be471b5d091d52f237', 'Made templates static  now must include (see doco). Added multi-language capability so can switch between languages for records on each page. Minor fixes for show-by-departments and label separators.', '', 1001000, 0, 0),
(14050, 0, 'wec_staffdirectory', 1, '1.1.1', 3792, 196, 'WEC Staff Directory', 'Shows directory listing of your staff with single view. Supports configurable fields to display, photos/images, user-editing staff pages, and working with fe_users or separate staff records.', 2, -1, 3, 1197570518, 'a:0:{}', 'Web-Empowered Church Team', 'staffdirectory(at)webempoweredchurch.org', 'webempoweredchurch', '2167ac39b3c6e66984746e3dfffbf302', 'manual is now fixed.', '', 1001001, 0, 0),
(14051, 0, 'wec_staffdirectory', 1, '1.2.0', 3792, 81, 'WEC Staff Directory', 'Show directory listing of your staff with single view. Supports configurable fields for display, photos/images, user-editing staff pages, and working with fe_users or separate staff records.', 2, -1, 3, 1206046661, 'a:0:{}', 'Web-Empowered Church Team', 'staffdirectory(at)webempoweredchurch.org', 'webempoweredchurch', '14bea2d9c16bb8bb70d033aa19ada9e3', 'Added WEC Map support. Added versioning support. Now supports full_name in staffdirectory_info (run UPDATE in ext mgr) for realURL.  Minor fixes.\n', '', 1002000, 0, 0),
(14052, 0, 'wec_staffdirectory', 1, '1.2.1', 3792, 197, 'WEC Staff Directory', 'Show directory listing of your staff with single view. Supports configurable fields for display, photos/images, user-editing staff pages, and working with fe_users or separate staff records.', 2, -1, 3, 1207159645, 'a:0:{}', 'Web-Empowered Church Team', 'staffdirectory(at)webempoweredchurch.org', 'webempoweredchurch', '805fc61b285d717437ded3eb1bb6e20a', 'Fixed error with sorting by name in frontend. Fixed staff listing title in backend. Changed mail link so uses TYPO3 core func. Fixed Update script in Ext Manager. New icons. Other minor fixes.', '', 1002001, 0, 0),
(14053, 0, 'wec_staffdirectory', 1, '1.2.3', 3792, 314, 'WEC Staff Directory', 'Show directory listing of your staff with single view. Supports configurable fields for display, photos/images, user-editing staff pages, and working with fe_users or separate staff records.', 2, -1, 3, 1214324624, 'a:1:{s:7:"depends";a:1:{s:3:"cms";s:0:"";}}', 'Web-Empowered Church Team', 'staffdirectory(at)webempoweredchurch.org', 'webempoweredchurch', '13874660c22666d016f6b78b26570d64', 'Fixed city,state, zip in list view. New backend labels if full_name not exists, 	verbose template now has small images, fixed edit link, fixed crash if paging on and no records, fixed charset (utf-8) display issues', '', 1002003, 0, 0),
(14054, 0, 'wec_staffdirectory', 1, '1.3.0', 3792, 60, 'WEC Staff Directory', 'Show directory listing of your staff with single view. Supports configurable fields for display, photos/images, user-editing staff pages, and working with fe_users or separate staff records.', 2, -1, 3, 1233707335, 'a:1:{s:7:"depends";a:1:{s:3:"cms";s:0:"";}}', 'Web-Empowered Church Team', 'staffdirectory(at)webempoweredchurch.org', 'webempoweredchurch', '750bc24a25eded5c011b9381224eb6a6', 'Support department as a record. Can show random staff (by day, week, month). Updated template and added markers. Can cache staff directory listing so can see in search results. More sort by fields added. Can use template reference. Added Greek and Dutch l', '', 1003000, 0, 0),
(14055, 0, 'wec_staffdirectory', 1, '1.4.0', 3792, 94, 'WEC Staff Directory', 'Show directory listing of your staff with single view. Supports configurable fields for display, photos/images, user-editing staff pages, and working with fe_users or separate staff records.', 2, -1, 3, 1246394111, 'a:1:{s:7:"depends";a:1:{s:3:"cms";s:0:"";}}', 'Web-Empowered Church Team', 'staffdirectory(at)webempoweredchurch.org', 'webempoweredchurch', '668f15d6a723dbfed0040a53394bed40', 'Added social media support (Twitter, Facebook, LinkedIn, mySpace, or whatever). Added dept dropdown (enable in template). Added cHash support. FIXED: multiple dept display, single view linking, alt tags for pictures, PHP 4 fixes, adding as a new plugin. A', '', 1004000, 0, 0),
(14056, 0, 'wec_staffdirectory', 1, '1.4.1', 3792, 184, 'WEC Staff Directory', 'Show directory listing of your staff with single view. Supports configurable fields for display, photos/images, user-editing staff pages, and working with fe_users or separate staff records.', 2, -1, 3, 1254948501, 'a:1:{s:7:"depends";a:1:{s:3:"cms";s:0:"";}}', 'Web-Empowered Church Team', 'staffdirectory(at)webempoweredchurch.org', 'webempoweredchurch', '32ea0099c77fdb607d643a2f659d9c04', 'Added an optional header for list-by-line view. Support two plugins on a page  list view and single view (set multiplePluginsPerPage constant). Can format first/last name by changing locallang labels (see FAQ). Department records now support languages. ', '', 1004001, 0, 0),
(14057, 0, 'wec_staffdirectory', 1, '1.4.2', 3792, 217, 'WEC Staff Directory', 'Show directory listing of your staff with single view. Supports configurable fields for display, photos/images, user-editing staff pages, and working with fe_users or separate staff records.', 2, -1, 3, 1260582403, 'a:1:{s:7:"depends";a:1:{s:3:"cms";s:0:"";}}', 'Web-Empowered Church Team', 'staffdirectory(at)webempoweredchurch.org', 'webempoweredchurch', '5574d37ed333f6d91494d8a9825196a2', 'Showing multiple departments is fixed; also can customize dept separator. Added 	gender and title option for list and single view in template and display fields. display_order can now handle  128 people. Fixed multilanguage issues.', '', 1004002, 0, 0),
(14058, 0, 'wec_staffdirectory', 1, '2.0.0', 3792, 10, 'WEC Staff Directory', 'Show directory listing of your staff with single view. Supports configurable fields for display, photos/images, user-editing staff pages, and working with fe_users or separate staff records.', 2, -1, 3, 1268663389, 'a:1:{s:7:"depends";a:1:{s:3:"cms";s:0:"";}}', 'Web-Empowered Church Team', 'devteam(at)webempoweredchurch.org', 'webempoweredchurch', '71def71ccd6f60cd3210ffe6a2923678', 'New templates and CSS - compatible with older templates until upgrade to new template. Can now select departments by dropdown (set option in Flexform). All functions are now PHP 5.x compatible.', '', 2000000, 0, 0),
(14059, 0, 'wec_staffdirectory', 1, '2.0.1', 3792, 12, 'WEC Staff Directory', 'Show directory listing of your staff with single view. Supports configurable fields for display, photos/images, user-editing staff pages, and working with fe_users or separate staff records.', 2, -1, 3, 1272048486, 'a:1:{s:7:"depends";a:1:{s:3:"cms";s:0:"";}}', 'Web-Empowered Church Team', 'devteam(at)webempoweredchurch.org', 'webempoweredchurch', '18c0bf90131e6f87bdc5fef3a585ea68', 'fixed photo image sizing, 2-column view (bad CSS), department names can have quotes, list of departments use separators, handle empty search results better', '', 2000001, 0, 0),
(14060, 0, 'wec_staffdirectory', 1, '2.1.0', 3792, 87, 'WEC Staff Directory', 'Show directory listing of your staff with single view. Supports configurable fields for display, photos/images, user-editing staff pages, and working with fe_users or separate staff records.', 2, -1, 3, 1280288765, 'a:1:{s:7:"depends";a:1:{s:3:"cms";s:0:"";}}', 'Web-Empowered Church Team', 'devteam(at)webempoweredchurch.org', 'webempoweredchurch', '5a8ba94861425fa864c26531b9e54110', 'Allow to use name for sorting and sortByDept. Updated CSS for 2-column view and other views -- check any custom templates. Many CSS fixes and updates. Fixed department edit in FE. ', '', 2001000, 0, 0),
(14061, 0, 'wec_staffdirectory', 1, '2.1.1', 3792, 194, 'WEC Staff Directory', 'Show directory listing of your staff with single view. Supports configurable fields for display, photos/images, user-editing staff pages, and working with fe_users or separate staff records.', 2, -1, 3, 1285962582, 'a:1:{s:7:"depends";a:1:{s:3:"cms";s:0:"";}}', 'Web-Empowered Church Team', 'devteam(at)webempoweredchurch.org', 'webempoweredchurch', '90cf340b55b68352422ef0974cb073c7', 'Fixed for map; fixed old verbose template; added french translation (thx to Laurent B); updated links in documentation.', '', 2001001, 0, 0),
(14062, 0, 'wec_staffdirectory', 1, '2.1.2', 3792, 447, 'WEC Staff Directory', 'Show directory listing of your staff with single view. Supports configurable fields for display, photos/images, user-editing staff pages, and working with fe_users or separate staff records.', 2, 0, 3, 1297103599, 'a:1:{s:7:"depends";a:1:{s:3:"cms";s:0:"";}}', 'Web-Empowered Church Team', 'devteam(at)webempoweredchurch.org', 'webempoweredchurch', '7ac9eac44a5131a8fb00a40ef5d98f3c', 'can add extra fields through TypoScript - dbShowFields and feUserFields. Fixed TCA error. Fixed FE photo upload security issue.', '', 2001002, 1, 0),
