(14088, 0, 'rgnewslinks', 1, '1.0.0', 1774, 17, ' next link in tt_news single-view', 'This extension makes it possible to browse to the previous & next record of tt_news. The order is taken from the single-view plugin, so please configure it properly (like in LATEST).', 2, 0, 3, 1175116082, 'a:0:{}', 'Georg Ringer', 'typo3 et ringerge dot org', 'just2b', 'b89358cd37385eae142a04615ef886ca', 'Prev & Next buttons of tt_news single view to get to the previous/next. Please read the manual and rate it if you like it!', '', 1000000, 0, 0);
