(14112, 0, 'abcsstidy', 1, '0.0.1', 838, 56, 'CSSTidy for TYPO3', 'This extension lets you chose whether your template should be optimized through csstidy. It therefore offers you a simple checkbox to activate it.', 3, 0, 0, 1175547602, 'a:0:{}', 'Andreas Balzer', 'typo3@andreas-balzer.de', 'abalzer', '15bf151b403a7ca95492fc89c64b57f9', 'I have found the error, but im not able to fix it.. Ill ask in mailinglist. Errors are in file class.tx_abcsstidy.php on lines 45 & 59.', '', 1, 0, 0),
(14113, 0, 'abcsstidy', 1, '0.0.2', 838, 19, 'CSSTidy for TYPO3', 'This extension lets you chose whether your template should be optimized through csstidy. It therefore offers you a simple checkbox to activate it.', 3, 0, 0, 1175811356, 'a:0:{}', 'Andreas Balzer', 'typo3@andreas-balzer.de', 'abalzer', '5f1f9c95003ced1253e6ccc642ed3d59', 'The bug..:\r\nIn theory the bug is fixed, but it didnt work out on Vista 64 Bit servers. Ill check it on Suse Linux now.\r\nFurther Changes:\r\nFirstly, abcsstidy doesnt use any checkboxes for longer. I have switched to Template Setup settings. See readme.tx', '', 2, 0, 0),
(14114, 0, 'abcsstidy', 1, '0.0.3', 838, 30, 'CSSTidy for TYPO3', 'This extension lets you chose whether your template should be optimized through csstidy. It therefore offers you a simple checkbox to activate it.', 3, 0, 0, 1175857614, 'a:0:{}', 'Andreas Balzer', 'typo3@andreas-balzer.de', 'abalzer', '1eb36d9112539e86bf0af21b1f3caf30', 'TER did not show my extension. See last changelog entry.', '', 3, 0, 0),
(14115, 0, 'abcsstidy', 1, '1.0.0', 838, 63, 'CSSTidy for TYPO3', 'This extension lets you chose whether your template should be optimized through csstidy. It therefore offers you several TSSetup options.', 2, 0, 2, 1176147062, 'a:0:{}', 'Andreas Balzer', 'typo3@andreas-balzer.de', 'abalzer', '84fbd710497e2155e1949be04f21820c', 'ext_localconf.php was missing. sry. Aem.. Theres a major security bug in this extension, so please be careful when using this extension. Ill update it soon.', '', 1000000, 0, 0),
