(14172, 0, 'meta_oscommerce', 1, '0.0.5', 1778, 57, 'Meta OSCommerce', 'OSCommerce for typo3', 0, 0, 3, 1180433274, 'a:2:{s:7:"depends";a:1:{s:3:"cms";s:0:"";}s:9:"conflicts";a:1:{s:4:"dbal";s:0:"";}}', 'Metaphore Multimedia (Christophe Monard, Olivier Saint-Clair)', 'typo3@metaphore.fr', 'cbalisky', '6e8cc80e06149f15530b950d14db1bd0', 'Major update. V0.0.4 seem to be an unworking version, please update.\nProduct attribute can now be more easily managed by clicking button on product listing page. It show a simplified page with only the product selected. Attribute list are now filtered and', 'Metaphore Multimedia', 5, 0, 0),
(14173, 0, 'meta_oscommerce', 1, '0.0.6', 1778, 176, 'Meta OSCommerce', 'OSCommerce for typo3', 0, 0, 3, 1180702857, 'a:2:{s:7:"depends";a:1:{s:3:"cms";s:0:"";}s:9:"conflicts";a:1:{s:4:"dbal";s:0:"";}}', 'Metaphore Multimedia (Christophe Monard, Olivier Saint-Clair)', 'typo3@metaphore.fr', 'cbalisky', '9cc7b27adaad8ab3998bb17f69364bf1', 'Some bug fixes.\nAdded categories listing box and quicksearch box in the plugin.', 'Metaphore Multimedia', 6, 0, 0),
(14174, 0, 'meta_oscommerce', 1, '0.0.7', 1778, 214, 'Meta OSCommerce', 'OSCommerce for typo3', 0, 0, 3, 1187625658, 'a:2:{s:7:"depends";a:1:{s:3:"cms";s:0:"";}s:9:"conflicts";a:1:{s:4:"dbal";s:0:"";}}', 'Metaphore Multimedia (Christophe Monard, Olivier Saint-Clair)', 'typo3@metaphore.fr', 'cbalisky', '54264a76b9401d1f4325e62a5854322b', 'Better implementation in backend, now take the force-charset of typo3 localconf.php if found (for utf-8 for example).\nBug fixe on the Atos module for French commerce', 'Metaphore Multimedia', 7, 0, 0),
(14175, 0, 'meta_oscommerce', 1, '0.0.8', 1778, 161, 'Meta OSCommerce', 'OSCommerce for typo3', 0, 0, 3, 1202134379, 'a:2:{s:7:"depends";a:1:{s:3:"cms";s:0:"";}s:9:"conflicts";a:1:{s:4:"dbal";s:0:"";}}', 'Metaphore Multimedia (Christophe Monard, Olivier Saint-Clair)', 'typo3@metaphore.fr', 'cbalisky', 'cf2232fd274ca56429aa3a32fd92d196', 'Install bug fix when changing value of db param.\nAdd France Mtropolitaine in France  zone.\nAdd France Mtropolitaine in UE  zone.\nCorrection of the search engine.\nAdd some pages in plugin configuration.', 'Metaphore Multimedia', 8, 0, 0),
