(14182, 0, 'pmkslimbox', 1, '1.0.0', 13052, 77, 'PMK SlimBox', 'PMK SlimBox - Use Lightbox effect instead of TYPO3s standard image click-enlarge. - No XCLASS as all is done using pure Typoscript. - Slimbox is a 7kb visual clone of the popular Lightbox JS v2.0 by Lokesh Dhakar, written using the ultra compact mootools', 1, -1, 2, 1175894721, 'a:0:{}', 'Peter Klein', 'peter@umloud.dk', 'pmk65', '11811a94e3d1721164fd5e723a5d9b20', 'First Public Version!', 'Umlound Untd', 1000000, 0, 0),
(14183, 0, 'pmkslimbox', 1, '1.1.0', 13052, 272, 'PMK SlimBox', 'PMK SlimBox - Use Lightbox effect instead of TYPO3s standard image click-enlarge. - No XCLASS as all is done using pure Typoscript. - Slimbox is a 7kb visual clone of the popular Lightbox JS v2.0 by Lokesh Dhakar, written using the ultra compact mootools', 1, -1, 2, 1176152557, 'a:0:{}', 'Peter Klein', 'peter@umloud.dk', 'pmk65', 'a1fe3c7dcd1171048919dd0a45d2646d', 'Switched javascript from Slimbox.js to Slimbox_ex.js which has some additional features, like opening HTML pages inside the Lightbox (using an IFRAME)  Added two new constants to define the maximum width/height of the image shown in the Lightbox.  Added', 'Umlound Untd', 1001000, 0, 0),
(14184, 0, 'pmkslimbox', 1, '2.0.0', 13052, 232, 'PMK SlimBox', 'PMK SlimBox - Use Lightbox effect instead of TYPO3s standard image click-enlarge. - No XCLASS as all is done using pure Typoscript. - Slimbox is a 7kb visual clone of the popular Lightbox JS v2.0 by Lokesh Dhakar, written using the ultra compact mootools', 2, -1, 2, 1180267187, 'a:0:{}', 'Peter Klein', 'peter@umloud.dk', 'pmk65', '254b00c9f6acac686ad158c209dcdfd0', 'Added: Mootools v1.1 framework library - Support for changing the Slimbox options from Typoscript. Now its possible to choose which transition to use, and the duration, Change the opacity level of the background, Control the scrolling parameter of the If', 'Umlound Untd', 2000000, 0, 0);
INSERT INTO `tx_extensionmanager_domain_model_extension` (`uid`, `pid`, `extension_key`, `repository`, `version`, `alldownloadcounter`, `downloadcounter`, `title`, `description`, `state`, `review_state`, `category`, `last_updated`, `serialized_dependencies`, `author_name`, `author_email`, `ownerusername`, `md5hash`, `update_comment`, `authorcompany`, `integer_version`, `current_version`, `lastreviewedversion`) VALUES
(14185, 0, 'pmkslimbox', 1, '2.1.0', 13052, 2152, 'PMK SlimBox', 'PMK SlimBox - Use Lightbox effect instead of TYPO3s standard image click-enlarge. - No XCLASS as all is done using pure Typoscript. - Slimbox is a 7kb visual clone of the popular Lightbox JS v2.0 by Lokesh Dhakar, written using the ultra compact mootools', 2, -1, 2, 1182797905, 'a:0:{}', 'Peter Klein', 'peter@umloud.dk', 'pmk65', '60b2e85f194e5ac5e439621e65e084eb', 'Added security fix by Stefan Aebischer. - Added showNumbers option to turn on/off the Page x of x text. - Improved the Save/Print functionality by using the baseURL.', 'Umloud Untd', 2001000, 0, 0),
(14186, 0, 'pmkslimbox', 1, '2.2.0', 13052, 1978, 'PMK SlimBox', 'PMK SlimBox - Use Lightbox effect instead of TYPO3s standard image click-enlarge. - No XCLASS as all is done using pure Typoscript. - Slimbox is a 7kb visual clone of the popular Lightbox JS v2.0 by Lokesh Dhakar, written using the ultra compact mootools', 2, -1, 2, 1189945674, 'a:0:{}', 'Peter Klein', 'peter@umloud.dk', 'pmk65', '0b5c64650af79c08cbe702a9a024e649', 'Added an new constant called slimboxJS which holds the path/name of the slimbox script\r\nAdded support for using the t3mootools extension.', 'Umloud Untd', 2002000, 0, 0),
(14187, 0, 'pmkslimbox', 1, '2.3.0', 13052, 590, 'PMK SlimBox', 'PMK SlimBox - Use Lightbox effect instead of TYPO3s standard image click-enlarge. - No XCLASS as all is done using pure Typoscript. - Slimbox is a 7kb visual clone of the popular Lightbox JS v2.0 by Lokesh Dhakar, written using the ultra compact mootools', 2, -1, 2, 1212912819, 'a:1:{s:9:"conflicts";a:4:{s:17:"kj_imagelightbox2";s:11:"0.0.0-0.0.0";s:15:"perfectlightbox";s:11:"0.0.0-0.0.0";s:15:"wsclicklightbox";s:11:"0.0.0-0.0.0";s:11:"ju_multibox";s:11:"0.0.0-0.0.0";}}', 'Peter Klein', 'peter@umloud.dk', 'pmk65', 'de2c0a87edaba76ba083134d9ba6b2db', 'Added a new script called slimboxmagnify. This script adds a small magnify icon to the SlimBox-enabled images (the thumbnails). So when you hover over a SlimBox-enabled image, the small magnify icon will appear in the l', 'Umloud Untd', 2003000, 0, 0),
(14188, 0, 'pmkslimbox', 1, '2.3.1', 13052, 390, 'PMK SlimBox', 'PMK SlimBox - Use Lightbox effect instead of TYPO3s standard image click-enlarge. - No XCLASS as all is done using pure Typoscript. - Slimbox is a 7kb visual clone of the popular Lightbox JS v2.0 by Lokesh Dhakar, written using the ultra compact mootools', 2, -1, 2, 1216382890, 'a:1:{s:9:"conflicts";a:4:{s:17:"kj_imagelightbox2";s:11:"0.0.0-0.0.0";s:15:"perfectlightbox";s:11:"0.0.0-0.0.0";s:15:"wsclicklightbox";s:11:"0.0.0-0.0.0";s:11:"ju_multibox";s:11:"0.0.0-0.0.0";}}', 'Peter Klein', 'peter@umloud.dk', 'pmk65', '2e507ac3c441db5d62e9ddd4a1e075ac', 'Fixed some positioning problems in the SlimboxMagnify script.', 'Umloud Untd', 2003001, 0, 0),
(14189, 0, 'pmkslimbox', 1, '2.3.2', 13052, 1588, 'PMK SlimBox', 'PMK SlimBox - Use Lightbox effect instead of TYPO3s standard image click-enlarge. - No XCLASS as all is done using pure Typoscript. - Slimbox is a 7kb visual clone of the popular Lightbox JS v2.0 by Lokesh Dhakar, written using the ultra compact mootools', 2, -1, 2, 1218383128, 'a:1:{s:9:"conflicts";a:4:{s:17:"kj_imagelightbox2";s:11:"0.0.0-0.0.0";s:15:"perfectlightbox";s:11:"0.0.0-0.0.0";s:15:"wsclicklightbox";s:11:"0.0.0-0.0.0";s:11:"ju_multibox";s:11:"0.0.0-0.0.0";}}', 'Peter Klein', 'peter@umloud.dk', 'pmk65', '08f1ce39cb207b98488dfc7eba3949d6', 'Inline Javascript now validates correctly under DOCTYPE  XHTML strict. - SlimboxMagnify.js has been rewritten so it also validates correctly.', 'Umloud Untd', 2003002, 0, 0),
(14190, 0, 'pmkslimbox', 1, '3.0.0', 13052, 388, 'PMK SlimBox', 'PMK SlimBox - Use Lightbox effect instead of TYPO3s standard image click-enlarge. - No XCLASS as all is done using pure Typoscript. - Slimbox is a 4kb visual clone of the popular Lightbox JS by Lokesh Dhakar, written using the ultra compact mootools v1.2', 2, -1, 2, 1225832692, 'a:1:{s:9:"conflicts";a:4:{s:17:"kj_imagelightbox2";s:11:"0.0.0-0.0.0";s:15:"perfectlightbox";s:11:"0.0.0-0.0.0";s:15:"wsclicklightbox";s:11:"0.0.0-0.0.0";s:11:"ju_multibox";s:11:"0.0.0-0.0.0";}}', 'Peter Klein', 'peter@umloud.dk', 'pmk65', 'fb16fb5d9713e34412a764cbb60d9e90', 'Now uses Mootools v1.2.1. (Support for t3mootools will come once I get some spare time to update the t3mootools ext to Mootools v1.2.1)\r\n- 3 different Slimbox scripts to choose from.', 'Umloud Untd', 3000000, 0, 0),
(14191, 0, 'pmkslimbox', 1, '3.0.1', 13052, 524, 'PMK SlimBox', 'PMK SlimBox - Use Lightbox effect instead of TYPO3s standard image click-enlarge. - No XCLASS as all is done using pure Typoscript. - Slimbox is a 4kb visual clone of the popular Lightbox JS by Lokesh Dhakar, written using the ultra compact mootools v1.2', 2, -1, 2, 1228165996, 'a:1:{s:9:"conflicts";a:4:{s:17:"kj_imagelightbox2";s:11:"0.0.0-0.0.0";s:15:"perfectlightbox";s:11:"0.0.0-0.0.0";s:15:"wsclicklightbox";s:11:"0.0.0-0.0.0";s:11:"ju_multibox";s:11:"0.0.0-0.0.0";}}', 'Peter Klein', 'peter@umloud.dk', 'pmk65', '193b3affa557f504ac6ae99247d7491b', 'Fixed problem with empty static templates. - Added 2 ext CSS setups for Mediabox Advanced.', 'Umloud Untd', 3000001, 0, 0),
(14192, 0, 'pmkslimbox', 1, '3.1.0', 13052, 4861, 'PMK SlimBox', 'PMK SlimBox - Use Lightbox effect instead of TYPO3s standard image click-enlarge. - No XCLASS as all is done using pure Typoscript. - Slimbox is a 4kb visual clone of the popular Lightbox JS by Lokesh Dhakar, written using the ultra compact mootools v1.2', 2, -1, 2, 1240508341, 'a:1:{s:9:"conflicts";a:4:{s:17:"kj_imagelightbox2";s:11:"0.0.0-0.0.0";s:15:"perfectlightbox";s:11:"0.0.0-0.0.0";s:15:"wsclicklightbox";s:11:"0.0.0-0.0.0";s:11:"ju_multibox";s:11:"0.0.0-0.0.0";}}', 'Peter Klein', 'peter@umloud.dk', 'pmk65', 'ab3153c8b59a0307eaff2195744b7358', 'Re-enabled t3mootools support - Updated Slimbox script to v1.69 - Updated MediaBoxAdv script to v0.99f -	Fixed problems with the save/print functionality.', 'Umloud Untd', 3001000, 1, 0),
