(14248, 0, 'wm_contentteaser', 1, '1.1.0', 925, 196, 'Content Teaser', 'This extension adds a flag, a pic, etc... to tt_content so that one is able to identify certain records. These records are selected by the frontend plugin and rendered anywhere on your site with the well-known template / marker / subpart mechanism.', 2, 0, 3, 1201423720, 'a:0:{}', 'Manfred Widmann', 'mpunktw@gmx.net', 'mpunktw', '92d0ae51e4f9526634eb42396b198554', ' The teaser now can contain a pic and a RTEable textfield.\n pi1: $this-cObj-enableFields( "table" ) used when accessing tables\n New improved structure of extension\n Lightbox display optionally anabled\n Lot of small changes in TCA i', '', 1001000, 0, 0),
(14249, 0, 'wm_contentteaser', 1, '1.2.0', 925, 14, 'Content Teaser', 'This extension adds a flag, a pic, etc... to tt_content so that one is able to identify certain records. These records are selected by the frontend plugin and rendered anywhere on your site with the well-known template / marker / subpart mechanism.', 2, 0, 3, 1235557551, 'a:0:{}', 'Manfred Widmann', 'mpunktw@gmx.net', 'mpunktw', '59fbdb1e220efa68fd8524ca3a4eedfe', ' All strings are localized now.\r\n Value assignment to template markers is done with function htmlspecialchars().\r\n sql_free_result() is consequently used now.\r\n String quotation is done with single quotation mark now.\r\n In SQL queries intval() a', '', 1002000, 0, 0),
(14250, 0, 'wm_contentteaser', 1, '1.2.1', 925, 75, 'Content Teaser', 'This extension adds a flag, a pic, etc... to tt_content so that one is able to identify certain records. These records are selected by the frontend plugin and rendered anywhere on your site with the well-known template / marker / subpart mechanism.', 2, 0, 3, 1245498142, 'a:0:{}', 'Manfred Widmann', 'mpunktw@gmx.net', 'mpunktw', '5467015262f5f618d5a62f72bdbe6abd', 'Error in TCA definition solved!', '', 1002001, 0, 0),
