(14259, 0, 'wc_scriptaculous', 1, '1.7.1', 643, 643, 'Script.aculo.us and Prototype Javascript Libraries', 'Dead simple inclusion of the javascript libraries in the FE. Upon install, includes prototype.js and effects.js on your pages', 2, 0, 2, 1179748202, 'a:0:{}', 'Sudara', 'sudara@modernthings.net', 'sudara', '820fee977f008025ee881591ea07e99a', 'Updated to Prototype 1.5.1 final and script.aculo.us 1.7.1 beta 2', '', 1007001, 1, 0),
(14260, 0, 'wc_lowpro', 1, '0.4.0', 378, 378, 'Low Pro for Typo!', 'Low Pro is an extension for the Prototype javascript library (among other things) allowing you to add behaviors to css classes. See http://www.danwebb.net/', 1, 0, 2, 1179748328, 'a:0:{}', 'Sudara', 'sudara@modernthings.net', 'sudara', 'a844a6222061bfa3396f6f0e570629f5', 'Updated to latest version in LowPro trunk.', '', 4000, 1, 0),
(14261, 0, 'wc_png_me_once', 1, '6.0.0', 653, 76, 'PNG me once!', 'Dead simple (well, as simple as IE gets, which is difficult, actually) png fixes for IE PNG transparency via Low Pro unobtrusive javascript.', 1, 0, 2, 1177341278, 'a:0:{}', 'Sudara', 'williams@web-crossing.com', 'sudara', '54ea180f542e2df4f0a34853fe7a61c9', 'First public version. Have at it and report your experiences to: http://wiki.typo3.org/index.php?titleEXT/wc_png_me_once/manual', '', 6000000, 0, 0),
(14262, 0, 'wc_png_me_once', 1, '6.0.1', 653, 7, 'PNG me once!', 'Dead simple (well, as simple as IE gets, which is difficult, actually) png fixes for IE PNG transparency via Low Pro unobtrusive javascript.', 1, 0, 2, 1177399546, 'a:0:{}', 'Sudara', 'williams@web-crossing.com', 'sudara', 'ebde954ddc00bfadb6325c754eb0107f', 'Have at it. Documentation and Questions are here: http://wiki.typo3.org/index.php/EXT/wc_png_me_once/manual', '', 6000001, 0, 0),
(14263, 0, 'wc_png_me_once', 1, '6.0.2', 653, 10, 'PNG me once!', 'Dead simple fixes for IE PNG transparency via Low Pro unobtrusive javascripting. Include the static template, give your img tags (foreground) and divs (background) special names in your template, obey the annoying AlphaImageLoader quirks and bada bing.', 1, 0, 2, 1177400133, 'a:0:{}', 'Sudara', 'williams@web-crossing.com', 'sudara', '2d434e85b6280d4356b6cda2cdaac469', 'Whups, forgot the dependencies! The Official Manual and Your Confused Questions go here: http://wiki.typo3.org/index.php/EXT/wc_png_me_once/manual', '', 6000002, 0, 0),
(14264, 0, 'wc_png_me_once', 1, '6.0.3', 653, 176, 'PNG me once!', 'Dead simple fixes for IE PNG transparency via Low Pro unobtrusive javascripting. Include the static template, give your img tags (foreground) and divs (background) special names in your template, obey the annoying AlphaImageLoader quirks and bada bing.', 1, 0, 2, 1177405339, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:4:"4.1+";s:16:"wc_scriptaculous";s:6:"1.7.1+";s:9:"wc_lowpro";s:6:"0.4.0+";}}', 'Sudara', 'williams@web-crossing.com', 'sudara', 'fecd87fa403a49aa58492ce7c617fc0f', 'Bum Bum Bum. Hard to get these dependencies right, eh? Questions and the lovely manual live here: http://wiki.typo3.org/index.php/EXT/wc_png_me_once/manual', '', 6000003, 0, 0),
(14265, 0, 'wc_png_me_once', 1, '6.0.4', 653, 384, 'PNG me once!', 'Dead simple fixes for IE PNG transparency via Low Pro unobtrusive javascripting. For Typo3 4.1 and higher. Include the static template, give your img tags (foreground) and divs (background) special names in your template, obey the annoying AlphaImageLoade', 1, 0, 2, 1177412665, 'a:1:{s:7:"depends";a:2:{s:16:"wc_scriptaculous";s:6:"1.7.1+";s:9:"wc_lowpro";s:6:"0.4.0+";}}', 'Sudara', 'williams@web-crossing.com', 'sudara', 'dbf064275d92b18f059f5fe35693a071', 'Enjoy, and visit the manual at http://wiki.typo3.org/index.php/EXT/wc_png_me_once/manual', '', 6000004, 1, 0),
