(14386, 0, 'donations', 1, '0.5.0', 432, 76, 'Donations', 'Collect donations for your project(s) using online payment. Requires PHP 5.', 0, 0, 3, 1189587778, 'a:1:{s:7:"depends";a:3:{s:10:"paymentlib";s:5:"0.3.0";s:8:"moneylib";s:0:"";s:18:"static_info_tables";s:0:"";}}', 'Tonni Aagesen, Francois Suter (Cobweb)', 'support@cobweb.ch', 'francois', 'c3813167b908b5dd48ea6d4ee798ea0e', 'First fully functional version. Please refer to the ChangeLog for a list of all changes.', '', 5000, 0, 0),
(14387, 0, 'donations', 1, '0.6.0', 432, 116, 'Donations', 'Collect donations for your project(s) using online payment. Requires PHP 5.', 0, 0, 3, 1214251155, 'a:1:{s:7:"depends";a:3:{s:10:"paymentlib";s:5:"0.3.0";s:8:"moneylib";s:0:"";s:18:"static_info_tables";s:0:"";}}', 'Tonni Aagesen, Francois Suter (Cobweb)', 'typo3@cobweb.ch', 'francois', 'f358c738e3cb9698975f9873ab7cd96f', 'Bug fixes and security fixes, better 4.2 compatibility. See changelog for full details.', '', 6000, 0, 0),
(14388, 0, 'donations', 1, '0.6.1', 432, 0, 'Donations', 'Collect donations for your project(s) using online payment.', 5, 0, 3, 1423998229, 'a:1:{s:7:"depends";a:4:{s:5:"typo3";s:12:"4.2.0-4.5.99";s:10:"paymentlib";s:5:"0.3.0";s:8:"moneylib";s:0:"";s:18:"static_info_tables";s:0:"";}}', 'Tonni Aagesen, Francois Suter (Cobweb)', 'typo3@cobweb.ch', 'francois', '63804e0a13ea27aa97068b357265948c', 'Marked as obsolete. Development has been discontinued for years already.', '', 6001, 1, 0),
