(14391, 0, 'wec_knowledgebase', 1, '0.9.0', 1072, 301, 'WEC Knowledgebase', 'Knowledgebase functionality including articles with comments and tutorial resources, category menu, and listing by most popular and latest entries, etc. Uses tt_news as base.', 1, 0, 3, 1178054742, 'a:0:{}', 'Web-Empowered Church Team', 'knowledgebase(at)webempoweredchurch.org', 'webempoweredchurch', 'c50460e73d0ee58570e76e934faa28ea', 'Initial version', 'Web-Empowered Church', 9000, 0, 0),
(14392, 0, 'wec_knowledgebase', 1, '0.9.1', 1072, 324, 'WEC Knowledgebase', 'Knowledgebase functionality including articles with comments and tutorial resources, category menu, and listing by most popular and latest entries, etc. Uses tt_news as base.', 1, 0, 3, 1182181844, 'a:0:{}', 'Web-Empowered Church Team', 'knowledgebase(at)webempoweredchurch.org', 'webempoweredchurch', '8d43ef5b159e628fd20782b412e82589', 'Fixed bug with showing tutorial with tutorialplayer code. Fixed bug with showing comments link in sidebar when comments turned off.', 'Web-Empowered Church', 9001, 0, 0),
(14393, 0, 'wec_knowledgebase', 1, '0.9.3', 1072, 184, 'WEC Knowledgebase', 'Knowledgebase functionality including articles with comments and tutorial resources, category menu, and listing by most popular and latest entries, etc. Uses tt_news as base.', 1, 0, 3, 1209657047, 'a:1:{s:7:"depends";a:1:{s:7:"tt_news";s:0:"";}}', 'Web-Empowered Church Team', 'knowledgebase(at)webempoweredchurch.org', 'webempoweredchurch', 'a6c11754348d6a8895848cd245abf17f', 'Now uses static template (MUST add to ext template for output). Fixed bug with loading locallang file, fixed bug with sortby in TCA setting. Changed to Show All \ninstead of Top in category listing. Fixed hidden/deleted cat bug. Other mino', 'Christian Technology Ministries International Inc.', 9003, 0, 0),
(14394, 0, 'wec_knowledgebase', 1, '0.9.4', 1072, 263, 'WEC Knowledgebase', 'Knowledgebase functionality including articles with comments and tutorial resources, category menu, and listing by most popular and latest entries, etc. Uses tt_news as base.', 1, 0, 3, 1225317068, 'a:1:{s:7:"depends";a:1:{s:7:"tt_news";s:0:"";}}', 'Web-Empowered Church Team', 'knowledgebase(at)webempoweredchurch.org', 'webempoweredchurch', 'a861eb5c074f09ec7ee01240cecffdf0', 'Fixed comments, fixed dropdown menu links, added caching of plugin (if no comments)  can search content site-wide. Improved XHTML compliance and added language support for categories (thx to Robert Heel).', 'Christian Technology Ministries International Inc.', 9004, 1, 0),
(14395, 0, 'csvdisplay', 1, '0.0.1', 1406, 45, 'CSV Display', 'Displays CSV Data In a HTML Table, options to generate Headers from first data row and display data in multiple pages', 0, 0, 2, 1178143520, 'a:0:{}', 'Christian Wolff', 'chris@connye.com', '1stmachine', '7144c8fe9f89cdf244cd3e031e1026d3', 'very first release, but shoud work if not mail me ;-)\nfeatures:\n - Displayes CSV Data in html Table\n - css styling header, and even/odd rows or even by individual row / cell number\n - posible to use first line of csv as headers\n - custom headers can enter', '', 1, 0, 0),
