(14406, 0, 'csvdisplay', 1, '0.1.2', 1406, 56, 'CSV Display', 'Displays CSV Data In a HTML Table, options to generate Headers from first data row and display data in multiple pages', 1, 0, 2, 1184709573, 'a:0:{}', 'Christian Wolff', 'chris@connye.com', '1stmachine', 'a42b7db38a66f27c77ba960f4d732aa0', 'bugfix: Extension Clears now Cache on Installation to prevent error message: "ERROR: Content Element type "csvdisplay_pi1" has no rendering definition!"', '', 1002, 0, 0),
