(14408, 0, 'csvdisplay', 1, '0.2.0', 1406, 175, 'CSV Display', 'Displays CSV Data In a HTML Table, options to generate Headers from first data row and display data in multiple pages', 1, 0, 2, 1197202628, 'a:0:{}', 'Christian Wolff', 'chris@connye.com', '1stmachine', '366fd786abfd63a6ea899ed0ab472b5b', 'Addet Automatic Detection of CSV Data Seperator. now parsing CSV data of my own not using the php function fgetcsv because this also removes quotes inside the data (if not escaped).', '', 2000, 0, 0),
