(14513, 0, 'cobweb_protector', 1, '1.0.0', 373, 253, 'Cobweb Protector', 'Protect access to a page by making sure that the user has submitted a given form beforehand (e.g. reading and agreeing to a disclaimer).', 2, 0, 3, 1179132037, 'a:0:{}', 'Francois Suter (Cobweb)', 'support@cobweb.ch', 'francois', '30d95313fd7c8a93c34152ae9d36aad1', 'Initial release', '', 1000000, 0, 0),
(14514, 0, 'cobweb_protector', 1, '1.1.0', 373, 120, 'Cobweb Protector', 'Restrict access to a page by checking some value(s), for example coming form a form submission.', 2, 0, 3, 1190573215, 'a:0:{}', 'Francois Suter (Cobweb)', 'support@cobweb.ch', 'francois', '48a4535bb26555318dc0ef8c87a3176c', 'Added choice of source for value and test; made value into stdWrap.', '', 1001000, 0, 0),
(14515, 0, 'cobweb_protector', 1, '1.1.1', 373, 0, 'Cobweb Protector', 'Restrict access to a page by checking some value(s), for example coming form a form submission.', 5, 0, 3, 1424010918, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"4.2.0-4.5.99";}}', 'Francois Suter (Cobweb)', 'support@cobweb.ch', 'francois', 'e4adfbf1cfeab15efe74844f3304e973', 'Marked as obsolete. Not developed anymore since a long while already.', '', 1001001, 1, 0),
(14516, 0, 'contagged', 1, '0.0.1', 2719, 243, 'Content parser and tagger', 'This extension parses the text of a content element to tag, replace and link specific terms. It is useful to auto-generate a glossary - but not only. Because it is configurable through TS.', 0, 0, 2, 1179139611, 'a:0:{}', 'Jochen Rau', 'j.rau@web.de', 'jocrau', '4f9695dd37bc8902dbdffe6d36839adb', 'initial upload', '', 1, 0, 0),
(14517, 0, 'contagged', 1, '0.0.2', 2719, 139, 'Content parser and tagger', 'The extension parses your content to tag, replace and link specific terms. It is useful to auto-generate a glossary - but not only. New types can be added and configurated via TS.', 0, 0, 2, 1179613698, 'a:0:{}', 'Jochen Rau', 'j.rau@web.de', 'jocrau', 'bb5e2b54f1170e226b4e49946a137115', 'Some minor bugfixes. New features: exclude tags; auto-generate keywords of the page (see change log).', '', 2, 0, 0),
(14518, 0, 'contagged', 1, '0.0.3', 2719, 47, 'Content parser and tagger', 'The extension parses your content to tag, replace and link specific terms. It is useful to auto-generate a glossary - but not only. New types can be added and configurated via TS. For version history see ChangeLog. For more information see WiKi (http:/', 0, 0, 2, 1188337988, 'a:0:{}', 'Jochen Rau', 'j.rau@web.de', 'jocrau', '22927cfdb4bc21ac7b45b4ddeb1ebad2', 'New FE plugin. Several improvments (see change log).', '', 3, 0, 0),
(14519, 0, 'contagged', 1, '0.0.4', 2719, 71, 'Content parser and tagger', 'The extension parses your content to tag, replace and link specific terms. It is useful to auto-generate a glossary - but not only. For version history see ChangeLog. For more information and a roadmap see WiKi (http://wiki.typo3.org/index.php/Contagge', 0, 0, 2, 1188401300, 'a:0:{}', 'Jochen Rau', 'j.rau@web.de', 'jocrau', '6872bc507eddf185c62e931693faf9fc', 'Better support for multibyte character sets (UTF8).', '', 4, 0, 0),
(14520, 0, 'contagged', 1, '0.0.5', 2719, 57, 'Content parser and tagger', 'The extension parses your content to tag, replace and link specific terms. It is useful to auto-generate a glossary - but not only. For more information see ChangeLog and WiKi (http://wiki.typo3.org/index.php/Contagged).', 0, 0, 2, 1189164872, 'a:0:{}', 'Jochen Rau', 'j.rau@web.de', 'jocrau', '6991ac35c8877c11e62789a4afbd614f', 'pure css tool-tips are now valid; added preStdWrap and postStdWrap; support for joined words (with a dash); fixed bug in SQL-Statement', '', 5, 0, 0);
INSERT INTO `tx_extensionmanager_domain_model_extension` (`uid`, `pid`, `extension_key`, `repository`, `version`, `alldownloadcounter`, `downloadcounter`, `title`, `description`, `state`, `review_state`, `category`, `last_updated`, `serialized_dependencies`, `author_name`, `author_email`, `ownerusername`, `md5hash`, `update_comment`, `authorcompany`, `integer_version`, `current_version`, `lastreviewedversion`) VALUES
(14521, 0, 'contagged', 1, '0.0.6', 2719, 52, 'Content parser and tagger', 'The extension parses your content to tag, replace and link specific terms. It is useful to auto-generate a glossary - but not only. For more information see ChangeLog and WiKi (http://wiki.typo3.org/index.php/Contagged).', 0, 0, 2, 1189759437, 'a:0:{}', 'Jochen Rau', 'j.rau@web.de', 'jocrau', '83a3bf16f8c2a30a35f295743ccd8c0a', 'see ChangeLog; stdWrap for the term to be searched (eg. "Steve Jobs" or custom tags); improved UTF-8 handling; small bugfixes', '', 6, 0, 0),
(14522, 0, 'contagged', 1, '0.0.7', 2719, 40, 'Content parser and tagger', 'The extension parses your content to tag, replace and link specific terms. It is useful to auto-generate a glossary - but not only. For more information see ChangeLog and WiKi (http://wiki.typo3.org/index.php/Contagged).', 0, 0, 2, 1190067474, 'a:0:{}', 'Jochen Rau', 'j.rau@web.de', 'jocrau', '7682c1f33266dedb2f72dfb8666fbaaf', 'see ChangeLog: improved auto generated index of the FE-Plugin (UTF-8, autoAddIndexChars); small bugfix (closing bracket in TS Setup)', '', 7, 0, 0),
(14523, 0, 'contagged', 1, '0.0.8', 2719, 43, 'Content parser and tagger', 'The extension parses your content to tag, replace and link specific terms. It is useful to auto-generate a glossary - but not only. For more information see ChangeLog and WiKi (http://wiki.typo3.org/index.php/Contagged).', 0, 0, 2, 1190119863, 'a:0:{}', 'Jochen Rau', 'j.rau@web.de', 'jocrau', 'a1416a00e2f0707951d4a653f588cf1d', 'Added experimental support for foreign tables like tt_address (configurable through TS Setup: table name, field mapping); see ChangeLog to activate', '', 8, 0, 0),
(14524, 0, 'contagged', 1, '0.0.9', 2719, 42, 'Content parser and tagger', 'The extension parses your content to tag, replace and link specific terms. It is useful to auto-generate a glossary - but not only. For more information see ChangeLog and WiKi (http://wiki.typo3.org/index.php/Contagged).', 0, 0, 2, 1190371050, 'a:0:{}', 'Jochen Rau', 'j.rau@web.de', 'jocrau', 'ad698615e7330e7ccd6be5fe89cc4233', 'Any database table can now be configured as a data source for every single type of term (very powerful!); example configuration for tt_address; matched terms are now registered as keywords to be inserted in the head-section; exclude individual content obj', '', 9, 0, 0),
(14525, 0, 'contagged', 1, '0.0.10', 2719, 67, 'Content parser and tagger', 'This extension parses your content to tag, replace and link specific terms. It is useful to auto-generate a glossary - but not only. For more information see ChangeLog and WiKi (http://wiki.typo3.org/index.php/Contagged).', 0, 0, 2, 1190413028, 'a:0:{}', 'Jochen Rau', 'j.rau@web.de', 'jocrau', '11487ef493521252e813875f5f0703ff', 'new type "Regular Expression" (every term is treated as RegEx and matches can be replaced; see TS Setup in setup.txt)', '', 10, 0, 0),
(14526, 0, 'contagged', 1, '0.0.11', 2719, 43, 'Content parser and tagger', 'This extension parses your content to tag, replace and link specific terms. It is useful to auto-generate a glossary - but not only. For more information see ChangeLog and WiKi (http://wiki.typo3.org/index.php/Contagged).', 0, 0, 2, 1190809440, 'a:0:{}', 'Jochen Rau', 'j.rau@web.de', 'jocrau', 'f3d50f7fc73915e2fd5ce6d7f5240950', 'You can and HAVE TO define storagePids (see ChangeLog)! Several other improvements.', '', 11, 0, 0),
(14527, 0, 'contagged', 1, '0.0.12', 2719, 62, 'Content parser and tagger', 'This extension parses your content to tag, replace and link specific terms. It is useful to auto-generate a glossary - but not only. For more information see ChangeLog and WiKi (http://wiki.typo3.org/index.php/Contagged).', 0, 0, 2, 1190941643, 'a:0:{}', 'Jochen Rau', 'j.rau@web.de', 'jocrau', '270406c9ef796044549f4b7092f6a88e', 'Now it will be checked if the table configured as a data source exists in the database (avoids an error message)', '', 12, 0, 0),
(14528, 0, 'contagged', 1, '0.0.13', 2719, 62, 'Content parser and tagger', 'This extension parses your content to tag, replace and link specific terms. It is useful to auto-generate a glossary - but not only. See ChangeLog and WiKi (http://wiki.typo3.org/index.php/Contagged). Needs PHP 4.4.0 or 5.1.0.', 0, 0, 2, 1191624802, 'a:0:{}', 'Jochen Rau', 'j.rau@web.de', 'jocrau', 'a4e618afe125040eb2a187776548f629', 'Enhanced performance of the FE-plugin; better support for joined words; fixed handling of ambiguities; some other improvements and fixes', '', 13, 0, 0),
(14529, 0, 'contagged', 1, '0.0.14', 2719, 60, 'Content parser and tagger', 'This extension parses your content to tag, replace and link specific terms. It is useful to auto-generate a glossary - but not only. See ChangeLog and WiKi (http://wiki.typo3.org/index.php/Contagged). Needs at least PHP 4.4.0', 0, 0, 2, 1191967910, 'a:0:{}', 'Jochen Rau', 'j.rau@web.de', 'jocrau', '049c010364b1cdd51d40a7f9b5604d02', 'fixed link back to page ... in FE-Plugin; improved support for multibyte character sets (using t3lib_cs instead of native strlen() and substr())', '', 14, 0, 0),
