(14539, 0, 'contagged', 1, '0.1.5', 2719, 90, 'Content parser and tagger', 'This extension parses your content to tag, replace and link specific terms. It is useful to auto-generate a glossary - but not only. See ChangeLog and WiKi (http://wiki.typo3.org/index.php/Contagged).', 1, 0, 2, 1222247894, 'a:0:{}', 'Jochen Rau', 'j.rau@web.de', 'jocrau', '051ce7ac9c8e6bd61f561e619118d63a', 'Its not necessary anymore to set maxRecurrences to invoke the parser; the parser is now invoked also for bullet lists and headers (if h[1-6] is not excluded); the matches are now spread over the cObj constantly', '', 1005, 0, 0),
(14540, 0, 'contagged', 1, '0.2.0', 2719, 48, 'Content parser and tagger (Glossary)', 'This extension parses your content to tag, replace and link specific terms. It is useful to auto-generate a glossary - but not only. See ChangeLog and WiKi (http://wiki.typo3.org/index.php/Contagged).', 1, 0, 2, 1228056353, 'a:0:{}', 'Jochen Rau', 'j.rau@web.de', 'jocrau', '26586bcf09410737deb9de911987244c', 'Restructured TS Setup (please adapt your TS Setup!). Sponsored by Paul Vetch (qedStudio): Mini list of terms found on a page; Search box; Page browser; Crosslinking between terms; Images in your term definitions (DAM aware).', '', 2000, 0, 0),
(14541, 0, 'contagged', 1, '0.2.1', 2719, 39, 'Content parser and tagger (Glossary)', 'This extension parses your content to tag, replace and link specific terms. It is useful to auto-generate a glossary - but not only. See ChangeLog and WiKi (http://wiki.typo3.org/index.php/Contagged).', 1, 0, 2, 1236674842, 'a:0:{}', 'Jochen Rau', 'j.rau@web.de', 'jocrau', '30f9a29d9a8a0f9aefde5ac1aff2a52d', 'Bugfix release (see ChangeLog): FIX Uninitialized variables (arrays); FIX Handling of UTF-8 (if you have UTF-8 enabled, please add "u" to "contagged.modifier  Uisu" in your TS constants)', '', 2001, 0, 0),
(14542, 0, 'contagged', 1, '1.0.0', 2719, 68, 'Content parser and tagger (Glossary)', 'This extension parses your content to tag, replace and link specific terms. It is useful to auto-generate a glossary - but not only. See ChangeLog and WiKi (http://wiki.typo3.org/index.php/Contagged).', 2, 0, 2, 1237546979, 'a:0:{}', 'Jochen Rau', 'j.rau@web.de', 'jocrau', 'a9264a419d9cbe5bee86255b64eccb46', 'Status is now STABLE (thanks for the numerous feed-back); default configuration of typolinks is now possible; added example configuration for CoolUrl (thanks to Carine); Bugfixes (see ChangeLog.txt)\r\n', '', 1000000, 0, 0),
(14543, 0, 'contagged', 1, '1.1.0', 2719, 37, 'Content parser and tagger (Glossary)', 'This extension parses your content to tag, replace and link specific terms. It is useful to auto-generate a glossary - but not only. See ChangeLog and WiKi (http://wiki.typo3.org/index.php/Contagged).', 2, 0, 2, 1250263710, 'a:0:{}', 'Jochen Rau', 'jochen.rau@typoplanet.de', 'jocrau', 'dc1d4bcd8f6d1cca8fe9dae40d5cce01', 'This is a bugfix release. Please see the ChangeLog and the project page on forge.typo3.org for more information.', 'typoplanet', 1001000, 0, 0),
(14544, 0, 'contagged', 1, '1.2.0', 2719, 45, 'Content parser and tagger (Glossary)', 'This extension parses your content to tag, replace and link specific terms. It is useful to auto-generate a glossary - but not only. See ChangeLog and WiKi (http://wiki.typo3.org/index.php/Contagged).', 2, 0, 2, 1251286648, 'a:0:{}', 'Jochen Rau', 'jochen.rau@typoplanet.de', 'jocrau', '4d4206e234799c2769204d438bb8ec86', 'Bugfix: Removed dependency to TYPO3 4.3 (t3lib_div::makeInstance()).', 'typoplanet', 1002000, 0, 0),
(14545, 0, 'contagged', 1, '1.3.0', 2719, 48, 'Content parser and tagger (Glossary)', 'This extension parses your content to tag, replace and link specific terms. It is useful to auto-generate a glossary - but not only. See ChangeLog and WiKi (http://wiki.typo3.org/index.php/Contagged).', 2, 0, 2, 1253099314, 'a:0:{}', 'Jochen Rau', 'jochen.rau@typoplanet.de', 'jocrau', '19af2bbdee8c9691b453797f28af5760', 'Fixed non-translated page titles in backlink (Thanks to Oliver Berg for reporting). Resolves 4478. Fixed an issue with the parser (appended terms to cObj in some rare cases).', 'typoplanet', 1003000, 0, 0),
(14546, 0, 'contagged', 1, '1.4.0', 2719, 155, 'Content parser and tagger (Glossary)', 'This extension parses your content to tag, replace and link specific terms. It is useful to auto-generate a glossary - but not only. See ChangeLog and WiKi (http://wiki.typo3.org/index.php/Contagged).', 2, 0, 2, 1254388738, 'a:0:{}', 'Jochen Rau', 'jochen.rau@typoplanet.de', 'jocrau', 'bb23bc544de695cad7fa836f3b87fc5d', 'Added configuration option plugin.tx_contagged.pagebrowser.wraps and switched to div-container. Added Icon for hidden terms (thx Matthias Koch). [!!!] Content of tables, uploads, captions, and html-cObj are now parsed, too. The long description of a term ', 'typoplanet', 1004000, 0, 0),
(14547, 0, 'contagged', 1, '1.5.0', 2719, 94, 'Content parser and tagger (Glossary)', 'This extension parses your content to tag, replace and link specific terms. It is useful to auto-generate a glossary - but not only. See ChangeLog and WiKi (http://wiki.typo3.org/index.php/Contagged).', 2, 0, 2, 1263293228, 'a:0:{}', 'Jochen Rau', 'jochen.rau@typoplanet.de', 'jocrau', 'e75482135965d7f81c4f8089099f79b8', 'Improved pagebrowser configuration. Added config option "respectCase". Template page id in the extension configuration not needed anymore. Replaced deprecated functions (now fully compliant to PHP 5.3). Removed experimental RTE integration. See ChangeLog ', 'typoplanet', 1005000, 0, 0),
(14548, 0, 'contagged', 1, '1.6.0', 2719, 431, 'Content parser and tagger (Glossary)', 'This extension parses your content to tag, replace and link specific terms. It is useful to auto-generate a glossary - but not only. See ChangeLog and WiKi (http://wiki.typo3.org/index.php/Contagged).', 2, 0, 2, 1265449464, 'a:0:{}', 'Jochen Rau', 'jochen.rau@typoplanet.de', 'jocrau', '5528dbb2644749ef005b84617e19ee5b', 'Huge performance improvement (tested with 1000 terms). New CSS based tooltip (even with block tags). [!!!] Changed $_GET parameters. Fixed compatibility with PHP 5.3.x. Please read the upgrade instructions in README.txt first!', 'typoplanet', 1006000, 0, 0),
(14549, 0, 'contagged', 1, '1.7.0', 2719, 0, 'Content parser and tagger (Glossary)', 'This extension parses your content to tag, replace and link specific terms. It is useful to auto-generate a glossary - but not only. See ChangeLog and WiKi (http://wiki.typo3.org/index.php/Contagged).', 2, 0, 2, 1343761820, 'a:0:{}', 'Jochen Rau', 'jochen.rau@typoplanet.de', 'jocrau', '98d9ec44b588d4952a69a598978dc10c', 'Bugfixes and some new features, including cross-reference, pronounciation, and media property. Please read change log for more information.', 'typoplanet', 1007000, 1, 0),
