(14599, 0, 'l10nmgr', 1, '8.1.2', 1986, 0, 'Localization Manager', 'Module for managing localization import and export', 1, 0, 1, 1507232904, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:13:"8.7.0-8.99.99";s:18:"static_info_tables";s:11:"6.4.2-0.0.0";}}', 'Kasper Skaarhoej, Daniel Zielinski, Daniel Poetzinger, Fabian Seltmann, Andreas Otto, Jo Hasenau, Peter Russ', 'kasperYYYY@typo3.com, info@loctimize.com, info@cybercraft.de, pruss@uon.li', 'l10nmgr', 'acacc1c4ccaf7fe939172057a8b623f6', 'Maintenance release that fixes problems with extensions implementing flexform data structures the "old school" way. Uses the deprecated core method BackendUtility::getFlexFormDS as fallback to ensure backward compatibility.', 'Localization Manager Team', 8001002, 0, 0),
(14600, 0, 'l10nmgr', 1, '8.2.0', 1986, 0, 'Localization Manager', 'Module for managing localization import and export', 1, 0, 1, 1507541387, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:13:"8.7.0-8.99.99";s:18:"static_info_tables";s:11:"6.4.2-0.0.0";}}', 'Kasper Skaarhoej, Daniel Zielinski, Daniel Poetzinger, Fabian Seltmann, Andreas Otto, Jo Hasenau, Peter Russ', 'kasperYYYY@typo3.com, info@loctimize.com, info@cybercraft.de, pruss@uon.li', 'l10nmgr', 'f665ea2eedaaaf0e66e108f68d7c3786', 'Maintenance release to stay compatible with new flexform methods of the CMS 8 core. Fixes issues with Gridelements, DCE and others. Still makes use of deprecated FlexformUtility methods as fallback solutions for extensions.', 'Localization Manager Team', 8002000, 0, 0),
(14601, 0, 'l10nmgr', 1, '8.2.1', 1986, 0, 'Localization Manager', 'Module for managing localization import and export', 1, 0, 1, 1507649850, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:13:"8.7.0-8.99.99";s:18:"static_info_tables";s:11:"6.4.2-0.0.0";}}', 'Kasper Skaarhoej, Daniel Zielinski, Daniel Poetzinger, Fabian Seltmann, Andreas Otto, Jo Hasenau, Peter Russ', 'kasperYYYY@typo3.com, info@loctimize.com, info@cybercraft.de, pruss@uon.li', 'l10nmgr', '1eabfb2e27cdb7f687de880bfcb6965d', 'This is a maintenance release for CMS 8 only. It fixes a regression introduced with version 8.1.1, that wrongly exported input fields with integer data. So sys_file_reference translations were reimported still connected to the parent element in the defaul', 'Localization Manager Team', 8002001, 1, 0),
