(14737, 0, 'sp_bettercontact', 1, '2.4.0', 5702, 108, 'Better Contact', 'Secure Contact form with solid Spam protection. Input can be checked for length, allowed and disallowed signs and with Regular Expressions. Attackers can be locked if they try to send a lot of mails. Admin can get detailed Spam notifications. Captcha supp', 2, 0, 3, 1276673931, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"5.2.0-0.0.0";s:5:"typo3";s:11:"4.2.0-0.0.0";}}', 'Kai Vogel', 'kai.vogel ( at ) speedprogs.de', 'speedprogs_de', 'a4179c81e4319de7634a66cbe231bf8e', 'HTML email support, Logging, Backend module with CSV export, Internal and external DB support, Added mathguard support, ...\r\nWarning: Removed support for TYPO3 below 4.2.0', 'www.speedprogs.de', 2004000, 0, 0),
(14738, 0, 'sp_bettercontact', 1, '2.4.1', 5702, 50, 'Better Contact', 'Secure Contact form with solid Spam protection. Input can be checked for length, allowed and disallowed signs and with Regular Expressions. Attackers can be locked if they try to send a lot of mails. Admin can get detailed Spam notifications. Captcha supp', 2, 0, 3, 1277892650, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"5.2.0-0.0.0";s:5:"typo3";s:11:"4.2.0-0.0.0";}}', 'Kai Vogel', 'kai.vogel ( at ) speedprogs.de', 'speedprogs_de', '6faefe3d6ec815b4158d5833cd350bcb', 'Added userFunc which is called if form was submitted, fixed comment line detection in Flexform-TypoScript-parser, fixed wizard icon in TYPO3 4.4.', 'www.speedprogs.de', 2004001, 0, 0),
(14739, 0, 'sp_bettercontact', 1, '2.4.2', 5702, 58, 'Better Contact', 'Secure Contact form with solid Spam protection. Input can be checked for length, allowed and disallowed signs and with Regex. Attackers can be locked. Admin can get detailed Spam notification. Requests can be stored into DB. Captcha support included.', 2, 0, 3, 1279189751, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"5.2.0-0.0.0";s:5:"typo3";s:11:"4.2.0-0.0.0";}}', 'Kai Vogel', 'kai.vogel ( at ) speedprogs.de', 'speedprogs_de', 'fae9377449cf8c352597bb91a9e07544', 'Added French translation, Fixed TemplaVoila wizard for new content elements, Added option to not send emails, Added option to choose sender address', 'www.speedprogs.de', 2004002, 0, 0),
