(14925, 0, 'pt_gsashop', 1, '0.9.6', 1067, 63, 'GSA Shop', 'PHP5 Shop System based on the database of the German ERP software GS AUFTRAG. NOTE: Current TER upload for testing only: pt_gsashop is still under development, not all features are tested thoroughly. Dont expect all APIs and templates staying unchanged!', 0, 0, 3, 1193243925, 'a:0:{}', 'Rainer Kuhn', 'kuhn@punkt.de', 'sonic', '3ef33aa3632a8fb4d632e05153716c20', 'Automatic invoice booking in ERP, reorganization of the article structure, bugfixes for article fixed costs etc. - see the manuals changelog for details', 'punkt.de GmbH', 9006, 0, 0),
(14926, 0, 'pt_gsashop', 1, '0.9.3', 1067, 59, 'GSA Shop', 'Online shop system to order products based on the database of the German enterprise resource planning software GS AUFTRAG', 0, 0, 3, 1183645563, 'a:1:{s:7:"depends";a:10:{s:3:"cms";s:0:"";s:4:"lang";s:0:"";s:6:"smarty";s:6:"1.0.2-";s:8:"pt_tools";s:7:"0.1.10-";s:12:"pt_gsasocket";s:6:"0.1.7-";s:13:"pt_gsauserreg";s:7:"0.0.10-";s:14:"pt_gsauserauth";s:6:"0.0.2-";s:12:"pt_heidelpay";s:6:"0.1.2-";s:3:"php";s:11:"5.1.0-0.0.0";s:5:"typo3";s:11:"4.0.0-0.0.0";}}', 'Rainer Kuhn', 'kuhn@punkt.de', 'sonic', '2af35bb234c5602c2811bae10d201a88', 'Initial TER upload for testing purposes. IMPORTANT: The extension is still under development in _alpha_ state and the current version has not been tested thoroughly, so dont expect every feature combination to work without problems and dont expect all A', 'punkt.de GmbH', 9003, 0, 0),
(14927, 0, 'pt_gsashop', 1, '0.9.4', 1067, 60, 'GSA Shop', 'PHP5 based shop system based on the database of the German ERP software GS AUFTRAG. NOTE: Current TER upload for testing only: pt_gsashop is under development in ALPHA state and not tested thoroughly. Dont expect all APIs and templates staying unchanged!', 0, 0, 3, 1185552210, 'a:0:{}', 'Rainer Kuhn', 'kuhn@punkt.de', 'sonic', 'f2116fa183157b75bc5afce89e00ac74', 'Internal change of processing 4 decimal places incl. complete conversion of all float calculations to BCMath functions - IMPORTANT: This requires PHP to be configured with  --enable-bcmath (see www.php.net/bc); several improvements and bugfixes', 'punkt.de GmbH', 9004, 0, 0),
(14928, 0, 'pt_gsashop', 1, '0.9.5', 1067, 42, 'GSA Shop', 'PHP5 Shop System based on the database of the German ERP software GS AUFTRAG. NOTE: Current TER upload for testing only: pt_gsashop is still under development, not all features are tested thoroughly. Dont expect all APIs and templates staying unchanged!', 0, 0, 3, 1192012166, 'a:1:{s:7:"depends";a:10:{s:3:"cms";s:0:"";s:4:"lang";s:0:"";s:6:"smarty";s:6:"1.0.2-";s:8:"pt_tools";s:6:"0.2.0-";s:12:"pt_gsasocket";s:6:"0.1.7-";s:13:"pt_gsauserreg";s:7:"0.0.10-";s:14:"pt_gsauserauth";s:6:"0.0.2-";s:12:"pt_heidelpay";s:6:"0.1.2-";s:3:"php";s:11:"5.1.0-0.0.0";s:5:"typo3";s:11:"4.0.0-0.0.0";}}', 'Rainer Kuhn', 'kuhn@punkt.de', 'sonic', '749c5e81fc911cf408b26d487cff1e8b', 'Overhaul of the GSA DB storage of shop order confirmations and invoices for seamless integration into GSA ERP, fixed bank account holder name bug for automatically created DTA records', 'punkt.de GmbH', 9005, 0, 0),
(14929, 0, 'pt_gsashop', 1, '0.10.0', 1067, 118, 'GSA Shop', 'PHP5 Shop System based on the database of the German ERP software GS AUFTRAG. NOTE: Current TER upload for testing only: pt_gsashop is still under development, not all features are tested thoroughly. Dont expect all APIs and templates staying unchanged!', 0, 0, 4, 1202468710, 'a:1:{s:7:"depends";a:9:{s:3:"cms";s:0:"";s:4:"lang";s:0:"";s:6:"smarty";s:6:"1.0.2-";s:8:"pt_tools";s:6:"0.2.2-";s:12:"pt_gsasocket";s:6:"0.1.7-";s:13:"pt_gsauserreg";s:7:"0.0.12-";s:12:"pt_heidelpay";s:6:"0.1.2-";s:3:"php";s:11:"5.1.0-0.0.0";s:5:"typo3";s:11:"4.0.0-0.0.0";}}', 'Rainer Kuhn', 'kuhn@punkt.de', 'sonic', 'e31668b6b7c973097e0917686b6cfdf9', 'Major changes and enhancements (article images implemented, usability improvements etc.) and general cleanup. Existing installations have to be updated manually(!) - see the manuals changelog for details.', 'punkt.de GmbH', 10000, 0, 0),
(14930, 0, 'pt_gsashop', 1, '0.11.0', 1067, 103, 'GSA Shop', 'PHP5 Shop System based on a data layer compatible to the German ERP system "GS AUFTRAG Professional". NOTE: pt_gsashop is still under development, not all features are tested thoroughly. Dont expect all APIs and templates staying unchanged!', 0, 0, 4, 1209560053, 'a:1:{s:7:"depends";a:9:{s:3:"cms";s:0:"";s:4:"lang";s:0:"";s:6:"smarty";s:6:"1.0.2-";s:8:"pt_tools";s:6:"0.2.5-";s:12:"pt_gsasocket";s:6:"0.2.1-";s:13:"pt_gsauserreg";s:7:"0.0.12-";s:12:"pt_heidelpay";s:6:"0.1.2-";s:3:"php";s:11:"5.1.0-0.0.0";s:5:"typo3";s:11:"4.0.0-0.0.0";}}', 'Rainer Kuhn', 'kuhn@punkt.de', 'sonic', '13d2caa82a9b8d7b63d7f101aa08a053', 'GSA Shop is usable as a TYPO3 standalone version now (disengagement of ERP software). Please refer to the manuals changelog for details of all other changes, improvements, bugfixes and cleanup.', 'punkt.de GmbH', 11000, 0, 0),
(14931, 0, 'pt_gsashop', 1, '0.12.0', 1067, 44, 'GSA Shop', 'PHP5 Shop System based on a data layer compatible to the German ERP system "GS AUFTRAG Professional". This extension is the core of the General Shop Applications (GSA) extension family.', 1, 0, 4, 1215028399, 'a:0:{}', 'Rainer Kuhn', 'kuhn@punkt.de', 'sonic', '5de1b22e3b1b3535f7f087cd116db86c', 'Major clean-up of legacy issues - due to incisive changes PLEASE READ THE MANUALS CHANGELOG CAREFULLY BEFORE UPDATING an existing installation!', 'punkt.de GmbH', 12000, 0, 0),
(14932, 0, 'pt_gsashop', 1, '0.12.1', 1067, 44, 'GSA Shop', 'PHP5 Shop System based on a data layer compatible to the German ERP system "GS AUFTRAG Professional". This extension is the core of the General Shop Applications (GSA) extension family.', 1, 0, 4, 1215176802, 'a:1:{s:7:"depends";a:8:{s:3:"cms";s:0:"";s:4:"lang";s:0:"";s:6:"smarty";s:6:"1.0.2-";s:8:"pt_tools";s:6:"0.3.0-";s:12:"pt_gsasocket";s:6:"0.2.1-";s:13:"pt_gsauserreg";s:7:"0.0.12-";s:3:"php";s:11:"5.1.0-0.0.0";s:5:"typo3";s:11:"4.1.0-0.0.0";}}', 'Rainer Kuhn', 'kuhn@punkt.de', 'sonic', '3d8eb26a20035c4b15b56c486fe97633', 'added update warning to EM - PLEASE READ THE MANUALS CHANGELOG CAREFULLY BEFORE UPDATING from version 0.11.0 or lower!', 'punkt.de GmbH', 12001, 0, 0),
(14933, 0, 'pt_gsashop', 1, '0.12.2', 1067, 116, 'GSA Shop', 'PHP5 Shop System based on a data layer compatible to the German ERP system "GS AUFTRAG Professional". This extension is the core of the General Shop Applications (GSA) extension family.', 1, 0, 4, 1215728636, 'a:1:{s:7:"depends";a:8:{s:3:"cms";s:0:"";s:4:"lang";s:0:"";s:6:"smarty";s:6:"1.0.2-";s:8:"pt_tools";s:6:"0.3.0-";s:12:"pt_gsasocket";s:6:"0.2.1-";s:13:"pt_gsauserreg";s:7:"0.0.12-";s:3:"php";s:11:"5.1.0-0.0.0";s:5:"typo3";s:11:"4.1.0-0.0.0";}}', 'Rainer Kuhn', 'kuhn@punkt.de', 'sonic', 'efc0d289f4c9d5635c098248ee3b9b63', 'Added new pricing settings, improved article plugin usage via Typoscript - please refer to the manuals changelog for details.', 'punkt.de GmbH', 12002, 0, 0),
(14934, 0, 'pt_gsashop', 1, '0.13.0', 1067, 67, 'GSA Shop', 'PHP5 Shop System based on a data layer compatible to the German ERP system "GS AUFTRAG Professional". This extension is the core of the General Shop Applications (GSA) extension family.', 1, 0, 4, 1224601856, 'a:1:{s:7:"depends";a:8:{s:3:"cms";s:0:"";s:4:"lang";s:0:"";s:6:"smarty";s:6:"1.0.2-";s:8:"pt_tools";s:6:"0.4.0-";s:12:"pt_gsasocket";s:6:"0.2.1-";s:13:"pt_gsauserreg";s:7:"0.0.12-";s:3:"php";s:11:"5.1.0-0.0.0";s:5:"typo3";s:11:"4.1.0-0.0.0";}}', 'Rainer Kuhn', 'kuhn@punkt.de', 'sonic', 'ca99bbfe502e24e2acb6dfdf334c6679', 'Major performance improvements, core additions for payment modifiers, several new hooks and default template markers, miscellaneous internal improvements - please refer to the manuals changelog for details.', 'punkt.de GmbH', 13000, 0, 0),
(14935, 0, 'pt_gsashop', 1, '0.14.0', 1067, 43, 'GSA Shop', 'PHP5 Web Shop System. This extension is the core of the General Shop Applications (GSA) extension family. GSA Shop is based on a data layer compatible to the German ERP system "GS AUFTRAG Professional" and allows optional usage combined with the ERP.', 1, 0, 4, 1229611638, 'a:1:{s:7:"depends";a:9:{s:3:"cms";s:0:"";s:4:"lang";s:0:"";s:6:"smarty";s:6:"1.0.2-";s:8:"pt_tools";s:6:"0.4.1-";s:7:"pt_mail";s:6:"0.0.1-";s:12:"pt_gsasocket";s:6:"0.3.0-";s:13:"pt_gsauserreg";s:6:"0.1.0-";s:3:"php";s:11:"5.1.0-0.0.0";s:5:"typo3";s:11:"4.1.0-0.0.0";}}', 'Rainer Kuhn', 'kuhn@punkt.de', 'sonic', '403e059decdb6a38c3bcb8380b440cce', 'Supports GSA DB imported into TYPO3 DB now, refactored order submission process, revised email dispatch, numerous improvements and fixes - due to incisive changes PLEASE READ THE MANUALS CHANGELOG CAREFULLY BEFORE UPDATING an existing installation!', 'punkt.de GmbH', 14000, 0, 0),
