(15042, 0, 'rvt_detectsqlinjection', 1, '0.0.1', 301, 30, 'SQL Injection Detection', 'Try to detect SQL injections in $_GET and $_POST variables', 1, 0, 4, 1182015756, 'a:0:{}', 'Ries van twisk', 'ries@vantwisk.nl', 'ries', 'fba37ec8ad49d763e73b8148617a15a0', 'First release of this extensions. Any comments are welcome!', '', 1, 0, 0),
(15043, 0, 'rvt_detectsqlinjection', 1, '0.0.2', 301, 26, 'SQL Injection Detection', 'Try to detect SQL injections in $_GET and $_POST variables', 1, 0, 4, 1182021537, 'a:0:{}', 'Ries van twisk', 'ries@vantwisk.nl', 'ries', '1a8a6cf7be1493e278f76abec82a81bc', 'Add a couple of more detections. Later I want to change the system a bit since when teh array grows large, the system gets slower.', '', 2, 0, 0),
(15044, 0, 'rvt_detectsqlinjection', 1, '0.0.3', 301, 36, 'SQL Injection Detection', 'Try to detect SQL injections in $_GET and $_POST variables', 1, 0, 4, 1182025741, 'a:0:{}', 'Ries van twisk', 'ries@vantwisk.nl', 'ries', '20ba2c99b843b06179bfbbd5ab645760', ' - Modified the code to handle more injection types.\r\n - Show in the email what was matched on which parameter (there is room for improvement still).\r\n', '', 3, 0, 0),
(15045, 0, 'rvt_detectsqlinjection', 1, '0.0.4', 301, 28, 'SQL Injection Detection', 'Try to detect SQL injections in $_GET and $_POST variables', 1, 0, 4, 1182088924, 'a:0:{}', 'Ries van twisk', 'ries@vantwisk.nl', 'ries', '1bec67323e8d5c11ae11ab9194f62260', '- Solved a small bug where a match couldnt be found.\r\n- Added a exclusion parameter list so you can tell teh system what parameters not to match on.\r\n- Update some of the match rules', '', 4, 0, 0),
(15046, 0, 'rvt_detectsqlinjection', 1, '0.0.5', 301, 28, 'SQL Injection Detection', 'Try to detect SQL injections in $_GET and $_POST variables', 1, 0, 4, 1182089294, 'a:0:{}', 'Ries van twisk', 'ries@vantwisk.nl', 'ries', 'd4f3fd974e5a3956a7a630fa749fb1c9', 'Reset unset parameters to nothing, to be really save.', '', 5, 0, 0),
(15047, 0, 'rvt_detectsqlinjection', 1, '0.0.6', 301, 100, 'SQL Injection Detection', 'Try to detect SQL injections in GET/POST and COOKIE variables. This extension was written after a discussion about how to secure TYPO3 more. This is one method and can be used as an first line of defence. It will catch some SQL injections attacks, but pos', 1, 0, 4, 1182091081, 'a:0:{}', 'Ries van twisk', 'ries@vantwisk.nl', 'ries', 'a3a2ddc9ef00f50b8e50198a0c967350', 'Added a readme.txt file so you can see how/why and will also contain installation notes.\r\n\r\n', '', 6, 0, 0),
(15048, 0, 'rvt_detectsqlinjection', 1, '0.1.0', 301, 53, 'SQL Injection Detection', 'Try to detect SQL injections in $_GET and $_POST variables', 1, 0, 4, 1250639411, 'a:0:{}', 'Ries van twisk', 'ries@vantwisk.nl', 'ries', 'ba79ef6c1fc4422b516a8e4a01ed30e1', 'Added more info im mail', '', 1000, 1, 0),
