(15283, 0, 'phpbb3_auth', 1, '0.0.1', 496, 33, 'Authenticate phpbb3 users as FE-users', 'Based on phpbb_auth. A service which allows FE users to authenticate against a phpbb3 forum, users can also be logged into the forum at the same time if autologin is enabled.\r\n	This version supports different databases for phpbb3 and TYPO3. Tested with RC', 0, 0, 5, 1183706151, 'a:0:{}', 'Fabian Friedrich, Carsten Fuchs,Graham Solomon', 'info@shar-k.de', 'fehlgeleitet', '9da5854ae83bb3c9d568c05dc9ce7709', 'Initial upload. Please refer to README.txt for installation hints.', 'http://www.shar-k.de', 1, 0, 0),
(15284, 0, 'phpbb3_auth', 1, '0.1.0', 496, 65, 'Authenticate phpbb3 users as FE-users', 'Based on phpbb_auth. A service which allows FE users to authenticate against a phpbb3 forum, users can also be logged into the forum at the same time if autologin is enabled.\n	This version supports different databases for phpbb3 and TYPO3. Tested with RC1', 0, 0, 5, 1184336837, 'a:0:{}', 'Fabian Friedrich, Carsten Fuchs,Graham Solomon', 'info@shar-k.de', 'fehlgeleitet', '9f817d2c8e39d775f65e33a096c15ce4', 'Authentcation of phpbb3-user against TYPO3 possible now. Group-handling implemented (both directions). Some bugs fixed.', 'http://www.shar-k.de', 1000, 0, 0),
(15285, 0, 'phpbb3_auth', 1, '0.1.1', 496, 328, 'Authenticate phpbb3 users as FE-users', 'Based on phpbb_auth. A service which allows FE users to authenticate against a phpbb3 forum, users can also be logged into the forum at the same time if autologin is enabled.\n	This version supports different databases for phpbb3 and TYPO3. Tested with RC1', 0, 0, 5, 1189940908, 'a:0:{}', 'Fabian Friedrich, Carsten Fuchs,Graham Solomon', 'info@shar-k.de', 'fehlgeleitet', '9f6f89b395289c61cc92124c829650a7', 'Fixed bug in handling of groups for newly created users, added manual.', 'http://www.shar-k.de', 1001, 0, 0),
