(15373, 0, 'pear', 1, '2.3.0', 884, 34, 'PEAR Manager', 'Install, delete or update PEAR-packages\n\nWe as ECT / Extension Coordination Team have seen that we need a defined location for PEAR-packages so that extensions can depend on PEAR. With this extension we have it now.\n\nPEAR-directory:\nEXT:pear/PEA', 2, 0, 5, 1184005056, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"3.0.0-0.0.0";s:5:"typo3";s:11:"4.0.0-0.0.0";}}', 'Rafael Schaer, Daniel Bruessler', 'info@patchworking.de', 'patchworker', '9d999169a66d358f3b4776a43a2f1fb1', ' transfer: from extension-key bypear to "pear\r\n added ChangeLog\r\n optimized: moduleicon 16x16\r\n translation for installation-process: added handling for llXML, added german version\r\n TESTED: Version 2.3.0 - Linux Ubuntu with PHP 5.1.2, TYPO3 4.1.1\r\n', 'TYPO3 ECT / ExtensionCoordinatonTeam', 2003000, 0, 0),
(15374, 0, 'pear', 1, '2.3.1', 884, 37, 'PEAR Manager', 'Install, delete or update PEAR-packages.\n\nWe as ECT / Extension Coordination Team have seen that we need a standard location for PEAR-packages so that extensions can depend on PEAR. With this extension we have it now:\nEXT:pear/PEAR\n\nPEAR-data-di', 2, 0, 5, 1184067335, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"4.4.2-0.0.0";s:5:"typo3";s:11:"4.0.0-0.0.0";}}', 'Daniel Bruessler, Rafael Schaer', 'info@patchworking.de', 'patchworker', '19f300f2bc1b9bb0b2ca3271a08788e5', ' translation: some corrections\r\n include_path: info how to set for current server in php.ini or any server with ini_set\r\n delete all: now the manual will NOT be deleted when one wants to delete all PEAR-packages ... (Argh!), created manual again\r\n upl', 'TYPO3 ECT / ExtensionCoordinatonTeam', 2003001, 0, 0),
(15375, 0, 'pear', 1, '2.3.2', 884, 30, 'PEAR Manager', 'Install, delete or update PEAR-packages.\n\nWe as ECT / Extension Coordination Team have seen that we need a standard location for PEAR-packages so that extensions can depend on PEAR. With this extension we have it now:\nEXT:pear/PEAR\n\nPEAR-data-di', 2, 0, 5, 1184240492, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"4.4.2-0.0.0";s:5:"typo3";s:11:"4.0.0-0.0.0";}}', 'Daniel Bruessler, Rafael Schaer', 'info@patchworking.de', 'patchworker', 'e844f3fd65bb91d0a331515b1b1e597d', 'link to last manual-version: http://typo3.org/documentation/document-library/extension-manuals/pear/2.3.1/view/\r\n\r\n     manual: corrections, tutorial for PEAR_Info, better screenshot for security-button\r\n     translation: french translation by Fabien Ud', 'TYPO3 ECT / ExtensionCoordinatonTeam', 2003002, 0, 0),
(15376, 0, 'pear', 1, '2.3.3', 884, 65, 'PEAR Manager', 'Install, delete or update PEAR-packages.\n\nWe as ECT / Extension Coordination Team have seen that we need a standard location for PEAR-packages so that extensions can depend on PEAR. With this extension we have it now:\nEXT:pear/PEAR .\n\nPEAR-data-', 2, 0, 5, 1184410086, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"4.4.2-0.0.0";s:5:"typo3";s:11:"4.0.0-0.0.0";}}', 'Extension Coordination Team (ECT), Daniel Bruessler, Rafael Schaer', 'info@patchworking.de', 'patchworker', '55f137908e655d9fb51a9344b09b281e', 'last manual http://typo3.org/documentation/document-library/extension-manuals/pear/2.3.2/view/\r\n     include_path: on-off-switch for automatic "auto-pilot" in Extension Manager\r\n     include_path: ext/pear/PEAR must be first in the queue of any pear-rep', 'TYPO3 ECT / ExtensionCoordinatonTeam', 2003003, 0, 0),
(15377, 0, 'pear', 1, '2.3.4', 884, 58, 'PEAR Manager', 'Install, delete or update PEAR-packages.\n\nWe as ECT / Extension Coordination Team have seen that we need a standard location for PEAR-packages so that extensions can depend on PEAR. With this extension we have it now:\nEXT:pear/PEAR .\n\nPEAR-data-', 2, 0, 4, 1190764004, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:12:"4.4.2-5.99.0";s:5:"typo3";s:12:"4.0.0-4.99.0";}}', 'Extension Coordination Team (ECT), Daniel Bruessler, Rafael Schaer', 'info@patchworking.de', 'patchworker', 'b48810caea3e9981fcb9a41a21aa8046', 'last manual http://typo3.org/documentation/document-library/extension-manuals/pear/2.3.3/view/\r\n\r\ninclude_path correction, error-handling, constraints, category misc', 'TYPO3 ECT / ExtensionCoordinatonTeam', 2003004, 0, 0),
(15378, 0, 'pear', 1, '2.3.5', 884, 178, 'PEAR Manager', 'Install, delete, update PEAR-packages (also for other extensions).\r\n\r\nThe central path for the PEAR-packages has changed: "typo3conf/pear/PEAR". The "auto-pilot" puts this as first PEAR-package into the include_path. Use the INSTALL-manager to put pear as', 2, 0, 4, 1192736989, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:12:"4.4.2-5.99.0";s:5:"typo3";s:12:"4.0.0-4.99.0";}}', 'Extension Coordination Team (ECT), Daniel Bruessler, Rafael Schaer', 'info@patchworking.de', 'patchworker', 'c0f82693d3265138e80ea4e06d33db2e', 'last manual http://typo3.org/documentation/document-library/extension-manuals/pear/2.3.4/view/ "auto-pilot" also for safe_mode_include_dir, download-location: http://pear.php.net/go-pear, new path "localconf/pear/PEAR", better usability for settings', 'TYPO3 ECT / ExtensionCoordinatonTeam', 2003005, 0, 0),
(15379, 0, 'pear', 1, '2.3.6', 884, 482, 'PEAR Manager', 'Install, delete, update PEAR-packages.\n\nTYPO3 4.2 bugfixed. Install pear before other PEAR-extensions (extList). So you can use $TYPO3_CONF_VARS[PEAR][isAuto] and $TYPO3_CONF_VARS[PEAR][packagePath] (with apostrophes) in your ext to check if a newer PEAR-', 2, 0, 4, 1208560152, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:13:"4.4.2-5.99.99";s:5:"typo3";s:13:"3.8.0-4.99.99";}}', 'ExtensionCoordinationTeam, Daniel Bruessler, Rafael Schaer', 'info@patchworking.de', 'patchworker', '80fe5211a8a1a9b373186298e898305e', 'last manual http://typo3.org/documentation/document-library/extension-manuals/pear/2.3.5/view/\r\n', 'TYPO3 ECT / ExtensionCoordinatonTeam', 2003006, 1, 0),
