(15384, 0, 'ttnews_teasertext', 1, '1.0.0', 399, 14, 'Teaser Text for tt_news', 'This extension adds another template marker for tt_news that will be replaced by teaser text of a news item, e.g. first sentence or first paragraph of news text.', 1, 0, 4, 1184151234, 'a:0:{}', 'Ralph Schuster', 'typo3@ralph-schuster.eu', 'zec100', '0b6c72dbd11f5becd4f1104bd6b27211', 'First upload of this extension. However, the extension runs stable on my productive website.', '', 1000000, 0, 0),
(15385, 0, 'ttnews_teasertext', 1, '1.0.1', 399, 12, 'Teaser Text for tt_news', 'This extension adds another template marker for tt_news that will be replaced by teaser text of a news item, e.g. first sentence or first paragraph of news text.', 1, 0, 4, 1184157114, 'a:0:{}', 'Ralph Schuster', 'typo3@ralph-schuster.eu', 'zec100', '3e7d7ff268543e62ccd1b92668a5e4a4', 'Fixed hookup registration, so the marker items get processed first by ttnews_teasertext. Also fixed counting method for text parts.', '', 1000001, 0, 0),
