(15389, 0, 'pagetreetools', 1, '1.0.1', 836, 105, 'PageTree Tools', 'Allows you to perform various actions via clickmenu, such as highlighting pages and branches, directly setting page type and improved expand/collapse parts of the page tree.', 2, 0, 0, 1185540392, 'a:0:{}', 'Dev-Team Typoheads', 'dev@typoheads.at', 'typoheads', '8f34bfedf3e40f07618d01352f8941d0', 'removed useless features, moved menu entries for "set page type" and "expand/collapse" to the original positions again.', '', 1000001, 0, 0),
(15390, 0, 'pagetreetools', 1, '0.0.1', 836, 10, 'PageTree Tools', 'Allows you to perform various actions via clickmenu, such as highlighting pages and branches, directly setting page type and improved expand/collapse parts of the page tree.', 2, 0, 0, 1186653410, 'a:0:{}', 'Dev-Team Typoheads', 'dev@typoheads.at', 'typoheads', '21e05b919aa256238c6f3580b88e3c35', 'Added feature to minimize/restore navigation frame\r\nMark Page feature can be disabled\r\nMark Branch feature can be disabled\r\nRemoved Advanced current page highlighting because its useless\r\nAdded feature to add a second link to reload tree from serve', '', 1, 0, 0),
(15391, 0, 'pagetreetools', 1, '1.0.2', 836, 59, 'PageTree Tools', 'Allows you to perform various actions via clickmenu, such as highlighting pages and branches, directly setting page type and improved expand/collapse parts of the page tree.', 2, 0, 0, 1186653472, 'a:0:{}', 'Dev-Team Typoheads', 'dev@typoheads.at', 'typoheads', '8376ddb9002774da2c7ebf31de670c43', 'Added feature to minimize/restore navigation frame\r\nMark Page feature can be disabled\r\nMark Branch feature can be disabled\r\nRemoved Advanced current page highlighting because its useless\r\nAdded feature to add a second link to reload tree from serve', '', 1000002, 0, 0),
