(15498, 0, 'dam_frontend', 1, '0.1.0', 3168, 484, 'DAM Frontend', 'Shows the dam category tree in frontend, so users can select files by combining dam categories. Files are delivered by a pushfile, so that the fileadmin directory can be secured by a .htaccess file. A second plugin shows selected (by an author) dam files.', 0, -1, 2, 1185217565, 'a:1:{s:7:"depends";a:3:{s:3:"dam";s:12:"0.0.0-1.0.99";s:3:"php";s:11:"4.0.0-0.0.0";s:5:"typo3";s:11:"4.0.0-0.0.0";}}', 'Martin Baum', 'typo3@bus-netzwerk.de', 'stefan.busemann', 'ebfa7b78c24fe5fa5286fc00e26ca245', 'First release. Please check the manual for detailed installation information. This is (currently) no plug & play extension', 'BUS GmbH', 1000, 0, 0),
(15499, 0, 'dam_frontend', 1, '0.1.1', 3168, 83, 'DAM Frontend', 'Shows the dam category tree in frontend, so users can select files by combining dam categories. Files are delivered by a pushfile, so that the fileadmin directory can be secured by a .htaccess file. A second plugin shows selected (by an author) dam files.', 0, -1, 3, 1216994919, 'a:1:{s:7:"depends";a:3:{s:3:"dam";s:12:"0.0.0-1.0.99";s:3:"php";s:11:"4.0.0-0.0.0";s:5:"typo3";s:11:"4.0.0-0.0.0";}}', 'Martin Baum, Stefan Busemann', 'typo3@in2form.com', 'stefan.busemann', 'f9309667a70776f309fc96ad0f175c81', 'Fixed multiple vulnerabilities in extension  dam_frontend. Thanks to the security team and Marcus Krausec[Ticket2008052210000041]', 'in2form.com', 1001, 0, 0),
(15500, 0, 'dam_frontend', 1, '0.1.2', 3168, 113, 'DAM Frontend', 'Shows the dam category tree in frontend, so users can select files by combining dam categories. Files are delivered by a pushfile, so that the fileadmin directory can be secured by a .htaccess file. A second plugin shows selected (by an author) dam files.', 0, -1, 3, 1218311417, 'a:1:{s:7:"depends";a:3:{s:3:"dam";s:12:"0.0.0-1.0.99";s:3:"php";s:11:"4.0.0-0.0.0";s:5:"typo3";s:11:"4.0.0-0.0.0";}}', 'Martin Baum, Stefan Busemann', 'typo3@in2form.com', 'stefan.busemann', '32c2523eb955ac60c443dd3d71c722fc', 'Feature 1248: stdWrap for all fields (pi1)\r\nThanks to Frank Ngler. Now it is posible to use typoscript for the views "single view" and "file list". Each database field, wich is used in the view can be customized with typoscript.\r\n\r\nBug 1254 resolved:', 'in2form.com', 1002, 0, 0),
