(15703, 0, 'gl_transstat', 1, '1.2.0', 607, 17, 'Translation Status', 'Automatize the creation of page and records translations, keeping track of translation status of them. Very useful for multilanguage websites and tasks related with internationalization and localization', 2, 0, 0, 1213874629, 'a:1:{s:7:"depends";a:2:{s:11:"templavoila";s:0:"";s:15:"gl_be_templates";s:0:"";}}', 'Diego Pino', 'dpino@igalia.com', 'mrego', '361897478d0d4214f765a84b8bc7c799', 'Automatized process to create translated pages and contents. Now it is possible to translate more than one page or record at the same time.', 'Igalia - http://www.igalia.com', 1002000, 0, 0),
(15704, 0, 'gl_transstat', 1, '1.2.1', 607, 9, 'Translation Status', 'Automatize the creation of page and records translations, keeping track of translation status of them. Very useful for multilanguage websites and tasks related with internationalization and localization', 2, 0, 0, 1213944905, 'a:1:{s:7:"depends";a:2:{s:11:"templavoila";s:0:"";s:15:"gl_be_templates";s:0:"";}}', 'Diego Pino', 'dpino@igalia.com', 'mrego', '17181dcfe3b7b10a37bd98a7934fb8da', 'Added a new configuration variable to select the default original language from which gl_transstat is going to create translated records.', 'Igalia - http://www.igalia.com', 1002001, 0, 0),
