(15771, 0, 'comments', 1, '1.1.0', 5486, 39, 'Commenting system', 'Adds commenting for pages or virtually any record visible in frontend. Public free support is provided only through TYPO3 mailing lists!', 1, 0, 3, 1202206866, 'a:1:{s:9:"conflicts";a:2:{s:11:"nc_commerce";s:0:"";s:11:"nc_comments";s:0:"";}}', 'Dmitry Dulepov [netcreators]', 'dmitry@typo3.org', 'flyguide', '2c602cdd970ad17b256a5b6d70dc37c0', 'New features: [1] ratings (through "ratings" extension) [2] pre-fill form with FE user data [3] show number of comments in tt_news (similar to timtab)', 'Netcreators BV', 1001000, 0, 0),
(15772, 0, 'comments', 1, '1.2.0', 5486, 69, 'Commenting system', 'Adds commenting for pages or virtually any record visible in frontend. Public free support is provided only through TYPO3 mailing lists! Contact by e-mail for commercial support.', 1, 0, 3, 1202310447, 'a:1:{s:9:"conflicts";a:2:{s:11:"nc_commerce";s:0:"";s:11:"nc_comments";s:0:"";}}', 'Dmitry Dulepov [netcreators]', 'dmitry@typo3.org', 'flyguide', '9bb2f5fa02bc890631710b967a147253', 'Better internationalization, automatic links, several bug fixes.', 'Netcreators BV', 1002000, 0, 0),
