(15880, 0, 'voucher', 1, '0.1.0', 134, 0, 'Vouchercode Manager', 'Backend extension to manage voucher codes for FE users. Use this together with tt_products 2.7.5 or later.', 2, 0, 1, 1398326784, 'a:1:{s:7:"depends";a:3:{s:3:"php";s:12:"5.2.0-5.4.99";s:5:"typo3";s:12:"4.5.0-6.2.99";s:7:"div2007";s:7:"0.14.1-";}}', 'Franz Holzinger', 'franz@ttproducts.de', 'franzholz', 'd0a263f3f711eac0b465aa1443017e76', ' \nnew fields usecounter, acquired_days and acquired_groups -\nsupport for agency extension\n', '', 1000, 0, 0),
(15881, 0, 'voucher', 1, '0.2.0', 134, 0, 'Vouchercode Manager', 'Backend extension to manage voucher codes for FE users. Use this together with tt_products 2.7.5 or later.', 2, 0, 1, 1408217277, 'a:1:{s:7:"depends";a:3:{s:3:"php";s:12:"5.2.0-5.4.99";s:5:"typo3";s:12:"4.5.0-6.2.99";s:7:"div2007";s:11:"1.1.6-0.0.0";}}', 'Franz Holzinger', 'franz@ttproducts.de', 'franzholz', 'b6c1b7d2234a6df81877d4780f01474a', ' \nSupport for a FE user dependant starttime and endtime of a FE user group \n Enhanced API and hook  reusable can have 4 different values\n ', '', 2000, 0, 0),
(15882, 0, 'voucher', 1, '0.3.0', 134, 0, 'Vouchercode Manager', 'Backend extension to manage voucher codes for FE users. This works together with tt_products or agency.', 2, 0, 1, 1479385524, 'a:1:{s:7:"depends";a:3:{s:3:"php";s:13:"5.3.0-7.99.99";s:5:"typo3";s:13:"6.2.0-7.99.99";s:7:"div2007";s:12:"1.6.15-0.0.0";}}', 'Franz Holzinger', 'franz@ttproducts.de', 'franzholz', '015eb0f9c7c739cd7df8e285d073107a', '\nNow it runs with TYPO3 7.x. Advanced API to generate voucher codes from FE extensions.\n', '', 3000, 0, 0),
(15883, 0, 'voucher', 1, '0.4.0', 134, 0, 'Vouchercode Manager', 'Backend extension to manage voucher codes for FE users. This works together with tt_products or agency.', 2, 0, 1, 1505723888, 'a:1:{s:7:"depends";a:3:{s:3:"php";s:13:"5.4.0-7.99.99";s:5:"typo3";s:13:"7.6.0-7.99.99";s:7:"div2007";s:12:"1.6.15-0.0.0";}}', 'Franz Holzinger', 'franz@ttproducts.de', 'franzholz', '0238b15925195e34edac9c70efc0399d', ' \nversion for TYPO3 8.x. Attention: The backend module does not work at the moment. You can hide it in the Extension Manager.\n', '', 4000, 1, 0);
INSERT INTO `tx_extensionmanager_domain_model_extension` (`uid`, `pid`, `extension_key`, `repository`, `version`, `alldownloadcounter`, `downloadcounter`, `title`, `description`, `state`, `review_state`, `category`, `last_updated`, `serialized_dependencies`, `author_name`, `author_email`, `ownerusername`, `md5hash`, `update_comment`, `authorcompany`, `integer_version`, `current_version`, `lastreviewedversion`) VALUES
(15884, 0, 'seo_basics', 1, '0.3.0', 7775, 20, 'Basic SEO Features', 'Introduces a separate field for title-tag per page, easy keywords and description editing as well as a clean output in the HTML Header and adds a Google Sitemap.', 1, -1, 0, 1187967022, 'a:1:{s:7:"depends";a:2:{s:3:"cms";s:0:"";s:7:"realurl";s:0:"";}}', 'Benjamin Mack', 'mack@xnos.org', 'benni', 'a675cc695be9aca16dc650fe181aefb7', 'Initial Release, mutliple languages still untested', 'mediales Internetstrategien', 3000, 0, 0),
(15885, 0, 'seo_basics', 1, '0.3.1', 7775, 335, 'Basic SEO Features', 'Introduces a separate field for title-tag per page, easy keywords and description editing as well as a clean output in the HTML Header and adds a Google Sitemap.', 1, -1, 0, 1187991458, 'a:1:{s:7:"depends";a:2:{s:3:"cms";s:0:"";s:7:"realurl";s:0:"";}}', 'Benjamin Mack', 'mack@xnos.org', 'benni', 'e5c9085eb56181158db01873c7e461a4', 'Fixed sitemap bug when starting page is a redirect to a subpage. Subpage also hides "not in menu" fields now. Fixed small bug in submodule when selecting the tree depth.', 'mediales Internetstrategien', 3001, 0, 0),
(15886, 0, 'seo_basics', 1, '0.5.0', 7775, 105, 'Basic SEO Features', 'Introduces a separate field for title-tag per page, easy keywords and description editing as well as a clean output in the HTML Header and adds a Google Sitemap.', 1, -1, 0, 1198545663, 'a:0:{}', 'Benjamin Mack', 'mack@xnos.org', 'benni', '1a8a848c9956d8282e18bd76fa55f9fa', 'Fixed multilanguage problems. Fixed problems with line breaks and indention with source formatter. CoolURI is now supported. Metatags are only added if there is content in it. Possibility to add static parts to the meta tags before and after through TS co', 'mediales Internetstrategien', 5000, 0, 0),
(15887, 0, 'seo_basics', 1, '0.5.1', 7775, 79, 'Basic SEO Features', 'Introduces a separate field for title-tag per page, easy keywords and description editing as well as a clean output in the HTML Header and adds a Google Sitemap.', 1, -1, 0, 1199103100, 'a:0:{}', 'Benjamin Mack', 'mack@xnos.org', 'benni', 'ec134ddaea55707f94001ab89a1aba90', 'Syntax highlighting in BE module is working again. Meta-Tags also work if only constants are defined, also: Constants are noTrimWraps from now on.\n', 'mediales Internetstrategien', 5001, 0, 0),
(15888, 0, 'seo_basics', 1, '0.5.2', 7775, 8, 'Basic SEO Features', 'Introduces a separate field for title-tag per page, easy keywords and description editing as well as a clean output in the HTML Header and adds a Google Sitemap.', 1, -1, 0, 1199896569, 'a:0:{}', 'Benjamin Mack', 'mack@xnos.org', 'benni', '7c0c3de05d0cb4f692e26554ddc64e0a', 'Manual: Added help for coolURI (thanks to Jan Bednarik and CryAngel), BE: When editing pagetype "shortcut", description & keywords are shown too now, BE module: Fixed error when in multilang mode, BE module: Fixed coloring in keywords', 'mediales Internetstrategien', 5002, 0, 0),
(15889, 0, 'seo_basics', 1, '0.5.3', 7775, 225, 'Basic SEO Features', 'Introduces a separate field for title-tag per page, easy keywords and description editing as well as a clean output in the HTML Header and adds a Google Sitemap.', 1, -1, 0, 1199897990, 'a:0:{}', 'Benjamin Mack', 'mack@xnos.org', 'benni', 'a702d036de14c24eabaa18b4a2d8cf23', 'Fixed some errors, updated manual & added TCA array for tx_seo_titletag field in the pages overlay', 'mediales Internetstrategien', 5003, 0, 0),
(15890, 0, 'seo_basics', 1, '0.5.4', 7775, 20, 'Basic SEO Features', 'Introduces a separate field for title-tag per page, easy keywords and description editing as well as a clean output in the HTML Header and adds a Google Sitemap.', 1, -1, 0, 1202913083, 'a:0:{}', 'Benjamin Mack', 'mack@xnos.org', 'benni', 'e9fe4a518d1a9ee73f0c903c375fc554', ' Configuration: Fixed problem showing default titletags for multilanguage sites (thanks Andreas Kostner)\n Sitemap: Added redirect so only main /sitemap.xml URLs are valid now, others are redirected to this one, must be enabled\n Sitemap: Fixed small iss', 'mediales Internetstrategien', 5004, 0, 0),
(15891, 0, 'seo_basics', 1, '0.5.5', 7775, 606, 'Basic SEO Features', 'Introduces a separate field for title-tag per page, easy keywords and description editing as well as a clean output in the HTML Header and adds a Google Sitemap.', 1, -1, 0, 1202926837, 'a:0:{}', 'Benjamin Mack', 'mack@xnos.org', 'benni', '9e2443d953f900947ce806fb1125d935', 'Sitemap: Fixed bug with missing ending brace', 'mediales Internetstrategien', 5005, 0, 0),
(15892, 0, 'seo_basics', 1, '0.5.6', 7775, 487, 'Basic SEO Features', 'Introduces a separate field for title-tag per page, easy keywords and description editing as well as a clean output in the HTML Header and adds a Google Sitemap.', 1, -1, 0, 1214836802, 'a:0:{}', 'Benjamin Mack', 'mack@xnos.org', 'benni', 'e3a0f218877aa85e47f054e60df735fa', 'Sitemap: Fixed problem with absolute external URLs without prefix -- Sitemap: Fixed problem with baseURLs, domain records and absRefPrefix, all possible now -- TCA order: Now compatible with 4.2 -- More to come soon!', 'mediales Internetstrategien', 5006, 0, 0),
(15893, 0, 'seo_basics', 1, '0.6.0', 7775, 1434, 'Basic SEO Features', 'Introduces a separate field for title-tag per page, easy keywords and description editing as well as a Google Sitemap (XML) and a clean output in the HTML Header.', 1, -1, 0, 1221858699, 'a:0:{}', 'Benjamin Mack', 'benni@typo3.org', 'benni', '3db05057aa7484bc850ef51b729a1af4', ' Sitemap: Links are now generated by typolink (better for coolURI)\r\n Sitemap: Only generates non-hidden pages now (taking starttime and endttime into account) Thanks to Morten Kjems\r\n Sitemap: Does not include pages that have the option "no_search" in', '', 6000, 0, 0),
(15894, 0, 'seo_basics', 1, '0.7.0', 7775, 2298, 'Basic SEO Features', 'Introduces a separate field for the title-tag per page, easy and SEO-friendly keywords and description editing in a new module as well as a Google Sitemap (XML) and a clean output in the HTML Source code.', 1, -1, 0, 1263556410, 'a:0:{}', 'Benjamin Mack', 'benni@typo3.org', 'benni', '5725144b61a3d58935b62722daf523d5', 'Breaking change: TypoScript is now in a static_template and needs to be added manually through WebTemplateEdit the whole template record! Also lots of bugfixes, see ChangeLog for more details.', '', 7000, 0, 0),
(15895, 0, 'seo_basics', 1, '0.8.0', 7775, 236, 'Basic SEO Features', 'Introduces a separate field for the title-tag per page, easy and SEO-friendly keywords and description editing in a new module as well as a Google Sitemap (XML) and a clean output in the HTML Source code.', 1, -1, 0, 1310222635, 'a:0:{}', 'Benjamin Mack', 'benni@typo3.org', 'benni', 'd6b83de307131680b24600cf0437f07b', 'Added feature for canonical tag functionality. Minor bugfixes. Also seo_basics is now on forge: http://forge.typo3.org/projects/extension-seo_basics/', '', 8000, 0, 0),
(15896, 0, 'seo_basics', 1, '0.8.1', 7775, 1719, 'Basic SEO Features', 'Introduces a separate field for the title-tag per page, easy and SEO-friendly keywords and description editing in a new module as well as a Google Sitemap (XML) and a clean output in the HTML Source code.', 1, -1, 0, 1311865082, 'a:1:{s:7:"depends";a:1:{s:7:"realurl";s:11:"0.0.0-0.0.0";}}', 'Benjamin Mack', 'benni@typo3.org', 'benni', '73a15fc6a04470a8f1dd79d62f998099', 'Fixed some small, but important issues.', '', 8001, 0, 0),
(15897, 0, 'seo_basics', 1, '0.8.2', 7775, 204, 'Basic SEO Features', 'Introduces a separate field for the title-tag per page, easy and SEO-friendly keywords and description editing in a new module as well as a Google Sitemap (XML) and a clean output in the HTML Source code.', 1, -1, 0, 1332920971, 'a:1:{s:7:"depends";a:1:{s:7:"realurl";s:11:"0.0.0-0.0.0";}}', 'Benjamin Mack', 'benni@typo3.org', 'benni', '74c686bb9926a3e113e298f70b1b5e82', 'Security fix, please update! See TYPO3-EXT-SA-2012-006! /mkr', '', 8002, 0, 0),
(15898, 0, 'seo_basics', 1, '0.8.3', 7775, 0, 'Basic SEO Features', 'Introduces a separate field for the title-tag per page, easy and SEO-friendly keywords and description editing in a new module as well as a Google Sitemap (XML) and a clean output in the HTML Source code.', 1, 0, 0, 1339055731, 'a:1:{s:7:"depends";a:1:{s:7:"realurl";s:11:"0.0.0-0.0.0";}}', 'Benjamin Mack', 'benni@typo3.org', 'benni', '8f4ff84e7223b23664db4a5be1de5f19', 'Security Fix, please update! For details see TYPO3-EXT-SA-2012-007. mbu', '', 8003, 0, 0),
