(15904, 0, 'punycode', 1, '0.1.0', 100, 15, 'Extended domains', 'This extension allows TYPO3 to use letters with umlauts in domain records (implements feature request 689 in TYPO3 core)', 1, 0, 4, 1188226115, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:4:"lang";s:0:"";s:5:"typo3";s:11:"4.1.2-0.0.0";}}', 'Dmitry Dulepov', 'dmitry@typo3.org', 'dmitry', '705c184d193ec1572e29159d945a346a', 'Initial release. There is no manual yet. Just install and it will work transparently. Enter domain names normally and it will be converted on the fly when saving and loading.', 'SIA "ACCIO"', 1000, 0, 0),
(15905, 0, 'punycode', 1, '1.0.0', 100, 85, 'Extended domains', 'This extension allows TYPO3 to use letters with umlauts in domain records (implements feature request 689 in TYPO3 core)', 2, 0, 4, 1188892372, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:4:"lang";s:0:"";s:5:"typo3";s:11:"4.1.2-0.0.0";}}', 'Dmitry Dulepov', 'dmitry@typo3.org', 'dmitry', 'e9150e253f3a5f898ea0491d6e7294af', 'Added manual. Extension will not use XCLASS if runs on TYPO3 4.2.', 'SIA "ACCIO"', 1000000, 1, 0),
