(16100, 0, 'dataquery', 1, '1.2.2', 374, 49, 'SQL-based Data Provider - Tesseract project', 'Assembles a query on data stored in the TYPO3 local database, automatically enforcing criteria like language, publication date, etc. More info on http://www.typo3-tesseract.com/', 2, 0, 4, 1305707628, 'a:1:{s:7:"depends";a:5:{s:9:"tesseract";s:11:"1.0.0-0.0.0";s:10:"datafilter";s:11:"1.0.0-0.0.0";s:8:"overlays";s:11:"2.0.0-0.0.0";s:5:"typo3";s:11:"4.3.0-0.0.0";s:11:"expressions";s:0:"";}}', 'Francois Suter (Cobweb)', 'typo3@cobweb.ch', 'francois', '782910a6fc3c0f6febd1c9c1b2695940', 'Added check to avoid caching in workspaces, solved bug with potentially empty fields during query building.', '', 1002002, 0, 0),
(16101, 0, 'dataquery', 1, '0.1.3', 374, 10, 'Data Query Engine', 'Assemble a query on data stored in the TYPO3 local database, automatically enforcing criteria like languages and versioning. Returns a standardised data set.', 0, 0, 4, 1210237958, 'a:0:{}', 'Francois Suter (Cobweb)', 'support@cobweb.ch', 'francois', 'a87f33558c9873b06f4dbbabcf93b97a', 'Early release for T3DD08. No manual, but a (rough) README file.', '', 1003, 0, 0),
(16102, 0, 'dataquery', 1, '0.1.4', 374, 46, 'Data Query Engine', 'Assemble a query on data stored in the TYPO3 local database, automatically enforcing criteria like languages and versioning. Returns a standardised data set.', 3, 0, 4, 1210238075, 'a:0:{}', 'Francois Suter (Cobweb)', 'support@cobweb.ch', 'francois', '3c84f7d3e0b2379ff577574e22d89782', '(again) Early release for T3DD08. No manual, but a (rough) README file. Set status to experimental.', '', 1004, 0, 0),
(16103, 0, 'dataquery', 1, '1.0.0', 374, 47, 'SQL-based Data Provider - Tesseract project', 'Assembles a query on data stored in the TYPO3 local database, automatically enforcing criteria like language, publication date, etc. More info on http://www.typo3-tesseract.com/', 2, 0, 4, 1285596236, 'a:1:{s:7:"depends";a:5:{s:9:"tesseract";s:11:"1.0.0-0.0.0";s:10:"datafilter";s:11:"1.0.0-0.0.0";s:8:"overlays";s:11:"1.0.0-0.0.0";s:5:"typo3";s:11:"4.3.0-0.0.0";s:11:"expressions";s:0:"";}}', 'Francois Suter (Cobweb)', 'typo3@cobweb.ch', 'francois', '2ec3e06feda1c09d5a079ad0fa132a67', 'New public release as part of the Tesseract project. Not compatible with previous public versions.', '', 1000000, 0, 0),
(16104, 0, 'dataquery', 1, '1.1.0', 374, 48, 'SQL-based Data Provider - Tesseract project', 'Assembles a query on data stored in the TYPO3 local database, automatically enforcing criteria like language, publication date, etc. More info on http://www.typo3-tesseract.com/', 2, 0, 4, 1293550943, 'a:1:{s:7:"depends";a:5:{s:9:"tesseract";s:11:"1.0.0-0.0.0";s:10:"datafilter";s:11:"1.0.0-0.0.0";s:8:"overlays";s:11:"1.0.0-0.0.0";s:5:"typo3";s:11:"4.3.0-0.0.0";s:11:"expressions";s:0:"";}}', 'Francois Suter (Cobweb)', 'typo3@cobweb.ch', 'francois', 'f8855bd5eafc0eb1a7f74a5824cd701b', 'Corrected handling of array-type values coming from filters; added new hook; added helper mechanism for matching aliases; additional bug fixes, see ChangeLog.', '', 1001000, 0, 0),
(16105, 0, 'dataquery', 1, '1.2.0', 374, 14, 'SQL-based Data Provider - Tesseract project', 'Assembles a query on data stored in the TYPO3 local database, automatically enforcing criteria like language, publication date, etc. More info on http://www.typo3-tesseract.com/', 2, 0, 4, 1300811255, 'a:1:{s:7:"depends";a:5:{s:9:"tesseract";s:11:"1.0.0-0.0.0";s:10:"datafilter";s:11:"1.0.0-0.0.0";s:8:"overlays";s:11:"2.0.0-0.0.0";s:5:"typo3";s:11:"4.3.0-0.0.0";s:11:"expressions";s:0:"";}}', 'Francois Suter (Cobweb)', 'typo3@cobweb.ch', 'francois', '4f66c19e189602494ed9cf619cff1615', 'Added support for workspace preview, improved unit testing, corrected a few bugs (seen ChangeLog)', '', 1002000, 0, 0),
(16106, 0, 'dataquery', 1, '1.2.1', 374, 39, 'SQL-based Data Provider - Tesseract project', 'Assembles a query on data stored in the TYPO3 local database, automatically enforcing criteria like language, publication date, etc. More info on http://www.typo3-tesseract.com/', 2, 0, 4, 1300871423, 'a:1:{s:7:"depends";a:5:{s:9:"tesseract";s:11:"1.0.0-0.0.0";s:10:"datafilter";s:11:"1.0.0-0.0.0";s:8:"overlays";s:11:"2.0.0-0.0.0";s:5:"typo3";s:11:"4.3.0-0.0.0";s:11:"expressions";s:0:"";}}', 'Francois Suter (Cobweb)', 'typo3@cobweb.ch', 'francois', '9ec61a83b35d2cf247d741b2799c7bf0', 'Bug fix: enable fields conditions were not applied to correct table when using table aliases in joins.', '', 1002001, 0, 0),
(16107, 0, 'dataquery', 1, '1.3.0', 374, 31, 'SQL-based Data Provider - Tesseract project', 'Assembles a query on data stored in the TYPO3 local database, automatically enforcing criteria like language, publication date, etc. More info on http://www.typo3-tesseract.com/', 2, 0, 4, 1313477787, 'a:1:{s:7:"depends";a:5:{s:9:"tesseract";s:11:"1.0.0-0.0.0";s:10:"datafilter";s:11:"1.0.0-0.0.0";s:8:"overlays";s:11:"2.0.0-0.0.0";s:5:"typo3";s:11:"4.3.0-0.0.0";s:11:"expressions";s:0:"";}}', 'Francois Suter (Cobweb)', 'typo3@cobweb.ch', 'francois', 'c0ff1d03c01d6c7c0d37e8dfbdc4b216', 'Added support for void filters, added many new unit tests.', '', 1003000, 0, 0),
(16108, 0, 'dataquery', 1, '1.4.0', 374, 54, 'SQL-based Data Provider - Tesseract project', 'Assembles a query on data stored in the TYPO3 local database, automatically enforcing criteria like language, publication date, etc. More info on http://www.typo3-tesseract.com/', 2, 0, 4, 1316587338, 'a:1:{s:7:"depends";a:5:{s:9:"tesseract";s:11:"1.0.0-0.0.0";s:10:"datafilter";s:11:"1.2.0-0.0.0";s:8:"overlays";s:11:"2.0.0-0.0.0";s:5:"typo3";s:11:"4.3.0-0.0.0";s:11:"expressions";s:0:"";}}', 'Francois Suter (Cobweb)', 'typo3@cobweb.ch', 'francois', '5c90509713b324a761936c0aa6b96d20', 'Corrected several bugs, in particular one about language overlays on joined tables (important). Added possibility to selectively exclude tables from language overlays.', '', 1004000, 0, 0),
(16109, 0, 'dataquery', 1, '1.5.0', 374, 36, 'SQL-based Data Provider - Tesseract project', 'Assembles a query on data stored in the TYPO3 local database, automatically enforcing criteria like language, publication date, etc. More info on http://www.typo3-tesseract.com/', 2, 0, 4, 1328515645, 'a:1:{s:7:"depends";a:5:{s:9:"tesseract";s:11:"1.0.0-0.0.0";s:10:"datafilter";s:11:"1.2.0-0.0.0";s:8:"overlays";s:11:"2.0.0-0.0.0";s:5:"typo3";s:12:"4.3.0-4.6.99";s:11:"expressions";s:0:"";}}', 'Francois Suter (Cobweb)', 'typo3@cobweb.ch', 'francois', '88175c52084fc99114fa9c0ea3b82190', 'Can now also return id-list-type structures; much internal refactoring; added support for negated conditions; fixed a bug with caching.', '', 1005000, 0, 0),
(16110, 0, 'dataquery', 1, '1.6.0', 374, 0, 'SQL-based Data Provider - Tess', 'Assembles a query on data stored in the TYPO3 local database, automatically enforcing criteria like language, publication date, etc. More info on http://www.typo3-tesseract.com/', 2, 0, 4, 1334840012, 'a:1:{s:7:"depends";a:5:{s:9:"tesseract";s:11:"1.4.0-0.0.0";s:10:"datafilter";s:11:"1.2.0-0.0.0";s:8:"overlays";s:11:"2.0.0-0.0.0";s:5:"typo3";s:12:"4.3.0-4.6.99";s:11:"expressions";s:0:"";}}', 'Francois Suter (Cobweb)', 'typo3@cobweb.ch', 'francois', '125097a1423d312ccd7942b82cb4b86b', 'Added support for random ordering; cleaned up creation of empty data structures; fixed a couple more bugs.', '', 1006000, 0, 0);
