(16130, 0, 'nano_jquery', 1, '0.0.1', 178, 17, 'Nano jQuery', 'jQuery is a new type of JavaScript library. This extension provides an easy to use configuration and includes all versions of jQuery. Until the latest version 1.2.1 in now 3 variants: uncompressed version (78.6 KB), minified version (45.3 KB) and the pack', 1, 0, 2, 1191016793, 'a:0:{}', 'Bjoern Ellebrecht', 'bjoern_ellebrecht@be-it-solutions.com', 'bjoern_ellebrecht', '7831140469dcb9d542dc89a21e03f7ed', 'Initial release with jQuery version 1.2.1. jQuery library is included from version 1.1.2 to 1.2.1, in uncompressed and packed version. Since jQuery version 1.2 there is a third variant (minified) available and also included. In next releases there will be', '', 1, 0, 0),
(16131, 0, 'nano_jquery', 1, '0.0.2', 178, 19, 'Nano jQuery', 'jQuery is a new type of JavaScript library. This extension includes many versions of jQuery. Of course the latest version 1.2.1 in 3 variants: uncompressed (78.6 KB), minified (45.3 KB) and packed (26.5 KB). [Important Notice: PHP 5 ONLY]', 1, 0, 2, 1191239216, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"5.1.2-0.0.0";s:5:"typo3";s:11:"4.1.0-0.0.0";}}', 'Bjoern Ellebrecht', 'bjoern_ellebrecht@be-it-solutions.com', 'bjoern_ellebrecht', 'bc32918b52e4a8589b3d9544c3cf19c1', 'Updated release, better documentation ( small API) and first 2 jQuery plugins are available: Thickbox v3.1 and pstrength v1.2 (Password Strength Field).', 'BE IT Solutions', 2, 0, 0),
(16132, 0, 'nano_jquery', 1, '0.0.3', 178, 35, 'Nano jQuery', 'jQuery is a new type of JavaScript library. This extension includes many versions of jQuery. Of course the latest version 1.2.1 in 3 variants: uncompressed (78.6 KB), minified (45.3 KB) and packed (26.5 KB). [Important Notice: PHP 5 ONLY]', 1, 0, 2, 1191524112, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"5.1.2-0.0.0";s:5:"typo3";s:11:"4.1.0-0.0.0";}}', 'Bjoern Ellebrecht', 'bjoern_ellebrecht@be-it-solutions.com', 'bjoern_ellebrecht', '701d46654e1bdd80b4ee1ecd0ab5cb2f', 'Minor update release, added missing features to Thickbox configuration. Little more documentation.', 'BE IT Solutions', 3, 0, 0),
