(16227, 0, 'vcommune', 1, '0.0.1', 203, 49, 'Video Commune', 'Video Commune extension tries to give some video community functionalities. Video Commune doesnt store video files, the idea is to use on-line videos links of the main famous providers youtube, google videos, metacafe,.. This could be good solution to sma', 0, 0, 3, 1196156474, 'a:1:{s:7:"depends";a:2:{s:5:"extjs";s:0:"";s:3:"lib";s:0:"";}}', 'Juan Lucas Madurga Martin-Serrano', 'jlmadurga@gmail.com', 'jlmadurga', 'c19eb6e81672f738db329808c9575766', '-Remote video search plugin (google videos):save,source,play buttons\r\n -Local video search plugin: filter by title or description\r\n', '', 1, 0, 0),
(16228, 0, 'vcommune', 1, '0.0.2', 203, 31, 'Video Commune', 'Video Commune doesnt store video files, the idea is to share on-line videos links of the main famous providers youtube,,.. .The extension is being developed with the MVC framework,lib 0.0.24 and extjs 1.1.1. PHP5 is required. Developed in typo3 4.1.2', 0, 0, 3, 1199106820, 'a:1:{s:7:"depends";a:2:{s:5:"extjs";s:3:"1.1";s:3:"lib";s:6:"0.0.24";}}', 'Juan Lucas Madurga Martin-Serrano', 'jlmadurga@gmail.com', 'jlmadurga', '6567f708f704fc46672a71e60d7f9e76', '- Video Stats plugin added.\r\n- Inappropriate video polls feature added.\r\n- Only works with users and groups!!!\r\n', '', 2, 0, 0),
(16229, 0, 'vcommune', 1, '0.0.3', 203, 123, 'Video Commune', 'Video Commune doesnt store video files, the idea is to share on-line videos links of the main famous providers youtube,,.. .The extension is being developed with the MVC framework,lib 0.0.24 and extjs 1.1.1. PHP5 is required. Developed in typo3 4.1.2', 0, 0, 3, 1201723773, 'a:1:{s:7:"depends";a:2:{s:5:"extjs";s:3:"1.1";s:3:"lib";s:6:"0.0.24";}}', 'Juan Lucas Madurga Martin-Serrano', 'jlmadurga@gmail.com', 'jlmadurga', 'f4db2be890a3d109766fb24f30099b3f', '- Fixed some bugs with non google or youtube videos', '', 3, 1, 0),
