(16376, 0, 'xw_ttnewsarchiver', 1, '0.1.1', 97, 48, 'Special tt_news Archiver', 'You can specify a number of news that wont be putted in the archive. These ones can be shown separately in another site. The archive field will not be touched, but if you want to use it could become confusing.', 1, 0, 3, 1192711143, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:12:"4.2.2-5.2.99";s:5:"typo3";s:12:"3.8.0-4.1.99";}}', 'Christian Juerges', 'christian.juerges@xwave.ch', 'chrisju', '31750bb06d643f3e5a2d1811dd94c0de', 'no special changes', 'Xwave GmbH', 1001, 0, 0),
