(16430, 0, 'cfa_mooflow', 1, '0.3.8', 1965, 8, 'MooFlow V0.2 integration', 'A Gallery Plugin integrate the MooFlow V0.2 project from Tobias Wetzel (www.outcut.de) CoverFlow / ImageFlow effect. Support Dam / Dam Category as image source. Support dynamic loading (Ajax) from Dam Cat. Demo: www.fassing.eu/demo/mooflow.html', 1, 0, 3, 1268566604, 'a:1:{s:7:"depends";a:3:{s:3:"php";s:11:"5.0.0-0.0.0";s:5:"typo3";s:11:"4.1.0-0.0.0";s:3:"cms";s:0:"";}}', 'Claus Fassing', 'claus@fassing.eu', 'fazzyx', 'd0f51e6e1bee494bd8a2a5b79e45ef8e', 'In use of dam can be used now html special chars in the title and description field. 0.4.0 testing released. www.fassing.eu/demo/mooflow-dev.html', '', 3008, 0, 0),
(16431, 0, 'cfa_mooflow', 1, '0.1.0', 1965, 26, 'MooFlow V0.2 integration', 'This Plugin integrate the MooFlow V0.2 project from Tobias Wetzel (http://www.outcut.de) which simulate a Mac like Cover Flow / Image Flow effect. The Plugin is full configurable by flexform. Demo: http://www.fassing.eu/demo/mooflow.html.', 1, 0, 3, 1217674871, 'a:0:{}', 'Claus Fassing', 'claus@fassing.eu', 'fazzyx', '11729d3dcb83f2d01e53bbdaf3d8cc6f', 'update manual.\r\nAlternative manual download : http://www.fassing.eu/demo/mooflow.html', '', 1000, 0, 0),
(16432, 0, 'cfa_mooflow', 1, '0.1.1', 1965, 72, 'MooFlow V0.2 integration', 'This Plugin integrate the MooFlow V0.2 project from Tobias Wetzel (http://www.outcut.de) which simulate a Mac like Cover Flow / Image Flow effect. The Plugin is full configurable by flexform. Demo: http://www.fassing.eu/demo/mooflow.html.', 1, 0, 3, 1217756950, 'a:0:{}', 'Claus Fassing', 'claus@fassing.eu', 'fazzyx', '13a97a04870c7c2e62a937ebd252a6a4', 'non critical bugfix\r\nupdate manual. \r\nAlternative manual download : http://www.fassing.eu/demo/mooflow.html', '', 1001, 0, 0),
(16433, 0, 'cfa_mooflow', 1, '0.2.0', 1965, 14, 'MooFlow V0.2 integration', 'This Plugin integrate the MooFlow V0.2 project from Tobias Wetzel (http://www.outcut.de) which simulate a Mac like Cover Flow / Image Flow effect. Support Dam and Dam Cat also. Demo: http://www.fassing.eu/demo/mooflow.html.', 1, 0, 3, 1221207549, 'a:0:{}', 'Claus Fassing', 'claus@fassing.eu', 'fazzyx', '195914b5def3b49187d8af69f937de14', 'New features available !\r\nAdd Dam, Dam Cat and Directory support as image selection mode.\r\nMake configuration of single selection mode much easier.', '', 2000, 0, 0),
(16434, 0, 'cfa_mooflow', 1, '0.2.1', 1965, 52, 'MooFlow V0.2 integration', 'This Plugin integrate the MooFlow V0.2 project from Tobias Wetzel (http://www.outcut.de) which simulate a Mac like Cover Flow / Image Flow effect. Support Dam and Dam Cat also. Demo: http://www.fassing.eu/demo/mooflow.html.', 1, 0, 3, 1221230259, 'a:0:{}', 'Claus Fassing', 'claus@fassing.eu', 'fazzyx', '03e0bf07dd7b18f4ae55ae47812b2408', 'Bugfix. v.0.2.0 does not work at all.\r\nCSS Update with better IE support.', '', 2001, 0, 0),
(16435, 0, 'cfa_mooflow', 1, '0.2.2', 1965, 38, 'MooFlow V0.2 integration', 'This Plugin integrate the MooFlow V0.2 project from Tobias Wetzel (http://www.outcut.de) which simulate a Mac like Cover Flow / Image Flow effect, also known as carousel effect. Support Dam / Dam Category. Demo: http://www.fassing.eu/demo/mooflow.html.', 1, 0, 3, 1221673565, 'a:0:{}', 'Claus Fassing', 'claus@fassing.eu', 'fazzyx', 'b859cbbf738f4d5cc0f594af271b9db8', 'Add option to switch between single or double click to fire event (enlarge or linking)\r\nUpdate configuration to let set a hyperlink in title / description field\r\n', '', 2002, 0, 0),
(16436, 0, 'cfa_mooflow', 1, '0.2.3', 1965, 25, 'MooFlow V0.2 integration', 'A Gallery Plugin integrate the MooFlow V0.2 project from Tobias Wetzel (http://www.outcut.de) which simulate a Mac like Cover Flow / Image Flow effect. Support Dam / Dam Category as image source. Demo: http://www.fassing.eu/demo/mooflow.html.', 1, 0, 3, 1221848949, 'a:1:{s:7:"depends";a:3:{s:3:"php";s:11:"5.0.0-0.0.0";s:5:"typo3";s:11:"4.1.0-0.0.0";s:3:"cms";s:0:"";}}', 'Claus Fassing', 'claus@fassing.eu', 'fazzyx', '50aa78d148da7cb8591116d44a4ee8f7', 'Bugfix 1560\r\nFix conflict with bgcolor setting to transparent related to Firefox 2', '', 2003, 0, 0),
