(16443, 0, 'cfa_mooflow', 1, '0.3.5', 1965, 212, 'MooFlow V0.2 integration', 'A Gallery Plugin integrate the MooFlow V0.2 project from Tobias Wetzel (www.outcut.de) CoverFlow / ImageFlow effect. Support Dam / Dam Category as image source. Support dynamic loading (Ajax) from Dam Cat. Demo: www.fassing.eu/demo/mooflow.html', 1, 0, 3, 1252841699, 'a:1:{s:7:"depends";a:3:{s:3:"php";s:11:"5.0.0-0.0.0";s:5:"typo3";s:11:"4.1.0-0.0.0";s:3:"cms";s:0:"";}}', 'Claus Fassing', 'claus@fassing.eu', 'fazzyx', 'dad9be2da670f224e77a521df544f3fe', 'Add current mootools release (1.2.3). This will fix the IE8 reflection issue.\r\nFix separate use of slider and resize.', '', 3005, 0, 0);
