(16454, 0, 'ste_invoice', 1, '0.7.0', 427, 24, 'Invoice', 'Creating and managing invoices with Typo3', 0, 0, 4, 1193704469, 'a:0:{}', 'Sacha Ligthert', 'sacha@ligthert.net', 'ligthert', '0d145586e9fa7fdc814d6d4f00bad746', '7-10-29 Sacha Ligthert  sacha@ligthert.net\n\n         Initial release\n         Added documentation\n\n07-07-04 Sacha Ligthert  sacha@ligthert.net\n\n         Startup development\n', '', 7000, 0, 0),
(16455, 0, 'ste_invoice', 1, '0.7.1', 427, 39, 'Invoice', 'Creating and managing invoices with Typo3', 0, 0, 4, 1193749442, 'a:0:{}', 'Sacha Ligthert', 'sacha@ligthert.net', 'ligthert', '3a5a138aedc5b2797bf916166b732e6a', '07-10-30 Sacha Ligthert  sacha@ligthert.net\n\n         Placed manual.sxw in doc/\n', '', 7001, 0, 0),
(16456, 0, 'ste_invoice', 1, '0.7.4', 427, 48, 'Invoice', 'Creating and managing invoices with Typo3', 0, 0, 4, 1194619546, 'a:0:{}', 'Sacha Ligthert', 'sacha@ligthert.net', 'ligthert', 'fdcc243d61161b57ec27d2e379becbf6', '07-11-09 Sacha Ligthert  sacha@ligthert\n\n         Manual.sxw should now show pictures on typo3.org\n         An empty record in tx_steinvoice_conf should now be made. If this is not the case do so manually. Configuration cant be s\ntored then.\n', '', 7004, 0, 0),
(16457, 0, 'ste_invoice', 1, '0.7.5', 427, 28, 'Invoice', 'Creating and managing invoices with Typo3', 0, 0, 4, 1195496799, 'a:0:{}', 'Sacha Ligthert', 'sacha@ligthert.net', 'ligthert', '4cacf73d01401d9f8cf1000f49b50d57', '07-11-19 Sacha Ligthert sacha@ligthert.net\n         Update the manual.sxw\n         Renamed annual to yearly (system wide)\n         Added the bi-monthly frequency.\n         Added discount to services\n         Added subliminal messages\n', '', 7005, 0, 0),
(16458, 0, 'ste_invoice', 1, '0.7.6', 427, 25, 'Invoice', 'Creating and managing invoices with Typo3', 0, 0, 4, 1195742724, 'a:0:{}', 'Sacha Ligthert', 'sacha@ligthert.net', 'ligthert', '62b77180481e09f55ca32a0ebc1fcb07', '07-11-22 Sacha Ligthert sacha@ligthert.net\n         Discount now actually works.\n         Modified the documentation a bit.', '', 7006, 0, 0),
(16459, 0, 'ste_invoice', 1, '0.7.7', 427, 30, 'Invoice', 'Creating and managing invoices with Typo3', 0, 0, 4, 1195829168, 'a:0:{}', 'Sacha Ligthert', 'sacha@ligthert.net', 'ligthert', 'a333c61afa5d2feccacf7840a98418bc', '07-11-23 Sacha Ligthert sacha@ligthert.net\n         Invoices without a PDF now offer an option to compile a PDF.\n         Invoices are now ordered on time.\n', '', 7007, 0, 0),
(16460, 0, 'ste_invoice', 1, '0.7.8', 427, 31, 'Invoice', 'Creating and managing invoices with Typo3', 0, 0, 4, 1197324526, 'a:0:{}', 'Sacha Ligthert', 'sacha@ligthert.net', 'ligthert', '2784cd946c084a1cb5d6df3f9f832289', '07-12-10 Sacha Ligthert sacha@ligthert.net\n         One-time services are now compiled into an invoice.\n         Fixed a HUGE bug that prevented the creation of PDF files.', '', 7008, 0, 0),
(16461, 0, 'ste_invoice', 1, '0.7.9', 427, 35, 'Invoice', 'Creating and managing invoices with Typo3', 0, 0, 4, 1199741087, 'a:0:{}', 'Sacha Ligthert', 'sacha@ligthert.net', 'ligthert', 'cfb3005ad56f88cc343e678a5dd3d782', '08-01-06 Sacha Ligthert sacha@ligthert.net\n         Added tons of updates I forgot.\n         Attach_mail class is replaced by Typo3 native htmlmail (directmail uses this lib).\n         Added a preview option.\n         Templates for the mails and the', '', 7009, 0, 0),
(16462, 0, 'ste_invoice', 1, '0.7.10', 427, 41, 'Invoice', 'Creating and managing invoices with Typo3', 0, 0, 4, 1199886240, 'a:0:{}', 'Sacha Ligthert', 'sacha@ligthert.net', 'ligthert', '895460dbe6b962e87c0e3639550599d8', '08-01-09 Sacha Ligthert sacha@ligthert.net\n         Fixed a the bug that caused incorrect handeling of the invoice template.', '', 7010, 0, 0),
