(16568, 0, 'ig_ldap_sso_auth', 1, '1.2.0', 863, 0, 'LDAP / SSO Authentication', 'Authenticate frontend and/or backend users using LDAP or Central Authentication Service (CAS). Provide SSO authentication service. Support for OpenLDAP, Active Directory and Novell eDirectory. Handle TLS and SSL (ldaps://).', 2, 0, 5, 1400488202, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"4.5.0-6.2.99";s:3:"php";s:12:"5.2.0-5.5.99";}}', 'Xavier Perseguers, Team Infoglobe', 'xavier@typo3.org', 'xperseguers', 'e75add61e566c8c7c915ecb1ca8b479a', 'Compatibility with TYPO3 4.5-6.2.\nProper support for SSL- and TLS-based LDAP connection.\nExtended mapping of LDAP attributes.\nDetails on http://forge.typo3.org/projects/extension-ig_ldap_sso_auth/wiki/IG_LDAP_SSO_AUTH_120', '', 1002000, 0, 0),
(16569, 0, 'ig_ldap_sso_auth', 1, '1.2.1', 863, 0, 'LDAP / SSO Authentication', 'Authenticate frontend and/or backend users using LDAP or Central Authentication Service (CAS). Provide SSO authentication service. Support for OpenLDAP, Active Directory and Novell eDirectory. Handle TLS and SSL (ldaps://).', 2, 0, 5, 1403595021, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"4.5.0-6.2.99";s:3:"php";s:12:"5.2.0-5.5.99";}}', 'Xavier Perseguers, Team Infoglobe', 'xavier@typo3.org', 'xperseguers', '16e2b91c1cdf1af9fcb658a41a6659a4', 'Regular bugfix release.\nDetails on http://forge.typo3.org/projects/extension-ig_ldap_sso_auth/wiki/IG_LDAP_SSO_AUTH_121', '', 1002001, 0, 0),
(16570, 0, 'ig_ldap_sso_auth', 1, '1.3.0', 863, 0, 'LDAP / SSO Authentication', 'Authenticate frontend and/or backend users using LDAP or Central Authentication Service (CAS). Provide SSO authentication service. Support for OpenLDAP, Active Directory and Novell eDirectory. Handle TLS and SSL (ldaps://).', 2, 0, 5, 1409004551, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"4.5.0-6.2.99";s:3:"php";s:12:"5.2.0-5.5.99";}}', 'Xavier Perseguers, Team Infoglobe', 'xavier@typo3.org', 'xperseguers', '787feababc11a45a5d0751eafa0ca0ca', 'Many UX enhancements and better handling of group membership.\nPlease migrate your configuration using the Update! tool in Extension Manager.\nDetails on http://forge.typo3.org/projects/extension-ig_ldap_sso_auth/wiki/IG_LDAP_SSO_AUTH_130', '', 1003000, 0, 0),
(16571, 0, 'ig_ldap_sso_auth', 1, '2.0.0', 863, 0, 'LDAP / SSO Authentication', 'This extension provides LDAP support for TYPO3 by delegating the authentication of frontend and/or backend users to the centrally-managed directory of your organization. It fully supports OpenLDAP, Active Directory and Novell eDirectory and is capable of connecting securely to the authentication server using either TLS or SSL (ldaps://).\nIn case of use in an intranet environment, this extension is a perfect match since it natively brings Single Sign-On (SSO) capability to TYPO3 without any complex configuration.', 2, -1, 5, 1415205828, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"4.5.0-6.2.99";s:3:"php";s:12:"5.3.3-5.6.99";}}', 'Xavier Perseguers, Team Infoglobe', 'xavier@typo3.org', 'xperseguers', '2803c8580d80d18d1683c991ba45e807', 'Full RSA-encrypted password support. SSO with Apache. Module to manually import users.\n[BREAKING CHANGES] PHP 5.2 and CAS are not supported anymore.\nDetails on http://forge.typo3.org/projects/extension-ig_ldap_sso_auth/wiki/IG_LDAP_SSO_AUTH_200', '', 2000000, 0, 0),
(16572, 0, 'ig_ldap_sso_auth', 1, '2.0.1', 863, 0, 'LDAP / SSO Authentication', 'This extension provides LDAP support for TYPO3 by delegating the authentication of frontend and/or backend users to the centrally-managed directory of your organization. It fully supports OpenLDAP, Active Directory and Novell eDirectory and is capable of connecting securely to the authentication server using either TLS or SSL (ldaps://).\nIn case of use in an intranet environment, this extension is a perfect match since it natively brings Single Sign-On (SSO) capability to TYPO3 without any complex configuration.', 2, 0, 5, 1418988148, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"4.5.0-6.2.99";s:3:"php";s:12:"5.3.3-5.6.99";}}', 'Xavier Perseguers, Team Infoglobe', 'xavier@typo3.org', 'xperseguers', '682551f52cff09c0b8dabab3821b1dac', 'Security Fix, PLEASE UPDATE.\n[BREAKING CHANGES] PHP 5.2 and CAS are not supported anymore.\nDetails on http://forge.typo3.org/projects/extension-ig_ldap_sso_auth/wiki/IG_LDAP_SSO_AUTH_201', '', 2000001, 0, 0),
(16573, 0, 'ig_ldap_sso_auth', 1, '2.1.0', 863, 0, 'LDAP / SSO Authentication', 'This extension provides LDAP support for TYPO3 by delegating the authentication of frontend and/or backend users to the centrally-managed directory of your organization. It fully supports OpenLDAP, Active Directory and Novell eDirectory and is capable of connecting securely to the authentication server using either TLS or SSL (ldaps://).\nIn case of use in an intranet environment, this extension is a perfect match since it natively brings Single Sign-On (SSO) capability to TYPO3 without any complex configuration.', 2, 0, 5, 1424422019, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"4.5.0-6.2.99";s:3:"php";s:12:"5.3.3-5.6.99";}}', 'Xavier Perseguers, Team Infoglobe', 'xavier@typo3.org', 'xperseguers', '465e04acd65791553bab96bfb6687b35', 'Support for mapping user groups from different LDAP server and various bug fixes.\nDetails on http://forge.typo3.org/projects/extension-ig_ldap_sso_auth/wiki/IG_LDAP_SSO_AUTH_210', '', 2001000, 0, 0),
(16574, 0, 'ig_ldap_sso_auth', 1, '2.1.1', 863, 0, 'LDAP / SSO Authentication', 'This extension provides LDAP support for TYPO3 by delegating the authentication of frontend and/or backend users to the centrally-managed directory of your organization. It fully supports OpenLDAP, Active Directory and Novell eDirectory and is capable of connecting securely to the authentication server using either TLS or SSL (ldaps://).\nIn case of use in an intranet environment, this extension is a perfect match since it natively brings Single Sign-On (SSO) capability to TYPO3 without any complex configuration.', 2, 0, 5, 1424443053, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"4.5.0-6.2.99";s:3:"php";s:12:"5.3.3-5.6.99";}}', 'Xavier Perseguers, Team Infoglobe', 'xavier@typo3.org', 'xperseguers', '07d1c973bd914da044af50f1b9f379f6', 'Username cannot be extracted from complex filter.\nDetails on http://forge.typo3.org/projects/extension-ig_ldap_sso_auth/wiki/IG_LDAP_SSO_AUTH_211', '', 2001001, 0, 0),
(16575, 0, 'ig_ldap_sso_auth', 1, '2.1.2', 863, 0, 'LDAP / SSO Authentication', 'This extension provides LDAP support for TYPO3 by delegating the authentication of frontend and/or backend users to the centrally-managed directory of your organization. It fully supports OpenLDAP, Active Directory and Novell eDirectory and is capable of connecting securely to the authentication server using either TLS or SSL (ldaps://).\nIn case of use in an intranet environment, this extension is a perfect match since it natively brings Single Sign-On (SSO) capability to TYPO3 without any complex configuration.', 2, 0, 5, 1427750168, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"4.5.0-6.2.99";s:3:"php";s:12:"5.3.3-5.6.99";}}', 'Xavier Perseguers, Team Infoglobe', 'xavier@typo3.org', 'xperseguers', '3a2c9cd202662088de090f77dcb6cbf9', 'Fix empty record rows in user import module and inability to authenticate for some new users.\nDetails on http://forge.typo3.org/projects/extension-ig_ldap_sso_auth/wiki/IG_LDAP_SSO_AUTH_212', '', 2001002, 0, 0),
(16576, 0, 'ig_ldap_sso_auth', 1, '3.0.0', 863, 0, 'LDAP / SSO Authentication', 'This extension provides LDAP support for TYPO3 by delegating the authentication of frontend and/or backend users to the centrally-managed directory of your organization. It fully supports OpenLDAP, Active Directory and Novell eDirectory and is capable of connecting securely to the authentication server using either TLS or SSL (ldaps://).\nIn case of use in an intranet environment, this extension is a perfect match since it natively brings Single Sign-On (SSO) capability to TYPO3 without any complex configuration.', 2, 0, 5, 1432578413, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:13:"6.2.0-7.99.99";s:3:"php";s:12:"5.3.3-5.6.99";}}', 'Xavier Perseguers', 'xavier@causal.ch', 'xperseguers', '00e78f2068ffc3c4f79f9746ebddf6e7', 'Compatibility with TYPO3 6.2 - 7.x and TypoScript stdWrap support for mapping. Please use Update! tool in Extension Manager.\nBreaking changes described on http://forge.typo3.org/projects/extension-ig_ldap_sso_auth/wiki/IG_LDAP_SSO_AUTH_300', '', 3000000, 0, 0),
