(16581, 0, 'ig_ldap_sso_auth', 1, '3.2.0', 863, 0, 'LDAP / SSO Authentication', 'This extension provides LDAP support for TYPO3 by delegating the authentication of frontend and/or backend users to the centrally-managed directory of your organization. It fully supports OpenLDAP and Active Directory and is capable of connecting securely to the authentication server using either TLS or SSL (ldaps://).\nIn case of use in an intranet environment, this extension is a perfect match since it natively brings Single Sign-On (SSO) capability to TYPO3 without any complex configuration.', 2, 0, 5, 1484642656, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:12:"5.5.0-7.1.99";s:5:"typo3";s:13:"6.2.0-8.99.99";}}', 'Xavier Perseguers', 'xavier@causal.ch', 'xperseguers', '8ddbe21e3d254d7bbdb5c31cf6a3551a', 'Support for LDAP pages and SSO in Backend.\r\nSupport for TYPO3 v8.\r\nRequires PHP  5.5 and does not support LDAP protocol v2 anymore.\r\nDetails on https://forge.typo3.org/projects/extension-ig_ldap_sso_auth/wiki/IG_LDAP_SSO_AUTH_320', '', 3002000, 0, 0),
(16582, 0, 'ig_ldap_sso_auth', 1, '3.2.1', 863, 0, 'LDAP / SSO Authentication', 'This extension provides LDAP support for TYPO3 by delegating the authentication of frontend and/or backend users to the centrally-managed directory of your organization. It fully supports OpenLDAP and Active Directory and is capable of connecting securely to the authentication server using either TLS or SSL (ldaps://).\nIn case of use in an intranet environment, this extension is a perfect match since it natively brings Single Sign-On (SSO) capability to TYPO3 without any complex configuration.', 2, 0, 5, 1494169238, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:12:"5.5.0-7.1.99";s:5:"typo3";s:12:"6.2.0-8.7.99";}}', 'Xavier Perseguers', 'xavier@causal.ch', 'xperseguers', '22e76c4438f889fa325828d6b7da1a0e', 'Last version compatible with TYPO3 6.2.\r\nVarious bug fixes for TYPO3 8 LTS.\r\nDetails on https://forge.typo3.org/projects/extension-ig_ldap_sso_auth/wiki/IG_LDAP_SSO_AUTH_321', '', 3002001, 0, 0),
(16583, 0, 'ig_ldap_sso_auth', 1, '3.2.2', 863, 0, 'LDAP / SSO Authentication', 'This extension provides LDAP support for TYPO3 by delegating the authentication of frontend and/or backend users to the centrally-managed directory of your organization. It fully supports OpenLDAP and Active Directory and is capable of connecting securely to the authentication server using either TLS or SSL (ldaps://).\nIn case of use in an intranet environment, this extension is a perfect match since it natively brings Single Sign-On (SSO) capability to TYPO3 without any complex configuration.', 2, 0, 5, 1495790356, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:12:"5.5.0-7.1.99";s:5:"typo3";s:12:"6.2.0-8.7.99";}}', 'Xavier Perseguers', 'xavier@causal.ch', 'xperseguers', '6d9f63c8d08d30b91fb1d5f49a3f8cce', 'Last version compatible with TYPO3 6.2.\r\nVarious bug fixes for TYPO3 8 LTS.\r\nDetails on https://forge.typo3.org/projects/extension-ig_ldap_sso_auth/wiki/IG_LDAP_SSO_AUTH_322', '', 3002002, 1, 0),
