(16606, 0, 'dix_easylogin', 1, '0.4.4', 141, 0, 'Easy Login and Register with OpenID (FE)', 'Do you know facebook connect? Easylogin is even better because it works not only with facebook but also with Google, Yahoo, myOpenId, twitter, and all other providers that offer OpenID or OAuth. It also integrates the common felogin (Username/Password)', 1, 0, 2, 1441455629, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:12:"6.2.0-6.2.99";s:5:"fluid";s:0:"";s:7:"extbase";s:0:"";}}', 'Markus Kappe', 'markus.kappe@dix.at', 'dix', '1aaa52b03ebac5c1259b90e1354fbf48', 'Compatible only with TYPO3 6.2.x\r\nFor TYPO3 7.x compatibility please look for dix_easylogin2 (currently under development)', '', 4004, 1, 0),
