(16622, 0, 'dix_easylogin', 1, '0.4.0', 141, 0, 'Easy Login and Register with OpenID (FE)', 'Do you know facebook connect? Easylogin is even better because it works not only with facebook but also with Google, Yahoo, myOpenId, twitter, and all other providers that offer OpenID or OAuth. It also integrates the common felogin (Username/Password)', 1, 0, 2, 1404141932, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:12:"4.5.0-6.2.99";s:5:"fluid";s:0:"";s:7:"extbase";s:0:"";}}', 'Markus Kappe', 'markus.kappe@dix.at', 'dix', '54d0b9442409defe9462ee2a971c6cc5', '	 Changed compatibility to 6.2.x\n	 Added OAuth 2.0 support.\n	 Added facebook with OAuth2 sample configuration (preferred over facebook native) (disabled by default)\n	 Added Google with OAuth2 sample configuration (preferred over OpenID) (disabled by d', '', 4000, 0, 0),
(16623, 0, 'dix_easylogin', 1, '0.4.1', 141, 0, 'Easy Login and Register with OpenID (FE)', 'Do you know facebook connect? Easylogin is even better because it works not only with facebook but also with Google, Yahoo, myOpenId, twitter, and all other providers that offer OpenID or OAuth. It also integrates the common felogin (Username/Password)', 1, 0, 2, 1405602285, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:12:"4.5.0-6.2.99";s:5:"fluid";s:0:"";s:7:"extbase";s:0:"";}}', 'Markus Kappe', 'markus.kappe@dix.at', 'dix', '4c41d16d9b2d399766047ec326a50ac7', ' Bugfix: proper encoding of &amp; in URLs\n cURL finetuning\n Thanks to ephraim@mokom01.com for reporting and fixing\n', '', 4001, 0, 0),
(16624, 0, 'dix_easylogin', 1, '0.4.2', 141, 0, 'Easy Login and Register with OpenID (FE)', 'Do you know facebook connect? Easylogin is even better because it works not only with facebook but also with Google, Yahoo, myOpenId, twitter, and all other providers that offer OpenID or OAuth. It also integrates the common felogin (Username/Password)', 1, 0, 2, 1428073819, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:12:"6.2.0-6.2.99";s:5:"fluid";s:0:"";s:7:"extbase";s:0:"";}}', 'Markus Kappe', 'markus.kappe@dix.at', 'dix', 'cc36514350b0ec9aee9a19cd60ef38ee', '	 Compatibility: only 6.2.x is supported for now\r\n	 Feature: trusted domains for registering\r\n	 Disabled Google OpenID by default - it will be shut down on April 20th 2015 (see https://developers.google.com/accounts/docs/OpenIDshutdown-timetable)\r\n	 ', '', 4002, 0, 0),
