(16875, 0, 'ecorss', 1, '0.1.0', 1028, 44, 'Ecodev : rss services', 'Generate quickly and easily RSS feeds based on the latest content of a SQL table. Can deal with flexform content.', 1, 0, 2, 1197485637, 'a:1:{s:7:"depends";a:4:{s:3:"cms";s:0:"";s:3:"div";s:11:"0.1.0-0.0.0";s:3:"lib";s:11:"0.1.0-0.0.0";s:5:"typo3";s:11:"4.0.0-0.0.0";}}', 'Fabien Udriot', 'fabien.udriot@ecodev.ch', 'franzholz', 'a14363acbf5bf2d1ae9903ef29be2213', 'First release. Based on lib/div 0.1.0. Please send feedback if you find bugs.', '', 1000, 0, 0),
(16876, 0, 'ecorss', 1, '0.2.0', 1028, 29, 'Ecodev : feeds services (RSS / ATOM)', 'Generate quickly and easily RSS / ATOM feeds based on the latest content of a SQL table. Can deal with flexform content.', 1, 0, 2, 1202846691, 'a:1:{s:7:"depends";a:4:{s:3:"cms";s:0:"";s:3:"div";s:11:"0.1.0-0.0.0";s:3:"lib";s:11:"0.1.0-0.0.0";s:5:"typo3";s:11:"4.0.0-0.0.0";}}', 'Fabien Udriot', 'fabien.udriot@ecodev.ch', 'franzholz', 'e144c0f935a9f3648e51788d14a5916f', 'Fix some bugs and a little documentation update', '', 2000, 0, 0),
(16877, 0, 'ecorss', 1, '0.2.1', 1028, 43, 'Ecodev : feeds services (RSS / ATOM)', 'Generate quickly and easily RSS / ATOM feeds based on the latest content of a SQL table. Can deal with flexform content.', 1, 0, 2, 1203346981, 'a:1:{s:7:"depends";a:4:{s:3:"cms";s:0:"";s:3:"div";s:11:"0.1.0-0.0.0";s:3:"lib";s:11:"0.1.0-0.0.0";s:5:"typo3";s:11:"4.0.0-0.0.0";}}', 'Fabien Udriot', 'fabien.udriot@ecodev.ch', 'franzholz', '6c578cd2fd89575b717a3759b32c8b7a', 'Fix a nasty PHP Header Warning! The express installation section has been updated in the documentation too. Thanks to Xavier Perseguers for the bug report and the fix.', '', 2001, 0, 0),
(16878, 0, 'ecorss', 1, '0.3.0', 1028, 45, 'Ecodev : feeds services (RSS / ATOM)', 'Generate quickly and easily RSS / ATOM feeds based on the latest content of a SQL table. Can deal with flexform content and multilingual websites.', 1, 0, 2, 1204500053, 'a:1:{s:7:"depends";a:4:{s:3:"cms";s:0:"";s:3:"div";s:11:"0.1.0-0.0.0";s:3:"lib";s:11:"0.1.0-0.0.0";s:5:"typo3";s:11:"4.0.0-0.0.0";}}', 'Fabien Udriot', 'fabien.udriot@ecodev.ch', 'franzholz', 'e5935f1925fb9c8e0fbfc2fad233ba02', 'Improvement : feed with multilanguage website supported - the title of an entry is now more intelligent - documentation update - code cleaning thanks to Xavier Perseguers', 'Ecodev', 3000, 0, 0),
(16879, 0, 'ecorss', 1, '0.3.1', 1028, 61, 'Ecodev : feeds services (RSS / ATOM)', 'Generate quickly and easily RSS / ATOM feeds based on the latest content of a SQL table. Can deal with flexform content and multilingual websites.', 1, 0, 2, 1206487978, 'a:1:{s:7:"depends";a:4:{s:3:"cms";s:0:"";s:3:"div";s:11:"0.1.0-0.0.0";s:3:"lib";s:11:"0.1.0-0.0.0";s:5:"typo3";s:11:"4.0.0-0.0.0";}}', 'Fabien Udriot', 'fabien.udriot@ecodev.ch', 'franzholz', 'b0ed623c58325df1743410aab978a542', 'Add the author and email to each entry of the feed. To cope with this information automatically in the backend, have a look at "fhm_author". This functionality has been added by Xavier Perseguers.', 'Ecodev', 3001, 0, 0),
(16880, 0, 'ecorss', 1, '0.4.1', 1028, 20, 'Ecodev : feeds services (RSS / ATOM)', 'Generate quickly and easily RSS / ATOM feeds based on the latest content of a SQL table. Can deal with flexform content and multilingual websites.', 1, 0, 2, 1209057798, 'a:1:{s:7:"depends";a:4:{s:3:"cms";s:0:"";s:3:"div";s:11:"0.1.0-0.0.0";s:3:"lib";s:11:"0.1.0-0.0.0";s:5:"typo3";s:11:"4.0.0-0.0.0";}}', 'Fabien Udriot / Xavier Perseguers', 'fabien.udriot@ecodev.ch', 'franzholz', '03e9d287c1798446b27f1b37ecca0605', 'This is a major release : caching mechanism - post processing hook - fixed back URL for feed whose content does not come from table tt_content (e.g. tt_news / mininews) - documentation update', 'Ecodev', 4001, 0, 0);
INSERT INTO `tx_extensionmanager_domain_model_extension` (`uid`, `pid`, `extension_key`, `repository`, `version`, `alldownloadcounter`, `downloadcounter`, `title`, `description`, `state`, `review_state`, `category`, `last_updated`, `serialized_dependencies`, `author_name`, `author_email`, `ownerusername`, `md5hash`, `update_comment`, `authorcompany`, `integer_version`, `current_version`, `lastreviewedversion`) VALUES
