(16882, 0, 'ecorss', 1, '0.5.1', 1028, 39, 'Ecodev : feeds services (RSS / ATOM)', 'Generate quickly and easily RSS / ATOM feeds based on the latest content of a SQL table. Can deal with flexform content and multilingual websites.', 1, 0, 2, 1209478252, 'a:1:{s:7:"depends";a:4:{s:3:"cms";s:0:"";s:3:"div";s:11:"0.1.0-0.0.0";s:3:"lib";s:11:"0.1.0-0.0.0";s:5:"typo3";s:11:"4.0.0-0.0.0";}}', 'Fabien Udriot / Xavier Perseguers', 'fabien.udriot@ecodev.ch', 'franzholz', '9c702ff09ced4a5b8c4337cf103ce08a', 'Remove javascript tag from "summary". Thanks to Marius Mhlberger for the regular expressions. The extension is feature ready and will go to "stable" if no bugs are reported in the next 4 weeks.', 'Ecodev', 5001, 0, 0),
(16883, 0, 'ecorss', 1, '0.5.2', 1028, 20, 'Ecodev : feeds services (RSS / ATOM)', 'Generate quickly and easily RSS / ATOM feeds based on the latest content of a SQL table. Can deal with flexform content and multilingual websites.', 1, 0, 2, 1211740835, 'a:1:{s:7:"depends";a:4:{s:3:"cms";s:0:"";s:3:"div";s:11:"0.1.0-0.0.0";s:3:"lib";s:11:"0.1.0-0.0.0";s:5:"typo3";s:11:"4.0.0-0.0.0";}}', 'Fabien Udriot / Xavier Perseguers', 'fabien.udriot@ecodev.ch', 'franzholz', 'f00cf4381dec4f43dd5e6e1e5cb6d7f9', 'small changes, bug fixing. Thanks to Steffen Gebert for reporting.', 'Ecodev', 5002, 0, 0),
(16884, 0, 'ecorss', 1, '0.5.3', 1028, 54, 'Ecodev : feeds services (RSS / ATOM)', 'Generate quickly and easily RSS / ATOM feeds based on the latest content of a SQL table. Can deal with flexform content and multilingual websites.', 1, 0, 2, 1212168550, 'a:1:{s:7:"depends";a:4:{s:3:"cms";s:0:"";s:3:"div";s:11:"0.1.0-0.0.0";s:3:"lib";s:11:"0.1.0-0.0.0";s:5:"typo3";s:11:"4.0.0-0.0.0";}}', 'Fabien Udriot / Xavier Perseguers', 'fabien.udriot@ecodev.ch', 'franzholz', '0b4696b1eb2828b081fd2e52d10e2355', 'Fix a blocking bug.', 'Ecodev', 5003, 0, 0),
(16885, 0, 'ecorss', 1, '0.6.0', 1028, 30, 'Ecodev : feeds services (RSS / ATOM)', 'Generate quickly and easily RSS / ATOM feeds based on the latest content of a SQL table. Can deal with flexform content and multilingual websites.', 1, 0, 2, 1215425572, 'a:1:{s:7:"depends";a:4:{s:3:"cms";s:0:"";s:3:"div";s:11:"0.1.0-0.0.0";s:3:"lib";s:11:"0.1.0-0.0.0";s:5:"typo3";s:11:"4.0.0-0.0.0";}}', 'Fabien Udriot / Xavier Perseguers', 'fabien.udriot@ecodev.ch', 'franzholz', '658c152282c17525e7b395649748db1c', 'Add 2 interesting features: a backend user can now exclude easily a content element from the feed - a administrator can clear the cache with the parameter clear_cache. (see documentation)', 'Ecodev', 6000, 0, 0),
