(17103, 0, 'div2007', 1, '1.7.13', 27681, 0, 'Static Methods since 2007', 'This library is called by several extensions. It provides a modified t3lib_div of TYPO3 4.7.10 and backwards compatibility to TYPO3 6.2 and 4.5. It replaces most tslib_pibase methods.', 2, 0, 4, 1506498155, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:13:"5.2.0-7.99.99";s:5:"typo3";s:13:"4.5.0-8.99.99";}}', 'Franz Holzinger', 'franz@ttproducts.de', 'franzholz', '447a7fbe10efb2aa84fd3a1da66c6e6e', ' \nadd new method getExtensionFilePath to class JambageComDiv2007UtilityExtensionUtility .\nbugfix for PHP 7\n', 'jambage.com', 1007013, 0, 0),
