(17106, 0, 'quick_shop', 1, '7.0.13', 1080, 0, 'Quick Shop - responsive e-commerce with TYPO3', 'http://typo3-quick-shop.de. Quick Shop is optimised for desktops, tablets and smartphones. You are welcome to install Quick Shop with one mouse-click  responsive and ready-to-use. Quick Shop is e-commerce for small budget and small-scale enterprises. Manual: http://typo3-quick-shop.deEXT:quick_shop/doc/manual.pdf', 2, 0, 3, 1500569449, 'a:0:{}', 'Dirk Wildt (Die Netzmacher)', 'http://wildt.at.die-netzmacher.de', 'dwildt', 'a5f5cee6c66b4159121e478fc575f9b1', 'Improvements: Update shipping Costs DHL. package upto 10 kg is moved from 14.99 to 16.99 EUR. If you use the DHL template, please adapt your information / text on your page shipping!', '', 7000013, 0, 0),
(17107, 0, 'quick_shop', 1, '1.0.1', 1080, 13, 'Quick Shop', 'Quick Shop is both a quick shop extension and a tutorial that enables you to build your own shop. With the Quick Shop Installer (quickshop_installer) you will need only one click for installing the Quick Shop with sample products.', 2, 0, 3, 1277905834, 'a:1:{s:7:"depends";a:2:{s:7:"browser";s:0:"";s:7:"wt_cart";s:0:"";}}', 'Dirk Wildt', 'http://wildt.at.die-netzmacher.de', 'dwildt', 'da93bfd23bbd48062d174d370b3f3245', 'Quick Shop is both a quick shop extension and a tutorial that enables you to build your own shop. With the Quick Shop Installer (quickshop_installer) you will need only one click for installing the Quick Shop with sample products. You configure and extend', '', 1000001, 0, 0),
(17108, 0, 'quick_shop', 1, '1.1.0', 1080, 15, 'Quick Shop', 'Quick Shop is both a quick shop extension and a tutorial that enables you to build your own shop. With the Quick Shop Installer (quickshop_installer) you will need only one click for installing the Quick Shop with sample products.', 2, 0, 3, 1279908457, 'a:0:{}', 'Dirk Wildt (Die Netzmacher)', 'http://wildt.at.die-netzmacher.de', 'dwildt', '6942426cd206e35677d0ffcfe46a1ece', 'New Feature: Optional manual ordering of records added', '', 1001000, 0, 0),
(17109, 0, 'quick_shop', 1, '1.1.1', 1080, 161, 'Quick Shop', 'Quick Shop is both a quick shop extension and a tutorial that enables you to build your own shop. With the Quick Shop Installer (quickshop_installer) you will need only one click for installing the Quick Shop with sample products.', 2, 0, 3, 1282773844, 'a:0:{}', 'Dirk Wildt (Die Netzmacher)', 'http://wildt.at.die-netzmacher.de', 'dwildt', '1ee220a286421d51676bd7a03ba40597', 'Manual - New section: Integratio in Facebook', '', 1001001, 0, 0),
