(17113, 0, 'quick_shop', 1, '1.3.1', 1080, 83, 'Quick Shop', 'Quick Shop is both a quick shop extension and a tutorial that enables you to build your own shop. With the Quick Shop Installer (quickshop_installer) you will need only one click for installing the Quick Shop with sample products.', 2, 0, 3, 1290945848, 'a:1:{s:7:"depends";a:1:{s:7:"browser";s:6:"3.5.0-";}}', 'Dirk Wildt (Die Netzmacher)', 'http://wildt.at.die-netzmacher.de', 'dwildt', 'b48a47dec46f151800a391b5c5134c2c', 'Improvement: 11114: Make Javascript Backbutton unvisible in single AJAX views', '', 1003001, 0, 0),
