(17153, 0, 'gotoedit', 1, '0.0.1', 134, 22, 'Goto Edit', 'Adds column and row fields to BE forms for textareas. These can be used to jump to a point in the file and the caret position can be retained after saving the file.', 0, 0, 0, 1199465120, 'a:0:{}', 'Benjamin Todd', 'b.todd@emnet.co.uk', 'thetypoteamonkey', '47f29aa3c6bb99b14fe40f59821d2b7f', '', '', 1, 0, 0),
