(17156, 0, 'gotoedit', 1, '0.0.3', 134, 17, 'Goto Edit', 'Adds a caret (cursor) position field to the BE file edit forms textarea. This can be used to jump to a page line in the file. Goto Edit also restores the caret position after a page is saved.', 0, 0, 0, 1201004435, 'a:0:{}', 'Benjamin Todd', 'b.todd@emnet.co.uk', 'thetypoteamonkey', '25cf4c96d5d037ba1c7476880dbf6cc3', 'The Goto Edit goto box now accepts page numbers, not character numbers.', '', 3, 0, 0),
