(17629, 0, 'bitsoffice', 1, '0.8.0', 279, 23, 'Extended Office Import', 'Imports and Displays Open Office Writer documents. This version extends the rlmp_officeimport from Robert Lemke. It render the backend pagetree depending on the headings in your document. Each heading section will render a page with a text element in the', 1, 0, 3, 1201989608, 'a:0:{}', 'Joachim Karl', 'joachim.karl@bitsafari.de', 'herrandrack', '07b9e9ac616fa5f35d934b92986c1a37', 'initial release', '', 8000, 0, 0),
