(17835, 0, 'event', 1, '0.2.4', 420, 6, 'Event', 'Event online booking - manages event online bookings with confirmation mail, configurable forms see manual, especially for the german lastschriftverfahren.', 1, -1, 3, 1242130662, 'a:0:{}', 'Joachim Ruhs', 'postmaster@joachim-ruhs.de', 'joachim_ruhs', 'e5167273d72d9e66b858a7eaf6a2b213', 'Fixed bug when checkboxes are used in the form. Please use only 1 checkbox per section. When more than 1 checkboxes are required create more sections.', '', 2004, 0, 0),
