(17842, 0, 'flux', 1, '4.7.10', 418, 0, 'Dynamic Fluid FlexForms', 'Uses Fluid to render FlexForms, making them highly dynamic. Has built-in content preview in BE page module for any content using Flux. Offspring of the FED extension.', 2, 0, 4, 1352405360, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'fluidtypo3', '89b66dc9226fb7ced15aa1ad60e9890a', 'Compatibility for the most recent 4.x versions. Unfortunately an expected patch was not merged - since the recent core update was an unexpected security fix.', 'Wildside A/S', 4007010, 0, 0),
(17843, 0, 'flux', 1, '1.0.0', 418, 20, 'Dynamic Fluid FlexForms', 'Uses Fluid to render FlexForms, making them highly dynamic. Has built-in content preview in BE page module for any content using Flux. Offspring of the FED extension.', 2, 0, 4, 1325092923, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'fluidtypo3', '9aba47e45b882534f97481c1a3221d22', 'Initial TER release. Feature state is stable since this is a branch from the FED project. Documentation at http://fedext.net/extensions/flux', 'Wildside A/S', 1000000, 0, 0),
(17844, 0, 'flux', 1, '1.1.0', 418, 18, 'Dynamic Fluid FlexForms', 'Uses Fluid to render FlexForms, making them highly dynamic. Has built-in content preview in BE page module for any content using Flux. Offspring of the FED extension.', 2, 0, 4, 1325445247, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'fluidtypo3', 'ed68fc22183f5282f39f360a6e29875e', 'Fix for backend previews. Note, this is a BREAKING CHANGE due to configuration changes to make Flux more compatible with Layouts and Partials from other extensions. You must change your ext_tables.php to pass $_EXTKEY as the first parameter to any Tx_Flux', 'Wildside A/S', 1001000, 0, 0),
(17845, 0, 'flux', 1, '1.1.1', 418, 25, 'Dynamic Fluid FlexForms', 'Uses Fluid to render FlexForms, making them highly dynamic. Has built-in content preview in BE page module for any content using Flux. Offspring of the FED extension.', 2, 0, 4, 1325781970, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'fluidtypo3', 'bb97eff02cccdee8b7128921edb2bce3', 'Updated manual with link to online documentation.', 'Wildside A/S', 1001001, 0, 0),
(17846, 0, 'flux', 1, '1.2.0', 418, 14, 'Dynamic Fluid FlexForms', 'Uses Fluid to render FlexForms, making them highly dynamic. Has built-in content preview in BE page module for any content using Flux. Offspring of the FED extension.', 2, 0, 4, 1326235908, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'fluidtypo3', 'b406ec7fbe1db3aba623579219ba40a3', 'Added support for attaching FlexForms to fields in any table (which has TCA present), also tables like pages, tt_content and tt_news. The exact same Fluid FlexForm logic applies in this context.', 'Wildside A/S', 1002000, 0, 0),
(17847, 0, 'flux', 1, '1.2.1', 418, 4, 'Dynamic Fluid FlexForms', 'Uses Fluid to render FlexForms, making them highly dynamic. Has built-in content preview in BE page module for any content using Flux. Offspring of the FED extension.', 2, 0, 4, 1326312124, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'fluidtypo3', '704609609aab4a74be815a60d3e6c5ad', 'Avoided a warning message due to no controllers existing when rendering content previews.', 'Wildside A/S', 1002001, 0, 0),
(17848, 0, 'flux', 1, '1.2.2', 418, 2, 'Dynamic Fluid FlexForms', 'Uses Fluid to render FlexForms, making them highly dynamic. Has built-in content preview in BE page module for any content using Flux. Offspring of the FED extension.', 2, 0, 4, 1326317318, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'fluidtypo3', '4c8aff16d92bb56086495cc897b1940d', 'Added support for using the GridViewHelper from Flux in FEDs page templates to create a Backend Layout (target feature is still unreleased though, so this is just a minor preparation update).', 'Wildside A/S', 1002002, 0, 0),
(17849, 0, 'flux', 1, '1.2.3', 418, 17, 'Dynamic Fluid FlexForms', 'Uses Fluid to render FlexForms, making them highly dynamic. Has built-in content preview in BE page module for any content using Flux. Offspring of the FED extension.', 2, 0, 4, 1326319054, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'fluidtypo3', '8c260bbb0c0d247d4ade971bf52b377a', 'Fixed an unfriendly (but harmless) error message when saving a record affected by Flux.', 'Wildside A/S', 1002003, 0, 0),
(17850, 0, 'flux', 1, '1.2.4', 418, 14, 'Dynamic Fluid FlexForms', 'Uses Fluid to render FlexForms, making them highly dynamic. Has built-in content preview in BE page module for any content using Flux. Offspring of the FED extension.', 2, 0, 4, 1326638934, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'fluidtypo3', 'cbb103bc0e2a930d2b7deca183839c60', 'Added a "debug mode" switch in extension configuration options. Fixed an incorrect usage of FED ViewHelpers to render the FlexForm source - Flux ViewHelpers should be and are now used.', 'Wildside A/S', 1002004, 0, 0),
(17851, 0, 'flux', 1, '1.2.5', 418, 18, 'Dynamic Fluid FlexForms', 'Uses Fluid to render FlexForms, making them highly dynamic. Has built-in content preview in BE page module for any content using Flux. Offspring of the FED extension.', 2, 0, 4, 1326745427, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'fluidtypo3', 'f3249757ccbbe24b0d9a822a35a947f4', 'Fixed sheet rendering bug. Added 4.5 compatibility (ext_autoload.php) entries not ported from FED. Fixed a possible error message if no TS was set.', 'Wildside A/S', 1002005, 0, 0),
