(17857, 0, 'flux', 1, '1.2.11', 418, 13, 'Dynamic Fluid FlexForms', 'Uses Fluid to render FlexForms, making them highly dynamic. Has built-in content preview in BE page module for any content using Flux. Offspring of the FED extension.', 2, 0, 4, 1330781720, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'fluidtypo3', '05df3dee5387cf9d5e3210d9d1ad836f', 'Minor bugfixes for nested content elements.', 'Wildside A/S', 1002011, 0, 0),
(17858, 0, 'flux', 1, '1.3.0', 418, 39, 'Dynamic Fluid FlexForms', 'Uses Fluid to render FlexForms, making them highly dynamic. Has built-in content preview in BE page module for any content using Flux. Offspring of the FED extension.', 2, 0, 4, 1330882627, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'fluidtypo3', '01a8fc10e038aa8964d37f01c1f809b5', 'Added all FlexForm field Wizards as ViewHelpers. Use these as tag content of a flux:flexform.field. ViewHelper to enable each Wizard for that field.', 'Wildside A/S', 1003000, 0, 0),
(17859, 0, 'flux', 1, '1.4.0', 418, 72, 'Dynamic Fluid FlexForms', 'Uses Fluid to render FlexForms, making them highly dynamic. Has built-in content preview in BE page module for any content using Flux. Offspring of the FED extension.', 2, 0, 4, 1331224160, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'fluidtypo3', 'e5c3cee08e3c6dce17fedbbba83cd6f0', 'Added support for using Sections in Fluid FlexForms. Documentation and examples at http://fedext.net will be updated shortly.', 'Wildside A/S', 1004000, 0, 0),
(17860, 0, 'flux', 1, '1.4.1', 418, 54, 'Dynamic Fluid FlexForms', 'Uses Fluid to render FlexForms, making them highly dynamic. Has built-in content preview in BE page module for any content using Flux. Offspring of the FED extension.', 2, 0, 4, 1332346101, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'fluidtypo3', '4aec5ba0dbdc1069478e91dca9283ddd', 'Important drag-n-drop/sorting bugfix. EXT:gridelements added to suggested extensions. Added flux:flexform.object used in flux:flexform.section to define different objects which can be inserted in the FlexForm section. Use of the new Object ViewHelper is h', 'Wildside A/S', 1004001, 0, 0),
(17861, 0, 'flux', 1, '1.4.2', 418, 0, 'Dynamic Fluid FlexForms', 'Uses Fluid to render FlexForms, making them highly dynamic. Has built-in content preview in BE page module for any content using Flux. Offspring of the FED extension.', 2, 0, 4, 1333747808, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'fluidtypo3', '182d2adc865b826059696223f7674a73', 'Stability and user experience improvements. Better error handling and added template validation. All references to and dependencies from FED have been purged.', 'Wildside A/S', 1004002, 0, 0),
(17862, 0, 'flux', 1, '4.7.0', 418, 0, 'Dynamic Fluid FlexForms', 'Uses Fluid to render FlexForms, making them highly dynamic. Has built-in content preview in BE page module for any content using Flux. Offspring of the FED extension.', 2, 0, 4, 1343610500, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'fluidtypo3', '027ae662ba29aa26dcd1633bcbe306c1', 'Major revision. Performance significantly improved, especially on 4.5 installs. Version scheme updated to reflect core extensions. For more information about this update see http://fedext.net/overview/fed-news/archive.html', 'Wildside A/S', 4007000, 0, 0),
(17863, 0, 'flux', 1, '4.7.1', 418, 0, 'Dynamic Fluid FlexForms', 'Uses Fluid to render FlexForms, making them highly dynamic. Has built-in content preview in BE page module for any content using Flux. Offspring of the FED extension.', 2, 0, 4, 1343740364, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'fluidtypo3', 'ee4c731b66125b10df41816c5fc583f1', 'Contains a number of small bugfixes in relation to changes introduced in 4.7.0 - most importantly, you now must manually enable "compact" in extension configuration to enable squishing of single-sheet FlexForms down to a ROOT-type form.', 'Wildside A/S', 4007001, 0, 0),
(17864, 0, 'flux', 1, '4.7.2', 418, 0, 'Dynamic Fluid FlexForms', 'Uses Fluid to render FlexForms, making them highly dynamic. Has built-in content preview in BE page module for any content using Flux. Offspring of the FED extension.', 2, 0, 4, 1343750103, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'fluidtypo3', '4ac8209377fea7627fb16776655515d6', 'Hotfix for BE previews of non-Flux elements.', 'Wildside A/S', 4007002, 0, 0),
(17865, 0, 'flux', 1, '4.7.3', 418, 0, 'Dynamic Fluid FlexForms', 'Uses Fluid to render FlexForms, making them highly dynamic. Has built-in content preview in BE page module for any content using Flux. Offspring of the FED extension.', 2, 0, 4, 1344447775, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'fluidtypo3', '07a0923282e20ff03d2282beb54470ce', 'Bugfixes for flexform fields; restored previous functionality lost in rework of internals. Minor performance improvements and workarounds for a few deprecated methods on 4.6.', 'Wildside A/S', 4007003, 0, 0),
(17866, 0, 'flux', 1, '4.7.4', 418, 0, 'Dynamic Fluid FlexForms', 'Uses Fluid to render FlexForms, making them highly dynamic. Has built-in content preview in BE page module for any content using Flux. Offspring of the FED extension.', 2, 0, 4, 1350169237, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'fluidtypo3', '10f9a6a93e7a1d4584cfcc599a54068f', 'Bugfixes and CGL mostly. Full change log can be found at https://github.com/NamelessCoder/flux/commits/master', 'Wildside A/S', 4007004, 0, 0),
(17867, 0, 'flux', 1, '4.7.5', 418, 0, 'Dynamic Fluid FlexForms', 'Uses Fluid to render FlexForms, making them highly dynamic. Has built-in content preview in BE page module for any content using Flux. Offspring of the FED extension.', 2, 0, 4, 1350931264, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'fluidtypo3', 'b2b165acaed0df048bf2fe04b317f28f', 'Pure bugfix release - needed by FED 4.7.7. Full changelog: https://github.com/NamelessCoder/flux/commits/master', 'Wildside A/S', 4007005, 0, 0),
(17868, 0, 'flux', 1, '4.7.6', 418, 0, 'Dynamic Fluid FlexForms', 'Uses Fluid to render FlexForms, making them highly dynamic. Has built-in content preview in BE page module for any content using Flux. Offspring of the FED extension.', 2, 0, 4, 1351629181, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'fluidtypo3', 'b4df5186f16f07994ae8c2172bd716ed', 'EXTREMELY important compat fix for plugins using Flux ConfigurationProviders. Does not affect FED content/page features, only the plugin-related implementation was affected. Full change log: https://github.com/NamelessCoder/flux/commits/master', 'Wildside A/S', 4007006, 0, 0),
(17869, 0, 'flux', 1, '4.7.7', 418, 0, 'Dynamic Fluid FlexForms', 'Uses Fluid to render FlexForms, making them highly dynamic. Has built-in content preview in BE page module for any content using Flux. Offspring of the FED extension.', 2, 0, 4, 1352201819, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'fluidtypo3', '40077288f12ae0f9f6d1a7c75e6db0bc', 'Bugfixes: Custom/Html Field ViewHelpers, PHP/SQL warnings when saving non-page records without modifying the data, broken page FlexForm on non-master TYPO3 versions. Changelog: https://github.com/NamelessCoder/flux/commits/master', 'Wildside A/S', 4007007, 0, 0),
(17870, 0, 'flux', 1, '4.7.8', 418, 0, 'Dynamic Fluid FlexForms', 'Uses Fluid to render FlexForms, making them highly dynamic. Has built-in content preview in BE page module for any content using Flux. Offspring of the FED extension.', 2, 0, 4, 1352294747, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'fluidtypo3', '39576ffb6f73b4934a87a53f56591f2c', 'Hotfix for broken BE previews; affected by the same "fieldName" bug which was addressed in other contexts by the two previous hotfixes.', 'Wildside A/S', 4007008, 0, 0),
(17871, 0, 'flux', 1, '4.7.9', 418, 0, 'Dynamic Fluid FlexForms', 'Uses Fluid to render FlexForms, making them highly dynamic. Has built-in content preview in BE page module for any content using Flux. Offspring of the FED extension.', 2, 0, 4, 1352324026, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'fluidtypo3', '79d1c1b5cdcbb662776a0548cadb14d3', 'Please excuse the last couple of defective sub-versions - a recent change deep inside the guts of all the latest TYPO3 4.x versions has been causing a lot of grief and Ive been a little distracted when fixing it. Hopefully this 4.7.9 version takes care ', 'Wildside A/S', 4007009, 0, 0),
(17872, 0, 'flux', 1, '4.7.11', 418, 0, 'Dynamic Fluid FlexForms', 'Uses Fluid to render FlexForms, making them highly dynamic. Has built-in content preview in BE page module for any content using Flux. Offspring of the FED extension.', 2, 0, 4, 1352839086, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'fluidtypo3', '3f9cbfbdd0265302c227b16cae065d5a', 'Compatibility update for the three latest TYPO3 4.5, 4.6 and 4.7 versions.', 'Wildside A/S', 4007011, 0, 0),
(17873, 0, 'flux', 1, '4.7.12', 418, 0, 'Dynamic Fluid FlexForms', 'Uses Fluid to render FlexForms, making them highly dynamic. Has built-in content preview in BE page module for any content using Flux. Offspring of the FED extension.', 2, 0, 4, 1353719832, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'fluidtypo3', 'adcfc7c2a053b4bfa54d9f2506819d3c', 'Minor update - few bugfixes, added attribute "displayCond" (TCE displayCond syntax) on every Flux field type, ConfigurationService to quickly fetch TypoScript and an unregisterConfigurationProvider method, something which was previously impossible. Impr', 'Wildside A/S', 4007012, 0, 0),
(17874, 0, 'flux', 1, '4.7.13', 418, 0, 'Dynamic Fluid FlexForms', 'Uses Fluid to render FlexForms, making them highly dynamic. Has built-in content preview in BE page module for any content using Flux. Offspring of the FED extension.', 2, 0, 4, 1354456446, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'fluidtypo3', '56a93b19d81f075c4b92826229658448', 'Bugfix for Version Utility on 4.x branches.', 'Wildside A/S', 4007013, 0, 0),
(17875, 0, 'flux', 1, '4.7.14', 418, 0, 'Dynamic Fluid FlexForms', 'Uses Fluid to render FlexForms, making them highly dynamic. Has built-in content preview in BE page module for any content using Flux. Offspring of the FED extension.', 2, 0, 4, 1355619127, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'fluidtypo3', '17f1f1659dd2177db486884178fae832', 'Final TER version in the 4.7 era. Last release which will be fully compatible with the 4.x branches of TYPO3. Future features may not be available when running on 4.x branches but compatibility will be maintained until LTS is discontinued.', 'Wildside A/S', 4007014, 0, 0),
(17876, 0, 'flux', 1, '5.0.0', 418, 0, 'Dynamic Fluid FlexForms', 'Uses Fluid to render FlexForms, making them highly dynamic. Has built-in content preview in BE page module for any content using Flux. Offspring of the FED extension.', 2, 0, 4, 1355620292, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'fluidtypo3', '9121179c604fd8745721dac6307d5944', 'Please welcome 5.0 - ready for TYPO3 6.0, compatibility with 4.7 will be preserved until LTS is discontinued. Please note: 4.7.14 was released moments ago, marking the last 4.7.x release.', 'Wildside A/S', 5000000, 0, 0),
(17877, 0, 'flux', 1, '5.0.1', 418, 0, 'Dynamic Fluid FlexForms', 'Uses Fluid to render FlexForms, making them highly dynamic. Has built-in content preview in BE page module for any content using Flux. Offspring of the FED extension.', 2, 0, 4, 1356912116, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'fluidtypo3', 'f0cc885ba80928ecfd2207b9ef03b7f1', 'Minor update, mostly bugfixes. New: added "subActions" argument on flux:flexform.field.controllerActions, allows extending individually selectable Controller actions with a list of also allowed actions on the same Controller.', 'Wildside A/S', 5000001, 0, 0),
(17878, 0, 'flux', 1, '5.0.2', 418, 0, 'Dynamic Fluid FlexForms', 'Uses Fluid to render FlexForms, making them highly dynamic. Has built-in content preview in BE page module for any content using Flux. Offspring of the FED extension.', 2, 0, 4, 1357691092, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'fluidtypo3', '3ecdcf1a34714e3ae0b1718121ce1115', 'Bugfix release, fixes a range of minor inconveniences. Please note: there is still an issue experienced by some 6.0 sites where FE previews would fail. See https://github.com/NamelessCoder/flux/issues/4 - a fix for that particular problem is coming as soo', 'Wildside A/S', 5000002, 0, 0),
(17879, 0, 'flux', 1, '5.0.3', 418, 0, 'Dynamic Fluid FlexForms', 'Uses Fluid to render FlexForms, making them highly dynamic. Has built-in content preview in BE page module for any content using Flux. Offspring of the FED extension.', 2, 0, 4, 1357855142, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'fluidtypo3', 'a7919dbb4e478361edb85cd766f922ad', 'Fixes: child content breaks relation to parent when parent element is saved from within page module on 6.0.', 'Wildside A/S', 5000003, 0, 0),
(17880, 0, 'flux', 1, '5.1.0', 418, 0, 'Dynamic Fluid FlexForms', 'Uses Fluid to render FlexForms, making them highly dynamic. Has built-in content preview in BE page module for any content using Flux. Offspring of the FED extension.', 2, 0, 4, 1358119246, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'fluidtypo3', '36b6dce0e5346b5af89d00407d7e2e82', 'A few new features: On 6.0 (only!) it is now possible to collapse the Grid Widget, hiding child elements. The state is memorised in a cookie. Added also is the option to add a "clearCacheCommand" method on any ConfigurationProvider, executed when caches', 'Wildside A/S', 5001000, 0, 0),
(17881, 0, 'flux', 1, '5.1.1', 418, 0, 'Dynamic Fluid FlexForms', 'Uses Fluid to render FlexForms, making them highly dynamic. Has built-in content preview in BE page module for any content using Flux. Offspring of the FED extension.', 2, 0, 4, 1358721325, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'fluidtypo3', '68c54be6847173398b2afc60732bc58d', 'Fixes: "...does not match interface" on some 6.0 due to a quirk in class mapping. Missing "wizardTab" value would cause bad tab placement for Fluid Content. Added: ViewHelper to fetch FlexForm data from any tableuidfield combination.', 'Wildside A/S', 5001001, 0, 0),
(17882, 0, 'flux', 1, '5.2.0', 418, 0, 'Flux: Fluid FlexForms', 'Uses Fluid to render FlexForms, making them highly dynamic. Has built-in content preview in BE page module for any content using Flux. Offspring of the FED extension.', 2, 0, 4, 1359909254, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'fluidtypo3', 'd93b97582146b7d26c4e140ce08751aa', 'New: Variable inhertiance, inline FlexForm field (6.0 only), ViewHelper to read FlexForm data, added class-local caching and some cleanups. BEWARE: you will need to truncate your typo3temp directory as well as your cache tables in the database; a class wa', 'Wildside A/S', 5002000, 0, 0),
(17883, 0, 'flux', 1, '5.2.1', 418, 0, 'Flux: Fluid FlexForms', 'Uses Fluid to render FlexForms, making them highly dynamic. Has built-in content preview in BE page module for any content using Flux. Offspring of the FED extension.', 2, 0, 4, 1361571507, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'fluidtypo3', 'e96cef3eba8f22843e8b0748762c57cf', 'Bugfixes: child content problem on TYPO3 sites not in DOCUMENT_ROOT. Improved error preventions and logging when processing Flux forms. Fixed default, cols and rows attributes on the textarea field type.', 'Wildside A/S', 5002001, 0, 0),
(17884, 0, 'flux', 1, '5.3.0', 418, 0, 'Flux: Fluid FlexForms', 'Uses Fluid to render FlexForms, making them highly dynamic. Has built-in content preview in BE page module for any content using Flux. Offspring of the FED extension.', 2, 0, 4, 1363561045, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'fluidtypo3', 'b5f04f1e2b8ddb2f2bc34b6bffe37d57', 'New: paste and paste reference feature for nested child content on 6.0. FlexForm Data ViewHelper now uses Flux to retrieve FlexForm values.', 'Wildside A/S', 5003000, 0, 0),
(17885, 0, 'flux', 1, '6.0.0', 418, 0, 'Flux: Fluid FlexForms', 'Uses Fluid to render FlexForms, making them highly dynamic. Has built-in content preview in BE page module for any content using Flux. Offspring of the FED extension.', 2, 0, 4, 1368966201, 'a:1:{s:7:"depends";a:4:{s:5:"typo3";s:10:"4.5-6.2.99";s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'fluidtypo3', '5ddb263a8a4da57981a9e7ab920423d5', 'Major update. Read more: http://fedext.net/news/new-major-versions.html', 'Wildside A/S', 6000000, 0, 0),
(17886, 0, 'flux', 1, '6.0.1', 418, 0, 'Flux: Fluid FlexForms', 'Uses Fluid to render FlexForms, making them highly dynamic. Has built-in content preview in BE page module for any content using Flux. Offspring of the FED extension.', 2, 0, 4, 1372627145, 'a:1:{s:7:"depends";a:4:{s:5:"typo3";s:10:"4.5-6.1.99";s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'fluidtypo3', 'de5cdda52d7ad4d9d1a082206a808868', 'Bugfix release. Also added is an extension configuration toggle for error handling in Flux controllers. Changes default behaviour to not handle errors by default; if you relied on error handling please activate this toggle after updating.', 'Wildside A/S', 6000001, 0, 0),
(17887, 0, 'flux', 1, '6.0.2', 418, 0, 'Flux: Fluid FlexForms', 'Uses Fluid to render FlexForms, making them highly dynamic. Has built-in content preview in BE page module for any content using Flux. Offspring of the FED extension.', 2, 0, 4, 1386177252, 'a:1:{s:7:"depends";a:4:{s:5:"typo3";s:12:"4.5.0-6.1.99";s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'fluidtypo3', '769901cc0779a5e06807fb40435c580c', 'Likely the last update to 6.x series - changelog: https://github.com/FluidTYPO3/flux/commits/6.0.2', 'Wildside A/S', 6000002, 0, 0),
(17888, 0, 'flux', 1, '6.0.3', 418, 0, 'Flux: Fluid FlexForms', 'Uses Fluid to render FlexForms, making them highly dynamic. Has built-in content preview in BE page module for any content using Flux. Offspring of the FED extension.', 2, 0, 4, 1394654887, 'a:1:{s:7:"depends";a:4:{s:5:"typo3";s:12:"4.5.0-6.1.99";s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'fluidtypo3', '096a600833a331541437b48b737cdec7', 'Fixes and performance. Note: new colPos value - RUN NEW EXTENSION UPGRADE SCRIPT IMMEDIATELY AFTER UPDATING!', 'Wildside A/S', 6000003, 0, 0),
(17889, 0, 'flux', 1, '7.0.0', 418, 0, 'Flux: Fluid FlexForms', 'Uses Fluid to render FlexForms, making them highly dynamic. Has built-in content preview in BE page module for any content using Flux. Offspring of the FED extension.', 2, 0, 4, 1395771121, 'a:1:{s:7:"depends";a:4:{s:5:"typo3";s:12:"6.1.0-6.2.99";s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'FluidTYPO3 Team', 'claus@namelesscoder.net', 'fluidtypo3', 'b183c65f7cca535c5565523f56743554', 'Its finally here - Flux 7.0.0. Find out more on http://fluidtypo3.org', '', 7000000, 0, 0),
