(17917, 0, 'mindmap_search_ajax', 1, '0.0.1', 170, 14, 'Mindmap-Searchfunction', 'It does search through all files and directories of a mindmap.', 3, 0, 3, 1203021169, 'a:0:{}', 'Benjamin Ajfrid', 'benjamin.ajfrid@gmx.at', 'mod_zero', '0cb71685cb8a324417a92934cfc98e9b', 'First Version, should work, but it doesnt\nNo Documentation\nMaybe you can get with it', '', 1, 0, 0),
(17918, 0, 'mindmap_search_ajax', 1, '0.1.0', 170, 11, 'Mindmap-Searchfunction', 'It does search through all files and directories of a mindmap.', 3, 0, 3, 1203063248, 'a:0:{}', 'Benjamin Ajfrid', 'benjamin.ajfrid@gmx.at', 'mod_zero', 'cbd4a0b3dbbdf4900b864a96da18e6b2', '- Fixed javascript errors\n- getfilelist() implemented in search.php\n- Output with urls\n', '', 1000, 0, 0),
(17919, 0, 'mindmap_search_ajax', 1, '0.1.1', 170, 10, 'Mindmap Search', 'It does search through all files and directories of a mindmap.', 1, 0, 3, 1203118697, 'a:0:{}', 'Benjamin Ajfrid', 'benjamin.ajfrid@gmx.at', 'mod_zero', 'fa78e56f5ee64c0940f909f7e1482859', 'Fixed some bugs: Fixed utf8-filenames, Included filetype-filter, google-like-output, included getfilelist() with subdir-mode, included iframe for second output, included on-hyperlink-click-change-iframe-source', '', 1001, 0, 0),
(17920, 0, 'mindmap_search_ajax', 1, '0.1.2', 170, 16, 'Mindmap Search', 'It does search through all files and directories of a mindmap.', 1, 0, 3, 1203159916, 'a:0:{}', 'Benjamin Ajfrid', 'benjamin.ajfrid@gmx.at', 'mod_zero', 'ecc869740922b70c457cec29f002d56c', 'Included manual', '', 1002, 0, 0),
(17921, 0, 'mindmap_search_ajax', 1, '0.2.0', 170, 27, 'Mindmap Search', 'It does search through all files and directories of a mindmap.', 1, 0, 3, 1203294284, 'a:0:{}', 'Benjamin Ajfrid', 'benjamin.ajfrid@gmx.at', 'mod_zero', '3c21e11ddda0e42d7b6d516271f48dc3', 'Included Flexforms for Mindmap-URL and -PATH at installation,show and hide functions for iframe and searchbar, 2 types of searching (whole and single-word), showing iframe (mindmap) instead of search-results (with switching back), can search in PDF-files,', '', 2000, 0, 0),
