(18040, 0, 'abcourses', 1, '1.3.0', 1029, 93, 'Seminar management', 'An extension for dealing with seminars and appointments with extensive opportunities for advertising your appointments and for subscribing to them. Developed for execution with PHP4. Offers a hook during the subscribe progress. Implementing a data access', 2, 0, 3, 1204286665, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:10:"tt_address";s:0:"";s:13:"kj_becalendar";s:0:"";}}', 'Andreas Behrens (@b-networks) and Stefan Precht (Tallence, Symplasson)', 'Andreas Behrens behrens@b-networks.de, Stefan Precht sprecht@gmx.de', 'sprecht', '0758033277059a4057db10263b89555f', 'An extension for dealing with seminars and appointments with extensive opportunities for advertising your appointments and for subscribing to them.', '@b-networks, SYMPLASSON GmbH, Tallence GmbH', 1003000, 0, 0),
(18041, 0, 'abcourses', 1, '1.3.1', 1029, 111, 'Seminar management', 'An extension for dealing with seminars and appointments with extensive opportunities for advertising your appointments and for subscribing to them. Developed for execution with PHP4. Offers a hook during the subscribe progress. Implementing a data access', 2, 0, 3, 1206222023, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:10:"tt_address";s:0:"";s:13:"kj_becalendar";s:0:"";}}', 'Andreas Behrens (@b-networks) and Stefan Precht (Tallence, Symplasson)', 'Andreas Behrens behrens@b-networks.de, Stefan Precht sprecht@gmx.de', 'sprecht', '6a797ff91ac59264f3db167b880c335f', 'Some important Bug-Fixes. The locallang file was not correctly initialised. Furthermore: Added some validations to avoid error messages if some data-collections was missing.', '@b-networks, SYMPLASSON GmbH, Tallence GmbH', 1003001, 0, 0),
(18042, 0, 'abcourses', 1, '1.3.2', 1029, 262, 'Seminar management', 'An extension for dealing with seminars and appointments with extensive opportunities for advertising your appointments and for subscribing to them. Developed for execution with PHP4. Offers a hook during the subscribe progress. Implementing a data access', 2, 0, 3, 1208725239, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:10:"tt_address";s:0:"";s:13:"kj_becalendar";s:0:"";}}', 'Andreas Behrens (@b-networks) and Stefan Precht (Tallence, Symplasson)', 'Andreas Behrens behrens@b-networks.de, Stefan Precht sprecht@gmx.de', 'sprecht', 'e3ef587f82e1b97b9a51e40d608e4cc5', 'Added some more markers for events. Change a query, because it fails on some environments. Added more localizations. ... See ChangeLog for more details.', '@b-networks, SYMPLASSON GmbH, Tallence GmbH', 1003002, 0, 0),
(18043, 0, 'abcourses', 1, '1.4.0', 1029, 27, 'Seminar management', 'An extension for dealing with seminars and appointments with extensive opportunities for advertising your appointments and for subscribing to them. Developed for execution with PHP4. Offers a hook during the subscribe progress. Implementing a data access', 2, 0, 3, 1221335770, 'a:1:{s:7:"depends";a:2:{s:3:"cms";s:0:"";s:10:"tt_address";s:0:"";}}', 'Andreas Behrens and Stefan Precht', 'Andreas Behrens behrens@b-networks.de, Stefan Precht sprecht@gmx.de', 'sprecht', '78292d947b5a8067d66f9b7d53d10b12', 'Many changes, new features, imrovements, bugfixing, more hooks... See the ChangeLog for details. The timestamp formatting is refactored as well. So dont miss to read the documentation .', '@b-networks, Tallence GmbH, SYMPLASSON GmbH', 1004000, 0, 0),
(18044, 0, 'abcourses', 1, '1.4.1', 1029, 84, 'Seminar management', 'An extension for dealing with seminars and appointments with extensive opportunities for advertising your appointments and for subscribing to them. Developed for execution with PHP4. Offers a hook during the subscribe progress. Implementing a data access', 2, 0, 3, 1221426817, 'a:1:{s:7:"depends";a:2:{s:3:"cms";s:0:"";s:10:"tt_address";s:0:"";}}', 'Andreas Behrens and Stefan Precht', 'Andreas Behrens behrens@b-networks.de, Stefan Precht sprecht@gmx.de', 'sprecht', '422ab66db20d54bf21c23159f130ad50', 'Deleted one duplicated folder... No Code changes to Version 1.4.0: Many changes, new features, imrovements, bugfixing, more hooks... See the ChangeLog for details. The timestamp formatting is refactored as well. So dont miss to read the documentation .', '@b-networks, Tallence GmbH, SYMPLASSON GmbH', 1004001, 0, 0),
(18045, 0, 'abcourses', 1, '1.4.2', 1029, 116, 'Seminar management', 'An extension for dealing with seminars and appointments with extensive opportunities for advertising your appointments and for subscribing to them. Developed for execution with PHP4. Offers a hook during the subscribe progress. Implementing a data access', 2, 0, 3, 1224146354, 'a:1:{s:7:"depends";a:2:{s:3:"cms";s:0:"";s:10:"tt_address";s:0:"";}}', 'Andreas Behrens and Stefan Precht', 'Andreas Behrens behrens@b-networks.de, Stefan Precht sprecht@gmx.de', 'sprecht', 'dca5c448e397f540cce918b6d9ce4b89', 'Fixed a bug within the calculation of the accommodation period. Occured only when switching between daylight saving and standard time.', '@b-networks, Tallence GmbH, SYMPLASSON GmbH', 1004002, 0, 0),
