(18218, 0, 'eepcollect', 1, '1.0.0', 600, 23, 'Pagecollector', 'Visitors can collect pages and add them to their own favorit-list like a basket in a shop. Inclusiv delete and sort functions. It can also show all collected content in one page.', 2, 0, 2, 1241822006, 'a:0:{}', 'Joerg Kummer', 'typo3@enobe.de', 'enobe.de', '248096537a98625222ba3552bd28aedc', ' all collection are written into database\r\n nocache-settings for plugin-object', '', 1000000, 0, 0),
