(18545, 0, 'mailform', 1, '0.8.5', 3387, 41, 'Mailform', 'Supports a multi col system, very good choice of field elements, an add-on platform for third developer, a very usable form wizard and a lot more. For more or detailed information visit: http://mailform.concastic.ch. Check other Mailform Addons: Mailform', 1, -1, 3, 1209342312, 'a:0:{}', 'Sebastian Winterhalder', 'sw@internetgalerie.ch', 'mephistasia', '74c968d71c7f2622cf7458db0dca939d', 'Bugfix: path fixed for mailform_statistics excel download. Documentation updated', '', 8005, 0, 0),
(18546, 0, 'mailform', 1, '0.8.6', 3387, 41, 'Mailform', 'Supports a multi col system, very good choice of field elements, an add-on platform for third developer, a very usable form wizard and a lot more. For more or detailed information visit: http://mailform.concastic.ch. Check out other Mailform Addons.', 1, -1, 3, 1209934517, 'a:0:{}', 'Sebastian Winterhalder', 'sw@internetgalerie.ch', 'mephistasia', '20815990942ba6e82d32df4bb75e15aa', 'New Field Type: Error List. Summarizes all Wrong FE inputs on one field. Addons can be added trough TS Constants. Many other little things updated too.', '', 8006, 0, 0),
(18547, 0, 'mailform', 1, '0.8.7', 3387, 99, 'Mailform', 'Supports a multi col system, very good choice of field elements, an add-on platform for third developer, a very usable form wizard and a lot more. For more or detailed information visit: http://mailform.concastic.ch. Check out other Mailform Addons.', 1, -1, 3, 1210109379, 'a:0:{}', 'Sebastian Winterhalder', 'sw@internetgalerie.ch', 'mephistasia', 'ed8287202f85f7ccd97dd028995bca8d', 'Text-Field supports GET/POST values. Error fixed which occurred while downloading an excel-file. Bug fixed with radio-buttons, the list can be built horizontal or vertical now, as wanted. View Details on Website.', '', 8007, 0, 0),
(18548, 0, 'mailform', 1, '0.8.8', 3387, 35, 'Mailform', 'Supports a multi col system, very good choice of field elements, an add-on platform for third developer, a very usable form wizard and a lot more. For more or detailed information visit: http://mailform.concastic.ch. Check out other Mailform Addons.', 1, -1, 3, 1213802716, 'a:0:{}', 'Sebastian Winterhalder', 'sw@internetgalerie.ch', 'mephistasia', 'd825802f805fb61a9ad35e12341a920a', 'Neuer Feldtyp: Absendebutton mit Bild (DAM, URL), Wizard CSS und Oberflche berarbeitet. Weitere Infos: http://mailform.typo3-extensions.ch', '', 8008, 0, 0),
(18549, 0, 'mailform', 1, '0.8.9', 3387, 25, 'Mailform', 'Simple wizard interface it supports a multi col system, Database storage, very good choice of field elements, an add-on platform for third developer, a very usable form wizard and a lot more. For more or detailed information visit: http://mailform.typo3-e', 1, -1, 3, 1213889085, 'a:0:{}', 'Sebastian Winterhalder', 'sw@internetgalerie.ch', 'mephistasia', '3130e00d1d8f709e6e36c3630071a9c6', 'Added Features to field-types: Radiobuttons, Checkboxes, Dropdown (Pre-Select with GET/POST or specified value in BE and CSV Values for required user inputs).\nFixed a Bug with Language translation.\nFor more Information visit: http://mailform.typo3-extensi', '', 8009, 0, 0),
(18550, 0, 'mailform', 1, '0.8.10', 3387, 35, 'Mailform', 'Simple wizard interface it supports a multi col system, Database storage, very good choice of field elements, an add-on platform for third developer, a very usable form wizard and a lot more. For more or detailed information visit: http://mailform.typo3-e', 1, -1, 3, 1213979572, 'a:0:{}', 'Sebastian Winterhalder', 'sw@internetgalerie.ch', 'mephistasia', '43c1d10f10567dad5b1c02ecd23b93c6', 'Neues Feature: Feldelemente sind nun als Variablen verfgbar (Header / Footer des E-Mails) Hotfix: Wizard funktioniert wieder wie gehabt.', '', 8010, 0, 0),
