(18834, 0, 't3p_scalable', 1, '0.9.1', 170, 10, 'TYPO3 more scalable', 't3p_scalable is a powerful designed extension with the idea to get a TYPO3 to be able to adapt its architecture in scenarios of heavy load. So with this extension you will be able to use MySQL replication and Memcached in transparently or semi-transparent', 1, 0, 4, 1210195249, 'a:0:{}', 'Fernando Arconada', 'fernando.arconada@gmail.com', 'farconada', 'a3b4851ccd80ada322b38c46370abc6c', 'Initial public release.\r\nJust test it and give me feedback, please', '', 9001, 0, 0),
(18835, 0, 't3p_scalable', 1, '0.9.2', 170, 15, 'TYPO3 more scalable', 't3p_scalable is a powerful designed extension with the idea to get a TYPO3 to be able to adapt its architecture in scenarios of heavy load. So with this extension you will be able to use MySQL replication and Memcached in transparently or semi-transparent', 1, 0, 4, 1210227961, 'a:0:{}', 'Fernando Arconada', 'fernando.arconada@gmail.com', 'farconada', '4e398b7796aac4b9d5f6f47fde32665d', 'Added manual', '', 9002, 0, 0),
(18836, 0, 't3p_scalable', 1, '1.0.0', 170, 17, 'TYPO3 more scalable', 't3p_scalable is a powerful designed extension with the idea to get a TYPO3 to be able to adapt its architecture in scenarios of heavy load. So with this extension you will be able to use MySQL replication and Memcached in transparently or semi-transparent', 1, 0, 4, 1211298315, 'a:0:{}', 'Fernando Arconada', 'fernando.arconada@gmail.com', 'farconada', '16a23233b506890636a5c78257009ea0', 'Lots of bugs fixed\nManual updated\nMuch more testing\nMuch scalable\nMemcached coding to avoid dog-pile effect', '', 1000000, 0, 0),
(18837, 0, 't3p_scalable', 1, '1.1.0', 170, 10, 'TYPO3 more scalable', 't3p_scalable is a powerful designed extension with the idea to get a TYPO3 to be able to adapt its architecture in scenarios of heavy load. So with this extension you will be able to use MySQL replication and Memcached in transparently or semi-transparent', 1, 0, 4, 1211406213, 'a:0:{}', 'Fernando Arconada', 'fernando.arconada@gmail.com', 'farconada', 'c4f475e83ab61f5aedfa5c089d49d0ef', 'If TYPO3 cant get a memcached connection then it disables memcached for this script.\nYou could share memcached with serveral application cause keys have a prefix', '', 1001000, 0, 0),
