(18877, 0, 'pmkautokeywords', 1, '1.1.3', 813, 68, 'PMK Autokeywords', 'Generates META keywords from page/content and tt_news records when page/content/news is created or updated. Supports multiple language sites and TemplaVoila', 2, 0, 0, 1240511494, 'a:2:{s:7:"depends";a:5:{s:3:"php";s:11:"5.0.0-0.0.0";s:5:"typo3";s:11:"3.9.9-0.0.0";s:18:"static_info_tables";s:0:"";s:3:"cms";s:0:"";s:4:"lang";s:0:"";}s:9:"conflicts";a:3:{s:12:"autokeywords";s:0:"";s:12:"autokeywordz";s:0:"";s:15:"mc_autokeywords";s:0:"";}}', 'Peter Klein', 'peter@umloud.dk', 'pmk65', 'dd35e2ea9a8b12ccc48e73a1a3de7fe9', 'Now also generates autokeywords for tt_news records. The tt_news keywords is then used on the tt_news SingleView page, instead of Page keywords.', 'Umloud Untd', 1001003, 0, 0),
(18878, 0, 'pmkautokeywords', 1, '1.1.5', 813, 434, 'PMK Autokeywords', 'Generates META keywords from page/content and tt_news records when page/content/news is created or updated. Supports multiple language sites and TemplaVoila', 2, 0, 0, 1247941765, 'a:2:{s:7:"depends";a:5:{s:3:"php";s:11:"5.0.0-0.0.0";s:5:"typo3";s:11:"3.9.9-0.0.0";s:18:"static_info_tables";s:0:"";s:3:"cms";s:0:"";s:4:"lang";s:0:"";}s:9:"conflicts";a:3:{s:12:"autokeywords";s:0:"";s:12:"autokeywordz";s:0:"";s:15:"mc_autokeywords";s:0:"";}}', 'Peter Klein', 'peter@umloud.dk', 'pmk65', '366b748df4f6a896e0175fa1cfa7f9f6', 'Summer update! ;) - See manual for list of changes/bug fixes.', 'Umloud Untd', 1001005, 1, 0),
(18879, 0, 'gimmefive', 1, '0.0.3', 357, 357, 'Some backported Aspects of FLOW3', 'A Backport of some aspects of FLOW3: component manager, object cache, dependency injection (constructor), auto wiring. Example Package included. Requires at least PHP 5.2', 0, 0, 4, 1210691267, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"5.2.0-0.0.0";s:5:"typo3";s:11:"4.0.0-0.0.0";}}', 'Jochen Rau', 'jochen.rau@typoplanet.de', 'jocrau', '0bc8cf240387d289fa933ff8b2466895', 'Initial upload to TER', 'typoplanet', 3, 1, 0),
