(18956, 0, 'flvplayer2', 1, '1.2.1', 3664, 744, 'Flash Video Player v2', 'This Flash Video (FLV) Player allows you to show your videos more controlled and to a broader audience as with Quicktime, Windows Media or Real Media. This extension is based and backwards-compatible with extension flvplayer, adding standards compliance a', 2, 0, 3, 1247646888, 'a:2:{s:7:"depends";a:5:{s:5:"typo3";s:11:"3.5.0-0.0.0";s:3:"php";s:11:"4.0.0-0.0.0";s:3:"cms";s:0:"";s:4:"lang";s:0:"";s:11:"api_macmade";s:0:"";}s:9:"conflicts";a:1:{s:9:"flvplayer";s:11:"0.0.0-0.9.0";}}', 'Jose Antonio Guerra', 'jaguerra@icti.es', 'balderiano', '2824551e074abd446ae4bd152c5ec59a', ' Now validates XHTML Strict (thanks to Emile Blume from Netcreators)\r\n Improved the url TS parameter (thanks to Loek Hilgersom)\r\n Bugfix: Now the fullscreen switch works (thanks to Maxim Levicky)', 'ICTI Consulting', 1002001, 0, 0),
(18957, 0, 'flvplayer2', 1, '1.3.0', 3664, 1892, 'Flash Video Player v2 (FLV and MP4)', 'This Video Player allows you to show your MP4 or FLV videos to a broader audience as with Quicktime, Windows Media or Real Media. This extension is based and backwards-compatible with extension flvplayer, adding standards compliance and an updated player ', 2, 0, 3, 1282307853, 'a:2:{s:7:"depends";a:5:{s:5:"typo3";s:11:"3.5.0-0.0.0";s:3:"php";s:11:"4.0.0-0.0.0";s:3:"cms";s:0:"";s:4:"lang";s:0:"";s:11:"api_macmade";s:0:"";}s:9:"conflicts";a:1:{s:9:"flvplayer";s:11:"0.0.0-0.9.0";}}', 'Jose Antonio Guerra', 'jaguerra@icti.es', 'balderiano', '32b4492c80d9338325b71a5fc4f11264', '	 version 1.3.0 - Upload to TER\r\n	 Added support for FlowPlayer (3.1)\r\n	 Upgraded JW Player to version 5\r\n	 Added base configuration (thanks to Sacha Vorbeck).\r\n	 Added codebase https support (thanks to Guillaume Crico).	\r\n	 Splash image now is ', 'ICTI Internet Passion', 1003000, 0, 0),
(18958, 0, 'flvplayer2', 1, '1.4.0', 3664, 0, 'Flash Video Player v2 (FLV, MP4, Youtube and Vimeo', 'This Video Player allows you to show your MP4 or FLV videos to a broader audience as with Quicktime, Windows Media or Real Media. This extension is based and backwards-compatible with extension flvplayer, adding standards compliance, an updated player (JW Player or Flowplayer) and improved support for YouTube and Vimeo.', 2, 0, 3, 1421755025, 'a:2:{s:7:"depends";a:1:{s:5:"typo3";s:12:"4.5.0-6.2.99";}s:9:"conflicts";a:1:{s:9:"flvplayer";s:11:"0.0.0-0.9.0";}}', 'Jose Antonio Guerra', 'jaguerra@icti.es', 'balderiano', 'e044aa3d03e3c93b67beffc7f4365790', ' Compatibility with TYPO3 4.5-6.2\r\n No longer depends on EXT:api_macmade\r\n Enhanced support for Youtube and Vimeo\r\n', 'ICTI Internet Passion', 1004000, 1, 0),
(18959, 0, 'crimson_banners', 1, '1.0.1', 163, 163, 'Advanced Banner Statistics', 'Shows banners statistics in the Backend e.g. user ip, banner clicks, impressions and others. Extends Advanced Banner Management Tool. Adds Ip checking functionality. Public free support is provided only through TYPO3 mailing lists! Contact by e-mail for c', 2, 0, 3, 1211421701, 'a:0:{}', 'Pavel Kruglov', 'Pavel@Kruglov.biz', 'taranis', '7b7dc92617a256de88d17decf2ef85f9', '', 'Crimson Sky', 1000001, 1, 0),
(18960, 0, 'phploadavg', 1, '0.1.0', 217, 7, 'phploadavg', 'Display a real-time chart of server load (performance).', 2, 0, 3, 1211502525, 'a:0:{}', 'Ukraine', 'slapidya@yahoo.com', 'ukraine', '6b94175d4f68ca64c92107a06980737b', '- Initial release. Only working in FE. Installation: put the FE plugin on the page and have a look. Pre-configured to generate GIFs (requires GDlib). Can be switched to make graph with HTML tables.', '', 1000, 0, 0),
