(18963, 0, 'phploadavg', 1, '0.4.0', 217, 133, 'phploadavg', 'Display a real-time chart of server load (performance).\n		Working from BE or FE or as a mydashboard plugin.\n		Installation: put the FE plugin on the page and have a look. \n		Pre-configured to generate GIFs (requires GDlib). \n		Can be switched to make grap', 2, 0, 3, 1212191024, 'a:0:{}', 'Ukraine', 'slapidya@yahoo.com', 'ukraine', 'd9638afee7fed476145aeec245666fa7', 'ADD link to live demo to manual\r\nADD BE module\r\nADD phploadavg as mydashboard widged\r\nADD feature to refresh GIF without refreshing whole page', '', 4000, 1, 0),
