INSERT INTO `tx_extensionmanager_domain_model_extension` (`uid`, `pid`, `extension_key`, `repository`, `version`, `alldownloadcounter`, `downloadcounter`, `title`, `description`, `state`, `review_state`, `category`, `last_updated`, `serialized_dependencies`, `author_name`, `author_email`, `ownerusername`, `md5hash`, `update_comment`, `authorcompany`, `integer_version`, `current_version`, `lastreviewedversion`) VALUES
(18987, 0, 'cgswigmore', 1, '0.1.1', 207, 8, 'Swigmore institute', 'manage staff of the institute. You can manage the location, different sections/working groups and staff members. Each section/work group can have different publications, their own sections staff members and a sections description.', 0, -1, 3, 1211831917, 'a:1:{s:7:"depends";a:1:{s:3:"cms";s:0:"";}}', 'Christoph Gostner', 'christoph.gostner@gmail.com', 'moe-pub', '2658b4fa73e2757ebf58252f66b8b750', 'small changes, first version of documentation completed.', '', 1001, 0, 0),
(18988, 0, 'cgswigmore', 1, '0.1.2', 207, 11, 'Swigmore institute', 'manage locations, publications, staff and so on', 0, 0, 3, 1213897937, 'a:1:{s:7:"depends";a:1:{s:3:"cms";s:0:"";}}', 'Christoph Gostner', 'christoph.gostner@gmail.com', 'moe-pub', 'a4c264ca2a621ad59619f6aeb5b932a3', 'Bug-Fix release (sql injections)', '', 1002, 0, 0),
(18989, 0, 'cgswigmore', 1, '0.1.3', 207, 8, 'Swigmore institute', 'manage locations, publications, staff and so on', 0, 0, 3, 1213949780, 'a:1:{s:7:"depends";a:1:{s:3:"cms";s:0:"";}}', 'Christoph Gostner', 'christoph.gostner@gmail.com', 'moe-pub', '4752eed11f74dd05af34fb4ecd064677', 'This version fixes a problem with the previous (archived) staff members, when the staffs section is disabled.', '', 1003, 0, 0),
(18990, 0, 'cgswigmore', 1, '0.1.4', 207, 9, 'Swigmore institute', 'manage locations, publications, staff and so on', 0, 0, 3, 1213961052, 'a:1:{s:7:"depends";a:1:{s:3:"cms";s:0:"";}}', 'Christoph Gostner', 'christoph.gostner@gmail.com', 'moe-pub', 'af5b1f1b755665277d3ff4f8b8f19085', ' Finally added the location to display locations information about your institute\r\n Fixed an error caused by the archived staff members, when the staff members section was set offline, \r\n  the staff member shouldnt be displayed in the archived staff', 'Tyrolean Cancer Research Institute', 1004, 0, 0),
(18991, 0, 'cgswigmore', 1, '0.1.5', 207, 14, 'Swigmore institute', 'manage locations, publications, staff and so on', 0, 0, 3, 1213975210, 'a:1:{s:7:"depends";a:1:{s:3:"cms";s:0:"";}}', 'Christoph Gostner', 'christoph.gostner@gmail.com', 'moe-pub', 'b85a30ee828139061c3212d7fb2ecd08', 'Fixed a problem with the sql query in the new part of the location.', 'Tyrolean Cancer Research Institute', 1005, 0, 0),
(18992, 0, 'cgswigmore', 1, '0.2.0', 207, 2, 'Swigmore institute', 'manage locations, publications, staff and so on', 0, 0, 3, 1215860330, 'a:1:{s:7:"depends";a:1:{s:3:"cms";s:0:"";}}', 'Christoph Gostner', 'christoph.gostner@gmail.com', 'moe-pub', '49e405e4b4e319f31fb2a0ba24e56693', ' added the userFunc possibilty for the publications\r\n added a file item to the publications that can be linked and/or added to the publication\r\n added an iconset, thanks to roy scholten (http://www.yoroy.com/)\r\n added a switcher for the job view to vi', '', 2000, 0, 0),
(18993, 0, 'cgswigmore', 1, '0.3.0', 207, 15, 'Swigmore institute', 'manage locations, publications, staff and so on', 0, 0, 3, 1215863463, 'a:1:{s:7:"depends";a:1:{s:3:"cms";s:0:"";}}', 'Christoph Gostner', 'christoph.gostner@gmail.com', 'moe-pub', '01cf53ec9ca5c1038969ebdf28d780ed', 'added a file item to the job', '', 3000, 0, 0),
(18994, 0, 'cgswigmore', 1, '0.4.0', 207, 4, 'Swigmore institute', 'manage locations, publications, staff and so on', 0, 0, 3, 1216249532, 'a:1:{s:7:"depends";a:1:{s:3:"cms";s:0:"";}}', 'Christoph Gostner', 'christoph.gostner@gmail.com', 'moe-pub', '9470114ecfbc4b23bcfba4aa6a3eb93c', '	 added a optional dependence to a SysFolder to the STAFFs option that can be enabled via TypoScript. \r\n	 Added a new marker to the staffs list view. Now the sections names behind a person can be linked to the sections 	  page, simply replace set th', '', 4000, 0, 0),
