(19035, 0, 'kk_csv2table', 1, '0.0.1', 222, 24, 'From a csv-file to a html-table', 'reads a csv-file and creates a html-table in the dedicated page-part', 0, -1, 2, 1212492034, 'a:0:{}', 'Kurt Kunig', 'kurt.kunig@kupix.de', 'kurt51', 'fa19c4a752944d6fb548e32b90a17441', 'Initial release', 'kupix web-design, Internet: http://www.kupix.de', 1, 0, 0),
(19036, 0, 'kk_csv2table', 1, '0.1.0', 222, 34, 'From a csv-file to a html-table', 'reads a csv-file and creates a html-table in the dedicated page-part', 0, -1, 2, 1212593257, 'a:0:{}', 'Kurt Kunig', 'kurt.kunig@kupix.de', 'kurt51', 'dbb109342e6aa2a450e7177bc53bfd5b', '1. 2 flexform fields more: own column-headers and table class (if desired)  \r\n2. empty rows will be ignored  \r\n3. max. csv- or txt-file-size  5 MB  \r\n4. last td-tag with colspan if the one or other row has less cols than maximum cols', 'kupix web-design, Internet: http://www.kupix.de', 1000, 0, 0),
(19037, 0, 'kk_csv2table', 1, '0.1.1', 222, 61, 'From a csv-file to a html-table', 'Very simple! Input:csv-(txt-)file  2 params; output:html-table - CType-Ext. incl. flexform - demo: http://www.kupix.de/service/typo3-snippets-ext/ext-kk-csv2table.html!', 1, -1, 2, 1213978212, 'a:0:{}', 'Kurt Kunig', 'kurt.kunig@kupix.de', 'kurt51', '032fe3ad78c53c21eb41ccb4818085a8', '1.) 2 more flexform fields: File incl. path rel. to fileadmin and Text delimiter (if desired)\r\n\r\n2.) Tabs as delimiters are allowed, take [T] as the delimiter-sign\r\n\r\n3.) doesnt matter if utf-8- or ANSIcoded input data\r\n\r\n4.) Line-feed within a c', 'kupix web-design, Internet: http://www.kupix.de', 1001, 0, 0),
(19038, 0, 'kk_csv2table', 1, '0.2.0', 222, 7, 'From a csv-file to a html-table', 'Very simple! Input:csv-(txt-)file  2 params; output:html-table - CType-Ext. incl. flexform - demo: http://www.kupix.de/service/typo3-snippets-ext/ext-kk-csv2table.html!', 1, -1, 2, 1245407666, 'a:0:{}', 'Kurt Kunig', 'kurt.kunig@kupix.de', 'kurt51', 'fc94c0947c9bc1a24d53025828955241', '1 more flexform field: CSV-Code - select-field;\r\nfield: UTF8 encode is now a select-field;\r\nconvert html with htmlentities(...  direct Code-parameters);\r\nThanks to Daniel Minder for the support', 'kupix web-design, Internet: http://www.kupix.de', 2000, 0, 0),
(19039, 0, 'kk_csv2table', 1, '0.1.2', 222, 9, 'From a csv-file to a html-table', 'Very simple! Input:csv-(txt-)file  2 params; output:html-table - CType-Ext. incl. flexform - demo: http://www.kupix.de/service/typo3-snippets-ext/ext-kk-csv2table.html!', 1, -1, 2, 1245173514, 'a:0:{}', 'Kurt Kunig', 'kurt.kunig@kupix.de', 'kurt51', '73f3f86fd5e0268f68c2810d8c3dbaac', '1 more flexform field: UTF8 encode Yes or No;\r\nminor bugs fixed: Column-Delimiter within a text;\r\nconvert html with htmlentities(...);\r\nThanks to Daniel Minder (University of Bonn, Institute of Computer Science IV) for the hints!', 'kupix web-design, Internet: http://www.kupix.de', 1002, 0, 0),
(19040, 0, 'kk_csv2table', 1, '0.2.1', 222, 72, 'From a csv-file to a html-table', 'Very simple! Input:csv-(txt-)file  2 params; output:html-table - CType-Ext. incl. flexform - demo: http://www.kupix.de/service/typo3-snippets-ext/ext-kk-csv2table.html!', 1, -1, 2, 1245490825, 'a:0:{}', 'Kurt Kunig', 'kurt.kunig@kupix.de', 'kurt51', '7c675014d2a502546481922823a786b1', 'minor bugfix, correction of manual', 'kupix web-design, Internet: http://www.kupix.de', 2001, 0, 0),
(19041, 0, 'kk_csv2table', 1, '0.2.2', 222, 15, 'From a csv-file to a html-table', 'Very simple! Input:csv-(txt-)file  2 params; output:html-table - CType-Ext. incl. flexform - demo: http://www.kupix.de/service/typo3-snippets-ext/ext-kk-csv2table.html!', 1, -1, 2, 1330948875, 'a:0:{}', 'Kurt Kunig', 'kurt.kunig@kupix.de', 'kurt51', '9659ee8784eb8a05e634c375ef646f9a', 'end bracket of an allowed tag was not decoded, so the tag ended with a "&gt;" instead', 'kupix web-design, Internet: http://www.kupix.de', 2002, 0, 0),
