(19196, 0, 'rs_linklayout', 1, '1.2.2', 617, 12, 'Linklayout with filetype and target icon', 'Shows an icon with the filetype for all links made in RTE. \n                    It is an very extended version of "dh_linklayout" by Dirk Hoffmann.\n                    So it also provides the functionality to different format internal, external and mailto', 2, 0, 2, 1226623450, 'a:2:{s:7:"depends";a:2:{s:5:"typo3";s:11:"3.5.0-0.0.0";s:3:"php";s:11:"4.1.0-0.0.0";}s:9:"conflicts";a:1:{s:13:"dh_linklayout";s:5:"0.0.0";}}', 'Rene', 'typo3@rs-softweb.de', 'rene-s', 'fffd3654442dac141c62ee5a9e265e7f', '- email address of "Dirk Hoffmann" from extension description removed (his own wish)\r\n- the extension manual has been updated to new manual template', '', 1002002, 0, 0),
(19197, 0, 'rs_linklayout', 1, '1.3.0', 617, 41, 'Linklayout with filetype and target icon', 'Shows an icon with the filetype for all links made in RTE. \n                    It is an very extended version of "dh_linklayout" by Dirk Hoffmann.\n                    So it also provides the functionality to different format internal, external and mailto', 2, 0, 2, 1228510234, 'a:2:{s:7:"depends";a:2:{s:5:"typo3";s:11:"3.5.0-0.0.0";s:3:"php";s:11:"4.1.0-0.0.0";}s:9:"conflicts";a:1:{s:13:"dh_linklayout";s:0:"";}}', 'Rene', 'typo3@rs-softweb.de', 'rene-s', '615c433e112a8be532ae461fff831e27', 'READ manual if you update from versions before 1.3.0!! Changed TS-Config vars from "plugin.tx_rs_linklayout." to "plugin.tx_rslinklayout." and renamed the class from "tx_rs_linklayout" to "tx_rslinklayout". Added short user manual', '', 1003000, 0, 0),
(19198, 0, 'rs_linklayout', 1, '1.3.1', 617, 243, 'Linklayout with filetype and target icon', 'Shows an icon with the filetype for all links made in RTE. \n                    It also provides the functionality to format internal, external and mailto links in different styles.', 2, 0, 2, 1241653619, 'a:2:{s:7:"depends";a:2:{s:5:"typo3";s:11:"3.5.0-0.0.0";s:3:"php";s:11:"4.1.0-0.0.0";}s:9:"conflicts";a:1:{s:13:"dh_linklayout";s:0:"";}}', 'Rene', 'typo3@rs-softweb.de', 'rene-s', 'b04018cb34c82b24e79479478baa0d2c', 'Search paths for the filetype icons are now customizable. Added new config var "linkFiletypePaths".', '', 1003001, 0, 0);
INSERT INTO `tx_extensionmanager_domain_model_extension` (`uid`, `pid`, `extension_key`, `repository`, `version`, `alldownloadcounter`, `downloadcounter`, `title`, `description`, `state`, `review_state`, `category`, `last_updated`, `serialized_dependencies`, `author_name`, `author_email`, `ownerusername`, `md5hash`, `update_comment`, `authorcompany`, `integer_version`, `current_version`, `lastreviewedversion`) VALUES
(19199, 0, 'rs_linklayout', 1, '1.3.2', 617, 0, 'Linklayout with filetype and target icon', 'Shows an icon with the filetype for all links made in RTE. \n                    It also provides the functionality to format internal, external and mailto links in different styles.', 2, 0, 2, 1363044232, 'a:2:{s:7:"depends";a:2:{s:5:"typo3";s:12:"4.5.0-4.7.99";s:3:"php";s:11:"4.1.0-0.0.0";}s:9:"conflicts";a:1:{s:13:"dh_linklayout";s:0:"";}}', 'Rene', 'typo3@rs-softweb.de', 'rene-s', 'eda6ce014a1c7ab967d4dd452994d5b8', 'fixed Typo3 dependency in ext_emconf', '', 1003002, 0, 0),
(19200, 0, 'rs_linklayout', 1, '1.4.0', 617, 0, 'Linklayout with filetype and target icon', 'Shows an icon with the filetype for all links made in RTE. It also provides the functionality to format internal, external and mailto links in different styles.', 2, 0, 2, 1406734329, 'a:2:{s:7:"depends";a:2:{s:5:"typo3";s:12:"4.5.0-6.2.99";s:3:"php";s:11:"4.1.0-0.0.0";}s:9:"conflicts";a:1:{s:13:"dh_linklayout";s:0:"";}}', 'Rene', 'typo3@rs-softweb.de', 'rene-s', '368d7383a7197099a8836ae4078a0ce5', 'added v6.2 compatibility - v6.0 and v6.1 branch compatibility is UNTESTED \nalso worked on CGL Compliance', '', 1004000, 1, 0),
(19201, 0, 'mh_httpbl', 1, '1.0.0', 252, 8, 'http:BL Blocking', 'Implements', 2, -1, 4, 1212839790, 'a:0:{}', 'Marc Hoersken', 'info@marc-hoersken.de', 'mback2k', 'd361b15c5ff15cd2f17b9712e1b9ef1b', 'Initial release.', '', 1000000, 0, 0),
(19202, 0, 'mh_httpbl', 1, '1.0.1', 252, 17, 'http:BL Blocking', 'Implements the http:BL blocking into TYPO3. Block spam bots and other "bad users" from your websites. More information at httpbl.org', 2, -1, 4, 1212841092, 'a:0:{}', 'Marc Hoersken', 'info@marc-hoersken.de', 'mback2k', 'f8e4bec39f4ccb51a583a302bd43eeef', 'Fixed small typos and added ext icon.', '', 1000001, 0, 0),
(19203, 0, 'mh_httpbl', 1, '1.1.0', 252, 64, 'http:BL Blocking', 'Implements the http:BL blocking into TYPO3. Block spam bots and other "bad users" from your websites. More information at httpbl.org', 2, -1, 4, 1212877709, 'a:0:{}', 'Marc Hoersken', 'info@marc-hoersken.de', 'mback2k', '586cda67b68c5c97ba10ac4ff4dae89a', 'Added backend module to manage block log and whitelisting. Blocked users are now logged to database and erased after one week. You can now whitelist IPs and stop them from being blocked. Added an easy option to add a Honey Pot link to your websites.', '', 1001000, 0, 0),
(19204, 0, 'mh_httpbl', 1, '1.1.1', 252, 9, 'http:BL Blocking', 'Implements the http:BL blocking into TYPO3. Block spam bots and other "bad users" from your websites. More information at httpbl.org', 2, -1, 4, 1228164197, 'a:0:{}', 'Marc Hoersken', 'info@marc-hoersken.de', 'mback2k', '1fd40e769ff05d9de0051ca891329ef9', 'Updated icons and manual to the new layout.', '', 1001001, 0, 0),
(19205, 0, 'mh_httpbl', 1, '1.1.2', 252, 9, 'http:BL Blocking', 'Implements the http:BL blocking into TYPO3. Block spam bots and other "bad users" from your websites. More information at httpbl.org', 2, -1, 4, 1229021287, 'a:0:{}', 'Marc Hoersken', 'info@marc-hoersken.de', 'mback2k', 'e75f2cd81b75fce71a1c9656d480c3fd', 'Fixed typo in class.tx_mhhttpbl.php that broke the extension! (thanks Jens)', '', 1001002, 0, 0),
(19206, 0, 'mh_httpbl', 1, '1.1.3', 252, 8, 'http:BL Blocking', 'Implements the http:BL blocking into TYPO3. Block spam bots and other "bad users" from your websites. More information at httpbl.org', 2, -1, 4, 1229183094, 'a:0:{}', 'Marc Hoersken', 'info@marc-hoersken.de', 'mback2k', '1943e4978a789993242e397332863283', 'Fixed invalid log entries and stopped blocking if no accesskey was set. (thanks Julian)', '', 1001003, 0, 0),
(19207, 0, 'mh_httpbl', 1, '1.1.4', 252, 15, 'http:BL Blocking', 'Implements the http:BL blocking into TYPO3. Block spam bots and other "bad users" from your websites. More information at httpbl.org', 2, -1, 4, 1229281822, 'a:0:{}', 'Marc Hoersken', 'info@marc-hoersken.de', 'mback2k', 'bd446629492e42aee85b3473f76debbe', 'Added link to delete all entries from the block log. Handling block entries per IP and not ID. (thanks Jens)', '', 1001004, 0, 0),
(19208, 0, 'mh_httpbl', 1, '1.1.5', 252, 48, 'http:BL Blocking', 'Implements the http:BL blocking into TYPO3. Block spam bots and other "bad users" from your websites. More information at httpbl.org', 2, -1, 4, 1229697576, 'a:0:{}', 'Marc Hoersken', 'info@marc-hoersken.de', 'mback2k', '03479475685ced174ccecca8f8dc9f6d', 'Added Javascript to redirect false-positives (human people). The block page is now outputted through TYPO3.', '', 1001005, 0, 0),
(19209, 0, 'mh_httpbl', 1, '1.1.6', 252, 74, 'http:BL Blocking', 'Implements the http:BL blocking into TYPO3. Block spam bots and other "bad users" from your websites. More information at httpbl.org', 2, -1, 4, 1267278322, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"3.0.0-0.0.0";s:5:"typo3";s:11:"3.5.0-0.0.0";}}', 'Marc Hoersken', 'info@marc-hoersken.de', 'mback2k', '76b96efc8fa18d84ee955f0492726d7b', 'Made quicklink HTML use TYPO3 for rendering. (thanks Jigal)  New function mod to view unique list of blocked IPs. (thanks Myroslav)  Made all table views in the backend sortable by table header.', '', 1001006, 0, 0),
(19210, 0, 'mh_httpbl', 1, '1.1.7', 252, 0, 'http:BL Blocking', 'Implements the http:BL blocking into TYPO3. Block spam bots and other "bad users" from your websites. More information at httpbl.org', 2, -1, 4, 1378485015, 'a:0:{}', 'Marc Hoersken', 'info@marc-hoersken.de', 'mback2k', '28680cac2c1e0e62de77b17673d8b32c', 'Updated for TYPO3 6.0.', '', 1001007, 0, 0),
(19211, 0, 'mh_httpbl', 1, '1.1.8', 252, 0, 'http:BL Blocking', 'Implements the http:BL blocking into TYPO3. Block spam bots and other "bad users" from your websites. More information at httpbl.org', 2, 0, 4, 1464686316, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"4.5.0-6.0.99";}}', 'Marc Hoersken', 'info@marc-hoersken.de', 'mback2k', 'd852315ad149b0a7a4604b0a8f04b8df', 'Security Fix PLEASE UPDATE See: https://typo3.org/teams/security/security-bulletins/typo3-extensions/typo3-ext-sa-2016-016/ for details nc ', '', 1001008, 0, 0),
(19212, 0, 'mh_httpbl', 1, '1.1.9', 252, 0, 'http:BL Blocking', 'Implements the http:BL blocking into TYPO3. Block spam bots and other "bad users" from your websites. More information at httpbl.org', 2, 0, 4, 1469871601, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"4.3.0-0.0.0";s:5:"typo3";s:12:"4.0.0-6.2.99";}}', 'Marc Hoersken', 'info@marc-hoersken.de', 'mback2k', '33232ecd215d8e2643ac71d07012cd22', 'Updated for TYPO3 6.2.\r\n\r\nFix TYPO3-EXT-SA-2015-021: SQL Injection. (thanks Nicole Cordes)\r\nFix TYPO3-EXT-SA-2016-016: Cross-Site Scripting. (thanks Nicole Cordes)\r\nFix deprecation notice exception by using fullQuoteStr instead.', '', 1001009, 1, 0),
(19213, 0, 'myquizpoll', 1, '0.1.1', 1732, 36, 'My quiz and poll', 'A quiz with a highscore list and a basic poll', 1, -1, 3, 1212865564, 'a:0:{}', 'Kurt Gusbeth', 'gusbeth@aol.com', 'bihor', 'ef43811a1b7cae8dae979b433b94073f', 'First upload of this quiz.', '', 1001, 0, 0),
