(19215, 0, 'myquizpoll', 1, '0.1.3', 1732, 28, 'My quiz and poll', 'A quiz with a highscore list and a basic poll', 1, -1, 3, 1215882080, 'a:0:{}', 'Kurt Gusbeth', 'gusbeth@aol.com', 'bihor', 'e1188f87c2aaaf220bd100a8668199ea', 'New property and markers for points added. Please read the changelog in the manual.', '', 1003, 0, 0),
(19216, 0, 'myquizpoll', 1, '0.1.4', 1732, 54, 'My quiz and poll', 'A quiz with a highscore list and a basic poll', 1, -1, 3, 1217365236, 'a:0:{}', 'Kurt Gusbeth', 'gusbeth@aol.com', 'bihor', '115e3066a6ba959dd1fe17d001ca2d23', 'security fix, please update...', '', 1004, 0, 0),
(19217, 0, 'myquizpoll', 1, '0.1.5', 1732, 81, 'My quiz and poll', 'A quiz with a highscore list and a basic poll', 1, -1, 3, 1220794478, 'a:0:{}', 'Kurt Gusbeth', 'gusbeth@aol.com', 'bihor', '34166624d18a96a3ed76cd8afedbe96c', 'Some exotic bugfixes und some new features.', '', 1005, 0, 0),
(19218, 0, 'myquizpoll', 1, '0.1.6', 1732, 12, 'My quiz and poll', 'A quiz with a highscore list and a basic poll', 2, -1, 3, 1228342807, 'a:0:{}', 'Kurt Gusbeth', 'info@myquizandpoll.de', 'bihor', '9b2b088a28b326a65935852df599c901', 'New features:\r\n- localization\r\n- text-field for answers\r\n- more layout possibilities on the final page\r\n- some minor bugs fixed', '', 1006, 0, 0),
(19219, 0, 'myquizpoll', 1, '0.1.7', 1732, 15, 'My quiz and poll', 'An advanced quiz with a lot of features (e.g. highscore list, multi-page, multi-lingual) and a basic poll', 2, -1, 3, 1232916799, 'a:0:{}', 'Kurt Gusbeth', 'info@myquizandpoll.de', 'bihor', '78829af1a25391d660487017146245e8', 'New features: \r\n- Possibility to show answers and questions on two different pages.\r\n- Possibility to show a result page which depends on reached points.\r\n- Possibility to cancel a quiz when a minimum percentage is reached.', '', 1007, 0, 0),
(19220, 0, 'myquizpoll', 1, '0.2.0', 1732, 12, 'My quiz and poll', 'An advanced quiz with a lot of features (e.g. highscore list, multi-page, multi-lingual) and a basic poll', 2, -1, 3, 1235599286, 'a:0:{}', 'Kurt Gusbeth', 'info@myquizandpoll.de', 'bihor', 'b18c958046e3fb57a616820ad6568e14', 'New features: more layout possibilities and time control. Bug fix: empty sys_language_uid was a big problem.', '', 2000, 0, 0),
(19221, 0, 'myquizpoll', 1, '0.2.1', 1732, 17, 'My quiz and poll', 'An advanced quiz with a lot of features (e.g. highscore list, multi-page, multi-lingual) and a basic poll', 2, -1, 3, 1238020964, 'a:0:{}', 'Kurt Gusbeth', 'info@myquizandpoll.de', 'bihor', '0098867b663cb39a7ee0231588252915', 'New poll features and some other minor things.', '', 2001, 0, 0),
(19222, 0, 'myquizpoll', 1, '0.2.2', 1732, 14, 'My quiz and poll', 'An advanced quiz with a lot of features (e.g. highscore list, multi-page, multi-lingual) and a basic poll', 2, -1, 3, 1245448543, 'a:0:{}', 'Kurt Gusbeth', 'info@myquizandpoll.de', 'bihor', '8b1287689fa5320a9d279572d0108e1e', 'New: jokers (if you have xajax and UTF-8); a lot of markers and TS variables; e.g. questions can be put back.', '', 2002, 0, 0),
(19223, 0, 'myquizpoll', 1, '0.3.0', 1732, 49, 'My quiz and poll', 'An advanced quiz with a lot of features (e.g. highscore list, multi-page, multi-lingual, jokers) and a basic poll', 2, -1, 3, 1251921367, 'a:0:{}', 'Kurt Gusbeth', 'info@myquizandpoll.de', 'bihor', '137eb5fa47b2b4d5738081224b9b58f3', 'A lot of new features added (see changelog in the documentation). defaultConfigs removed. Import the new defaultSettings!', '', 3000, 0, 0),
(19224, 0, 'myquizpoll', 1, '0.4.0', 1732, 157, 'My quiz and poll', 'An advanced quiz with a lot of features (e.g. highscore list, multi-page, multi-lingual, jokers) and a basic poll', 2, -1, 3, 1256107963, 'a:0:{}', 'Kurt Gusbeth', 'info@myquizandpoll.de', 'bihor', 'badef07b5ae464d553a6a4d7d680c218', '2 Bugs fixed and a few new features (e.g. enter user data only once).', '', 4000, 0, 0),
(19225, 0, 'myquizpoll', 1, '1.0.0', 1732, 61, 'My quiz and poll', 'An advanced quiz with a lot of features (e.g. highscore list, multi-page, multi-lingual, jokers) and a basic poll', 2, -1, 3, 1262114987, 'a:0:{}', 'Kurt Gusbeth', 'info@myquizandpoll.de', 'bihor', '174060b7721c657f8bb235dd54d8b36b', 'Backend module added. New features. DB improvements. Some minor bugs fixed. Please read the changelog in the manual and execute the update skript!', '', 1000000, 0, 0),
(19226, 0, 'myquizpoll', 1, '1.0.1', 1732, 114, 'My quiz and poll', 'An advanced quiz with a lot of features (e.g. highscore list, multi-page, multi-lingual, jokers) and a basic poll', 2, -1, 3, 1263155375, 'a:0:{}', 'Kurt Gusbeth', 'info@myquizandpoll.de', 'bihor', '0f7eb7ff15c1858ffa188705ac8b50fc', '3 (minor) bugs fixed...', '', 1000001, 0, 0),
(19227, 0, 'myquizpoll', 1, '1.1.0', 1732, 55, 'My quiz and poll', 'An advanced quiz with a lot of features (e.g. highscore list, multi-page, multi-lingual, jokers) which can be used as a quiz, questionnaire, survey, poll or psychological test', 2, -1, 3, 1266501740, 'a:1:{s:7:"depends";a:1:{s:3:"cms";s:0:"";}}', 'Kurt Gusbeth', 'info@myquizandpoll.de', 'bihor', '6c9872594f037e5841966c2b150a1d25', 'Some new features (e.g. CSV-import) and one bugfix.', '', 1001000, 0, 0),
(19228, 0, 'myquizpoll', 1, '1.2.0', 1732, 6, 'My quiz and poll', 'An advanced quiz with a lot of features (e.g. highscore list, multi-page, multi-lingual, jokers) which can be used as a quiz, questionnaire, survey, poll or psychological test', 2, -1, 3, 1272230148, 'a:1:{s:7:"depends";a:1:{s:3:"cms";s:0:"";}}', 'Kurt Gusbeth', 'info@myquizandpoll.de', 'bihor', 'b69fb978cfa2043ece0e3e549bff7f30', 'Import and export added. More languages added. Some improvements.', '', 1002000, 0, 0),
(19229, 0, 'myquizpoll', 1, '1.2.3', 1732, 139, 'My quiz and poll', 'An advanced quiz with a lot of features (e.g. highscore list, multi-page, multi-lingual, jokers) which can be used as a quiz, questionnaire, survey, poll or psychological test', 2, -1, 3, 1273563626, 'a:1:{s:7:"depends";a:1:{s:3:"cms";s:0:"";}}', 'Kurt Gusbeth', 'info@myquizandpoll.de', 'bihor', '3c59b7762be915860ea745e52bbde08f', 'Deprecated functions replaced. Please update.', '', 1002003, 0, 0),
(19230, 0, 'myquizpoll', 1, '1.3.0', 1732, 161, 'My quiz and poll', 'An advanced quiz with a lot of features (e.g. highscore list, multi-page, multi-lingual, jokers) which can be used as a quiz, questionnaire, survey, poll or psychological test', 2, -1, 3, 1289204953, 'a:0:{}', 'Kurt Gusbeth', 'info@myquizandpoll.de', 'bihor', 'f1ea305e4482806f53c2df4cfff5c528', 'Several small new features and changes.', '', 1003000, 0, 0),
(19231, 0, 'myquizpoll', 1, '1.4.0', 1732, 122, 'My quiz and poll', 'An advanced quiz with a lot of features (e.g. highscore list, multi-page, multi-lingual, jokers) which can be used as a quiz, questionnaire, survey, poll, rating or psychological test', 2, -1, 3, 1296253117, 'a:0:{}', 'Kurt Gusbeth', 'info@myquizandpoll.de', 'bihor', '81440ddc32051768d8c3349ebbb8e8f1', 'Rating possibility added. Bug with Typo3 4.3.x fixed.', '', 1004000, 0, 0),
(19232, 0, 'myquizpoll', 1, '1.5.0', 1732, 66, 'My quiz and poll', 'An advanced quiz with a lot of features (e.g. highscore list, multi-page, multi-lingual, jokers) which can be used as a quiz, questionnaire, survey, poll, rating or psychological test', 1, -1, 3, 1300746245, 'a:0:{}', 'Kurt Gusbeth', 'info@myquizandpoll.de', 'bihor', '0bb230e27fd7f96946f29579467504af', 'New method for sending emails in Typo3 4.5.x. Several new features and improvements.', '', 1005000, 0, 0),
(19233, 0, 'myquizpoll', 1, '1.6.0', 1732, 269, 'My quiz and poll', 'An advanced quiz with a lot of features (e.g. highscore list, multi-page, multi-lingual, jokers) which can be used as a quiz, questionnaire, survey, poll, rating or psychological test', 2, -1, 3, 1304190920, 'a:0:{}', 'Kurt Gusbeth', 'info@myquizandpoll.de', 'bihor', '322e506cb213241176c6807d849e3174', 'New options for the highscore. Name of all highscore variables changed. Explanation also available at the poll result page.', '', 1006000, 0, 0),
(19234, 0, 'myquizpoll', 1, '1.7.0', 1732, 120, 'My quiz and poll', 'An advanced quiz with a lot of features (e.g. highscore list, multi-page, multi-lingual, jokers) which can be used as a quiz, questionnaire, survey, poll, rating or psychological test', 2, -1, 3, 1322329386, 'a:0:{}', 'Kurt Gusbeth', 'info@myquizandpoll.de', 'bihor', '950b480ad8487136ef1bbd3dedbf4325', 'jQuery support for a quiz.\r\nAdd-ons now avaiable.\r\nMinor bugfixes.', '', 1007000, 0, 0),
(19235, 0, 'myquizpoll', 1, '1.8.0', 1732, 104, 'My quiz and poll', 'An advanced quiz with a lot of features (e.g. highscore list, multi-page, multi-lingual, jokers) which can be used as a quiz, questionnaire, survey, poll, rating or psychological test', 2, -1, 3, 1329076173, 'a:0:{}', 'Kurt Gusbeth', 'info@myquizandpoll.de', 'bihor', '8cae6e3e4dd87f93041c8086ae055e95', 'New: an address can be saved into tt_address.\r\nYou can select more than one sysfolder.\r\nYou need now an add-on for the frontend-import.\r\nNew debug-mode.', '', 1008000, 0, 0),
