(19313, 0, 'customerreferences', 1, '0.1.0', 189, 20, 'Customer References', 'Places an extensibly configurable Flash object on the page that scrolls logos from records saved in the database. Its possible to add a link to each of these Logos so that clicking them redirects the user to a page that contains more information about th', 0, 0, 3, 1213705804, 'a:0:{}', 'Andrew Plank', 'plankmeister@hotmail.com', 'plankmeister', '5c75fa141467e9e63686ab34b9f38dfc', 'Tidied code, added comments etc.\n\nFixed a few bugs.\n\nNo manual yet, but it will come soon.\n\nThis version works as expected. Tested on 4.1.5\n\nAdd the plugin to the page using TS, add some Customer Reference records, and add the plugin to a page.', '', 1000, 0, 0),
(19314, 0, 'customerreferences', 1, '0.1.1', 189, 15, 'Customer References', 'Places an extensibly configurable Flash object on the page that scrolls logos from records saved in the database. Its possible to add a link to each of these Logos so that clicking them redirects the user to a page that contains more information about th', 0, 0, 3, 1213948429, 'a:0:{}', 'Andrew Plank', 'plankmeister@hotmail.com', 'plankmeister', 'cfaeaa402965118a0f48c55abce818b8', 'Fixed bug for Typo3 4.2, where wrong PID was used in the source, leading to an incorrect redirection in the back-end when adding records.\r\n\r\nAlso removed some stray empty lines after the closing php tag in one file that lead to header errors.', '', 1001, 0, 0),
(19315, 0, 'customerreferences', 1, '0.1.2', 189, 20, 'Customer References', 'Places an extensibly configurable Flash object on the page that scrolls logos from records saved in the database. Its possible to add a link to each of these Logos so that clicking them redirects the user to a page that contains more information about th', 0, 0, 3, 1214040818, 'a:0:{}', 'Andrew Plank', 'plankmeister@hotmail.com', 'plankmeister', 'e49cbc8a259d0c6007c3323ca1f6c6b2', 'Added a check for a default rootPid. If there was no default rootPid set, the addition of records failed with unpredictable results.', '', 1002, 0, 0),
(19316, 0, 'customerreferences', 1, '0.1.3', 189, 109, 'Customer References', 'Places an extensibly configurable Flash object on the page that scrolls logos from records saved in the database. Its possible to add a link to each of these Logos so that clicking them redirects the user to a page that contains more information about th', 0, 0, 3, 1214216214, 'a:0:{}', 'Andrew Plank', 'plankmeister@hotmail.com', 'plankmeister', '7267c651aaec12456ae775a67ca2bb6a', 'Added manual', '', 1003, 1, 0),
