(19408, 0, 'bees', 1, '1.0.0', 27, 27, 'Typo3 Bees', 'Bees is a lightweight framework for use with Typo3 (4.x). It makes basic use of the MVC concept but keeps bounds for developers constantly low: Bees are global accessible within a very flat hirarchy. They are flexible and extensible by any Typo3 Extension', 0, 0, 4, 1214702827, 'a:0:{}', 'Arne Holzenburg', 'arne@holzenburg.de', 'arne.holzenburg', 'bc4332ff1e72739137e5d8e4923a6a64', 'Initial Upload (does nothing)', '', 1000000, 1, 0),
