(19501, 0, 'media_center', 1, '0.1.0', 2903, 54, 'Media Center', 'Flash based Media Center using the JW FLV Player to display multiple media files in an integrated playlist. Supports several video, audio and image files (flv, youtube, mp3, jpg, png, gif). Fully configurable, multiple plugins on one page, uses swfobject', 1, 0, 3, 1215842735, 'a:0:{}', 'Patrick Rodacker', 'patrick.rodacker@the-reflection.de', 'rodi', '50308fb6e58e068d8618b2100a23e7da', 'initial release', '', 1000, 0, 0),
(19502, 0, 'media_center', 1, '0.1.1', 2903, 50, 'Media Center', 'Flash based Media Center using the JW FLV Player to display multiple media files with an integrated playlist. Supports several video, audio and image files (flv, youtube, mp3, jpg, png, gif). Fully configurable, multiple plugins on one page, uses swfobjec', 1, 0, 3, 1215968521, 'a:0:{}', 'Patrick Rodacker', 'patrick.rodacker@the-reflection.de', 'rodi', 'eeb8921c19c87c4898409d94e1702018', '- added german translations\r\n- updated manual\r\n- added t3lib_extMgm::allowTableOnStandardPages(tx_mediacenter_item); to ext_tables.php so Media Center files can be created on standard pages as well\r\n', '', 1001, 0, 0),
(19503, 0, 'media_center', 1, '0.1.2', 2903, 19, 'Media Center', 'Flash based Media Center using the JW FLV Player to display multiple media files with an integrated playlist. Supports several video, audio and image files (flv, youtube, mp3, jpg, png, gif). Fully configurable, multiple plugins on one page, uses swfobjec', 1, 0, 3, 1216109827, 'a:0:{}', 'Patrick Rodacker', 'patrick.rodacker@the-reflection.de', 'rodi', '65752e481c11f4b5d16ab0b21ba3b496', 'bugfixes:\r\n limited title and description length to 256 chars\r\n corrected autostart setting in plugin configuration\r\n allow html special chars in title and description of Media Center File records\r\n removed errors in german translation', '', 1002, 0, 0),
(19504, 0, 'media_center', 1, '0.1.3', 2903, 15, 'Media Center', 'Flash based Media Center using the JW FLV Player to display multiple media files with an integrated playlist. Supports several video, audio and image files (flv, youtube, mp3, jpg, png, gif). Fully configurable, multiple plugins on one page, uses swfobjec', 1, 0, 3, 1216161668, 'a:0:{}', 'Patrick Rodacker', 'patrick.rodacker@the-reflection.de', 'rodi', 'af04ef1d294612cddcef37caff202c44', ' feature: allow to add pages to the media files section of the plugin flexform configuration\r\n\r\n feature: added link wizards to logo, skin and aboutlink fields of flexform configuration\r\n\r\n bugfix: playlist size (height and width) calculation based on', '', 1003, 0, 0),
(19505, 0, 'media_center', 1, '0.1.4', 2903, 87, 'Media Center', 'Flash based Media Center using the JW FLV Player to display multiple media files with an integrated playlist. Supports several video, audio and image files (flv, youtube, mp3, jpg, png, gif). Fully configurable, multiple plugins on one page, uses swfobjec', 1, 0, 3, 1216196773, 'a:0:{}', 'Patrick Rodacker', 'patrick.rodacker@the-reflection.de', 'rodi', 'c97e7bfe8b79eb34705e941cc9375ed3', 'bugfix: changed required flash version back to 9.0.0 (was set to 10.0.0 for testing purposes before, which broke the entire plugin ouput)\r\n', '', 1004, 0, 0),
(19506, 0, 'media_center', 1, '0.1.5', 2903, 123, 'Media Center', 'Flash based Media Center using the JW FLV Player to display multiple media files with an integrated playlist. Supports several video, audio and image files (flv, youtube, mp3, jpg, png, gif). Fully configurable, multiple plugins on one page, uses swfobjec', 1, 0, 3, 1216852610, 'a:0:{}', 'Patrick Rodacker', 'patrick.rodacker@the-reflection.de', 'rodi', '663b675585c8b30ac3b440411494325a', 'added missing yt.swf for youtube video support, sorry guys, missed that one!\r\n\r\nfixed url bugs with the link wizard\r\nadded iRSS support', '', 1005, 0, 0),
(19507, 0, 'media_center', 1, '0.1.6', 2903, 217, 'Media Center', 'Flash based Media Center using the JW FLV Player to display multiple media files with an integrated playlist. Supports several video, audio and image files (flv, youtube, mp3, jpg, png, gif). Fully configurable, multiple plugins on one page, uses swfobjec', 1, 0, 3, 1219449028, 'a:0:{}', 'Patrick Rodacker', 'patrick.rodacker@the-reflection.de', 'rodi', '16e05491649cfea5b894b7f57fb4f4ef', 'updated JW FLV Player to version 4.1.6, added new export format XSPF (default), added captions support using XSPF format', '', 1006, 0, 0),
(19508, 0, 'media_center', 1, '0.3.0', 2903, 3, 'Media Center', 'Flash based Media Center using the JW FLV Player to display multiple media files with an integrated playlist. Supports several video, audio and image files (flv, youtube, mp3, jpg, png, gif). Fully configurable, multiple plugins on one page, uses swfobjec', 1, 0, 3, 1224611325, 'a:0:{}', 'Patrick Rodacker', 'patrick.rodacker@the-reflection.de', 'rodi', '15ea2ddcac0d633c4b64905ca57e0d0f', 'changed several things, make sure to update your configuration.\r\n\r\nupdated player.swf to version 4.2.90,feature: added suppport for typoscript integration, feature: added streaming support using the streamer flashvar and the typoscript rendering mode, fea', '', 3000, 0, 0),
(19509, 0, 'media_center', 1, '1.0.0', 2903, 48, 'Media Center', 'Flash based Media Center using the JW FLV Player to display multiple media files with an integrated playlist. Supports several video, audio and image files (flv, youtube, mp3, jpg, png, gif). Fully configurable, multiple plugins on one page, uses swfobjec', 2, 0, 3, 1224611814, 'a:0:{}', 'Patrick Rodacker', 'patrick.rodacker@the-reflection.de', 'rodi', 'bcc68fbecd9e09b4d4aff270eff04474', 'first stable release with several updates and changes. Make sure to update your configuration:\r\n\r\nupdated player.swf to version 4.2.90\r\n	 feature: added suppport for typoscript integration\r\n	 feature: added streaming support using the streamer flashvar', '', 1000000, 0, 0),
(19510, 0, 'media_center', 1, '1.0.1', 2903, 299, 'Media Center', 'Flash based Media Center using the JW FLV Player to display multiple media files with an integrated playlist. Supports several video, audio and image files (flv, youtube, mp3, jpg, png, gif). Fully configurable, multiple plugins on one page, uses swfobjec', 2, 0, 3, 1224681841, 'a:0:{}', 'Patrick Rodacker', 'patrick.rodacker@the-reflection.de', 'rodi', 'a2c8448562a045046a9bd58e1c05e7a4', 'small bugfix and feature release. Integrated wrong and missing flashvars. Make sure to update your configuration !\r\n\r\nbugfix: fixed settings for flashvar repeat  from false/true to none/list/always\r\nfeature: added a couple of example skins to use from htt', '', 1000001, 0, 0),
(19511, 0, 'media_center', 1, '1.0.2', 2903, 418, 'Media Center', 'Flash based Media Center using the JW FLV Player to display multiple media files with an integrated playlist. Supports several video, audio and image files (flv, youtube, mp3, jpg, png, gif). Fully configurable, multiple plugins on one page, uses swfobjec', 2, 0, 3, 1226352999, 'a:0:{}', 'Patrick Rodacker', 'patrick.rodacker@the-reflection.de', 'rodi', '9241bea573d60e592574e9afec573601', 'bugfix: fixed wrong table declaration for multilanguage support in tca.php\r\nbugfix: fixed wrong labels for flashvars repeat in tca.php and flexform.xml\r\nfeature: mutlilingual support of media files\r\n', '', 1000002, 0, 0),
