(19543, 0, 'ods_ajaxmailsubscription', 1, '0.1.1', 1633, 34, 'Ajax mail subscription', 'Adds a plugin for subscription to direct mail newsletters', 1, 0, 3, 1218037090, 'a:1:{s:7:"depends";a:2:{s:10:"tt_address";s:0:"";s:5:"xajax";s:0:"";}}', 'Robert Heel', 'rheel@1drop.de', 'bobosch', 'c6638ce6e68e1020083458c058322c34', '	 Add dependencies.\r\n	 Now check fe_users, too.\r\n	 Add logging (syslog).\r\n', '', 1001, 0, 0),
