(19548, 0, 'ods_ajaxmailsubscription', 1, '0.2.4', 1633, 23, 'Ajax mail subscription', 'Adds a plugin for subscription to direct mail newsletters', 1, 0, 3, 1223367474, 'a:1:{s:7:"depends";a:3:{s:11:"direct_mail";s:0:"";s:10:"tt_address";s:0:"";s:5:"xajax";s:0:"";}}', 'Robert Heel', 'rheel@1drop.de', 'bobosch', 'f418aaa95f9e8b319915ebfdbb954e0b', ' Bugfix: Unsubscribe with realurl.', '', 2004, 0, 0),
(19549, 0, 'ods_ajaxmailsubscription', 1, '0.3.0', 1633, 68, 'Ajax mail subscription', 'Adds a plugin for subscription to direct mail newsletters', 1, 0, 3, 1223540378, 'a:1:{s:7:"depends";a:3:{s:11:"direct_mail";s:0:"";s:10:"tt_address";s:0:"";s:5:"xajax";s:0:"";}}', 'Robert Heel', 'rheel@1drop.de', 'bobosch', '0efc8d33082f87cf4ca694f3b66548c6', '	 Posibility to join to more default groups.\r\n	 Join to direct_mail categories.\r\n	 Process join to default group after mail confirmation.\r\n', '', 3000, 0, 0),
(19550, 0, 'ods_ajaxmailsubscription', 1, '0.4.0', 1633, 24, 'Ajax mail subscription', 'Adds a plugin for subscription to direct mail newsletters', 2, 0, 3, 1226571156, 'a:1:{s:7:"depends";a:3:{s:11:"direct_mail";s:0:"";s:10:"tt_address";s:0:"";s:5:"xajax";s:0:"";}}', 'Robert Heel', 'rheel@1drop.de', 'bobosch', '09acc8c2671cf48fd803350ef14496e0', ' Add link to edit page.\r\n Add info text if authorised.\r\n Add config option for return-path.\r\n Use htmlmail instead of plainMailEncoded.\r\n', 'http://www.1drop.de', 4000, 0, 0),
(19551, 0, 'ods_ajaxmailsubscription', 1, '0.4.1', 1633, 54, 'Ajax mail subscription', 'Adds a plugin for subscription to direct mail newsletters', 2, 0, 3, 1229530736, 'a:1:{s:7:"depends";a:3:{s:11:"direct_mail";s:0:"";s:10:"tt_address";s:0:"";s:5:"xajax";s:0:"";}}', 'Robert Heel', 'rheel@1drop.de', 'bobosch', 'b19df33d48329b30284226d1148522e3', '	 Workaround if direct_mail only substitude SYS_TABLE_NAME with first letter of tablename.\r\n	 Add mail address for notify mails.\r\n', 'http://www.1drop.de', 4001, 0, 0),
(19552, 0, 'ods_ajaxmailsubscription', 1, '0.4.2', 1633, 134, 'Ajax mail subscription', 'Adds a plugin for subscription to direct mail newsletters', 2, 0, 3, 1241507107, 'a:1:{s:7:"depends";a:3:{s:11:"direct_mail";s:0:"";s:10:"tt_address";s:0:"";s:5:"xajax";s:0:"";}}', 'Robert Heel', 'rheel@1drop.de', 'bobosch', '7d809441e585be41ec1cd1a21383e06e', ' You can now add other optional fields in subscription.\r\n Disable subscription with default mail address.\r\n Remove default mail address onclick.', 'http://www.1drop.de', 4002, 0, 0),
(19553, 0, 'ods_ajaxmailsubscription', 1, '0.4.3', 1633, 70, 'Ajax mail subscription', 'Adds a plugin for subscription to direct mail newsletters', 2, 0, 3, 1259070921, 'a:1:{s:7:"depends";a:3:{s:11:"direct_mail";s:0:"";s:10:"tt_address";s:0:"";s:5:"xajax";s:0:"";}}', 'Robert Heel', 'rheel@1drop.de', 'bobosch', 'e00aec13b52e65d5674a187994867521', '	 New: Default TS setup code\r\n	 Bugfix: wrong fieldname on fe_users\r\n	 Bugfix: Translation mistake', 'http://www.1drop.de', 4003, 0, 0),
(19554, 0, 'ods_ajaxmailsubscription', 1, '0.5.0', 1633, 129, 'Ajax mail subscription', 'Adds a plugin for subscription to direct mail newsletters', 2, 0, 3, 1261390477, 'a:1:{s:7:"depends";a:3:{s:11:"direct_mail";s:0:"";s:10:"tt_address";s:0:"";s:5:"xajax";s:0:"";}}', 'Robert Heel', 'rheel@1drop.de', 'bobosch', '8e598446ab686c969b71957e7bda079c', '	 New: Mail text on successful subscription and unsubscription\r\n	 New: Redirect to page on successful unsubscription\r\n	 New: Config option for reply-to\r\n', 'http://www.1drop.de', 5000, 0, 0),
(19555, 0, 'ods_ajaxmailsubscription', 1, '0.5.1', 1633, 4, 'Ajax mail subscription', 'Adds a plugin for subscription to direct mail newsletters', 2, 0, 3, 1273594536, 'a:1:{s:7:"depends";a:3:{s:11:"direct_mail";s:0:"";s:10:"tt_address";s:0:"";s:5:"xajax";s:0:"";}}', 'Robert Heel', 'rheel@1drop.de', 'bobosch', '88f07602b20778a4dfe38b4d7893bb3a', '	 Bugfix: Disable multilanguage flexform.\r\n	 Bugfix: All default configuration in TS.\r\n', 'http://www.1drop.de', 5001, 0, 0),
(19556, 0, 'ods_ajaxmailsubscription', 1, '0.6.0', 1633, 6, 'Ajax mail subscription', 'Adds a plugin for subscription to direct mail newsletters', 2, 0, 3, 1275582599, 'a:1:{s:7:"depends";a:3:{s:11:"direct_mail";s:0:"";s:10:"tt_address";s:0:"";s:5:"xajax";s:0:"";}}', 'Robert Heel', 'rheel@1drop.de', 'bobosch', '0886a0850724f50ab3052c881d4fa651', '	 Add: Allow link anchor on preferences and redirect page.\r\n	 Add: TS option to create new addresses as fe_users.\r\n', 'http://www.1drop.de', 6000, 0, 0),
(19557, 0, 'ods_ajaxmailsubscription', 1, '0.6.1', 1633, 4, 'Ajax mail subscription', 'Adds a plugin for subscription to direct mail newsletters', 2, 0, 3, 1279034682, 'a:1:{s:7:"depends";a:3:{s:11:"direct_mail";s:0:"";s:10:"tt_address";s:0:"";s:5:"xajax";s:0:"";}}', 'Robert Heel', 'rheel@1drop.de', 'bobosch', 'c3f224946d6b7ac05c381882d42bf48f', '	 Bugfix: No new users if default_table not set.\r\n	 Bugfix: TS option for authcode fields.\r\n	 Add: French FE translation.\r\n', 'http://www.1drop.de', 6001, 0, 0),
(19558, 0, 'ods_ajaxmailsubscription', 1, '0.6.2', 1633, 4, 'Ajax mail subscription', 'Adds a plugin for subscription to direct mail newsletters', 2, 0, 3, 1279113984, 'a:1:{s:7:"depends";a:3:{s:11:"direct_mail";s:0:"";s:10:"tt_address";s:0:"";s:5:"xajax";s:0:"";}}', 'Robert Heel', 'rheel@1drop.de', 'bobosch', '7e9c57f24e63fe45ab23791d7889ace0', '	 Bugfix: Add field middle_name to fe_users.\r\n	 Bugfix: Update name field on tt_address records.\r\n	 Bugfix: Preselection of gender (Thanks to Andreas Heling).\r\n', 'http://www.1drop.de', 6002, 0, 0),
(19559, 0, 'ods_ajaxmailsubscription', 1, '0.7.0', 1633, 24, 'Ajax mail subscription', 'Adds a plugin for subscription to direct mail newsletters', 2, 0, 3, 1281004451, 'a:1:{s:7:"depends";a:3:{s:11:"direct_mail";s:0:"";s:10:"tt_address";s:0:"";s:5:"xajax";s:0:"";}}', 'Robert Heel', 'rheel@1drop.de', 'bobosch', '4369c42ed0dddebdc26ca4974b040c19', '	 Change: Move "Page/Sysfolder containing tt_address records" to "Startingpoint". Please run UPDATE! function (Thanks to Rupert Germann for tt_news update script).\r\n	 Add: Search sysfolder recursive.\r\n	 Add: Italian FE translation (Thanks to Clemens Ri', 'http://www.1drop.de', 7000, 0, 0),
(19560, 0, 'ods_ajaxmailsubscription', 1, '0.7.1', 1633, 51, 'Ajax mail subscription', 'Adds a plugin for subscription to direct mail newsletters', 2, 0, 3, 1283272170, 'a:1:{s:7:"depends";a:3:{s:11:"direct_mail";s:0:"";s:10:"tt_address";s:0:"";s:5:"xajax";s:0:"";}}', 'Robert Heel', 'rheel@1drop.de', 'bobosch', '2c75b57aa07af7491e6439c31b0ca605', '	 Bugfix: Use active user record if two records exists.\r\n	 Add: Set username to emailaddress and module_sys_dmail_newsletter on fe_users creation.\r\n	 Add: TS option indication.enable and indication.disable to use own javascript effects.\r\n', 'http://www.1drop.de', 7001, 0, 0),
(19561, 0, 'ods_ajaxmailsubscription', 1, '1.0.0', 1633, 187, 'Ajax mail subscription', 'Adds a plugin for subscription to direct mail newsletters', 1, 0, 3, 1284764151, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"4.4.0-0.0.0";s:11:"direct_mail";s:0:"";s:10:"tt_address";s:0:"";}}', 'Robert Heel', 'rheel@1drop.de', 'bobosch', 'b6ad38451c2a48c620789204ad381106', '	 Incompatible Change: New (simplified) template file and extra mail template file (TS option mailtemplate).\r\n	 Change: Using jQuery instead of xajax.\r\n	 Add: TS constants.\r\n	 Add: HTML mail (TS option mail_html).\r\n	 Add: TS option mail_confirmation.', 'http://www.1drop.de/', 1000000, 0, 0),
(19562, 0, 'ods_ajaxmailsubscription', 1, '1.0.1', 1633, 593, 'Ajax mail subscription', 'Adds a plugin for subscription to direct mail newsletters', 2, 0, 3, 1298480668, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"4.4.0-0.0.0";s:11:"direct_mail";s:0:"";s:10:"tt_address";s:0:"";}}', 'Robert Heel', 'rheel@1drop.de', 'bobosch', '94c304003200b33fb79586c161e1ffca', '	 Bugfix 12869: E-Mail address name (TS option mail_from_name and mail_reply_name).\r\n	 Update: jQuery 1.4.4.\r\n	 Bugfix: Replaced forgotten %s in mail template.\r\n', 'http://www.1drop.de/', 1000001, 0, 0),
(19563, 0, 'ods_ajaxmailsubscription', 1, '1.1.0', 1633, 63, 'Ajax mail subscription', 'Adds a plugin for subscription to direct mail newsletters', 2, 0, 3, 1330511396, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"4.4.0-0.0.0";s:11:"direct_mail";s:0:"";s:10:"tt_address";s:0:"";}}', 'Robert Heel', 'rheel@1drop.de', 'bobosch', '2e620a6bb784c256113a262bcb3bf5e6', '	 Add: Support for fe_groups and tt_address_group.\r\n	 Bugfix: User registration now works if no pid is set.\r\n	 Add: Greek FE translation (Thanks to Lars Jochimsen).\r\n', 'http://www.1drop.de/', 1001000, 0, 0),
(19564, 0, 'ods_ajaxmailsubscription', 1, '1.2.0', 1633, 0, 'Ajax mail subscription', 'Adds a plugin for subscription to direct mail newsletters', 2, 0, 3, 1337927523, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:11:"4.5.0-0.0.0";s:10:"tt_address";s:0:"";}}', 'Robert Heel', 'rheel@1drop.de', 'bobosch', '424e40b4af3b72f5d7301ca27e234849', '	 Bug 36899: Using t3lib_mail_message instead of t3lib_htmlmail for TYPO3 4.7 compatibility (Thanks to Loek Hilgersom).\n	 Feature 36901: Make direct_mail optional.\n', 'http://www.1drop.de/', 1002000, 0, 0),
(19565, 0, 'ods_ajaxmailsubscription', 1, '1.2.1', 1633, 0, 'Ajax mail subscription', 'Adds a plugin for subscription to direct mail newsletters', 2, 0, 3, 1339181387, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:11:"4.5.0-0.0.0";s:10:"tt_address";s:0:"";}}', 'Robert Heel', 'rheel@1drop.de', 'bobosch', 'f1108687d45d699e6394165a4ccce143', ' Bugfix: Ignore empty email address.', 'http://www.1drop.de/', 1002001, 0, 0),
