(19704, 0, 'mouseoverimages', 1, '0.2.0', 821, 23, 'Mouse Over Effects for Images', 'Adds mouse over effects to the image content element: Image effects become mouse over highlight effects. Also, completely different images can be added as overlay images which are displayed until mouse over', 1, 0, 3, 1219546979, 'a:1:{s:7:"depends";a:2:{s:3:"cms";s:0:"";s:18:"css_styled_content";s:0:"";}}', 'Till Korten', 'webmaster@korten-rivat.de', 'tillko', 'ce7fedc62340b5c18c846411e8b8615d', 'New feature: Image effect as highlight effect\r\nAdded Manual\r\nCode cleanup', '', 2000, 0, 0),
