(19714, 0, 'kickstarter__mvc_ex', 1, '0.1.1', 212, 10, 'Extension Kickstarter for lib/div MVC framework (E', 'This is an addon to the kickstarter and generates code for the lib/div extension development framework of ECT, with focus on extranet-applications. Please report bugs to http://bugs.typo3.org section kickstarter__mvc.', 3, 0, 0, 1218418966, 'a:0:{}', 'Christian Welzel, Niels Frhling', 'gawain@camlann.de,niels@frohling.biz', 'metatron', '6af9196031462fbde83c8f6cfb7df9ce', 'Added some features:\r\n\r\n- explanations\r\n- autogenerates validationRules\r\n- autogenerates forms\r\n- autogenerates FE language-file\r\n- autogenerates working io-code for the model\r\n', 'schech.net,frohling.biz', 1001, 0, 0),
(19715, 0, 'kickstarter__mvc_ex', 1, '0.1.2', 212, 9, 'Extension Kickstarter for lib/div MVC framework (E', 'This is an addon to the kickstarter and generates code for the lib/div extension development framework of ECT, with focus on extranet-applications. Please report bugs to http://bugs.typo3.org section kickstarter__mvc.', 3, 0, 0, 1218451584, 'a:0:{}', 'Christian Welzel, Niels Frhling', 'gawain@camlann.de,niels@frohling.biz', 'metatron', '6a40427262b9ab2c4e3fbdcb7ceec7e3', 'just escaped all the  in comments of code to be generated', 'schech.net,frohling.biz', 1002, 0, 0),
(19716, 0, 'kickstarter__mvc_ex', 1, '0.1.3', 212, 13, 'Extension Kickstarter for lib/div MVC framework (E', 'This is an addon to the kickstarter and generates code for the lib/div extension development framework of ECT, with focus on extranet-applications. Please report bugs to http://bugs.typo3.org section kickstarter__mvc.', 3, 0, 0, 1218473971, 'a:0:{}', 'Christian Welzel, Niels Frhling', 'gawain@camlann.de,niels@frohling.biz', 'metatron', '8dd954c0c3392ca60478956f9f65b4ed', '- finished implementation of fully functional inline-list maintenance without JS-requirement (related to listedform and maintainlisted)\r\n- phpTemplateEx-implementation for easy positional error-by-validation reporting\r\n- TODO: generic aux-MVC', 'schech.net,frohling.biz', 1003, 0, 0),
(19717, 0, 'kickstarter__mvc_ex', 1, '0.2.0', 212, 58, 'Extension Kickstarter for lib/div MVC framework (E', 'This is an addon to the kickstarter and generates code for the lib/div extension development framework of ECT, with focus on extranet-applications. Please report bugs to http://bugs.typo3.org section kickstarter__mvc.', 3, 0, 0, 1219104717, 'a:0:{}', 'Christian Welzel, Niels Frhling', 'gawain@camlann.de,niels@frohling.biz', 'metatron', 'dcb141c9bd044094039180684a47735e', '- almost generic aux-MVC\r\n- autotransportation of table-relations\r\n- segmentation of forms (not paging!) through presets\r\n- exposing state to TS\r\n- almost 100% autogenerative now\r\n- TODO: fixing non-dynamic part of the aux-MVC\r\n- TODO: documentation and t', 'schech.net,frohling.biz', 2000, 0, 0),
(19718, 0, 'kickstarter__mvc_ex', 1, '0.3.0', 212, 122, 'Extension Kickstarter for lib/div MVC framework (E', 'This is an addon to the kickstarter and generates code for the lib/div extension development framework of ECT, with focus on extranet-applications. Please report bugs to http://bugs.typo3.org section kickstarter__mvc.', 3, 0, 0, 1227606861, 'a:0:{}', 'Christian Welzel, Niels Frhling', 'gawain@camlann.de,niels@frohling.biz', 'metatron', 'cd797248da4173a7a44cb2d09407b2c3', '- UML-alike diagram for relationships and easy configuration\r\n- even more relaxed predefined action-names, but still some time to go\r\n- reverse engineered TCEforms form some DAM tables, for further use in automated forms\r\n', 'schech.net,frohling.biz', 3000, 1, 0),
