(19738, 0, 'powersearch', 1, '1.0.1', 264, 11, 'PowerSearch', 'Powersearch is an extensible, powerful search module that indexes \ntypo3 content and files (pdf/txt/doc) out of the box.\n\nUsing Zend_Search_Lucene from the Zend_Framework fulltext search results can be\nretrieved very fast and indexing is highly scalable.\n', 1, 0, 4, 1218605181, 'a:0:{}', 'Norbert Sendetzky', 'typo3@metaways.de', 'mixkxel', 'd4313a861683cda2886fbd900be2589c', 'Initial release', 'Metaways Infosystems GmbH', 1000001, 0, 0),
(19739, 0, 'powersearch', 1, '1.0.2', 264, 253, 'PowerSearch', 'PowerSearch is an extensible, powerful search framework to index typo3 content, files (pdf/txt/doc) and other sources out of the box. It consists of the framework module, an indexer (e.g. PowerSearchIndexLucene) and an user interface (e.g. PowerSearchUI)', 1, 0, 4, 1219332072, 'a:0:{}', 'Norbert Sendetzky', 'typo3@metaways.de', 'mixkxel', 'e57e5eb13a4de08a4651b1cabda0ce4a', 'Documentation updates', 'Metaways Infosystems GmbH', 1000002, 1, 0),
(19740, 0, 'powersearchui', 1, '1.0.1', 231, 11, 'PowerSearch UI Default', 'Powersearch is an extensible, powerful search module that indexes \ntypo3 content and files (pdf/txt/doc) out of the box.\n\nUsing Zend_Search_Lucene from the Zend_Framework fulltext search results can be\nretrieved very fast and indexing is highly scalable.\n', 1, 0, 3, 1218605212, 'a:1:{s:7:"depends";a:1:{s:11:"powersearch";s:0:"";}}', 'Norbert Sendetzky', 'typo3@metaways.de', 'mixkxel', '04404918e678455de949ca205c007344', 'Initial release', 'Metaways Infosystems GmbH', 1000001, 0, 0),
(19741, 0, 'powersearchui', 1, '1.0.2', 231, 220, 'PowerSearch UI Default', 'PowerSearch is an extensible, powerful search framework to index typo3 content, files (pdf/txt/doc) and other sources out of the box. It consists of the framework module (PowerSearch), the indexer (e.g. PowerSearchIndexLucene) and the user interface', 1, 0, 3, 1219332138, 'a:1:{s:7:"depends";a:1:{s:11:"powersearch";s:0:"";}}', 'Norbert Sendetzky', 'typo3@metaways.de', 'mixkxel', '9f4ddbe8d13bb752194e3a16c8a41fd4', '', 'Metaways Infosystems GmbH', 1000002, 1, 0),
(19742, 0, 'powersearchindexlucene', 1, '1.0.1', 304, 10, 'PowerSearch Index Lucene', 'Powersearch is an extensible, powerful search module that indexes \ntypo3 content and files (pdf/txt/doc) out of the box.\n\nUsing Zend_Search_Lucene from the Zend_Framework fulltext search results can be\nretrieved very fast and indexing is highly scalable.\n', 1, 0, 5, 1218605250, 'a:1:{s:7:"depends";a:1:{s:11:"powersearch";s:0:"";}}', 'Knut Mller', 'typo3@metaways.de', 'mixkxel', '904ce9016e71fbb1c4e8d22bc2d0103a', 'Initial release', 'Metaways Infosystems GmbH', 1000001, 0, 0),
