(19852, 0, 'rgnewsce', 1, '0.0.2', 2102, 60, 'Content elements in tt_news', 'Add normal content elements to tt_news. Full project documentation: http://forge.typo3.org/wiki/extension-rgnewsce.  Screencast: http://screencast.com/t/epJcCG0cpsk', 0, 0, 2, 1220093496, 'a:1:{s:7:"depends";a:1:{s:7:"tt_news";s:0:"";}}', 'Georg Ringer / Krystian Szymukowicz', 'http://www.ringer.it', 't33k', '97ac878c2fc4b9fbd961dfb789bad1e8', 'Fixed some bugs. For details see http://forge.typo3.org/versions/show/133', '', 2, 0, 0),
(19853, 0, 'rgnewsce', 1, '0.0.3', 2102, 206, 'Content elements in tt_news', 'Add another type of news "Extended news". In this type of news you can add normal content elements to tt_news. Full project documentation: http://forge.typo3.org/wiki/extension-rgnewsce.  Screencast: http://screencast.com/t/epJcCG0cpsk', 0, 0, 2, 1220697907, 'a:1:{s:7:"depends";a:1:{s:7:"tt_news";s:0:"";}}', 'Georg Ringer / Krystian Szymukowicz', 'http://www.ringer.it', 't33k', '0bae00e417bea6114dd56114c8bbc2b4', 'Added new tt_news record type: "Extended News". From now you can edit old tt_news records and choose how youd like to edit new one.', '', 3, 0, 0),
(19854, 0, 'rgnewsce', 1, '0.0.4', 2102, 378, 'Content elements in tt_news', 'This extension allows to add any number of any content elements to a news record.\n	Additionally it allows to divide tt_news fields into more tabs and to format standard news text and images using css_styled_content.\n	Some screenshots: http://forge.typo3.o', 0, 0, 2, 1225294483, 'a:1:{s:7:"depends";a:3:{s:7:"tt_news";s:0:"";s:18:"css_styled_content";s:0:"";s:5:"typo3";s:12:"4.1.0-4.2.99";}}', 'Georg Ringer / Krystian Szymukowicz', 'http://www.ringer.it - http://typo3.prolabium.com', 't33k', '0de047d9860b89fae9da93ef8b07ecdd', '1. New tab "extra" with content elements can be now added to standard news. First standard text and image is rendered - then content elements from tab "Extra".\r\n\r\n2. Old text and images of tt_news can be now rendered using css_styled_content\r\n\r\n3. Fixed:', '', 4, 0, 0),
(19855, 0, 'rgnewsce', 1, '0.1.0', 2102, 314, 'Content elements in tt_news', 'This extension allows to add any number of any content elements to a news record.\n	Additionally it allows to divide tt_news fields into more tabs and to format standard news text and images using css_styled_content.\n	Some screenshots: http://forge.typo3.o', 1, 0, 2, 1260094973, 'a:1:{s:7:"depends";a:3:{s:7:"tt_news";s:0:"";s:18:"css_styled_content";s:0:"";s:5:"typo3";s:12:"4.1.0-4.3.00";}}', 'Georg Ringer / Krystian Szymukowicz', 'http://www.ringer.it - http://typo3.prolabium.com', 't33k', '8d86bbc37521e4636da9eb344b978fdf', 'compatibility with tt_news 3.0.0,  support for multilanguage, support for firstImageIsPreview and forceFirstImageIsPreview', '', 1000, 0, 0),
(19856, 0, 'rgnewsce', 1, '0.1.1', 2102, 1039, 'Content elements in tt_news', 'This extension allows to add any number of any content elements to a news record.	Idea and first implementation by Georg Ringer. Now maintainer is Krystian Szymukowicz.', 1, 0, 2, 1269345277, 'a:1:{s:7:"depends";a:3:{s:7:"tt_news";s:0:"";s:18:"css_styled_content";s:0:"";s:5:"typo3";s:11:"4.1.0-4.3.2";}}', 'Krystian Szymukowicz / Georg Ringer', 'http://www.cms-partner.pl , http://www.ringer.it', 't33k', '7b9971d44c365de1d39e152107d237fc', 'Fixed compatibility bug with tt_news  3.0.0', '', 1001, 1, 0),
