(19873, 0, 'patch1822', 1, '0.0.3', 1377, 193, 'API to list tables in the Web-Page module', 'This implements the patch for bug1822 which is already pending in the Core list since many months.', 2, 0, 0, 1225694870, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"4.2.0-4.3.99";}}', 'Franz Holzinger', 'contact@fholzinger.com', 'franzholz', '3358ed484edd94087c0914b1ca3a6d50', 'Easier usage of locallang.xml files. Activate the root page.', 'jambage.com', 3, 0, 0),
(19874, 0, 'patch1822', 1, '0.0.4', 1377, 41, 'List tables in Web-Page module', 'This implements the patch for bug1822 which is pending in the Core list since many months.', 2, 0, 0, 1243686953, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"4.2.0-4.3.99";}}', 'Franz Holzinger', 'franz@ttproducts.de', 'franzholz', '78dbf2de7d4a14697ff8b33cd24466fc', 'Include the bug fix for TYPO3 4.3 alpha.\nNew feature to add a translated field which corresponds to the language of the BE user in front of a field in English language.', 'jambage.com', 4, 0, 0),
(19875, 0, 'patch1822', 1, '0.0.5', 1377, 13, 'List tables in Web-Page module', 'This implements the patch for bug1822 which is pending in the Core list since many months.', 2, 0, 0, 1245700675, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"4.2.0-4.3.99";}}', 'Franz Holzinger', 'franz@ttproducts.de', 'franzholz', 'ee22a54cb476c6df9245830ea86e1f49', 'replace exec_SELECTcountRows for TYPO3 versions  4.2.6', 'jambage.com', 5, 0, 0),
(19876, 0, 'patch1822', 1, '0.0.6', 1377, 219, 'List tables in Web-Page module', 'This implements the patch for bug1822 which is pending in the Core list since many months.', 2, 0, 0, 1245772019, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"3.8.0-4.3.99";}}', 'Franz Holzinger', 'franz@ttproducts.de', 'franzholz', '8726b93ac48cafde8974f336015aab0d', 'Bug fixes to make it working for TYPO3 4.1 and probably also for former versions.', 'jambage.com', 6, 0, 0),
(19877, 0, 'patch1822', 1, '0.0.7', 1377, 317, 'List tables in Web-Page module', 'This implements the patch for bug1822 which is pending in the Core list since many months.', 2, 0, 0, 1257418478, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"3.8.0-4.3.99";}}', 'Franz Holzinger', 'franz@ttproducts.de', 'franzholz', '319b762238351a7f90dbab1d2707a4c7', 'modification for TYPO3 4.3.0 beta2\n', 'jambage.com', 7, 0, 0),
(19878, 0, 'patch1822', 1, '0.0.8', 1377, 110, 'List tables in Web-Page module', 'This implements the patch for bug1822 which is pending in the Core list since many months.', 2, 0, 0, 1265483055, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"3.8.0-4.3.99";}}', 'Franz Holzinger', 'franz@ttproducts.de', 'franzholz', '4ddf79fde947da22877caa72dab989e1', 'maintenance upload\n\nThanks to Steffen Kamper for looking on this patch.\n', 'jambage.com', 8, 0, 0),
(19879, 0, 'patch1822', 1, '0.0.9', 1377, 76, 'List tables in Web-Page module', 'This implements the patch for bug1822 which is shipped since TYPO3 4.4. This extension is needed only for TYPO3  4.4', 2, 0, 0, 1278154954, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"3.8.0-4.3.99";}}', 'Franz Holzinger', 'franz@ttproducts.de', 'franzholz', '29031660834e454c2927626cd7561a03', 'maintenance upload\r\n\r\nDo not install this extension in TYPO3 since 4.4. This code is already there.', 'jambage.com', 9, 0, 0),
(19880, 0, 'patch1822', 1, '0.0.10', 1377, 302, 'List tables in Web-Page module', 'This implements the patch for bug1822 which is shipped since TYPO3 4.4. So this extension is wont be needed any more.', 5, 0, 0, 1278155168, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"3.8.0-4.3.99";}}', 'Franz Holzinger', 'franz@ttproducts.de', 'franzholz', 'f3f533e7f7a5ce3ffa306ed0c054ca36', 'Obsolete, if you use TYPO3 4.4 or higher.', 'jambage.com', 10, 1, 0),
(19881, 0, 'sm_tagcloudcleanup', 1, '0.1.0', 1558, 1558, 'Remove pids from Better Tag Cloud', 'Removes page IDs from tag cloud links. It extends "A Better Tag Cloud" (vge_tagcloud) by stripping IDs from vgetagcloud_pi2[pages]. This gives you more control of the results just before the cloud is rendered. It uses a hook in vge_tagcloud.', 1, 0, 3, 1219828795, 'a:1:{s:7:"depends";a:1:{s:12:"vge_tagcloud";s:0:"";}}', 'Steffen Mueller', 'typo3@t3node.com', 'xonx', '2f00991ab8a61e2aeccfad73c2e108ce', 'initial upload. beta state.', '', 1000, 1, 0),
(19882, 0, 'ods_workspace_mail', 1, '1.0.0', 54, 42, 'Sender address for workspace', 'This extension adds a senders address to the mails sent by the workspace.', 1, 0, 0, 1219843299, 'a:0:{}', 'Andreas Heling', 'aheling@1drop.de', 'aheling', '708fd85a6dea92165d34a353ba981cca', 'Initial release', '', 1000000, 0, 0),
(19883, 0, 'ods_workspace_mail', 1, '1.0.1', 54, 12, 'Sender address for workspace', 'This extension adds a senders address to the mails sent by the workspace.', 5, 0, 0, 1304409436, 'a:0:{}', 'Andreas Heling', 'aheling@1drop.de', 'aheling', '67a4ed559c73035a2353aee588ecb4ca', 'This extension is obsolete in TYPO3 4.5.x.\r\nYou can set the sender address in pageTS\r\n(e.g. tx_version.workspaces.stageNotificationEmail.additionalHeaders  From: mail@example.com)', '', 1000001, 1, 0),
