(19895, 0, 'nwt_iebasetagfix', 1, '1.0.0', 91, 91, 'Fix for XHTML base tag problems with IE6', 'This fixes the unclosed base tag problem for IE6 (a.k.a. "Operation aborted"). Just install to use it, see README for more information.', 1, 0, 2, 1219934229, 'a:0:{}', 'Christopher Hlubek', 'hlubek@networkteam.com', 'networkteam_hlubek', 'd8621c0c0e538cd99f3ee6c300d519c9', 'Initial version of this fix.', 'networkteam - creative webprojects.', 1000000, 1, 0),
(19896, 0, 'df_foundation5', 1, '2.1.3', 0, 0, 'Foundation 5', 'Responsive frontend framework for TYPO3. Render content and images in different responsive layouts. Foundation has a ton of components and structures to help you build a responsive site without having to worry about all of your baseline, foundational code.', 2, 0, 6, 1441388589, 'a:2:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.2.0-7.0.99";}s:9:"conflicts";a:1:{s:13:"nwt_imagecrop";s:0:"";}}', 'Detlef Fluess', 'fluess@2-ad.de', 'dfluess', 'de6fe7014c6bc8a93ef865f615fae836', 'Foundation Version update to 5.5.2', '', 2001003, 1, 0),
(19897, 0, 'df_foundation5', 1, '0.0.1', 0, 0, 'Foundation 5', 'Allows you to use responsive content elements with output conditions.', 0, 0, 4, 1391680733, 'a:1:{s:7:"depends";a:4:{s:3:"cms";s:0:"";s:7:"version";s:0:"";s:3:"php";s:11:"5.3.3-0.0.0";s:5:"typo3";s:12:"4.7.0-6.1.99";}}', 'Detlef Fluess', 'fluess@2-ad.de', 'dfluess', '991c571b3d6607a0f1457fbf534eccd0', 'new zurb.foundation version 5', '', 1, 0, 0),
(19898, 0, 'df_foundation5', 1, '0.0.2', 0, 0, 'Foundation 5', 'Allows you to use responsive content elements with output conditions.', 0, 0, 4, 1392110946, 'a:1:{s:7:"depends";a:4:{s:3:"cms";s:0:"";s:7:"version";s:0:"";s:3:"php";s:11:"5.3.3-0.0.0";s:5:"typo3";s:12:"4.7.0-6.1.99";}}', 'Detlef Fluess', 'fluess@2-ad.de', 'dfluess', '432ab126a42270f97375eb587c929bfd', 'small bug fixes.', '', 2, 0, 0),
(19899, 0, 'df_foundation5', 1, '0.0.3', 0, 0, 'Foundation 5', 'Allows you to use responsive content elements with output conditions.', 0, 0, 4, 1392199936, 'a:1:{s:7:"depends";a:4:{s:3:"cms";s:0:"";s:7:"version";s:0:"";s:3:"php";s:11:"5.3.3-0.0.0";s:5:"typo3";s:12:"4.7.0-6.1.99";}}', 'Detlef Fluess', 'fluess@2-ad.de', 'dfluess', '3dc21d4b06c36a3c1e5ed7a4dbbcdfaa', 'small bug fixes and custom css optimization.', '', 3, 0, 0),
(19900, 0, 'df_foundation5', 1, '0.1.0', 0, 0, 'Foundation 5', 'Allows you to use responsive content elements with output conditions.', 0, 0, 4, 1392224153, 'a:1:{s:7:"depends";a:4:{s:3:"cms";s:0:"";s:7:"version";s:0:"";s:3:"php";s:11:"5.3.3-0.0.0";s:5:"typo3";s:12:"4.7.0-6.1.99";}}', 'Detlef Fluess', 'fluess@2-ad.de', 'dfluess', '993d17a0b4538de3e7d5db3c7b1ea797', '- ZURB Foundation 5 version 5.1.1 added\n- Optional libraries outsourced as static templates for navigation. (if required please add)\n\nConfigurations on Constants possible. \nExample of use:\npage.10 lib.off-canvas\npage.10.stdWrap.wrap  section class"sh', '', 1000, 0, 0),
(19901, 0, 'df_foundation5', 1, '0.1.1', 0, 0, 'Foundation 5', '\r\n	Allows you to use responsive content elements with output conditions. \r\n	-Optional libraries for navigation as static templates.  \r\n	-Configurations possible on Constants. \r\n\r\n Example of usage: \r\n page.10 lib.off-canvas \r\n page.10.stdWrap.wrap  section class"show-for-small"  / section \r\n page.20 lib.top-bar\r\n page.20.stdWrap.wrap  section class"hide-for-small"  / section \r\n	', 1, 0, 4, 1392225180, 'a:1:{s:7:"depends";a:4:{s:3:"cms";s:0:"";s:7:"version";s:0:"";s:3:"php";s:11:"5.3.3-0.0.0";s:5:"typo3";s:12:"4.7.0-6.1.99";}}', 'Detlef Fluess', 'fluess@2-ad.de', 'dfluess', 'f5ade867ce4958d99ee8c6e3f825f6bd', '- ZURB Foundation added 5 version 5.1.1 \n- Optional libraries outsourced for navigation as static templates. (if required please add) \n- Configurations possible on Constants ', '', 1001, 0, 0),
(19902, 0, 'df_foundation5', 1, '0.1.2', 0, 0, 'Foundation 5', 'Allows you to use responsive content elements with output conditions. \n	-Optional libraries for navigation as static templates.  \n	-Configurations possible on Constants. \n\n Example of usage: \n page.10 lib.off-canvas \n page.10.stdWrap.wrap  section class"show-for-small"  / section \n page.20 lib.top-bar\n page.20.stdWrap.wrap  section class"hide-for-small"  / section', 1, 0, 4, 1392642141, 'a:1:{s:7:"depends";a:4:{s:3:"cms";s:0:"";s:7:"version";s:0:"";s:3:"php";s:11:"5.3.3-0.0.0";s:5:"typo3";s:12:"4.7.0-6.1.99";}}', 'Detlef Fluess', 'fluess@2-ad.de', 'dfluess', '8821c86c7807f8aaba10dbc4fe899222', 'Functions added:\n\nImage processing - Interchange: uses media queries to dynamically load content responsive did is Appropriate for different users browsers.\n\nNavigation - Off-canvas: menus are Positioned outside of the viewport and slide in When activat', '', 1002, 0, 0),
