(19934, 0, 'df_foundation5', 1, '2.1.2', 0, 0, 'Foundation 5', 'Responsive frontend framework for TYPO3. Render content and images in different responsive layouts. Foundation has a ton of components and structures to help you build a responsive site without having to worry about all of your baseline, foundational code.', 2, 0, 6, 1434377070, 'a:2:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.2.0-7.0.99";}s:9:"conflicts";a:1:{s:13:"nwt_imagecrop";s:0:"";}}', 'Detlef Fluess', 'fluess@2-ad.de', 'dfluess', '2cd0bcc2a1c82e05cf96ae6ed7f9fcb5', 'Add TYPO3 CMS 7.0.x compatiblity. \r\nVersion update to 5.5.1', '', 2001002, 0, 0),
(19935, 0, 'ts45min_de', 1, '0.5.1', 203, 167, '45 Minuten TypoScript', 'Diese Einfhrung in TypoScript ist ein erster Schritt. Die aktuelle (Wiki-) Version ist 0.5 - das bedeutet, dass wir uns bewusst sind, dass noch einiges fehlt oder verbesserungswrdig ist. Aber wir denken, dass sie bereits in diesem Stadium dem eine', 1, 0, 8, 1220183167, 'a:0:{}', 'TYPO3 DocTeam - Martin Holtz, Susanne Moog', 'typo3@martinholtz.de', 'docteam', 'f65689a721950291b25ddcf0f99f225a', 'First release.', '', 5001, 0, 0),
(19936, 0, 'ts45min_de', 1, '0.5.2', 203, 36, '45 Minuten TypoScript', 'Diese Einfhrung in TypoScript ist ein erster Schritt. Die aktuelle (Wiki-) Version ist 0.5 - das bedeutet, dass wir uns bewusst sind, dass noch einiges fehlt oder verbesserungswrdig ist. Aber wir denken, dass sie bereits in diesem Stadium ', 5, 0, 8, 1292342496, 'a:0:{}', 'TYPO3 DocTeam - Martin Holtz, Susanne Moog', 'typo3@martinholtz.de', 'docteam', 'f9e8d03cf9f4174ea883caa797aa5617', 'This is extension is now maintained as "doc_tut_ts45_de". This version is therefore obsolete.', '', 5002, 1, 0),
(19937, 0, 'sav_library', 1, '2.0.1', 744, 19, 'SAV Library Extension Generator', 'The SAV Library Extension Generator makes it possible to directly build extensions without any PHP coding, thanks to simple configuration parameters using the Kickstarter as an extension editor.', 1, 0, 4, 1220193549, 'a:0:{}', 'Yolf', 'yolf.typo3@orange.fr', 'yolf', 'b5802a3406f98130a35320862230b7cc', '', '', 2000001, 0, 0),
(19938, 0, 'sav_library', 1, '2.0.2', 744, 45, 'SAV Library Extension Generator', 'The SAV Library Extension Generator makes it possible to directly build extensions without any PHP coding, thanks to simple configuration parameters using the Kickstarter as an extension editor.', 1, 0, 4, 1220297424, 'a:0:{}', 'Yolf', 'yolf.typo3@orange.fr', 'yolf', 'b0263cb6949b598901dd15f7fd5fd4df', 'Update the manual to the new documentation template (doc_template 1.2.5)\n', '', 2000002, 0, 0),
(19939, 0, 'sav_library', 1, '2.0.3', 744, 32, 'SAV Library Extension Generator', 'The SAV Library Extension Generator makes it possible to directly build extensions without any PHP coding, thanks to simple configuration parameters using the Kickstarter as an extension editor.', 1, 0, 4, 1221337717, 'a:0:{}', 'Yolf', 'yolf.typo3@orange.fr', 'yolf', '99be4bdcbb3875ad6cdd9745b12f342e', 'Small bugs fixed\nDocumentation updated', '', 2000003, 0, 0),
(19940, 0, 'sav_library', 1, '2.0.4', 744, 39, 'SAV Library Extension Generator', 'The SAV Library Extension Generator makes it possible to directly build extensions without any PHP coding, thanks to simple configuration parameters using the Kickstarter as an extension editor.', 1, 0, 4, 1223845352, 'a:0:{}', 'Yolf', 'yolf.typo3@orange.fr', 'yolf', 'e2c59d84897223d693ef409aeccbf070', '1.Small bugs fixed.\n2.Tutorials section reorganized.\n3.Session is now dealt with the TYPO3 session API.\n', '', 2000004, 0, 0),
(19941, 0, 'sav_library', 1, '2.0.5', 744, 36, 'SAV Library Extension Generator', 'The SAV Library Extension Generator makes it possible to directly build extensions without any PHP coding, thanks to simple configuration parameters using the Kickstarter as an extension editor.', 1, 0, 4, 1225051143, 'a:0:{}', 'Yolf', 'yolf.typo3@orange.fr', 'yolf', '660b284fe386221fbca1c5a5a028a936', '1.Major bug fixed in the kickstarter. It was occurring when creating a new extension.\n2.Minor bugs fixed.\n3.Item viewer for password field added.\n4.New tutorial section added (Tutorial 8) to explain how to export data.', '', 2000005, 0, 0),
(19942, 0, 'sav_library', 1, '2.0.6', 744, 31, 'SAV Library Extension Generator', 'The SAV Library Extension Generator makes it possible to directly build extensions without any PHP coding, thanks to simple configuration parameters using the Kickstarter as an extension editor.', 1, 0, 4, 1225651997, 'a:0:{}', 'Yolf', 'yolf.typo3@orange.fr', 'yolf', '74f4cb7bfe4aec32929d181c8ad9f269', '1.Link field removed in form Queries in the Kickstarter.\n2.Minor changes in the code.\n3.Error message added on errors in queries.\n4.Property reqValue restricted to SELECT query.\n5.Property query has now to be authorized by an admin', '', 2000006, 0, 0),
(19943, 0, 'sav_library', 1, '2.0.7', 744, 4, 'SAV Library Extension Generator', 'The SAV Library Extension Generator makes it possible to directly build extensions without any PHP coding, thanks to simple configuration parameters using the Kickstarter as an extension editor. Multiple views of the data including forms can be generated.', 1, 0, 4, 1227566383, 'a:0:{}', 'Yolf', 'yolf.typo3@orange.fr', 'yolf', '1e536501c8773adb8c4e9bf42bc4f342', '1.Reference section for field configurations added to the documentation.\n2.Group added to the export configuration so that configurations can be shared by the group members.\n3.Additional field input added to the export configuration so that aliases can be', '', 2000007, 0, 0),
(19944, 0, 'sav_library', 1, '2.0.8', 744, 20, 'SAV Library Extension Generator', 'The SAV Library Extension Generator makes it possible to directly build extensions without any PHP coding, thanks to simple configuration parameters using the Kickstarter as an extension editor. Multiple views of the data including forms can be generated.', 1, 0, 4, 1229280976, 'a:0:{}', 'Yolf', 'yolf.typo3@orange.fr', 'yolf', 'fe481ea2e2420917b76f434f0056ad6b', '1.onclick attribute replaced by ondblclick to retrieve default values.\n2.Up and down selectors in subforms modified so that when clicking on the up (resp. down) selector associated with the first (resp. last) item, it becomes the last (resp. first) item.', '', 2000008, 0, 0),
(19945, 0, 'sav_library', 1, '3.0.0', 744, 11, 'SAV Library Extension Generator', 'The SAV Library Extension Generator makes it possible to directly build extensions without any PHP coding, thanks to simple configuration parameters using the Kickstarter as an extension editor. Multiple views of the data including forms can be generated.', 1, 0, 4, 1235558508, 'a:1:{s:7:"depends";a:1:{s:11:"kickstarter";s:5:"0.4.0";}}', 'Yolf', 'yolf.typo3@orange.fr', 'yolf', '17c4400189cf3bbbafab6723153e2295', 'New main version - see Changelog in the documentation. \nThe extensions generated with the previous version must be updated using the BE update tool.', '', 3000000, 0, 0),
(19946, 0, 'sav_library', 1, '3.0.1', 744, 14, 'SAV Library Extension Generator', 'The SAV Library Extension Generator makes it possible to directly build extensions without any PHP coding, thanks to simple configuration parameters using the Kickstarter as an extension editor. Multiple views of the data including forms can be generated.', 1, 0, 4, 1236546704, 'a:1:{s:7:"depends";a:1:{s:11:"kickstarter";s:5:"0.4.0";}}', 'Yolf (Laurent Foulloy)', 'yolf.typo3@orange.fr', 'yolf', '372dc30fde045c8295964197ef7e8b35', '1.Several bugs fixed.\n2.Default image configuration added.\n3.Display of the extension version in the SAV Library Extension update tool.', '', 3000001, 0, 0),
(19947, 0, 'sav_library', 1, '3.0.2', 744, 7, 'SAV Library Extension Generator', 'The SAV Library Extension Generator makes it possible to directly build extensions without any PHP coding, thanks to simple configuration parameters using the Kickstarter as an extension editor. Multiple views of the data including forms can be generated.', 1, 0, 4, 1237849240, 'a:1:{s:7:"depends";a:1:{s:11:"kickstarter";s:5:"0.4.0";}}', 'Yolf (Laurent Foulloy)', 'yolf.typo3@orange.fr', 'yolf', '9542eb4234d654a098029637aceba3d3', '1.New item viewer added for displaying XML JpGraph (see the extension sav_jpgraph).\n2.New example added in the tutorial explaining how to use XML JpGraph.', '', 3000002, 0, 0),
(19948, 0, 'sav_library', 1, '3.0.3', 744, 7, 'SAV Library Extension Generator', 'The SAV Library Extension Generator makes it possible to directly build extensions without any PHP coding, thanks to simple configuration parameters using the Kickstarter as an extension editor. Multiple views of the data including forms can be generated.', 1, 0, 4, 1238703056, 'a:1:{s:7:"depends";a:1:{s:11:"kickstarter";s:5:"0.4.0";}}', 'Yolf (Laurent Foulloy)', 'yolf.typo3@orange.fr', 'yolf', '5736e0199dc0eee0ffebb147f5493895', '1.Smalls bugs fixed and documentation updated for example 9.\n2.Translations available through the translation server.', '', 3000003, 0, 0),
(19949, 0, 'sav_library', 1, '3.0.4', 744, 3, 'SAV Library Extension Generator', 'The SAV Library Extension Generator makes it possible to directly build extensions without any PHP coding, thanks to simple configuration parameters using the Kickstarter as an extension editor. Multiple views of the data including forms can be generated.', 1, 0, 4, 1239740625, 'a:1:{s:7:"depends";a:1:{s:11:"kickstarter";s:5:"0.4.0";}}', 'Yolf (Laurent Foulloy)', 'yolf.typo3@orange.fr', 'yolf', '5023dc8ddeeaa3726d49cf6a6a4c8b34', '1.Bugs 3085 and 3086  fixed.\n2.New property added to use TypoScript in generated extensions (Feature 3087).\n3.New example added in the tutorial to illustrate how to use TypoScript (gallery with google map position).', '', 3000004, 0, 0),
(19950, 0, 'sav_library', 1, '3.0.5', 744, 12, 'SAV Library Extension Generator', 'The SAV Library Extension Generator makes it possible to directly build extensions without any PHP coding, thanks to simple configuration parameters using the Kickstarter as an extension editor. Multiple views of the data including forms can be generated.', 1, 0, 4, 1240954584, 'a:1:{s:7:"depends";a:1:{s:11:"kickstarter";s:5:"0.4.0";}}', 'Yolf (Laurent Foulloy)', 'yolf.typo3@orange.fr', 'yolf', 'afaae5d8c52c5e8fb5d84b0b24162d75', '1.Bug 3146 fixed.\n2.Use of localization tags in the wrapItem property added (Feature 3145).\n3.Localization improved for translations (Feature 3202).\n4.One variable changed in the class tx_savlibrary_filter. Update the extension sav_filter_pagea', '', 3000005, 0, 0),
(19951, 0, 'sav_library', 1, '3.1.0', 744, 10, 'SAV Library Extension Generator', 'The SAV Library Extension Generator makes it possible to directly build extensions without any PHP coding, thanks to simple configuration parameters using the Kickstarter as an extension editor. Multiple views of the data including forms can be generated.', 1, 0, 4, 1242595132, 'a:1:{s:7:"depends";a:1:{s:11:"kickstarter";s:5:"0.4.0";}}', 'Yolf (Laurent Foulloy)', 'yolf.typo3@orange.fr', 'yolf', 'a72e312ea5c95ed65907ed979d9f2a4d', '1.Bug 3228 fixed.\n2.Each form the plugin can either be a USER or a USER_INT (Feature 3251). The status of each form can be viewed and changed in the update tool. \n3.Only one parameter is now used for links in all extensions generated by the SAV Library', '', 3001000, 0, 0),
(19952, 0, 'sav_library', 1, '3.1.1', 744, 14, 'SAV Library Extension Generator', 'The SAV Library Extension Generator makes it possible to directly build extensions without any PHP coding, thanks to simple configuration parameters using the Kickstarter as an extension editor. Multiple views of the data including forms can be generated.', 1, 0, 4, 1243457987, 'a:1:{s:7:"depends";a:1:{s:11:"kickstarter";s:5:"0.4.0";}}', 'Yolf (Laurent Foulloy)', 'yolf.typo3@orange.fr', 'yolf', 'e0ade5ec1ac524b8acac070ee11afcec', '1.Minor changes in the code.\n2.New section Other examples added in the documentation and two new examples added in the TER (sav_download and sav_meetings).', '', 3001001, 0, 0),
(19953, 0, 'sav_library', 1, '3.1.2', 744, 31, 'SAV Library Extension Generator', 'The SAV Library Extension Generator makes it possible to directly build extensions without any PHP coding, thanks to simple configuration parameters using the Kickstarter as an extension editor. Multiple views of the data including forms can be generated.', 1, 0, 4, 1249502489, 'a:1:{s:7:"depends";a:1:{s:11:"kickstarter";s:5:"0.4.0";}}', 'Yolf (Laurent Foulloy)', 'yolf.typo3@orange.fr', 'yolf', '5df9cf44beff0102142429630e568870', 'see changelog', '', 3001002, 0, 0),
(19954, 0, 'sav_library', 1, '3.1.3', 744, 141, 'SAV Library Extension Generator', 'The SAV Library Extension Generator makes it possible to directly build extensions without any PHP coding, thanks to simple configuration parameters using the Kickstarter as an extension editor. Multiple views of the data including forms can be generated.', 1, 0, 4, 1257804403, 'a:1:{s:7:"depends";a:1:{s:11:"kickstarter";s:5:"0.4.0";}}', 'Yolf (Laurent Foulloy)', 'yolf.typo3@orange.fr', 'yolf', '1e856350b1732d48f976101730492017', 'On-line manual display corrected.\n\n1.Bug when using TYPO3 4.3 fixed (Bug 4191).\n2.Bug when using JpGraph in an extension fixed (Bug 4192).\n3.Exec command can be added when exporting data. See the section Exporting to other formats in example 8.', '', 3001003, 0, 0),
(19955, 0, 'sav_library', 1, '3.2.0', 744, 81, 'SAV Library Extension Generator', 'The SAV Library Extension Generator makes it possible to directly build extensions without any PHP coding, thanks to simple configuration parameters using the Kickstarter as an extension editor. Multiple views of the data including forms can be generated.', 2, 0, 4, 1292004764, 'a:0:{}', 'Yolf (Laurent Foulloy)', 'yolf.typo3@orange.fr', 'yolf', '8f0bdaab65be3dedcbb33aa3cbda8966', 'See the Changelog section.', '', 3002000, 0, 0),
(19956, 0, 'sav_library', 1, '3.2.1', 744, 75, 'SAV Library Extension Generator', 'The SAV Library Extension Generator makes it possible to directly build extensions without any PHP coding, thanks to simple configuration parameters using the Kickstarter as an extension editor. Multiple views of the data including forms can be generated.', 2, 0, 4, 1298236432, 'a:0:{}', 'Laurent Foulloy', 'yolf.typo3@orange.fr', 'yolf', '13a4a106ca32545cd6436aa7b7afda26', 'Path to the calendar image corrected and calendar image added.\r\nCompatibility with the kickstarter 0.5.0 added.\r\nSmall bugs corrected.', '', 3002001, 0, 0),
(19957, 0, 'sav_library', 1, '3.2.2', 744, 112, 'SAV Library Extension Generator', 'The SAV Library Extension Generator makes it possible to directly build extensions without any PHP coding, thanks to simple configuration parameters using the Kickstarter as an extension editor. Multiple views of the data including forms can be generated.', 2, 0, 4, 1309161052, 'a:0:{}', 'Laurent Foulloy', 'yolf.typo3@orange.fr', 'yolf', 'e208297b4cc7bb0f0a3c793e54580169', 'See changelog', '', 3002002, 0, 0);
