(19958, 0, 'sav_library', 1, '3.2.3', 744, 0, 'SAV Library Extension Generato', 'The SAV Library Extension Generator makes it possible to directly build extensions without any PHP coding, thanks to simple configuration parameters using the Kickstarter as an extension editor. Multiple views of the data including forms can be generated.', 2, 0, 4, 1340608781, 'a:0:{}', 'Laurent Foulloy', 'yolf.typo3@orange.fr', 'yolf', '5af1a67268c4f8bb096047c55b4b2733', 'This extension is maintained for compatibility only. Please use SAV Library Plus and SAV Library Kickstarter.\nCompatibility with SAV Library Plus added.', '', 3002003, 0, 0),
(19959, 0, 'sav_library', 1, '3.3.0', 744, 0, 'SAV Library Extension Generator', 'The SAV Library Extension Generator makes it possible to directly build extensions without any PHP coding, thanks to simple configuration parameters using the Kickstarter as an extension editor. Multiple views of the data including forms can be generated.', 5, 0, 4, 1375871096, 'a:0:{}', 'Laurent Foulloy', 'yolf.typo3@orange.fr', 'yolf', 'f579ac73ce3544edfb761c98e79ff20b', 'Status changed to Obsolete. This extension is replaced by sav_library_plus.\n', '', 3003000, 1, 0),
