(20081, 0, 'ws_scriptaculous', 1, '1.0.1', 160, 24, 'Script.aculo.us and Prototype Javascript Libraries', 'Includes prototype.js and scriptaculous.js in the FE. Differences to other extensions: The additional scriptaculous libraries can be added by setting TS conf variables.', 2, 0, 2, 1220916910, 'a:0:{}', 'Sven Wappler (http://www.wapplersystems.de)', 'typo3@wapplersystems.de', 'svenwappler', 'd2a3eacae7775d6aab31b2d693f1d533', 'Init upload', 'WapplerSystems', 1000001, 0, 0),
