(20131, 0, 'dre_cctbasedcontent', 1, '1.1.1', 168, 7, 'CCT Based content', 'Have users create content based on a content creation template. Define your own content entry!', 1, 0, 0, 1249572854, 'a:0:{}', 'M. Kamminga, M.Nederlof, B. Lewinsky', 'm.kamminga@drecomm.nl,m.nederlof@drecomm.nl,b.lewinksy@drecomm.nl', 'drecomm_mnederlof', '8951a2ab4a71b37efae206f62964c160', 'small update in manual :)', 'Drecomm B.V.', 1001001, 0, 0),
(20132, 0, 'dre_cctbasedcontent', 1, '1.1.3', 168, 21, 'CCT Based content', 'Gives you as administrator of the site the ability to define your own content entry templates (CCTs).\n\nThis simplifies the process of entering content for content editors by use of a standard set of templates with a fixed set of fields. \nMost importantly ', 2, 0, 0, 1256809270, 'a:0:{}', 'M. Nederlof, M.Kamminga, B. Lewinsky', 'm.nederlof@drecomm.nl;m.kamminga@drecomm.nl;b.lewinsky@drecomm.nl', 'drecomm_mnederlof', '2a94a1b63edf6142690b1f4cbb330a17', 'Bugfix upload: \r\n- When a CCT template was copied or deleted, the template choosing did not work properly - fixed! \r\n- When you copied a page which was a CCT page, not all references were updated correctly - fixed!', 'Drecomm B.V.', 1001003, 0, 0),
(20133, 0, 'dre_cctbasedcontent', 1, '1.2.0', 168, 2, 'CCT Based content', 'Base content creation on an information model specified in a CCT', 2, 0, 0, 1261471455, 'a:0:{}', 'M.Nederlof, B. Lewinsky', 'm.nederlof@drecomm.nl, b.lewinsky@drecomm.nl', 'drecomm_mnederlof', 'c9baae54116bdcc88ad7d6a1adf18a28', 'New features:\r\n- Allow doktype override: this way you can create a CCT template for shortcuts or mountpages!\r\n- When create new record chosen, you can now directly choose the CCT template to use when creating a page.\r\n\r\nBug fixes:\r\n- IE7, when user change', 'Drecomm B.V.', 1002000, 0, 0),
(20134, 0, 'dre_cctbasedcontent', 1, '1.2.1', 168, 24, 'CCT Based content', 'Gives you as administrator of the site the ability to define your own content entry templates (CCTs). This simplifies the process of entering content for content editors by use of a standard set of templates with a fixed set of fields.', 2, 0, 0, 1261471920, 'a:0:{}', 'M.Nederlof, B. Lewinsky', 'm.nederlof@drecomm.nl, b.lewinsky@drecomm.nl', 'drecomm_mnederlof', '116793a7b0d0544eb087f41713f7430c', 'Update, new feature (include cct item):\r\n- With this feature, you now can define the configuration on one page, and then on different CCT templates include these CCT items, by using internal shortcut functionalities. This way you can build up a library of', 'Drecomm B.V.', 1002001, 0, 0),
(20135, 0, 'dre_cctbasedcontent', 1, '1.4.0', 168, 37, 'CCT Based content', 'Gives you as administrator of the site the ability to define your own content entry templates (CCTs). This simplifies the process of entering content for content editors by use of a standard set of templates with a fixed set of fields.', 2, 0, 0, 1282657859, 'a:0:{}', 'B. Lewinsky, M.Nederlof', 'b.lewinsky@drecomm.nl, m.nederlof@drecomm.nl', 'drecomm_mnederlof', 'b10602091e5abfc36ec32cd4103c89ae', '- Added TemplaVoila! FCE support\r\n- Added summary on top of cct page\r\n- Ability to use cct for typo3 default doktypes.\r\n- Bugfix when copying CCT pages: when copied the relations were lost  fixed\r\n- Added Migration tool for Default FCEs. Converts Default', 'Drecomm B.V.', 1004000, 0, 0),
(20136, 0, 'dre_cctbasedcontent', 1, '1.6.0', 168, 30, 'CCT Based content', 'Gives you as administrator of the site the ability to define your own content entry templates (CCTs). This simplifies the process of entering content for content editors by use of a standard set of templates with a fixed set of fields.', 2, 0, 0, 1309414459, 'a:0:{}', 'B.Lewinsky, M.Nederlof', 'b.lewinsky@drecomm.nl, m.nederlof@drecomm.nl', 'drecomm_mnederlof', 'a744a0295185b586cc2c4b2e860ec353', 'Lots of fixes made, TYPO 4.5 compatible', 'Drecomm B.V.', 1006000, 1, 0),
(20137, 0, 'ttnewscacheexpire', 1, '0.1.0', 44, 44, 'tt_news Cache Expire', 'Page Cache Expires cares of tt_news starttime/endtime', 3, 0, 0, 1221291365, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"4.2.0-0.0.0";s:3:"php";s:11:"5.0.0-0.0.0";s:3:"cms";s:0:"";}}', 'Martin Holtz', 'typo3@martinholtz.de', 'maholtz', 'da0911c398b5f89f25e8f7819acba1ff', 'First Upload - use together with clearcache.\r\nAt the moment this extension checks all tt_news records if there is a starttime/stoptime to change the cache expiretimestamp. Plugin-Settings are ignored at the moment, so there is an overhead. Join on forge', '', 1000, 0, 0),
