(20227, 0, 'sevenpack', 1, '0.5.1', 634, 5, 'Sevenpack bibliography manager', 'A customizable bibliography and publication reference manager with a convenient frontend editor and import/export functionality.', 1, 0, 3, 1236539461, 'a:0:{}', 'Sebastian Holtermann', 'holtermann@bccms.uni-bremen.de', 'sebotypo', 'ca0e53fb09bbacdfe1b9e3fbdd7ad2a1', 'Fixed missing pid field in tx_sevenpack_authorships. \r\nUpdaters must use the UPDATE! function in the extension manager! Some more minor changes, check the Changelog for more information.', '', 5001, 0, 0),
(20228, 0, 'sevenpack', 1, '0.5.2', 634, 9, 'Sevenpack bibliography manager', 'A customizable bibliography and publication reference manager with a convenient frontend editor and import/export functionality.', 1, 0, 3, 1236611503, 'a:0:{}', 'Sebastian Holtermann', 'sebholt@web.de', 'sebotypo', 'e19d8d289260a6aa46945ae649c81b77', 'Some FlexForm simplifications and the authorship table is no longer hidden in the backend.', '', 5002, 0, 0),
