(20231, 0, 'sevenpack', 1, '0.5.5', 634, 11, 'Sevenpack bibliography manager', 'A customizable bibliography and publication reference manager with a convenient frontend editor and import/export functionality.', 1, 0, 3, 1239788237, 'a:1:{s:7:"depends";a:1:{s:15:"ajaxgroupsearch";s:0:"";}}', 'Sebastian Holtermann', 'sebholt@web.de', 'sebotypo', '342908bb7f0233701f4814488c9d4412', 'FE users can use the editor. Removed character set conversions. Cleanups and Bugfixes.', '', 5005, 0, 0),
