(20364, 0, 'mail2news', 1, '1.1.0', 512, 54, 'Mail to tt_news', 'Import mail messages to tt_news records', 1, 0, 5, 1223330511, 'a:1:{s:7:"depends";a:1:{s:7:"tt_news";s:5:"2.0.0";}}', 'Loek Hilgersom', 'typo3extensions@netcoop.nl', 'loek', '4e71b583921466708210e95ac3a0fadf', ' Added clearCacheCmd for clearing cache of specified pages after new imports\r\n Added extension icon', 'NetCoop.nl', 1001000, 0, 0),
(20365, 0, 'mail2news', 1, '1.9.1', 512, 10, 'Mail to tt_news', 'Import mail messages to tt_news records', 0, 0, 5, 1234806208, 'a:1:{s:7:"depends";a:1:{s:7:"tt_news";s:5:"2.0.0";}}', 'Loek Hilgersom', 'typo3extensions@netcoop.nl', 'loek', '5ca7198768e9196c2bbe9b07667b21ff', 'Completely rewritten, now object oriented code, better structured, maintainable and extendible.\r\nMany new features, see changelog for details.', 'NetCoop.nl', 1009001, 0, 0),
(20366, 0, 'mail2news', 1, '1.9.2', 512, 12, 'Mail to tt_news', 'Import mail messages to tt_news records', 1, 0, 5, 1235141052, 'a:1:{s:7:"depends";a:1:{s:7:"tt_news";s:5:"2.0.0";}}', 'Loek Hilgersom', 'typo3extensions@netcoop.nl', 'loek', '472abe774edc0d74e8d4f7f4610b8201', 'Cronjob now runs though cli_dispatch, check manual for instructions.\r\nFixed charset conversion for subject line.', 'NetCoop.nl', 1009002, 0, 0),
(20367, 0, 'mail2news', 1, '1.9.3', 512, 57, 'Mail to tt_news', 'Import mail messages to tt_news records', 1, 0, 5, 1235575120, 'a:1:{s:7:"depends";a:1:{s:7:"tt_news";s:5:"2.0.0";}}', 'Loek Hilgersom', 'typo3extensions@netcoop.nl', 'loek', 'b50ddf019a0f6137b630e6c4ce140543', 'Added options to choose news category and subheader/short-text in messages\r\nCategory input can be both category title or id\r\nNicer log file output', 'NetCoop.nl', 1009003, 0, 0),
(20368, 0, 'mail2news', 1, '1.9.5', 512, 5, 'Mail to tt_news', 'Import mail messages to tt_news records', 1, 0, 5, 1272979990, 'a:1:{s:7:"depends";a:3:{s:7:"tt_news";s:5:"2.0.0";s:3:"php";s:11:"5.0.0-0.0.0";s:5:"typo3";s:11:"4.1.0-0.0.0";}}', 'Loek Hilgersom', 'typo3extensions@netcoop.nl', 'loek', 'a4847a68cbdd568fea1cb269933caedb', '- Added automatic cli_key registration (ATTENTION: if you upgrade, remove the line with $TYPO3_CONF_VARS[SC_OPTIONS][GLOBAL][cliKeys][getmail_cli] from localconf.php)\r\n- Fixed bug 6678\r\n- Added MIME-header decoding and character set conversion for', 'NetCoop.nl', 1009005, 0, 0),
(20369, 0, 'mail2news', 1, '1.9.6', 512, 4, 'Mail to tt_news', 'Import mail messages to tt_news records', 1, 0, 5, 1273235316, 'a:1:{s:7:"depends";a:3:{s:7:"tt_news";s:5:"2.0.0";s:3:"php";s:11:"5.0.0-0.0.0";s:5:"typo3";s:11:"4.1.0-0.0.0";}}', 'Loek Hilgersom', 'typo3extensions@netcoop.nl', 'loek', '3b4a01d532ebfd41178fdbec1db98e54', 'Creates cleaner filenames, no more random no prepended (issue 7678)\r\nFixed bug 7680, special chars in filenames\r\nFixed bug 3783, formatting/line breaks improved', 'NetCoop.nl', 1009006, 0, 0),
(20370, 0, 'mail2news', 1, '1.9.7', 512, 18, 'Mail to tt_news', 'Import messages from an email account into tt_news records. The easiest way to publish content on your site, start "moblogging" with TYPO3!', 1, 0, 5, 1274195253, 'a:1:{s:7:"depends";a:3:{s:7:"tt_news";s:5:"2.0.0";s:3:"php";s:11:"5.0.0-0.0.0";s:5:"typo3";s:11:"4.1.0-0.0.0";}}', 'Loek Hilgersom', 'typo3extensions@netcoop.nl', 'loek', '7a6a74502393d663fd3f7753e72265db', 'Many new features: multiple configurations using records, scheduler support, reference index updated, logging to sys_log table, improved error handling, automatic link recognition in plain text messages.\r\nPlease test!', 'NetCoop.nl', 1009007, 0, 0),
(20371, 0, 'mail2news', 1, '1.9.8', 512, 131, 'Mail to tt_news', 'Import messages from an email account into tt_news records. The easiest way to publish content on your site, start "moblogging" with TYPO3!', 1, 0, 5, 1284038698, 'a:1:{s:7:"depends";a:3:{s:7:"tt_news";s:5:"2.0.0";s:3:"php";s:11:"5.0.0-0.0.0";s:5:"typo3";s:11:"4.1.0-0.0.0";}}', 'Loek Hilgersom', 'typo3extensions@netcoop.nl', 'loek', '336a0ec64b77182cc9a5d258898ef0e8', 'Bugfix: solved issue 8054/8806 (Fallback to emConf not working when there are no mail2news configuration records)', 'NetCoop.nl', 1009008, 0, 0),
(20372, 0, 'mail2news', 1, '1.9.9', 512, 64, 'Mail to tt_news', 'Import messages from an email account into tt_news records. The easiest way to publish content on your site, start "moblogging" with TYPO3!', 2, 0, 5, 1310823032, 'a:1:{s:7:"depends";a:3:{s:7:"tt_news";s:5:"2.0.0";s:3:"php";s:11:"5.0.0-0.0.0";s:5:"typo3";s:11:"4.1.0-0.0.0";}}', 'Loek Hilgersom', 'typo3extensions@netcoop.nl', 'loek', 'da2c7bf0221efc8e93d5f9d404b78b21', 'mail2news is now compatible with TYPO3 v4.5.x; Improved category recognition & input sanitation; Updated manual; This will be the last version of this 1.x.x branch, a new version will be released later which may require some configuration changes!', 'NetCoop.nl', 1009009, 0, 0),
(20373, 0, 'mail2news', 1, '2.0.0', 512, 52, 'Mail to tt_news', 'Import messages from an email account into tt_news or t3blog records. The easiest way to publish content on your site, start "moblogging" with TYPO3!', 1, 0, 5, 1317775396, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"5.2.0-0.0.0";s:5:"typo3";s:11:"4.1.0-0.0.0";}}', 'Loek Hilgersom', 'typo3extensions@netcoop.nl', 'loek', '7f2b14eeb20fc5e0238d3f283c5a56e9', 'Major new features: \r\nNow also import email messages into T3BLOG! \r\nVery flexible fieldMarkers feature, add multiple categories, transform date import to tstamps ', 'NetCoop.nl', 2000000, 0, 0),
