(20440, 0, 'simplevcard', 1, '0.1.0', 146, 31, 'Simple vCard Creator', 'Fully customisable templates, with a front end plug in that outputs a list of selected addresses from the tt_address table, including a download link for a vCard.', 0, 0, 3, 1223463785, 'a:1:{s:7:"depends";a:4:{s:3:"php";s:11:"4.0.0-0.0.0";s:5:"typo3";s:11:"3.8.0-0.0.0";s:10:"tt_address";s:0:"";s:7:"realurl";s:0:"";}}', 'Andrew Plank', 'andrew@nybroe.dk', 'plankmeister', '691ba49a79fbcb17ede66a7ddc715870', 'Initial upload. Not throroughly bug-checked, but seems to work fine.', '', 1000, 0, 0),
(20441, 0, 'simplevcard', 1, '0.3.0', 146, 2, 'Simple vCard Download', 'Add an extra marker to your tt_address template that adds an icon file, that when clicked, downloads a vCard file for that contact. All fields are mappable from tt_address to the VCF format using Typoscript.', 1, 0, 2, 1240314891, 'a:1:{s:7:"depends";a:2:{s:10:"tt_address";s:0:"";s:7:"realurl";s:0:"";}}', 'Andrew Plank', 'andrew@nybroe.dk', 'plankmeister', 'bf2df11e25c3c5943dbf0fa9fec14fc9', ' Removed plugin upon discovery that tt_address can display single records using specified templates via plugin config.\n Restructured TS configuration to make field mapping easier\n Re-implemented the link and icon using TS, leaving only a single marker,', '', 3000, 0, 0),
(20442, 0, 'simplevcard', 1, '0.3.1', 146, 113, 'Simple vCard Download', 'Add an extra marker to your tt_address template that adds an icon file, that when clicked, downloads a vCard file for that contact. All fields are mappable from tt_address to the VCF format using Typoscript.', 1, 0, 2, 1258708468, 'a:1:{s:7:"depends";a:2:{s:10:"tt_address";s:0:"";s:7:"realurl";s:0:"";}}', 'Andrew Plank', 'andrew@nybroe.dk', 'plankmeister', '3ae91504371e85b8baab4abc31406c7c', '09-11-20 Andrew Plank  plankmeister@yahoo.com\r\n	 Switched the content of the vcf file to ISO-8859-1 from UTF-8, as the most predominant vcard application out there, MS Outlook, cannot correctly parse UTF-8 data. Typical MS.\r\n\r\n09-04-21 Andrew Plank  p', '', 3001, 1, 0),
(20443, 0, 'ch_flash_carrousel', 1, '0.0.1', 74, 74, 'Flash Carrousel', 'Controls a flash with rotating images.', 3, 0, 4, 1223539135, 'a:0:{}', 'Carsten Hartwig', '', 'dh1ch', '22bd1e2643860215a29d5619a545bf65', 'first build', '', 1, 1, 0),
