(20718, 0, 'dwoo', 1, '2.0.0', 56, 27, 'Dwoo', 'Dwoo is a PHP5 template engine positioned as an alternative to Smarty, it is (nearly) fully compatible with its templates and plugins, but it is written from scratch and aimed at going one step further with a cleaner codebase.', 2, 0, 4, 1227818271, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"4.0.0-0.0.0";s:3:"php";s:11:"5.2.0-0.0.0";s:3:"cms";s:0:"";}}', 'Romain Ruetschi', 'romain@kryzalid.com', 'romac', 'a3581d9993db401176ae9948436b4b72', 'Initial release.', 'kryzalid.com', 2000000, 1, 0),
(20719, 0, 'dwoo', 1, '1.0.2', 56, 9, 'Dwoo', 'Dwoo is a PHP5 template engine positioned as an alternative to Smarty, it is (nearly) fully compatible with its templates and plugins, but it is written from scratch and aimed at going one step further with a cleaner codebase.', 2, 0, 4, 1233047540, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"4.0.0-0.0.0";s:3:"php";s:11:"5.2.0-0.0.0";s:3:"cms";s:0:"";}}', 'Romain Ruetschi', 'romain@kryzalid.com', 'romac', 'ea523f297f07aac505a2f651890721bf', 'Upgraded Dwoo to version 1.0.1.\r\n\r\nDwoo Changelog\r\n------------------\r\n Direct assignments like {$foo  5} now allow spaces around the operator\r\n Fixed a {foreach} bug with the implode argument\r\n Fixed modulo operator in if statements\r\n Fixed date_for', 'kryzalid.com', 1000002, 0, 0),
(20720, 0, 'dwoo', 1, '1.0.1', 56, 20, 'Dwoo', 'Dwoo is a PHP5 template engine positioned as an alternative to Smarty, it is (nearly) fully compatible with its templates and plugins, but it is written from scratch and aimed at going one step further with a cleaner codebase.', 2, 0, 4, 1233048232, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"4.0.0-0.0.0";s:3:"php";s:11:"5.2.0-0.0.0";s:3:"cms";s:0:"";}}', 'Romain Ruetschi', 'romain@kryzalid.com', 'romac', '87d5a58c8c267ad8efde8aa50a883ad3', 'Upgraded Dwoo to version 1.0.1.\r\n\r\nSee http://www.dwoo.org for the changelog.', 'kryzalid.com', 1000001, 0, 0),
