(20750, 0, 'gl_pages_cat', 1, '0.1.2', 101, 8, 'Pages categorization', 'Relate pages with tt_news categories.', 1, 0, 0, 1231166265, 'a:1:{s:7:"depends";a:1:{s:7:"tt_news";s:0:"";}}', 'Manuel Rego Casasnovas [Igalia]', 'mrego@igalia.com', 'mrego', 'a8c17cebfdba6afb245334e0d1da641b', ' ext_emconf.php: Added "pages" table to "modify_tables" property.', 'Igalia - http://www.igalia.com', 1002, 0, 0),
