(20754, 0, 'imagemap_wizard', 1, '0.1.0', 1768, 11, 'Imagemap Wizard', 'Provides an TYPO3 Wizard which enables interactive Imagemap-Creation - related to the TYPO3-Linkwizard.', 0, 0, 0, 1228335374, 'a:1:{s:7:"depends";a:2:{s:3:"cms";s:5:"0.0.0";s:18:"css_styled_content";s:5:"0.0.0";}}', 'Tolleiv Nietsch', 'extensions@myfirstname.de', 'sfischer', 'f8da687f9074c152094635bbf30b2453', 'Imagemap-Wizard with support for Workspaces, Rectangle-, Circle- and Polygone-Shapes, Refindex-Reports and XCLASS-free integration.', '', 1000, 0, 0),
(20755, 0, 'imagemap_wizard', 1, '0.1.1', 1768, 18, 'Imagemap Wizard', 'Provides an TYPO3 Wizard which enables interactive Imagemap-Creation - related to the TYPO3-Linkwizard.', 0, 0, 0, 1228392707, 'a:1:{s:7:"depends";a:2:{s:3:"cms";s:5:"0.0.0";s:18:"css_styled_content";s:5:"0.0.0";}}', 'Tolleiv Nietsch', 'extensions@myfirstname.de', 'sfischer', '89773e44688d659633d1f7f0295daede', 'Compatibility-Fixes for TYPO3 4.1.x and 4.0.x ...\r\nImagemap-Wizard with support for Workspaces, Rectangle-, Circle- and Polygone-Shapes, Refindex-Reports and XCLASS-free integration.', '', 1001, 0, 0),
(20756, 0, 'imagemap_wizard', 1, '0.2.0', 1768, 10, 'Imagemap Wizard', 'Provides an TYPO3 Wizard which enables interactive Imagemap-Creation - related to the TYPO3-Linkwizard.', 0, 0, 0, 1229019261, 'a:1:{s:7:"depends";a:2:{s:3:"cms";s:5:"0.0.0";s:18:"css_styled_content";s:5:"0.0.0";}}', 'Tolleiv Nietsch', 'extensions@myfirstname.de', 'sfischer', 'bbc79e8d5ea2c8160fce16665d0957df', 'Added the possibility to drag objects just by clicking on their border, added the possibility to add new edges to polygons with double clicks\r\nRemoved some more compatibility-problems with 4.x versions, added Locallang-labels, updated manual', '', 2000, 0, 0),
(20757, 0, 'imagemap_wizard', 1, '0.2.3', 1768, 9, 'Imagemap Wizard', 'Provides an TYPO3 Wizard which enables interactive Imagemap-Creation - related to the TYPO3-Linkwizard.', 1, 0, 0, 1231361382, 'a:1:{s:7:"depends";a:4:{s:3:"php";s:12:"5.0.0-5.2.99";s:5:"typo3";s:12:"3.8.0-4.2.99";s:3:"cms";s:5:"0.0.0";s:18:"css_styled_content";s:5:"0.0.0";}}', 'Tolleiv Nietsch', 'extensions@myfirstname.de', 'sfischer', 'eca690e7c1dbb58ccc819d7e497be996', 'Bugfixes  for valid HTML and PHP code, TYPO3 integration and usability. See forge.typo3.org for details. Creating imagemaps is fun again :)', '', 2003, 0, 0),
(20758, 0, 'imagemap_wizard', 1, '0.3.2', 1768, 9, 'Imagemap Wizard', 'Provides an TYPO3 Wizard which enables interactive Imagemap-Creation - related to the TYPO3-Linkwizard.', 1, 0, 0, 1232117222, 'a:1:{s:7:"depends";a:4:{s:3:"php";s:12:"5.0.0-5.2.99";s:5:"typo3";s:12:"3.8.0-4.2.99";s:3:"cms";s:5:"0.0.0";s:18:"css_styled_content";s:5:"0.0.0";}}', 'Tolleiv Nietsch', 'extensions@myfirstname.de', 'sfischer', 'e366b45530d38e5868bd6ed35ee95cdb', 'Added autoscale feature - large image are scaled down to fit the wizard-popup with the option to scale back to 100%.', '', 3002, 0, 0),
(20759, 0, 'imagemap_wizard', 1, '0.3.3', 1768, 30, 'Imagemap Wizard', 'Provides an TYPO3 Wizard which enables interactive Imagemap-Creation - related to the TYPO3-Linkwizard.', 1, 0, 0, 1232127280, 'a:1:{s:7:"depends";a:4:{s:3:"php";s:12:"5.0.0-5.2.99";s:5:"typo3";s:12:"3.8.0-4.2.99";s:3:"cms";s:5:"0.0.0";s:18:"css_styled_content";s:5:"0.0.0";}}', 'Tolleiv Nietsch', 'extensions@myfirstname.de', 'sfischer', 'e675c3ae63012b083306736d26abb4f8', 'Solved critical bug 2475 which was introduced in version 0.3.2 ...', '', 3003, 0, 0),
(20760, 0, 'imagemap_wizard', 1, '0.4.0', 1768, 15, 'Imagemap Wizard', 'Provides an TYPO3 Wizard which enables interactive Imagemap-Creation - related to the TYPO3-Linkwizard. Supported by AOE media.', 1, 0, 0, 1238292349, 'a:1:{s:7:"depends";a:4:{s:3:"php";s:12:"5.0.0-5.2.99";s:5:"typo3";s:12:"3.8.0-4.2.99";s:3:"cms";s:5:"0.0.0";s:18:"css_styled_content";s:5:"0.0.0";}}', 'Tolleiv Nietsch', 'extensions@myfirstname.de', 'sfischer', '820581470568877ec34f559e3171976d', 'Added option to configure additional attributes for imagemap-areas, added double-click feature for polygons and fixed a couple bugs (see forge.typo3.org)', '', 4000, 0, 0),
(20761, 0, 'imagemap_wizard', 1, '0.4.1', 1768, 17, 'Imagemap Wizard', 'Provides an TYPO3 Wizard which enables interactive Imagemap-Creation - related to the TYPO3-Linkwizard. Supported by AOE media.', 1, 0, 0, 1238911815, 'a:1:{s:7:"depends";a:4:{s:3:"php";s:12:"5.0.0-5.2.99";s:5:"typo3";s:12:"3.8.0-4.2.99";s:3:"cms";s:5:"0.0.0";s:18:"css_styled_content";s:5:"0.0.0";}}', 'Tolleiv Nietsch', 'extensions@myfirstname.de', 'sfischer', 'ee9400711a1de0a76f7f7a910960d5ce', 'Improved tooptip when IM is saved, small bug fixes, basic CSH and additional TypoScript options :)', '', 4001, 0, 0),
(20762, 0, 'imagemap_wizard', 1, '0.4.2', 1768, 83, 'Imagemap Wizard', 'Provides an TYPO3 Wizard which enables interactive Imagemap-Creation - related to the TYPO3-Linkwizard. Supported by AOE media.', 1, 0, 0, 1240051195, 'a:1:{s:7:"depends";a:4:{s:3:"php";s:12:"5.0.0-5.2.99";s:5:"typo3";s:12:"3.8.0-4.2.99";s:3:"cms";s:5:"0.0.0";s:18:"css_styled_content";s:5:"0.0.0";}}', 'Tolleiv Nietsch', 'extensions@myfirstname.de', 'sfischer', 'f49b48eb93fae245f32c22ab6b744cca', 'Small changes for better usability and better error-handling (or at least better error-messages).', '', 4002, 0, 0),
(20763, 0, 'imagemap_wizard', 1, '0.5.3', 1768, 64, 'Imagemap Wizard', 'Provides an TYPO3 Wizard which enables interactive Imagemap-Creation - related to the TYPO3-Linkwizard. Supported by AOE media.', 2, 0, 0, 1255872299, 'a:1:{s:7:"depends";a:4:{s:3:"php";s:12:"5.0.0-5.2.99";s:5:"typo3";s:12:"3.8.0-4.3.99";s:3:"cms";s:5:"0.0.0";s:18:"css_styled_content";s:5:"0.0.0";}}', 'Tolleiv Nietsch', 'extensions@myfirstname.de', 'sfischer', '8ef4ecc6e7d0f8b03148b3727d2e9fd9', 'Wizard can now be used in Flexforms, new Undo and Redo features, TYPO3 4.3 compatibility changes and Bugfixes. Extension is considered to be stable now.\r\nPlease send feedback or ratings if you like to extension.', '', 5003, 0, 0),
(20764, 0, 'imagemap_wizard', 1, '0.5.4', 1768, 85, 'Imagemap Wizard', 'Provides an TYPO3 Wizard which enables interactive Imagemap-Creation - related to the TYPO3-Linkwizard. Supported by AOE media.', 2, 0, 0, 1257001686, 'a:1:{s:7:"depends";a:4:{s:3:"php";s:12:"5.0.0-5.2.99";s:5:"typo3";s:12:"3.8.0-4.3.99";s:3:"cms";s:5:"0.0.0";s:18:"css_styled_content";s:5:"0.0.0";}}', 'Tolleiv Nietsch', 'extensions@myfirstname.de', 'sfischer', 'e5536014fd5a023cd42a207a8b8d8843', 'improved IE6-IE8 compatibility (mainly 5188), Imagemap-Review is rendered on access-restricted pages now (5139), using wz_jsgraphics v. 3.0.5 now', '', 5004, 0, 0),
(20765, 0, 'imagemap_wizard', 1, '0.5.5', 1768, 238, 'Imagemap Wizard', 'Provides an TYPO3 Wizard which enables interactive Imagemap-Creation - related to the TYPO3-Linkwizard. Supported by AOE media.', 2, 0, 0, 1259136139, 'a:1:{s:7:"depends";a:4:{s:3:"php";s:12:"5.0.0-5.2.99";s:5:"typo3";s:12:"3.8.0-4.3.99";s:3:"cms";s:5:"0.0.0";s:18:"css_styled_content";s:5:"0.0.0";}}', 'Tolleiv Nietsch', 'extensions@myfirstname.de', 'sfischer', '8b388b51fee38fddd84e282837b41a59', 'Userinterface improvements, TYPO3 4.3 compatibility improvements. use within common elements feature enabled (works only for the first image of the elements)', '', 5005, 0, 0),
(20766, 0, 'imagemap_wizard', 1, '0.5.6', 1768, 173, 'Imagemap Wizard', 'Provides an TYPO3 Wizard which enables interactive Imagemap-Creation - related to the TYPO3-Linkwizard. Supported by AOE media.', 2, 0, 0, 1280100674, 'a:1:{s:7:"depends";a:4:{s:3:"php";s:12:"5.0.0-5.2.99";s:5:"typo3";s:12:"3.8.0-4.3.99";s:3:"cms";s:5:"0.0.0";s:18:"css_styled_content";s:5:"0.0.0";}}', 'Tolleiv Nietsch', 'extensions@myfirstname.de', 'sfischer', '52e77f645d460b301545c1c2ca6b8929', 'Compatibility fixes for newer TYPO3 versions (sprites, deprecated functions replaced)', '', 5006, 0, 0),
