(21184, 0, 'spamshield', 1, '0.0.1', 1600, 8, 'Spamshield', 'Universal Spamshield for all Forms. Works like a spell and protects any form in Typo3 FrontEnd from spam without being noticed by human users.', 1, 0, 2, 1232833168, 'a:0:{}', 'Ronald P. Steiner, Alexander Kellner', 'ronald.steiner@googlemail.com, Alexander.Kellner@einpraegsam.net', 'sgalinsk', '547f26663cf060ba673a451022b24166', 'First release, enjoy', '', 1, 0, 0),
(21185, 0, 'spamshield', 1, '0.0.2', 1600, 4, 'Spamshield', 'Universal Spamshield for any forms in TYPO3 FrontEnd. Includes: javascirpt check, honeypot, renaming of form fields, unique check, session check, ... Works like a charm: invisible protection!', 1, 0, 2, 1232899264, 'a:0:{}', 'Ronald P. Steiner, Alexander Kellner', 'ronald.steiner@googlemail.com, Alexander.Kellner@einpraegsam.net', 'sgalinsk', 'c4ba3ce29a8223d684e3854d45c3c2ed', 'optional renaming of form fields to make it more hard for bots to fill the form\r\nimprovement in session and javascript check\r\nimproved logging', '', 2, 0, 0),
(21186, 0, 'spamshield', 1, '0.0.3', 1600, 2, 'Spamshield', 'Universal Spamshield for any forms in TYPO3 FrontEnd. Includes: javascirpt check, honeypot, renaming of form fields, unique check, session check, ... Works like a charm: invisible protection! This extension is the result of furthere development from wt_sp', 1, 0, 2, 1233087260, 'a:0:{}', 'Ronald P. Steiner, Alexander Kellner', 'ronald.steiner@googlemail.com, Alexander.Kellner@einpraegsam.net', 'sgalinsk', '7ff5294fd24f835a853b3c983c2ff369', 'give the various spam checks a weight and set total spam weight for baning.', '', 3, 0, 0),
