(21230, 0, 'logmail', 1, '0.0.1', 95, 5, 'Login Mail', 'Sends a Login Mail to a Frontend User. The Login Mail includes a link to a login page and a one time usable code.', 0, 0, 3, 1232908145, 'a:0:{}', 'Christof Hagedorn', 'christof.hagedorn@kinea.de', 'kinea', 'f70770e12c3a1e8b93eeebfdc0ebdbfc', '', '', 1, 0, 0),
(21231, 0, 'logmail', 1, '0.0.2', 95, 2, 'Login Mail', 'Sends a Login Mail to a Frontend User. The Login Mail includes a link to a login page and a one time usable code.', 0, 0, 3, 1232978866, 'a:0:{}', 'Christof Hagedorn', 'christof.hagedorn@kinea.de', 'kinea', 'e6f81705a250921ecfa3c3b3d09ee09d', 'Added important installation notes to the documentation.\r\nPasswords will be generated in case the extension is configured to register new users.\r\nStoragePID can be set with typoscript\r\nregisterNewUser is set to 0 by default.', '', 2, 0, 0),
(21232, 0, 'logmail', 1, '0.0.3', 95, 2, 'Login Mail', 'Sends a Login Mail to a Frontend User. The Login Mail includes a link to a login page and a one time usable code.', 0, 0, 3, 1232980011, 'a:0:{}', 'Christof Hagedorn', 'christof.hagedorn@kinea.de', 'kinea', 'cc7c50c52e1e0ae54c4fa29f52837190', 'Made some language and label correction the language files.', '', 3, 0, 0),
