(21236, 0, 'logmail', 1, '0.0.7', 95, 4, 'Login Mail', 'Sends a Login Mail to a Frontend User. The Login Mail includes a link to a login page and a one time usable code.', 0, 0, 3, 1303944358, 'a:0:{}', 'Christof Hagedorn', 'christof.hagedorn@kinea.de', 'kinea', 'bae15cc60765906f7a572d5570ebca47', 'Added the option to use the eID mechanism to login the users. (f.e. if you like to restrict access to the logmail plugin for special users)', '', 7, 0, 0),
(21237, 0, 'logmail', 1, '0.0.8', 95, 2, 'Login Mail', 'Sends a Login Mail to a Frontend User. The Login Mail includes a link to a login page and a one time usable code.', 0, 0, 3, 1303983224, 'a:0:{}', 'Christof Hagedorn', 'christof.hagedorn@kinea.de', 'kinea', '5cc53f9239a71d7f28111e5f8c69da1d', 'The option to use the eID mechanism to login is now possible without changing the localconf.\r\nJust set the typoscript option\r\nplugin.tx_logmail_pi1.useEID1', '', 8, 0, 0),
(21238, 0, 'logmail', 1, '0.0.9', 95, 6, 'Login Mail', 'Authenticating of frontend-users by email! Users can login without a password, just by clicking a link in an email (optional with autoregistration of user). Users enter the email address in a textfield, the form sends a "login mail" to the user. The login', 0, 0, 3, 1303990041, 'a:0:{}', 'Christof Hagedorn', 'christof.hagedorn@kinea.de', 'kinea', 'b47f9521d8ada73b2c831b16c812b108', 'The option to use the eID mechanism to login is now possible without changing the localconf. Just set the typoscript option plugin.tx_logmail_pi1.useEID1', '', 9, 0, 0),
(21239, 0, 'logmail', 1, '0.0.10', 95, 18, 'Login Mail', 'Authenticating of frontend-users by email! Users can login without a password, just by clicking a link in an email (optional with autoregistration of user).', 0, 0, 3, 1303997712, 'a:0:{}', 'Christof Hagedorn,Anselm Cosler,Katja Stricker', 'christof.hagedorn@kinea.de', 'kinea', '24d012b9be04534dcdb86cf2afe75b32', 'Improved the documentation', 'KINEA Informationsdesign', 10, 0, 0),
(21240, 0, 'logmail', 1, '0.1.0', 95, 22, 'Login Mail', 'Authenticating of frontend-users by email! Users can login without a password, just by clicking a link in an email (optional with autoregistration of user).', 0, 0, 3, 1323764108, 'a:0:{}', 'Christof Hagedorn,Anselm Cosler,Katja Stricker', 'christof.hagedorn@kinea.de', 'kinea', '4580e88f486e0ff1a04c03912bffaf2f', 'configure timetolive values for logmails\r\nconfigure labels with typoscript\r\nswitch for using eID for protected pages', 'KINEA Informationsdesign', 1000, 1, 0),
