(21368, 0, 'dkm_ttnewscobjmarkers', 1, '0.1.0', 61, 61, 'tt_news cObject markers', 'This extension makes it possible extend tt_news by adding your own markers through the use of TS setup. The content for the markers is added through a COA/cObjectArray content object.', 2, 0, 3, 1233912495, 'a:1:{s:7:"depends";a:1:{s:7:"tt_news";s:0:"";}}', 'Stig Nrgaard Frch', 'stig@8620.dk', 'inshadow', 'bbdb4aa4c3dd9217775b62941a505ec1', 'initial release.', '', 1000, 1, 0),
(21369, 0, 'nd_library', 1, '0.0.23', 59, 8, 'Library', 'Collect your books, search through them and filter them. Adding a book is made as easy as entering the ISBN (fetched through amazon).', 0, 0, 3, 1234015859, 'a:0:{}', 'Andreas Lappe', 'off-pist.de', 'crazynd', 'ebebea5aafca38b48d4404ae83fe5ecb', 'First version in TER', '', 23, 0, 0),
