(21371, 0, 'varfeform', 1, '1.0.0', 32, 6, 'Variable Form for FE', 'Variables Forumlar fr den FE mit List Ausgabe', 0, 0, 3, 1234133506, 'a:0:{}', 'Michael Preis', 'info@simadesign.de', 'msvp', 'e6f9e12f9774a60c120b6692abcac4d4', 'First version of varfeform.\r\n\r\n- You can add oder delete up to 20 new fields\r\n- Use every single field as you wich with your own template file\r\n- shows up to 20 fields in a frontend Form which can be optimized with your template file (give them names, as', '', 1000000, 0, 0),
(21372, 0, 'varfeform', 1, '1.1.0', 32, 3, 'Variable Form for FE', 'Variables Forumlar fr den FE mit List Ausgabe', 0, 0, 3, 1234208539, 'a:0:{}', 'Michael Preis', 'info@simadesign.de', 'msvp', 'ad296fec549db50972776868cfb8fc7f', '- Add a manual with screenshots and an extension-Icon', '', 1001000, 0, 0),
(21373, 0, 'varfeform', 1, '1.2.0', 32, 23, 'Variable Form for FE', 'Adds an variable Form to your page.', 0, 0, 3, 1237296006, 'a:0:{}', 'Michael Preis', 'info@simadesign.de', 'msvp', 'd4376d339305c281fbb3ac9c90745cd6', '- You can now use Fileupload Fields in your form. The script will test each formfield. If there is any file with the format jpeg or gif, it will upload it in the uploads/extension Folder up to 1 MB.\r\n Also the script creates two thumbnails with 100 px an', 'SiMa Design', 1002000, 1, 0),
(21374, 0, 'a21glossary_preselected', 1, '1.0.0', 55, 4, 'a21glossary preselected terms', 'Display selected glossary records only', 1, 0, 3, 1234196178, 'a:1:{s:7:"depends";a:1:{s:11:"a21glossary";s:0:"";}}', 'Sven Burkert', 'sventb@googlemail.com', 'sventb', 'a87f5b6d14ee28bafa3cdf1847e1bc50', '', '', 1000000, 0, 0),
(21375, 0, 'a21glossary_preselected', 1, '1.0.1', 55, 51, 'a21glossary preselected terms', 'Select your preferred glossary records and display them in frontend. You can use this plugin as teaser or for the first page of your glossary, for example.', 1, 0, 3, 1234252716, 'a:1:{s:7:"depends";a:1:{s:11:"a21glossary";s:0:"";}}', 'Sven Burkert', 'sventb@googlemail.com', 'sventb', '99e9e402fe56209868f8b6a1ef067525', 'Updated manual', 'netz98', 1000001, 0, 0),
(21376, 0, 'a21glossary_preselected', 1, '1.0.2', 55, 0, 'a21glossary preselected terms', 'Select your preferred glossary records and display them in frontend. You can use this plugin as teaser or for the first page of your glossary, for example.', 1, 0, 3, 1409051280, 'a:1:{s:7:"depends";a:2:{s:11:"a21glossary";s:0:"";s:5:"typo3";s:12:"4.5.0-4.5.99";}}', 'Sven Burkert', 'sventb@googlemail.com', 'sventb', 'c70b5e344499c7b6a5c0163fc11e467a', 'Mention dependencies', 'netz98', 1000002, 1, 0),
(21377, 0, 'multilinepgttl', 1, '2.0.0', 42, 42, 'CWS - Multi Line Page Title', 'This extension extends the backend so that you can enter the page titles in multiple lines.\n		The extension even contains Static TypoScript code and code examples for creating menu items with multiple lines.!!!', 1, 0, 2, 1234246746, 'a:0:{}', 'Prakash A Bhat (spabhat)', 'spabhat@chandanweb.com', 'spabhat', '475be0492a25d97c3dd7b1ceda41326f', ' First commint to Typo3 repository\r\n Document updated', 'Chandan Web Solutions', 2000000, 1, 0),
