(21387, 0, 'n98_mailenstein_registration', 1, '1.1.0', 66, 9, 'netz98 - Mailenstein Registrierungsformular', 'Ein Formular wird via SOAP Schnittstelle vom Mailenstein-Server erstellt. Achtung! Es wird die PHP Extension "SOAP" bentigt.', 2, 0, 3, 1234273553, 'a:0:{}', 'Peter Schulz, Christian Mnch, Sven Burkert', 'p.schulz@netz98.de, c.muench@netz98.de, s.burkert@netz98.de', 'sventb', 'b1a16becfbef20615e414b20d6a4ccdc', 'Some minor changes, e.g. default text for messages\r\nManual added', 'netz98', 1001000, 0, 0),
(21388, 0, 'n98_mailenstein_registration', 1, '1.1.1', 66, 57, 'netz98 - Mailenstein Registrierungsformular', 'Newsletter registration form for german e-mail marketing system mailenstein.de.', 2, 0, 3, 1234273795, 'a:0:{}', 'Peter Schulz, Christian Mnch, Sven Burkert', 'p.schulz@netz98.de, c.muench@netz98.de, s.burkert@netz98.de', 'sventb', 'c210a7d699e8aa29a7ae6c7d2d614870', 'Some minor changes, e.g. default text for messages\r\nManual added', 'netz98', 1001001, 1, 0),
