(21390, 0, 'browser', 1, '1.0.2', 3146, 8, 'Browser', 'Displays content from related tables in the frontend in list and single views. You need 8 lines typoscript for a list with a search and a file browser only. Browser wraps images, every table field has the stdWrap property. With SEO, Search Engine Optimisa', 0, -1, 3, 1234377649, 'a:0:{}', 'Dirk Wildt (Die Netzmacher)', 'dirk.wildt.at.die-netzmacher.de', 'dwildt', '547461e99d4e03e7d5599c7859774726', 'Publishing. Browser substitutes the extension Frontend Database Browser (extKey: fe_db_brwoser)', '', 1000002, 0, 0),
(21391, 0, 'browser', 1, '1.0.3', 3146, 7, 'Browser', 'Displays content from related tables in the frontend in list and single views. You need 8 lines typoscript for a list with a search and a file browser only. Browser wraps images, every table field has the stdWrap property. With SEO, Search Engine Optimisa', 0, -1, 3, 1234889779, 'a:0:{}', 'Dirk Wildt (Die Netzmacher)', 'dirk.wildt.at.die-netzmacher.de', 'dwildt', '24b13e8aef1c95427cecc0a8efbf4eee', 'Bugfix TCA internal_type: There was a bug in case of relation and a missing internal_type field in the TCA', '', 1000003, 0, 0),
(21392, 0, 'browser', 1, '1.0.4', 3146, 8, 'Browser', 'Displays content from related tables in the frontend in list and single views. You need 8 lines typoscript for a list with a search and a file browser only. Browser wraps images, every table field has the stdWrap property. With SEO, Search Engine Optimisa', 0, -1, 3, 1235320265, 'a:0:{}', 'Dirk Wildt (Die Netzmacher)', 'dirk.wildt.at.die-netzmacher.de', 'dwildt', '16459fe8a4eac399d1a6e2f7340403c9', 'Bugfix: Search doesnt worked, if the SQL-debug-mode was off', '', 1000004, 0, 0),
(21393, 0, 'browser', 1, '1.1.1', 3146, 10, 'Browser', 'Displays content from related tables in the frontend in list and single views. You need 8 lines typoscript for a list with a search and a file browser only. Browser wraps images, every table field has the stdWrap property. With SEO, Search Engine Optimisa', 0, -1, 3, 1235424779, 'a:0:{}', 'Dirk Wildt (Die Netzmacher)', 'dirk.wildt.at.die-netzmacher.de', 'dwildt', 'd87e85f1a6d232febce6d9eaf224269f', 'New Feature:A-Z-Browser. Configureable by typoscript. New default CSS stylesheet.', '', 1001001, 0, 0),
(21394, 0, 'browser', 1, '2.3.1', 3146, 9, 'Browser', 'Displays content from related tables in the frontend. You need 1 line typoscript for a result list with a search form, a record browser and an a-z browser. Images are wrapped self-acting. With SEO, Search Engine Optimisation. The log displays the SQL rela', 0, -1, 3, 1242055586, 'a:0:{}', 'Dirk Wildt (Die Netzmacher)', 'dirk.wildt.at.die-netzmacher.de', 'dwildt', '51f32d2b3c1d63c7e52c8422ebce91d3', 'Manual is up to date (nearby). New Features: Templating with TT_CONTAINER. DRS - Development Reporting System. SQL query definition with JOINS manually. A-Z-Browser can process utf-8 database und multi-byte charset in PHP. The SEO meta tags title, keyword', '', 2003001, 0, 0),
(21395, 0, 'browser', 1, '2.3.2', 3146, 35, 'Browser', 'Browser - The fastest way for your data into the TYPO3 frontend. Displays content from related tables in the frontend. You need 1 line typoscript for a result list with a search form, a record browser and an a-z browser. Images are wrapped self-acting. SE', 0, -1, 3, 1242157749, 'a:0:{}', 'Dirk Wildt (Die Netzmacher)', 'dirk.wildt.at.die-netzmacher.de', 'dwildt', 'f32cf2631d009db4df2fbbace1cc04df', 'MARKER and piVars will replaced in the TypoScript now. Updating the manual.', '', 2003002, 0, 0),
(21396, 0, 'browser', 1, '2.3.3', 3146, 10, 'Browser - Highway to Frontend', 'Browser - Fast way for your data to the TYPO3 frontend. Displays content from related tables. You need 1 line typoscript for a result list with a search form, a record browser and an a-z browser. Images are wrapped self-acting. SEO, Search Engine Optimisa', 0, -1, 3, 1243522511, 'a:0:{}', 'Dirk Wildt (Die Netzmacher)', 'dirk.wildt.at.die-netzmacher.de', 'dwildt', '996acdb4344b5e7b434cda4f223effb8', 'Maintenance: Simplifying the SQL query in case there is a configured search but there isnt any sword. Bugfixing: There was a bug in case of using relation.mm and LEFT JOIN and more than two related tables. There was a bug with handleAs[document]', '', 2003003, 0, 0),
(21397, 0, 'browser', 1, '2.3.4', 3146, 13, 'Browser - Highway to Frontend', 'Browser - Fast way for your data to the TYPO3 frontend. Displays content from related tables. You need 1 line typoscript for a result list with a search form, a record browser and an a-z browser. Images are wrapped self-acting. SEO, Search Engine Optimisa', 0, -1, 3, 1243527346, 'a:0:{}', 'Dirk Wildt (Die Netzmacher)', 'dirk.wildt.at.die-netzmacher.de', 'dwildt', '051a0e72daae73425e9f4078b4f2c365', 'Update Manual', '', 2003004, 0, 0),
(21398, 0, 'browser', 1, '2.3.6', 3146, 10, 'Browser - Highway to Frontend', 'Browser - Fast way for your data to the TYPO3 frontend. Displays content from related tables. You need 1 line typoscript for a result list with a search form, a record browser and an a-z browser. Images are wrapped self-acting. SEO, Search Engine Optimisa', 0, -1, 3, 1244244065, 'a:0:{}', 'Dirk Wildt (Die Netzmacher)', 'dirk.wildt.at.die-netzmacher.de', 'dwildt', 'cd148b850f5136aea0e25af972cd32fb', '  Maintenance\n  - Extending the A-Z-Browser with the defaultTabWrap property\n  - Extending SQL manual mode for single views\n  - Integration of the function hierarchically order\n  Documentation\n  - Extending the manual with examples for\n    - the synonym f', '', 2003006, 0, 0),
(21399, 0, 'browser', 1, '2.3.7', 3146, 23, 'Browser - Highway to Frontend', 'Browser - Fast way for your data to the TYPO3 frontend. Displays content from related tables. You need 1 line typoscript for a result list with a search form, a record browser and an a-z browser. Images are wrapped self-acting. SEO, Search Engine Optimisa', 0, -1, 3, 1244838265, 'a:0:{}', 'Dirk Wildt (Die Netzmacher)', 'dirk.wildt.at.die-netzmacher.de', 'dwildt', '6a7684bc6ca09703af990d7fc6b2519c', 'Maintenance - Simplification of real URL configuration\n', '', 2003007, 0, 0),
(21400, 0, 'browser', 1, '3.0.1', 3146, 39, 'Browser - The Frontend Engine', 'Browser  - Highway to Frontend. The frontend engine displays content from related tables. You need 1 line typoscript for a result list with a search form, a record browser and an a-z browser. Images are wrapped self-acting. SEO, Search Engine Optimisation', 1, -1, 3, 1255021290, 'a:0:{}', 'Dirk Wildt (Die Netzmacher)', 'wildt.at.die-netzmacher.de', 'dwildt', '27c03e9d2f825cabf7b6a54e40859053', 'Major Version Release. New Features: Multiple Plugins, Localization, Filter, TypoSCript Update Assistent, Self-defined Markers, Sword has AND functionality by default, Flexform. Maintenance: Consolidation. Security: Enhanced security handling of piVars. T', '', 3000001, 0, 0),
(21401, 0, 'browser', 1, '3.0.2', 3146, 17, 'Browser - The Frontend Engine', 'Browser  - Highway to Frontend. The frontend engine displays content from related tables. You need 1 line typoscript for a result list with a search form, a record browser and an a-z browser. Images are wrapped self-acting. SEO, Search Engine Optimisation', 1, -1, 3, 1255112943, 'a:0:{}', 'Dirk Wildt (Die Netzmacher)', 'wildt.at.die-netzmacher.de', 'dwildt', 'f03b6ad8754ec25946061f2c4856e086', 'Maintenance: Suggest to install Extension\n', '', 3000002, 0, 0),
