(21527, 0, 'daimi_responsible', 1, '1.0.0', 87, 9, 'Responsible', 'Show who is responsible for the content of a page, optional emailadress or link to issuetracking system', 2, 0, 3, 1234531230, 'a:0:{}', 'Morten Nisker', 'nisker@cs.au.dk', 'daimi', 'e7cd129a311a64fe3f82da1382701208', 'Initial upload', '', 1000000, 0, 0),
