(21529, 0, 'daimi_responsible', 1, '1.1.0', 87, 12, 'Responsible', 'Show who is responsible for the content of a page, optional emailadress or link to issuetracking system', 2, 0, 3, 1242629736, 'a:0:{}', 'Morten Nisker', 'nisker@cs.au.dk', 'daimi', 'f77e02c2bcea07692d9760dabca04a7b', 'Added optional parameter default name/email- is used if a pageowner is missing name and/or email.\nMisc. bugfixes:\n- javascript crash if  in pagetitle\n- text set in _LOCAL_LANG with TS did not overload\n- a few minor issues.\n', '', 1001000, 0, 0),
(21530, 0, 'daimi_responsible', 1, '1.2.0', 87, 8, 'Responsible', 'Show who is responsible for the content of a page, optional emailadress or link to issuetracking system', 2, 0, 3, 1257408546, 'a:0:{}', 'Morten Nisker', 'nisker@cs.au.dk', 'daimi', 'ed9497db13ea180728759c27c76e0e7b', 'Added workaround for same chars breaking spamProtectEmailAdress javascript. \r\nAdded option to urlEncode mailto link - wont work if you use spamProtectEmailAdress\r\nIf responsible comes from tt_news record and Id is added to the mail subject, tt_news Id is ', '', 1002000, 0, 0),
(21531, 0, 'daimi_responsible', 1, '1.2.1', 87, 21, 'Responsible', 'Show who is responsible for the content of a page, optional emailadress or link to issuetracking system', 2, 0, 3, 1257774840, 'a:0:{}', 'Morten Nisker', 'nisker@cs.au.dk', 'daimi', '43198d8a0987cc9a21b2d621ea97f714', 'Fixed a bug with author information not being correct localized, when taken from metadata.', '', 1002001, 0, 0),
(21532, 0, 'daimi_responsible', 1, '1.2.2', 87, 28, 'Responsible', 'Show who is responsible for the content of a page, optional emailadress or link to issuetracking system', 2, 0, 3, 1276767687, 'a:0:{}', 'Morten Nisker', 'nisker@cs.au.dk', 'daimi', '3f10e4c131ae1ec57c3ab25df39d945c', 'Fixes a a bug with display of responsible info for singleview tt_news page.', '', 1002002, 1, 0),
(21533, 0, 'smile_jumpurl_fix', 1, '2.0.0', 34, 34, 'Smile JumpURL HotFix', 'Fix Typo3 Bug "typo3-sa-2009-002":\n\nAn Information Disclosure vulnerability in jumpUrl mechanism, used to track access on web pages and provided files, allows a remote attacker to read arbitrary files on a host.\nThe expected value of a mandatory hash secr', 2, 0, 4, 1234537721, 'a:0:{}', 'Smile', 'rolel@smile.fr', 'badr', '31e69695eb3e111333d8d3e2ac505096', 'First Public Release.\nThis extension hotfix the "typo3-sa-2009-002" bug. \nYou do not need this extension if youre using Typo3 4.2.6 or more recent.', '', 2000000, 0, 0),
(21534, 0, 'smile_jumpurl_fix', 1, '2.0.1', 34, 0, '[Smile] JumpURL HotFix', 'Fix Typo3 Bug "typo3-sa-2009-002":\n\nAn Information Disclosure vulnerability in jumpUrl mechanism, used to track access on web pages and provided files, allows a remote attacker to read arbitrary files on a host.\nThe expected value of a mandatory hash secret, intended to invalidate such requests, is exposed to remote users allowing them to bypass access control by providing the correct value.\nTheres no authentication required to exploit this vulnerability. The vulnerability allows to read any file, the web server user account has access to.\n\nhttp://typo3.org/teams/security/security-bulletins/typo3-core/typo3-sa-2009-002/\n\nSee README.txt in the extension package.', 5, 0, 4, 1400085333, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:11:"4.1.0-4.2.5";}}', 'Smile', 'typo3@smile.fr', 'badr', '4f4fc6179b63d370fb4679b8d6ceed13', 'Now obsolete. Please update core.', '', 2000001, 1, 0),
(21535, 0, 'cs_rte_no_fsbutton', 1, '1.0.0', 26, 26, 'Hide fullscreen button next to RTE', 'This extension allows you to hide the fullscreen button next to the editing area of the RTE.\nIt does not disable the fullscreen mode in general. You can still click on "Edit in RTE" in columns view to get the fullscreen mode.', 2, 0, 0, 1234639231, 'a:0:{}', 'Christopher', 'Chrissitopher@gmx.de', 'chrissitopher', '1a9c5655df3ce09bd0381e551a0b9eae', '', '', 1000000, 0, 0),
