(21549, 0, 'sb_portfolio', 1, '2.0.0', 1103, 128, 'SB Portfolio', 'Portfolio for Webdesign and illustration etc.', 2, 0, 3, 1266540495, 'a:0:{}', 'Stephen Bungert', 'stephenbungert@yahoo.de', 'stephenbungert', '949962a4891c2ec00201aef2c0d41bc0', 'Major update. Many new features and optimisations. Support for jQuery Tabs, jQuery Carousel, and Lightboxes. Lots of additional features and functionality.', '', 2000000, 0, 0),
(21550, 0, 'sb_portfolio', 1, '2.0.1', 1103, 115, 'SB Portfolio', 'Portfolio for Webdesign and illustration etc.', 2, 0, 3, 1266663765, 'a:0:{}', 'Stephen Bungert', 'stephenbungert@yahoo.de', 'stephenbungert', 'b1c57bda3f00a5be00f6a5b76f297453', 'Changed manual so that it is more readable.\r\n\r\nAdded a section to the manual about using sb_portfolio with tt_news\r\n\r\nBUGFIX: Made it possible to actually see the list/grid in tt_news. Sorry. This was disabled for bug checking by me', '', 2000001, 0, 0),
