(21560, 0, 'sb_portfolio', 1, '2.4.2', 1103, 50, 'SB Portfolio', 'Portfolio for Webdesign and illustration etc.', 1, 0, 3, 1291564093, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:9:"5.0-0.0.0";s:5:"typo3";s:11:"4.3.0-0.0.0";}}', 'Stephen Bungert', 'stephenbungert@yahoo.de', 'stephenbungert', '0abe22a13f7151dd296f6966fe94c7e0', 'Fixed a bug with categories in Single display mode. Not all the categories were displayed.\r\nFixed a bug in the FlexForm.', '', 2004002, 0, 0),
