INSERT INTO `tx_extensionmanager_domain_model_extension` (`uid`, `pid`, `extension_key`, `repository`, `version`, `alldownloadcounter`, `downloadcounter`, `title`, `description`, `state`, `review_state`, `category`, `last_updated`, `serialized_dependencies`, `author_name`, `author_email`, `ownerusername`, `md5hash`, `update_comment`, `authorcompany`, `integer_version`, `current_version`, `lastreviewedversion`) VALUES
(21606, 0, 'sav_jpgraph', 1, '0.0.3', 257, 5, 'SAV JpGraph', 'This extension makes it possible to generate JpGraph from xml files.\nIt includes templating for JpGraph, data queries, markers, ...', 2, 0, 3, 1236545854, 'a:0:{}', 'Yolf (Laurent Foulloy)', 'yolf.typo3@orange.fr', 'yolf', '76b0bf2c30f47175998837340883bb46', '1.Configuration added for the TTF directory.\n2.Method setArrayFromQuery added in data.\n3.CSH added in English and French.', '', 3, 0, 0),
(21607, 0, 'sav_jpgraph', 1, '0.0.4', 257, 7, 'SAV JpGraph', 'This extension makes it possible to generate JpGraph from xml files.\nIt includes templating for JpGraph, data queries, markers, ...', 2, 0, 3, 1237849717, 'a:0:{}', 'Yolf (Laurent Foulloy)', 'yolf.typo3@orange.fr', 'yolf', '41469d37d3719214ce27e740447e7b2a', '1.typo3 tag added to process queries in other extensions.', '', 4, 0, 0),
(21608, 0, 'sav_jpgraph', 1, '0.0.5', 257, 15, 'SAV JpGraph', 'This extension makes it possible to generate JpGraph from xml files.\nIt includes templating for JpGraph, data queries, markers, ...', 2, 0, 3, 1238702631, 'a:0:{}', 'Yolf (Laurent Foulloy)', 'yolf.typo3@orange.fr', 'yolf', '964aa26c7d8da7df7a4db96bc1aa0ccd', '1.Translations available through the translation server.', '', 5, 0, 0),
(21609, 0, 'sav_jpgraph', 1, '0.0.6', 257, 9, 'SAV JpGraph', 'This extension makes it possible to generate JpGraph from xml files.\nIt includes templating for JpGraph, data queries, markers, ...', 2, 0, 3, 1240937236, 'a:0:{}', 'Yolf (Laurent Foulloy)', 'yolf.typo3@orange.fr', 'yolf', 'dfbad100c75b5dd0371c782eff3b24af', 'Improve the localization for translation purpose (feature 3199).', '', 6, 0, 0),
(21610, 0, 'sav_jpgraph', 1, '0.0.7', 257, 8, 'SAV JpGraph', 'This extension makes it possible to generate JpGraph from xml files.\nIt includes templating for JpGraph, data import, markers, ...', 2, 0, 3, 1244538065, 'a:0:{}', 'Yolf (Laurent Foulloy)', 'yolf.typo3@orange.fr', 'yolf', '096b51a232439c362d5feef7f81cb456', '1.The extension runs as a USER plugin except when queries are used. In this case the extension runs as a USER_INT plugin. The change is performed using a XCLASS of the class tslib_cObj based on an idea taken from Dmitry Dulepov (see See the TYPO3 bugtrack', '', 7, 0, 0),
(21611, 0, 'sav_jpgraph', 1, '0.0.8', 257, 8, 'SAV JpGraph', 'This extension makes it possible to generate JpGraph from xml files.\nIt includes templating for JpGraph, data import, markers, ...', 2, 0, 3, 1245956885, 'a:0:{}', 'Yolf (Laurent Foulloy)', 'yolf.typo3@orange.fr', 'yolf', '792b450f75a654b02644e2a09cee3b22', '1.Small correction in the code to improve the use of php constants.\n2.New template radarex7.xml added', '', 8, 0, 0),
(21612, 0, 'sav_jpgraph', 1, '0.0.9', 257, 7, 'SAV JpGraph', 'This extension makes it possible to generate JpGraph from xml files.\nIt includes templating for JpGraph, data import, markers, ...', 2, 0, 3, 1248638816, 'a:0:{}', 'Yolf (Laurent Foulloy)', 'yolf.typo3@orange.fr', 'yolf', '5a04d932bdd15699d604b89b10275cf3', '1.JpGraph Library updated to v3.0.1 released on 24/07/2009.', '', 9, 0, 0),
(21613, 0, 'sav_jpgraph', 1, '0.0.10', 257, 4, 'SAV JpGraph', 'This extension makes it possible to generate JpGraph from xml files.\nIt includes templating for JpGraph, data import, markers, ...', 2, 0, 3, 1249763020, 'a:0:{}', 'Yolf (Laurent Foulloy)', 'yolf.typo3@orange.fr', 'yolf', '689e17819c97d0200f8b56dc73ae91d9', '1.JpGraph Library updated to v3.0.2 released on 01/08/2009.', '', 10, 0, 0),
(21614, 0, 'sav_jpgraph', 1, '0.0.11', 257, 4, 'SAV JpGraph', 'This extension makes it possible to generate JpGraph from xml files.\nIt includes templating for JpGraph, data import, markers, ...', 2, 0, 3, 1252535166, 'a:0:{}', 'Yolf (Laurent Foulloy)', 'yolf.typo3@orange.fr', 'yolf', '4a946f06db6e713c7753cdeb26a9093a', '1.Bug when using TYPO3 4.3 fixed (Bug 4193).\n2.JpGraph Library updated to v3.0.2 released on 02/09/2009.\n3.Two new templates added (groupBarPlot.xml and accBarPlot.xml)', '', 11, 0, 0),
(21615, 0, 'sav_jpgraph', 1, '0.0.12', 257, 10, 'SAV JpGraph', 'This extension makes it possible to generate JpGraph from xml files.\nIt includes templating for JpGraph, data import, markers, ...', 2, 0, 3, 1253461591, 'a:0:{}', 'Yolf (Laurent Foulloy)', 'yolf.typo3@orange.fr', 'yolf', '64592263ef4e62f7a5e0433c4b2b84b7', 'New feature added. Overloaded tags are automatically displayed in the BE flexform. By double-clicking on a tag, it is inserted in the related section.', '', 12, 0, 0),
