(21770, 0, 'metaext', 1, '0.2.2', 414, 7, ' SEO Features', 'This extension provides you with an editable set of all the important config parameters including multilanguage settings, adds additional metatag fields to the page module and provides global settings for some of them (those who make sense to be filled', 1, 0, 0, 1237147420, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:11:"4.2.0-0.0.0";}}', 'Michael Iggy Rudolph - sensomedia.de', 'info@sensomedia.de', 'sensomedia', '1e9c476ee44cc28f3975a24f023559e0', 'initial ter', 'sensomedia.de', 2002, 0, 0),
