(21809, 0, 'ab_booking', 1, '0.3.0', 853, 26, 'Simple booking extension', 'An availability calendar is presentable for each item/room. You may check the date and enter your details for booking.\nAnother view is an availability check.', 1, 0, 3, 1260826205, 'a:1:{s:7:"depends";a:1:{s:14:"ab_swiftmailer";s:0:"";}}', 'Alexander Bigga', 'linux@bigga.de', 'albigdd', '171cb526c524066a6c95974307614869', 'Add single line list mode as calendar view. Replace support for rlmp_dateselect with date2cal. Make date2cal optional. Code cleanup. Going Beta now.\r\n', '', 3000, 0, 0),
(21810, 0, 'ab_booking', 1, '0.3.1', 853, 27, 'Simple booking extension', 'An availability calendar is presentable for each item/room. You may check the date and enter your details for booking.\nAnother view is an availability check.', 1, 0, 3, 1260981435, 'a:0:{}', 'Alexander Bigga', 'linux@bigga.de', 'albigdd', '5889274829b491ba3b1eedfaca4434ff', 'Fix some PHP warnings. Make ab_swiftmailer optional. Updated documentation.', '', 3001, 0, 0),
