(21812, 0, 'ab_booking', 1, '0.3.3', 853, 42, 'Simple booking extension', 'An availability calendar is presentable for each item/room. You may check the date and enter your details for booking.\nAnother view is an availability check.', 1, 0, 3, 1263380572, 'a:0:{}', 'Alexander Bigga', 'linux@bigga.de', 'albigdd', '7777f25d7139b1bc2096d57f0c9917ba', 'Fix issue with date2cal checkbox. This is shown now to avoid javascript errors. With date2cal 7.4.0 it may be deselected hopefully.', '', 3003, 0, 0),
(21813, 0, 'ab_booking', 1, '0.3.4', 853, 17, 'Simple booking extension', 'An availability calendar is presentable for each item/room. You may check the date and enter your details for booking.\nAnother view is an availability check.', 1, 0, 3, 1265828763, 'a:0:{}', 'Alexander Bigga', 'linux@bigga.de', 'albigdd', '34ff41deb86092d04d93c7831997820a', 'This release fixes some minor bugs. The flexform is reworked. So please check each plugins, save again and clear the cache!\r\nNow its possible to display months in one row.\r\nA new feature (remote query) is introduced but doesnt have any effect yet.', '', 3004, 0, 0),
(21814, 0, 'ab_booking', 1, '0.3.5', 853, 29, 'Simple booking extension', 'An availability calendar is presentable for each item/room. You may check the date and enter your details for booking.\nAnother view is an availability check.', 1, 0, 3, 1265881121, 'a:0:{}', 'Alexander Bigga', 'linux@bigga.de', 'albigdd', 'a2c5902c221fdb1129438653357aa643', 'This fix compatibility with Typo3 4.2.x.', '', 3005, 0, 0),
(21815, 0, 'ab_booking', 1, '0.3.6', 853, 3, 'Simple booking extension', 'An availability calendar is presentable for each item/room. You may check the date and enter your details for booking.\nAnother view is an availability check.', 1, 0, 3, 1272357910, 'a:0:{}', 'Alexander Bigga', 'linux@bigga.de', 'albigdd', '84eb223913650aee255f0852939b4941', 'Fixed a bug reported by Lim Chivy concerning the usage of the storage PID. Added a "progress bar" to show  the booking steps: enter - verify - finished', '', 3006, 0, 0),
(21816, 0, 'ab_booking', 1, '0.3.7', 853, 3, 'Simple booking extension', 'An availability calendar is presentable for each item/room. You may check the date and enter your details for booking.\nAnother view is an availability check.', 1, 0, 3, 1273780518, 'a:0:{}', 'Alexander Bigga', 'linux@bigga.de', 'albigdd', 'e207a8b124ed6d2184e2b06ee5a2b286', 'This fixes serveral PHP warnings and an error in sending emails without ab_swiftmailer', '', 3007, 0, 0),
(21817, 0, 'ab_booking', 1, '0.3.8', 853, 9, 'Simple booking extension', 'An availability calendar is presentable for each item/room. You may check the date and enter your details for booking.\nAnother view is an availability check.', 1, 0, 3, 1273835209, 'a:0:{}', 'Alexander Bigga', 'linux@bigga.de', 'albigdd', 'be82f96c617a196931ccce293d02df86', 'bugfix in 0.3.7. error message is shown if you select more than one room/product', '', 3008, 0, 0),
(21818, 0, 'ab_booking', 1, '0.4.0', 853, 5, 'Simple booking extension', 'An availability calendar is presentable for each item/room. You may check the date and enter your details for booking.\nAnother view is an availability check.', 1, 0, 3, 1278505901, 'a:0:{}', 'Alexander Bigga', 'linux@bigga.de', 'albigdd', '7b368110cafe59e1089e02717ff73cb0', 'This adds support for seasonal prices. After upgrade you have to add at least one season and assign it to your prices.\r\nPlease edit/save all flexform plugins otherwise you loose the number of persons selector in the availability check form.', '', 4000, 0, 0),
(21819, 0, 'ab_booking', 1, '0.4.1', 853, 67, 'Simple booking extension', 'An availability calendar is presentable for each item/room. You may check the date and enter your details for booking.\nAnother view is an availability check.', 1, 0, 3, 1294780957, 'a:0:{}', 'Alexander Bigga', 'linux@bigga.de', 'albigdd', '69baf84e67cd5e06726263ee4ff4e7f9', 'Bugfixes\r\n\r\nNew demo-site http://ab_booking.bigga.de', '', 4001, 0, 0),
(21820, 0, 'ab_booking', 1, '0.4.2', 853, 66, 'Simple booking extension', 'An availability calendar is presentable for each item/room. You may check the date and enter your details for booking.\nAnother view is an availability check.', 1, 0, 3, 1294781165, 'a:0:{}', 'Alexander Bigga', 'linux@bigga.de', 'albigdd', '7d5619c32c7036ee69e2ab21bef7b04f', 'Sorry, bugfix release version was wrong in 0.4.1', '', 4002, 0, 0),
(21821, 0, 'ab_booking', 1, '0.4.3', 853, 75, 'Simple booking extension', 'An availability calendar is presentable for each item/room. You may check the date and enter your details for booking.\nAnother view is an availability check.', 1, 0, 3, 1298388069, 'a:0:{}', 'Alexander Bigga', 'linux@bigga.de', 'albigdd', 'a379ff29e5b6b6ac2a8709b4c7d4857c', '- bugfix 12834 and 12972\r\n- some style changes\r\n- check your rates and seasons after upgrade!', '', 4003, 0, 0),
(21822, 0, 'ab_booking', 1, '0.4.4', 853, 46, 'Simple booking extension', 'An availability calendar is presentable for each item/room. You may check the date and enter your details for booking.\nAnother view is an availability check.', 1, 0, 3, 1307391930, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:11:"4.4.0-0.0.0";}}', 'Alexander Bigga', 'linux@bigga.de', 'albigdd', '10588898d18beebd41488df36e4be2f9', 'CHECK your prices after upgrading!\nNEW: multilanguage support. Bugfixes, no new features in this release.', '', 4004, 0, 0),
(21823, 0, 'ab_booking', 1, '0.4.5', 853, 83, 'Simple booking extension', 'An availability calendar is presentable for each item/room. You may check the date and enter your details for booking.\nAnother view is an availability check.', 1, 0, 3, 1311106277, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:11:"4.4.0-0.0.0";}}', 'Alexander Bigga', 'linux@bigga.de', 'albigdd', '97f81bebcd5d1a9ce357727397c316f5', 'Some Bugfixes and a new feature: add minimum stay period to your prices!\n\nAs always: there are some database table changes. Please check after update again in the extension manager if all changes applied to the database.\n\nPlease use forge to report bugs a', '', 4005, 0, 0),
(21824, 0, 'ab_booking', 1, '0.5.0', 853, 45, 'Simple Booking Extension', 'An availability calendar is presentable for each item/room. You may check the date and enter your details for booking.\nAnother view is an availability check.', 1, 0, 3, 1318537043, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:11:"4.4.0-0.0.0";}}', 'Alexander Bigga', 'linux@bigga.de', 'albigdd', '50b38d3117215746fa6db544a4dce24f', 'New features to make the prices, the minimum stay and single components like room cleaning depending on the duration of stay.\n\nSome bugfixes and for sure some, fresh bugs. Please use the bugtracker at forge to report your issues.\n\nAfter upgrade: check the', '', 5000, 0, 0),
(21825, 0, 'ab_booking', 1, '0.5.1', 853, 68, 'Simple Booking Extension', 'An availability calendar is presentable for each item/room. You may check the date and enter your details for booking.\nAnother view is an availability check.', 1, 0, 3, 1323204923, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:11:"4.4.0-0.0.0";}}', 'Alexander Bigga', 'linux@bigga.de', 'albigdd', '40ac944b0b7f71cd53ad7a9ac8cbe5cc', '- Updated Documentation\n- calendar view is now rendered using divs instead of tables. So check your CSS after upgrade!', '', 5001, 1, 0),
(21826, 0, 't3c_konfigurator', 1, '0.1.1', 57, 7, 'T3C Konfigurator', 'Like a configurator. See screenshots/manual/Changelog', 0, 0, 3, 1237300906, 'a:1:{s:7:"depends";a:1:{s:3:"cms";s:0:"";}}', 'Niels Tiedt', 'nt@typo3_coder.org', 'danton', 'fc8756f43e22406eface246935b9097b', 'First upload was the false version from my repository. This is the working one.', '', 1001, 0, 0),
(21827, 0, 't3c_konfigurator', 1, '0.1.2', 57, 6, 'T3C Konfigurator', 'Like a configurator. See screenshots/manual/Changelog', 0, 0, 3, 1245688704, 'a:1:{s:7:"depends";a:1:{s:3:"cms";s:0:"";}}', 'Niels Tiedt', 'nt@typo3_coder.org', 'danton', 'f58009498c91d4a459cf3955bf42877f', 'Fixed: Global elementtitle and pagetitle func now work\r\nFixed: BE: list property item now shows parent correct\r\nFixed: locallang text correction', '', 1002, 0, 0),
(21828, 0, 't3c_konfigurator', 1, '0.1.3', 57, 4, 'T3C Konfigurator', 'Like a configurator. See screenshots/manual/Changelog', 0, 0, 3, 1245688998, 'a:1:{s:7:"depends";a:1:{s:3:"cms";s:0:"";}}', 'Niels Tiedt', 'nt@typo3_coder.org', 'danton', 'f89b22e9fc45c5898a95e7be6858d8ab', 'Fixed: Global elementtitle and pagetitle func now work\r\nFixed: BE: list property item now shows parent correct\r\nFixed: locallang text correction', '', 1003, 0, 0),
(21829, 0, 't3c_konfigurator', 1, '0.1.4', 57, 40, 'T3C Konfigurator', 'Like a configurator. See screenshots and manual section Configuration/Property options', 1, 0, 3, 1248166735, 'a:1:{s:7:"depends";a:1:{s:3:"cms";s:0:"";}}', 'Niels Tiedt', 'nt@typo3_coder.org', 'danton', '8d01e1b092fd849fc6dc3a815c55ea26', '20-07-09\r\n0.1.4 New: Field elements to select items from an another table e.g. tt_products articles\r\n      	New: Extension Manager Configuration', '', 1004, 1, 0),
(21830, 0, 'html2ts', 1, '1.0.0', 77, 77, 'HTML to TS', 'Feed with XHTML, get Typoscript back ! Basic mean of the Wizard is transform HTM to TS, but with additional markup, Wizard can generate a functional template for a new site ! Must have for TS beginners.', 1, 0, 0, 1237325876, 'a:1:{s:7:"depends";a:1:{s:12:"func_wizards";s:0:"";}}', 'Emmanuel Pire', 'piremmanuel@gmail.com', 'epire', '085b01eaf44a3f9571aa53638068815a', 'First release. Many features will coma later. Please report bugs and specially HTM that cannot be parsed or incorrectly.', '', 1000000, 1, 0),
(21831, 0, 'netcos_data', 1, '0.9.1', 67, 8, 'Netcos data classes and a better print_r', 'Basic classes with error handling for usage in other extensions', 0, 0, 4, 1237385200, 'a:1:{s:7:"depends";a:1:{s:3:"cms";s:0:"";}}', 'Bernd Warken', 'be.warken@netcos.de', 'bwarken', '6534b422bc40250de21ad35832b53489', 'Initial release', '', 9001, 0, 0),
(21832, 0, 'netcos_data', 1, '0.9.2', 67, 3, 'Netcos data classes and a better print_r', 'Basic classes with error handling for usage in other extensions', 0, 0, 4, 1238053849, 'a:1:{s:7:"depends";a:1:{s:3:"cms";s:0:"";}}', 'Bernd Warken', 'be.warken@netcos.de', 'bwarken', '8fdf79a5208222a4e9906b0c956d1c3d', 'Make class data non-abstract. Fix class printStr in many areas. Correct handling of empty arguments.	In all clases, suit __construct to tslib_pibase (by using NULL as default argument).', '', 9002, 0, 0);
INSERT INTO `tx_extensionmanager_domain_model_extension` (`uid`, `pid`, `extension_key`, `repository`, `version`, `alldownloadcounter`, `downloadcounter`, `title`, `description`, `state`, `review_state`, `category`, `last_updated`, `serialized_dependencies`, `author_name`, `author_email`, `ownerusername`, `md5hash`, `update_comment`, `authorcompany`, `integer_version`, `current_version`, `lastreviewedversion`) VALUES
(21833, 0, 'netcos_data', 1, '0.9.3', 67, 11, 'Netcos data classes and a better print_r', 'Basic classes with error handling for usage in other extensions', 0, 0, 4, 1238087896, 'a:1:{s:7:"depends";a:1:{s:3:"cms";s:0:"";}}', 'Bernd Warken', 'be.warken@netcos.de', 'bwarken', '24bd29dc59873b4526993ddf77837ad5', 'Fix class printStr: line break (including 0 for none), string_to_preg(), strings to HTML. Fix class error.', '', 9003, 0, 0),
(21834, 0, 'netcos_data', 1, '1.0.0', 67, 10, 'Netcos data classes and a better print_r', 'Basic classes with error handling for usage in other extensions', 1, 0, 4, 1254401200, 'a:1:{s:7:"depends";a:1:{s:3:"cms";s:0:"";}}', 'Bernd Warken', 'be.warken@netcos.de', 'bwarken', '78373d616f1d4e3eedf83089f167d8ef', 'Create own language handling for whole extension; new class lang.\r\n Recreate error management with prepend_error() and use translation.\r\n Restructure the print classes: new class printClass without error management.\r\n\r\nMany new methods for class dataArray', '', 1000000, 0, 0),
(21835, 0, 'netcos_data', 1, '1.0.1', 67, 9, 'Netcos data classes and a better print_r', 'Basic classes with error handling for usage in other extensions', 1, 0, 4, 1257775154, 'a:1:{s:7:"depends";a:1:{s:3:"cms";s:0:"";}}', 'Bernd Warken', 'be.warken@netcos.de', 'bwarken', '56a3b6db67f6580b93e605c71b9efacb', 'To class array, add sort methods sort(), rsort(), asort(), arsort(), natsort(), natcasesort(), and shuffle().', '', 1000001, 0, 0),
(21836, 0, 'netcos_data', 1, '1.0.2', 67, 26, 'Netcos data classes and a better print_r', 'Basic classes with error handling for usage in other extensions', 1, 0, 4, 1257864386, 'a:1:{s:7:"depends";a:1:{s:3:"cms";s:0:"";}}', 'Bernd Warken', 'be.warken@netcos.de', 'bwarken', 'b99b4910cdc3c2015789186c57a82714', 'Add class array methods ksort(), krsort(), and usort().  Fix shuttle().  Document methods in manual.', '', 1000002, 1, 0),
