(21839, 0, 'mooslide', 1, '0.2.0', 264, 9, 'Mooslide', 'This extension utilizes "mooslide", a mootools extension class which implements a convenient animated slideshow/ticker. everything is highly configurable via the flexform (and typoscript if wanted). \n						To start: simply insert this plugin on a page, se', 1, 0, 3, 1237425632, 'a:0:{}', 'Iggy - sensomedia.de', 'info@sensomedia.de', 'sensomedia', 'd963d755f8c48b3131e4fa6bc558675b', 'Initial release to TER', 'sensomedia.de', 2000, 0, 0),
(21840, 0, 'mooslide', 1, '0.2.1', 264, 9, 'Mooslide', 'This extension utilizes "mooslide", a mootools extension class which implements a convenient animated slideshow/ticker. everything is highly configurable via the flexform (and typoscript if wanted). \n						To start: simply insert this plugin on a page, se', 1, 0, 3, 1237429735, 'a:0:{}', 'Iggy - sensomedia.de', 'info@sensomedia.de', 'sensomedia', '6a74f8023badf3f03f7b661577a05e52', '- If mouse enters and leaves the ticker before the transition effect has actually started for the first time, the script most probably breaks. This is fixed now.\r\n', 'sensomedia.de', 2001, 0, 0),
(21841, 0, 'mooslide', 1, '0.2.2', 264, 246, 'Mooslide', 'This extension utilizes "mooslide", a mootools extension class which implements a convenient animated slideshow/ticker. everything is highly configurable via the flexform (and typoscript if wanted). \n						To start: simply insert this plugin on a page, se', 1, 0, 3, 1237846086, 'a:0:{}', 'Iggy - sensomedia.de', 'info@sensomedia.de', 'sensomedia', '572bc10218d977e16e5acc68af2c6106', 'Minor Bugfix: changed background style to transparent (instead of none) if no bgcolor is supplied', 'sensomedia.de', 2002, 1, 0),
