(21999, 0, 'coago', 1, '0.1.2', 138, 14, 'COA_GO - per cObj caching with cache period', 'This extension improves caching of content objects in TYPO3 so it can increase time rendering of page and overall performance of your site. Tags: COA_CACHED, COA_INT_CACHED, COA_INT_CACHED_AJAX', 1, 0, 2, 1240176169, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"4.1.0-4.2.99";}}', 'Krystian Szymukowicz', 'http://typo3.prolabium.com', 't33k', '950a0892bdf34bc20157a6101223a255', 'First upload.', 'http://typo3.prolabium.com', 1002, 0, 0),
(22000, 0, 'coago', 1, '0.1.3', 138, 3, 'COA_GO - per content object caching with cache per', 'This extension improves caching of content objects in TYPO3 so it can decrease time rendering of page and improve overall performance of your site.', 1, 0, 2, 1240844097, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"4.1.0-4.2.99";}}', 'Krystian Szymukowicz', 'http://typo3.prolabium.com', 't33k', '835d09ea42c02342adf925c63a20869c', ' Fix ajax problem in IE  compress the script. Now ajax works in all browsers.\r\n Setting default cacheDirectory if this from EM is not set.\r\n Setting default type of caching to beforeCache_db. Renaming $hash to $cacheHash.\r\n Cache period checks are', 'http://typo3.prolabium.com', 1003, 0, 0),
(22001, 0, 'coago', 1, '0.1.4', 138, 9, 'COA_GO - per content object caching with cache per', 'This extension improves caching of content objects in TYPO3 so it can decrease time rendering of page and improve overall performance of your site.', 1, 0, 2, 1252915752, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:11:"4.1.0-4.3.0";}}', 'Krystian Szymukowicz', 'http://typo3.prolabium.com', 't33k', '2ceb6601923e5fdbe64b0d51d8891b8c', 'NOTE! Remember to include static TS from extension if you use afterCacheFileAjax method; cObject regeneration are now conducted using special PAGE type ; new options: debug, refresh, onLoading, fileExtension;  Hook for own javascript ajax fetch  ', 'http://typo3.prolabium.com', 1004, 0, 0),
(22002, 0, 'coago', 1, '0.1.5', 138, 18, 'COA_GO - per cObject caching with cache period', 'This extension improves caching of content objects in TYPO3. It can decrease time rendering of page and improve overall performance of your site.', 1, 0, 2, 1256207921, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:11:"4.1.0-4.3.0";}}', 'Krystian Szymukowicz', 'http://typo3.prolabium.com', 't33k', 'ad5baffb1c358a94252fe07ec51d3b6f', ' request method in ajax call changed from POST to GET. With POST method there was some problems on Safari at MAC (many thanks to Kurt Knote for fighting with this bug!)\r\n fixed bug in beforeCache_db. No assign to $content after get from cache.\r\n added ', 'http://typo3.prolabium.com', 1005, 0, 0),
(22003, 0, 'coago', 1, '0.2.0', 138, 8, 'COA_GO - per cObject caching with cache period', 'This extension improves caching of content objects in TYPO3. It can decrease time rendering of page and improve overall performance of your site.', 1, 0, 2, 1257758819, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:11:"4.1.0-4.3.0";}}', 'Krystian Szymukowicz', 'http://typo3.prolabium.com', 't33k', 'fffd0fedafac9bbc61320cbf84db4e46', 'Lots of new features. a) hash.special.unique.pidList b) hash.special.lang c) clearCacheOnTableChange d) Render COA_GO as COA e) hash from cObj path', 'http://typo3.prolabium.com', 2000, 0, 0),
(22004, 0, 'coago', 1, '0.2.1', 138, 86, 'COA_GO - per cObject caching with cache period', 'This extension improves caching of content objects in TYPO3. It can decrease time rendering of page and improve overall performance of your site.', 1, 0, 2, 1257941197, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:11:"4.1.0-4.3.0";}}', 'Krystian Szymukowicz', 'http://typo3.prolabium.com', 't33k', 'f8bf9ce5ebe13b0a106fb25d2ce6f509', 'Bugfix. One file was missing in previous version causing backend problems  one more bug fixed. Sorry for that missing file - I have no idea how it could happen. ', 'http://typo3.prolabium.com', 2001, 1, 0),
