(22054, 0, 'mmsynchro', 1, '2.0.1', 121, 6, 'Synchronisation', 'Synchronisation modul for Typo3 installations. Extension synchronises two installations via SSH (Remote) or synchronise two installations on a local system. Synchronisation backups database, filesystem and pagetree. The extension provides CLI. (German doc', 1, 0, 1, 1240912227, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"5.2.6-0.0.0";s:5:"typo3";s:11:"4.2.1-0.0.0";}}', 'Patrick Kaeller, Timo Webler', 'kaeller@mediaman.de', 'paka76', '15a41a1de0019b89a421735c35728251', 'Add description and manual', 'mediaman Gesellschaft fuer Kommunikation mbH', 2000001, 0, 0),
(22055, 0, 'mmsynchro', 1, '2.0.2', 121, 109, 'Synchronisation', 'Synchronisation modul for Typo3 installations. Extension synchronises two installations via SSH (Remote) or synchronise two installations on a local system. Synchronisation backups database, filesystem and pagetree. The extension provides CLI.', 1, 0, 1, 1240916981, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"5.2.6-0.0.0";s:5:"typo3";s:11:"4.2.1-0.0.0";}}', 'Patrick Kaeller, Timo Webler', 'kaeller@mediaman.de', 'paka76', '4fd21e823e8bb6babe1a1c613d4aca84', 'Add manual (english)', 'mediaman Gesellschaft fuer Kommunikation mbH', 2000002, 1, 0),
