(22079, 0, 'gh_fontsize', 1, '0.4.1', 260, 4, 'GH Change Font Size', 'Small menu to  decrease, reset and increase a numerical value, normaly fontsize, via CSS. Uses ajax functionality where possible.', 1, 0, 3, 1251367255, 'a:0:{}', 'Gregor Hermens', 'gregor@a-mazing.de', 'ghermens', '53291c63b92ac98e44263d39ab9eceb8', 'Changed description to match the new features of version 0.4.x', '', 4001, 0, 0),
