(22081, 0, 'gh_fontsize', 1, '0.4.3', 260, 5, 'GH Change Font Size', 'Small menu to  decrease, reset and increase a numerical value, normaly fontsize, via CSS. Uses ajax functionality where possible.', 1, 0, 3, 1251743803, 'a:0:{}', 'Gregor Hermens', 'gregor@a-mazing.de', 'ghermens', 'e1db08581f13493fd0bd8bcfc30a0d4b', 'added feature 4408: Make display links (smaller, reset, larger) configurable', '', 4003, 0, 0),
(22082, 0, 'gh_fontsize', 1, '0.4.4', 260, 7, 'GH Change Font Size', 'Small menu to  decrease, reset and increase a numerical value, normaly fontsize, via CSS. Uses ajax functionality where possible.', 1, 0, 3, 1252219613, 'a:0:{}', 'Gregor Hermens', 'gregor@a-mazing.de', 'ghermens', '746a321bbeb440efa9a2845b9bd07470', 'Ajax now works with IDs and most numerical CSS parameters.', '', 4004, 0, 0),
