(22145, 0, 't3designkit', 1, '0.1.0', 77, 77, 'TYPO3 Design Kit', 'Create a website within just a few minutes by importing it from a set of predefined dummy page trees. Combine it with lots of designs available for download at t3.designkit.org and import and modify them using a sophisticated backend user interface.', 1, 0, 1, 1242174037, 'a:1:{s:7:"depends";a:2:{s:3:"cms";s:0:"";s:18:"css_styled_content";s:0:"";}}', 'JoH asenau', 'jh@eqony.com', 'cybercraft', '1a122bbf49aae46985af018726291ea8', 'Initial upload of the Page Tree Wizard, since this will already run on TYPO3 4.2. It might be useful as a stand-alone tool as well. It is more or less self explaining so give it a try! The second module called "Design Manager" will be available for TYPO3', '', 1000, 1, 0),
(22146, 0, 'imageannotate', 1, '1.0.0', 35, 35, 'Image Annotations', 'This extension adds the ability to annotate / describe various areas of an image.\n\nThis works similar to image annotations as in Flickr and such similar sites.\nThis uses simple html and css techniques without the use of any javascript code.', 1, 0, 3, 1242197012, 'a:0:{}', 'Prakash, Vinay N, Ganapati Bhat', 'spabhat@chandanweb.com', 'spabhat', '12b695179c1282bd497d916458e55326', '', '', 1000000, 1, 0),
