(22241, 0, 'blog_example', 1, '0.9.6', 2674, 95, 'A Blog Example for the Extbase Framework', 'An example extension demonstrating the features of the Extbase Framework. It is the back-ported and tweaked Blog Example package of FLOW3. Have fun playing with it!', 1, 0, 9, 1254467259, 'a:1:{s:7:"depends";a:4:{s:3:"php";s:11:"5.2.0-0.0.0";s:5:"typo3";s:14:"4.3.dev-4.3.99";s:7:"extbase";s:11:"0.9.5-0.0.0";s:5:"fluid";s:11:"0.9.5-0.0.0";}}', '', '', 'bwaidelich', 'd8ed9d4262c01ceb1944e837c378f7a5', 'The Blog Example demonstrates several new Features of Extbase and Fluid. We also fixed some Bugs. ', 'TYPO3 core team', 9006, 0, 0),
(22242, 0, 'blog_example', 1, '0.9.8', 2674, 73, 'A Blog Example for the Extbase Framework', 'An example extension demonstrating the features of the Extbase Framework. It is the back-ported and tweaked Blog Example package of FLOW3. Have fun playing with it!', 1, 0, 9, 1257778499, 'a:1:{s:7:"depends";a:4:{s:3:"php";s:11:"5.2.0-0.0.0";s:5:"typo3";s:14:"4.3.dev-4.3.99";s:7:"extbase";s:11:"0.9.5-0.0.0";s:5:"fluid";s:11:"0.9.5-0.0.0";}}', '', '', 'bwaidelich', '7f83280869092dccc9cd81659a778638', 'Several improvements and fixes. Corresponds to Extbase 0.9.17 and Fluid 0.9.17 shipped with TYPO3 4.3beta3.', 'TYPO3 core team', 9008, 0, 0),
