(22324, 0, 'minify', 1, '1.1.0', 807, 4, 'Minify', 'Minify and merge JS and CSS files', 2, 0, 2, 1271782266, 'a:0:{}', 'Christopher Hlubek', 'hlubek@networkteam.com', 'networkteam_hlubek', '13c9369eb8823d90519290d118caa6eb', 'Minify will now add modification timestamps to images in CSS files through the Minify CSS URI rewrite mechanism. This is useful for aggressive caching.', '', 1001000, 0, 0),
