(22380, 0, 'px_phpids', 1, '1.1.4', 1048, 76, 'Typo3 PHP Intrusion Detection System - PHPIDS', 'Secure your Typo3 Installation with this IDS from www.phpids.org. Currently the PHPIDS detects all sorts of XSS, SQL Injection, header injection, directory traversal, RFE/LFI, DoS and LDAP attacks.', 2, -1, 3, 1248078937, 'a:0:{}', 'pixabit GmbH / Pascal Naujoks', 'pascal.naujoks@pixabit.de', 'qualle', '5542149568c1277263783e542d3b4ffe', '- Added a page browser in the PHPIDS backend \r\n- Added some css improvements in the backend \r\n- Updated Converter.php \r\n- Updated default_filter.xml \r\n- Updated the manual', '', 1001004, 0, 0),
(22381, 0, 'px_phpids', 1, '1.1.5', 1048, 119, 'Typo3 PHP Intrusion Detection System - PHPIDS', 'Secure your Typo3 Installation with this IDS from www.phpids.org. Currently the PHPIDS detects all sorts of XSS, SQL Injection, header injection, directory traversal, RFE/LFI, DoS and LDAP attacks.', 2, -1, 3, 1260957272, 'a:0:{}', 'pixabit GmbH / Pascal Naujoks', 'pascal.naujoks@pixabit.de', 'qualle', '04b535718ea500b7b04dbe2b71c78392', '- Improvements for Typo3 4.3.0 \r\n- Updated the default_filter.xml to Version 0.6.3 Revision 1370)\r\n- Updated the Converter.php to Version 0.6.3 Revision 1370)\r\n', '', 1001005, 0, 0);
INSERT INTO `tx_extensionmanager_domain_model_extension` (`uid`, `pid`, `extension_key`, `repository`, `version`, `alldownloadcounter`, `downloadcounter`, `title`, `description`, `state`, `review_state`, `category`, `last_updated`, `serialized_dependencies`, `author_name`, `author_email`, `ownerusername`, `md5hash`, `update_comment`, `authorcompany`, `integer_version`, `current_version`, `lastreviewedversion`) VALUES
(22382, 0, 'px_phpids', 1, '1.2.0', 1048, 4, 'TYPO3 Security / Intrusion Detection System - PHPI', 'Currently the PHPIDS detects all sorts of XSS, SQL Injection, header injection, directory traversal, RFE/LFI, DoS and LDAP attacks. Through special conversion algorithms the PHPIDS is even able to detect heavily obfuscated attacks.', 2, -1, 3, 1267198457, 'a:0:{}', 'pixabit GmbH / Pascal Naujoks', 'pascal.naujoks@pixabit.de', 'qualle', '272c037d927ef626f6ee5505a6bbecbc', '- Added support for ADODB/DBAL and replaced all PDO functions with TYPO3 DB query functions.\r\n- Added support for up to 3 exceptions.\r\n- Removed false positives for Google Analytics.\r\n- Fixed a bug in the database caching method.\r\n- Style improvements in ', '', 1002000, 0, 0),
(22383, 0, 'px_phpids', 1, '1.2.1', 1048, 19, 'TYPO3 Security / Intrusion Detection System - PHPI', 'Currently the PHPIDS detects all sorts of XSS, SQL Injection, header injection, directory traversal, RFE/LFI, DoS and LDAP attacks. Through special conversion algorithms the PHPIDS is even able to detect heavily obfuscated attacks.', 2, -1, 3, 1281612808, 'a:0:{}', 'pixabit GmbH / Pascal Naujoks', 'pascal.naujoks@pixabit.de', 'qualle', 'ba82a0b0ca1ba701d05adb209564e43d', '- Fixed a bug in the backend module, thanks to Tobias Schfer\r\n- Updated the default_filter.xml\r\n- Updated the Converter.php\r\n- Enabled the bugtracker for phpids on TYPO3 Forge', '', 1002001, 0, 0),
(22384, 0, 'px_phpids', 1, '1.2.2', 1048, 73, 'TYPO3 Security / Intrusion Detection System - PHPI', 'Currently the PHPIDS detects all sorts of XSS, SQL Injection, header injection, directory traversal, RFE/LFI, DoS and LDAP attacks. Through special conversion algorithms the PHPIDS is even able to detect heavily obfuscated attacks.', 2, -1, 3, 1283332529, 'a:0:{}', 'pixabit GmbH / Pascal Naujoks', 'pascal.naujoks@pixabit.de', 'qualle', 'a34380f3e96c61043280dbf5c2442c4c', ' - Style improvements in the backend for TYPO3 4.2, 4.3 and 4.4 - Thanks to Tobias Schfer\r\n - Now you can add unlimited exceptions for eg. your WYIWYG Editor in the Constants of plugin.px_phpids\r\n - The constants are now categorized and sorted :)\r\n - ', '', 1002002, 0, 0),
(22385, 0, 'px_phpids', 1, '1.2.3', 1048, 109, 'TYPO3 Security / Intrusion Detection System - PHPI', 'Currently the PHPIDS detects all sorts of XSS, SQL Injection, header injection, directory traversal, RFE/LFI, DoS and LDAP attacks. Through special conversion algorithms the PHPIDS is even able to detect heavily obfuscated attacks.', 2, -1, 3, 1286458226, 'a:0:{}', 'pixabit GmbH / Pascal Naujoks', 'pascal.naujoks@pixabit.de', 'qualle', '95b4abf40c5b0b5dc2cbdc0d0a817515', '- Added a whitelist feature\r\n- Updated Monitor.php to PHPIDS v0.6.4\r\n- Updated default_filter.xml to Revision 1426\r\n- Updated Converter.php to Revision 1422', '', 1002003, 0, 0),
