(22408, 0, 'cag_longlists', 1, '1.2.0', 287, 9, 'cag_lists', 'Display contents of CSV-files (Excel export) or database query results as tables in frontend. Features: pagination, autofilter and fulltext search, sort columns by clicking on head. Fully customizable HTML-Template. Runs out of the box with included examp', 1, 0, 3, 1244827950, 'a:0:{}', 'Jens Eipel, Connecta AG', 'j.eipel@connecta.ag', 'j.eipel', '7df528ee3423a9b61788e09ca17bff0c', 'Extension now works out of the box after installation  using an included example.\r\nMajor improvements to manual by request\r\nImproved config for Database query as Datsource.\r\nImproved HTML-Template', '', 1002000, 0, 0),
(22409, 0, 'cag_longlists', 1, '1.2.1', 287, 16, 'cag_lists', 'Display contents of CSV-files (Excel export) or database query results as tables in frontend. Features: pagination, autofilter and fulltext search, sort columns by clicking on head. Fully customizable HTML-Template. Runs out of the box with included examp', 1, 0, 3, 1246349261, 'a:0:{}', 'Jens Eipel, Connecta AG', 'j.eipel@connecta.ag', 'j.eipel', '9b1048f5eb94b9691cf9b400c775e44e', 'Quickfix:\r\nTemplatepath not recocnized correctly in Flexform configuration since last update', '', 1002001, 0, 0),
(22410, 0, 'cag_longlists', 1, '1.2.2', 287, 54, 'cag_lists', 'Display contents of CSV-files (Excel export) or database query results as tables in frontend. Features: pagination, autofilter and fulltext search, sort columns by clicking on head. Fully customizable HTML-Template. Runs out of the box with included examp', 1, 0, 3, 1257151841, 'a:0:{}', 'Jens Eipel, Connecta AG', 'j.eipel@connecta.ag', 'j.eipel', 'a208027b11f1a5fed056cb8287023cfe', 'Completely rewritten manual by M.Sauter. Thanks for the support.', '', 1002002, 0, 0),
