(22434, 0, 'cag_relatedcontent', 1, '1.9.0', 343, 20, 'Show Related Content, Categorize Pages and Content', 'Auto recommendation of similar pages. Assign categories to content and pages. List pages or content related to current page in Frontend. Show index of categories and associated pages and much more ...', 2, 0, 2, 1279206770, 'a:0:{}', 'Jens Eipel, Connecta AG', 'j.eipel@connecta.ag', 'j.eipel', '3c878b2f8d66c085ec0958845b734a76', 'Added new plugin to list related content elements in frontend. New Plugin lets you display a list of content elements of your Site on a basis of their assigned categories.  \r\nAssign categories to pages AND content.', 'Connecta AG, Wiesbaden', 1009000, 0, 0),
(22435, 0, 'cag_relatedcontent', 1, '1.9.2', 343, 23, 'Show Related Content, Categorize Pages and Content', 'Auto recommendation of similar pages. Assign categories to content and pages. List pages or content related to current page in Frontend. Show index of categories and associated pages and much more ...', 2, 0, 2, 1284552177, 'a:0:{}', 'Jens Eipel, Connecta AG', 'j.eipel@connecta.ag', 'j.eipel', 'd4567f03e3b964b8557baf630e1cde21', 'Bugfix in Plugin 5 (New plugin to list related content elements in frontend. New Plugin lets you display a list of content elements of your Site on a basis of their assigned categories. Assign categories to pages AND content.)', 'Connecta AG, Wiesbaden', 1009002, 0, 0),
