(22705, 0, 'db_list', 1, '0.0.2', 54, 8, 'enhancements to the list module', 'This implements hooks and copied classes from the records list also used in the list module. For TYPO3  4.3 you must install debug_mysql_db.', 2, 0, 0, 1247847961, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"4.2.0-4.3.99";}}', 'Franz Holzinger', 'franz@ttproducts.de', 'franzholz', '09a903b7f03394c645958e290469c1c6', 'This brings you the List module of TYPO3 4.3 also to former versions of TYPO3. You must install debug_mysql_db before to make all DB calls working.', 'jambage.com', 2, 0, 0),
(22706, 0, 'db_list', 1, '0.0.3', 54, 46, 'Enhancements to the list module', 'This implements hooks and copied classes from the records list also used in the list module. For TYPO3 before 4.3 you must install debug_mysql_db.', 1, 0, 0, 1250062870, 'a:1:{s:7:"depends";a:4:{s:3:"php";s:11:"5.1.2-0.0.0";s:5:"typo3";s:12:"4.2.0-4.3.99";s:7:"div2007";s:11:"0.2.1-0.0.0";s:7:"alt_doc";s:11:"0.0.0-0.0.0";}}', 'Franz Holzinger', 'franz@ttproducts.de', 'franzholz', 'a76b707192c5b80c07fbc44b655ddc59', 'Bug fixes to the record browser.', 'jambage.com', 3, 0, 0),
