(22709, 0, 'db_list', 1, '0.3.0', 54, 0, 'Enhancements of the list module', 'This implements slots for the records list which is used in the TYPO3 backend list module.', 1, 0, 0, 1493118332, 'a:1:{s:7:"depends";a:3:{s:3:"php";s:13:"5.3.3-7.99.99";s:5:"typo3";s:13:"7.0.0-8.99.99";s:10:"recordlist";s:13:"7.0.0-8.99.99";}}', 'Franz Holzinger', 'franz@ttproducts.de', 'franzholz', '04f24300956341aedbcd299f09006827', '\nAll former features have been removed. New feature: slot for the csv export in the TYPO3 backend list module\n', 'jambage.com', 3000, 1, 0),
