(22890, 0, 'ab_swiftmailer', 1, '0.0.1', 172, 3, 'Swiftmailer Lib', 'Write Emails using Swiftmailer (www.swiftmailer.org). This only glues swiftmailer to typo3. A simple contact form is provided. \nAdditional features have to be coded by yourself.', 0, 0, 2, 1249655310, 'a:0:{}', 'Alexander Bigga', 'linux@bigga.de', 'albigdd', 'fe6187ef1239fe2aeb5cce14725b79a0', 'quick an dirty inital release. Makes it possible to use the swiftmailer library in Typo3 extension. A simple contact form is provided. SMTP settings after installing Typo3 extension', '', 1, 0, 0),
(22891, 0, 'ab_swiftmailer', 1, '0.1.0', 172, 4, 'Swiftmailer Lib', 'Write Emails using Swiftmailer (www.swiftmailer.org). This only glues swiftmailer to typo3. A simple contact form is provided. \nAdditional features have to be coded by yourself.', 0, 0, 2, 1250617474, 'a:0:{}', 'Alexander Bigga', 'linux@bigga.de', 'albigdd', '22bccd0ef7d21842b8d05a9dfda2a84a', 'Update to swiftmailer 4.0.4; added flexform for SMTP-Settings and Signature', '', 1000, 0, 0),
(22892, 0, 'ab_swiftmailer', 1, '0.1.1', 172, 21, 'Swiftmailer Lib', 'Write Emails using Swiftmailer (www.swiftmailer.org). This only glues swiftmailer to typo3. A simple contact form is provided. \nAdditional features have to be coded by yourself.', 0, 0, 2, 1251971089, 'a:0:{}', 'Alexander Bigga', 'linux@bigga.de', 'albigdd', '95df5c5813a207261b56aa4746144966', 'Fixed a problem sending messages from ab_booking. Now using the swiftmailer logger-plugin to get information about failed SMTP-connections', '', 1001, 0, 0),
