(22894, 0, 'ab_swiftmailer', 1, '0.1.3', 172, 24, 'Swiftmailer Lib', 'Write Emails using Swiftmailer (www.swiftmailer.org). This only glues swiftmailer to typo3. A simple contact form is provided. \nAdditional features have to be coded by yourself.', 0, 0, 2, 1259062484, 'a:0:{}', 'Alexander Bigga', 'linux@bigga.de', 'albigdd', 'd8c25a283ebfa8ebbebb372c9108a0b8', 'This adds a check for HTML-links in the message field of the contact form. Hopefully this will block most spambots.', '', 1003, 0, 0),
