(22997, 0, 'sfjquery', 1, '1.1.0', 775, 9, 'SF jQuery', 'This is an interface between jQuery and TYPO3. Make use of TS and HTML for templating. Add CSS. So programm what ever you want.', 2, 0, 3, 1254307702, 'a:0:{}', 'Stefan Froemken', 'firma@sfroemken.de', 'froemken', '3d8392cf910a881d45e41e34d77605b4', 'Removed templateFile, because it was used for headerparts only. Complete rewritten template part. Updated documentation. Now you can use your own jquery-files, if I not updated my extension fast enought :-)', '', 1001000, 0, 0),
(22998, 0, 'sfjquery', 1, '1.1.1', 775, 36, 'SF jQuery', 'This is an interface between jQuery and TYPO3. Make use of TS and HTML for templating. Add CSS. So programm what ever you want.', 2, 0, 3, 1254497253, 'a:0:{}', 'Stefan Froemken', 'firma@sfroemken.de', 'froemken', '13e8d9f7e92e5330fc64ff096726edcf', 'Bugfix: CSS_PATH was not replaced', '', 1001001, 0, 0),
(22999, 0, 'sfjquery', 1, '1.1.2', 775, 2, 'SF jQuery', 'This is an interface between jQuery and TYPO3. Make use of TS and HTML for templating. Add CSS. So programm what ever you want.', 2, 0, 3, 1256046339, 'a:0:{}', 'Stefan Froemken', 'firma@sfroemken.de', 'froemken', '8fded01e729b43e43e1e6a8388cf794a', 'Added a hook to insert additional JavaScript-files. jQuery has many plugins, so now you can insert them very simple and they are inserted behind jQuery-core-script', '', 1001002, 0, 0),
(23000, 0, 'sfjquery', 1, '1.1.3', 775, 100, 'SF jQuery', 'This is an interface between jQuery and TYPO3. Make use of TS and HTML for templating. Add CSS. So programm what ever you want.', 2, 0, 3, 1256047827, 'a:0:{}', 'Stefan Froemken', 'firma@sfroemken.de', 'froemken', '22fc30cc77c5c3b275de2709e80593aa', 'Bugfix: There was a big mistake in my last upload. It was my first implemented hook, but now it should work. Ive tested it.', '', 1001003, 0, 0),
(23001, 0, 'sfjquery', 1, '1.2.0', 775, 19, 'SF jQuery', 'This is an interface between jQuery and TYPO3. Make use of TS and HTML for templating. Add CSS. So programm what ever you want.', 2, 0, 3, 1262862932, 'a:0:{}', 'Stefan Froemken', 'firma@sfroemken.de', 'froemken', 'e21ba7eddb9f160aca829adf04a50aef', 'Now you can add external files to all of your codingboxes. This is very helpful within big project or if you want to code in your own software. Further you can use sfjquery as a plain template machine if you want it. Some Bugfixes and Code cleanings.', '', 1002000, 0, 0),
(23002, 0, 'sfjquery', 1, '1.3.0', 775, 20, 'SF jQuery', 'This is an interface between jQuery and TYPO3. Make use of TS and HTML for templating. You can realize accordions, tabs, sliders, prograssbars and datepicker. So programm what ever you want.', 2, 0, 3, 1263232385, 'a:0:{}', 'Stefan Froemken', 'firma@sfroemken.de', 'froemken', '0093b3162589c080de33adffa22729a7', 'You can save your scripts in database now\r\nAdded a new documentation\r\nUPDATE: There is no global configuration anymore. Please use static-template instead', '', 1003000, 0, 0),
(23003, 0, 'sfjquery', 1, '1.3.1', 775, 51, 'SF jQuery', 'This is an interface between jQuery and TYPO3. Make use of TS and HTML for templating. You can realize accordions, tabs, sliders, prograssbars and datepicker. So programm what ever you want.', 2, 0, 3, 1263331504, 'a:0:{}', 'Stefan Froemken', 'firma@sfroemken.de', 'froemken', '9844e60eabfdf024d6def6bb1b69c53b', 'I added some sample scripts like accordion, tabs, sliders, dialog and datepicker to the database. Further only admins can edit, create and delete db-scripts on root-page.', '', 1003001, 0, 0),
(23004, 0, 'sfjquery', 1, '1.3.2', 775, 58, 'SF jQuery', 'This is an interface between jQuery and TYPO3. Make use of TS and HTML for templating. You can realize accordions, tabs, sliders, prograssbars and datepicker. So programm what ever you want.', 2, 0, 3, 1264691009, 'a:0:{}', 'Stefan Froemken', 'firma@sfroemken.de', 'froemken', '0f13d3ed3d481b2ad595a0c1f5dc1d52', 'jQuery 1.4.1 was released. I only updated jQuery 1.3.2 to 1.4.1 in my extension. There is also a new alpha Version of jQuery-UI available, but I dont want to have an alpha-Version in my extension. You can download it yourself and add it with help of Cons', '', 1003002, 0, 0),
(23005, 0, 'sfjquery', 1, '1.3.3', 775, 3, 'SF jQuery', 'This is an interface between jQuery and TYPO3. Make use of TS and HTML for templating. You can realize accordions, tabs, sliders, prograssbars and datepicker. So programm what ever you want.', 2, 0, 3, 1270325048, 'a:0:{}', 'Stefan Froemken', 'firma@sfroemken.de', 'froemken', 'bf28ad6cdcdf30355209f2c0fac0555d', 'add slideshow-plugin and reflection-plugin. Each plugin and effect can now be activated individual. Added new hook to implement CSS-File', '', 1003003, 0, 0),
(23006, 0, 'sfjquery', 1, '1.3.4', 775, 6, 'SF jQuery', 'This is an interface between jQuery and TYPO3. Make use of TS and HTML for templating. You can realize accordions, tabs, sliders, prograssbars and datepicker. So programm what ever you want.', 2, 0, 3, 1270734810, 'a:0:{}', 'Stefan Froemken', 'firma@sfroemken.de', 'froemken', '0b3f5c097eda09215d4d9d542acef034', 'Now all samples work again. There was a mistake in sql-file.', '', 1003004, 0, 0),
