(23008, 0, 'dd_googlesitemap_t3blog', 1, '1.1.0', 106, 106, 'Enable t3blog in Google sitemap', 'By default dd_googlesitemap only renders sitemaps from pages and tt_news. Install this extension and it will also render it for your t3blog. Call is like this: http://www.example.com/?eIDdd_googlesitemap&sitemapblog&blogPidYOURBLOGPID. By default t3blo', 2, 0, 2, 1250769317, 'a:0:{}', 'Sebastian Gebhard', 'sebastian.gebhard@googlemail.com', 'phpprof', '23d375b40dff24a5089b4eecb23553e1', 'Inital TER Release', '', 1001000, 1, 0),
