(23012, 0, 'pmkihateie', 1, '0.1.0', 206, 10, 'PMK "I hate IE"', 'Displays a fake IE "infobar" in Internet Explorer browsers (Similar to the annoying ActiveX infobar) with user defined text and link.\r\nCould be used to try persuading IE6 users to upgrade. Customizable "Hate level", so you can decide which IE versions sho', 1, 0, 2, 1250798679, 'a:0:{}', 'Peter Klein', 'pmk@io.dk', 'pmk65', '2202795f8ef1b7acb28e7accfad7d1f3', 'First version released on TER', '', 1000, 0, 0),
