(23283, 0, 'cookie', 1, '1.0.0', 38, 32, 'Store referrer in a Cookie', 'This extension finds search engine traffic and store the search terms in a cookie (yahoo, google, bing.com, web.de, ask.com). Its also possible to track a url param as a campaign marker.', 2, 0, 2, 1259860745, 'a:0:{}', 'Michael Fritz', 'michael.fritz@marit.ag', 'mitchiru', 'd6c889d01606eaebe3bbde896fc9476f', 'Multiple params possible to set up via record. Inheritance of records.', 'Marit AG', 1000000, 1, 0),
(23284, 0, 'cookie', 1, '0.0.0', 38, 6, 'Store referrer in a Cookie', 'This extension sets a cookie to all users reffered as search engine traffic. the refferer info (where,why) is stored in the cookie (yahoo, google, bing.com, web.de, ask.com). Its also possible to track an GET-param as a campaign marker. All runs with jQue', 2, 0, 2, 1253178217, 'a:0:{}', 'Michael Fritz', 'michael.fritz@marit.ag', 'mitchiru', '7a4b04ac5b8cff6c8a64c51fb02a39d0', 'Manual updated', 'Marit AG', 0, 0, 0),
