(23327, 0, 'pmkfdl', 1, '0.2.0', 305, 18, 'PMK Forced Download', 'Makes it possible to force download of files like images, PDFs, MP3 ect., overriding the browser settings. Can create secure download links based on usergroup access.', 1, 0, 2, 1255859670, 'a:2:{s:7:"depends";a:2:{s:5:"typo3";s:11:"4.0.0-0.0.0";s:3:"php";s:11:"5.0.0-0.0.0";}s:9:"conflicts";a:3:{s:19:"alternet_securelink";s:11:"0.0.0-0.0.0";s:14:"bzb_securelink";s:11:"0.0.0-0.0.0";s:11:"securelinks";s:11:"0.0.0-0.0.0";}}', 'Peter Klein', 'pmk@io.dk', 'pmk65', 'd8ccf40eecb6928668794e5c247ab663', 'See manual for list of changes.', '', 2000, 0, 0),
