(23569, 0, 'stg_clearcache', 1, '2.0.0', 263, 46, 'Clear cache recursive', '"Clear cache for this page" now also affects child pages, if user owns them. Is helpful in bigger installations, where each user has its own branch and cant be allowed to clear the cache of the whole server.', 2, 0, 0, 1254499372, 'a:0:{}', 'Steffen Gebert', 'steffen@steffen-gebert.de', 'stephenking', 'c38f03fc095d04b1d6ae1a5c00f2eaec', 'Initial release to TER', 'Webteam der Freien Whler Bayern', 2000000, 0, 0),
(23570, 0, 'stg_clearcache', 1, '2.1.0', 263, 56, 'Clear cache recursive', '"Clear cache for this page" now also affects child pages. This is helpful in bigger installations, where you cant/dont want to enable users to clear the cache of the whole server.', 2, 0, 0, 1265925150, 'a:0:{}', 'Steffen Gebert', 'steffen@steffen-gebert.de', 'stephenking', '1553209f564999c90953550787155b99', 'Changed default behavior: now (as you expect) cache is cleared recursive regardless of user access rights.', 'Webteam der Freien Whler Bayern', 2001000, 0, 0),
