(23708, 0, 'direct_mail_userfunc', 1, '1.1.0', 173, 13, 'Direct Mail User Functions', 'Adds support for user functions to Direct Mail. Currently allows recipient lists to be defined using a user function.', 2, 0, 1, 1255875501, 'a:1:{s:7:"depends";a:3:{s:3:"php";s:11:"5.2.0-0.0.0";s:5:"typo3";s:12:"4.2.0-4.3.99";s:11:"direct_mail";s:11:"2.6.3-0.0.0";}}', 'Xavier Perseguers', 'typo3@perseguers.ch', 'xperseguers', '8f188d0e14f51fec25c9d73e43a116a2', 'Added selector for registered user functions. Using extension configuration option to enable/disable sample user functions.', '', 1001000, 0, 0),
(23709, 0, 'direct_mail_userfunc', 1, '1.2.0', 173, 43, 'Direct Mail User Functions', 'Adds support for user functions to Direct Mail. Currently allows recipient lists to be defined using a user function.', 2, 0, 1, 1256725550, 'a:1:{s:7:"depends";a:3:{s:3:"php";s:11:"5.2.0-0.0.0";s:5:"typo3";s:12:"4.2.0-4.3.99";s:11:"direct_mail";s:11:"2.6.3-0.0.0";}}', 'Xavier Perseguers', 'typo3@perseguers.ch', 'xperseguers', 'f10edd8e3b67b2171aa47c63a20f9067', 'Changed parameter DB field from tinytext to mediumtext to accomodate large parameter array serialization. Updated icon.', '', 1002000, 0, 0),
(23710, 0, 'direct_mail_userfunc', 1, '1.2.1', 173, 86, 'Direct Mail User Functions', 'Adds support for user functions to Direct Mail. Currently allows recipient lists to be defined using a user function.', 2, 0, 1, 1279993516, 'a:1:{s:7:"depends";a:3:{s:3:"php";s:11:"5.2.0-0.0.0";s:5:"typo3";s:12:"4.2.0-4.4.99";s:11:"direct_mail";s:11:"2.6.3-0.0.0";}}', 'Xavier Perseguers', 'typo3@perseguers.ch', 'xperseguers', 'e1f08589f7c5bea7915ecb4ac54fa53a', 'Updated compatibility range for TYPO3 4.4', '', 1002001, 0, 0),
(23711, 0, 'direct_mail_userfunc', 1, '1.3.0', 173, 0, 'Direct Mail User Functions', 'Adds support for user functions to Direct Mail. Currently allows recipient lists to be defined using a user function.', 2, 0, 1, 1361551235, 'a:1:{s:7:"depends";a:3:{s:3:"php";s:11:"5.2.0-0.0.0";s:5:"typo3";s:12:"4.2.0-4.7.99";s:11:"direct_mail";s:11:"2.7.0-0.0.0";}}', 'Xavier Perseguers', 'xavier@causal.ch', 'xperseguers', '8191ddd7e23e19898c368bd990eb3f42', 'Long awaited update fixing compatibility with EXT:direct_mail', '', 1003000, 0, 0),
(23712, 0, 'direct_mail_userfunc', 1, '1.3.1', 173, 0, 'Direct Mail User Functions', 'Adds support for user functions to Direct Mail. Currently allows recipient lists to be defined using a user function.', 2, 0, 1, 1381493889, 'a:1:{s:7:"depends";a:3:{s:3:"php";s:12:"5.3.7-5.4.99";s:5:"typo3";s:12:"4.5.0-6.1.99";s:11:"direct_mail";s:12:"3.0.0-3.1.99";}}', 'Xavier Perseguers (Causal)', 'xavier@causal.ch', 'xperseguers', '5d7dad4f2abaa415c55a0422df2322da', 'Bugfix release.\nCompatibility with TYPO3 6.x.\nExtension manual rewritten as Sphinx/reStructuredText.', 'Causal Srl', 1003001, 0, 0);
INSERT INTO `tx_extensionmanager_domain_model_extension` (`uid`, `pid`, `extension_key`, `repository`, `version`, `alldownloadcounter`, `downloadcounter`, `title`, `description`, `state`, `review_state`, `category`, `last_updated`, `serialized_dependencies`, `author_name`, `author_email`, `ownerusername`, `md5hash`, `update_comment`, `authorcompany`, `integer_version`, `current_version`, `lastreviewedversion`) VALUES
(23713, 0, 'direct_mail_userfunc', 1, '1.4.0', 173, 0, 'External Providers for Direct Mail', 'Adds support for external providers to Direct Mail. This extension extends the types of recipient lists handled by Direct Mail with an entry for parameterized custom lists. These custom lists are prepared by user functions and may easily reuse your own business logic.', 2, 0, 1, 1383577265, 'a:1:{s:7:"depends";a:3:{s:3:"php";s:12:"5.3.7-5.4.99";s:5:"typo3";s:12:"4.5.0-6.1.99";s:11:"direct_mail";s:12:"3.0.0-4.0.99";}}', 'Xavier Perseguers (Causal)', 'xavier@causal.ch', 'xperseguers', 'e86d03635aa1ea3fe4cd877601eb1cc7', 'Feature release. Major rework (backward compatible) to be much more user-friendly. Now supporting custom TCA definition for additional parameters with automatic and transparent serialization/deserialization. Translate me on: http://translation.typo3.org', 'Causal Srl', 1004000, 0, 0),
(23714, 0, 'direct_mail_userfunc', 1, '1.4.1', 173, 0, 'External Providers for Direct Mail', 'Adds support for external providers to Direct Mail. This extension extends the types of recipient lists handled by Direct Mail with an entry for parameterized custom lists. These custom lists are prepared by user functions and may easily reuse your own business logic.', 2, 0, 1, 1383643444, 'a:1:{s:7:"depends";a:3:{s:3:"php";s:12:"5.3.7-5.4.99";s:5:"typo3";s:12:"4.5.0-6.2.99";s:11:"direct_mail";s:12:"3.0.0-4.0.99";}}', 'Xavier Perseguers (Causal)', 'xavier@causal.ch', 'xperseguers', 'a17b456481e82c185f129085495b9d5a', 'Bugfix release. Major rework (backward compatible) to be much more user-friendly. Now supporting custom TCA definition for additional parameters with automatic and transparent serialization/deserialization. Translate me on: http://translation.typo3.org', 'Causal Srl', 1004001, 0, 0),
(23715, 0, 'direct_mail_userfunc', 1, '1.4.2', 173, 0, 'External Providers for Direct Mail', 'Adds support for external providers to Direct Mail. This extension extends the types of recipient lists handled by Direct Mail with an entry for parameterized custom lists. These custom lists are prepared by user functions and may easily reuse your own business logic.', 2, 0, 1, 1403030006, 'a:1:{s:7:"depends";a:3:{s:3:"php";s:12:"5.3.7-5.5.99";s:5:"typo3";s:12:"4.5.0-6.2.99";s:11:"direct_mail";s:12:"3.1.0-4.0.99";}}', 'Xavier Perseguers (Causal)', 'xavier@causal.ch', 'xperseguers', '34b384c110d687a4623d9589be96b648', 'Native integration with direct_mail 3.1-4.0', 'Causal Srl', 1004002, 0, 0),
