(23717, 0, 'direct_mail_userfunc', 1, '1.5.0', 173, 0, 'External Providers for Direct Mail', 'Adds support for external providers to Direct Mail. This extension extends the types of recipient lists handled by Direct Mail with an entry for parameterized custom lists. These custom lists are prepared by user functions and may easily reuse your own business logic.', 2, 0, 1, 1481729957, 'a:1:{s:7:"depends";a:3:{s:3:"php";s:12:"5.5.0-7.0.99";s:5:"typo3";s:12:"6.2.0-7.6.99";s:11:"direct_mail";s:12:"4.1.0-5.1.99";}}', 'Xavier Perseguers (Causal)', 'xavier@causal.ch', 'xperseguers', 'adf36b1da56fd0231c8ddd9dcc6edf3e', 'Compatibility with recent version of direct_mail and TYPO3 v7.', 'Causal Srl', 1005000, 1, 0),
