(23930, 0, 'ogonki', 1, '0.0.4', 69, 6, 'Ogonki', 'Small extension that tries to remove some characters into new line (with non-breaking space). Initialy works with Polish language, but due to configuration possibilities can be used also for other similar job.', 1, 0, 2, 1257506842, 'a:0:{}', 'Marcus Biesioroff', 'marcus@typo3.pl', 'biesior', 'a8aa579ecf82afc2308c804aab1e994f', 'The extension is tested and working, although still missing some functions (i.e. TS configuration - now rules can be edited directly in the source code).\nManual in Polish will be translated ASAP... just include static from ext in TS and add the line from ', '', 4, 0, 0),
(23931, 0, 'ogonki', 1, '0.0.5', 69, 16, 'Ogonki', 'Small extension that tries to remove some characters into new line (with non-breaking space). Initialy works with Polish language, but due to configuration possibilities can be used also for other similar job.', 1, 0, 2, 1257509008, 'a:0:{}', 'Marcus Biesioroff', 'marcus@typo3.pl', 'biesior', '66dd3e0ab97d497ac44dfb1e74dd1f46', 'Manual translated to English', '', 5, 0, 0),
(23932, 0, 'ogonki', 1, '1.0.0', 69, 4, 'Ogonki', 'Small extension that tries to remove some characters into new line (with non-breaking space). Initialy works with Polish language, but due to configuration possibilities can be used also for other similar job.', 2, 0, 2, 1266429814, 'a:0:{}', 'Marcus Biesioroff', 'marcus@typo3.pl', 'biesior', '6660f9f03bdbba3711150d917afa5d39', 'Added TS config to make it more flexible.\nTuned manual (rendering problems)', '', 1000000, 0, 0),
