(23937, 0, 'ics_layar_service', 1, '0.1.0', 54, 29, 'Generic Layar Service Provider', 'Provides a Layar Service Provider for custom configurable layer Content Source. Layar is an augmented reality engine for last generation mobile phones. See http://layar.pbworks.com/ for more information about Layar.', 0, 0, 2, 1257523231, 'a:0:{}', 'In Cite Solution', 'technique@in-cite.net', 'incite', '9ab451262311191693881dfff0a46b30', 'First release with minimal features. Only support the rendering of the title, type and coord fields in the POIs. No page.', '', 1000, 0, 0),
(23938, 0, 'ics_layar_service', 1, '0.1.1', 54, 8, 'Generic Layar Service Provider', 'Provides a Layar Service Provider for custom configurable layer Content Source. Layar is an augmented reality engine for last generation mobile phones. See http://layar.pbworks.com/ for more information about Layar.', 1, 0, 2, 1322732668, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:11:"4.3.0-0.0.0";}}', 'In Cite Solution', 'technique@in-cite.net', 'incite', '63959bb7d8b8e6b30a026ba75b6272cf', 'Bug fixes in queries. \nImplemented image URL as field or path. \nDepends on TYPO3 4.3 autoloader. \nForge r55181.', 'In Cite Solution', 1001, 0, 0),
(23939, 0, 'ics_layar_service', 1, '0.2.0', 54, 17, 'Generic Layar Service Provider', 'Provides a Layar Service Provider for custom configurable layer Content Source. Layar is an augmented reality engine for last generation mobile phones. See http://layar.pbworks.com/ for more information about Layar. Support only API v2.1.', 1, 0, 2, 1322845223, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:11:"4.3.0-0.0.0";s:3:"php";s:11:"5.2.0-0.0.0";}}', 'In Cite Solution', 'technique@in-cite.net', 'incite', '099c0f1d414455b656ecaf7fc13a7ffa', 'All features are now implemented.\nLanguage support is not yet tested. One field coordinate case is not tested. Image field is not tested.\nPOI translation is not yet planned.\nForge revision 55221.', 'In Cite Solution', 2000, 1, 0),
