(24033, 0, 'feeditadvanced', 1, '1.0.1', 8858, 203, 'Advanced Frontend Editing', '', 1, 0, 2, 1258557982, 'a:2:{s:7:"depends";a:2:{s:5:"typo3";s:11:"4.3.0-0.0.0";s:3:"php";s:11:"5.2.0-0.0.0";}s:9:"conflicts";a:1:{s:6:"feedit";s:0:"";}}', 'Frontend Editing Team', 'jeff@webempoweredchurch.org', 'webempoweredchurch', '2232a06dfefaf1ac4dc4a976d246cb07', 'Fixed lockType issue in ext_emconf to allow local installation. See http://forge.typo3.org/wiki/typo3v4-feedit for more information.', '', 1000001, 0, 0),
