INSERT INTO `tx_extensionmanager_domain_model_extension` (`uid`, `pid`, `extension_key`, `repository`, `version`, `alldownloadcounter`, `downloadcounter`, `title`, `description`, `state`, `review_state`, `category`, `last_updated`, `serialized_dependencies`, `author_name`, `author_email`, `ownerusername`, `md5hash`, `update_comment`, `authorcompany`, `integer_version`, `current_version`, `lastreviewedversion`) VALUES
(24035, 0, 'feeditadvanced', 1, '1.2.0', 8858, 1220, 'Advanced Frontend Editing', 'This extension is the next generation for editing basic content directly through the frontend. It has all the bells an whistles like AJAX and Drag&Drop. TemplaVoila support included.', 1, 0, 2, 1263448810, 'a:2:{s:7:"depends";a:2:{s:5:"typo3";s:11:"4.3.0-0.0.0";s:3:"php";s:11:"5.2.0-0.0.0";}s:9:"conflicts";a:1:{s:6:"feedit";s:0:"";}}', 'Frontend Editing Team', 'jeff@webempoweredchurch.org', 'webempoweredchurch', '15e7210cfe333c3a6a7cd39cf24633f9', 'Improved handling of special characters and different charsets between FE output and BE editing. Javascript bugfixes for drag&drop and IE8 support.', '', 1002000, 0, 0),
(24036, 0, 'feeditadvanced', 1, '1.3.0', 8858, 72, 'Advanced Frontend Editing', 'This extension is the next generation for editing basic content directly through the frontend. It has all the bells an whistles like AJAX and Drag&Drop. TemplaVoila support included.', 1, 0, 2, 1268625377, 'a:2:{s:7:"depends";a:2:{s:5:"typo3";s:11:"4.3.0-0.0.0";s:3:"php";s:11:"5.2.0-0.0.0";}s:9:"conflicts";a:1:{s:6:"feedit";s:0:"";}}', 'Frontend Editing Team', 'jeff@webempoweredchurch.org', 'webempoweredchurch', '3358334ba24169c7996760c48a46c913', 'Fixed major issues when editing with a frontend login and when editing hidden content. Added feature to size editing window more intelligently. Several other minor bugfixes.', '', 1003000, 0, 0),
(24037, 0, 'feeditadvanced', 1, '1.4.0', 8858, 2889, 'Advanced Frontend Editing', 'This extension is the next generation for editing basic content directly through the frontend. It has all the bells an whistles like AJAX and Drag&Drop. TemplaVoila support included.', 1, 0, 2, 1281729911, 'a:2:{s:7:"depends";a:2:{s:5:"typo3";s:11:"4.3.0-0.0.0";s:3:"php";s:11:"5.2.0-0.0.0";}s:9:"conflicts";a:1:{s:6:"feedit";s:0:"";}}', 'Frontend Editing Team', 'jeff@webempoweredchurch.org', 'webempoweredchurch', '42a99ded046356123b85e31e2e3238ec', 'Major styling improvements in TYPO3 4.4, added logout button, and many bugfixes. When TemplaVoila is used, delete elements rather than unlink.', '', 1004000, 0, 0),
(24038, 0, 'feeditadvanced', 1, '1.5.0', 8858, 2542, 'Advanced Frontend Editing', 'This extension is the next generation for editing basic content directly through the frontend. It has all the bells an whistles like AJAX and Drag&Drop. TemplaVoila support included.', 1, 0, 2, 1304976933, 'a:2:{s:7:"depends";a:2:{s:5:"typo3";s:11:"4.3.0-0.0.0";s:3:"php";s:11:"5.2.0-0.0.0";}s:9:"conflicts";a:1:{s:6:"feedit";s:0:"";}}', 'Frontend Editing Team', 'jeff@webempoweredchurch.org', 'webempoweredchurch', 'ebeb218d47850d9a56e8d9ecb10a09a4', 'Improved TYPO3 4.5 Compatibility. Added basic manual. Many bugfixes.  See ChangeLog file for full details.\r\n', '', 1005000, 0, 0),
(24039, 0, 'feeditadvanced', 1, '1.6.0', 8858, 0, 'Advanced Frontend Editing', 'This extension is the next generation for editing basic content directly through the frontend. It has all the bells an whistles like AJAX and Drag&Drop. TemplaVoila support included.', 1, 0, 2, 1407287685, 'a:2:{s:7:"depends";a:2:{s:5:"typo3";s:12:"4.5.0-6.2.99";s:3:"php";s:11:"5.2.0-0.0.0";}s:9:"conflicts";a:1:{s:6:"feedit";s:0:"";}}', 'Frontend Editing Team', 'jeff@webempoweredchurch.org', 'webempoweredchurch', 'ff0c53b6570eea2e265250913b4e2c68', 'Compatibility for TYPO3 up to and including version 6.2. Thanks to Christopher, Lorenz Ulrich, and other contributors.', '', 1006000, 1, 0),
