(24129, 0, 'cw_powerrotator', 1, '3.0.0', 214, 44, 'PowerRotator', 'PowerRotator for TYPO3.\n\nThis Extension adds PowerRotator from Adobe to your TYPO3 website.\n\nIt supports following effects: Ken Burns, fading, crossfading, windows, audio, links, captions an much more.\n\nA detailed documentation is located under EXT:doc', 2, 0, 2, 1273266144, 'a:0:{}', 'Carsten Walther', 'carsten.walther@d-complex.de', 'd-complex', '4e9c6df0e0dd94ebc38bca698cc48715', 'some fixes, config via flexforms, have fun', '', 3000000, 0, 0),
