(24251, 0, 'comet', 1, '1.0.0', 61, 5, 'Techniques to implement Comet with PHP', 'This extension implements several techniques to implement Comet with PHP.\nFor example, this can be useful to know in real time the result of a database query made by a FE plugin without reload the page. \nIt includes a FE plugin and two examples extracted ', 1, 0, 3, 1260194570, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"5.2.0-0.0.0";s:5:"typo3";s:12:"4.2.10-0.0.0";}}', 'Antonio lvarez Feijoo', 'aafeijoo (at) gmail.com', 'aafeijoo', '6be5ba020d97587cad319644f846a281', 'First release', '', 1000000, 0, 0);
