(24252, 0, 'comet', 1, '1.0.1', 61, 6, 'Techniques to implement Comet with PHP', 'This extension implements several techniques to implement Comet with PHP.\nFor example, this can be useful to know in real time the result of a database query made by a FE plugin without reload the page. \nIt includes a FE plugin and two examples extracted ', 1, 0, 3, 1260200809, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"5.2.0-0.0.0";s:5:"typo3";s:12:"4.2.10-0.0.0";}}', 'Antonio Alvarez Feijoo', 'aafeijoo (at) gmail.com', 'aafeijoo', 'de4fad0be5281c7188671161b8ac4c6e', '', '', 1000001, 0, 0),
(24253, 0, 'comet', 1, '1.0.2', 61, 14, 'Techniques to implement Comet with PHP', 'This extension implements several techniques to implement Comet with PHP.\nThis can be useful to do things in real time without reload the page.\nIt includes two examples from http://kerphi.zeitoun.net/articles/comet_and_php/\nYou have to include manually Pr', 1, 0, 3, 1260204436, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"5.2.0-0.0.0";s:5:"typo3";s:12:"4.2.10-0.0.0";}}', 'Antonio Alvarez Feijoo', 'aafeijoo (at) gmail.com', 'aafeijoo', '0dadff0a0df5b2eb840fed3164ac52c5', 'Changed the description to indicate the need to manually include the Prototype JavaScript Framework (typo3_src/typo3/contrib/prototype/prototype.js)', '', 1000002, 0, 0),
(24254, 0, 'comet', 1, '1.1.0', 61, 36, 'Techniques to implement Comet with PHP', 'This extension implements several techniques to implement Comet with PHP.\nThis can be useful to do things in real time without reload the page.\nYou have to include manually Prototype JS (typo3_src/typo3/contrib/prototype/prototype.js)', 1, 0, 3, 1260434712, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"5.2.0-0.0.0";s:5:"typo3";s:12:"4.2.10-0.0.0";}}', 'Antonio Alvarez Feijoo', 'aafeijoo (at) gmail.com', 'aafeijoo', '4526b51467b269248c2d837e2efd5db2', ' - Added support to call CLI scripts with AJAX long polling.\r\n - Added a new example with tt_news', '', 1001000, 1, 0),
