(24627, 0, 'transactor', 1, '0.0.1', 184, 33, 'Payment Transactor API', 'This is a basic API to develop extensions which connect to different payment transaction gateways.', 0, 0, 4, 1262248450, 'a:1:{s:7:"depends";a:4:{s:3:"cms";s:0:"";s:7:"div2007";s:6:"0.2.1-";s:3:"php";s:11:"5.0.4-0.0.0";s:5:"typo3";s:11:"3.8.2-0.0.0";}}', 'Franz Holzinger', 'franz@ttproducts.de', 'franzholz', 'cfdd0dedb65733b953846166fe551ea4', 'Payment API with internal logic. Build you specific payment extensions named transactor_extkey with transactor as the base extension.', '', 1, 0, 0),
(24628, 0, 'transactor', 1, '0.0.3', 184, 45, 'Payment Transactor API', 'This is a basic API to develop extensions which connect to different payment transaction gateways.', 0, 0, 4, 1293439798, 'a:1:{s:7:"depends";a:4:{s:3:"cms";s:0:"";s:7:"div2007";s:11:"0.3.2-0.0.0";s:3:"php";s:11:"5.0.4-0.0.0";s:5:"typo3";s:11:"3.8.2-0.0.0";}}', 'Franz Holzinger', 'franz@ttproducts.de', 'franzholz', 'c3e78344fb555c8f2d70131e0300f282', 'Support for voucher - Change in the return of the $errorMessage - Fields are configurable in the EM.', '', 3, 0, 0),
