(24632, 0, 'transactor', 1, '0.1.2', 184, 0, 'Payment Transactor API', 'This is a basic API to develop extensions which connect to different payment transaction gateways.', 0, 0, 4, 1338060247, 'a:1:{s:7:"depends";a:4:{s:3:"cms";s:0:"";s:7:"div2007";s:11:"0.8.1-0.0.0";s:3:"php";s:11:"5.0.4-0.0.0";s:5:"typo3";s:12:"3.8.2-4.7.99";}}', 'Franz Holzinger', 'franz@ttproducts.de', 'franzholz', '02cee7317b012568b056e5074cc1a5bb', 'support for the new language system of TYPO3 4.6 - \nDo not overwrite a formerly generated error message -\nAdd a marker XML file.', '', 1002, 0, 0),
(24633, 0, 'transactor', 1, '0.4.2', 184, 0, 'Payment Transactor API', 'This is a basic API to develop extensions which connect to different payment transaction gateways.', 2, 0, 4, 1477467220, 'a:1:{s:7:"depends";a:3:{s:3:"php";s:13:"5.3.0-7.99.99";s:5:"typo3";s:13:"4.5.0-7.99.99";s:7:"div2007";s:12:"1.6.10-0.0.0";}}', 'Franz Holzinger', 'franz@ttproducts.de', 'franzholz', '7e492410d7f98ec75269f2dc925e496c', ' \nsupport to add payment costs to the handling costs or to add an internal payment product for an external payment Gateway. Add a new PaymentApi class for TYPO3 7.x. \n', '', 4002, 0, 0),
