(24636, 0, 'transactor', 1, '0.3.0', 184, 0, 'Payment Transactor API', 'This is a basic API to develop extensions which connect to different payment transaction gateways.', 2, 0, 4, 1417875983, 'a:1:{s:7:"depends";a:3:{s:3:"php";s:12:"5.2.4-5.5.99";s:5:"typo3";s:12:"4.3.0-6.2.99";s:7:"div2007";s:11:"1.0.3-0.0.0";}}', 'Franz Holzinger', 'franz@ttproducts.de', 'franzholz', 'e2cf088d7cbf1e118c55641007eb0ff8', ' \nWorks also with TYPO3 6.2. It provides a listener hook.\n', '', 3000, 0, 0),
