(24639, 0, 'transactor', 1, '0.4.0', 184, 0, 'Payment Transactor API', 'This is a basic API to develop extensions which connect to different payment transaction gateways.', 2, 0, 4, 1461700078, 'a:1:{s:7:"depends";a:3:{s:3:"php";s:12:"5.3.0-5.7.99";s:5:"typo3";s:12:"4.5.0-7.7.99";s:7:"div2007";s:11:"1.0.3-0.0.0";}}', 'Franz Holzinger', 'franz@ttproducts.de', 'franzholz', 'bd289a2fe77e4ce63ba943434eaf52f1', ' \nSupport for tt_products 2.12.0 which supports multiply country specific taxes\nfrom the next version of static_info_tables_taxes. Support for TYPO3 7.6.2.\n', '', 4000, 0, 0),
