(24641, 0, 'transactor', 1, '0.4.3', 184, 0, 'Payment Transactor API', 'This is a basic API to develop extensions which connect to different payment transaction gateways.', 2, 0, 4, 1494445929, 'a:1:{s:7:"depends";a:3:{s:3:"php";s:13:"5.3.5-7.99.99";s:5:"typo3";s:13:"4.5.0-8.99.99";s:7:"div2007";s:11:"1.7.6-0.0.0";}}', 'Franz Holzinger', 'franz@ttproducts.de', 'franzholz', '8ee7d453a476c5bc2c973908d1cad576', ' \nReady for TYPO3 8.7.x\n', '', 4003, 0, 0),
(24642, 0, 'transactor', 1, '0.5.0', 184, 0, 'Payment Transactor API', 'This is a basic API to develop extensions which connect to different payment transaction gateways.', 2, 0, 4, 1506937496, 'a:1:{s:7:"depends";a:3:{s:3:"php";s:13:"5.3.3-7.99.99";s:5:"typo3";s:13:"4.5.0-8.99.99";s:7:"div2007";s:12:"1.7.12-0.0.0";}}', 'Franz Holzinger', 'franz@ttproducts.de', 'franzholz', '01c7379191286985eda973db136eb252', ' \nAdd an additional namespace API. This must be activated in the Extension Manager. Set compatibility  0 .\n', '', 5000, 0, 0),
(24643, 0, 'transactor', 1, '0.5.1', 184, 0, 'Payment Transactor API', 'This is a basic API to develop extensions which connect to different payment transaction gateways.', 2, 0, 4, 1507202193, 'a:1:{s:7:"depends";a:3:{s:3:"php";s:13:"5.3.3-7.99.99";s:5:"typo3";s:13:"4.5.0-8.99.99";s:7:"div2007";s:12:"1.7.12-0.0.0";}}', 'Franz Holzinger', 'franz@ttproducts.de', 'franzholz', 'f080f4e6c1329aa1585b6efb96678dd7', ' \nAPI change for transactionGetForm. The payment method needs not to be like transactor_my_payment_method . \n ', '', 5001, 0, 0),
(24644, 0, 'transactor', 1, '0.6.0', 184, 0, 'Payment Transactor API', 'This is a basic API to develop extensions which connect to different payment transaction gateways.', 2, 0, 4, 1509098171, 'a:1:{s:7:"depends";a:3:{s:3:"php";s:13:"5.3.3-7.99.99";s:5:"typo3";s:13:"4.5.0-8.99.99";s:7:"div2007";s:12:"1.7.12-0.0.0";}}', 'Franz Holzinger', 'franz@ttproducts.de', 'franzholz', '3269d5aed3b2d4c913e678b925c6cee3', ' \nmodification of the new namespace API with 2 new parameters order number and notification email \nbugfix of the usage of the field gatewayid. This must be used for a gateway specific transaction id.\n', '', 6000, 0, 0),
(24645, 0, 'transactor', 1, '0.6.1', 184, 0, 'Payment Transactor API', 'This is a basic API to develop extensions which connect to different payment transaction gateways.', 2, 0, 4, 1510168758, 'a:1:{s:7:"depends";a:3:{s:3:"php";s:13:"5.3.3-7.99.99";s:5:"typo3";s:13:"4.5.0-8.99.99";s:7:"div2007";s:12:"1.7.14-0.0.0";}}', 'Franz Holzinger', 'franz@ttproducts.de', 'franzholz', 'd68623cc40a20c29ffd0b96de483647d', ' \nSet the gateway mode in the methods.xml file gatewaymode entry instead of the setup.\nThe payment notification urls have a new parameter transactor which refers to the request id which is the abbreviation of the reference id\n', '', 6001, 1, 0),
