(24651, 0, 'be_secure_pw', 1, '0.1.1', 494, 14, 'Make BE user password really secure', 'You can set password conventions to force secure passwords for BE users. Works with TYPO3 4.3.0.', 1, 0, 0, 1262615110, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:11:"4.2.7-4.3.0";}}', 'Thomas Loeffler', 'typo3@tomalo.de', 'tomalo.stuttgart', 'fcd88497f4bd40c558c4f25abb852d52', 'Bugfix: Password was hashed with MD5 again if password was not changed but other fields.', '', 1001, 0, 0),
(24652, 0, 'be_secure_pw', 1, '0.1.2', 494, 12, 'Make BE user password really secure', 'You can set password conventions to force secure passwords for BE users. Works with TYPO3 4.3.0.', 1, 0, 0, 1263501769, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"4.2.7-4.3.99";}}', 'Thomas Loeffler', 'typo3@tomalo.de', 'tomalo.stuttgart', 'ed23fbf7d5423d0b4d8a936a682ff2ed', '- Set old password if conventions not fit\r\n- Better error messages\r\n\r\nBuilt during TYPO3 Usergroup Stuttgart (thx for feedback)', '', 1002, 0, 0),
