(24958, 0, 'pit_googlemap', 1, '1.0.2', 128, 10, 'Google Map', 'This extension is used to display events in a specified area with the help of google map. The extension allows to enter the events from the backend and frontend. Admin review is also possible for the frontend entry. Also detailed view of each event is pos', 1, 0, 3, 1289299939, 'a:0:{}', 'Ajesh M S (PIT Solutions)', 'ajesh@pitsolutions.com', 'ajeshms1981', '80f3d981579bbff913bbec504621681e', '', 'PIT Solutions', 1000002, 0, 0),
(24959, 0, 'pit_googlemap', 1, '1.0.3', 128, 74, 'Google Map', 'Allows to display events in google map based on location. Frontend event entry also possible. The event markers loaded dynamically from xml on each mouse drag. This is ideally suited for showing lot of events on the map. Region based grouping also possibl', 1, 0, 3, 1289364555, 'a:0:{}', 'Ajesh M S (PIT Solutions)', 'ajesh@pitsolutions.com', 'ajeshms1981', '1ba8e18bc5b55c0ba68edd953f3c80f5', '', 'PIT Solutions', 1000003, 1, 0);
INSERT INTO `tx_extensionmanager_domain_model_extension` (`uid`, `pid`, `extension_key`, `repository`, `version`, `alldownloadcounter`, `downloadcounter`, `title`, `description`, `state`, `review_state`, `category`, `last_updated`, `serialized_dependencies`, `author_name`, `author_email`, `ownerusername`, `md5hash`, `update_comment`, `authorcompany`, `integer_version`, `current_version`, `lastreviewedversion`) VALUES
(24960, 0, 'dam_tree_view', 1, '0.1.1', 0, 0, 'Hierarchical File List according to DAM Categories', 'Frontend plugin shows a hierarchical list of files sorted by DAM categories similar to FIONA media pools. \nBy the way FIONA is a commercial content management system that can handle lists of e.g. pdf files very easily - easier than media in typo3. Of course for other stuff this extentions programmer prefers typo3.', 2, 0, 3, 1397590398, 'a:1:{s:7:"depends";a:4:{s:5:"typo3";s:12:"4.5.0-4.5.99";s:3:"cms";s:0:"";s:3:"dam";s:0:"";s:11:"dam_catedit";s:0:"";}}', 'Frank Thorsten Breuer', 'frank-thorsten.breuer@udo.edu', 'ftb', '8e83063b7ea58f24876b8e7bc0f9f0b4', 'Added a manual, corrected typos in language files, added static template files, defining extensions style sheets.', '', 1001, 1, 0),
(24961, 0, 'dam_tree_view', 1, '0.1.0', 0, 0, 'Hierarchical File List according to DAM Categories', 'Frontend plugin shows a hierarchical list of files sorted by DAM categories similar to FIONA media pools. \nBy the way FIONA is a commercial content management system that can handle lists of e.g. pdf files very easily - easier than media in typo3. Of course for other stuff this extentions programmer prefers typo3.', 2, 0, 3, 1394743641, 'a:1:{s:7:"depends";a:4:{s:5:"typo3";s:12:"4.5.0-4.5.99";s:3:"cms";s:0:"";s:3:"dam";s:0:"";s:11:"dam_catedit";s:0:"";}}', 'Frank Thorsten Breuer', 'frank-thorsten.breuer@udo.edu', 'ftb', '6003be96e30f01e022fb8208015714c2', 'Frontend plugin shows a hierarchical list of files sorted by DAM categories similar to FIONA media pools. ', '', 1000, 0, 0),
