(25119, 0, 't3xcscimp', 1, '0.0.1', 187, 25, 'T3X CSS styled content improvement', 'Improves "css_styled_content" with automatically generated CSS, additional content-rendering and strict XHTML-compliant output, which can be edited with a new styling-mechanism in the backend. Adds captcha functionality to forms if "sr_freecap" or "captch', 3, 0, 2, 1265819263, 'a:2:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:5:"typo3";s:11:"4.3.0-4.3.1";s:18:"css_styled_content";s:11:"1.0.0-1.0.0";}s:9:"conflicts";a:1:{s:16:"eu_edit_dropdown";s:6:"0.0.0-";}}', 'Stephan N Kellermayr', 'stephan.kellermayr(t)t3x.at', 'sonority', '6d5124ebef1dd80560e867a5146b3587', '"Oops! I Did It Again". First experimental release of a new TYPO3-styling-mechanism. DO NOT USE THIS IN PRODUCTION ENVIRONMENT! ...But you need not be afraid to test it!', 'www.sonority.at - MULTIMEDIA ART DESIGN', 1, 0, 0),
(25120, 0, 't3xcscimp', 1, '0.1.0', 187, 17, 'T3X CSS styled content improvement', 'Improves "css_styled_content" with automatically generated CSS, additional content-rendering and strict XHTML-compliant output, which can be edited with a new styling-mechanism in the backend. Adds captcha functionality to forms (sr_freecap, captcha).', 1, 0, 2, 1298220464, 'a:2:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:5:"typo3";s:11:"4.3.0-4.5.0";s:18:"css_styled_content";s:11:"1.0.0-1.0.0";}s:9:"conflicts";a:1:{s:16:"eu_edit_dropdown";s:6:"0.0.0-";}}', 'Stephan Kellermayr', 'stephan.kellermayr(at)t3x.at', 'sonority', '9351288fe5aabc80ffe054db39cf0634', 'A new TYPO3-styling-mechanism to bridge the gap between designers and TYPO3-integrators. Added many small features on the way to a helpful "website kickstarter"...', 'www.sonority.at - MULTIMEDIA ART DESIGN', 1000, 0, 0),
(25121, 0, 't3xcscimp', 1, '0.1.1', 187, 29, 'T3X CSS styled content improvement', 'Improves "css_styled_content" with automatically generated CSS, additional content-rendering and strict XHTML-compliant output, which can be edited with a new styling-mechanism in the backend. Adds captcha functionality to forms (sr_freecap, captcha).', 1, 0, 2, 1298306892, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:11:"4.3.0-4.5.0";}}', 'Stephan Kellermayr', 'stephan.kellermayr(at)t3x.at', 'sonority', '5f7b8889dd002e0f0f5580a35c8db24a', 'Updated the manual...', 'www.sonority.at - MULTIMEDIA ART DESIGN', 1001, 0, 0),
(25122, 0, 't3xcscimp', 1, '0.2.0', 187, 17, 'T3X CSS styled content improvement', 'Improves "css_styled_content" with automatically generated CSS, additional content-rendering and strict XHTML-compliant output, which can be edited with a new styling-mechanism in the backend. Adds captcha functionality to forms (sr_freecap, captcha).', 1, 0, 2, 1299531313, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:11:"4.3.0-4.5.0";}}', 'Stephan Kellermayr', 'stephan.kellermayr(at)t3x.at', 'sonority', 'd450f533930ab5a5a1bc4169b7e95dd9', 'Major rewrite of the constants-editor part. Added functionality for google-webfonts.', 'www.sonority.at - MULTIMEDIA ART DESIGN', 2000, 0, 0),
(25123, 0, 't3xcscimp', 1, '0.3.0', 187, 34, 'T3X CSS styled content improvement', 'Improves "css_styled_content" with automatically generated CSS, additional content-rendering and strict XHTML-compliant output, which can be edited with a new styling-mechanism in the backend. Adds captcha functionality to forms (sr_freecap, captcha).', 1, 0, 2, 1299842560, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:11:"4.3.0-4.5.0";}}', 'Stephan Kellermayr', 'stephan.kellermayr(at)t3x.at', 'sonority', 'c167559d23514418b9c2df6a950720ad', 'Added support for colPos 1/2/3. Stylemapping can be configured column-specific.\r\nBugfix in constants-editor.', 'www.sonority.at - MULTIMEDIA ART DESIGN', 3000, 0, 0),
