(25157, 0, 'html5meta_t3lib_pagerenderer', 1, '0.0.2', 438, 14, 'HTML5 charset-metatag', 'Generate the correct HTML5 charset-metatag for your website. Using XCLASS to overwrite the wrong value in t3lib_pagerenderer.', 3, 0, 2, 1266333564, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"5.2.0-0.0.0";s:5:"typo3";s:15:"4.3.dev-4.99.99";}}', 'Dan Untenzu', 'untenzu@webit.de', 'udwebit', '5e0b57c77bd9897383495a6e466e5cd1', 'Initial upload', '', 2, 0, 0),
(25158, 0, 'html5meta_t3lib_pagerenderer', 1, '0.0.3', 438, 388, 'HTML5 charset-metatag', 'TYPO3 is able to generate a valid HTML5-header. There is just a tiny imperfection with the charset-metatag. This extension provides a cosmetic change on the charset-metatag by using the XCLASS-mechanism to overwrite a value in t3lib_pagerenderer.', 2, 0, 2, 1274257583, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"5.2.0-0.0.0";s:5:"typo3";s:15:"4.3.dev-4.99.99";}}', 'Dan Untenzu', 'untenzu@webit.de', 'udwebit', '5fa362df54b83ac5715e4b345f8c8fd5', '', '', 3, 0, 0),
(25159, 0, 'html5meta_t3lib_pagerenderer', 1, '0.0.4', 438, 36, 'HTML5 charset-metatag', 'TYPO3 is able to generate a valid HTML5-header. There is just a tiny imperfection with the charset-metatag. This extension provides a cosmetic change on the charset-metatag by using the XCLASS-mechanism to overwrite a value in t3lib_pagerenderer. [obsolete] This feature is a core functionality since TYPO3 version 4.5.4! See manual for details.', 5, 0, 2, 1343376784, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"5.2.0-0.0.0";s:5:"typo3";s:13:"4.3.dev-4.5.3";}}', 'Dan Untenzu', 'untenzu@webit.de', 'udwebit', 'de506ecd5834db8dfc5b0550158a5a2b', 'This extension is marked as obsolete from now on, since this feature is a TYPO3 core functionality by now (in all versions greater than 4.5.3). Just use config.doctype html5 instead.\n\n// reuploaded because of TER hickups', '', 4, 0, 0),
(25160, 0, 'html5meta_t3lib_pagerenderer', 1, '0.0.5', 438, 0, 'HTML5 charset-metatag', 'TYPO3 is able to generate a valid HTML5-header. There is just a tiny imperfection with the charset-metatag. This extension provides a cosmetic change on the charset-metatag by using the XCLASS-mechanism to overwrite a value in t3lib_pagerenderer. [obsolete] This feature is a core functionality since TYPO3 version 4.5.4! See manual for details.', 5, 0, 2, 1343727070, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"5.2.0-0.0.0";s:5:"typo3";s:13:"4.3.dev-4.5.3";}}', 'Dan Untenzu', 'untenzu@webit.de', 'udwebit', '9c5f566431e98c6e54597a89466e66a8', 'This extension is marked as obsolete from now on, since this feature is a TYPO3 core functionality by now (in all versions greater than 4.5.3). Just use config.doctype html5 instead.\n\n// reuploaded due to md5 hash error in TER', '', 5, 0, 0),
(25161, 0, 'html5meta_t3lib_pagerenderer', 1, '0.1.0', 438, 0, 'HTML5 charset-metatag', 'TYPO3 is able to generate a valid HTML5-header. There is just a tiny imperfection with the charset-metatag. This extension provides a cosmetic change on the charset-metatag by using the XCLASS-mechanism to overwrite a value in t3lib_pagerenderer. [obsolete] This feature is a core functionality since TYPO3 version 4.5.4! See manual for details.', 5, 0, 2, 1343727112, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"5.2.0-0.0.0";s:5:"typo3";s:13:"4.3.dev-4.5.3";}}', 'Dan Untenzu', 'untenzu@webit.de', 'udwebit', 'f8877f2cbf0296f40513de29445fed94', 'This extension is marked as obsolete from now on, since this feature is a TYPO3 core functionality by now (in all versions greater than 4.5.3). Just use config.doctype html5 instead.\n\n// reuploaded due to md5 hash error in TER', '', 1000, 1, 0),
