(25238, 0, 'jftabulatorsitemap', 1, '1.3.0', 624, 0, 'Tabulator Sitemap', 'Display a sitemap in a jQuery UI tab, requested by ajax. Use t3jquery for better integration of other jQuery extensions.', 2, 0, 3, 1351369014, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:3:"php";s:11:"5.0.0-0.0.0";s:5:"typo3";s:11:"4.3.0-0.0.0";}}', 'Juergen Furrer', 'juergen.furrer@gmail.com', 'abandoned_extensions', 'cef2e8ff7058635fa91e23bad73c6641', 'Change Lib to jQuery UI 1.9.1 Add jQuery 1.8.2 / If you use t3jquery, you have to change the jQuery UI Version to 1.9.x and generate the Lib again', '', 1003000, 0, 0),
