(25240, 0, 'rm_staticfile', 1, '0.1.6', 40, 40, 'Delete static cache files', 'Improve your performance! This extension enables the delete of static files, which where generated by nc_staticfilecache. It is a team play with the TYPO3 cache management, ttnews, ttnewscache, sg_newsplus and sg_zfelib.', 3, 0, 0, 1266695297, 'a:2:{s:7:"depends";a:3:{s:7:"realurl";s:0:"";s:18:"nc_staticfilecache";s:0:"";s:11:"ttnewscache";s:0:"";}s:9:"conflicts";a:1:{s:27:"delete_staticfile_by_3party";s:0:"";}}', 'Dirk Wildt', 'dirk.wildt.at.think-visually.com', 'dwildt', 'cf4819372f0020664923e1c34063e5cc', 'Publishing in the TER. Corporate Design Die Netzmacher GbR', 'think visually!', 1006, 1, 0),
(25241, 0, 't3xskin', 1, '0.0.1', 140, 27, 'T3X TYPO3 skin', 'A new concept of iconset-redesign/consistency. Please use this version as preview!', 3, 0, 4, 1266769552, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"5.1.0-0.0.0";s:5:"typo3";s:11:"4.3.1-0.0.0";}}', 'Stephan N Kellermayr', 'stephan.kellermayr(t)t3x.at', 'sonority', 'f7ee65c4d668c9f82e2e30e9ba2be191', 'first release of the new TYPO3-iconset, which will hopefully observed by the core-development-team!', 'www.sonority.at - MULTIMEDIA ART DESIGN', 1, 0, 0),
(25242, 0, 't3xskin', 1, '0.0.2', 140, 4, 'T3X TYPO3 skin', 'A modern redesign of the default TYPO3 backend-skin. Use this, if you want a handsome and stylish backend. Essentially its stable, because it has the same structure as t3skin.', 3, 0, 0, 1267041245, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:11:"4.3.1-0.0.0";}}', 'Stephan N Kellermayr', 'stephan.kellermayr(t)t3x.at', 'sonority', 'a681aae91108c4b44fba4b87667306ab', 'Added some new icons...', 'www.sonority.at - MULTIMEDIA ART DESIGN', 2, 0, 0),
(25243, 0, 't3xskin', 1, '1.0.0', 140, 109, 'T3X TYPO3 skin', 'A modern redesign of the TYPO3-backend with 26 different color-styles and two iconsets. Use this, if you want a handsome and stylish backend.', 0, 0, 0, 1270312437, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:11:"4.3.0-0.0.0";}}', 'Stephan N Kellermayr', 'stephan.kellermayr(t)t3x.at', 'sonority', '1c35ef47b91f8c57f45613cc5dbf2620', 'massive structural changes, added 26 different CSS-styles and two iconsets! feedbacks are appreciated!', 'www.sonority.at - MULTIMEDIA ART DESIGN', 1000000, 1, 0),
(25244, 0, 'ods_osm', 1, '0.1.0', 718, 5, 'Openstreetmap', 'Add an interactive openstreetmap map to your website.', 0, 0, 3, 1267121185, 'a:1:{s:7:"depends";a:1:{s:10:"tt_address";s:0:"";}}', 'Robert Heel', 'rheel@1drop.de', 'bobosch', '76f9ae486d31f6c7570a0040b26759e2', 'Initial release', '', 1000, 0, 0),
(25245, 0, 'ods_osm', 1, '0.2.0', 718, 3, 'Openstreetmap', 'Add an interactive openstreetmap map to your website.', 0, 0, 3, 1267232090, 'a:1:{s:7:"depends";a:1:{s:10:"tt_address";s:0:"";}}', 'Robert Heel', 'rheel@1drop.de', 'bobosch', '7e878960f07ca4702ec69b3a81a13e8e', '	 Add: Coordinate selection wizard.\r\n	 Add: Coordinates in fe_users.', '', 2000, 0, 0),
(25246, 0, 'ods_osm', 1, '0.3.0', 718, 3, 'OpenStreetMap', 'Add an interactive OpenStreetMap map to your website.', 1, 0, 3, 1267568236, 'a:1:{s:7:"depends";a:1:{s:10:"tt_address";s:0:"";}}', 'Robert Heel', 'rheel@1drop.de', 'bobosch', 'cd23a3c76aeda2df4ac2c18c1bfd7351', '	 Add: Show GPX tracks.\r\n	 Change: Optimize database fields.\r\n', '', 3000, 0, 0),
(25247, 0, 'ods_osm', 1, '0.3.1', 718, 3, 'OpenStreetMap', 'Add an interactive OpenStreetMap map to your website.', 1, 0, 3, 1267812636, 'a:1:{s:7:"depends";a:1:{s:10:"tt_address";s:0:"";}}', 'Robert Heel', 'rheel@1drop.de', 'bobosch', '285b49d78cc74d950cd372b790ad0df4', '	 Add: Documentation.\r\n	 Add: absRefPrefix.\r\n	 Bugfix: Allow negative longitude.', '', 3001, 0, 0),
(25248, 0, 'ods_osm', 1, '0.4.0', 718, 2, 'OpenStreetMap', 'Add an interactive OpenStreetMap map to your website.', 1, 0, 3, 1268675019, 'a:1:{s:7:"depends";a:1:{s:10:"tt_address";s:0:"";}}', 'Robert Heel', 'rheel@1drop.de', 'bobosch', 'fde0bd9f65460e549b599ce4454870e4', '	 Add: Marker popups.\r\n	 Change: Javascript cleanup.\r\n	 Update: Documentation.\r\n', '', 4000, 0, 0),
(25249, 0, 'ods_osm', 1, '0.5.0', 718, 2, 'OpenStreetMap', 'Add an interactive OpenStreetMap map to your website.', 1, 0, 3, 1269281413, 'a:1:{s:7:"depends";a:1:{s:10:"tt_address";s:0:"";}}', 'Robert Heel', 'rheel@1drop.de', 'bobosch', '1af1181dbf8d0499a4a8a6f8c5f1e4a4', '	 Add: Get items from pages, fe_groups, tt_address_group.\r\n	 Add: Set icon in group.\r\n	 Add: Optional local javascript and image files.\r\n	 Update: Documentation.\r\n', '', 5000, 0, 0),
(25250, 0, 'ods_osm', 1, '0.6.0', 718, 2, 'OpenStreetMap', 'Add an interactive OpenStreetMap map to your website.', 1, 0, 3, 1270200484, 'a:1:{s:7:"depends";a:1:{s:10:"tt_address";s:0:"";}}', 'Robert Heel', 'rheel@1drop.de', 'bobosch', 'b21f6faea219f4cdef8f2182a2bf24e7', '	 Add: Layerswitcher. (Thanks to Markus Volkmer)\r\n	 Add: Static Osmarender map.\r\n	 Bugfix: Show fe_groups marker.\r\n	 Bugfix: Allow negative values in offset.\r\n	 Update: Documentation.\r\n', '', 6000, 0, 0),
(25251, 0, 'ods_osm', 1, '0.6.1', 718, 2, 'OpenStreetMap', 'Add an interactive OpenStreetMap map to your website.', 1, 0, 3, 1270581785, 'a:1:{s:7:"depends";a:1:{s:10:"tt_address";s:0:"";}}', 'Robert Heel', 'rheel@1drop.de', 'bobosch', '9b65a08033b14ec0abf267d19c3d9acc', '	 Add: TS option for script path.\r\n	 Add: TS option for additional layerswitcher options.\r\n	 Add: CycleMap.\r\n', '', 6001, 0, 0),
(25252, 0, 'ods_osm', 1, '1.0.0', 718, 2, 'OpenStreetMap', 'Add an interactive OpenStreetMap map to your website.', 2, 0, 3, 1270843121, 'a:1:{s:7:"depends";a:1:{s:10:"tt_address";s:0:"";}}', 'Robert Heel', 'rheel@1drop.de', 'bobosch', '05807cdf9ec1948323f7706e82669f02', '	 Incompatible change: Base layers as more flexible database elements. Please update your configuration if you didnt use Mapnik.\r\n	 Incompatible change: Cleanup map control options: Renamed show_navigation to mouse_navigation, show_pan_zoom_bar to show', '', 1000000, 0, 0),
(25253, 0, 'ods_osm', 1, '1.1.0', 718, 2, 'OpenStreetMap', 'Add an interactive OpenStreetMap map to your website.', 2, 0, 3, 1270947649, 'a:1:{s:7:"depends";a:1:{s:10:"tt_address";s:0:"";}}', 'Robert Heel', 'rheel@1drop.de', 'bobosch', '7cd6770e079d8a3bb2d1dae1c7d45ffd', '	 Add: Layer field for static javascript and static url.\r\n	 Add: Base layer "http://openpistemap.org/".\r\n	 Add: First marker to static map.\r\n', '', 1001000, 0, 0),
(25254, 0, 'ods_osm', 1, '1.2.0', 718, 2, 'OpenStreetMap', 'Add an interactive OpenStreetMap map to your website. Can also show other OpenLayers compatible maps.', 2, 0, 3, 1272801708, 'a:1:{s:7:"depends";a:1:{s:10:"tt_address";s:0:"";}}', 'Robert Heel', 'rheel@1drop.de', 'bobosch', 'd13bdacc5121a4dd9ab670c10555df36', '	 Add: Option to update coordinates on every address change.\r\n	 Add: Update cached files after one week.\r\n	 Change: Include "OpenStreetMap.js" only if needed.\r\n	 Remove: TS option "path_openstreetmap" (can be changed in the layer element).\r\n	 Add: Ma', '', 1002000, 0, 0),
