(25298, 0, 'ods_osm', 1, '1.11.1', 718, 0, 'OpenStreetMap', 'Add an interactive OpenStreetMap map to your website. Can also show other OpenLayers compatible maps.', 2, 0, 3, 1414094150, 'a:1:{s:7:"depends";a:2:{s:10:"tt_address";s:0:"";s:5:"typo3";s:12:"4.5.0-6.2.99";}}', 'Robert Heel', 'typo3@bobosch.de', 'bobosch', '8a89fa8a52b0f533c10f789e52303d93', '	 Bug 62424: Set default image path in leaflet (Thanks to Michael Oehlhof).\r\n	 Bugfix: Escape slash in javascript.\r\n	 Add: Overlay layer "Stamen Terrain Labels" (http://maps.stamen.com/).\r\n	 Bug 61011: Invalid argument supplied for foreach() in clas', '', 1011001, 0, 0),
