(25303, 0, 'ods_osm', 1, '1.11.6', 718, 0, 'OpenStreetMap', 'Add an interactive OpenStreetMap map to your website. Can also show other OpenLayers compatible maps.', 2, 0, 3, 1434656500, 'a:1:{s:7:"depends";a:2:{s:10:"tt_address";s:0:"";s:5:"typo3";s:12:"4.5.0-6.2.99";}}', 'Robert Heel', 'typo3@bobosch.de', 'bobosch', '9af31fbdb994d30a6416d9e1f9dde78a', '	 Change: Add scalebar to leaflet map.\r\n	 Change: Allow different javascript calls for OpenLayers and Leaflet. Please run update.\r\n	 Update: leaflet-plugins to 1.3.3.\r\n	 Bugfix: Bug with base layers and leaflet. \r\n', '', 1011006, 0, 0),
(25304, 0, 'ods_osm', 1, '1.11.7', 718, 0, 'OpenStreetMap', 'Add an interactive OpenStreetMap map to your website. Can also show other OpenLayers compatible maps.', 2, 0, 3, 1452376619, 'a:1:{s:7:"depends";a:2:{s:10:"tt_address";s:0:"";s:5:"typo3";s:12:"4.5.0-6.2.99";}}', 'Robert Heel', 'typo3@bobosch.de', 'bobosch', '157e6b33cfa24515f975c9fd458c8f98', '	 Feature 67722: Add marker clusterer to leaflet.\r\n	 Change: New version of update script.\r\n	 Change: Use leaflet geoJson object for vector elements.\r\n	 Bugfix: Unsupported operand types in class.tx_odsosm_pi1.php on line 99\r\n	 Bug 72208: Invalid ar', '', 1011007, 0, 0),
