(25306, 0, 'ods_osm', 1, '1.12.1', 718, 0, 'OpenStreetMap', 'Add an interactive OpenStreetMap map to your website. Can also show other OpenLayers compatible maps.', 2, 0, 3, 1457471176, 'a:1:{s:7:"depends";a:2:{s:10:"tt_address";s:6:"3.0.0-";s:5:"typo3";s:13:"6.2.0-7.99.99";}}', 'Robert Heel', 'typo3@bobosch.de', 'bobosch', '984a66618ed1501a392fbfce23b697f2', '	 Bugfix: Show tt_address records in sys_category.\r\n	 Bugfix: Fix static functions.\r\n	 Bug 21: Coordinatepicker Wizard error in TYPO3 6.2.\r\n', '', 1012001, 0, 0),
(25307, 0, 'ods_osm', 1, '1.12.2', 718, 0, 'OpenStreetMap', 'Add an interactive OpenStreetMap map to your website. Can also show other OpenLayers compatible maps.', 2, 0, 3, 1457729400, 'a:1:{s:7:"depends";a:2:{s:10:"tt_address";s:6:"3.0.0-";s:5:"typo3";s:13:"6.2.0-7.99.99";}}', 'Robert Heel', 'typo3@bobosch.de', 'bobosch', 'a3e759f3301fa75c23e4cd6917152b25', '	 Bugfix: Correct mm relation for sys_category.\r\n	 Bugfix: IN instead of  in flexform.xml.\r\n	 Bugfix: Color attribute in leaflet tracks.\r\n	 Bugfix: Show tt_content lon and lat in coordinate picker.\r\n	 Bugfix: TYPO3 7 compatibility for tracks.\r\n', '', 1012002, 0, 0),
(25308, 0, 'ods_osm', 1, '1.12.3', 718, 0, 'OpenStreetMap', 'Add an interactive OpenStreetMap map to your website. Can also show other OpenLayers compatible maps.', 2, 0, 3, 1458242508, 'a:1:{s:7:"depends";a:2:{s:10:"tt_address";s:6:"3.0.0-";s:5:"typo3";s:13:"6.2.0-7.99.99";}}', 'Robert Heel', 'typo3@bobosch.de', 'bobosch', '57d28947d229b5a631e19f4db33fa5c8', '	 Feature 48742: Allow jQuery usage.\r\n	 Change: Add php 5.4 compatibility to class.tx_odsosm_div.php (Thanks to Daniel Minder).\r\n	 Change: The usage of $GLOBALS[TSFE]-JSeventFuncCalls is deprecated as of TYPO3 CMS 7. Use Javascript directly.\r\n	 Up', '', 1012003, 0, 0),
(25309, 0, 'ods_osm', 1, '2.0.0', 718, 0, 'OpenStreetMap', 'Add an interactive OpenStreetMap map to your website. Can also show other OpenLayers compatible maps.', 2, 0, 3, 1458509827, 'a:2:{s:7:"depends";a:1:{s:5:"typo3";s:13:"6.2.0-7.99.99";}s:8:"suggests";a:2:{s:11:"ods_osm_cal";s:0:"";s:18:"ods_osm_tt_address";s:0:"";}}', 'Robert Heel', 'typo3@bobosch.de', 'bobosch', 'a22a6d3af3e8e5e1a1afb431b28aa316', '	 Change: Transfered tt_address marker into extension "ods_osm_tt_address". Install it if you use tt_address records!\r\n	 Add: Extension ods_osm_tt_address 2.0.0 for tt_address 2.x\r\n	 Add: Extension ods_osm_tt_address 3.0.0 for tt_address 3.x\r\n	 Add: E', '', 2000000, 0, 0),
(25310, 0, 'ods_osm', 1, '2.1.0', 718, 0, 'OpenStreetMap', 'Add an interactive OpenStreetMap map to your website. Can also show other OpenLayers compatible maps.', 2, 0, 3, 1461525333, 'a:2:{s:7:"depends";a:1:{s:5:"typo3";s:13:"6.2.0-7.99.99";}s:8:"suggests";a:2:{s:11:"ods_osm_cal";s:0:"";s:18:"ods_osm_tt_address";s:0:"";}}', 'Robert Heel', 'typo3@bobosch.de', 'bobosch', '2b22d728aa0bd7077ae5a383b0269192', '	 Bufix: Ignore wrong TS marker entries.\r\n	 Bugfix: Typo in locallang_db.\r\n	 Add: Missing configuration examples in TS setup and TS constants.\r\n	 Change: Convert manual to REST format.\r\n	 Add: Define marker icon with TS TEXT object.\r\n	 Change: Searc', '', 2001000, 0, 0),
