(25335, 0, 'load_optimization', 1, '1.0.0', 111, 4, 'JS/CSS - Merger and Minimizer', 'This extension merges all included JS and CSS files and compresses them.\n  works with includeCSS includeJS, additionalHeaderData, headerData and CSS_DFAULT_STYLE\n  reads out css media types\n  the script tag can added at the end or at the top of the pag', 1, 0, 4, 1267619227, 'a:0:{}', 'Dirk Rudolph (T-Systems Multimedia Solutions GmbH)', 'Dirk.Rudolph@t-systems-mms.com', 'capd', 'bfa906fc190c74f31a5efd1598bdf96a', 'initial upload', 'T-Systems Multimedia Solutions GmbH', 1000000, 0, 0),
(25336, 0, 'load_optimization', 1, '1.0.1', 111, 3, 'JS/CSS - Merger and Minimizer', 'This extension merges all included JS and CSS files and compresses them.\n  works with includeCSS includeJS, additionalHeaderData, headerData and CSS_DFAULT_STYLE\n  reads out css media types\n  the script tag can added at the end or at the top of the pag', 1, 0, 4, 1267798726, 'a:0:{}', 'Dirk Rudolph (T-Systems Multimedia Solutions GmbH)', 'Dirk.Rudolph@t-systems-mms.com', 'capd', 'f9fe5d7c82dff74e1c35bd76fd8aadf6', 'fixed bug with building relative paths in subdirectories', 'T-Systems Multimedia Solutions GmbH', 1000001, 0, 0);
