(25337, 0, 'load_optimization', 1, '1.0.2', 111, 3, 'JS/CSS - Merger and Minimizer', 'This extension merges all included JS and CSS files and compresses them. Additional features: extentible compressor system, base64 encoded inline images, http and html optimization', 1, 0, 4, 1268732834, 'a:0:{}', 'Dirk Rudolph (T-Systems Multimedia Solutions GmbH)', 'Dirk.Rudolph@t-systems-mms.com', 'capd', 'e04be54b35b79bc7db1f6706dedfbd60', 'bugfix:building relative paths\r\nbugfix:executing paths with   using shell_exec\r\nadded:hook to clean cached files', 'T-Systems Multimedia Solutions GmbH', 1000002, 0, 0),
(25338, 0, 'load_optimization', 1, '1.0.3', 111, 101, 'JS/CSS - Merger and Minimizer', 'This extension merges all included JS and CSS files and compresses them. Main features: extentible compressor system, base64 encoded inline images, http and html optimization', 1, 0, 4, 1274887415, 'a:0:{}', 'Dirk Rudolph (T-Systems Multimedia Solutions GmbH)', 'Dirk.Rudolph@t-systems-mms.com', 'capd', '8f32d3c95a23e32c2f9fb02657bc7cb0', 'add: support for external libs (like google apis)\r\nadd: seperated configuration for js/css handling\r\nadd: html optimization for ajax requests\r\nfix: allowed ", in css: url() definition\r\n \r\nthanks to Matthias Koch for all related reports', 'T-Systems Multimedia Solutions GmbH', 1000003, 1, 0),
(25339, 0, 'dcformcreator', 1, '0.0.1', 58, 6, 'Zend Form Creator', 'Create a form with Zend Framework. \n	The form structure and the data which are filled in the form were stored in database tables. It can send an email, too.', 0, 0, 3, 1268133291, 'a:0:{}', 'Jan-Felix Weber', 'jan-felix.weber@deelgood.com', 'typobo', '8901f0bb4ec8a2e5622506c0807ac278', '- inserted dependency "zend_framework"\r\n- manual updated', '', 1, 0, 0),
