(25364, 0, 'cmd_api', 1, '0.1.6', 132, 0, 'CMD Api', 'Collection of useful functions helping in extension development', 1, 0, 4, 1355308222, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:12:"4.3.0-4.7.99";s:3:"php";s:11:"5.0.0-0.0.0";s:3:"cms";s:0:"";}}', 'Christophe Monard', 'contact@cmonard.fr', 'thorfin', 'a5ea08e87b4025a5be46c667ad672b52', ' small new functions\n remove empty line from CSS compressor output\n remove deprecated function usage\n add possibility to change wrap caracteres for markers generated by some function\n added copy of substituteMarkerAndSubpartArrayRecursive from TYPO3 ', '', 1006, 0, 0),
(25365, 0, 'cmd_api', 1, '0.2.0', 132, 0, 'CMD Api', 'Collection of useful functions helping in extension development', 1, 0, 4, 1363735088, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:12:"4.3.0-4.7.99";s:3:"php";s:11:"5.0.0-0.0.0";s:3:"cms";s:0:"";}}', 'Christophe Monard', 'contact@cmonard.fr', 'thorfin', 'c2a6c1c85f888a5fce2c850bd8e474d2', 'bugfix: optionSplit make noTrimWrap not working: If there is no option split needed, use standard method\nadd: __construct as constructor, classname still available for compatibility\nrewrite dependancies\n', '', 2000, 0, 0),
(25366, 0, 'cmd_api', 1, '0.2.1', 132, 0, 'CMD Api', 'Collection of useful functions helping in extension development', 2, 0, 4, 1363948125, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:12:"4.3.0-4.7.99";s:3:"php";s:11:"5.0.0-0.0.0";s:3:"cms";s:0:"";}}', 'Christophe Monard', 'contact@cmonard.fr', 'thorfin', 'bad583fce319e156aea840d0bb9ebc72', 'Added global marker cObj generation during rendering (called by insertLanguagesAndClean)\nAdded local marker cObj generation during row rendering (called by generateMarkersFromTableRow)\n', '', 2001, 0, 0),
(25367, 0, 'cmd_api', 1, '0.2.2', 132, 0, 'CMD Api', 'Collection of useful functions helping in extension development', 2, 0, 4, 1363948705, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:12:"4.3.0-4.7.99";s:3:"php";s:11:"5.0.0-0.0.0";s:3:"cms";s:0:"";}}', 'Christophe Monard', 'contact@cmonard.fr', 'thorfin', 'a74c1eae1fd5c1f98987a56fd4670d08', 'reup: small correction on the new function getGlobalMarker\nAdded global marker cObj generation during rendering (called by insertLanguagesAndClean)\nAdded local marker cObj generation during row rendering (called by generateMarkersFromTableRow)\nnever said ', '', 2002, 0, 0),
(25368, 0, 'cmd_api', 1, '0.2.3', 132, 0, 'CMD Api', 'Collection of useful functions helping in extension development', 2, 0, 4, 1370352598, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:12:"4.3.0-4.7.99";s:3:"php";s:11:"5.0.0-0.0.0";s:3:"cms";s:0:"";}}', 'Christophe Monard', 'contact@cmonard.fr', 'thorfin', '213d7bc0c8f5168cf3346b85101a5bdb', 'Sonar test corrections\n', '', 2003, 0, 0),
(25369, 0, 'cmd_api', 1, '1.0.0', 132, 0, 'CMD Api', 'Collection of useful functions helping in extension development', 2, 0, 4, 1384955436, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:12:"4.3.0-4.7.99";s:3:"php";s:11:"5.0.0-0.0.0";s:3:"cms";s:0:"";}}', 'Christophe Monard', 'contact@cmonard.fr', 'thorfin', '6cb2317a1743e0cc6fec121aa9578bc5', 'Last release before code update and cleaning for TYPO3 v6.\nCorrection on constructor compatibility func for the lib.\n', '', 1000000, 0, 0),
