(25371, 0, 'cmd_api', 1, '6.0.0', 132, 0, 'CMD Api', 'Collection of useful functions helping in extension development', 1, 0, 4, 1385121517, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:12:"6.0.0-6.2.99";s:3:"php";s:11:"5.3.7-0.0.0";s:3:"cms";s:0:"";}}', 'Christophe Monard', 'contact@cmonard.fr', 'thorfin', 'e6a84d3c534732837d050c6c14526a4c', 'WARNING : Breaking update !\nRemove compatibility with TYPO3 v4.\nUpdate php compatiblity to 5.3.7\nUpdate TYPO3 compatiblity to 6.0.0-6.2.99\nUpdate extension version to 6.0.0\nSet status back to Beta (some function need to be tested again)\nTODO: Remove decla', '', 6000000, 0, 0),
(25372, 0, 'cmd_api', 1, '6.0.1', 132, 0, 'CMD Api', 'Collection of useful functions helping in extension development', 1, 0, 4, 1391527164, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:12:"6.0.0-6.2.99";s:3:"php";s:11:"5.3.7-0.0.0";s:3:"cms";s:0:"";}}', 'Christophe Monard', 'contact@cmonard.fr', 'thorfin', '51fd322057a180ed0d2e556dd0850ada', 'Remove Deprecated function\nBugfix with pagebrowser function and some PHP version, parameter name not set correctly\nImprove quoteForLike with new arguments to improve its flexibility\nNew function to easily handle (get or set) cookie or session data in th', '', 6000001, 0, 0),
