(25375, 0, 'cmd_api', 1, '6.0.4', 132, 0, 'CMD Api', 'Collection of useful functions helping in extension development', 2, 0, 4, 1395652501, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:12:"6.0.0-6.2.99";s:3:"php";s:11:"5.3.7-0.0.0";s:3:"cms";s:0:"";}}', 'Christophe Monard', 'contact@cmonard.fr', 'thorfin', '0dc0e28dd3da558a3ff3adbbfb5e8a57', 'Added class alias map migration code\r\nBugfix on eID backend user retrieve\r\nBugfix on 6.2 version of TYPO3 for some functions\r\nChange state to stable', '', 6000004, 0, 0),
(25376, 0, 'cmd_api', 1, '6.0.5', 132, 0, 'CMD Api', 'Collection of useful functions helping in extension development', 2, 0, 4, 1405084060, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:12:"6.0.0-6.2.99";s:3:"php";s:11:"5.3.7-0.0.0";s:3:"cms";s:0:"";}}', 'Christophe Monard', 'contact@cmonard.fr', 'thorfin', '36bfc6a61717b24c8172e28b5445919a', 'Added possibility to change sort field in list mode: mod.web_list.alternateSortingField.table  field ASC/DESC\r\nAdded contentStdWrap to insertLanguagesAndClean function, simply declare contentStdWrap.xxx in your extension configuration to wrap the wole co', '', 6000005, 0, 0),
