(25431, 0, 'changepassword', 1, '0.2.0', 217, 5, 'Change front end user password', 'Change the password of the front end user in the frontend. Easy template system to configure the layout. User have to enter his old password an twice the new one.\nThe password can be stored with md5.', 1, 0, 2, 1268183123, 'a:1:{s:7:"depends";a:1:{s:7:"felogin";s:0:"";}}', 'Muhammed Alat', 'alat@bizlogix.de', 'frederic.gaus', '0c521bda5cccc252b24f3c150fe5ee2d', '', '', 2000, 0, 0),
(25432, 0, 'changepassword', 1, '0.2.1', 217, 4, 'Change front end user password', 'Change the password of the front end user in the frontend. Easy template system to configure the layout. User have to enter his old password an twice the new one.\nThe password can be stored with md5.', 1, 0, 2, 1268216808, 'a:1:{s:7:"depends";a:1:{s:7:"felogin";s:0:"";}}', 'Muhammed Alat', 'alat@bizlogix.de', 'frederic.gaus', 'aced433087f06ee9907bbed4b609e968', 'It supports plain text, md5 and saltedpasswords', '', 2001, 0, 0),
(25433, 0, 'changepassword', 1, '0.2.2', 217, 4, 'Change front end user password', 'Change the password of the front end user in the frontend. Easy template system to configure the layout. User have to enter his old password an twice the new one.\nThe password can be stored with md5.', 1, 0, 2, 1268226440, 'a:1:{s:7:"depends";a:1:{s:7:"felogin";s:0:"";}}', 'Muhammed Alat', 'alat@bizlogix.de', 'frederic.gaus', 'ebcf5812fb63312984a6acc77d130978', '- It supports plain text, md5, saltedpasswords\r\n- tested with typo3 4.3\r\n- bugfixes', '', 2002, 0, 0),
