(25442, 0, 'wortewolke', 1, '0.0.6', 173, 53, 'WorteWolke', 'With this extension the awesome cumulus tagcloud from Roy Tanck (originally made for WordPress) can be used in TYPO3. \n	The tags are rotating depending on the mouse movement. Extension made by  Rainer Schleevoigt. It is an improves version auf cumulus mad', 1, 0, 3, 1290258054, 'a:0:{}', 'Rainer Schleevoigt', 'rainer@webmasterei-hamburg.de', 'kontaktschmied', 'a2c596efd72969aadca98de9b0218f4b', '', 'Webmasterei Hamburg', 6, 0, 0),
