(25616, 0, 't3blogjquery', 1, '2.0.0', 196, 71, 't3blog: original widgets using jQuery', 'The original widgets of the t3blog extension are useing jQuery instead of Mootools now.', 2, 0, 2, 1296582033, 'a:1:{s:7:"depends";a:2:{s:3:"cms";s:0:"";s:6:"t3blog";s:0:"";}}', 'Hauke Hain, Andrey Aksenov', 'hhpreuss@googlemail.com, aksenovaa@bk.ru', 't3blogjquery', 'fc705c6cd4086fc93e2488951b17734c', 'New features and easier configuration.\r\nATTENTION: If you update an existing installation, you have to configure the extension again because of significant changes! Please read the new manual.', '', 2000000, 0, 0),
(25617, 0, 't3blogjquery', 1, '2.0.1', 196, 89, 't3blog: original widgets using jQuery', 'The original widgets of the t3blog extension are useing jQuery instead of Mootools now.', 2, 0, 2, 1307954119, 'a:1:{s:7:"depends";a:2:{s:3:"cms";s:0:"";s:6:"t3blog";s:11:"0.0.0-1.1.0";}}', 'Hauke Hain, Andrey Aksenov', 'hhpreuss@googlemail.com, aksenovaa@bk.ru', 't3blogjquery', '4fbc60ffefc8fb28230b4f685c56a2d0', 't3blog 1.1.1 is not compatible with this extension as it uses Ext JS. The JavaScript inclusion is hardcoded now and cannot switched off.\r\nHint: Use the current trunk version of t3blogjquery and the t3blog patch: http://forge.typo3.org/issues/26840', '', 2000001, 0, 0),
(25618, 0, 't3blogjquery', 1, '3.0.0', 196, 0, 'T3BLOG: original widgets using jQuery', 'The original widgets of the t3blog extension are useing jQuery instead of Ext JS now.', 5, 0, 2, 1379093372, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:6:"t3blog";s:5:"1.1.1";s:5:"typo3";s:12:"4.3.0-4.7.99";}}', 'Hauke Hain, Andrey Aksenov', 'hhpreuss@googlemail.com, aksenovaa@bk.ru', 't3blogjquery', '4ef9dc06940efac9cf8cdbfda6480094', 'Obsolete, because the extension is not being maintained anymore! (T3Blog does not support TYPO3 6.x!)\r\n\r\nLast version synced with repository (breaking change!). Works great with T3Blog on TYPO3 4.x if you change T3Blogs source code a bit. Have a look at t', '', 3000000, 0, 0),
(25619, 0, 't3blogjquery', 1, '3.0.1', 196, 0, 'T3BLOG: original widgets using jQuery', 'The original widgets of the t3blog extension are useing jQuery instead of Ext JS now.', 5, 0, 2, 1379094073, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:6:"t3blog";s:5:"1.1.1";s:5:"typo3";s:12:"4.3.0-4.7.99";}}', 'Hauke Hain, Andrey Aksenov', 'hhpreuss@googlemail.com, aksenovaa@bk.ru', 't3blogjquery', '7e4d9700a1eda51c9754377f6574859d', 'Updated manual.\r\n\r\nWarning: This extension works only after changing a few lines of source code of T3Blog.\r\nThis extension is not maintained any longer!', '', 3000001, 1, 0),
