(25737, 0, 'decospublisher', 1, '2.0.3', 125, 13, 'Decos Publisher', 'Allows importing Decos XML exports and flexibly publish their contents.', 2, 0, 3, 1300365967, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"4.4.0-4.5.99";s:3:"php";s:11:"5.2.0-0.0.0";}}', 'Frenck Lutke', 'frenck@innologi.nl', 'frenck', '7e54a2f5982a9163a8028533cd6aa129', 'Maintenance release. Please perform database update. If you had any document relation issues since 2.0.0, delete/reimport your document xmls.', 'INNOLOGI / Gemeente Heemskerk', 2000003, 0, 0),
(25738, 0, 'decospublisher', 1, '2.1.0', 125, 13, 'Decos Publisher', 'Allows importing Decos XML exports and flexibly publish their contents.', 2, 0, 3, 1301155200, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:11:"4.4.0-0.0.0";s:3:"php";s:11:"5.2.0-0.0.0";}}', 'Frenck Lutke', 'frenck@innologi.nl', 'frenck', '65e7a272e4ca6118204390368e14f4e3', 'Please execute update-script! Also: cron/cli scripts dropped; use the Scheduler-tasks instead! For more new features, see changelog in manual.', 'INNOLOGI / Gemeente Heemskerk', 2001000, 0, 0),
(25739, 0, 'decospublisher', 1, '3.0.0', 125, 19, 'Decos Publisher', 'Allows importing Decos XML exports and flexibly publish their contents.', 2, 0, 3, 1317297210, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:11:"4.5.0-0.0.0";s:3:"php";s:11:"5.2.0-0.0.0";}}', 'Frenck Lutke', 'frenck@innologi.nl', 'frenck', '7b3049d3af478f59a1192a236d6de979', 'Contentfield conditions, pdftk support & much more, see changelog. Several breaking changes, perform update scripts!', 'INNOLOGI / Gemeente Heemskerk', 3000000, 0, 0),
(25740, 0, 'decospublisher', 1, '3.1.0', 125, 0, 'Decos Publisher', 'Allows importing Decos XML exports and flexibly publish their contents.', 2, 0, 3, 1334303689, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"4.5.0-4.6.99";s:3:"php";s:11:"5.2.0-0.0.0";}}', 'Frenck Lutke', 'frenck@innologi.nl', 'frenck', 'fe378881cd4b65844a775ca1a50e2b5d', 'NEW: email on updates, feed template mode, new options. Includes some important bugfixes that require running database update and included update scripts! Also: XLIFF locallang. (T3 4.5 requires xliff ext) See changelog for full details.', 'INNOLOGI / Gemeente Heemskerk', 3001000, 0, 0),
(25741, 0, 'decospublisher', 1, '6.0.0', 125, 0, 'Decos Publisher', 'Import Decos XML exports and flexibly publish their contents.', 2, 0, 3, 1396000991, 'a:2:{s:7:"depends";a:2:{s:5:"typo3";s:12:"4.5.2-6.2.99";s:3:"php";s:11:"5.2.0-0.0.0";}s:8:"suggests";a:1:{s:5:"xliff";s:5:"1.0.1";}}', 'Frenck Lutke', 'frenck@innologi.nl', 'frenck', '385b45f50c6ce07f51c20e857cf77267', 'Raised supported TYPO3 versions to 6.2.99, fixed several bugs, bumped version to 6.0.0 due to TER-issues causing the erroneous 5.0.0 release.', 'www.innologi.nl / www.heemskerk.nl', 6000000, 0, 0),
