(25941, 0, 'fh_debug', 1, '0.3.1', 242, 25, 'Debugger', 'PHP debugger', 2, 0, 2, 1322903518, 'a:1:{s:7:"depends";a:1:{s:3:"php";s:11:"5.1.2-0.0.0";}}', 'Franz Holzinger', 'franz@ttproducts.de', 'franzholz', '3832a542a523077eaac4386e76824c97', 'bugfix: No debug output must be shown when the given IP address does not match.', 'jambage.com', 3001, 0, 0),
