(25943, 0, 'fh_debug', 1, '0.3.3', 242, 25, 'Debugger', 'PHP debugger', 2, 0, 2, 1331110849, 'a:1:{s:7:"depends";a:1:{s:3:"php";s:11:"5.1.2-0.0.0";}}', 'Franz Holzinger', 'franz@ttproducts.de', 'franzholz', 'e9837f7422f18f4da46a95812ccbf64f', 'No other IP addresses than the set one may overwrite the debug output file.', 'jambage.com', 3003, 0, 0),
(25944, 0, 'fh_debug', 1, '0.3.4', 242, 14, 'Debugger', 'PHP debugger', 2, 0, 2, 1332954688, 'a:1:{s:7:"depends";a:1:{s:3:"php";s:11:"5.1.2-0.0.0";}}', 'Franz Holzinger', 'franz@ttproducts.de', 'franzholz', '2b8728b2f4ac3948474be313c70f8408', 'Feature to enter the name of the starting PHP file which will generate debug output.\nConvert the output into UTF-8 characters.\n', 'jambage.com', 3004, 0, 0),
