(25946, 0, 'fh_debug', 1, '0.3.6', 242, 0, 'Debugger', 'PHP debugger', 2, 0, 2, 1369663898, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:12:"5.2.5-5.3.99";s:5:"typo3";s:10:"4.3-6.0.99";}}', 'Franz Holzinger', 'franz@ttproducts.de', 'franzholz', 'b3fe78f06670d9ae34c83b5f7f9f5682', '\n new feature: an error_log file can be used instead of the debug output file\n bug fix: the ip address mask  must allow all ip addresses even the empty one\n', 'jambage.com', 3006, 0, 0),
(25947, 0, 'fh_debug', 1, '0.4.0', 242, 0, 'Debugger', 'PHP debugger', 2, 0, 2, 1385060311, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:12:"5.3.0-5.4.99";s:5:"typo3";s:12:"6.0.0-6.2.99";}}', 'Franz Holzinger', 'franz@ttproducts.de', 'franzholz', '32cae44c75b79cec6039df78d002c6ba', '\nruns with TYPO3 6.2\n', 'jambage.com', 4000, 0, 0),
(25948, 0, 'fh_debug', 1, '0.5.0', 242, 0, 'Debugger', 'PHP debugger', 2, 0, 4, 1395305549, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:12:"5.3.0-5.4.99";s:5:"typo3";s:12:"6.0.0-6.2.99";}}', 'Franz Holzinger', 'franz@ttproducts.de', 'franzholz', '0a4d140cebcdf02dacd1dc07095a2c80', '\n remove GlobalDebugFunctions and DebugFunctions from the trace\n new feature: debug the devLog\nUse fh_debug to display the devLog output.\n Write into the debug file and an error_log file simulatneously.\n', 'jambage.com', 5000, 0, 0),
(25949, 0, 'fh_debug', 1, '0.5.1', 242, 0, 'Debug and Devlog', 'PHP debugger and devLog Logger', 2, 0, 4, 1407412235, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:12:"5.3.0-5.4.99";s:5:"typo3";s:12:"6.0.0-6.2.99";}}', 'Franz Holzinger', 'franz@ttproducts.de', 'franzholz', '98a285802e5b7dec380d6983168ed73d', '  \nBug fix for debug depth. HTML class for the contents of an array.\n', 'jambage.com', 5001, 0, 0),
(25950, 0, 'fh_debug', 1, '0.5.2', 242, 0, 'Debug and Devlog', 'PHP debugger and devLog Logger', 2, 0, 4, 1412759251, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:12:"5.3.0-5.5.99";s:5:"typo3";s:12:"6.0.0-6.2.99";}}', 'Franz Holzinger', 'franz@ttproducts.de', 'franzholz', 'c856e49bcbb0ea931bb482fd580e9b71', '  \nNew features for the Frontend Debugging: \nShow the private and protected member variables of objects. \nExclude some variable names and array or object members from the debug output.\n', 'jambage.com', 5002, 0, 0),
(25951, 0, 'fh_debug', 1, '0.5.3', 242, 0, 'Debug and Devlog', 'PHP debugger and devLog Logger', 2, 0, 4, 1437763238, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:12:"5.3.0-5.6.99";s:5:"typo3";s:12:"6.0.0-7.4.99";}}', 'Franz Holzinger', 'franz@ttproducts.de', 'franzholz', '43d3a6ee5f58469189a461571f1da858', '  \ntested under TYPO3 7.4.0 alpha\n', 'jambage.com', 5003, 0, 0),
(25952, 0, 'fh_debug', 1, '0.5.4', 242, 0, 'Debug and Devlog', 'PHP debugger and devLog Logger', 2, 0, 4, 1464853277, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:13:"5.3.0-7.99.99";s:5:"typo3";s:13:"6.0.0-7.99.99";}}', 'Franz Holzinger', 'franz@ttproducts.de', 'franzholz', '1eb78e0301c375cd5b1479008706695f', '  \nBugfix to also show an array with empty keys. Show the types boolean, integer and float. Support for PHP 7.x and TYPO3 7.x. Add a header for arrays.\n', 'jambage.com', 5004, 0, 0),
