(25954, 0, 'fh_debug', 1, '0.5.6', 242, 0, 'Debug and Devlog', 'PHP debugger and devLog Logger', 2, 0, 4, 1484655750, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:13:"5.3.0-7.99.99";s:5:"typo3";s:13:"6.0.0-7.99.99";}}', 'Franz Holzinger', 'franz@ttproducts.de', 'franzholz', 'e52b7660e80e3a314dec9f93af0f3250', '  \nNo HTML output for the exception "oops, an error occurred".\nSupport for Deutsche Bahn WLAN\ndebug sys_log without a need for debugBegin and debugEnd\n', 'jambage.com', 5006, 0, 0),
