(26008, 0, 'ods_osm_search', 1, '0.2.0', 46, 41, 'Openstreetmap radial search', 'Search tt_address records in a given radius (german "Umkreissuche").', 0, 0, 2, 1275592769, 'a:1:{s:7:"depends";a:1:{s:7:"ods_osm";s:6:"1.3.0-";}}', 'Robert Heel', 'rheel@1drop.de', 'bobosch', '8d00658950fb6b69ca1f8e5a24bf9817', '	 Add: Extension icon.\r\n	 Bugfix: Show dropdown only on list types.\r\n	 Change: Use address cache of ods_osm.\r\n	 Change: Configure corresponding map in plugin configuration. \r\n', 'http://www.1drop.de/', 2000, 0, 0),
(26009, 0, 'ods_osm_search', 1, '1.0.0', 46, 0, 'Openstreetmap radial search', 'Search tt_address records in a given radius (german "Umkreissuche").', 1, 0, 2, 1372966118, 'a:1:{s:7:"depends";a:1:{s:7:"ods_osm";s:6:"1.3.0-";}}', 'Robert Heel', 'typo3@bobosch.de', 'bobosch', '65bc3a84300d4dbb41f729e51c68f162', '	 Change: Search in all tt_address records if no Record Storage Page is set.\n	 Bugfix: Show also addresses with the same coordinates as the searched address.\n	 Add: TS option "standard_on_none_found"\n	 Add: TS option "limit"\n	 Add: TS option "un', '', 1000000, 0, 0),
(26010, 0, 'ods_osm_search', 1, '1.1.0', 46, 0, 'Openstreetmap radial search', 'Search tt_address records in a given radius (german "Umkreissuche").', 1, 0, 2, 1373058178, 'a:1:{s:7:"depends";a:2:{s:7:"ods_osm";s:6:"1.3.0-";s:5:"typo3";s:11:"4.5.0-9.9.9";}}', 'Robert Heel', 'typo3@bobosch.de', 'bobosch', '593608fefbff953a16c6615f23128665', '	 Change: Move form tag into html template.\n	 Add: TS option "pid" to configure page id.', '', 1001000, 0, 0),
(26011, 0, 'ods_osm_search', 1, '1.1.1', 46, 0, 'Openstreetmap radial search', 'Search tt_address records in a given radius (german "Umkreissuche").', 1, 0, 2, 1373397408, 'a:1:{s:7:"depends";a:2:{s:7:"ods_osm";s:6:"1.3.0-";s:5:"typo3";s:11:"4.5.0-9.9.9";}}', 'Robert Heel', 'typo3@bobosch.de', 'bobosch', 'a6a1a97e282a65a3cb7ba2355306d222', '	 Bugfix: Dont cache page when searching.', '', 1001001, 0, 0),
(26012, 0, 'ods_osm_search', 1, '1.2.0', 46, 0, 'Openstreetmap radial search', 'Search tt_address records in a given radius (german "Umkreissuche").', 1, 0, 2, 1397375827, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:12:"4.5.0-6.2.99";s:7:"ods_osm";s:6:"1.3.0-";s:18:"static_info_tables";s:0:"";}}', 'Robert Heel', 'typo3@bobosch.de', 'bobosch', '1f55c1f62f50418cb174f8d9434644be', '	 Change: TS option "country" to add a country selection dropdown (also uncomment select field in template).\r\n	 Change: Use static_info_tables for distance number format.\r\n', '', 1002000, 0, 0),
(26013, 0, 'ods_osm_search', 1, '2.0.0', 46, 0, 'OpenStreetMap radial search', 'Search tt_address records in a given radius (german "Umkreissuche").', 1, 0, 2, 1499805080, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:13:"6.2.0-8.99.99";s:7:"ods_osm";s:6:"2.0.0-";s:18:"static_info_tables";s:0:"";}}', 'Robert Heel', 'typo3@bobosch.de', 'bobosch', 'b68186532aa8821df565cdf140374763', '	 Bugfix: Compatibility to TYPO3 8.x.\r\n	 Update: README.\r\n', '', 2000000, 1, 0),
(26014, 0, 'ods_html5_media', 1, '0.1.0', 418, 6, 'HTML5 Media tags', 'Use HTML5 video and audio tags in the media element.', 0, 0, 2, 1274209495, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:11:"4.3.0-0.0.0";}}', 'Robert Heel', 'rheel@1drop.de', 'bobosch', '0fd2f7444d74937519f15ac2dc617081', 'Initial release.', 'http://www.1drop.de/', 1000, 0, 0),
(26015, 0, 'ods_html5_media', 1, '0.2.0', 418, 5, 'HTML5 Media tags', 'Use HTML5 video and audio tags in the media element.', 0, 0, 2, 1274292966, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:11:"4.3.0-0.0.0";}}', 'Robert Heel', 'rheel@1drop.de', 'bobosch', 'b2b9d5a7985917c278c66a9c735d46be', '	 Add: autoPlay and loop option.\r\n	 Add: Search all files with the same basename in the current directory.\r\n	 Add: absRefPrefix.\r\n	 Add: Extension icon.\r\n', 'http://www.1drop.de/', 2000, 0, 0),
(26016, 0, 'ods_html5_media', 1, '0.3.0', 418, 4, 'HTML5 Media tags', 'Use HTML5 video and audio tags in the media element.', 0, 0, 2, 1274769970, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:11:"4.3.0-0.0.0";}}', 'Robert Heel', 'rheel@1drop.de', 'bobosch', 'f8340f7b5d5146a143c10e6ad07fa0f6', '	 Add: Get codec information with ffmpeg.\r\n', 'http://www.1drop.de/', 3000, 0, 0),
(26017, 0, 'ods_html5_media', 1, '0.4.0', 418, 13, 'HTML5 Media tags', 'Use HTML5 video and audio tags in the media element.', 0, 0, 2, 1274893281, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:11:"4.3.0-0.0.0";}}', 'Robert Heel', 'rheel@1drop.de', 'bobosch', 'de72f9de74c553ac51b974fa081b7bb9', '	 Bugfix: Correct codec declaration.\r\n	 Add: Mime Type identification.\r\n	 Add: Experimental video conversion with ffmpeg. Only use it if you know what youre doing. Feedback is welcome.\r\n', 'http://www.1drop.de/', 4000, 0, 0),
(26018, 0, 'ods_html5_media', 1, '0.5.0', 418, 14, 'HTML5 Media tags', 'Use HTML5 video and audio tags in the media element.', 0, 0, 2, 1289519115, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:11:"4.3.0-0.0.0";}}', 'Robert Heel', 'rheel@1drop.de', 'bobosch', '1d4f89df19a0cabca7ec7827f0c7e11b', '	 Add: Automatic "Render Type" selection on file extensions mkv, oga, ogg, ogv, spx and webm.\r\n	 Change: Move TS options and mime type configuration to tt_content.media.20.\r\n	 Add: Manual.\r\n', 'http://www.1drop.de/', 5000, 0, 0),
(26019, 0, 'ods_html5_media', 1, '0.5.1', 418, 20, 'HTML5 Media tags', 'Use HTML5 video and audio tags in the media element. Allows automatic encoding of video files into different formats using ffmpeg (experimental).', 1, 0, 2, 1293798170, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:11:"4.3.0-0.0.0";}}', 'Robert Heel', 'rheel@1drop.de', 'bobosch', '0ebc1f76b7a270277125c280f2cefaa9', '	 Bufix: Correct handling of files with special characters.\r\n	 Bufix: Add previously encoded file to file list.\r\n	 Change: Use shell_exec instead of exec.\r\n', 'http://www.1drop.de/', 5001, 0, 0),
(26020, 0, 'ods_html5_media', 1, '0.5.2', 418, 43, 'HTML5 Media tags', 'Use HTML5 video and audio tags in the media element. Allows automatic encoding of video files into different formats using ffmpeg (experimental).', 1, 0, 2, 1294247875, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:11:"4.3.0-0.0.0";}}', 'Robert Heel', 'rheel@1drop.de', 'bobosch', '665c763a2d484ad6573372e1b0150db3', '	 Bugfix: Add additional file extensions to media file wizard.\r\n', 'http://www.1drop.de/', 5002, 0, 0),
(26021, 0, 'ods_html5_media', 1, '0.5.3', 418, 229, 'HTML5 Media tags', 'Use HTML5 video and audio tags in the media element. Allows automatic encoding of video files into different formats using ffmpeg (experimental).', 1, 0, 2, 1298571249, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:11:"4.3.0-0.0.0";}}', 'Robert Heel', 'rheel@1drop.de', 'bobosch', '825dc20e3d3661011d9d55f04dfade32', '	 Fixed bug 13243: Width and height will not appear in the video-tag and erases every video-attribute (Thanks to Jochen Overwien).\r\n	 Fixed bug 13244: Alternative content will be ignored.\r\n', 'http://www.1drop.de/', 5003, 0, 0),
(26022, 0, 'ods_html5_media', 1, '0.6.0', 418, 20, 'HTML5 Media tags', 'Use HTML5 video and audio tags in the media element. Allows automatic encoding of video files into different formats using ffmpeg (experimental).', 1, 0, 2, 1327273942, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:11:"4.3.0-0.0.0";}}', 'Robert Heel', 'rheel@1drop.de', 'bobosch', '9a0ba6d6a960929d26285e1498974c11', '	 Add: Preview image.\r\n	 Change: Build html5 element with DOMDocument.\r\n	 Add hook 31945: Hook to customize output.\r\n', 'http://www.1drop.de/', 6000, 0, 0),
(26023, 0, 'ods_html5_media', 1, '0.7.0', 418, 64, 'HTML5 Media tags', 'Use HTML5 video and audio tags in the media element. Allows automatic encoding of video files into different formats using ffmpeg (experimental).', 1, 0, 2, 1328864994, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:11:"4.3.0-0.0.0";}}', 'Robert Heel', 'rheel@1drop.de', 'bobosch', 'b9e8c5c97989dc2d09526ef6c7a4f316', '	 Bugfix: Avoid PHP warnings if some attributes are not set (Thanks to Bart Dubelaar).\r\n	 Change: Move TS to static templates (Thanks to Bart Dubelaar).\r\n	 Change: Improve regex for codec recognition (Thanks to Bart Dubelaar).\r\n	 Change: Add suggestio', 'http://www.1drop.de/', 7000, 0, 0),
(26024, 0, 'ods_html5_media', 1, '0.7.1', 418, 0, 'HTML5 Media tags', 'Use HTML5 video and audio tags in the media element. Allows automatic encoding of video files into different formats using ffmpeg (experimental).', 1, 0, 2, 1344354238, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:11:"4.3.0-0.0.0";}}', 'Robert Heel', 'rheel@1drop.de', 'bobosch', '17c375ef2000e450eef1bb5d5f20e724', '	 Feature 36119: Set "Hide controls when not over the video" to hide controls.\n	 Bugfix: Compatibility to TYPO3 4.7.\n', 'http://www.1drop.de/', 7001, 1, 0),
