(26345, 0, 'backend_login_news', 1, '0.0.2', 79, 5, 'Backend Login News', 'Show News from a RSS Feed below the backend login. With "Backend Login News" you  fetch the news from a RSS feed und cache the imtes on the server. This extenion is no import extension!', 1, 0, 0, 1277470101, 'a:1:{s:7:"depends";a:1:{s:11:"rss2_import";s:0:"";}}', 'Tim Lochmueller', 'webmaster@fruit-lab.de', 'abandoned_extensions', 'a6954173caddc81b616c0bfd17b87e98', 'First Version. Check it out. Yeah....', '', 2, 0, 0),
(26346, 0, 'backend_login_news', 1, '0.0.3', 79, 4, 'Backend Login News', 'Show News from a RSS Feed below the backend login. With "Backend Login News" you  fetch the news from a RSS feed und cache the imtes on the server. This extenion is no import extension!', 1, 0, 0, 1277472469, 'a:1:{s:7:"depends";a:3:{s:11:"rss2_import";s:0:"";s:3:"php";s:12:"5.0.0-5.3.99";s:5:"typo3";s:12:"4.3.0-4.4.99";}}', 'Tim Lochmueller', 'webmaster@fruit-lab.de', 'abandoned_extensions', '2acfe47242105f4578949836842b6325', 'array-implode bugfix for the installation. And extension dependencies for php & TYPO3.', '', 3, 0, 0),
