(26348, 0, 'backend_login_news', 1, '0.0.5', 79, 20, 'Backend Login News', 'Show News from a RSS Feed below the backend login. With "Backend Login News" you  fetch the news from a RSS feed und cache the imtes on the server. This extenion is no import extension!', 1, 0, 0, 1281440276, 'a:1:{s:7:"depends";a:3:{s:11:"rss2_import";s:0:"";s:3:"php";s:12:"5.0.0-5.3.99";s:5:"typo3";s:12:"4.3.0-4.4.99";}}', 'Tim Lochmueller', 'webmaster@fruit-lab.de', 'abandoned_extensions', '30da37a7dc7426579abd8eb9bfcd02e7', 'Remove HTML from RSS Feed description. Same feeds have large images and the images destroy the layout of the backend login.', '', 5, 0, 0),
