(26513, 0, 'karussell', 1, '0.1.7', 676, 25, 'Karussell: based on jCarousel', 'This extension is based on the JavaScript plugin "jQuery Carousel" by Jan Sorgalla. It allows you to display any content on a carousel.', 1, 0, 3, 1279122263, 'a:1:{s:7:"depends";a:1:{s:8:"t3jquery";s:0:"";}}', 'Kurt Gusbeth', 'info@myquizandpoll.de', 'bihor', 'fb9a9738920a8f743c61230897eefc64', 'First upload to TER.', '', 1007, 0, 0),
