INSERT INTO `tx_extensionmanager_domain_model_extension` (`uid`, `pid`, `extension_key`, `repository`, `version`, `alldownloadcounter`, `downloadcounter`, `title`, `description`, `state`, `review_state`, `category`, `last_updated`, `serialized_dependencies`, `author_name`, `author_email`, `ownerusername`, `md5hash`, `update_comment`, `authorcompany`, `integer_version`, `current_version`, `lastreviewedversion`) VALUES
(26517, 0, 'karussell', 1, '0.4.0', 676, 195, 'Karussell: based on jCarousel', 'This extension is based on the JavaScript plugin "jQuery Carousel" by Jan Sorgalla. It allows you to display any content on a carousel.', 2, 0, 3, 1297009879, 'a:1:{s:7:"depends";a:1:{s:8:"t3jquery";s:0:"";}}', 'Kurt Gusbeth', 'info@myquizandpoll.de', 'bihor', '2c04b654c963eaeb9d0099990fa1e665', 'You can now display thumbnails too.', '', 4000, 0, 0),
(26518, 0, 'karussell', 1, '0.5.0', 676, 104, 'Karussell: based on jCarousel', 'This extension is based on the JS plugin "jQuery Carousel (jCarousel)". It allows you to display any content on a carousel, even with other JS plugins.', 2, 0, 3, 1311882357, 'a:1:{s:7:"depends";a:1:{s:8:"t3jquery";s:0:"";}}', 'Kurt Gusbeth', 'info@myquizandpoll.de', 'bihor', 'c68755e4f1e829d9c9110a3e0b42b644', 'More examples added. More select possibilities.', '', 5000, 0, 0),
(26519, 0, 'karussell', 1, '0.5.2', 676, 53, 'Karussell: based on jCarousel', 'This extension is based on the JS plugin "jQuery Carousel (jCarousel)". It allows you to display any content on a carousel, even with other JS plugins.', 2, 0, 3, 1318000725, 'a:1:{s:7:"depends";a:1:{s:8:"t3jquery";s:0:"";}}', 'Kurt Gusbeth', 'info@myquizandpoll.de', 'bihor', '255c7be49acff3e35bfa1b3a50f4d425', 'New example and small bugfix.', '', 5002, 0, 0),
(26520, 0, 'karussell', 1, '0.6.0', 676, 55, 'Karussell: based on jCarousel', 'This extension is based on the JS plugin "jQuery Carousel (jCarousel)". It allows you to display any content on a carousel, even with other JS plugins.', 2, 0, 3, 1323808150, 'a:1:{s:7:"depends";a:1:{s:8:"t3jquery";s:0:"";}}', 'Kurt Gusbeth', 'info@myquizandpoll.de', 'bihor', 'b569f23123eae2a493b7adda42ee0547', 'New examples. Deprecated functions replaced. New debug method.', '', 6000, 0, 0),
(26521, 0, 'karussell', 1, '0.6.3', 676, 63, 'Karussell: based on jCarousel', 'This flexible extension is based on the JS plugin "jQuery Carousel (jCarousel)". It allows you to display any content on a carousel, even with other JS plugins.', 2, 0, 3, 1329075898, 'a:1:{s:7:"depends";a:1:{s:8:"t3jquery";s:0:"";}}', 'Kurt Gusbeth', 'info@myquizandpoll.de', 'bihor', '50fe2d3c3d3f315be3a96fe767f8c87c', '2 bugs fixed. 2 examples added.', '', 6003, 0, 0),
(26522, 0, 'karussell', 1, '0.7.0', 676, 0, 'Karussell: based on jCarousel', 'This flexible extension is based on the JS plugin "jQuery Carousel (jCarousel)". It allows you to display any content on a carousel, even with other JS plugins.', 2, 0, 3, 1336406912, 'a:1:{s:7:"depends";a:1:{s:8:"t3jquery";s:0:"";}}', 'Kurt Gusbeth', 'info@myquizandpoll.de', 'bihor', 'e69db1185ceca31b36cc79cd43e2ef42', 'Random and crop possibility added.\r\nDeprecated methods replaced.\r\nLink generation improved.', '', 7000, 0, 0),
(26523, 0, 'karussell', 1, '1.0.0', 676, 0, 'Karussell: based on jCarousel', 'This flexible extension is based on the JS plugin "jQuery Carousel (jCarousel)". It allows you to display any content on a carousel, even with other JS plugins.', 2, 0, 3, 1350398387, 'a:1:{s:7:"depends";a:1:{s:8:"t3jquery";s:0:"";}}', 'Kurt Gusbeth', 'info@myquizandpoll.de', 'bihor', 'e203201bcd3bb0b27069f9fa9a4ec3b7', 'New features and examples (works now with more other JS-plugins).\nSome default properties changed!\nSee changelog in the manual.', '', 1000000, 0, 0),
(26524, 0, 'karussell', 1, '1.1.0', 676, 0, 'Karussell: a flexible jQuery carousel', 'This extension is based on the JS plugin "jQuery Carousel (jCarousel)". It allows you to display any content on a carousel, even with other JS plugins like Barousel, Scrollable, Roundabout, Galleryview, Bootstrap and others.', 2, 0, 3, 1359662334, 'a:0:{}', 'Kurt Gusbeth', 'info@myquizandpoll.de', 'bihor', 'fef3ba884a7fac9c2efb7edf48791704', 'New examples added and security improvement. Security notice added.', '', 1001000, 0, 0),
