(26573, 0, 'image_autoresize', 1, '0.5.0', 713, 5, 'Resize images automatically', 'This extension allows you to automatically resize down huge pictures uploaded by your editors.', 1, 0, 0, 1280225383, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"5.2.0-0.0.0";s:5:"typo3";s:11:"4.3.0-0.0.0";}}', 'Xavier Perseguers', 'typo3@perseguers.ch', 'xperseguers', '458d5dc7cad7eeb3371d11f0b7bfd29a', 'Initial release', '', 5000, 0, 0),
