(26576, 0, 'image_autoresize', 1, '1.1.0', 713, 225, 'Resize images automatically', 'This extension allows you to automatically resize down huge pictures uploaded by your editors.', 2, 0, 0, 1320684182, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"5.2.0-0.0.0";s:5:"typo3";s:12:"4.3.0-4.6.99";}}', 'Xavier Perseguers', 'xavier@causal.ch', 'xperseguers', 'c858fbff55c83018be6e18f3f727cef2', 'Fix compatibility issue with TYPO3 4.6.', 'Causal Srl', 1001000, 0, 0),
(26577, 0, 'image_autoresize', 1, '1.1.1', 713, 87, 'Resize images automatically', 'This extension allows you to automatically resize down huge pictures uploaded by your editors.', 2, 0, 0, 1332067946, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"5.2.0-0.0.0";s:5:"typo3";s:12:"4.3.0-4.6.99";}}', 'Xavier Perseguers', 'xavier@causal.ch', 'xperseguers', '6b83ae6d97d7687f60ea3f1d530d6abb', 'No CSS styles loaded when using configuration module in TYPO3 4.5.', 'Causal Srl', 1001001, 0, 0),
(26578, 0, 'image_autoresize', 1, '1.2.0', 713, 0, 'Resize images automatically', 'This extension allows you to automatically resize down huge pictures uploaded by your editors.', 2, 0, 0, 1348488284, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"5.2.0-0.0.0";s:5:"typo3";s:12:"4.3.0-4.7.99";}}', 'Xavier Perseguers', 'xavier@causal.ch', 'xperseguers', '7a86c99b511e64864f3368003197b6e2', 'DAM is finally fully supported with TYPO3 4.5 and up.', 'Causal Srl', 1002000, 0, 0),
(26579, 0, 'image_autoresize', 1, '1.3.0', 713, 0, 'Resize images automatically', 'This extension allows you to automatically resize down huge pictures uploaded by your editors.', 2, 0, 0, 1363542471, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"5.3.0-0.0.0";s:5:"typo3";s:12:"4.5.0-6.0.99";}}', 'Xavier Perseguers', 'xavier@causal.ch', 'xperseguers', '8f53a243701e1312158e5edfe6b74d91', 'Compatibility with TYPO3 6.0 and FAL. Long awaited feature to auto-rotate pictures with GraphicsMagick has been implemented.\n\nBeware: PHP 5.3 required even in TYPO3 4.5 LTS.', 'Causal Srl', 1003000, 0, 0),
(26580, 0, 'image_autoresize', 1, '1.3.1', 713, 0, 'Resize images automatically', 'This extension allows you to automatically resize down huge pictures uploaded by your editors.', 2, 0, 0, 1364918361, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"5.3.0-0.0.0";s:5:"typo3";s:12:"4.5.0-6.0.99";}}', 'Xavier Perseguers', 'xavier@causal.ch', 'xperseguers', '48fd41422cee92e42975b75e32e840b7', 'Configuration in TYPO3 6.0 could sometimes not be properly saved.\n\nAuto-rotate pictures now works with both ImageMagicks and GraphicsMagick.\n\nBeware: PHP 5.3 required even in TYPO3 4.5 LTS.', 'Causal Srl', 1003001, 0, 0),
(26581, 0, 'image_autoresize', 1, '1.3.2', 713, 0, 'Resize images automatically', 'This extension allows you to automatically resize down huge pictures uploaded by your editors.', 2, 0, 0, 1367501281, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"5.3.0-0.0.0";s:5:"typo3";s:12:"4.5.0-6.1.99";}}', 'Xavier Perseguers', 'xavier@causal.ch', 'xperseguers', 'fc71dfcb912f4a33428e45153510e40a', 'Checked compatibility with TYPO3 6.1.', 'Causal Srl', 1003002, 0, 0),
(26582, 0, 'image_autoresize', 1, '1.4.0', 713, 0, 'Resize images automatically', 'Simplify the way your editors may upload their pictures: no complex local procedure needed, let TYPO3 resize down their huge pictures on-the-fly during upload (or using a scheduler task for batch processing) and according to your own business rules (directory/groups).', 2, 0, 0, 1387616014, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:12:"5.3.3-5.5.99";s:5:"typo3";s:12:"4.5.0-6.2.99";}}', 'Xavier Perseguers (Causal)', 'xavier@causal.ch', 'xperseguers', '8025c7e72b02b8163975379c6f2c7bd2', 'Batch resize images using scheduler task (e.g., useful if uploaded via FTP).\nEXIF/IPTC extractor for FAL.\nCompatibility with TYPO3 6.2.\nDetails on http://forge.typo3.org/projects/extension-image_autoresize/wiki/IMAGE_AUTORESIZE_140', 'Causal Srl', 1004000, 0, 0),
(26583, 0, 'image_autoresize', 1, '1.5.0', 713, 0, 'Resize images automatically', 'Simplify the way your editors may upload their images: no complex local procedure needed, let TYPO3 automatically resize down their huge images/pictures on-the-fly during upload (or using a scheduler task for batch processing) and according to your own business rules (directory/groups). This will highly reduce the footprint on your server and speed-up response time if lots of images are rendered (e.g., in a gallery). Features an EXIF/IPTC extractor to ensure metadata may be used by the FAL indexer even if not preserved upon resizing.', 2, 0, 0, 1394986401, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:12:"5.3.3-5.5.99";s:5:"typo3";s:12:"4.5.0-6.2.99";}}', 'Xavier Perseguers (Causal)', 'xavier@causal.ch', 'xperseguers', '5e5ad50023389e8a694afbc36e9b5771', 'Tight integration with TYPO3 6.2 LTS.\nTransparently available for Frontend upload (if done properly).\nDetails on http://forge.typo3.org/projects/extension-image_autoresize/wiki/IMAGE_AUTORESIZE_150', 'Causal Srl', 1005000, 0, 0),
(26584, 0, 'image_autoresize', 1, '1.6.0', 713, 0, 'Resize images automatically', 'Simplify the way your editors may upload their images: no complex local procedure needed, let TYPO3 automatically resize down their huge images/pictures on-the-fly during upload (or using a scheduler task for batch processing) and according to your own business rules (directory/groups). This will highly reduce the footprint on your server and speed-up response time if lots of images are rendered (e.g., in a gallery). Features an EXIF/IPTC extractor to ensure metadata may be used by the FAL indexer even if not preserved upon resizing.', 2, 0, 0, 1417293075, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:12:"5.3.3-5.6.99";s:5:"typo3";s:13:"6.2.0-7.99.99";}}', 'Xavier Perseguers (Causal)', 'xavier@causal.ch', 'xperseguers', 'a6ceea6eb8bc283edb48f6ef845f2218', 'Compatibility with TYPO3 6.2-7.x. If you need support for TYPO3 4.5-6.1, please use version 1.5 instead.\nDetails on http://forge.typo3.org/projects/extension-image_autoresize/wiki/IMAGE_AUTORESIZE_160', 'Causal Srl', 1006000, 0, 0),
(26585, 0, 'image_autoresize', 1, '1.6.1', 713, 0, 'Resize images automatically', 'Simplify the way your editors may upload their images: no complex local procedure needed, let TYPO3 automatically resize down their huge images/pictures on-the-fly during upload (or using a scheduler task for batch processing) and according to your own business rules (directory/groups). This will highly reduce the footprint on your server and speed-up response time if lots of images are rendered (e.g., in a gallery). Features an EXIF/IPTC extractor to ensure metadata may be used by the FAL indexer even if not preserved upon resizing.', 2, 0, 0, 1431522424, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:12:"5.3.3-5.6.99";s:5:"typo3";s:13:"6.2.0-7.99.99";}}', 'Xavier Perseguers (Causal)', 'xavier@causal.ch', 'xperseguers', '38525851d7bfb75e9482899adf50aceb', 'Compatibility with TYPO3 7.2 and 7.3-dev.', 'Causal Srl', 1006001, 0, 0),
(26586, 0, 'image_autoresize', 1, '1.6.2', 713, 0, 'Resize images automatically', 'Simplify the way your editors may upload their images: no complex local procedure needed, let TYPO3 automatically resize down their huge images/pictures on-the-fly during upload (or using a scheduler task for batch processing) and according to your own business rules (directory/groups). This will highly reduce the footprint on your server and speed-up response time if lots of images are rendered (e.g., in a gallery). Features an EXIF/IPTC extractor to ensure metadata may be used by the FAL indexer even if not preserved upon resizing.', 2, 0, 0, 1437810409, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:12:"5.3.3-5.6.99";s:5:"typo3";s:13:"6.2.0-7.99.99";}}', 'Xavier Perseguers (Causal)', 'xavier@causal.ch', 'xperseguers', 'daf6e604a98a7ad140fccda85b41eedd', 'Support for modal upload replace dialog introduced by TYPO3 7.4.\nDetails on http://forge.typo3.org/projects/extension-image_autoresize/wiki/IMAGE_AUTORESIZE_162', 'Causal Srl', 1006002, 0, 0),
(26587, 0, 'image_autoresize', 1, '1.6.3', 713, 0, 'Resize images automatically', 'Simplify the way your editors may upload their images: no complex local procedure needed, let TYPO3 automatically resize down their huge images/pictures on-the-fly during upload (or using a scheduler task for batch processing) and according to your own business rules (directory/groups). This will highly reduce the footprint on your server and speed-up response time if lots of images are rendered (e.g., in a gallery). Features an EXIF/IPTC extractor to ensure metadata may be used by the FAL indexer even if not preserved upon resizing.', 2, 0, 0, 1438603716, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:12:"5.3.3-5.6.99";s:5:"typo3";s:13:"6.2.0-7.99.99";}}', 'Xavier Perseguers (Causal)', 'xavier@causal.ch', 'xperseguers', 'b7176045e70212e5eb647ee7ef10df58', 'Support for modal upload replace dialog introduced (and changed afterwards) by TYPO3 7.4.\nDetails on http://forge.typo3.org/projects/extension-image_autoresize/wiki/IMAGE_AUTORESIZE_163', 'Causal Srl', 1006003, 0, 0),
(26588, 0, 'image_autoresize', 1, '1.6.4', 713, 0, 'Resize images automatically', 'Simplify the way your editors may upload their images: no complex local procedure needed, let TYPO3 automatically resize down their huge images/pictures on-the-fly during upload (or using a scheduler task for batch processing) and according to your own business rules (directory/groups). This will highly reduce the footprint on your server and speed-up response time if lots of images are rendered (e.g., in a gallery). Features an EXIF/IPTC extractor to ensure metadata may be used by the FAL indexer even if not preserved upon resizing.', 2, 0, 0, 1445026362, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:12:"5.3.3-5.6.99";s:5:"typo3";s:13:"6.2.0-7.99.99";}}', 'Xavier Perseguers (Causal)', 'xavier@causal.ch', 'xperseguers', '7f4e77011d74fe02961b0752194f12b5', 'Configuration module is now using a standalone FormEngine (1st extension doing that), making it compatible with TYPO3 7.5 and new toolbar UI for 7.6.\nDetails on https://forge.typo3.org/projects/extension-image_autoresize/wiki/IMAGE_AUTORESIZE_164', 'Causal Srl', 1006004, 0, 0),
(26589, 0, 'image_autoresize', 1, '1.6.5', 713, 0, 'Resize images automatically', 'Simplify the way your editors may upload their images: no complex local procedure needed, let TYPO3 automatically resize down their huge images/pictures on-the-fly during upload (or using a scheduler task for batch processing) and according to your own business rules (directory/groups). This will highly reduce the footprint on your server and speed-up response time if lots of images are rendered (e.g., in a gallery). Features an EXIF/IPTC extractor to ensure metadata may be used by the FAL indexer even if not preserved upon resizing.', 2, 0, 0, 1447168411, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:12:"5.3.3-5.6.99";s:5:"typo3";s:13:"6.2.0-7.99.99";}}', 'Xavier Perseguers (Causal)', 'xavier@causal.ch', 'xperseguers', '4c887837aca479868f3d5655fe935cb5', 'Last bits of fine-tuning to be ready for TYPO3 7 LTS.\nDetails on https://forge.typo3.org/projects/extension-image_autoresize/wiki/IMAGE_AUTORESIZE_165', 'Causal Srl', 1006005, 0, 0),
(26590, 0, 'image_autoresize', 1, '1.6.6', 713, 0, 'Resize images automatically', 'Simplify the way your editors may upload their images: no complex local procedure needed, let TYPO3 automatically resize down their huge images/pictures on-the-fly during upload (or using a scheduler task for batch processing) and according to your own business rules (directory/groups). This will highly reduce the footprint on your server and speed-up response time if lots of images are rendered (e.g., in a gallery). Features an EXIF/IPTC extractor to ensure metadata may be used by the FAL indexer even if not preserved upon resizing.', 2, 0, 0, 1447251342, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:12:"5.3.3-5.6.99";s:5:"typo3";s:13:"6.2.0-7.99.99";}}', 'Xavier Perseguers (Causal)', 'xavier@causal.ch', 'xperseguers', 'dfe31af60e6d6ceea43025a2dd5f566d', 'Bug fix in TYPO3 v7. Resize process was triggered when FAL processes files and not only after upload.\nDetails on https://forge.typo3.org/projects/extension-image_autoresize/wiki/IMAGE_AUTORESIZE_166', 'Causal Srl', 1006006, 0, 0),
(26591, 0, 'image_autoresize', 1, '1.6.7', 713, 0, 'Resize images automatically', 'Simplify the way your editors may upload their images: no complex local procedure needed, let TYPO3 automatically resize down their huge images/pictures on-the-fly during upload (or using a scheduler task for batch processing) and according to your own business rules (directory/groups). This will highly reduce the footprint on your server and speed-up response time if lots of images are rendered (e.g., in a gallery). Features an EXIF/IPTC extractor to ensure metadata may be used by the FAL indexer even if not preserved upon resizing.', 2, 0, 0, 1449139206, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:12:"5.3.3-5.6.99";s:5:"typo3";s:13:"6.2.0-7.99.99";}}', 'Xavier Perseguers (Causal)', 'xavier@causal.ch', 'xperseguers', '8d3ccfef318ea65e8971846d7cf5fc5c', 'Resize process may possibly not start when replacing an existing file.\nPHP deprecation notice in scheduler task.\nDetails on https://forge.typo3.org/projects/extension-image_autoresize/wiki/IMAGE_AUTORESIZE_167', 'Causal Srl', 1006007, 0, 0),
(26592, 0, 'image_autoresize', 1, '1.7.0', 713, 0, 'Resize images automatically', 'Simplify the way your editors may upload their images: no complex local procedure needed, let TYPO3 automatically resize down their huge images/pictures on-the-fly during upload (or using a scheduler task for batch processing) and according to your own business rules (directory/groups). This will highly reduce the footprint on your server and speed-up response time if lots of images are rendered (e.g., in a gallery). Features an EXIF/IPTC extractor to ensure metadata may be used by the FAL indexer even if not preserved upon resizing.', 2, 0, 0, 1454941080, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:12:"5.5.0-7.0.99";s:5:"typo3";s:13:"6.2.0-7.99.99";}}', 'Xavier Perseguers (Causal)', 'xavier@causal.ch', 'xperseguers', 'f645626da9de3543cca6151c67ba62b9', 'Natively takes advantage of any third-party metadata extraction service (e.g., EXT:extractor).\nFew deprecated method calls removed.\nDetails on https://forge.typo3.org/projects/extension-image_autoresize/wiki/IMAGE_AUTORESIZE_170', 'Causal Srl', 1007000, 0, 0),
