(26597, 0, 'image_autoresize', 1, '1.7.5', 713, 0, 'Resize images automatically', 'Simplify the way your editors may upload their images: no complex local procedure needed, let TYPO3 automatically resize down their huge images/pictures on-the-fly during upload (or using a scheduler task for batch processing) and according to your own business rules (directory/groups). This will highly reduce the footprint on your server and speed-up response time if lots of images are rendered (e.g., in a gallery). Features an EXIF/IPTC extractor to ensure metadata may be used by the FAL indexer even if not preserved upon resizing.', 2, 0, 0, 1478178248, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:12:"5.5.0-7.0.99";s:5:"typo3";s:13:"6.2.0-8.99.99";}}', 'Xavier Perseguers (Causal)', 'xavier@causal.ch', 'xperseguers', 'f69492210a94f178bb2ddfe3119f83c4', 'Regular bug fix release.\r\nDetails on https://forge.typo3.org/projects/extension-image_autoresize/wiki/IMAGE_AUTORESIZE_175', 'Causal Srl', 1007005, 0, 0),
(26598, 0, 'image_autoresize', 1, '1.8.0', 713, 0, 'Resize images automatically', 'Simplify the way your editors may upload their images: no complex local procedure needed, let TYPO3 automatically resize down their huge images/pictures on-the-fly during upload (or using a scheduler task for batch processing) and according to your own business rules (directory/groups). This will highly reduce the footprint on your server and speed-up response time if lots of images are rendered (e.g., in a gallery). Features an EXIF/IPTC extractor to ensure metadata may be used by the FAL indexer even if not preserved upon resizing.', 2, 0, 0, 1489409281, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:12:"5.5.0-7.1.99";s:5:"typo3";s:12:"7.6.0-8.9.99";}}', 'Xavier Perseguers (Causal)', 'xavier@causal.ch', 'xperseguers', 'f654858808f986cb42ff98e1273714c0', 'TYPO3 6.2 is not supported anymore.\r\nFix a crash when configuring the extension in EM (no fix for TYPO3 8.6.0-8.6.1, use latest release instead).\r\nDetails on https://forge.typo3.org/projects/extension-image_autoresize/wiki/IMAGE_AUTORESIZE_180', 'Causal Srl', 1008000, 0, 0),
(26599, 0, 'image_autoresize', 1, '1.8.1', 713, 0, 'Resize images automatically', 'Simplify the way your editors may upload their images: no complex local procedure needed, let TYPO3 automatically resize down their huge images/pictures on-the-fly during upload (or using a scheduler task for batch processing) and according to your own business rules (directory/groups). This will highly reduce the footprint on your server and speed-up response time if lots of images are rendered (e.g., in a gallery). Features an EXIF/IPTC extractor to ensure metadata may be used by the FAL indexer even if not preserved upon resizing.', 2, 0, 0, 1500292186, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:12:"5.5.0-7.1.99";s:5:"typo3";s:12:"7.6.0-8.7.99";}}', 'Xavier Perseguers (Causal)', 'xavier@causal.ch', 'xperseguers', '2f3dfc9503dadaa86996c3995d799a2c', 'This release prevents a crash when creating new resize rules in TYPO3 v8.\r\nDetails on https://forge.typo3.org/projects/extension-image_autoresize/wiki/IMAGE_AUTORESIZE_181', 'Causal Srl', 1008001, 1, 0),
(26600, 0, 'mst_books', 1, '1.1.0', 69, 3, 'MST Book Library', 'Ever tried to keep track on all your books? This library will help you to keep track of all books. Based on extension sf_books 1.5.1 by Sebastian Fischer typo3@fischer.im.', 2, 0, 3, 1280240836, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"4.1.0-0.0.0";s:3:"php";s:11:"5.0.0-0.0.0";s:3:"cms";s:0:"";}}', 'Martin Strigl', 'mst@friendlynet.at', 'seldon', '821a5e18439f38889193d070a9e8dd86', ' initial release \r\n based on and extending sf_books by Sebastian Fischer typo3@fischer.im', '', 1001000, 0, 0),
