(26684, 0, 'c1x1_flashplayer', 1, '4.9.10', 367, 0, 'Nice HTML5 Flashplayer', 'Flash player shows FLV/MP4-Videos with the open-source Javascript video-js on your website. Easy configuration for admins and comfort handling for editors. Set preview image, playersize and other usefull settings.', 2, 0, 3, 1350550495, 'a:0:{}', 'Michael Blasius - consulting1x1 GmbH', 'typo3@consulting1x1.com', 'consulting1x1', '0ad506ae70f7600c1000161269f8eae4', 'Completely redone! New engine and Javascript library. Documentation will be submitted with the next update.', 'consulting1x1 GmbH', 4009010, 0, 0),
