(26689, 0, 'c1x1_flashplayer', 1, '4.4.0', 367, 0, 'Nice HTML5 Videoplayer', 'Videoplayer shows HTML5 videos with the open-source Javascript video-js on your website. An easy configuration for admins and comfort handling for editors. Set preview image, playersize and other usefull settings. Uses video-js 4.0.3. Only supports mp4, ogv and webm. FLV needs to be converted.', 2, 0, 3, 1370608880, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"5.2.0-0.0.0";s:5:"typo3";s:11:"4.5.3-0.0.0";}}', 'consulting1x1 GmbH', 'typo3@consulting1x1.com', 'consulting1x1', 'c53616a8af825cb7c9dc6e7ae856fa3d', '- Descriptions modified\r\n- Upgrade to video.js 4.0.3\r\n- Use of integrated flash fallback\r\n- FLV files no longer supported\r\n- Support for mp4, ogv and webm video files\r\n- Some bugfixing', 'consulting1x1 GmbH', 4004000, 0, 0),
(26690, 0, 'c1x1_flashplayer', 1, '4.14.0', 367, 0, 'Nice HTML5 Videoplayer', 'Videoplayer shows HTML5 videos with the open-source Javascript video-js on your website. An easy configuration for admins and comfort handling for editors. Set preview image, playersize and other usefull settings. Uses video-js 4.0.3. Only supports mp4, ogv and webm. FLV needs to be converted.', 2, 0, 3, 1370609057, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"5.2.0-0.0.0";s:5:"typo3";s:11:"4.5.3-0.0.0";}}', 'consulting1x1 GmbH', 'typo3@consulting1x1.com', 'consulting1x1', 'be1597672002d9e66870077fddc9fa01', 'Upgrade to new video.js 4.0.3 - FLV files no longer supported - all HTML5 video formats supported (mp4, ogv, webm)', 'consulting1x1 GmbH', 4014000, 0, 0),
