(26729, 0, 'simplehtmldom', 1, '0.0.1', 55, 6, 'Simple HTML DOM Parser', 'A HTML DOM parser written in PHP5 let you manipulate HTML in a very easy way!\nRequire PHP 5.\nSupports invalid HTML.\nFind tags on an HTML page with selectors just like jQuery.\nExtract contents from HTML in a single line.\nAuthor: S.C. Chen\nOriginal idea i', 0, 0, 2, 1281565300, 'a:0:{}', 'Tomas J Stehlik', 'tomas@stehlik.sk', 'stehlo', '0d322265ab0ffc5442aa2718a32e6244', 'Initial upload. Early development. No docs. No API.', '', 1, 0, 0),
(26730, 0, 'simplehtmldom', 1, '0.0.2', 55, 7, 'Simple HTML DOM Parser', 'A HTML DOM parser written in PHP5 let you manipulate HTML in a very easy way!\nRequire PHP 5.\nSupports invalid HTML.\nFind tags on an HTML page with selectors just like jQuery.\nExtract contents from HTML in a single line.\nAuthor: S.C. Chen\nOriginal idea i', 0, 0, 2, 1281570338, 'a:0:{}', 'Tomas J Stehlik', 'tomas@stehlik.sk', 'stehlo', 'e000acc967f684fc50407e95e849b4c2', 'Initial upload. Not intended for public use yet. No docs. No API.', '', 2, 0, 0),
