(27664, 0, 'cwmobileredirect', 1, '1.1.0', 1334, 74, 'Mobile Redirect', 'Your all-in-one mobile device detection and redirection solution! Detects mobile browsers and redirects to other Typo3 sites in your setup (most likely optimized for mobiles). Allows to easily switch back to the normal version, with Cookie support to reme', 2, 0, 2, 1291737116, 'a:0:{}', 'Carsten Windler', 'info@windler-consulting.de', 'el_curtismo', '63b58edd5d213e0dba63964a3ac215aa', '- TypoScript support for mobile detection\r\n- mobile detection can now easily be used in your own extension ', '', 1001000, 0, 0),
(27665, 0, 'cwmobileredirect', 1, '1.1.1', 1334, 53, 'Mobile Redirect', 'Your all-in-one mobile device detection and redirection solution! Detects mobile browsers and redirects to other Typo3 sites in your setup (most likely optimized for mobiles). Allows to easily switch back to the normal version, with Cookie support to reme', 2, 0, 2, 1294955877, 'a:0:{}', 'Carsten Windler', 'info@windler-consulting.de', 'el_curtismo', 'c93bee33c6a37db5f9f984fb092032de', 'Some important issues fixed (please see changelog). New userfunctions which now take account of the Cookie settings.', '', 1001001, 0, 0),
(27666, 0, 'cwmobileredirect', 1, '1.2.0', 1334, 62, 'Mobile Redirect', 'Your all-in-one mobile device detection and redirection solution! Detects mobile browsers and redirects to other Typo3 sites in your setup (most likely optimized for mobiles). Allows to easily switch back to the normal version, with Cookie support to reme', 2, 0, 2, 1295821743, 'a:0:{}', 'Carsten Windler', 'info@windler-consulting.de', 'el_curtismo', 'a2d8fc1a8abd6f3468c17e509dda46ab', 'Multi domain setups are now supported, configuration is now changeable via TypoScript', '', 1002000, 0, 0),
(27667, 0, 'cwmobileredirect', 1, '1.2.1', 1334, 156, 'Mobile Redirect', 'Your all-in-one mobile device detection and redirection solution! Detects mobile browsers and redirects to other Typo3 sites in your setup (most likely optimized for mobiles). Allows to easily switch back to the normal version, with Cookie support to reme', 2, 0, 2, 1296512060, 'a:0:{}', 'Carsten Windler', 'info@windler-consulting.de', 'el_curtismo', '5d594a7a148f799001bc5557afc97f77', 'Bugfix. Please try this version if the previous release didnt work (pls dont forget to press the Update button in the Ext Manager configuration after updating!)', '', 1002001, 0, 0);
