(27671, 0, 'cwmobileredirect', 1, '1.4.2', 1334, 304, 'Mobile Redirect', 'Your all-in-one mobile device detection and redirection solution! Detects mobile browsers and redirects to other Typo3 sites in your setup (most likely optimized for mobiles). Allows to easily switch back to the normal version, with Cookie support to reme', 2, 0, 2, 1324243804, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:11:"4.3.0-0.0.0";}}', 'Carsten Windler', 'info@windler-consulting.de', 'el_curtismo', 'd35b3e559bbe7627f0750a42c4d40c76', 'One bugfix and some improvements. Please see documentation for more details.', '', 1004002, 0, 0),
(27672, 0, 'cwmobileredirect', 1, '1.4.3', 1334, 0, 'Mobile Redirect', 'Your all-in-one mobile device detection and redirection solution! Detects mobile browsers and redirects to other Typo3 sites in your setup (most likely optimized for mobiles). Allows to easily switch back to the normal version, with Cookie support to remember the users choice. The browser detection can be access via TypoScript or in your own extension.', 2, 0, 2, 1388960443, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"4.3.0-6.1.99";s:3:"php";s:11:"5.3.0-0.0.0";}}', 'Carsten Windler', 'carsten@windler-online.de', 'el_curtismo', 'ce1a9f3ce030c8f0536727a457b30547', 'Finally - bugfixes, updates and small changes! Important: please read changelog and "Updating from prior versions" carefully before installing this version!', '', 1004003, 0, 0),
(27673, 0, 'cwmobileredirect', 1, '1.4.4', 1334, 0, 'Mobile Redirect', 'Your all-in-one mobile device detection and redirection solution! Detects mobile browsers and redirects to other Typo3 sites in your setup (most likely optimized for mobiles). Allows to easily switch back to the normal version, with Cookie support to remember the users choice. The browser detection can be access via TypoScript or in your own extension.', 2, 0, 2, 1412064306, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"4.3.0-6.2.99";s:3:"php";s:11:"5.3.0-0.0.0";}}', 'Carsten Windler', 'carsten@windler-online.de', 'el_curtismo', '9efd0923794be8f379d1cbc6343195f1', 'Compatibility with Typo3 6.2.x. No other new features.', '', 1004004, 0, 0),
(27674, 0, 'cwmobileredirect', 1, '1.5.0', 1334, 0, 'Mobile Redirect', 'Your all-in-one mobile device detection and redirection solution! Detects mobile browsers andredirects to other Typo3 sites in your setup (most likely optimized for mobiles). Allows to easily switch back to the normal version, with Cookie support to remember the users choice. The browser detection can be access via TypoScript or in your own extension.', 2, 0, 2, 1473017306, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:13:"7.5.0-7.99.99";}}', 'Carsten Windler', 'carsten@carstenwindler.de', 'el_curtismo', 'e3bf55673be81d4be970d8f87ea1f0ea', 'Added Typo3 7.x support, dropped Typo3 4.x support', '', 1005000, 1, 0),
