(27780, 0, 'filelinks', 1, '0.0.1', 410, 10, 'Filelinks', '', 1, 0, 2, 1287385861, 'a:1:{s:7:"depends";a:1:{s:3:"cms";s:0:"";}}', 'Thomas Breuss', 'thomas.breuss@zephir.ch', 'tebe', 'bdb87a6aa039e3dfbfc513c87ead2e1b', 'Initial upload. Creating links to internal pages, files, external urls and emails. Secure filelinks possible. No typoscript - just php.', '', 1, 0, 0),
(27781, 0, 'filelinks', 1, '0.0.2', 410, 10, 'Filelinks', 'Creates a list of links (internal pages, files, external urls and emails). Secure file downloads are possible. Easy to use your own template (php view). No typoscript - just php. See README.txt.', 1, 0, 2, 1287555167, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:9:"4.2-0.0.0";s:3:"cms";s:0:"";}}', 'Thomas Breuss', 'thomas.breuss@zephir.ch', 'tebe', 'e7856bc2a6d4f18e874b3705c05cd1f3', 'German instructions (see README.txt). Small bugfix.', 'Zephir AG', 2, 0, 0),
(27782, 0, 'filelinks', 1, '0.0.3', 410, 22, 'Filelinks', 'Creates a link list with internal pages, files, external urls or emails. Secure file downloads possible. Easy to use your own template (php view). No typoscript - just php. See README.txt.', 1, 0, 2, 1287641417, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:9:"4.2-0.0.0";s:3:"cms";s:0:"";}}', 'Thomas Breuss', 'thomas.breuss@zephir.ch', 'tebe', '65fe4b9a449189fd645f7dac6eea6555', 'Bugfix and typos.', 'Zephir AG', 3, 0, 0),
(27783, 0, 'filelinks', 1, '0.0.4', 410, 18, 'Filelinks', 'Creates a link list with internal pages, files, external urls or emails. Secure file downloads possible. Easy to use your own template (php view). No typoscript - just php. German instructions in README.txt.', 2, 0, 2, 1289386132, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:9:"4.2-0.0.0";s:3:"cms";s:0:"";}}', 'Thomas Breuss', 'thomas.breuss@zephir.ch', 'tebe', '90ff8e010e9a91e5867d2b46348c9d3f', 'Testing for constant TYPO3_MODE in php views. Setting extension as stable.', 'Zephir AG', 4, 0, 0),
(27784, 0, 'filelinks', 1, '0.0.5', 410, 42, 'Filelinks', 'Creates a link list with internal pages, files, external urls or emails. Secure file downloads possible. Easy to use your own template (php view). No typoscript - just php. German instructions in README.txt.', 2, 0, 2, 1289896280, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:9:"4.2-0.0.0";s:3:"cms";s:0:"";}}', 'Thomas Breuss', 'thomas.breuss@zephir.ch', 'tebe', '741214a1fd9f856e0f8e73b089b84586', 'Fixed bug with missing file icon. Added flv and default file icon.', 'Zephir AG', 5, 0, 0),
