(27881, 0, 'moc_varnish', 1, '1.3.0', 183, 18, 'MOC Varnish', 'Extension that provides useful features when using Varnish with TYPO3, like cache-clearing and automatic ESI.', 2, 0, 4, 1332424485, 'a:0:{}', 'Jan-Erik Revsbech', 'janerik@mocsystems.com', 'revsbech', 'adefc2916955ab8d4ec02c331254def6', 'Bugfixes for clearing rootpage (/)\r\nIntroduced a new configuration for clearing subpages differently.', 'MOC Systems', 1003000, 0, 0),
