(27898, 0, 'flipit', 1, '6.0.2', 0, 0, 'Flip it!', 'Flip it! enables you to run over pages in PDF documents like in a real magazine. Flip it! offers lovely and smooth page flip transitions. The visitor of your website does not need any PDF plugin but a Flash plugin. Flip it! can convert PDF documents to SWF files automatically. See: http://typo3-flipit.de/', 1, 0, 3, 1441306471, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"4.5.0-6.2.99";}}', 'Dirk Wildt (Die Netzmacher)', 'http://wildt.at.die-netzmacher.de', 'dwildt', '2ffa33078b8fcd19c51a9e390ba91dfd', 'Bugfix: PHP Warnings', '', 6000002, 1, 0),
(27899, 0, 'flipit', 1, '0.0.3', 0, 0, 'Flip it!', 'Flip it! enables you to run over pages in PDF documents and magazines. Flip it! offers lovely and smooth page flip transitions. The visitor of your website does not need any PDF plugin but a Flash plugin. Flip it! converts PDF documents to SWF files automatically. BE AWARE: You have to install one software package on the web server (Linux and  Windows are supported). You must be root.', 0, 0, 3, 1357070886, 'a:0:{}', 'Dirk Wildt (Die Netzmacher)', 'http://wildt.at.die-netzmacher.de', 'dwildt', '5f2187dedf52409e4f2aec5da30fe118', 'SWFTOOLS can convert JPEG, PDF, PNG and WAV files to SWF / Flash files. Install SWFTOOLS on a Linux server. You must be root!', '', 3, 0, 0),
