(27960, 0, 'we_google_analytics', 1, '1.0.0', 715, 41, 'Google Analytics', 'Insert Google Anlytics code and choose if sync/async and with anonymizeIP or not. Different configuration per domain possible (throught TypoScript)', 1, 0, 2, 1287751319, 'a:0:{}', 'Andreas Becker - websedit AG', 'extensions@websedit.de', 'websedit-ag', '4f3974f6ed966dc1829796b831db8d7b', 'Initial release', 'websedit AG', 1000000, 0, 0),
(27961, 0, 'we_google_analytics', 1, '1.0.1', 715, 76, 'Google Analytics', 'Insert Google Anlytics code and choose if sync/async and with anonymizeIP or not. Different configuration per domain possible (throught TypoScript)', 1, 0, 2, 1289213503, 'a:0:{}', 'Andreas Becker - websedit AG', 'extensions@websedit.de', 'websedit-ag', '36ebbe66289d20a1a272750dbc145547', 'Correction in Warning message, if wrong Account Number is set; updated manual', 'websedit AG', 1000001, 0, 0),
(27962, 0, 'we_google_analytics', 1, '1.1.0', 715, 278, 'Google Analytics', 'This Plugin will add the Google Analytics Code to your site automagically. Mobile Tracking Code supported.', 1, 0, 2, 1293549049, 'a:0:{}', 'Andreas Becker - websedit AG', 'extensions@websedit.de', 'websedit-ag', '1ff130a3d8261ca2ae33d10cf393ce1c', 'ATTENTION: Asynchronous Mode is now default! Set "tx_we_google_analytics.type  sync" to keep synchronous Mode.\r\nAdded Mobile Tracking Code and support for \r\n_option-Tags like _setDomainName.\r\n', 'websedit AG', 1001000, 0, 0),
(27963, 0, 'we_google_analytics', 1, '1.2.0', 715, 68, 'Google Analytics', 'This Plugin will add the Google Analytics Code to your site automagically. Mobile Tracking Code supported.', 2, 0, 2, 1320664030, 'a:0:{}', 'Andreas Becker - websedit AG', 'extensions@websedit.de', 'websedit-ag', '5b2b702591132fc4717f97e7cddbb0ec', 'Added support for file and pageload tracking', 'websedit AG', 1002000, 0, 0),
(27964, 0, 'we_google_analytics', 1, '1.2.1', 715, 252, 'Google Analytics', 'This Plugin will add the Google Analytics Code to your site automagically. Mobile Tracking Code supported.', 2, 0, 2, 1322144309, 'a:0:{}', 'Andreas Becker - websedit AG', 'extensions@websedit.de', 'websedit-ag', 'bb99afa02ad7387745e97b51aa477314', 'Extended file tracking support (file types can now be defined); Updated manual due to the online layout rendering', 'websedit AG', 1002001, 0, 0),
(27965, 0, 'we_google_analytics', 1, '1.3.0', 715, 0, 'Google Analytics', 'This Plugin will add the Google Analytics Code to your site automagically. Mobile Tracking Code supported.', 2, 0, 2, 1346665382, 'a:0:{}', 'Andreas Becker - websedit AG', 'extensions@websedit.de', 'websedit-ag', 'e25d47c736a1272ca533a4871211c17c', 'Compatibility update for TYPO3 4.6.\r\nReplaced old Funktion t3lib_div::GPvar. \r\nExternal links kann now be tracked (protocols to track can be defined).', 'websedit AG', 1003000, 0, 0),
(27966, 0, 'we_google_analytics', 1, '1.4.0', 715, 0, 'Google Analytics', 'This Plugin will add the Google Analytics Code to your site automagically. Mobile Tracking Code supported.', 2, 0, 2, 1355920356, 'a:0:{}', 'Andreas Becker - websedit AG', 'extensions@websedit.de', 'websedit-ag', '161783696d8893ca5b27284b47e5508a', 'Added Enhanced Link Attribution. Analytics account number is now converted automatically for the defined type (UA- or MO-). Marked deprecated Google Analytics functions in the manual.', 'websedit AG', 1004000, 0, 0),
(27967, 0, 'we_google_analytics', 1, '1.4.1', 715, 0, 'Google Analytics', 'This Plugin will add the Google Analytics Code to your site automagically. Mobile Tracking Code supported.', 2, 0, 2, 1360060633, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"4.3.0-6.1.99";}}', 'Andreas Becker - websedit AG', 'extensions@websedit.de', 'websedit-ag', 'fc9b598e4e9bfbd41df4f4e2feebd731', 'Bugfix trackexternal, thanks to Thomas Maurer.\r\nSet correct dependencies in em_conf.', 'websedit AG', 1004001, 0, 0),
(27968, 0, 'we_google_analytics', 1, '1.5.0', 715, 0, 'Google Analytics', 'This Plugin will add the Google Analytics Code to your site automagically. Mobile Tracking Code supported.', 2, 0, 2, 1363852636, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"4.3.0-6.1.99";}}', 'Andreas Becker - websedit AG', 'extensions@websedit.de', 'websedit-ag', '462a8b287c23ef3fcb2729e89accadcc', 'Added Code to Support Display Advertising and to Adjusted  Bounce Rate', 'websedit AG', 1005000, 0, 0),
(27969, 0, 'we_google_analytics', 1, '1.6.0', 715, 0, 'Google Analytics', 'This Plugin will add the Google Analytics Code to your site automagically. Mobile Tracking Code supported.', 2, 0, 4, 1383126249, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"4.3.0-6.1.99";}}', 'Andreas Becker - websedit AG', 'extensions@websedit.de', 'websedit-ag', 'ac7646b98089a7b21eeb27da09cae9c2', 'Changed "recordOutboundLink()" to work even when GA is blocked by browserplugins. Thanks to Sebastian During.\r\nAdded basic Universal Analytics support (dualtagging possible). See Changelog for more informations.', 'websedit AG', 1006000, 0, 0),
(27970, 0, 'we_google_analytics', 1, '1.6.1', 715, 0, 'Google Analytics', 'This Plugin will add the Google Analytics Code to your site automagically. Mobile Tracking Code supported.', 2, 0, 4, 1400225151, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"4.3.0-6.1.99";}}', 'Andreas Becker - websedit AG', 'extensions@websedit.de', 'websedit-ag', 'd45c3d8371e0012213128f78dabfc124', 'Bugfix: The filetracking code on async tracking did not include the basefolder (e.g. fileadmin). Thanks to Andreas Fragner', 'websedit AG', 1006001, 0, 0),
(27971, 0, 'we_google_analytics', 1, '1.7.0', 715, 0, 'Google Analytics', 'This Plugin will add the Google Analytics Code to your site automagically. Mobile Tracking Code supported.', 2, 0, 2, 1404307388, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"4.3.0-6.2.99";}}', 'Andreas Becker - websedit AG', 'extensions@websedit.de', 'websedit-ag', 'b2145962318b5701c81797f89199d031', 'Now Supporting TYPO3 up to 6.2.99. Thanks to Andreas Fragner', 'websedit AG', 1007000, 0, 0),
