(28073, 0, 'hpfavideo', 1, '1.0.0', 111, 13, 'Flash Ajax driven videoplayer (FAVideo)', 'Easy to use implementation of the Flash JavaScript player "FAVideo".\nMore information: http://opensource.adobe.com/wiki/display/favideo/Flash-AjaxVideoComponent', 2, 0, 3, 1289677184, 'a:1:{s:7:"depends";a:1:{s:3:"cms";s:0:"";}}', 'Hauke Hain', 'hhpreuss@googlemail.com', 'acquire', '60847fa8c3cbb42ad4f1dd31f74ea9e5', 'Fully via TypoScript customizeable output.\r\nThis extension got some workarounds for FAVideo: scale mode and control color gets applied by events of the player, so slow internet connections are no problem.', '', 1000000, 0, 0),
(28074, 0, 'hpfavideo', 1, '1.1.0', 111, 2, 'Flash Ajax driven videoplayer (FAVideo)', 'Easy to use implementation of the Flash JavaScript player "FAVideo".\nMore information: http://opensource.adobe.com/wiki/display/favideo/Flash-AjaxVideoComponent', 2, 0, 3, 1289755793, 'a:1:{s:7:"depends";a:1:{s:3:"cms";s:0:"";}}', 'Hauke Hain', 'hhpreuss@googlemail.com', 'acquire', '24e65909fcfd0a5433f9c28c1a7ace8b', 'Multiple hpfavideo plugins on the same page are now possible', '', 1001000, 0, 0),
