(28083, 0, 'elemente_fenews', 1, '1.0.5', 636, 57, 'Frontend News', 'Frontend news submitter with RTE support (htmlArea RTE) and upload capabilities. Supports CAPTCHA (captcha, sr_freecap) for none access protected sites and DAM references (dam_ttnews) for image and file upload.', 2, 0, 3, 1290000891, 'a:1:{s:7:"depends";a:2:{s:10:"taskcenter";s:0:"";s:7:"tt_news";s:0:"";}}', 'Andre Steiling', 'steiling@elemente.ms', 'commodore', 'be7be3e6ef3547761895f75a94256459', 'Initial release. Further information & feedback at forge.typo3.org. Comes without a documentation yet. Anyone who wants to write it? ;) ', 'elemente websolutions', 1000005, 0, 0),
(28084, 0, 'elemente_fenews', 1, '1.0.6', 636, 45, 'Frontend News', 'Frontend news submitter with RTE support (htmlArea RTE) and upload capabilities. Supports CAPTCHA (captcha, sr_freecap) for none access protected sites and DAM references (dam_ttnews) for image and file upload.', 2, 0, 3, 1291823568, 'a:1:{s:7:"depends";a:1:{s:7:"tt_news";s:0:"";}}', 'Andre Steiling', 'steiling@elemente.ms', 'commodore', 'c22ba24701318b0dcc45135ba0bd3a52', 'Fixed critical bug with "tx_dam_mm_ref" relation handling in case of deleting a record. Please update!', 'elemente websolutions', 1000006, 0, 0),
(28085, 0, 'elemente_fenews', 1, '1.0.7', 636, 10, 'Frontend News', 'Frontend news submitter with RTE support (htmlArea RTE) and upload capabilities. Supports CAPTCHA (captcha, sr_freecap) for none access protected sites and DAM references (dam_ttnews) for image and file upload.', 2, 0, 3, 1292320134, 'a:1:{s:7:"depends";a:1:{s:7:"tt_news";s:5:"2.5.0";}}', 'Andre Steiling', 'steiling@elemente.ms', 'commodore', '3ea8b7e9d2946972d81ed03be3a6f57b', 'Bugfix: Added a version switch for tt_news v2.5 / v3.0 to support categories selection in flexforms again when using tt_news v2.5.', 'elemente websolutions', 1000007, 0, 0),
