(28148, 0, 'pagenotfoundhandling', 1, '0.2.1', 318, 223, '404 Page not found handling', 'Highly configurable 404 page handling. Supports multi domain systems with multiple languages.', 1, -1, 2, 1297877105, 'a:0:{}', 'Christian Futterlieb', 'development@agenturamwasser.ch', 'christian.futterlieb', '296251b597ba73845109c4cb04b81bdc', 'Important Bugfix: defaultTemplateFile/default404Page was ignored on access restriction errors\r\nSmall feature: replacement of CURRENT_URL in the additionalGetParams/additional403GetParams', ' Partner AG', 2001, 0, 0),
(28149, 0, 'pagenotfoundhandling', 1, '0.2.2', 318, 0, '404 Page not found handling', 'Highly configurable 404 page handling. Supports multi domain systems with multiple languages.', 1, -1, 2, 1373646723, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"4.5.0-6.1.99";}}', 'Christian Futterlieb', 'development@agenturamwasser.ch', 'christian.futterlieb', '34dcf413a7df569978c169374114a4f7', ' Setting the correct TYPO3 version dependency (4.5.0 - 6.1.99)\n Tiny fixes\n No further changes to the extensions behaviour, it is save to just update.', ' Partner AG', 2002, 0, 0),
(28150, 0, 'pagenotfoundhandling', 1, '0.2.3', 318, 0, '404 Page not found handling', 'Highly configurable 404 page handling. Supports multi domain systems with multiple languages.', 1, -1, 2, 1396889499, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"4.5.0-6.1.99";}}', 'Christian Futterlieb', 'development@agenturamwasser.ch', 'christian.futterlieb', '43eed494db0bd8000c92dc18635e03bc', 'added new feature to passthrough the Content-Type HTTP header to fix bug 57662 (http://forge.typo3.org/issues/57662)', ' Partner AG', 2003, 0, 0),
(28151, 0, 'pagenotfoundhandling', 1, '2.0.0', 318, 0, '404 Page not found handling', 'Highly configurable 404 page handling. Supports multi domain systems with multiple languages.', 2, -1, 2, 1403524502, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"4.5.0-6.2.99";}}', 'Christian Futterlieb', 'development@agenturamwasser.ch', 'christian.futterlieb', 'bca4371e5d4edece825247dd58ddef24', 'Stable version with support for TYPO3 4.5 - 6.2.\nAdded a new feature to send additional HTTP headers with the 404/403 page, database update is required!', ' Partner AG', 2000000, 0, 0),
(28152, 0, 'pagenotfoundhandling', 1, '2.0.1', 318, 0, '404 Page not found handling', 'Highly configurable 404 page handling. Supports multi domain systems with multiple languages.', 2, -1, 2, 1403538997, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"4.5.0-6.2.99";}}', 'Christian Futterlieb', 'development@agenturamwasser.ch', 'christian.futterlieb', '4351a820672390565bfc396cf829afb8', 'This release includes a new option to build correct URLs when fetching 404 page (see http://forge.typo3.org/issues/59815) and the documentation is now moved to reStructuredText (see http://forge.typo3.org/issues/59807). Some cleanups are in as well.\n\nIf y', ' Partner AG', 2000001, 0, 0),
(28153, 0, 'pagenotfoundhandling', 1, '2.1.0', 318, 0, '404 Page not found handling', 'Highly configurable 404 page handling. Supports multi domain systems with multiple languages.', 2, -1, 2, 1431088162, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"4.5.0-6.2.99";}}', 'Christian Futterlieb', 'development@agenturamwasser.ch', 'christian.futterlieb', 'f6138f621296b0ab9ff73fd54859c9ba', 'Added new feature to send X-Forwarded-To HTTP Header. Database needs to be updated!', ' Partner AG', 2001000, 0, 0),
(28154, 0, 'pagenotfoundhandling', 1, '2.1.1', 318, 0, '404 Page not found handling', 'Highly configurable 404 page handling. Supports multi domain systems with multiple languages.', 2, 0, 2, 1435578584, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"4.5.0-6.2.99";}}', 'Christian Futterlieb', 'development@agenturamwasser.ch', 'christian.futterlieb', 'abb8a28f29fe4b1c1b6069c40a04e941', 'Security Fix PLEASE UPDATE See: http://typo3.org/teams/security/security-bulletins/typo3-extensions/typo3-ext-sa-2015-015/ for details nc ', ' Partner AG', 2001001, 0, 0),
(28155, 0, 'pagenotfoundhandling', 1, '2.2.0', 318, 0, '404 Page not found handling', 'Highly configurable 404 page handling. Supports multi domain systems with multiple languages.', 2, 0, 2, 1447869376, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:13:"6.2.1-7.6.999";}}', 'Christian Futterlieb', 'development@agenturamwasser.ch', 'christian.futterlieb', '9b2838198ab78c42a7573cb85c99942f', 'TYPO3 7 LTS compatibility release', ' Partner AG', 2002000, 0, 0),
(28156, 0, 'pagenotfoundhandling', 1, '2.3.0', 318, 0, '404 Page not found handling', 'Highly configurable 404 page handling. Supports multi domain systems with multiple languages.', 2, 0, 2, 1453729326, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:13:"6.2.1-7.6.999";}}', 'Christian Futterlieb', 'development@agenturamwasser.ch', 'christian.futterlieb', '8efc5197a36f252d072b27009b202730', 'Added a new feature that supports sending an authorization HTTP header when fetching the 403/404 page (thanks to Sascha Egerer for his work). It supports basic and digest authentication. For details see https://forge.typo3.org/issues/72868 and the manual.', ' Partner AG', 2003000, 0, 0),
(28157, 0, 'pagenotfoundhandling', 1, '2.3.1', 318, 0, '404 Page not found handling', 'Highly configurable 404 page handling. Supports multi domain systems with multiple languages.', 2, 0, 2, 1458338420, 'a:2:{s:7:"depends";a:1:{s:5:"typo3";s:13:"6.2.1-7.6.999";}s:8:"suggests";a:1:{s:7:"realurl";s:6:"1.12.8";}}', 'Christian Futterlieb', 'development@agenturamwasser.ch', 'christian.futterlieb', 'ce129889c9fac31cf95b25c2af3b968c', 'Improved language guessing with realurl. If youre still stuck with realurl_force404lang youre lucky, you can get rid of it after updating to 2.3.1. No further changes, its safe to just update.', ' Partner AG', 2003001, 0, 0),
