(28298, 0, 'wildside_extbase', 1, '2.1.0', 662, 12, 'Wildside Extbase Framework', 'Extbase Helper Framework. Provides ViewHelpers and an AS3-for-JS style API for advanced Widget-style AJAX components.', 2, 0, 3, 1300379006, 'a:1:{s:7:"depends";a:2:{s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'abandoned_extensions', '3b11b34bbffe41ef57fee560f4536cd9', 'Yet another addition: beginnings of almost automated AJAX Widgets for record selection and file upload, major updates to the EventDispatcher framework. There will be quite a few of these releases in the coming week - the end goal is fully automated AJAX W', 'Wildside A/S', 2001000, 0, 0),
(28299, 0, 'wildside_extbase', 1, '2.1.1', 662, 13, 'Wildside Extbase Framework', 'Extbase Helper Framework. Provides ViewHelpers and an AS3-for-JS style API for advanced Widget-style AJAX components.', 2, 0, 3, 1300405059, 'a:1:{s:7:"depends";a:2:{s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'abandoned_extensions', '6b876d811bcc18adf9342d44006d78a2', 'A few bugfixes and a switchable trace-method for all DisplayObjects.', 'Wildside A/S', 2001001, 0, 0),
(28300, 0, 'wildside_extbase', 1, '2.2.0', 662, 10, 'Wildside Extbase Framework', 'Extbase Helper Framework. Provides ViewHelpers and an AS3-for-JS style API for advanced Widget-style AJAX components.', 2, 0, 3, 1300474096, 'a:1:{s:7:"depends";a:2:{s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'abandoned_extensions', '933fa99578df3760bc0d60ae13015790', 'Added a manual with a few examples and some notes for developers who use this extension.', 'Wildside A/S', 2002000, 0, 0),
