(28305, 0, 'wildside_extbase', 1, '2.2.5', 662, 11, 'Wildside Extbase Framework', 'Extbase Helper Framework. Provides ViewHelpers and an AS3-for-JS style API for advanced Widget-style AJAX components.', 2, 0, 3, 1300650678, 'a:1:{s:7:"depends";a:2:{s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'abandoned_extensions', 'ca79c21eb6c6e2c3210f40c22a7ad678', 'Updated the manual; Aloha optimizations done.', 'Wildside A/S', 2002005, 0, 0),
(28306, 0, 'wildside_extbase', 1, '2.3.0', 662, 6, 'Wildside Extbase Framework', 'Extbase Helper Framework. Provides ViewHelpers and an AS3-for-JS style API for advanced Widget-style AJAX components.', 2, 0, 3, 1300734481, 'a:1:{s:7:"depends";a:2:{s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'abandoned_extensions', '9f1879a3dd00818a24261791d8320743', 'API feature freeze milestone: all basic API methods have now been added. RecordSelectorWidget, FileUploadWidget and DatePickerWidget still unfinished. Nice, big extended example added in the manual.', 'Wildside A/S', 2003000, 0, 0),
(28307, 0, 'wildside_extbase', 1, '2.3.1', 662, 11, 'Wildside Extbase Framework', 'Extbase Helper Framework. Provides ViewHelpers and an AS3-for-JS style API for advanced Widget-style AJAX components.', 2, 0, 3, 1300734895, 'a:1:{s:7:"depends";a:2:{s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'abandoned_extensions', '6ab378f93a3e158608723303e56460eb', 'API feature freeze milestone: all basic API methods have now been added. RecordSelectorWidget, FileUploadWidget and DatePickerWidget still unfinished. Nice, big extended example added in the manual. Bugfix version to remove two console-calls.', 'Wildside A/S', 2003001, 0, 0),
(28308, 0, 'wildside_extbase', 1, '2.4.0', 662, 10, 'Wildside Extbase Framework', 'For Extbase extension developers. Provides ViewHelpers and an AS3-for-JS style API for Widget-style AJAX components. Includes an injectable CloningService to easily clone (copy) Domain Objects with full control over relations.', 2, 0, 3, 1300819547, 'a:1:{s:7:"depends";a:2:{s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'abandoned_extensions', '4d6534b979edcd0d8a645c2546247c8d', 'Added a much needed service singleton to safely clone/copy Domain Objects even with relations. Added a PropertyMapper singleton to extract values from Domain Objects based on annotations. Updated the manual with examples for these two new injectable servi', 'Wildside A/S', 2004000, 0, 0),
(28309, 0, 'wildside_extbase', 1, '2.4.1', 662, 7, 'Wildside Extbase Framework', 'For Extbase extension developers. Provides ViewHelpers and an AS3-for-JS style API for Widget-style AJAX components. Includes an injectable CloningService to easily clone (copy) Domain Objects with full control over relations.', 2, 0, 3, 1300905513, 'a:1:{s:7:"depends";a:2:{s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'abandoned_extensions', '4fb49d592678d6aca4497c2594dfcee9', 'Minor addition: a Recursion Handler for injection in classes which use recursive functions. Lets the developer record encounters (identifier strings) and specify the max. allowed encounters of a unique identifier - or a max. allowed recursion level. Is us', 'Wildside A/S', 2004001, 0, 0),
(28310, 0, 'wildside_extbase', 1, '2.4.2', 662, 7, 'Wildside Extbase Framework', 'For Extbase extension developers. Provides ViewHelpers and an AS3-for-JS style API for Widget-style AJAX components. Includes an injectable CloningService to easily clone (copy) Domain Objects with full control over relations.', 2, 0, 3, 1300916737, 'a:1:{s:7:"depends";a:2:{s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'abandoned_extensions', '1de8f4f3a58b3a3823a32b3a80a5b321', 'Added Field type "Message" in JS API; Widgets use this field, if present with name"messages", to display messages. Added Field/MessageViewHelper with a few options to configure message display. Fixed a few bugs in messaging.', 'Wildside A/S', 2004002, 0, 0),
(28311, 0, 'wildside_extbase', 1, '2.4.3', 662, 14, 'Wildside Extbase Framework', 'For Extbase extension developers. Provides ViewHelpers and an AS3-for-JS style API for Widget-style AJAX components. Includes an injectable CloningService to easily clone (copy) Domain Objects with full control over relations.', 2, 0, 3, 1300989899, 'a:1:{s:7:"depends";a:2:{s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'abandoned_extensions', 'feb3b8e1b7adab09c851314c1fb9cfed', 'Added support for multiple namespace Javascript APIs in the same extension; API-ViewHelper now needs extension name as argument. A few bugfixes too.', 'Wildside A/S', 2004003, 0, 0),
