(28394, 0, 'tt_products', 1, '2.8.20', 64430, 0, 'Shop System', 'New versions at ttproducts.de. Documented in E-Book "Der TYPO3-Webshop" - Shop with listing in multiple languages, with order tracking, photo gallery, DAM, product variants, credit card payment and bank accounts, bill, creditpoint, voucher system and gift certificates. Latest updates at ttproducts.de.', 2, 0, 3, 1510922200, 'a:2:{s:7:"depends";a:5:{s:7:"div2007";s:12:"1.7.11-0.0.0";s:3:"php";s:13:"5.2.0-7.99.99";s:5:"table";s:11:"0.3.0-0.0.0";s:8:"tsparser";s:0:"";s:5:"typo3";s:13:"4.5.0-8.99.99";}s:9:"conflicts";a:7:{s:12:"mkl_products";s:0:"";s:11:"su_products";s:0:"";s:11:"zk_products";s:0:"";s:15:"ast_rteproducts";s:0:"";s:19:"onet_ttproducts_rte";s:0:"";s:8:"shopsort";s:0:"";s:20:"c3bi_cookie_at_login";s:0:"";}}', 'Franz Holzinger', 'franz@ttproducts.de', 'franzholz', 'efebe7bbe4782fcec68c2be115f0bc72', '\nbugfix: pid_list  0 is possible like before. In this case the products from the current page and all subpages are used and listed. bugfix for TYPO3 8.7.1: show product assigned to an article for article mode 0 . bugfix for the voucher extension.\n', 'jambage.com', 2008020, 1, 0),
(28395, 0, 'freizeitplan', 1, '0.0.1', 76, 76, 'FREIZEITPLAN.NET Online-Reservierungssystem', 'Bindet das Online-Reservierungssystem FREIZEITPLAN.NET in das Frontend ein.\n\nMit FREIZEITPLAN.NET verwalten Sie Ihre Mietobjekte online. Diese Typo3-Erweiterung sorgt fr die Ausgabe der Online-Buchungsmaske oder des Belegungskalenders fr Ihre Miet', 0, 0, 3, 1292851220, 'a:1:{s:7:"depends";a:1:{s:3:"cms";s:0:"";}}', 'Torsten Schnebaum', 'torsten.schoenebaum@planquadrat-software.de', 'rhuebsch', 'bfa7ca1b5f43a9be8adf87b6a600c662', 'initial release', 'Planquadrat Software-Integration GmbH', 1, 1, 0),
