(28399, 0, 'imagickimg', 1, '0.1.0', 113, 0, 'Image Processing via Imagick', 'Resize FE and BE images with Imagick PHP extension. Use all image effects available in standard CE elements like Image or Text with image. Useful on servers where exec() function is disabled.', 0, 0, 4, 1349104642, 'a:0:{}', 'Radu Dumbraveanu, Dmitri Paramonov', 'vundicind@gmail.com, dimirlan@mail.ru', 'tomkraw', 'bd2844577ae218eafd4ed2c94d75154a', 'Added identyfication images by Imagick. \nAdded an option to remove EXIF info from images and optimize images.\nAdded compatibility with TYPO3 version 4.6.\nAdded effects and compression for standard CE (Images only and Text with images).\nAdded two method cr', '', 1000, 0, 0),
(28400, 0, 'imagickimg', 1, '0.1.1', 113, 0, 'Image Processing via Imagick', 'Resize FE and BE images with Imagick PHP extension. Use all image effects available in standard CE elements like Image or Text with image. Useful on servers where exec() function is disabled.', 0, 0, 4, 1349588003, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:11:"4.5.0-4.6.0";}}', 'Radu Dumbraveanu, Dmitri Paramonov, Tomasz Krawczyk', 'vundicind@gmail.com, dimirlan@mail.ru, tomasz@typo3.pl', 'tomkraw', '194b37fb6ccb9fb9c405e794cb408131', 'Fixed bug in the effect of rounded corners.\nFixed file permissions.\nAdded TYPO3 version dependencies.\n\n', '', 1001, 0, 0),
