(28405, 0, 'pw_teaser', 1, '1.0.0', 369, 7, 'Professor Web Teaser', 'Extensions to create dynamic teasers, with data from page properties and its content elements. Professor Web Teaser based on Extbase and Fluid Template Engine.', 0, 0, 3, 1292925906, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"4.4.0-0.0.0";s:7:"extbase";s:17:"1.3.0beta2a-0.0.0";s:5:"fluid";s:16:"1.3.0beta2-0.0.0";}}', 'Armin Ruediger Vieweg', 'info@professorweb.de', 'professorweb', 'f225bdd0d26e77c07a11ea1c0a7ca550', 'First initial publication of alpha version.', '', 1000000, 0, 0),
(28406, 0, 'pw_teaser', 1, '1.0.1', 369, 44, 'Professor Web Teaser', 'Extensions to create dynamic teasers, with data from page properties and its content elements. Professor Web Teaser based on Extbase and Fluid Template Engine.', 0, 0, 3, 1292931332, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"4.4.0-0.0.0";s:7:"extbase";s:17:"1.3.0beta2a-0.0.0";s:5:"fluid";s:16:"1.3.0beta2-0.0.0";}}', 'Armin Ruediger Vieweg', 'info@professorweb.de', 'professorweb', '02191f40b9805b583502ba63c9ea4874', 'Removed accidentally added trunk, branches and tag directory. Some flexform fixes.', '', 1000001, 0, 0),
(28407, 0, 'pw_teaser', 1, '2.0.0', 369, 17, 'Page Teaser (with Fluid)', 'Create powerful, dynamic page teasers with data from page properties and its content elements. pw_teaser based on Extbase and Fluid Template Engine.', 2, 0, 3, 1307615478, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"4.5.0-0.0.0";s:7:"extbase";s:11:"1.3.0-0.0.0";s:5:"fluid";s:11:"1.3.0-0.0.0";}}', 'Armin Ruediger Vieweg', 'info@professorweb.de', 'professorweb', '175eff2a8643efa0f75b17b3a114e41c', 'Add very much new features and possibilities to order and filter pages. Add new hook to manipulate or add new pages or properties.', 'Professor Web', 2000000, 0, 0),
(28408, 0, 'pw_teaser', 1, '2.0.1', 369, 20, 'Page Teaser (with Fluid)', 'Create powerful, dynamic page teasers with data from page properties and its content elements. pw_teaser based on Extbase and Fluid Template Engine.', 2, 0, 3, 1307708186, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"4.5.0-0.0.0";s:7:"extbase";s:11:"1.3.0-0.0.0";s:5:"fluid";s:11:"1.3.0-0.0.0";}}', 'Armin Ruediger Vieweg', 'info@professorweb.de', 'professorweb', 'd123c9d7117985b90f50ffda20d2d751', 'Fixed a bug with the rendering of given typoscript. Now it is possible to give pw_teaser typoscript, which will be interpreted before it will be used as property of pw_teaser.', 'Professor Web', 2000001, 0, 0),
(28409, 0, 'pw_teaser', 1, '2.0.2', 369, 42, 'Page Teaser (with Fluid)', 'Create powerful, dynamic page teasers with data from page properties and its content elements. pw_teaser based on Extbase and Fluid Template Engine.', 2, 0, 3, 1308140701, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"4.5.0-0.0.0";s:7:"extbase";s:11:"1.3.0-0.0.0";s:5:"fluid";s:11:"1.3.0-0.0.0";}}', 'Armin Ruediger Vieweg', 'info@professorweb.de', 'professorweb', '233aae3f6e8b648b99239493d870c73c', 'Some code improvement to increase performance.\n\nPut extbase model mappings to extension setup, to prevent the appear of an exception if the user has forgotten to include the static setup to template.', 'Professor Web', 2000002, 0, 0),
(28410, 0, 'pw_teaser', 1, '2.0.3', 369, 24, 'Page Teaser (with Fluid)', 'Create powerful, dynamic page teasers with data from page properties and its content elements. pw_teaser based on Extbase and Fluid Template Engine.', 2, 0, 3, 1311581879, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"4.5.0-0.0.0";s:7:"extbase";s:11:"1.3.0-0.0.0";s:5:"fluid";s:11:"1.3.0-0.0.0";}}', 'Armin Ruediger Vieweg', 'info@professorweb.de', 'professorweb', '8d53839d610d8c5ee39a2e0c894f31e9', 'Fixed a bug with multi inclusion of pw_teaser on one page. Thanks to Andreas W. Wylach.', 'Professor Web', 2000003, 0, 0),
(28411, 0, 'pw_teaser', 1, '2.0.4', 369, 30, 'Page Teaser (with Fluid)', 'Create powerful, dynamic page teasers with data from page properties and its content elements. pw_teaser based on Extbase and Fluid Template Engine.', 2, 0, 3, 1312468338, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"4.5.0-0.0.0";s:7:"extbase";s:11:"1.3.0-0.0.0";s:5:"fluid";s:11:"1.3.0-0.0.0";}}', 'Armin Ruediger Vieweg', 'info@professorweb.de', 'professorweb', 'be956c4c982e6f545f147b6c8dd361a0', 'Fixed a bug which appears if random sorting and limit1 has been set. Thanks to Tim Klein-Hitpass, for reporting.', 'Professor Web', 2000004, 0, 0),
(28412, 0, 'pw_teaser', 1, '2.1.0', 369, 4, 'Page Teaser (with Fluid)', 'Create powerful, dynamic page teasers with data from page properties and its content elements. pw_teaser based on Extbase and Fluid Template Engine.', 2, 0, 3, 1313672397, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"4.5.0-0.0.0";s:7:"extbase";s:11:"1.3.0-0.0.0";s:5:"fluid";s:11:"1.3.0-0.0.0";}}', 'Armin Ruediger Vieweg', 'info@professorweb.de', 'professorweb', '800267dc64c8f04ae78a325c3357f6e2', 'Add new order method: by customField. Make it possible to order by a field which has been added to pages table by another extension, i.e.', 'Professor Web', 2001000, 0, 0),
(28413, 0, 'pw_teaser', 1, '2.2.0', 369, 27, 'Page Teaser (with Fluid)', 'Create powerful, dynamic page teasers with data from page properties and its content elements. pw_teaser based on Extbase and Fluid Template Engine.', 2, 0, 3, 1313677985, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"4.5.0-0.0.0";s:7:"extbase";s:11:"1.3.0-0.0.0";s:5:"fluid";s:11:"1.3.0-0.0.0";}}', 'Armin Ruediger Vieweg', 'info@professorweb.de', 'professorweb', 'f4addb714eb85c2adfeae03cfba3cee7', 'Add possibility to select fluid-html-file directly via typoscript:\n\n10  lib.pwteaser\n10.view.templatePathAndFilename  path/to/fluidtemplate.html', 'Professor Web', 2002000, 0, 0);
