(28696, 0, 'tsconf', 1, '6.1.0', 272, 0, 'TSconfig Pages and Users by extManager', 'Configure the TSconfig for your pages and users with the mouse! tsconf offers the eight most commonly used porperties like page tree uids, activated extended view, activated clipboard, activated admin panel and cache management for editors among others. Add your own icons to the page tree.', 2, 0, 0, 1427886737, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"4.5.0-7.0.99";}}', 'Dirk Wildt (Die Netzmacher)', 'http://wildt.at.die-netzmacher.de', 'dwildt', '09e82ebd2c7d1150f3dfc021f8656c1f', 'New Feature: Own Icons. Bugfix: TYPO3 4.x', '', 6001000, 0, 0),
(28697, 0, 'tsconf', 1, '6.2.0', 272, 0, 'TSconfig Pages and Users by extManager', 'Configure the TSconfig for your pages and users with the mouse! tsconf offers the eight most commonly used porperties like page tree uids, activated extended view, activated clipboard, activated admin panel and cache management for editors among others. Add your own icons to the page tree.', 2, 0, 0, 1444164115, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"4.5.0-7.0.99";}}', 'Dirk Wildt (Die Netzmacher)', 'http://wildt.at.die-netzmacher.de', 'dwildt', '2f33e974637bb79bbc401936381e9066', 'New feature: pagetree with enhanced context menu. Thanks to Andreas Kieling/pluspol for this new feature.', '', 6002000, 0, 0),
(28698, 0, 'tsconf', 1, '6.2.1', 272, 0, 'TSconfig Pages and Users by extManager', 'Configure the TSconfig for your pages and users with the mouse! tsconf offers the eight most commonly used porperties like page tree uids, activated extended view, activated clipboard, activated admin panel and cache management for editors among others. Add your own icons to the page tree.', 2, 0, 0, 1445455614, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"4.5.0-7.0.99";}}', 'Dirk Wildt (Die Netzmacher)', 'http://wildt.at.die-netzmacher.de', 'dwildt', '759a08540a01bed365df2d822cf98346', 'Bugfix: JavaScript for enhanced page tree menu was misssing', '', 6002001, 0, 0),
(28699, 0, 'tsconf', 1, '7.0.0', 272, 0, 'tsconf - Simplify your TYPO3 Backend!', 'Configure the TSconfig of your pages and your users by a mouse click. tsconf offers the configuration of the eight most commonly used porperties within the estension manager. Like page tree uids and icons, activated extended view, activated clipboard, activated admin panel and clear cache for editors among others. Add your own icons to the page tree.', 2, 0, 0, 1467126073, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.0.0-7.6.99";}}', 'Dirk Wildt (Die Netzmacher)', 'http://wildt.at.die-netzmacher.de', 'dwildt', 'd8689d3255451c76dc0c87621e082aea', 'COMPATIBILITY: TYPO3 7.x is supported, TYPO3 4.x isnt supported any longer. Removed: simplify page properties.', '', 7000000, 0, 0),
(28700, 0, 'tsconf', 1, '7.1.1', 272, 0, 'Backend Simplifier', 'The Backend Simplifier offers the configuration of the eight most commonly used porperties for simplifying the TYPO3 backend by a mouse cklick. User interface is the estension manager. Enable page tree uids, use indvidual page tree icons, activate the extended view and the clipboard and the admin panel for all editors. Extend the cache thunderbolts with one for the system cache.', 2, 0, 0, 1481736982, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.2.0-7.6.99";}}', 'Dirk Wildt (Die Netzmacher)', 'http://wildt.at.die-netzmacher.de', 'dwildt', '5f99c565de0d54016c2c717a1467381b', 'TYPO3 7.6 Compatibility. Bugfix pagetree icons. ReST documentation.', '', 7001001, 0, 0),
(28701, 0, 'tsconf', 1, '7.2.0', 272, 0, 'Backend Simplifier', 'The Backend Simplifier offers the configuration of the eight most commonly used porperties for simplifying the TYPO3 backend by a mouse cklick. User interface is the estension manager. Enable page tree uids, use indvidual page tree icons, activate the extended view and the clipboard and the admin panel for all editors. Extend the cache thunderbolts with one for the system cache.', 2, 0, 0, 1506785446, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.2.0-8.9.99";}}', 'Dirk Wildt (Die Netzmacher)', 'http://wildt.at.die-netzmacher.de', 'dwildt', '949e6f3b7441db6cb4b8673810380baa', 'UPGRADE for TYPO3 8.7. Compatible with TYPO3 6.2 and 7.6.', '', 7002000, 0, 0),
(28702, 0, 'tsconf', 1, '7.2.1', 272, 0, 'Backend Simplifier', 'The Backend Simplifier offers the configuration of the eight most commonly used porperties for simplifying the TYPO3 backend by a mouse cklick. User interface is the extension manager. Enable page tree uids, use indvidual page tree icons, activate the extended view and the clipboard and the admin panel for all editors. Extend the cache thunderbolts with one for the system cache.', 2, 0, 0, 1506847793, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.2.0-8.9.99";}}', 'Dirk Wildt (Die Netzmacher)', 'http://wildt.at.die-netzmacher.de', 'dwildt', '43de390df9fe8441f4dfde4f28449419', 'BUGFIX for TYPO3 6.x', '', 7002001, 0, 0),
(28703, 0, 'tsconf', 1, '7.2.2', 272, 0, 'Backend Simplifier', 'The Backend Simplifier offers the configuration of the eight most commonly used porperties for simplifying the TYPO3 backend by a mouse cklick. User interface is the extension manager. Enable page tree uids, use indvidual page tree icons, activate the extended view and the clipboard and the admin panel for all editors. Extend the cache thunderbolts with one for the system cache.', 2, 0, 0, 1507216090, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.2.0-8.9.99";}}', 'Dirk Wildt (Die Netzmacher)', 'http://wildt.at.die-netzmacher.de', 'dwildt', 'f77931d0905802b77613c632e8055261', 'IMPROVEMENT Extension manager  Reduce headers: Header 1 will not longer removed. This is in respect to fluid_styled_content. 0 (Default) is wrapped with h2.', '', 7002002, 1, 0),
