(28808, 0, 'sprite_stylist', 1, '0.1.0', 49, 13, 'Sprite Stylist', 'Allows to associate background sprite image with menu items to get CSS based  graphical menu.\nThis extension creates CSS only, use common HMENU cObject to build menu itself.', 0, 0, 2, 1296064422, 'a:0:{}', 'Marcus Biesioroff', 'marcus@biesioroff.com', 'biesior', 'cf0e45f2a69d5337ba9b6b0b5e3bc010', '- Initial upload, waiting for your feedback (see manual/changelog)!\r\n- Its possible that something fill fail, use this extension carefuly!\r\n- If I get few positive feedbacks Ill change it to stable', '', 1000, 0, 0),
(28809, 0, 'sprite_stylist', 1, '0.1.1', 49, 36, 'Sprite Stylist', 'Allows to associate your own designed background sprite image with menu items to get CSS based graphical menu.\nThis extension creates CSS only, use common HMENU cObject to build menu itself. Use your favorite graphic editor to design the images of your dr', 1, 0, 2, 1296127104, 'a:0:{}', 'Marcus Biesioroff', 'marcus@biesioroff.com', 'biesior', 'b1ed806bcd48ffe03a82307dcaa9840b', 'Added manual with description, samples, TS references and tutorials. No changes in features/code so you can just download manual only directly from the repository and overwrite it in extensions doc folder.', '', 1001, 1, 0),
(28810, 0, 'wildside_amazon_ses', 1, '1.0.0', 31, 7, 'Wildside Amazon SES MailInvoker', 'Acts as a complete replacement for the built-in TYPO3 email sending functions. Uses the Amazon SES (Simple Email Service) bulk emailing service instead. SES is a paid service, but you will be able to try it out quite thouroughly for less than 10 cents if ', 0, 0, 3, 1296068318, 'a:1:{s:7:"depends";a:2:{s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'abandoned_extensions', '997361544a4141ad6e80636844304226', 'ONLY FOR TYPO3 4.5!\r\n\r\nInitial upload. Framework is ready but does not currently do anything except pipe the mail through the ordinary mail() function. An update is expected in a few days which finally implements the first beta version capable of sending ', 'Wildside A/S', 1000000, 0, 0),
(28811, 0, 'wildside_amazon_ses', 1, '1.1.0', 31, 4, 'Wildside Amazon SES MailInvoker', 'Acts as a complete replacement for the built-in TYPO3 email sending functions. Uses the Amazon SES (Simple Email Service) bulk emailing service instead. SES is a paid service, but you will be able to try it out quite thouroughly for less than 10 cents if ', 0, 0, 3, 1296088833, 'a:1:{s:7:"depends";a:2:{s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'abandoned_extensions', '5a3416a25bfd81e20fd36648beb219ab', 'Working beta release. Is now capable of sending emails through SES - only configuration necessary is TS for plugin.tx_wildsideamazonses.settings.accessKeyId and .secretKey gotten from Amazon AWS account.\r\n\r\nYou do need to manually verify the email address', 'Wildside A/S', 1001000, 0, 0),
(28812, 0, 'wildside_amazon_ses', 1, '1.1.1', 31, 20, 'Wildside Amazon SES MailInvoker', 'Acts as a complete replacement for the built-in TYPO3 email sending functions. Uses the Amazon SES (Simple Email Service) bulk emailing service instead. SES is a paid service, but you will be able to try it out quite thouroughly for less than 10 cents if ', 1, 0, 3, 1296089134, 'a:1:{s:7:"depends";a:2:{s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'abandoned_extensions', '756239f820c50987297af5c0bbe5b882', 'Raised to beta version - see previous changelog message for important information.', 'Wildside A/S', 1001001, 1, 0),
(28813, 0, 'nfcflashmessages', 1, '1.0.0', 52, 12, 'NETFORMIC :: Flash Messages', 'Extension for displaying "flash messages" in frontend.', 1, 0, 2, 1296136858, 'a:0:{}', 'Dominique Muhlke, Christoph Mayer', 'typo3@netformic.de', 'netformic', '75bbf21b4275bda0eda32250cdde7a9c', 'Initial Release', '', 1000000, 0, 0),
