(28815, 0, 'nfcflashmessages', 1, '1.0.3', 52, 0, 'NETFORMIC :: Flash Messages', 'Extension for displaying "flash messages" in frontend.', 1, 0, 2, 1347276812, 'a:0:{}', 'Dominique Muhlke, Christoph Mayer', 'typo3@netformic.de', 'netformic', 'd93d2928b20c14c53709fe2a61d67692', '- added flashmessage javascript support and sorting manipulation options\n- added support for typoscript (readout flashmessages via ts)', '', 1000003, 1, 0),
