(28819, 0, 'ts_select', 1, '1.2.0', 244, 6, 'TypoScript Object Select', 'You can define typoscript objects (like lib.myTsObj)\nand the BE User is able to select it like a Content Element.', 1, 0, 3, 1298366518, 'a:0:{}', 'Hendrik Reimers', 'hendrik.reimers@web.de', 'kern23', 'd3f96553ba3bba075237f60283688b5f', 'New Features, New Icons, Updated locallang, see manual for details!', '', 1002000, 0, 0),
