(28824, 0, 'positionit', 1, '2.6.34', 1904, 51, 'positionIt', 'Creates forms and whole processes visually by drag & drop. Easy to use, saves much time. For documentation see http://positionit.org', 1, 0, 4, 1296313207, 'a:1:{s:7:"depends";a:1:{s:18:"static_info_tables";s:0:"";}}', 'Ososoft GmbH', 'info@ososoft.de', 'ososoft', '0d0acf78666a4e61ed7fcffb8705ed79', 'Initial public release. For more information, please visit http://positionit.org', '', 2006034, 0, 0),
(28825, 0, 'positionit', 1, '2.6.35', 1904, 60, 'positionIt', 'Creates forms, mailforms or whole web processes visually by drag & drop. Easy to use, saves much time. For documentation see http://positionit.org', 1, 0, 4, 1296497445, 'a:1:{s:7:"depends";a:1:{s:18:"static_info_tables";s:0:"";}}', 'Ososoft GmbH', 'info@ososoft.de', 'ososoft', 'f50c8f1c229c985cb7e39c5f72c04236', 'Several bug fixes. Started BE translation to english.', '', 2006035, 0, 0),
(28826, 0, 'positionit', 1, '2.6.40', 1904, 51, 'positionIt', 'Creates forms, mailforms or whole web processes visually by drag & drop. Easy to use, saves much time. For documentation see http://positionit.org', 1, 0, 4, 1297266554, 'a:1:{s:7:"depends";a:1:{s:18:"static_info_tables";s:0:"";}}', 'Ososoft GmbH', 'info@ososoft.de', 'ososoft', 'bd7e5b39ad2a239dc004e891766e299c', 'Major bugs fixed. Backend now translateable and translated to english and german. Much more documentation on http://positionit.org', '', 2006040, 0, 0),
