INSERT INTO `tx_extensionmanager_domain_model_extension` (`uid`, `pid`, `extension_key`, `repository`, `version`, `alldownloadcounter`, `downloadcounter`, `title`, `description`, `state`, `review_state`, `category`, `last_updated`, `serialized_dependencies`, `author_name`, `author_email`, `ownerusername`, `md5hash`, `update_comment`, `authorcompany`, `integer_version`, `current_version`, `lastreviewedversion`) VALUES
(28828, 0, 'positionit', 1, '2.6.42', 1904, 19, 'positionIt', 'Creates forms, mailforms or whole web processes visually by drag & drop. Easy to use, saves much time. For documentation see http://positionit.org', 1, 0, 4, 1297443992, 'a:1:{s:7:"depends";a:1:{s:18:"static_info_tables";s:0:"";}}', 'Ososoft GmbH', 'info@ososoft.de', 'ososoft', '76fee245fae875346bdf81ec6f11e0c7', 'Small bug fixes. Moving of multiple objects improved. New feature: clearing of session data can be defined for every process step.', '', 2006042, 0, 0),
(28829, 0, 'positionit', 1, '2.6.43', 1904, 38, 'positionIt', 'Creates forms, mailforms or whole web processes visually by drag & drop. Easy to use, saves much time. For documentation see http://positionit.org', 1, 0, 4, 1297527862, 'a:1:{s:7:"depends";a:1:{s:18:"static_info_tables";s:0:"";}}', 'Ososoft GmbH', 'info@ososoft.de', 'ososoft', '3b6893f18c6c4a74f004e994b2a48df1', 'Small bugs fixed. Improved positionIt editor usability.', '', 2006043, 0, 0),
(28830, 0, 'positionit', 1, '2.6.44', 1904, 38, 'positionIt', 'Creates forms, mailforms or whole web processes visually by drag & drop. Easy to use, saves much time. For documentation see http://positionit.org', 1, 0, 4, 1297702948, 'a:1:{s:7:"depends";a:1:{s:18:"static_info_tables";s:0:"";}}', 'Ososoft GmbH', 'info@ososoft.de', 'ososoft', '65db0191b2d41d9be0ebb374c0e3d958', 'Small bugs fixed. Checked TYPO3 4.5 compatiblity. More documentation to installation params on http://positionit.org', '', 2006044, 0, 0),
(28831, 0, 'positionit', 1, '2.6.45', 1904, 56, 'positionIt', 'Creates forms, mailforms or whole web processes visually by drag & drop. Easy to use, saves much time. For documentation see http://positionit.org', 2, 0, 4, 1298064368, 'a:1:{s:7:"depends";a:1:{s:18:"static_info_tables";s:0:"";}}', 'Ososoft GmbH', 'info@ososoft.de', 'ososoft', 'cecfea0ff924dd4b27711407fa5b375c', 'Small bugs fixed. New features: custom validation, HTML object available, added Dutch language (thx to Lars from METMEER!). Extension is stable now. More documentation will follow in the next days on http://positionit.org', '', 2006045, 0, 0),
(28832, 0, 'positionit', 1, '2.6.46', 1904, 48, 'positionIt', 'Creates forms, mailforms or whole web processes visually by drag & drop. Easy to use, saves much time. For documentation see http://positionit.org', 2, 0, 4, 1298411729, 'a:1:{s:7:"depends";a:1:{s:18:"static_info_tables";s:0:"";}}', 'Ososoft GmbH', 'info@ososoft.de', 'ososoft', '5f3ac1fb08504867ab823e44b4f21fe2', 'Added russian language (thx to Andrei Aksenov!)', '', 2006046, 0, 0),
(28833, 0, 'positionit', 1, '2.6.47', 1904, 52, 'positionIt', 'Creates forms, mailforms or whole web processes visually by drag & drop. Easy to use, saves much time. For documentation see http://positionit.org', 2, 0, 4, 1298640201, 'a:1:{s:7:"depends";a:1:{s:18:"static_info_tables";s:0:"";}}', 'Ososoft GmbH', 'info@ososoft.de', 'ososoft', 'd048f31007c02a6e4841602132f9692c', 'Small bugs fixed. Insertion of database data through business logic improved.', '', 2006047, 0, 0),
(28834, 0, 'positionit', 1, '2.6.48', 1904, 42, 'positionIt', 'Creates forms, mailforms or whole web processes visually by drag & drop. Easy to use, saves much time. For documentation see http://positionit.org', 2, 0, 4, 1299513088, 'a:1:{s:7:"depends";a:1:{s:18:"static_info_tables";s:0:"";}}', 'Ososoft GmbH', 'info@ososoft.de', 'ososoft', '5a6652886be3e13f911192c8592df4fa', 'New features: input field formatting, object fonts text alignment, E-Mail encoding. Several usability improvements. Small bugs fixed.', '', 2006048, 0, 0),
(28835, 0, 'positionit', 1, '2.6.49', 1904, 50, 'positionIt', 'Creates forms, mailforms or whole web processes visually by drag & drop. Easy to use, saves much time. For documentation see http://positionit.org', 2, 0, 4, 1299686370, 'a:1:{s:7:"depends";a:1:{s:18:"static_info_tables";s:0:"";}}', 'Ososoft GmbH', 'info@ososoft.de', 'ososoft', 'fac9fc32ab5b44233be57e8b9751df1a', 'Small bugs fixed', '', 2006049, 0, 0),
(28836, 0, 'positionit', 1, '2.6.50', 1904, 51, 'positionIt', 'Creates forms, mailforms or whole web processes visually by drag & drop. Easy to use, saves much time. For documentation see http://positionit.org', 2, 0, 4, 1299871602, 'a:1:{s:7:"depends";a:1:{s:18:"static_info_tables";s:0:"";}}', 'Ososoft GmbH', 'info@ososoft.de', 'ososoft', '9c063953a130e9249e87338d55e4d3ba', 'Small bugs fixed. Bug with UTF-8 e-mails fixed.', '', 2006050, 0, 0),
(28837, 0, 'positionit', 1, '2.6.51', 1904, 58, 'positionIt', 'Creates forms, mailforms or whole web processes visually by drag & drop. Easy to use, saves much time. For documentation see http://positionit.org', 2, 0, 4, 1300141106, 'a:1:{s:7:"depends";a:1:{s:18:"static_info_tables";s:0:"";}}', 'Ososoft GmbH', 'info@ososoft.de', 'ososoft', 'ad12b524cd159cb7d8b3d78ddecd78e7', 'New feature: css class for editor area. Small bugs fixed.', '', 2006051, 0, 0),
(28838, 0, 'positionit', 1, '2.6.52', 1904, 26, 'positionIt', 'Creates forms, mailforms or whole web processes visually by drag & drop. Easy to use, saves much time. For documentation see http://positionit.org', 2, 0, 4, 1300787893, 'a:1:{s:7:"depends";a:1:{s:18:"static_info_tables";s:0:"";}}', 'Ososoft GmbH', 'info@ososoft.de', 'ososoft', '88e3c545c876b2d2eaf1e2d9a1971a04', 'New feature: css and js files can be assigned to steps. Several bugfixes and usability improvements. Upgrade note: a new database table was added, please use the Extmanager to add it.', '', 2006052, 0, 0),
(28839, 0, 'positionit', 1, '2.6.53', 1904, 53, 'drop form generator', 'Creates forms, surveys, quizzes, mailforms or whole web processes visually by drag & drop. Easy to use, many features. Form/Process data can be passed to or from programming code at every time. For documentation see http://positionit.org', 2, 0, 4, 1301073066, 'a:1:{s:7:"depends";a:1:{s:18:"static_info_tables";s:0:"";}}', 'Ososoft GmbH', 'info@ososoft.de', 'ososoft', 'd8758591a06c422bc0d2399fe271be46', 'Fixed a bug on session data handling with changed technical names.', '', 2006053, 0, 0),
(28840, 0, 'positionit', 1, '2.6.54', 1904, 44, 'drop form generator', 'Creates multilanguage forms, surveys, quizzes, mailforms or whole web processes visually by drag & drop. Easy to use, many features. Form/Process data can be passed to or from programming code at every time. For documentation see http://positionit.org', 2, 0, 4, 1302280365, 'a:1:{s:7:"depends";a:1:{s:18:"static_info_tables";s:0:"";}}', 'Ososoft GmbH', 'info@ososoft.de', 'ososoft', '9d1984540c4356f22154aa2f44c2d18b', 'Usability improvements on selecting multiple objects. Several bug fixes.', '', 2006054, 0, 0),
(28841, 0, 'positionit', 1, '2.6.60', 1904, 50, 'drop form generator', 'Creates multilanguage forms, surveys, quizzes, mailforms or whole web processes visually by drag & drop. Easy to use, many features. Form/Process data can be passed to or from programming code at every time. For documentation see http://positionit.org', 2, 0, 4, 1303146121, 'a:1:{s:7:"depends";a:1:{s:18:"static_info_tables";s:0:"";}}', 'Ososoft GmbH', 'info@ososoft.de', 'ososoft', 'bac7af613e529fb38b2d19c6d341839b', 'Usability improvements in rules manager and in (de-)assigning objects. Several bugs fixed.', '', 2006060, 0, 0),
(28842, 0, 'positionit', 1, '2.6.61', 1904, 36, 'drop form generator', 'Creates multilanguage forms, surveys, quizzes, mailforms or whole web processes visually by drag & drop. Easy to use, many features. Form/Process data can be passed to or from programming code at every time. For documentation see http://positionit.org', 2, 0, 4, 1303894816, 'a:1:{s:7:"depends";a:1:{s:18:"static_info_tables";s:0:"";}}', 'Ososoft GmbH', 'info@ososoft.de', 'ososoft', '88657403ce1db62cbb59ffeb8a8ce7c3', 'Bugfix release: user defined mail recipients bug fixed, validating while going back in a process bug fixed, minor  e-mail bugs fixed.', '', 2006061, 0, 0),
