(28848, 0, 'positionit', 1, '2.7.25', 1904, 50, 'drop form generator', 'Creates multilanguage forms, surveys, quizzes, mailforms or whole web processes visually by drag & drop. Easy to use, many features. Form/Process data can be passed to or from programming code at every time. For documentation see http://positionit.org', 2, 0, 4, 1306154978, 'a:1:{s:7:"depends";a:1:{s:18:"static_info_tables";s:0:"";}}', 'Ososoft GmbH', 'info@ososoft.de', 'ososoft', '36477046e5c1b78253a5f22c6aefca42', 'Sending mails with 2.7.24 is fully functional but shows a debug output. Users of 2.7.24 please upgrade.', '', 2007025, 0, 0),
