(29229, 0, 'mageconnect', 1, '0.5.0', 175, 0, 'MAGEconnect', 'Easy-to-implement solution of connecting Magento and TYPO3', 1, 0, 3, 1334823831, 'a:1:{s:7:"depends";a:1:{s:3:"cms";s:0:"";}}', 'Bastian Zagar', 'kontakt@magedeveloper.de', 'breep', 'ce108900520376de3b51dc19696ef789', 'New Version 0.5.0.\nThis module now offers product integration of Magentos Products in TYPO3. Use list/grid/detail/single view in your TYPO3 instance!', '', 5000, 0, 0),
