(29422, 0, 'yag', 1, '1.5.0', 3730, 192, 'Yet Another Gallery', 'Scalable, powerfull, easy-to-manage Gallery Extension for TYPO3. Features Frontend with lightbox, Backend Administration Module and Themes for personalization. Uses Caching-Framework for better performance. See http://www.yag-gallery.de for demonstration.', 2, -1, 3, 1331842614, 'a:1:{s:7:"depends";a:6:{s:3:"cms";s:0:"";s:7:"extbase";s:5:"1.3.0";s:5:"fluid";s:5:"1.3.0";s:10:"pt_extlist";s:5:"0.5.0";s:10:"pt_extbase";s:5:"0.1.4";s:5:"typo3";s:11:"4.5.0-0.0.0";}}', 'Daniel Lienert, Michael Knoll', 'daniel@lienert.cc, mimi@kaktusteam.de', 'daniellienert', 'dd6b04935adca07736b7956a4f1351d4', 'This release replaces the old lightbox with a fancybox in a fresh design.  We also killed a load of bugs. Thanks to all bug reporters!', '', 1005000, 0, 0),
(29423, 0, 'yag', 1, '1.5.1', 3730, 0, 'Yet Another Gallery', 'Scalable, powerfull, easy-to-manage Gallery Extension for TYPO3. Features Frontend with lightbox, Backend Administration Module and Themes for personalization. Uses Caching-Framework for better performance. See http://www.yag-gallery.de for demonstration.', 2, -1, 3, 1346671596, 'a:1:{s:7:"depends";a:6:{s:3:"cms";s:0:"";s:7:"extbase";s:5:"1.3.0";s:5:"fluid";s:5:"1.3.0";s:10:"pt_extlist";s:9:"0.5.0-dev";s:10:"pt_extbase";s:5:"0.1.4";s:5:"typo3";s:11:"4.5.0-0.0.0";}}', 'Daniel Lienert, Michael Knoll', 'daniel@lienert.cc, mimi@kaktusteam.de', 'daniellienert', 'df6714b5f33faf5fa4793423cb931e37', 'The T3CON12-ASIA Release!\r\n\r\nFixed a lot of Bugs, thanks for your bug-reports and patches:\r\n39211. Now missing directory is re-created if origs directory is deleted and file-not-found images\r\ncan be created within this newly created directory.\r\n37239 CS', '', 1005001, 0, 0),
(29424, 0, 'yag', 1, '1.5.2', 3730, 0, 'Yet Another Gallery', 'Scalable, powerfull, easy-to-manage Gallery Extension for TYPO3. Features Frontend with lightbox, Backend Administration Module and Themes for personalization. Uses Caching-Framework for better performance. See http://www.yag-gallery.de for demonstration.', 2, -1, 3, 1346654384, 'a:1:{s:7:"depends";a:6:{s:3:"cms";s:0:"";s:7:"extbase";s:5:"1.3.0";s:5:"fluid";s:5:"1.3.0";s:10:"pt_extlist";s:9:"0.5.0-dev";s:10:"pt_extbase";s:5:"0.1.4";s:5:"typo3";s:11:"4.5.0-0.0.0";}}', 'Daniel Lienert, Michael Knoll', 'daniel@lienert.cc, mimi@kaktusteam.de', 'daniellienert', '681a2a6d01b3134e796da9e41210b9ad', 'Fixed a lot of Bugs, thanks for your bug-reports and patches:\n39211. Now missing directory is re-created if origs directory is deleted and file-not-found images can be created within this newly created directory.\n37239 CSS does not align album/gallery d', '', 1005002, 0, 0),
