(29491, 0, 'tinysource', 1, '1.0.1', 133, 51, 'Tiny Source', 'The tinysource extension is a small extension which compresses the output source code of every page. Basically it removes line breaks, tabs, comments and double spaces. The setup of tinysource allows to configure which of these strip-methods should be use', 2, 0, 2, 1299792101, 'a:0:{}', 'Armin Ruediger Vieweg', 'info@professorweb.de', 'professorweb', '779591513d1c305032faccd97968a0bb', 'Changed some typos in documentation and emconf. Thanks to Jens Wellmeyer for his corrections.', 'Professor Web - Webdesign Blog', 1000001, 0, 0);
INSERT INTO `tx_extensionmanager_domain_model_extension` (`uid`, `pid`, `extension_key`, `repository`, `version`, `alldownloadcounter`, `downloadcounter`, `title`, `description`, `state`, `review_state`, `category`, `last_updated`, `serialized_dependencies`, `author_name`, `author_email`, `ownerusername`, `md5hash`, `update_comment`, `authorcompany`, `integer_version`, `current_version`, `lastreviewedversion`) VALUES
(29492, 0, 'tinysource', 1, '1.0.2', 133, 59, 'Tiny Source', 'The tinysource extension is a small extension which compresses the output source code of every page. Basically it removes line breaks, tabs, comments and double spaces. The setup of tinysource allows to configure which of these strip-methods should be use', 2, 0, 2, 1311082193, 'a:0:{}', 'Armin Ruediger Vieweg', 'info@professorweb.de', 'professorweb', '98a24e6a7f981b941fdeb2a2dbd801a8', 'Fixed a bug which appears if config.disableAllHeaderCode is enabled. If this option is enabled, tinysource will be disabled.', 'Professor Web - Webdesign Blog', 1000002, 0, 0),
(29493, 0, 'tinysource', 1, '2.0.0', 133, 0, 'Tiny Source', 'Compresses the output source code of every page by removing line breaks, tabs, comments and double spaces. Highly configurable. Works with static file cache extensions.', 2, 0, 2, 1354813740, 'a:0:{}', 'Armin Ruediger Vieweg', 'armin@v.ieweg.de', 'professorweb', 'f3feb04067f3579c7340d86cb0ad0603', 'New major version of tinysource extension. Works now together with static file cache extensions. Adds customReplacements. Some more improvements. See documentation for further informations. Thanks to Dennis Rmmich for his support!', '', 2000000, 0, 0),
(29494, 0, 'tinysource', 1, '2.0.1', 133, 0, 'Tiny Source', 'Compresses the output source code of every page by removing line breaks, tabs, comments and double spaces. Highly configurable. Works with static file cache extensions.', 2, 0, 2, 1355694552, 'a:0:{}', 'Armin Ruediger Vieweg', 'armin@v.ieweg.de', 'professorweb', '46826e9da02535d0ed4df012f7fa0f25', 'Fixed a major bug which blocked the whole tinysource functionality on most of installations.', '', 2000001, 0, 0),
(29495, 0, 'tinysource', 1, '2.1.0', 133, 0, 'Tiny Source', 'Compresses the output source code of every page by removing line breaks, tabs, comments and double spaces. Highly configurable. Works with static file cache extensions.', 2, 0, 2, 1356085242, 'a:0:{}', 'Armin Ruediger Vieweg', 'armin@v.ieweg.de', 'professorweb', 'c80c84c13119da6320e8a5bcc2375690', 'Small christmas gift for all tinysource users. This version fixes a major bug with stripping comments. It had in previous versions the effect that user_int and additional headerdata got stripped, which causes errors. An update to this version is strongly ', '', 2001000, 0, 0),
(29496, 0, 'tinysource', 1, '2.1.1', 133, 0, 'Tiny Source', 'Compresses the output source code of every page by removing line breaks, tabs, comments and double spaces. Highly configurable. Works with static file cache extensions.', 2, 0, 2, 1357812484, 'a:0:{}', 'Armin Ruediger Vieweg', 'armin@v.ieweg.de', 'professorweb', 'ccdbda61796dc05e0ddea70872a88e94', 'Small bug fix, if no customReplacement has been set.', '', 2001001, 0, 0),
(29497, 0, 'tinysource', 1, '2.1.2', 133, 0, 'Tiny Source', 'Compresses the output source code of every page by removing line breaks, tabs, comments and double spaces. Highly configurable. Works with static file cache extensions.', 2, 0, 2, 1366625214, 'a:0:{}', 'Armin Ruediger Vieweg', 'armin@v.ieweg.de', 'professorweb', '719d58f795de91b123d1f55bc2b987d4', 'Fixed a bug with very long source code. Using php string functions instead of preg_match_all to avoid this issue.', '', 2001002, 0, 0),
(29498, 0, 'tinysource', 1, '3.0.0', 133, 0, 'Tiny Source', 'Compresses the output source code of every page by removing line breaks, tabs, comments and double spaces. Highly configurable. Works with static file cache extensions.', 2, 0, 2, 1397036794, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"4.5.0-6.1.99";}}', 'Armin Ruediger Vieweg', 'armin@v.ieweg.de', 'professorweb', '067dc89704a1ba205566a6a9a30f103d', 'Small fixes. This version works now with TYPO3 6.2', '', 3000000, 0, 0),
(29499, 0, 'tinysource', 1, '3.0.1', 133, 0, 'Tiny Source', 'Compresses the output source code of every page by removing line breaks, tabs, comments and double spaces. Highly configurable. Works with static file cache extensions.', 2, 0, 2, 1400491135, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"4.5.0-6.2.99";}}', 'Armin Ruediger Vieweg', 'armin@v.ieweg.de', 'professorweb', 'e5612140262cb5bd55cd51e167219cfe', 'Fixed wrong em_conf dependency for TYPO3. This version is compatible for TYPO3 6.2', '', 3000001, 0, 0),
(29500, 0, 'tinysource', 1, '4.0.0', 133, 0, 'Tiny Source', 'Compresses the output source code of every page by removing line breaks, tabs, comments and double spaces. Highly configurable. Works with static file cache extensions.', 2, 0, 2, 1450104326, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.2.0-7.6.99";}}', 'Armin Ruediger Vieweg', 'armin@v.ieweg.de', 'professorweb', '129432bd324ef7fb10e610a31846693c', 'TYPO3 7.6 LTS compatibility.', '', 4000000, 0, 0),
(29501, 0, 'tinysource', 1, '4.99.99', 133, 0, 'Tiny Source', 'Tinysource has been merged with EXT:min. Use this extension instead. https://typo3.org/extensions/repository/view/min/', 5, 0, 2, 1482971305, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:13:"6.2.0-8.99.99";}}', 'Armin Ruediger Vieweg', 'armin@v.ieweg.de', 'professorweb', '8067cc204fa52b6217894246afe0cce8', 'Tinysource is outdated and has been merged with EXT:min. Use this extension instead. https://typo3.org/extensions/repository/view/min/', '', 4099099, 1, 0),
