(29819, 0, 'cenoshop', 1, '0.1.1', 343, 25, 'Cenoshop', 'Typo3 shop system, complete with products, options, price lists, supplier ordes, replenishment calculations, profits and loss, catalog generators.', 0, 0, 3, 1301660131, 'a:1:{s:7:"depends";a:2:{s:3:"cms";s:0:"";s:18:"static_info_tables";s:5:"2.2.0";}}', 'Viktor Bauer', 'typo3@cenotaphe.net', 'cenotaphe', '3a344b32aed9c6bdcc4bc7222c7305cf', 'Documentation update. The rendering on the typo3 "read online" documentatation should now be ok.', '', 1001, 0, 0),
(29820, 0, 'cenoshop', 1, '0.1.2', 343, 22, 'Cenoshop', 'Typo3 shop system, complete with products, options, price lists, supplier ordes, replenishment calculations, profits and loss, catalog generators.', 0, 0, 3, 1301917546, 'a:1:{s:7:"depends";a:2:{s:3:"cms";s:0:"";s:18:"static_info_tables";s:5:"2.2.0";}}', 'Viktor Bauer', 'typo3@cenotaphe.net', 'cenotaphe', 'c9e819d8fe2aaad55c69cb4aa796c7d2', 'Documentation update, some bug fixing that caused the sys_log table to grow dramatically, improvement of the components management on the products.', '', 1002, 0, 0),
(29821, 0, 'cenoshop', 1, '0.2.0', 343, 33, 'Cenoshop', 'Typo3 shop system, complete with products, options, price lists, supplier ordes, replenishment calculations, profits and loss, catalog generators.', 0, 0, 3, 1302800120, 'a:1:{s:7:"depends";a:2:{s:3:"cms";s:0:"";s:18:"static_info_tables";s:5:"2.2.0";}}', 'Viktor Bauer', 'typo3@cenotaphe.net', 'cenotaphe', '1746c458938af93eeb9f8dbe85066643', 'Added a filtering on the delivery modes so that only the delivery modes for the usergroup are displayed\r\nAdded the pi5 plugin, that allows to display the delivery modes\r\nleft only the pi1 plugin for easy inserting. All the other ones do not happen so ofte', '', 2000, 0, 0),
(29822, 0, 'cenoshop', 1, '0.2.1', 343, 36, 'Cenoshop', 'Typo3 shop system, complete with products, options, price lists, supplier ordes, replenishment calculations, profits and loss, catalog generators.', 0, 0, 3, 1309961822, 'a:1:{s:7:"depends";a:2:{s:3:"cms";s:0:"";s:18:"static_info_tables";s:5:"2.2.0";}}', 'Viktor Bauer', 'typo3@cenotaphe.net', 'cenotaphe', '64d2a1768a3e0e88e29184490101766d', 'small bugfixes and small function enhancements. Plese refer to dicumentation.', '', 2001, 0, 0),
