(29858, 0, 'org', 1, '1.0.0', 345, 118, 'Organiser', 'Org is a powerfull database for organisations, companies and organisers: You can publish all data in real terms. You can design an organisation with headquarters, locations, staff, events,  news and documents. Org displays data in list, single and calenda', 1, 0, 3, 1301703236, 'a:1:{s:7:"depends";a:3:{s:7:"browser";s:6:"3.6.4-";s:18:"css_styled_content";s:6:"1.0.0-";s:11:"linkhandler";s:6:"0.3.1-";}}', 'Dirk Wildt (Die Netzmacher)', 'http://wildt.at.die-netzmacher.de', 'dwildt', 'f1f0c15143ef70b49545a80ac46c906c', 'INITIAL RELEASE: Publish your news and events with Organiser! Organiser provides a lot of features for handle news, events, staff, headquarters, location and a calendar. Sell your tickets with the integrated shop!', '', 1000000, 0, 0);
INSERT INTO `tx_extensionmanager_domain_model_extension` (`uid`, `pid`, `extension_key`, `repository`, `version`, `alldownloadcounter`, `downloadcounter`, `title`, `description`, `state`, `review_state`, `category`, `last_updated`, `serialized_dependencies`, `author_name`, `author_email`, `ownerusername`, `md5hash`, `update_comment`, `authorcompany`, `integer_version`, `current_version`, `lastreviewedversion`) VALUES
(29859, 0, 'org', 1, '2.0.0', 345, 38, 'Organiser', 'Org is a powerfull database for organisations, companies and organisers: You can publish all data in real terms. You can design an organisation with headquarters, locations, staff, events,  news and documents. Org displays data in list, single and calenda', 1, 0, 3, 1313267615, 'a:1:{s:7:"depends";a:3:{s:7:"browser";s:6:"3.7.0-";s:18:"css_styled_content";s:6:"1.0.0-";s:11:"linkhandler";s:6:"0.3.1-";}}', 'Dirk Wildt (Die Netzmacher)', 'http://wildt.at.die-netzmacher.de', 'dwildt', '5671abc7a4960c5a50d5493f5c6bae73', 'NEW FEATURES localisation; record browser for the single view', '', 2000000, 0, 0),
(29860, 0, 'org', 1, '2.0.2', 345, 62, 'Organiser', 'Org is a powerfull database for organisations, companies and organisers: You can publish all data in real terms. You can design an organisation with headquarters, locations, staff, events,  news and documents. Org displays data in list, single and calenda', 1, 0, 3, 1314298118, 'a:1:{s:7:"depends";a:3:{s:7:"browser";s:6:"3.7.0-";s:18:"css_styled_content";s:6:"1.0.0-";s:11:"linkhandler";s:6:"0.3.1-";}}', 'Dirk Wildt (Die Netzmacher)', 'http://wildt.at.die-netzmacher.de', 'dwildt', 'aab362b1ec431a418c95bb79644943c4', 'Improvement: TypoScript template is adapted to browser version 3.7: a-z_Browser and pageBrowser are moved to navigation', '', 2000002, 0, 0),
(29861, 0, 'org', 1, '2.0.4', 345, 127, 'Organiser', 'Org is a powerfull database for organisations, companies and organisers: You can publish all data in real terms. You can design an organisation with headquarters, locations, staff, events,  news and documents. Org displays data in list, single and calenda', 1, 0, 3, 1318186871, 'a:1:{s:7:"depends";a:3:{s:7:"browser";s:6:"3.7.0-";s:18:"css_styled_content";s:6:"1.0.0-";s:11:"linkhandler";s:6:"0.3.1-";}}', 'Dirk Wildt (Die Netzmacher)', 'http://wildt.at.die-netzmacher.de', 'dwildt', 'dcc49a89147bd5064e9e24b059aa28fb', 'Improvement: new database field datetime end in calendar\r\n', '', 2000004, 0, 0),
(29862, 0, 'org', 1, '2.1.8', 345, 0, 'Organiser', 'Org is a powerfull database for organisations, companies and organisers: You can publish all data in real terms. You can design an organisation with headquarters, locations, staff, events,  news and downloads. Org displays data in list, single and calendar views.Org hasnt any PHP code. It is  based on the TYPO3-Fronend-Engine Browser. You can control and develop org by plugins and TypoScript.', 1, 0, 3, 1354234442, 'a:2:{s:7:"depends";a:6:{s:7:"browser";s:13:"3.9.14-3.9.14";s:11:"cps_tcatree";s:11:"0.3.0-0.0.0";s:18:"css_styled_content";s:11:"1.0.0-0.0.0";s:11:"linkhandler";s:11:"0.3.1-0.0.0";s:18:"static_info_tables";s:11:"2.2.0-0.0.0";s:7:"wt_cart";s:11:"1.3.9-0.0.0";}s:9:"conflicts";a:1:{s:13:"css_filelinks";s:6:"-0.0.0";}}', 'Dirk Wildt (Die Netzmacher)', 'http://wildt.at.die-netzmacher.de', 'dwildt', 'dcba1605e8bbde50702daf10caaeed4f', 'NEW FEATURES download module; headquarters are prepaired for BrowserMaps; multiple managers for departments UPDATE for Browser - TYPO3 without PHP - version 4.1.x', '', 2001008, 0, 0),
(29863, 0, 'org', 1, '3.0.0', 345, 0, 'Organiser', 'Org is a powerfull database for organisations, companies and organisers: You can publish all data in real terms. You can design an organisation with headquarters, locations, staff, events,  news and downloads. Org displays data in list, single and calendar views.Org hasnt any PHP code. It is  based on the TYPO3-Fronend-Engine Browser. You can control and develop org by plugins and TypoScript.', 1, 0, 3, 1355521855, 'a:2:{s:7:"depends";a:6:{s:7:"browser";s:11:"4.2.0-4.2.0";s:11:"cps_tcatree";s:11:"0.4.1-0.0.0";s:18:"css_styled_content";s:11:"1.0.0-0.0.0";s:11:"linkhandler";s:11:"0.3.1-0.0.0";s:18:"static_info_tables";s:11:"2.3.0-0.0.0";s:7:"wt_cart";s:11:"1.4.6-1.4.6";}s:9:"conflicts";a:1:{s:13:"css_filelinks";s:6:"-0.0.0";}}', 'Dirk Wildt (Die Netzmacher)', 'http://wildt.at.die-netzmacher.de', 'dwildt', '0ec9b50e83f97c97e3f9b086d07c72b9', 'NEW FEATURES: HTML5 support. Two HTML templates for all views (before 15). jQuery theme support. News categories as tree view.', '', 3000000, 0, 0),
