(29936, 0, 'mn_mysql2json', 1, '1.0.0', 133, 20, 'MySQL to JSON', 'An eID call of any table in MySQL to get the data back as JSON. The tables in MySQL that are allowed are configurable, defaults are tt_content and pages.', 1, -1, 4, 1302508250, 'a:0:{}', 'Mattias Nilsson', 'tollepjaer@gmail.com', 'mattias.nilsson', '735ab486d30cdda2d65270485bb51f9a', '', '', 1000000, 0, 0),
(29937, 0, 'mn_mysql2json', 1, '0.0.1', 133, 6, 'MySQL to JSON', 'An eID call of any table in MySQL to get the data back as JSON. The tables in MySQL that are allowed are configurable, defaults are tt_content and pages. The request is being made like this:\n\nhttp://yourdomain/?eIDtx_mnmysql2json_Table&tx_mnmysql2json[ac', 1, -1, 4, 1302947892, 'a:0:{}', 'Mattias Nilsson', 'tollepjaer@gmail.com', 'mattias.nilsson', '0420b047a6e1d645409079eb2fa97c8b', 'Added documentation for how an request is being made in emconf', '', 1, 0, 0),
