(29944, 0, 'w4_ext_shopfinder', 1, '0.0.2', 54, 13, 'W4 Shopfinder', 'Find shops by address and/or geo locale using google maps.', 1, 0, 3, 1302512461, 'a:1:{s:7:"depends";a:5:{s:5:"typo3";s:11:"4.4.4-0.0.0";s:3:"cms";s:0:"";s:15:"w4_ext_geostore";s:0:"";s:7:"extbase";s:6:"1.2.1-";s:5:"fluid";s:6:"1.2.1-";}}', 'Jens Schulzendorf', 'jschulzendorf@w-4.ch', 'jschulzendorf', '2ec86bbdde0767bb727aae0755f305b3', 'inital import', 'W4 Services GmbH', 2, 0, 0),
(29945, 0, 'w4_ext_shopfinder', 1, '0.0.3', 54, 41, 'W4 Shopfinder', 'The Shopfinder gives your customer the possibility to find the exact locations of your branches. Its based on Google Maps and doesnt need any plugins. Therefore its compatible with all common browsers and mobile tools what offers you nearly unlimited o', 1, 0, 3, 1302606019, 'a:0:{}', 'Jens Schulzendorf', 'jschulzendorf@w-4.ch', 'jschulzendorf', '71aec737d8f470f3d3886f9a0a290370', 'update description', 'W4 Services GmbH', 3, 1, 0),
