(29947, 0, 'w4_ext_geolocator', 1, '0.0.3', 61, 48, 'W4 Geolocator', 'The Geolocator allows your customers to get an interactive overview of your locations and branches. Its highly configurable and can be modulated to your wishes and desires. Since the Geolocator is built on  modern Web-standards only (like HTML 5) , its ', 1, 0, 3, 1302606042, 'a:1:{s:7:"depends";a:5:{s:5:"typo3";s:11:"4.4.4-0.0.0";s:3:"cms";s:0:"";s:15:"w4_ext_geostore";s:0:"";s:7:"extbase";s:6:"1.2.1-";s:5:"fluid";s:6:"1.2.1-";}}', 'Jens Schulzendorf', 'jschulzendorf@w-4.ch', 'jschulzendorf', 'ee37e84b1839340da2c28373231246ac', 'update description', 'W4 Services GmbH', 3, 1, 0),
