(30089, 0, 'jasmine', 1, '0.1.0', 24, 24, 'Jasmine BDD', 'Jasmine is a behavior-driven development framework for testing your JavaScript code. It does not depend on any other JavaScript frameworks. It does not require a DOM. And it has a clean, obvious syntax so that you can easily write tests. ', 0, 0, 4, 1303509390, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Rens Admiraal', 'r.admiraal@drecomm.nl', 'heiko-hardt', '6a60719228e044f74bde2d2b623a4e61', 'Initial release', '', 1000, 1, 0),
(30090, 0, 'realurlautoconf', 1, '2.0.0', 158, 158, 'Typical autoconf for realurl', 'Adds typical autoconf values to realurl when autoconf enabled: tt_news, no_cache, cal. Take language from title instead of iso code.', 2, 0, 4, 1303832287, 'a:1:{s:7:"depends";a:2:{s:3:"cms";s:0:"";s:7:"realurl";s:0:"";}}', 'Stefan Regniet', 's.regniet@notos-media.de', 'notosmedia', '96e020bce6a8df78cc6ebb65a902159d', '', '', 2000000, 1, 0),
(30091, 0, 'html5iframe', 1, '1.0.0', 107, 107, 'HTML5 Iframe Extension', 'Iframe with html5 parameters like seamless, sandbox and others. Can also render HTML4/XHTML iframes. Based on extbase/fluid. Easy addition of parameters and global URL setting in TYPOScript.', 1, 0, 3, 1303901309, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Stefan Regniet', 's.regniet@notos-media.de', 'willky', '2fe1e47637022e99ab6746915981589d', 'First upload', '', 1000000, 0, 0),
(30092, 0, 'html5iframe', 1, '3.0.0', 107, 0, 'HTML5 Iframe Extension', 'Now 6.0 ready (backwards compatible). Iframe with html5 parameters like seamless, sandbox and others. Can also render HTML4/XHTML iframes. Based on extbase/fluid. Easy addition of parameters and global URL setting in TYPOScript.', 1, 0, 3, 1363274866, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:12:"4.5.0-6.0.99";s:7:"extbase";s:5:"1.3.0";s:5:"fluid";s:0:"";}}', 'Stefan Regniet, TechDivision GmbH', 's.regniet@techdivision.com', 'willky', '65be3cff1644e9540f26e68b7bec9ea1', 'Updated for 6.0\nRemoved tt_content wizicon\nSeveral minor bugfixes ', '', 3000000, 1, 0),
