(30315, 0, 'calendarize', 1, '2.5.0', 0, 0, 'Calendarize - Event Management', 'Create a structure for timely controlled tables (e.g. events) and one plugin for the different output of calendar views (list, detail, month, year, day, week...). The extension is shipped with one default event table, but you can also "calendarize" your own table/model. It is completely independent and configurable! Use your own models as event items in this calender. Development on https://github.com/lochmueller/calendarize', 2, 0, 2, 1477482460, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:13:"6.2.0-8.99.99";s:3:"php";s:11:"5.5.0-0.0.0";s:10:"autoloader";s:11:"2.0.0-0.0.0";}}', 'Tim Lochmller', 'tim@fruit-lab.de', 'spyker', 'cb06db1a15b2d0b7e94b77698152108e', 'News hanlding of include, exclude and override events (Run Install Tool Update for migration), polish translations', '', 2005000, 0, 0),
(30316, 0, 'calendarize', 1, '1.0.0', 0, 0, 'Calendarize', 'Create a structure for timely controlled tables and plugins for the different output. The extension is shipped with one default event table, but the target table is completely independent and configurable from this extension. Use your own Models as Event items in this calender. Experimental concept at the moment / Dev on https://github.com/lochmueller/calendarize', 0, 0, 4, 1413054388, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"6.2.0-6.2.99";s:10:"autoloader";s:11:"1.2.1-0.0.0";}}', 'Tim Lochmller', 'tim@fruit-lab.de', 'spyker', 'e435ed19de2bc67ce4f42db1ef75b1db', 'First Release to get a look into the concept of "calendarize" event structures... do not hesitate to ask questions!', '', 1000000, 0, 0),
(30317, 0, 'calendarize', 1, '1.0.2', 0, 0, 'Calendarize', 'Create a structure for timely controlled tables and one plugin for the different output. The extension is shipped with one default event table, but the target table is completely independent and configurable from this extension. Use your own Models as Event items in this calender. Experimental concept at the moment / Dev on https://github.com/lochmueller/calendarize', 0, 0, 4, 1422483944, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"6.2.0-6.2.99";s:10:"autoloader";s:11:"1.2.1-0.0.0";}}', 'Tim Lochmller', 'tim@fruit-lab.de', 'spyker', '6e81e68fe4df3f451b4615420ab176ea', 'Fix ICS View, more stable index process, fix bug in time table service', '', 1000002, 0, 0),
(30318, 0, 'calendarize', 1, '1.1.0', 0, 0, 'Calendarize', 'Create a structure for timely controlled tables and one plugin for the different output: calendar. The extension is shipped with one default event table, but the target table is completely independent and configurable from this extension. Use your own Models as Event items in this calender. Experimental concept at the moment / Dev on https://github.com/lochmueller/calendarize', 0, 0, 4, 1423586158, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"6.2.0-6.2.99";s:10:"autoloader";s:11:"1.2.1-0.0.0";}}', 'Tim Lochmller', 'tim@fruit-lab.de', 'spyker', '89cb3a4c7dba4c5e62b0d48bc3bb0718', 'Many L10N cleanups, smarter configuration titles, fix date range selection, create search structure (WIP), TCA cleanups (no group withour configuration), PhpDoc cleanups....', '', 1001000, 0, 0),
(30319, 0, 'calendarize', 1, '1.1.1', 0, 0, 'Calendarize', 'Create a structure for timely controlled tables and one plugin for the different output: calendar. The extension is shipped with one default event table, but the target table is completely independent and configurable from this extension. Use your own Models as Event items in this calender. Experimental concept at the moment / Dev on https://github.com/lochmueller/calendarize', 0, 0, 4, 1424850600, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"6.2.0-6.2.99";s:10:"autoloader";s:11:"1.5.5-0.0.0";}}', 'Tim Lochmller', 'tim@fruit-lab.de', 'spyker', '52c1b87960f7dca9120998bb92f93eec', 'Prepare search functions, TCA fixes, remove absolute paths, use the current autoloader ext nd fix labels (also hook)... Thanks for the feedback!', '', 1001001, 0, 0),
