(30365, 0, 'calendarize', 1, '3.1.2', 0, 0, 'Calendarize - Event Management', 'Create a structure for timely controlled tables (e.g. events) and one plugin for the different output of calendar views (list, detail, month, year, day, week...). The extension is shipped with one default event table, but you can also "calendarize" your own table/model. It is completely independent and configurable! Use your own models as event items in this calender. Development on https://github.com/lochmueller/calendarize', 2, 0, 2, 1497250680, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:13:"7.6.0-8.99.99";s:3:"php";s:11:"7.0.0-0.0.0";s:10:"autoloader";s:11:"2.0.0-0.0.0";}}', 'Tim Lochmller', 'tim@fruit-lab.de', 'spyker', 'fd2f9eadc009b2e1d86f4fcf6d81474f', 'Release 3.1.2 Bugfix release', '', 3001002, 1, 0),
(30366, 0, 'fed', 1, '0.9.1', 2210, 6, 'Fluid Extbase Development Framework', 'Previously wildside_extbase. Provides ViewHelpers, Services and a few frontend plugins especially useful when developing Extbase/Fluid extensions.', 2, -1, 4, 1305835606, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'namelesscoder', 'aaa3d100725abe12f2b3ed80fa9592ca', 'This is the extension formerly known as wildside_extbase. Initial release intended to test the new scopes - please report any bugs you encounter.', 'Wildside A/S', 9001, 0, 0),
(30367, 0, 'fed', 1, '0.9.2', 2210, 19, 'Fluid Extbase Development Framework', 'Previously wildside_extbase. Provides ViewHelpers, Services and a few frontend plugins especially useful when developing Extbase/Fluid extensions.', 2, -1, 4, 1305836027, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'namelesscoder', '3fb521fd8234dabd7c12c3c9960d94be', 'Bugfixed ViewHelper class names and occurrences.', 'Wildside A/S', 9002, 0, 0),
(30368, 0, 'fed', 1, '1.3.0', 2210, 5, 'Fluid Extbase Development Framework', 'Previously wildside_extbase. Provides ViewHelpers, Services and a few frontend plugins especially useful when developing Extbase/Fluid extensions.', 2, -1, 4, 1305975406, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'namelesscoder', 'ea09c7058fd5cb05881fc33adeb92920', 'Moved to version 1.3 to match Extbase/Fluid. New Cache, Session and Cooke Control ViewHelpers for temporary use during development.', 'Wildside A/S', 1003000, 0, 0),
(30369, 0, 'fed', 1, '1.3.1', 2210, 12, 'Fluid Extbase Development Framework', 'Previously wildside_extbase. Provides ViewHelpers, Services and a few frontend plugins especially useful when developing Extbase/Fluid extensions.', 2, -1, 4, 1305976425, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'namelesscoder', '37a734e21aa6b0fcbbd6648ec482c96b', '1.3.1: Bugfix Data ViewHelpers', 'Wildside A/S', 1003001, 0, 0),
(30370, 0, 'fed', 1, '1.3.2', 2210, 26, 'Fluid Extbase Development Framework', 'Previously wildside_extbase. Provides ViewHelpers, Services and a few frontend plugins especially useful when developing Extbase/Fluid extensions.', 2, -1, 4, 1306082569, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'namelesscoder', 'b15bad51bee489763ccab6f34e3b8c67', 'Support for "object" and "property" attributes in AJAX Widget ViewHelpers for easier use. Note: Widget JS class and event class refactored.', 'Wildside A/S', 1003002, 0, 0),
(30371, 0, 'fed', 1, '1.3.3', 2210, 11, 'Fluid Extbase Development Framework', 'Previously wildside_extbase. Provides ViewHelpers, Services and a few frontend plugins especially useful when developing Extbase/Fluid extensions.', 2, -1, 4, 1306232361, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'namelesscoder', '946b63272f65238180e0fc1add065b7b', 'Bugfix in FE plugin Flexforms - thanks to Moritz Helten for pointing these out.', 'Wildside A/S', 1003003, 0, 0),
(30372, 0, 'fed', 1, '1.3.4', 2210, 4, 'Fluid Extbase Development Framework', 'Previously wildside_extbase. Provides ViewHelpers, Services and a few frontend plugins especially useful when developing Extbase/Fluid extensions.', 2, -1, 4, 1306274592, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'namelesscoder', '615300bf927c5d2127d7a922549e2933', 'Important bugfix in Style ViewHelper when css used inline. Restored incorrectly refactored functions to data.sort ViewHelper. Thanks to Moritz Helten once again.', 'Wildside A/S', 1003004, 0, 0),
(30373, 0, 'fed', 1, '1.3.5', 2210, 12, 'Fluid Extbase Development Framework', 'Previously wildside_extbase. Provides ViewHelpers, Services and a few frontend plugins especially useful when developing Extbase/Fluid extensions.', 2, -1, 4, 1306275350, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'namelesscoder', '1ce0101bccb73d60987b59d9c174a24c', 'Shifted from call_user_func to call_user_func_array in data.func ViewHelper in order to properly support multivalued argument arrays.', 'Wildside A/S', 1003005, 0, 0),
(30374, 0, 'fed', 1, '1.3.6', 2210, 19, 'Fluid Extbase Development Framework', 'Previously wildside_extbase. Provides ViewHelpers, Services and a few frontend plugins especially useful when developing Extbase/Fluid extensions.', 2, -1, 4, 1306373463, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'namelesscoder', 'e555c84d7216a61219e2219d5586b0ce', 'Implemented t3editor HTML/Fluid fields in the included frontend plugins. Class which renders this type of field can be used in your FlexForms etc. As always, see manual.', 'Wildside A/S', 1003006, 0, 0),
(30375, 0, 'fed', 1, '1.3.7', 2210, 2, 'Fluid Extbase Development Framework', 'Previously wildside_extbase. Provides ViewHelpers, Services and a few frontend plugins especially useful when developing Extbase/Fluid extensions.', 2, -1, 4, 1306444378, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'namelesscoder', '146c2b6fa32e059ea2e10b9b2e9552e4', 'Added jQuery TabViewHelper to easily make tab groups and individual tabs using very few, very simple tags without the need for custom Javascript. As always, see manual for usage example.', 'Wildside A/S', 1003007, 0, 0),
(30376, 0, 'fed', 1, '1.3.8', 2210, 4, 'Fluid Extbase Development Framework', 'Previously wildside_extbase. Provides ViewHelpers, Services and a few frontend plugins especially useful when developing Extbase/Fluid extensions.', 2, -1, 4, 1306444587, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'namelesscoder', '67fa6ae74acfd45c3695ffa5babef13e', 'Bugfix Data SortViewHelper. See changelog and manual for new jQuery TabViewHelper.', 'Wildside A/S', 1003008, 0, 0),
(30377, 0, 'fed', 1, '1.3.9', 2210, 25, 'Fluid Extbase Development Framework', 'Previously wildside_extbase. Provides ViewHelpers, Services and a few frontend plugins especially useful when developing Extbase/Fluid extensions.', 2, -1, 4, 1306446808, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'namelesscoder', 'a1505001bc91a714a6f92b125c8e60cc', 'Simplified arguments and argument checks in jQuery TabViewHelper', 'Wildside A/S', 1003009, 0, 0),
(30378, 0, 'fed', 1, '1.3.10', 2210, 25, 'Fluid Extbase Development Framework', 'Previously wildside_extbase. Provides ViewHelpers, Services and a few frontend plugins especially useful when developing Extbase/Fluid extensions.', 2, -1, 4, 1306615898, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'namelesscoder', 'd4a5d2a4677e4dc64f5c1266bbb46e84', 'New jQuery AccordionViewHelper. Added support for wildcard filename patterns (i.e. .js) in style and script ViewHelpers plus includeFile() in AbstractViewHelper. Manual updated; AbstractViewHelper doc added.', 'Wildside A/S', 1003010, 0, 0),
(30379, 0, 'fed', 1, '1.3.11', 2210, 27, 'Fluid Extbase Development Framework', 'Previously wildside_extbase. Provides ViewHelpers, Services and a few frontend plugins especially useful when developing Extbase/Fluid extensions.', 2, -1, 4, 1306791107, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'namelesscoder', '5b33eeb12be7c3b7be87d4f0c3ad30a9', 'New SASS ViewHelper and Service. Coming VERY soon: ExtJS4 Development Suite with automatic export of Extbase Models to ExtJS4 supporting AJAX CRUD, among other things. Read manual about how this will work.', 'Wildside A/S', 1003011, 0, 0),
(30380, 0, 'fed', 1, '1.3.12', 2210, 27, 'Fluid/Extbase/ExtJS4 Development Framework', 'Provides ViewHelpers, Services and a few frontend plugins especially useful when developing Fluid/Extbase/ExtJS4 extensions.', 2, -1, 4, 1306883764, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'namelesscoder', 'd6eb1331f0cc38fb0c206488955eeb3d', 'Introducing on-the-fly generation of ExtJS4 Model classes based on your Extbase Model objects. Currently works for getting full list of data from server - a fully CRUD-capable version is coming next. See manual.', 'Wildside A/S', 1003012, 0, 0),
(30381, 0, 'fed', 1, '1.3.13', 2210, 21, 'Fluid/Extbase/ExtJS4 Development Framework', 'Provides a lot of ViewHelpers and Services plus a few frontend plugins especially useful when developing Fluid/Extbase/ExtJS4 extensions.', 2, -1, 4, 1306948905, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'namelesscoder', '4caa7cb4425c58d63ffd5794dfbec9b1', 'Greatly revised manual for better structure and more current information. Bugfixes for PDFViewHelper - thanks to Jan Loderhosen for reporting issues.', 'Wildside A/S', 1003013, 0, 0),
(30382, 0, 'fed', 1, '1.3.14', 2210, 28, 'Fluid/Extbase/ExtJS4 Development Framework', 'Official FED web site: http://fedext.net - FED provides a lot of ViewHelpers and Services plus a few frontend plugins especially useful when developing Fluid/Extbase/ExtJS4 extensions.', 2, -1, 4, 1307198359, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'namelesscoder', 'cd0ee745c9323e41a959a1be7498cddd', 'Im very proud to present the brand new, official web site for FED, featuring full documentation and live examples: http://fedext.net - along with a bunch of small bug fixes in ViewHelpers.', 'Wildside A/S', 1003014, 0, 0),
(30383, 0, 'fed', 1, '1.3.15', 2210, 27, 'Fluid/Extbase/ExtJS4 Development Framework', 'Official FED web site: http://fedext.net - FED provides a lot of ViewHelpers and Services plus a few frontend plugins especially useful when developing Fluid/Extbase/ExtJS4 extensions.', 2, -1, 4, 1307385219, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'namelesscoder', '8656f7639633387732db4b2faac30e5a', 'CONTAINS BREAKING CHANGES. Important update notes: http://fedext.net/updates', 'Wildside A/S', 1003015, 0, 0),
(30384, 0, 'fed', 1, '1.3.16', 2210, 21, 'Fluid/Extbase/ExtJS4 Development Framework', 'Official FED web site: http://fedext.net - FED provides a lot of ViewHelpers and Services plus a few frontend plugins especially useful when developing Fluid/Extbase/ExtJS4 extensions.', 2, -1, 4, 1307639253, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'namelesscoder', '504d456cebd55f13bef76a14101749a1', 'ExtJS4 REST CRUD now fully functional - see web site for sandbox example and how-to. FED now contains a "Sandbox" FE plugin you can install and inspect; it examplifies implementation ExtJS4 REST CRUD features.', 'Wildside A/S', 1003016, 0, 0),
(30385, 0, 'fed', 1, '1.3.17', 2210, 17, 'Fluid/Extbase/ExtJS4 Development Framework', 'Official FED web site: http://fedext.net - FED provides a lot of ViewHelpers and Services plus a few frontend plugins especially useful when developing Fluid/Extbase/ExtJS4 extensions.', 2, -1, 4, 1307808390, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'namelesscoder', '8b01626bb4311f00964ea10be272d5e6', 'Added advanced ImageViewHelper - supports wildcard filenames, CSV filenames  path, array filenames, sorting, limiting, clickenlarge etc.', 'Wildside A/S', 1003017, 0, 0);
INSERT INTO `tx_extensionmanager_domain_model_extension` (`uid`, `pid`, `extension_key`, `repository`, `version`, `alldownloadcounter`, `downloadcounter`, `title`, `description`, `state`, `review_state`, `category`, `last_updated`, `serialized_dependencies`, `author_name`, `author_email`, `ownerusername`, `md5hash`, `update_comment`, `authorcompany`, `integer_version`, `current_version`, `lastreviewedversion`) VALUES
(30386, 0, 'fed', 1, '1.3.18', 2210, 11, 'Fluid/Extbase/ExtJS4 Development Framework', 'Official FED web site: http://fedext.net - FED provides a lot of ViewHelpers and Services plus a few frontend plugins especially useful when developing Fluid/Extbase/ExtJS4 extensions.', 2, -1, 4, 1307912762, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'namelesscoder', '0500ec7bf2c44feb9b933d1692126fe6', 'Added Resource ViewHelpers and File Object along with full documentation; see web site. Supported by the FED ImageViewHelper and has backwards compatibility with ViewHelpers string requiring filenames.', 'Wildside A/S', 1003018, 0, 0),
(30387, 0, 'fed', 1, '1.3.19', 2210, 41, 'Fluid/Extbase/ExtJS4 Development Framework', 'Official FED web site: http://fedext.net - FED provides a lot of ViewHelpers and Services plus a few frontend plugins especially useful when developing Fluid/Extbase/ExtJS4 extensions.', 2, -1, 4, 1307969273, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'namelesscoder', '423cab37fa975a6c6022bd7cab205419', 'Hotfix for Resource ViewHelpers, naming conventions changed from plural to singular form.', 'Wildside A/S', 1003019, 0, 0),
(30388, 0, 'fed', 1, '1.3.20', 2210, 39, 'Fluid/Extbase/ExtJS4 Development Framework', 'Official FED web site: http://fedext.net - FED provides a lot of ViewHelpers and Services plus a few frontend plugins especially useful when developing Fluid/Extbase/ExtJS4 extensions.', 2, -1, 4, 1308512918, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'namelesscoder', '73fd24266ef468666ea420460aa91027', 'Proud to present: Fluid Template based FCE feature with virtual FlexForm configuration of FCE settings. Requires ONE single file for a complete FCE definition - see web site. Next version will support insertion of TYPO3 content elements as well.', 'Wildside A/S', 1003020, 0, 0),
(30389, 0, 'fed', 1, '1.3.21', 2210, 27, 'Fluid/Extbase/ExtJS4 Development Framework', 'Official FED web site: http://fedext.net - FED provides a lot of ViewHelpers and Services plus a few frontend plugins especially useful when developing Fluid/Extbase/ExtJS4 extensions.', 2, -1, 4, 1309041674, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'namelesscoder', '2e5faa4f1775d26bce73b7c5d3bd8e41', 'New feature: Zero-config yet highly customizable SOLR AJAX Service and Fluid ViewHelper plus full documentation and live examples. As usual, see web site.', 'Wildside A/S', 1003021, 0, 0),
(30390, 0, 'fed', 1, '1.3.22', 2210, 14, 'Fluid/Extbase/ExtJS4 Development Framework', 'Official FED web site: http://fedext.net - FED provides a lot of ViewHelpers and Services plus a few frontend plugins especially useful when developing Fluid/Extbase/ExtJS4 extensions.', 2, -1, 4, 1309186482, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'namelesscoder', '302bd45a3ba602e1b1abcd0f87818f58', 'Fluid FCE logic simplified and extended to support writing values to fields in tt_content. New approach uses Typoscript instead of records to define location of FCE templates - see http://fedext.net/updates/', 'Wildside A/S', 1003022, 0, 0),
(30391, 0, 'fed', 1, '1.3.23', 2210, 6, 'Fluid/Extbase/ExtJS4 Development Framework', 'Official FED web site: http://fedext.net - FED provides a lot of ViewHelpers and Services plus a few frontend plugins especially useful when developing Fluid/Extbase/ExtJS4 extensions.', 2, -1, 4, 1309207635, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'namelesscoder', '35ad4a74754d83c83830c97afe77e5df', 'Hotfix for Fluid FCE - fixes unhandled exception when using Fluid FCEs. This release also includes basic support for using Content Areas in Fluid FCEs. Sorting still not supported.', 'Wildside A/S', 1003023, 0, 0),
(30392, 0, 'fed', 1, '1.3.24', 2210, 22, 'Fluid/Extbase/ExtJS4 Development Framework', 'Official FED web site: http://fedext.net - FED provides a lot of ViewHelpers and Services plus a few frontend plugins especially useful when developing Fluid/Extbase/ExtJS4 extensions.', 2, -1, 4, 1309208881, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'namelesscoder', '30654e3e7f8f5d12f4bb9f75c7fc6803', 'Another hotfix for Fluid FCE. Rogue shell command had added a nasty whitespace to some ViewHelper files, causing the whitespace to be output in the browser when rendering an FCE.', 'Wildside A/S', 1003024, 0, 0),
(30393, 0, 'fed', 1, '1.3.25', 2210, 23, 'Fluid/Extbase/ExtJS4 Development Framework', 'Official FED web site: http://fedext.net - FED provides a lot of ViewHelpers and Services plus a few frontend plugins especially useful when developing Fluid/Extbase/ExtJS4 extensions.', 2, -1, 4, 1309300761, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'namelesscoder', '2dfe9c7c72744793ed1bff83eebf9787', 'Bugfixes for FlexFormService and Fluid FCE - thanks for Marcel Zweifel for reporting and assisting with bug info. Contains an update to greatly improve BE editing experience for Fluid FCEs.', 'Wildside A/S', 1003025, 0, 0),
(30394, 0, 'fed', 1, '1.3.26', 2210, 24, 'Fluid/Extbase/ExtJS4 Development Framework', 'Official FED web site: http://fedext.net - FED provides a lot of ViewHelpers and Services plus a few frontend plugins especially useful when developing Fluid/Extbase/ExtJS4 extensions.', 2, -1, 4, 1309449406, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'namelesscoder', '3b44c1fb2d32d89e9c2c83b6202b25ca', 'Introducing Fluid FCE Backend Editing Grids - Backend-layout-style control over the representation of content areas. Documentation added on web site along with a whole bunch of downloadable example FCEs ready to use.', 'Wildside A/S', 1003026, 0, 0),
(30395, 0, 'fed', 1, '1.3.27', 2210, 45, 'Fluid/Extbase/ExtJS4 Development Framework', 'Official FED web site: http://fedext.net - FED provides a lot of ViewHelpers and Services plus a few frontend plugins especially useful when developing Fluid/Extbase/ExtJS4 extensions.', 2, -1, 4, 1309540561, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'namelesscoder', 'd95136c63ed5b916a2564ec4089eca55', 'Added extended IfViewHelper and SwitchCaseViewHelpers along with documentation on web site. IfViewHelper supports complex expressions, arithmetic expressions and string comparisons - and is backwards compatible with Fluid IfViewHelper.', 'Wildside A/S', 1003027, 0, 0),
(30396, 0, 'fed', 1, '1.3.28', 2210, 34, 'Fluid Extbase Development Framework', 'Extensive library of Plugins, ViewHelpers and Services allowing usage of Fluid Content Elements, automatically generated ExtJS4 Stores and Models, REST Controller features for Extbase and so much more. Documentation web site: http://fedext.net', 2, -1, 4, 1310333928, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'namelesscoder', 'ca5e550ba11d0260d501ec96742a5068', 'Many bugfixes. New feature: other extensions may their own add Fluid FCEs to selector through Typoscript, multiple paths to FCE templates now also supported. See web site; FCE implementation guide.', 'Wildside A/S', 1003028, 0, 0),
(30397, 0, 'fed', 1, '1.3.29', 2210, 51, 'Fluid Extbase Development Framework', 'Extensive library of Plugins, ViewHelpers and Services allowing usage of Fluid Content Elements, automatically generated ExtJS4 Stores and Models, REST Controller features for Extbase and so much more. Documentation web site: http://fedext.net', 2, -1, 4, 1310939737, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'namelesscoder', 'f2ddacd902b71ddc481db35338a56e94', 'Introducing Fluid Page feature. Extensions building on FED may now provide entire Layout/Template/Partial structures which can be selected as Page layouts. See web site.', 'Wildside A/S', 1003029, 0, 0),
(30398, 0, 'fed', 1, '1.3.30', 2210, 14, 'Fluid Extbase Development Framework', 'Extensive library of Configuration, Plugins, ViewHelpers and Services for making Fluid Page Templates, Fluid Content Elements, AJAX form validations, AJAX-REST-enabled ExtJS4 Models and so much more. Web site: http://fedext.net', 1, -1, 4, 1311267683, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'namelesscoder', '505fbb250ed2863e3358cc2d64294fe4', 'Major Fluid FCE update: BE previews for FCEs, finished content area support and more - but unfortunately a few breaking changes have also been introduced. See update notes on web site for full information. Docs also updated correspondingly.', 'Wildside A/S', 1003030, 0, 0),
(30399, 0, 'fed', 1, '1.3.31', 2210, 32, 'Fluid Extbase Development Framework', 'Extensive library of Configuration, Plugins, ViewHelpers and Services for making Fluid Page Templates, Fluid Content Elements, AJAX form validations, AJAX-REST-enabled ExtJS4 Models and so much more. Web site: http://fedext.net', 1, -1, 4, 1311285125, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'namelesscoder', 'df6819337573bdc758fe66c00f075130', 'HOTFIX for 1.3.30 which had compatibility issues with Fluid 1.3 in regards to using dynamic variables as layout name in backend. Until a workaround is found, BE previews of FCEs is disabled (all other features are still enabled).', 'Wildside A/S', 1003031, 0, 0),
(30400, 0, 'fed', 1, '1.3.32', 2210, 49, 'Fluid Extbase Development Framework', 'Extensive library of Configuration, Plugins, ViewHelpers and Services for making Fluid Page Templates, Fluid Content Elements, AJAX form validations, AJAX-REST-enabled ExtJS4 Models and so much more. Web site: http://fedext.net', 1, -1, 4, 1311516645, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'namelesscoder', '9269c37ce56c1929e055b6611ed9f812', 'Added important page and content related ViewHelpers: Menu, BreadCrumb and Redirect. Added BreadCrumb and Redirect Fluid FCEs.', 'Wildside A/S', 1003032, 0, 0),
(30401, 0, 'fed', 1, '1.3.34', 2210, 22, 'Fluid Extbase Development Framework', 'Extensive library of Configuration, Plugins, ViewHelpers and Services for making Fluid Page Templates, Fluid Content Elements, AJAX form validations, AJAX-REST-enabled ExtJS4 Models and so much more. Web site: http://fedext.net', 1, -1, 4, 1312315220, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'namelesscoder', 'c436d923434419102a2706868a70a91e', 'Many improvements for MultiUploadViewHelper; smaller page footprint, nicer styles, more arguments and cleaned up code. Necessary update for initial release of "fedexample" extension.', 'Wildside A/S', 1003034, 0, 0),
(30402, 0, 'fed', 1, '1.3.33', 2210, 4, 'Fluid Extbase Development Framework', 'Extensive library of Configuration, Plugins, ViewHelpers and Services for making Fluid Page Templates, Fluid Content Elements, AJAX form validations, AJAX-REST-enabled ExtJS4 Models and so much more. Web site: http://fedext.net', 1, -1, 4, 1312151641, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'namelesscoder', 'f0b789169947a644910c68af32493e99', 'Bugfixes and new features: FileObjectStorage, File Service, MultiUploadViewHelper - all compatible with TYPO3 TCA file fields. MultiUploadViewHelper still experimental - next version will support renaming files, sorting, TCA max/minitems, type filters etc', 'Wildside A/S', 1003033, 0, 0),
(30403, 0, 'fed', 1, '1.3.35', 2210, 22, 'Fluid Extbase Development Framework', 'Extensive library of Configuration, Plugins, ViewHelpers and Services for making Fluid Page Templates, Fluid Content Elements, AJAX form validations, AJAX-REST-enabled ExtJS4 Models and so much more. Web site: http://fedext.net', 1, -1, 4, 1312318785, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'namelesscoder', 'e48875b168c59a23be6663a7eefe0546', 'Includes fixes for (known) TYPO3 4.6-beta1 (Fluid and Extbase 1.4-beta1) compatibility issues.', 'Wildside A/S', 1003035, 0, 0),
(30404, 0, 'fed', 1, '1.3.36', 2210, 7, 'Fluid Extbase Development Framework', 'Extensive library of Configuration, Plugins, ViewHelpers and Services for making Fluid Page Templates, Fluid Content Elements, AJAX form validations, AJAX-REST-enabled ExtJS4 Models and so much more. Web site: http://fedext.net', 1, -1, 4, 1312570232, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'namelesscoder', 'a4766b875cc076808262e4c2a7f419ba', 'BREAKING CHANGE: more robust and portable FCE. Partial and Layout support, compat with 4.5 TYPO3 and new 4.6 (beta1) installs - thanks to Sebastian Kurfrst. See http://fedext.net/updates for update information.', 'Wildside A/S', 1003036, 0, 0),
(30405, 0, 'fed', 1, '1.3.37', 2210, 9, 'Fluid Extbase Development Framework', 'Extensive library of Configuration, Plugins, ViewHelpers and Services for making Fluid Page Templates, Fluid Content Elements, AJAX form validations, AJAX-REST-enabled ExtJS4 Models and so much more. Web site: http://fedext.net', 1, -1, 4, 1312586875, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'namelesscoder', '7b6a01a455a8dbc5f7ef083ad867aca3', 'Enabled BE previews in FCEs. Small beauty-issues fixed. Note breaking changes from previous version!', 'Wildside A/S', 1003037, 0, 0),
(30406, 0, 'fed', 1, '1.3.38', 2210, 9, 'Fluid Extbase Development Framework', 'Extensive library of Configuration, Plugins, ViewHelpers and Services for making Fluid Page Templates, Fluid Content Elements, AJAX form validations, AJAX-REST-enabled ExtJS4 Models and so much more. Web site: http://fedext.net', 1, -1, 4, 1312624450, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'namelesscoder', '319a6b59038ed1eca0b7d9ae5e58f8b0', 'Yet another important feature: Transformation of values from fields in FCEs; supports DomainObjects, ObjectStorage, File/Image Resource, FileObjectStorage etc. Apologies for the many updates but I think these are important enough to rush a bit.', 'Wildside A/S', 1003038, 0, 0),
(30407, 0, 'fed', 1, '1.3.39', 2210, 45, 'Fluid Extbase Development Framework', 'Extensive library of Configuration, Plugins, ViewHelpers and Services for making Fluid Page Templates, Fluid Content Elements, AJAX form validations, AJAX-REST-enabled ExtJS4 Models and so much more. Web site: http://fedext.net', 1, -1, 4, 1312668117, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'namelesscoder', 'ff120eaba7563d426373385724ebb50f', 'Fixes broken Fluid Page by adopting FCE approach. Page templates now also expect section named Configuration to contain fed:page definitions. Added error tolerance to disable selector options rather than allow fatal errors to happen in BE - this should he', 'Wildside A/S', 1003039, 0, 0),
(30408, 0, 'fed', 1, '1.3.40', 2210, 25, 'Fluid Extbase Development Framework', 'Extensive library of Configuration, Plugins, ViewHelpers and Services for making Fluid Page Templates, Fluid Content Elements, AJAX form validations, AJAX-REST-enabled ExtJS4 Models and so much more. Web site: http://fedext.net', 1, -1, 4, 1313332760, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'namelesscoder', '16ed9a9f337fa8dba24c7fe66dd9856f', 'Many new features and Fluid Content Element improvements such as FlexForm sheets and Fluid Content Element-style FlexForms possible for any TYPO3 plugin. See web site for more information.', 'Wildside A/S', 1003040, 0, 0),
(30409, 0, 'fed', 1, '1.3.41', 2210, 36, 'Fluid Extbase Development Framework', 'Extensive library of Configuration, Plugins, ViewHelpers and Services for making Fluid Page Templates, Fluid Content Elements, AJAX form validations, AJAX-REST-enabled ExtJS4 Models and so much more. Web site: http://fedext.net', 1, -1, 4, 1313424332, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'namelesscoder', '49b93d0b3fa3e872ef45d9e84dcd4a0b', 'COMPAT hotfix for 4.5.x installs without any active Extbase BE modules and TYPO3s running TemplaVoila which had its content element previews broken by the new Fluid FlexForm feature.', 'Wildside A/S', 1003041, 0, 0),
(30410, 0, 'fed', 1, '1.3.42', 2210, 62, 'Fluid Extbase Development Framework', 'Extensive library of Configuration, Plugins, ViewHelpers and Services for making Fluid Page Templates, Fluid Content Elements, AJAX form validations, AJAX-REST-enabled ExtJS4 Models and so much more. Web site: http://fedext.net', 1, -1, 4, 1313950756, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'namelesscoder', '37c83a164b2a962f1bd655e236f878b6', 'New ViewHelpers: Select w/ Optgroup and Option support. Backported FLOW3 Debugger w/ associated ViewHelper. Interface cleanups. See web site for more information and usage examples.', 'Wildside A/S', 1003042, 0, 0),
(30411, 0, 'fed', 1, '1.3.43', 2210, 128, 'Fluid Extbase Development Framework', 'Extensive library of Configuration, Plugins, ViewHelpers and Services for making Fluid Page Templates, Fluid Content Elements, AJAX form validations, AJAX-REST-enabled ExtJS4 Models and so much more. Web site: http://fedext.net', 1, -1, 4, 1315777296, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'namelesscoder', 'f48d25b4ad1749fd96e5e77b327a9dce', 'Bugfix and cleanup release: Bug when inserting content elements inside Fluid Content Elements fixed - plus smaller bugs in ViewHelpers mainly. Better Menu- and BreadCrumb ViewHelpers, thanks to suggestions from Marcel Zweifel.', 'Wildside A/S', 1003043, 0, 0),
(30412, 0, 'fed', 1, '1.3.44', 2210, 15, 'Fluid Extbase Development Framework', 'Extensive library of Configuration, Plugins, ViewHelpers and Services for making Fluid Page Templates, Fluid Content Elements, AJAX form validations, AJAX-REST-enabled ExtJS4 Models and so much more. Web site: http://fedext.net', 1, -1, 4, 1318792514, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'namelesscoder', 'a09aab6b5b7510b8d29d9fc02265c76b', 'Implementation improvements for Fluid Page / Content Elements. New Backend Record Controller feature. See http://fedext.net/overview/history-and-status/update-notes/ for more information.', 'Wildside A/S', 1003044, 0, 0),
(30413, 0, 'fed', 1, '1.3.45', 2210, 32, 'Fluid Extbase Development Framework', 'Extensive library of Configuration, Plugins, ViewHelpers and Services for making Fluid Page Templates, Fluid Content Elements, AJAX form validations, AJAX-REST-enabled ExtJS4 Models and so much more. Web site: http://fedext.net', 1, -1, 4, 1318842855, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'namelesscoder', '3bb5a677c98f6ec5cae6313088094a56', 'Added missing autoload entries - with apologies to all 4.5-users. See previous changelog.', 'Wildside A/S', 1003045, 0, 0),
(30414, 0, 'fed', 1, '1.3.46', 2210, 12, 'Fluid Extbase Development Framework', 'Extensive library of Configuration, Plugins, ViewHelpers and Services for making Fluid Page Templates, Fluid Content Elements, AJAX form validations, AJAX-REST-enabled ExtJS4 Models and so much more. Web site: http://fedext.net', 1, -1, 4, 1319047079, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'namelesscoder', '12254f473b545432aa2ee4d2cc7da77f', 'Performance improvements, bugfixes and many 4.5 compatibility issues fixed.', 'Wildside A/S', 1003046, 0, 0),
(30415, 0, 'fed', 1, '1.3.47', 2210, 111, 'Fluid Extbase Development Framework', 'Extensive library of Configuration, Plugins, ViewHelpers and Services for making Fluid Page Templates, Fluid Content Elements, AJAX form validations, AJAX-REST-enabled ExtJS4 Models and so much more. Web site: http://fedext.net', 1, -1, 4, 1319094174, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'namelesscoder', 'de33840425837665e1c816bde893eb84', 'Bugfix: typo in variable name, dynamic flexform. Prevented creation of new Fluid Content Elements.', 'Wildside A/S', 1003047, 0, 0),
(30416, 0, 'fed', 1, '1.3.48', 2210, 60, 'Fluid Extbase Development Framework', 'Extensive library of Configuration, Plugins, ViewHelpers and Services for making Fluid Page Templates, Fluid Content Elements, AJAX form validations, AJAX-REST-enabled ExtJS4 Models and so much more. Web site: http://fedext.net', 1, -1, 4, 1321385190, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'namelesscoder', '3890d340af2b0c91e755537afbe83e88', 'Previous, Next and IndexOf ViewHelpers - for ObjectStorage, QueryResult and Array. Form VH AJAX validation now supports typeNum, multiple objects and per-field validation. Plus some bugfixes.', 'Wildside A/S', 1003048, 0, 0),
(30417, 0, 'fed', 1, '1.4.0', 2210, 19, 'Fluid Extbase Development Framework', 'Extensive library of Configuration, Plugins, ViewHelpers and Services for making Fluid Page Templates, Fluid Content Elements, AJAX form validations, AJAX-REST-enabled ExtJS4 Models and so much more. Web site: http://fedext.net', 1, -1, 4, 1322169299, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'namelesscoder', '1bf4739909c9931b18d901a3caec2988', 'Many new ViewHelpers, two new AJAX Fluid Widgets (RecordSelector, ImageCrop) - plus general improvements. Raising TYPO3 version requirement to 4.6 but still compatible with 4.5 for a while longer.', 'Wildside A/S', 1004000, 0, 0),
(30418, 0, 'fed', 1, '1.4.1', 2210, 10, 'Fluid Extbase Development Framework', 'Extensive library of Configuration, Plugins, ViewHelpers and Services for making Fluid Page Templates, Fluid Content Elements, AJAX form validations, AJAX-REST-enabled ExtJS4 Models and so much more. Web site: http://fedext.net', 1, -1, 4, 1322267211, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'namelesscoder', '87ca7547dbec0c408bdce61b9a1a46f5', 'BE Editor experience improvements - human readable page template selector labels, better tab labels, more standards compliant implementation approach (fed_template and fed_datasource are now regular plugins).', 'Wildside A/S', 1004001, 0, 0),
(30419, 0, 'fed', 1, '1.4.2', 2210, 46, 'Fluid Extbase Development Framework', 'Extensive library of Configuration, Plugins, ViewHelpers and Services for making Fluid Page Templates, Fluid Content Elements, AJAX form validations, AJAX-REST-enabled ExtJS4 Models and so much more. Web site: http://fedext.net', 1, -1, 4, 1322341834, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'namelesscoder', 'fda6ef5c1cd96994d8cf6bd3d2043625', 'Further editor experience improvements - dedicated section for Fluid Content. Fixed an important bug in FCE handling; nested content elements can now be copied recursively. Added feature to run CommandController commands through Scheduler Tasks.', 'Wildside A/S', 1004002, 0, 0),
(30420, 0, 'fed', 1, '1.4.3', 2210, 61, 'Fluid Extbase Development Framework', 'Extensive library of Configuration, Plugins, ViewHelpers and Services for making Fluid Page Templates, Fluid Content Elements, AJAX form validations, AJAX-REST-enabled ExtJS4 Models and so much more. Web site: http://fedext.net', 1, -1, 4, 1322969335, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'namelesscoder', 'f909d60614737d75561132b7b9d90e0d', 'New Dynamic FlexForm feature added, doocumentation online. A few bugfixes and refactorings - minor changes only.', 'Wildside A/S', 1004003, 0, 0),
(30421, 0, 'fed', 1, '1.4.4', 2210, 13, 'Fluid Extbase Development Framework', 'Extensive library of Configuration, Plugins, ViewHelpers and Services for making Fluid Page Templates, Fluid Content Elements, AJAX form validations, AJAX-REST-enabled ExtJS4 Models and so much more. Web site: http://fedext.net', 2, -1, 4, 1323638893, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'namelesscoder', 'e4ffe460229f193421950586a431f8d1', 'Raising state to stable. New ViewHelpers for PageRenderer integration and DHTML form field groups w/ token support. Minor refactoring of Services. General PHPdoc comment improvements. And a handful of bugfixes.', 'Wildside A/S', 1004004, 0, 0),
(30422, 0, 'fed', 1, '1.4.5', 2210, 4, 'Fluid Extbase Development Framework', 'Extensive library of Configuration, Plugins, ViewHelpers and Services for making Fluid Page Templates, Fluid Content Elements, AJAX form validations, AJAX-REST-enabled ExtJS4 Models and so much more. Web site: http://fedext.net', 2, -1, 4, 1323684507, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'namelesscoder', 'ce8e5db93b3bcf4aa0b0ca047e1f00bb', 'Corrected missing ext_autoload entries for 4.5 compatibility. You only need this update if you did not download 1.4.4 or are a TYPO3 4.5 user. Apologies to all 4.5 users!', 'Wildside A/S', 1004005, 0, 0),
(30423, 0, 'fed', 1, '1.4.6', 2210, 67, 'Fluid Extbase Development Framework', 'Extensive library of Configuration, Plugins, ViewHelpers and Services for making Fluid Page Templates, Fluid Content Elements, AJAX form validations, AJAX-REST-enabled ExtJS4 Models and so much more. Web site: http://fedext.net', 2, -1, 4, 1323685097, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'namelesscoder', '1a3c0fb3a4dc84c0e11118f1639895bb', 'Corrected missing ext_autoload entries for 4.5 compatibility. You only need this update if you did not download 1.4.4 or are a TYPO3 4.5 user. Apologies to all 4.5 users!', 'Wildside A/S', 1004006, 0, 0),
(30424, 0, 'fed', 1, '1.4.7', 2210, 23, 'Fluid Extbase Development Framework', 'Extensive library of Configuration, Plugins, ViewHelpers and Services for making Fluid Page Templates, Fluid Content Elements, AJAX form validations, AJAX-REST-enabled ExtJS4 Models and so much more. Web site: http://fedext.net', 2, -1, 4, 1324827354, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'namelesscoder', 'dd3cb7f5ac88f55c589983705dae3470', 'New Solr AJAX Fluid Widget, new Fluid FlexForm field type "tree" (selects records usign a tree widget) and "suggest" features for select, group and tree field types (requires TYPO3 4.6.3 to function). As well as a handful of bugfixes.', 'Wildside A/S', 1004007, 0, 0),
(30425, 0, 'fed', 1, '1.4.8', 2210, 66, 'Fluid Extbase Development Framework', 'Extensive library of Configuration, Plugins, ViewHelpers and Services for making Fluid Page Templates, Fluid Content Elements, AJAX form validations, AJAX-REST-enabled ExtJS4 Models and so much more. Web site: http://fedext.net', 2, -1, 4, 1324927784, 'a:1:{s:7:"depends";a:4:{s:5:"typo3";s:9:"4.5-0.0.0";s:3:"cms";s:0:"";s:7:"extbase";s:7:"1.3-0.0";s:5:"fluid";s:7:"1.3-0.0";}}', 'Claus Due', 'claus@wildside.dk', 'namelesscoder', '6ecbc1e7e15486542da6ebb14ef4548a', 'Greatly improves Scheduler support and allows the gridelements extension to drag and drop nested content elements in FCEs. Extension set to suggest gridelements - highly recommended in combination with FED!', 'Wildside A/S', 1004008, 0, 0),
(30426, 0, 'fed', 1, '1.4.9', 2210, 38, 'Fluid Extbase Development Framework', 'Integrates Fluid and Extbase even further with TYPO3, allowing pages to be rendered through Fluid, content elements based on Fluid templates, dynamic FlexForms based on Fluid. Integrates Scheduler with Extbase CommandControllers. Contains hundreds of View', 2, -1, 4, 1325554412, 'a:1:{s:7:"depends";a:4:{s:5:"typo3";s:9:"4.5-0.0.0";s:3:"cms";s:0:"";s:7:"extbase";s:3:"1.3";s:5:"fluid";s:3:"1.3";}}', 'Claus Due', 'claus@wildside.dk', 'namelesscoder', '343ca5db4a149e856c9f4d853098b706', 'Fix for version dependencies, fix for FlexForm sheet support in FCEs. Changed extension description slightly.', 'Wildside A/S', 1004009, 0, 0),
