(30947, 0, 'fedexample', 1, '2.1.0', 345, 0, 'FED Example', 'Demonstration of EXT:fed, EXT:fluidpages and/or EXT:fluidcontent. Includes a Twitter Bootstrap based FED/fluidpages page template.', 1, 0, 9, 1355623704, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'abandoned_extensions', '531ae9e982e4355dfdec40e5a26edeb1', 'Updated Bootstrap resources, added demonstration of Backend Layout contained in page template, dynamic just like every other Flux component. No longer requires FED but suggest it along with EXT:fluidcontent and EXT:fluidpages.', 'Wildside A/S', 2001000, 1, 0),
(30948, 0, 'quickshop_stock', 1, '0.1.0', 68, 68, 'Quick Shop Stock', 'Advanced handling of Quick Shop products stock, using a powermail hook. After order the number of products in stock will be reduced by the number of ordered products.', 1, 0, 3, 1312788210, 'a:1:{s:7:"depends";a:2:{s:10:"quick_shop";s:0:"";s:9:"powermail";s:11:"1.6.3-0.0.0";}}', 'Ulfried Herrmann (Die Netzmacher)', 'http://herrmann.at.die-netzmacher.de/', 'uherrmann', '58a53f9508c35da29f210cc73035e6e9', 'Initial Release', '', 1000, 1, 0),
