(31029, 0, 'extension_builder', 1, '2.5.0', 1957, 0, 'Extension Builder', 'The Extension Builder helps you build and manage your Extbase based TYPO3 extensions.', 1, 0, 1, 1354607714, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:9:"6.0-0.0.0";s:7:"extbase";s:3:"6.0";s:5:"fluid";s:3:"6.0";}}', 'Ingmar Schlecht, Nico de Haen', 'ingmar@typo3.org,mail@ndh-websolutions.de', 'nicodh', 'b6c733be9217d5e6bcd4338d665403b6', 'Added namespace support and TYPO3v6 compatibility.\n\nThis is still beta!\n\nPlease report bugs!', '', 2005000, 0, 0),
(31030, 0, 'extension_builder', 1, '2.5.1', 1957, 0, 'Extension Builder', 'The Extension Builder helps you build and manage your Extbase based TYPO3 extensions.', 1, 0, 1, 1354704798, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:9:"6.0-0.0.0";s:7:"extbase";s:3:"6.0";s:5:"fluid";s:3:"6.0";}}', 'Ingmar Schlecht, Nico de Haen', 'ingmar@typo3.org,mail@ndh-websolutions.de', 'nicodh', '31aa46840d165af312f726162b3939fc', 'Disables the loading of extensions generated with the versions  2.5 since loading non name spaced extensions is not supported.', '', 2005001, 0, 0),
