(31032, 0, 'extension_builder', 1, '6.2.0', 1957, 0, 'Extension Builder', 'The Extension Builder helps you build and manage your Extbase based TYPO3 extensions.', 1, 0, 1, 1399923737, 'a:2:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.1.0-6.2.99";}s:8:"suggests";a:1:{s:7:"phpunit";s:0:"";}}', 'Nico de Haen', 'mail@ndh-websolutions.de', 'nicodh', '3269f45c06cb0c6af723d83478f36635', 'Complete refactoring:\r\nnew PHP parser,\r\nnamespaced classes,\r\nimproved GUI,\r\nvarious new configuration options,\r\nnew documentation', '', 6002000, 0, 0),
