(31202, 0, 'doc_guide_install_ru', 1, '2.1.0', 49, 49, 'Russian translation of TYPO3 Installation and Upgr', 'Very important document describing the filestructure of TYPO3 and taking you step by step through the installation.\nDoes not deal with specific servers/OSes - just general TYPO3 installation issues.', 2, 0, 8, 1314948703, 'a:0:{}', 'Official Documentation', 'documentation@typo3.org', 'docteam', '44faf19f5071c76025891014201fbd39', 'Thanks to Andrey Aksenov for creating this translation!', '', 2001000, 1, 0),
(31203, 0, 'doc_core_tsconfig_ru', 1, '4.5.2', 38, 38, 'TSconfig', 'Russian translation of Page TSconfig and User TSconfig reference.', 2, 0, 8, 1314951090, 'a:0:{}', 'Official Documentation', 'documentation@typo3.org', 'docteam', 'b6dfa71c8a05ff5420902029dbab0454', 'Thanks to Andrey Aksenov for translating the document!', '', 4005002, 1, 0),
