(31206, 0, 'jb_genericlistanddetail', 1, '1.0.0', 35, 35, 'Generic List and Detail', 'Displays list and detail of any table items, fully customizable by template and TS', 1, 0, 2, 1314988044, 'a:1:{s:7:"depends";a:1:{s:10:"pagebrowse";s:0:"";}}', 'Jan Bednarik', 'info@bednarik.org', 'bednee', '2d9d75c2a2f2526f08ef9de27d24805d', 'Initial upload', '', 1000000, 1, 0),
(31207, 0, 'gridelements', 1, '0.1.0', 645, 38, 'Grid Elements', 'This extension integrates the grid layout concept also to regular content elements - the grid elements.\nThis approach is an alternative to TemplaVoila to store relations normalized in the database without using XML.', 1, -1, 0, 1315302166, 'a:2:{s:7:"depends";a:1:{s:3:"cms";s:0:"";}s:9:"conflicts";a:1:{s:11:"templavoila";s:0:"";}}', 'Jo Hasenau, Rocco Georgi', 'info@cybercraft.de, r.georgi@telekom.de', 'cybercraft', '04089c481f3b3f253799d10c503287c2', 'Initial upload. Grid view for CE works completely. D&D, FE output via TS/plugin and manual still pending.\r\n\r\nCan be installed together with TV but will disable some of the TV hooks, which is the reason for the message during the install. So you can still ', '', 1000, 0, 0),
(31208, 0, 'gridelements', 1, '0.2.0', 645, 11, 'Grid Elements', 'This extension integrates the grid layout concept also to regular content elements - the grid elements.\nThis approach is an alternative to TemplaVoila to store relations normalized in the database without using XML.', 1, -1, 0, 1315407016, 'a:2:{s:7:"depends";a:1:{s:3:"cms";s:0:"";}s:9:"conflicts";a:1:{s:11:"templavoila";s:0:"";}}', 'Jo Hasenau, Rocco Georgi', 'info@cybercraft.de, r.georgi@telekom.de', 'cybercraft', '82f8b685327d6bc45a0a38e355fef2a5', 'security fix - please update!', '', 2000, 0, 0),
(31209, 0, 'gridelements', 1, '0.3.0', 645, 30, 'Grid Elements', 'This extension integrates the grid layout concept also to regular content elements - the grid elements.\nThis approach is an alternative to TemplaVoila to store relations normalized in the database without using XML.', 1, -1, 0, 1315502090, 'a:2:{s:7:"depends";a:1:{s:3:"cms";s:0:"";}s:9:"conflicts";a:1:{s:11:"templavoila";s:0:"";}}', 'Jo Hasenau, Rocco Georgi', 'info@cybercraft.de, r.georgi@telekom.de', 'cybercraft', 'c540453f35141c3deed2bf0e0df34df2', 'security fix - please update!', '', 3000, 0, 0),
(31210, 0, 'gridelements', 1, '0.5.0', 645, 10, 'Grid Elements', 'This extension integrates the grid layout concept also to regular content elements - the grid elements.\nThis approach is an alternative to TemplaVoila to store relations normalized in the database without using XML.', 1, -1, 0, 1318160067, 'a:2:{s:7:"depends";a:1:{s:3:"cms";s:0:"";}s:9:"conflicts";a:1:{s:11:"templavoila";s:0:"";}}', 'Jo Hasenau, Rocco Georgi', 'info@cybercraft.de, rocco@pavingways.com', 'cybercraft', 'd03f9be65a7c61097a8db92eed19df1c', ' lots of improvements to the D&D feature\r\n Drag & Drop works properly now including copying with CTRL-key pressed\r\n Grid containers are updated and logged as well during actions of a child element between one or two container(s)\r\n Basic concept for Dr', '', 5000, 0, 0),
(31211, 0, 'gridelements', 1, '0.6.0', 645, 20, 'Grid Elements', 'This extension integrates the grid layout concept also to regular content elements - the grid elements.\nThis approach is an alternative to TemplaVoila to store relations normalized in the database without using XML.', 1, -1, 0, 1318184834, 'a:2:{s:7:"depends";a:1:{s:3:"cms";s:0:"";}s:9:"conflicts";a:1:{s:11:"templavoila";s:0:"";}}', 'Jo Hasenau, Rocco Georgi', 'info@cybercraft.de, rocco@pavingways.com', 'cybercraft', 'ab52c54ac959d4e9c858d364884180ed', ' Drag In of new content elements complete\r\n Just activate the drag in wizard by clicking on the "create new content element" icon on top of the page\r\n', '', 6000, 0, 0),
(31212, 0, 'gridelements', 1, '1.0.0', 645, 35, 'Grid Elements', 'This extension integrates the grid layout concept also to regular content elements - the grid elements.\nThis approach is an alternative to TemplaVoila to store relations normalized in the database without using XML.', 1, -1, 0, 1318254404, 'a:2:{s:7:"depends";a:1:{s:3:"cms";s:0:"";}s:9:"conflicts";a:1:{s:11:"templavoila";s:0:"";}}', 'Jo Hasenau, Rocco Georgi', 'info@cybercraft.de, rocco@pavingways.com', 'cybercraft', '6edaa2979870800cb96e06e4b73d6faf', ' Fixed different bugs with D&D in IE8\r\n Fixed the handling of the layout wizard BACK_PATH for global and local installs of the extension\r\n Fixed bug: Dragging in of new elements after elements outside of grid containers does not work', '', 1000000, 0, 0),
(31213, 0, 'gridelements', 1, '1.1.0', 645, 103, 'Grid Elements', 'This extension integrates the grid layout concept also to regular content elements - the grid elements.\nThis approach is an alternative to TemplaVoila to store relations normalized in the database without using XML.', 1, -1, 0, 1320655504, 'a:2:{s:7:"depends";a:1:{s:3:"cms";s:0:"";}s:9:"conflicts";a:1:{s:11:"templavoila";s:0:"";}}', 'Jo Hasenau, Rocco Georgi', 'info@cybercraft.de, rocco@pavingways.com', 'cybercraft', 'ab32936b58c32106eb5a80e9b56d0554', 'Numerous features and bugfixes\r\n Fixed: $BACK_PATH issue with symlinked filesystem, now theres a $BACK_PATH_ABS variable - only used for PHP requires\r\n Fixed: backend layout wizard was linked to typo3/ext for some reason, path edited to use t3lib_extMg', '', 1001000, 0, 0),
