(31322, 0, 'ts_cleverreach', 1, '1.1.0', 48, 34, 'CleverReach Newsletter', 'The CleverReach Newsletter Subscription plugin provides an interface for Typo3 to interact with the CleverReach.com E-Mail Marketing Software service. It utilizes the CleverReach API to subscribe or unsubscribe a user to or from an e-mail newsletter list ', 2, 0, 3, 1317228319, 'a:0:{}', '3spin', 'dev.typo3@3spin.de', '3spin', '577f84260f9bc1557f0d79fd82603a69', ' Added flexform for display mode selection  you can now select whether to show both forms at once or just one (subscription/unsubscription).\r\n Added variables "redirectSubscribePID" and "redirectUnsubscribePID" to have an optional page redirect on', '', 1001000, 0, 0),
(31323, 0, 'ts_cleverreach', 1, '1.3.1', 48, 0, 'CleverReach Newsletter', 'The CleverReach Newsletter Subscription plugin provides an interface for Typo3 to interact with the CleverReach.com E-Mail Marketing Software service. It utilizes the CleverReach API to subscribe or unsubscribe a user to or from an e-mail newsletter list using the SOAP service from PHP.', 2, 0, 3, 1336123120, 'a:0:{}', '3spin', 'dev.typo3@3spin.de', '3spin', '3f4852df7603d4a2baf0cb07eb0aa48b', 'Added support for using additional options with the SoapClient (Thanks to Martin Joisten for his input on this topic)', '', 1003001, 0, 0),
(31324, 0, 'ts_cleverreach', 1, '2.0.0', 48, 0, 'CleverReach Newsletter', 'The CleverReach Newsletter Subscription plugin provides an interface for Typo3 to interact with the CleverReach.com E-Mail Marketing Software service. It utilizes the CleverReach API to subscribe or unsubscribe a user to or from an e-mail newsletter list using the SOAP service from PHP.', 2, 0, 3, 1357301951, 'a:0:{}', '3spin', 'dev.typo3@3spin.de', '3spin', 'b2bb15f3c2b7a33c395adf24c447d9fa', 'Updated plugin to work with new API 5.1\r\nFixed a bug related to empty SoapClientOptions\r\nAdded error message for invalid API key', '', 2000000, 0, 0),
(31325, 0, 'ts_cleverreach', 1, '2.0.1', 48, 0, 'CleverReach Newsletter', 'The CleverReach Newsletter Subscription plugin provides an interface for Typo3 to interact with the CleverReach.com E-Mail Marketing Software service. It utilizes the CleverReach API to subscribe or unsubscribe a user to or from an e-mail newsletter list using the SOAP service from PHP.', 2, 0, 3, 1368793890, 'a:0:{}', '3spin', 'dev.typo3@3spin.de', '3spin', '0c4e9dc5378c4f24b03d47e5083d4de0', 'Fixed default WSDL URL pointing to the old API in the plugins main class', '', 2000001, 1, 0),
