(31370, 0, 'pazpar2', 1, '1.0.0', 86, 6, 'pazpar2', 'Interface to indexdatas pazpar2 metasearch middleware', 1, 0, 2, 1316421696, 'a:1:{s:7:"depends";a:4:{s:3:"php";s:11:"5.2.0-0.0.0";s:5:"typo3";s:11:"4.5.3-0.0.0";s:7:"extbase";s:11:"1.3.0-0.0.0";s:5:"fluid";s:11:"1.3.0-0.0.0";}}', 'Sven-S. Porst', 'porst@sub.uni-goettingen.de', 'cv47al', '8ec225c08310ed8a8e4d20606adc52c6', 'initial release', 'Gttingen State and University Library, Germany http://sub.uni-goettingen.de', 1000000, 0, 0),
(31371, 0, 'pazpar2', 1, '1.0.1', 86, 5, 'pazpar2', 'Interface to indexdatas pazpar2 metasearch middleware', 1, 0, 2, 1316539014, 'a:1:{s:7:"depends";a:4:{s:3:"php";s:11:"5.2.0-0.0.0";s:5:"typo3";s:11:"4.5.3-0.0.0";s:7:"extbase";s:11:"1.3.0-0.0.0";s:5:"fluid";s:11:"1.3.0-0.0.0";}}', 'Sven-S. Porst', 'porst@sub.uni-goettingen.de', 'cv47al', 'a444fe8eab42f6ec9a3b57c13922e62d', ' add icon\r\n fix loss of parameters when running without JavaScript\r\n reflect users setting of fulltext search option when redisplaying the form', 'Gttingen State and University Library, Germany http://sub.uni-goettingen.de', 1000001, 0, 0),
(31372, 0, 'pazpar2', 1, '1.0.2', 86, 7, 'pazpar2', 'Interface to indexdatas pazpar2 metasearch middleware', 1, 0, 2, 1316615594, 'a:0:{}', 'Sven-S. Porst', 'porst@sub.uni-goettingen.de', 'cv47al', '824df5e83f6d9a0cefaf3ba2b36e966c', ' add information about feed link to README\r\n make Neuerwerbungen feed link optional\r\n make fulltext checkbox in extended search form configurable\r\n make date field in extended search form configurable\r\n fix problem with passed parameters in Neuerwerb', 'Gttingen State and University Library, Germany http://sub.uni-goettingen.de', 1000002, 0, 0),
(31373, 0, 'pazpar2', 1, '1.0.3', 86, 9, 'pazpar2', 'Interface to indexdatas pazpar2 metasearch middleware', 1, 0, 2, 1316702799, 'a:1:{s:7:"depends";a:4:{s:3:"php";s:11:"5.2.0-0.0.0";s:5:"typo3";s:11:"4.5.3-0.0.0";s:7:"extbase";s:11:"1.3.0-0.0.0";s:5:"fluid";s:11:"1.3.0-0.0.0";}}', 'Sven-S. Porst', 'porst@sub.uni-goettingen.de', 'cv47al', 'ace61a70a1da6f40f9492984dc547bff', ' add class pz2-neuerwerbungen to container when using Neuerwerbungen', 'Gttingen State and University Library, Germany http://sub.uni-goettingen.de', 1000003, 0, 0),
(31374, 0, 'pazpar2', 1, '1.1.0', 86, 7, 'pazpar2', 'Interface to indexdatas pazpar2 metasearch middleware', 1, 0, 2, 1321381555, 'a:1:{s:7:"depends";a:4:{s:3:"php";s:11:"5.2.0-0.0.0";s:5:"typo3";s:11:"4.5.3-0.0.0";s:7:"extbase";s:11:"1.3.0-0.0.0";s:5:"fluid";s:11:"1.3.0-0.0.0";}}', 'Sven-S. Porst', 'porst@sub.uni-goettingen.de', 'cv47al', '832843ab845fccc0e5d7446a1ea03b30', ' support Piwik tracking\r\n support for pazpar2-access proxy\r\n improve URL sorting\r\n improve location sorting\r\n better total result count in non-JavaScript version\r\n leaner Fluid templates\r\n single year selection in year histogram', 'Gttingen State and University Library, Germany http://www.sub.uni-goettingen.de', 1001000, 0, 0),
(31375, 0, 'pazpar2', 1, '1.1.1', 86, 6, 'pazpar2', 'Interface to indexdatas pazpar2 metasearch middleware', 1, 0, 2, 1321549051, 'a:0:{}', 'Sven-S. Porst', 'porst@sub.uni-goettingen.de', 'cv47al', '3f86c20d24e435170f04af1073fe8669', ' recognise Gttingen Opac https URLs\r\n fix recognition of Guest access\r\n improve automatic restarting of searches on session loss', 'Gttingen State and University Library, Germany http://www.sub.uni-goettingen.de', 1001001, 0, 0),
(31376, 0, 'pazpar2', 1, '1.1.2', 86, 3, 'pazpar2', 'Interface to indexdatas pazpar2 metasearch middleware', 1, 0, 2, 1321871061, 'a:1:{s:7:"depends";a:4:{s:3:"php";s:11:"5.2.0-0.0.0";s:5:"typo3";s:11:"4.5.3-0.0.0";s:7:"extbase";s:11:"1.3.0-0.0.0";s:5:"fluid";s:11:"1.3.0-0.0.0";}}', 'Sven-S. Porst', 'porst@sub.uni-goettingen.de', 'cv47al', '1db4811d0200c48b11b296336e7b7717', ' do not add access information to Fluid template when the query did not run in PHP', 'Gttingen State and University Library, Germany http://www.sub.uni-goettingen.de', 1001002, 0, 0),
(31377, 0, 'pazpar2', 1, '1.1.3', 86, 3, 'pazpar2', 'Interface to indexdatas pazpar2 metasearch middleware', 1, 0, 2, 1321899285, 'a:1:{s:7:"depends";a:4:{s:3:"php";s:11:"5.2.0-0.0.0";s:5:"typo3";s:11:"4.5.3-0.0.0";s:7:"extbase";s:11:"1.3.0-0.0.0";s:5:"fluid";s:11:"1.3.0-0.0.0";}}', 'Sven-S. Porst', 'porst@sub.uni-goettingen.de', 'cv47al', '60a930e339b66b0c2400bfbb4ad6fa5b', ' reduce maximum GET query length for pz2.js to 512 (the default limit set by Suhosin on SLES 11)\r\n improve Content-Type header information for export formats', 'Gttingen State and University Library, Germany http://www.sub.uni-goettingen.de', 1001003, 0, 0),
(31378, 0, 'pazpar2', 1, '1.1.4', 86, 5, 'pazpar2', 'Interface to indexdatas pazpar2 metasearch middleware', 1, 0, 2, 1321969397, 'a:1:{s:7:"depends";a:4:{s:3:"php";s:11:"5.2.0-0.0.0";s:5:"typo3";s:11:"4.5.3-0.0.0";s:7:"extbase";s:11:"1.3.0-0.0.0";s:5:"fluid";s:11:"1.3.0-0.0.0";}}', 'Sven-S. Porst', 'porst@sub.uni-goettingen.de', 'cv47al', '46ec1f961ce8a57e8a16bb814fd8f3dc', ' make automatic query starting more reliable in Neuerwerbungen\r\n prevent incorrect usage of the no-JavaScript codepath', 'Gttingen State and University Library, Germany http://www.sub.uni-goettingen.de', 1001004, 0, 0);
INSERT INTO `tx_extensionmanager_domain_model_extension` (`uid`, `pid`, `extension_key`, `repository`, `version`, `alldownloadcounter`, `downloadcounter`, `title`, `description`, `state`, `review_state`, `category`, `last_updated`, `serialized_dependencies`, `author_name`, `author_email`, `ownerusername`, `md5hash`, `update_comment`, `authorcompany`, `integer_version`, `current_version`, `lastreviewedversion`) VALUES
(31379, 0, 'pazpar2', 1, '1.2.0', 86, 5, 'pazpar2', 'Interface to indexdatas pazpar2 metasearch middleware', 2, 0, 2, 1322209963, 'a:1:{s:7:"depends";a:4:{s:3:"php";s:11:"5.2.0-0.0.0";s:5:"typo3";s:11:"4.5.3-0.0.0";s:7:"extbase";s:11:"1.3.0-0.0.0";s:5:"fluid";s:11:"1.3.0-0.0.0";}}', 'Sven-S. Porst', 'porst@sub.uni-goettingen.de', 'cv47al', '5e26ee10c7822f144b07ce4ff30f29a5', ' add links to show all facets when facets needed to be hidden\r\n more reliable tooltip hiding for histogram\r\n require nkwgok 1.2.0 or above and use its updated database schema for Neuerwerbungen\r\n fix Piwik tracking for metadata export links', 'Gttingen State and University Library, Germany http://www.sub.uni-goettingen.de', 1002000, 0, 0),
(31380, 0, 'pazpar2', 1, '1.3.0', 86, 5, 'pazpar2', 'Interface to indexdatas pazpar2 metasearch middleware', 2, 0, 2, 1323098858, 'a:1:{s:7:"depends";a:4:{s:3:"php";s:11:"5.2.0-0.0.0";s:5:"typo3";s:11:"4.5.3-0.0.0";s:7:"extbase";s:11:"1.3.0-0.0.0";s:5:"fluid";s:11:"1.3.0-0.0.0";}}', 'Sven-S. Porst', 'porst@sub.uni-goettingen.de', 'cv47al', 'ea0f3bbabbfed047ae119d26b8db7ae9', 'Neuerwerbungen:\r\n number of months in popup menu is now configurable in TypoScript\r\n if there is just single checkbox, automatically select it', 'Gttingen State and University Library, Germany http://www.sub.uni-goettingen.de', 1003000, 0, 0),
(31381, 0, 'pazpar2', 1, '1.4.0', 86, 4, 'pazpar2', 'Interface to indexdatas pazpar2 metasearch middleware', 2, 0, 2, 1326705431, 'a:0:{}', 'Sven-S. Porst', 'porst@sub.uni-goettingen.de', 'cv47al', '74609e238387120f5acd0f93c615ce11', ' add keyword search and ability to display keywords in result details\n add support for additional media types (letter, manuscript, image)\n small display tweaks\n stop using deprecated form field View Helper', 'Gttingen State and University Library, Germany http://www.sub.uni-goettingen.de', 1004000, 0, 0),
(31382, 0, 'pazpar2', 1, '1.5.0', 86, 7, 'pazpar2', 'Interface to indexdatas pazpar2 metasearch middleware', 2, 0, 2, 1326877204, 'a:1:{s:7:"depends";a:4:{s:3:"php";s:11:"5.2.0-0.0.0";s:5:"typo3";s:11:"4.5.3-0.0.0";s:7:"extbase";s:11:"1.3.0-0.0.0";s:5:"fluid";s:11:"1.3.0-0.0.0";}}', 'Sven-S. Porst', 'porst@sub.uni-goettingen.de', 'cv47al', 'e0e6b30f668b5327293413ddddf487dd', ' add second set of paging controls beneath the results\n work around localisation breakage of TYPO3 4.6\n add Geo-specific placeholder search term to main search field configuration', 'Gttingen State and University Library, Germany http://www.sub.uni-goettingen.de', 1005000, 0, 0),
(31383, 0, 'pazpar2', 1, '1.6.0', 86, 9, 'pazpar2', 'Interface to indexdatas pazpar2 metasearch middleware', 2, 0, 3, 1330100281, 'a:1:{s:7:"depends";a:4:{s:3:"php";s:11:"5.2.0-0.0.0";s:5:"typo3";s:11:"4.5.3-0.0.0";s:7:"extbase";s:11:"1.3.0-0.0.0";s:5:"fluid";s:11:"1.3.0-0.0.0";}}', 'Sven-S. Porst', 'porst@sub.uni-goettingen.de', 'cv47al', '19f4d411f5b50d138ec63bacb6ffecf0', ' Restructure Resources/Public to provide the JavaScript interface as a standalone repository: [pazpar2-js-client](https://github.com/ssp/pazpar2-js-client)\n change date format for Neuerwerbungen to YYYYMM\n improved reliability of triggering the pazpar2', 'Gttingen State and University Library, Germany http://www.sub.uni-goettingen.de', 1006000, 0, 0),
(31384, 0, 'pazpar2', 1, '1.7.0', 86, 5, 'pazpar2', 'Interface to indexdatas pazpar2 metasearch middleware', 2, 0, 3, 1333110070, 'a:1:{s:7:"depends";a:4:{s:3:"php";s:11:"5.2.0-0.0.0";s:5:"typo3";s:11:"4.5.3-0.0.0";s:7:"extbase";s:11:"1.3.0-0.0.0";s:5:"fluid";s:11:"1.3.0-0.0.0";}}', 'Sven-S. Porst', 'porst@sub.uni-goettingen.de', 'cv47al', '84f9bb7afb86baa9d77a004a108f3d4a', ' Display the location covered by maps\n Display the scale of maps\n Remove ZDB-JOP sid configuration from script, it has to be inserted into the URL by the proxy now\n Add ability to display a link to the parent record (catalogue-url-parent field)\n Remo', 'Gttingen State and University Library, Germany http://www.sub.uni-goettingen.de', 1007000, 0, 0),
