(31477, 0, 'doc_core_cgl_ru', 1, '4.5.0', 21, 21, 'Russian translation of TYPO3 Coding Guidelines', 'A description of the formal requirements or standards regarding PHP coding that you should adhere to when you develop TYPO3 Extensions or Core parts.', 2, 0, 8, 1317029681, 'a:0:{}', 'TYPO3 Core Development Team', 'info@typo3.org', 'docteam', '4a09fdd367850c85db0f55e7da2b694e', 'First official release. Thanks to Andrey Aksenov for translating the document!', '', 4005000, 1, 0),
(31478, 0, 'google_auth', 1, '1.0.0', 71, 8, 'Google OpenAuth v2', 'Provides a service for TYPO3 which lets users log in through Google Accounts (and indeed other OAuth2 enabled account providers)', 0, 0, 5, 1317037114, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'namelesscoder', '375594ec99c57c5b6b873a5fa2a11ad3', 'Google OAuth2 implementation. Authorize your fe_users remotely, then creates a local fe_users record with data from Google Account for use in access protection. Login form can be replaced by one button - all auth happens at Google Apps. Requires Google Ap', 'Wildside A/S', 1000000, 0, 0),
(31479, 0, 'google_auth', 1, '0.0.1', 71, 2, 'Google OpenAuth v2', 'Google OAuth2 implementation. Authorize your fe_users remotely, then creates a local fe_users record with data from Google Account for use in access protection. Login form can be replaced by one button - all auth happens at Google Apps. Requires Google Ap', 1, 0, 5, 1317037227, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'namelesscoder', '3d8614a074adb912e0af9fa7d56f0490', 'Initial release in beta state.', 'Wildside A/S', 1, 0, 0),
