(31665, 0, 'alt_gd_magick', 1, '0.2.0', 114, 8, 'ALTAIR GD Magick', 'Drop-in replacement for ImageMagick using GD, in case IM is not available at the hoster.\n            Idea from jb_gd_resize and srgd Typo3 extension.\n            This extension tries to modified the smallest part of the original Typo3 code, mainly by repl', 0, 0, 2, 1319102418, 'a:0:{}', 'Laszlo Vass', 'lvass@altair.hu', 'lvass', 'c6ffa349041b65b0eecb3816daaf5c2f', 'Initial relases.\r\nCrop and resize works as with IM.\r\nBE thumbs also works.', '', 2000, 0, 0),
(31666, 0, 'alt_gd_magick', 1, '0.2.1', 114, 10, 'ALTAIR GD Magick', 'Drop-in replacement for ImageMagick using GD, in case IM is not available at the hoster.\n            Scale and resize function work the same way then the original Typo3 code with IM.\n            Idea from jb_gd_resize and srgd Typo3 extension.\n           ', 0, 0, 2, 1319204790, 'a:0:{}', 'Laszlo Vass', 'lvass@altair.hu', 'lvass', '44bfc27d113826c6ff0c09978fe54ffb', 'Added documentation', '', 2001, 0, 0),
(31667, 0, 'alt_gd_magick', 1, '0.3.0', 114, 4, 'ALTAIR GD Magick', 'Drop-in replacement for ImageMagick using GD, in case IM is not available at the hoster.\n            Scale and resize function work the same way then the original Typo3 code with IM.\n            Idea from jb_gd_resize and srgd Typo3 extension.\n           ', 1, 0, 4, 1319614892, 'a:0:{}', 'Laszlo Vass', 'lvass@altair.hu', 'lvass', '9b892745602ba2197dae9638cf717cd4', 'Better error handling and logging (using devlog).\r\nSilently ignores unhandled actions (only log).\r\nPassed to beta stage.', '', 3000, 0, 0),
(31668, 0, 'alt_gd_magick', 1, '0.3.1', 114, 16, 'ALTAIR GD Magick', 'Drop-in replacement for ImageMagick using GD, in case IM is not available at the hoster.\n            Scale and resize function work the same way then the original Typo3 code with IM.\n            Idea from jb_gd_resize and srgd Typo3 extension.\n           ', 1, 0, 4, 1319617926, 'a:0:{}', 'Laszlo Vass', 'lvass@altair.hu', 'lvass', 'bf496c3b751e82c655541371c637e50b', 'Fixed bad upload (unnecessary subdir)', '', 3001, 0, 0),
(31669, 0, 'alt_gd_magick', 1, '0.5.0', 114, 10, 'ALTAIR GD Magick', 'Drop-in replacement for ImageMagick using GD, in case IM is not available at the hoster.\n            Scale and resize function work the same way then the original Typo3 code with IM.\n            Idea from jb_gd_resize and srgd Typo3 extension.\n           ', 1, 0, 4, 1320545551, 'a:0:{}', 'Laszlo Vass', 'lvass@altair.hu', 'lvass', '55f667e84e4785ad168e07c993e3aebe', 'Restructured code\r\n-rotate command is now supported.\r\n\r\nTESTERS NEEDED! Any feedback is welcome!\r\nThanks.', '', 5000, 0, 0),
(31670, 0, 'alt_gd_magick', 1, '0.5.1', 114, 66, 'ALTAIR GD Magick', 'Drop-in replacement for ImageMagick using GD, in case IM is not available at the hoster.\n            Scale and resize function work the same way then the original Typo3 code with IM.\n            Idea from jb_gd_resize and srgd Typo3 extension.\n           ', 1, 0, 4, 1320645267, 'a:0:{}', 'Laszlo Vass', 'lvass@altair.hu', 'lvass', '32cb96ef86821a1099a590d325fa3fbc', 'Fixed unhandled actions handling (removed forgetten die command)', '', 5001, 0, 0),
