(31676, 0, 'fluidlayout', 1, '1.0.0', 76, 76, ' backend_layout', 'Create FLUIDTEMPLATE as templates your user can select. Create a backend_layout and give your user a nice backend.', 0, 0, 4, 1319436628, 'a:1:{s:7:"depends";a:1:{s:5:"fluid";s:0:"";}}', 'Soren Malling', 'soren.malling@gmail.com', 'sorenmalling', 'b5e17040f1f58dfd55a23ddb36c3f145', 'First release, find blog post on \n\nhttp://buzz.typo3.org/people/soeren-malling/', '', 1000000, 1, 0),
