(31679, 0, 'slub_rss_aggregator', 1, '0.1.2', 47, 12, 'SLUB RSS Aggregator', 'Simple RSS aggregator for RSS feeds.', 1, 0, 3, 1321351479, 'a:0:{}', 'Alexander Bigga', 'alexander.bigga@slub-dresden.de', 'albigdd', '545a5ba397a6809de14a5fd7e7672834', 'Enables plugin to be multiple used on one page.', '', 1002, 0, 0),
(31680, 0, 'slub_rss_aggregator', 1, '0.1.3', 47, 3, 'SLUB RSS Aggregator', 'Simple RSS aggregator for RSS feeds.', 1, 0, 3, 1324462160, 'a:0:{}', 'Alexander Bigga', 'alexander.bigga@slub-dresden.de', 'albigdd', '4b08ac18182060b0eb613aa39c9f8e16', 'The timestamp of feed items is updated now on every fetch. This makes it possible to aggregate feeds without pubDate-tag given.', '', 1003, 0, 0),
