(31682, 0, 'slub_rss_aggregator', 1, '0.1.5', 47, 12, 'SLUB RSS Aggregator', 'Simple RSS aggregator for RSS feeds.', 1, 0, 3, 1326200433, 'a:0:{}', 'Alexander Bigga', 'alexander.bigga@slub-dresden.de', 'albigdd', '799bbf1e165ae64a4beeb04a30b627a7', 'use link field instead of title field as unique item identifier. \r\nSome blogs change the title after submitting the article but the link stays constant. This led to double entries.', '', 1005, 1, 0),
