(31699, 0, 'tnm_nicefaq', 1, '0.0.1', 18, 18, '(tnm) Nice FAQ', 'This extension is a complete rebuild of the first-draft extension "tnm_ttnewsfaq" based on tt_news records.\nThe aim of this extension is to use its own records instead of tt_news which adds the functionality of using "IRRE" to manage the category/item st', 1, 0, 3, 1319711325, 'a:1:{s:7:"depends";a:1:{s:3:"cms";s:0:"";}}', 'Gabriel Kaufmann  Typoworx', 'info@typoworx.de', 'typoworx-de', '59a4062189fee449a0eaf743e7dc769d', 'This is the first official release including:\r\n- recent updates: improvements/bugfixes\r\n- added new Item-Type "Reference":\r\n  you can reference to existing items.', '', 1, 0, 0),
(31700, 0, 'tnm_nicefaq', 1, '0.0.2', 18, 0, '(tnm) Nice FAQ', 'This extension is a complete rebuild of the first-draft extension "tnm_ttnewsfaq" based on tt_news records.\nThe aim of this extension is to use its own records instead of tt_news which adds the functionality of using "IRRE" to manage the category/item structure.', 1, 0, 3, 1334052393, 'a:1:{s:7:"depends";a:1:{s:3:"cms";s:0:"";}}', 'Gabriel Kaufmann  Typoworx', 'info@typoworx.de', 'typoworx-de', '4155890f32eb574dfe383471cd3b8cd5', 'some major bugfixes for the IRRE / TCE-Hook.', 'Typoworx NewMedia', 2, 0, 0),
