(31759, 0, 'simplecalendar', 1, '0.1.0', 175, 10, 'Simple Calendar', 'This is a simple but powerful calendar extension.\n\nFeature overview:\nsimple event-management in Typo3-Backend\nMonth-View Frontend-Plugin to display a month calender\nDay-View Frontend-Plugin to display all events of one day in a list\nMonth-View (simplified', 1, 0, 3, 1320542146, 'a:0:{}', 'Lars Ebert', 'info@advitum.de', 'advitum', '550dd4a90db80578f04350b87a8a13c3', 'Created the extension, wrote all the code in some sleepless nights and finally wrote this manual. I hope you will like it.', '', 1000, 0, 0),
(31760, 0, 'simplecalendar', 1, '0.1.1', 175, 5, 'Simple Calendar', 'This is a simple but powerful calendar extension.\n\nFeature overview:\nsimple event-management in Typo3-Backend\nMonth-View Frontend-Plugin to display a month calender\nDay-View Frontend-Plugin to display all events of one day in a list\nMonth-View (simplified', 1, 0, 3, 1320573596, 'a:0:{}', 'Lars Ebert', 'info@advitum.de', 'advitum', '6637eb86d93fba68a63bf58765d47ae1', 'Fixed some ugly displaying errors in the online-manual.', '', 1001, 0, 0),
(31761, 0, 'simplecalendar', 1, '0.1.2', 175, 47, 'Simple Calendar', 'This is a simple but powerful calendar extension.\n\nFeature overview:\nsimple event-management in Typo3-Backend\nMonth-View Frontend-Plugin to display a month calender\nDay-View Frontend-Plugin to display all events of one day in a list\nMonth-View (simplified', 1, 0, 3, 1320580319, 'a:0:{}', 'Lars Ebert', 'info@advitum.de', 'advitum', '476402902f8e65266562996235c8e861', 'Fixed an error in the localization of week- and monthnames.', '', 1002, 0, 0),
(31762, 0, 'simplecalendar', 1, '0.1.3', 175, 42, 'Simple Calendar', 'This is a simple but powerful calendar extension.\n\nFeature overview:\nsimple event-management in Typo3-Backend\nMonth-View Frontend-Plugin to display a month calender\nDay-View Frontend-Plugin to display all events of one day in a list\nMonth-View (simplified', 1, 0, 3, 1324146945, 'a:0:{}', 'Lars Ebert', 'info@advitum.de', 'advitum', 'e6a988e4a81928d5a0c9811fd796ea01', 'Finally added the csv-importer to the extenson. See "Users manual" for details!\r\nSmall changes in the manual. Fixed some typos in the german localization.', '', 1003, 0, 0),
(31763, 0, 'simplecalendar', 1, '0.1.4', 175, 71, 'Simple Calendar', 'This is a simple but powerful calendar extension.\n\nFeature overview:\nsimple event-management in Typo3-Backend\nMonth-View Frontend-Plugin to display a month calender\nDay-View Frontend-Plugin to display all events of one day in a list\nMonth-View (simplified', 1, 0, 3, 1326446045, 'a:0:{}', 'Lars Ebert', 'info@advitum.de', 'advitum', 'b3e0d2d49ef6d772a39ac0b5def2208f', 'Fixed a nasty bug which messed up the month-view when a month started with a sunday.', '', 1004, 0, 0),
(31764, 0, 'simplecalendar', 1, '0.2.0', 175, 0, 'Simple Calendar', 'This is a simple but powerful calendar extension.\n\nFeature overview:\nsimple event-management in Typo3-Backend\nMonth-View Frontend-Plugin to display a month calender\nDay-View Frontend-Plugin to display all events of one day in a list\nMonth-View (simplified) Frontend-Plugin - same as the Month-View Plugin, only simplified and minified to fit in an extra small space, e.g. a sidebar', 1, 0, 3, 1339706598, 'a:0:{}', 'Lars Ebert', 'info@advitum.de', 'advitum', '9cea595faa1da901b20a089b9c8c7f14', 'Finally added the List-view-mode I promised from the beginning.\r\nI also fixed several bugs in the CSV-Importer. Additionally I added the PerPage-Configuration', '', 2000, 0, 0),
(31765, 0, 'simplecalendar', 1, '0.3.0', 175, 0, 'Simple Calendar', 'This is a simple but powerful calendar extension.\n\nFeature overview:\nSimple event-management in Typo3-Backend\nSwitch between displaying a full month, just one day or a simplified month view to fit into a sidebar.', 1, 0, 3, 1414678117, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:12:"6.2.0-6.2.99";s:7:"extbase";s:5:"1.3.4";s:5:"fluid";s:5:"1.3.1";}}', 'Lars Ebert', 'info@advitum.de', 'advitum', '61dfb8da12b239b63acd75ca0fdb3d9a', 'Extension works now with Typo3 6.2. The old csv-import had to go, but there will soon be a new import tool.', '', 3000, 1, 0),
(31766, 0, 'df_tabs', 1, '3.0.0', 172, 23, 'Tabbed Content and Pages', 'Create tab based content elements and pages easily and flexible with configurable mouseover handling, animations, ajax and autoplay features! Its based upon mootools.', 2, 0, 2, 1320673808, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:12:"5.2.0-5.3.99";s:5:"typo3";s:12:"4.5.0-4.6.99";}}', 'Stefan Galinski', 'sgalinski@df.eu', 'sgalinsk', '2cb8ba178c438db4b639f150fb88fae4', 'Initial Release', 'domainFACTORY', 3000000, 0, 0),
