(32012, 0, 'deletefiles', 1, '0.0.1', 24, 24, 'Delete old files', 'This scheduler task helps to maintain your TYPO3 installation and / or to improve the privacy of your customers by deleting old files in specific intervals.', 1, 0, 5, 1323997228, 'a:1:{s:7:"depends";a:2:{s:9:"scheduler";s:0:"";s:5:"typo3";s:11:"4.3.0-0.0.0";}}', 'Felix Nagel', 'info@felixnagel.com', 'fnagel', 'b0da28da8d47ac0fb6d2ca634d057d2f', 'initial release, tested and ready for use but no warranty!', '', 1, 0, 0),
(32013, 0, 'deletefiles', 1, '0.0.2', 24, 0, 'Delete old files', 'This scheduler task helps to maintain your TYPO3 installation and / or to improve the privacy of your customers by deleting old files in specific intervals.', 1, 0, 5, 1363034482, 'a:1:{s:7:"depends";a:2:{s:9:"scheduler";s:0:"";s:5:"typo3";s:12:"4.3.0-4.7.99";}}', 'Felix Nagel', 'info@felixnagel.com', 'fnagel', 'f06045f8064d79b2f53b24a7ad04375d', 'TYPO3 dependency added (no changes required)', '', 2, 0, 0),
