(32142, 0, 'dialog', 1, '0.1.0', 67, 2, 'Dialog - Lightweight discussion module', 'Fluid AJAX Widget discussion component which can be used from any Fluid template or as a content element. Features automatic setup. Configurable threaded, flat or chat mode.', 0, 0, 3, 1326141784, 'a:1:{s:7:"depends";a:4:{s:3:"cms";s:0:"";s:7:"extbase";s:3:"1.3";s:5:"fluid";s:3:"1.3";s:3:"fed";s:3:"1.4";}}', 'Claus Due', 'claus@wildside.dk', 'namelesscoder', '396dade5e9805bc2c83984632e1fb2e0', 'Initial TER relase. Currently only has AJAX chat as plugin and Fluid Widget. The forum features are coming shortly.', 'Wildside A/S', 1000, 0, 0),
(32143, 0, 'dialog', 1, '0.1.1', 67, 24, 'Dialog - Lightweight discussion module', 'Fluid AJAX Widget discussion component which can be used from any Fluid template or as a content element. Features automatic setup. Configurable threaded, flat or chat mode.', 0, 0, 3, 1326144386, 'a:1:{s:7:"depends";a:4:{s:3:"cms";s:0:"";s:7:"extbase";s:3:"1.3";s:5:"fluid";s:3:"1.3";s:3:"fed";s:3:"1.4";}}', 'Claus Due', 'claus@wildside.dk', 'namelesscoder', '6162ed50ddb7974ae76747caac45cbde', 'Fixed Widget usage with custom ID.', 'Wildside A/S', 1001, 0, 0),
(32144, 0, 'dialog', 1, '1.0.0', 67, 15, 'Dialog - Lightweight discussion module', 'Fluid AJAX Widget discussion component which can be used from any Fluid template or as a content element. Features automatic setup. Configurable threaded, flat or chat mode.', 1, 0, 3, 1331548452, 'a:1:{s:7:"depends";a:5:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";s:4:"flux";s:0:"";s:3:"fed";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'namelesscoder', '79feb188dc9b122c72297db923906afd', 'Forum component added. Info: http://fedext.net/extensions/flux', 'Wildside A/S', 1000000, 0, 0),
(32145, 0, 'dialog', 1, '1.1.0', 67, 9, 'Dialog - Lightweight discussion module', 'Fluid AJAX Widget discussion component which can be used from any Fluid template or as a content element. Features automatic setup. Configurable threaded, flat or chat mode.', 1, 0, 3, 1331844810, 'a:1:{s:7:"depends";a:5:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";s:4:"flux";s:0:"";s:3:"fed";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'namelesscoder', '448146a0e5b087c50947cc5c8bcf09e8', 'FE users now automatically recognized and used as Poster. Fixed some CSS issues and allowed HTML conservation bugs. Added option to include custom stylesheet from within plugin or TS (build this CSS using LESS - see Twitter Bootstrap).', 'Wildside A/S', 1001000, 0, 0),
(32146, 0, 'dialog', 1, '1.1.1', 67, 17, 'Dialog - Lightweight discussion module', 'Fluid AJAX Widget discussion component which can be used from any Fluid template or as a content element. Features automatic setup. Configurable threaded, flat or chat mode.', 1, 0, 3, 1332010375, 'a:1:{s:7:"depends";a:5:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";s:4:"flux";s:0:"";s:3:"fed";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'namelesscoder', '58be5c2f59fe1bd855065fbc9e690dc2', 'Improvements to Post content rendering. Uses Fluid to render and format text for each Post. Fixes issues with line break replacements and adds the link and list pseudo-HTML elements to use in Posts.', 'Wildside A/S', 1001001, 0, 0),
(32147, 0, 'dialog', 1, '1.0.1', 67, 0, 'Dialog - Lightweight discussion module', 'Discussion components - comments, chat, forum - all based on Fluid Widgets. All components can be used as plugins or as Widgets in your templates.', 1, 0, 3, 1333331680, 'a:0:{}', 'Claus Due', 'claus@wildside.dk', 'namelesscoder', 'f373c522be848c25b276af902c6833a1', 'Just small fixes. Primarily in the Chat Widget and plugin.', 'Wildside A/S', 1000001, 0, 0),
(32148, 0, 'dialog', 1, '1.2.0', 67, 0, 'Dialog - Lightweight discussion module', 'Fluid AJAX Widget discussion component which can be used from any Fluid template or as a content element. Features automatic setup. Configurable threaded, flat or chat mode.', 1, 0, 3, 1353262443, 'a:1:{s:7:"depends";a:5:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";s:4:"flux";s:0:"";s:3:"fed";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'namelesscoder', 'e0407a37b15670f8180a483b66f2177e', 'New AJAX commenting Widget, currently only available as Fluid Widget. Improvements in FE-user recognition, Discussion Widget (hide Poster form if user logged in). jQuery no longer auto-insertable. Default styles no longer necessary. Watch out for possible', 'Wildside A/S', 1002000, 0, 0),
(32149, 0, 'dialog', 1, '2.0.0', 67, 0, 'Dialog - Lightweight discussion module', 'Fluid AJAX Widget discussion component which can be used from any Fluid template or as a content element. Features automatic setup. Configurable threaded, flat or chat mode.', 2, 0, 3, 1356918035, 'a:1:{s:7:"depends";a:6:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";s:4:"flux";s:0:"";s:6:"notify";s:0:"";s:3:"vhs";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'namelesscoder', '47630a51ae0fb99e49d1f052542343c7', 'Major update, potential breakage. Improves all views - especially Discussion and Thread lists, editing of posts, integration with EXT:notify (subscription to new posts/threads), Markdown (cached) support in Posts, "last post" and "last activity" indic', 'Wildside A/S', 2000000, 0, 0),
(32150, 0, 'dialog', 1, '2.1.0', 67, 0, 'Dialog: Lightweight discussion module', 'Fluid Widget discussion components which can be used from any Fluid template or as a content elements. Features automatic setup. Configurable threaded or flat (comments style) displays.', 2, 0, 3, 1357691222, 'a:1:{s:7:"depends";a:6:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";s:4:"flux";s:0:"";s:6:"notify";s:0:"";s:3:"vhs";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'namelesscoder', 'c20bbd9d9c8fbc1409c28850a0a62b31', 'Smaller improvements, minor bugfixes. Consider this a maintenance update - which may require you to make minor CSS adjustments due to some cleanups.', 'Wildside A/S', 2001000, 1, 0),
