(32217, 0, 'podcast', 1, '0.3.0', 42, 2, 'Podcast', 'Handel multiple Podcasts.', 0, 0, 3, 1327563139, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Nol Bossart', 'n dot company at me dot com', 'noelboss', '8924ab72fe19665355e04e65faa48a66', 'New Podcast extension for TYPO3 from the creator of nbo_podcast. Based on Extbase and Fluid. Includes HTML5 video and audio support. Visit http://noelboss.github.com/Podcast\r\n Initial Release', 'noelboss.ch', 3000, 0, 0),
(32218, 0, 'podcast', 1, '0.3.1', 42, 2, 'Podcast for TYPO3', 'A new Podcast extension for Typo3 from the creator of nbo_podcast. Makes creating and managing Podcasts a breeze. Support for HTML5 video and audio, RealURL out of the box, automatic feed publishing and much more. Visit http://noelboss.github.com/Podcast', 0, 0, 3, 1327568591, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:9:"4.5-0.0.0";s:7:"extbase";s:3:"1.3";s:5:"fluid";s:3:"1.3";}}', 'Nol Bossart', 'n dot company at me dot com', 'noelboss', '6cf3265b617b35f9134ed116d539f11b', 'Direct Download:\r\nhttps://github.com/noelboss/Podcast/zipball/0.3.1 Fixed relative image URL in Feed\r\n Updated default CSS\r\n Updated Description', 'noelboss.ch', 3001, 0, 0),
(32219, 0, 'podcast', 1, '0.3.2', 42, 8, 'Podcast for TYPO3', 'A new Podcast extension for Typo3 from the creator of nbo_podcast. Makes creating and managing Podcasts a breeze. Support for HTML5 video and audio, RealURL out of the box, automatic feed publishing and much more. Visit http://noelboss.github.com/Podcast', 0, 0, 3, 1327575624, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:9:"4.5-0.0.0";s:7:"extbase";s:3:"1.3";s:5:"fluid";s:3:"1.3";}}', 'Noel Bossart', 'n dot company at me dot com', 'noelboss', '1ab30e76a62ee495c79df7f2052291a9', 'Direct Download:\r\nhttps://github.com/noelboss/Podcast/zipball/0.3.1- fixed missing upload folder\r\n- fixed wrong database definition', 'noelboss.ch', 3002, 0, 0),
(32220, 0, 'podcast', 1, '0.3.3', 42, 15, 'Podcast for TYPO3', 'A new Podcast extension for Typo3 from the creator of nbo_podcast. Makes publishing and managing Podcasts a breeze. Out of the box support for HTML5 video and audio, RealURL, automatic feed publishing and much more. Visit http://noelboss.github.com/Podcas', 0, 0, 3, 1327683277, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:9:"4.5-0.0.0";s:7:"extbase";s:3:"1.3";s:5:"fluid";s:3:"1.3";}}', 'Noel Bossart', 'n dot company at me dot com', 'noelboss', '7db0aae5ff2d0989c5d64fb113560a81', 'Backend much improved, added Plugin wizard, Podcasts are now also displayed in page-view, fixes. \r\n\r\nDirect Download: https://github.com/noelboss/Podcast/zipball/0.3.3', 'noelboss.ch', 3003, 0, 0),
