(32227, 0, 'podcast', 1, '0.3.10', 42, 0, 'Podcast for TYPO3', 'A new Podcast extension for Typo3 from the creator of nbo_podcast. Makes publishing and managing Podcasts a breeze. Out of the box support for HTML5 video and audio, RealURL, automatic feed publishing and much more. See http://noelboss.github.com/Podcast', 0, 0, 3, 1353156156, 'a:2:{s:7:"depends";a:3:{s:5:"typo3";s:9:"4.5-0.0.0";s:7:"extbase";s:3:"1.3";s:5:"fluid";s:3:"1.3";}s:9:"conflicts";a:1:{s:9:"cbrealurl";s:5:"1.4.1";}}', 'Noel Bossart', 'n dot company at me dot com', 'noelboss', 'f58a699bbb8560030c1ff318ac7a498c', 'Added build and publication build date. Added a bit of documentation in readme.md. This release should fix Issue 14. For more information, visit http://noelboss.github.com/Podcast', 'noelboss.ch', 3010, 0, 0),
(32228, 0, 'podcast', 1, '0.3.11', 42, 0, 'Podcast for TYPO3', 'A new Podcast extension for Typo3 from the creator of nbo_podcast. Makes publishing and managing Podcasts a breeze. Out of the box support for HTML5 video and audio, RealURL, automatic feed publishing and much more. See http://noelboss.github.com/Podcast', 0, 0, 3, 1353162467, 'a:2:{s:7:"depends";a:3:{s:5:"typo3";s:9:"4.5-0.0.0";s:7:"extbase";s:3:"1.3";s:5:"fluid";s:3:"1.3";}s:9:"conflicts";a:1:{s:9:"cbrealurl";s:5:"1.4.1";}}', 'Noel Bossart', 'n dot company at me dot com', 'noelboss', '117058e49cc26f20d2794d24e6a7dbcb', 'Added build and publication build date. Added a bit of documentation in readme.md. This release should fix Issue 14. For more information, visit http://noelboss.github.com/Podcast', 'noelboss.ch', 3011, 0, 0),
(32229, 0, 'podcast', 1, '0.3.12', 42, 0, 'Podcast for TYPO3', 'A new Podcast extension for Typo3 from the creator of nbo_podcast. Makes publishing and managing Podcasts a breeze. Out of the box support for HTML5 video and audio, RealURL, automatic feed publishing and much more. See http://noelboss.github.com/Podcast', 0, 0, 3, 1354218194, 'a:2:{s:7:"depends";a:3:{s:5:"typo3";s:9:"4.5-0.0.0";s:7:"extbase";s:3:"1.3";s:5:"fluid";s:3:"1.3";}s:9:"conflicts";a:1:{s:9:"cbrealurl";s:5:"1.4.1";}}', 'Noel Bossart', 'n dot company at me dot com', 'noelboss', 'e3be99e919e864c51f2f965f611fb171', 'This update adds dates to the feed (configurable via TS) and fixes several issues. Adds proper parsing for feed.', 'noelboss.ch', 3012, 0, 0),
(32230, 0, 'podcast', 1, '0.4.0', 42, 0, 'Podcast for TYPO3', 'A new Podcast extension for Typo3 from the creator of nbo_podcast. Makes publishing and managing Podcasts a breeze. Out of the box support for HTML5 video and audio, RealURL, automatic feed publishing and much more. See http://noelboss.github.com/Podcast', 0, 0, 3, 1364444063, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:9:"4.5-6.0.3";s:7:"extbase";s:3:"1.3";s:5:"fluid";s:3:"1.3";}}', 'Noel Bossart', 'n dot company at me dot com', 'noelboss', '298cf12bfcf67020517daf5bbd5f8ff4', 'After the update, save the plugin again! Fixed single view. New Media Player with flash fallback, much nicer URLs. CoolUri example included. https://github.com/noelboss/Podcastchangelog', 'noelboss.ch', 4000, 0, 0),
(32231, 0, 'podcast', 1, '0.5.0', 42, 0, 'Podcast for TYPO3', 'A new Podcast extension for Typo3 from the creator of nbo_podcast. Makes publishing and managing Podcasts a breeze. Out of the box support for HTML5 video and audio, RealURL, automatic feed publishing and much more. See http://noelboss.github.com/Podcast', 0, 0, 3, 1364437056, 'a:2:{s:7:"depends";a:3:{s:5:"typo3";s:9:"4.5-6.0.3";s:7:"extbase";s:3:"1.3";s:5:"fluid";s:3:"1.3";}s:9:"conflicts";a:1:{s:9:"cbrealurl";s:0:"";}}', 'Noel Bossart', 'n dot company at me dot com', 'noelboss', 'f9438aae4ae2dd80e98fd2b4dbac890a', 'After the update, save the plugin again! Fixed single view. New Media Player with flash fallback, much nicer URLs. CoolUri example included. https://github.com/noelboss/Podcastchangelog', 'noelboss.ch', 5000, 0, 0),
(32232, 0, 'podcast', 1, '0.5.1', 42, 0, 'Podcast for TYPO3', 'The new Podcast extension for Typo3 makes publishing and managing Podcasts a breeze. Out of the box support for HTML5 video and audio, RealURL support, automatic feed publishing and much more. For more infos, see http://noelboss.github.com/Podcast Bug reports https://github.com/noelboss/Podcast/issues', 0, 0, 3, 1364522336, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:9:"4.5-6.0.3";s:7:"extbase";s:3:"1.3";s:5:"fluid";s:3:"1.3";}}', 'Noel Bossart', 'n dot company at me dot com', 'noelboss', '4bd5a48882961f5b9bbd5f5458f221f7', 'After the update, save the plugin again and update the new feed url in iTunes! Fixed issue 17. Fixed single view. New Media Player with flash fallback, much nicer URLs. CoolUri example included. https://github.com/noelboss/Podcastchangelog', 'noelboss.ch', 5001, 0, 0),
(32233, 0, 'podcast', 1, '0.5.2', 42, 0, 'Podcast for TYPO3', 'The new Podcast extension for Typo3 makes publishing and managing Podcasts a breeze. Out of the box support for HTML5 video and audio, RealURL support, automatic feed publishing and much more. For more infos, see http://noelboss.github.com/Podcast Bug reports https://github.com/noelboss/Podcast/issues', 0, 0, 3, 1364836607, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:9:"4.5-6.0.3";s:7:"extbase";s:3:"1.3";s:5:"fluid";s:3:"1.3";}}', 'Noel Bossart', 'n dot company at me dot com', 'noelboss', 'fef2d0d7228da83ab4d0c92d93fac1ab', 'Fixed HTML errors, added TypoScript added preload options, added FlashFallback. If urls dont work for you, try deactivate both podcast and realurl and then activate realurl first, then podcast, clear the caches. If it does still not work, report bug.\r\nht', 'noelboss.ch', 5002, 1, 0),
(32234, 0, 'tcemainhooks', 1, '1.0.0', 22, 3, 'SIMPLE interface to hook into tcemain', 'Usually you need four hook methods and some more logic to hook into tcemain to get informed whenever a record is updated, created or deleted.\nThis extension provides a simple interface that informs you on those changes. It provides you with two hooks , on', 0, 0, 0, 1327576550, 'a:0:{}', 'Michael Knabe', 'mk@e-netconsulting.com', 'michi.k', 'f603963dd8c34ca197612fc0e2db1340', 'Initial upload to TER', '', 1000000, 0, 0),
