(32279, 0, 'typo3mind', 1, '1.0.3', 29, 0, 'TYPO3Mind', 'TYPO3Mind is an extension for generating mind mapping files from your whole TYPO3 installation. Mind maps helps you to understand how your TYPO3 project has been setup and what the current running status is. Currently you can only export .mm files which can be imported by FreeMind (strongly recommended), Freeplane, XMind, Mindjet, MindManager, etc. TYPO3Mind uses the cool icon from FreeMind. This extension hooks into the tree click menu and in the left pane. The mind map includes many icons and pictures with URIs to your webserver. You have a lot of configuration options. Needs TYPO3 4.5 or later, SimpleXML, PHP5.2 or later.', 1, 0, 0, 1336829581, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Cyrill Schumacher', 'Cyrill@Schumacher.fm', 'kiri', '9ca04a5f56229b573b128e2f8f7eafdc', 'Bugfix Release.\nRefactored FreeMind Class to add later additional mind map export formats.\nAdded therefore the new TypoScript config flag: exportFormatClass to specify the class for loading (currently only one)\nUpdated TYPO3 related URLs.\nLooking forward ', '', 1000003, 0, 0),
(32280, 0, 'typo3mind', 1, '1.0.4', 29, 0, 'TYPO3Mind', 'TYPO3Mind is an extension for generating mind mapping files from your whole TYPO3 installation. Mind maps helps you to understand how your TYPO3 project has been setup and what the current running status is. Currently you can only export .mm files which can be imported by FreeMind (strongly recommended), Freeplane, XMind, Mindjet, MindManager, etc. TYPO3Mind uses the cool icon from FreeMind. This extension hooks into the tree click menu and in the left pane. The mind map includes many icons and pictures with URIs to your webserver. You have a lot of configuration options. Needs TYPO3 4.5 or later, SimpleXML, PHP5.2 or later.', 1, 0, 0, 1337063389, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Cyrill Schumacher', 'Cyrill@Schumacher.fm', 'kiri', 'c66447fdc74864643b1e829af371b62e', 'Bugfix: Shows an clear error message if TypoScript is not found.\nAdded basic HTML5 MindMap export format. See http://drichard.org/mindmaps/', '', 1000004, 0, 0),
(32281, 0, 'typo3mind', 1, '1.0.5', 29, 0, 'TYPO3Mind', 'TYPO3Mind is an extension for generating mind mapping files from your whole TYPO3 installation. Mind maps helps you to understand how your TYPO3 project has been setup and what the current running status is. Currently you can only export .mm files which can be imported by FreeMind (strongly recommended), Freeplane, XMind, Mindjet, MindManager, etc. TYPO3Mind uses the cool icon from FreeMind. This extension hooks into the tree click menu and in the left pane. The mind map includes many icons and pictures with URIs to your webserver. You have a lot of configuration options. Needs TYPO3 4.5 or later, SimpleXML, PHP5.2 or later.', 1, 0, 0, 1337112342, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Cyrill Schumacher', 'Cyrill@Schumacher.fm', 'kiri', 'cce678ed8fc942b5165dae7eb169ec83', 'Bugfix. Removed eID and API Key.\nLooking forward for some feedback :-)\nAnd maybe for some contributors.\nVersion is nearly stable.\n', '', 1000005, 0, 0),
(32282, 0, 'typo3mind', 1, '1.0.6', 29, 0, 'TYPO3Mind', 'TYPO3Mind is an extension for generating mind mapping files from your whole TYPO3 installation. Mind maps helps you to understand how your TYPO3 project has been setup and what the current running status is. Currently you can only export .mm files which can be imported by FreeMind (strongly recommended), Freeplane, XMind, Mindjet, MindManager, etc. TYPO3Mind uses the cool icon from FreeMind. This extension hooks into the tree click menu and in the left pane. The mind map includes many icons and pictures with URIs to your webserver. You have a lot of configuration options. Needs TYPO3 4.5 or later, SimpleXML, PHP5.2 or later.', 1, 0, 0, 1339741653, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Cyrill Schumacher', 'Cyrill@Schumacher.fm', 'kiri', 'e5c090f2777d63c908c4836e38d09bca', 'Fixed Bug 37931 / added subfolder path if TYPO3 is not installed in the root directory of a domain', '', 1000006, 0, 0),
(32283, 0, 'typo3mind', 1, '1.1.0', 29, 0, 'TYPO3Mind', 'TYPO3Mind is an extension for generating mind mapping files from your whole TYPO3 installation. Mind maps helps you to understand how your TYPO3 project has been setup and what the current running status is. Currently you can only export .mm files which can be imported by FreeMind (strongly recommended), Freeplane, XMind, Mindjet, MindManager, etc. TYPO3Mind uses the cool icon from FreeMind. This extension hooks into the tree click menu and in the left pane. The mind map includes many icons and pictures with URIs to your webserver. You have a lot of configuration options. Needs TYPO3 4.5 or later, SimpleXML, PHP5.2 or later.', 2, 0, 0, 1350806729, 'a:1:{s:7:"depends";a:4:{s:5:"typo3";s:11:"4.5.0-0.0.0";s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Cyrill Schumacher', 'Cyrill@Schumacher.fm', 'kiri', '095947a02db6e463d753ac925cb9ccc8', 'Changed version to stable.\nNo more errors reported from the community.\nFixed a description if an error shows up while generating the map.\n', '', 1001000, 0, 0),
(32284, 0, 'typo3mind', 1, '1.2.0', 29, 0, 'TYPO3Mind', 'TYPO3Mind is an extension for generating mind mapping files from your whole TYPO3 installation. Mind maps helps you to understand how your TYPO3 project has been setup and what the current running status is. Currently you can only export .mm files which can be imported by FreeMind (strongly recommended), Freeplane, XMind, Mindjet, MindManager, etc. TYPO3Mind uses the cool icon from FreeMind. This extension hooks into the tree click menu and in the left pane. The mind map includes many icons and pictures with URIs to your webserver. You have a lot of configuration options. Needs TYPO3 4.5 or later, SimpleXML, PHP5.2 or later.', 2, 0, 0, 1352546857, 'a:1:{s:7:"depends";a:4:{s:5:"typo3";s:11:"4.5.0-0.0.0";s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Cyrill Schumacher', 'Cyrill@Schumacher.fm', 'kiri', 'e691045fd79b5d1876995ee9da68ad0f', 'Added new feature: http://forge.typo3.org/issues/42834\nPage Tree with custom columns in a note\n\nMinor bug fixes.', '', 1002000, 1, 0),
