(32413, 0, 'dce', 1, '0.3.0', 88, 0, 'Dynamic Content Elements (DCE)', 'Creates easily and fast dynamic content elements. It is an alternative to flexible content elements (FCE) but without need of TemplaVoila (TV). Based on Extbase and Fluid.', 1, -1, 4, 1336722832, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"4.5.0-0.0.0";s:7:"extbase";s:11:"1.3.0-0.0.0";s:5:"fluid";s:11:"1.3.0-0.0.0";}}', 'Armin Ruediger Vieweg', 'armin@v.ieweg.de', 'professorweb', '3f187452ead087afb716095101d8f62c', 'Add possibility to use fluid templates for backend rendering. Now you can separate same DCE types in page view using header and bodytext.\n\nThe use of lib.stdheader has been removed completely. Some refactorings included, too.\n\nPlease dont forget to upda', '', 3000, 0, 0),
(32414, 0, 'dce', 1, '0.3.1', 88, 0, 'Dynamic Content Elements (DCE)', 'Creates easily and fast dynamic content elements. It is an alternative to flexible content elements (FCE) but without need of TemplaVoila (TV). Based on Extbase and Fluid.', 1, -1, 4, 1336920683, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"4.5.0-0.0.0";s:7:"extbase";s:11:"1.3.0-0.0.0";s:5:"fluid";s:11:"1.3.0-0.0.0";}}', 'Armin Ruediger Vieweg', 'armin@v.ieweg.de', 'professorweb', 'b00a285a2cc533f34a1bf22d8289bdaa', 'Fixed missing hide_default_ce_wrap column in sql. Sorry for that and many thanks to Florian Elischer, who reported that issue.', '', 3001, 0, 0),
(32415, 0, 'dce', 1, '0.3.2', 88, 0, 'Dynamic Content Elements (DCE)', 'Creates easily and fast dynamic content elements. It is an alternative to flexible content elements (FCE) but without need of TemplaVoila (TV). Based on Extbase and Fluid.', 1, -1, 4, 1337677273, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"4.5.0-0.0.0";s:7:"extbase";s:11:"1.3.0-0.0.0";s:5:"fluid";s:11:"1.3.0-0.0.0";}}', 'Armin Ruediger Vieweg', 'armin@v.ieweg.de', 'professorweb', '6264e9e92a0ee40981c3fbb33c5760b9', 'Fixed a bug which appears in TYPO3 4.7. DceFieldRepository had problems to find dceFields. This got the effect, that the preview in backend has not been rendered. Thanks to Nicola Lombardini for reporting the issue.', '', 3002, 0, 0),
(32416, 0, 'dce', 1, '0.3.3', 88, 0, 'Dynamic Content Elements (DCE)', 'Creates easily and fast dynamic content elements. It is an alternative to flexible content elements (FCE) but without need of TemplaVoila (TV). Based on Extbase and Fluid.', 1, -1, 4, 1337703505, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"4.5.0-0.0.0";s:7:"extbase";s:11:"1.3.0-0.0.0";s:5:"fluid";s:11:"1.3.0-0.0.0";}}', 'Armin Ruediger Vieweg', 'armin@v.ieweg.de', 'professorweb', 'a414a23718e48f7a88604588956273e2', 'Avoid an error which appears if a content element based on DCE gets created or updated by frontend extensions (like feeditadvanced).\n\nFixed a bug in DAM viewhelper. If you have used it: The argument returnArray was interpreted wrong. Now it does, what the', '', 3003, 0, 0),
(32417, 0, 'dce', 1, '0.3.4', 88, 0, 'Dynamic Content Elements (DCE)', 'Creates easily and fast dynamic content elements. It is an alternative to flexible content elements (FCE) but without need of TemplaVoila (TV). Based on Extbase and Fluid.', 1, -1, 4, 1337961958, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"4.5.0-0.0.0";s:7:"extbase";s:11:"1.3.0-0.0.0";s:5:"fluid";s:11:"1.3.0-0.0.0";}}', 'Armin Ruediger Vieweg', 'armin@v.ieweg.de', 'professorweb', '132b6b60f502527ce8eb3a620b9bcc53', 'Updated all options in extension settings. Add option to disable autoupdate of preview texts. This could produces some issues, if the amount of existing DCEs is high. If this option is enabled the preview texts can get updated right from the page view, wi', '', 3004, 0, 0),
(32418, 0, 'dce', 1, '0.3.5', 88, 0, 'Dynamic Content Elements (DCE)', 'Creates easily and fast dynamic content elements. It is an alternative to flexible content elements (FCE) but without need of TemplaVoila (TV). Based on Extbase and Fluid.', 1, -1, 4, 1341577043, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"4.5.0-0.0.0";s:7:"extbase";s:11:"1.3.0-0.0.0";s:5:"fluid";s:11:"1.3.0-0.0.0";}}', 'Armin Ruediger Vieweg', 'armin@v.ieweg.de', 'professorweb', 'c6adc2e07e455f38867376de1c63cdfe', 'Avoid error message, if dce field is wrong or not configured (flexform xml).', '', 3005, 0, 0),
(32419, 0, 'dce', 1, '0.4.0', 88, 0, 'Dynamic Content Elements (DCE)', 'Creates easily and fast dynamic content elements. It is an alternative to flexible content elements (FCE) but without need of TemplaVoila (TV). Based on Extbase and Fluid.', 1, -1, 4, 1343299691, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"4.5.0-0.0.0";s:7:"extbase";s:11:"1.3.0-0.0.0";s:5:"fluid";s:11:"1.3.0-0.0.0";}}', 'Armin Ruediger Vieweg', 'armin@v.ieweg.de', 'professorweb', '8f19b199f2288333004cd975be2938ae', 'Add option to extension settings, to enable a new backend module to access DCE faster. The module will be displayed under "admin tools".\n\nRefactored the javascripts and fixing some bugs with codemirror editor.\n\nAdd a typoscript condition to check if the', '', 4000, 0, 0);
INSERT INTO `tx_extensionmanager_domain_model_extension` (`uid`, `pid`, `extension_key`, `repository`, `version`, `alldownloadcounter`, `downloadcounter`, `title`, `description`, `state`, `review_state`, `category`, `last_updated`, `serialized_dependencies`, `author_name`, `author_email`, `ownerusername`, `md5hash`, `update_comment`, `authorcompany`, `integer_version`, `current_version`, `lastreviewedversion`) VALUES
(32420, 0, 'dce', 1, '0.4.1', 88, 0, 'Dynamic Content Elements (DCE)', 'Creates easily and fast dynamic content elements. It is an alternative to flexible content elements (FCE) but without need of TemplaVoila (TV). Based on Extbase and Fluid.', 1, -1, 4, 1343300268, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"4.5.0-0.0.0";s:7:"extbase";s:11:"1.3.0-0.0.0";s:5:"fluid";s:11:"1.3.0-0.0.0";}}', 'Armin Ruediger Vieweg', 'armin@v.ieweg.de', 'professorweb', '76b30fd8123c9cdbfcfa95d84ded2f3a', 'Fixed small issue with codemirror editor and preview text inputs.', '', 4001, 0, 0),
(32421, 0, 'dce', 1, '0.4.2', 88, 0, 'Dynamic Content Elements (DCE)', 'Creates easily and fast dynamic content elements. It is an alternative to flexible content elements (FCE) but without need of TemplaVoila (TV). Based on Extbase and Fluid.', 1, -1, 4, 1343316556, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"4.5.0-0.0.0";s:7:"extbase";s:11:"1.3.0-0.0.0";s:5:"fluid";s:11:"1.3.0-0.0.0";}}', 'Armin Ruediger Vieweg', 'armin@v.ieweg.de', 'professorweb', 'f4e3edfb7f63fc073ff3aa9281badd19', 'Fixed a bug, which avoids display of preview images in backend.', '', 4002, 0, 0),
(32422, 0, 'dce', 1, '0.5.0', 88, 0, 'Dynamic Content Elements (DCE)', 'Creates easily and fast dynamic content elements. It is an alternative to flexible content elements (FCE) but without need of TemplaVoila (TV). Based on Extbase and Fluid.', 1, -1, 4, 1352717015, 'a:1:{s:7:"depends";a:4:{s:3:"php";s:11:"5.3.0-0.0.0";s:5:"typo3";s:11:"4.5.0-0.0.0";s:7:"extbase";s:11:"1.3.0-0.0.0";s:5:"fluid";s:11:"1.3.0-0.0.0";}}', 'Armin Ruediger Vieweg', 'armin@v.ieweg.de', 'professorweb', 'e3a05870721805fa55efe5cb047ba4d5', 'Add some new features and much bugfixings. Documentation will be released soon. Thanks for your patience.\n\n Massive refactoring of handling and rendering of DCE items. (See: http://forge.typo3.org/issues/39734)\n Add detail pages to DCE\n Rename "show a', '', 5000, 0, 0),
(32423, 0, 'dce', 1, '0.5.1', 88, 0, 'Dynamic Content Elements (DCE)', 'Creates easily and fast dynamic content elements. It is an alternative to flexible content elements (FCE) but without need of TemplaVoila (TV). Based on Extbase and Fluid.', 1, -1, 4, 1352739406, 'a:1:{s:7:"depends";a:4:{s:3:"php";s:11:"5.3.0-0.0.0";s:5:"typo3";s:11:"4.5.0-0.0.0";s:7:"extbase";s:11:"1.3.0-0.0.0";s:5:"fluid";s:11:"1.3.0-0.0.0";}}', 'Armin Ruediger Vieweg', 'armin@v.ieweg.de', 'professorweb', '05a686e02c270eec753303072d91f2e1', 'Small bugfix for TYPO3 4.5. The docHeaderButtonsHook throws notices. There was also an error with auto including of statically called method (just in 4.5).', '', 5001, 0, 0),
(32424, 0, 'dce', 1, '0.6.0', 88, 0, 'Dynamic Content Elements (DCE)', 'Creates easily and fast dynamic content elements. It is an alternative to flexible content elements (FCE) but without need of TemplaVoila (TV). Based on Extbase and Fluid.', 1, -1, 4, 1354642542, 'a:1:{s:7:"depends";a:4:{s:3:"php";s:11:"5.3.0-0.0.0";s:5:"typo3";s:12:"4.5.0-6.0.99";s:7:"extbase";s:11:"1.3.0-0.0.0";s:5:"fluid";s:11:"1.3.0-0.0.0";}}', 'Armin Ruediger Vieweg', 'armin@v.ieweg.de', 'professorweb', '275c1301f27df4156a1b507b48eac165', 'Add TYPO3 6.0 support', '', 6000, 0, 0),
(32425, 0, 'dce', 1, '0.6.1', 88, 0, 'Dynamic Content Elements (DCE)', 'Creates easily and fast dynamic content elements. It is an alternative to flexible content elements (FCE) but without need of TemplaVoila (TV). Based on Extbase and Fluid.', 1, 0, 4, 1354717456, 'a:1:{s:7:"depends";a:4:{s:3:"php";s:11:"5.3.0-0.0.0";s:5:"typo3";s:12:"4.5.0-6.0.99";s:7:"extbase";s:11:"1.3.0-0.0.0";s:5:"fluid";s:11:"1.3.0-0.0.0";}}', 'Armin Ruediger Vieweg', 'armin@v.ieweg.de', 'professorweb', '5e9fdd1f854a72d5d0e4283f29699e46', 'Small fixes. If you have existing DCEs please check after update the used f:layout name in fluid templates. Layout name must be written with UpperCamelCase! namedefault is wrong and may causes errors in frontend. Correct is: nameDefault.', '', 6001, 0, 0),
(32426, 0, 'dce', 1, '0.7.0', 88, 0, 'Dynamic Content Elements (DCE)', 'Creates easily and fast dynamic content elements. It is an alternative to flexible content elements (FCE) but without need of TemplaVoila (TV). Based on Extbase and Fluid.', 1, -1, 4, 1357552292, 'a:1:{s:7:"depends";a:4:{s:3:"php";s:11:"5.3.0-0.0.0";s:5:"typo3";s:12:"4.5.0-6.0.99";s:7:"extbase";s:11:"1.3.0-0.0.0";s:5:"fluid";s:11:"1.3.0-0.0.0";}}', 'Armin Ruediger Vieweg', 'armin@v.ieweg.de', 'professorweb', '82a48149c259b873a7c1105639698a6c', 'New important feature: Sections. Now, you are able to set a field as section. Below section you may create as much as fields as you want. Eg. you create a new section employees with subfields firstname and lastname. In DCE instance you may create several ', '', 7000, 0, 0),
(32427, 0, 'dce', 1, '0.7.1', 88, 0, 'Dynamic Content Elements (DCE)', 'Creates easily and fast dynamic content elements. It is an alternative to flexible content elements (FCE) but without need of TemplaVoila (TV). Based on Extbase and Fluid.', 1, -1, 4, 1357918935, 'a:1:{s:7:"depends";a:4:{s:3:"php";s:11:"5.3.0-0.0.0";s:5:"typo3";s:12:"4.5.0-6.0.99";s:7:"extbase";s:11:"1.3.0-0.0.0";s:5:"fluid";s:11:"1.3.0-0.0.0";}}', 'Armin Ruediger Vieweg', 'armin@v.ieweg.de', 'professorweb', '79a609f372657805ef96a006a8adde6e', 'Several bugfixes, especially for usage in TYPO3 6.0. Inline fields have now also a Create new button below the field list.', '', 7001, 0, 0),
(32428, 0, 'dce', 1, '0.7.2', 88, 0, 'Dynamic Content Elements (DCE)', 'Creates easily and fast dynamic content elements. It is an alternative to flexible content elements (FCE) but without need of TemplaVoila (TV). Based on Extbase and Fluid.', 1, -1, 4, 1358270011, 'a:1:{s:7:"depends";a:4:{s:3:"php";s:11:"5.3.0-0.0.0";s:5:"typo3";s:12:"4.5.0-6.0.99";s:7:"extbase";s:11:"1.3.0-0.0.0";s:5:"fluid";s:11:"1.3.0-0.0.0";}}', 'Armin Ruediger Vieweg', 'armin@v.ieweg.de', 'professorweb', 'e8546674424f46f9b855144e6bcad733', 'Fixed a small bug with disable csc-default wrap feature for dce items. If there is no dce configured using this function, it may happen that other CTypes (like list) looses their wrapping. The solution was to fill the value which will be checked initially', '', 7002, 0, 0),
(32429, 0, 'dce', 1, '0.7.3', 88, 0, 'Dynamic Content Elements (DCE)', 'Creates easily and fast dynamic content elements. It is an alternative to flexible content elements (FCE) but without need of TemplaVoila (TV). Based on Extbase and Fluid.', 1, -1, 4, 1363130614, 'a:1:{s:7:"depends";a:4:{s:3:"php";s:11:"5.3.0-0.0.0";s:5:"typo3";s:12:"4.5.0-6.0.99";s:7:"extbase";s:11:"1.3.0-0.0.0";s:5:"fluid";s:11:"1.3.0-0.0.0";}}', 'Armin Ruediger Vieweg', 'armin@v.ieweg.de', 'professorweb', 'd8f7b989e4890f71cc0d86c81adb770e', 'Fixed some bugs and an section example to inline template dropdown box. ', '', 7003, 0, 0),
(32430, 0, 'dce', 1, '0.7.4', 88, 0, 'Dynamic Content Elements (DCE)', 'Creates easily and fast dynamic content elements. It is an alternative to flexible content elements (FCE) but without need of TemplaVoila (TV). Based on Extbase and Fluid.', 1, -1, 4, 1363170934, 'a:1:{s:7:"depends";a:4:{s:3:"php";s:11:"5.3.0-0.0.0";s:5:"typo3";s:12:"4.5.0-6.0.99";s:7:"extbase";s:11:"1.3.0-0.0.0";s:5:"fluid";s:11:"1.3.0-0.0.0";}}', 'Armin Ruediger Vieweg', 'armin@v.ieweg.de', 'professorweb', '630eb2707ad3fcf907d9b8370c043792', 'Fixed bug when dbal extension is in use.', '', 7004, 0, 0),
(32431, 0, 'dce', 1, '0.7.5', 88, 0, 'Dynamic Content Elements (DCE)', 'Creates easily and fast dynamic content elements. It is an alternative to flexible content elements (FCE) but without need of TemplaVoila (TV). Based on Extbase and Fluid.', 1, -1, 4, 1363639107, 'a:1:{s:7:"depends";a:4:{s:3:"php";s:11:"5.3.0-0.0.0";s:5:"typo3";s:12:"4.5.0-6.0.99";s:7:"extbase";s:11:"1.3.0-0.0.0";s:5:"fluid";s:11:"1.3.0-0.0.0";}}', 'Armin Ruediger Vieweg', 'armin@v.ieweg.de', 'professorweb', 'dbc1d8fb944f23cfd36ac07faed9481e', 'Fixed regression bug, which causes errors when using the dce_load_schema option.', '', 7005, 0, 0),
(32432, 0, 'dce', 1, '0.8.0', 88, 0, 'Dynamic Content Elements (DCE)', 'Creates easily and fast dynamic content elements. It is an alternative to flexible content elements (FCE) but without need of TemplaVoila (TV). Based on Extbase and Fluid.', 1, -1, 4, 1367586850, 'a:1:{s:7:"depends";a:4:{s:3:"php";s:11:"5.3.0-0.0.0";s:5:"typo3";s:12:"4.5.0-6.0.99";s:7:"extbase";s:11:"1.3.0-0.0.0";s:5:"fluid";s:11:"1.3.0-0.0.0";}}', 'Armin Ruediger Vieweg', 'armin@v.ieweg.de', 'professorweb', '53991835ed05d46d2c3fa98ae68d6181', 'Many new features and bugfixes. When updating to 0.8.0 you need to update the database, clear all caches and execute the update script in the extension manager. See http://forge.typo3.org/news/638 for further informations.', '', 8000, 0, 0),
(32433, 0, 'dce', 1, '0.8.1', 88, 0, 'Dynamic Content Elements (DCE)', 'Creates easily and fast dynamic content elements. It is an alternative to flexible content elements (FCE) but without need of TemplaVoila (TV). Based on Extbase and Fluid.', 1, -1, 4, 1367931295, 'a:1:{s:7:"depends";a:4:{s:3:"php";s:11:"5.3.0-0.0.0";s:5:"typo3";s:12:"4.5.0-6.1.99";s:7:"extbase";s:11:"1.3.0-0.0.0";s:5:"fluid";s:11:"1.3.0-0.0.0";}}', 'Armin Ruediger Vieweg', 'armin@v.ieweg.de', 'professorweb', 'bfa260d39387f10f31f9f0cf4ccd7c1b', 'Fixed bug to make DCE work with TYPO3 6.1.', '', 8001, 0, 0),
