(32435, 0, 'dce', 1, '0.8.3', 88, 0, 'Dynamic Content Elements (DCE)', 'Creates easily and fast dynamic content elements. It is an alternative to flexible content elements (FCE) but without need of TemplaVoila (TV). Based on Extbase and Fluid.', 1, -1, 4, 1371198226, 'a:1:{s:7:"depends";a:4:{s:3:"php";s:11:"5.3.0-0.0.0";s:5:"typo3";s:12:"4.5.0-6.1.99";s:7:"extbase";s:11:"1.3.0-0.0.0";s:5:"fluid";s:11:"1.3.0-0.0.0";}}', 'Armin Ruediger Vieweg', 'armin@v.ieweg.de', 'professorweb', '041d791131e998db123a9b9fad749cd2', 'Small fix: When importing DCEs the creation of preview texts will not be performed.', '', 8003, 0, 0),
(32436, 0, 'dce', 1, '0.8.4', 88, 0, 'Dynamic Content Elements (DCE)', 'Creates easily and fast dynamic content elements. It is an alternative to flexible content elements (FCE) but without need of TemplaVoila (TV). Based on Extbase and Fluid.', 1, -1, 4, 1373302693, 'a:1:{s:7:"depends";a:4:{s:3:"php";s:11:"5.3.0-0.0.0";s:5:"typo3";s:12:"4.5.0-6.1.99";s:7:"extbase";s:11:"1.3.0-0.0.0";s:5:"fluid";s:11:"1.3.0-0.0.0";}}', 'Armin Ruediger Vieweg', 'armin@v.ieweg.de', 'professorweb', 'c0b4695403dd10e8cc834272708409e1', 'Add FAL support (for TYPO3 6.0 or greater). Just use FAL viewhelper and example configuration in category inline and group (goo.gl/cpY).', '', 8004, 0, 0),
(32437, 0, 'dce', 1, '0.8.5', 88, 0, 'Dynamic Content Elements (DCE)', 'Creates easily and fast dynamic content elements. It is an alternative to flexible content elements (FCE) but without need of TemplaVoila (TV). Based on Extbase and Fluid.', 1, -1, 4, 1375200033, 'a:1:{s:7:"depends";a:4:{s:3:"php";s:11:"5.3.0-0.0.0";s:5:"typo3";s:12:"4.5.0-6.1.99";s:7:"extbase";s:11:"1.3.0-0.0.0";s:5:"fluid";s:11:"1.3.0-0.0.0";}}', 'Armin Ruediger Vieweg', 'armin@v.ieweg.de', 'professorweb', '73c7d86a3874145bc9dae7783f7b9b39', 'Fixed bug with umlauts in TYPO3 6.1 and permissions of DCE cache files. Add new option to field configuration: dce_enable_autotranslation. Also fixed some other bugs.', '', 8005, 0, 0),
