(32477, 0, 'dce', 1, '1.3.7', 88, 0, 'Dynamic Content Elements (DCE)', 'DCE is an extension for the CMS TYPO3, which creates easily and fast dynamic content elements. It is an alternative to flexible content elements (FCE) but without need of TemplaVoila (TV). Based on Extbase and Fluid.', 2, 0, 4, 1476623119, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.2.0-7.6.99";}}', 'Armin Ruediger Vieweg', 'armin@v.ieweg.de', 'professorweb', '919e2e067243c76dc696fc98c4ed3103', 'Last version with TYPO3 6.2 compatibility. Improves the fal viewhelper and add an containerIterator to DCE object, when iterating through DCE container. See release notes for more: https://goo.gl/kfRt4U', '', 1003007, 0, 0),
(32478, 0, 'dce', 1, '1.3.8', 88, 0, 'Dynamic Content Elements (DCE)', 'DCE is an extension for the CMS TYPO3, which creates easily and fast dynamic content elements. It is an alternative to flexible content elements (FCE) but without need of TemplaVoila (TV). Based on Extbase and Fluid.', 2, 0, 4, 1483289681, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.2.0-7.6.99";}}', 'Armin Ruediger Vieweg', 'armin@v.ieweg.de', 'professorweb', 'e8655925ee6467a8e4f6c5e4e3173d54', '[BUGFIX] Add check for starttime and endtime to DCE container item get query\r\n\r\nVery last version of DCE with TYPO3 6.2 support.', '', 1003008, 0, 0),
(32479, 0, 'dce', 1, '1.4.0', 88, 0, 'Dynamic Content Elements (DCE)', 'DCE is an extension for the CMS TYPO3, which creates easily and fast dynamic content elements. It is an alternative to flexible content elements (FCE) but without need of TemplaVoila (TV). Based on Extbase and Fluid.', 2, 0, 4, 1483739386, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"7.6.0-8.9.99";}}', 'Armin Ruediger Vieweg', 'armin@v.ieweg.de', 'professorweb', '29f41436e5cdd440ccdea3e8769fd989', 'DCE major release with many new features and improvements. One breaking change, regarding backend templates. Check out release slides for all new stuff: https://goo.gl/Xp4R2w', '', 1004000, 0, 0),
(32480, 0, 'dce', 1, '1.4.1', 88, 0, 'Dynamic Content Elements (DCE)', 'DCE is an extension for the CMS TYPO3, which creates easily and fast dynamic content elements. It is an alternative to flexible content elements (FCE) but without need of TemplaVoila (TV). Based on Extbase and Fluid.', 2, 0, 4, 1487622142, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"7.6.0-8.9.99";}}', 'Armin Ruediger Vieweg', 'armin@v.ieweg.de', 'professorweb', '06f7a42151b60e2fa5b998da8730e5f5', 'Bug and compatibility fixes for TYPO3 8.6', '', 1004001, 0, 0),
(32481, 0, 'dce', 1, '1.4.2', 88, 0, 'Dynamic Content Elements (DCE)', 'DCE is an extension for the CMS TYPO3, which creates easily and fast dynamic content elements. It is an alternative to flexible content elements (FCE) but without need of TemplaVoila (TV). Based on Extbase and Fluid.', 2, 0, 4, 1487759452, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"7.6.0-8.9.99";}}', 'Armin Ruediger Vieweg', 'armin@v.ieweg.de', 'professorweb', 'c12c3be5bb6bf6b86a45e382d1a92193', 'More fixes for TYPO3 7/8 compatibility in backend.', '', 1004002, 0, 0),
(32482, 0, 'dce', 1, '1.4.4', 88, 0, 'Dynamic Content Elements (DCE)', 'Best flexform based content elements since 2012. With TCA mapping feature, simple backend view and much more features which makes it super easy to create own content element types.', 2, 0, 4, 1493986716, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"7.6.0-8.9.99";}}', 'Armin Ruediger Vieweg', 'armin@v.ieweg.de', 'professorweb', 'fbce2e2d2fa3852fa68a406a961edca3', 'Bug and compatibility fixes for TYPO3 8. Also improved dev-ops tools. The typolink viewhelpers in DCE are marked as deprecated. Please use f:link.typolink or f:uri.typolink instead.', '', 1004004, 0, 0),
(32483, 0, 'dce', 1, '1.4.5', 88, 0, 'Dynamic Content Elements (DCE)', 'Best flexform based content elements since 2012. With TCA mapping feature, simple backend view and much more features which makes it super easy to create own content element types.', 2, 0, 4, 1494320897, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"7.6.0-8.9.99";}}', 'Armin Ruediger Vieweg', 'armin@v.ieweg.de', 'professorweb', 'ca57577027273e1187effd63da62f539', 'Compatibility fixes for TYPO3 7.6 and 8.7 LTS. Also updated RTE code snippets.', '', 1004005, 0, 0),
(32484, 0, 'dce', 1, '1.4.6', 88, 0, 'Dynamic Content Elements (DCE)', 'Best flexform based content elements since 2012. With TCA mapping feature, simple backend view and much more features which makes it super easy to create own content element types.', 2, 0, 4, 1494837959, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"7.6.0-8.9.99";}}', 'Armin Ruediger Vieweg', 'armin@v.ieweg.de', 'professorweb', 'f56d83504353aed1abfb0a44e5da571a', 'Fixed Typolink Viewhelper for TYPO3 7.6 LTS and added conditional code snippets (for 7.6 and 8.7 snippets) in DCE configuration.', '', 1004006, 0, 0),
(32485, 0, 'dce', 1, '1.4.7', 88, 0, 'Dynamic Content Elements (DCE)', 'Best flexform based content elements since 2012. With TCA mapping feature, simple backend view and much more features which makes it super easy to create own content element types.', 2, 0, 4, 1494850905, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"7.6.0-8.9.99";}}', 'Armin Ruediger Vieweg', 'armin@v.ieweg.de', 'professorweb', 'e6eeb6434a2ae5bcf735f1a54fe6630c', 'Bugfixes', '', 1004007, 0, 0),
(32486, 0, 'dce', 1, '1.4.8', 88, 0, 'Dynamic Content Elements (DCE)', 'Best flexform based content elements since 2012. With TCA mapping feature, simple backend view and much more features which makes it super easy to create own content element types.', 2, 0, 4, 1500212769, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"7.6.0-8.7.99";}}', 'Armin Ruediger Vieweg', 'armin@v.ieweg.de', 'professorweb', '86eb0e587306c0e41f2b6044e893e321', 'Bugfix release, Developer Days editon. Fixes big performance issue in backend and increases compatibility to EXT:flux.', '', 1004008, 0, 0),
(32487, 0, 'dce', 1, '1.4.9', 88, 0, 'Dynamic Content Elements (DCE)', 'Best flexform based content elements since 2012. With TCA mapping feature, simple backend view and much more features which makes it super easy to create own content element types.', 2, 0, 4, 1506038085, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"7.6.0-8.7.99";}}', 'Armin Ruediger Vieweg', 'armin@v.ieweg.de', 'professorweb', '22b4ee82afeb4141ee45d5b2163e3e48', 'Massive refactorings, to improve speed of DCE extension. Special thanks to Bernhard Kraft!', '', 1004009, 0, 0),
(32488, 0, 'dce', 1, '1.4.10', 88, 0, 'Dynamic Content Elements (DCE)', 'Best flexform based content elements since 2012. With TCA mapping feature, simple backend view and much more features which makes it super easy to create own content element types.', 2, 0, 4, 1507034512, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"7.6.0-8.7.99";}}', 'Armin Ruediger Vieweg', 'armin@v.ieweg.de', 'professorweb', '3b1beccd45fa02bceb4f2ed434c67969', 'Small bugfix and add example to code snippets of RTE, of how to define a preset for CKeditor.', '', 1004010, 0, 0),
(32489, 0, 'dce', 1, '1.4.11', 88, 0, 'Dynamic Content Elements (DCE)', 'Best flexform based content elements since 2012. With TCA mapping feature, simple backend view and much more features which makes it super easy to create own content element types.', 2, 0, 4, 1510318086, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"7.6.0-8.7.99";}}', 'Armin Ruediger Vieweg', 'armin@v.ieweg.de', 'professorweb', '4c60838b90a97b12115021979e63071a', 'Several bugfixes\r\n- Permission issue for non-admins fixed\r\n- Removed php warnings in backend\r\n- Fixed Typolink 8.7 code snippet', '', 1004011, 1, 0),
(32490, 0, 'maintenance', 1, '2.0.0', 84, 70, 'Maintenance', 'Switch your TYPO3 installation into maintenance mode with only one click!\nIn maintenance mode you can easily deploy new features, make bigger update operations or update the whole system without active user on the system.', 2, 0, 4, 1329837022, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:12:"5.0.0-5.3.99";s:5:"typo3";s:12:"4.5.0-4.7.99";}}', 'Andy Grunwald', 'andygrunwald@gmail.com', 'andy.grunwald', '2dd4a55c816c4eb12eef6e26eeed5706', 'First upload of EXT:maintenance in version 1.0.0.\r\nSwitch your TYPO3 installation into maintenance mode with only ONE click!\r\n', '', 2000000, 1, 0),
(32491, 0, 'maintenance', 1, '1.0.0', 84, 6, 'Maintenance', 'Switch your TYPO3 installation into maintenance mode with only one click!\nIn maintenance mode you can easily deploy new features, make bigger update operations or update the whole system without active user on the system.', 2, 0, 4, 1329837284, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:12:"5.0.0-5.3.99";s:5:"typo3";s:12:"4.5.0-4.7.99";}}', 'Andy Grunwald', 'andygrunwald@gmail.com', 'andy.grunwald', '3e84d9769e00a16ddf17c3210276e8f7', '"Second" upload of EXT:maintenance in version 1.0.0 (now really ;)).\r\nSwitch your TYPO3 installation into maintenance mode with only ONE click!', '', 1000000, 0, 0),
(32492, 0, 'maintenance', 1, '1.0.1', 84, 8, 'Maintenance', 'Switch your TYPO3 installation into maintenance mode with only one click!\nIn maintenance mode you can easily deploy new features, make bigger update operations or update the whole system without active user on the system.', 2, 0, 4, 1331497802, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:12:"5.0.0-5.4.99";s:5:"typo3";s:12:"4.5.0-4.7.99";}}', 'Andy Grunwald', 'andygrunwald@gmail.com', 'andy.grunwald', '951fda9691c459af9b32813e3950f927', 'Small bugfix release:\r\n Fixed bug 34229: DevIpMask check and reports emails\r\n Fixed bug 34612: Fatal error: Call to undefined function lcfirst() in maintenance/Classes/Reports/Configuration.php on line 56', '', 1000001, 0, 0),
(32493, 0, 'timecollect', 1, '0.0.1', 11, 11, 'TimeCollect', 'The base for the TimeCollect System.\nTable for companies and company fields in fe_groups and fe_users', 1, 0, 0, 1329868773, 'a:1:{s:7:"depends";a:1:{s:3:"cms";s:0:"";}}', 'Casper Bach Andersen', 'casper@projectopen.dk', 'casperba', '9691b9955e9ba462aecd4811e5967d38', 'bugfixes', '', 1, 1, 0),
(32494, 0, 'tc_fbconnect', 1, '0.0.1', 22, 11, 'TCFacebook Connect', 'Let users use their Facebook account to login into TYPO3. When the user login they are logged into both Facebook and TYPO3 (using services). This preserves all standard TYPO3 fe_user functions. This is mostly a profe-of-concept, which will be presented at', 3, -1, 2, 1329894754, 'a:1:{s:7:"depends";a:1:{s:3:"cms";s:0:"";}}', 'Jon Langeland', 'jl@typoconsult.dk', 'langeland', 'e5efde77b64def0dbbb32ecdba2b65a3', 'Initial release. This is a proof-of-concept, do not use in production.', '', 1, 0, 0),
(32495, 0, 'tc_fbconnect', 1, '0.0.2', 22, 11, 'TCFacebook Connect', 'Let users use their Facebook account to login into TYPO3. When the user login they are logged into both Facebook and TYPO3 (using services). This preserves all standard TYPO3 fe_user functions.', 3, 0, 2, 1330070679, 'a:1:{s:7:"depends";a:1:{s:3:"cms";s:0:"";}}', 'Jon Langeland', 'jl@typoconsult.dk', 'langeland', 'd6ccb61a813ee92acef55d1675330b65', 'Security fix, please update', '', 2, 1, 0),
