(32536, 0, 'tnm_indexedsearchtitle', 1, '0.0.1', 7, 7, '(tnm) IndexedSearchTitle', 'This is a helper for Typoscript to properly set the Title for a search result-entry of EXT:indexed_search.\n\nJust call this userFunc by ts and set the title by using: searchTitle  myTitle [stdWrap possible]', 1, 0, 4, 1330426788, 'a:1:{s:7:"depends";a:1:{s:14:"indexed_search";s:0:"";}}', 'Gabriel Kaufmann  Typoworx', 'info@typoworx.de', 'typoworx-de', '6141429ca3a8cdf98cd4d497cd5c9a0b', 'First inital upload.', '', 1, 1, 0),
(32537, 0, 'tnm_css3pie', 1, '0.0.1', 16, 16, '(tnm) css3PIE integration', 'This is an integration of the great CSS3-PIE for migrating most useful CSS3-Features to cross-platform and IE.\nThe CSS3-PIE ports some most useful CSS3-Features to the IE-Platform (IE6) using some Javascript and IE-VML.\n\nFor a introduction-demo on TYPO3 ', 1, 0, 2, 1330427076, 'a:1:{s:7:"depends";a:1:{s:3:"cms";s:0:"";}}', 'Gabriel Kaufmann  Typoworx', 'info@typoworx.de', 'typoworx-de', 'e5aebe3ea89b4e32ddf0cb17fdb75915', 'First release.', '', 1, 0, 0),
(32538, 0, 'tnm_css3pie', 1, '0.0.2', 16, 0, '(tnm) css3PIE integration', 'This is an integration of the great CSS3-PIE for migrating most useful CSS3-Features to cross-platform and IE.\nThe CSS3-PIE ports some most useful CSS3-Features to the IE-Platform (IE6) using some Javascript and IE-VML.\n\nFor a introduction-demo on TYPO3 just include this in Typoscript:\nTyposcript-Setup\npage.includeCSS.css3PIE_demo  EXT:tnm_css3pie/res/example.css\npage.50  TEXT\npage.50.value  div class"css3pie_demo"CSS3 Pie Works ;-)/div\n/Typoscript-Setup\n\nFor a complete reference of features and more informations, please visit the CSS3PIE Webpage:\nhttp://css3pie.com\n\nDocumentation:\nhttp://css3pie.com/documentation/supported-css3-features/', 1, 0, 2, 1363276512, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:11:"4.5.0-0.0.0";}}', 'Gabriel Kaufmann  Typoworx', 'info@typoworx.de', 'typoworx-de', '8aee55d2bc945a017706bde83edf0c7b', '- fixed typo3 min-version dependency', '', 2, 1, 0),
