(32654, 0, 'ext_bibsonomy_csl', 1, '1.4.0', 0, 0, 'BibSonomy/PUMA CSL', 'Add a list of publications and tag clouds from BibSonomy or PUMA to your TYPO3 pages. Style your publication lists using CSL stylesheets (http://citationstyles.org).', 2, 0, 3, 1422294912, 'a:1:{s:7:"depends";a:3:{s:7:"extbase";s:3:"1.3";s:5:"fluid";s:3:"1.3";s:5:"typo3";s:12:"4.5.0-6.1.99";}}', 'Sebastian Bttger', 'boettger@cs.uni-kassel.de', 'bibsonomy', '165e171cad2624ba0a7b3abf2da8148e', 'For full change log have a look at https://bitbucket.org/bibsonomy/bibsonomy-typo3-csl/overviewmarkdown-header-change-log\r\n\r\n- improvements in citeproc-php for rendering csl\r\n- enhanced grouping options\r\n- removed html (br /) tags in abstracts\r\n- possi', 'HothoData GmbH, http://www.academic-puma.de', 1004000, 0, 0),
(32655, 0, 'ext_bibsonomy_csl', 1, '1.0.0', 0, 0, 'Bibsonomy CSL Extension', '', 1, 0, 3, 1349701849, 'a:1:{s:7:"depends";a:3:{s:7:"extbase";s:3:"1.3";s:5:"fluid";s:3:"1.3";s:5:"typo3";s:9:"4.3-0.0.0";}}', '', '', 'bibsonomy', 'ae37f7106fdf77fe73a696ad744969eb', '"Extension to create publication lists based on the Citation Style Language (CSL). Allows direct integration with the social bookmarking and publication sharing system Bibsonomy http://www.bibsonomy.org or different sources. \n\nFeatures:\n- Render publicat', '', 1000000, 0, 0),
(32656, 0, 'ext_bibsonomy_csl', 1, '0.0.1', 0, 0, 'BibSonomy CSL Extension', 'This is new version  of the BibSonomy extension. The older version is no longer being developed. Extension to create publication lists based on the Citation Style Language (CSL). Allows direct integration with the social bookmarking and publication sharing system Bibsonomy http://www.bibsonomy.org or different sources.', 1, 0, 3, 1350379341, 'a:1:{s:7:"depends";a:3:{s:7:"extbase";s:3:"1.3";s:5:"fluid";s:3:"1.3";s:5:"typo3";s:9:"4.3-0.0.0";}}', 'Sebastian Bttger, Dominik Benz, Andreas Hotho', 'typo3@bibsonomy.org', 'bibsonomy', '11d615f2b38cdb94a23591971109c002', 'Changed extension description details and author informations.', 'Knowledge and Data Engineering, University of Kassel', 1, 0, 0),
(32657, 0, 'ext_bibsonomy_csl', 1, '0.0.2', 0, 0, 'BibSonomy CSL Extension', 'This is new version  of the BibSonomy extension. The older version is no longer being developed. Extension to create publication lists based on the Citation Style Language (CSL). Allows direct integration with the social bookmarking and publication sharing system Bibsonomy http://www.bibsonomy.org or different sources.', 1, 0, 3, 1350893485, 'a:1:{s:7:"depends";a:3:{s:7:"extbase";s:3:"1.3";s:5:"fluid";s:3:"1.3";s:5:"typo3";s:9:"4.3-0.0.0";}}', 'Sebastian Bttger, Dominik Benz, Andreas Hotho', 'typo3@bibsonomy.org', 'bibsonomy', 'bc1100b10cc0946a7cf54fbf35229537', 'This is new version of the BibSonomy extension. The older version is no longer being developed. Extension to create publication lists based on the Citation Style Language (CSL). Allows direct integration with the social bookmarking and publication sharing', 'Knowledge and Data Engineering, University of Kassel', 2, 0, 0),
