(32676, 0, 'ext_bibsonomy_csl', 1, '2.1.7', 0, 0, 'PUMA/BibSonomy CSL', 'Create advanced bibliographies or simple lists of publications and tag clouds from your PUMA or BibSonomy account. Style your publication lists using CSL stylesheets (http://citationstyles.org).', 1, 0, 3, 1486571056, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:12:"5.4.0-7.0.99";s:5:"typo3";s:12:"6.2.0-7.6.99";}}', 'Sebastian Bttger', 'boettger@cs.uni-kassel.de', 'bibsonomy', 'ab3ee049c4220f657a4875aaa902498f', 'Fixes: \r\n- Umlaute were fixed via a new restclien-php\r\n- Grouping is now working as expected \r\n- custom CSL is working again\r\n- download button for missing publications deativated \r\n- custom server setting is default now\r\n- Markup is improved (dangling ', '', 2001007, 0, 0),
(32677, 0, 'ext_bibsonomy_csl', 1, '2.1.8', 0, 0, 'PUMA/BibSonomy CSL', 'Create advanced bibliographies or simple lists of publications and tag clouds from your PUMA or BibSonomy account. Style your publication lists using CSL stylesheets (http://citationstyles.org).', 1, 0, 3, 1487939107, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:12:"5.4.0-7.0.99";s:5:"typo3";s:12:"6.2.0-7.6.99";}}', 'Sebastian Bttger', 'boettger@cs.uni-kassel.de', 'bibsonomy', 'cf5a779729d71292d75ba37264220b70', 'Fixed: \r\n- Problem with TagCloud when conjuction of tags leads to empty set. ', '', 2001008, 0, 0),
(32678, 0, 'ext_bibsonomy_csl', 1, '2.1.9', 0, 0, 'PUMA/BibSonomy CSL', 'Create advanced bibliographies or simple lists of publications and tag clouds from your PUMA or BibSonomy account. Style your publication lists using CSL stylesheets (http://citationstyles.org).', 1, 0, 3, 1488538991, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:12:"5.4.0-7.0.99";s:5:"typo3";s:12:"6.2.0-7.6.99";}}', 'Sebastian Bttger', 'boettger@cs.uni-kassel.de', 'bibsonomy', 'b73b57922bed536690bb8253cd0e1703', 'This version fixes the tag-cloud-probelm  with random ignored tags.', '', 2001009, 0, 0),
(32679, 0, 'ext_bibsonomy_csl', 1, '2.1.12', 0, 0, 'PUMA/BibSonomy CSL', 'Create advanced bibliographies or simple lists of publications and tag clouds from your PUMA or BibSonomy account. Style your publication lists using CSL stylesheets (http://citationstyles.org).', 1, 0, 3, 1494860842, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:12:"5.4.0-7.0.99";s:5:"typo3";s:12:"6.2.0-7.6.99";}}', 'Sebastian Bttger', 'boettger@cs.uni-kassel.de', 'bibsonomy', 'c93c8b3c40e6705ed9cc968fb90d2f31', 'Fixed several issues and enhanced functionality: \r\n- Now handling publications with the entrytype Unpublished"\r\n- Possible to sort after publication type within year grouping (DBLP-like)\r\n- Option to escape reserved special characters in the BibTeX of th', '', 2001012, 0, 0),
(32680, 0, 'ext_bibsonomy_csl', 1, '2.1.13', 0, 0, 'PUMA/BibSonomy CSL', 'Create advanced bibliographies or simple lists of publications and tag clouds from your PUMA or BibSonomy account. Style your publication lists using CSL stylesheets (http://citationstyles.org).', 1, 0, 3, 1496759439, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:12:"5.4.0-7.0.99";s:5:"typo3";s:12:"6.2.0-7.6.99";}}', 'Sebastian Bttger', 'boettger@cs.uni-kassel.de', 'bibsonomy', 'e70e4614ebfbedfa2194c6b532a2ba23', 'Fixed: \r\n- Capitalization issues\r\n- Improved notes placement\r\n- PDF in new Tab\r\n- completed DBLP-like sort', '', 2001013, 0, 0),
(32681, 0, 'ext_bibsonomy_csl', 1, '2.1.15', 0, 0, 'PUMA/BibSonomy CSL', 'Create advanced bibliographies or simple lists of publications and tag clouds from your PUMA or BibSonomy account. Style your publication lists using CSL stylesheets (http://citationstyles.org).', 1, 0, 3, 1499785103, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:12:"5.4.0-7.0.99";s:5:"typo3";s:12:"6.2.0-7.6.99";}}', 'Sebastian Bttger', 'boettger@cs.uni-kassel.de', 'bibsonomy', '5167bb01e3beb20ff97eb0016a8a8342', '- Fixed various problems with math operators in math environments. \r\n- Introduced new name-link feature. \r\n- Links are now opened in new tabs. \r\n- DBLP-like sorting fixed.', '', 2001015, 0, 0),
(32682, 0, 'ext_bibsonomy_csl', 1, '2.1.16', 0, 0, 'PUMA/BibSonomy CSL', 'Create advanced bibliographies or simple lists of publications and tag clouds from your PUMA or BibSonomy account. Style your publication lists using CSL stylesheets (http://citationstyles.org).', 1, 0, 3, 1505916355, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:12:"5.4.0-7.0.99";s:5:"typo3";s:12:"6.2.0-7.6.99";}}', 'Kevin Choong', 'kch@cs.uni-kassel.de', 'bibsonomy', '7f4dffa17535597a0bf1542fa9649e12', 'Fixes: \r\n- DBLP-Sort for other parenthesis type\r\n- Tag-Cloud-Links fixed\r\n- pdf-files with comma in chrome now working\r\nFeatures:\r\n- Host-Button for resource added\r\n- Now pure BibTex is provided after clikcing on BibTeX button', '', 2001016, 0, 0),
(32683, 0, 'ext_bibsonomy_csl', 1, '2.1.17', 0, 0, 'PUMA/BibSonomy CSL', 'Create advanced bibliographies or simple lists of publications and tag clouds from your PUMA or BibSonomy account. Style your publication lists using CSL stylesheets (http://citationstyles.org).', 1, 0, 3, 1506433464, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:12:"5.4.0-7.0.99";s:5:"typo3";s:12:"6.2.0-7.6.99";}}', 'Sebastian Bttger', 'boettger@cs.uni-kassel.de', 'bibsonomy', '6c5cad5e8d0ce9bc902692e0b9082caf', '- Removed depricated methods for image paths\r\n- Improved author links\r\n- Remove leading backslashes in class paths (Thanks Maximilian Vlker)\r\n- Fixed wrong namespace in AuthenticationRepository (Thanks Maximilian Vlker)', '', 2001017, 0, 0),
(32684, 0, 'ext_bibsonomy_csl', 1, '2.1.18', 0, 0, 'PUMA/BibSonomy CSL', 'Create advanced bibliographies or simple lists of publications and tag clouds from your PUMA or BibSonomy account. Style your publication lists using CSL stylesheets (http://citationstyles.org).', 1, 0, 3, 1508848777, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:12:"5.4.0-7.0.99";s:5:"typo3";s:12:"6.2.0-7.6.99";}}', 'Kevin Choong', 'kch@cs.uni-kassel.de', 'bibsonomy', 'effa62f6fc08c1e8bca4c3fbe6bc76b1', 'FixesnFeatures: \r\n- Fixed Author-Links for umlauts\r\n- The Author-Links data can now be provided via link instead of list\r\n- LNCS-Support for author links\r\n- DBLP-like-sort now honors CoRR and related things', '', 2001018, 1, 0),
