(32703, 0, 'leadlab', 1, '0.0.1', 17, 6, 'LeadLab-Integration for Typo3', 'Integration of a countingcode used by LeadLab. The code will be placed in front of the /body tag to each page rendered by Typo3. \nThe User has full control both of general and individual Settings without the need of writing one single line of TypoScript', 1, 0, 2, 1330883092, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:3:"php";s:12:"5.0.0-5.3.99";s:5:"typo3";s:12:"4.1.0-4.7.99";}}', 'Uwe Jakobs', 'leadlab@imageco.de', 'bitbull', '852163e1e2c65b3faeff6c1590df2a15', 'Initial Release', '', 1, 0, 0),
