(32744, 0, 't3_less', 1, '0.0.1', 59, 7, 'LESS for TYPO3', 'An easy to use extbase extension to compile .less-files with the leafo.net less-php-compiler. It is also possible to include compiled files and delete unused/old compiled files automaticaly.', 0, 0, 3, 1331711695, 'a:1:{s:7:"depends";a:2:{s:7:"extbase";s:5:"1.3.0";s:5:"fluid";s:5:"1.3.0";}}', 'David Greiner', 'hallo@davidgreiner.de', 'greinerd', 'e8531fb420b81aa5c5d7d0f55e6d874b', 'Initial release on TER. Documentation will coming soon, but isnt really needed. This extension is very easy to use. Install the extension, include static template and configure some settings in the constant editor. Have fun!', '', 1, 0, 0),
(32745, 0, 't3_less', 1, '0.0.2', 59, 6, 'LESS for TYPO3', 'An easy to use extbase extension to compile .less-files with the leafo.net less-php-compiler. It is also possible to include compiled files and delete unused/old compiled files automaticaly.', 0, 0, 3, 1331797789, 'a:1:{s:7:"depends";a:2:{s:7:"extbase";s:5:"1.3.0";s:5:"fluid";s:5:"1.3.0";}}', 'David Greiner', 'hallo@davidgreiner.de', 'greinerd', 'c2ccbbb7acff4d60192463dc8d83494f', 'Adding short documentation, full-documentation will coming soon! Have fun!', '', 2, 0, 0),
(32746, 0, 't3_less', 1, '0.1.0', 59, 2, 'LESS for TYPO3', 'An easy to use extbase extension to compile .less-files with the leafo.net less-php-compiler. It is also possible to include compiled files and delete unused/old compiled files automaticaly.', 1, 0, 3, 1331926220, 'a:0:{}', 'David Greiner', 'hallo@davidgreiner.de', 'greinerd', 'fe433acfc275db2ae138d29d23037832', 'Adding possibility to choose beetween php-compiler and js-compiler. Js-compiler uses less.js from lesscss.org and includes all less-files from defined lessfolder to the head and less.js to the footer. Have fun! ', '', 1000, 0, 0),
(32747, 0, 't3_less', 1, '0.1.1', 59, 15, 'LESS for TYPO3', 'An easy to use extbase extension for using LESScss in TYPO3. You can choose between leafo.net LESS-PHP-compiler or Javascript-based less.js-compiler. It is also possible to include compiled files and delete unused/old compiled files automaticaly.', 2, 0, 3, 1331972932, 'a:1:{s:7:"depends";a:2:{s:7:"extbase";s:5:"1.3.0";s:5:"fluid";s:5:"1.3.0";}}', 'David Greiner', 'hallo@davidgreiner.de', 'greinerd', 'e821d10b5e58d99cd5bc511b260ecb8f', 'Delete some no longer files and changing extension description', '', 1001, 0, 0),
