(32753, 0, 't3_less', 1, '0.3.3', 59, 0, 'LESS for TYPO3', 'An easy to use extbase extension for using LESScss in TYPO3. You can choose between leafo.net LESS-PHP-compiler or Javascript-based less.js-compiler. It is also possible to include compiled files and delete unused/old compiled files automaticaly.', 2, 0, 3, 1335608853, 'a:0:{}', 'David Greiner', 'hallo@davidgreiner.de', 'greinerd', '16be907d6d34bd4f8d4582621579e59c', '- Updating PHP-Compiler to v0.3.4 (http://leafo.net/lessphp/, thanks to leafo)\n- syncing TER with version from forge\n- Adding possibility to exclude seperate files from pagerenderer (See @forge: 35938, thanks to Manfred Egger) \n- Updating manual', '', 3003, 0, 0),
(32754, 0, 't3_less', 1, '0.4.0', 59, 0, 'LESS for TYPO3', 'An easy to use extbase extension for using LESScss in TYPO3. You can choose between leafo.net LESS-PHP-compiler or Javascript-based less.js-compiler. It is also possible to include compiled files and delete unused/old compiled files automaticaly.', 2, 0, 3, 1335693707, 'a:0:{}', 'David Greiner', 'hallo@davidgreiner.de', 'greinerd', '51e132224ae986ba62c2d22eae52d355', 'Extension now uses TYPO3-render-preProcess-Hook to be integrated in renderprocess. Please remove extension and import the new version. Have fun and thanks to Manfred Egger for this hint!', '', 4000, 0, 0),
(32755, 0, 't3_less', 1, '0.5.0', 59, 0, 'LESS for TYPO3', 'An easy to use extbase extension for using LESScss in TYPO3. You can choose between leafo.net LESS-PHP-compiler or Javascript-based less.js-compiler. It is also possible to include compiled files and delete unused/old compiled files automaticaly.', 2, 0, 3, 1338123845, 'a:0:{}', 'David Greiner', 'hallo@davidgreiner.de', 'greinerd', '139e4e28e6f2a42297d34d8c59d96191', 'Adding/fixing feature requests/bugs: 37117, 37514, 37515. Thanks for reporting! \nIt is now possible to pass less-files from other extensions using a hook. See manual for details.\n', '', 5000, 0, 0),
(32756, 0, 't3_less', 1, '0.5.1', 59, 0, 'LESS for TYPO3', 'An easy to use extbase extension for using LESScss in TYPO3. You can choose between leafo.net LESS-PHP-compiler or Javascript-based less.js-compiler. It is also possible to include compiled files and delete unused/old compiled files automaticaly.', 2, 0, 3, 1339847350, 'a:0:{}', 'David Greiner', 'hallo@davidgreiner.de', 'greinerd', 'a62086d0b16538f4e74d02e1dbf61cd1', '- Adding feature to define sort order for each included file\n- manual is included, but it seems there are some render problems, take it from doc/manual.sxw', '', 5001, 0, 0),
(32757, 0, 't3_less', 1, '0.5.2', 59, 0, 'LESS for TYPO3', 'An easy to use extbase extension for using LESScss in TYPO3. You can choose between leafo.net LESS-PHP-compiler or Javascript-based less.js-compiler. It is also possible to include compiled files and delete unused/old compiled files automaticaly.', 2, 0, 3, 1347562097, 'a:0:{}', 'David Greiner', 'hallo@davidgreiner.de', 'greinerd', 'eaddf76298d32890dc0f38408a5de777', '- Updating lessphp-script to 0.3.8,\n- Adding some features like file-compression, force-mode\n- Updating manual \nFor more details look at http://forge.typo3.org/projects/extension-t3_less\n', '', 5002, 0, 0),
