(32787, 0, 'zw_secfileform', 1, '0.0.2', 9, 9, '2W Secure Download Form', 'This extension combines the power of formhandler and css_filelinks & dam_filelinks to display a form before being able to download files. Once the form is submitted successfully the filelinks are enabled and the files can be downloaded (securely throght "', 0, 0, 3, 1332167990, 'a:1:{s:7:"depends";a:6:{s:7:"extbase";s:5:"1.3.0";s:5:"fluid";s:5:"1.3.0";s:11:"formhandler";s:0:"";s:3:"dam";s:0:"";s:13:"css_filelinks";s:0:"";s:13:"dam_filelinks";s:0:"";}}', 'Robert Wunsch', 'robert.wunsch@2w.de', 'rwunsch', 'dddfd337a88aa37b1ba41076c45760c4', 'Initial release.\nNot fully finished,\nWraps css_filelinks with dam_filelinks for DAM to display a form before being able to download files.', '2W Media GmbH', 2, 1, 0),
(32788, 0, 'tnm_pagebrowse4ts', 1, '0.0.1', 9, 9, '(tnm) pagebrowse for typoscript', 'This extension can be used to integrate the well-known Extension "pagebrowse" to be used in pure typoscript (without touching PHP!).', 1, 0, 3, 1332335776, 'a:1:{s:7:"depends";a:2:{s:3:"cms";s:0:"";s:10:"pagebrowse";s:0:"";}}', 'Gabriel Kaufmann  Typoworx', 'info@typoworx.de', 'typoworx-de', 'e5cc979f7b2f7ebeee566b7de31c7f3a', 'Added PI1 to Improve PageBrowse-functionality for use with Typoscript "CONTENT" Objects. The PI1 can be used as 1:1 alternative for "CONTENT" Objects implementing the EXT: Pagebrowse PageBrowser without tricks in Typoscript.', '', 1, 0, 0),
