(32923, 0, 'rx_shariff', 1, '9.0.0', 0, 0, 'Heise Shariff', 'Shariff implementation for TYPO3 CMS including the backend module, a viewhelper and a plugin.', 2, 0, 3, 1475518297, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:12:"5.6.0-7.1.99";s:5:"typo3";s:13:"6.2.9-8.99.99";}}', 'Markus Klein', 'support@reelworx.at', 'liayn', '6f2773a816a476418050a6e040b64cc6', ' BREAKING: The static templates have been renamed and need to be re-included.\r\n  Moreover, including a static template is now mandatory.\r\n Feature: The plugin options can be defiend via TypoScript now.\r\n Documentation has been updated to the new render', 'Reelworx GmbH', 9000000, 0, 0),
(32924, 0, 'rx_shariff', 1, '9.0.1', 0, 0, 'Heise Shariff', 'Shariff implementation for TYPO3 CMS including the backend module, a viewhelper and a plugin.', 2, 0, 3, 1478354394, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:12:"5.6.0-7.1.99";s:5:"typo3";s:12:"6.2.9-8.5.99";}}', 'Markus Klein', 'support@reelworx.at', 'liayn', '7b14e992460e4494754a45ea67c5b83b', ' The cache for share counts now uses the correct cache backend,\r\n  so entries are expired correctly now.\r\n Documentation fixes', 'Reelworx GmbH', 9000001, 0, 0),
(32925, 0, 'rx_shariff', 1, '10.1.0', 0, 0, 'Heise Shariff', 'Shariff implementation for TYPO3 CMS including the backend module, a viewhelper and a plugin.', 2, 0, 3, 1504699857, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:12:"5.6.0-7.1.99";s:5:"typo3";s:12:"6.2.9-8.7.99";}}', 'Markus Klein', 'support@reelworx.at', 'liayn', 'df218657075821a0c656ab2191961d94', ' Updated shariff to version 1.26.2\r\n Added new static templates to include the new complete-JS of Shariff, which does not depend on jQuery anymore.', 'Reelworx GmbH', 10001000, 0, 0),
(32926, 0, 'rx_shariff', 1, '10.0.0', 0, 0, 'Heise Shariff', 'Shariff implementation for TYPO3 CMS including the backend module, a viewhelper and a plugin.', 2, 0, 3, 1490884017, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:12:"5.6.0-7.1.99";s:5:"typo3";s:12:"6.2.9-8.7.99";}}', 'Markus Klein', 'support@reelworx.at', 'liayn', '8e168eba50cac7c788bc8756027aca8e', ' BREAKING: The Facebook backend now always needs an app id and an API secret the former FQL mode has been removed.\r\n Updated shariff-backend to version 7.0.0\r\n Updated shariff to version 1.24.1', 'Reelworx GmbH', 10000000, 0, 0),
(32927, 0, 'rx_shariff', 1, '10.0.1', 0, 0, 'Heise Shariff', 'Shariff implementation for TYPO3 CMS including the backend module, a viewhelper and a plugin.', 2, 0, 3, 1493913307, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:12:"5.6.0-7.1.99";s:5:"typo3";s:12:"6.2.9-8.7.99";}}', 'Markus Klein', 'support@reelworx.at', 'liayn', '3de2fc44385810cefcff05d62c380f13', ' Fixed Fluid template to work in TYPO3 6.2 as well', 'Reelworx GmbH', 10000001, 0, 0),
(32928, 0, 'rx_shariff', 1, '10.2.0', 0, 0, 'Heise Shariff', 'Shariff implementation for TYPO3 CMS including the backend module, a viewhelper and a plugin.', 2, 0, 3, 1508945551, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:12:"5.6.0-7.1.99";s:5:"typo3";s:12:"6.2.9-8.7.99";}}', 'Markus Klein', 'support@reelworx.at', 'liayn', 'c27e617ef64267827764c24160e6c619', ' Updated shariff to version 2.0.1\r\n  This fixes IE issues\r\n Allow explicit definition of language via plugin or TypoScript again.\r\n  This may cause unexpected language selection in FE when a plugin was\r\n  created before version 7.3.0 because these plugi', 'Reelworx GmbH', 10002000, 0, 0),
(32929, 0, 'rx_shariff', 1, '10.2.1', 0, 0, 'Heise Shariff', 'Shariff implementation for TYPO3 CMS including the backend module, a viewhelper and a plugin.', 2, 0, 3, 1511181328, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:12:"5.6.0-7.1.99";s:5:"typo3";s:12:"6.2.9-8.7.99";}}', 'Markus Klein', 'support@reelworx.at', 'liayn', '2fa03cd5eba9f6b04c86734a4fea533c', 'Updated shariff-backend to version 7.0.1.\r\nThis fixes issues with newer Facebook accounts not showing the share count.', 'Reelworx GmbH', 10002001, 1, 0),
