(33104, 0, 'sf_register', 1, '6.2.2', 0, 0, 'Frontend User Registration', 'Offers the possibility to maintain the fe_user data in frontend by the user self.', 1, -1, 3, 1411998049, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:12:"6.2.0-6.2.99";s:7:"extbase";s:12:"6.2.0-6.2.99";s:5:"fluid";s:12:"6.2.0-6.2.99";}}', 'Sebastian Fischer', 'typo3@evoweb.de', 'sfischer', 'c7d885718e606a183f882daf554597b7', 'Bugfixing image upload thanks to Frans Saris\r\nAdd unique exclude current validator thanks to Frans Saris\r\nModifying confirmation thanks to Oliver Hader \r\nBugfixing validation if empty value thanks to Oliver Hader', 'evoweb', 6002002, 0, 0),
(33105, 0, 'sf_register', 1, '6.2.3', 0, 0, 'Frontend User Registration', 'Offers the possibility to maintain the fe_user data in frontend by the user self.', 1, -1, 3, 1413126916, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:12:"6.2.0-6.2.99";s:7:"extbase";s:12:"6.2.0-6.2.99";s:5:"fluid";s:12:"6.2.0-6.2.99";}}', 'Sebastian Fischer', 'typo3@evoweb.de', 'sfischer', '9f33aeadae6efbfdb08cab15496b9130', 'Add signal in initializeAction of FeuserController\r\nAdd slot that consumes the signal and redirects if a user is not logged in in the edit form', 'evoweb', 6002003, 0, 0),
