(33165, 0, 'fluidcontent', 1, '1.0.0', 0, 0, 'Fluid Content Elements', 'Content elements written in Fluid using EXT:fed. Install dependencies, include static TS and enable Fluid Content Elements in extension configuration for EXT:fed.', 2, 0, 4, 1335097959, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:9:"4.5-0.0.0";s:3:"cms";s:0:"";s:3:"fed";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'fluidtypo3', 'e40135af679c5491a9e5b3028cee3ee9', 'Initial TER upload. Contains all built-in Fluid Content Elements from EXT:fed - required companion extension for EXT:fed 1.4.14 which will be released very soon.', 'Wildside A/S', 1000000, 0, 0),
(33166, 0, 'fluidcontent', 1, '1.1.0', 0, 0, 'Fluid Content Elements', 'Content elements written in Fluid using EXT:fed. Install dependencies, include static TS and enable Fluid Content Elements in extension configuration for EXT:fed.', 2, 0, 4, 1335125140, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:9:"4.5-0.0.0";s:3:"cms";s:0:"";s:3:"fed";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'fluidtypo3', '35bc9f55607351d233b1da382c5f959b', 'Added basic set of Twitter Bootstrap content elements.', 'Wildside A/S', 1001000, 0, 0),
(33167, 0, 'fluidcontent', 1, '1.2.0', 0, 0, 'Fluid Content Elements', 'Content elements written in Fluid using EXT:fed. Install dependencies, include static TS and enable Fluid Content Elements in extension configuration for EXT:fed.', 2, 0, 4, 1335215204, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:9:"4.5-0.0.0";s:3:"cms";s:0:"";s:3:"fed";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'fluidtypo3', '9d5155dc91013fad8e311e8468651986', 'Added Twitter Bootstrap Tab/Pill and Accordion content elements. Divides other content elements into tabs, pill-type navigation sections or accordion panels.', 'Wildside A/S', 1002000, 0, 0),
(33168, 0, 'fluidcontent', 1, '1.3.0', 0, 0, 'Fluid Content Elements', 'Content elements written in Fluid using EXT:fed. Install dependencies, include static TS and enable Fluid Content Elements in extension configuration for EXT:fed.', 2, 0, 4, 1335646566, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:9:"4.5-0.0.0";s:3:"cms";s:0:"";s:3:"fed";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'fluidtypo3', '15284d67e75d8c4802587512a1c2d9dd', 'Added Navigation List element (Twitter Bootstrap) - very versatile links list ideal for sliding content, highlights active page if used as page menu and supports icons. Improved Tabs element (Bootstrap) to allow tabs to be placed left, right top and botto', 'Wildside A/S', 1003000, 0, 0),
(33169, 0, 'fluidcontent', 1, '1.3.1', 0, 0, 'Fluid Content Elements', 'Content elements written in Fluid using EXT:fed. Install dependencies, include static TS and enable Fluid Content Elements in extension configuration for EXT:fed.', 1, 0, 4, 1346515221, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:9:"4.5-0.0.0";s:3:"cms";s:0:"";s:3:"fed";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'fluidtypo3', '67ccf6e66cc790790e5d6819f8488306', 'Bugfix for NavigationList Bootstrap FCE to work with latest Flux version.', 'Wildside A/S', 1003001, 0, 0),
(33170, 0, 'fluidcontent', 1, '1.3.2', 0, 0, 'Fluid Content Elements', 'Content elements written in Fluid using EXT:fed. Install dependencies, include static TS and enable Fluid Content Elements in extension configuration for EXT:fed.', 1, 0, 4, 1346516158, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:9:"4.5-0.0.0";s:3:"cms";s:0:"";s:3:"fed";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'fluidtypo3', '06fd0b5660daf29ba3993efc1f81740d', 'Removed accidentally included testing element.', 'Wildside A/S', 1003002, 0, 0),
(33171, 0, 'fluidcontent', 1, '1.3.3', 0, 0, 'Fluid Content Elements', 'Content elements written in Fluid using EXT:fed. Install dependencies, include static TS and enable Fluid Content Elements in extension configuration for EXT:fed.', 1, 0, 4, 1350170175, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:9:"4.5-0.0.0";s:3:"cms";s:0:"";s:3:"fed";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'fluidtypo3', '5c737b152840048d638e26956b1d410f', 'Added AJAX container; elements inserted into this content element are loaded through AJAX. Requires all latest versions of flux and fluidwidget; read more in the full change log at https://github.com/NamelessCoder/fluidcontent/commits/master', 'Wildside A/S', 1003003, 0, 0),
(33172, 0, 'fluidcontent', 1, '2.0.0', 0, 0, 'Fluid Content Elements', 'Fluid Content Element engine - integrates extremely compact and highly dynamic content element templates written in Fluid. See: https://github.com/NamelessCoder/fluidcontent', 1, 0, 4, 1355621493, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:9:"4.5-0.0.0";s:3:"cms";s:0:"";s:4:"flux";s:5:"5.0.0";}}', 'Claus Due', 'claus@wildside.dk', 'fluidtypo3', 'f13ad0b213bef6dbe107604ff0869408', 'Now functions without FED: contains the Fluid Content Element features ported from FED - if installed at the same time as FED, will override the Fluid Content Elements feature in FED.', 'Wildside A/S', 2000000, 0, 0),
(33173, 0, 'fluidcontent', 1, '2.1.0', 0, 0, 'Fluid Content Elements', 'Fluid Content Element engine - integrates extremely compact and highly dynamic content element templates written in Fluid. See: https://github.com/NamelessCoder/fluidcontent', 2, 0, 4, 1356911612, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:9:"4.5-0.0.0";s:3:"cms";s:0:"";s:4:"flux";s:5:"5.0.0";}}', 'Claus Due', 'claus@wildside.dk', 'fluidtypo3', '0f83a6fb662478c96009878e9fa73a7f', 'WARNING: removes the included elements - you must install EXT:fluidcontent_fed and/or EXT:fluidcontent_bootstrap (and include their static TS) to restore your content elements, depending on which set(s) you use. Only affects elements from EXT:fluidcontent', 'Wildside A/S', 2001000, 0, 0),
(33174, 0, 'fluidcontent', 1, '2.1.1', 0, 0, 'Fluid Content Engine', 'Fluid Content Element engine - integrates extremely compact and highly dynamic content element templates written in Fluid. See: https://github.com/NamelessCoder/fluidcontent', 2, 0, 4, 1357690859, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:9:"4.5-0.0.0";s:3:"cms";s:0:"";s:4:"flux";s:5:"5.0.0";}}', 'Claus Due', 'claus@wildside.dk', 'fluidtypo3', '62c1992911044dbc143d5c74a0dac8b6', 'Fixes logout crash bug on 6.0. Improves error reporting in frontend when configuration or selected element is invalid - previously would cause exceptions.', 'Wildside A/S', 2001001, 0, 0),
(33175, 0, 'fluidcontent', 1, '2.2.0', 0, 0, 'Fluid Content Engine', 'Fluid Content Element engine - integrates extremely compact and highly dynamic content element templates written in Fluid. See: https://github.com/NamelessCoder/fluidcontent', 2, 0, 4, 1358119600, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:9:"4.5-0.0.0";s:3:"cms";s:0:"";s:4:"flux";s:5:"5.0.0";}}', 'Claus Due', 'claus@wildside.dk', 'fluidtypo3', '14fbc24df1ab1cc599ddfd356a014952', 'Refactors detection, parsing and generation of wizard tab items for Fluid Content Elements into a Service. Restores clearing of cached element registrations on clearing cache. Improves stability when processing FCE registrations. Improves fault tolerance ', 'Wildside A/S', 2002000, 0, 0),
