(33201, 0, 'styleguide', 1, '0.5.0', 0, 0, 'TYPO3 CMS Backend Styleguide', '', 0, 0, 3, 1376146374, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:3:"6.2";}}', 'Felix Kopp', 'felix-source@phorax.com', '7elix', '84d04a0b9981ffd93c77cdb04044df86', 'Release 0.5.0, new structure and new tempates and examples. Also brings descriptions and improved structure / sections.', 'PHORAX', 5000, 0, 0),
(33202, 0, 'styleguide', 1, '0.5.2', 0, 0, 'TYPO3 CMS Backend Styleguide', '', 0, 0, 3, 1380875974, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.1.0-6.1.99";}}', 'Felix Kopp', 'felix-source@phorax.com', '7elix', '6c688d8ff2c18a91be7e250f3d672e50', 'Minor typography adaptions. Removes override lead since lead is included in 6.2-dev now. ', 'PHORAX', 5002, 0, 0),
(33203, 0, 'styleguide', 1, '0.6.0', 0, 0, 'TYPO3 CMS Backend Styleguide', '', 0, 0, 3, 1390606609, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.1.0-6.2.99";}}', 'Felix Kopp', 'felix-source@phorax.com', '7elix', '391d7d27430a01408f0ef979ac54f931', 'Version 0.6.0 brings buttons overview and minor bugfixes.', 'PHORAX', 6000, 0, 0),
(33204, 0, 'styleguide', 1, '0.6.1', 0, 0, 'TYPO3 CMS Backend Styleguide', 'Presents all supported styles for TYPO3 backend modules. Mocks typography, tables, forms, buttons, flash messages and helpers. More at https://github.com/7elix/TYPO3.CMS.Styleguide', 0, 0, 3, 1390954633, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.2.0-6.2.99";}}', 'Felix Kopp', 'felix-source@phorax.com', '7elix', '9eecaa7f8860790edc1f371160641b46', 'Minor change in table view based on http://forge.typo3.org/issues/52599. Also adds description for TER.', 'PHORAX', 6001, 0, 0),
(33205, 0, 'styleguide', 1, '0.7.0', 0, 0, 'TYPO3 CMS Backend Styleguide', 'Presents all supported styles for TYPO3 backend modules. Mocks typography, tables, forms, buttons, flash messages and helpers. More at https://github.com/7elix/TYPO3.CMS.Styleguide', 0, 0, 3, 1391968678, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.2.0-6.2.99";}}', 'Felix Kopp', 'felix-source@phorax.com', '7elix', 'ba243574dd4c7dad53cb83b3a574991c', '0.7.0 brings lists to typography: UL & OL', 'PHORAX', 7000, 0, 0),
(33206, 0, 'styleguide', 1, '0.8.0', 0, 0, 'TYPO3 CMS Backend Styleguide', 'Presents all supported styles for TYPO3 backend modules. Mocks typography, tables, forms, buttons, flash messages and helpers. More at https://github.com/7elix/TYPO3.CMS.Styleguide', 2, 0, 3, 1393717750, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.2.0-6.2.99";}}', 'Felix Kopp', 'felix-source@phorax.com', '7elix', 'fcd75a6ead947ce3d8cad725b3b9fe1c', 'Now with beautiful colorful styling for code previews.', 'PHORAX', 8000, 0, 0),
(33207, 0, 'styleguide', 1, '7.0.0', 0, 0, 'TYPO3 CMS Backend Styleguide', 'Presents all supported styles for TYPO3 backend modules. Mocks typography, tables, forms, buttons, flash messages and helpers. More at https://github.com/7elix/TYPO3.CMS.Styleguide', 2, 0, 3, 1417625661, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:13:"7.0.0-7.0.999";}}', 'Felix Kopp', 'felix-source@phorax.com', '7elix', '4e28a0a698e71c2818b3700b8956e667', 'For extension developers and integrators - release 7.0 brings compatibility with TYPO3 CMS 7 and includes twbs Bootstrap, panel, master TCA record, icons listing, tabs. Major release for your extensions 3', 'PHORAX', 7000000, 0, 0),
(33208, 0, 'styleguide', 1, '7.4.0', 0, 0, 'TYPO3 CMS Backend Styleguide', 'Presents most supported styles for TYPO3 backend modules. Mocks typography, tables, forms, buttons, flash messages and helpers. More at https://github.com/7elix/TYPO3.CMS.Styleguide', 2, 0, 3, 1439312495, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:13:"7.4.0-7.99.99";}}', 'Felix Kopp', 'felix-source@phorax.com', '7elix', '3a78228c81b488f4120b51e3ebfb05ae', 'Updates for TYPO3 CMS version 7.4 with new icon file paths, loads of TCA improvements and require demo, avatar show case, simplyfied travis-ci integration. 3', 'PHORAX', 7004000, 0, 0),
(33209, 0, 'styleguide', 1, '7.6.0', 0, 0, 'TYPO3 CMS Backend Styleguide', 'Presents most supported styles for TYPO3 backend modules. Mocks typography, tables, forms, buttons, flash messages and helpers. More at https://github.com/7elix/TYPO3.CMS.Styleguide', 2, 0, 3, 1448209063, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:13:"7.6.0-7.99.99";}}', 'Felix Kopp', 'felix-source@phorax.com', '7elix', '43ee10080f20bd6c9f6bd4ced77adf7d', 'Compatibility release for TYPO3 CMS 7 LTS / 7.6.0. Now includes Infobox, cli command, new docheader and icon overview and tree. Create better extensions with the help of Styleguide 3', 'PHORAX', 7006000, 1, 0),
(33210, 0, 'sffirstimages', 1, '1.0.1', 0, 0, 'SF first images', 'With this extension you can create a preview of the first images of the subpages of the selected page.', 2, 0, 3, 1335212726, 'a:1:{s:7:"depends";a:2:{s:7:"extbase";s:5:"1.3.0";s:5:"fluid";s:5:"1.3.0";}}', 'Stefan Froemken, Micha Vorlaender', 'firma@sfroemken.de, micha@vorlaender.net', 'froemken', '30bf1faa4a621af3ac61e77edf90eb8f', 'With this extension you can build a little sitemap which contains the first images of the subpages. Templates are FLUID-based', 'Stefan Froemken, Vorlaender.net', 1000001, 0, 0),
(33211, 0, 'sffirstimages', 1, '1.0.2', 0, 0, 'SF first images', 'With this extension you can create a preview of the first images of the subpages of the selected page.', 2, 0, 3, 1335990308, 'a:1:{s:7:"depends";a:2:{s:7:"extbase";s:5:"1.3.0";s:5:"fluid";s:5:"1.3.0";}}', 'Stefan Froemken, Micha Vorlaender', 'firma@sfroemken.de, micha@vorlaender.net', 'froemken', 'aa6287de40424c94767408b6d01acdc8', 'Bug: An error appears if a page has no tt_content elements', 'Stefan Froemken, Vorlaender.net', 1000002, 0, 0),
(33212, 0, 'sffirstimages', 1, '1.0.3', 0, 0, 'SF first images', 'With this extension you can create a preview of the first images of the subpages of the selected page.', 2, 0, 3, 1350935321, 'a:1:{s:7:"depends";a:2:{s:7:"extbase";s:5:"1.3.0";s:5:"fluid";s:5:"1.3.0";}}', 'Stefan Froemken, Micha Vorlaender', 'firma@sfroemken.de, micha@vorlaender.net', 'froemken', '0d2d33df860b91c81710b54acd8f3629', 'Now this extension searches all contentelements of a subpage to find an image.', 'Stefan Froemken, Vorlaender.net', 1000003, 1, 0),
