(33274, 0, 'restdoc', 1, '0.1.0', 0, 0, 'reST Documentation Viewer', 'Integrates a reST documentation (generated as JSON) into a TYPO3 website.', 0, 0, 3, 1336242838, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"4.5.0-4.7.99";}}', 'Xavier Perseguers', 'xavier@causal.ch', 'xperseguers', 'a5749d5cd7510df1fa640ee265c0fe8d', 'Initial release. Please read documentation.', 'Causal Srl', 1000, 0, 0),
(33275, 0, 'restdoc', 1, '1.0.0', 0, 0, 'reST Documentation Viewer', 'Integrates a reStructuredText documentation (generated as JSON) into a TYPO3 website.', 2, 0, 3, 1361021223, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"4.5.0-6.0.99";}}', 'Xavier Perseguers', 'xavier@causal.ch', 'xperseguers', '98d0b0ffb76e533ffbec28fa2edf17ae', 'Bug fixes, better integration using TypoScript. Extension is now considered stable.', 'Causal Srl', 1000000, 0, 0),
(33276, 0, 'restdoc', 1, '1.1.0', 0, 0, 'reST Documentation Viewer', 'Integrates a reStructuredText documentation (generated as JSON) into a TYPO3 website.', 2, 0, 3, 1362670301, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"4.5.0-6.0.99";}}', 'Xavier Perseguers', 'xavier@causal.ch', 'xperseguers', 'f6610ec85d9efd6dbd9f1dfb272f3ed4', 'Support for general index, breadcrumb menu, menu of recent changes and integration of chapters into Google Sitemap (EXT:dd_googlesitemap).\n\nBEWARE: Minor breaking changes, please consult corresponding bug tracker entries if ever you need help: https://for', 'Causal Srl', 1001000, 0, 0),
(33277, 0, 'restdoc', 1, '1.2.0', 0, 0, 'reST Documentation Viewer', 'Integrates a reStructuredText documentation (generated as JSON with Sphinx) into a TYPO3 website.', 2, 0, 3, 1365079087, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"4.5.0-6.1.99";}}', 'Xavier Perseguers', 'xavier@causal.ch', 'xperseguers', '5f3698bad99403a28a9103b8c31f8aa1', 'Now compatible with FAL in TYPO3 6.x.\nSupport for metadata and Sphinx advertisement (Wappalizer).\nBuilt-in Sphinx search within the documentation.\n\nPlease check your deprecation log after upgrading.', 'Causal Srl', 1002000, 0, 0),
(33278, 0, 'restdoc', 1, '1.2.1', 0, 0, 'reST Documentation Viewer', 'Integrates a reStructuredText documentation (generated as JSON with Sphinx) into a TYPO3 website.', 2, 0, 3, 1365675222, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"4.5.0-6.1.99";}}', 'Xavier Perseguers', 'xavier@causal.ch', 'xperseguers', 'ff1b7f9630212e03a63ef185127ea152', 'Regular bugfix release. Invalid index definition in database table. Search module now compatible with upcoming Sphinx v1.2.\nRelease notes: https://forge.typo3.org/projects/extension-restdoc/wiki/RESTDOC_121', 'Causal Srl', 1002001, 0, 0),
(33279, 0, 'restdoc', 1, '1.3.0', 0, 0, 'reST Documentation Viewer', 'Integrates a reStructuredText documentation (generated as JSON with Sphinx) into a TYPO3 website.', 2, 0, 3, 1370348365, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"5.3.3-0.0.0";s:5:"typo3";s:12:"4.5.0-6.1.99";}}', 'Xavier Perseguers', 'xavier@causal.ch', 'xperseguers', 'bd3d0a4947a9eeff9bc386d26fa03243', 'Compatibility with official TYPO3 manuals and integration with EXT:sphinx 0.5.0', 'Causal Srl', 1003000, 0, 0),
(33280, 0, 'restdoc', 1, '1.3.1', 0, 0, 'Sphinx/reStructuredText Documentation Viewer', 'Seamlessly embeds Sphinx/reStructuredText-based documentation into your TYPO3 website. Instead of publishing your various manual, in-house documents, guides, references, ... solely as PDF, render them as JSON and use this extension to show them as part of your website to enhance the overall user experience and Search Engine Optimization (SEO). Lets you merge the chapter structure with the breadcrumb menu and much more. Documentation styles automatically inherit from your corporate design.', 2, 0, 3, 1381871812, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:12:"5.3.3-5.5.99";s:5:"typo3";s:12:"4.5.0-6.2.99";}}', 'Xavier Perseguers (Causal)', 'xavier@causal.ch', 'xperseguers', 'c5a05922a84d766e78ffa61abcedb3ac', 'Compatibility with TYPO3 6.2 LTS.\nBEWARE: default file is now expected to be "Index.rst" (UpperCase) and not "index.rst" anymore. Adapt TypoScript constant if needed.\nDetails on http://forge.typo3.org/projects/extension-restdoc/wiki/RESTDOC_131', 'Causal Srl', 1003001, 0, 0),
(33281, 0, 'restdoc', 1, '1.3.2', 0, 0, 'Sphinx/reStructuredText Documentation Viewer', 'Seamlessly embeds Sphinx/reStructuredText-based documentation into your TYPO3 website. Instead of publishing your various manual, in-house documents, guides, references, ... solely as PDF, render them as JSON and use this extension to show them as part of your website to enhance the overall user experience and Search Engine Optimization (SEO). Lets you merge the chapter structure with the breadcrumb menu and much more. Documentation styles automatically inherit from your corporate design.', 2, 0, 3, 1398197426, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:12:"5.3.3-5.5.99";s:5:"typo3";s:12:"4.5.0-6.2.99";}}', 'Xavier Perseguers (Causal)', 'xavier@causal.ch', 'xperseguers', '342dafc01f039a3c3d7eb8a0de8922bb', 'Regular maintenance release. Compatibility with Flow manuals.\nDetails on http://forge.typo3.org/projects/extension-restdoc/wiki/RESTDOC_132', 'Causal Srl', 1003002, 0, 0),
(33282, 0, 'restdoc', 1, '1.4.0', 0, 0, 'Sphinx/reStructuredText Documentation Viewer', 'Seamlessly embeds Sphinx/reStructuredText-based documentation into your TYPO3 website. Instead of publishing your various manual, in-house documents, guides, references, ... solely as PDF, render them as JSON and use this extension to show them as part of your website to enhance the overall user experience and Search Engine Optimization (SEO). Lets you merge the chapter structure with the breadcrumb menu and much more. Documentation styles automatically inherit from your corporate design.', 2, 0, 3, 1417690493, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:12:"5.3.3-5.6.99";s:5:"typo3";s:13:"6.2.0-7.99.99";}}', 'Xavier Perseguers (Causal)', 'xavier@causal.ch', 'xperseguers', '28c8aae92be17faa79535c927956052e', 'Compatibility with TYPO3 6.2-7.x.\nIf you need support for TYPO3 4.5-6.1, please use version 1.3 instead.\nDetails on http://forge.typo3.org/projects/extension-restdoc/wiki/RESTDOC_140', 'Causal Srl', 1004000, 0, 0),
(33283, 0, 'restdoc', 1, '1.5.0', 0, 0, 'Sphinx Documentation Viewer Plugin', 'Seamlessly embeds Sphinx/reStructuredText-based documentation into your TYPO3 website. Instead of publishing your various manual, in-house documents, guides, references, ... solely as PDF, render them as JSON and use this extension to show them as part of your website to enhance the overall user experience and Search Engine Optimization (SEO). Lets you merge the chapter structure with the breadcrumb menu and much more. Documentation styles automatically inherit from your corporate design.', 2, 0, 3, 1435157790, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:12:"5.3.3-5.6.99";s:5:"typo3";s:13:"6.2.0-7.99.99";}}', 'Xavier Perseguers (Causal)', 'xavier@causal.ch', 'xperseguers', '96e946efe2669cbb9a710f5f20c095f2', 'Extended support for RealURL (simply said: beautiful URLs).\nDetails on http://forge.typo3.org/projects/extension-restdoc/wiki/RESTDOC_150', 'Causal Srl', 1005000, 0, 0),
(33284, 0, 'restdoc', 1, '1.5.1', 0, 0, 'Sphinx Documentation Viewer Plugin', 'Seamlessly embeds Sphinx/reStructuredText-based documentation into your TYPO3 website. Instead of publishing your various manual, in-house documents, guides, references, ... solely as PDF, render them as JSON and use this extension to show them as part of your website to enhance the overall user experience and Search Engine Optimization (SEO). Lets you merge the chapter structure with the breadcrumb menu and much more. Documentation styles automatically inherit from your corporate design.', 2, 0, 3, 1447161555, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:12:"5.3.3-5.6.99";s:5:"typo3";s:13:"6.2.0-7.99.99";}}', 'Xavier Perseguers (Causal)', 'xavier@causal.ch', 'xperseguers', 'f322ef70f21ec1506a26bedb27d117a4', 'Last bits of fine-tuning to be ready for TYPO3 7 LTS.\nDetails on https://forge.typo3.org/projects/extension-restdoc/wiki/RESTDOC_151', 'Causal Srl', 1005001, 0, 0),
(33285, 0, 'restdoc', 1, '1.6.0', 0, 0, 'Sphinx Documentation Viewer Plugin', 'Seamlessly embeds Sphinx/reStructuredText-based documentation into your TYPO3 website. Instead of publishing your various manual, in-house documents, guides, references, ... solely as PDF, render them as JSON and use this extension to show them as part of your website to enhance the overall user experience and Search Engine Optimization (SEO). Lets you merge the chapter structure with the breadcrumb menu and much more. Documentation styles automatically inherit from your corporate design.', 2, 0, 3, 1459320609, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:12:"5.3.3-7.0.99";s:5:"typo3";s:13:"6.2.0-8.99.99";}}', 'Xavier Perseguers (Causal)', 'xavier@causal.ch', 'xperseguers', '999cdaa8e69b9e0c14e4e9faff36ed47', 'Additional methods for supporting new docs.typo3.org theme (EXT:sphinx 2.4).\nCompatibility with TYPO3 v8 and PHP 7.\nDetails on https://forge.typo3.org/projects/extension-restdoc/wiki/RESTDOC_160', 'Causal Srl', 1006000, 1, 0),
(33286, 0, 'xf_imgopt', 1, '0.0.2', 0, 0, 'Image Optimizer', 'Optimize PNG,JPG and JPEG for less traffic and disk use. Some images nearly perfect and next can drop 96% of the size. READ THE MANUEL FIRST (in doc/manuel.(odtpdf)).', 3, 0, 4, 1336269046, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"5.3.0-0.0.0";s:5:"typo3";s:11:"4.7.0-0.0.0";}}', 'Xaver Maierhofer', 'xaver.maierhofer@xwissen.info', 'x--f', '24494cbcf3cb9df3c793392e9faee52f', 'initial upload. Read the documentation. some typos and misspelled sentence will be found in documentation. only pdf and odt as documentation, reason can be found in documentation.\nPlease send feedback!', 'Sam-City', 2, 0, 0),
(33287, 0, 'xf_imgopt', 1, '0.1.0', 0, 0, 'Image Optimizer', 'Optimize PNG, JPG or JPEG for less traffic and disk usage. The image size can be reduced between 0-98%. Please read the manual frist (avaiable as odt or pdf in doc folder).', 3, 0, 4, 1336342740, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"5.3.0-0.0.0";s:5:"typo3";s:11:"4.7.0-0.0.0";}}', 'Xaver Maierhofer', 'xaver.maierhofer@xwissen.info', 'x--f', '95a808ceb1c109dec1ba91705114ea26', 'Added logfile and some other options like turn on off every tool. Infos for different Linux OS. Fixed some typos.', 'Sam-City', 1000, 0, 0),
(33288, 0, 'xf_imgopt', 1, '0.1.1', 0, 0, 'Image Optimizer', 'Optimize PNG, JPG or JPEG for less traffic and disk usage. The image size can be reduced between 0-98%. Please read the manual frist (avaiable as odt or pdf in doc folder).', 3, 0, 4, 1336396255, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"5.3.0-0.0.0";s:5:"typo3";s:11:"4.7.0-0.0.0";}}', 'Xaver Maierhofer', 'xaver.maierhofer@xwissen.info', 'x--f', 'bfb3d17bf9645a7a140c4eb8c272fd88', 'Added manual as sxw for Read Online (THX2sorenmalling for the help) and dropped pdf/odt.', 'Sam-City', 1001, 0, 0),
