(33309, 0, 'ttaddress_l18n', 1, '0.1.1', 0, 0, 'Address List Multilang / Sorting Field', 'This extension adds the fields sorting / sys_language_uid / l18n_parent / l18n_diffsource added to the database.\n		By XCLASS the functions getSingleRecords, getRecordsFromGroups and checkSorting overridden.\n		This can be translated and show tt_adresse entries.\n		\n		Diese Extension fgt die Felder sorting / sys_language_uid / l18n_parent / l18n_diffsource in der Datenbank hinzu.\n		Per XCLASS werden die Funktionen getSingleRecords, getRecordsFromGroups und checkSorting bersteuert.\n		Damit knnen tt_adresse Eintrge bersetzt und ausgegeben werden.', 2, 0, 4, 1336908022, 'a:1:{s:7:"depends";a:3:{s:10:"tt_address";s:0:"";s:3:"php";s:11:"5.2.0-0.0.0";s:5:"typo3";s:11:"4.3.0-0.0.0";}}', 'thefox.ch', 'typo3ext@thefox.ch', 'thefox', '9c80770710a60834e50263dd7cfb39c6', '', '', 1001, 0, 0),
(33310, 0, 'ttaddress_l18n', 1, '0.1.2', 0, 0, 'Address List Multilang / Sorti', 'tt_address multilingual. This extension adds the fields sorting / sys_language_uid / l18n_parent / l18n_diffsource added to the database.\n		By XCLASS the functions getSingleRecords, getRecordsFromGroups and checkSorting overridden.\n		This can be translated and show tt_adresse entries.\n		 :GERMAN: \n		tt_address mehrsprachig. Diese Extension fuegt die Felder sorting / sys_language_uid / l18n_parent / l18n_diffsource in der Datenbank hinzu.\n		Per XCLASS werden die Funktionen getSingleRecords, getRecordsFromGroups und checkSorting uebersteuert.\n		Damit koennen tt_address Eintraege uebersetzt und ausgegeben werden.', 2, 0, 4, 1340468305, 'a:1:{s:7:"depends";a:3:{s:10:"tt_address";s:0:"";s:3:"php";s:11:"5.2.0-0.0.0";s:5:"typo3";s:11:"4.3.0-0.0.0";}}', 'thefox.ch', 'typo3ext@thefox.ch', 'thefox', '1f4f749fcf8e9e030803e2089a6abf09', 'code cleanup', '', 1002, 0, 0),
(33311, 0, 'ttaddress_l18n', 1, '0.1.3', 0, 0, 'Address List Multilang / Sorting Field', 'tt_address multilingual. This extension adds the fields sorting / sys_language_uid / l18n_parent / l18n_diffsource added to the database.\n		By XCLASS the functions getSingleRecords, getRecordsFromGroups and checkSorting overridden.\n		This can be translated and show tt_adresse entries.\n		 :GERMAN: \n		tt_address mehrsprachig. Diese Extension fuegt die Felder sorting / sys_language_uid / l18n_parent / l18n_diffsource in der Datenbank hinzu.\n		Per XCLASS werden die Funktionen getSingleRecords, getRecordsFromGroups und checkSorting uebersteuert.\n		Damit koennen tt_address Eintraege uebersetzt und ausgegeben werden.', 2, 0, 4, 1341604716, 'a:1:{s:7:"depends";a:3:{s:10:"tt_address";s:0:"";s:3:"php";s:11:"5.2.0-0.0.0";s:5:"typo3";s:11:"4.3.0-0.0.0";}}', 'thefox.ch', 'typo3ext@thefox.ch', 'thefox', 'af8ece76dae49f8c9e6e4e9db57128f7', 'New Manual Template for better online read', '', 1003, 1, 0),
