(33381, 0, 'browser_manual_en', 1, '4.5.3', 0, 0, 'Browser Manual (en)', 'Browser - TYPO3 without PHP - the manual. Develop your TYPO3 extensions eight times faster!', 2, 0, 8, 1365102411, 'a:0:{}', 'Dirk Wildt - Die Netzmacher', 'http://wildt.at.die-netzmacher.de', 'dwildt', '29419679e5ae1a3d431686b130058a6a', 'NEW FEATURES: TYPO3 6.x compatibility, GoogleMaps, Calendar handles periods over days, controlling JSS alerts', '', 4005003, 0, 0),
