(33383, 0, 'browser_manual_en', 1, '4.6.2', 0, 0, 'Browser Manual (en)', 'Publish your data in list and single views and in maps! You dont need neither any own plugin nor any line PHP code. The Browser - TYPO3 without PHP - provides an index browser (a-z), a page browser, a record browser, a search form, filters, category menus, AJAX, GoogleMaps and OpenStreetMap by default. Your data will be detected as objects, i.e. images will be wrapped automatically. SEO - Search Engine Optimization - is supported. The Browser enables the development of TYPO3-Extensions without any line PHP. TYPO3 developers and TYPO3 integrators  will be eight times faster! The browser is very suitable for database development.', 2, 0, 8, 1379622017, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"4.5.0-6.1.99";}}', 'Dirk Wildt - Die Netzmacher', 'http://wildt.at.die-netzmacher.de', 'dwildt', 'efe6bb06a59ec2e13ddaffa162d54129', 'NEW FEATURES: Automatic Geocoding, BrowserMaps Mobile, oxMap without jQuery, Placement controlling of JSS scripts, Route, SEO Dynamic Tag 2', '', 4006002, 0, 0),
(33384, 0, 'browser_manual_en', 1, '4.8.5', 0, 0, 'Browser Manual (en)', 'Publish your data in list and single views and in maps! You dont need neither any own plugin nor any line PHP code. The Browser - TYPO3 without PHP - provides an index browser (a-z), a page browser, a record browser, a search form, filters, category menus, AJAX, GoogleMaps and OpenStreetMap by default. Your data will be detected as objects, i.e. images will be wrapped automatically. SEO - Search Engine Optimization - is supported. The Browser enables the development of TYPO3-Extensions without any line PHP. TYPO3 developers and TYPO3 integrators  will be eight times faster! The browser is very suitable for database development.', 2, 0, 8, 1388279839, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"4.5.0-6.1.99";}}', 'Dirk Wildt - Die Netzmacher', 'http://wildt.at.die-netzmacher.de', 'dwildt', 'b7533ac12478cb39eea8b10718e45227', 'NEW FEATURES: BrowserMaps / Routes: evaluation of relations. jQuery: live() - on(). Radial Search (Umkreissuche). User function: render_table. tt_address tutorial (german). TYPO3 6.1.', '', 4008005, 0, 0),
(33385, 0, 'browser_manual_en', 1, '4.9.0', 0, 0, 'Browser Manual (en)', 'Publish your data in list and single views and in maps! You dont need neither any own plugin nor any line PHP code. The Browser - TYPO3 without PHP - provides an index browser (a-z), a page browser, a record browser, a search form, filters, category menus, AJAX, GoogleMaps and OpenStreetMap by default. Your data will be detected as objects, i.e. images will be wrapped automatically. SEO - Search Engine Optimization - is supported. The Browser enables the development of TYPO3-Extensions without any line PHP. TYPO3 developers and TYPO3 integrators  will be eight times faster! The browser is very suitable for database development.', 2, 0, 8, 1398908985, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"4.5.0-6.1.99";}}', 'Dirk Wildt - Die Netzmacher', 'http://wildt.at.die-netzmacher.de', 'dwildt', 'd635b875d4ab62df730097c37e013304', 'New Features: TYPO3 6.1, improved frontend filter', '', 4009000, 0, 0),
(33386, 0, 'browser_manual_en', 1, '4.10.0', 0, 0, 'Browser Manual (en)', 'Publish your data in list and single views and in maps! You dont need neither any own plugin nor any line PHP code. The Browser - TYPO3 without PHP - provides an index browser (a-z), a page browser, a record browser, a search form, filters, category menus, AJAX, GoogleMaps and OpenStreetMap by default. Your data will be detected as objects, i.e. images will be wrapped automatically. SEO - Search Engine Optimization - is supported. The Browser enables the development of TYPO3-Extensions without any line PHP. TYPO3 developers and TYPO3 integrators	will be eight times faster! The browser is very suitable for database development.', 2, 0, 8, 1414876759, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"4.5.0-6.2.99";}}', 'Dirk Wildt - Die Netzmacher', 'http://wildt.at.die-netzmacher.de', 'dwildt', '7786646c6451ecaae338c7f973fba35b', 'Manual for the Browser - TYPO3 without PHP - for TYPO3 6.2', '', 4010000, 0, 0);
