(33391, 0, 'browser_manual_en', 1, '7.2.2', 0, 0, 'Browser Manual (en)', 'Publish the data of your extension with the Browser  TYPO3 without PHP! You dont need neither any own PHP code nor any own plugin. You can save up to 85 percent of your operating expense. The Browser  TYPO3 without PHP  provides responsive templates, an index browser (a-z), a page browser, a record browser, a search form, filters, category menus, AJAX, GoogleMaps and OpenStreetMap by default. SEO  Search Engine Optimization  is optional.Manual: http://typo3-browser.deEXT:browser_tut_manual_en/doc/manual.pdf', 2, 0, 8, 1433885784, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"4.5.0-6.2.99";}}', 'Dirk Wildt - Die Netzmacher', 'http://wildt.at.die-netzmacher.de', 'dwildt', 'aeb84e316e41c55070bc540019933793', 'NEW FEATURE: vCard 2.1 and 4.0 selectable by the Constant Editor', '', 7002002, 0, 0),
(33392, 0, 'browser_manual_en', 1, '7.2.6', 0, 0, 'Browser Manual (en)', 'Publish the data of your extension with the Browser  TYPO3 without PHP! You dont need neither any own PHP code nor any own plugin. You can save up to 85 percent of your operating expense. The Browser  TYPO3 without PHP  provides responsive templates, an index browser (a-z), a page browser, a record browser, a search form, filters, category menus, AJAX, GoogleMaps and OpenStreetMap by default. SEO  Search Engine Optimization  is optional.Manual: http://typo3-browser.deEXT:browser_tut_manual_en/doc/manual.pdf', 2, 0, 8, 1440345772, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"4.5.0-6.2.99";}}', 'Dirk Wildt - Die Netzmacher', 'http://wildt.at.die-netzmacher.de', 'dwildt', '24293f29a926537b4c702876e1b7ed15', 'Improvement: Backend filter are extended for CURRENT_PID, MM_match_fields, TYPO3 6.2', '', 7002006, 0, 0),
(33393, 0, 'browser_manual_en', 1, '7.3.0', 0, 0, 'Browser Manual (en)', 'Publish your data in list and single views and in maps! You dont need neither any own plugin nor any line PHP code. The Browser - TYPO3 without PHP - provides an index browser (a-z), a page browser, a record browser, a search form, filters, category menus, AJAX, GoogleMaps and OpenStreetMap by default. Your data will be detected as objects, i.e. images will be wrapped automatically. SEO - Search Engine Optimization - is supported. The Browser enables the development of TYPO3-Extensions without any line PHP. TYPO3 developers and TYPO3 integrators	will be eight times faster! The browser is very suitable for database development.', 2, 0, 8, 1451322826, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"4.5.0-6.2.99";}}', 'Dirk Wildt - Die Netzmacher', 'http://wildt.at.die-netzmacher.de', 'dwildt', '7d98d61c5660e9a96293553e9dd966b0', 'Bootstrap support. See manual: Whats new in 7.3', '', 7003000, 0, 0),
(33394, 0, 'browser_manual_en', 1, '7.3.1', 0, 0, 'Browser Manual (en)', 'Publish your data in list and single views and in maps! You dont need neither any own plugin nor any line PHP code. The Browser - TYPO3 without PHP - provides an index browser (a-z), a page browser, a record browser, a search form, filters, category menus, AJAX, GoogleMaps and OpenStreetMap by default. Your data will be detected as objects, i.e. images will be wrapped automatically. SEO - Search Engine Optimization - is supported. The Browser enables the development of TYPO3-Extensions without any line PHP. TYPO3 developers and TYPO3 integrators	will be eight times faster! The browser is very suitable for database development.', 2, 0, 8, 1468599855, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"4.5.0-7.6.99";}}', 'Dirk Wildt - Die Netzmacher', 'http://wildt.at.die-netzmacher.de', 'dwildt', '1e97bf14dff9f1af683c4d1d8a1bd8ba', 'IMPROVEMENT: Manual is compatible with TYPO3 7.x', '', 7003001, 1, 0),
(33395, 0, 'external_link_parameter', 1, '1.0.0', 0, 0, 'Add possible parameters to external link', 'Add possible GET parameters to external link given a "white" list of domains. The extension uses a typolink hook under the hood: "typoLink_PostProc".', 2, 0, 3, 1337771696, 'a:1:{s:7:"depends";a:1:{s:3:"cms";s:0:"";}}', 'Fabien Udriot', 'fabien.udriot@gebruederheitz.de', 'fab1en', '6df483651acfb6bcc37ce33dec365a73', 'Initial upload. Check Readme file for documentation', '', 1000000, 0, 0),
