(33460, 0, 'monoloop', 1, '0.1.0', 0, 0, 'monoloop', 'Add FREE behavioral targeting and personalization to your TYPO3 site and transform your static site into a dynamic user experience. \nAutomate behavioral profiling of site visitors. Enable easy triggering of different content variations for different visitors. \nInsert, replace or add variations of existing content on any page and define trigger conditions using more than 60 predefined parameters covering location, recency, frequency, monetary. Track categories, products, downloads, search terms, purchases, shopping baskets or any custom property you want to capture. \nInclude backend profile data from your frontend users to the behavioral profile or include behavioral data and scores in your FE-user profile.', 1, 0, 2, 1338981224, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"5.2.0-0.0.0";s:5:"typo3";s:11:"4.3.0-0.0.0";}}', 'nut', 'nut@monoloop.com', 'monoloop', '4012f553df3b0fd5bc7ade11747abf9b', '', '', 1000, 0, 0),
(33461, 0, 'monoloop', 1, '0.0.1', 0, 0, 'monoloop', '\r\nAdd FREE behavioral targeting and personalization to your TYPO3 site and transform your static site into a dynamic user experience. \r\nAutomate behavioral profiling of site visitors. Enable easy triggering of different content variations for different visitors. \r\nInsert, replace or add variations of existing content on any page and define trigger conditions using more than 60 predefined parameters covering location, recency, frequency, monetary. Track categories, products, downloads, search terms, purchases, shopping baskets or any custom property you want to capture. \r\nInclude backend profile data from your frontend users to the behavioral profile or include behavioral data and scores in your FE-user profile.', 1, 0, 2, 1338981193, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"5.2.0-0.0.0";s:5:"typo3";s:11:"4.3.0-0.0.0";}}', 'nut', 'nut@monoloop.com', 'monoloop', '5583b77e14117c5d04a299f5e18f77e7', '', '', 1, 0, 0),
(33462, 0, 'monoloop', 1, '1.0.1', 0, 0, 'Monoloop', 'Add FREE behavioral targeting and personalization to your TYPO3 site and transform your static site into a dynamic user experience. Automate behavioral profiling of site visitors. Enable easy triggering of different content variations for different visitors. Insert, replace or add variations of existing content on any page and define trigger conditions using more than 60 predefined parameters covering location, recency, frequency, monetary. Track categories, products, downloads, search terms, purchases, shopping baskets or any custom property you want to capture. Include backend profile data from your frontend users to the behavioral profile or include behavioral data and scores in your FE-user profile.', 1, 0, 2, 1339055353, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"5.2.0-0.0.0";s:5:"typo3";s:11:"4.3.0-0.0.0";}}', 'Sune Brodersen', 'sune@monoloop.com', 'monoloop', '6a7d55809ca52fb87d44959b42b34d03', '', 'Monoloop', 1000001, 1, 0),
