(33474, 0, 'sf_yubikey', 1, '0.6.0', 0, 0, 'YubiKey two-factor OTP authentication', 'An authentication service for TYPO3 which extends the backend/frontend login by YubiKey OTP two-factor authentication.', 1, 0, 5, 1397031713, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"4.5.0-6.2.99";}}', 'Torben Hansen', 'derhansen@gmail.com', 'derhansen', '42962b0f5d4a720b356fb1c797cf4429', 'This version uses an included version of Yubico.php, if the library is not available in the servers include path. Added compatibility for TYPO3 6.2', 'Skyfillers GmbH', 6000, 0, 0),
(33475, 0, 'sf_yubikey', 1, '0.7.0', 0, 0, 'YubiKey two-factor OTP authentication', 'An authentication service for TYPO3 which extends the backend/frontend login by YubiKey OTP two-factor authentication.', 2, 0, 5, 1420890092, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"4.5.0-6.2.99";}}', 'Torben Hansen', 'derhansen@gmail.com', 'derhansen', 'c304b9d1f6d4cb7b2e7dd2bf43fc639a', 'Make PEAR usage optional, allow multiple YubiKeys for backend users, updated documentation. This is the last version compatible with TYPO3 4.5', 'Skyfillers GmbH', 7000, 0, 0),
