(33484, 0, 'meinpraktikum_widget', 1, '1.0.0', 0, 0, 'meinpraktikum.de Widget', 'The meinpraktikum.de widget enables universities to integrate the jobs and reviews of meinpraktikum.de into their own webpages to simplify the students discovery for the most suitable internship.', 1, 0, 3, 1339406112, 'a:1:{s:7:"depends";a:2:{s:7:"extbase";s:3:"1.3";s:5:"fluid";s:3:"1.3";}}', 'Marc Bastian Heinrichs', 'mbh@mbh-software.de', 'meinpraktikum', 'ac98a5f43470063d362b62a7b3b68aa2', 'Initial release', '', 1000000, 0, 0),
(33485, 0, 'meinpraktikum_widget', 1, '1.0.1', 0, 0, 'meinpraktikum.de Widget', 'The meinpraktikum.de widget enables universities to integrate the jobs and reviews of meinpraktikum.de into their own webpages to simplify the students discovery for the most suitable internship.', 1, 0, 3, 1339406540, 'a:1:{s:7:"depends";a:2:{s:7:"extbase";s:3:"1.3";s:5:"fluid";s:3:"1.3";}}', 'meinpraktikum.de', 'info@employour.de', 'meinpraktikum', '13d33d8d276dc392521f30bb672cb376', '', '', 1000001, 1, 0);
INSERT INTO `tx_extensionmanager_domain_model_extension` (`uid`, `pid`, `extension_key`, `repository`, `version`, `alldownloadcounter`, `downloadcounter`, `title`, `description`, `state`, `review_state`, `category`, `last_updated`, `serialized_dependencies`, `author_name`, `author_email`, `ownerusername`, `md5hash`, `update_comment`, `authorcompany`, `integer_version`, `current_version`, `lastreviewedversion`) VALUES
(33486, 0, 'nsvpingbacks', 1, '1.0.0', 0, 0, 'Pingbacks', 'Makes TYPO3 capable of receiving pingbacks', 1, 0, 3, 1339530736, 'a:1:{s:7:"depends";a:1:{s:10:"xmlrpc_lib";s:0:"";}}', 'Nikolas Schmidt-Voigt', 'n.schmidtvoigt@googlemail.com', 'nikolassv', '945792416494a5efcd9472ec39bae924', 'Just released the first version of nsvpingbacks', '', 1000000, 0, 0),
(33487, 0, 'nsvpingbacks', 1, '1.0.1', 0, 0, 'Pingbacks', 'Makes TYPO3 capable of receiving pingbacks', 1, 0, 3, 1343158443, 'a:1:{s:7:"depends";a:1:{s:10:"xmlrpc_lib";s:0:"";}}', 'Nikolas Schmidt-Voigt', 'n.schmidtvoigt@googlemail.com', 'nikolassv', '56600bb72db45670baa226a287717018', '- solved problems with special chars in post titles\r\n- optimized the extraction of the excerpt', '', 1000001, 0, 0),
(33488, 0, 'nsvpingbacks', 1, '1.1.0', 0, 0, 'Pingbacks', 'Makes TYPO3 capable of receiving pingbacks', 2, 0, 3, 1353270100, 'a:1:{s:7:"depends";a:1:{s:10:"xmlrpc_lib";s:0:"";}}', 'Nikolas Schmidt-Voigt', 'n.schmidtvoigt@googlemail.com', 'nikolassv', '47c9280014b2aa08f196a29f9f041bca', 'Changed the BE-Module:\r\n - Latest pingbacks are displayed at the top of the table by default\r\n - removed unecessary scroll bars\r\n\r\nMarked as stable because no major bugs appeared since I published the first version.', '', 1001000, 1, 0),
(33489, 0, 'qm_powermail_paypal', 1, '0.1.0', 0, 0, 'Integrate a Paypal payment with a powermail form', 'Install and check the new options in Powermail forms under Fields. The rest should be automatic.', 0, 0, 2, 1339540570, 'a:1:{s:7:"depends";a:2:{s:3:"cms";s:0:"";s:9:"powermail";s:0:"";}}', 'Qc mdia', 'qcmedia@qcmedia.ca', 'qcmedia', '0e409d3f7e4d00c6eacbcc0109ed8dae', 'Very initial release.', '', 1000, 0, 0),
(33490, 0, 'qm_powermail_paypal', 1, '0.2.0', 0, 0, 'Integrate a Paypal payment with a powermail form', 'Install and check the new options in Powermail forms under Fields. The rest should be automatic.', 0, 0, 2, 1342561539, 'a:1:{s:7:"depends";a:2:{s:3:"cms";s:0:"";s:9:"powermail";s:0:"";}}', 'Qc mdia', 'qcmedia@qcmedia.ca', 'qcmedia', 'a52bc9896e3a98fe89798b1d147fe641', 'More options. Better message.', '', 2000, 0, 0),
(33491, 0, 'qm_powermail_paypal', 1, '0.3.0', 0, 0, 'Integrate a Paypal payment with a powermail form (', 'Install and check the new options in Powermail forms under Fields. The rest should be automatic.', 1, 0, 2, 1349449382, 'a:1:{s:7:"depends";a:2:{s:3:"cms";s:0:"";s:9:"powermail";s:0:"";}}', 'Qc mdia', 'qcmedia@qcmedia.ca', 'qcmedia', 'c7deae1168712b56b85808223f4bb965', 'New field to specify your own formula (its pretty cool).', '', 3000, 1, 0),
(33492, 0, 'fastce', 1, '0.0.9', 0, 0, 'Fast CE', 'Build fast CE from flexfrom data. With Fluid / Smarty / langfiles / css / js with T3 API. All conf in files - great for git. Docs comming soon.', 1, 0, 2, 1339580113, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"5.2.0-0.0.0";s:5:"typo3";s:12:"4.3.0-4.5.99";}}', 'Krystian Szymukowicz', 'ks@cms-partner.pl', 't33k', '2728b0f6681ae5bdf1e7a99ff1d00225', 'Init. docs comming soon.', 'cms-partner.pl', 9, 1, 0),
(33493, 0, 'cablan_list_cat_settings', 1, '0.0.1', 0, 0, 'Tt_news category list settings', 'This extension allows custom tt_news settings on a per selected category basis, such as:\n\n- different templates\n- different number of sub-templates (with option split)\n- different max number of items', 0, 0, 2, 1339687621, 'a:1:{s:7:"depends";a:1:{s:7:"tt_news";s:0:"";}}', 'Martin-Pierre Frenette', 'typo3@cablan.net', 'cablan', '47819507d8deb97cb095fc69b4bed987', 'First initial, non-cleaned up version.', '', 1, 1, 0),
(33494, 0, 'cablan_virtual_tt_news', 1, '0.0.1', 0, 0, 'tt_news virtual tree system', 'This extension allows to build a virtual news category tree', 0, 0, 3, 1339687707, 'a:1:{s:7:"depends";a:1:{s:7:"tt_news";s:0:"";}}', 'Martin-Pierre Frenette', 'typo3@cablan.net', 'cablan', '741c990e32f1606cca4c89a62d43f3f6', 'First non-cleaned up version', '', 1, 0, 0),
(33495, 0, 'cablan_virtual_tt_news', 1, '0.1.0', 0, 0, 'tt_news virtual tree system', 'This extension allows to build a virtual news category tree', 0, 0, 3, 1340117648, 'a:1:{s:7:"depends";a:1:{s:7:"tt_news";s:0:"";}}', 'Martin-Pierre Frenette', 'typo3@cablan.net', 'cablan', '9f8a1c0420bfc5e996e05ced50a409aa', 'Now, there is a constants.txt file for the constant editor. You can change the HTML for the first 2 level of menus in the constant editor, and the first 5 levels in the setup.\n\nIt is not fully tested, but I wanted to push it as soon as possible to get rid', '', 1000, 0, 0),
(33496, 0, 'cablan_virtual_tt_news', 1, '0.1.1', 0, 0, 'tt_news virtual tree system', 'This extension allows to build a virtual news category tree', 0, 0, 3, 1342027689, 'a:1:{s:7:"depends";a:1:{s:7:"tt_news";s:0:"";}}', 'Martin-Pierre Frenette', 'typo3@cablan.net', 'cablan', 'd10f60489a23324310333b4ee91aefae', 'Small typo in the AddSubCategoriesToCurrentPage function.', '', 1001, 0, 0),
(33497, 0, 'cablan_virtual_tt_news', 1, '0.1.2', 0, 0, 'tt_news virtual tree system', 'This extension allows to build a virtual news category tree', 0, 0, 3, 1342190184, 'a:1:{s:7:"depends";a:1:{s:7:"tt_news";s:0:"";}}', 'Martin-Pierre Frenette', 'typo3@cablan.net', 'cablan', '6eb0b4c1a634552a5b7bf22dbd5f8a97', 'Bugfix: GetSubCategoriesRecursively bug. Please  upgrade.\r\n\r\nNew features: Constants for now 5 levels of menu, and support for 10 levels deep in the PHP.\r\n\r\n', '', 1002, 0, 0),
(33498, 0, 'cablan_virtual_tt_news', 1, '0.2.0', 0, 0, 'tt_news virtual tree system', 'This extension allows to build a virtual news category tree', 0, 0, 3, 1344963134, 'a:1:{s:7:"depends";a:1:{s:7:"tt_news";s:0:"";}}', 'Martin-Pierre Frenette', 'typo3@cablan.net', 'cablan', '30f9228dc00f94098d78d35c7e19a06c', 'First version with [limited] documentation. Breadcrumbs menu supported now. More typoscript options. And NEW: ability to create links to other CAT pages from within tt_news articles.', '', 2000, 0, 0),
(33499, 0, 'cablan_virtual_tt_news', 1, '0.3.0', 0, 0, 'tt_news virtual tree system', 'This extension allows to build a virtual news category tree', 0, 0, 3, 1346935396, 'a:1:{s:7:"depends";a:1:{s:7:"tt_news";s:0:"";}}', 'Martin-Pierre Frenette', 'typo3@cablan.net', 'cablan', '48c934b077235e453a54a943cac8e043', 'Added localization support', '', 3000, 1, 0),
(33500, 0, 'cablan_cat_news_markers', 1, '0.0.1', 0, 0, 'Cablan.net tt_news Category Markers', '', 0, 0, 2, 1339687851, 'a:1:{s:7:"depends";a:1:{s:7:"tt_news";s:0:"";}}', 'Martin-Pierre Frenette', 'typo3@cablan.net', 'cablan', '8b11806931aedd5a4d658aadea8dd0ae', 'First non-cleaned up version', '', 1, 1, 0),
(33501, 0, 'cablan_news_tags', 1, '0.0.1', 0, 0, 'Cablan News Tags', 'Allows to tag news articles', 0, 0, 2, 1339687957, 'a:1:{s:7:"depends";a:1:{s:7:"tt_news";s:0:"";}}', 'Martin-Pierre Frenette', 'typo3@cablan.net', 'cablan', '7204f365d7b10e1c6ebf2d7319d72ed0', 'First non-cleaned up version', '', 1, 1, 0),
(33502, 0, 'sorting_tt_news', 1, '0.0.1', 0, 0, 'TT_news custom sorting', 'This extension offers a new plug-in which allows to define new tt_news sorting order. It is only a wrapper around the tt_news plugin.', 0, 0, 3, 1339688106, 'a:1:{s:7:"depends";a:1:{s:7:"tt_news";s:0:"";}}', 'Martin-Pierre Frenette', 'typo3@cablan.net', 'cablan', '3ce95683973a6f1c89365b7a30a14b51', 'First non-cleaned up version', '', 1, 1, 0),
(33503, 0, 'cablan_news_search_advanced', 1, '0.0.1', 0, 0, 'tt_news aditional search fields', 'This extension add to the tt_news seach form 4 new field: Exact Phrase, With ALL of the words, With Any of the words, Without the words, as well as a category selector', 0, 0, 4, 1339688208, 'a:1:{s:7:"depends";a:1:{s:7:"tt_news";s:0:"";}}', 'Martin-Pierre Frenette', 'typo3@cablan.net', 'cablan', 'ff3c55834a92447600608a3556d96bdf', 'First non-cleaned-up version', '', 1, 1, 0),
(33504, 0, 'cablan_safe_single_news', 1, '0.0.1', 0, 0, 'Safe Single News', 'This extension adds a new tt_news code: SAFE_SINGLE which ensures that a single news article is shown even if none is specified.\n\nIf a news article is selected, it will simply show it. If none is selected, it will display the latest news article for the configured category.\n\nIt is compatible with a specified category (a cat menu) and with virtual tt_news.', 0, 0, 4, 1339688351, 'a:1:{s:7:"depends";a:1:{s:7:"tt_news";s:0:"";}}', 'Martin-Pierre Frenette', 'typo3@cablan.net', 'cablan', '14d81c3414c0bd41c2a5c5a91f167800', 'First non-cleaned version', '', 1, 1, 0),
(33505, 0, 'cablan_tca_helper', 1, '0.0.1', 0, 0, 'TCA Marker Helper', 'Plugin and service which helps to substitute markers for other extensions', 0, 0, 5, 1339688436, 'a:1:{s:7:"depends";a:1:{s:7:"tt_news";s:0:"";}}', 'Martin-Pierre Frenette', 'typo3@cablan.net', 'cablan', '9c8221c397f541304c122487743cbc42', 'First non-cleaned up version.', '', 1, 1, 0),
(33506, 0, 'w_rating', 1, '0.2.0', 0, 0, 'Rating of records', 'Simple records star-like rating, with jquery ajax. Default voted is table  "pages" and uid  current page. You can set it to any table and uid, use it standalone or easy in own markers for extensions like tt_news. Cookie and IP protected. Any number of votings on one page.', 2, 0, 2, 1339806740, 'a:0:{}', 'wolo.pl', 'wolo.wolski@gmail.com', 'wolo', '3be96c501872d9a29696fbb888a549fa', 'initial release', '', 2000, 0, 0),
(33507, 0, 'w_rating', 1, '0.2.1', 0, 0, 'Rating of records', 'Simple records star-like rating, with jquery ajax. Default voted is table  "pages" and uid  current page. You can set it to any table and uid, use it standalone or easy in own markers for extensions like tt_news. Cookie and IP protected. Any number of votings on one page.', 2, 0, 2, 1339810114, 'a:0:{}', 'wolo.pl', 'wolo.wolski@gmail.com', 'wolo', '12cdd8ea371558b4cedbf20b460a979c', 'fix for conflicting html ids in some cases when using from other extensions (same cobj-uid)', '', 2001, 1, 0),
(33508, 0, 'ks_templavoila_dam_filelinks', 1, '1.0.0', 0, 0, 'Templavoila mit DAM Filelinks', 'Bei der Verwendung von Templavoila und Bereichen mit Content Elementen zeigen diese im Backend unter Verwendung von dam_filelinks nur die Inhalte des alten Feldes an, aber nicht die verwendeten DAM Dateien. Diese Erweiterung behebt das Problem.', 2, 0, 0, 1340048145, 'a:1:{s:7:"depends";a:2:{s:13:"dam_filelinks";s:0:"";s:11:"templavoila";s:0:"";}}', 'Ingo Siebeck', 'info@kalandro.de', 'isiebeck', 'cc806c8ff4954affe6ca2d98d3f82e7e', 'Release', '', 1000000, 0, 0),
