(33517, 0, 'cablan_path_segment_fix', 1, '0.0.1', 0, 0, 'Cablan path segment fix for non latin languages', 'This extension automatically set the default language page title as the Real url path segment for non latin languages.\n\nThis prevents Japanese, Chinese, Vietnamese or other similar languages from preventing', 0, 0, 4, 1340102032, 'a:0:{}', 'Martin-Pierre Frenette', 'typo3@cablan.net', 'cablan', '1cc408ebc36a482d937dd3598d54f88b', 'First upload. This is a relatively new extension, build in June 2012 with little testing. ', '', 1, 1, 0),
(33518, 0, 'sticky_parameters', 1, '1.0.0', 0, 0, 'Add possible parameters to every links on the page', 'Add possible GET parameters to internal / external links given a white list of domains. Uses a JavaScript approach for performance reasons (TYPO3 wouldnt cache the page otherwise unless using cHash). JQuery is expected to be loaded.', 2, 0, 3, 1340186124, 'a:1:{s:7:"depends";a:1:{s:3:"cms";s:0:"";}}', 'Fabien Udriot', 'fabien.udriot@gebruederheitz.de', 'fab1en', '8ac37e0ed052f6fedba77e18f3b79893', 'First upload. Documentation is in the Readme', '', 1000000, 1, 0),
