(33526, 0, 'kmcs_fileedit', 1, '1.0.0', 0, 0, 'FileEdit', '', 0, 0, 0, 1340386282, 'a:0:{}', 'Timo Kiefer', 'timo.kiefer@kmcs.de', 'timo.kiefer', '9b2a942134e923a8e0578e0f7d4997df', 'This is a easy to use file editor. You can browse your files and folders in a tree and open a file with a double click in a new tab.\r\nThis is the first upload to TER.', '', 1000000, 0, 0),
(33527, 0, 'kmcs_fileedit', 1, '1.0.2', 0, 0, 'File Editor', 'This is a rich file editor especially for developers. You can browse your web server file directory like on your local system in a tree. Open a file with a double click in a tab. See your source code highlighted in PHP, HTML, CSS or JavaScript. You can also open more than one file, just select the file tab like your file editor in eclipse. Edit your file and save it with Crtl  S key press.', 1, 0, 0, 1343763622, 'a:0:{}', 'Timo Kiefer', 'timo.kiefer@kmcs.de', 'timo.kiefer', '51f920ddb73f4314cbd8e656ec1aca7b', 'new version with manual and new qooxdoo lib 2.0.1', '', 1000002, 0, 0),
(33528, 0, 'kmcs_fileedit', 1, '1.0.3', 0, 0, 'File Editor', 'This is a rich file editor especially for developers. You can browse your web server file directory like on your local system in a tree. Open a file with a double click in a tab. See your source code highlighted in PHP, HTML, CSS or JavaScript. You can also open more than one file, just select the file tab like your file editor in eclipse. Edit your file and save it with Crtl  S key press.', 1, 0, 0, 1343763649, 'a:0:{}', 'Timo Kiefer', 'timo.kiefer@kmcs.de', 'timo.kiefer', 'd31cafb973d2f60e1bf2b4ef678f6b52', 'new version with manual and new qooxdoo lib 2.0.1', '', 1000003, 0, 0),
