(33533, 0, 'kmcs_fileedit', 1, '1.4.0', 0, 0, 'File Editor', 'This is a rich file editor especially for developers. You can browse your web server file directory like on your local system in a tree. Open a file with a double click in a tab. See your source code highlighted in PHP, HTML, CSS or JavaScript. You can also open more than one file, just select the file tab like your file editor in eclipse. Edit your file and save it with Crtl  S key press.', 1, 0, 0, 1452102741, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:13:"6.2.0-7.99.99";}}', 'Timo Kiefer', 'timo.kiefer@kmcs.de', 'timo.kiefer', '15c46d73ca3069134fd2f3adbcdd58e1', '     Version 1.4.0\r\n     Now this extension works with 7.x\r\n     New CodeMirror Version 5.10\r\n     Update qooxdoo Framework to 4.x\r\n', '', 1004000, 0, 0),
(33534, 0, 'kmcs_fileedit', 1, '1.4.1', 0, 0, 'File Editor', 'This is a rich file editor especially for developers. You can browse your web server file directory like on your local system in a tree. Open a file with a double click in a tab and just upload your files with drag and drop. See your source code highlighted in PHP, HTML, CSS or JavaScript. You can also open more than one file, just select the file tab like your file editor in eclipse. Edit your file and save it with Crtl  S key press.', 1, 0, 0, 1452115929, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:13:"6.2.0-7.99.99";}}', 'Timo Kiefer', 'timo.kiefer@kmcs.de', 'timo.kiefer', '3e9e1aea4d148c098abb44b1e777acd2', 'Added Feature: File Upload via Drag and Drop!', '', 1004001, 0, 0),
(33535, 0, 'kmcs_fileedit', 1, '1.4.2', 0, 0, 'File Editor', 'This is a rich file editor especially for developers. You can browse your web server file directory like on your local system in a tree. Open a file with a double click in a tab and just upload your files with drag and drop. See your source code highlighted in PHP, HTML, CSS or JavaScript. You can also open more than one file, just select the file tab like your file editor in eclipse. Edit your file and save it with Crtl  S key press.', 1, 0, 0, 1453892680, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:13:"6.2.0-7.99.99";}}', 'Timo Kiefer', 'timo.kiefer@kmcs.de', 'timo.kiefer', '7b0af2c67d0efc74b1248c4466f9626b', 'Fix: TYPO3 6.2 Module Loading\r\nFix: Default language should not German', '', 1004002, 1, 0),
(33536, 0, 'flickrimages', 1, '0.0.1', 0, 0, 'Flickr Images', 'Display flickr images on your website, either your own images or other peoples by keywords, or using keywords from the page or a single displayed record.', 1, 0, 3, 1340458665, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:3:"4.6";s:7:"extbase";s:5:"1.4.1";s:5:"fluid";s:5:"1.4.1";}}', 'Stephen Bungert', 'stephenbungert@yahoo.de', 'stephenbungert', '2744231ed3b0b66223541b09820ee8c9', 'Initial release :)', '', 1, 0, 0),
