(33590, 0, 'xf_googlepagespeed', 1, '0.1.0', 0, 0, 'Google Pagespeed', 'Google Pagespeed extension get from Google Pagespeed API for statistics form every site in your sitemap(s) and show your mistakes or problems.', 0, 0, 1, 1341149566, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"5.3.0-0.0.0";s:5:"typo3";s:11:"4.5.0-0.0.0";}}', 'Xaver Maierhofer', 'xaver.maierhofer@xwissen.info', 'x--f', 'dd06e8c8c4c22e8871807a3078db0142', '2 lines for each row, overflow in first result table (paging and search always visible), title over table, jQuery datatable update', 'Sam-City', 1000, 0, 0),
(33591, 0, 'xf_googlepagespeed', 1, '0.2.0', 0, 0, 'Google Pagespeed', 'Google Pagespeed extension get from Google Pagespeed API for statistics form every site in your sitemap(s) and show your mistakes or problems.', 0, 0, 1, 1347822299, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"5.3.0-0.0.0";s:5:"typo3";s:11:"4.5.0-0.0.0";}}', 'Xaver Maierhofer', 'xaver.maierhofer@xwissen.info', 'x--f', '61cf25e9656ebd32b27b12a99014b9bc', 'More colors, better overview, works better with small resolutions, target blank everywhere, jquery update, manual improvment, mark rows - THX2 t3cm12 for nice feedback and nice event!', 'Sam-City', 2000, 0, 0),
(33592, 0, 'xf_googlepagespeed', 1, '0.2.1', 0, 0, 'Google Pagespeed', 'Google Pagespeed extension get from Google Pagespeed API for statistics form every site in your sitemap(s) and show your mistakes or problems.', 0, 0, 1, 1347913239, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"5.3.0-0.0.0";s:5:"typo3";s:11:"4.5.0-0.0.0";}}', 'Xaver Maierhofer', 'xaver.maierhofer@xwissen.info', 'x--f', '73eaac6bfcadbb1aa9ecfbe3eef22b6b', 'Manual update & icon to Google insights', 'Sam-City', 2001, 0, 0),
(33593, 0, 'xf_googlepagespeed', 1, '0.3.0', 0, 0, 'Google Pagespeed', 'Google Pagespeed extension get from Google Pagespeed API for statistics form every site in your sitemap(s) and show your mistakes or problems.', 0, 0, 1, 1359224009, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"5.3.0-0.0.0";s:5:"typo3";s:11:"4.5.0-0.0.0";}}', 'Xaver Maierhofer', 'xaver.maierhofer@xwissen.info', 'x--f', '4be395fba88b73a7ccda7286d4b1499a', 'Added W3c and ValidatorNu; jQuery 2 beta much faster and no IE 6/7/8 support;less database usage; Reorganized settings', 'Sam-City', 3000, 0, 0),
(33594, 0, 'xf_googlepagespeed', 1, '0.3.1', 0, 0, 'Google Pagespeed', 'Gets information from Google Pagespeed API, W3c and ValidatorNu for every site in your sitemap(s) and shows possible mistakes or problems.', 999, 0, 1, 1367617806, 'a:2:{s:7:"depends";a:2:{s:3:"php";s:11:"5.3.0-0.0.0";s:5:"typo3";s:11:"4.5.0-6.1.0";}s:8:"suggests";a:1:{s:9:"xf_imgopt";s:11:"1.0.0-0.0.0";}}', 'Xaver Maierhofer', 'xaver.maierhofer@xwissen.info', 'x--f', '790eb4898ba090014cb4f280b6ea9760', 'SQL TYPO3  6.1 compatibly - fixed typo in ext_conf_template thx2opi99 - jQuery 2.0.0', 'Sam-City', 3001, 1, 0),
(33595, 0, 'xf_awstats', 1, '0.6.0', 0, 0, 'AWStats', 'Includes the AWStats logfile analyzer as a backend module. This is a fork of ics_awstats to continue development.', 2, 0, 1, 1341069104, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"5.3.0-0.0.0";s:5:"typo3";s:11:"4.5.0-0.0.0";}}', 'Xaver Maierhofer', 'xaver.maierhofer@xwissen.info', 'x--f', '523d35883b88e495f0ad5155ba9ae87f', 'Fork of ics_awstats, Security update awstats, fixed  TYPO3 v4.5, fixed IE9 overlap, fix CLI error, switched google charts to ssl, improved translation, manual changes', 'Sam-City', 6000, 0, 0),
(33596, 0, 'xf_awstats', 1, '0.7.0', 0, 0, 'AWStats', 'Includes the AWStats logfile analyzer as a backend module. This is a fork of ics_awstats to continue development.', 2, 0, 1, 1360111602, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"5.3.0-0.0.0";s:5:"typo3";s:11:"4.5.0-6.1.0";}}', 'Xaver Maierhofer', 'xaver.maierhofer@xwissen.info', 'x--f', '45dbd4bf85dd28f6766f7785e8914580', 'Update - AwStats to 7.1 - Added Win8 support / Added Tooltips / IPv6 GeoData - Changed logo - 1px, not visible\n', 'Sam-City', 7000, 1, 0),
(33597, 0, 'xf_web_awstats', 1, '0.5.0', 0, 0, 'Webuser AWStats', 'Provide AWStats Statistics in the Web-Section.', 2, 0, 1, 1341069342, 'a:1:{s:7:"depends";a:3:{s:3:"php";s:11:"5.3.0-0.0.0";s:5:"typo3";s:11:"4.5.0-0.0.0";s:10:"xf_awstats";s:11:"0.6.0-0.0.0";}}', 'Xaver Maierhofer', 'xaver.maierhofer@xwissen.info', 'x--f', '35610c2ea6b52e41eb21fae1f20f08f1', 'fork of ics_web_awstats, Moved plugin into help for full size, without pagetree. Use db_mountpoint for users, Manual updated (formation, actual style)', 'Sam-City', 5000, 0, 0),
(33598, 0, 'xf_web_awstats', 1, '0.6.0', 0, 0, 'Webuser AWStats', 'Provide AWStats Statistics in the help-section for normal beuser for xf_awstats plugin.', 2, 0, 1, 1341874565, 'a:1:{s:7:"depends";a:3:{s:3:"php";s:11:"5.3.0-0.0.0";s:5:"typo3";s:11:"4.5.0-0.0.0";s:10:"xf_awstats";s:11:"0.6.0-0.0.0";}}', 'Xaver Maierhofer', 'xaver.maierhofer@xwissen.info', 'x--f', '3199728023dbbd775a01a6f35f8dc393', 'Improvment - Moved plugin again to new menu point Statistic; Bugfix - db_mountpoint, array pointer problem', 'Sam-City', 6000, 0, 0),
(33599, 0, 'xf_web_awstats', 1, '0.6.1', 0, 0, 'Webuser AWStats', 'Provide AWStats Statistics in the help-section for normal beuser for xf_awstats plugin.', 2, 0, 1, 1342041562, 'a:1:{s:7:"depends";a:3:{s:3:"php";s:11:"5.3.0-0.0.0";s:5:"typo3";s:11:"4.5.0-0.0.0";s:10:"xf_awstats";s:11:"0.6.0-0.0.0";}}', 'Xaver Maierhofer', 'xaver.maierhofer@xwissen.info', 'x--f', '0a7c545458aa6f457647c5bda1ffa9b2', 'Bugfix - Small mistake (wrong variable), i dont know why it worked here... Sorry for update!', 'Sam-City', 6001, 1, 0),
