(33623, 0, 'readspeaker', 1, '0.1.0', 0, 0, 'ReadSpeaker - Online Text to Speech', 'This extension allows to integrate the ReadSpeaker service (http://www.readspeaker.com/) into TYPO3.', 0, 0, 2, 1342035156, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:11:"4.5.0-0.0.0";}}', 'Oliver Hader', 'oliver.hader@typo3.org', 'ohader', 'ba7ce78cb74c76ea3c649d57a6b50dbc', 'First release. Documentation is available in subfolder of this extension.\n\nFind project at http://forge.typo3.org/projects/show/extension-readspeaker', '', 1000, 0, 0),
(33624, 0, 'readspeaker', 1, '0.2.0', 0, 0, 'ReadSpeaker - Online Text to Speech', 'This extension allows to integrate the ReadSpeaker service (http://www.readspeaker.com/) into TYPO3.', 1, 0, 2, 1342041253, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:11:"4.5.0-0.0.0";}}', 'Oliver Hader', 'oliver.hader@typo3.org', 'ohader', 'baf5a7dafd92ee3d476a0f2945d8a57d', '[BUGFIX] ReadSpeaker application URL gets encoded twice\n[FEATURE] Add baseUrl as replacement for URL host prefix to be read\n[FEATURE] Add support for alternative voice used to read text\n[TASK] Update documentation\n', '', 2000, 0, 0),
