(33646, 0, 'mf_typekit', 1, '0.0.1', 0, 0, 'Typekit Webfont Loader', 'This little plugin includes the JavaScript-Code from typekit.com by using your  personal Typekit ID into your page header, easily configurable via TypoScript.\n\nTo use typekit, you will need an account. They have free and commercial accounts. ;) \n\nThe plugin is inspired from Google Web Font Loader (google_webfont) by  Graham Solomon.', 0, 0, 2, 1343037359, 'a:0:{}', 'Dipl.-Ing. (FH) Christoph Raschke', 'raschke@media-fire.de', 'craschke', '20a02ec2865bf3f1bb68361708b9559e', 'first release', '', 1, 0, 0),
