(33652, 0, 'tw_googleanalytics', 1, '0.9.0', 0, 0, 'tollwerk Google Analytics', 'Frontend plugin for advanced Google Analytics integration with a wide range of features including pageView and event tracking, custom variables, cross domain tracking, tracking of file downloads and external domains and much more. The extension is built on extbase / fluid and supports the asynchronous tracking code only (ga.js).', 1, 0, 3, 1343065278, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Joschi Kuphal', 'joschi@tollwerk.de', 'tollwerk', '8a1ef27739841ef0e9403843c9361063', '', 'tollwerk GmbH', 9000, 0, 0),
