INSERT INTO `tx_extensionmanager_domain_model_extension` (`uid`, `pid`, `extension_key`, `repository`, `version`, `alldownloadcounter`, `downloadcounter`, `title`, `description`, `state`, `review_state`, `category`, `last_updated`, `serialized_dependencies`, `author_name`, `author_email`, `ownerusername`, `md5hash`, `update_comment`, `authorcompany`, `integer_version`, `current_version`, `lastreviewedversion`) VALUES
(33683, 0, 'ods_magento', 1, '1.0.0', 0, 0, 'Magento category menu', 'Insert magento category tree in TYPO3 as menu items.', 1, 0, 4, 1343147467, 'a:0:{}', 'Robert Heel', 'rheel@1drop.de', 'bobosch', '562a703354d3d0ed0145aa16a2ad038d', 'Initial release.', 'http://www.1drop.de/', 1000000, 1, 0),
(33684, 0, 'hriseo', 1, '2.0.0', 0, 0, 'Search Engine Toolkit', 'Create sitemap.xml, robots.txt, canonical page tags and configures realurl', 2, 0, 2, 1343209358, 'a:2:{s:7:"depends";a:4:{s:7:"extbase";s:3:"1.3";s:5:"fluid";s:3:"1.3";s:5:"typo3";s:9:"4.5-0.0.0";s:7:"realurl";s:4:"1.11";}s:9:"conflicts";a:1:{s:16:"mc_googlesitemap";s:5:"0.4.2";}}', 'Ralf Schneider', 'ralf@hr-interactive.de', 'ralfbs', '0615da987ad234a8840153633696b163', 'Search Engine Toolkit', 'hr-interactive', 2000000, 1, 0),
(33685, 0, 'ods_felogin_button', 1, '0.1.0', 0, 0, 'Frontend Login Button', 'Simply login fe_users with one click. Could be used to accept disclaimers or something else.', 999, 0, 4, 1343228570, 'a:0:{}', 'Robert Heel', 'rheel@1drop.de', 'bobosch', '9528c57cd5faba70a17c33ee538801a4', 'Initial release.', 'http://www.1drop.de/', 1000, 1, 0),
(33686, 0, 'notify', 1, '0.1.0', 0, 0, 'Notification and subscription', 'Provides everything necessary to control subscriptions to changes in any record or file, along with all the infrastructure to send out fully customized notifications in many different ways. Highly configurable.', 0, 0, 3, 1343248321, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'namelesscoder', 'aabefca452c857096e4b490225704513', 'Initial release. CURRENTLY ALPHA STATE; sending of electronic messages incomplete, subscription logic complete, FE plugins complete. Example and description: http://extensions.fedext.net/extension-notify/overview.html', 'Wildside A/S', 1000, 0, 0),
(33687, 0, 'notify', 1, '0.2.0', 0, 0, 'Notification and subscription', 'Provides everything necessary to control subscriptions to changes in any record or file, along with all the infrastructure to send out fully customized notifications in many different ways. Highly configurable.', 0, 0, 3, 1347211939, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'namelesscoder', '6a4173f3759abf9fef8544618d7c95c5', 'Now beta quality. Additions: Notifications digest via email. Scheduler task to send notifications. FE user support.', 'Wildside A/S', 2000, 0, 0),
(33688, 0, 'notify', 1, '0.3.0', 0, 0, 'Notification and subscription', 'Provides everything necessary to control subscriptions to changes in any record or file, along with all the infrastructure to send out fully customized notifications in many different ways. Highly configurable.', 1, 0, 3, 1354472920, 'a:0:{}', 'Claus Due', 'claus@wildside.dk', 'namelesscoder', 'f0a45f0f9b14690eb4b68beb463a5651', 'Added: Fluid-based emails with ViewHelpers for attachment of inline images and files in your HTML emails; simply create a FluidEmail Message, feed it a template and Send through EmailService. Uses "eml" extension/format for template files.', 'Wildside A/S', 3000, 0, 0),
(33689, 0, 'notify', 1, '0.3.1', 0, 0, 'Notification and subscription', 'Provides everything necessary to control subscriptions to changes in any record or file, along with all the infrastructure to send out fully customized notifications in many different ways. Highly configurable.', 1, 0, 3, 1357691487, 'a:1:{s:7:"depends";a:7:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";s:4:"flux";s:0:"";s:11:"fluidwidget";s:0:"";s:3:"fed";s:0:"";s:3:"vhs";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'namelesscoder', '81effa8cd811511ec1531c0b05113f2f', 'Expected last beta state release. Fixes a number of bugs and introduces new features such as record data extraction, integration with EXT:dialog, CLI command (cron supported), improved Scheduler and a few minor UI features added. Documentation is coming s', 'Wildside A/S', 3001, 0, 0),
(33690, 0, 'notify', 1, '0.4.0', 0, 0, 'Notification and subscription', 'Provides everything necessary to control subscriptions to changes in any record or file, along with all the infrastructure to send out fully customized notifications in many different ways. Highly configurable.', 1, 0, 3, 1357691584, 'a:1:{s:7:"depends";a:7:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";s:4:"flux";s:0:"";s:11:"fluidwidget";s:0:"";s:3:"fed";s:0:"";s:3:"vhs";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'namelesscoder', '59dc0c96244e397235bd4cde1159ea00', 'Raised version to 0.4.0 - see last changelog message for change description.', 'Wildside A/S', 4000, 1, 0),
