(33717, 0, 'crystalis', 1, '0.0.8', 0, 0, 'Crystalis', 'The Crystalis Package Project. Very eraly development phase. DO NOT USE THIS EXTENSION ON LIVE SYSTEMS.', 3, 0, 0, 1344587360, 'a:0:{}', 'Daniel Haring', 'daniel@haring.co.at', 'cirgan', '84b4c99d3a3f15d7ac5bd87099b5aa33', 'Initial Upload. Basic structure and settings. Gallery module works partly.Early development phase.', '', 8, 0, 0),
(33718, 0, 'crystalis', 1, '1.0.0', 0, 0, 'Crystalis', 'The Crystalis package project. The goal is to substitute css_styled_content and to provide an own news and gallery system. Rendering will be processed with as many Typoscript as possible. THIS VERSION REPRESENTS THE VERY INITIAL DEVELOPMENT PHASE. DO NOT USE IT ON PRODUCTIVE SYSTEMS! ONLY CONTENT RENDERING IS IMPLEMENTED PARTLY.', 3, 0, 3, 1363292295, 'a:1:{s:7:"depends";a:3:{s:7:"extbase";s:3:"6.0";s:5:"fluid";s:3:"6.0";s:5:"typo3";s:9:"6.0-0.0.0";}}', 'Daniel Haring', 'daniel@haring.co.at', 'cirgan', '55ddf0aa362a069bbd30e12fc4619de6', 'Complete rewrite of the extension to support DDD and namespaces. Very initial phase. Not intended to be used already.', '', 1000000, 0, 0),
(33719, 0, 'crystalis', 1, '1.3.0', 0, 0, 'Crystalis', 'The Crystalis package project. The goal is to provide an own content rendering-, news- and gallery-system. Rendering will be processed with as many Typoscript as possible. THIS EXTENSION IS WORK IN PROGRESS. ONLY CONTENT RENDERING HAS GOT FINISHED SO FAR.', 0, 0, 2, 1364141240, 'a:1:{s:7:"depends";a:3:{s:7:"extbase";s:3:"6.0";s:5:"fluid";s:3:"6.0";s:5:"typo3";s:9:"6.0-0.0.0";}}', 'Daniel Haring', 'daniel@haring.co.at', 'cirgan', '56c9c2e691274705a151e2f7aa6e4765', 'Finished content rendering. Added german localization.', '', 1003000, 0, 0),
