(33729, 0, 'crystalis', 1, '1.6.0', 0, 0, 'Crystalis', 'The Crystalis package project. The goal is to provide an own content rendering-, news- and gallery-system. Rendering will be processed with as many Typoscript as possible. A complete rewrite of the gallery system is pending, as a result it can be rated as deprecated for now. THIS EXTENSION IS WORK IN PROGRESS. CONTENT RENDERING AND THE GALLERY SYSTEM ARE IMPLEMENTED SO FAR.', 0, 0, 2, 1399732242, 'a:1:{s:7:"depends";a:3:{s:7:"extbase";s:3:"6.1";s:5:"fluid";s:3:"6.1";s:5:"typo3";s:12:"6.1.0-6.2.99";}}', 'Daniel Haring', 'development@haring.co.at', 'cirgan', '33e23722c2e4de92fec03c920be7f014', 'Implemented the File Backend Layout Data Provider and some smaller fixes. Increased version compatibility to 6.2.99. See ChangeLog for a complete list.', '', 1006000, 0, 0),
(33730, 0, 'crystalis', 1, '1.6.1', 0, 0, 'Crystalis', 'The Crystalis package project. The goal is to provide an own content rendering-, news- and gallery-system. Rendering will be processed with as many Typoscript as possible. A complete rewrite of the gallery system is pending, as a result it can be rated as deprecated for now. THIS EXTENSION IS WORK IN PROGRESS. CONTENT RENDERING AND THE GALLERY SYSTEM ARE IMPLEMENTED SO FAR.', 0, 0, 2, 1400138462, 'a:1:{s:7:"depends";a:3:{s:7:"extbase";s:3:"6.1";s:5:"fluid";s:3:"6.1";s:5:"typo3";s:12:"6.1.0-6.2.99";}}', 'Daniel Haring', 'development@haring.co.at', 'cirgan', '5cf45bd12105df9d9659522e80b6423a', 'Fixed a bug where positioning CSS class is not assigned to content elements of type textpic.', '', 1006001, 0, 0),
(33731, 0, 'crystalis', 1, '6.2.0', 0, 0, 'Crystalis', 'A flexible headstone for professional next generation TYPO3 CMS websites. Crystalis provides content rendering, pre-configured setups, fully automatic language handling and many more. ', 2, 0, 2, 1426490697, 'a:1:{s:7:"depends";a:4:{s:3:"php";s:12:"5.4.0-5.6.99";s:7:"extbase";s:12:"6.2.0-6.2.99";s:5:"fluid";s:12:"6.2.0-6.2.99";s:5:"typo3";s:12:"6.2.1-6.2.99";}}', 'Daniel Haring', 'development@haring.co.at', 'cirgan', 'd92c3da8047bcae292fd368af8024734', 'Complete Rewrite from scratch. Crystalis version number will be synchronized with TYPO3 CMS core from now on.', '', 6002000, 0, 0),
