(33736, 0, 'crystalis', 1, '7.6.1', 0, 0, 'Crystalis', 'A flexible headstone for professional next generation TYPO3 CMS websites. Crystalis provides content rendering, pre-configured setups, fully automatic language handling and many more. ', 2, 0, 2, 1458762411, 'a:2:{s:7:"depends";a:3:{s:7:"extbase";s:12:"7.6.0-7.6.99";s:5:"fluid";s:12:"7.6.0-7.6.99";s:5:"typo3";s:12:"7.6.0-7.6.99";}s:8:"suggests";a:2:{s:7:"realurl";s:13:"1.13.4-2.0.99";s:7:"felogin";s:12:"7.6.0-7.6.99";}}', 'Daniel Haring', 'development@haring.co.at', 'cirgan', '91242a45d49f6e0f6cb462a05a31bed3', 'Fixed some major issues, changed vendor name, added support for RealURL 2.0.x. See ChangeLog for a complete list.', '', 7006001, 1, 0),
(33737, 0, 'tw_lucenesearch', 1, '0.6.0', 0, 0, 'tollwerk Lucene search', 'Simple and lightweight implementation of the Apache Lucene Index as frontend search solution for TYPO3, built on extbase / fluid, supporting wildcard and fuzzy searches, search term highlighting, indexing of uncached pages, custom search term rewrite hooks and much more  without any further software requirements (Java application server, Apache Solr etc.)', 1, 0, 3, 1345047636, 'a:1:{s:7:"depends";a:4:{s:7:"extbase";s:11:"1.3.0-0.0.0";s:5:"fluid";s:11:"1.3.0-0.0.0";s:3:"php";s:11:"5.2.0-0.0.0";s:5:"typo3";s:11:"4.5.0-0.0.0";}}', 'Dipl.-Ing. Joschi Kuphal', 'joschi@tollwerk.de', 'tollwerk', 'a96c2e5b91326bd409426935eda13fbc', 'Initial public release to the TYPO3 Extension Repository', 'tollwerk GmbH', 6000, 0, 0),
(33738, 0, 'tw_lucenesearch', 1, '0.6.1', 0, 0, 'tollwerk Lucene search', 'Simple and lightweight implementation of the Apache Lucene Index as frontend search solution for TYPO3, built on extbase / fluid, supporting wildcard and fuzzy searches, search term highlighting, indexing of uncached pages, custom search term rewrite hooks and much more  without any further software requirements (Java application server, Apache Solr etc.)', 1, 0, 3, 1348131491, 'a:1:{s:7:"depends";a:4:{s:7:"extbase";s:11:"1.3.0-0.0.0";s:5:"fluid";s:11:"1.3.0-0.0.0";s:3:"php";s:11:"5.2.0-0.0.0";s:5:"typo3";s:11:"4.5.0-0.0.0";}}', 'Dipl.-Ing. Joschi Kuphal', 'joschi@tollwerk.de', 'tollwerk', '548b1a9b7b4eecc6c5a7249c41012dbd', 'Fixed significant manual error: The indexing start marker is !--TYPO3SEARCH_begin-- (instead of !--TYPO3SEARCH_start-- as erroneously documented before)! Minor manual corrections', 'tollwerk GmbH', 6001, 0, 0),
(33739, 0, 'tw_lucenesearch', 1, '1.0.0', 0, 0, 'tollwerk Lucene search', '[TYPO3 CMS 6 Release] Simple and lightweight implementation of the Apache Lucene Index as frontend search solution for TYPO3, built on extbase / fluid, supporting wildcard and fuzzy searches, search term highlighting, indexing of uncached pages, custom search term rewrite hooks and much more without any further software requirements (Java application server, Apache Solr etc.). ATTENTION: Support for TYPO3 4.x has been dropped, use the 0.x versions instead!', 2, 0, 3, 1387644909, 'a:1:{s:7:"depends";a:4:{s:7:"extbase";s:11:"6.0.0-0.0.0";s:5:"fluid";s:11:"6.0.0-0.0.0";s:3:"php";s:11:"5.3.0-0.0.0";s:5:"typo3";s:12:"6.0.0-6.1.99";}}', 'Dipl.-Ing. Joschi Kuphal', 'joschi@tollwerk.de', 'tollwerk', '00d654d42d34c889e5a76da2c7b94f84', 'TYPO3 CMS 6 Release: Switch to PHP namespaces and the new class / sysext structure (no usage of the compatibility layer!)\nATTENTION: Support for TYPO3 4.x has been dropped, use the 0x versions instead!\nAdded more German language labels', 'tollwerk GmbH', 1000000, 0, 0),
(33740, 0, 'tw_lucenesearch', 1, '1.0.1', 0, 0, 'tollwerk Lucene search', '[TYPO3 CMS 6 Release] Simple and lightweight implementation of the Apache Lucene Index as frontend search solution for TYPO3, built on extbase / fluid, supporting wildcard and fuzzy searches, search term highlighting, indexing of uncached pages, custom search term rewrite hooks and much more without any further software requirements (Java application server, Apache Solr etc.). ATTENTION: Support for TYPO3 4.x has been dropped, use the 0.x versions instead!', 2, 0, 3, 1390401958, 'a:1:{s:7:"depends";a:4:{s:7:"extbase";s:11:"6.0.0-0.0.0";s:5:"fluid";s:11:"6.0.0-0.0.0";s:3:"php";s:11:"5.3.0-0.0.0";s:5:"typo3";s:12:"6.0.0-6.1.99";}}', 'Dipl.-Ing. Joschi Kuphal', 'joschi@tollwerk.de', 'tollwerk', '04eec26f96318c5d07a8fcac3369798a', 'Fixed a bug causing whitespace errors when indexing HTML5 documents', 'tollwerk GmbH', 1000001, 0, 0),
(33741, 0, 'tw_lucenesearch', 1, '1.0.2', 0, 0, 'tollwerk Lucene search', '[TYPO3 CMS 6 Release] Simple and lightweight implementation of the Apache Lucene Index as frontend search solution for TYPO3, built on extbase / fluid, supporting wildcard and fuzzy searches, search term highlighting, indexing of uncached pages, custom search term rewrite hooks and much more without any further software requirements (Java application server, Apache Solr etc.). ATTENTION: Support for TYPO3 4.x has been dropped, use the 0.x versions instead!', 2, 0, 3, 1390427427, 'a:1:{s:7:"depends";a:4:{s:7:"extbase";s:11:"6.0.0-0.0.0";s:5:"fluid";s:11:"6.0.0-0.0.0";s:3:"php";s:11:"5.3.0-0.0.0";s:5:"typo3";s:12:"6.0.0-6.1.99";}}', 'Dipl.-Ing. Joschi Kuphal', 'joschi@tollwerk.de', 'tollwerk', '595bc8c8daad628826790d870449aebe', 'Fixed a regression bug with wrong Flexform file name', 'tollwerk GmbH', 1000002, 1, 0),
