(33807, 0, 'toctoc_comments', 1, '3.1.0', 0, 0, 'AJAX Social Network Components', 'Adds AJAX social network components like commenting, rating, sharing or specific attachments to content elements or virtually any record visible in frontend. compatible with TemplaVoila.', 1, 0, 3, 1356046000, 'a:1:{s:7:"depends";a:1:{s:3:"php";s:13:"5.2.0-100.0.0";}}', 'Gisele Wendl', 'gisele.wendl@toctoc.ch', 'giselew', 'be23c3a14aa871e3681793e3dea0e457', 'fixed missing commentdate when displaying only comments without ratings\nfixed missing comment after insert of a subsequent comment in logged in mode\nfixed additional cache pages\nadded IP-blocking for comments\nmoved triggering prefixes from TS-config to an', 'TocToc Internetmanagement', 3001000, 0, 0),
(33808, 0, 'toctoc_comments', 1, '3.2.0', 0, 0, 'AJAX Social Network Components', 'Adds AJAX social network components like commenting, rating, sharing or specific attachments to content elements or virtually any record visible in frontend. compatible with TemplaVoila.', 1, 0, 3, 1357770516, 'a:1:{s:7:"depends";a:1:{s:3:"php";s:13:"5.2.0-100.0.0";}}', 'Gisele Wendl', 'gisele.wendl@toctoc.ch', 'giselew', 'a775f8df4b6ef5d06dab04e3205014bf', 'added a new marker for tt_news for entire plugin display in LIST, SEARCH and LATEST views\nredesigned and enhanced display of iLikes (and iDislikes) with facebook-like info about the users\nintroducing jQuery Tools (Tooltips in Comments-List)\nadded marker f', 'TocToc Internetmanagement', 3002000, 0, 0),
