(33810, 0, 'toctoc_comments', 1, '3.3.0', 0, 0, 'AJAX Social Network Components', 'Modern AJAX-based commenting and rating system. It allows sharing as well. Comments or ratings can be made on content elements or for any record visible in frontend. Compatible with TemplaVoila, tt_news, tt_products, community, cwt_community and many other extensions. Update from comments is possible. Comments can have attachments, BB-Code and smilies. Ratings by voting stars and facebook-like iLikes. Many options for spam-protection. AJAX is based on jQuery. The extension is extremely configurable.', 2, 0, 3, 1360538205, 'a:1:{s:7:"depends";a:1:{s:3:"php";s:13:"5.2.0-100.0.0";}}', 'Gisele Wendl', 'gisele.wendl@toctoc.ch', 'giselew', '2ae60d584d00b09f13e7389a045e1161', 'Classic mode COMMENTS,FORM can be changed to FORM,COMMENTS or COMMENTS now\nIntroducing picture- and PDF-attachments with nice presentation in frontend (scaled and cropped images as well as a nice jQuery Lightbox)\nHTML5 Fileuploading (only HTML5...)\nRevers', 'TocToc Internetmanagement', 3003000, 0, 0),
(33811, 0, 'toctoc_comments', 1, '9.2.5', 0, 0, 'AJAX Social Network Components', 'AJAX-based commenting, review, rating and sharing system (jQuery) for TYPO3 4.5 to 8.x. \n		Comments or reviews can have webpage previews, pictures and pdfs attached. You can use BB-Codes, emojis and smilies. \n		Userpictures include gravatar-, Facebook- or fe_users-userpictures. \n		More plugin-modes for comments are available, a user center, a recent comments list, a report bad comment form and several charts. \n		Many looks for ratings by voting stars and Facebook-like iLikes. Usage of scopes for categorized ratings. \n		There is a plugin-mode for top ratings. Many options for spam- and data-protection. AJAX runs with jQuery.\n		ViewHelpers for extension news. \n		Comments, reviews or ratings can trigger content elements, pages or records in other extensions DETAIL-views and LIST-views (LIST-view tt_news, news, modify all other pi1-extensions in PHP and implement a new marker or ViewHelper for comments and ratings in LIST-views).\n		Includes full featured AJAX Login and Sign Up, including login with Facebook or Google account. \n		Backendmodule for comments, users and system control\n		Works with TemplaVoila, tx_news, tt_news, tt_products, community, cwt_community and most of all other extensions.\n		Designable from included LESS-model', 2, 0, 3, 1477233357, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"4.5.0-8.9.99";s:3:"php";s:12:"5.5.0-7.9.99";}}', 'Gisele Wendl', 'gisele.wendl@toctoc.ch', 'giselew', 'bc087c93559f1ea2f42f18b4da1c34fa', 'Resolved all $TCA-migration messages in TYPO3 8.4.0 Installtool\nFixed: PHP warnings on AJAX-calls in TYPO3 8.4.0\nRemoved topSharings totally\nFixed: problem with user pictures in the commenting form containing special chars\nFixed: User pictures from Facebo', 'TocToc Internetmanagement', 9002005, 0, 0),
(33812, 0, 'toctoc_comments', 1, '3.4.0', 0, 0, 'AJAX Social Network Components', 'AJAX-based commenting and rating system. It allows sharing as well. Comments or ratings can be made on content elements or for any record visible in frontend. Compatible TYPO3 4.3 - 6.0, works with TemplaVoila, tt_news, tt_products, community, cwt_community and many other extensions. Update from ext. comments and associated ratings is possible. Comments can have attachments, BB-Code and smilies. 3 looks for ratings by voting stars and facebook-like iLikes. Many options for spam-protection. AJAX is based on jQuery. The extension is extremely configurable.', 2, 0, 3, 1363294363, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"4.5.0-6.0.99";s:3:"php";s:13:"5.2.0-100.0.0";}}', 'Gisele Wendl', 'gisele.wendl@toctoc.ch', 'giselew', 'e5f99c793957965a305b9fdb3e205787', '- Added inline reply mode with open form or linked form.\n- Added 2 new rating designs.\n- Added support for boxmodels, they document and implement changes to the CSS layout in a single file.\n- 9 new TS Options for Plugin Design are available as theme-o', 'TocToc Internetmanagement', 3004000, 0, 0),
(33813, 0, 'toctoc_comments', 1, '3.5.0', 0, 0, 'AJAX Social Network Components', 'AJAX-based commenting and rating system. It allows sharing as well. Comments or ratings can be made on content elements or for any record visible in frontend. Compatible TYPO3 4.4 - 6.0, works with TemplaVoila, tt_news, tt_products, community, cwt_community and many other extensions. Update from ext. comments and associated ratings is possible. Comments can have attachments, BB-Code and smilies. 3 looks for ratings by voting stars and facebook-like iLikes. Many options for spam-protection. AJAX is based on jQuery. The extension is extremely configurable.', 2, 0, 3, 1364854429, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"4.4.0-6.0.99";s:3:"php";s:13:"5.2.0-100.0.0";}}', 'Gisele Wendl', 'gisele.wendl@toctoc.ch', 'giselew', '91ea5db3f6bd55841660560ef73dcf06', 'Support for Unicode Emoji (iOS 6 set): You can type :RAINBOW: or any Emojitext, it will be converted to Unicode symbol (or insert a symbol directly) and after saving Emojis are displayed as images.\nAdded option advanced.useEmoji, which by default is set t', 'TocToc Internetmanagement', 3005000, 0, 0),
(33814, 0, 'toctoc_comments', 1, '3.6.0', 0, 0, 'AJAX Social Network Components', 'AJAX-based commenting and rating system. Compatible TYPO3 4.3 to 6.1 - works with TemplaVoila, tt_news, tt_products, community, cwt_community and many other extensions. Comments can have attachments, BB-Code and smilies. 3 looks for ratings by voting stars and facebook-like iLikes. Many options for spam-protection. AJAX is based on jQuery. Comments or ratings can trigger records in other extensions DETAIL-views. For all other views, pi1-extensions can be modified in PHP and implement a new marker for comments and ratings. The extension allows sharing as well and is extremely configurable.', 2, 0, 3, 1367779434, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"4.3.0-6.1.99";s:3:"php";s:13:"5.2.0-100.0.0";}}', 'Gisele Wendl', 'gisele.wendl@toctoc.ch', 'giselew', 'f234a3b9c3e25399c015ce7bba7a4e44', 'Added support for TYPO3-installations in subdirectories\nAdded support for multilingual or monolingual mode\nDatabase Update required	\nOptimization of use of TYPO3-Cache, less deletions of cache entries. Now page cache is only deleted on calls for recent co', 'TocToc Internetmanagement', 3006000, 0, 0),
(33815, 0, 'toctoc_comments', 1, '4.0.0', 0, 0, 'AJAX Social Network Components', 'AJAX-based commenting and rating system. Compatible TYPO3 4.3 to 6.1 - works with TemplaVoila, tt_news, tt_products, community, cwt_community and many other extensions. Comments can have webpage previews, pictures and pdfs attached. You can use BB-Codes, emojis and smilies. Additionally two more available plugin-modes for comments are available, a recent comments list and a report bad comment form. Three looks for ratings by voting stars and facebook-like iLikes, usage of scopes for categorizing ratings. For ratings there is a plugin-mode for top ratings. Many options for spam-protection. AJAX runs with jQuery. Comments or ratings can trigger records in other extensions DETAIL-views and LIST-views (LIST-view tt_news only, modify all other pi1-extensions in PHP and implement a new marker for comments and ratings in LIST-views). The extension allows sharing as well and is extremely configurable.', 2, 0, 3, 1375892955, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"4.3.0-6.1.99";s:3:"php";s:13:"5.2.0-100.0.0";}}', 'Gisele Wendl', 'gisele.wendl@toctoc.ch', 'giselew', '0eb132673ee42149fce453675ffc9a12', ' Added a smilie and emoji selection panel\n Added scopes (categories) for ratings\n Added plugin mode for top ratings\n Added support for custom texts from TypoScript\n Fixed position of a close button for messages occurring on comment-inserts for concer', 'TocToc Internetmanagement', 4000000, 0, 0),
(33816, 0, 'toctoc_comments', 1, '4.1.0', 0, 0, 'AJAX Social Network Components', 'AJAX-based commenting and rating system. Compatible TYPO3 4.3 to 6.1 - works with TemplaVoila, tt_news, tt_products, community, cwt_community and many other extensions. Comments can have webpage previews, pictures and pdfs attached. You can use BB-Codes, emojis and smilies. Additionally two more available plugin-modes for comments are available, a recent comments list and a report bad comment form. Three looks for ratings by voting stars and facebook-like iLikes, usage of scopes for categorizing ratings. For ratings there is a plugin-mode for top ratings. Many options for spam-protection. AJAX runs with jQuery. Comments or ratings can trigger records in other extensions DETAIL-views and LIST-views (LIST-view tt_news only, modify all other pi1-extensions in PHP and implement a new marker for comments and ratings in LIST-views). The extension allows sharing as well and is extremely configurable.', 2, 0, 3, 1378927604, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"4.3.0-6.1.99";s:3:"php";s:13:"5.2.0-100.0.0";}}', 'Gisele Wendl', 'gisele.wendl@toctoc.ch', 'giselew', 'dd51e9b1d8ccb9ed9eaf2649ea6bbf66', 'The main CSS, theme CSS, main JS now always have number of the extension version (now: 410) in the filename. On extension updates the old files will be preserved, this can be useful to track your changes.\nAdded checks for valid e-mails when sending notifi', 'TocToc Internetmanagement', 4001000, 0, 0),
(33817, 0, 'toctoc_comments', 1, '4.3.0', 0, 0, 'AJAX Social Network Components', 'AJAX-based commenting and rating system (jQuery). TYPO3 4.3 to 6.2. Works with TemplaVoila, tt_news, tt_products, community, cwt_community and many other extensions. Comments can have webpage previews, pictures and pdfs attached. You can use BB-Codes, emojis and smilies. More plugin-modes for comments are available, a recent comments list and a report bad comment form and several charts. Three looks for ratings by voting stars and facebook-like iLikes, usage of scopes for categorizing ratings. For ratings there is a plugin-mode for top ratings. Many options for spam-protection. AJAX runs with jQuery. Comments or ratings can trigger records in other extensions DETAIL-views and LIST-views (LIST-view tt_news only, modify all other pi1-extensions in PHP and implement a new marker for comments and ratings in LIST-views). The extension allows sharing as well and is extremely configurable.', 2, 0, 3, 1383048592, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"4.3.0-6.2.99";s:3:"php";s:13:"5.2.0-100.0.0";}}', 'Gisele Wendl', 'gisele.wendl@toctoc.ch', 'giselew', '8267fd0d75adf268bd3649e7a8070b61', 'Compatibility TYPO3 6.2\nAdded new commenting mode "login required", toctoc_comments installs a wrapper (XCLASS) on felogin. 2 new templates for standalone mode of the login form as well as the template needed for the loginRequired-mode (in folder res/te', 'TocToc Internetmanagement', 4003000, 0, 0),
(33818, 0, 'toctoc_comments', 1, '4.3.1', 0, 0, 'AJAX Social Network Components', 'AJAX-based commenting and rating system (jQuery). TYPO3 4.3 to 6.2. Works with TemplaVoila, tt_news, tt_products, community, cwt_community and many other extensions. Comments can have webpage previews, pictures and pdfs attached. You can use BB-Codes, emojis and smilies. More plugin-modes for comments are available, a recent comments list and a report bad comment form and several charts. Three looks for ratings by voting stars and facebook-like iLikes, usage of scopes for categorizing ratings. For ratings there is a plugin-mode for top ratings. Many options for spam-protection. AJAX runs with jQuery. Comments or ratings can trigger records in other extensions DETAIL-views and LIST-views (LIST-view tt_news only, modify all other pi1-extensions in PHP and implement a new marker for comments and ratings in LIST-views). The extension allows sharing as well and is extremely configurable.', 2, 0, 3, 1384435951, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"4.3.0-6.2.99";s:3:"php";s:11:"5.2.0-5.5.0";}}', 'Gisele Wendl', 'gisele.wendl@toctoc.ch', 'giselew', '6eff5205b60a007bfe1c1c6e4f0f9b51', 'Fixed PHP-code for code quality: See https://metrics.typo3.org/, see http://metrics.toctoc.ch/ for current quality (also JavaScript)\nHunting and fixing PHP 5.4 warnings and errors.\nUpdated sharing component sharrre to version 1.3.5\nUpdated comment report-', 'TocToc Internetmanagement', 4003001, 0, 0),
(33819, 0, 'toctoc_comments', 1, '4.3.2', 0, 0, 'AJAX Social Network Components', 'AJAX-based commenting and rating system (jQuery). TYPO3 4.3 to 6.2. Works with TemplaVoila, tt_news, tt_products, community, cwt_community and many other extensions. Comments can have webpage previews, pictures and pdfs attached. You can use BB-Codes, emojis and smilies. More plugin-modes for comments are available, a recent comments list and a report bad comment form and several charts. Three looks for ratings by voting stars and facebook-like iLikes, usage of scopes for categorizing ratings. For ratings there is a plugin-mode for top ratings. Many options for spam-protection. AJAX runs with jQuery. Comments or ratings can trigger records in other extensions DETAIL-views and LIST-views (LIST-view tt_news only, modify all other pi1-extensions in PHP and implement a new marker for comments and ratings in LIST-views). The extension allows sharing as well and is extremely configurable.', 2, 0, 3, 1384531798, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"4.3.0-6.2.99";s:3:"php";s:11:"5.2.0-5.5.0";}}', 'Gisele Wendl', 'gisele.wendl@toctoc.ch', 'giselew', 'ac18fa7381b9d298c590cbd52b1e4bc2', 'Fixed PHP-code for rules compliance with https://metrics.typo3.org/, see http://metrics.toctoc.ch/ for current quality (also JavaScript)\nFixed bug Captcha did not resolve, which was very annoying for anonymous commenters entering new comments\nHunting and ', 'TocToc Internetmanagement', 4003002, 0, 0),
(33820, 0, 'toctoc_comments', 1, '5.0.0', 0, 0, 'AJAX Social Network Components', 'AJAX-based commenting and rating system (jQuery) for TYPO3 4.3 to 6.2. Works with TemplaVoila, tt_news, tt_products, community, cwt_community and many other extensions. \n		Comments can have webpage previews, pictures and pdfs attached. You can use BB-Codes, emojis and smilies. \n		More plugin-modes for comments are available, a recent comments list and a report bad comment form and several charts. \n		Three looks for ratings by voting stars and facebook-like iLikes, usage of scopes for categorizing ratings. \n		For ratings there is a plugin-mode for top ratings. Many options for spam-protection. AJAX runs with jQuery. \n		Comments or ratings can trigger records in other extensions DETAIL-views and LIST-views (LIST-view tt_news only, modify all other pi1-extensions in PHP and implement a new marker for comments and ratings in LIST-views).\n		Includes full featured AJAX Login and Sign Up, including login with facebook account.\n		The extension allows sharing as well and is extremely configurable.', 2, 0, 3, 1391001450, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"4.3.0-6.2.99";s:3:"php";s:11:"5.2.0-5.5.0";}}', 'Gisele Wendl', 'gisele.wendl@toctoc.ch', 'giselew', '8c1e77ee061975dd197238dcc4140382', 'Removed all Inline-CSS and Inline-JavaScript, thus reducing radically the size of the HTML transferred from the server to the client.\nAdded BB-Code Selection Popup, advanced.useBBCodeMenu and advanced.BBCodebbs, a list with allowed BB-codes, configure the', 'TocToc Internetmanagement', 5000000, 0, 0),
(33821, 0, 'toctoc_comments', 1, '5.0.1', 0, 0, 'AJAX Social Network Components', 'AJAX-based commenting and rating system (jQuery) for TYPO3 4.3 to 6.2. Works with TemplaVoila, tt_news, tt_products, community, cwt_community and many other extensions. \n		Comments can have webpage previews, pictures and pdfs attached. You can use BB-Codes, emojis and smilies. \n		More plugin-modes for comments are available, a recent comments list and a report bad comment form and several charts. \n		Three looks for ratings by voting stars and facebook-like iLikes, usage of scopes for categorizing ratings. \n		For ratings there is a plugin-mode for top ratings. Many options for spam-protection. AJAX runs with jQuery. \n		Comments or ratings can trigger records in other extensions DETAIL-views and LIST-views (LIST-view tt_news only, modify all other pi1-extensions in PHP and implement a new marker for comments and ratings in LIST-views).\n		Includes full featured AJAX Login and Sign Up, including login with facebook account.\n		The extension allows sharing as well and is extremely configurable.', 2, 0, 3, 1393415480, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"4.3.0-6.2.99";s:3:"php";s:11:"5.2.0-5.5.0";}}', 'Gisele Wendl', 'gisele.wendl@toctoc.ch', 'giselew', '926212859fa1a34ca6116051ace0de52', '- Fixed JavaScript bug "After edit and save comment, the save comment event is not rebound"\n- Deleted smilie "frown  :[" from setup.txt. It interacted with BB-Codes\n- Fixed JavaScript error for AJAX page part refreshs after logins/logouts: "ids on t', 'TocToc Internetmanagement', 5000001, 0, 0),
(33822, 0, 'toctoc_comments', 1, '5.1.0', 0, 0, 'AJAX Social Network Components', 'AJAX-based commenting and rating system (jQuery) for TYPO3 4.3 to 6.2. Works with TemplaVoila, tt_news, tt_products, community, cwt_community and many other extensions. \n		Comments can have webpage previews, pictures and pdfs attached. You can use BB-Codes, emojis and smilies. \n		More plugin-modes for comments are available, a recent comments list and a report bad comment form and several charts. \n		Three looks for ratings by voting stars and facebook-like iLikes, usage of scopes for categorizing ratings. \n		For ratings there is a plugin-mode for top ratings. Many options for spam-protection. AJAX runs with jQuery. \n		Comments or ratings can trigger records in other extensions DETAIL-views and LIST-views (LIST-view tt_news only, modify all other pi1-extensions in PHP and implement a new marker for comments and ratings in LIST-views).\n		Includes full featured AJAX Login and Sign Up, including login with facebook account.\n		The extension allows sharing as well and is extremely configurable.', 2, 0, 3, 1398947392, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"4.3.0-6.2.99";s:3:"php";s:12:"5.2.0-5.4.99";}}', 'Gisele Wendl', 'gisele.wendl@toctoc.ch', 'giselew', '446d8114d20063bb73ba3348a2c561aa', 'Please change to the new template, it changed a little because of improvements in HTML-quality and support for $TYPO3_CONF_VARS[FE][versionNumberInFilename].\nCSS: Fixed calculation for top-margin of ratingstars and like-button with new entries in ', 'TocToc Internetmanagement', 5001000, 0, 0),
(33823, 0, 'toctoc_comments', 1, '5.2.0', 0, 0, 'AJAX Social Network Components', 'AJAX-based commenting and rating system (jQuery) for TYPO3 4.3 to 6.2. Works with TemplaVoila, tt_news, tt_products, community, cwt_community and many other extensions. \n		Comments can have webpage previews, pictures and pdfs attached. You can use BB-Codes, emojis and smilies. \n		More plugin-modes for comments are available, a recent comments list and a report bad comment form and several charts. \n		Three looks for ratings by voting stars and facebook-like iLikes, usage of scopes for categorizing ratings. \n		For ratings there is a plugin-mode for top ratings. Many options for spam-protection. AJAX runs with jQuery. \n		Comments or ratings can trigger records in other extensions DETAIL-views and LIST-views (LIST-view tt_news only, modify all other pi1-extensions in PHP and implement a new marker for comments and ratings in LIST-views).\n		Includes full featured AJAX Login and Sign Up, including login with facebook account.\n		The extension allows sharing as well and is extremely configurable.', 2, 0, 3, 1401616358, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"4.3.0-6.2.99";s:3:"php";s:12:"5.2.0-5.4.99";}}', 'Gisele Wendl', 'gisele.wendl@toctoc.ch', 'giselew', 'ef7a4e38efc011fe0123c638e5fcb57e', ' Please change to the new template\n Changed display of youtube-videos to the new embed-style, which allows videos to be seen also on tablets and handy\n Fixed CSS display of top rated item entry to "display: table;"\n added support for storagePid in t', 'TocToc Internetmanagement', 5002000, 0, 0),
(33824, 0, 'toctoc_comments', 1, '5.2.1', 0, 0, 'AJAX Social Network Components', 'AJAX-based commenting and rating system (jQuery) for TYPO3 4.3 to 6.2. Works with TemplaVoila, tt_news, tt_products, community, cwt_community and many other extensions. \n		Comments can have webpage previews, pictures and pdfs attached. You can use BB-Codes, emojis and smilies. \n		More plugin-modes for comments are available, a recent comments list and a report bad comment form and several charts. \n		Three looks for ratings by voting stars and facebook-like iLikes, usage of scopes for categorizing ratings. \n		For ratings there is a plugin-mode for top ratings. Many options for spam-protection. AJAX runs with jQuery. \n		Comments or ratings can trigger records in other extensions DETAIL-views and LIST-views (LIST-view tt_news only, modify all other pi1-extensions in PHP and implement a new marker for comments and ratings in LIST-views).\n		Includes full featured AJAX Login and Sign Up, including login with facebook account.\n		The extension allows sharing as well and is extremely configurable.', 2, 0, 3, 1402414094, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"4.3.0-6.2.99";s:3:"php";s:12:"5.2.0-5.5.99";}}', 'Gisele Wendl', 'gisele.wendl@toctoc.ch', 'giselew', '26b173d7190e7c6c45ff3da4b0397541', ' Fixed PHP Warning that appeared when page.IncludeJS or page.IncludeJSLibs is not set\n removed console.log print out from jquery.elastic\n  fixed wrong conversion of BB-Code [bq] when editing comments\n Set PHP compatibility to 5.2.0-5.5.99\n', 'TocToc Internetmanagement', 5002001, 0, 0),
(33825, 0, 'toctoc_comments', 1, '5.2.2', 0, 0, 'AJAX Social Network Components', 'AJAX-based commenting and rating system (jQuery) for TYPO3 4.3 to 6.2. \n		Comments can have webpage previews, pictures and pdfs attached. You can use BB-Codes, emojis and smilies. \n		More plugin-modes for comments are available, a recent comments list and a report bad comment form and several charts. \n		Three looks for ratings by voting stars and facebook-like iLikes, usage of scopes for categorizing ratings. \n		For ratings there is a plugin-mode for top ratings. Many options for spam-protection. AJAX runs with jQuery. \n		Comments or ratings can trigger records in other extensions DETAIL-views and LIST-views (LIST-view tt_news only, modify all other pi1-extensions in PHP and implement a new marker for comments and ratings in LIST-views).\n		Includes full featured AJAX Login and Sign Up, including login with facebook account. \n		Works with TemplaVoila, tt_news, tt_products, community, cwt_community and many other extensions. \n		The extension allows sharing as well and is extremely configurable.', 2, 0, 3, 1404724348, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"4.3.0-6.2.99";s:3:"php";s:12:"5.2.0-5.5.99";}}', 'Gisele Wendl', 'gisele.wendl@toctoc.ch', 'giselew', 'e0d0b4a4e0e767d6ddeab0bb5ec32a1c', '- CSS by toctoc_comments is now compressed by default. New option theme.crunchCSS enables (default) or disables the compression\n- Username for logged in facebook users displays now as first- and last name with link to the facebook profile page\n- Changed C', 'TocToc Internetmanagement', 5002002, 0, 0),
(33826, 0, 'toctoc_comments', 1, '5.3.0', 0, 0, 'AJAX Social Network Components', 'AJAX-based commenting and rating system (jQuery) for TYPO3 4.3 to 6.2. \n		Comments can have webpage previews, pictures and pdfs attached. You can use BB-Codes, emojis and smilies. \n		Userpictures include gravatar-, facebook- or fe_users-userpictures. \n		More plugin-modes for comments are available, a recent comments list and a report bad comment form and several charts. \n		Three looks for ratings by voting stars and facebook-like iLikes, usage of scopes for categorizing ratings. \n		For ratings there is a plugin-mode for top ratings. Many options for spam-protection. AJAX runs with jQuery. \n		Comments or ratings can trigger records in other extensions DETAIL-views and LIST-views (LIST-view tt_news only, modify all other pi1-extensions in PHP and implement a new marker for comments and ratings in LIST-views).\n		Includes full featured AJAX Login and Sign Up, including login with facebook account. \n		Works with TemplaVoila, tt_news, tt_products, community, cwt_community and many other extensions. \n		The extension allows sharing as well and is extremely configurable.', 2, 0, 3, 1406459895, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"4.3.0-6.2.99";s:3:"php";s:12:"5.2.0-5.5.99";}}', 'Gisele Wendl', 'gisele.wendl@toctoc.ch', 'giselew', '5fad305999fe272ed48c5e088c58abeb', 'Added gravatar user pictures with TypoScript option advanced.gravatarEnable. \nMax shown gravatar-rating can be configured with advanced.gravatarRating\nDefaultpictures in "gravatar"-mode remain existing user-pictures. \nTo prevent errors when gravatar.com', 'TocToc Internetmanagement', 5003000, 0, 0),
(33827, 0, 'toctoc_comments', 1, '5.4.0', 0, 0, 'AJAX Social Network Components', 'AJAX-based commenting and rating system (jQuery) for TYPO3 4.3 to 6.2. \n		Comments can have webpage previews, pictures and pdfs attached. You can use BB-Codes, emojis and smilies. \n		Userpictures include gravatar-, facebook- or fe_users-userpictures. \n		More plugin-modes for comments are available, a recent comments list and a report bad comment form and several charts. \n		Three looks for ratings by voting stars and facebook-like iLikes, usage of scopes for categorizing ratings. \n		For ratings there is a plugin-mode for top ratings. Many options for spam-protection. AJAX runs with jQuery. \n		Comments or ratings can trigger records in other extensions DETAIL-views and LIST-views (LIST-view tt_news only, modify all other pi1-extensions in PHP and implement a new marker for comments and ratings in LIST-views).\n		Includes full featured AJAX Login and Sign Up, including login with facebook account. \n		Works with TemplaVoila, tt_news, tt_products, community, cwt_community and many other extensions. \n		The extension allows sharing as well and is extremely configurable.', 2, 0, 3, 1410432144, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"4.3.0-6.2.99";s:3:"php";s:12:"5.2.0-5.5.99";}}', 'Gisele Wendl', 'gisele.wendl@toctoc.ch', 'giselew', '927c3878adb9ee622e413092d2739549', 'Minor changes in the template, please update, users of TYPO3 4.x please run database update in extension manager\n- Added hotlink to notification emails on already approved comments\n- Added TypoScript option advanced.notificationLevel: email-notifications ', 'TocToc Internetmanagement', 5004000, 0, 0),
(33828, 0, 'toctoc_comments', 1, '5.4.1', 0, 0, 'AJAX Social Network Components', 'AJAX-based commenting and rating system (jQuery) for TYPO3 4.3 to 6.2. \n		Comments can have webpage previews, pictures and pdfs attached. You can use BB-Codes, emojis and smilies. \n		Userpictures include gravatar-, facebook- or fe_users-userpictures. \n		More plugin-modes for comments are available, a recent comments list and a report bad comment form and several charts. \n		Three looks for ratings by voting stars and facebook-like iLikes, usage of scopes for categorizing ratings. \n		For ratings there is a plugin-mode for top ratings. Many options for spam-protection. AJAX runs with jQuery. \n		Comments or ratings can trigger records in other extensions DETAIL-views and LIST-views (LIST-view tt_news only, modify all other pi1-extensions in PHP and implement a new marker for comments and ratings in LIST-views).\n		Includes full featured AJAX Login and Sign Up, including login with facebook account. \n		Works with TemplaVoila, tt_news, tt_products, community, cwt_community and many other extensions. \n		The extension allows sharing as well and is extremely configurable.', 2, 0, 3, 1410526253, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"4.3.0-6.2.99";s:3:"php";s:12:"5.2.0-5.5.99";}}', 'Gisele Wendl', 'gisele.wendl@toctoc.ch', 'giselew', '9dc38ec849ebfc7a198a934732599612', 'Fixed bug comment insertion fails with MySQL 5.5.', 'TocToc Internetmanagement', 5004001, 0, 0),
(33829, 0, 'toctoc_comments', 1, '5.5.0', 0, 0, 'AJAX Social Network Components', 'AJAX-based commenting and rating system (jQuery) for TYPO3 4.3 to 6.2. \r\n		Comments can have webpage previews, pictures and pdfs attached. You can use BB-Codes, emojis and smilies. \r\n		Userpictures include gravatar-, facebook- or fe_users-userpictures. \r\n		More plugin-modes for comments are available, a recent comments list and a report bad comment form and several charts. \r\n		Three looks for ratings by voting stars and facebook-like iLikes, usage of scopes for categorizing ratings. \r\n		For ratings there is a plugin-mode for top ratings. Many options for spam-protection. AJAX runs with jQuery. \r\n		Comments or ratings can trigger records in other extensions DETAIL-views and LIST-views (LIST-view tt_news only, modify all other pi1-extensions in PHP and implement a new marker for comments and ratings in LIST-views).\r\n		Includes full featured AJAX Login and Sign Up, including login with facebook account. \r\n		Works with TemplaVoila, tt_news, tt_products, community, cwt_community and many other extensions. \r\n		The extension allows sharing as well and is extremely configurable.', 2, 0, 3, 1413373388, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"4.3.0-6.2.99";s:3:"php";s:12:"5.2.0-5.5.99";}}', 'Gisele Wendl', 'gisele.wendl@toctoc.ch', 'giselew', '6e8c91ed278a18fc93209d1573bb3978', 'Minor changes in the template for data protection features, please update\nCookies from not logged in users are no longer stored in clear text\nWith TypoScript-option advanced.acceptTermsCondsOnSubmit specify an ID of your page with term and conditions, the', 'TocToc Internetmanagement', 5005000, 0, 0);
INSERT INTO `tx_extensionmanager_domain_model_extension` (`uid`, `pid`, `extension_key`, `repository`, `version`, `alldownloadcounter`, `downloadcounter`, `title`, `description`, `state`, `review_state`, `category`, `last_updated`, `serialized_dependencies`, `author_name`, `author_email`, `ownerusername`, `md5hash`, `update_comment`, `authorcompany`, `integer_version`, `current_version`, `lastreviewedversion`) VALUES
(33830, 0, 'toctoc_comments', 1, '6.0.0', 0, 0, 'AJAX Social Network Components', 'AJAX-based commenting, review, rating and sharing system (jQuery) for TYPO3 4.3 to 6.2. \n		Comments or reviews can have webpage previews, pictures and pdfs attached. You can use BB-Codes, emojis and smilies. \n		Userpictures include gravatar-, facebook- or fe_users-userpictures. \n		More plugin-modes for comments are available, a user center, a recent comments list, a report bad comment form and several charts. \n		Three looks for ratings by voting stars and facebook-like iLikes, usage of scopes for categorizing ratings. \n		For ratings there is a plugin-mode for top ratings. Many options for spam- and data-protection. AJAX runs with jQuery.\n		ViewHelpers for extension news. \n		Comments, reviews or ratings can trigger records in other extensions DETAIL-views and LIST-views (LIST-view tt_news only, modify all other pi1-extensions in PHP and implement a new marker for comments and ratings in LIST-views).\n		Includes full featured AJAX Login and Sign Up, including login with facebook account. \n		Works with TemplaVoila, tx_news, tt_news, tt_products, community, cwt_community and many other extensions. \n		The extension is extremely configurable.', 2, 0, 3, 1417875899, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"4.3.0-6.2.99";s:3:"php";s:12:"5.2.0-5.5.99";}}', 'Gisele Wendl', 'gisele.wendl@toctoc.ch', 'giselew', 'dea42cb5c869a6fd0c58cb83e10881ec', ' Added TypoScript option advanced.commentReviews. When set to 1, then commenting is considered as reviewing: A review is a rating with a comment.\nOnly logged in users can write reviews. Reviews can be commented and rated like normal comments. At the base', 'TocToc Internetmanagement', 6000000, 0, 0),
(33831, 0, 'toctoc_comments', 1, '7.0.0', 0, 0, 'AJAX Social Network Components', 'AJAX-based commenting, review, rating and sharing system (jQuery) for TYPO3 4.3 to 7.0. \n		Comments or reviews can have webpage previews, pictures and pdfs attached. You can use BB-Codes, emojis and smilies. \n		Userpictures include gravatar-, facebook- or fe_users-userpictures. \n		More plugin-modes for comments are available, a user center, a recent comments list, a report bad comment form and several charts. \n		Three looks for ratings by voting stars and facebook-like iLikes, usage of scopes for categorizing ratings. \n		For ratings there is a plugin-mode for top ratings. Many options for spam- and data-protection. AJAX runs with jQuery.\n		ViewHelpers for extension news. \n		Comments, reviews or ratings can trigger records in other extensions DETAIL-views and LIST-views (LIST-view tt_news only, modify all other pi1-extensions in PHP and implement a new marker for comments and ratings in LIST-views).\n		Includes full featured AJAX Login and Sign Up, including login with facebook account. \n		Works with TemplaVoila, tx_news, tt_news, tt_products, community, cwt_community and many other extensions. \n		The extension is extremely configurable.', 2, 0, 3, 1419165970, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"4.3.0-7.0.99";s:3:"php";s:12:"5.2.0-5.6.99";}}', 'Gisele Wendl', 'gisele.wendl@toctoc.ch', 'giselew', 'a005dc2c3d8c1c159b39f9c3491d2221', ' Compatibility TYPO3 7 with or without EXT:compatibility6 installed, compatibility now covers TYPO3 versions 4.3 up to 7.0\n Compatibility PHP 5.6\n Fixed JS-error and wrong height of website-previews window when using captcha to confirm comment\n Beauti', 'TocToc Internetmanagement', 7000000, 0, 0),
(33832, 0, 'toctoc_comments', 1, '7.0.1', 0, 0, 'AJAX Social Network Components', 'AJAX-based commenting, review, rating and sharing system (jQuery) for TYPO3 4.3 to 7.0. \n		Comments or reviews can have webpage previews, pictures and pdfs attached. You can use BB-Codes, emojis and smilies. \n		Userpictures include gravatar-, facebook- or fe_users-userpictures. \n		More plugin-modes for comments are available, a user center, a recent comments list, a report bad comment form and several charts. \n		Three looks for ratings by voting stars and facebook-like iLikes, usage of scopes for categorizing ratings. \n		For ratings there is a plugin-mode for top ratings. Many options for spam- and data-protection. AJAX runs with jQuery.\n		ViewHelpers for extension news. \n		Comments, reviews or ratings can trigger records in other extensions DETAIL-views and LIST-views (LIST-view tt_news only, modify all other pi1-extensions in PHP and implement a new marker for comments and ratings in LIST-views).\n		Includes full featured AJAX Login and Sign Up, including login with facebook account. \n		Works with TemplaVoila, tx_news, tt_news, tt_products, community, cwt_community and many other extensions. \n		The extension is extremely configurable.', 2, 0, 3, 1424183633, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"4.3.0-7.0.99";s:3:"php";s:12:"5.3.7-5.6.99";}}', 'Gisele Wendl', 'gisele.wendl@toctoc.ch', 'giselew', '5e76e1008ec2ec53188cbcebbd80e980', ' Added refresh of spamhaus banned IPs to the backend administration interface, removed old files in /resources \n Fixed function getPreserveGetVars() in class.toctoc_comments_felogin_pi1.php to be fully compatible with TYPO3 older than version 4.7	\n Add', 'TocToc Internetmanagement', 7000001, 0, 0),
(33833, 0, 'toctoc_comments', 1, '7.1.0', 0, 0, 'AJAX Social Network Components', 'AJAX-based commenting, review, rating and sharing system (jQuery) for TYPO3 4.3 to 7.0. \n		Comments or reviews can have webpage previews, pictures and pdfs attached. You can use BB-Codes, emojis and smilies. \n		Userpictures include gravatar-, facebook- or fe_users-userpictures. \n		More plugin-modes for comments are available, a user center, a recent comments list, a report bad comment form and several charts. \n		Three looks for ratings by voting stars and facebook-like iLikes, usage of scopes for categorizing ratings. \n		For ratings there is a plugin-mode for top ratings. Many options for spam- and data-protection. AJAX runs with jQuery.\n		ViewHelpers for extension news. \n		Comments, reviews or ratings can trigger records in other extensions DETAIL-views and LIST-views (LIST-view tt_news only, modify all other pi1-extensions in PHP and implement a new marker for comments and ratings in LIST-views).\n		Includes full featured AJAX Login and Sign Up, including login with facebook account. \n		Works with TemplaVoila, tx_news, tt_news, tt_products, community, cwt_community and many other extensions. \n		The extension is extremely configurable.', 2, 0, 3, 1425659256, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"4.3.0-7.0.99";s:3:"php";s:12:"5.3.7-5.6.99";}}', 'Gisele Wendl', 'gisele.wendl@toctoc.ch', 'giselew', '7e9f64405c5f055c8f5564a50310382e', 'Added Plugin mode Comment Search, new TypoScript-options section "search" holds 7 options allowing customizing the search. \nAdded gender to fe_users, if not already there, added gender to fe_users TCA if not present yet.\nAdded error message if commenter', 'TocToc Internetmanagement', 7001000, 0, 0),
(33834, 0, 'toctoc_comments', 1, '7.2.0', 0, 0, 'AJAX Social Network Components', 'AJAX-based commenting, review, rating and sharing system (jQuery) for TYPO3 4.3 to 7.x. \n		Comments or reviews can have webpage previews, pictures and pdfs attached. You can use BB-Codes, emojis and smilies. \n		Userpictures include gravatar-, facebook- or fe_users-userpictures. \n		More plugin-modes for comments are available, a user center, a recent comments list, a report bad comment form and several charts. \n		Three looks for ratings by voting stars and facebook-like iLikes, usage of scopes for categorizing ratings. \n		For ratings there is a plugin-mode for top ratings. Many options for spam- and data-protection. AJAX runs with jQuery.\n		ViewHelpers for extension news. \n		Comments, reviews or ratings can trigger records in other extensions DETAIL-views and LIST-views (LIST-view tt_news only, modify all other pi1-extensions in PHP and implement a new marker for comments and ratings in LIST-views).\n		Includes full featured AJAX Login and Sign Up, including login with facebook account. \n		Works with TemplaVoila, tx_news, tt_news, tt_products, community, cwt_community and many other extensions. \n		The extension is extremely configurable.', 2, 0, 3, 1427451151, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"4.3.0-7.9.99";s:3:"php";s:12:"5.3.7-5.6.99";}}', 'Gisele Wendl', 'gisele.wendl@toctoc.ch', 'giselew', 'f5e4de1433787feb43e3e0dc903832d4', 'Compatibility with toctoccommentsce - new wrapper for toctoc_comments in content elements.\nNew popup message in the frontend if problems with jQuery are detected.\nExtended comments search to authors names.\nAfter login with the stand alone AJAX Login, new ', 'TocToc Internetmanagement', 7002000, 0, 0),
(33835, 0, 'toctoc_comments', 1, '7.3.0', 0, 0, 'AJAX Social Network Components', 'AJAX-based commenting, review, rating and sharing system (jQuery) for TYPO3 4.3 to 7.x. \n		Comments or reviews can have webpage previews, pictures and pdfs attached. You can use BB-Codes, emojis and smilies. \n		Userpictures include gravatar-, Facebook- or fe_users-userpictures. \n		More plugin-modes for comments are available, a user center, a recent comments list, a report bad comment form and several charts. \n		Four looks for ratings by voting stars and Facebook-like iLikes, usage of scopes for categorizing ratings. \n		For ratings there is a plugin-mode for top ratings. Many options for spam- and data-protection. AJAX runs with jQuery.\n		ViewHelpers for extension news. \n		Comments, reviews or ratings can trigger records in other extensions DETAIL-views and LIST-views (LIST-view tt_news, news, modify all other pi1-extensions in PHP and implement a new marker or ViewHelper for comments and ratings in LIST-views).\n		Includes full featured AJAX Login and Sign Up, including login with Facebook or Google account. \n		Works with TemplaVoila, tx_news, tt_news, tt_products, community, cwt_community and many other extensions. \n		The extension is extremely configurable.', 2, 0, 3, 1429893426, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"4.3.0-7.9.99";s:3:"php";s:12:"5.3.7-5.6.99";}}', 'Gisele Wendl', 'gisele.wendl@toctoc.ch', 'giselew', '43e395aec3bc192f75f9155b70c90f8e', 'Added Login with Google: You need create a google app on https://console.developers.google.com/project?authuser0 and use ClientID and ClientSecret to enable the feature\nHow to add an app on Google? See https://developers.google.com//web/signin/add-butt', 'TocToc Internetmanagement', 7003000, 0, 0),
