INSERT INTO `tx_extensionmanager_domain_model_extension` (`uid`, `pid`, `extension_key`, `repository`, `version`, `alldownloadcounter`, `downloadcounter`, `title`, `description`, `state`, `review_state`, `category`, `last_updated`, `serialized_dependencies`, `author_name`, `author_email`, `ownerusername`, `md5hash`, `update_comment`, `authorcompany`, `integer_version`, `current_version`, `lastreviewedversion`) VALUES
(33857, 0, 'toctoc_comments', 1, '9.2.10', 0, 0, 'AJAX Social Network Components', 'AJAX-based commenting, review, rating and sharing system (jQuery) for TYPO3 4.5 to 8.x. \n		Comments or reviews can have webpage previews, pictures and pdfs attached. You can use BB-Codes, emojis and smilies. \n		Userpictures include gravatar-, Facebook- or fe_users-userpictures. \n		More plugin-modes for comments are available, a user center, a recent comments list, a report bad comment form and several charts. \n		Many looks for ratings by voting stars and Facebook-like iLikes. Usage of scopes for categorized ratings. \n		There is a plugin-mode for top ratings. Many options for spam- and data-protection. AJAX runs with jQuery.\n		ViewHelpers for extension news. \n		Comments, reviews or ratings can trigger content elements, pages or records in other extensions DETAIL-views and LIST-views (LIST-view tt_news, news, modify all other pi1-extensions in PHP and implement a new marker or ViewHelper for comments and ratings in LIST-views).\n		Includes full featured AJAX Login and Sign Up, including login with Facebook or Google account. \n		Backendmodule for comments, users and system control\n		Works with TemplaVoila, tx_news, tt_news, tt_products, community, cwt_community and most of all other extensions.\n		Designable from included LESS-model', 2, 0, 3, 1492100468, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"4.5.0-8.9.99";s:3:"php";s:12:"5.5.0-7.9.99";}}', 'Gisele Wendl', 'gisele.wendl@toctoc.ch', 'giselew', '9d8a6d3a5ceb07f77d02b7e8be204190', 'Compatibility TYPO3 8.7 LTS\nCompatibility jQuery v3: When you use jQuery v3, then please set new TS-Setup-option advanced.usesjQuery3  1 (default 0)\nFixed links to images in administrators-eID-replies when using https\nFixed problem with likes on pagemode', 'TocToc Internetmanagement', 9002010, 1, 0),
