(33867, 0, 'parkside_storelocator', 1, '0.0.1', 0, 0, 'Storelocator', 'This Plugin offers, to import stores, seperated by countries, via xml.\n\nThe user has the possibility to search for a store nearby, or list all stores.', 0, 0, 2, 1345732548, 'a:1:{s:7:"depends";a:2:{s:3:"cms";s:0:"";s:18:"static_info_tables";s:0:"";}}', 'Florian Steinbauer', 'steinbauer@parkside.at', 'fsteinbauer', '025c30cd6405970f647e2e23f29641e9', 'First Preview, not fully functionable', '', 1, 0, 0),
(33868, 0, 'parkside_storelocator', 1, '0.1.0', 0, 0, 'Storelocator', 'This Extension allows you to manage all your stores in the Backend (Add, Change, Remove Stores, Import XML Storelist) and Output them in the Frontend. \nThis Extension also provides a plugin to show only nearby stores (filtered by zip code).', 0, 0, 2, 1346069378, 'a:1:{s:7:"depends";a:2:{s:3:"cms";s:0:"";s:18:"static_info_tables";s:0:"";}}', 'Florian Steinbauer', 'steinbauer@parkside.at', 'fsteinbauer', '798be51aa384f6eaec04497d4b044d64', '- HTML exported to Templates\n- Basic Configuration via TS\n- Fixed Bugs\n- Added Documentation', '', 1000, 1, 0),
