(33905, 0, 'frsupersized', 1, '0.1.0', 0, 0, 'Supersized - full screen background slideshow', 'This extension implements the jquery supersized plugin - full screen background slideshow  (http://buildinternet.com/project/supersized/ - MIT License / GPL License). Fully configurable via TS and Flexform. Can be used for a full sreen background / background slideshow and a background banner / banner slideshow. Realized with easy adaptable fluid templates.', 1, 0, 3, 1346762311, 'a:1:{s:7:"depends";a:4:{s:3:"cms";s:0:"";s:7:"extbase";s:5:"1.3.0";s:5:"fluid";s:5:"1.3.0";s:5:"typo3";s:11:"4.5.0-0.0.0";}}', 'Frank Frewer', 'info@frankfrewer.de', 'klaks', '8db8884e290b1fa7fa533e350729ac4d', 'Initial release.', 'medienbro // FRANK FREWER', 1000, 0, 0),
(33906, 0, 'frsupersized', 1, '0.1.1', 0, 0, 'Supersized - full screen background slideshow', 'This extension implements the jquery supersized plugin - full screen background slideshow  (http://buildinternet.com/project/supersized/ - MIT License / GPL License). Fully configurable via TS and Flexform. Can be used for a full sreen background / background slideshow and a background banner / banner slideshow. Realized with easy adaptable fluid templates.', 1, 0, 3, 1347190797, 'a:1:{s:7:"depends";a:4:{s:3:"cms";s:0:"";s:7:"extbase";s:5:"1.3.0";s:5:"fluid";s:5:"1.3.0";s:5:"typo3";s:11:"4.5.0-0.0.0";}}', 'Frank Frewer', 'info@frankfrewer.de', 'klaks', '4b97f8e38fe73f264d800ab6e4a779f8', 'Fixed a TYPO3 v.6beta compatibility issue.\nFixed two small bugs in fluid template Index.html \nRemove a leading slash in slides array image path in fluid template Headerdata.html \nIncrease maxitems for the slides field from 10 to 30 in flexform.\nTry to', 'medienbro // FRANK FREWER', 1001, 0, 0),
