(33946, 0, 'esp', 1, '1.1.0', 0, 0, 'Stored Procedures for TypoScript', '\nInterface to call Mysql Stored Procedures directly from TypoScript. \n\nThis is the implemantation of the ideas form a workshop in TYPO3 CampRheinRhur 2012. \n\nInput from the workshop:\n\n  TYPO3 works with mysql_pconnect. The scope of temporary tables is questionable.\n  To get them nonambiguous, use tablenames generated from random numbers.\n  Configure TypoScript of joined tables similiar to menus. (JoH)\n\nThe documentation is written in the upcomming sphinx format. \nTER still does not render it, yet. \n\n  You find HTML doc under EXT:exp/Manual/\n  TS-online: https://github.com/t3elmar/esp/blob/master/Documentation/TypoScriptReference.rst  \n\nClone the latest version from github: https://github.com/t3elmar/esp.git\n', 0, 0, 4, 1364638992, 'a:0:{}', 'Elmar Hinz', 't3elmar@gmail.com', 't3elmar', '93c29c6187915e48628e48059f79fe41', 'Back to ALPHA. Handling for non created tables.', '', 1001000, 0, 0),
(33947, 0, 'esp', 1, '2.0.1', 0, 0, 'esp - Call Stored Procedures from TypoScript', 'Back to Speed! Write extensions with only stored procedures and TypoScript, but without PHP. Originates CampRheinRhur 2012.', 1, 0, 4, 1365170577, 'a:0:{}', 'Elmar Hinz', 't3elmar@gmail.com', 't3elmar', 'f814145273ac3ab8da23601f6123a8c7', 'Going BETA. New API. No temporary tables. Mysqli. SimpleRenderer.', '', 2000001, 0, 0),
(33948, 0, 'esp', 1, '2.0.2', 0, 0, 'esp - Call Stored Procedures from TypoScript', 'Back to Speed! Write extensions with only stored procedures and TypoScript, but without PHP. Originates CampRheinRuhr 2012.', 1, 0, 4, 1437676486, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:3:"php";s:26:"5.0.0-5.4.99 --with-mysqli";s:5:"typo3";s:12:"4.5.0-6.2.99";}}', 'Elmar Hinz', 't3elmar@gmail.com', 't3elmar', '1bec933d12839d4ec5f41623bf198527', 'Bugfix version for JoinRenderer to access values of higher levels', '', 2000002, 0, 0),
(33949, 0, 'esp', 1, '2.0.3', 0, 0, 'esp - Call Stored Procedures from TypoScript', 'Back to Speed! -- Model: Roaring fast MySQL Stored Procedures, View: Good old TypoScript. No Extbase. -- Contains a SimpleRenderer for single table queries and a JoinRenderer for joined table queries. You can easily add your own renderer class for special tasks. Just implement the method render() like seen in the SimpleRenderer.', 1, 0, 4, 1437737163, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:27:"5.0.0-5.99.99 --with-mysqli";s:5:"typo3";s:12:"4.5.0-6.2.99";}}', 'Elmar Hinz', 't3elmar@gmail.com', 't3elmar', '07e899779ceed63b6f7b1cde8f95f5ad', 'Update of the description', 'Elmar Hinz', 2000003, 0, 0);
INSERT INTO `tx_extensionmanager_domain_model_extension` (`uid`, `pid`, `extension_key`, `repository`, `version`, `alldownloadcounter`, `downloadcounter`, `title`, `description`, `state`, `review_state`, `category`, `last_updated`, `serialized_dependencies`, `author_name`, `author_email`, `ownerusername`, `md5hash`, `update_comment`, `authorcompany`, `integer_version`, `current_version`, `lastreviewedversion`) VALUES
(33950, 0, 'esp', 1, '6.2.0', 0, 0, 'esp - Call Stored Procedures from TypoScript', '\nBack to speed!  \n-- Model: Roaring fast MySQL Stored Procedures, View: Good old TypoScript. -- A fast alternative to Extbase. \n-- Ships the classes SimpleRenderer for single table queries and JoinRenderer for joined table queries. \n-- You can easily add your own renderer classes for special tasks. Just implement the method render() like seen in SimpleRenderer or JoinRenderer.\n', 1, 0, 4, 1437751608, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:15:"5.3.2-5.999.999";s:5:"typo3";s:13:"6.0.0-6.2.999";}}', 'Elmar Hinz', 't3elmar@gmail.com', 't3elmar', 'f32711343395ea8e2614b0afab9785b1', 'TYPO3 6.x uses mysqli. From now on we can use the default DB-Connection of TYPO3 to call stored procedures.', 'Elmar Hinz', 6002000, 0, 0),
(33951, 0, 'esp', 1, '6.2.1', 0, 0, 'esp - Call Stored Procedures from TypoScript', '\nBack to speed!	\n-- Model: Roaring fast MySQL Stored Procedures, View: Good old TypoScript. -- A fast alternative to Extbase. \n-- Ships the classes SimpleRenderer for single table queries and JoinRenderer for joined table queries. \n-- You can easily add your own renderer classes for special tasks. Just implement the method render() like seen in SimpleRenderer or JoinRenderer.\n', 1, 0, 4, 1438083085, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:15:"5.3.2-5.999.999";s:5:"typo3";s:13:"6.0.0-6.2.999";}}', 'Elmar Hinz', 't3elmar@gmail.com', 't3elmar', 'a28c882c5b99ae069099a1597ea815ac', 'Migrating to namespaces. The old API is supported via ClassAliasMap.', 'Elmar Hinz', 6002001, 0, 0),
(33952, 0, 'esp', 1, '6.2.2', 0, 0, 'esp - Call Stored Procedures from TypoScript', '\nBack to speed!	\n-- Model: Roaring fast MySQL Stored Procedures, View: Good old TypoScript. -- A fast alternative to Extbase. \n-- Ships the classes SimpleRenderer for single table queries and JoinRenderer for joined table queries. \n-- You can easily add your own renderer classes for special tasks. Just implement the method render() like seen in SimpleRenderer or JoinRenderer.\n', 1, 0, 4, 1438101097, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.0.0-6.2.99";}}', 'Elmar Hinz', 't3elmar@gmail.com', 't3elmar', 'bf9d5183d8ef9a24030f025236253951', 'Renaming fetchAssociated to fetchAssociative. Keeping old API for backward compatibility but depreciated.', 'Elmar Hinz', 6002002, 0, 0),
(33953, 0, 'esp', 1, '6.2.3', 0, 0, 'esp - Call Stored Procedures from TypoScript', '\nBack to speed!	\n-- Model: Roaring fast MySQL Stored Procedures, View: Good old TypoScript. -- A fast alternative to Extbase. \n-- Ships the classes SimpleRenderer for single table queries and JoinRenderer for joined table queries. \n-- You can easily add your own renderer classes for special tasks. Just implement the method render() like seen in SimpleRenderer or JoinRenderer.\n', 1, 0, 4, 1438184059, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.0.0-6.2.99";}}', 'Elmar Hinz', 't3elmar@gmail.com', 't3elmar', 'd9351697b45c893a69a8fd6cd95317cb', 'Try to enable automatic manual rendering', 'Elmar Hinz', 6002003, 0, 0),
(33954, 0, 'esp', 1, '6.2.4', 0, 0, 'esp - Call Stored Procedures from TypoScript', '\nBack to speed!	\n-- Model: Roaring fast MySQL Stored Procedures, View: Good old TypoScript. -- A fast alternative to Extbase. \n-- Ships the classes SimpleRenderer for single table queries and JoinRenderer for joined table queries. \n-- You can easily add your own renderer classes for special tasks. Just implement the method render() like seen in SimpleRenderer or JoinRenderer.\n', 1, 0, 4, 1438236088, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.1.0-6.2.99";}}', 'Elmar Hinz', 't3elmar@gmail.com', 't3elmar', '7f13f9fb1b7d53e16c1be09c2b335a2a', 'Try to enable automatic PDF rendering on docs.typo3.org', 'Elmar Hinz', 6002004, 0, 0),
(33955, 0, 'esp', 1, '6.2.5', 0, 0, 'esp - Call Stored Procedures from TypoScript', '\nBack to speed!	\n-- Model: Roaring fast MySQL Stored Procedures, View: Good old TypoScript. -- A fast alternative to Extbase. \n-- Ships the classes SimpleRenderer for single table queries and JoinRenderer for joined table queries. \n-- You can easily add your own renderer classes for special tasks. Just implement the method render() like seen in SimpleRenderer or JoinRenderer.\n', 1, 0, 4, 1438254098, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.1.0-6.2.99";}}', 'Elmar Hinz', 't3elmar@gmail.com', 't3elmar', '0cbe5c1d3cf50a0646f475fed6816451', 'Try to enable automatic PDF rendering on docs.typo3.org', 'Elmar Hinz', 6002005, 0, 0),
(33956, 0, 'esp', 1, '6.2.6', 0, 0, 'esp - Call Stored Procedures from TypoScript', '\nBack to speed!	\n-- Model: Roaring fast MySQL Stored Procedures, View: Good old TypoScript. -- A fast alternative to Extbase. \n-- Ships the classes SimpleRenderer for single table queries and JoinRenderer for joined table queries. \n-- You can easily add your own renderer classes for special tasks. Just implement the method render() like seen in SimpleRenderer or JoinRenderer.\n', 1, 0, 4, 1438344478, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.1.0-6.2.99";}}', 'Elmar Hinz', 't3elmar@gmail.com', 't3elmar', 'd0d2224d5436b2fdd2cf6d8ad0e13fa5', 'Improve usecase documentation.', 'Elmar Hinz', 6002006, 1, 0),
