(33986, 0, 'mksearch', 1, '1.1.3', 0, 0, 'MK Search', 'Generic highly adjustable and extendable search engine framework, using Zend Lucene or Apache Solr.', 1, 0, 3, 1372406211, 'a:1:{s:7:"depends";a:2:{s:7:"rn_base";s:6:"0.13.2";s:5:"typo3";s:12:"4.4.0-6.1.99";}}', 'Michael Wagner, Hannes Bochmann, Rene Nitzsche', 'kontakt@das-medienkombinat.de', 'dasmedienkombinatgmbh', '834c42d7b109d2da56c50456ee25a5da', 'Some modifications for T3 6.x, single view for Solr-Plugin implemented. Better support for I18n. Better support for multivalued fields in plugin. Better default config for DAM indexer.', 'das MedienKombinat GmbH', 1001003, 0, 0),
