(33988, 0, 'mksearch', 1, '1.3.0', 0, 0, 'MK Search', 'Generic highly adjustable and extendable search engine framework, using Zend Lucene or Apache Solr.', 1, 0, 3, 1410255170, 'a:1:{s:7:"depends";a:2:{s:7:"rn_base";s:6:"0.13.7";s:5:"typo3";s:12:"4.4.0-6.2.99";}}', 'Michael Wagner, Hannes Bochmann, Rene Nitzsche', 'kontakt@das-medienkombinat.de', 'dasmedienkombinatgmbh', '8aafa4edaf2a81c4b924c9c0ab52fe74', ' compatbility to TYPO3 6.2.x\r\n fixed and optimized lucene search\r\n path to lucene can be relative\r\n added grouped facets\r\n several optimzations and bufixes', 'das MedienKombinat GmbH', 1003000, 0, 0),
(33989, 0, 'mksearch', 1, '1.4.0', 0, 0, 'MK Search', 'Generic highly adjustable and extendable search engine framework, using Zend Lucene or Apache Solr. But support for other search engines like elastic search etc. can be provided easily.', 2, 0, 3, 1419264854, 'a:1:{s:7:"depends";a:2:{s:7:"rn_base";s:6:"0.13.7";s:5:"typo3";s:12:"4.4.0-6.2.99";}}', 'Michael Wagner, Hannes Bochmann, Rene Nitzsche', 'dev@dmk-ebusiness.de', 'dasmedienkombinatgmbh', 'f1929d472562b115f0f7b8da9b01aee0', 'Basic support for ElasticSearch as search engine though the FE plugin is still experimental.\r\nThe manual is still not updated, too.', 'DMK E-Business GmbH', 1004000, 0, 0),
(33990, 0, 'mksearch', 1, '1.4.2', 0, 0, 'MK Search', 'Generic highly adjustable and extendable search engine framework, using Zend Lucene or Apache Solr. But support for other search engines like elastic search etc. can be provided easily.', 2, 0, 3, 1420806626, 'a:1:{s:7:"depends";a:2:{s:7:"rn_base";s:6:"0.13.7";s:5:"typo3";s:12:"4.4.0-6.2.99";}}', 'Michael Wagner, Hannes Bochmann, Rene Nitzsche', 'dev@dmk-ebusiness.de', 'dasmedienkombinatgmbh', 'eb43701dc1c52bebc9ad57598eb18642', ' Documentation now in rest format.\r\n Documentation for ElasticSearch support added.\r\n debugging of ElasticSearch requests added\r\n', 'DMK E-Business GmbH', 1004002, 0, 0),
(33991, 0, 'mksearch', 1, '1.4.4', 0, 0, 'MK Search', 'Generic highly adjustable and extendable search engine framework, using Zend Lucene, Apache Solr or ElasticSearch. But support for other search engines can be provided easily.', 2, 0, 3, 1425377449, 'a:1:{s:7:"depends";a:2:{s:7:"rn_base";s:7:"0.13.7-";s:5:"typo3";s:12:"4.4.0-6.2.99";}}', 'Michael Wagner, Hannes Bochmann, Rene Nitzsche', 'dev@dmk-ebusiness.de', 'dasmedienkombinatgmbh', 'f6d7be6c66c9f95c06d349c93e40ac9f', 'Bugfix: datasets in a rootline with a backenduser section is no longer indexed', 'DMK E-Business GmbH', 1004004, 0, 0),
(33992, 0, 'mksearch', 1, '1.4.8', 0, 0, 'MK Search', 'Generic highly adjustable and extendable search engine framework, using Zend Lucene, Apache Solr or ElasticSearch. But support for other search engines can be provided easily.', 2, 0, 3, 1425994185, 'a:1:{s:7:"depends";a:2:{s:7:"rn_base";s:7:"0.13.7-";s:5:"typo3";s:12:"4.4.0-6.2.99";}}', 'Michael Wagner, Hannes Bochmann, Rene Nitzsche', 'dev@dmk-ebusiness.de', 'dasmedienkombinatgmbh', 'b0994ac8bd5beaa748496707292d2d27', ' berwachung von FAL Dateien gefixed\r\n FAl Dateien auch indizieren bei nderungen an Metadata\r\n Datenstze nicht indizieren wenn Seite Backendbenutzerbereich ist', 'DMK E-Business GmbH', 1004008, 0, 0),
