(34029, 0, 'jh_basketballbund_import', 1, '0.0.3', 0, 0, 'basketball-bund.net - import', 'Import tables, results, playing schedules and statistics from basketball-bund.net to your website.', 0, 0, 3, 1348349194, 'a:0:{}', 'Jonathan Heilmann', 'mail@jonathan-heilmann.de', 'roboterfreak', '7511ab1bd23fe703ef5d62ac2769666b', 'Bugfixes in playing schedule and tables - Updated flexform for results - Added function for results - Removed nobr tag in all content-types - Updated manual', '', 3, 0, 0),
(34030, 0, 'jh_basketballbund_import', 1, '0.0.4', 0, 0, 'basketball-bund.net - import', 'Import tables, results, playing schedules and statistics from basketball-bund.net to your website.', 0, 0, 3, 1348418396, 'a:0:{}', 'Jonathan Heilmann', 'mail@jonathan-heilmann.de', 'roboterfreak', '5abbe668758a349b13b098e5d90c661a', 'Bugfix in playing schedule: selected columns have had the wrong order - Updated flexform-lables - Layout-settings in flexform are now useable - Added function for results -  Updated manual -- please report bugs to mail@jonathan-heilmann.de', '', 4, 0, 0),
(34031, 0, 'jh_basketballbund_import', 1, '0.0.5', 0, 0, 'basketball-bund.net - import', 'Import tables, results, playing schedules and statistics from basketball-bund.net to your website.', 0, 0, 3, 1348510857, 'a:0:{}', 'Jonathan Heilmann', 'mail@jonathan-heilmann.de', 'roboterfreak', '94ea6f40c08f63b31dbf9e722f236f4c', 'tidy code and added several comments - added flexform and function to allow or dissallow linebreaks in table-rows for all content-types (default: linebreaks are allowed) -- please report bugs to mail@jonathan-heilmann.de', '', 5, 0, 0),
(34032, 0, 'jh_basketballbund_import', 1, '0.0.6', 0, 0, 'basketball-bund.net - import', 'Import tables, results, playing schedules and statistics from basketball-bund.net to your website.', 0, 0, 3, 1348846222, 'a:0:{}', 'Jonathan Heilmann', 'mail@jonathan-heilmann.de', 'roboterfreak', '32ab7202c69bcc0fc9af5141af64536b', 'Import content from basketball-bund.net only if settings in flexform or TypoScript, or the content on basketball-bund.net, has been changed - accelerates the loading time and server speed noticeable  for mor changes see changelog and manual  please r', '', 6, 0, 0),
(34033, 0, 'jh_basketballbund_import', 1, '0.1.0', 0, 0, 'basketball-bund.net - import', 'Import tables, results, playing schedules and statistics from basketball-bund.net to your website.', 1, 0, 3, 1349019169, 'a:0:{}', 'Jonathan Heilmann', 'mail@jonathan-heilmann.de', 'roboterfreak', '4b7adaef7602fa1b8675e7fcdbc0e3dd', 'Released backend module to manage cache. Read manual for more information and changes. Please report bugs to mail@jonathan-heilmann.de', '', 1000, 0, 0),
(34034, 0, 'jh_basketballbund_import', 1, '0.1.1', 0, 0, 'basketball-bund.net - import', 'Import tables, results, playing schedules and statistics from basketball-bund.net to your website.', 1, 0, 3, 1349042719, 'a:0:{}', 'Jonathan Heilmann', 'mail@jonathan-heilmann.de', 'roboterfreak', 'a8c93db64fd28572ac8c14633781e27b', 'Updated manual (table of content was not updated) - Bugfix: wrong tablecolumns where displayed in some configuration-settings - please report bugs to mail@jonathan-heilmann.de', '', 1001, 0, 0),
