(34152, 0, 'aimeos', 1, '16.10.1', 0, 0, 'Aimeos web shop', 'Aimeos is a fast, flexible and usability optimized shop system and e-commerce solution available in multiple languages (also available as TYPO3 distribution). Several plugins e.g. for facetted search, product listing, detail view, basket, checkout process and other parts of a shop are available. Furthermore, Aimeos offers powerful interfaces to integrate CRM and ERP systems as well as payment and delivery service providers', 2, 0, 3, 1477468679, 'a:2:{s:7:"depends";a:6:{s:3:"php";s:13:"5.4.0-7.99.99";s:5:"typo3";s:13:"6.2.0-7.99.99";s:5:"fluid";s:13:"6.2.0-7.99.99";s:7:"extbase";s:13:"6.2.0-7.99.99";s:9:"scheduler";s:13:"6.2.0-7.99.99";s:18:"static_info_tables";s:13:"6.0.0-7.99.99";}s:8:"suggests";a:1:{s:7:"realurl";s:14:"1.12.8-2.99.99";}}', 'Aimeos', 'aimeos@aimeos.org', 'aimeos', 'bd957e576276393af4bd7076abfdeb3f', 'Enables default locale automatically to avoid exception after installation. Removing configurable attributes from basket products works again. Bugfix for RealURL. Beware: Use RealURL 1.13.6 instead of buggy 2.x!', '', 16010001, 0, 0),
(34153, 0, 'aimeos', 1, '1.3.0', 0, 0, 'Aimeos web shop', 'Aimeos is a flexible, high performance shop system available in multiple languages. Several plugins e.g. for facetted search, product listing, detail view, basket, checkout process and other parts of a shop are available. Furthermore, Aimeos offers powerful interfaces to integrate CRM and ERP systems as well as payment and delivery service providers', 2, 0, 3, 1412619406, 'a:3:{s:7:"depends";a:6:{s:3:"php";s:13:"5.3.2-5.99.99";s:5:"typo3";s:12:"4.5.0-6.2.99";s:5:"fluid";s:13:"1.3.1-6.99.99";s:7:"extbase";s:13:"1.3.2-6.99.99";s:9:"scheduler";s:13:"1.1.0-6.99.99";s:18:"static_info_tables";s:13:"1.8.0-6.99.99";}s:9:"conflicts";a:1:{s:14:"jquerycolorbox";s:11:"0.0.0-0.0.1";}s:8:"suggests";a:1:{s:7:"realurl";s:14:"1.10.0-1.99.99";}}', 'Aimeos', 'aimeos@aimeos.org', 'aimeos', '0bfaa323e3b72e89df7518fc27c4180e', 'Adds user-related pinned, favorite and watched product lists as well as social media integration. Cross selling possibilities were also extended by automatically calculated products bought by other customers in the product detail view and basket view.', '', 1003000, 0, 0),
(34154, 0, 'aimeos', 1, '1.4.0', 0, 0, 'Aimeos web shop', 'Aimeos is a flexible, high performance shop system available in multiple languages. Several plugins e.g. for facetted search, product listing, detail view, basket, checkout process and other parts of a shop are available. Furthermore, Aimeos offers powerful interfaces to integrate CRM and ERP systems as well as payment and delivery service providers', 2, 0, 3, 1418291339, 'a:2:{s:7:"depends";a:6:{s:3:"php";s:13:"5.3.2-5.99.99";s:5:"typo3";s:12:"4.5.0-6.2.99";s:5:"fluid";s:13:"1.3.1-6.99.99";s:7:"extbase";s:13:"1.3.2-6.99.99";s:9:"scheduler";s:13:"1.1.0-6.99.99";s:18:"static_info_tables";s:13:"1.8.0-6.99.99";}s:9:"conflicts";a:1:{s:14:"jquerycolorbox";s:11:"0.0.0-0.0.1";}}', 'Aimeos', 'aimeos@aimeos.org', 'aimeos', 'b2f97dce26f515d95111f7b3c03edaa8', 'Adds basic support for product bundles and multiple databases during setup. Content caching can be disabled now. All JS files can now be managed via TypoScript and two bugs for translation handling and overwriting configuration in extensions were fixed', '', 1004000, 0, 0),
(34155, 0, 'aimeos', 1, '1.4.1', 0, 0, 'Aimeos web shop', 'Aimeos is a flexible, high performance shop system available in multiple languages. Several plugins e.g. for facetted search, product listing, detail view, basket, checkout process and other parts of a shop are available. Furthermore, Aimeos offers powerful interfaces to integrate CRM and ERP systems as well as payment and delivery service providers', 2, 0, 3, 1418297421, 'a:2:{s:7:"depends";a:6:{s:3:"php";s:13:"5.3.2-5.99.99";s:5:"typo3";s:12:"4.5.0-6.2.99";s:5:"fluid";s:13:"1.3.1-6.99.99";s:7:"extbase";s:13:"1.3.2-6.99.99";s:9:"scheduler";s:13:"1.1.0-6.99.99";s:18:"static_info_tables";s:13:"1.8.0-6.99.99";}s:9:"conflicts";a:1:{s:14:"jquerycolorbox";s:11:"0.0.0-0.0.1";}}', 'Aimeos', 'aimeos@aimeos.org', 'aimeos', 'a1db66e9616b72341249f8fa610affb8', 'Adds basic support for product bundles and multiple databases during setup. Content caching can be disabled now. All JS files can now be managed via TypoScript and two bugs for translation handling and overwriting configuration in extensions were fixed', '', 1004001, 0, 0),
(34156, 0, 'aimeos', 1, '2.0.0', 0, 0, 'Aimeos web shop', 'Aimeos is a flexible, high performance shop system available in multiple languages. Several plugins e.g. for facetted search, product listing, detail view, basket, checkout process and other parts of a shop are available. Furthermore, Aimeos offers powerful interfaces to integrate CRM and ERP systems as well as payment and delivery service providers', 2, 0, 3, 1420457055, 'a:3:{s:7:"depends";a:6:{s:3:"php";s:13:"5.3.2-5.99.99";s:5:"typo3";s:12:"6.1.0-7.0.99";s:5:"fluid";s:12:"6.1.0-7.0.99";s:7:"extbase";s:12:"6.1.0-7.0.99";s:9:"scheduler";s:12:"6.1.0-7.0.99";s:18:"static_info_tables";s:13:"6.0.0-7.99.99";}s:9:"conflicts";a:1:{s:14:"jquerycolorbox";s:11:"0.0.0-0.0.1";}s:8:"suggests";a:1:{s:7:"realurl";s:14:"1.12.8-1.99.99";}}', 'Aimeos', 'aimeos@aimeos.org', 'aimeos', 'fc8b6a74c66ce37ce309ba49858e725b', 'Support for TYPO3 7.0 and 6.x, Aimeos 1.x will continue to support TYPO3 4.5 and later. Includes a simplified, more flexible and adaptable infrastructure for themes and has the ability to store non-shared properties for each product.', '', 2000000, 0, 0),
(34157, 0, 'aimeos', 1, '2.1.0', 0, 0, 'Aimeos web shop', 'Aimeos is a flexible, high performance shop system available in multiple languages (also available as TYPO3 distribution). Several plugins e.g. for facetted search, product listing, detail view, basket, checkout process and other parts of a shop are available. Furthermore, Aimeos offers powerful interfaces to integrate CRM and ERP systems as well as payment and delivery service providers', 1, 0, 3, 1424887064, 'a:3:{s:7:"depends";a:6:{s:3:"php";s:13:"5.3.2-5.99.99";s:5:"typo3";s:12:"6.1.0-7.0.99";s:5:"fluid";s:12:"6.1.0-7.0.99";s:7:"extbase";s:12:"6.1.0-7.0.99";s:9:"scheduler";s:12:"6.1.0-7.0.99";s:18:"static_info_tables";s:13:"6.0.0-7.99.99";}s:9:"conflicts";a:1:{s:14:"jquerycolorbox";s:11:"0.0.0-0.0.1";}s:8:"suggests";a:1:{s:7:"realurl";s:14:"1.12.8-1.99.99";}}', 'Aimeos', 'aimeos@aimeos.org', 'aimeos', '7d12b88ee946593fe73e061249f7e070', 'Adapt code to core changes: Improve compatibility by using better parameter names and renames catalog list JSON plugin to "suggest". Both require adapting existing installations. New feature: Scheduler job to generate XML sitemaps for search engines', '', 2001000, 0, 0);
