(34158, 0, 'aimeos', 1, '2.2.0', 0, 0, 'Aimeos web shop', 'Aimeos is a fast, flexible and usability optimized shop system available in multiple languages (also available as TYPO3 distribution). Several plugins e.g. for facetted search, product listing, detail view, basket, checkout process and other parts of a shop are available. Furthermore, Aimeos offers powerful interfaces to integrate CRM and ERP systems as well as payment and delivery service providers', 2, 0, 3, 1427786342, 'a:2:{s:7:"depends";a:6:{s:3:"php";s:13:"5.3.2-5.99.99";s:5:"typo3";s:12:"6.1.0-7.1.99";s:5:"fluid";s:12:"6.1.0-7.1.99";s:7:"extbase";s:12:"6.1.0-7.1.99";s:9:"scheduler";s:12:"6.1.0-7.1.99";s:18:"static_info_tables";s:13:"6.0.0-7.99.99";}s:8:"suggests";a:1:{s:7:"realurl";s:14:"1.12.8-1.99.99";}}', 'Aimeos', 'aimeos@aimeos.org', 'aimeos', '9d5f1d214175b17bcf3835a257076075', 'Stable LTS release with full Turkish translation. Support for MySQL sockets, template partials, placing pinned products an a different page and canonical URLs. Bugfixes for order addresses and direct debit as well as many layout improvements.', '', 2002000, 0, 0),
(34159, 0, 'aimeos', 1, '2.2.1', 0, 0, 'Aimeos web shop', 'Aimeos is a fast, flexible and usability optimized shop system available in multiple languages (also available as TYPO3 distribution). Several plugins e.g. for facetted search, product listing, detail view, basket, checkout process and other parts of a shop are available. Furthermore, Aimeos offers powerful interfaces to integrate CRM and ERP systems as well as payment and delivery service providers', 2, 0, 3, 1429601306, 'a:2:{s:7:"depends";a:6:{s:3:"php";s:13:"5.3.2-5.99.99";s:5:"typo3";s:12:"6.1.0-7.1.99";s:5:"fluid";s:12:"6.1.0-7.1.99";s:7:"extbase";s:12:"6.1.0-7.1.99";s:9:"scheduler";s:12:"6.1.0-7.1.99";s:18:"static_info_tables";s:13:"6.0.0-7.99.99";}s:8:"suggests";a:1:{s:7:"realurl";s:14:"1.12.8-1.99.99";}}', 'Aimeos', 'aimeos@aimeos.org', 'aimeos', '8428cc8566919dbfda0308d496ae647f', 'Important bugfix for faceted search in Google Chrome, PayPal provider didnt work when open_basedir was enabled, basket migrates between several sites without error and the "quote" subpart was missing in the product list view', '', 2002001, 0, 0),
(34160, 0, 'aimeos', 1, '2.2.2', 0, 0, 'Aimeos web shop', 'Aimeos is a fast, flexible and usability optimized shop system available in multiple languages (also available as TYPO3 distribution). Several plugins e.g. for facetted search, product listing, detail view, basket, checkout process and other parts of a shop are available. Furthermore, Aimeos offers powerful interfaces to integrate CRM and ERP systems as well as payment and delivery service providers', 2, 0, 3, 1432023775, 'a:2:{s:7:"depends";a:6:{s:3:"php";s:13:"5.3.2-5.99.99";s:5:"typo3";s:13:"6.1.0-7.99.99";s:5:"fluid";s:13:"6.1.0-7.99.99";s:7:"extbase";s:13:"6.1.0-7.99.99";s:9:"scheduler";s:13:"6.1.0-7.99.99";s:18:"static_info_tables";s:13:"6.0.0-7.99.99";}s:8:"suggests";a:1:{s:7:"realurl";s:14:"1.12.8-2.99.99";}}', 'Aimeos', 'aimeos@aimeos.org', 'aimeos', 'f8658f9e0d9f65659ca5daade4e0525f', 'Official support for TYPO3 7.2 and full compatibility of tag names. Fixes selection of country specific languages in admin interface incl. Dutch translation update. Prevents loosing the language ID in address checkout and improved image animation in list', '', 2002002, 0, 0),
(34161, 0, 'aimeos', 1, '2.2.3', 0, 0, 'Aimeos web shop', 'Aimeos is a fast, flexible and usability optimized shop system available in multiple languages (also available as TYPO3 distribution). Several plugins e.g. for facetted search, product listing, detail view, basket, checkout process and other parts of a shop are available. Furthermore, Aimeos offers powerful interfaces to integrate CRM and ERP systems as well as payment and delivery service providers', 2, 0, 3, 1434623822, 'a:2:{s:7:"depends";a:6:{s:3:"php";s:13:"5.3.2-5.99.99";s:5:"typo3";s:13:"6.1.0-7.99.99";s:5:"fluid";s:13:"6.1.0-7.99.99";s:7:"extbase";s:13:"6.1.0-7.99.99";s:9:"scheduler";s:13:"6.1.0-7.99.99";s:18:"static_info_tables";s:13:"6.0.0-7.99.99";}s:8:"suggests";a:1:{s:7:"realurl";s:14:"1.12.8-2.99.99";}}', 'Aimeos', 'aimeos@aimeos.org', 'aimeos', '8acfeda5fef9f17528a6926a4ff4f691', 'Contains a more robust parameter handling for the basket and an improved locale selector. Product labels used in all languages without product names fixes sorting problems. Zend i18n adapter change fixes e-mail problems in scheduler. Translations and CSS ', '', 2002003, 0, 0),
(34162, 0, 'aimeos', 1, '2.3.0', 0, 0, 'Aimeos web shop', 'Aimeos is a fast, flexible and usability optimized shop system available in multiple languages (also available as TYPO3 distribution). Several plugins e.g. for facetted search, product listing, detail view, basket, checkout process and other parts of a shop are available. Furthermore, Aimeos offers powerful interfaces to integrate CRM and ERP systems as well as payment and delivery service providers', 1, 0, 3, 1437985651, 'a:2:{s:7:"depends";a:6:{s:3:"php";s:13:"5.3.2-5.99.99";s:5:"typo3";s:13:"6.1.0-7.99.99";s:5:"fluid";s:13:"6.1.0-7.99.99";s:7:"extbase";s:13:"6.1.0-7.99.99";s:9:"scheduler";s:13:"6.1.0-7.99.99";s:18:"static_info_tables";s:13:"6.0.0-7.99.99";}s:8:"suggests";a:1:{s:7:"realurl";s:14:"1.12.8-2.99.99";}}', 'Aimeos', 'aimeos@aimeos.org', 'aimeos', '6410dd393f83813dd2953902bf60a20f', 'Contains a flexible CSV importer to add or update products and a extended payment provider interface. It supports 50 payment gateways by using the Aimeos ai-payments extension. Fixed default cache lifetime and a few problems in the admin interface.', '', 2003000, 0, 0),
(34163, 0, 'aimeos', 1, '2.2.4', 0, 0, 'Aimeos web shop', 'Aimeos is a fast, flexible and usability optimized shop system available in multiple languages (also available as TYPO3 distribution). Several plugins e.g. for facetted search, product listing, detail view, basket, checkout process and other parts of a shop are available. Furthermore, Aimeos offers powerful interfaces to integrate CRM and ERP systems as well as payment and delivery service providers', 2, 0, 3, 1441183037, 'a:2:{s:7:"depends";a:6:{s:3:"php";s:13:"5.3.2-5.99.99";s:5:"typo3";s:13:"6.1.0-7.99.99";s:5:"fluid";s:13:"6.1.0-7.99.99";s:7:"extbase";s:13:"6.1.0-7.99.99";s:9:"scheduler";s:13:"6.1.0-7.99.99";s:18:"static_info_tables";s:13:"6.0.0-7.99.99";}s:8:"suggests";a:1:{s:7:"realurl";s:14:"1.12.8-2.99.99";}}', 'Aimeos', 'aimeos@aimeos.org', 'aimeos', '5c17afc7a4213af9748f9b54b65a523c', 'Security release: Prevents malformed SQL queries. Please upgrade immediately!', '', 2002004, 0, 0),
(34164, 0, 'aimeos', 1, '2.3.1', 0, 0, 'Aimeos web shop', 'Aimeos is a fast, flexible and usability optimized shop system and e-commerce solution available in multiple languages (also available as TYPO3 distribution). Several plugins e.g. for facetted search, product listing, detail view, basket, checkout process and other parts of a shop are available. Furthermore, Aimeos offers powerful interfaces to integrate CRM and ERP systems as well as payment and delivery service providers', 2, 0, 3, 1441194445, 'a:2:{s:7:"depends";a:6:{s:3:"php";s:13:"5.3.2-5.99.99";s:5:"typo3";s:13:"6.1.0-7.99.99";s:5:"fluid";s:13:"6.1.0-7.99.99";s:7:"extbase";s:13:"6.1.0-7.99.99";s:9:"scheduler";s:13:"6.1.0-7.99.99";s:18:"static_info_tables";s:13:"6.0.0-7.99.99";}s:8:"suggests";a:1:{s:7:"realurl";s:14:"1.12.8-2.99.99";}}', 'Aimeos', 'aimeos@aimeos.org', 'aimeos', '65092bcaca39571a45e49492d20948b2', 'Security release: Prevents malformed SQL queries. Please upgrade immediately!\r\nFurthermore, it improves the CSV product importer and fixes HTML client decorators. Switching sites in the admin interface has also been fixed and passwords arent encoded twic', '', 2003001, 0, 0),
(34165, 0, 'aimeos', 1, '2.4.0', 0, 0, 'Aimeos web shop', 'Aimeos is a fast, flexible and usability optimized shop system and e-commerce solution available in multiple languages (also available as TYPO3 distribution). Several plugins e.g. for facetted search, product listing, detail view, basket, checkout process and other parts of a shop are available. Furthermore, Aimeos offers powerful interfaces to integrate CRM and ERP systems as well as payment and delivery service providers', 2, 0, 3, 1444888566, 'a:2:{s:7:"depends";a:6:{s:3:"php";s:13:"5.3.2-7.99.99";s:5:"typo3";s:13:"6.2.0-7.99.99";s:5:"fluid";s:13:"6.2.0-7.99.99";s:7:"extbase";s:13:"6.2.0-7.99.99";s:9:"scheduler";s:13:"6.2.0-7.99.99";s:18:"static_info_tables";s:13:"6.0.0-7.99.99";}s:8:"suggests";a:1:{s:7:"realurl";s:14:"1.12.8-2.99.99";}}', 'Aimeos', 'aimeos@aimeos.org', 'aimeos', '8b41bf72d2f39ab81dac6b5cc763a610', 'Full support for PHP 7 and almost every class can now be decorated. Customer accounts are created after ordering. Shop owners can manage customers and customer groups as well as supplier information. Stock levels of shop bundles are recalculated automatic', '', 2004000, 0, 0),
(34166, 0, 'aimeos', 1, '2.4.1', 0, 0, 'Aimeos web shop', 'Aimeos is a fast, flexible and usability optimized shop system and e-commerce solution available in multiple languages (also available as TYPO3 distribution). Several plugins e.g. for facetted search, product listing, detail view, basket, checkout process and other parts of a shop are available. Furthermore, Aimeos offers powerful interfaces to integrate CRM and ERP systems as well as payment and delivery service providers', 2, 0, 3, 1448547120, 'a:2:{s:7:"depends";a:6:{s:3:"php";s:13:"5.3.2-7.99.99";s:5:"typo3";s:13:"6.2.0-7.99.99";s:5:"fluid";s:13:"6.2.0-7.99.99";s:7:"extbase";s:13:"6.2.0-7.99.99";s:9:"scheduler";s:13:"6.2.0-7.99.99";s:18:"static_info_tables";s:13:"6.0.0-7.99.99";}s:8:"suggests";a:1:{s:7:"realurl";s:14:"1.12.8-2.99.99";}}', 'Aimeos', 'aimeos@aimeos.org', 'aimeos', 'a429a90eeb871792732741226e4f7551', 'Uses optimized MySQL catalog index by default and improves compatibility to MySQL 5.7. Fixed the catalog stage navigator subpart and image zoom in detail view. Improves product import from CSV and updates translations.', '', 2004001, 0, 0),
(34167, 0, 'aimeos', 1, '2.4.2', 0, 0, 'Aimeos web shop', 'Aimeos is a fast, flexible and usability optimized shop system and e-commerce solution available in multiple languages (also available as TYPO3 distribution). Several plugins e.g. for facetted search, product listing, detail view, basket, checkout process and other parts of a shop are available. Furthermore, Aimeos offers powerful interfaces to integrate CRM and ERP systems as well as payment and delivery service providers', 2, 0, 3, 1450349176, 'a:2:{s:7:"depends";a:6:{s:3:"php";s:13:"5.3.2-7.99.99";s:5:"typo3";s:13:"6.2.0-7.99.99";s:5:"fluid";s:13:"6.2.0-7.99.99";s:7:"extbase";s:13:"6.2.0-7.99.99";s:9:"scheduler";s:13:"6.2.0-7.99.99";s:18:"static_info_tables";s:13:"6.0.0-7.99.99";}s:8:"suggests";a:1:{s:7:"realurl";s:14:"1.12.8-2.99.99";}}', 'Aimeos', 'aimeos@aimeos.org', 'aimeos', '307e646a1c98dfe955e3433b28ed7c40', 'Fixed wrong exceptions during update and use the set category ID in the promotion list. Sets language in CSV import explicitly and solved the "undefined index" warning. Contains service decorator for downloads and displaying products from sub-categories', '', 2004002, 0, 0),
(34168, 0, 'aimeos', 1, '2.4.3', 0, 0, 'Aimeos web shop', 'Aimeos is a fast, flexible and usability optimized shop system and e-commerce solution available in multiple languages (also available as TYPO3 distribution). Several plugins e.g. for facetted search, product listing, detail view, basket, checkout process and other parts of a shop are available. Furthermore, Aimeos offers powerful interfaces to integrate CRM and ERP systems as well as payment and delivery service providers', 2, 0, 3, 1452601315, 'a:2:{s:7:"depends";a:6:{s:3:"php";s:13:"5.3.2-7.99.99";s:5:"typo3";s:13:"6.2.0-7.99.99";s:5:"fluid";s:13:"6.2.0-7.99.99";s:7:"extbase";s:13:"6.2.0-7.99.99";s:9:"scheduler";s:13:"6.2.0-7.99.99";s:18:"static_info_tables";s:13:"6.0.0-7.99.99";}s:8:"suggests";a:1:{s:7:"realurl";s:14:"1.12.8-2.99.99";}}', 'Aimeos', 'aimeos@aimeos.org', 'aimeos', '969d0af4b2b7639549b67109c96f7ed0', 'Keeps demo data untouched in the future and doesnt enable APC by default. Removes creating URLs in e-mail scheduler task due to TYPO3 bug. Fixes category list in catalog filter and updating customer items in admin interface. Spanish translation update\r\n', '', 2004003, 0, 0),
(34169, 0, 'aimeos', 1, '16.01.1', 0, 0, 'Aimeos web shop', 'Aimeos is a fast, flexible and usability optimized shop system and e-commerce solution available in multiple languages (also available as TYPO3 distribution). Several plugins e.g. for facetted search, product listing, detail view, basket, checkout process and other parts of a shop are available. Furthermore, Aimeos offers powerful interfaces to integrate CRM and ERP systems as well as payment and delivery service providers', 1, 0, 3, 1454685232, 'a:2:{s:7:"depends";a:6:{s:3:"php";s:13:"5.3.2-7.99.99";s:5:"typo3";s:13:"6.2.0-7.99.99";s:5:"fluid";s:13:"6.2.0-7.99.99";s:7:"extbase";s:13:"6.2.0-7.99.99";s:9:"scheduler";s:13:"6.2.0-7.99.99";s:18:"static_info_tables";s:13:"6.0.0-7.99.99";}s:8:"suggests";a:1:{s:7:"realurl";s:14:"1.12.8-2.99.99";}}', 'Aimeos', 'aimeos@aimeos.org', 'aimeos', '5a5762e8f6926f643deaad7d069b227c', 'Includes a simplified admin interface based on Bootstrap 4 and JQuery and a JSON API for administration. Content files can now be stored in the cloud transparently. Full support for PHP 7, MySQL 5.7 and PSR-1 / PSR-4 / PSR-7 standards.', '', 16001001, 0, 0),
