(34175, 0, 'aimeos', 1, '17.7.0', 0, 0, 'Aimeos web shop', 'Aimeos is a fast, flexible and usability optimized shop system and e-commerce solution available in multiple languages (also available as TYPO3 distribution). Several plugins e.g. for facetted search, product listing, detail view, basket, checkout process and other parts of a shop are available. Furthermore, Aimeos offers powerful interfaces to integrate CRM and ERP systems as well as payment and delivery service providers', 2, 0, 3, 1500369086, 'a:2:{s:7:"depends";a:4:{s:3:"php";s:13:"5.4.0-8.99.99";s:5:"typo3";s:13:"6.2.0-8.99.99";s:9:"scheduler";s:13:"6.2.0-8.99.99";s:18:"static_info_tables";s:13:"6.0.0-6.99.99";}s:8:"suggests";a:1:{s:7:"realurl";s:14:"1.12.8-1.99.99";}}', 'Aimeos', 'aimeos@aimeos.org', 'aimeos', 'e2ce07fe53bb6f05b29381abf2342449', 'Contains new administration interface and a JSON REST API hardened against attacks. Click&Collect and delivery times are supported and vouchers can have custom product prices. Theme design got a fresh-up and record updates are now up to 50% faster', '', 17007000, 0, 0),
(34176, 0, 'aimeos', 1, '2.4.6', 0, 0, 'Aimeos web shop', 'Aimeos is a fast, flexible and usability optimized shop system and e-commerce solution available in multiple languages (also available as TYPO3 distribution). Several plugins e.g. for facetted search, product listing, detail view, basket, checkout process and other parts of a shop are available. Furthermore, Aimeos offers powerful interfaces to integrate CRM and ERP systems as well as payment and delivery service providers', 2, 0, 3, 1459522155, 'a:2:{s:7:"depends";a:6:{s:3:"php";s:13:"5.3.2-7.99.99";s:5:"typo3";s:13:"6.2.0-7.99.99";s:5:"fluid";s:13:"6.2.0-7.99.99";s:7:"extbase";s:13:"6.2.0-7.99.99";s:9:"scheduler";s:13:"6.2.0-7.99.99";s:18:"static_info_tables";s:13:"6.0.0-7.99.99";}s:8:"suggests";a:1:{s:7:"realurl";s:14:"1.12.8-2.99.99";}}', 'Aimeos', 'aimeos@aimeos.org', 'aimeos', '7722e298ca6088519afd020a59549a27', 'Security release, please upgrade immediately!\r\nPrevents delivery/payment e-mails to be sent to customers who shouldnt receive it', '', 2004006, 0, 0),
(34177, 0, 'aimeos', 1, '16.4.1', 0, 0, 'Aimeos web shop', 'Aimeos is a fast, flexible and usability optimized shop system and e-commerce solution available in multiple languages (also available as TYPO3 distribution). Several plugins e.g. for facetted search, product listing, detail view, basket, checkout process and other parts of a shop are available. Furthermore, Aimeos offers powerful interfaces to integrate CRM and ERP systems as well as payment and delivery service providers', 2, 0, 3, 1460442986, 'a:2:{s:7:"depends";a:6:{s:3:"php";s:13:"5.4.0-7.99.99";s:5:"typo3";s:13:"6.2.0-7.99.99";s:5:"fluid";s:13:"6.2.0-7.99.99";s:7:"extbase";s:13:"6.2.0-7.99.99";s:9:"scheduler";s:13:"6.2.0-7.99.99";s:18:"static_info_tables";s:13:"6.0.0-7.99.99";}s:8:"suggests";a:1:{s:7:"realurl";s:14:"1.12.8-2.99.99";}}', 'Aimeos', 'aimeos@aimeos.org', 'aimeos', 'f544439535b9892e8ebc328fb610a8bb', 'Contians scheduler tasks improvements and message queue infrastructure for sending e-mails. Simple admin interface allows managing product attributes and properties. Orders are associated to customer accounts via e-mail address. Supports schema.org tags', '', 16004001, 0, 0),
