(34179, 0, 'aimeos', 1, '16.4.3', 0, 0, 'Aimeos web shop', 'Aimeos is a fast, flexible and usability optimized shop system and e-commerce solution available in multiple languages (also available as TYPO3 distribution). Several plugins e.g. for facetted search, product listing, detail view, basket, checkout process and other parts of a shop are available. Furthermore, Aimeos offers powerful interfaces to integrate CRM and ERP systems as well as payment and delivery service providers', 2, 0, 3, 1463558356, 'a:2:{s:7:"depends";a:6:{s:3:"php";s:13:"5.4.0-7.99.99";s:5:"typo3";s:13:"6.2.0-7.99.99";s:5:"fluid";s:13:"6.2.0-7.99.99";s:7:"extbase";s:13:"6.2.0-7.99.99";s:9:"scheduler";s:13:"6.2.0-7.99.99";s:18:"static_info_tables";s:13:"6.0.0-7.99.99";}s:8:"suggests";a:1:{s:7:"realurl";s:14:"1.12.8-2.99.99";}}', 'Aimeos', 'aimeos@aimeos.org', 'aimeos', '5d8d079ed26049ac3f879a9d923d938c', 'Fixed password sent when creating a new customer account automatically. Sanitizes URL parameters and removes characters that may confuse RealURL like slashes', '', 16004003, 0, 0),
(34180, 0, 'aimeos', 1, '2.4.7', 0, 0, 'Aimeos web shop', 'Aimeos is a fast, flexible and usability optimized shop system and e-commerce solution available in multiple languages (also available as TYPO3 distribution). Several plugins e.g. for facetted search, product listing, detail view, basket, checkout process and other parts of a shop are available. Furthermore, Aimeos offers powerful interfaces to integrate CRM and ERP systems as well as payment and delivery service providers', 2, 0, 3, 1465376479, 'a:2:{s:7:"depends";a:6:{s:3:"php";s:13:"5.3.2-7.99.99";s:5:"typo3";s:13:"6.2.0-7.99.99";s:5:"fluid";s:13:"6.2.0-7.99.99";s:7:"extbase";s:13:"6.2.0-7.99.99";s:9:"scheduler";s:13:"6.2.0-7.99.99";s:18:"static_info_tables";s:13:"6.0.0-7.99.99";}s:8:"suggests";a:1:{s:7:"realurl";s:14:"1.12.8-2.99.99";}}', 'Aimeos', 'aimeos@aimeos.org', 'aimeos', 'ed9b1b4e447e81d75933621b6c65f17f', 'Prevents duplicate orders for postpay / direct debit payment methods if users are clicking several times. No caching for logged in users is done any more. Translation update including a complete Chinese translation.', '', 2004007, 0, 0),
(34181, 0, 'aimeos', 1, '16.7.0', 0, 0, 'Aimeos web shop', 'Aimeos is a fast, flexible and usability optimized shop system and e-commerce solution available in multiple languages (also available as TYPO3 distribution). Several plugins e.g. for facetted search, product listing, detail view, basket, checkout process and other parts of a shop are available. Furthermore, Aimeos offers powerful interfaces to integrate CRM and ERP systems as well as payment and delivery service providers', 2, 0, 3, 1468923292, 'a:2:{s:7:"depends";a:6:{s:3:"php";s:13:"5.4.0-7.99.99";s:5:"typo3";s:13:"6.2.0-7.99.99";s:5:"fluid";s:13:"6.2.0-7.99.99";s:7:"extbase";s:13:"6.2.0-7.99.99";s:9:"scheduler";s:13:"6.2.0-7.99.99";s:18:"static_info_tables";s:13:"6.0.0-7.99.99";}s:8:"suggests";a:1:{s:7:"realurl";s:14:"1.12.8-2.99.99";}}', 'Aimeos', 'aimeos@aimeos.org', 'aimeos', '8a603080ac7ae4705ca94d065240c700', 'Many usability and layout improvments in the frontend. A dashboard is now part of the backend, displays various order related charts. Composer support. Bootstrap code can be replaced now in own extensions. DBAL support for PostgreSQL, Oracle, SQL Server', '', 16007000, 0, 0),
(34182, 0, 'aimeos', 1, '16.7.1', 0, 0, 'Aimeos web shop', 'Aimeos is a fast, flexible and usability optimized shop system and e-commerce solution available in multiple languages (also available as TYPO3 distribution). Several plugins e.g. for facetted search, product listing, detail view, basket, checkout process and other parts of a shop are available. Furthermore, Aimeos offers powerful interfaces to integrate CRM and ERP systems as well as payment and delivery service providers', 2, 0, 3, 1471514742, 'a:2:{s:7:"depends";a:6:{s:3:"php";s:13:"5.4.0-7.99.99";s:5:"typo3";s:13:"6.2.0-7.99.99";s:5:"fluid";s:13:"6.2.0-7.99.99";s:7:"extbase";s:13:"6.2.0-7.99.99";s:9:"scheduler";s:13:"6.2.0-7.99.99";s:18:"static_info_tables";s:13:"6.0.0-7.99.99";}s:8:"suggests";a:1:{s:7:"realurl";s:14:"1.12.8-2.99.99";}}', 'Aimeos', 'aimeos@aimeos.org', 'aimeos', 'f5a682d826b5bb787f5f5bfaea1138d1', 'Composer problem in TYPO3 6.2 has been fixed and autoloader problems should be gone now. Fixed some minor bug in the frontend and configuration settings arent merged any more so the can be overwritten.', '', 16007001, 0, 0),
(34183, 0, 'aimeos', 1, '16.7.2', 0, 0, 'Aimeos web shop', 'Aimeos is a fast, flexible and usability optimized shop system and e-commerce solution available in multiple languages (also available as TYPO3 distribution). Several plugins e.g. for facetted search, product listing, detail view, basket, checkout process and other parts of a shop are available. Furthermore, Aimeos offers powerful interfaces to integrate CRM and ERP systems as well as payment and delivery service providers', 2, 0, 3, 1474275638, 'a:2:{s:7:"depends";a:6:{s:3:"php";s:13:"5.4.0-7.99.99";s:5:"typo3";s:13:"6.2.0-7.99.99";s:5:"fluid";s:13:"6.2.0-7.99.99";s:7:"extbase";s:13:"6.2.0-7.99.99";s:9:"scheduler";s:13:"6.2.0-7.99.99";s:18:"static_info_tables";s:13:"6.0.0-7.99.99";}s:8:"suggests";a:1:{s:7:"realurl";s:14:"1.12.8-2.99.99";}}', 'Aimeos', 'aimeos@aimeos.org', 'aimeos', '6de591941dca19e0ed23653906a574ea', 'Allow e-mail addresses with more than 32 chars. Fixed problems for selections and texts without language in JQAdm interface. Improved upgrade from 2.4. Better RealURL config for checkout URLs. More information for errors in TS. Reduced package size', '', 16007002, 0, 0),
(34184, 0, 'aimeos', 1, '16.10.0', 0, 0, 'Aimeos web shop', 'Aimeos is a fast, flexible and usability optimized shop system and e-commerce solution available in multiple languages (also available as TYPO3 distribution). Several plugins e.g. for facetted search, product listing, detail view, basket, checkout process and other parts of a shop are available. Furthermore, Aimeos offers powerful interfaces to integrate CRM and ERP systems as well as payment and delivery service providers', 2, 0, 3, 1476946309, 'a:2:{s:7:"depends";a:6:{s:3:"php";s:13:"5.4.0-7.99.99";s:5:"typo3";s:13:"6.2.0-7.99.99";s:5:"fluid";s:13:"6.2.0-7.99.99";s:7:"extbase";s:13:"6.2.0-7.99.99";s:9:"scheduler";s:13:"6.2.0-7.99.99";s:18:"static_info_tables";s:13:"6.0.0-7.99.99";}s:8:"suggests";a:1:{s:7:"realurl";s:14:"1.12.8-2.99.99";}}', 'Aimeos', 'aimeos@aimeos.org', 'aimeos', '967391695aba9ea5e5a3c346678755aa', 'LTS version with up to 4 years support. Allows overwriting the Aimeos bootstrap code, selecting multiple default categories in list views and an alternative list view. Updated translations incl. Hungarian and Chinese. Note: RealURL 2.x is still unusable!', '', 16010000, 0, 0),
(34185, 0, 'aimeos', 1, '16.10.2', 0, 0, 'Aimeos web shop', 'Aimeos is a fast, flexible and usability optimized shop system and e-commerce solution available in multiple languages (also available as TYPO3 distribution). Several plugins e.g. for facetted search, product listing, detail view, basket, checkout process and other parts of a shop are available. Furthermore, Aimeos offers powerful interfaces to integrate CRM and ERP systems as well as payment and delivery service providers', 2, 0, 3, 1481803958, 'a:2:{s:7:"depends";a:6:{s:3:"php";s:13:"5.4.0-7.99.99";s:5:"typo3";s:13:"6.2.0-7.99.99";s:5:"fluid";s:13:"6.2.0-7.99.99";s:7:"extbase";s:13:"6.2.0-7.99.99";s:9:"scheduler";s:13:"6.2.0-7.99.99";s:18:"static_info_tables";s:13:"6.0.0-7.99.99";}s:8:"suggests";a:1:{s:7:"realurl";s:14:"1.12.8-2.99.99";}}', 'Aimeos', 'aimeos@aimeos.org', 'aimeos', '40ee8b078f63899cca387ba2d026970b', 'Tables managed by DBAL can now be modified by extensions. New Category decorator to show/hide delivery/payment options. Increased flexibility and some improvements/bugfixes.', '', 16010002, 0, 0),
(34186, 0, 'aimeos', 1, '16.10.3', 0, 0, 'Aimeos web shop', 'Aimeos is a fast, flexible and usability optimized shop system and e-commerce solution available in multiple languages (also available as TYPO3 distribution). Several plugins e.g. for facetted search, product listing, detail view, basket, checkout process and other parts of a shop are available. Furthermore, Aimeos offers powerful interfaces to integrate CRM and ERP systems as well as payment and delivery service providers', 2, 0, 3, 1484228607, 'a:2:{s:7:"depends";a:6:{s:3:"php";s:13:"5.4.0-7.99.99";s:5:"typo3";s:13:"6.2.0-7.99.99";s:5:"fluid";s:13:"6.2.0-7.99.99";s:7:"extbase";s:13:"6.2.0-7.99.99";s:9:"scheduler";s:13:"6.2.0-7.99.99";s:18:"static_info_tables";s:13:"6.0.0-7.99.99";}s:8:"suggests";a:1:{s:7:"realurl";s:14:"1.12.8-2.99.99";}}', 'Aimeos', 'aimeos@aimeos.org', 'aimeos', 'a2e1b4539584f507d0b0f238098a00ec', 'Bugfix for facetted search and better handling of transparency in uploaded images. Usability improvement in basket for long running requests and "create account" checkbox is only shown in checkout if customer isnt already logged in. Translation update', '', 16010003, 0, 0),
(34187, 0, 'aimeos', 1, '17.1.0', 0, 0, 'Aimeos web shop', 'Aimeos is a fast, flexible and usability optimized shop system and e-commerce solution available in multiple languages (also available as TYPO3 distribution). Several plugins e.g. for facetted search, product listing, detail view, basket, checkout process and other parts of a shop are available. Furthermore, Aimeos offers powerful interfaces to integrate CRM and ERP systems as well as payment and delivery service providers', 2, 0, 3, 1484822887, 'a:2:{s:7:"depends";a:6:{s:3:"php";s:13:"5.4.0-7.99.99";s:5:"typo3";s:13:"6.2.0-7.99.99";s:5:"fluid";s:13:"6.2.0-7.99.99";s:7:"extbase";s:13:"6.2.0-7.99.99";s:9:"scheduler";s:13:"6.2.0-7.99.99";s:18:"static_info_tables";s:13:"6.0.0-7.99.99";}s:8:"suggests";a:1:{s:7:"realurl";s:14:"1.12.8-2.99.99";}}', 'Aimeos', 'aimeos@aimeos.org', 'aimeos', 'd6d7ee6ce8cd51194249d7fade7e7fed', 'Templates are radically simplified and focus on templates, not configuration. JS libraries are updated and widely used PhotoSwipe/Slick are used for zoom and slider. Stock levels got their own data domain. "seperator..." config renamed to "separator..."', '', 17001000, 0, 0),
(34188, 0, 'aimeos', 1, '17.2.0', 0, 0, 'Aimeos web shop', 'Aimeos is a fast, flexible and usability optimized shop system and e-commerce solution available in multiple languages (also available as TYPO3 distribution). Several plugins e.g. for facetted search, product listing, detail view, basket, checkout process and other parts of a shop are available. Furthermore, Aimeos offers powerful interfaces to integrate CRM and ERP systems as well as payment and delivery service providers', 1, 0, 3, 1486640811, 'a:2:{s:7:"depends";a:6:{s:3:"php";s:13:"5.4.0-7.99.99";s:5:"typo3";s:13:"6.2.0-7.99.99";s:5:"fluid";s:13:"6.2.0-7.99.99";s:7:"extbase";s:13:"6.2.0-7.99.99";s:9:"scheduler";s:13:"6.2.0-7.99.99";s:18:"static_info_tables";s:13:"6.0.0-7.99.99";}s:8:"suggests";a:1:{s:7:"realurl";s:14:"1.12.8-2.99.99";}}', 'Aimeos', 'aimeos@aimeos.org', 'aimeos', '5de178b01870b66e05bdcb10bb6309ea', 'You can now use Fluid templates in your Aimeos project. Some bugfixes', '', 17002000, 0, 0),
(34189, 0, 'aimeos', 1, '17.2.1', 0, 0, 'Aimeos web shop', 'Aimeos is a fast, flexible and usability optimized shop system and e-commerce solution available in multiple languages (also available as TYPO3 distribution). Several plugins e.g. for facetted search, product listing, detail view, basket, checkout process and other parts of a shop are available. Furthermore, Aimeos offers powerful interfaces to integrate CRM and ERP systems as well as payment and delivery service providers', 1, 0, 3, 1487765525, 'a:2:{s:7:"depends";a:6:{s:3:"php";s:13:"5.4.0-7.99.99";s:5:"typo3";s:13:"6.2.0-7.99.99";s:5:"fluid";s:13:"6.2.0-7.99.99";s:7:"extbase";s:13:"6.2.0-7.99.99";s:9:"scheduler";s:13:"6.2.0-7.99.99";s:18:"static_info_tables";s:13:"6.0.0-7.99.99";}s:8:"suggests";a:1:{s:7:"realurl";s:14:"1.12.8-2.99.99";}}', 'Aimeos', 'aimeos@aimeos.org', 'aimeos', '4380b577ff6d32cb61d6ecc80e6026a3', 'Important bugfixes.\r\nPlease update to this version instead of 17.1.0 and 17.2.0!', '', 17002001, 0, 0),
(34190, 0, 'aimeos', 1, '16.10.4', 0, 0, 'Aimeos web shop', 'Aimeos is a fast, flexible and usability optimized shop system and e-commerce solution available in multiple languages (also available as TYPO3 distribution). Several plugins e.g. for facetted search, product listing, detail view, basket, checkout process and other parts of a shop are available. Furthermore, Aimeos offers powerful interfaces to integrate CRM and ERP systems as well as payment and delivery service providers', 2, 0, 3, 1488885578, 'a:2:{s:7:"depends";a:6:{s:3:"php";s:13:"5.4.0-7.99.99";s:5:"typo3";s:13:"6.2.0-8.99.99";s:5:"fluid";s:13:"6.2.0-8.99.99";s:7:"extbase";s:13:"6.2.0-8.99.99";s:9:"scheduler";s:13:"6.2.0-8.99.99";s:18:"static_info_tables";s:13:"6.0.0-6.99.99";}s:8:"suggests";a:1:{s:7:"realurl";s:14:"1.12.8-1.99.99";}}', 'Aimeos', 'aimeos@aimeos.org', 'aimeos', '3bee489b0268ddaf4f32b3ae754745e7', 'Workaround for TYPO3 7.6.16, support for TYPO3 8.x and bootstrap_package 7.x. The shown admin interface is configurable now and it implements OR-conditions for the faceted search. Translations have been updated too.', '', 16010004, 0, 0),
(34191, 0, 'aimeos', 1, '17.3.0', 0, 0, 'Aimeos web shop', 'Aimeos is a fast, flexible and usability optimized shop system and e-commerce solution available in multiple languages (also available as TYPO3 distribution). Several plugins e.g. for facetted search, product listing, detail view, basket, checkout process and other parts of a shop are available. Furthermore, Aimeos offers powerful interfaces to integrate CRM and ERP systems as well as payment and delivery service providers', 2, 0, 3, 1489485653, 'a:2:{s:7:"depends";a:6:{s:3:"php";s:13:"5.4.0-8.99.99";s:5:"typo3";s:13:"6.2.0-8.99.99";s:5:"fluid";s:13:"6.2.0-8.99.99";s:7:"extbase";s:13:"6.2.0-8.99.99";s:9:"scheduler";s:13:"6.2.0-8.99.99";s:18:"static_info_tables";s:13:"6.0.0-6.99.99";}s:8:"suggests";a:1:{s:7:"realurl";s:14:"1.12.8-1.99.99";}}', 'Aimeos', 'aimeos@aimeos.org', 'aimeos', 'afa33c44f013bf390f8ef9850033004d', 'Adds workaround for TYPO3 7.6.16. Implements frontend JSON REST API and adds config for admin interface shown by default. The export jobs are now listed in the advanced scheduler. Changed RealURL config to avoid PHP-FPM "Primary script unknown" issue', '', 17003000, 0, 0),
(34192, 0, 'aimeos', 1, '17.4.0', 0, 0, 'Aimeos web shop', 'Aimeos is a fast, flexible and usability optimized shop system and e-commerce solution available in multiple languages (also available as TYPO3 distribution). Several plugins e.g. for facetted search, product listing, detail view, basket, checkout process and other parts of a shop are available. Furthermore, Aimeos offers powerful interfaces to integrate CRM and ERP systems as well as payment and delivery service providers', 2, 0, 3, 1492679423, 'a:2:{s:7:"depends";a:4:{s:3:"php";s:13:"5.4.0-8.99.99";s:5:"typo3";s:13:"6.2.0-8.99.99";s:9:"scheduler";s:13:"6.2.0-8.99.99";s:18:"static_info_tables";s:13:"6.0.0-6.99.99";}s:8:"suggests";a:1:{s:7:"realurl";s:14:"1.12.8-1.99.99";}}', 'Aimeos', 'aimeos@aimeos.org', 'aimeos', 'f367f69398af3fc7ff624f5c6e1fdf9c', 'Full frontend JSON REST API for mobile and JS apps, merged "order" and "process" checkout steps. Fixed generating URLs in the scheduler task, page tree is now hidden by default and extended catalog filter flexform. Many improvements for developers', '', 17004000, 0, 0),
(34193, 0, 'aimeos', 1, '17.4.1', 0, 0, 'Aimeos web shop', 'Aimeos is a fast, flexible and usability optimized shop system and e-commerce solution available in multiple languages (also available as TYPO3 distribution). Several plugins e.g. for facetted search, product listing, detail view, basket, checkout process and other parts of a shop are available. Furthermore, Aimeos offers powerful interfaces to integrate CRM and ERP systems as well as payment and delivery service providers', 2, 0, 3, 1495101048, 'a:2:{s:7:"depends";a:4:{s:3:"php";s:13:"5.4.0-8.99.99";s:5:"typo3";s:13:"6.2.0-8.99.99";s:9:"scheduler";s:13:"6.2.0-8.99.99";s:18:"static_info_tables";s:13:"6.0.0-6.99.99";}s:8:"suggests";a:1:{s:7:"realurl";s:14:"1.12.8-1.99.99";}}', 'Aimeos', 'aimeos@aimeos.org', 'aimeos', '4d476a06fdfcb3fae1ffdc2b3d711a22', 'Security release due to payment handling vulnerability, please update! Also includes various bugfixes and several improvements like the new delivery time decorator', '', 17004001, 0, 0),
(34194, 0, 'aimeos', 1, '16.10.5', 0, 0, 'Aimeos web shop', 'Aimeos is a fast, flexible and usability optimized shop system and e-commerce solution available in multiple languages (also available as TYPO3 distribution). Several plugins e.g. for facetted search, product listing, detail view, basket, checkout process and other parts of a shop are available. Furthermore, Aimeos offers powerful interfaces to integrate CRM and ERP systems as well as payment and delivery service providers', 2, 0, 3, 1495448820, 'a:2:{s:7:"depends";a:6:{s:3:"php";s:13:"5.4.0-7.99.99";s:5:"typo3";s:13:"6.2.0-8.99.99";s:5:"fluid";s:13:"6.2.0-8.99.99";s:7:"extbase";s:13:"6.2.0-8.99.99";s:9:"scheduler";s:13:"6.2.0-8.99.99";s:18:"static_info_tables";s:13:"6.0.0-6.99.99";}s:8:"suggests";a:1:{s:7:"realurl";s:14:"1.12.8-1.99.99";}}', 'Aimeos', 'aimeos@aimeos.org', 'aimeos', 'fa4cd3e12ead749c168c3f3914d62390', 'Security release due to payment handling weakness. Contains bugfixes and improvements for tax and service handling (downloads). ', '', 16010005, 0, 0),
(34195, 0, 'aimeos', 1, '17.4.2', 0, 0, 'Aimeos web shop', 'Aimeos is a fast, flexible and usability optimized shop system and e-commerce solution available in multiple languages (also available as TYPO3 distribution). Several plugins e.g. for facetted search, product listing, detail view, basket, checkout process and other parts of a shop are available. Furthermore, Aimeos offers powerful interfaces to integrate CRM and ERP systems as well as payment and delivery service providers', 2, 0, 3, 1498124828, 'a:2:{s:7:"depends";a:4:{s:3:"php";s:13:"5.4.0-8.99.99";s:5:"typo3";s:13:"6.2.0-8.99.99";s:9:"scheduler";s:13:"6.2.0-8.99.99";s:18:"static_info_tables";s:13:"6.0.0-6.99.99";}s:8:"suggests";a:1:{s:7:"realurl";s:14:"1.12.8-1.99.99";}}', 'Aimeos', 'aimeos@aimeos.org', 'aimeos', '3b31ee091d5a0a7253b2a3e7e28dcf51', 'Removed "orderid" parameter from RealUrl config because it resets values of the same parameter name from payment gateways', '', 17004002, 0, 0),
