(34197, 0, 'aimeos', 1, '17.7.2', 0, 0, 'Aimeos web shop', 'Aimeos is a fast, flexible and usability optimized shop system and e-commerce solution available in multiple languages (also available as TYPO3 distribution). Several plugins e.g. for facetted search, product listing, detail view, basket, checkout process and other parts of a shop are available. Furthermore, Aimeos offers powerful interfaces to integrate CRM and ERP systems as well as payment and delivery service providers', 2, 0, 3, 1505390102, 'a:2:{s:7:"depends";a:4:{s:3:"php";s:13:"5.4.0-8.99.99";s:5:"typo3";s:13:"6.2.0-8.99.99";s:9:"scheduler";s:13:"6.2.0-8.99.99";s:18:"static_info_tables";s:13:"6.0.0-6.99.99";}s:8:"suggests";a:1:{s:7:"realurl";s:14:"1.12.8-1.99.99";}}', 'Aimeos', 'aimeos@aimeos.org', 'aimeos', 'f7382b2d6c8d413ed8991c73ca5c2bca', 'New version due to TER security incident. See\r\n]https://typo3.org/teams/security/security-bulletins/psa/typo3-psa-2017-001/', '', 17007002, 0, 0),
(34198, 0, 'aimeos', 1, '17.10.0', 0, 0, 'Aimeos web shop', 'Aimeos is a fast, flexible and usability optimized shop system and e-commerce solution available in multiple languages (also available as TYPO3 distribution). Several plugins e.g. for facetted search, product listing, detail view, basket, checkout process and other parts of a shop are available. Furthermore, Aimeos offers powerful interfaces to integrate CRM and ERP systems as well as payment and delivery service providers', 2, 0, 3, 1508313970, 'a:2:{s:7:"depends";a:4:{s:3:"php";s:13:"5.4.0-8.99.99";s:5:"typo3";s:13:"6.2.0-8.99.99";s:9:"scheduler";s:13:"6.2.0-8.99.99";s:18:"static_info_tables";s:13:"6.0.0-6.99.99";}s:8:"suggests";a:1:{s:7:"realurl";s:14:"1.12.8-1.99.99";}}', 'Aimeos', 'aimeos@aimeos.org', 'aimeos', '8f926d1965e50ecc84e3aaeab23fd86b', 'Full-featured administration interface using the JSON REST API incl. new panels for managing suppliers, services, plugins, locales and types. CSV imports and exports in administration interface. Contains a configurable group based access control system', '', 17010000, 0, 0),
(34199, 0, 'aimeos', 1, '17.10.1', 0, 0, 'Aimeos web shop', 'Aimeos is a fast, flexible and usability optimized shop system and e-commerce solution available in multiple languages (also available as TYPO3 distribution). Several plugins e.g. for facetted search, product listing, detail view, basket, checkout process and other parts of a shop are available. Furthermore, Aimeos offers powerful interfaces to integrate CRM and ERP systems as well as payment and delivery service providers', 2, 0, 3, 1510831832, 'a:0:{}', 'Aimeos', 'aimeos@aimeos.org', 'aimeos', '7859c656116693401d9b0d955ce41762', 'Contains bugfixes and improvements for the administration interface and the HTML client. A new "Quantity" service decorator for delivery costs by product quantities is also included', '', 17010001, 1, 0),
