(34368, 0, 'countrymanager', 1, '0.1.0', 0, 0, 'Typo3 Country Manager', 'Managing countries and languages was never an easy task with Typo3. Typo3 Country Manager aims to fix this.', 0, 0, 3, 1351724820, 'a:1:{s:7:"depends";a:4:{s:7:"extbase";s:3:"1.3";s:5:"fluid";s:3:"1.3";s:5:"typo3";s:9:"4.7-0.0.0";s:18:"static_info_tables";s:5:"2.3.0";}}', 'Noel Bossart', 'n.company at me dot com', 'noelboss', '5d414d5043ad47156ae6f05ba1bb184c', 'Managing countries and languages was never an easy task with Typo3. Typo3 Country Manager aims to fix this. The extension adds information to sys_language records about the country. This makes it possible to have a single page tree with the flexibility to', 'www.noelboss.ch', 1000, 1, 0),
(34369, 0, 'rrzk_htmlimport', 1, '0.1.0', 0, 0, 'Import URL', 'Die Extension gibt einem Redakteur die Mglichkeit anhand von Parametern von einer Quellwebseite auf \neine andere verlinkte Webseite zuzugreifen. Die Quellwebseite (Default URL) als auch das Template \n(Template URL) fr die verlinkte Seite sollen ber das Formular im Backend eingegeben werden. \nDie in Rules angegebenen Parameter werden in dem Template URL ersetzt und die entsprechende \nWebseite im Browser angezeigt.', 0, 0, 3, 1351847748, 'a:0:{}', 'RRZK Uni Kln', 'typo3master@uni-koeln.de', 'grat', 'edd0930b3225a0a97d40a1cc030325af', 'First published version!', '', 1000, 0, 0),
(34370, 0, 'rrzk_htmlimport', 1, '0.1.1', 0, 0, 'Import URL', 'Die Extension gibt einem Redakteur die Mglichkeit anhand von Parametern von einer Quellwebseite auf \neine andere verlinkte Webseite zuzugreifen. Die Quellwebseite (Default URL) als auch das Template \n(Template URL) fr die verlinkte Seite sollen ber das Formular im Backend eingegeben werden. \nDie in Rules angegebenen Parameter werden in dem Template URL ersetzt und die entsprechende \nWebseite im Browser angezeigt.', 0, 0, 3, 1363078416, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:11:"4.5.0-4.7.0";}}', 'RRZK Uni Koeln', 'typo3master@uni-koeln.de', 'grat', '079a63ce8f004188ec12b9c1cd537b5b', '', '', 1001, 1, 0),
(34371, 0, 'sm_downloads', 1, '1.0.0', 0, 0, 'Simpel Downloadcenter', 'a very simpel download plugin. \nMaking Downloadlinks & Folders all by its own. Just upload, maybe add your styles.', 0, 0, 3, 1352031270, 'a:1:{s:7:"depends";a:3:{s:7:"extbase";s:3:"1.3";s:5:"fluid";s:3:"1.3";s:5:"typo3";s:9:"4.5-0.0.0";}}', 'Stefan Masztalerz', 'stefan.masztalerz@aoemedia.de', 'stefan.masztalerz', '02b4060c0be517bc03fa857cb0e16db3', 'Initial upload - quit a lot todo', 'AOEmedia', 1000000, 0, 0),
(34372, 0, 'sm_downloads', 1, '1.0.1', 0, 0, 'Simple Downloadcenter', 'a very simple download plugin.\nMaking Downloadlinks & Folders all by its own. Just upload, maybe add your styles.', 0, 0, 3, 1352159946, 'a:1:{s:7:"depends";a:3:{s:7:"extbase";s:3:"1.3";s:5:"fluid";s:3:"1.3";s:5:"typo3";s:9:"4.5-0.0.0";}}', 'Stefan Masztalerz', 'stefan.masztalerz@aoemedia.de', 'stefan.masztalerz', '53875182990c5f501867f2fc37c2f7f8', 'fixed spelling & added labels', 'AOEmedia', 1000001, 1, 0),
(34373, 0, 'extbase_realurl', 1, '0.9.0', 0, 0, 'Extbase Realurl: Automatic Realurl configuration f', 'Creates automatic Realurl rules for all plugins used on the TYPO3 site. Enables extension developers to use class and method annotations to modify the rules that are generated. Supports all versions of Extbase.', 1, 0, 4, 1352039412, 'a:1:{s:7:"depends";a:4:{s:5:"typo3";s:9:"4.5-0.0.0";s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:7:"realurl";s:12:"1.12.3-0.0.0";}}', 'Claus Due', 'claus@wildside.dk', 'fluidtypo3', '4cd6366a2e1d10b015043234d95e50ba', 'First TER version. Works like a charm on basic setups, but be careful if you have a huge site with a lot of Extbase plugins being used. We are still only at beta quality here ;) Docs: https://github.com/NamelessCoder/extbase_realurl', 'Wildside A/S', 9000, 0, 0),
(34374, 0, 'extbase_realurl', 1, '0.9.1', 0, 0, 'Extbase Realurl: Automatic Realurl configuration f', 'Creates automatic Realurl rules for all plugins used on the TYPO3 site. Enables extension developers to use class and method annotations to modify the rules that are generated. Supports all versions of Extbase.', 1, 0, 4, 1352043529, 'a:1:{s:7:"depends";a:4:{s:5:"typo3";s:9:"4.5-0.0.0";s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:7:"realurl";s:12:"1.12.3-0.0.0";}}', 'Claus Due', 'claus@wildside.dk', 'fluidtypo3', '4caaf247c2e18149c8999dec53345227', 'Removed reference to class from Flux.', 'Wildside A/S', 9001, 0, 0),
(34375, 0, 'extbase_realurl', 1, '0.9.2', 0, 0, 'Extbase Realurl: Automatic Realurl configuration f', 'Creates automatic Realurl rules for all plugins used on the TYPO3 site. Enables extension developers to use class and method annotations to modify the rules that are generated. Supports all versions of Extbase.', 1, 0, 4, 1361571913, 'a:1:{s:7:"depends";a:4:{s:5:"typo3";s:9:"4.5-0.0.0";s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:7:"realurl";s:12:"1.12.3-0.0.0";}}', 'Claus Due', 'claus@wildside.dk', 'fluidtypo3', '16432966b7a838d8d73897b44ef56238', 'Added passthrough and integer support, added fallback to passthrough mode, improved compatibility with 6.0 core.', 'Wildside A/S', 9002, 0, 0),
(34376, 0, 'extbase_realurl', 1, '0.9.3', 0, 0, 'Extbase URL handling', 'Makes it possible to call Extbase controllers directly using nice urls - if Realurl is installed, also enables automatic rules for plugins in pages', 1, 0, 4, 1388321965, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:12:"6.0.0-6.2.99";s:3:"cms";s:0:"";s:7:"extbase";s:0:"";}}', 'Claus Due', 'claus@namelesscoder.net', 'fluidtypo3', '0417550ee3e9fe49e1b1cebdd7a18d33', 'Changelog: https://github.com/FluidTYPO3/extbase_realurl/commits/0.9.3', '', 9003, 0, 0),
