(34378, 0, 'fs_code_snippet', 1, '1.6.1', 0, 0, 'Code Snippet CE', 'A content element to render code snippet of various programming languages.', 2, 0, 2, 1477518878, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:12:"7.6.0-8.4.99";s:20:"fluid_styled_content";s:0:"";s:8:"t3editor";s:0:"";}}', 'Daniel Goerz', 'ervaude@gmail.com', 'ervaude', 'd32e90067febc1b1baa8c7b324f000ef', 'New Feature: All supported languages can be activated now in the extension configuration in the extension manager.\r\n\r\nCompatibility with TYPO3 8.4', '', 1006001, 0, 0),
