(34385, 0, 'fs_code_snippet', 1, '1.5.0', 0, 0, 'Code Snippet CE', 'A content element to render code snippet of various programming languages.', 2, 0, 2, 1473510473, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"7.6.0-8.3.99";s:20:"fluid_styled_content";s:0:"";}}', 'Daniel Goerz', 'ervaude@gmail.com', 'ervaude', 'd8417651eb9173f480d46fef6c151c7c', '  [FEATURE] Line numbers are now configurable\r\n  [TASK] Appearance tab is now visible in TCA\r\n  [TASK] prism.js updated to 1.5.1\r\n  [TASK] Compatibility with TYPO3 7 LTS and 8.3\r\n  [TASK] Improved Documentation', '', 1005000, 0, 0),
