(34413, 0, 'drcpageteaser', 1, '1.1.0', 0, 0, 'DRC Page Teaser With Isotopes', 'DRC Page Teaser is a responsive and most effective way to display the page teaser view using isotopes', 0, 0, 3, 1477566712, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"7.6.0-7.6.99";}}', 'DRCSystems', 'info@drcsystems.com', 'drc_systems', '44a7e54fdb588bc45e5e97ac3b7a133e', 'DRC Page Teaser is a responsive and most effective way to display the page teaser view using isotopes.Its very simple and easy you configure.Based on Extbase and Fluid Template Engine.', '', 1001000, 1, 0),
(34414, 0, 'vhs', 1, '1.0.0', 0, 0, 'VHS: Fluid ViewHelpers', 'A collection of ViewHelpers to perform rendering tasks which are not natively supported by Fluid - for example: advanced formatters, math calculators, specialized conditions and Iterator/Array calculators and processors', 2, 0, 4, 1352073108, 'a:1:{s:7:"depends";a:4:{s:5:"typo3";s:9:"4.5-0.0.0";s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'fluidtypo3', '4363358b5cb04244ca31c33ec5df3d5b', 'First version. Includes all general-purpose ViewHelpers from FED and some new ones. No dependencies except Extbase and Fluid. Docs: https://github.com/NamelessCoder/vhs', 'Wildside A/S', 1000000, 0, 0),
(34415, 0, 'vhs', 1, '1.0.1', 0, 0, 'VHS: Fluid ViewHelpers', 'A collection of ViewHelpers to perform rendering tasks which are not natively supported by Fluid - for example: advanced formatters, math calculators, specialized conditions and Iterator/Array calculators and processors', 2, 0, 4, 1352076466, 'a:1:{s:7:"depends";a:4:{s:5:"typo3";s:9:"4.5-0.0.0";s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'fluidtypo3', '3f7ab2681f0981886e416e56391c2704', 'Fixes for some refactoring-related class naming issues. Full ViewHelper reference can be found at http://fedext.net/vhs-viewhelpers/', 'Wildside A/S', 1000001, 0, 0),
(34416, 0, 'vhs', 1, '1.1.0', 0, 0, 'VHS: Fluid ViewHelpers', 'A collection of ViewHelpers to perform rendering tasks which are not natively supported by Fluid - for example: advanced formatters, math calculators, specialized conditions and Iterator/Array calculators and processors', 2, 0, 4, 1353267961, 'a:1:{s:7:"depends";a:4:{s:5:"typo3";s:9:"4.5-0.0.0";s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'fluidtypo3', '12f7a2c978d911195050c9ec977dde1c', 'New ViewHelpers: Render / Template, Inline, Cache, Request. Extension / Icon. Condition / Browser, System, Extend - and a Condition ViewHelper that allows using extended expressions through Condition / Extend.', 'Wildside A/S', 1001000, 0, 0),
(34417, 0, 'vhs', 1, '1.2.0', 0, 0, 'VHS: Fluid ViewHelpers', 'A collection of ViewHelpers to perform rendering tasks which are not natively supported by Fluid - for example: advanced formatters, math calculators, specialized conditions and Iterator/Array calculators and processors', 2, 0, 4, 1353857320, 'a:1:{s:7:"depends";a:4:{s:5:"typo3";s:9:"4.5-0.0.0";s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'fluidtypo3', '81d43ca9eda59f999acacf4a0cdefb46', 'New ViewHelpers: Site / Url, Name; Iterator / Slice; Format / Substring; Math / Square, SquareRoot, Cube, CubicRoot, Minimum, Maximum; Once / Standard, Instance, Cookie, Session.', 'Wildside A/S', 1002000, 0, 0),
(34418, 0, 'vhs', 1, '1.3.0', 0, 0, 'VHS: Fluid ViewHelpers', 'A collection of ViewHelpers to perform rendering tasks which are not natively supported by Fluid - for example: advanced formatters, math calculators, specialized conditions and Iterator/Array calculators and processors', 2, 0, 4, 1354472527, 'a:1:{s:7:"depends";a:4:{s:5:"typo3";s:9:"4.5-0.0.0";s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'fluidtypo3', '554689c003d9825075957bd5535de4fa', 'Added: Random / String and Number, Format / Replace, Form / Required. New: Support for RAND and SHUFFLE ordering in Iterator / Sort ViewHelper.', 'Wildside A/S', 1003000, 0, 0),
(34419, 0, 'vhs', 1, '1.3.1', 0, 0, 'VHS: Fluid ViewHelpers', 'A collection of ViewHelpers to perform rendering tasks which are not natively supported by Fluid - for example: advanced formatters, math calculators, specialized conditions and Iterator/Array calculators and processors', 2, 0, 4, 1356663799, 'a:1:{s:7:"depends";a:4:{s:5:"typo3";s:9:"4.5-0.0.0";s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'fluidtypo3', '90fcfcc9a9221a9bdbdda3f49cc8e6c5', 'Minor update, required by up-and-coming EXT:dialog 2.0. Bugfix for menu localization and Var / Isset. Two new minor system variable ViewHelpers: System / Timestamp and System / DateTime. Finally, adds attribute "htmlentities" on Format / Markdown.', 'Wildside A/S', 1003001, 0, 0);
INSERT INTO `tx_extensionmanager_domain_model_extension` (`uid`, `pid`, `extension_key`, `repository`, `version`, `alldownloadcounter`, `downloadcounter`, `title`, `description`, `state`, `review_state`, `category`, `last_updated`, `serialized_dependencies`, `author_name`, `author_email`, `ownerusername`, `md5hash`, `update_comment`, `authorcompany`, `integer_version`, `current_version`, `lastreviewedversion`) VALUES
(34420, 0, 'vhs', 1, '1.3.2', 0, 0, 'VHS: Fluid ViewHelpers', 'A collection of ViewHelpers to perform rendering tasks which are not natively supported by Fluid - for example: advanced formatters, math calculators, specialized conditions and Iterator/Array calculators and processors', 2, 0, 4, 1356918366, 'a:1:{s:7:"depends";a:4:{s:5:"typo3";s:9:"4.5-0.0.0";s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'fluidtypo3', '15d5be8a6fd8615250baba72e3c06ad4', 'Bugfix for Page / BreadCrumb ViewHelper. Added ViewHelpers: Call (calls methods on object instances w/ arguments), Media / Files and Media / Extension to read lists of files and get the extension of a file, respectively.', 'Wildside A/S', 1003002, 0, 0),
(34421, 0, 'vhs', 1, '1.4.0', 0, 0, 'VHS: Fluid ViewHelpers', 'A collection of ViewHelpers to perform rendering tasks which are not natively supported by Fluid - for example: advanced formatters, math calculators, specialized conditions and Iterator/Array calculators and processors', 2, 0, 4, 1357691821, 'a:1:{s:7:"depends";a:4:{s:5:"typo3";s:9:"4.5-0.0.0";s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'fluidtypo3', '729b9563e4d2d95ca809b5f7c09f648a', 'New ViewHelpers: Iterator / Merge, Values, Pop and Shift; Media / Size, Mimetype, Width and Height and enabled support for "useShortcutData" on both menu-type ViewHelpers.', 'Wildside A/S', 1004000, 0, 0),
(34422, 0, 'vhs', 1, '1.5.0', 0, 0, 'VHS: Fluid ViewHelpers', 'A collection of ViewHelpers to perform rendering tasks which are not natively supported by Fluid - for example: advanced formatters, math calculators, specialized conditions and Iterator/Array calculators and processors', 2, 0, 4, 1359928311, 'a:1:{s:7:"depends";a:4:{s:5:"typo3";s:9:"4.5-0.0.0";s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'fluidtypo3', 'ac056ef71f3ef867beca97b805583c9b', 'New: Asset ViewHelpers, Menu / List and Directory, Form / HasValidator, Media / Spotify, Vimeo, Youtube, Format / Json / Encode and Decode (DomainObject and DateTime support), Iterator / Reverse. Read more about Assets on fedext.net.', 'Wildside A/S', 1005000, 0, 0),
(34423, 0, 'vhs', 1, '1.6.0', 0, 0, 'VHS: Fluid ViewHelpers', 'A collection of ViewHelpers to perform rendering tasks which are not natively supported by Fluid - for example: advanced formatters, math calculators, specialized conditions and Iterator/Array calculators and processors', 2, 0, 4, 1361744419, 'a:1:{s:7:"depends";a:4:{s:5:"typo3";s:9:"4.5-0.0.0";s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'fluidtypo3', '735a07818a57f3e4099fe374a68b4740', 'New Asset sub-feature: CompilableAsset (to manually compile your custom Asset types). New: Iterator / Extract VH, Try VH (Exception handler), Mobile client detection VH. New divider and doktypes attributes on all Menus.', 'Wildside A/S', 1006000, 0, 0),
(34424, 0, 'vhs', 1, '1.7.0', 0, 0, 'VHS: Fluid ViewHelpers', 'A collection of ViewHelpers to perform rendering tasks which are not natively supported by Fluid - for example: advanced formatters, math calculators, specialized conditions and Iterator/Array calculators and processors', 2, 0, 4, 1368917333, 'a:1:{s:7:"depends";a:4:{s:5:"typo3";s:10:"4.5-6.2.99";s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'fluidtypo3', '3b1327bc19d61d5cbc0a69ad77046acc', 'New: Uri / Request, Page / Menu / Sub, Browse, List, Var / Convert and a Simple but effective translation ViewHelper (v:l). Added: merge and cache files referenced by CSS, multi-level menu fixes And many other important bugfixes - much more than can fit h', 'Wildside A/S', 1007000, 0, 0),
(34425, 0, 'vhs', 1, '1.8.0', 0, 0, 'VHS: Fluid ViewHelpers', 'A collection of ViewHelpers to perform rendering tasks which are not natively supported by Fluid - for example: advanced formatters, math calculators, specialized conditions and Iterator/Array calculators and processors', 2, 0, 4, 1371414025, 'a:1:{s:7:"depends";a:4:{s:5:"typo3";s:10:"4.5-6.1.99";s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'fluidtypo3', '9f59d291cadb5b16ff8de6f7be48d81f', 'Url / Decode and Encode, DateRange, Render / Ascii, Iterator / Random, Page / Info, a new suite of condition ViewHelpers and a special deferred menu renderer (see docs). And finally: VHS Assets can be included from PHP and TypoScript as well as Fluid ;)', 'Wildside A/S', 1008000, 0, 0),
(34426, 0, 'vhs', 1, '1.8.1', 0, 0, 'VHS: Fluid ViewHelpers', 'A collection of ViewHelpers to perform rendering tasks which are not natively supported by Fluid - for example: advanced formatters, math calculators, specialized conditions and Iterator/Array calculators and processors', 2, 0, 4, 1372615184, 'a:1:{s:7:"depends";a:4:{s:5:"typo3";s:10:"4.5-6.1.99";s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'fluidtypo3', 'e68ad444ed21d5b33b36b2952b1f2797', 'Primarily a bugfix release (for Assets mainly). Also added: Page / Info and Link, support for the "as" argument on all Menus, non-wrapping (fx A directly inside NAV tags) mode for Menus and an extension configuration toggle to disable Asset caching. The', 'Wildside A/S', 1008001, 0, 0),
(34427, 0, 'vhs', 1, '1.8.2', 0, 0, 'VHS: Fluid ViewHelpers', 'A collection of ViewHelpers to perform rendering tasks which are not natively supported by Fluid - for example: advanced formatters, math calculators, specialized conditions and Iterator/Array calculators and processors', 2, 0, 4, 1375884312, 'a:1:{s:7:"depends";a:4:{s:5:"typo3";s:10:"4.5-6.1.99";s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'fluidtypo3', '66403fd7bfccf7a472c93713adf75c81', 'New: Page / Menu can exclude pages and adds special first/last classes to first/last page link. If / Form / HasValidator no longer requires a name (renders true if property has any Validator). And many bug fixes and small improvements.', 'Wildside A/S', 1008002, 0, 0),
(34428, 0, 'vhs', 1, '1.8.3', 0, 0, 'VHS: Fluid ViewHelpers', 'A collection of ViewHelpers to perform rendering tasks which are not natively supported by Fluid - for example: advanced formatters, math calculators, specialized conditions and Iterator/Array calculators and processors', 2, 0, 4, 1385065532, 'a:1:{s:7:"depends";a:4:{s:5:"typo3";s:12:"4.5.0-6.1.99";s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'fluidtypo3', 'd344e6de19bb0ce2664a1195df39b3e7', 'Changelog can be found at https://github.com/FluidTYPO3/vhs/commits/1.8.3', 'Wildside A/S', 1008003, 0, 0),
(34429, 0, 'vhs', 1, '1.8.4', 0, 0, 'VHS: Fluid ViewHelpers', 'A collection of ViewHelpers to perform rendering tasks which are not natively supported by Fluid - for example: advanced formatters, math calculators, specialized conditions and Iterator/Array calculators and processors', 2, 0, 4, 1387118663, 'a:1:{s:7:"depends";a:4:{s:5:"typo3";s:12:"4.5.0-6.2.99";s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'fluidtypo3', '7e03e4a0822c9d2ff2bed5055dbe52ba', 'Change log: https://github.com/FluidTYPO3/vhs/commits/1.8.4', 'Wildside A/S', 1008004, 0, 0),
(34430, 0, 'vhs', 1, '1.8.5', 0, 0, 'VHS: Fluid ViewHelpers', 'A collection of ViewHelpers to perform rendering tasks which are not natively supported by Fluid - for example: advanced formatters, math calculators, specialized conditions and Iterator/Array calculators and processors', 2, 0, 4, 1395672773, 'a:1:{s:7:"depends";a:4:{s:5:"typo3";s:12:"4.5.0-6.2.99";s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'FluidTYPO3 Team', 'claus@namelesscoder.net', 'fluidtypo3', '1b84159f6b355e6e8bfb3fae5b91854b', 'Various fixes, mainly small bugs.', '', 1008005, 0, 0),
(34431, 0, 'vhs', 1, '1.9.0', 0, 0, 'VHS: Fluid ViewHelpers', 'A collection of ViewHelpers to perform rendering tasks which are not natively supported by Fluid - for example: advanced formatters, math calculators, specialized conditions and Iterator/Array calculators and processors', 2, 0, 4, 1401663279, 'a:1:{s:7:"depends";a:4:{s:5:"typo3";s:12:"6.0.0-6.2.99";s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'FluidTYPO3 Team', 'claus@namelesscoder.net', 'fluidtypo3', 'a52d8375f64255657ace129a518991c9', 'No more TYPO3 4.x support. Last sub version iteration before switching to namespaces. Changelog: https://github.com/FluidTYPO3/vhs/commits/staging', '', 1009000, 0, 0),
