(34492, 0, 'responsiveslides', 1, '0.0.4', 0, 0, 'ResponsiveSlides for Typo3', 'An implementation of the responsive slideshow http://responsive-slides.viljamis.com to TYPO3. Responsive slides is a tiny jQuery plugin that creates a responsive slider using list items inside ul. It works with wide range of browsers including all IE versions from IE6 and up. It also adds css max-width support for IE6 and other browsers that dont natively support it. ', 0, 0, 3, 1352790473, 'a:0:{}', 'Rikard Birath', 'akora@hotmail.com', 'hundra', '481c48a43398615ba807970c91fe478d', 'Code cleaning  added description', '', 4, 1, 0),
