(34637, 0, 'th_feedback', 1, '0.0.1', 0, 0, 'TYPOHOSTING.AT Feedback', 'When i saw this feedback form the first time on stackoverflow.com, i knew thats what i wanted for my\n web projects. so why not make one for typo. i got it up and running and even extended it with a cool "yes, but.." comment field.', 0, 0, 3, 1353329787, 'a:0:{}', 'Akin Ajewole', 'info@typohosting.at', 'typohostingat', '02af0f3b8678817f7d43e7ea52ff534f', '', '', 1, 0, 0),
(34638, 0, 'th_feedback', 1, '0.0.2', 0, 0, 'TYPOHOSTING.AT Feedback', 'When i saw this feedback form the first time on stackoverflow.com, i knew thats what i wanted for my\n web projects. so why not make one for typo. i got it up and running and even extended it with a cool "yes, but.." comment field.', 0, 0, 3, 1355070341, 'a:0:{}', 'Akin Ajewole', 'info@typohosting.at', 'typohostingat', 'a0858c67d6899cad6c74f62b2c6a1690', 'PHP: fixed db connections\r\nDate-time: fixed date-time selection in statistics Ajax: fixed ajax through the use of eID', '', 2, 0, 0);
INSERT INTO `tx_extensionmanager_domain_model_extension` (`uid`, `pid`, `extension_key`, `repository`, `version`, `alldownloadcounter`, `downloadcounter`, `title`, `description`, `state`, `review_state`, `category`, `last_updated`, `serialized_dependencies`, `author_name`, `author_email`, `ownerusername`, `md5hash`, `update_comment`, `authorcompany`, `integer_version`, `current_version`, `lastreviewedversion`) VALUES
(34639, 0, 'th_feedback', 1, '0.0.3', 0, 0, 'TYPOHOSTING.AT Feedback', 'When i saw this feedback form the first time on stackoverflow.com, i knew thats what i wanted for my\n web projects. so why not make one for typo. i got it up and running and even extended it with a cool "yes, but.." comment field.', 0, 0, 3, 1355147391, 'a:0:{}', 'Akin Ajewole', 'info@typohosting.at', 'typohostingat', 'ba5cf7a05b710fc9d2568951852aaf10', 'Ajax: fixed embarrassing absolute path bug (now it runs just fine)', '', 3, 1, 0),
(34640, 0, 'fbapp', 1, '1.0.0', 0, 0, 'TYPO3 Facebook Apps', 'Adds a new tab "Facebook Apps" to your page settings. Here, you can decide whether the page should be fan-gated and which tt_content should appear as fan-gate fallback. Or you can make the page accessible only within Facebook and forbid external access. This rather self-explanatory plugin should help you configuring a page as a Facebook app. More features coming soon.', 2, 0, 3, 1353403734, 'a:0:{}', 'Felix Kiesewetter', 'info@felixkiesewetter.de', 'felixkiesewetter', '5698c7fdbca0b921521071f351ad4b69', '', '', 1000000, 0, 0),
(34641, 0, 'fbapp', 1, '1.0.1', 0, 0, 'TYPO3 Facebook App', '', 2, 0, 3, 1385719339, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:3:"php";s:12:"5.0.0-5.3.99";s:5:"typo3";s:12:"4.3.0-6.2.99";}}', 'Felix Kiesewetter', 'info@felixkiesewetter.de', 'felixkiesewetter', 'cde38d4306c780cde4353e39d3de6cb7', 'Some bugfixes and minor changes in usability', '', 1000001, 0, 0),
(34642, 0, 'fbapp', 1, '1.1.0', 0, 0, 'TYPO3 Facebook App', '', 2, 0, 3, 1385734123, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:3:"php";s:12:"5.0.0-5.3.99";s:5:"typo3";s:12:"4.3.0-6.2.99";}}', 'Felix Kiesewetter', 'info@felixkiesewetter.de', 'felixkiesewetter', '9125a63553ace775b6db83d09232c83a', 'Rewritten Facebook authentification process and user-like process from scratch with the official Facebook PHP SDK.', '', 1001000, 0, 0),
(34643, 0, 'fbapp', 1, '1.2.0', 0, 0, 'TYPO3 Facebook App (DEPRECATED)', 'ATTENTION!!! As of November 2014, Facebook does not allow any more like-enforcing tools such as a fan-gate! Thus, this extension has become deprecated. In the future (as of version 2.0.0) it will only include Facebooks JS and PHP API for you to work with and to help you authenticate your FB apps. Sorry, guys!', 2, 0, 3, 1418030854, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:3:"php";s:12:"5.0.0-5.3.99";s:5:"typo3";s:12:"4.3.0-6.2.99";}}', 'Felix Kiesewetter', 'info@felixkiesewetter.de', 'felixkiesewetter', '7f701eb204029334d754b52347f812d6', 'ATTENTION! Facebook does not allow fan-gates anymore. This extension is useless for now ;-)', '', 1002000, 1, 0),
(34644, 0, 'adx_less', 1, '1.0.0', 0, 0, 'ad: LESS', 'Contains a server- and client-side LESS compiler (http://leafo.net/lessphp/, http://lesscss.org). Supports a new cObject "LESS", a hook for t3lib_pagerenderer witch compiles LESS files for "includeCSS", hooks for rtehtmlarea for the property "RTE.default.contentCSS" and tinymce_rte for the property "RTE.default.init.content_css" and a ViewHelper for Fluid. Furthermore includes the Twitter Bootstrap grid system. Only the grid system and nothing more ;)', 2, 0, 3, 1353406572, 'a:0:{}', 'Arno Dudek', 'webmaster@adgrafik.at', 'adgrafik', '170484fd90fe4f492213ecf8c4a64c2d', 'Initial release', 'ad:grafik', 1000000, 0, 0),
(34645, 0, 'adx_less', 1, '1.0.1', 0, 0, 'ad: LESS', 'Contains a server- and client-side LESS compiler (http://leafo.net/lessphp/, http://lesscss.org). Supports a new cObject "LESS", a hook for t3lib_pagerenderer witch compiles LESS files for "includeCSS", hooks for rtehtmlarea for the property "RTE.default.contentCSS" and tinymce_rte for the property "RTE.default.init.content_css" and a ViewHelper for Fluid. Furthermore includes the Twitter Bootstrap grid system. Only the grid system and nothing more ;)', 2, 0, 3, 1353592546, 'a:0:{}', 'Arno Dudek', 'webmaster@adgrafik.at', 'adgrafik', '48d5805f231ad823610fb3848e5699d2', 'Bugfix release.', 'ad:grafik', 1000001, 0, 0),
(34646, 0, 'adx_less', 1, '1.0.2', 0, 0, 'ad: LESS', 'Contains a server- and client-side LESS compiler (http://leafo.net/lessphp/, http://lesscss.org). Supports a new cObject "LESS", a hook for t3lib_pagerenderer witch compiles LESS files for "includeCSS", hooks for rtehtmlarea for the property "RTE.default.contentCSS" and tinymce_rte for the property "RTE.default.init.content_css" and a ViewHelper for Fluid. Furthermore includes the Twitter Bootstrap grid system. Only the grid system and nothing more ;)', 2, 0, 3, 1380544107, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"4.6.0-6.1.99";}}', 'Arno Dudek', 'webmaster@adgrafik.at', 'adgrafik', 'e994fd4bd4fb1acc5f8025a26e4d6b71', 'Bugfix release and fit for TYPO3 6.0.', 'ad:grafik', 1000002, 0, 0),
