(34691, 0, 'indexedsearch_rendered_ttnews', 1, '2.1.6', 0, 0, 'Render news content for IndexedSearch Crawler tt_n', 'Renders the content-field for news before indexing it. Useful for f.e. rgnewsce.', 2, 0, 4, 1370978207, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"4.5.0-6.1.99";s:28:"indexedsearch_ttnews_crawler";s:0:"";}}', 'Simon Schick', 'simonsimcity@gmail.com', 'simonsimcity', '9b893464f5eb5956ceeb53773b97d1c5', 'Prevent all kind of image-rendering (better work-around introduced in 2.1.3)', '', 2001006, 0, 0),
