(34730, 0, 'uncache', 1, '1.0.0', 0, 0, 'Uncache: Caches? What do you mean, caches...?', 'You know caches. You hate them while developing - so this extension prevents them all from working.', 2, 0, 4, 1354670988, 'a:1:{s:7:"depends";a:1:{s:4:"core";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'fluidtypo3', '31dbbdc924fe8ae7fc632802040e171f', 'Initial stable TER version. Do you love developing but hate caches while you do? Then youll love this. 6.0 only - sorry.', 'Wildside A/S', 1000000, 0, 0),
(34731, 0, 'uncache', 1, '1.0.1', 0, 0, 'Uncache: Caches? What do you mean, caches...?', 'You know caches. You hate them while developing - so this extension prevents them all from working.', 2, 0, 4, 1376253190, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.0.0-6.1.99";}}', 'Claus Due', 'claus@wildside.dk', 'fluidtypo3', '4ce6151b801cdcb0fe61461bf3c9bc01', 'Fixed TYPO3 core version dependency entry, added Travis build script. No changes to code.', 'Wildside A/S', 1000001, 0, 0);
