(34732, 0, 'uncache', 1, '1.1.0', 0, 0, 'Uncache: Caching Framework Crippler', 'You know caches. You hate them while developing - when installed, this extension prevents them all from working. NOT FOR PRODUCTION USE!', 2, 0, 4, 1396486250, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.0.0-6.2.99";}}', 'FluidTYPO3 Team', 'claus@namelesscoder.net', 'fluidtypo3', '0888a85e1943fbc230daedba4a7a2566', '6.2 compatibility, namespace fix. Make sure your caches are properly cleaned after update. Oh, wait... you dont have any caches...', '', 1001000, 1, 0),
(34733, 0, 'view', 1, '1.0.0', 0, 0, 'View: Extended Fluid Views', 'Extends the built-in Fluid Views with smart overlay capabilities', 2, 0, 4, 1354671340, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'fluidtypo3', '0966c688de1d65a84c7810e4d887bd22', 'Initial TER release. Extends every Fluid TemplateView with support for overlay template path sets, without modifying any code. See: https://github.com/NamelessCoder/view - 6.0 only, sorry!', 'Wildside A/S', 1000000, 0, 0),
(34734, 0, 'view', 1, '1.1.0', 0, 0, 'View: Extended Fluid Views', 'Extends the built-in Fluid Views with smart overlay capabilities', 2, 0, 4, 1355045833, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'fluidtypo3', '3efbb35075f3267eda444d793b6d58ac', 'Now compatible with 4.5, 4.6 and 4.7 as well as 6.0.', 'Wildside A/S', 1001000, 0, 0),
(34735, 0, 'view', 1, '1.1.1', 0, 0, 'View: Extended Fluid Views', 'Extends the built-in Fluid Views with smart overlay capabilities', 2, 0, 4, 1357690205, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'fluidtypo3', '0a2659fbea85683e106a08cad0c9a279', 'Bugfix only - fixes an issue with resolving paths on 4.x branches and corrects supported TYPO3 versions in ext_emconf.php.', 'Wildside A/S', 1001001, 0, 0),
(34736, 0, 'view', 1, '1.2.0', 0, 0, 'View: Extended Fluid Views', 'Extends the built-in Fluid Views with smart overlay capabilities', 2, 0, 4, 1363559806, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'fluidtypo3', 'cbec3ad12b29f02ab89c80f0e52c5d2b', 'New: set argument values of ViewHelpers through TypoScript, by class name of ViewHelper. Define as overrides or substitute default values.', 'Wildside A/S', 1002000, 0, 0),
(34737, 0, 'view', 1, '1.2.1', 0, 0, 'View: Extended Fluid Views', 'Extends the built-in Fluid Views with smart overlay capabilities', 2, 0, 4, 1368960480, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'fluidtypo3', '7602f308165654c82c032c73007044ff', 'Bugfixes: template paths, order of path detection, conversion of arguments. And a small cleanup to improve performance ever so slightly.', 'Wildside A/S', 1002001, 0, 0),
(34738, 0, 'view', 1, '1.2.2', 0, 0, 'View: Extended Fluid Views', 'Extends the built-in Fluid Views with smart overlay capabilities', 2, 0, 4, 1386181356, 'a:1:{s:7:"depends";a:4:{s:5:"typo3";s:12:"4.5.0-6.1.99";s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Claus Due', 'claus@wildside.dk', 'fluidtypo3', 'f9e1b76676782acf67732b82b9fb1d53', 'Maintenance release. Keep it simple.', 'Wildside A/S', 1002002, 0, 0),
