(34800, 0, 'tinyaccordion', 1, '1.0.0', 0, 0, 'JavaScript Accordion based on TinyAccordion', 'A very easy to use extension to display tt_content or tt_news elements as an Accordion.', 2, 0, 3, 1377016777, 'a:1:{s:7:"depends";a:3:{s:7:"extbase";s:3:"1.3";s:5:"fluid";s:3:"1.3";s:5:"typo3";s:13:"4.5.00-6.2.99";}}', 'Kurt Gusbeth', 'info@quizpalme.de', 'bihor', 'c6dc520cc6e6c5df14be699b7ce093f8', 'Extbase-version. Read the manual before you update!', '', 1000000, 0, 0),
(34801, 0, 'tinyaccordion', 1, '1.1.0', 0, 0, 'JavaScript Accordion based on TinyAccordion', 'An easy to use extension to display tt_content or tt_news elements as an Accordion.', 2, 0, 3, 1383841156, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:13:"4.5.00-6.2.99";}}', 'Kurt Gusbeth', 'info@quizpalme.de', 'bihor', 'e12d704aa62977c95797e0835bf8d6b7', 'CE-UID added to the UL-ID. You need to clean the cache after the update. Read the manual if you are updating from 0.1.0.\r\nCode cleaning.', '', 1001000, 0, 0),
(34802, 0, 'tinyaccordion', 1, '1.1.2', 0, 0, 'JavaScript Accordion based on TinyAccordion', 'An easy to use extension to display tt_content or tt_news elements as an Accordion.', 2, 0, 3, 1397157684, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:13:"4.5.00-6.2.99";}}', 'Kurt Gusbeth', 'info@quizpalme.de', 'bihor', '7188b4adb077a9f62d03e0e7e1b6fd2a', 'Content-titles are now hidden by default. Ready for Typo3 6.2.', '', 1001002, 0, 0),
(34803, 0, 'tinyaccordion', 1, '2.0.0', 0, 0, 'JavaScript Accordion based on TinyAccordion', 'An easy to use extension to display tt_content or tt_news elements as an Accordion.', 2, 0, 3, 1400048703, 'a:1:{s:7:"depends";a:3:{s:7:"extbase";s:3:"1.3";s:5:"fluid";s:3:"1.3";s:5:"typo3";s:13:"4.5.00-6.2.99";}}', 'Kurt Gusbeth', 'info@quizpalme.de', 'bihor', 'b81776ccaefb20bdd4286e6240709c37', 'FlexForms and templates extended. Language added. Maybe you need to save your plugin-settings again.', '', 2000000, 0, 0),
(34804, 0, 'tinyaccordion', 1, '2.1.1', 0, 0, 'JavaScript Accordion based on TinyAccordion', 'An easy to use extension to display tt_content or tt_news elements as an Accordion.', 2, 0, 3, 1420886657, 'a:1:{s:7:"depends";a:3:{s:7:"extbase";s:3:"1.3";s:5:"fluid";s:3:"1.3";s:5:"typo3";s:13:"4.5.00-6.2.99";}}', 'Kurt Gusbeth', 'info@quizpalme.de', 'bihor', '7a96924daa213d806c019cf76a6ee706', 'The extension can use now the old extension key (version 0.1.0) too.', '', 2001001, 0, 0),
(34805, 0, 'tinyaccordion', 1, '2.2.0', 0, 0, 'JavaScript Accordion based on TinyAccordion', 'An easy to use extension to display tt_content, tt_news or Camaliga elements as an Accordion.', 2, 0, 3, 1426934428, 'a:1:{s:7:"depends";a:3:{s:7:"extbase";s:3:"1.3";s:5:"fluid";s:3:"1.3";s:5:"typo3";s:13:"4.5.00-6.2.99";}}', 'Kurt Gusbeth', 'info@quizpalme.de', 'bihor', 'bfdd9bae16f88474d53414140a05b55d', 'New documentation format.\r\nThe UI Accordion template can be selected directly without moving the file to fileadmin.\r\nCamaliga-elements can be used now too.', '', 2002000, 0, 0),
(34806, 0, 'tinyaccordion', 1, '2.2.1', 0, 0, 'JavaScript Accordion based on TinyAccordion', 'An easy to use extension to display tt_content, tt_news or Camaliga elements as an Accordion.', 2, 0, 3, 1452758204, 'a:1:{s:7:"depends";a:3:{s:7:"extbase";s:3:"1.3";s:5:"fluid";s:3:"1.3";s:5:"typo3";s:13:"4.5.00-7.6.99";}}', 'Kurt Gusbeth', 'info@quizpalme.de', 'bihor', 'c93fb038a3f3ac67ed57e31786c73950', 'HTML5 problem solved.\r\nWorks with TYPO3 7.6.', '', 2002001, 0, 0),
(34807, 0, 'tinyaccordion', 1, '3.0.0', 0, 0, 'JavaScript Accordion based on TinyAccordion', 'An easy to use extension to display tt_content, tt_news or Camaliga elements as an Accordion.', 2, 0, 3, 1453736411, 'a:1:{s:7:"depends";a:3:{s:7:"extbase";s:3:"1.3";s:5:"fluid";s:3:"1.3";s:5:"typo3";s:13:"6.2.00-7.6.99";}}', 'Kurt Gusbeth', 'info@quizpalme.de', 'bihor', '8461979eb6d45eff413afae47973b049', 'Now TYPO3 7 LTS compatible (you need to use another TypoScript in TYPO3 7; see manual).\r\nYou need to flush the general cache after updating!', '', 3000000, 0, 0),
