(34811, 0, 'tinyaccordion', 1, '4.0.0', 0, 0, 'JavaScript Accordion based on TinyAccordion.', 'An easy to use extension to display pages, tt_content, tt_news or Camaliga elements as an Accordion. Runs with TinyAccordion or jQuery UI-Accordion.', 2, 0, 3, 1493151137, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:13:"7.0.00-7.6.99";}}', 'Kurt Gusbeth', 'info@quizpalme.de', 'bihor', '22057c5bab9f68e8bdc584b0304783e9', 'Major clean up for TYPO3 7. Not yet tested with TYPO3 8.\r\nNew templates and FlexForms (for pages  tt_content).', '', 4000000, 1, 0),
(34812, 0, 'filedeletion', 1, '0.1.0', 0, 0, 'Remove files with no references', 'You can specify a file with a list of files which should be deleted.\nGo to "DB check - Database Relations" and copy the "files with no references at all" to a file\nand this extension will delete that files! Helps you to clean up your file system.', 2, 0, 1, 1356172426, 'a:0:{}', 'Kurt Gusbeth', 'info@myquizandpoll.de', 'abandoned_extensions', '2234cbbe787ee13dd2477ba50d0708d4', 'First upload.', '', 1000, 0, 0),
