(34950, 0, 'rs_lock', 1, '0.2.0', 0, 0, 'RS  Advanced Locking', 'Features TYPO3 with an advanced and rewritten locking. TYPO3 offers locking methods are: simple (is_file method), flock (filesystem locking attributes) and semaphore (System V IPC Key). These three drivers are rewritten into an adaptive driver api to boost performance and abstraction. There is also a new driver for MySQL Locking through an InnoDB table called sys_lock. Very extendable structure, even if this is an really really initial version. Try & Fail :-)', 0, 0, 2, 1358263972, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:9:"4.5-0.0.0";}}', 'Daniel Hrtgen', 'huertgen@rheinschafe.de', 'shaak', '49bc125879040349ce1d2bc27ff2ed73', 'Init alpha version.', 'Rheinschafe GmbH', 2000, 0, 0),
(34951, 0, 'rs_lock', 1, '1.0.0', 0, 0, 'RS  Advanced TYPO3 Locking', 'Features TYPO3 with an advanced and rewritten locking. TYPO3 offers locking methods are: simple (is_file method), flock (filesystem locking attributes) and semaphore (System V IPC Key). These three drivers are rewritten into an adaptive driver api to boost performance and abstraction. There is also a new driver for MySQL Locking through an InnoDB table called sys_lock. Very extendable structure, even if this is an really really initial version. Try & Fail :-)', 2, 0, 2, 1435656201, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"4.5.0-4.7.99";}}', 'Daniel Hrtgen', 'huertgen@rheinschafe.de', 'shaak', '93d63ed291e1b621a3be694355d95efc', 'First stable release', 'Rheinschafe GmbH', 1000000, 0, 0);
INSERT INTO `tx_extensionmanager_domain_model_extension` (`uid`, `pid`, `extension_key`, `repository`, `version`, `alldownloadcounter`, `downloadcounter`, `title`, `description`, `state`, `review_state`, `category`, `last_updated`, `serialized_dependencies`, `author_name`, `author_email`, `ownerusername`, `md5hash`, `update_comment`, `authorcompany`, `integer_version`, `current_version`, `lastreviewedversion`) VALUES
(34952, 0, 'rs_lock', 1, '1.0.1', 0, 0, 'RS  Advanced TYPO3 Locking', 'Features TYPO3 with an advanced and rewritten locking. TYPO3 offers locking methods are: simple (is_file method), flock (filesystem locking attributes) and semaphore (System V IPC Key). These three drivers are rewritten into an adaptive driver api to boost performance and abstraction. There is also a new driver for MySQL Locking through an InnoDB table called sys_lock. Very extendable structure, even if this is an really really initial version. Try & Fail :-)', 2, 0, 2, 1435656631, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"4.5.0-4.7.99";}}', 'Daniel Hrtgen', 'huertgen@rheinschafe.de', 'shaak', 'd1915eb2e5ece028c5439c5f6d932e6f', 'Bugfix release.\r\n\r\nFixes a mysql lock release issue while php shuts down.', 'Rheinschafe GmbH', 1000001, 1, 0),
