(34955, 0, 'indexedsearch_ttnews_crawler', 1, '1.1.1', 0, 0, 'IndexedSearch Crawler for tt_news', 'Adds a crawler for tt_news entries into the indexed_search configuration', 2, 0, 4, 1359553061, 'a:1:{s:7:"depends";a:3:{s:14:"indexed_search";s:0:"";s:7:"crawler";s:0:"";s:7:"tt_news";s:0:"";}}', 'Simon Schick', 'simonsimcity@gmail.com', 'simonsimcity', 'ae9eb1800f750d8d0071ddf68e434edf', 'Fixed that having use subcategories checked will cause an MySQL error for every news-entry\nhaving no categories. (Thanks again to Paavo Schmid)', '', 1001001, 0, 0),
