(34957, 0, 'indexedsearch_ttnews_crawler', 1, '1.1.3', 0, 0, 'IndexedSearch Crawler for tt_news', 'Adds a crawler for tt_news entries into the indexed_search configuration', 2, 0, 4, 1367506069, 'a:1:{s:7:"depends";a:4:{s:5:"typo3";s:12:"4.5.0-6.0.99";s:14:"indexed_search";s:0:"";s:7:"crawler";s:0:"";s:7:"tt_news";s:0:"";}}', 'Simon Schick', 'simonsimcity@gmail.com', 'simonsimcity', '3a4c66ca531fa13daaa142fa7a8ca3d1', 'Major performance increase by not re-generating the TypoScript on each call.', '', 1001003, 0, 0),
