(34998, 0, 'restrictfe', 1, '6.0.5', 0, 0, 'Restrict access for staging and prod instances', 'This extension blocks access to frontend and allows to show it only to some defined exceptions like if the request is from an authorized backend user, has specific IP, header, domain, language or GET/POST vars. Useful to protect your staging and production instances.', 2, 0, 2, 1489918395, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.2.0-8.6.99";}}', 'SourceBroker Team', 'office@sourcebroker.net', 't33k', '789f52e42ea6113f0abf76b50c6c9430', '[DOC] update docs and ext description', 'SourceBroker', 6000005, 0, 0),
