(35009, 0, 'webcon_ftptransfer', 1, '1.0.0', 0, 0, 'webconsulting FTP transfer', 'This extension allows you to create a scheduler task which is responsible for transfering files locally or to/from an FTP account. All configuration is done from within the task configuration form. Documentation in new TYPO3 documentation format "ReST" compiled at "doc/manual.pdf" or "doc/html/".', 0, 0, 4, 1358858860, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:11:"4.5.0-0.0.0";s:3:"php";s:11:"5.1.0-0.0.0";s:9:"scheduler";s:6:"1.1.0-";}}', 'Kraft Bernhard', 'kraft@web-consulting.at', 'dirnbauer', 'd576b30a7c9edb6897a934d994069e57', 'Initial release to TER.', '', 1000000, 1, 0),
(35010, 0, 'schedgmaps', 1, '2.0.0', 0, 0, 'Google Maps: Address cache', 'Adds a task for the scheduler, which checks all address-entries stored in tt_address, gets the according address coordinates and caches them into an extra added field. (needs TYPO3 4.3 or higher)', 1, 0, 4, 1358902983, 'a:0:{}', 'Dominic Simm', 'dominic.simm@sub.uni-goettingen.de', 'dsim', '94a0ad1a93ef6ef120c4520cd2b9c697', '2013-01-23 - 1.0.0 - Dominic Simm dominic.simm@sub.uni-goettingen.de\n solved dependency to class class.tx_nkwlib.php\n clean up and adding comments\n added short documentation\n renamed extension from dsschedgmaps to  schedgmaps because of ', 'Goettingen State and University Library, Germany http://sub.uni-goettingen,de', 2000000, 0, 0),
(35011, 0, 'schedgmaps', 1, '2.0.1', 0, 0, 'Google Maps: Address cache', 'Adds a new task to the scheduler, which checks all address-entries stored in tt_address, gets the according address coordinates and caches them into an extra added field. (needs TYPO3 4.3 or higher)', 1, 0, 4, 1358935299, 'a:1:{s:7:"depends";a:4:{s:9:"scheduler";s:11:"4.0.0-0.0.0";s:3:"php";s:11:"5.2.0-0.0.0";s:5:"typo3";s:15:"4.3.dev-4.99.99";s:10:"tt_address";s:11:"2.2.1-0.0.0";}}', 'Dominic Simm', 'dominic.simm@sub.uni-goettingen.de', 'dsim', '302348fdf042b148ca705f900b9c6048', 'Added new manual.sxw/pdf', 'Goettingen State and University Library, Germany http://sub.uni-goettingen.de', 2000001, 1, 0),
