(35143, 0, 't3events', 1, '0.16.2', 0, 0, 'Events', 'Manage events, show teasers, list and single views.', 1, 0, 3, 1429170089, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"6.2.0-7.1.99";s:18:"static_info_tables";s:12:"6.1.0-6.1.99";}}', 'Dirk Wenzel, Michael Kasten', 'wenzel@webfox01.de, kasten@webfox01.de', 'dw', 'bd42f79edee74164e7725f670ecf3f90', 'Bugfix release. t3events now works for TYPO3 version 6.2.0 - 7.1.99', 'Agentur Webfox', 16002, 0, 0),
(35144, 0, 't3events', 1, '0.30.0', 0, 0, 'Events', 'Manage events, show teasers, list and single views.', 1, 0, 3, 1481757255, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:13:"6.2.0-8.99.99";s:3:"php";s:11:"5.5.0-0.0.0";}}', 'Dirk Wenzel, Michael Kasten', 't3events@gmx.de, kasten@webfox01.de', 'dw', 'e76b1a4a08df14d627d15a34af66f1a3', 'Major changes - please see release notes: https://github.com/dwenzel/t3events/releases/tag/0.30.0', 'Agentur Webfox GmbH, Consulting Piezunka Schamoni - Information Technologies GmbH', 30000, 0, 0),
(35145, 0, 't3events', 1, '0.31.0', 0, 0, 'Events', 'Manage events, show teasers, list and single views.', 1, 0, 3, 1483634750, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:13:"6.2.0-8.99.99";s:3:"php";s:11:"5.5.0-0.0.0";s:10:"t3calendar";s:11:"0.1.1-0.0.0";}}', 'Dirk Wenzel, Michael Kasten', 't3events@gmx.de, kasten@webfox01.de', 'dw', 'a007778adfecc9a1b003bc2fc47f06b1', 'Breaking changes - please see release notes: https://github.com/dwenzel/t3events/releases/tag/0.31.0', 'Agentur Webfox GmbH, Consulting Piezunka Schamoni - Information Technologies GmbH', 31000, 0, 0),
(35146, 0, 't3events', 1, '0.31.1', 0, 0, 'Events', 'Manage events, show teasers, list and single views.', 1, 0, 3, 1489248740, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:13:"6.2.0-8.99.99";s:3:"php";s:11:"5.5.0-0.0.0";s:10:"t3calendar";s:11:"0.2.0-0.0.0";}}', 'Dirk Wenzel, Michael Kasten', 't3events@gmx.de, kasten@webfox01.de', 'dw', '99105ba9fafd9d67e59c6446af840b6a', 'This is a hotfix release for issue 52\r\nFatal error: missing class CalendarItemStorage (caused by wrong version of constraint of t3calendar).\r\nSee https://github.com/dwenzel/t3events/releases/tag/0.31.1 for details.', 'Agentur Webfox GmbH, Consulting Piezunka Schamoni - Information Technologies GmbH', 31001, 0, 0),
(35147, 0, 't3events', 1, '0.31.2', 0, 0, 'Events', 'Manage events, show teasers, list and single views.', 1, 0, 3, 1489697708, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:13:"6.2.0-8.99.99";s:3:"php";s:11:"5.5.0-0.0.0";s:10:"t3calendar";s:11:"0.2.0-0.0.0";}}', 'Dirk Wenzel, Michael Kasten', 't3events@gmx.de, kasten@webfox01.de', 'dw', 'cf354ec7f79d5af2d00719360bb99f7c', 'This is a hotfix release. If fixes an issue where the list view of events did not respect the sorting from plugin configuration. (Thanks for reporting and providing a fix to Marco Pfeiffer)', 'Agentur Webfox GmbH, Consulting Piezunka Schamoni - Information Technologies GmbH', 31002, 0, 0),
(35148, 0, 't3events', 1, '0.32.0', 0, 0, 'Events', 'Manage events, show teasers, list and single views.', 1, 0, 3, 1490629786, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:13:"6.2.0-8.99.99";s:3:"php";s:11:"5.5.0-0.0.0";s:10:"t3calendar";s:11:"0.3.0-0.0.0";}}', 'Dirk Wenzel, Michael Kasten', 't3events@gmx.de, kasten@webfox01.de', 'dw', '6785c882ae22b3bcced609ef652af128', 'This is a maintenance release which fixes several minor issues. Please see https://github.com/dwenzel/t3events/releases/tag/0.32.0 for details', 'Agentur Webfox GmbH, Consulting Piezunka Schamoni - Information Technologies GmbH', 32000, 0, 0),
(35149, 0, 't3events', 1, '0.33.0', 0, 0, 'Events', 'Manage events, show teasers, list and single views.', 1, 0, 3, 1493990373, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:13:"6.2.0-8.99.99";s:3:"php";s:11:"5.5.0-0.0.0";s:10:"t3calendar";s:11:"0.4.0-0.0.0";}}', 'Dirk Wenzel, Michael Kasten', 't3events@gmx.de, kasten@webfox01.de', 'dw', 'cb0995cd797ebf2585f6104afae536a1', 'Events now supports TYPO3 version 8.7. Future versions will not support TYPO3 6.x any more. See: https://github.com/dwenzel/t3events/releases/tag/0.33.0 for details.', 'Agentur Webfox GmbH, Consulting Piezunka Schamoni - Information Technologies GmbH', 33000, 0, 0),
