(35154, 0, 't3events', 1, '0.37.2', 0, 0, 'Events', 'Manage events, show teasers, list and single views.', 1, 0, 3, 1508960855, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:13:"7.6.0-8.99.99";s:10:"t3calendar";s:11:"0.4.0-0.0.0";}}', 'Dirk Wenzel, Michael Kasten', 't3events@gmx.de, kasten@webfox01.de', 'dw', '28ae1397ff732c84fe51955678f84b17', 'This is a bugfix release. Please see https://github.com/dwenzel/t3events/releases/tag/0.37.2 for details.', 'Agentur Webfox GmbH, Consulting Piezunka Schamoni - Information Technologies GmbH', 37002, 1, 0),
(35155, 0, 'itypo_expiring_fe_users', 1, '0.0.1', 0, 0, 'iTypo Expiring FE Users', 'Description here..', 0, 0, 0, 1359530808, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"4.0.0-4.7.99";}}', 'Sander Leeuwesteijn  iTypo', 'info@itypo.nl', 'itypo', 'f5bb8d9dbb479ea7f40f89141e6df262', 'Removed some minor bugs. Retested the extension with TYPO3 4.5.x and 4.7x Improved the position of the field in the fe_user TCA. Lots of code cleanup. Added a manual. Added German and Dutch translations.', 'iTypo', 1, 0, 0),
(35156, 0, 'itypo_expiring_fe_users', 1, '0.0.2', 0, 0, 'iTypo Expiring FE Users', 'Description here..', 0, 0, 0, 1359729878, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"4.0.0-4.7.99";}}', 'Sander Leeuwesteijn  iTypo', 'info@itypo.nl', 'itypo', '454bfdd8dcdabcd0ae04c37da2e52f07', 'Dont download this extension, it is not finished and uploaded by accident.', 'iTypo', 2, 1, 0),
(35157, 0, 'forcerealurls2', 1, '0.2.0', 0, 0, 'Force RealURLs (avoid infinite redirect in Workspa', 'Working with Workspaces and Versioning!! Checks if a page is trying to be accessed by an old style URL, and does a 301 redirect to the appropriate URL if so. This extension is based in FORCEREALURLS from Christian Jul Jensen.', 999, 0, 2, 1359632804, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"3.0.0-0.0.0";s:5:"typo3";s:11:"3.7.0-0.0.0";}}', 'Marcos Fadul', 'info@edirect24.com', 'turko', 'b72445746e8d3b1130d39dc261b80d1b', 'Initial Upload', 'eDIRECT24 UG', 2000, 0, 0),
(35158, 0, 'forcerealurls2', 1, '0.3.0', 0, 0, 'Force RealURLs (avoid infinite redirect in Workspa', 'Working with Workspaces and Versioning!! Checks if a page is trying to be accessed by an old style URL, and does a 301 redirect to the appropriate URL if so. This extension is based in FORCEREALURLS from Christian Jul Jensen.', 999, 0, 2, 1397648513, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"4.5.0-6.1.99";}}', 'Marcos Fadul', 'info@edirect24.com', 'turko', 'c4c37c71aa263e2b8f9996b88677fe76', ' Add hook for indexing\r\n Add noforce check to skip redirect\r\n Changed dependency to TYPO3-4.5', 'eDIRECT24 UG', 3000, 0, 0),
(35159, 0, 'forcerealurls2', 1, '0.4.0', 0, 0, 'Force RealURLs (fixed)', 'Working with Workspaces and Versioning!! Checks if a page is trying to be accessed by an old style URL, and does a 301 redirect to the appropriate URL if so. This extension is based in FORCEREALURLS from Christian Jul Jensen.', 999, 0, 2, 1442466313, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"4.5.0-7.5.99";}}', 'Marcos Fadul', 'info@edirect24.com', 'turko', 'ec33b854e09d402cc97f273578381929', 'Update to Typo3 7.5.99\r\nStop redirect if BE User is logged in', 'eDIRECT24 UG', 4000, 1, 0),
(35160, 0, 'itypo_404handler', 1, '1.0.0', 0, 0, 'iTypo 404/403 Handler', 'Proper 404 & 403 handling. URL does not change & correct HTTP status codes. (Even when logged in!) Tested with TYPO3 4.5.x - 4.7.x. Compatible with RealURL.', 2, 0, 2, 1359636175, 'a:2:{s:7:"depends";a:1:{s:5:"typo3";s:12:"4.5.0-4.7.99";}s:9:"conflicts";a:3:{s:20:"pagenotfoundhandling";s:0:"";s:6:"ws_404";s:0:"";s:10:"hype_error";s:0:"";}}', 'Sander Leeuwesteijn  iTypo', 'info@itypo.nl', 'itypo', '19960f0bc4a115b53de325cdc632fbfa', 'Initial upload to TER, if you spot any bugs please report them via my BitBucket issue tracker! (see manual)', 'iTypo', 1000000, 1, 0);
INSERT INTO `tx_extensionmanager_domain_model_extension` (`uid`, `pid`, `extension_key`, `repository`, `version`, `alldownloadcounter`, `downloadcounter`, `title`, `description`, `state`, `review_state`, `category`, `last_updated`, `serialized_dependencies`, `author_name`, `author_email`, `ownerusername`, `md5hash`, `update_comment`, `authorcompany`, `integer_version`, `current_version`, `lastreviewedversion`) VALUES
(35161, 0, 'itypo_securedfiles', 1, '1.0.0', 0, 0, 'iTypo Secured Files', 'Simple protection of files. You can protect filemounts with fe_groups. Requires simple htaccess setting.', 2, 0, 2, 1359636185, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"4.5.0-4.7.99";}}', 'Sander Leeuwesteijn  iTypo', 'info@itypo.nl', 'itypo', 'da7c09dedbf466665cdef5cbd4b3093e', 'Initial upload to TER, if you spot any bugs please report them via my BitBucket issue tracker! (see manual)', 'iTypo', 1000000, 1, 0),
(35162, 0, 'w_chromephp', 1, '0.1.0', 0, 0, 'ChromePhp', 'ChromePhp - chrome console php debug. @See http://www.chromephp.com/', 1, 0, 3, 1359851810, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"4.3.0-4.7.99";}}', 'wolo', 'wolo.wolski@gmail.com', 'wolo', '29ea94c6a57f407c7021a78304b5c7e9', 'Should work perfect.', '', 1000, 0, 0),
(35163, 0, 'w_chromephp', 1, '0.1.2', 0, 0, 'ChromePhp - debug in Google Chrome', 'Chromes Developer tools Console php debug. Short call - just use cp(var);. ChromePHP globally included in TYPO. Respects DevIpMask. Needs Chrome Logger ext for Chrome. @See README for details. @See http://www.chromephp.com/', 2, 0, 3, 1386217574, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"4.3.0-6.2.99";}}', 'wolo', 'wolo.wolski@gmail.com', 'wolo', 'c24913fcd2f1d2042f339b52caa2c0c7', ' ChromePhp 4.1\r\n fix: Better compare ip for devIpMask test (cp didnt show on some server configurations)', '', 1002, 0, 0),
(35164, 0, 'w_chromephp', 1, '0.2.0', 0, 0, 'ChromePHP / Chrome Logger - debug in Chrome consol', 'Chromes Developer tools Console php debug. Short call - just use cp(var);. ChromePHP globally included in TYPO. Respects DevIpMask. Needs Chrome Logger ext for Chrome. @See README for details. @See https://craig.is/writing/chrome-logger', 2, 0, 3, 1481441781, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"4.5.0-7.6.99";}}', 'wolo', 'wolo.wolski@gmail.com', 'wolo', '3d6d0156d22237ce33d8d9725489f7bc', ' Compatibility with TYPO3 7.6\r\n Option to include short functions, or only ChromePhp script\r\n Fixed calls with type (warn, info, error) and added dedicated functions: cpInfo(), cpWarn(), cpError()', '', 2000, 1, 0),
(35165, 0, 'swftools4windows', 1, '0.0.3', 0, 0, 'Swftools for Windows', 'swftools.exe: Install swftools on a Windows server. You must be root!', 0, 0, 4, 1359904283, 'a:0:{}', 'Dirk Wildt (Die Netzmacher)', 'http://wildt.at.die-netzmacher.de', 'dwildt', '7317693726e28ab22a8a383c4eee2904', 'PUBLISHING: swftools.exe: Install swftools on a Windows server. You must be root!', '', 3, 1, 0),
(35166, 0, 'titletag', 1, '0.1.0', 0, 0, 'Title Tag Configuration', 'Manages the configurable generation of the html tag "title"', 1, 0, 2, 1359913253, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:9:"4.5-0.0.0";}}', ' Partner AG', 'development@agenturamwasser.ch', 'christian.futterlieb', '30b375da5eeb90b3805c4a720d857187', 'First release', ' Partner AG', 1000, 0, 0),
(35167, 0, 'titletag', 1, '0.1.1', 0, 0, 'Title Tag Configuration', 'Manages the configurable generation of the html tag "title"', 1, 0, 2, 1359926170, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:9:"4.5-0.0.0";}}', ' Partner AG', 'development@agenturamwasser.ch', 'christian.futterlieb', 'd79e403f58860bb851a1a76a319331c6', 'Bugfix: Extension did not work correct with TYPO3 6.0', ' Partner AG', 1001, 0, 0),
(35168, 0, 'titletag', 1, '0.1.2', 0, 0, 'Title Tag Configuration', 'Manages the configurable generation of the html tag "title"', 1, 0, 2, 1359977682, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:9:"4.5-0.0.0";}}', ' Partner AG', 'development@agenturamwasser.ch', 'christian.futterlieb', '54e8830f9fb9a93bf4b82eb1d7e0d705', 'Bugfix release: added workaround for core bug 28745 (seehttp://forge.typo3.org/issues/28745) and fixed a bug with config.pageTitleFirst stdWrap', ' Partner AG', 1002, 0, 0),
(35169, 0, 'titletag', 1, '0.2.0', 0, 0, 'Title Tag Configuration', 'Manages the configurable generation of the html tag "title"', 1, 0, 2, 1361795569, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:9:"4.5-0.0.0";}}', ' Partner AG', 'development@agenturamwasser.ch', 'christian.futterlieb', 'a3d51ed7f0c88907ae92d271cb07d5b5', 'new with version 0.2.0:\nadded possibility to use _INT cObjects in a page title configuration', ' Partner AG', 2000, 0, 0),
(35170, 0, 'titletag', 1, '0.3.0', 0, 0, 'Title Tag Configuration', 'Manages the configurable generation of the html tag "title". Fully compatible with TYPO3 4.5 - 6.x', 1, 0, 2, 1373620591, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:9:"4.5-0.0.0";}}', ' Partner AG', 'development@agenturamwasser.ch', 'christian.futterlieb', '6a129851ee5e71d72365eab94e95598a', ' Re-structured code base\n Tested compatibility from TYPO3 4.5 until 6.1\n No changes to any configuration behaviour, it is save to just upgrade', ' Partner AG', 3000, 0, 0),
(35171, 0, 'titletag', 1, '0.3.1', 0, 0, 'Title Tag Configuration', 'Manages the configurable generation of the html tag "title". Fully compatible with TYPO3 4.5 - 6.x', 1, 0, 2, 1373641568, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"4.5.0-6.1.99";}}', ' Partner AG', 'development@agenturamwasser.ch', 'christian.futterlieb', 'bae53d80742c480ebb6a1784c3622916', ' Fixed TYPO3 version dependency setting\n No changes to any configuration behaviour, it is save to just upgrade', ' Partner AG', 3001, 0, 0),
(35172, 0, 'titletag', 1, '0.3.2', 0, 0, 'Title Tag Configuration', 'Manages the configurable generation of the html tag "title". Fully compatible with TYPO3 4.5 - 6.x', 1, 0, 2, 1373889888, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"4.5.0-6.1.99";}}', ' Partner AG', 'development@agenturamwasser.ch', 'christian.futterlieb', '32f8fa60f098335f11fe259097b32e97', ' bugfix: last version did not work correctly in TYPO3 4.5\n No changes to any configuration behaviour, it is save to just upgrade', ' Partner AG', 3002, 0, 0),
(35173, 0, 'titletag', 1, '0.3.3', 0, 0, 'Title Tag Configuration', 'Manages the configurable generation of the html tag "title". Fully compatible with TYPO3 4.5 - 6.x', 2, 0, 2, 1403116493, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"4.5.0-6.2.99";}}', ' Partner AG', 'development@agenturamwasser.ch', 'christian.futterlieb', '95173cf1ab5c4542df2006e661e592f6', 'Added TYPO3 6.2 compatibility, migrated documentation to reStructuredText, defined state as stable.\n\nNo functional or configuration changes, it is save to just update!', ' Partner AG', 3003, 0, 0),
(35174, 0, 'titletag', 1, '0.4.0', 0, 0, 'Title Tag Configuration', 'Manages the configurable generation of the html tag "title". Fully compatible with TYPO3 4.5 - 6.2', 2, 0, 2, 1410270388, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"4.5.0-6.2.99";}}', ' Partner AG', 'development@agenturamwasser.ch', 'christian.futterlieb', 'a7147e2c6060004aada287274050a122', 'Added support for stdWrap on plain page- and sitetitle. No further changes, it is save to just update', ' Partner AG', 4000, 1, 0),
(35175, 0, 'abahospital', 1, '1.0.1', 0, 0, 'Aba Hospital', '', 1, 0, 3, 1359970092, 'a:0:{}', 'Daniele Maffoli (Abaco Informatica)', 'd.maffoli@abanet.it', 'dmaffoli', '3ebe2cfcc531ad9a70614f9f8f921598', '', 'Abaco Informatica S.r.l.', 1000001, 0, 0),
