(35177, 0, 'contentlightbox', 1, '1.0.0', 0, 0, 'Content-Fancybox', 'This allows to make links to content-Elements to appear in a lightbox. \nAn API allows to implement plugins in other extensinos to show forms in the lightbox that are evaluated by ajax.\nTo prevent compatibility problems, normal click-enlarge functionality is included. \nThis is copied from jq_fancybox by Aji Yahya aji.yahya@gmail.com.', 2, 0, 2, 1360011433, 'a:0:{}', 'Alexander von Drach', 'avd@net-up.de', 'mindw0rm', '347262ea7c424eebe7227dc3c3ea6eda', 'state set to stable', 'Net-Up AG', 1000000, 0, 0),
