(35241, 0, 'we_betatext', 1, '1.0.0', 0, 0, 'betatext', 'Betatext does allow users to comment any part of a text. The comments can be rated up and down. Users may request to be marked as verified to show that they represent officially an institution, use their real name or are especially trusted. \n		Betatext is used for collaborating work; One can leave constructive criticism towards specific words and phrases in a text and what may be added or changed before the final version of the document is printed.', 1, 0, 3, 1360935849, 'a:1:{s:7:"depends";a:2:{s:15:"saltedpasswords";s:0:"";s:7:"realurl";s:0:"";}}', 'Alexander Schulze, Marko Deutscher', 'asz@wegewerk.com, mdt@wegewerk.com', 'jurim', '204de98cae5d4e7cbe0864ccd46af94d', 'First release', 'Wegewerk', 1000000, 0, 0),
(35242, 0, 'we_betatext', 1, '1.0.1', 0, 0, 'betatext', 'Betatext does allow users to comment any part of a text. The comments can be rated up and down. Users may request to be marked as verified to show that they represent officially an institution, use their real name or are especially trusted. Betatext is used for collaborating work; One can leave constructive criticism towards specific words and phrases in a text and what may be added or changed before the final version of the document is printed. This extension is available on github: https://github.com/wegewerk/betatext.git', 1, 0, 3, 1367568975, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:13:"4.5.22-4.7.99";s:15:"saltedpasswords";s:0:"";s:7:"realurl";s:0:"";}}', 'Alexander Schulze, Marko Deutscher', 'asz@wegewerk.com, mdt@wegewerk.com', 'jurim', 'e8aed4ae9baad3efbd0c1b717b0c5f4b', 'documentation update', 'Wegewerk', 1000001, 0, 0),
