(35320, 0, 'vibeo', 1, '0.2.0', 0, 0, 'Vibo accessible HTML5 media player - Based on Me', 'This extension integrates the Vibo project, an accessible media player based on MediaElement.js that is meant to respect the SGQRI standards of the provincial government of Qubec. It supports all major video and audio formats, preview images, track files, and is able to fetch video files from Youtube and Vimeo. Vibo is developed and maintained by Libo, this TYPO3 extension was built by Qc mdia. \nThe documentation will be maintained on the tracker, at http://forge.typo3.org/projects/extension-vibeo', 1, 0, 3, 1361133918, 'a:1:{s:7:"depends";a:3:{s:7:"extbase";s:3:"1.3";s:5:"fluid";s:3:"1.3";s:5:"typo3";s:9:"4.5-0.0.0";}}', 'Philippe Moreau', 'philippe.moreau@qcmedia.ca', 'qcmedia', '2fd5f3a7a4b26d547d4ce4bd506c6e95', 'First upload. All features implemented but not all tested. Basic documentation at http://forge.typo3.org/projects/extension-vibeo/wiki', 'Qc Mdia', 2000, 0, 0),
(35321, 0, 'vibeo', 1, '0.3.0', 0, 0, 'Vibeo accessible HTML5 media player - Based on Med', 'This extension integrates the Vibeo project, an accessible media player based on MediaElement.js that is meant to respect the SGQRI standards of the provincial government of Quebec. It supports all major video and audio formats, preview images, track files, and is able to fetch video files from Youtube and Vimeo. Vibeo is developed and maintained by Libo, this TYPO3 extension was built by Qc media. \nThe documentation will be maintained on the tracker, at http://forge.typo3.org/projects/extension-vibeo', 1, 0, 3, 1361224881, 'a:1:{s:7:"depends";a:3:{s:7:"extbase";s:3:"1.3";s:5:"fluid";s:3:"1.3";s:5:"typo3";s:9:"4.5-0.0.0";}}', 'Philippe Moreau', 'philippe.moreau@qcmedia.ca', 'qcmedia', '873ab5dfabd02d484fc646ad5a3db774', 'Bug fixes. Better localization.', 'Qc Media', 3000, 0, 0),
(35322, 0, 'vibeo', 1, '0.3.1', 0, 0, 'Vibeo accessible HTML5 media player - Based on Med', 'This extension integrates the Vibeo project, an accessible media player based on MediaElement.js that is meant to respect the SGQRI standards of the provincial government of Quebec. It supports all major video and audio formats, preview images, track files, and is able to fetch video files from Youtube and Vimeo. Vibeo is developed and maintained by Libo, this TYPO3 extension was built by Qc media. \nThe documentation will be maintained on the tracker, at http://forge.typo3.org/projects/extension-vibeo', 1, 0, 3, 1361654330, 'a:1:{s:7:"depends";a:3:{s:7:"extbase";s:3:"1.3";s:5:"fluid";s:3:"1.3";s:5:"typo3";s:9:"4.5-0.0.0";}}', 'Philippe Moreau', 'philippe.moreau@qcmedia.ca', 'qcmedia', '94ec3cbdd9722a65d83f8d339292f5e6', 'Corrected bug that prevented more than one element per page. \nSmall skin fix for Firefox.', 'Qc Media', 3001, 0, 0),
(35323, 0, 'vibeo', 1, '0.5.0', 0, 0, 'Vibeo accessible HTML5 media player - Based on Med', 'This extension integrates the Vibeo project, an accessible media player based on MediaElement.js that is meant to respect the SGQRI standards of the provincial government of Quebec. It supports all major video and audio formats, preview images, track files, and is able to fetch video files from Youtube and Vimeo. Vibeo is developed and maintained by Libo, this TYPO3 extension was built by Qc media. \nThe documentation will be maintained on the tracker, at http://forge.typo3.org/projects/extension-vibeo', 1, 0, 3, 1401398710, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:13:"4.5.0-6.2.999";}}', 'Philippe Moreau', 'philippe.moreau@qcmedia.ca', 'qcmedia', '2bff6d3463cc7df455446d7ffee94a41', 'FAL support\r\nTYPO3 6.2 support\r\nLatest version of vibeo\r\nFlexform fixes and additional typoscript configurations', 'Qc Media', 5000, 1, 0),
