(35352, 0, 'tnm_feloginrsaauth', 1, '0.0.1', 0, 0, '(tnm) FE-Login RSA-Auth', 'Provides a HTML-Template for EXT:felogin in combination with RSAAuth/SaltedPasswords.\nIn some cases this combination leads in problems with some Browsers (f.e. Internet Explorer). The\ntemplate provided with this Extension replaces the default-template of felogin fixing some RSA-Javascript.\n\nTested with IE 9-7, Chrome and Firefox to work fine!\nThe current version requires jQuery to be present!', 0, 0, 2, 1361965829, 'a:1:{s:7:"depends";a:2:{s:7:"felogin";s:0:"";s:7:"rsaauth";s:0:"";}}', 'Gabriel Kaufmann  Typoworx NewMedia', 'info@typoworx.de', 'typoworx-de', '9e6278f92b618898e3d73c146ed19971', 'first draft.', '', 1, 0, 0),
(35353, 0, 'tnm_feloginrsaauth', 1, '0.0.2', 0, 0, '(tnm) FE-Login RSA-Auth', 'Provides a HTML-Template for EXT:felogin in combination with RSAAuth/SaltedPasswords.\nIn some cases this combination leads in problems with some Browsers (f.e. Internet Explorer). The\ntemplate provided with this Extension replaces the default-template of felogin fixing some RSA-Javascript.\n\nTested with IE 9-7, Chrome and Firefox to work fine!\nThe current version requires jQuery to be present!', 0, 0, 2, 1362651840, 'a:1:{s:7:"depends";a:2:{s:7:"felogin";s:0:"";s:7:"rsaauth";s:0:"";}}', 'Gabriel Kaufmann  Typoworx NewMedia', 'info@typoworx.de', 'typoworx-de', 'a576085826fad92dcbd186726ce01ad4', '- Updated Javascript\n- Added Loading-Indicator (AJAX Animation)', '', 2, 0, 0),
(35354, 0, 'tnm_feloginrsaauth', 1, '0.0.3', 0, 0, '(tnm) FE-Login RSA-Auth', 'Provides a HTML-Template for EXT:felogin in combination with RSAAuth/SaltedPasswords.\nIn some cases this combination leads in problems with some Browsers (f.e. Internet Explorer). The\ntemplate provided with this Extension replaces the default-template of felogin fixing some RSA-Javascript.\n\nTested with IE 9-7, Chrome and Firefox to work fine!\nThe current version requires jQuery to be present!', 0, 0, 2, 1362747091, 'a:1:{s:7:"depends";a:2:{s:7:"felogin";s:0:"";s:7:"rsaauth";s:0:"";}}', 'Gabriel Kaufmann  Typoworx NewMedia', 'info@typoworx.de', 'typoworx-de', '12b3f51f8860ec8e11f2054fa1ef922e', '', '', 3, 0, 0),
