(35386, 0, 'extbase_fal', 1, '0.0.1', 0, 0, 'Extbase FAL', 'Provides some useful helper to use FAL in Extbase and Fluid.', 0, 0, 3, 1362850594, 'a:1:{s:7:"depends";a:3:{s:7:"extbase";s:3:"6.0";s:5:"fluid";s:3:"6.0";s:5:"typo3";s:9:"6.0-0.0.0";}}', 'Albrecht Koehnlein', 'ak@koehnlein.eu', 'whnsnn', 'b9b97a2c1f00184d8b0b48b9d0ac337b', 'First release of extension contains: 1) A model, you can use or extend in your own Extbase extension to have access to your FAL records. 2) An (experimental) BE module to migrate old file fields into FAL structure.', '', 1, 1, 0),
(35387, 0, 'tweetnews', 1, '0.9.0', 0, 0, 'Tweet News: Automatic tweeting of published EXT:ne', 'Use the Twitter API to tweet about news items added in Georg Ringers EXT:news extension. Minimal configuration - no database storage used.', 1, 0, 3, 1362954660, 'a:0:{}', 'Claus Due', 'claus@wildside.dk', 'namelesscoder', 'e509b4dc196ce75de3125b71e25af9be', 'First TER version - see README.md for installation and setup instructions.', 'Wildside A/S', 9000, 0, 0);
