(35398, 0, 'mue_template', 1, '1.0.0', 0, 0, 'Mueters Template Parser', 'A simple template parses. Simply replaces given HTML comment blocks with the code you assigned to it.\nFast, simple and efficient.', 2, 0, 3, 1363123821, 'a:0:{}', 'JMTiepo3', 'JMTiepo3@hmamail.com', 'mueters', 'bcb0219aa9e384b4293581a6e0439871', '[RELEASE] 1.0.0 Released\n\n[INFO] Please read the README file if you dont know how to set it up. \n\n[INFO] A manual will be written very soon.', '', 1000000, 0, 0),
(35399, 0, 'mue_template', 1, '2.0.0', 0, 0, 'Mueters Template Parser', 'A Simple Template Parser using PHP DOM. Fast and Easy. Please read the README.txt file!', 2, 0, 3, 1365543943, 'a:0:{}', 'JMTiepo3', 'JMTiepo3@hmamail.com', 'mueters', 'f307398cb06b04ae6ec7f8915d590a53', 'Totally Rewritten\nUses DOM Parser instead of TYPO3s HTML parser\nImplemented Recursion\nUpdated Extension Description\nHighered minimum PHP version (5.3.6)', '', 2000000, 1, 0),
