(35401, 0, 'titech_jobs', 1, '0.0.1', 0, 0, 'Job Communicator', 'Add jobs,Enable communication.More features coming soon', 0, 0, 1, 1363180708, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:3:"php";s:12:"5.0.0-5.3.99";s:5:"typo3";s:12:"4.3.0-4.7.99";}}', 'Ti Technologies(info@titechnologies.in)', 'info@titechnologies.in', 'titechnologies', '31c666fe3ce79c023cf2bb584ace7c03', '', '', 1, 0, 0),
(35402, 0, 'titech_jobs', 1, '1.0.0', 0, 0, 'Job Communicator', 'Admin can add jobs and categories, can assign jobs to user group, he can sent messages to users, can add notes and attachments corresponding to a job.\n	                  Users after logged in can view job lists assingned to them.This extension enable communication between users of same group. Users can add notes and attachments corresponding to a job, can send mails to other group members.More features coming soon', 2, 0, 1, 1363342391, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:3:"php";s:12:"5.0.0-5.3.99";s:5:"typo3";s:12:"4.3.0-4.7.99";}}', 'Ti Technologies(info@titechnologies.in)', 'info@titechnologies.in', 'titechnologies', '912bf62b89c677f6a539c9a1a550cb55', 'Update the documentation and new featured ajax for message.', '', 1000000, 0, 0),
(35403, 0, 'titech_jobs', 1, '2.0.0', 0, 0, 'Job Communicator', 'Admin can add jobs and categories, can assign jobs to user group, he can sent messages to users, can add notes and attachments corresponding to a job.\n										Users after logged in can view job lists assingned to them.This extension enable communication between users of same group. Users can add notes and attachments corresponding to a job, can send mails to other group members.More features coming soon', 2, 0, 1, 1421739260, 'a:1:{s:7:"depends";a:2:{s:5:"fluid";s:0:"";s:5:"typo3";s:12:"4.5.0-6.2.99";}}', 'Ti Technologies(info@titechnologies.in)', 'info@titechnologies.in', 'titechnologies', 'de7f19fe3291d1c393e60ed1b15a8b6a', 'Updated with 6.2.x support.', '', 2000000, 1, 0),
(35404, 0, 'dhbw_ux_naw_single_signon', 1, '1.0.0', 0, 0, 'Extends naw_single_signon', 'Extension to make naw_single_signon usable with dhbw_naw_sso (transform query-string with prefixes to avoid conflicts)', 0, 0, 3, 1363181456, 'a:1:{s:7:"depends";a:2:{s:17:"naw_single_signon";s:0:"";s:5:"typo3";s:11:"4.5.0-0.0.0";}}', 'Jan Kristoffer Roth', 'roth@dhbw-mosbach.de', 'nixahnung', '0cee809ff03a8b1682bed9572e21d425', 'Initial upload', '', 1000000, 1, 0),
