(35406, 0, 'turnjs', 1, '0.1.1', 0, 0, 'turnjs', 'turn.js is a flipbook framework build on HTML5. See all about turn.js on www.turnjs.com\n		This extension implements turn.js for whole TYPO3 pages', 1, 0, 3, 1363256052, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'hmmh Team TYPO3', 'typo3@hmmh.de', 'hmmh', '6a1f2ed4f149570d27df2be5b14f53bb', 'Initial upload.', 'hmmh multimediahaus AG', 1001, 1, 0),
(35407, 0, 'stash', 1, '0.2.0', 0, 0, 'Stash', 'Stash makes it easy to speed up your code by caching the results of expensive functions or code. Certain actions, like database queries or calls to external APIs, take a lot of time to run but tend to have the same results over short periods of time. This makes it much more efficient to store the results and call them back up later.', 1, 0, 4, 1363262955, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"5.3.0-0.0.0";s:5:"typo3";s:11:"4.5.0-0.0.0";}}', 'Markus Wagner', 'markus.wagner@bgm-gmbh.de', 'teddai', 'f6a79a0ea2389cd043c91b14d5f60c41', 'First version of wrapper for Stash', ' Co. KG', 2000, 1, 0),
