(35551, 0, 'pits_wd_calender', 1, '2.1.0', 0, 0, 'Event Calender', 'Event Calender:This extension is used to display events in a specified area with the help of  Google map. \n	                  The extension allows to enter the events from the back-end and front end.  \n	                  Also detailed view of each event is possible using this extension. \n	                  The events can be categorized into regions based on there geographical location. \n	                  The plug-in provides option to filter events based on region in the map.\n	                  Admin can add manually from the backend the events for the map or for the compact view.', 2, 0, 3, 1365422185, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:9:"4.5-0.0.0";}}', 'Abin Sabu', 'abin.s@pitsolutions.com', 'pitsolutions_typo3', '782fa251c938fd75d365cb30c91251d1', 'Description AndDocument updated.', 'PIT Solutions Pvt.Ltd.', 2001000, 0, 0),
(35552, 0, 'pits_wd_calender', 1, '2.2.0', 0, 0, 'Event Calender', 'Event Calender:This extension can be used to display events in a specified area with the help of  Google map. \r\n	                  The extension allows to enter the events from the back-end and front end.  \r\n	                  Also detailed view of each event is possible using this extension. \r\n	                  The events can be categorized into regions based on there geographical location. \r\n	                  The plug-in provides option to filter events based on region in the map.\r\n	                  This extension can be used as simple map in the FE.\r\n	                  For queries and bug reporting please feel free to conatct through email at abin.s@pitsolutions.com.', 2, 0, 3, 1365424489, 'a:1:{s:7:"depends";a:3:{s:7:"extbase";s:3:"1.3";s:5:"fluid";s:3:"1.3";s:5:"typo3";s:9:"4.5-0.0.0";}}', 'Abin Sabu', 'abin.s@pitsolutions.com', 'pitsolutions_typo3', 'd0b267c2f614e18553f572baf74436bb', 'Description And Document updated.', 'PIT Solutions Pvt.Ltd.', 2002000, 0, 0),
