(35648, 0, 'orphanfiles', 1, '0.4.0', 0, 0, 'Orphan Files', 'This backend extension finds any file uploaded by an editor which is not used anymore in the CMS - Not working with DAM/Workspaces/FAL, please read the manual!', 1, 0, 1, 1431417342, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"4.5.0-6.2.99";}}', 'Dan Untenzu', 'untenzu@webit.de', 'udwebit', 'a655d5861148b41565ac696b6934ad90', 'Allow modification of file pattern via TSconfig\r\n\r\nNote: It is possible to run this extension in 6.2 as well, but use it to search for orphaned files of legacy extensions only (eg. during/after upgrade from version 4.5 to 6.2), since orphanfiles still i', '', 4000, 0, 0),
(35649, 0, 'orphanfiles', 1, '0.4.1', 0, 0, 'Orphan Files', 'This backend extension finds any file uploaded by an editor which is not used anymore in the CMS - Not working with DAM/Workspaces/FAL, please read the manual!', 1, 0, 1, 1431419118, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"4.5.0-6.2.99";}}', 'Dan Untenzu', 'untenzu@webit.de', 'udwebit', '2a7c0451a2ad0231316bc206522ec512', 'Bugfix release. Note: It is possible to run this extension in 6.2 as well, but use it to search for orphaned files of legacy extensions only (eg. during upgrade from TYPO3 4.5 to 6.2), since orphanfiles still ignores FAL!', '', 4001, 1, 0),
(35650, 0, 'sphinx', 1, '0.1.0', 0, 0, 'Sphinx Python Documentation Generator', 'Provides a local Sphinx generator for your TYPO3 website.', 0, 0, 4, 1366380326, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"6.0.0-6.1.99";s:3:"php";s:11:"5.3.0-0.0.0";}}', 'Xavier Perseguers', 'xavier@causal.ch', 'xperseguers', '058d0ace16bbdc1ebfde062a8964dd4d', 'Initial release to gather feedback. Happy documenting!', 'Causal Srl', 1000, 0, 0),
(35651, 0, 'sphinx', 1, '0.2.0', 0, 0, 'Sphinx Python Documentation Generator', 'One-click install Sphinx generator for your TYPO3 website. This extension builds ReStructuredText documentation (format of official TYPO3 manuals).', 0, 0, 4, 1367055733, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"6.0.0-6.1.99";s:3:"php";s:11:"5.3.0-0.0.0";}}', 'Xavier Perseguers', 'xavier@causal.ch', 'xperseguers', '5a592311f3e631769c1b7cb3e97d6f6c', 'Wizard for kickstarting a TYPO3 documentation (with pretty orange HTML template).\nFully capable of cross-linking to official TYPO3 manuals (example included).\nPlease rebuild your Python environment!', 'Causal Srl', 2000, 0, 0),
(35652, 0, 'sphinx', 1, '0.3.0', 0, 0, 'Sphinx Python Documentation Generator', 'One-click install Sphinx generator for your TYPO3 website. This extension builds ReStructuredText documentation (format of official TYPO3 manuals).', 1, 0, 4, 1368186301, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"6.0.0-6.2.99";s:3:"php";s:11:"5.3.0-0.0.0";}}', 'Xavier Perseguers', 'xavier@causal.ch', 'xperseguers', 'ea937e24ab9e3b3bd1947b77444c8d6b', 'Better handling of official TYPO3 documentation structure.\nColored console output.\nCompilation in PDF if pdflatex is available.\nReworked importer in EM with support for manual build of components.', 'Causal Srl', 3000, 0, 0),
(35653, 0, 'sphinx', 1, '0.4.0', 0, 0, 'Sphinx Python Documentation Generator', 'One-click install Sphinx generator for your TYPO3 website. This extension builds ReStructuredText documentation (format of official TYPO3 manuals).', 1, 0, 4, 1369734698, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"5.3.3-0.0.0";s:5:"typo3";s:12:"6.0.0-6.1.99";}}', 'Xavier Perseguers', 'xavier@causal.ch', 'xperseguers', 'add98273aaeb420a7c88280ba881a4e1', 'Now can use globally installed Sphinx as well, if available.\nNew Backend module: Sphinx documentation viewer to locally render extensions manuals', 'Causal Srl', 4000, 0, 0),
(35654, 0, 'sphinx', 1, '0.5.0', 0, 0, 'Sphinx Python Documentation Generator and Viewer', 'One-click install Sphinx generator for your TYPO3 website. This extension builds ReStructuredText documentation\n	(format of official TYPO3 manuals), renders other extension manuals and provides an integrated editor for your own extension manuals.', 1, 0, 4, 1370356740, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"5.3.3-0.0.0";s:5:"typo3";s:12:"6.0.0-6.1.99";}}', 'Xavier Perseguers', 'xavier@causal.ch', 'xperseguers', '943a55430a3b758d68e4a622a403d87b', 'Now features an integrated ReStructuredText editor and a revamped documentation viewer for extensions with Sphinx-based manuals.', 'Causal Srl', 5000, 0, 0),
(35655, 0, 'sphinx', 1, '0.6.0', 0, 0, 'Sphinx Python Documentation Generator and Viewer', 'One-click install Sphinx generator for your TYPO3 website. This extension builds ReStructuredText documentation\n	(format of official TYPO3 manuals), renders other extension manuals and provides an integrated editor for your own extension manuals.', 1, 0, 4, 1371539445, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:12:"5.3.3-5.4.99";s:5:"typo3";s:12:"6.0.0-6.1.99";}}', 'Xavier Perseguers', 'xavier@causal.ch', 'xperseguers', 'c33a38ed02a6e2aa59bee4b894155441', 'Extension is now compatible with MS Windows platform! In addition, signal/slot mechanism has been added to let you register your own documentation in Sphinx Documention Viewer.', 'Causal Srl', 6000, 0, 0),
(35656, 0, 'sphinx', 1, '1.0.0', 0, 0, 'Sphinx Python Documentation Generator and Viewer', 'One-click install Sphinx generator for your TYPO3 website. This extension builds ReStructuredText documentation\n	(format of official TYPO3 manuals), renders other extension manuals and provides an integrated editor for your own extension manuals.', 2, 0, 4, 1373013223, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:12:"5.3.3-5.4.99";s:5:"typo3";s:12:"6.0.0-6.1.99";}}', 'Xavier Perseguers', 'xavier@causal.ch', 'xperseguers', 'a916a4831c3722aaf52827b4fa0634d3', 'T3DD13 release.\nExtension is now considered stable.\nTYPO3 branding with LaTeX for PDF rendering.\n[experimental] support of rst2pdf.', 'Causal Srl', 1000000, 0, 0),
(35657, 0, 'sphinx', 1, '1.1.0', 0, 0, 'Sphinx Python Documentation Generator and Viewer', 'One-click install Sphinx generator for your TYPO3 website. This extension builds ReStructuredText documentation\n	(format of official TYPO3 manuals), renders other extension manuals and provides an integrated editor for your own extension manuals.', 2, 0, 4, 1376070184, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:12:"5.3.3-5.4.99";s:5:"typo3";s:12:"6.0.0-6.1.99";}}', 'Xavier Perseguers (Causal)', 'xavier@causal.ch', 'xperseguers', 'bb58698c8e6733d13ee79ad4aeb1c05c', 'Support for multilingual documentation.\nFrench documentation.\nTypoScript highlighting.\nSimply register custom projects.\nOpenOffice to Sphinx converter.\nExtend EXT:documentation (TYPO3 6.2 only).', 'Causal Srl', 1001000, 0, 0),
(35658, 0, 'sphinx', 1, '1.1.1', 0, 0, 'Sphinx Python Documentation Generator and Viewer', 'One-click install Sphinx generator for your TYPO3 website. This extension builds Sphinx/reStructuredText documents (format of official TYPO3 manuals), renders extension manuals as HTML/JSON/PDF and provides an integrated editor for your own extension manuals and documents.', 2, 0, 4, 1377352031, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:12:"5.3.3-5.4.99";s:5:"typo3";s:12:"6.0.0-6.1.99";}}', 'Xavier Perseguers (Causal)', 'xavier@causal.ch', 'xperseguers', '1054befb74f29422d5d83e19b3b393c3', 'Bugfix release.\nUse of online Ace editor has been blacklisted due to abuse.\nFix broken styles in TYPO3 6.2.\nDetails on http://forge.typo3.org/projects/extension-sphinx/wiki/SPHINX_111', 'Causal Srl', 1001001, 0, 0),
(35659, 0, 'sphinx', 1, '1.2.0', 0, 0, 'Sphinx Python Documentation Generator and Viewer', 'Installs a full-fledged Sphinx environment within your TYPO3 website. Builds and render Sphinx/reStructuredText-based projects such as extension manuals, official reference guides or your own in-house documents as HTML/JSON/PDF either from TYPO3 Backend or from command-line, as you prefer. Features an reStructuredText editor with cross-reference browser.', 2, 0, 4, 1379868898, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:12:"5.3.3-5.4.99";s:5:"typo3";s:12:"6.0.0-6.1.99";}}', 'Xavier Perseguers (Causal)', 'xavier@causal.ch', 'xperseguers', 'af7ca432b6cdec4b3e1a1f3e07dac291', 'Enhanced reStructuredText/Sphinx built-in editor.\nSupport for 3rd-party plugins (YouTube/Google Maps/...).\nKeep Sphinx environment when upgrading.\nDetails on http://forge.typo3.org/projects/extension-sphinx/wiki/SPHINX_120', 'Causal Srl', 1002000, 0, 0),
(35660, 0, 'sphinx', 1, '1.2.1', 0, 0, 'Sphinx Python Documentation Generator and Viewer', 'Installs a full-fledged Sphinx environment within your TYPO3 website. Builds and renders Sphinx/reStructuredText-based projects such as extension manuals, official reference guides or your own in-house documents as HTML/JSON/PDF either from TYPO3 Backend or from command-line, as you prefer. Features a reStructuredText editor with cross-reference browser.', 2, 0, 4, 1379938934, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:12:"5.3.3-5.4.99";s:5:"typo3";s:12:"6.0.0-6.1.99";}}', 'Xavier Perseguers (Causal)', 'xavier@causal.ch', 'xperseguers', 'fc7744e23c1aa853c53a9af507a75662', 'Bugfix. Interactive layout has been broken by attempting to prevent cache problem with browsers built-in PDF viewer pdf.js.\nDetails on http://forge.typo3.org/projects/extension-sphinx/wiki/SPHINX_121', 'Causal Srl', 1002001, 0, 0),
(35661, 0, 'sphinx', 1, '1.2.2', 0, 0, 'Sphinx Python Documentation Generator and Viewer', 'Installs a full-fledged Sphinx environment within your TYPO3 website. Builds and renders Sphinx/reStructuredText-based projects such as extension manuals, official reference guides or your own in-house documents as HTML/JSON/PDF either from TYPO3 Backend or from command-line, as you prefer. Features a reStructuredText editor with cross-reference browser.', 2, 0, 4, 1381872221, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:12:"5.3.3-5.5.99";s:5:"typo3";s:12:"6.0.0-6.2.99";}}', 'Xavier Perseguers (Causal)', 'xavier@causal.ch', 'xperseguers', '3e8f0efecf295a01b8a3946207cb7692', 'Bugfix release and compatibility with TYPO3 6.2 LTS.\nDetails on http://forge.typo3.org/projects/extension-sphinx/wiki/SPHINX_122', 'Causal Srl', 1002002, 0, 0),
(35662, 0, 'sphinx', 1, '1.3.0', 0, 0, 'Sphinx Python Documentation Generator and Viewer', 'Installs a full-fledged Sphinx environment within your TYPO3 website. Builds and renders Sphinx/reStructuredText-based projects such as extension manuals, official reference guides or your own in-house documents as HTML/JSON/PDF either from TYPO3 Backend or from command-line, as you prefer. Features a reStructuredText editor with cross-reference browser and syntax highlighting.', 2, 0, 5, 1388946318, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:12:"5.3.3-5.5.99";s:5:"typo3";s:12:"6.0.0-6.2.99";}}', 'Xavier Perseguers (Causal)', 'xavier@causal.ch', 'xperseguers', 'e49cc850e96de527b646b97a9cf189d1', 'Syntax highlighting, keyboad shortcuts, auto-mapping for Intersphinx. Details on http://forge.typo3.org/projects/extension-sphinx/wiki/SPHINX_130', 'Causal Srl', 1003000, 0, 0),
(35663, 0, 'sphinx', 1, '1.3.1', 0, 0, 'Sphinx Python Documentation Generator and Viewer', 'Installs a full-fledged Sphinx environment within your TYPO3 website. Builds and renders Sphinx/reStructuredText-based projects such as extension manuals, official reference guides or your own in-house documents as HTML/JSON/PDF either from TYPO3 Backend or from command-line, as you prefer. Features a reStructuredText editor with cross-reference browser and syntax highlighting.', 2, 0, 5, 1389906980, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:12:"5.3.3-5.5.99";s:5:"typo3";s:12:"6.0.0-6.2.99";}}', 'Xavier Perseguers (Causal)', 'xavier@causal.ch', 'xperseguers', 'f2faf9a65959d6fa10d4285639f70601', 'Crash when converting an OpenOffice manual to Sphinx.\nDetails on http://forge.typo3.org/projects/extension-sphinx/wiki/SPHINX_131', 'Causal Srl', 1003001, 0, 0),
(35664, 0, 'sphinx', 1, '1.3.2', 0, 0, 'Sphinx Python Documentation Generator and Viewer', 'Installs a full-fledged Sphinx environment within your TYPO3 website. Builds and renders Sphinx/reStructuredText-based projects such as extension manuals, official reference guides or your own in-house documents as HTML/JSON/PDF either from TYPO3 Backend or from command-line, as you prefer. Features a reStructuredText editor with cross-reference browser and syntax highlighting.', 2, 0, 1, 1394987100, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:12:"5.3.3-5.5.99";s:5:"typo3";s:12:"6.0.0-6.2.99";}}', 'Xavier Perseguers (Causal)', 'xavier@causal.ch', 'xperseguers', '47e5122f7690a3d5b126f9dec420971f', 'Properly generates URIs with security token introduced in TYPO3 6.2.\nDetails on http://forge.typo3.org/projects/extension-sphinx/wiki/SPHINX_132', 'Causal Srl', 1003002, 0, 0),
(35665, 0, 'sphinx', 1, '2.0.0', 0, 0, 'Sphinx Python Documentation Generator and Viewer', 'Installs a full-fledged Sphinx environment within your TYPO3 website. Builds and renders Sphinx/reStructuredText-based projects such as extension manuals, official reference guides or your own in-house documents as HTML/JSON/PDF either from TYPO3 Backend or from command-line, as you prefer. Features a reStructuredText editor with cross-reference browser and syntax highlighting.', 2, 0, 1, 1396885313, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:12:"5.3.3-5.5.99";s:5:"typo3";s:12:"6.0.0-6.2.99";}}', 'Xavier Perseguers (Causal)', 'xavier@causal.ch', 'xperseguers', '84ad718857f2d1a1aab67e2102041e7b', 'Rebranded dashboard to easily manage/kickstart custom projects (from template or external git repository).\nEnhanced documentation editor (drag and drop, ...) supporting git.\nDetails on http://forge.typo3.org/projects/extension-sphinx/wiki/SPHINX_200', 'Causal Srl', 2000000, 0, 0),
(35666, 0, 'sphinx', 1, '2.0.1', 0, 0, 'Sphinx Python Documentation Generator and Viewer', 'Installs a full-fledged Sphinx environment within your TYPO3 website. Builds and renders Sphinx/reStructuredText-based projects such as extension manuals, official reference guides or your own in-house documents as HTML/JSON/PDF either from TYPO3 Backend or from command-line, as you prefer. Features a reStructuredText editor with cross-reference browser and syntax highlighting.', 2, 0, 1, 1397981275, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:12:"5.3.3-5.5.99";s:5:"typo3";s:12:"6.0.0-6.2.99";}}', 'Xavier Perseguers (Causal)', 'xavier@causal.ch', 'xperseguers', '0a6d13b6c8d0cf6d9b1c45b27a98e732', 'Regular maintenance release. Fixes various PHP warnings.\nDetails on http://forge.typo3.org/projects/extension-sphinx/wiki/SPHINX_201', 'Causal Srl', 2000001, 0, 0),
(35667, 0, 'sphinx', 1, '2.1.0', 0, 0, 'Sphinx Python Documentation Generator and Viewer', 'Installs a full-fledged Sphinx environment within your TYPO3 website. Builds and renders Sphinx/reStructuredText-based projects such as extension manuals, official reference guides or your own in-house documents as HTML/JSON/PDF either from TYPO3 Backend or from command-line, as you prefer. Features a reStructuredText editor with cross-reference browser and syntax highlighting.', 2, 0, 1, 1401961013, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:12:"5.3.3-5.5.99";s:5:"typo3";s:12:"6.0.0-6.2.99";}}', 'Xavier Perseguers (Causal)', 'xavier@causal.ch', 'xperseguers', '0b6769cbed77383089f29550c458a61b', 'Support for pattern-based external links (e.g., for Forge tickets, TER, ...) and upload of images (or files) with built-in reStructuredText editor.\nDetails on http://forge.typo3.org/projects/extension-sphinx/wiki/SPHINX_210', 'Causal Srl', 2001000, 0, 0),
(35668, 0, 'sphinx', 1, '2.2.0', 0, 0, 'Sphinx Python Documentation Generator and Viewer', 'Installs a full-fledged Sphinx environment within your TYPO3 website. Builds and renders Sphinx/reStructuredText-based projects such as extension manuals, official reference guides or your own in-house documents as HTML/JSON/PDF either from TYPO3 Backend or from command-line, as you prefer. Features a reStructuredText editor with cross-reference browser and syntax highlighting.', 2, 0, 1, 1417708888, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:12:"5.3.3-5.6.99";s:5:"typo3";s:13:"6.2.0-7.99.99";}}', 'Xavier Perseguers (Causal)', 'xavier@causal.ch', 'xperseguers', '3293ef9c434b5dfe3080e870583faaf8', 'Compatibility with TYPO3 6.2 - 7.x.\nDetails on https://forge.typo3.org/projects/extension-sphinx/wiki/SPHINX_220', 'Causal Srl', 2002000, 0, 0),
