(35771, 0, 'femanager', 1, '1.0.0', 0, 0, 'femanager', 'FE-User Registration and Management based on Extbase and Fluid. This extension basicly works like sr_feuser_register.', 0, -1, 3, 1373020657, 'a:1:{s:7:"depends";a:3:{s:7:"extbase";s:7:"6.0-6.2";s:5:"fluid";s:7:"6.0-6.2";s:5:"typo3";s:7:"6.0-6.2";}}', 'Alex Kellner', 'alexander.kellner@in2code.de', 'wunschtacho', 'f1d034a978374dbd1c3723f188138560', 'Initial Upload of femanager. TYPO3 Frontenduser Registration. TYPO3 6.0/6.1/6.2 - Looking forward for your feedback!', 'in2code.de - Wir leben TYPO3', 1000000, 0, 0),
