(35954, 0, 'slub_events', 1, '1.0.7', 0, 0, 'SLUB: Event Registration', 'Tool for event registration and experts booking.\n\nThis extension is developped and used in production at the Saxony State and University Library (SLUB) Dresden, Germany.\n', 1, 0, 3, 1370015470, 'a:1:{s:7:"depends";a:3:{s:7:"extbase";s:3:"1.5";s:5:"fluid";s:3:"1.5";s:5:"typo3";s:9:"4.7-0.0.0";}}', 'Alexander Bigga', 'alexander.bigga@slub-dresden.de', 'albigdd', '423381f8c6f972b2aff1644d1962b844', 'This is the initial release into the TER.', 'SLUB Dresden', 1000007, 0, 0),
