(35956, 0, 'slub_events', 1, '1.0.10', 0, 0, 'SLUB: Event Registration', 'Tool for event registration and experts booking.\n\nThis extension is developped and used in production at the Saxony State and University Library (SLUB) Dresden, Germany.', 1, 0, 3, 1372683954, 'a:1:{s:7:"depends";a:3:{s:7:"extbase";s:3:"1.5";s:5:"fluid";s:3:"1.5";s:5:"typo3";s:9:"4.7-0.0.0";}}', 'Alexander Bigga', 'alexander.bigga@slub-dresden.de', 'albigdd', '3e011cd56871fd830fce6ed4f4d967ab', 'Fixed several issues when using the extension with language overlay in categories.', 'SLUB Dresden', 1000010, 0, 0),
(35957, 0, 'slub_events', 1, '1.0.11', 0, 0, 'SLUB: Event Registration', 'Tool for event registration and experts booking.\n\nThis extension is developped and used in production at the Saxony State and University Library (SLUB) Dresden, Germany.', 1, 0, 3, 1372754326, 'a:1:{s:7:"depends";a:3:{s:7:"extbase";s:3:"1.5";s:5:"fluid";s:3:"1.5";s:5:"typo3";s:9:"4.7-0.0.0";}}', 'Alexander Bigga', 'alexander.bigga@slub-dresden.de', 'albigdd', 'e88571cdb17e851608543c8072d1dd19', 'fixed issue with selecting categories in list view; fixed issue with copy events in backend module', 'SLUB Dresden', 1000011, 0, 0),
(35958, 0, 'slub_events', 1, '1.0.15', 0, 0, 'SLUB: Event Registration', 'Tool for event registration and experts booking.\n\nThis extension is developped and used in production at the Saxony State and University Library (SLUB) Dresden, Germany.', 1, 0, 3, 1374495050, 'a:1:{s:7:"depends";a:3:{s:7:"extbase";s:3:"1.5";s:5:"fluid";s:3:"1.5";s:5:"typo3";s:12:"4.7.0-6.2.99";}}', 'Alexander Bigga', 'alexander.bigga@slub-dresden.de', 'albigdd', 'bf3a216b5023500ea385f10a74ea301a', 'Fixed error when event is not given in detail and subscription view', 'SLUB Dresden', 1000015, 0, 0),
(35959, 0, 'slub_events', 1, '1.0.17', 0, 0, 'SLUB: Event Registration', 'Tool for event registration and experts booking.\n\nThis extension is developped and used in production at the Saxony State and University Library (SLUB) Dresden, Germany.', 1, 0, 3, 1374655949, 'a:1:{s:7:"depends";a:3:{s:7:"extbase";s:3:"1.5";s:5:"fluid";s:3:"1.5";s:5:"typo3";s:12:"4.7.0-6.2.99";}}', 'Alexander Bigga', 'alexander.bigga@slub-dresden.de', 'albigdd', '5b6b22505800696937290932b529002c', 'Make the sender email address configurable by typoscript: ', 'SLUB Dresden', 1000017, 0, 0),
(35960, 0, 'slub_events', 1, '1.0.19', 0, 0, 'SLUB: Event Registration', 'Tool for event registration and experts booking.\n\nThis extension is developped and used in production at the Saxony State and University Library (SLUB) Dresden, Germany.', 1, 0, 3, 1375195813, 'a:1:{s:7:"depends";a:3:{s:7:"extbase";s:3:"1.5";s:5:"fluid";s:3:"1.5";s:5:"typo3";s:12:"4.7.0-6.2.99";}}', 'Alexander Bigga', 'alexander.bigga@slub-dresden.de', 'albigdd', 'ada50c94c1527eb682faad5397737a89', 'Some bugfixes for TYPO3 6.1: make a version switch for some deprecated functions; use the update()-method after modification of existent objects (not necessary before 6.1).', 'SLUB Dresden', 1000019, 0, 0),
(35961, 0, 'slub_events', 1, '1.0.26', 0, 0, 'SLUB: Event Registration', 'Tool for event registration and experts booking.\n\nThis extension is developped and used in production at the Saxony State and University Library (SLUB) Dresden, Germany.', 1, 0, 3, 1383840365, 'a:1:{s:7:"depends";a:3:{s:7:"extbase";s:3:"1.5";s:5:"fluid";s:3:"1.5";s:5:"typo3";s:12:"4.7.0-6.2.99";}}', 'Alexander Bigga', 'alexander.bigga@slub-dresden.de', 'albigdd', 'e0178c4e8872cc2735393ff30d73517a', 'Deleted the old OpenOffice Documentation and started with ReST. \n\nSmal bugfixes.', 'SLUB Dresden', 1000026, 0, 0),
(35962, 0, 'slub_events', 1, '1.1.0', 0, 0, 'SLUB: Event Registration', 'Tool for event registration and experts booking.\n\nThis extension is developped and used in production at the Saxony State and University Library (SLUB) Dresden, Germany.', 1, 0, 3, 1385735531, 'a:1:{s:7:"depends";a:3:{s:7:"extbase";s:3:"1.5";s:5:"fluid";s:3:"1.5";s:5:"typo3";s:12:"4.7.0-6.2.99";}}', 'Alexander Bigga', 'alexander.bigga@slub-dresden.de', 'albigdd', '3f1c520dee421bb2524a4c22c24d81a5', 'This adds a new feature to notify the contact person about every subscription not only if the subscription end is reached. This option is off by default. \n\nUpdated the ReST manual about typoscript settings and scheduler task.\n\nAdded fullcalendar feature. ', 'SLUB Dresden', 1001000, 0, 0),
(35963, 0, 'slub_events', 1, '1.1.1', 0, 0, 'SLUB: Event Registration', 'Tool for event registration and experts booking.\n\nThis extension is developped and used in production at the Saxony State and University Library (SLUB) Dresden, Germany.', 1, 0, 3, 1385735851, 'a:1:{s:7:"depends";a:3:{s:7:"extbase";s:3:"1.5";s:5:"fluid";s:3:"1.5";s:5:"typo3";s:12:"4.7.0-6.2.99";}}', 'Alexander Bigga', 'alexander.bigga@slub-dresden.de', 'albigdd', '48e41d9491bd2f5c8e77c2e4db51b0e9', 'Updated the ReST manual to right version number.', 'SLUB Dresden', 1001001, 0, 0),
(35964, 0, 'slub_events', 1, '1.1.5', 0, 0, 'SLUB: Event Registration', 'Tool for event registration and experts booking.\n\nThis extension is developped and used in production at the Saxony State and University Library (SLUB) Dresden, Germany.\n', 1, 0, 3, 1390409132, 'a:1:{s:7:"depends";a:3:{s:7:"extbase";s:3:"1.5";s:5:"fluid";s:3:"1.5";s:5:"typo3";s:12:"4.7.0-6.2.99";}}', 'Alexander Bigga', 'alexander.bigga@slub-dresden.de', 'albigdd', '98962966f4b0da0e542131ec4dddc6e3', 'Changed cache clearing if new events are added or modified to tag based clearing.\n\nAdded new error page in case the backend user didnt select a page or folder in the page tree.\n\nAdded extra fields to the TCA to make it a little easier to enter new event', 'SLUB Dresden', 1001005, 0, 0),
(35965, 0, 'slub_events', 1, '1.1.8', 0, 0, 'SLUB: Event Registration', 'Tool for event registration and experts booking.\n\nThis extension is developped and used in production at the Saxony State and University Library (SLUB) Dresden, Germany.', 1, 0, 3, 1392303544, 'a:1:{s:7:"depends";a:3:{s:7:"extbase";s:3:"1.5";s:5:"fluid";s:3:"1.5";s:5:"typo3";s:12:"4.7.0-6.2.99";}}', 'Alexander Bigga', 'alexander.bigga@slub-dresden.de', 'albigdd', '66de3fe13ace23898c6450571b455e4b', 'fixed issues in the backend module: \n\n- dont show hidden contacts, categories and locations\n- dont loose contacts if all are selected\n- add selectbox to easier select all contacts', 'SLUB Dresden', 1001008, 0, 0),
(35966, 0, 'slub_events', 1, '1.2.0', 0, 0, 'SLUB: Event Registration', 'Tool for event registration and experts booking.\n\nThis extension is developped and used in production at the Saxony State and University Library (SLUB) Dresden, Germany.', 1, 0, 3, 1395663787, 'a:1:{s:7:"depends";a:3:{s:7:"extbase";s:3:"1.5";s:5:"fluid";s:3:"1.5";s:5:"typo3";s:12:"4.7.0-6.2.99";}}', 'Alexander Bigga', 'alexander.bigga@slub-dresden.de', 'albigdd', '1717b00ee2a465b9d1e204e41b9e30e0', 'New feature: send emails to contact person if minimum number of subscribers is reached again due to cancellation;\n\nBugfix rendering of pagination in case no event exists at all.', 'SLUB Dresden', 1002000, 0, 0),
(35967, 0, 'slub_events', 1, '1.2.2', 0, 0, 'SLUB: Event Registration', 'Tool for event registration and experts booking.\n\nThis extension is developped and used in production at the Saxony State and University Library (SLUB) Dresden, Germany.', 1, 0, 3, 1399449311, 'a:1:{s:7:"depends";a:3:{s:7:"extbase";s:3:"1.5";s:5:"fluid";s:3:"1.5";s:5:"typo3";s:12:"4.7.0-6.2.99";}}', 'Alexander Bigga', 'alexander.bigga@slub-dresden.de', 'albigdd', '27c0ecf9c92704250c99ed97ab1c2aa9', 'Bugfix release for TYPO3 6.2.\n\n"Tx_SlubEvents_Domain_Model_Contact" was not found because of a CamelCase-typo.', 'SLUB Dresden', 1002002, 0, 0),
(35968, 0, 'slub_events', 1, '1.4.0', 0, 0, 'SLUB: Event Registration', 'Tool for event registration and experts booking.\n\nThis extension is developped and used in production at the Saxony State and University Library (SLUB) Dresden, Germany.', 1, 0, 3, 1406626448, 'a:1:{s:7:"depends";a:3:{s:7:"extbase";s:12:"4.7.0-6.2.99";s:5:"fluid";s:12:"4.7.0-6.2.99";s:5:"typo3";s:12:"4.7.0-6.2.99";}}', 'Alexander Bigga', 'alexander.bigga@slub-dresden.de', 'albigdd', '07d109fa9898aa9da125e7c352ebd106', '- list plugin  with new filters for disciplines, author, past event and ordering\n- knowledge bar categories are shown only in knowledgebar events\n- contact person images are shown in single view of events if present\n- more documentation\n\nIMPORTANT: Update', 'SLUB Dresden', 1004000, 0, 0),
(35969, 0, 'slub_events', 1, '1.4.1', 0, 0, 'SLUB: Event Registration', 'Tool for event registration and experts booking.\n\nThis extension is developped and used in production at the Saxony State and University Library (SLUB) Dresden, Germany.', 1, 0, 3, 1407399229, 'a:1:{s:7:"depends";a:3:{s:7:"extbase";s:12:"4.7.0-6.2.99";s:5:"fluid";s:12:"4.7.0-6.2.99";s:5:"typo3";s:12:"4.7.0-6.2.99";}}', 'Alexander Bigga', 'alexander.bigga@slub-dresden.de', 'albigdd', '12464a461dc061b7d5a491603c5df493', 'Different handling of localized categories to work with 4.7 and 6.2 the same way.', 'SLUB Dresden', 1004001, 0, 0),
