(36197, 0, 'multiblog', 1, '0.9.2', 0, 0, 'multiblog', 'A blog extension for typo3: Complete Frontend Editing of Blogentries, including blog widgets and comment system, multiple blogs in one installation possible. Easy to install and administration. Responsive Design, works perfectly with the extension responsive_template. TYPO3 4.7 or 6.1 required.', 1, 0, 3, 1373569945, 'a:1:{s:7:"depends";a:4:{s:3:"php";s:11:"5.2.0-0.0.0";s:5:"typo3";s:14:"4.5.dev-4.7.99";s:7:"extbase";s:12:"4.5.0-6.1.99";s:5:"fluid";s:12:"4.5.0-6.1.99";}}', 'Klaus Heuer', 'klaus.heuer@t3-developer.com', 'klaus_ger', '599291be2b1e7a62967cbe9af6e8d86b', 'First release. Installation and configuration see documentation. Live example: http://www.responsive-design.t3-developer.com/blog', 't3-developer.com', 9002, 0, 0),
(36198, 0, 'multiblog', 1, '0.9.6', 0, 0, 'multiblog', 'A blog extension for TYPO3: including several blog widgets, comment system, facebook, google and twitter sharing buttons and seo fields. Fully social individual meta-tags for each post. Works with TYPO3 6.2 and 6.1. Do NOT update old versions of multiblog - actual there is no update script for the new content structure.', 2, 0, 3, 1396425576, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:15:"6.1.00 - 6.2.99";}}', 'Klaus Heuer', 'klaus.heuer@t3-developer.com', 'klaus_ger', '8ad329cdf03257c92441a0d613fa2466', 'Rewritten on namespaces, works with TYPO3 6.1 and 6.2. Do not update from older multiblog versions.', 't3-developer.com', 9006, 0, 0),
(36199, 0, 'multiblog', 1, '0.9.7', 0, 0, 'multiblog', 'A blog extension for TYPO3: including several blog widgets, comment system, facebook, google and twitter sharing buttons and seo fields. Fully social individual meta-tags for each post. Works with TYPO3 6.2 and 6.1. Do NOT update old versions of multiblog - actual there is no update script for the new content structure.', 2, 0, 3, 1396513721, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:15:"6.1.00 - 6.2.99";}}', 'Klaus Heuer', 'klaus.heuer@t3-developer.com', 'klaus_ger', '33f760a057feb76b115d09f0fb9476c9', 'A blog extension for TYPO3: including several blog widgets, comment system, facebook, google and twitter sharing buttons and seo fields. Fully social individual meta-tags for each post. Works with TYPO3 6.2 and 6.1. Do NOT update old versions of multiblo', 't3-developer.com', 9007, 0, 0),
(36200, 0, 'multiblog', 1, '1.0.0', 0, 0, 'multiblog', 'A blog extension for TYPO3: including several blog widgets, comment system, facebook, google and twitter sharing buttons and seo fields. Fully social individual meta-tags for each post. Works with TYPO3 6.2 and 6.1. Do NOT update old versions of multiblog - actual there is no update script for the new content structure.', 2, 0, 3, 1398958273, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:15:"6.1.00 - 6.2.99";}}', 'Klaus Heuer', 'klaus.heuer@t3-developer.com', 'klaus_ger', 'c523e0a622fdbba4db71af9b03644dd7', 'A Blog Extension for TYPO3 with several widgets, a comment system and social sharing.\r\nNew in Version 1.0.0: \r\nAdded a complete fontend editing for the blog: write posts, approve comments, edit kategories and set up your blog in frontend forms for easy bl', 't3-developer.com', 1000000, 0, 0),
(36201, 0, 'multiblog', 1, '1.0.1', 0, 0, 'multiblog', 'A blog extension for TYPO3: complete Frontend editig of a blog, including several blog widgets, comment system, facebook, google and twitter sharing buttons and seo fields. Fully social individual meta-tags for each post. Works with TYPO3 6.2 and 6.1.', 2, 0, 3, 1399190508, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:15:"6.1.00 - 6.2.99";}}', 'Klaus Heuer', 'klaus.heuer@t3-developer.com', 'klaus_ger', '153415fd739ccffb2656e07e3f18209b', 'Improved storage handling of post categories, add some CSS stylings.', 't3-developer.com', 1000001, 1, 0),
