(36245, 0, 'cf_lifetime_patch', 1, '1.0.0', 0, 0, 'Caching Framework Lifetime Patch (rootline and pag', 'Fixes invalid setting of cf_cache_rootline and cf_cache_pagesection lifetime which results in cache recreation after 1 hour. The expiry timestamps are set to "unlimited lifetime" (default) or to a user defined value. Fixes http://forge.typo3.org/issues/50231', 2, 0, 4, 1374708483, 'a:0:{}', 'Sven Tappert', 'tappert@sven-t.de', 'tappert', '655fabcf0dec6d650d8613d14e8c5a40', 'Fixes http://forge.typo3.org/issues/50231. Uses hook. Currently for 6.x branch of Typo3 only.\r\n', 'SvenT', 1000000, 0, 0),
(36246, 0, 'cf_lifetime_patch', 1, '1.1.0', 0, 0, 'Caching Framework Lifetime Patch', 'Fixes invalid setting of lifetime in caches pagesection (and rootline in Typo3 6.x). \r\n\r\nIn typo3 6.X a hook is used which is safe.\r\n\r\nIn typo3 4.X an XCLASS is used to extend t3lib_TStemplate - might conflict with other extensions.\r\n\r\nFixes http://forge.typo3.org/issues/50231 and http://forge.typo3.org/issues/39295.', 2, 0, 4, 1374726326, 'a:0:{}', 'Sven Tappert', 'tappert@sven-t.de', 'tappert', '1a4b16b1604fa6c9da2eb6643d4fe07a', 'Added patches for typo3 4.5 - 4.7. \r\n\r\nXCLASS used for 4.x branches to extend "t3lib_TStemplate" - so conflicts might occur.', 'SvenT', 1001000, 0, 0),
(36247, 0, 'cf_lifetime_patch', 1, '1.1.1', 0, 0, 'Caching Framework Lifetime Patch', 'Fixes invalid setting of lifetime in caches pagesection (and rootline in Typo3 6.x). \r\n\r\nIn typo3 6.X a hook is used which is safe.\r\n\r\nIn typo3 4.X an XCLASS is used to extend t3lib_TStemplate - might conflict with other extensions.\r\n\r\nFixes http://forge.typo3.org/issues/50231 and http://forge.typo3.org/issues/39295.', 2, 0, 4, 1374728631, 'a:0:{}', 'Sven Tappert', 'tappert@sven-t.de', 'tappert', '2b48dfc619a10664464ba8b92fc2fa05', 'Updated typo3 version compatibility.', 'SvenT', 1001001, 0, 0),
(36248, 0, 'cf_lifetime_patch', 1, '1.1.2', 0, 0, 'Caching Framework Lifetime Patch', 'Fixes invalid setting of lifetime in caches pagesection (and rootline in Typo3 6.x). \r\n\r\nIn typo3 6.X a hook is used which is safe.\r\n\r\nIn typo3 4.X an XCLASS is used to extend t3lib_TStemplate - might conflict with other extensions.\r\n\r\nFixes http://forge.typo3.org/issues/50231 and http://forge.typo3.org/issues/39295.', 2, 0, 4, 1374795065, 'a:0:{}', 'Sven Tappert', 'tappert@sven-t.de', 'tappert', '549db5199947e75bd12430cb22560a17', 'Added manual (and extension icon).', 'SvenT', 1001002, 0, 0),
(36249, 0, 'cf_lifetime_patch', 1, '1.2.0', 0, 0, 'Caching Framework Lifetime Patch', 'Fixes invalid setting of lifetime in caches pagesection (and rootline in Typo3 6.x). \r\n\r\nIn typo3 6.X a hook is used which is safe.\r\n\r\nIn typo3 4.X an XCLASS is used to extend t3lib_TStemplate - might conflict with other extensions.\r\n\r\nFixes http://forge.typo3.org/issues/50231 and http://forge.typo3.org/issues/39295.', 2, 0, 4, 1375457858, 'a:0:{}', 'Sven Tappert', 'tappert@sven-t.de', 'tappert', 'ab09aa05430bdd2bfb3f7ce52df9151e', 'Removed XCLASS and Hook usage. The extension now just manipulates the config settings.', 'SvenT', 1002000, 0, 0),
(36250, 0, 'cf_lifetime_patch', 1, '1.2.1', 0, 0, 'Caching Framework Lifetime Patch', 'Easy setting of cache lifetime for pagesection cache (and rootline cache in Typo3 6.x). No XCLASSes or Hooks used anymore. \r\nFixes http://forge.typo3.org/issues/50231 and http://forge.typo3.org/issues/39295.', 2, 0, 4, 1375458414, 'a:0:{}', 'Sven Tappert', 'tappert@sven-t.de', 'tappert', 'b0c1206e7745668fd138814a327f895c', 'Minor update to 1.2.0: modified extension description.', 'SvenT', 1002001, 1, 0),
(36251, 0, 'infinite_scroll_gallery', 1, '1.2.0', 0, 0, 'Infinite Scroll Gallery', 'Display images as you scroll. Images can also be displayed within a slideshow.', 1, 0, 3, 1374743865, 'a:1:{s:7:"depends";a:5:{s:5:"typo3";s:12:"6.1.1-6.1.99";s:5:"media";s:12:"1.0.0-1.0.99";s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Fabien Udriot, Sylvain Tissot', 'fabien.udriot@ecodev.ch, sylvain.tissot@ecodev.ch', 'ecodev', '54e92f3f9c914e1d7f3d37a002b4daf8', 'First upload', 'Ecodev', 1002000, 0, 0),
(36252, 0, 'infinite_scroll_gallery', 1, '1.2.2', 0, 0, 'Infinite Scroll Gallery', 'Display images as you scroll. Images can also be displayed within a slideshow.', 1, 0, 3, 1374744457, 'a:1:{s:7:"depends";a:5:{s:5:"typo3";s:12:"6.1.1-6.1.99";s:5:"media";s:12:"1.0.0-1.0.99";s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Fabien Udriot, Sylvain Tissot', 'fabien.udriot@ecodev.ch, sylvain.tissot@ecodev.ch', 'ecodev', 'ad0b8c0a453018b79230368c23df25d2', 'Full change log https://github.com/Ecodev/infinite_scroll_gallery/compare/1.2.0...1.2.2', 'Ecodev', 1002002, 1, 0),
