(36403, 0, 'content_designer', 1, '2.0.0', 0, 0, 'Content Designer', 'Quickly and easily create new content elements with TypoScript without a new extension to write. Based on flexforms and TypoScript. Useful element already included (Google Maps, Google Maps static image, YouTube, etc.).  NEW: TSconfig Conditions to control the fields depented on colPos or any other Content Element field. Also you can now disable Drag and Drop for CTypes.', 2, 0, 3, 1391343110, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:12:"6.0.0-6.1.99";s:7:"extbase";s:10:"6.0-6.9.99";s:5:"fluid";s:10:"6.0-6.9.99";}}', 'Hendrik Reimers (kern23.de)', 'kontakt@kern23.de', 'kern23', '386ebf9097bfbde1b4f1a8ffe90bc7a1', 'Bugfixes and new Features. For example... Control the drag and drop dependent of the CType to disable the dragging on columns.', 'KERN23.de', 2000000, 0, 0),
(36404, 0, 'content_designer', 1, '2.1.0', 0, 0, 'Content Designer', 'Quick and easy create new Content Elements, page properties, or just disable Drag and Drop of Elements. Just with TypoScript or Flexforms. Useful examples, like google maps, youtube, etc already included.', 2, 0, 3, 1392796581, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:12:"6.0.0-6.1.99";s:7:"extbase";s:10:"6.0-6.9.99";s:5:"fluid";s:10:"6.0-6.9.99";}}', 'Hendrik Reimers (kern23.de)', 'kontakt@kern23.de', 'kern23', '53c9715d7c0989f3285603985e975563', 'New features: extend Page properties. Code optimized. See manual eq changelog for more info.', 'KERN23.de', 2001000, 0, 0),
(36405, 0, 'content_designer', 1, '2.1.1', 0, 0, 'Content Designer', 'Quick and easy create new Content Elements, page properties, or just disable Drag and Drop of Elements. Just with TypoScript or Flexforms. Useful examples, like google maps, youtube, etc already included.', 2, 0, 3, 1392915555, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:12:"6.0.0-6.1.99";s:7:"extbase";s:10:"6.0-6.9.99";s:5:"fluid";s:10:"6.0-6.9.99";}}', 'Hendrik Reimers (kern23.de)', 'kontakt@kern23.de', 'kern23', '1e7e122614e67d323273946d3d88af5a', 'Small bugfix of the google Maps Element.', 'KERN23.de', 2001001, 0, 0),
(36406, 0, 'content_designer', 1, '2.1.2', 0, 0, 'Content Designer', 'Quick and easy create new Content Elements, page properties, or just disable Drag and Drop of Elements. Just with TypoScript or Flexforms. Useful examples, like google maps, youtube, etc already included.', 2, 0, 3, 1393050958, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:12:"6.0.0-6.1.99";s:7:"extbase";s:10:"6.0-6.9.99";s:5:"fluid";s:10:"6.0-6.9.99";}}', 'Hendrik Reimers (kern23.de)', 'kontakt@kern23.de', 'kern23', '19277a55311b35c5b11bff13ccbdfd9d', 'Fixed bug by adding to the NewContentElementWizard. Thanks to Martin Keck!', 'KERN23.de', 2001002, 0, 0),
