(36539, 0, 'mm_forum_blog', 1, '1.0.0', 0, 0, 'Blog comments with mm_forum', 't3blog comments are also written to the mm_forum topic created by mm_forum_comments.', 0, 0, 2, 1379104040, 'a:1:{s:7:"depends";a:5:{s:3:"cms";s:0:"";s:8:"mm_forum";s:11:"1.9.0-0.0.0";s:17:"mm_forum_comments";s:11:"1.1.0-0.0.0";s:6:"t3blog";s:11:"0.9.1-0.0.0";s:5:"typo3";s:12:"4.3.0-4.5.99";}}', 'Hauke Hain', 'hhpreuss@googlemail.com', 'acquire', '475d7e2e8048c37e13478298549971e4', 'Initial upload - unchanged since 2010.\r\nWorks with TYPO3 4.5 and mm_forum 1.9 (SVN).', '', 1000000, 0, 0),
(36540, 0, 'mm_forum_blog', 1, '1.0.1', 0, 0, 'Blog comments with mm_forum', 't3blog comments are also written to the mm_forum topic created by mm_forum_comments.', 5, 0, 2, 1379104367, 'a:1:{s:7:"depends";a:5:{s:3:"cms";s:0:"";s:8:"mm_forum";s:11:"1.9.0-0.0.0";s:17:"mm_forum_comments";s:11:"1.1.0-0.0.0";s:6:"t3blog";s:11:"0.9.1-0.0.0";s:5:"typo3";s:12:"4.3.0-4.5.99";}}', 'Hauke Hain', 'hhpreuss@googlemail.com', 'acquire', '28f70b0dd3eb04453980270026f058d1', 'This extension is not maintained anymore because mm_forum is not TYPO3 6.x ready yet and lacks an active development.', '', 1000001, 1, 0),
(36541, 0, 'groupdocssignature', 1, '0.0.1', 0, 0, 'GroupDocs Signature', 'GroupDocs Documents Signature plugin to embed GroupDocs Signature', 0, 0, 3, 1379267515, 'a:0:{}', 'GroupDocs Marketplace Team', 'marketplace@groupdocs.com', 'groupdocs', 'ceeb5eb5d1f9a5810cae8ca14db52736', 'The GroupDocs Signature plugin for Typo3 CMS allows you to embed signature forms to your websites and helps collect online signatures from partners easily.\r\n\r\nGroupDocs Signature is a web-based app used to sign documents and collect electronic signatures.', '', 1, 0, 0),
(36542, 0, 'groupdocssignature', 1, '1.1.0', 0, 0, 'GroupDocs Signature', 'GroupDocs Documents Signature plugin to embed GroupDocs Signature', 0, 0, 3, 1379309597, 'a:0:{}', 'GroupDocs Marketplace Team', 'marketplace@groupdocs.com', 'groupdocs', '9ccb70ba5f00c5d5baadc80afe5f121c', 'GroupDocs Signature promotes a paperless environment. Avoid printing, or faxing documents. Just create a signature form from your GroupDocs account and embed it into your Typo3 website. Invite partners to sign documents online. Different signature options', '', 1001000, 1, 0),
(36543, 0, 'groupdocssignature', 1, '1.0.1', 0, 0, 'GroupDocs.Signature for Cloud', 'The GroupDocs.Signature for Cloud plugin for Typo3 CMS allows you to embed signature forms to your websites and helps collect online signatures from partners easily.\n\nGroupDocs.Signature is a web-based app used to sign documents and collect electronic signatures. Simply create forms, add signature fields and email documents to your partners. Once the document is signed, you and them receive instant notification. No new software installations are needed. Sign documents from your desk with a web-browser.', 0, 0, 3, 1413982184, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"4.5.0-6.1.99";}}', 'GroupDocs Marketplace Team', 'marketplace@groupdocs.com', 'groupdocs', 'f6df3aa714f64c50e20696290f758972', 'The GroupDocs.Signature for Cloud plugin for Typo3 CMS allows you to embed signature forms to your websites and helps collect online signatures from partners easily.\r\n\r\nGroupDocs.Signature is a web-based app used to sign documents and collect electronic s', '', 1000001, 0, 0),
(36544, 0, 'groupdocs_annotation', 1, '0.0.1', 0, 0, 'groupdocsannotation', 'GroupDocs Documents Annotation plugin to embed GroupDocs Annotation', 0, 0, 3, 1379267722, 'a:0:{}', 'GroupDocs Marketplace Team', 'marketplace@groupdocs.com', 'groupdocs', 'c1ec72b57db42f4b5dea24b0dbd89ded', 'Annotate PDF, Word, Excel, or image files online with GroupDocs Annotation from your Typo3 websites.\r\n\r\nGroupDocs Annotation is a web-based app for sharing and annotating documents. Invite colleagues to review documents and collaborate in real-time. Add c', '', 1, 0, 0),
(36545, 0, 'groupdocs_annotation', 1, '1.1.0', 0, 0, 'groupdocsannotation', 'GroupDocs Documents Annotation plugin to embed GroupDocs Annotation', 0, 0, 3, 1379309395, 'a:0:{}', 'GroupDocs Marketplace Team', 'marketplace@groupdocs.com', 'groupdocs', '15921837d06bef7580cf6f6e76f2c655', 'GroupDocs Annotation lets you annotate text documents or images using your web-browser. It is beneficial for publishing teams, marketing teams, or product managers who need to constantly interact and collaborate with other groups for feedback and review. ', '', 1001000, 1, 0),
(36546, 0, 'groupdocs_annotation', 1, '1.0.1', 0, 0, 'GroupDocs.Annotation for Cloud', 'Annotate PDF, Word, Excel, or image files online with GroupDocs Annotation from your Typo3 websites.\n\nGroupDocs Annotation is a web-based app for sharing and annotating documents. Invite colleagues to review documents and collaborate in real-time. Add comments, exchange ideas, and resolve conflicts. Speed up the review cycle and improve communication channel between teams with GroupDocs.Annotation.', 0, 0, 3, 1413982884, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"4.5.0-6.1.99";}}', 'GroupDocs Marketplace Team', 'marketplace@groupdocs.com', 'groupdocs', 'f11a2123b3f14b234b2dba9f77210571', 'Annotate PDF, Word, Excel, or image files online with GroupDocs.Annotation from your Typo3 websites.\r\n\r\nGroupDocs.Annotation is a web-based app for sharing and annotating documents. Invite colleagues to review documents and collaborate in real-time. Add c', '', 1000001, 0, 0),
(36547, 0, 'groupdocs_comparison', 1, '0.0.1', 0, 0, 'GroupDocs Comparison', 'GroupDocs Documents Comparison plugin to embed GroupDocs Comparison', 0, 0, 3, 1379267915, 'a:0:{}', 'GroupDocs Marketplace Team', 'marketplace@groupdocs.com', 'groupdocs', '49de09aef0c30fa69bcfa38916a819cd', 'The GroupDocs Comparison plugin for Typo3 CMS allows you to embed and compare two Word documents, as well as PDF files and Excel spreadsheets, from within your website.\r\n\r\nGroupDocs Comparison is a web-based app that lets you compare documents online usin', '', 1, 0, 0),
(36548, 0, 'groupdocs_comparison', 1, '1.1.0', 0, 0, 'GroupDocs Comparison', 'GroupDocs Documents Comparison plugin to embed GroupDocs Comparison', 0, 0, 3, 1379310017, 'a:0:{}', 'GroupDocs Marketplace Team', 'marketplace@groupdocs.com', 'groupdocs', '4b594cc2db03cb9593b38a15967f87b6', 'GroupDocs document comparison tool offers great value to professionals working in different industry verticals. Save time on finding errors or differences in documents manually. Upload two files to your GroupDocs account and run the comparison tool to ch', '', 1001000, 1, 0),
(36549, 0, 'groupdocs_comparison', 1, '1.0.1', 0, 0, 'GroupDocs.Comparison for Cloud', 'The GroupDocs.Comparison for Cloud plugin for Typo3 CMS allows you to embed and compare two Word documents, as well as PDF files and Excel spreadsheets, from within your website.\n\nGroupDocs.Comparison is a web-based app that lets you compare documents online using a browser. Simply upload two Word documents and let GroupDocs Comparison find the difference between them. It even allows you to merge the differences and export the document to a Word file!', 0, 0, 3, 1413983873, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"4.5.0-6.1.99";}}', 'GroupDocs Marketplace Team', 'marketplace@groupdocs.com', 'groupdocs', 'fb9b22963cbd8b2989831c75f29cc1b9', 'The GroupDocs.Comparison for Cloud plugin for Typo3 CMS allows you to embed and compare two Word documents, as well as PDF files and Excel spreadsheets, from within your website.\r\n\r\nGroupDocs.Comparison is a web-based app that lets you compare documents o', '', 1000001, 0, 0),
(36550, 0, 'groupdocs_assembly', 1, '0.0.1', 0, 0, 'groupdocsassembly', 'GroupDocs Documents Assembly plugin to embed GroupDocs Assembly', 0, 0, 3, 1379268041, 'a:0:{}', 'GroupDocs Marketplace Team', 'marketplace@groupdocs.com', 'groupdocs', 'f83fbbe87d13f496643eb72b47bd8d43', 'The GroupDocs Assembly plugin for Typo3 CMS allows you to embed questionnaire forms in a website to easily collect information from users.\r\n\r\nGroupDocs Assembly is an online document generation service that allows you to add fields to a template and share', '', 1, 0, 0),
(36551, 0, 'groupdocs_assembly', 1, '1.1.0', 0, 0, 'groupdocsassembly', 'GroupDocs Documents Assembly plugin to embed GroupDocs Assembly', 0, 0, 3, 1379309843, 'a:0:{}', 'GroupDocs Marketplace Team', 'marketplace@groupdocs.com', 'groupdocs', '22a62da9f487b3130bc43e403564cd46', 'GroupDocs document assembly tool can be used in to gather sensitive business information. Be it NDAs, contracts, applications, invoices, or other business documents, a service that helps you automate document generation speeds up the transaction cycle. G', '', 1001000, 1, 0),
(36552, 0, 'groupdocs_assembly', 1, '1.0.1', 0, 0, 'GroupDocs.Assembly for Cloud', 'The GroupDocs.Assembly for Cloud plugin for Typo3 CMS allows you to embed questionnaire forms in a website to easily collect information from users.\n\nGroupDocs.Assembly is an online document generation service that allows you to add fields to a template and share it with partners to gather information. It then generates a new document that retains the original layout and structure but contains user-entered data.', 0, 0, 3, 1413983410, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"4.5.0-6.1.99";}}', 'GroupDocs Marketplace Team', 'marketplace@groupdocs.com', 'groupdocs', '02f322e93032aaac069a741020c3aff4', 'The GroupDocs.Assembly for Cloud plugin for Typo3 CMS allows you to embed questionnaire forms in a website to easily collect information from users.\r\n\r\nGroupDocs.Assembly is an online document generation service that allows you to add fields to a template', '', 1000001, 0, 0),
