(36788, 0, 'jh_smilie_viewhelper', 1, '0.0.3', 0, 0, 'Smilie Viewhelper', 'This extensions provides two fluid viewhelpers for EXT:smilie', 2, 0, 3, 1390937739, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"4.5.0-6.1.99";s:6:"smilie";s:0:"";}}', 'Jonathan Heilmann', 'mail@jonathan-heilmann.de', 'roboterfreak', '1896a9d71d83f994b45939bc633b077c', 'Added ReST documentation, removed empty TypoScript static inclusion and added dependencies', '', 3, 1, 0),
(36789, 0, 'formhandler_backend', 1, '0.1.0', 0, 0, 'Formhandler Backend', 'Formhandler is a very flexibel form handling tool. Due to its flexibility, it is hard to integrate a backend GUI. Instead of a GUI, the "formhandler backend" provides a mechanism to build file and typoscript templates from scratch.\n\nThis makes it possible to quickly generate the base of a working form, which thereafter can be configured in detail. Or, it will be possible to let a user edit parts of a predefined form without requesting programming knowledge.', 0, 0, 1, 1384871783, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:11:"formhandler";s:0:"";s:5:"typo3";s:11:"4.5.0-6.1.0";}}', 'Michel Baeriswyl', 'formhandler_backend@pragmas.ch', 'pragmas', '4b61d3d1d10a7a5545c7329e9cc1d838', 'Initial public release', '', 1000, 0, 0),
(36790, 0, 'formhandler_backend', 1, '0.1.1', 0, 0, 'Formhandler Backend', 'Formhandler is a very flexible form handling tool. Due to its flexibility, it is hard to integrate a backend GUI. Instead of a GUI, the "formhandler backend" provides a mechanism to build file and typoscript templates from scratch.\r\n\r\nThis makes it possible to quickly generate the base of a working form, which thereafter can be configured in detail. Or, it will be possible to let a user edit parts of a predefined form without requesting programming knowledge.', 1, 0, 1, 1452009288, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:11:"formhandler";s:0:"";s:5:"typo3";s:12:"6.2.0-6.2.99";}}', 'Michel Baeriswyl', 'formhandler_backend@pragmas.ch', 'pragmas', '6daf5af5da95da1c1769420c02836044', 'Formhandler is a very flexibel form handling tool. Due to its flexibility, it is hard to integrate a backend GUI. Instead of a GUI, the "formhandler backend" provides a mechanism to build file and typoscript templates from scratch. This makes it possible ', '', 1001, 1, 0),
