(36792, 0, 'ajaxfilebrowser', 1, '0.2.0', 0, 0, 'Ajax file browser - GPG support', 'File browser. Ajax. Can browse directories beyond typo3. Protect files with GPG encryption and let only logged user download them-', 1, 0, 2, 1385028753, 'a:0:{}', 'Lebrija invest s.r.o.', 'petr.snobl@lebrija.cz', 'petrsnobl', '4724a492c8fe58ffd77e7bf8c2702019', 'Initial upload. Working plugin.', '', 2000, 0, 0),
(36793, 0, 'ajaxfilebrowser', 1, '0.2.1', 0, 0, 'Ajax file browser - GPG support', 'File browser. Ajax. Can browse directories beyond typo3. Protect files with GPG encryption and let only logged user download them-', 2, 0, 2, 1386935359, 'a:1:{s:7:"depends";a:2:{s:3:"cms";s:0:"";s:5:"typo3";s:12:"4.5.0-4.7.99";}}', 'Lebrija invest s.r.o.', 'petr.snobl@lebrija.cz', 'petrsnobl', '10e0cde790f775a22a014c625d049d7e', 'Fixed bug. GPG key was not passed to GPG command.  Added option to choose between force download dialog  or just output the content.  Now zou can choose if zou want to strip out the GPG suffix on encoding files.', '', 2001, 0, 0),
