(36810, 0, 'mfc_author', 1, '2.0.0', 0, 0, 'Author', 'Gives you the possibility to add author informations into every page or tx_news entry', 2, 0, 4, 1411546591, 'a:2:{s:7:"depends";a:2:{s:3:"php";s:12:"5.3.0-5.5.99";s:5:"typo3";s:12:"6.0.1-6.2.99";}s:8:"suggests";a:1:{s:4:"news";s:12:"3.0.1-3.9.99";}}', 'Simon Schmidt', 'typo3@marketing-factory.de', 'sfsmfc', 'b84b1f946dfce4726535fc04a8cff058', 'New version works with FAL for the author image. Version needs at least TYPO3 6.x. For lower TYPO3 version use extension version 1.x.', 'Marketing Factory Consulting GmbH', 2000000, 1, 0),
(36811, 0, 'no_opcode_cache_check', 1, '1.0.0', 0, 0, 'Hide opcode cache check in system environment chec', 'In case you are running your TYPO3 system in an environment where no opcode cache is available and you do not want to see errors in the system environment check about that (which causes a lot of emails using the system status update cron job) this extension is for you.', 2, 0, 4, 1385762244, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"5.2.0-0.0.0";s:5:"typo3";s:12:"6.0.0-6.2.99";}}', 'Adrian Dymorz', 'dev@adrian.dymorz.ch', 'adymorz', '766dcad7f4ed39184ad2c686d13642e9', 'First release', '', 1000000, 0, 0),
