(36814, 0, 'nkhyphenation', 1, '1.0.0', 0, 0, 'Server side hyphenation for TYPO3', 'Adds soft hyphenation capabilities to TYPO3. Provides a ViewHelper, a stdWrap property and some static templates to enable hyphenation.', 1, 0, 2, 1385928552, 'a:1:{s:7:"depends";a:4:{s:5:"typo3";s:12:"6.0.0-6.1.99";s:3:"php";s:12:"5.3.0-5.5.99";s:5:"fluid";s:12:"1.3.0-6.1.99";s:7:"extbase";s:12:"1.3.0-6.1.99";}}', 'Jost Baron', 'j.baron@netzkoenig.de', 'jost_baron', '8a8ae93fe535b19b0e262807a47bb16c', 'Initial release.', 'Netzknig GbR', 1000000, 0, 0),
(36815, 0, 'nkhyphenation', 1, '1.0.2', 0, 0, 'Server side hyphenation for TYPO3', 'Adds soft hyphenation capabilities to TYPO3. Provides a ViewHelper, a stdWrap property and some static templates to enable hyphenation.', 1, 0, 2, 1388842461, 'a:1:{s:7:"depends";a:4:{s:5:"typo3";s:12:"6.0.0-6.1.99";s:3:"php";s:12:"5.3.7-5.5.99";s:5:"fluid";s:12:"6.0.0-6.1.99";s:7:"extbase";s:12:"6.0.0-6.1.99";}}', 'Jost Baron', 'j.baron@netzkoenig.de', 'jost_baron', 'c9ebf78479695a00d6c104995840c858', 'Small bugfixes, minor documentation updates.\r\nChangelog in repository: https://github.com/JostBaron/typo3-nkhyphenation', 'Netzknig GbR', 1000002, 0, 0),
(36816, 0, 'nkhyphenation', 1, '1.0.3', 0, 0, 'Server side hyphenation for TYPO3', 'Adds soft hyphenation capabilities to TYPO3. Provides a ViewHelper, a stdWrap property and some static templates to enable hyphenation.', 1, 0, 2, 1388926491, 'a:1:{s:7:"depends";a:4:{s:5:"typo3";s:12:"6.0.0-6.2.99";s:3:"php";s:12:"5.3.7-5.5.99";s:5:"fluid";s:12:"6.0.0-6.2.99";s:7:"extbase";s:12:"6.0.0-6.2.99";}}', 'Jost Baron', 'j.baron@netzkoenig.de', 'jost_baron', 'd77a084cb63c56fae0ecbb422b04d06e', 'Compatibility to 6.2beta3, bugfix in static templates for CSC (hyphenation is now executed after parseFunc_RTE).', 'Netzknig GbR', 1000003, 0, 0),
(36817, 0, 'nkhyphenation', 1, '1.0.4', 0, 0, 'Server side hyphenation for TYPO3', 'Adds soft hyphenation capabilities to TYPO3. Provides a ViewHelper, a stdWrap property and some static templates to enable hyphenation.', 1, 0, 2, 1390163004, 'a:1:{s:7:"depends";a:4:{s:5:"typo3";s:12:"6.0.0-6.2.99";s:3:"php";s:12:"5.3.7-5.5.99";s:5:"fluid";s:12:"6.0.0-6.2.99";s:7:"extbase";s:12:"6.0.0-6.2.99";}}', 'Jost Baron', 'j.baron@netzkoenig.de', 'jost_baron', 'fdc707a8a16f9ff43c771ee0fbbe2908', 'Bugfix release, fixes encoding problems when the php default_charset is not utf8 and makes unit tests work again in 6.2', 'Netzknig GbR', 1000004, 1, 0),
(36818, 0, 'arcavias', 1, '0.9.0', 0, 0, 'Arcavias', 'Flexible, high performance shop system', 1, 0, 3, 1385988508, 'a:2:{s:7:"depends";a:6:{s:3:"php";s:13:"5.2.0-5.99.99";s:5:"typo3";s:12:"4.5.0-6.2.99";s:7:"extbase";s:13:"1.3.2-6.99.99";s:9:"scheduler";s:13:"1.1.0-6.99.99";s:18:"sr_feuser_register";s:13:"2.6.3-3.99.99";s:18:"static_info_tables";s:13:"1.8.0-6.99.99";}s:9:"conflicts";a:1:{s:14:"jquerycolorbox";s:11:"0.0.0-0.0.1";}}', 'Metaways Software Engineering Team', 'typo3@metaways.de', 'nsendetzky', '72bd8485b7c478677cbc456be7ec69c1', 'Initial TER release of Arcavias TYPO3 extension\n\nOlder versions can be found at http://www.arcavias.com/en/download.html', 'Metaways Infosystems GmbH', 9000, 0, 0),
(36819, 0, 'arcavias', 1, '0.9.1', 0, 0, 'Arcavias', 'Flexible, high performance shop system', 1, 0, 3, 1387204752, 'a:2:{s:7:"depends";a:5:{s:3:"php";s:13:"5.2.0-5.99.99";s:5:"typo3";s:12:"4.5.0-6.2.99";s:7:"extbase";s:13:"1.3.2-6.99.99";s:9:"scheduler";s:13:"1.1.0-6.99.99";s:18:"static_info_tables";s:13:"1.8.0-6.99.99";}s:9:"conflicts";a:1:{s:14:"jquerycolorbox";s:11:"0.0.0-0.0.1";}}', 'Metaways Software Engineering Team', 'typo3@metaways.de', 'nsendetzky', '61f588a3e2ab4f5cd792045dbb963204', 'sr_feuser_register is optional now and only a suggestion like datamints_feuser. Fixes some bugs related to selection products and improves performance when rebuilding the catalog index. Also contains minor fixes for the admin interface and frontend', 'Metaways Infosystems GmbH', 9001, 0, 0),
(36820, 0, 'arcavias', 1, '0.10.0', 0, 0, 'Arcavias', 'Flexible, high performance shop system', 1, 0, 3, 1391441044, 'a:3:{s:7:"depends";a:5:{s:3:"php";s:13:"5.2.0-5.99.99";s:5:"typo3";s:12:"4.5.0-6.2.99";s:7:"extbase";s:13:"1.3.2-6.99.99";s:9:"scheduler";s:13:"1.1.0-6.99.99";s:18:"static_info_tables";s:13:"1.8.0-6.99.99";}s:9:"conflicts";a:1:{s:14:"jquerycolorbox";s:11:"0.0.0-0.0.1";}s:8:"suggests";a:3:{s:7:"realurl";s:14:"1.10.0-1.99.99";s:16:"datamints_feuser";s:13:"0.6.4-1.99.99";s:18:"sr_feuser_register";s:13:"2.6.3-3.99.99";}}', 'Metaways Software Engineering Team', 'typo3@metaways.de', 'nsendetzky', '5b69a2d743456b8b884cde06797f337b', 'Now completely translatable and available in English, German, French and Spanish. High code coverage and proven to work with TYPO3 4.5 till 6.1 by unit tests. Full facetted search is now available even with 100000 products. Improved usability in the fron', 'Metaways Infosystems GmbH', 10000, 0, 0),
(36821, 0, 'arcavias', 1, '1.0.0', 0, 0, 'Arcavias', 'Flexible, high performance shop system', 2, 0, 3, 1396430491, 'a:0:{}', 'Metaways Software Engineering Team', 'typo3@metaways.de', 'nsendetzky', '3800aa6fe018552075f72b4913c7882a', 'Fully compatible with TYPO3 6.2 LTS and will be supported for three years, too. Creates some demo data during installation for a completely working demo shop out of the box. The standard front-end layout is more robust when embedded into existing layouts', 'Metaways Infosystems GmbH', 1000000, 0, 0),
(36822, 0, 'arcavias', 1, '1.0.1', 0, 0, 'Arcavias shop system', 'Arcavias is a flexible, high performance shop system available in multiple languages. Several plugins e.g. for facetted search, product listing, detail view, basket, checkout process and other parts of a shop are available. Furthermore, Arcavias offers powerful interfaces to integrate CRM and ERP systems as well as payment and delivery service providers', 2, 0, 3, 1398869663, 'a:3:{s:7:"depends";a:5:{s:3:"php";s:13:"5.2.0-5.99.99";s:5:"typo3";s:12:"4.5.0-6.2.99";s:7:"extbase";s:13:"1.3.2-6.99.99";s:9:"scheduler";s:13:"1.1.0-6.99.99";s:18:"static_info_tables";s:13:"1.8.0-6.99.99";}s:9:"conflicts";a:1:{s:14:"jquerycolorbox";s:11:"0.0.0-0.0.1";}s:8:"suggests";a:3:{s:7:"realurl";s:14:"1.10.0-1.99.99";s:16:"datamints_feuser";s:13:"0.6.4-1.99.99";s:18:"sr_feuser_register";s:13:"2.6.3-3.99.99";}}', 'Metaways Software Engineering Team', 'typo3@metaways.de', 'nsendetzky', '972e787d9255ff1b80d8ef59a9c181a2', 'Bugfix release with improved Windows compatibility, fixes in the catalog detail view, new autofill basket plugin, cleanup of removed products from categories and many fixes and improvements in the admin interface', 'Metaways Infosystems GmbH', 1000001, 0, 0),
(36823, 0, 'arcavias', 1, '1.1.0', 0, 0, 'Arcavias shop system', 'Arcavias is a flexible, high performance shop system available in multiple languages. Several plugins e.g. for facetted search, product listing, detail view, basket, checkout process and other parts of a shop are available. Furthermore, Arcavias offers powerful interfaces to integrate CRM and ERP systems as well as payment and delivery service providers', 2, 0, 3, 1401745095, 'a:3:{s:7:"depends";a:5:{s:3:"php";s:13:"5.2.0-5.99.99";s:5:"typo3";s:12:"4.5.0-6.2.99";s:7:"extbase";s:13:"1.3.2-6.99.99";s:9:"scheduler";s:13:"1.1.0-6.99.99";s:18:"static_info_tables";s:13:"1.8.0-6.99.99";}s:9:"conflicts";a:1:{s:14:"jquerycolorbox";s:11:"0.0.0-0.0.1";}s:8:"suggests";a:3:{s:7:"realurl";s:14:"1.10.0-1.99.99";s:16:"datamints_feuser";s:13:"0.6.4-1.99.99";s:18:"sr_feuser_register";s:13:"2.6.3-3.99.99";}}', 'Metaways Software Engineering Team', 'typo3@metaways.de', 'nsendetzky', '007a5e7fe9118e6f7ed0493fc3686aeb', 'Contains a complete infrastructure for coupons including the most often used actions when codes are redeemed. Windows-based XAMPP environments are now completely supported and a special scheduler task for sending e-mails simplifies the configuration.', 'Metaways Infosystems GmbH', 1001000, 0, 0),
(36824, 0, 'arcavias', 1, '1.1.1', 0, 0, 'Arcavias shop system', 'Arcavias is a flexible, high performance shop system available in multiple languages. Several plugins e.g. for facetted search, product listing, detail view, basket, checkout process and other parts of a shop are available. Furthermore, Arcavias offers powerful interfaces to integrate CRM and ERP systems as well as payment and delivery service providers', 2, 0, 3, 1404143833, 'a:3:{s:7:"depends";a:5:{s:3:"php";s:13:"5.2.0-5.99.99";s:5:"typo3";s:12:"4.5.0-6.2.99";s:7:"extbase";s:13:"1.3.2-6.99.99";s:9:"scheduler";s:13:"1.1.0-6.99.99";s:18:"static_info_tables";s:13:"1.8.0-6.99.99";}s:9:"conflicts";a:1:{s:14:"jquerycolorbox";s:11:"0.0.0-0.0.1";}s:8:"suggests";a:3:{s:7:"realurl";s:14:"1.10.0-1.99.99";s:16:"datamints_feuser";s:13:"0.6.4-1.99.99";s:18:"sr_feuser_register";s:13:"2.6.3-3.99.99";}}', 'Metaways Software Engineering Team', 'typo3@metaways.de', 'nsendetzky', '21ead9bd07edf3a201e497b91b38eb4f', 'The checkout process steps are now passed correctly, problems with a missing default site are fixed, texts and images for attribute part in catalog detail view are displayed and the tax line in basket is hidden if the tax rate is 0.00%.', 'Metaways Infosystems GmbH', 1001001, 0, 0),
(36825, 0, 'arcavias', 1, '1.2.0', 0, 0, 'Arcavias shop system', 'Arcavias is a flexible, high performance shop system available in multiple languages. Several plugins e.g. for facetted search, product listing, detail view, basket, checkout process and other parts of a shop are available. Furthermore, Arcavias offers powerful interfaces to integrate CRM and ERP systems as well as payment and delivery service providers', 2, 0, 3, 1406793204, 'a:3:{s:7:"depends";a:5:{s:3:"php";s:13:"5.2.0-5.99.99";s:5:"typo3";s:12:"4.5.0-6.2.99";s:7:"extbase";s:13:"1.3.2-6.99.99";s:9:"scheduler";s:13:"1.1.0-6.99.99";s:18:"static_info_tables";s:13:"1.8.0-6.99.99";}s:9:"conflicts";a:1:{s:14:"jquerycolorbox";s:11:"0.0.0-0.0.1";}s:8:"suggests";a:3:{s:7:"realurl";s:14:"1.10.0-1.99.99";s:16:"datamints_feuser";s:13:"0.6.4-1.99.99";s:18:"sr_feuser_register";s:13:"2.6.3-3.99.99";}}', 'Metaways Software Engineering Team', 'typo3@metaways.de', 'nsendetzky', '7dc74430ca1e61cde27ac1c294eaa723', 'Arcavias integrates the TYPO3 caching framework to deliver pages within 300ms and is able to use several databases at once. The usability of the front-end was improved and each plug-in can be placed several times on a page and configured individually', 'Metaways Infosystems GmbH', 1002000, 1, 0),
(36826, 0, 'tableupdater', 1, '1.0.0', 0, 0, 'Table Updater', 'Update database tables from the command line.', 2, 0, 0, 1386543459, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"4.5.0-6.2.99";}}', 'Michiel Roos', 'extensions@donationbasedhosting.org', 'tuurlijk', 'bf89047f4ebf4ebf03a632a969ca757b', 'Initial release', 'Donation Based Hosting', 1000000, 0, 0),
