(36828, 0, 'sm_hints', 1, '1.0.0', 0, 0, 'Hints', 'Adds a new content element "hint", which basically provides an info box containing a symbol and some text. Symbol sets are fully configurable in the backend. The is extension is developed for and used in production by Stiftung Mitarbeit, Bonn, Germany.', 2, 0, 2, 1386761139, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"4.5.0-6.2.99";s:5:"fluid";s:0:"";}}', 'Sebastian Michaelsen', 'sebastian@app-zap.de', 'phpprof', '81babeb1b7377be73dc2f01b3468232c', 'Initial Release.\r\nhttps://github.com/smichaelsen/typo3-smhints', '', 1000000, 1, 0),
(36829, 0, 'cool_js', 1, '6.1.5', 0, 0, 'Cool Java Library v6.1.x', 'Javascript, jQuery and more extensions (no need to install)', 2, 0, 3, 1386949903, 'a:1:{s:7:"depends";a:3:{s:3:"php";s:12:"5.0.0-5.5.99";s:5:"typo3";s:12:"6.1.0-6.1.99";s:10:"cool_libs2";s:12:"6.1.5-6.1.99";}}', 'Cornelis Olsthoorn', 'cornelis@olsthoorn.ch', '19cool53', '0806fbf977df63721e970d75f4e3274b', 'Bugfixes and new options\r\nReplaces cool_jquery\r\nPartially tested with Typo3 6.1.5', '', 6001005, 0, 0),
(36830, 0, 'cool_js', 1, '6.1.6', 0, 0, 'Cool Java Library v6.1.x', 'Javascript, jQuery and more extensions (no need to install)', 2, 0, 3, 1387057677, 'a:1:{s:7:"depends";a:3:{s:3:"php";s:12:"5.0.0-5.5.99";s:5:"typo3";s:12:"6.1.0-6.1.99";s:10:"cool_libs2";s:12:"6.1.5-6.1.99";}}', 'Cornelis Olsthoorn', 'cornelis@olsthoorn.ch', '19cool53', '44c5c8e88156a5f2090e08e87288b239', 'Fixed gallary adGallary, Galleria, nivoSlider, prettyPhoto\r\nRemoved unused\r\n', '', 6001006, 1, 0),
(36831, 0, 'authenticator', 1, '0.0.1', 0, 0, 'Authenticator', 'Implements a two factor authentication for TYPO3. Currently a functional preview for backend only.', 0, 0, 5, 1387057141, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.0.0-6.2.99";}}', 'Philipp Gampe', 'philipp.gampe@typo3.org', 'pgampe', '258927268cbc2f216c01dbddad14be86', 'Technical preview. Works for BE only so far, although FE support is already in place. No manual yet. Active in user settings after scanning your QR code into your token app.', '', 1, 0, 0),
(36832, 0, 'authenticator', 1, '0.0.2', 0, 0, 'Authenticator', 'Implements a two factor authentication for TYPO3. Currently a functional preview for backend only.', 0, 0, 5, 1396114112, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.2.0-6.2.99";}}', 'Philipp Gampe', 'philipp.gampe@typo3.org', 'pgampe', '1fea620630da98f5159ea5ef99bf2e03', 'Reduced amount of queries, code refactoring, dependency set to 6.2 only; although it should work with 6.1 too (untested).', '', 2, 0, 0),
(36833, 0, 'authenticator', 1, '0.0.3', 0, 0, 'Authenticator', 'Implements a two factor authentication for TYPO3. Currently a for backend only.', 1, 0, 5, 1412534783, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.2.0-6.2.99";}}', 'Philipp Gampe', 'philipp.gampe@typo3.org', 'pgampe', 'c07fc6505c2e88ff159b91234345772a', 'The last release contained a bug where the secret was not generated if missing. This is fixed now.\r\n\r\nThe backend users settings now use a fluid template too. The token form uses the backend style.\r\n\r\nExternal classes are now loaded with the autoloader.', '', 3, 0, 0),
(36834, 0, 'authenticator', 1, '0.0.4', 0, 0, 'Authenticator', 'Implements a two factor authentication for TYPO3. Currently a for backend only.', 1, 0, 5, 1424778399, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.2.0-6.2.99";}}', 'Philipp Gampe', 'philipp.gampe@typo3.org', 'pgampe', '50867a40fa1c3011547cd912cd607e49', 'Bugfix release. Fixes the fatal error with empty caches.', '', 4, 0, 0),
(36835, 0, 'authenticator', 1, '0.0.5', 0, 0, 'Authenticator', 'Implements a two factor authentication for TYPO3. Currently a for backend only.', 1, 0, 5, 1444947865, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:11:"6.2.0-6.7.5";}}', 'Philipp Gampe', 'philipp.gampe@typo3.org', 'pgampe', 'fa5c294f2f62479ab519c1afaf1bcf35', '- Confirm working with TYPO3 7.5.\r\n- Use qrcode.js instead of PHP library.', '', 5, 0, 0),
(36836, 0, 'authenticator', 1, '0.0.6', 0, 0, 'Authenticator', 'Implements a two factor authentication for TYPO3. Currently a for backend only.', 1, 0, 5, 1444948653, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:11:"6.2.0-7.5.0";}}', 'Philipp Gampe', 'philipp.gampe@typo3.org', 'pgampe', 'd9d2647913c90a70d99dee906bc71e34', 'Correct dependency', '', 6, 0, 0),
(36837, 0, 'authenticator', 1, '0.1.0', 0, 0, 'Authenticator', 'Implements a two factor authentication for TYPO3. Currently a for backend only.', 2, 0, 5, 1447502640, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"7.6.0-7.6.99";}}', 'Philipp Gampe', 'philipp.gampe@typo3.org', 'pgampe', '1d6818d59d459652cdc58d6e5b0f2efd', ' New template\r\n TYPO3 CMS 7 LTS support', '', 1000, 0, 0),
(36838, 0, 'authenticator', 1, '0.1.1', 0, 0, 'Authenticator', 'Implements a two factor authentication for TYPO3. Currently a for backend only.', 2, 0, 5, 1447520472, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"7.6.0-7.6.99";}}', 'Philipp Gampe', 'philipp.gampe@typo3.org', 'pgampe', '82f08a912d3d1b51aada0793144e78b3', ' New template\r\n TYPO3 7 LTS compatibility\r\n Removed unused files\r\n Big thanks to Jonathan Starck (Cretection)', '', 1001, 0, 0),
(36839, 0, 'authenticator', 1, '0.1.2', 0, 0, 'Authenticator', 'Implements a two factor authentication for TYPO3. Currently a for backend only.', 2, 0, 5, 1478951626, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"7.4.0-7.6.99";}}', 'Philipp Gampe', 'philipp.gampe@typo3.org', 'pgampe', '557d9e15e8053e2c5dc16c144ccc3ec6', 'Add composer.json. Should fix autoloading issues.', '', 1002, 0, 0),
(36840, 0, 'authenticator', 1, '0.2.0', 0, 0, 'Authenticator', 'Implements a two factor authentication for TYPO3. Currently a for backend only.', 2, 0, 5, 1479575745, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"7.6.0-8.9.99";}}', 'Philipp Gampe', 'philipp.gampe@typo3.org', 'pgampe', '2882036421333e76d9c46ba34d0f7756', ' - PSR-2 refactorings\r\n - Use style settings (logo, color)\r\n - Error message for failed token\r\n - 8.x support\r\n', '', 2000, 1, 0),
