(36849, 0, 'glcrossword', 1, '0.0.0', 0, 0, 'Crossword', 'Supplies a crossword extension, to create your own crossword on a homepage.', 0, 0, 3, 1387420071, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"4.5.0-4.5.99";}}', 'Gerald Lo', 'gerald.loss@gmx.de', 'gerald_loss', '1faf34353c75cf0770b6c352bd3c5c06', 'Crossword extension for very flexible crosswords.', '', 0, 0, 0),
