(36852, 0, 'glcrossword', 1, '0.5.2', 0, 0, 'Crossword', 'Supplies a crossword extension, to create your own crossword on a homepage.', 1, 0, 3, 1387679139, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:12:"5.0.0-5.4.99";s:5:"typo3";s:12:"4.5.0-4.5.99";}}', 'Gerald Lo', 'gerald.loss@gmx.de', 'gerald_loss', '4795b4fec5a54a274eb591e77d5e5524', 'Better documentation in manual.sxw.\r\nCreate icons for backend.', '', 5002, 0, 0),
(36853, 0, 'glcrossword', 1, '0.5.3', 0, 0, 'Crossword', 'Supplies a crossword extension, to create your own crossword on a homepage. \n		This extension is very flexible. You can define crosswords of every size, \n		answer fields with more then one letter and you can define answers in every posible direction.\n		All you need is to create your own questions and answers an assign it with your crossword.\n		In the frontend you can edit the crossword with javascript very user friendly. \n		The communication with the backend is performed with ajax.', 1, 0, 3, 1387766026, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:12:"5.0.0-5.4.99";s:5:"typo3";s:12:"4.5.0-6.1.99";}}', 'Gerald Lo', 'gerald.loss@gmx.de', 'gerald_loss', '8c213f96ce8de93e69f374cb3f3d4edf', 'Successfully testet in all typo3 versions from 4.5 until 6.1.\r\nSome updates in the manual.\r\nCorrect some errors in the manual for the online documentation of this extension.', '', 5003, 0, 0),
(36854, 0, 'glcrossword', 1, '0.5.4', 0, 0, 'Crossword', 'Supplies a crossword extension, to create your own crossword on a homepage. \n		This extension is very flexible. You can define crosswords of every size, \n		answer fields with more then one letter and you can define answers in every posible direction.\n		All you need is to create your own questions and answers and assign it with your crossword.\n		In the frontend you can edit the crossword with javascript very user friendly. \n		The communication with the backend is performed with ajax.\n		See under http://www.schulze-thulin.de/en/games/crossword/ for an online example.', 1, 0, 3, 1388414408, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:12:"5.0.0-5.4.99";s:5:"typo3";s:12:"4.5.0-6.1.99";}}', 'Gerald Loss', 'gerald.loss@gmx.de', 'gerald_loss', '9e992d1c115b1f8ad3bafbfe5b4bfab0', '1. Bugfix: Losing session while accessing from two different IP addresses to the crossword. Only the first IP address is working until someone has accessed the crossword from somewhere else. This Problem is now resolved.\r\n\r\n2. A better documentation in th', '', 5004, 0, 0),
(36855, 0, 'glcrossword', 1, '0.5.5', 0, 0, 'Crossword', 'Supplies a crossword extension, to create your own crossword on a homepage. \n		This extension is very flexible. You can define crosswords of every size, \n		answer fields with more then one letter and you can define answers in every posible direction.\n		All you need is to create your own questions and answers and assign it with your crossword.\n		In the frontend you can edit the crossword with javascript very user friendly. \n		The communication with the backend is performed with ajax.\n		See under http://www.schulze-thulin.de/en/games/welsh-crossword/ for an online example.', 1, 0, 3, 1388721992, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:12:"5.0.0-5.4.99";s:5:"typo3";s:12:"4.5.0-6.1.99";}}', 'Gerald Loss', 'gerald.loss@gmx.de', 'gerald_loss', '6e98331900838d5d01f7d3826285a2a7', 'Resolved a couple of bugs with UTF issues. See changelog.', '', 5005, 0, 0),
