(36866, 0, 'glcrossword', 1, '2.0.4', 0, 0, 'Crossword', 'Supplies a crossword extension, to create your own crossword on a homepage. \n		This extension is very flexible. You can define crosswords of every size, \n		answer fields with more then one letter and you can define answers in every posible direction.\n		All you need is to create your own questions and answers and assign it with your crossword.\n		In the frontend you can edit the crossword with javascript very user friendly. \n		The communication with the backend is performed with ajax.\n		See under http://www.schulze-thulin.de/en/games/welsh-crossword/ for an online example.', 2, 0, 3, 1455751410, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:12:"5.0.0-5.6.99";s:5:"typo3";s:13:"6.2.0-7.99.99";}}', 'Gerald Loss', 'gerald.loss@gmx.de', 'gerald_loss', 'e2243f3036e8ad358a36320f9650cc8f', 'Bug fixes for Typo3 CMS 7 LTS.', '', 2000004, 0, 0),
(36867, 0, 'glcrossword', 1, '2.0.5', 0, 0, 'Crossword', 'Supplies a crossword extension, to create your own crossword on a homepage. \n		This extension is very flexible. You can define crosswords of every size, \n		answer fields with more then one letter and you can define answers in every posible direction.\n		All you need is to create your own questions and answers and assign it with your crossword.\n		In the frontend you can edit the crossword with javascript very user friendly. \n		The communication with the backend is performed with ajax.\n		See under http://www.schulze-thulin.de/en/games/welsh-crossword/ for an online example.', 2, 0, 3, 1489279499, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:12:"5.0.0-5.6.99";s:5:"typo3";s:13:"6.2.0-7.99.99";}}', 'Gerald Loss', 'gerald.loss@gmx.de', 'gerald_loss', '8d6105441d37d599a05bff274f1653e3', 'Fix some errors in the TCA for entering questions in the backend. This are compaitibility issues with Typo3 7.x\r\nAttention! This is the last version with jQuery 1.10.2, jQuery UI 1.10.3 and qTip 2.1.1\r\nThe next version will work with jQuery 3.x and Boots', '', 2000005, 0, 0),
(36868, 0, 'glcrossword', 1, '3.0.0', 0, 0, 'Crossword', 'Supplies a crossword extension, to create your own crossword on a homepage. \n		This extension is very flexible. You can define crosswords of every size, \n		answer fields with more then one letter and you can define answers in every posible direction.\n		All you need is to create your own questions and answers and assign it with your crossword.\n		In the frontend you can edit the crossword with javascript very user friendly. \n		The communication with the backend is performed with ajax.\n		See under http://www.schulze-thulin.de/en/games/walisisches-kreuzwortraetsel/ for an online example.\n		This extension use jQuery 3.x and Bootstrap 3.x.', 2, 0, 3, 1489357289, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:12:"5.0.0-5.6.99";s:5:"typo3";s:13:"6.2.0-7.99.99";}}', 'Gerald Loss', 'gerald.loss@gmx.de', 'gerald_loss', '53271289982837df7559e322c1a095ad', ' Removed the qTip and jQuery UI library\r\n Upgrade to the jQuery 3.x library\r\n UI implementation with the Bootstrap 3.x library', '', 3000000, 0, 0),
