(36880, 0, 'camaliga', 1, '2.0.0', 0, 0, 'Camaliga: CArousel/MAp/LIst/GAllery', 'A modern extbase carousel/gallery/map/list extension that can use the TYPO3 categories and different jQuery-plugins like FlexSlider or GalleryView. Indexer for ke_search.', 2, 0, 3, 1413664514, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.0.0-6.2.99";}}', 'Kurt Gusbeth', 'info@quizpalme.de', 'bihor', 'fb3e2af7e2b8837c60dfe8a7ad8a9fd8', 'Several new features. \r\n{content.categories} renamed to {content.categoriesAndParents}. \r\nSee changelog in the documentation for all changes.', '', 2000000, 0, 0),
(36881, 0, 'camaliga', 1, '3.0.0', 0, 0, 'Camaliga: CArousel/MAp/LIst/GAllery', 'A modern extbase carousel/gallery/map/list extension that can use the TYPO3 categories and different jQuery-plugins like FlexSlider or GalleryView. Indexer for ke_search.', 2, 0, 3, 1419528036, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.2.2-7.0.99";}}', 'Kurt Gusbeth', 'info@quizpalme.de', 'bihor', '2fc5d31863a4f5b9187b9882eb1b87b6', 'Many templates improved. More images for the detail-site added.\r\nFolder-image added. Category-restriction works now with every template.', '', 3000000, 0, 0),
(36882, 0, 'camaliga', 1, '3.1.0', 0, 0, 'Camaliga: CArousel/MAp/LIst/GAllery', 'A modern extbase carousel/gallery/map/list extension that can use the TYPO3 categories and different jQuery-plugins like FlexSlider or GalleryView. Indexer for ke_search.', 2, 0, 3, 1426330281, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.2.2-7.0.99";}}', 'Kurt Gusbeth', 'info@quizpalme.de', 'bihor', 'f1748aabb3ca6bbec4efe92ad9d94b22', 'New: \r\n- template Tab.html (for Bootstrap) and Lightslider.html \r\n- option for automatic search of Latitude and Longitude. \r\n- posibility to extend the Camaliga-table-fields. \r\n\r\nTypo3 7 compatibility increased (does still not work 100% with Typo3 7.1).', '', 3001000, 0, 0),
(36883, 0, 'camaliga', 1, '3.2.0', 0, 0, 'Camaliga: CArousel/MAp/LIst/GAllery', 'A modern extbase carousel/gallery/map/list extension that can use the TYPO3 categories and different jQuery-plugins like FlexSlider, GalleryView or Isotope. Indexer for ke_search.', 2, 0, 3, 1439738510, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.2.2-7.0.99";}}', 'Kurt Gusbeth', 'info@quizpalme.de', 'bihor', '7be479a4a902fd8d31ca352362172043', 'New form in the backend module: sortable thumbnail overview.\r\nNew templates and minor bugs fixed.', '', 3002000, 0, 0),
(36884, 0, 'camaliga', 1, '4.0.0', 0, 0, 'Camaliga: CArousel/MAp/LIst/GAllery', 'A modern extbase carousel/gallery/map/list extension that can use the TYPO3 categories and different jQuery-plugins like FlexSlider or Isotope. Bootstrap support. Indexer for ke_search.', 2, 0, 3, 1442593447, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.2.2-7.0.99";}}', 'Kurt Gusbeth', 'info@quizpalme.de', 'bihor', '9f4730cd1ac2de5f571a2ddcb1ecabe0', 'Several improvements. More Bootstrap support. New templates.', '', 4000000, 0, 0),
(36885, 0, 'camaliga', 1, '5.0.0', 0, 0, 'Camaliga: CArousel/MAp/LIst/GAllery', 'A carousel/gallery/map/list extension that can use the TYPO3 categories and different jQuery-plugins like Slick or Isotope. Bootstrap support. Indexer for ke_search. Many import scripts. Big manual (even in german).', 2, 0, 3, 1448556374, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.2.2-7.0.99";}}', 'Kurt Gusbeth', 'info@quizpalme.de', 'bihor', '41c7f233ea619ac71b12b5228168968f', 'Important changes. Read the changelog of the manual and use the update script in the extension manager after updating. Note: 3 templates are now deprecated.\r\nTYPO3 7 LTS compatibility will follow soon.', '', 5000000, 0, 0),
(36886, 0, 'camaliga', 1, '6.0.0', 0, 0, 'Camaliga: CArousel/MAp/LIst/GAllery', 'A carousel/gallery/map/list extension that can use the TYPO3 categories and different jQuery-plugins like Slick or Isotope. Bootstrap support. Indexer for ke_search. Many import scripts. Big manual (even in german).', 2, 0, 3, 1454184267, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.2.2-7.6.99";}}', 'Kurt Gusbeth', 'info@quizpalme.de', 'bihor', 'af364dbae6f08e1481775fde19ab5726', 'Now TYPO3 7 LTS compatible.\r\nPath to the templates changed!\r\nRead the chapter Changelog and "Updating to camaliga 6.0.0" before updating.\r\nFlush the general caches after updating.', '', 6000000, 0, 0),
(36887, 0, 'camaliga', 1, '6.0.3', 0, 0, 'Camaliga: CArousel/MAp/LIst/GAllery', 'A carousel/gallery/map/list extension that can use the TYPO3 categories and different jQuery-plugins like Slick or Isotope. Bootstrap support. Indexer for ke_search. Many import scripts. Big manual (even in german).', 2, 0, 3, 1454434990, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.2.2-7.6.99";}}', 'Kurt Gusbeth', 'info@quizpalme.de', 'bihor', '3f9f3e2a90678fa49d3e63bd320f8f91', 'Bugfix-release for TYPO3 7.\r\nRead the manual (Changelog and Updating to version 6.0.0) if you are updating from version 5.0.0.', '', 6000003, 0, 0),
(36888, 0, 'camaliga', 1, '6.0.6', 0, 0, 'Camaliga: CArousel/MAp/LIst/GAllery', 'A carousel/gallery/map/list extension that can use the TYPO3 categories and different jQuery-plugins like Slick or Isotope. Bootstrap support. Indexer for ke_search. Many import scripts. Big manual (even in german).', 2, 0, 3, 1456265703, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.2.2-7.6.99";}}', 'Kurt Gusbeth', 'info@quizpalme.de', 'bihor', '9dea1011508f2760f2bd5ac870603b15', 'Bugfix-release for TYPO3 7.\r\nTypoScript for google maps added/changed.\r\nRead the manual (Changelog and Updating to version 6.0.0) if you are updating from version 5.0.0.', '', 6000006, 0, 0),
(36889, 0, 'camaliga', 1, '6.1.0', 0, 0, 'Camaliga: CArousel/MAp/LIst/GAllery', 'A carousel/gallery/map/list extension that can use the TYPO3 categories and different jQuery-plugins like Slick or Isotope. Bootstrap support. Indexer for ke_search. Many import scripts. Big manual (even in german).', 2, 0, 3, 1460234837, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.2.2-7.6.99";}}', 'Kurt Gusbeth', 'info@quizpalme.de', 'bihor', 'a4d4c41010ddb17678d700b9d080e50f', 'Parallax template added.\r\nUpdate script added.\r\nNew icon.\r\nTYPO3 7 related bugfix again.', '', 6001000, 0, 0),
(36890, 0, 'camaliga', 1, '6.2.0', 0, 0, 'Camaliga: CArousel/MAp/LIst/GAllery', 'A carousel/gallery/map/list extension that can use the TYPO3 categories and different jQuery-plugins like Slick or Isotope. Bootstrap support. Indexer for ke_search. Many import scripts. Big manual (even in german).', 2, 0, 3, 1462301858, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.2.2-7.6.99";}}', 'Kurt Gusbeth', 'info@quizpalme.de', 'bihor', '4d386314c33f4e2b2515d00b2833711f', 'Some more templates can now be configured by TypoScript or FlexForms.\r\n3 more templates are now deprecated: see Changelog.\r\nValidation-error bug fixed?', '', 6002000, 0, 0),
(36891, 0, 'camaliga', 1, '6.3.0', 0, 0, 'Camaliga: CArousel/MAp/LIst/GAllery', 'A carousel/gallery/map/list extension that can use the TYPO3 categories and different jQuery-plugins like Slick or Isotope. Bootstrap support. Indexer for ke_search. Many features! Big manual (even in german).', 2, 0, 3, 1467454781, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.2.2-7.6.99";}}', 'Kurt Gusbeth', 'info@quizpalme.de', 'bihor', '6f7682659890d08ba0e58ef5a4436e8a', '2 ViewHelpers added: content- and addPublicResources-ViewHelper.\r\nBugfix: minor things.', '', 6003000, 0, 0),
