(36970, 0, 'k23_imagecrop', 1, '1.0.0', 0, 0, 'Image Crop Presets', 'Simply crop Images in File Module. Admin can set multiple presets with preview overlay and resizing for cropping. Overlay can be merged to the cropped image. Needs ImageMagick!', 2, 0, 0, 1388844039, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"5.0.0-0.0.0";s:5:"typo3";s:12:"6.1.0-6.1.99";}}', 'Hendrik Reimers (kern23)', 'kontakt@kern23.de', 'kern23', 'b139f866ff580822a65c186b1d3568fa', 'First TYPO3 Repository release! Donate it if you like it :-)', 'KERN23', 1000000, 0, 0),
(36971, 0, 'k23_imagecrop', 1, '1.0.1', 0, 0, 'KERN23 Image Crop (with Presets)', 'Simply crop Images in File Module. Admin can set multiple presets with preview overlay and resizing for cropping. Overlay can be merged to the cropped image. Needs ImageMagick!', 1, 0, 0, 1389000484, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"5.0.0-0.0.0";s:5:"typo3";s:12:"6.1.0-6.1.99";}}', 'Hendrik Reimers (kern23.de)', 'kontakt@kern23.de', 'kern23', 'a8cc6709180471125186d10ae451c3d0', 'Small changes, like new Icons', 'KERN23', 1000001, 0, 0),
