(37058, 0, 'extbase_rest', 1, '0.0.2', 0, 0, 'Route REST requests for Extbase', 'Route HTTP/REST request to action on your controller based on the request method (e.g. GET, POST, PUT)', 0, 0, 2, 1391098971, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:13:"4.5.27-4.5.32";s:7:"extbase";s:11:"1.3.4-0.0.0";}}', 'Arno Schoon', 'arno@maxserv.nl', 'maxserv-arno', '00c00312aa186bb2be34586d1771240e', 'Initial upload. Usage: http://example.com/_rest/{extensionKey}.{pluginName}/{controllerName}.{format} (e.g. http://example.com/_rest/my_extension.fancy_plugin/data.json)', 'MaxServ B.V.', 2, 1, 0),
