(37106, 0, 'operations', 1, '1.0.0', 0, 0, 'Operations', 'Manage operations with reports and images. This extension were build to manage firefighter operations from "Freiwillige Feuerwehr Thale".', 0, 0, 3, 1392580215, 'a:1:{s:7:"depends";a:3:{s:7:"extbase";s:3:"6.0";s:5:"fluid";s:3:"6.0";s:5:"typo3";s:12:"6.1.0-6.2.99";}}', 'Karsten Nowak', 'captnnowi@gmx.de', 'nowi', 'f69aeb49683dbcb4a9aac86bae2a6912', 'Manage firefighter operations. List and Single View in Frontend. Its possible to use this extension for other types of operations too, but the main goal is using this on websites of a fire department.', 'undkonsorten', 1000000, 0, 0),
(37107, 0, 'operations', 1, '1.0.1', 0, 0, 'Operations', 'Manage operations with reports and images. This extension were build to manage firefighter operations from "Freiwillige Feuerwehr Thale".', 0, 0, 3, 1393264930, 'a:1:{s:7:"depends";a:3:{s:7:"extbase";s:3:"6.0";s:5:"fluid";s:3:"6.0";s:5:"typo3";s:12:"6.1.0-6.2.99";}}', 'Karsten Nowak', 'captnnowi@gmx.de', 'nowi', 'c00a1fff56521c316bef03ba6b886796', 'Manage operations with reports and images. This extension were build to manage firefighter operations from "Freiwillige Feuerwehr Thale". ', 'undkonsorten', 1000001, 0, 0),
(37108, 0, 'operations', 1, '1.0.2', 0, 0, 'Operations', 'Manage firefighter operations with detailed reports and images. This extension were build to manage firefighter operations from "Freiwillige Feuerwehr Thale". Use slider and lightbox for images.', 0, 0, 3, 1393534944, 'a:1:{s:7:"depends";a:3:{s:7:"extbase";s:3:"6.0";s:5:"fluid";s:3:"6.0";s:5:"typo3";s:12:"6.1.0-6.2.99";}}', 'Karsten Nowak', 'captnnowi@gmx.de', 'nowi', 'bdd068f0eb42aec1e38a52410414ac56', 'Manage firefighter operations for fire departments or use it for other operation types. Lightbox and slider for images are completely (JS, CSS) included now. No other setup will be needed.', 'undkonsorten', 1000002, 0, 0),
(37109, 0, 'operations', 1, '1.0.3', 0, 0, 'Operations', 'Manage firefighter operations with detailed reports and images. This extension were build to manage firefighter operations from "Freiwillige Feuerwehr Thale". Use slider and lightbox for images. Possibly to use it for other reportable events.', 0, 0, 3, 1393710356, 'a:1:{s:7:"depends";a:3:{s:7:"extbase";s:3:"6.0";s:5:"fluid";s:3:"6.0";s:5:"typo3";s:12:"6.1.0-6.2.99";}}', 'Karsten Nowak', 'captnnowi@gmx.de', 'nowi', '600bee45df753f66a8c03def5a577a39', 'ReST documentation added.', 'undkonsorten', 1000003, 0, 0),
