(37121, 0, 'operations', 1, '2.0.1', 0, 0, 'Operations', 'Manage (firefighter,Feuerwehr) operations with detailed reports, images used resources or vehicles, google map view for locations, slider and lightbox for images. Possibly to use it for other reportable events like THW and so on.', 1, 0, 3, 1496688430, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:3:"5.6";s:5:"typo3";s:14:"8.7.0 - 8.7.99";}}', 'Karsten Nowak', 'captnnowi@gmx.de', 'nowi', '6018adf590eee85247d71811ef1af4c4', 'TYPO3 8.7 compatibility, clean up code.', 'undkonsorten', 2000001, 1, 0),
