(37182, 0, 'causal_accounts', 1, '1.4.1', 0, 0, 'Central Account Management', 'This extension allows TYPO3 administrator accounts to be managed centrally and automatically synchronized with remote websites using a secure link. No need for complex LDAP / ActiveDirectory infrastructure.', 2, 0, 5, 1394877371, 'a:1:{s:7:"depends";a:3:{s:3:"php";s:12:"5.3.3-5.5.99";s:5:"typo3";s:12:"4.5.0-6.2.99";s:6:"openid";s:0:"";}}', 'Xavier Perseguers (Causal)', 'xavier@causal.ch', 'xperseguers', '66a5d9ee49e2d355db2be29dceaab831', 'Initial public release', 'Causal Srl', 1004001, 0, 0),
(37183, 0, 'causal_accounts', 1, '1.5.0', 0, 0, 'Central Account Management', 'This extension allows TYPO3 administrator accounts to be managed centrally and automatically synchronized with remote websites using a secure link. No need for complex LDAP / ActiveDirectory infrastructure.', 2, 0, 5, 1404487572, 'a:1:{s:7:"depends";a:3:{s:3:"php";s:12:"5.3.3-5.5.99";s:5:"typo3";s:12:"4.5.0-6.2.99";s:6:"openid";s:0:"";}}', 'Xavier Perseguers (Causal)', 'xavier@causal.ch', 'xperseguers', 'fddc53b93474c555598fed4d022806ba', 'New option to let you synchronize users from master repository regularly, without scheduler task', 'Causal Srl', 1005000, 0, 0),
