(37185, 0, 'causal_accounts', 1, '1.5.2', 0, 0, 'Central Account Management', 'This extension allows TYPO3 administrator accounts to be managed centrally and automatically synchronized with remote websites using a secure link. No need for complex LDAP / ActiveDirectory infrastructure.', 2, 0, 5, 1410163277, 'a:1:{s:7:"depends";a:4:{s:3:"php";s:12:"5.3.3-5.5.99";s:5:"typo3";s:12:"4.5.0-6.2.99";s:6:"openid";s:0:"";s:9:"scheduler";s:0:"";}}', 'Xavier Perseguers (Causal)', 'xavier@causal.ch', 'xperseguers', '9211ea47132864470d713a870e2272dc', 'Fixes another compatibility issue in TYPO3 4.5.', 'Causal Srl', 1005002, 0, 0),
(37186, 0, 'causal_accounts', 1, '1.5.3', 0, 0, 'Central Account Management', 'This extension allows TYPO3 administrator accounts to be managed centrally and automatically synchronized with remote websites using a secure link. No need for complex LDAP / ActiveDirectory infrastructure.', 2, 0, 5, 1410710428, 'a:1:{s:7:"depends";a:4:{s:3:"php";s:12:"5.3.3-5.5.99";s:5:"typo3";s:12:"4.5.0-6.2.99";s:6:"openid";s:0:"";s:9:"scheduler";s:0:"";}}', 'Xavier Perseguers (Causal)', 'xavier@causal.ch', 'xperseguers', '7f7d8bfb578d277112363140f97a4737', 'Compatibility issue in TYPO3 6.2', 'Causal Srl', 1005003, 0, 0),
(37187, 0, 'causal_accounts', 1, '1.6.0', 0, 0, 'Central Account Management', 'This extension allows TYPO3 administrator accounts to be managed centrally and automatically synchronized with remote websites using a secure link. No need for complex LDAP / ActiveDirectory infrastructure.', 2, 0, 5, 1421136906, 'a:1:{s:7:"depends";a:4:{s:3:"php";s:12:"5.3.3-5.6.99";s:5:"typo3";s:13:"4.5.0-7.99.99";s:6:"openid";s:0:"";s:9:"scheduler";s:0:"";}}', 'Xavier Perseguers (Causal)', 'xavier@causal.ch', 'xperseguers', 'ea8dcffe394eedbe9d292b3cb9bed235', 'Native compatibility with TYPO3 4.5-7.x.', 'Causal Srl', 1006000, 0, 0),
(37188, 0, 'causal_accounts', 1, '1.7.0', 0, 0, 'Central Account Management', 'This extension allows TYPO3 administrator accounts to be managed centrally and automatically synchronized with remote websites using a secure link. No need for complex LDAP / ActiveDirectory infrastructure.', 2, 0, 5, 1447334489, 'a:1:{s:7:"depends";a:4:{s:3:"php";s:12:"5.3.3-5.6.99";s:5:"typo3";s:13:"4.5.0-7.99.99";s:6:"openid";s:0:"";s:9:"scheduler";s:0:"";}}', 'Xavier Perseguers (Causal)', 'xavier@causal.ch', 'xperseguers', '4102d151469e961deeb4a29b7650c5ee', 'Last bits of fine-tuning to be ready for TYPO3 7 LTS since outsourcing of EXT:openid to TER.\nNative compatibility with TYPO3 4.5 LTS to 7 LTS is preserved.', 'Causal Srl', 1007000, 0, 0),
(37189, 0, 'causal_accounts', 1, '1.7.1', 0, 0, 'Central Account Management', 'This extension allows TYPO3 administrator accounts to be managed centrally and automatically synchronized with remote websites using a secure link. No need for complex LDAP / ActiveDirectory infrastructure.', 2, 0, 5, 1454683621, 'a:1:{s:7:"depends";a:4:{s:3:"php";s:12:"5.3.3-7.0.99";s:5:"typo3";s:13:"4.5.0-7.99.99";s:6:"openid";s:0:"";s:9:"scheduler";s:0:"";}}', 'Xavier Perseguers (Causal)', 'xavier@causal.ch', 'xperseguers', 'd6b9276959f8d14f97eb674a1f320cde', 'Regular maintenance release (compatibility with PHP 7 and bug fix in TYPO3 7 LTS).', 'Causal Srl', 1007001, 1, 0),
(37190, 0, 'extractor', 1, '0.1.0', 0, 0, 'TYPO3 Bridge Metadata Extractor for FAL', 'Provides a bridge between TYPO3 metadata extraction services and FAL extractors. Lets you use extensions such as "svmetaextract" or "tika" with FAL. Will automatically populate EXIF / IPTC and other file metadata extracted from images, videos, sounds or standard files (PDF, DOC, ...) by running the FAL indexer scheduler task.', 0, 0, 5, 1394914861, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:12:"5.3.3-5.5.99";s:5:"typo3";s:12:"6.2.0-6.2.99";}}', 'Xavier Perseguers (Causal)', 'xavier@causal.ch', 'xperseguers', '834c0fbac85dae08f418d6e4b43d7128', 'Initial release to gather feedback.', 'Causal Srl', 1000, 0, 0),
(37191, 0, 'extractor', 1, '0.2.0', 0, 0, 'Bridge between Metadata Services and FAL Extractor', 'Provides a bridge between TYPO3 metadata extraction services and FAL extractors. Lets you use extensions such as "svmetaextract" or "tika" with FAL. Will automatically populate EXIF / IPTC / XMP and other file metadata extracted from images, videos, sounds or standard files (PDF, DOC, ...) by running the FAL indexer scheduler task. NOTE: a configuration option lets you extract metadata on-the-fly while uploading files.', 1, 0, 5, 1394980102, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:12:"5.3.3-5.5.99";s:5:"typo3";s:12:"6.2.0-6.2.99";}}', 'Xavier Perseguers (Causal)', 'xavier@causal.ch', 'xperseguers', '2ee852f39310c79fb34097d0f6c1011b', 'Support for Apache Tika. Configuration option to extract metadata on-the-fly during upload (no need for FAL scheduler task).', 'Causal Srl', 2000, 0, 0),
(37192, 0, 'extractor', 1, '1.0.0', 0, 0, 'Metadata and content analysis service', 'This extension detects and extracts metadata and text (EXIF / IPTC / XMP / ...) from potentially thousand different file types (such as MS Word/Powerpoint/Excel documents and PDF) and bring them automatically and natively to TYPO3 when uploading assets. Can take advantage of Apache Tika and other external tools.', 2, 0, 5, 1445275129, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:12:"5.3.3-5.6.99";s:5:"typo3";s:13:"6.2.0-7.99.99";}}', 'Xavier Perseguers (Causal)', 'xavier@causal.ch', 'xperseguers', '1dbcd9eb0ffea081e092db6357727dd3', 'Extension is not acting as a bridge anymore since the former dependency extensions lack any plausible sign of life.\nDetails on https://forge.typo3.org/projects/extension-extractor/wiki/EXTRACTOR_100', 'Causal Srl', 1000000, 0, 0),
(37193, 0, 'extractor', 1, '1.1.0', 0, 0, 'Metadata and content analysis service', 'This extension detects and extracts metadata (EXIF / IPTC / XMP / ...) from potentially thousand different file types (such as MS Word/Powerpoint/Excel documents, PDF and images) and bring them automatically and natively to TYPO3 when uploading assets. Works with built-in PHP functions but takes advantage of Apache Tika and other external tools for enhanced metadata extraction.', 2, 0, 5, 1445877350, 'a:1:{s:7:"depends";a:3:{s:3:"php";s:12:"5.3.3-5.6.99";s:5:"typo3";s:13:"6.2.0-7.99.99";s:12:"filemetadata";s:0:"";}}', 'Xavier Perseguers (Causal)', 'xavier@causal.ch', 'xperseguers', '6a32edb1377e94b0aeb4c6b583662938', 'Streamlined metadata user interface in 6.2 as in 7.\nEnhanced autonomous extraction with PHP (docx, xlsx, pdf, jpg, ...).\nDetails on https://forge.typo3.org/projects/extension-extractor/wiki/EXTRACTOR_110', 'Causal Srl', 1001000, 0, 0),
(37194, 0, 'extractor', 1, '1.2.0', 0, 0, 'Metadata and content analysis service', 'This extension detects and extracts metadata (EXIF / IPTC / XMP / ...) from potentially thousand different file types (such as MS Word/Powerpoint/Excel documents, PDF and images) and bring them automatically and natively to TYPO3 when uploading assets. Works with built-in PHP functions but takes advantage of Apache Tika and other external tools for enhanced metadata extraction.', 2, 0, 5, 1447077642, 'a:1:{s:7:"depends";a:3:{s:3:"php";s:12:"5.3.3-5.6.99";s:5:"typo3";s:13:"6.2.0-7.99.99";s:12:"filemetadata";s:0:"";}}', 'Xavier Perseguers (Causal)', 'xavier@causal.ch', 'xperseguers', '61a9440f6e1cd095450be6a709d790a3', 'Loads of additional file types analysed in native PHP.\nTakes EXT:media changes to TCA into account. Use of EXT:metadata is however discouraged (and useless anyway).\nDetails on https://forge.typo3.org/projects/extension-extractor/wiki/EXTRACTOR_120', 'Causal Srl', 1002000, 0, 0),
(37195, 0, 'extractor', 1, '1.2.1', 0, 0, 'Metadata and content analysis service', 'This extension detects and extracts metadata (EXIF / IPTC / XMP / ...) from potentially thousand different file types (such as MS Word/Powerpoint/Excel documents, PDF and images) and bring them automatically and natively to TYPO3 when uploading assets. Works with built-in PHP functions but takes advantage of Apache Tika and other external tools for enhanced metadata extraction.', 2, 0, 5, 1449140486, 'a:1:{s:7:"depends";a:3:{s:3:"php";s:12:"5.3.3-5.6.99";s:5:"typo3";s:13:"6.2.0-7.99.99";s:12:"filemetadata";s:0:"";}}', 'Xavier Perseguers (Causal)', 'xavier@causal.ch', 'xperseguers', 'ba6c370cf5d88daa133d39f8e9ba0ddc', 'Extraction could fail to be triggered in TYPO3 7.\nBetter handling of PDF metadata using native PHP extraction.\nDetails on https://forge.typo3.org/projects/extension-extractor/wiki/EXTRACTOR_121', 'Causal Srl', 1002001, 0, 0),
