(37256, 0, 'smoothmigration', 1, '1.0.0', 0, 0, 'LTS to LTS smooth migration report', 'The module analyses your current setup, extensions and configuration in regard to features, functions and configuration which have been removed or changed since the release of TYPO3 4.5 LTS.', 1, 0, 0, 1395683550, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:12:"4.5.0-4.7.99";s:7:"extbase";s:12:"1.3.0-1.3.99";s:5:"fluid";s:12:"1.3.0-1.3.99";}}', 'Steffen Ritter', 'steffen.ritter@typo3.org', 'typo3v4', 'a69c71ff8b4dc446a101b520f308c225', 'Initial upload for TYPO3 6.2', 'rs websystems', 1000000, 0, 0),
(37257, 0, 'smoothmigration', 1, '1.0.1', 0, 0, 'LTS to LTS smooth migration report', 'The module analyses your current setup, extensions and configuration in regard to features, functions and configuration which have been removed or changed since the release of TYPO3 4.5 LTS.', 1, 0, 0, 1395819546, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:12:"4.5.0-4.7.99";s:7:"extbase";s:12:"1.3.0-1.3.99";s:5:"fluid";s:12:"1.3.0-1.3.99";}}', 'Steffen Ritter', 'steffen.ritter@typo3.org', 'typo3v4', '6925b147d7919a85bcd1429d4c4e4db7', 'Fixed fatal error (thx to Alexander Bigga)', 'rs websystems', 1000001, 1, 0),
