(37259, 0, 'conn_w2p', 1, '1.0.0', 0, 0, 'connetation:// w2p', 'Render HTML5 Pages for connetation:// w2p PDF Rendering Service', 1, 0, 1, 1395827107, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:12:"4.5.0-4.7.99";s:9:"sfpipauth";s:0:"";s:18:"static_info_tables";s:0:"";}}', 'Paul Leitner', 'p.leitner@connetation.at', 'connetation', 'd2ed4e80ae323600711b8bf253a4304a', '', '', 1000000, 0, 0),
(37260, 0, 'conn_w2p', 1, '1.0.1', 0, 0, 'connetation:// w2p', 'Web2Print is a framework to create HTML5 content out of different sources.The extension displays the content in a preview environment which resembles the single rendered pages in the finished document.Since rendering  especially for print production  is a time consuming task, the preview provides the user with the possibility to check the result.\nThe rendering process itself is finished by the w2pservice, a server- side ensemble of different tools and proprietary code taking care of converting existing RGB Images to CMYK colorspace if needed and creating a print-ready PDF-X3 document.', 1, 0, 1, 1396287193, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:12:"4.5.0-4.7.99";s:9:"sfpipauth";s:0:"";s:18:"static_info_tables";s:0:"";}}', 'Connetation Web Engineering GmbH', 'support@connetation.at', 'connetation', 'b0713bf8ed0129808c4c7973c3c20cb0', '-updated manual', '', 1000001, 0, 0),
(37261, 0, 'conn_w2p', 1, '1.0.3', 0, 0, 'connetation:// w2p', 'Web2Print is a framework to create HTML5 content out of different sources.The extension displays the content in a preview environment which resembles the single rendered pages in the finished document.Since rendering  especially for print production  is a time consuming task, the preview provides the user with the possibility to check the result.\nThe rendering process itself is finished by the w2pservice, a server- side ensemble of different tools and proprietary code taking care of converting existing RGB Images to CMYK colorspace if needed and creating a print-ready PDF-X3 document.', 1, 0, 1, 1398783212, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"4.5.0-4.7.99";s:18:"static_info_tables";s:0:"";}}', 'Connetation Web Engineering GmbH', 'support@connetation.at', 'connetation', '969991223ffb0f67888a477e08252df7', '	 Changed rendering service authentication to token based system (replacing previous implementation using sfpipauth)\r\n	 New flag "loginEnabled" to choose between protected and publicly available W2P rendering frontend\r\n	 Additional description/screensh', '', 1000003, 0, 0),
(37262, 0, 'conn_w2p', 1, '1.0.5', 0, 0, 'connetation:// w2p', 'Web2Print is a framework to create HTML5 content out of different sources.The extension displays the content in a preview environment which resembles the single rendered pages in the finished document.Since rendering  especially for print production  is a time consuming task, the preview provides the user with the possibility to check the result.\nThe rendering process itself is finished by the w2pservice, a server- side ensemble of different tools and proprietary code taking care of converting existing RGB Images to CMYK colorspace if needed and creating a print-ready PDF-X3 document.', 1, 0, 1, 1405343748, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"4.5.0-4.7.99";s:18:"static_info_tables";s:0:"";}}', 'Connetation Web Engineering GmbH', 'support@connetation.at', 'connetation', 'ec85b1a5b1847c81849c4f84e65eece1', '2014-07-14\r\n	 flag for start with left page\r\n	 changed handling of subelements (sorting)\r\n\r\n2014-05-20\r\n	 ext config changes\r\n\r\n2014-05-09\r\n	 fetch authtoken before rendering via AJAX (fix for cached old authtoken)\r\n	 increased token age\r\n	\r\n2014-05-', '', 1000005, 0, 0),
(37263, 0, 'conn_w2p', 1, '1.1.0', 0, 0, 'connetation:// w2p', 'Web2Print is a framework to create HTML5 content out of different sources.The extension displays the content in a preview environment which resembles the single rendered pages in the finished document.Since rendering  especially for print production  is a time consuming task, the preview provides the user with the possibility to check the result.\r\nThe rendering process itself is finished by the w2pservice, a server- side ensemble of different tools and proprietary code taking care of converting existing RGB Images to CMYK colorspace if needed and creating a print-ready PDF-X3 document.', 1, 0, 1, 1411377231, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"4.5.0-4.7.99";s:18:"static_info_tables";s:0:"";}}', 'Connetation Web Engineering GmbH', 'support@connetation.at', 'connetation', 'dbf369e0cd648e1d3b68f744fcca0fe1', 'v1.1.0', '', 1001000, 0, 0),
