(37265, 0, 'nn_address', 1, '1.0.0', 0, 0, 'NN Address', 'Alternative to tt_address based on Typo3 6.x and extbase/fluid. For one contact you can add multiple addresses,mails,numbers and can extend fields with Flexform.', 1, 0, 3, 1395832135, 'a:1:{s:7:"depends";a:3:{s:7:"extbase";s:12:"6.0.0-6.2.99";s:5:"fluid";s:12:"6.0.0-6.2.99";s:5:"typo3";s:12:"6.0.0-6.2.99";}}', 'Hendrik Reimers (Neonaut GmbH)', 'info@neonaut.de', 'kern23', 'e68a23bc0f3e44b43b7ff423865a7653', 'Initial release', 'Neonaut GmbH', 1000000, 0, 0),
(37266, 0, 'nn_address', 1, '2.0.0', 0, 0, 'NN Address', 'Powerful Address extension. Fully based on Extbase/Fluid as an new alternative to tt_address. You can add multiple addresses,email address, etc. to a contact. No need to create multiple for one anymore. If more fields neededyou can simply extend them with flexforms.', 2, 0, 3, 1399559827, 'a:1:{s:7:"depends";a:3:{s:7:"extbase";s:12:"6.0.0-6.2.99";s:5:"fluid";s:12:"6.0.0-6.2.99";s:5:"typo3";s:12:"6.0.0-6.2.99";}}', 'Hendrik Reimers (neonaut.de, belnet.de)', 'info@neonaut.de, typo3@belnet.de', 'kern23', '47432051ddd0ba68e3f842be8023edfa', 'New features: filter address list, show google map', 'Neonaut GmbH, BEL NET GmbH', 2000000, 0, 0),
(37267, 0, 'nn_address', 1, '2.1.0', 0, 0, 'NN Address', 'Powerful Address extension. Fully based on Extbase/Fluid as an new alternative to tt_address. You can add multiple addresses,email address, etc. to a contact. No need to create multiple for one anymore. If more fields neededyou can simply extend them with flexforms.', 2, 0, 3, 1400663937, 'a:1:{s:7:"depends";a:3:{s:7:"extbase";s:12:"6.0.0-6.2.99";s:5:"fluid";s:12:"6.0.0-6.2.99";s:5:"typo3";s:12:"6.0.0-6.2.99";}}', 'Hendrik Reimers (neonaut.de, belnet.de)', 'info@neonaut.de, typo3@belnet.de', 'kern23', '76eb0b146e170f66c4e4fbbfc761c888', 'Features update like: \r\nshorter-urls,\r\npossibility to extend now all models (not only person) with flexform, \r\nand more. see manual or forge', 'Neonaut GmbH, BEL NET GmbH', 2001000, 0, 0),
