(37354, 0, 'frames', 1, '1.0.0', 0, 0, 'Frames', 'Sick of configuring section frames for tt_content elements via Page TS Config and manipulating css_styled_content? Well, I was. So I created this little plugin which allows you to define section frames as standalone records, freely configure them in your list view and apply them to your content elements in the easiest way possible. It has never been so easy to wrap tt_content elements in custom divs etc.', 0, 0, 0, 1397575656, 'a:1:{s:7:"depends";a:3:{s:3:"cms";s:0:"";s:3:"php";s:12:"5.0.0-5.4.99";s:5:"typo3";s:12:"4.5.0-6.2.99";}}', 'Felix Kiesewetter', 'info@felixkiesewetter.de', 'felixkiesewetter', '165fb47b8c0b46631ad2ee1818207d0b', 'Plugin created', '', 1000000, 1, 0),
(37355, 0, 'namespaces', 1, '1.0.0', 0, 0, 'Global Namespaces in fluid', 'Adds the possibility to register a namespace globally in fluid so you dont have to declare it in every file.', 2, 0, 3, 1397590811, 'a:1:{s:7:"depends";a:3:{s:3:"php";s:11:"5.3.7-0.0.0";s:5:"typo3";s:12:"6.1.0-6.2.99";s:5:"fluid";s:12:"6.1.0-6.2.99";}}', 'Mato Ilic', 'info@matoilic.ch', 'matoilic', '3127c4de7991640630a1354a677c9f80', 'First public release', '', 1000000, 1, 0),
