(37443, 0, 'braintreecopier', 1, '1.0.0', 0, 0, 'Tree Copier', 'Create copies of a page tree without copying the content elements. Copies all subpages of a given source page to a destination page, sets the copied pages to "show content of {original} page". Source and target page id are configurable in a back-end module.', 2, 0, 1, 1400848385, 'a:1:{s:7:"depends";a:3:{s:7:"extbase";s:3:"1.3";s:5:"fluid";s:3:"1.3";s:5:"typo3";s:12:"4.5.0-4.7.99";}}', '', '', 'brainappeal', '20540b9268ef963d672966b87ebc927d', 'First public release', '', 1000000, 0, 0),
(37444, 0, 'braintreecopier', 1, '1.0.1', 0, 0, 'Tree Copier', 'Create copies of a page tree without copying the content elements. Copies all subpages of a given source page to a destination page, sets the copied pages to "show content of {original} page". Source and target page id are configurable in a back-end module.', 2, 0, 1, 1400853461, 'a:1:{s:7:"depends";a:3:{s:7:"extbase";s:3:"1.3";s:5:"fluid";s:3:"1.3";s:5:"typo3";s:12:"4.5.0-4.7.99";}}', 'Brain Appeal GmbH', 'info@brain-appeal.com', 'brainappeal', '095e60630dce9026587a75ffd8cd0193', 'Amended author information', 'Brain Appeal GmbH', 1000001, 0, 0),
(37445, 0, 'braintreecopier', 1, '1.0.3', 0, 0, 'Tree Copier', 'Create copies of a page tree without copying the content elements. Copies all subpages of a given source page to a destination page, sets the copied pages to "show content of {original} page". Source and target page id are configurable in a back-end module.', 2, 0, 1, 1403009889, 'a:1:{s:7:"depends";a:4:{s:7:"extbase";s:3:"1.3";s:5:"fluid";s:3:"1.3";s:5:"typo3";s:12:"4.5.0-6.2.99";s:3:"php";s:9:"5.3-0.0.0";}}', 'Brain Appeal GmbH', 'info@brain-appeal.com', 'brainappeal', 'bb8ce268a5320b580f3e31c97e26518f', ' Extension works with TYPO3 6.2.\r\n Added option to select which translations of the pages should be copied in addition to the default language.\r\n On TYPO3 4.7 and 6.x a custom icon is used for pages set to "show content from page".', 'Brain Appeal GmbH', 1000003, 1, 0),
(37446, 0, 'brainmulticolumntogridelements', 1, '1.0.0', 0, 0, 'Migrate Multicolumn to Gridelements', 'Migrates multicolumn containers to gridelements containers, since both have a different DB structure but still enough in common so this can work.\nHowever, both extension are customizable and it is therefore impossible to make it work with every custom configuration.\nUSE AT YOUR OWN RISK and MAKE BACKUPS of your database.', 2, 0, 1, 1400848473, 'a:1:{s:7:"depends";a:3:{s:7:"extbase";s:3:"1.3";s:5:"fluid";s:3:"1.3";s:5:"typo3";s:12:"4.5.0-4.7.99";}}', 'Brain Appeal GmbH', 'info@brain-appeal.com', 'brainappeal', 'c30d5b24d74f02190475b819d4eb34cf', 'First public release', 'Brain Appeal GmbH', 1000000, 0, 0),
(37447, 0, 'brainmulticolumntogridelements', 1, '1.0.1', 0, 0, 'Migrate Multicolumn to Gridelements', 'Migrates multicolumn containers to gridelements containers, since both have a different DB structure but still enough in common so this can work.\nHowever, both extension are customizable and it is therefore impossible to make it work with every custom configuration.\nUSE AT YOUR OWN RISK and MAKE BACKUPS of your database.', 2, 0, 1, 1406286488, 'a:1:{s:7:"depends";a:3:{s:7:"extbase";s:3:"1.3";s:5:"fluid";s:3:"1.3";s:5:"typo3";s:12:"4.5.0-4.7.99";}}', 'Brain Appeal GmbH', 'info@brain-appeal.com', 'brainappeal', 'ea63f09a46b1e42170c37c393978bad3', ' Fixed a bug that would cause mapping of MC layouts to GE layouts to be ignored.\r\n Pages on which only one MC layout is used are shown in bold so you can view that layout in the front-end without mixing it up with other MC layouts.', 'Brain Appeal GmbH', 1000001, 1, 0),
(37448, 0, 'dpn_get_text_contents', 1, '0.9.0', 0, 0, 'Get text contents', 'CLI tool to fetch all text elements from each page and serve it to you as an CSV', 1, 0, 4, 1401011255, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.0.0-6.2.99";}}', 'Daniel Dorndorf', 'dorndorf@dreipunktnull.com', 'featdd', '0effc993eb68418665624846e6eebe52', 'This TYPO3 extension provides a small CLI tool, you can use to fetch text contents from all pages of your site.\r\n\r\nIt serves you all contents as a CSV file, this might be necessary if you have to translate your site by a translation agency.', '', 9000, 1, 0),
