(37490, 0, 't3ddy', 1, '0.1.1', 0, 0, 'T3ddy - Super cute tabs and accordions', 'T3ddy provides comfortable tabs and accordion handling right in TYPO3 page module using the magic of gridelements.', 1, 0, 4, 1401986137, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"6.0.0-6.2.99";s:12:"gridelements";s:12:"2.0.0-3.0.99";}}', 'Armin Ruediger Vieweg', 'armin@v.ieweg.de', 'professorweb', '0a916160faa2e3a6e8a17ad032178ed4', 'Fixed bug with tabs and pages (t3ddy-items) which get not displayed, when page is cached.', '', 1001, 0, 0),
(37491, 0, 't3ddy', 1, '0.2.0', 0, 0, 't3ddy - Super cute tabs and accordions', 't3ddy provides comfortable tabs and accordion handling right in TYPO3 page module using the magic of gridelements.', 2, 0, 4, 1409317788, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"6.0.0-6.2.99";s:12:"gridelements";s:12:"2.0.0-3.0.99";}}', 'Armin Ruediger Vieweg', 'armin@v.ieweg.de', 'professorweb', '0072b7a856ba4bb82d565ad9a447a465', 'Major update for t3ddy including many bugfixes. Nested tab and accordion containers are supported now. The display of "normal" gridelements inside of tabs or accordions will not break anymore. Also documentation has been added to extension. Enjoy!', '', 2000, 0, 0),
(37492, 0, 't3ddy', 1, '0.3.0', 0, 0, 't3ddy - Super cute tabs and accordions', 't3ddy provides comfortable tabs and accordion handling right in TYPO3 page module using the magic of gridelements.', 2, 0, 4, 1435598045, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"6.0.0-6.2.99";s:12:"gridelements";s:12:"3.0.0-3.2.99";}}', 'Armin Ruediger Vieweg', 'armin@v.ieweg.de', 'professorweb', 'c2408d5c2b15fad6e0d20ab7b78c3291', 'Fixed gridelements dependency. t3ddy works with latest gridelements version. Also added option to jQueryUI which opens accordion pages by given content element hash in URL.', '', 3000, 0, 0),
