(37494, 0, 't3ddy', 1, '1.0.0', 0, 0, 't3ddy - Super cute tabs and accordions', 't3ddy provides comfortable tabs and accordion handling right in TYPO3 page module, using the techniques of gridelements.', 2, 0, 4, 1459451309, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"7.6.0-7.6.99";s:12:"gridelements";s:13:"3.0.5-7.99.99";}}', 'Armin Ruediger Vieweg', 'armin@v.ieweg.de', 'professorweb', '57a92a2c496913bb6d5d66bce04a0f2e', 'This version of t3ddy is compatible for TYPO3 7.6 and contains much more options than the versions before.', '', 1000000, 0, 0),
(37495, 0, 't3ddy', 1, '1.1.0', 0, 0, 't3ddy - Super cute tabs and accordions', 't3ddy provides comfortable tabs and accordion handling right in TYPO3 page module, using the techniques of gridelements.', 2, 0, 4, 1471172107, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"7.6.0-7.6.99";s:12:"gridelements";s:13:"3.0.5-7.99.99";}}', 'Armin Ruediger Vieweg', 'armin@v.ieweg.de', 'professorweb', 'f2b63a08c7d9a6f71d6211d71554ea0e', 'New option for accordions: Collapsible. When checked, all pages of accordion can get closed again by clicking on header. If you use and like t3ddy please concider a small donation: https://goo.gl/1Qbzhr (PayPal)', '', 1001000, 0, 0),
