(37504, 0, 'cwenvbanner', 1, '0.0.1', 0, 0, 'Environment Banner', 'Adds a small Banner in both FE and BE and changes title tag to easier distinct between different Typo3 installations (hopefully no more "Ups - I was on Live all the time...")', 0, 0, 4, 1402484767, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"4.5.0-6.2.99";}}', 'Carsten Windler', 'carsten@carstenwindler.de', 'el_curtismo', 'cc2c50c8455f713ed32fb43233090ce7', 'First release, very early alpha so use it at your own risk only (although it can hardly break anything ...)', '', 1, 0, 0),
(37505, 0, 'cwenvbanner', 1, '0.0.2', 0, 0, 'Environment Banner', 'Adds a small Banner in both FE and BE and changes title tag to easier distinct between different Typo3 installations (hopefully no more "Ups - I was on Live all the time...")', 0, 0, 4, 1402653440, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"4.5.0-6.2.99";}}', 'Carsten Windler', 'carsten@carstenwindler.de', 'el_curtismo', '4a85b2e4a9ac6aa8fdb606608ee4f5eb', 'First bugfix (environment label rendered twice). Upon first installation, please make sure you save the configuration once, otherwise you will see nothing. Please also see the README.md until the documentation is complete. Im happy about feedback!\n\n', '', 2, 0, 0),
(37506, 0, 'cwenvbanner', 1, '0.0.3', 0, 0, 'Environment Banner', 'Adds a small Banner in both FE and BE and changes title tag to easier distinct between different Typo3 installations (hopefully no more "Ups - I was on Live all the time...")', 0, 0, 4, 1403680386, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"4.5.0-6.2.99";}}', 'Carsten Windler', 'carsten@carstenwindler.de', 'el_curtismo', 'b5f4a5961231622e9e22be7cdeaf4086', 'Important Bugfix: Fixed Typo3 crash on 6.x  Linux', '', 3, 0, 0),
(37507, 0, 'cwenvbanner', 1, '0.1.0', 0, 0, 'Environment Banner', 'Adds a small Banner in both FE and BE and changes title tag to easier distinct between different Typo3 installations (hopefully no more "Ups - I was on Live all the time...")', 1, 0, 4, 1408701981, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"4.5.0-6.2.99";s:3:"php";s:11:"5.3.0-0.0.0";}}', 'Carsten Windler', 'carsten@carstenwindler.de', 'el_curtismo', '4936dde41dde59df08bb0c447edfa7d1', 'New feature: predefined banner styles, code cleanup and such. PHP 5.2 support has been dropped! Please see readme.md for more details.', '', 1000, 0, 0),
(37508, 0, 'cwenvbanner', 1, '1.0.0', 0, 0, 'Environment Banner', 'Adds a small Banner in both FE and BE and changes title tag to easWier distinct between different Typo3 installations (hopefully no more "Ups - I was on Live all the time...")', 2, 0, 4, 1473017858, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:13:"7.5.0-7.99.99";}}', 'Carsten Windler', 'carsten@carstenwindler.de', 'el_curtismo', '9d777f21320a791b439698c19d250427', 'Maintenance update, no new features', '', 1000000, 1, 0),
