(37513, 0, 'sz_ebook', 1, '1.0.4', 0, 0, 'eBook', 'Converts PDFs to eBook, using turn.js, based on Extbase and Fluid. Works with Tablets and Smartphones.', 1, 0, 3, 1403790793, 'a:1:{s:7:"depends";a:3:{s:7:"extbase";s:3:"1.3";s:5:"fluid";s:3:"1.3";s:5:"typo3";s:12:"4.5.0-6.2.99";}}', 'Dennis Rmmich', 'dennis.roemmich@sunzinet.com', 'dennisr', '0f0ab51c76a8ad45918b36e8f8052032', 'init TypoScript settings for TaskController\r\nUpdate documentation\r\nThrow Exception if no TypoScript was found', 'sunzinet AG', 1000004, 0, 0),
(37514, 0, 'sz_ebook', 1, '1.0.5', 0, 0, 'eBook', 'Converts PDFs to eBook, using turn.js, based on Extbase and Fluid. Works with Tablets and Smartphones.', 1, 0, 3, 1407913406, 'a:1:{s:7:"depends";a:3:{s:7:"extbase";s:3:"1.3";s:5:"fluid";s:3:"1.3";s:5:"typo3";s:12:"4.5.0-6.2.99";}}', 'Dennis Rmmich', 'dennis.roemmich@sunzinet.com', 'dennisr', '19a149b32fbb277966edfbb8f7d82102', ' Fixes a bug, that throws an unexpected exception\r\n Fixes a bug, that displays an error, when no PDF was saved\r\n Some Codestyles', 'sunzinet AG', 1000005, 0, 0),
(37515, 0, 'sz_ebook', 1, '1.1.0', 0, 0, 'eBook', 'Shows eBooks in your browser, using turn.js and pdf.js, based on Extbase and Fluid. Works with Tablets and Smartphones.', 0, 0, 3, 1420470590, 'a:1:{s:7:"depends";a:3:{s:7:"extbase";s:3:"1.3";s:5:"fluid";s:3:"1.3";s:5:"typo3";s:12:"4.5.0-6.2.99";}}', 'Dennis Rmmich', 'dennis.roemmich@sunzinet.com', 'dennisr', '903bf95185c126f910853c73353278ff', 'Features:\r\n\r\nSwitch from Imagick to pdf.js\r\nNo Scheduler Task needed anymore\r\nFlip pages with arrow keys\r\nLink to a special Page using anchors\r\nPossibility to scale the eBook\r\nPreview Image is optional and will be the hard cover', 'sunzinet AG', 1001000, 0, 0),
(37516, 0, 'sz_ebook', 1, '2.0.0', 0, 0, 'eBook', 'Shows eBooks in your browser, \r\n        using turn.js and pdf.js, \r\n        based on Extbase and Fluid. Works with Tablets and Smartphones.', 0, 0, 3, 1484608250, 'a:1:{s:7:"depends";a:3:{s:7:"extbase";s:3:"1.3";s:5:"fluid";s:3:"1.3";s:5:"typo3";s:12:"6.2.0-7.6.99";}}', 'Dennis Rmmich', 'dennis@roemmich.eu', 'dennisr', '39690716d54ad2cbbfa0f12d8f9a1842', 'Add TYPO3 7.6 Support', 'sunzinet AG', 2000000, 0, 0);
