(37554, 0, 'formprocess', 1, '1.0.0', 0, 0, 'Form Process', 'This extension offers the opportunity to define a custom Post Processor for the TYPO3 form system extension. It also completely integrates itself into the TYPO3 Form Wizard.', 1, 0, 4, 1404213453, 'a:1:{s:7:"depends";a:2:{s:4:"form";s:3:"6.0";s:5:"typo3";s:12:"6.2.0-6.2.99";}}', 'Ben Walch', 'ben.walch@world-direct.at', 'ben-', '90349bd6ad6c791787e8cc94952ab81a', 'Initial Upload.', 'World Direct eBusiness solutions GmbH', 1000000, 1, 0),
(37555, 0, 'glpairs', 1, '0.8.0', 0, 0, 'Pairs', 'Provide a extension for creating a pairs game on a homepage. The you can configure the pairs game in many different types. You can assign two cards with the same image, two cards with similar images, two cards with an image and a description of the image or two text cards with the same description (i.e. in different languages)', 1, 0, 3, 1403516626, 'a:1:{s:7:"depends";a:4:{s:3:"php";s:12:"5.0.0-5.4.99";s:7:"extbase";s:11:"6.0.0-0.0.0";s:5:"fluid";s:11:"6.0.0-0.0.0";s:5:"typo3";s:12:"6.0.0-6.2.99";}}', 'Gerald Lo', 'gerald.loss@gmx.de', 'gerald_loss', 'cad340ac416f7cad90ab506abb97af8d', 'First beta version with cemprehensive developer test.\r\nAll important features are included.\r\nThe manual with a detailed tutorial is created.', '', 8000, 0, 0),
(37556, 0, 'glpairs', 1, '0.8.1', 0, 0, 'Pairs/Memory Card Game', 'Provide a extension for creating a pairs game on a homepage. You are able to configure the pairs game in many different types. You can assign two cards with the same image, two cards with similar images, two cards with an image and a description of the image or two text cards with the same description (i.e. in different languages)', 1, 0, 3, 1403623580, 'a:1:{s:7:"depends";a:4:{s:3:"php";s:12:"5.4.0-5.4.99";s:7:"extbase";s:11:"6.0.0-0.0.0";s:5:"fluid";s:11:"6.0.0-0.0.0";s:5:"typo3";s:12:"6.0.0-6.2.99";}}', 'Gerald Lo', 'gerald.loss@gmx.de', 'gerald_loss', 'bbf5edda74002a5cae2b3db604449f15', 'Bug fixing of the border width customization\r\nBug fixing of the animation of the cards in the chrome browser\r\nImproving of the manual.', '', 8001, 0, 0),
(37557, 0, 'glpairs', 1, '0.9.0', 0, 0, 'Pairs/Memory Card Game', 'Provide a extension for creating a pairs game on a homepage. You are able to configure the pairs game in many different types. You can assign two cards with the same image, two cards with similar images, two cards with an image and a description of the image or two text cards with the same description (i.e. in different languages)', 1, 0, 3, 1403713819, 'a:1:{s:7:"depends";a:4:{s:3:"php";s:12:"5.4.0-5.4.99";s:7:"extbase";s:11:"6.0.0-0.0.0";s:5:"fluid";s:11:"6.0.0-0.0.0";s:5:"typo3";s:12:"6.0.0-6.2.99";}}', 'Gerald Lo', 'gerald.loss@gmx.de', 'gerald_loss', 'bcd4693bc33a1db647913c85b70905cf', 'Some more options in the backend for adjust the animation speed of the frontend.\r\n\r\nAttention!!! Attention!!! Attention!!! Attention!!!\r\nIf you have already setup a pairs, you need to go there and fill sane parameters for the new options in the backend. O', '', 9000, 0, 0),
(37558, 0, 'glpairs', 1, '0.9.1', 0, 0, 'Pairs/Memory Card Game', 'Provide a very flexible pairs game. You are able to configure the pairs game in many different types. You can assign two cards with the same image, two cards with similar images, two cards with an image and a description of the image or two text cards with the same description (i.e. in different languages)', 1, 0, 3, 1405465221, 'a:1:{s:7:"depends";a:4:{s:3:"php";s:12:"5.4.0-5.4.99";s:7:"extbase";s:11:"6.0.0-0.0.0";s:5:"fluid";s:11:"6.0.0-0.0.0";s:5:"typo3";s:12:"6.0.0-6.2.99";}}', 'Gerald Lo', 'gerald.loss@gmx.de', 'gerald_loss', 'd1675bb3d975f3e23eed4f5220de44e1', 'Fixed a major bug with the caching. Because of the cache the pairs didnt response after the second access.\r\nLots of tests on different browsers with the animations\r\nFixed some minor bugs', '', 9001, 0, 0),
(37559, 0, 'glpairs', 1, '0.9.2', 0, 0, 'Pairs/Memory Card Game', 'Provide a very flexible pairs game. You are able to configure the pairs game in many different types. You can assign two cards with the same image, two cards with similar images, two cards with an image and a description of the image or two text cards with the same description (i.e. in different languages)', 1, 0, 3, 1405639440, 'a:1:{s:7:"depends";a:4:{s:3:"php";s:12:"5.4.0-5.4.99";s:7:"extbase";s:11:"6.0.0-0.0.0";s:5:"fluid";s:11:"6.0.0-0.0.0";s:5:"typo3";s:12:"6.0.0-6.2.99";}}', 'Gerald Lo', 'gerald.loss@gmx.de', 'gerald_loss', '30454de2f80b149606baa130a715fd85', 'Fixed a bug with the animation on the card stack with chrome on slow computers.\r\n', '', 9002, 0, 0),
(37560, 0, 'glpairs', 1, '1.0.0', 0, 0, 'Pairs/Memory Card Game', 'Provide a very flexible pairs game. You are able to configure the pairs game in many different types. You can assign two cards with the same image, two cards with similar images, two cards with an image and a description of the image or two text cards with the same description (i.e. in different languages). See an example on http://www.schulze-thulin.de/en/games/pairs/', 2, 0, 3, 1407537181, 'a:0:{}', 'Gerald Lo', 'gerald.loss@gmx.de', 'gerald_loss', 'bd9997f7c306af9fc3dbbc4587a80d39', 'After a long time of testing switch to a stable state.\r\nA test mode is available for checking the configuration of a pairs game. See the tutorial in the documentation for details.', '', 1000000, 0, 0),
