(37569, 0, 'glpairs', 1, '2.0.0', 0, 0, 'Pairs/Memory Card Game', 'Provide a flexible pairs game. You are able to configure the pairs game in many different types. You can assign two cards with the same image, two cards with similar images, two cards with an image and a description of the image or two text cards with the same description (i.e. in different languages). See an example on http://www.schulze-thulin.de/en/games/pairs-german-welsh-irish/', 2, 0, 3, 1489715267, 'a:1:{s:7:"depends";a:4:{s:3:"php";s:12:"5.4.0-5.6.99";s:7:"extbase";s:11:"6.0.0-0.0.0";s:5:"fluid";s:11:"6.0.0-0.0.0";s:5:"typo3";s:12:"6.0.0-7.6.99";}}', 'Gerald Lo', 'gerald.loss@gmx.de', 'gerald_loss', 'c0e4d084839ac881931f20273da4a0e4', '!!!Attention!!!\r\nSince this version you need a static template. See chapter Configuration in the manual.\r\n!!!Attention!!!\r\nChanging to jQuery 3.x and Bootstrap 3.x\r\nRemoving jQuery UI Library\r\n', '', 2000000, 0, 0),
(37570, 0, 'glpairs', 1, '2.0.1', 0, 0, 'Pairs/Memory Card Game', 'Provide a flexible pairs game. You are able to configure the pairs game in many different types. You can assign two cards with the same image, two cards with similar images, two cards with an image and a description of the image or two text cards with the same description (i.e. in different languages). See an example on http://www.schulze-thulin.de/en/games/pairs-german-welsh-irish/', 2, 0, 3, 1489890823, 'a:1:{s:7:"depends";a:4:{s:3:"php";s:12:"5.4.0-5.6.99";s:7:"extbase";s:11:"6.0.0-0.0.0";s:5:"fluid";s:11:"6.0.0-0.0.0";s:5:"typo3";s:12:"6.0.0-7.6.99";}}', 'Gerald Lo', 'gerald.loss@gmx.de', 'gerald_loss', 'f1859ea183e40f8386c76935f39c5808', '!!!Attention!!!\r\nSince this version you need a static template. See chapter Configuration in the manual.\r\n!!!Attention!!!\r\n\r\nSome minor improvements with the documentation.\r\nSome bugfixing with the layout.', '', 2000001, 1, 0),
