(37738, 0, 'exl_page_advanced', 1, '0.1.0', 0, 0, 'Page Advanced', 'Adds a preview of a pages edition directly by using the "Page" module. Meaning you can for example modify categories, title, etc.', 1, 0, 4, 1406294126, 'a:1:{s:7:"depends";a:3:{s:7:"extbase";s:3:"6.2";s:5:"fluid";s:3:"6.2";s:5:"typo3";s:12:"6.2.0-6.2.99";}}', 'Romain CANON', 'romain.canon@exl-group.com', 'romm', '9af349ec8af5c5b6752c3d140872d983', 'Initial release.', 'EXL Group', 1000, 0, 0),
(37739, 0, 'exl_page_advanced', 1, '0.1.1', 0, 0, 'Page Advanced', 'Edit page properties directly in the page module. Its useful for example when you want to edit categories  without having to click several times. You can use TSConfig to add several fields to edit, by default add the TYPO3 6.2 categories field.', 1, 0, 4, 1406295297, 'a:1:{s:7:"depends";a:3:{s:7:"extbase";s:3:"6.2";s:5:"fluid";s:3:"6.2";s:5:"typo3";s:12:"6.2.0-6.2.99";}}', 'Romain CANON', 'romain.canon@exl-group.com', 'romm', 'c3c9db3a5d8f956d519927c133be5c7f', 'Some minor extension modifications.', 'EXL Group', 1001, 1, 0),
(37740, 0, 'videoce', 1, '0.5.0', 0, 0, 'Video Content Element', 'Another ctype for external videos, currently youtube and vimeo videos are supported. The default media ctype is a little bit to complicated for CMS enduser.', 1, 0, 4, 1406394808, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:12:"6.2.0-6.2.99";s:7:"extbase";s:12:"6.2.0-6.2.99";s:5:"fluid";s:12:"6.2.0-6.2.99";}}', 'Pascal Mayer', 'typo3@simple.ch', 'laxap', 'da30d69fcb75aed694d06ff8b1dd5f99', 'Initial upload.', 'simplicity gmbh', 5000, 0, 0),
