(37805, 0, 'bsdist', 1, '2.0.2', 0, 0, 'Bootstrap Kickstart Package', 'Kickstart package to create a new TYPO3 website. Delivers a simple page tree for a new website based on the bootstrap framework. Ads bootstrap layout features to some of the content elements.', 2, 0, 10, 1495606925, 'a:2:{s:7:"depends";a:5:{s:5:"typo3";s:12:"8.7.0-8.7.99";s:20:"fluid_styled_content";s:12:"8.7.0-8.7.99";s:9:"scheduler";s:12:"8.7.0-8.7.99";s:8:"recycler";s:12:"8.7.0-8.7.99";s:7:"realurl";s:12:"	2.2.0-0.0.0";}s:9:"conflicts";a:2:{s:18:"css_styled_content";s:1:"*";s:17:"bootstrap_package";s:1:"*";}}', 'Pascal Mayer', 'typo3@bsdist.ch', 'laxap', 'e3446a1159cdb8c2d5f4d56b08e07c98', '- switch to ckeditor. optional custom config added. removed rtehtmleditor config, \r\n- felogin tmpl: pwd field attribute added', '', 2000002, 1, 0);
