(37919, 0, 'includekrexx', 1, '0.1.2', 0, 0, 'Include kreXX', 'kreXX is a php debug tool, which displays debug information about objects and variables in its own draggable debug output.', 1, 0, 2, 1409913255, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"4.5.0-6.2.99";s:3:"php";s:12:"5.3.0-5.5.99";}}', 'BRAINWORXX GmbH', 'tobias.guelzow@brainworxx.de', 'moorth', '17f7aa6250d0f9956332e831da524639', 'Updated to kreXX 1.0.1. Updates include PHP 5.3 fixes and support for inherited comments in the class analysis.', '', 1002, 0, 0),
