(37922, 0, 'includekrexx', 1, '1.0.0', 0, 0, 'Include kreXX', 'kreXX is a php debugger, which displays debug information about objects and variables in its own draggable output.', 2, 0, 2, 1417524311, 'a:1:{s:7:"depends";a:4:{s:5:"typo3";s:12:"4.5.0-6.2.99";s:3:"php";s:12:"5.3.0-5.5.99";s:7:"extbase";s:11:"1.3.0-0.0.0";s:5:"fluid";s:11:"1.3.0-0.0.0";}}', 'BRAINWORXX GmbH', 'tobias.guelzow@brainworxx.de', 'moorth', '01220ceed4fe941fb930006cd73382ef', 'Updated to kreXX 1.2.0. Updates include reduced memory usage, bugfixes and a settings editor in the backend.', '', 1000000, 0, 0),
(37923, 0, 'includekrexx', 1, '1.1.0', 0, 0, 'Include kreXX', 'kreXX is a php debugger with a fatal error handler. It displays debug information about objects and variables in its own draggable output.', 2, 0, 2, 1422892642, 'a:1:{s:7:"depends";a:4:{s:5:"typo3";s:12:"4.5.0-7.0.99";s:3:"php";s:12:"5.3.0-5.5.99";s:7:"extbase";s:11:"1.3.0-0.0.0";s:5:"fluid";s:11:"1.3.0-0.0.0";}}', 'BRAINWORXX GmbH', 'tobias.guelzow@brainworxx.de', 'moorth', '6cfb59251be58371444dc87413a3eb0b', 'Updated to kreXX 1.3.0. Added search and collapse functions to the Hans skin, as well as bugfixes. The frontend editing is now configurable in the backend.', 'BRAINWORXX GmbH', 1001000, 0, 0),
