(37927, 0, 'includekrexx', 1, '1.3.4', 0, 0, 'Include kreXX', 'kreXX is a php debugger with a fatal error handler. It displays debug information about objects and variables in its own draggable output.', 2, 0, 2, 1439034965, 'a:1:{s:7:"depends";a:4:{s:5:"typo3";s:12:"4.5.0-7.4.99";s:3:"php";s:12:"5.3.0-5.5.99";s:7:"extbase";s:11:"1.3.0-0.0.0";s:5:"fluid";s:11:"1.3.0-0.0.0";}}', 'BRAINWORXX GmbH', 'tobias.guelzow@brainworxx.de', 'moorth', '6ab085b984f305dc3069ccb18f0a3203', 'Updated to Typo3 7.4. Added Closure analysis as well as a few bugfixes.', 'BRAINWORXX GmbH', 1003004, 0, 0),
