(38064, 0, 'mkphpids', 1, '1.5.0', 0, 0, 'TYPO3 Security / Intrusion Detection System', 'Currently the PHPIDS detects all sorts of XSS, SQL Injection, header injection, directory traversal, RFE/LFI, DoS and LDAP attacks. Through special conversion algorithms the PHPIDS is even able to detect heavily obfuscated attacks.', 2, 0, 3, 1410435153, 'a:1:{s:7:"depends";a:6:{s:3:"php";s:11:"5.1.6-0.0.0";s:5:"typo3";s:12:"4.4.0-6.2.99";s:3:"cms";s:0:"";s:4:"core";s:0:"";s:8:"frontend";s:0:"";s:7:"rn_base";s:0:"";}}', 'Hannes Bochmann', 'dev@dmk-ebusiness.de', 'dasmedienkombinatgmbh', '80b373c957d721fe48ea9a4f59e80093', 'initial release', 'DMK E-BUSINESS', 1005000, 0, 0),
