(38088, 0, 'fal_sftp', 1, '0.2.4', 0, 0, 'fal_sftp', 'This FAL 2.0 Driver enables TYPO3 to connect to remote hosts via SFTP', 1, 0, 0, 1410797079, 'a:1:{s:7:"depends";a:2:{s:7:"extbase";s:12:"6.2.0-6.2.99";s:5:"typo3";s:12:"6.2.0-6.2.99";}}', 'Oliver Eglseder', 'oliver.eglseder@in2code.de', 'vertexvaar', 'fc8158b8cf9603858ec0d7bf74c777a3', 'This version is a BETA version. Ill come up with a manual soon.\r\n\r\nRequirements:\r\n TYPO3 6.2.\r\n php Extension ssh2\r\n\r\nInstallation;\r\n1. Install from TER\r\n2. New File-Stroage on root (id0)\r\n3. Enter configuration\r\n\r\nHelp:\r\nIf something does not seem t', 'in2code GmbH', 2004, 0, 0),
(38089, 0, 'fal_sftp', 1, '0.2.5', 0, 0, 'fal_sftp', 'This FAL 2.0 Driver enables TYPO3 to connect to remote hosts via SFTP', 1, 0, 0, 1410989382, 'a:1:{s:7:"depends";a:2:{s:7:"extbase";s:12:"6.2.0-6.2.99";s:5:"typo3";s:12:"6.2.0-6.2.99";}}', 'Oliver Eglseder', 'oliver.eglseder@in2code.de', 'vertexvaar', '46f76bfc7c71cea801ccc1b73d7113f6', 'Add Documentation', 'in2code GmbH', 2005, 0, 0),
(38090, 0, 'fal_sftp', 1, '0.2.6', 0, 0, 'fal_sftp', 'This FAL 2.0 Driver enables TYPO3 to connect to remote hosts via SFTP', 1, 0, 0, 1413405460, 'a:1:{s:7:"depends";a:2:{s:7:"extbase";s:12:"6.2.0-6.2.99";s:5:"typo3";s:12:"6.2.0-6.2.99";}}', 'Oliver Eglseder', 'oliver.eglseder@in2code.de', 'vertexvaar', 'eb60e5462ab7f56638f504035d1ae516', 'Small fixes and one big bugfix (permissions).\r\n\r\nHopefully the Docs will render this time', 'in2code GmbH', 2006, 0, 0),
(38091, 0, 'fal_sftp', 1, '0.2.7', 0, 0, 'fal_sftp', 'This FAL 2.0 Driver enables TYPO3 to connect to remote hosts via SFTP', 1, 0, 0, 1417859761, 'a:1:{s:7:"depends";a:2:{s:7:"extbase";s:12:"6.2.0-6.2.99";s:5:"typo3";s:12:"6.2.0-6.2.99";}}', 'Oliver Eglseder', 'oliver.eglseder@in2code.de', 'vertexvaar', '0a41bbd023097a702e7151ebad14c25e', 'Small bugfix, thanks to Jost Baron again ;)\r\n', 'in2code GmbH', 2007, 1, 0),
