(38096, 0, 'powermailext', 1, '1.0.0', 0, 0, 'Powermail Extended', 'This extension extends powermail', 1, 0, 3, 1410871333, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:12:"6.2.0-6.2.99";s:9:"powermail";s:12:"2.1.1-2.1.99";s:18:"static_info_tables";s:12:"6.1.0-6.1.99";}}', 'Ben Walch', 'ben.walch@world-direct.at', 'ben-', '1e732eb81d73a09ededc1bac3389b615', 'Powermail Ext\r\nThis Extension was developed to add some functionality powermail.\r\n\r\nFeatures\r\n Dependencies for Fields of other Fields: Conditional Validation and Display\r\n Additional Validators (IBAN, Birthdate 18)\r\n Additional HTML Tag Attributes (m', '', 1000000, 0, 0),
