(38098, 0, 'powermailext', 1, '1.2.0', 0, 0, 'Powermail Extended', 'This Extension was developed to add some functionality powermail. Features: Dependencies for Fields of other Fields: Conditional Validation and Display, Additional Validators (IBAN, Birthdate 18), Additional HTML Tag Attributes (maxlength, disabled, readonly) for Input/Select Fields, Viewhelper for correct Text Answer in Confirmation View for Radiobuttons and Checkboxes', 1, 0, 3, 1432109296, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:12:"6.2.0-6.2.99";s:9:"powermail";s:12:"2.1.1-2.9.99";s:18:"static_info_tables";s:12:"6.1.0-6.2.99";}}', 'Ben Walch', 'ben.walch@world-direct.at', 'ben-', 'b434fec8418919fcc8bbb49f2949968f', 'updated emconf', '', 1002000, 0, 0),
