(38307, 0, 'tslib_fetce', 1, '0.0.0', 0, 0, 'tslib_feTCE', 'It brings the deprecated TYPO3 4.x class tslib_feTCE back into TYPO3 6.x. This is needed by tt_board and tt_guest.', 2, 0, 3, 1413919716, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:12:"5.3.0-5.5.99";s:5:"typo3";s:12:"6.1.0-6.2.99";}}', 'Franz Holzinger', 'franz@ttproducts.de', 'franzholz', '74a9c26bea9a07ded9459dafa0760d67', ' \nUse this extension for tt_board and tt_guest under TYPO3 6.2.\n', 'jambage.com', 0, 0, 0),
(38308, 0, 'tslib_fetce', 1, '0.1.0', 0, 0, 'Frontend TCE', 'It brings the deprecated TYPO3 4.x class tslib_feTCE and the processScript FEData setup back into TYPO3 7.x. This is needed by tt_board and tt_guest. For TYPO3 6.2 use version 0.0.1. For form MAIL and form wizards use the extension compatibility6.', 2, 0, 3, 1470162714, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:13:"5.3.0-7.99.99";s:5:"typo3";s:12:"7.2.0-7.8.99";}}', 'Franz Holzinger', 'franz@ttproducts.de', 'franzholz', 'a147d73b480e951981def70b503102c6', '\nsupport for TYPO3 7.6.10. Remove the MAIL feature. \n', 'jambage.com', 1000, 0, 0),
(38309, 0, 'tslib_fetce', 1, '0.2.0', 0, 0, 'Frontend TCE', 'It brings the deprecated TYPO3 4.x class tslib_feTCE and the processScript FEData setup back into TYPO3 7.x. This is needed by tt_board and tt_guest. For TYPO3 6.2 use version 0.0.1. For form MAIL and form wizards use the extension compatibility6.', 2, 0, 3, 1501152237, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:13:"5.3.3-7.99.99";s:5:"typo3";s:13:"7.2.0-8.99.99";}}', 'Franz Holzinger', 'franz@ttproducts.de', 'franzholz', 'fe5dc79a267855fb13831feddf42f39d', '\nSupport for TYPO3 8.7.x . PHP files are allowed under any path.\n', 'jambage.com', 2000, 0, 0),
(38310, 0, 'tslib_fetce', 1, '0.3.0', 0, 0, 'Frontend TCE', 'It brings the deprecated TYPO3 4.x class tslib_feTCE and the processScript FEData setup with new features partly back into TYPO3 8.x. This is needed by tt_board and tt_guest. Form MAIL and form wizards require the extension compatibility6.', 2, 0, 3, 1505205879, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:13:"5.5.0-7.99.99";s:5:"typo3";s:13:"7.6.0-8.99.99";}}', 'Franz Holzinger', 'franz@ttproducts.de', 'franzholz', '14428040557bdc15075d810ff042e494', ' \nsupport for a namespace class call with processScript  setup\n', 'jambage.com', 3000, 0, 0),
