(38492, 0, 'cookie_consent', 1, '1.0.0', 0, 0, 'Cookie consent', 'Show information and get consent for tracking cookies. Handles "doNotTrack" setting from browser automatically. Javascript based. Needs jQuery.', 2, 0, 2, 1419252094, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:12:"5.3.3-5.6.99";s:5:"typo3";s:13:"6.2.0-7.99.99";}}', 'Patrick Broens', 'patrick@patrickbroens.nl', 'patrick', 'e7b69e9eeb5fc2588f794cc05d37c364', 'Initial upload', '', 1000000, 0, 0),
(38493, 0, 'cookie_consent', 1, '2.0.0', 0, 0, 'Cookie consent', 'Show information and get consent for tracking cookies. Handles "doNotTrack" setting from browser automatically. Filters out unwanted tracking scripts by AOP. Javascript based. Needs jQuery.', 2, 0, 2, 1449763156, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"7.6.0-7.6.99";}}', 'Patrick Broens', 'patrick@patrickbroens.nl', 'patrick', '689fac04f84a56f0d0629f4eda15108a', 'Replaced the controller with TypoScript call to FLUIDTEMPLATE\r\nAdded the possibility to deny the browser DNT setting\r\nAdded the possibility to hide/show the deny button, which is new as well\r\nAdded a TypoScript condition to check if cookie is accepted or ', '', 2000000, 0, 0);
