(38498, 0, 'crt_metatags', 1, '0.0.1', 0, 0, 'Cretection: Metatags', 'Organisiert die TYPO3 Metatags inklusive Dublin Core und bald OpenGraph-Informationen', 1, 0, 3, 1419801636, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.1.0-6.2.99";}}', 'Jonathan Starck', 'support@cretection.eu', 'cretection', 'a30d371f2de7b6e682e709f996e0e98c', 'Initial Upload.', '', 1, 1, 0),
