(38536, 0, 'stores', 1, '0.1.5', 0, 0, 'Stores', 'Plugin to search for stores and show them in responsive Google maps with driving routes.', 1, 0, 3, 1420978285, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.2.0-6.2.99";}}', 'Joachim Ruhs', 'postmaster@joachim-ruhs.de', 'joachim_ruhs', 'ee2394ecca1195c2a92817cbac1b765f', 'Google maps now full responsive. Templates changed in javascript function resize().', 'Web Services Ruhs', 1005, 0, 0),
(38537, 0, 'stores', 1, '0.1.6', 0, 0, 'Stores', 'Plugin to search for stores and show them in responsive Google maps with driving routes.', 1, 0, 3, 1424177925, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.2.0-6.2.99";}}', 'Joachim Ruhs', 'postmaster@joachim-ruhs.de', 'joachim_ruhs', '04061fa381c73cc9cdc7112c038a2351', 'Bugfix in setup.txt. New configuration option includejQueryCore.', 'Web Services Ruhs', 1006, 0, 0),
(38538, 0, 'stores', 1, '0.1.7', 0, 0, 'Stores', 'Plugin to search for stores and show them in responsive Google maps with driving routes. Single view implemented too.', 1, 0, 3, 1424622837, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.2.0-6.2.99";}}', 'Joachim Ruhs', 'postmaster@joachim-ruhs.de', 'joachim_ruhs', 'f0e652efc44bb9ea951ec63c9124de1f', 'The store search works now with storagePid - this way you could use different storage pages for different store categories. Bugfix in singleView-Template.', 'Web Services Ruhs', 1007, 0, 0),
(38539, 0, 'stores', 1, '0.1.8', 0, 0, 'Stores', 'Plugin to search for stores and show them in responsive Google maps with driving routes. Single view implemented too.', 1, 0, 3, 1447588451, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.2.0-6.2.99";}}', 'Joachim Ruhs', 'postmaster@joachim-ruhs.de', 'joachim_ruhs', '38ac14b3b0935978f70f0c4eb1bc417a', 'Signals implemented in singleView action, search action and route action for extending the functionality for you needs.', 'Web Services Ruhs', 1008, 0, 0),
(38540, 0, 'stores', 1, '0.2.1', 0, 0, 'Stores', 'Plugin to search for stores and show them in responsive Google maps with driving routes. Single view implemented too.', 1, 0, 3, 1468425586, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.2.0-7.6.99";}}', 'Joachim Ruhs', 'postmaster@joachim-ruhs.de', 'joachim_ruhs', 'ada1f011aad1240b20b129790b4d52d4', 'Google Browser and Google Server keys implemented. Insert them with the constant editor. Templates changed (loading Google maps API with key). The Google server API key is used for geocoding.', 'Web Services Ruhs', 2001, 1, 0),
