(38576, 0, 'simplefaq', 1, '1.0.0', 0, 0, 'Simple FAQs', 'A simple FAQ Extension.', 2, 0, 3, 1421351269, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:12:"6.0.0-6.2.99";s:5:"fluid";s:12:"6.0.0-6.2.99";s:7:"extbase";s:12:"6.0.0-6.2.99";}}', 'Mark Kirstein', 'mark.kirstein@sector12.de', 'sector12', '95a42dfceedc4ab8ee17edd8e3bddb19', 'Just a simple possibility for FAQs as typical content element with different themes. Customizable with css / sass. No typoscript integration needed. Faq Articles as IRRE elements.', '', 1000000, 0, 0),
(38577, 0, 'simplefaq', 1, '1.1.0', 0, 0, 'Simple FAQ', 'A simple FAQ Extension. Uses IRRE for FAQ articles. Easy to use, no configuration is needed. Adds a new Simple FAQ content element to the common content elements list.', 2, 0, 3, 1421693498, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:12:"6.2.0-7.9.99";s:5:"fluid";s:12:"6.2.0-7.9.99";s:7:"extbase";s:12:"6.2.0-7.9.99";}}', 'Mark Kirstein', 'mark.kirstein@sector12.de', 'sector12', 'bae657e21c16f5476ae746f068924fa0', 'Recoded core for better performance.\r\n\r\nAdds the possibility ti use custom css and fluid templates.', '', 1001000, 0, 0),
(38578, 0, 'simplefaq', 1, '1.2.0', 0, 0, 'Simple FAQ', 'A simple FAQ Extension. Uses IRRE for FAQ articles. Easy to use, no configuration is needed. Adds a new Simple FAQ content element to the common content elements list.', 2, 0, 3, 1421696920, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:12:"6.2.0-7.9.99";s:5:"fluid";s:12:"6.2.0-7.9.99";s:7:"extbase";s:12:"6.2.0-7.9.99";}}', 'Mark Kirstein', 'mark.kirstein@sector12.de', 'sector12', '42cf801319d4b0abc437fa9e3f787514', 'Manual added...', '', 1002000, 0, 0),
(38579, 0, 'simplefaq', 1, '1.3.0', 0, 0, 'Simple FAQ', 'A simple FAQ Extension. Uses IRRE for FAQ articles. Easy to use, no configuration is needed. Adds a new Simple FAQ content element to the common content elements list.', 2, 0, 3, 1422386595, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:12:"6.2.0-7.9.99";s:5:"fluid";s:12:"6.2.0-7.9.99";s:7:"extbase";s:12:"6.2.0-7.9.99";}}', 'Mark Kirstein', 'mark.kirstein@sector12.de', 'sector12', 'ed17e41c8da2dc30c3cca88e5d73319a', 'Just code improvements in the controller and view.', '', 1003000, 0, 0),
(38580, 0, 'simplefaq', 1, '1.4.0', 0, 0, 'Simple FAQ', 'A simple FAQ Extension. Uses IRRE for FAQ articles. Easy to use, no configuration is needed. Adds a new Simple FAQ content element to the common content elements list.', 2, 0, 3, 1423494885, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:12:"6.2.0-7.9.99";s:5:"fluid";s:12:"6.2.0-7.9.99";s:7:"extbase";s:12:"6.2.0-7.9.99";}}', 'Mark Kirstein', 'mark.kirstein@sector12.de', 'sector12', 'b188d9220528f1057c0ea753534b40d3', 'Add a colorpicker to change the colors as you want. Take a look in the manual to see how easy you can change the complete look and feel without knowledge of css. Just pick your favorite color for text, borders, background colors and border-radius, too.\r\n\r', '', 1004000, 1, 0),
