(38707, 0, 'pixelink_newsletter', 1, '1.0.0', 0, 0, 'Pixelink Newsletter', 'Create cleverreach newsletter from TYPO3 page', 0, 0, 1, 1424356067, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.2.0-6.2.99";}}', 'Lukas Jakob', 'lu.jakob@googlemail.com', 'pixelink', '1be7bffbb32ff0d551c8ac7340cdca7c', 'The extension provides a possibility to send any page in your TYPO3 Installation to the newsletter provider "Cleverreach".\r\nIt sends an HTML and Text version of the page to CleverReach\r\n\r\nPlease keep in mind that you still have to submit the newsletter to', '', 1000000, 1, 0),
(38708, 0, 'simplepoll', 1, '1.0.0', 0, 0, 'Simple Poll', 'An easy to setup and use poll system', 1, 0, 3, 1424356732, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:12:"6.2.0-6.2.99";s:7:"extbase";s:3:"6.2";s:5:"fluid";s:3:"6.2";}}', 'Alex Bigott', 'support@pixel-ink.de', 'pixelink', 'dbbcaebbbf82a17684ca14be8a1328e5', 'Create a simple poll. If youll in need of any improvements or have some suggestions send an E-Mail to support@pixel-ink.de\r\n\r\nThx Alex for the coding', '', 1000000, 0, 0),
(38709, 0, 'simplepoll', 1, '1.0.2', 0, 0, 'Simple Poll', 'An easy to setup and use poll system', 2, 0, 3, 1425656755, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.2.0-6.2.99";}}', 'Alex Bigott', 'support@pixel-ink.de', 'pixelink', '06816b2d2d8502f33a9a6c0cf9ea7849', 'Removed current date as end date since like that the poll was not shown by default. End date is now empty which is allowed since 1.0.1', '', 1000002, 0, 0),
