(38713, 0, 'simplepoll', 1, '1.0.7', 0, 0, 'Simple Poll', 'An easy to setup and use poll system', 2, 0, 3, 1473616394, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.2.0-7.9.99";}}', 'Alex Bigott / Pixel Ink', 'support@pixel-ink.de', 'pixelink', '435c326080be69353501de2443063ed0', 'Option added to sum up voting results within different languages. \r\nTCA removed from ext_tables.php for future compatibility.', '', 1000007, 0, 0),
