(38716, 0, 'simplepoll', 1, '1.1.1', 0, 0, 'Simple Poll', 'An easy to setup and use poll system', 2, 0, 3, 1485114787, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.2.0-7.9.99";}}', 'Alex Bigott / Pixel Ink', 'support@pixel-ink.de', 'pixelink', 'b570e07b4d91acca747d70d2ccf7ddaa', 'Bugfix Version\r\nUsage of data attribute in fluid caused exception.', '', 1001001, 0, 0),
(38717, 0, 'simplepoll', 1, '2.0.0', 0, 0, 'Simple Poll', 'An easy to setup and use poll system', 2, 0, 3, 1493061752, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"7.6.0-8.9.99";}}', 'Alex Bigott / Pixel Ink', 'support@pixel-ink.de', 'pixelink', '39fc26835bd33821f9e364f6f5c4a1db', 'Works now with TYPO3 8.7 \r\nRemoved compatibility for TYPO3 6.2.\r\nIf you need 6.2 support its available via github.com tag v1.1.2', '', 2000000, 0, 0),
