(38757, 0, 'groupdocs_annotation_for_net', 1, '1.0', 0, 0, 'GroupDocs.Annotation for .NET', 'This extension allows you to integrate the downloadable .NET version of the GroupDocs.Annotation into TYPO3 CMS. Once installed, you will be able to display over 50 types of documents and images along with an annotation toolbar on any page within your TYPO3 website. Supported file formats include: PDF, Microsoft Word, Excel, PowerPoint, Visio, Outlook, Project, OpenDocument, AutoCAD and raster images. Among key benefits of the GroupDocs.Annotation for .NET are: 1. Documents embedded to your website can be viewed and annotated from any web-enabled device and using any standard web-browser. Your website visitors dont have to install any office software or browser plugins. 2. A comprehensive set of annotation tools, including: sticky notes, rectangles, polyline, arrows, watermarks, redaction, text underline/strikethrough and ruler. 3. Several users can review and annotate the same document simultaneously, each seeing others comments in real time. 4. Documents annotated online on your website can then be exported to a PDF file or printed out with annotations in them. 5. Thanks to the built-in Digital Rights Management feature, you can prevent users from copying, downloading and printing the documents you share on your website. Please note that this plugin requires the GroupDocs.Annotation for .NET library to be installed on your server first. You can download a free evaluation copy of the library from the GroupDocs website: https://groupdocs.com/dot-net/document-annotation-library', 1, 0, 3, 1425028203, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"4.5.0-6.1.99";}}', 'GroupDocs Marketplace Team', 'support@groupdocs.com', 'groupdocs', '4db7c09b1607e98cad546e3a2c9d4dee', 'This extension allows you to integrate the downloadable .NET version of the GroupDocs.Annotation into TYPO3 CMS. Once installed, you will be able to display over 50 types of documents and images along with an annotation toolbar on any page within your TYP', '', 1000000, 0, 0),
(38758, 0, 'groupdocs_annotation_for_net', 1, '1.0.1', 0, 0, 'GroupDocs.Annotation for .NET', 'This extension allows you to integrate the downloadable .NET version of the GroupDocs.Annotation into TYPO3 CMS. Once installed, you will be able to display over 50 types of documents and images along with an annotation toolbar on any page within your TYPO3 website. Supported file formats include: PDF, Microsoft Word, Excel, PowerPoint, Visio, Outlook, Project, OpenDocument, AutoCAD and raster images. Among key benefits of the GroupDocs.Annotation for .NET are: 1. Documents embedded to your website can be viewed and annotated from any web-enabled device and using any standard web-browser. Your website visitors dont have to install any office software or browser plugins. 2. A comprehensive set of annotation tools, including: sticky notes, rectangles, polyline, arrows, watermarks, redaction, text underline/strikethrough and ruler. 3. Several users can review and annotate the same document simultaneously, each seeing others comments in real time. 4. Documents annotated online on your website can then be exported to a PDF file or printed out with annotations in them. 5. Thanks to the built-in Digital Rights Management feature, you can prevent users from copying, downloading and printing the documents you share on your website. Please note that this plugin requires the GroupDocs.Annotation for .NET library to be installed on your server first. You can download a free evaluation copy of the library from the GroupDocs website: https://groupdocs.com/dot-net/document-annotation-library', 1, 0, 3, 1425028494, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"4.5.0-6.1.99";}}', 'GroupDocs Marketplace Team', 'support@groupdocs.com', 'groupdocs', 'e872589527cbee1849d0b4e04ebe45e5', 'This extension allows you to integrate the downloadable .NET version of the GroupDocs.Annotation into TYPO3 CMS. Once installed, you will be able to display over 50 types of documents and images along with an annotation toolbar on any page within your TYP', '', 1000001, 0, 0),
(38759, 0, 'groupdocs_annotation_for_net', 1, '1.0.2', 0, 0, 'GroupDocs.Annotation for .NET', 'This extension allows you to integrate the downloadable .NET version of the GroupDocs.Annotation into TYPO3 CMS. Once installed, you will be able to display over 50 types of documents and images along with an annotation toolbar on any page within your TYPO3 website. Supported file formats include: PDF, Microsoft Word, Excel, PowerPoint, Visio, Outlook, Project, OpenDocument, AutoCAD and raster images. Among key benefits of the GroupDocs.Annotation for .NET are: 1. Documents embedded to your website can be viewed and annotated from any web-enabled device and using any standard web-browser. Your website visitors dont have to install any office software or browser plugins. 2. A comprehensive set of annotation tools, including: sticky notes, rectangles, polyline, arrows, watermarks, redaction, text underline/strikethrough and ruler. 3. Several users can review and annotate the same document simultaneously, each seeing others comments in real time. 4. Documents annotated online on your website can then be exported to a PDF file or printed out with annotations in them. 5. Thanks to the built-in Digital Rights Management feature, you can prevent users from copying, downloading and printing the documents you share on your website. Please note that this plugin requires the GroupDocs.Annotation for .NET library to be installed on your server first. You can download a free evaluation copy of the library from the GroupDocs website: https://groupdocs.com/dot-net/document-annotation-library', 1, 0, 3, 1425298981, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"4.5.0-6.1.99";}}', 'GroupDocs Marketplace Team', 'support@groupdocs.com', 'groupdocs', 'cb9d85b71508b87eabf4bdf021b296c3', 'This extension allows you to integrate the downloadable .NET version of the GroupDocs.Annotation into TYPO3 CMS.', '', 1000002, 1, 0),
