(39057, 0, 'start', 1, '1.0.3', 0, 0, 'Starter Kit Responsive', 'TYPO3 Starter Kit optimised for desktops, tablets and smartphones. Provides 12 ready-to-use backend layouts. Based on the responive Foundation framework (Zurb). Manual: http://typo3-start.deEXT:start/doc/manual.pdf. ', 3, 0, 0, 1429737214, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.2.0-7.0.99";}}', 'Dirk Wildt (Die Netzmacher)', 'http://wildt.at.die-netzmacher.de', 'dwildt', '2a3c2c321d7b804834b2de752fe16449', '1.1.0 Initial Release', '', 1000003, 0, 0),
(39058, 0, 'start', 1, '2.1.1', 0, 0, 'Start TYPO3 Responsive!', 'Start is installing and managing a responsive TYPO3 - optimised for desktops, tablets and smartphones. Provides 12 ready-to-use backend layouts and some grid-layouts. Template is included for a responsive newsletter. TYPO3 editors are able to create nested layouts. Based on the responsive framework Foundation (Zurb). Manual: http://start-typo3-responsive.deEXT:start/doc/manual.pdf. ', 1, 0, 0, 1443044775, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.2.0-7.0.99";}}', 'Dirk Wildt (Die Netzmacher)', 'http://wildt.at.die-netzmacher.de', 'dwildt', 'd28f631ef07f2742ed08d7c1969f7325', '2.1.0  Initial Release', '', 2001001, 0, 0),
(39059, 0, 'start', 1, '2.1.2', 0, 0, 'Start TYPO3 Responsive!', 'Start TYPO3 Responsive! (start) extends TYPO3 with the responsive framework Foundation (Zurb), a dozen responsive Backend Layouts and some responsive Grid Elements. It enables editors, to create responsive nested layouts within a few minutes. It extends some backend forms for controlling the display of content elements depending on devices like smartphones, tablets and desktops. It extends TYPO3 content elements and menus with some helpful responsive Foundation features. A template for a responsive newsletter is included. Manual: http://start-typo3-responsive.deEXT:start/doc/manual.pdf. ', 1, 0, 0, 1443169249, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.2.0-7.0.99";}}', 'Dirk Wildt (Die Netzmacher)', 'http://wildt.at.die-netzmacher.de', 'dwildt', '4b8f7f6454aa577d2e3d807d76d3ec8e', '2.1.2  Improvement: extension description', '', 2001002, 0, 0),
