(39076, 0, 'start', 1, '2.7.3', 0, 0, 'Start TYPO3 Responsive!', 'Start TYPO3 Responsive! (start) extends TYPO3 with the responsive framework Foundation (Zurb), a dozen responsive Backend Layouts and some responsive Gridelements. It enables editors, to create responsive nested layouts within a few minutes. It extends some backend forms for controlling the display of content elements depending on devices like smartphones, tablets and desktops. It extends TYPO3 content elements and menus with some helpful responsive Foundation features. A template for a responsive newsletter is included. Manual: http://start-typo3-responsive.deEXT:start/doc/manual.pdf. ', 1, 0, 6, 1508950535, 'a:3:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.2.0-8.9.99";}s:9:"conflicts";a:1:{s:11:"templavoila";s:0:"";}s:8:"suggests";a:3:{s:12:"gridelements";s:3:"1.0";s:13:"startcustomer";s:5:"2.9.0";s:12:"t3foundation";s:5:"1.6.0";}}', 'Dirk Wildt (Die Netzmacher)', 'http://wildt.at.die-netzmacher.de', 'dwildt', '4f251eadd268c02885880b7d06c5fc91', 'FEATURE: New search form at sitelinetop. See details @ ChangeLog', '', 2007003, 0, 0),
(39077, 0, 'start', 1, '2.7.4', 0, 0, 'Start TYPO3 Responsive!', 'Start TYPO3 Responsive! (start) extends TYPO3 with the responsive framework Foundation (Zurb), a dozen responsive Backend Layouts and some responsive Gridelements. It enables editors, to create responsive nested layouts within a few minutes. It extends some backend forms for controlling the display of content elements depending on devices like smartphones, tablets and desktops. It extends TYPO3 content elements and menus with some helpful responsive Foundation features. A template for a responsive newsletter is included. Manual: http://start-typo3-responsive.deEXT:start/doc/manual.pdf. ', 1, 0, 6, 1510691879, 'a:3:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.2.0-8.9.99";}s:9:"conflicts";a:1:{s:11:"templavoila";s:0:"";}s:8:"suggests";a:3:{s:12:"gridelements";s:3:"1.0";s:13:"startcustomer";s:5:"2.9.0";s:12:"t3foundation";s:5:"1.6.0";}}', 'Dirk Wildt (Die Netzmacher)', 'http://wildt.at.die-netzmacher.de', 'dwildt', '5bba497b1843817727eaf3bcc3c87e1f', 'BUGFIX: Partial bronze: footer.library was missed.', '', 2007004, 1, 0),
(39078, 0, 't3socials', 1, '1.1.0', 0, 0, 'T3 SOCIALS', 'This TYPO3 extension provides an API to communicate with socials networks. So its possible for example to publish newly created news (or whatever you like) directly into social networks.', 1, 0, 5, 1429872700, 'a:1:{s:7:"depends";a:3:{s:3:"php";s:11:"5.0.0-0.0.0";s:7:"rn_base";s:12:"0.14.9-0.0.0";s:5:"typo3";s:12:"4.4.0-6.2.99";}}', 'Michael Wagner, Rene Nitzsche', 'dev@dmk-ebusiness.de', 'dasmedienkombinatgmbh', 'f3255dc299d859c3db233f14e681b735', 'initial release', 'DMK E-BUSINESS GmbH', 1001000, 0, 0),
