(39085, 0, 'mmc_directmail_subscription', 1, '0.9.1', 0, 0, 'MMC directmail subscription', 'Custom direct-mail subscription built with extbase', 1, -1, 3, 1429928398, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:12:"6.2.0-6.2.99";s:10:"tt_address";s:5:"2.3.5";s:11:"direct_mail";s:5:"4.0.1";}}', 'Matthias Mchler', 'maechler@mm-computing.ch', 'thismaechler', '5efd335eb9aa5ae4f0b40177059bf578', 'Initial Upload\r\nBeta, but functional and quite tested\r\nLanguages: en, de, fr, it', '', 9001, 0, 0),
