(39188, 0, 'languagefallback', 1, '1.0.1', 0, 0, 'Full language fallback for TYPO3', 'Full language fallback for TYPO3 including page title and menu to non-default language id. This is not solved in core since 2007! Based on Ext:danp_languagefallback_patch and adopted for TYPO3 6.2.', 2, 0, 4, 1433355194, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.0.0-7.2.99";}}', 'Sven Reuter', '', 't3le', 'cb135c68e7bab98614404ec3e49425ba', 'Full language fallback for TYPO3 including page title and menu to non-default language id. This is not solved in core since 2007! Based on Ext:danp_languagefallback_patch and adopted for TYPO3 6.2.', 'T3LE', 1000001, 0, 0),
(39189, 0, 'languagefallback', 1, '1.0.2', 0, 0, 'Full language fallback for TYPO3', 'Full language fallback for TYPO3 including page title and menu to non-default language id. This is not solved in core since 2007! Based on Ext:danp_languagefallback_patch and adopted for TYPO3 6.2.\n    Just add this to your TS setup:\n    config.sys_language_mode  content_fallback ; 1,0\n    config.sys_language_fallBackOrder  1,0', 2, 0, 4, 1433356181, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.0.0-7.2.99";}}', 'Sven Reuter', '', 't3le', '3256e957b84fd43a1d57a9cc1f17b4a2', 'Full language fallback for TYPO3 including page title and menu to non-default language id. This is not solved in core since 2007! Based on Ext:danp_languagefallback_patch and adopted for TYPO3 6.2.\r\n\r\nJust add this to your TS setup:\r\nconfig.sys_language_m', 'T3LE', 1000002, 0, 0),
(39190, 0, 'languagefallback', 1, '1.0.3', 0, 0, 'Full language fallback for TYPO3', 'Full language fallback for TYPO3 including page title and menu to non-default language id. This is not solved in core since 2007! Based on Ext:danp_languagefallback_patch and adopted for TYPO3 6.2.\n    Just add this to your TS setup:\n    config.sys_language_mode  content_fallback ; 1,0\n    config.sys_language_fallBackOrder  1,0', 2, 0, 4, 1433392110, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.0.0-7.2.99";}}', 'Sven Reuter', '', 't3le', '882a2aec216c9e554763f28183cb9ed9', 'Improved documentation - Im new to this Sphinx stuff ;)', 'T3LE', 1000003, 0, 0),
(39191, 0, 'languagefallback', 1, '1.0.4', 0, 0, 'Full language fallback for TYPO3', 'Full language fallback for TYPO3 including page title and menu to non-default language id. This is not solved in core since 2007! Based on Ext:danp_languagefallback_patch and adopted for TYPO3 6.2.\n    Just add this to your TS setup:\n    config.sys_language_mode  content_fallback ; 1,0\n    config.sys_language_fallBackOrder  1,0', 2, 0, 4, 1433478648, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:13:"6.0.0-7.99.99";}}', 'Sven Reuter', '', 't3le', '71f48222b10ec91709429f3daa964e2d', 'Improved documentation - Im new to this Sphinx stuff ;)\r\nAdded some information to emconf', 'T3LE', 1000004, 0, 0),
(39192, 0, 'languagefallback', 1, '1.0.5', 0, 0, 'Full language fallback for TYPO3', 'Full language fallback for TYPO3 including page title and menu to non-default language id. This is not solved in core since 2007! Based on Ext:danp_languagefallback_patch and adopted for TYPO3 6.2.\n    Just add this to your TS setup:\n    config.sys_language_mode  content_fallback ; 1,0\n    config.sys_language_fallBackOrder  1,0', 2, 0, 4, 1433488182, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:13:"6.0.0-7.99.99";}}', 'Sven Reuter', '', 't3le', 'd17c68ef9f07edd736c5ef34886e7237', 'Improved documentation', 'T3LE', 1000005, 0, 0),
(39193, 0, 'languagefallback', 1, '1.0.6', 0, 0, 'Full language fallback for TYPO3', 'Full language fallback for TYPO3 including page title and menu to non-default language id. This is not solved in core since 2007! Based on Ext:danp_languagefallback_patch and adopted for TYPO3 6.2.\n    Just add this to your TS setup:\n    config.sys_language_mode  content_fallback ; 1,0\n    config.sys_language_fallBackOrder  1,0', 2, 0, 4, 1448204230, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:13:"6.0.0-7.99.99";}}', 'Sven Reuter', '', 't3le', 'e1b68482aadf5fe20d94a0146099485b', 'Bugfix with charset handling. Thanks to Volker Kemeter for the patch!', 'T3LE', 1000006, 1, 0),
