(39240, 0, 'mmc_guestbook', 1, '0.9.3', 0, 0, 'MMC Guestbook', 'Very simple Guestbook built on Extbase/Fluid, using honeypot for spam prevention.', 1, 0, 3, 1435542384, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.2.0-6.2.99";}}', 'Matthias Mchler', 'maechler@mm-computing.ch', 'thismaechler', 'a14adba46a9f970c6833967e298bc01e', 'Initial upload', '', 9003, 0, 0),
(39241, 0, 'mmc_guestbook', 1, '0.9.5', 0, 0, 'MMC Guestbook', 'This is a guestbook built on extbase using several mechanisms to prevent spam (honeypot, form submission time, form html scramble, hashing, security question, redactional review by email, block IP of entries marked as spam)', 1, 0, 3, 1445060299, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.2.0-6.2.99";}}', 'Matthias Mchler', 'maechler@mm-computing.ch', 'thismaechler', '436b572d2a8bde2b20e75e5b9461c13b', '0.9.5\r\n------\r\n\r\nAdded several spam protection features\r\n\r\n- Block form POST replay (spambot-blocker)\r\n- Minimal form submission time (spambot-blocker)\r\n- Form HTML scramble (spambot-blocker)\r\n- Security question (s', '', 9005, 0, 0),
(39242, 0, 'mmc_guestbook', 1, '0.9.6', 0, 0, 'MMC Guestbook', 'This is a guestbook built on extbase using several mechanisms to prevent spam (honeypot, form submission time, form html scramble, hashing, security question, redactional review by email, block IP of entries marked as spam)', 1, 0, 3, 1445061040, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.2.0-6.2.99";}}', 'Matthias Mchler', 'maechler@mm-computing.ch', 'thismaechler', '996d3a21f1298064b45cdb01f6f89aed', '0.9.6\r\n------\r\nBufix (Form was cached)\r\n\r\n0.9.5\r\n------\r\n\r\nAdded several spam protection features\r\n\r\n- Block form POST replay (spambot-blocker)\r\n- Minimal form submission time (spambot-blocker)\r\n- Form HTML scramble', '', 9006, 0, 0),
