(39298, 0, 'toctoccommentssiteban', 1, '1.0.0', 0, 0, 'ASNC Siteban', 'AJAX Social Network Components (ASNC) Siteban allows to ban IPs blocked in EXT:toctoc_comments for website access', 1, 0, 3, 1436990167, 'a:1:{s:7:"depends";a:3:{s:15:"toctoc_comments";s:14:"7.3.0-99.99.99";s:5:"typo3";s:12:"6.0.0-7.3.99";s:3:"php";s:12:"5.3.7-5.6.99";}}', 'Gisele Wendl', 'gisele.wendl@toctoc.ch', 'giselew', 'afcd9d7023765fa1d13e2daeca093f3f', 'IP- oder IP-range based redirects using EXT:toctoc_comments IP-blocklists, initial release\nCompatible TYPO3 newer than version 6, no need for EXT:compatibility6 under TYPO3 7.x\nRequires and automatically installs EXT:toctoc_comments version 7.2.0 or newer', 'TocToc Internetmanagement', 1000000, 0, 0),
(39299, 0, 'toctoccommentssiteban', 1, '1.0.1', 0, 0, 'ASNC Siteban', 'AJAX Social Network Components (ASNC) Siteban allows to ban IPs blocked in EXT:toctoc_comments for website access', 1, 0, 3, 1449690505, 'a:1:{s:7:"depends";a:3:{s:15:"toctoc_comments";s:14:"7.3.0-99.99.99";s:5:"typo3";s:12:"6.0.0-7.9.99";s:3:"php";s:12:"5.3.7-5.6.99";}}', 'Gisele Wendl', 'gisele.wendl@toctoc.ch', 'giselew', 'bae899cd54d98171c90e8cadab359fe7', 'Added TS option badGetVars, part out of GET-Parameters you like to ban. Separate strings with comma ,\nAdded documentation in rst-format\nCompatibility TYPO3 7.6	', 'TocToc Internetmanagement', 1000001, 1, 0),
