(39693, 0, 'contentfce', 1, '1.0.1', 0, 0, 'Provider extension for pages content', 'Provider extension for pages content ', 3, 0, 4, 1447327547, 'a:1:{s:7:"depends";a:5:{s:5:"typo3";s:12:"7.4.0-7.6.99";s:4:"flux";s:0:"";s:10:"fluidpages";s:0:"";s:12:"fluidcontent";s:0:"";s:3:"vhs";s:0:"";}}', 'Vinay', 'nvinayvinay@gmail.com', 'nvinayvinay', '35f9bbea2a4315dd5035e5779deed0ba', 'The extension provides fluidcontent based fluid content elements. The fluid content element added in a page can be exported in the form of DITA  xml file. The Table fluid template helps in creating dynamic table up-to 12 columns.  The main aim of the proj', '', 1000001, 0, 0);
INSERT INTO `tx_extensionmanager_domain_model_extension` (`uid`, `pid`, `extension_key`, `repository`, `version`, `alldownloadcounter`, `downloadcounter`, `title`, `description`, `state`, `review_state`, `category`, `last_updated`, `serialized_dependencies`, `author_name`, `author_email`, `ownerusername`, `md5hash`, `update_comment`, `authorcompany`, `integer_version`, `current_version`, `lastreviewedversion`) VALUES
(39694, 0, 'contentfce', 1, '1.0.2', 0, 0, 'Dustbin', 'The extension provides fluidcontent based fluid content elements. The fluid content element (regular Text Element and Dita content Element) added in a page can be exported in the form of DITA xml files. The Table fluid template helps in creating dynamic table up-to 12 columns. The aim of the project is to add content structurally and to make the content intelligent. Structured content is is development. In future there might be intelligent and channel specific content ', 3, 0, 4, 1455244102, 'a:1:{s:7:"depends";a:5:{s:5:"typo3";s:12:"7.4.0-7.6.99";s:4:"flux";s:0:"";s:10:"fluidpages";s:0:"";s:12:"fluidcontent";s:0:"";s:3:"vhs";s:0:"";}}', 'Vinay', 'nvinayvinay@gmail.com', 'nvinayvinay', '3be67fbecd9454c3683a42918b60b4d0', 'Selected page and subpages are created as Dita file in typo3temp/tx_contentfce. Fluid content element DIta block paragraph is newly added and there are few bug fixes', '', 1000002, 0, 0),
(39695, 0, 'contentfce', 1, '2.0.0', 0, 0, 'Dustbin', 'The extension provides fluidcontent based fluid content elements. The fluid content element (regular Text Element and Dita content Element) added in a page can be exported in the form of DITA xml files. The Table fluid template helps in creating dynamic table up-to 12 columns. The aim of the project is to add content structurally and to make the content intelligent. Structured content is is development. In future there might be intelligent and channel specific content ', 2, 0, 4, 1492950190, 'a:1:{s:7:"depends";a:5:{s:5:"typo3";s:12:"7.6.0-7.6.99";s:4:"flux";s:0:"";s:10:"fluidpages";s:0:"";s:12:"fluidcontent";s:0:"";s:3:"vhs";s:0:"";}}', 'Vinay', 'nvinayvinay@gmail.com', 'nvinayvinay', '33f0e5989ec007113e5d06a77076dda8', 'Selected Page and subpages can be converted to DITA XML files. Only the DITA content will be added to XML file. Content are created based on the order of colPos.  Gives the option to download ZIP directory with all the pages created as DITA XML file. ', '', 2000000, 0, 0),
(39696, 0, 'contentfce', 1, '2.0.1', 0, 0, 'Dustbin', 'The extension provides fluidcontent based fluid content elements. The fluid content element (regular Text Element and Dita content Element) added in a page can be exported in the form of DITA xml files. The Table fluid template helps in creating dynamic table up-to 12 columns. The aim of the project is to add content structurally and to make the content intelligent. Structured content is is development. In future there might be intelligent and channel specific content ', 2, 0, 4, 1493783632, 'a:1:{s:7:"depends";a:5:{s:5:"typo3";s:12:"7.6.0-7.6.99";s:4:"flux";s:5:"7.3.0";s:10:"fluidpages";s:5:"3.4.0";s:12:"fluidcontent";s:5:"4.4.0";s:3:"vhs";s:5:"2.4.0";}}', 'Vinay', 'nvinayvinay@gmail.com', 'nvinayvinay', 'd468073303dbb1158d31194468533c32', 'Added the compatibility version with extension flux,vhsfluidpages and fluidcontent. Issue like DITA Zip file  downloaded without the zip extension is fixed now.', '', 2000001, 1, 0),
