(39764, 0, 't3lephant', 1, '1.0.0', 0, 0, 't3lephant data provider', 'Makes necessary system records in database deployable.', 1, 0, 4, 1448018400, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.2.0-7.6.99";}}', 'Armin Ruediger Vieweg', 'armin@v.ieweg.de', 'professorweb', 'c6872898509286da9d15068d5d44562f', 'Initial upload of t3lephant - data handler. Checkout documentation to see where t3lephant is able to help you: https://goo.gl/3gkiMK', '', 1000000, 1, 0),
(39765, 0, 'dynamic', 1, '0.0.1', 0, 0, 'Dynamic', 'Dynamic approach based on FluidTYPO3.org stack', 1, 0, 4, 1448205109, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:12:"7.6.0-7.6.99";s:10:"fluidpages";s:12:"3.4.0-3.9.99";s:3:"php";s:12:"5.5.0-5.6.99";}}', 'Juan Manuel Vergs Solanas', 'juanmanuel@vergessolanas.es', 'jmverges', '65512b812535422bfbb5b95551d0818f', 'Dynamic approach based on FluidTYPO3.org stack\r\n\r\nProvides a Page Layout for dynamic BE Layouts based on Hans Hchtl post http://blog.1drop.de/en/dynamic-be-layouts-with-fluidtypo3-ideal-for-one-pager/\r\n\r\nBasically you can create a Page Layout with Sectio', '', 1, 0, 0),
