(39767, 0, 'dynamic', 1, '0.0.3', 0, 0, 'Dynamic', 'Dynamic approach based on FluidTYPO3.org stack', 1, 0, 4, 1448282838, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:12:"7.6.0-7.6.99";s:10:"fluidpages";s:12:"3.4.0-3.9.99";s:3:"php";s:12:"5.5.0-5.6.99";}}', 'Juan Manuel Vergs Solanas', 'juanmanuel@vergessolanas.es', 'jmverges', '001f36623b7e952bfb6226789cb0614f', 'Dynamic approach based on FluidTYPO3.org stack\r\nhttps://www.youtube.com/watch?vreVbTvl4X64 \r\nProvides a Page Layout for dynamic BE Layouts based on Hans Hchtl post http://blog.1drop.de/en/dynamic-be-layouts-with-fluidtypo3-ideal-for-one-pager/\r\nBasicall', '', 3, 0, 0),
