(39811, 0, 'mymap', 1, '0.1.5', 0, 0, 'MYMAP', 'Google maps with radial search. Show the results in responsive Google maps, traffic- and bicyling layer included and can be activated via constant editor.', 1, 0, 3, 1448887719, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.2.0-7.6.99";}}', 'Joachim Ruhs', 'postmaster@joachim-ruhs.de', 'joachim_ruhs', 'ed753e4a0e6662df9c810311ab09e5be', 'Ready for TYPO3 7.6.x', '', 1005, 0, 0),
(39812, 0, 'mymap', 1, '0.1.6', 0, 0, 'MYMAP', 'Google maps with radial search. Show the results in responsive Google maps, traffic- and bicyling layer included and can be activated via constant editor.', 1, 0, 3, 1449158307, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.2.0-7.6.99";}}', 'Joachim Ruhs', 'postmaster@joachim-ruhs.de', 'joachim_ruhs', '5ad0fe52379273a17b3d890da114fc22', 'New plugin ajaxSearch implemented. Bugfixes when used with TYPO3 7.6.x and not installed extension compatibility6. For templateRootPath and TYPO3 7.6 see known problems.', '', 1006, 0, 0),
(39813, 0, 'mymap', 1, '0.1.7', 0, 0, 'MYMAP', 'Google maps with radial search. Show the results in responsive Google maps, traffic- and bicyling layer included and can be activated via constant editor.', 1, 0, 3, 1449438120, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.2.0-7.6.99";}}', 'Joachim Ruhs', 'postmaster@joachim-ruhs.de', 'joachim_ruhs', '38fd2e2e467b79a6cc8e999fd2126d87', 'RandomView implemented. Bugfixes in path to upload folder and TCA.', '', 1007, 0, 0),
(39814, 0, 'mymap', 1, '0.2.0', 0, 0, 'MYMAP', 'Google maps with radial search. Show the results in responsive Google maps, traffic- and bicyling layer included and can be activated via constant editor.', 1, 0, 3, 1452436174, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.2.0-7.6.99";}}', 'Joachim Ruhs', 'postmaster@joachim-ruhs.de', 'joachim_ruhs', '827ce6f58e2399806c14e734ee516708', 'Locations categories implemented. Template AjaxSearch modified. Shows all locations in the map when page is loaded. If you want to show only n locations see template and set the page value to 0. If you want to show the search circle the modify the templat', '', 2000, 0, 0),
(39815, 0, 'mymap', 1, '0.2.1', 0, 0, 'MYMAP', 'Google maps with radial search. Show the results in responsive Google maps, traffic- and bicyling layer included and can be activated via constant editor.', 1, 0, 3, 1453565799, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.2.0-7.6.99";}}', 'Joachim Ruhs', 'postmaster@joachim-ruhs.de', 'joachim_ruhs', '2f96e87ceb960dafadeb14381ef82228', 'New field startup implemented. Bugfixes in icon paths when used in subdomains.', '', 2001, 0, 0),
(39816, 0, 'mymap', 1, '0.2.3', 0, 0, 'MYMAP', 'Google maps with radial search. Show the results in responsive Google maps, traffic- and bicyling layer included and can be activated via constant editor.', 1, 0, 3, 1455859092, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.2.0-7.6.99";}}', 'Joachim Ruhs', 'postmaster@joachim-ruhs.de', 'joachim_ruhs', '5f911fae53a6a7f60b70438ef8fc4045', 'New configuration options enableMarkerAnimation and initialMapCoordinates implemented. MapAll list ordered by name ascending.', '', 2003, 0, 0),
(39817, 0, 'mymap', 1, '0.2.4', 0, 0, 'MYMAP', 'Google maps with radial search. Show the results in responsive Google maps, traffic- and bicyling layer included and can be activated via constant editor.', 1, 0, 3, 1455865265, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.2.0-7.6.99";}}', 'Joachim Ruhs', 'postmaster@joachim-ruhs.de', 'joachim_ruhs', '49f8fafa8b728cd054e8e4800014bdb8', 'New configuration options enableMarkerAnimation and initialMapCoordinates implemented. MapAll list ordered by name ascending. Bugfix ASCENDING in mapAll.', '', 2004, 0, 0),
(39818, 0, 'mymap', 1, '0.2.5', 0, 0, 'MYMAP', 'Google maps with radial search. Show the results in responsive Google maps, traffic- and bicyling layer included and can be activated via constant editor.', 1, 0, 3, 1457818340, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"6.2.0-7.6.99";s:3:"vhs";s:5:"2.4.0";}}', 'Joachim Ruhs', 'postmaster@joachim-ruhs.de', 'joachim_ruhs', '8970d3781e8e1783ccf575dba8bdbaac', 'MarkerClusterer implemented, can be activated via constant editor. 2 new fields implemented, images and files. Templates changed. Field images can be used for a gallery of the location.', '', 2005, 0, 0),
(39819, 0, 'mymap', 1, '0.2.6', 0, 0, 'MYMAP', 'Google maps with radial search. Show the results in responsive Google maps, traffic- and bicyling layer included and can be activated via constant editor.', 1, 0, 3, 1465715481, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"6.2.0-7.6.99";s:3:"vhs";s:5:"2.4.0";}}', 'Joachim Ruhs', 'postmaster@joachim-ruhs.de', 'joachim_ruhs', '576d68e646fb9d5f391e70b1f0874e71', 'Goecoding improved with automatic delay, template AjaxSearch and AjaxSearchList modified, shows now number of locations in AjaxSearch categorySelector.', '', 2006, 0, 0),
(39820, 0, 'mymap', 1, '0.2.7', 0, 0, 'MYMAP', 'Google maps with radial search. Show the results in responsive Google maps, traffic- and bicyling layer included and can be activated via constant editor.', 1, 0, 3, 1466870524, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"6.2.0-7.6.99";s:3:"vhs";s:5:"2.4.0";}}', 'Joachim Ruhs', 'postmaster@joachim-ruhs.de', 'joachim_ruhs', 'a4bde96fc7079b954f7d59bc4b9d5ec3', 'Bugfix MarkerClusterer. Clusterer images included to the extension. Templates changed (call to MarkerClusterer with imagePath): MapAll.html, AjaxSeach.html and Search.html.', '', 2007, 0, 0),
(39821, 0, 'mymap', 1, '0.2.9', 0, 0, 'MYMAP', 'Google maps with radial search. Show the results in responsive Google maps, traffic- and bicyling layer included and can be activated via constant editor.', 1, 0, 3, 1468155110, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"6.2.0-7.6.99";s:3:"vhs";s:5:"2.4.0";}}', 'Joachim Ruhs', 'postmaster@joachim-ruhs.de', 'joachim_ruhs', '095285b0bfb00da3e6a4e9a2a3799045', 'Google Browser and Google Server keys implemented. Insert them with the constant editor. Templates changed (loading Google maps API with key). Many changes in template AjaxSearch.html.', '', 2009, 0, 0),
(39822, 0, 'mymap', 1, '0.3.0', 0, 0, 'MYMAP', 'Google maps with radial search. Show the results in responsive Google maps, traffic- and bicycling layer included and can be activated via constant editor.', 1, 0, 3, 1468340084, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"6.2.0-7.6.99";s:3:"vhs";s:5:"2.4.0";}}', 'Joachim Ruhs', 'postmaster@joachim-ruhs.de', 'joachim_ruhs', '594ce462c75fcdffc069cfb08c7da9a6', 'Bugfix in AjaxController (stdClass) - sorry for that. Google Browser and Google Server keys implemented. Insert them with the constant editor. Templates changed (loading Google maps API with key). Many changes in template AjaxSearch.html.. ', '', 3000, 0, 0),
(39823, 0, 'mymap', 1, '0.4.3', 0, 0, 'MyMap', 'Google maps with radial search and hierarchic categories (category tree). Show the results in responsive Google maps, traffic- and bicycling layer included and can be activated via constant editor.', 1, 0, 3, 1474724127, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"7.6.0-7.6.99";s:3:"vhs";s:5:"2.4.0";}}', 'Joachim Ruhs', 'postmaster@joachim-ruhs.de', 'joachim_ruhs', 'd4cdec39dff6f802321fb8996e5bc1c4', 'Hierarchic categories implemented. When updating, you have to reassign categories. Template SearchForm.html and AjaxSearch.html modified.', 'Web Services Ruhs', 4003, 0, 0),
(39824, 0, 'mymap', 1, '0.4.7', 0, 0, 'MyMap', 'Google maps with radial search and hierarchic categories (category tree). Show the results in responsive Google maps, traffic- and bicycling layer included and can be activated via constant editor.', 1, 0, 3, 1478034329, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"7.6.0-8.9.99";s:3:"vhs";s:5:"2.4.0";}}', 'Joachim Ruhs', 'postmaster@joachim-ruhs.de', 'joachim_ruhs', '6cc8cf6eadc46b73b6d889ec51b931ed', 'Ready for TYPO3 8.x. Three new fields added, additionalname, additionaladdress and additionalcontact. Bugfix in typoscript setup.txt. Templates changed, when updating check your templates.', 'Web Services Ruhs', 4007, 0, 0),
(39825, 0, 'mymap', 1, '0.5.1', 0, 0, 'MyMap', 'Google maps with radial search and hierarchic categories (category tree). Show the results in responsive Google maps, traffic- and bicycling layer included and can be activated via constant editor.', 1, 0, 3, 1483117105, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"7.6.0-8.5.99";s:3:"vhs";s:5:"2.4.0";}}', 'Joachim Ruhs', 'postmaster@joachim-ruhs.de', 'joachim_ruhs', 'd2ae44e0dfbb7dd8196f6507d82864aa', 'Bugfix in MapAll.html template (namespace definition map) and tx_mymap_domain_model_location.php.', 'Web Services Ruhs', 5001, 0, 0),
(39826, 0, 'mymap', 1, '0.5.2', 0, 0, 'MyMap', 'Google maps with radial search and hierarchic categories (category tree). Show the results in responsive Google maps, traffic- and bicycling layer included and can be activated via constant editor.', 1, 0, 3, 1485885305, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"7.6.0-8.5.99";s:3:"vhs";s:5:"2.4.0";}}', 'Joachim Ruhs', 'postmaster@joachim-ruhs.de', 'joachim_ruhs', '91fa80c18cee112ffc15180515cfdfe6', 'Bugfix in template AjaxSearch.html, listener for autocompleter implemented and onchange event modified for field city (call to geocodeByClient removed). Missing Google API key implemented in template AutocompleterForm.html.', 'Web Services Ruhs', 5002, 0, 0),
