(39891, 0, 'lib_js_analytics', 1, '0.0.1', 0, 0, 'JS Library: Google Analytics', '', 1, 0, 2, 1450111622, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.2.0-7.6.99";}}', 'Stephan Kellermayr', 'stephan.kellermayr@gmail.com', 'sonority', 'cd711cdbc3324474df076d3a9a777071', 'Initial upload.', 'sonority.at - MULTIMEDIA ART DESIGN', 1, 0, 0),
(39892, 0, 'lib_js_analytics', 1, '0.0.2', 0, 0, 'JS Library: Google Analytics', 'This extension simple integrates googles analytics.js into your website. Configurable with constants-editor and equipped with a scheduler task to periodically download a local copy of analytics.js if you dont want to use Googles CDN.', 1, 0, 2, 1450112789, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.2.0-7.6.99";}}', 'Stephan Kellermayr', 'stephan.kellermayr@gmail.com', 'sonority', 'e77fdabeb233eaa05af8d63dfde56a2f', 'Updated the manual.', 'sonority.at - MULTIMEDIA ART DESIGN', 2, 1, 0),
(39893, 0, 'html5mediaelements', 1, '2.2.0', 0, 0, 'HTML5 Media Elements', 'A media plugin that embeds audio and video files using HTML5 tags and Adobe Flash as a fallback. If the command line utilities "ffmpeg" and "ffprobe" are available on the server, a scheduler task can be configured to convert the source files to web-friendly media formats such as mp4, webm and mp3. The goal is to make embedding local media files as easy as uploading a video to YouTube.', 1, 0, 3, 1450286496, 'a:2:{s:7:"depends";a:1:{s:5:"typo3";s:11:"6.2.0-7.6.0";}s:8:"suggests";a:1:{s:9:"scheduler";s:0:"";}}', 'Simon Praetorius', 'praetorius@wiro-consultants.de', 's2b', '6388519521cd316ece79e88bb419d843', ' More code cleanup\r\n TYPO3 7.6 compatibility\r\n Documentation cleanup\r\n PHPDOC support\r\n Initial public release', '', 2002000, 0, 0),
(39894, 0, 'html5mediaelements', 1, '2.2.1', 0, 0, 'HTML5 Media Elements', 'A media plugin that embeds audio and video files using HTML5 tags and Adobe Flash as a fallback. If the command line utilities "ffmpeg" and "ffprobe" are available on the server, a scheduler task can be configured to convert the source files to web-friendly media formats such as mp4, webm and mp3. The goal is to make embedding local media files as easy as uploading a video to YouTube.', 1, 0, 3, 1450287349, 'a:2:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.2.0-7.6.99";}s:8:"suggests";a:1:{s:9:"scheduler";s:0:"";}}', 'Simon Praetorius', 'praetorius@wiro-consultants.de', 's2b', 'd0b9a05648889d2c03171ef6d9f9208c', ' Correct TYPO3 dependency setting', '', 2002001, 1, 0),
(39895, 0, 'amt_feed_reader', 1, '1.0.0', 0, 0, 'Feed Reader', 'Extension to fetch items from multiple feeds (RSS2 and Atom) and show them on the website', 2, 0, 3, 1450345058, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"6.2.5-6.2.99";s:3:"vhs";s:11:"2.4.0-0.0.0";}}', 'Krzysztof Kasprzyca', 'k.kasprzyca@amtsolution.pl', 'kkasprzyca', '85934d1fa75925c1bc73111672e47136', 'Initial release', '', 1000000, 0, 0),
(39896, 0, 'amt_feed_reader', 1, '1.0.1', 0, 0, 'Feed Reader', 'Extension to fetch items from multiple feeds (RSS2 and Atom) and show them on the website', 2, 0, 3, 1450424574, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"6.2.5-6.2.99";s:3:"vhs";s:11:"2.4.0-0.0.0";}}', 'Krzysztof Kasprzyca', 'k.kasprzyca@amtsolution.pl', 'kkasprzyca', '3a4ac5db76f8fe52dcaed224e7d00e79', '[BUGFIX] Exception when feed is unreachable or its content is incorrect', '', 1000001, 1, 0);
