(39958, 0, 'px_shopware', 1, '1.1.0', 0, 0, 'Shopware Client for TYPO3', 'Provides frontend plugins to render articles, products from shopware systems', 2, 0, 3, 1462269629, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:13:"7.2.0-7.99.99";}}', 'Andr Wuttig', 'support@portrino.de', 'Wuuu', 'abfd4fe64e6023e0f2fd8e003863f942', 'Adds the concept of cache chaining which increases performance by preventing duplicate requests to the Typo3DatabaseCache. Cached API Requests will be searched in TransientMemoryBackend first. \r\n\r\nremoves findById() from getSubCategories() method in c', 'portrino GmbH', 1001000, 0, 0),
(39959, 0, 'px_shopware', 1, '1.0.0', 0, 0, 'Shopware Client for TYPO3', 'Provides frontend plugins to render articles, products from shopware systems', 2, 0, 3, 1461222363, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:13:"7.2.0-7.99.99";}}', 'Andr Wuttig', 'support@portrino.de', 'Wuuu', 'db19163238002d16deecbdeb4e4c665c', 'This extension connects Shopware with TYPO3 CMS. It retrieves data from shopware REST API and provides many frontend plugins to show or list shopware data like articles, categories, etc on your TYPO3 website.\r\n\r\nMore features coming soon!', 'portrino GmbH', 1000000, 0, 0),
(39960, 0, 'px_shopware', 1, '1.2.0', 0, 0, 'Shopware Client for TYPO3', 'Provides frontend plugins to render articles, products from shopware systems', 2, 0, 3, 1462372723, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:13:"7.2.0-7.99.99";}}', 'Andr Wuttig', 'support@portrino.de', 'Wuuu', 'cb345c343e908c37a917583153b98002', 'Enables localization for plugins\r\n\r\nThe correct translation for a given active sys_language will be retrieved via shopware REST API as described here: https://developers.shopware.com/developers-guide/rest-api/api-resource-article/optional-parameters\r\n\r\n', 'portrino GmbH', 1002000, 0, 0),
(39961, 0, 'px_shopware', 1, '1.3.0', 0, 0, 'Shopware Client for TYPO3', 'Provides frontend plugins to render articles, products from shopware systems', 2, 0, 3, 1462802375, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:13:"7.2.0-7.99.99";}}', 'Andr Wuttig', 'support@portrino.de', 'Wuuu', '6d3a52d11f9ab05dc5955d3d694342d2', 'adds possibility to set specific template for plugins via typoscript or flexform\r\n\r\nnew templates could be added or removed easily via pageTS\r\n\r\nsome bugfixes', 'portrino GmbH', 1003000, 0, 0),
(39962, 0, 'px_shopware', 1, '1.5.0', 0, 0, 'Shopware Client for TYPO3', 'Provides frontend plugins to render articles, products from shopware systems', 2, 0, 3, 1466409503, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:13:"7.2.0-7.99.99";}}', 'Andr Wuttig', 'support@portrino.de', 'Wuuu', '2bfdcdf82a0e4f8003a592ea3409c061', 'complete refactoring of localization features\r\n\r\nadds Pi1PageLayoutViewDraw for previewing of px_showare plugin configuration\r\n\r\n', 'portrino GmbH', 1005000, 0, 0),
(39963, 0, 'px_shopware', 1, '1.5.4', 0, 0, 'Shopware Client for TYPO3', 'Provides frontend plugins to render articles, products from shopware systems', 2, 0, 3, 1467122026, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:13:"7.2.0-7.99.99";}}', 'Andr Wuttig', 'support@portrino.de', 'Wuuu', 'f227d215f92bbfa6c89e946b7a07dd23', 'fixes a bug in Pi1PageLayoutViewDraw which leads to exception in backend if no template or not existent template was selected\r\n\r\nadds rowDescription to content elements for px_shopware \r\n\r\nfixes multi-language support for categories\r\n\r\nfixes multi-langu', 'portrino GmbH', 1005004, 0, 0),
(39964, 0, 'px_shopware', 1, '2.0.0', 0, 0, 'Shopware Client for TYPO3', 'Provides frontend plugins to render articles, products from shopware systems', 2, 0, 3, 1474538243, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:13:"7.2.0-7.99.99";}}', 'Andr Wuttig, Sascha Nowak', 'support@portrino.de, sascha.nowak@netlogix.de', 'Wuuu', '42501a4e42f76bc73db5dfec084f6b64', 'Major Release 2.0.0: \r\n\r\nCleanup solr indexing\r\ncachetags for api request\r\ncache tags for articles and categories in list action\r\nnotification interface for shopware\r\nlink handler for products and categories\r\nretrieve orderNumber directly from raw respons', 'portrino, netlogix', 2000000, 0, 0),
