(39986, 0, 'easylogin2', 1, '0.9.6', 0, 0, 'Easylogin', 'Followup of dix_easylogin for TYPO3 7LTS. Use Authentication from facebook, Xing, Google, etc. (everything that uses OAuth or OpenID)', 1, 0, 3, 1452277898, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"7.6.0-7.6.99";}}', 'Markus Kappe', 'markus.kappe@dix.at', 'dix', '3eabab8f25d538210467fbc6558b4cf3', 'Initial upload. Followup of dix_easylogin, just for TYPO3 7.6 LTS. Manual is still missing, but have a look at the constants in the meantime to get an idea of how to configure easylogin2. Reading the manual of dix_easylogin may also help.', '', 9006, 0, 0),
(39987, 0, 'easylogin2', 1, '0.10.0', 0, 0, 'Easylogin', 'Followup of dix_easylogin for TYPO3 7LTS. Use Authentication from facebook, Xing, Google, etc. (everything that uses OAuth or OpenID)', 1, 0, 3, 1500050381, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"7.6.0-7.6.99";}}', 'Markus Kappe', 'markus.kappe@dix.at', 'dix', '2a85e6f51fbe7f8e1dc4a25da564af84', 'Bugfixes: \r\n- commented in a require statement that was accidentially commented out\r\n- adapted the profile configuration for google\r\n- added a signal slot afterUserCreate (DixeasyloginController.php line 318)\r\n- throw an error if registration with the sam', '', 10000, 1, 0),
(39988, 0, 'pc_event_scheduler', 1, '1.0.0', 0, 0, 'Event Scheduler', 'Event scheduler can be used for planning of recurring events. Example: If you are in a small sports club, you could plan weekly games. Members will be able to join or cancel, so other members can see who participates in the game. You can plan vacation schedules, where no events will be scheduled. Last but not least you can notify users that have not accepted or canceled the event yet by email.', 0, 0, 3, 1452440388, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"7.6.0-7.6.99";}}', 'Thomas Poisl', 'thomas@poisl.org', 'poisl', '0fe86935761569d35ee5ee55a16c5a95', 'Event scheduler can be used for planning of recurring events. Example: If you are in a small sports club, you could plan weekly games. Members will be able to join or cancel, so other members can see who participates in the game. You can plan vacation sch', '', 1000000, 0, 0),
(39989, 0, 'pc_event_scheduler', 1, '1.0.1', 0, 0, 'Event Scheduler', 'Event scheduler can be used for planning of recurring events. Example: If you are in a small sports club, you could plan weekly games. Members will be able to join or cancel, so other members can see who participates in the game. You can plan vacation schedules, where no events will be scheduled. Last but not least you can notify users that have not accepted or canceled the event yet by email.', 1, 0, 3, 1452466442, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"7.6.0-7.6.99";}}', 'Thomas Poisl', 'thomas@poisl.org', 'poisl', 'c735e7a9e658c9107dc27712539723e5', 'Mail subject and body have been added to the typoscript setup.\r\n\r\nExtension is fully functional, so the state was changed from alpha to beta.', '', 1000001, 0, 0),
(39990, 0, 'pc_event_scheduler', 1, '1.0.2', 0, 0, 'Event Scheduler', 'Event scheduler can be used for planning of recurring events. Example: If you are in a small sports club, you could plan weekly games. Members will be able to join or cancel, so other members can see who participates in the game. You can plan vacation schedules, where no events will be scheduled. Last but not least you can notify users that have not accepted or canceled the event yet by email.', 1, 0, 3, 1452563080, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"7.6.0-7.6.99";}}', 'Thomas Poisl', 'thomas@poisl.org', 'poisl', '2acd7e7f0610a303e699a8f58c3e2bb3', 'Events in the past can not be accepted or canceled.', '', 1000002, 0, 0),
(39991, 0, 'pc_event_scheduler', 1, '1.0.3', 0, 0, 'Event Scheduler', 'Event scheduler can be used for planning of recurring events. Example: If you are in a small sports club, you could plan weekly games. Members will be able to join or cancel, so other members can see who participates in the game. You can plan vacation schedules, where no events will be scheduled. Last but not least you can notify users that have not accepted or canceled the event yet by email.', 2, 0, 3, 1452636672, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"7.6.0-7.6.99";}}', 'Thomas Poisl', 'thomas@poisl.org', 'poisl', 'd5dcad12ad1fbf737124824cd3c63ef7', 'Added security checks\r\nShow email of participants\r\nPast events can not be modified anymore\r\n\r\nChanged state from beta to stable', '', 1000003, 0, 0),
(39992, 0, 'pc_event_scheduler', 1, '1.0.4', 0, 0, 'Event Scheduler', 'Event scheduler can be used for planning of recurring events. Example: If you are in a small sports club, you could plan weekly games. Members will be able to join or cancel, so other members can see who participates in the game. You can plan vacation schedules, where no events will be scheduled. Last but not least you can notify users that have not accepted or canceled the event yet by email.', 2, 0, 3, 1452792396, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"7.6.0-7.6.99";}}', 'Thomas Poisl', 'thomas@poisl.org', 'poisl', 'e908b1aa7f63e9497fa711b3fc5defc9', 'Added event statistics', '', 1000004, 0, 0),
(39993, 0, 'pc_event_scheduler', 1, '1.0.5', 0, 0, 'Event Scheduler', 'Event scheduler can be used for planning of recurring events. Example: If you are in a small sports club, you could plan weekly games. Members will be able to join or cancel, so other members can see who participates in the game. You can plan vacation schedules, where no events will be scheduled. Last but not least you can notify users that have not accepted or canceled the event yet by email.', 2, 0, 3, 1452867242, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"7.6.0-7.6.99";}}', 'Thomas Poisl', 'thomas@poisl.org', 'poisl', '4fdaa4a495bf18381179973cd0e8e18f', 'New event statistics will now be shown first.', '', 1000005, 0, 0),
(39994, 0, 'pc_event_scheduler', 1, '1.0.6', 0, 0, 'Event Scheduler', 'Event scheduler can be used for planning of recurring events. Example: If you are in a small sports club, you could plan weekly games. Members will be able to join or cancel, so other members can see who participates in the game. You can plan vacation schedules, where no events will be scheduled. Last but not least you can notify users that have not accepted or canceled the event yet by email.', 2, 0, 3, 1453151919, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"7.6.0-7.6.99";}}', 'Thomas Poisl', 'thomas@poisl.org', 'poisl', 'c9d8a59778e570cd3aee9c270159c747', 'Fixed and changed next event calculation\r\n\r\nTS setup changed:\r\n added "eventStartDate"\r\n removed "eventWeekday"', '', 1000006, 0, 0),
(39995, 0, 'pc_event_scheduler', 1, '1.0.7', 0, 0, 'Event Scheduler', 'Event scheduler can be used for planning of recurring events. Example: If you are in a small sports club, you could plan weekly games. Members will be able to join or cancel, so other members can see who participates in the game. You can plan vacation schedules, where no events will be scheduled. Last but not least you can notify users that have not accepted or canceled the event yet by email.', 2, 0, 3, 1484689832, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"7.6.0-7.6.99";}}', 'Thomas Poisl', 'thomas@poisl.org', 'poisl', '5368d6598b3a37407efbe1c5b3ebea5c', 'In recent Typo3 version 7, the way of handling datetime fields was changed.\r\nDatetimes are now converted to UTC before they are stored in the database.\r\nA workaround was introduced, that fixes this problem.\r\nIt might be, that you already have wrong event ', '', 1000007, 1, 0),
