(40052, 0, 'eudoconnect', 1, '2.0.0', 0, 0, 'Eudoconnect', 'Eudoconnect connects Eudonet XRM/CRM with TYPO3.\n	You will be able to send information from TYPO3 to the CRM (Incoming Leads by retrieving directly CRM fields into TYPO3) and receive information with a webservice (Creation of Front-End users which are Contacts in the CRM).', 2, 0, 3, 1454519573, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"6.2.0-6.2.99";s:3:"vhs";s:11:"2.3.0-2.4.0";}}', 'Amrouche Hamza', 'hamza@oblady.fr', 'oblady', 'c4c514e9eaeba277fec5da4e3456a720', 'First upload of Eudonet(Eudoweb) connector.', '', 2000000, 1, 0),
