(40059, 0, 'tgm_copyright', 1, '0.1.3', 0, 0, 'TgM Picture Copyrights', 'This extension will add a copyright field on every image palette and generate a list of all copyright images from the FAL. Additionally the copyright of each image can be shown below it.', 1, 0, 3, 1457428315, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"6.2.0-7.6.99";s:12:"filemetadata";s:12:"6.2.0-7.6.99";}}', 'Paul Beck', 'pb@teamgeist-medien.de', 'paul_beck', 'b389c8223f26c39c7675ffef5ef7259b', 'Fixes: Alternative templating failure, respect rootline, add copyright field to 6.2 metadata, select of non-existing pictures, respect hidden and deleted pages, performance update', '', 1003, 0, 0),
