(40061, 0, 'tgm_copyright', 1, '0.2.0', 0, 0, 'Picture Copyrights and Image Sitemap', 'This extension will add a copyright field on every image palette and can show it below each image. All pictures with a copyright can be listed with a plugin. An Image Sitemap XML for Google of ALL used images can be generated by this extension.', 1, 0, 3, 1458118868, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"6.2.0-7.6.99";s:12:"filemetadata";s:12:"6.2.0-7.6.99";}}', 'Paul Beck', 'pb@teamgeist-medien.de', 'paul_beck', '9650f0916cdab3d73e5f2e4f985056d3', 'BREAKING FEATURE - Image Sitemap Generator; Bugfixes regarding workspaces and expired records (starttime / endtime); extension renaming', '', 2000, 0, 0),
(40062, 0, 'tgm_copyright', 1, '1.0.0', 0, 0, 'Picture Copyrights and Image Sitemap', 'This extension will add a copyright field on every image palette and can show it below each image. All pictures with a copyright can be listed with a plugin. An Image Sitemap XML for Google of ALL used images can be generated by this extension.', 1, 0, 3, 1493378505, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"7.6.0-8.7.99";s:12:"filemetadata";s:12:"7.6.0-8.7.99";}}', 'Paul Beck', 'pb@teamgeist-medien.de', 'paul_beck', '5d9f1c6f7a26ec1ad4d8a6f28cb785c8', 'This version will add configuration options for others extensions like "news" to link copyright images correctly to their belonging records detail view (in the copyright-list and sitemap). Please read the docs to find out more about this feature.', '', 1000000, 0, 0),
