(40113, 0, 'arx_accuweather', 1, '1.0.0', 0, 0, 'Accuweather', 'This extension displays the weather based on accuweather api :\n	- display the weather for the next 4 days for a city\n	- display the current temperature for a few cities from a country with link to see the weather for 4 days\n	- search for a city from a country and display the weather for the next 4 days', 2, 0, 3, 1456490844, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"7.6.0-7.6.99";s:18:"static_info_tables";s:0:"";}}', 'Nikolett Szilagyi', 'nikolett.szilagyi@arxia.com', 'nikiszilagyi', '84b2e719990cf880e4687fcda47e0db4', 'This is the first version of arx_accuweather extension.', '', 1000000, 0, 0),
