(40425, 0, 'http2_push', 1, '0.2.0', 0, 0, 'HTTP/2 Push', 'HTTP/2 Push for TYPO3. Be sure to include extension after scriptmerger if installed. It should be the "last hook".', 1, 0, 4, 1463414244, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.2.0-7.6.99";}}', 'Kevin Lieser', 'info@ka-mediendesign.de', 'caomhan', '466849627aed47e4cf7e7a0e2241c49e', 'Added webserver header length limit setting in extension config. Set this to your webserver header length limit size. If the header is longer than the limit an error 500 occurs.\r\n\r\nDefault limit size for Apache is 8190.', '', 2000, 0, 0),
(40426, 0, 'http2_push', 1, '0.3.0', 0, 0, 'HTTP/2 Push', 'HTTP/2 Push for TYPO3. Be sure to include extension after scriptmerger if installed. It should be the "last hook".', 1, 0, 4, 1473074727, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.2.0-7.6.99";}}', 'Kevin Lieser', 'info@ka-mediendesign.de', 'caomhan', 'db02ebdad53c62e0059d5244b16021ab', 'Added cache breaker timestamps in requested URI.', '', 3000, 0, 0),
