(40461, 0, 'cs_seo', 1, '1.8.4', 0, 0, '[clickstorm] SEO', 'SEO Extension: Enables important on-page features for search engine optimization (SEO). Expands \n						the page settings and any existing records, e.g. with a preview for Google search results (SERP), \n						Open Graph, Twitter Cards and a Focus Keyword. Sitemap.xml and robots.txt handling. Support for \n						Session Tracking (Google Analytics or Piwik) and href"lang" tags. Further features are shown in\n						the extension manual.', 2, 0, 5, 1482416574, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:13:"6.2.0-8.99.99";s:3:"php";s:14:"5.5.0-99.99.99";}}', 'Angela Dudtkowski, Marc Hirdes, Andreas Kirilow - clickstorm GmbH', 'hirdes@clickstorm.de', 'clickstorm_gmbh', '8c1d3e8c31edc9cae7cf1ac45922d35a', '[RELEASE] v. 1.8.4 - bugfix release: href"lang" TypoScript sorting, further small fixes', 'clickstorm GmbH', 1008004, 0, 0),
