(40527, 0, 'maps2', 1, '2.3.0', 0, 0, 'Maps2', 'This extension gives you the possibility to make use of the Google Maps API', 2, 0, 3, 1465940498, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:13:"6.2.0-7.99.99";}}', 'Stefan Froemken', 'projects@jweiland.net', 'jweiland', 'f6ec1068d8712fcd232ea7900c54c99a', 'First upload to TER', 'jweiland.net', 2003000, 0, 0),
(40528, 0, 'maps2', 1, '2.3.4', 0, 0, 'Maps2', 'This extension gives you the possibility to make use of the Google Maps API', 2, 0, 3, 1469095096, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:13:"6.2.0-7.99.99";}}', 'Stefan Froemken', 'projects@jweiland.net', 'jweiland', '84baf8b61f90a5423b987b14a59924a9', '(De-)Activate zoom via mouse scroll wheel. Add PHP 7 support in composer.json. Only show checkboxes for categories which are assigned in plugin. Do not render Area or Route, if there are no pois defined', 'jweiland.net', 2003004, 0, 0),
(40529, 0, 'maps2', 1, '2.6.0', 0, 0, 'Maps2', 'This extension gives you the possibility to make use of the Google Maps API', 2, 0, 3, 1472632136, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:13:"6.2.0-7.99.99";}}', 'Stefan Froemken', 'projects@jweiland.net', 'jweiland', '5763d3fe46091cc60bfa9c9a599d66f1', 'Lower cased cache tables. Now you can implement maps2 multiple time in your own extensions for one record.', 'jweiland.net', 2006000, 0, 0),
