(40531, 0, 'maps2', 1, '2.7.0', 0, 0, 'Maps2', 'This extension gives you the possibility to make use of the Google Maps API', 2, 0, 3, 1483633955, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:13:"6.2.0-8.99.99";}}', 'Stefan Froemken', 'projects@jweiland.net', 'jweiland', 'ef4a563b12bc44134596dfa38a509350', 'We have added a new feature to design the google maps. Updated documentation. Some bugfixes', 'jweiland.net', 2007000, 0, 0),
(40532, 0, 'maps2', 1, '2.9.1', 0, 0, 'Maps2', 'This extension gives you the possibility to make use of the Google Maps API', 2, 0, 3, 1504698613, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:13:"6.2.0-8.99.99";}}', 'Stefan Froemken', 'projects@jweiland.net', 'jweiland', '3f2025d7658139f55c9030d83ae45f15', 'New version due to TER security incident. See https://typo3.org/teams/security/security-bulletins/psa/typo3-psa-2017-001/"', 'jweiland.net', 2009001, 1, 0),
