(40591, 0, 'pitcher', 1, '1.0.0', 0, 0, 'Pitcher', 'Pitcher App (http://www.pitcher-app.com) is a webservice which allows you to easily send exceptions from your project. In contrast to classical monitoring webservices, Pitcher is able to pitch individual exceptions from projects, where Pitcher is acting like a satellite which communicates whith ground control. Register now at pitcher-app.com and create your project. After receiving the secret, the next step is installing the PHP component (or Bundle in case of using Symfony) and linking the satellite by defining the secret.', 2, 0, 3, 1467635379, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.2.0-7.6.99";}}', 'Braune Digital GmbH', 'mail@braune-digital.com', 'hbraune', 'ae2c12a8ba5c439ed6b1f28601395d6c', 'Initial import', '', 1000000, 0, 0),
(40592, 0, 'pitcher', 1, '1.0.1', 0, 0, 'Pitcher', 'Pitcher App (http://www.pitcher-app.com) is a webservice which allows you to easily send exceptions from your project. In contrast to classical monitoring webservices, Pitcher is able to pitch individual exceptions from projects, where Pitcher is acting like a satellite which communicates whith ground control. Register now at pitcher-app.com and create your project. After receiving the secret, the next step is installing the PHP component (or Bundle in case of using Symfony) and linking the satellite by defining the secret.', 2, 0, 3, 1467635803, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.2.0-7.6.99";}}', 'Braune Digital GmbH', 'mail@braune-digital.com', 'hbraune', '8c0f1741be3bbb257c939af62e677d59', 'Initial import', '', 1000001, 0, 0),
