(40611, 0, 'mask_export', 1, '0.9.0', 0, 0, 'Mask Export', 'Export your mask elements as extension', 1, 0, 1, 1494583019, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"7.6.0-8.7.99";s:4:"mask";s:11:"2.0.0-0.0.0";}}', 'Nicole Cordes', 'cordes@cps-it.de', 'cpsitgmbh', 'c97773b82b6c6bc434e46dd4a4ff1640', 'FEATURE: DataProvider for CType restrictions for nested content elements now integrated\r\nBUGFIX: Several bug fixes for 8.7 compatibility of the exported extension\r\nBUGFIX: More bug fixes for colPos DataProvider\r\n\r\nFor more information see ChangeLog.', 'CPS-IT GmbH', 9000, 0, 0),
(40612, 0, 'mask_export', 1, '0.9.1', 0, 0, 'Mask Export', 'Export your mask elements as extension', 1, 0, 1, 1495628529, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"7.6.0-8.7.99";s:4:"mask";s:11:"2.0.0-0.0.0";}}', 'Nicole Cordes', 'cordes@cps-it.de', 'cpsitgmbh', '45c8e88af86aac5d94c0d2c56563f64f', 'Task: Raise compatibility to Mask 3.0.0\r\nBugfix: Use correct SQL for timestamp fields in new tables', 'CPS-IT GmbH', 9001, 1, 0),
(40613, 0, 'social_autopublish', 1, '1.0.1', 0, 0, 'Social Publisher', 'Social Publisher is used to publish your typo3 pages into different social medias like Facebook, Twitter, Linkedin and Xing on a single click.', 2, 0, 3, 1468243456, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.2.0-7.6.99";}}', 'Siju E Raju', 'siju.er@pitsolutions.com', 'pitsolutions_typo3', 'b61c737b87fdcbe810bc23dceebe646c', 'Initial Version', '', 1000001, 0, 0),
(40614, 0, 'social_autopublish', 1, '1.0.2', 0, 0, 'Social Publisher', 'Social Publisher allows to publish your typo3 website content into different social media pages like Facebook, Twitter, Linkedin and Xing. Easy to configure, and also there is an option to test the configurations individually.', 2, 0, 3, 1493097878, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.2.0-8.9.99";}}', 'Siju E Raju', 'typo3support@pitsolutions.com', 'pitsolutions_typo3', '53072420f41dfcd8f5cabf18b5cba492', 'Updated for Typo3 8 LTS', '', 1000002, 1, 0),
(40615, 0, 'templavoila_converter', 1, '0.0.1', 0, 0, 'TemplaVoila! converter', 'The TemplaVoila! converter translates TemplaVoila-Flexform content to TYPO3-TCA content. So you can migrate your TemplaVoila project to a modern TYPO3 version.', 2, 0, 1, 1468474541, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.2.0-7.6.99";}}', 'Gernot Ploiner', 'gp@webprofil.at', 'gernott', '33230d8276759ec781ff858aff058fbe', 'Initial version with informations how to convert.', '', 1, 0, 0),
(40616, 0, 'templavoila_converter', 1, '0.0.2', 0, 0, 'TemplaVoila! converter', 'This extensions exports all necessary tables, if you want to convert from TemplaVoila! to any another system. So you can migrate your TemplaVoila project to a modern TYPO3 version.', 2, 0, 1, 1468575599, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.2.0-7.6.99";}}', 'Gernot Ploiner', 'gp@webprofil.at', 'gernott', '31835ef059eec0d74b9aee1229de0bd9', 'Removed commercial info and links and added export function.', '', 2, 0, 0),
(40617, 0, 'templavoila_converter', 1, '0.0.3', 0, 0, 'TemplaVoila! converter', 'This extensions exports all necessary tables, if you want to convert from TemplaVoila! to any another system. So you can migrate your TemplaVoila project to a modern TYPO3 version.', 2, 0, 1, 1468916705, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.2.0-7.6.99";}}', 'WEBprofil - Gernot Ploiner e.U.', 'office@webprofil.at', 'gernott', 'd6f20a65ba6780262d26198854b5680e', 'More informations about the workflow, better UI', '', 3, 0, 0),
(40618, 0, 'templavoila_converter', 1, '0.0.4', 0, 0, 'TemplaVoila! converter', 'This extension exports all necessary tables, if you want to convert from TemplaVoila! to another system. So you can migrate your TemplaVoila project with the tvconverter to a modern TYPO3 version.', 2, 0, 1, 1469254103, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.2.0-7.6.99";}}', 'WEBprofil - Gernot Ploiner e.U.', 'office@webprofil.at', 'gernott', '7b986d30fedc5d4269a6be1b38c87cf9', 'Text corrections', '', 4, 0, 0),
(40619, 0, 'templavoila_converter', 1, '0.0.5', 0, 0, 'TemplaVoila! converter', 'This extension exports all necessary tables, if you want to convert from TemplaVoila! to another system. So you can migrate your TemplaVoila project with the tvconverter to a modern TYPO3 version.', 2, 0, 1, 1478240684, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.2.0-7.6.99";}}', 'WEBprofil - Gernot Ploiner e.U.', 'office@webprofil.at', 'gernott', 'd1c83fe1d1767049cd91a7244f1ad7ac', 'text corrections', '', 5, 0, 0),
(40620, 0, 'templavoila_converter', 1, '1.0.0', 0, 0, 'TemplaVoila! converter', 'This extension exports all necessary tables, if you want to convert from TemplaVoila! to another system. So you can migrate your TemplaVoila project with the tvconverter to a modern TYPO3 version.', 2, 0, 1, 1506841358, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.2.0-8.7.99";}}', 'Gernot Ploiner', 'office@webprofil.at', 'gernott', 'c2e0a55472345b5dc68083f5f5255592', 'Works now from TYPO3 6.2 to TYPO3 8.7', 'WEBprofil - Gernot Ploiner e.U.', 1000000, 1, 0);
INSERT INTO `tx_extensionmanager_domain_model_extension` (`uid`, `pid`, `extension_key`, `repository`, `version`, `alldownloadcounter`, `downloadcounter`, `title`, `description`, `state`, `review_state`, `category`, `last_updated`, `serialized_dependencies`, `author_name`, `author_email`, `ownerusername`, `md5hash`, `update_comment`, `authorcompany`, `integer_version`, `current_version`, `lastreviewedversion`) VALUES
(40621, 0, 'export', 1, '0.0.1', 0, 0, 'Export Task', 'This extension offers export tasks for the TYPO3 Scheduler which can be extended by other extensions. It is intended to export SQL database tables into files.', 0, 0, 0, 1468608465, 'a:1:{s:7:"depends";a:3:{s:3:"php";s:13:"5.6.0-7.99.99";s:5:"typo3";s:13:"6.2.5-7.99.99";s:7:"div2007";s:12:"1.6.12-0.0.0";}}', 'Franz Holzinger', 'franz@ttproducts.de', 'franzholz', '3193c98b9214a89335b353c9f0158fbd', '\ninitial version: export of the TYPO3 tables into a CSV file.\nThe configuration is done in the Install Tool.\nIt offers hooks for TYPO3 extensions.\n', '', 1, 1, 0),
(40622, 0, 'export_tt_products', 1, '0.0.1', 0, 0, 'Export tt_products Task', 'This extension offers the tt_products export tasks for the Export extension which bases on the Scheduler. The tt_products orders can be saved into a csv file.', 0, 0, 0, 1468609369, 'a:1:{s:7:"depends";a:5:{s:3:"php";s:13:"5.6.0-7.99.99";s:5:"typo3";s:12:"6.2.5-7.6.99";s:7:"div2007";s:12:"1.6.12-0.0.0";s:6:"export";s:11:"0.0.1-0.1.0";s:11:"tt_products";s:11:"1.0.0-0.0.0";}}', 'Franz Holzinger', 'franz@ttproducts.de', 'franzholz', 'ad07cb88dd97ed8c2148a2d9b6222f85', '\ninitial version: export scheduler support for tt_products\nBestellungen table\n', '', 1, 1, 0),
(40623, 0, 'bvt_powermail_pdf', 1, '1.0.0', 0, 0, 'Powermail PDF generator', 'Adds the possibility to download a generated pdf with input data from powermail. This extension is a fork of "bw_powermail_mpdf" which is based on "powermailpdf"', 2, 0, 2, 1468776466, 'a:1:{s:7:"depends";a:5:{s:5:"typo3";s:13:"6.2.7-7.99.99";s:9:"powermail";s:5:"2.1.8";s:7:"extbase";s:13:"6.2.0-7.99.99";s:5:"fluid";s:13:"6.2.0-7.99.99";s:3:"php";s:11:"5.5.0-0.0.0";}}', 'Reinhard Schneidewind', 'info@bluevisiontec.de', 'schnere', 'acbb88e3c15a7924335e48e7526f176d', 'Initial version based on bw_powermail_mpdf 1.0.4 . \r\n fixed: dont flood database with powermail fields\r\n added marker for pdf_link and pdf_url\r\n added marker for powermail_all to use in pdf\r\n added possibility to generate a request id for use in pdf ', 'BlueVisionTec UG (haftungsbeschrnkt)', 1000000, 0, 0),
(40624, 0, 'bvt_powermail_pdf', 1, '1.0.1', 0, 0, 'Powermail PDF generator', 'Adds the possibility to download a generated pdf with input data from powermail. This extension is a fork of "bw_powermail_mpdf" which is based on "powermailpdf"', 2, 0, 2, 1468879738, 'a:1:{s:7:"depends";a:5:{s:5:"typo3";s:13:"6.2.7-7.99.99";s:9:"powermail";s:13:"2.1.8-3.99.99";s:7:"extbase";s:13:"6.2.0-7.99.99";s:5:"fluid";s:13:"6.2.0-7.99.99";s:3:"php";s:11:"5.5.0-0.0.0";}}', 'Reinhard Schneidewind', 'info@bluevisiontec.de', 'schnere', 'f3632fa25da934e89276f9071a9d72e2', 'fixed xml error in translation file. \r\nadded mpdf configuration options. \r\nupdated readme.\r\nchanged supported powermail versions.', 'BlueVisionTec UG (haftungsbeschrnkt)', 1000001, 1, 0),
(40625, 0, 'powermail_fastexport', 1, '1.0.0', 0, 0, 'Powermail FastExport', 'Extend powermail for faster export to .xlsx / .csv files.\nThis is useful if you have many records to be exported.', 2, 0, 0, 1468934395, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"6.2.0-7.6.99";s:9:"powermail";s:11:"3.2.0-0.0.0";}}', 'Markus Mchler, Esteban Marin', 'markus.maechler@bithost.ch, esteban.marin@bithost.ch', 'bithostgmbh', '98e8f2d7efe247d9dfb6ef6c3e696d97', 'This extension extends powermail for faster export to .xlsx / .csv files by\r\nfetching the data directly and\r\nrendering the output directly without Fluid.\r\nThis is useful if you have many records to be exported.\r\nIn our test case with  10000 records to b', '', 1000000, 1, 0),
(40626, 0, 'fluxtemplating', 1, '0.0.1', 0, 0, 'Flux: Website Template', 'Flux Templating with TYPO3 8.2', 0, 0, 4, 1468950423, 'a:1:{s:7:"depends";a:5:{s:5:"typo3";s:12:"7.6.0-8.2.99";s:4:"flux";s:0:"";s:3:"vhs";s:0:"";s:12:"fluidcontent";s:0:"";s:10:"fluidpages";s:0:"";}}', 'Manthan Budheliya', 'manthanbudheliya@gmail.com', 'manthanbudheliya', '94434dee8b045da1076020d019de32bd', 'Flux Templating Method Compatible with 8.2.99', '', 1, 1, 0),
(40627, 0, 'satoshipay', 1, '0.4.1', 0, 0, 'SatoshiPay', 'Integrates SatoshiPay paid content in TYPO3', 1, 0, 3, 1469027335, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"7.6.0-7.6.99";}}', 'Christopher Zechendorf', 'christopher@zechendorf.com', 'zechendorf', '27763e8745ba55b8e1426dd49c6989c1', 'Fresh out of alpha. Everything works, nothing is documented.', '', 4001, 0, 0),
(40628, 0, 'satoshipay', 1, '0.4.2', 0, 0, 'SatoshiPay', 'Integrates SatoshiPay paid content in TYPO3', 1, 0, 3, 1469028751, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"7.6.0-7.6.99";}}', 'Christopher Zechendorf', 'christopher@zechendorf.com', 'zechendorf', 'fe0643cc016ac3039361689adcb3c77e', 'Bugfix version. This thing is still very fresh out of alpha.', '', 4002, 0, 0),
(40629, 0, 'satoshipay', 1, '0.4.3', 0, 0, 'SatoshiPay', 'Integrates SatoshiPay paid content in TYPO3', 1, 0, 3, 1469033511, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"7.6.0-7.6.99";}}', 'Christopher Zechendorf', 'christopher@zechendorf.com', 'zechendorf', '593ce13b5bda746025f64c582508622e', 'Started documentation. I cant stress too much how fresh out of alpha this thing is.', '', 4003, 0, 0),
(40630, 0, 'satoshipay', 1, '0.5.0', 0, 0, 'SatoshiPay', 'Integrates SatoshiPay paid content in TYPO3', 1, 0, 3, 1469085183, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"7.6.0-7.6.99";}}', 'Christopher Zechendorf', 'christopher@zechendorf.com', 'zechendorf', 'eec2fd6193097f74f0aa075a7476a87f', 'Version 0.5.0 now includes full documentation.', '', 5000, 0, 0),
(40631, 0, 'satoshipay', 1, '0.5.1', 0, 0, 'SatoshiPay', 'Earn money with your content: This extension implements SatoshiPay paywall with micro and nanopayments (in Bitcoin).', 1, 0, 3, 1469166669, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"7.6.0-7.6.99";}}', 'Christopher Zechendorf', 'christopher@zechendorf.com', 'zechendorf', 'c152cbc92e7d1461f634b5e64c9af46c', '0.5.1: Now with even more documentation (pdf/github editability) and code cleanup.\r\nMinor upgrade. No added functionality.', '', 5001, 0, 0),
(40632, 0, 'satoshipay', 1, '0.6.0', 0, 0, 'SatoshiPay', 'Earn money with your content: This extension implements SatoshiPay paywall with micro and nanopayments (in Bitcoin).', 1, 0, 3, 1469210772, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"7.6.0-7.6.99";}}', 'Christopher Zechendorf', 'christopher@zechendorf.com', 'zechendorf', 'fd17d94ee72338f2743ae7fd90a41f28', 'New in 0.6.0: Besides paywalling any content element you want (or more than one content element behind one paywall), you now can paywall single images and show a teaser image.', '', 6000, 0, 0),
(40633, 0, 'satoshipay', 1, '0.7.0', 0, 0, 'SatoshiPay', 'Earn money with your content: This extension implements SatoshiPay paywall with micro and nanopayments (in Bitcoin).', 1, 0, 3, 1469212915, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"7.6.0-7.6.99";}}', 'Christopher Zechendorf', 'christopher@zechendorf.com', 'zechendorf', '9c338aaddf240417081d7d54b8d5d503', 'New in 0.7.0: Besides paywalling any content element you want (or more than one content element behind one paywall), you now can:\r\n- paywall single images (and show a teaser image).\r\n- paywall file downloads', '', 7000, 0, 0),
(40634, 0, 'satoshipay', 1, '0.7.1', 0, 0, 'SatoshiPay', 'Earn money with your content: This extension implements SatoshiPay paywall with micro and nanopayments (in Bitcoin).', 1, 0, 3, 1469265662, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"7.6.0-7.6.99";}}', 'Christopher Zechendorf', 'christopher@zechendorf.com', 'zechendorf', 'b6b8844a2531c329b94c7ead09347a00', 'New in 0.7.1: \r\nGraceful handling of images if no teaserimage or no width/height are defined.', '', 7001, 0, 0),
(40635, 0, 'satoshipay', 1, '0.7.2', 0, 0, 'SatoshiPay', 'Earn money with your content: This extension allows you to paywall any content elements, images or file downloads. Paywall provided by SatoshiPay. Micropayments or nanopayments in Bitcoin.', 1, 0, 3, 1469285360, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"7.6.0-7.6.99";}}', 'Christopher Zechendorf', 'christopher@zechendorf.com', 'zechendorf', '345d92fa6718d56fa3dc26c247b9bcd2', '0.7.2 - important bugfix for delivery of paid content', '', 7002, 0, 0),
(40636, 0, 'satoshipay', 1, '1.0.0', 0, 0, 'SatoshiPay', 'Earn money with your content: This extension allows you to paywall any content elements, images or file downloads. Paywall provided by SatoshiPay. Micropayments or nanopayments in Bitcoin.', 2, 0, 3, 1469787462, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"7.6.0-7.6.99";}}', 'Christopher Zechendorf', 'christopher@zechendorf.com', 'zechendorf', '14406e1955c59d92c448b868040ed4ee', 'New in 1.0.0 stable: \r\n Added element to new content element wizard.\r\n Streamlined user experience', '', 1000000, 1, 0),
(40637, 0, 'secure_downloads', 1, '2.0.0', 0, 0, 'Secure Downloads', '"Secure Download": Apply TYPO3 access rights to ALL file assets (PDFs, TGZs or JPGs etc. - configurable) - protect them from direct access.', 1, 0, 2, 1469098592, 'a:2:{s:7:"depends";a:2:{s:3:"php";s:5:"5.5.0";s:5:"typo3";s:12:"6.2.0-8.9.99";}s:9:"conflicts";a:1:{s:12:"naw_securedl";s:0:"";}}', 'Florian Wessels, Helmut Hummel', 'typo3-ext(at)bitmotion.de', 'bitmotion', '6605330940b1c544e97efb15afbd2bbb', 'Initial release of version 2.0.0', '', 2000000, 0, 0),
(40638, 0, 'secure_downloads', 1, '2.0.1', 0, 0, 'Secure Downloads', '"Secure Download": Apply TYPO3 access rights to ALL file assets (PDFs, TGZs or JPGs etc. - configurable) - protect them from direct access.', 1, 0, 2, 1469168933, 'a:2:{s:7:"depends";a:2:{s:3:"php";s:5:"5.5.0";s:5:"typo3";s:12:"6.2.0-8.2.99";}s:9:"conflicts";a:1:{s:12:"naw_securedl";s:0:"";}}', 'Florian Wessels, Helmut Hummel', 'typo3-ext(at)bitmotion.de', 'bitmotion', '9544b1878065c44d7b00a679ec33f517', 'Fix bug in composer.json and move documentation', '', 2000001, 0, 0),
(40639, 0, 'secure_downloads', 1, '2.0.2', 0, 0, 'Secure Downloads', '"Secure Download": Apply TYPO3 access rights to ALL file assets (PDFs, TGZs or JPGs etc. - configurable) - protect them from direct access.', 1, 0, 2, 1469170314, 'a:2:{s:7:"depends";a:2:{s:3:"php";s:12:"5.5.0-7.0.99";s:5:"typo3";s:12:"6.2.0-8.2.99";}s:9:"conflicts";a:1:{s:12:"naw_securedl";s:0:"";}}', 'Florian Wessels, Helmut Hummel', 'typo3-ext(at)bitmotion.de', 'bitmotion', '79fdd947271fa532f29d661122c5d0da', 'Release of version 2.0.2. Contains bugfixes only.', '', 2000002, 0, 0),
(40640, 0, 'secure_downloads', 1, '2.0.3', 0, 0, 'Secure Downloads', '"Secure Download": Apply TYPO3 access rights to ALL file assets (PDFs, TGZs or JPGs etc. - configurable) - protect them from direct access.', 1, 0, 2, 1472572575, 'a:2:{s:7:"depends";a:2:{s:3:"php";s:12:"5.5.0-7.0.99";s:5:"typo3";s:12:"6.2.0-8.3.99";}s:9:"conflicts";a:1:{s:12:"naw_securedl";s:0:"";}}', 'Florian Wessels, Helmut Hummel', 'typo3-ext(at)bitmotion.de', 'bitmotion', '2862f636d45bf3c859f7f4e274d1c7d9', 'Fix regex for parsing html and add raw documentation in rst format.', '', 2000003, 0, 0),
(40641, 0, 'secure_downloads', 1, '2.0.4', 0, 0, 'Secure Downloads', '"Secure Download": Apply TYPO3 access rights to ALL file assets (PDFs, TGZs or JPGs etc. - configurable) - protect them from direct access.', 1, 0, 2, 1491409128, 'a:2:{s:7:"depends";a:2:{s:3:"php";s:12:"5.5.0-7.1.99";s:5:"typo3";s:12:"7.6.0-8.7.99";}s:9:"conflicts";a:1:{s:12:"naw_securedl";s:0:"";}}', 'Florian Wessels, Helmut Hummel', 'typo3-ext@bitmotion.de', 'bitmotion', '6c5f9081ea82d71c552ae276e2cace45', 'First release that supports TYPO3 8 LTS', 'Bitmotion GmbH', 2000004, 0, 0),
