(40716, 0, 'cart', 1, '1.8.3', 0, 0, 'Cart', 'Shopping Cart(s) for TYPO3', 1, 0, 3, 1481411969, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:13:"6.2.0-7.99.99";s:3:"php";s:5:"5.4.0";}}', 'Daniel Lorenz', 'ext.cart@extco.de', 'extcode', '8bcefea735669cea99ecd1210e8c9af8', 'Fix an issue with special prices in Variants. Add some documentation for frontend and backend variants.', 'extco.de UG (haftungsbeschrnkt)', 1008003, 0, 0),
