(40733, 0, 'cart', 1, '3.12.8', 0, 0, 'Cart', 'Shopping Cart(s) for TYPO3', 1, 0, 3, 1502391182, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"6.2.0-8.7.99";s:3:"php";s:5:"5.4.0";}}', 'Daniel Lorenz', 'ext.cart@extco.de', 'extcode', '967d98ba4b4d555ffa011e9a87f5b61d', 'Fix in backend module when generating the invoice document without a generated invoice number.\r\nFix stock handling for backend variants.', 'extco.de UG (haftungsbeschrnkt)', 3012008, 0, 0),
(40734, 0, 'cart', 1, '4.0.8', 0, 0, 'Cart', 'Shopping Cart(s) for TYPO3', 1, 0, 3, 1502391287, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"7.6.0-8.7.99";s:3:"php";s:5:"5.6.0";}}', 'Daniel Lorenz', 'ext.cart@extco.de', 'extcode', 'd068b325175266398aa14ba3360d01ce', 'Fix in backend module when generating the invoice document without a generated invoice number.\r\nFix stock handling for backend variants.\r\nChange the fetching order of the payment and shipping TypoScript configurations.', 'extco.de UG (haftungsbeschrnkt)', 4000008, 0, 0),
