(40784, 0, 'legalinfogen', 1, '0.3.0', 0, 0, 'Legal Info Generator', 'Copy and paste for legal notes on a website sucks. Everyone who writes more than one page a week knows that. With this generator itll take you no more than 5 minutes to get a complete legal notes section.', 2, 0, 3, 1472116455, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:13:"6.2.00-7.6.99";}}', 'Felix Kiesewetter', 'info@felixkiesewetter.de', 'felixkiesewetter', '1bc482e84b84543962e50a95e61eabcb', 'Added some new options to the plugin configuration', '', 3000, 1, 0),
(40785, 0, 'messenger', 1, '0.9.0', 0, 0, 'Send messages to a bunch of people', 'Send emails to a bunch of people. A message is wrapped in a template / layout that the User can freely edit in a BE module.', 1, 0, 3, 1472537381, 'a:1:{s:7:"depends";a:2:{s:4:"vidi";s:0:"";s:5:"typo3";s:12:"7.6.0-7.6.99";}}', 'Fabien Udriot', 'fabien@ecodev.ch', 'ecodev', '6e2333863d9a04c2b7cc2ca1c289d391', 'Release 0.9.0 - https://github.com/fabarea/messenger/compare/0.9.0...master\n\nFirst public release on TER.', '', 9000, 1, 0),
(40786, 0, 'mailing', 1, '0.1.0', 0, 0, 'Mailing list', 'Authenticated FE users can send bunch of messages to a list of recipients. This list is defined as a dynamic selection in a FE module (Vidi).', 1, 0, 3, 1472539849, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:13:"7.6.0-7.99.99";s:4:"vidi";s:11:"2-0.0-0.0.0";s:9:"messenger";s:11:"0.9.0-0.0.0";}}', 'Fabien Udriot', 'fabien@ecodev.ch', 'ecodev', 'a99af6a1267c88758406cc38efe0332d', 'Release 0.1.0 - https://github.com/Ecodev/mailing/compare/0.1.0...master\n\nFirst public release on TER', '', 1000, 1, 0),
