(40804, 0, 'dataviewer', 1, '1.7.1', 0, 0, 'MageDeveloper DataViewer', 'Build easy and intuitive TCA-records (e.g. News, Jobs, Events and more) on the fly without developing a new extension. Only templating is needed; includes many plugins for all kinds of usage!', 2, 0, 3, 1490255169, 'a:1:{s:7:"depends";a:4:{s:5:"typo3";s:12:"7.6.5-8.3.99";s:3:"cms";s:0:"";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Bastian Zagar', 'kontakt@magedeveloper.de', 'breep', '1b4734b4ac27abf232347abdff74bf90', 'Fixed Backend Search Issues; Filter with field value_content now working', '', 1007001, 0, 0),
