(40826, 0, 'quickexplorer', 1, '7.6.0', 0, 0, 'Typo3 Quickexplorer', 'This extension introduces quickexplorer, a with typo3 7.6 compatible version of t3quickexplorer. A backend module that makes you capable of exploring the files and folders of your entire webserver. Browse directories. View and edit ascii files. Create, copy, move, delete, archive files and directories. Download and upload files. Change permissions on files and folders.', 2, 0, 1, 1473269558, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"3.0.0-0.0.0";s:5:"typo3";s:12:"7.6.0-7.6.99";}}', 'Karel Kuijpers', 'karelkuijpers@gmail.com', 'karelkuijpers', '7763adf21d8372329ab348404907175d', 'This a version of t3quixplorer made compatible with typo3 7.6', '', 7006000, 0, 0),
(40827, 0, 'quickexplorer', 1, '7.6.1', 0, 0, 'Typo3 Quickexplorer', 'This extension introduces quickexplorer, a with typo3 7.6 compatible version of t3quixplorer. A backend module that makes you capable of exploring the files and folders of your entire webserver. Browse directories. View and edit ascii files. Create, copy, move, delete, archive files and directories. Download and upload files. Change permissions on files and folders.', 2, 0, 1, 1474291600, 'a:1:{s:7:"depends";a:2:{s:3:"php";s:11:"3.0.0-0.0.0";s:5:"typo3";s:12:"7.6.0-7.6.99";}}', 'Karel Kuijpers', 'karelkuijpers@gmail.com', 'karelkuijpers', 'a3e6a59e4a40b297f5daf206d1fb0b9f', 'Script calling replaced by routeTarget so no more depreciation logs are generated. For security reasons  the module is only accessible by admin users  and browsing of files and folders is limited to the own home directory.', '', 7006001, 1, 0),
