(40961, 0, 'blog', 1, '1.3.0', 0, 0, 'TYPO3 Blog Extension', 'This blog extension use TYPO3s core concepts and elements to provide a full-blown blog that users of TYPO3 can instantly understand and use.', 2, 0, 2, 1491579611, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"7.6.0-8.7.99";}}', 'TYPO3 GmbH', 'info@typo3.com', 'typo3com', '553638d22d262c2b6d90de3668e9547c', '[RELEASE] 1.3.0\r\nEXTBLOG-59	Show only active comments in comments widget\r\nEXTBLOG-68	Limit for Recent Posts Widget\r\nEXTBLOG-71	custom renderType in pagetype blog\r\nEXTBLOG-72	Blog administration module under "Web" for editors\r\nEXTBLOG-78	Title of blog post', '', 1003000, 0, 0),
