(40992, 0, 'facebookpage', 1, '1.0.0', 0, 0, 'Facebook Page', 'Facebook page extension can be used to embed facebook page to site.Website visitors can Like as well as share the facebook page without leaving the website.', 2, 0, 3, 1479198875, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.2.0-8.4.99";}}', 'Aswathy.S', 'aswathy.sh@pitsolutions.com', 'pitsolutions_typo3', 'fff12aed4cff82883afb77c3ee8b81e1', 'facebookpage\r\n\r\nThe Facebook Page extension helps to embed your facebook page into your typo3 site.The website visitors can like as well as share your facebook page without leaving the site.Facebook Page also provides a facebook like and share widget.You ', '', 1000000, 1, 0),
(40993, 0, 'pits_googlecse', 1, '1.0.0', 0, 0, 'Google CSE', 'This extension provides seamless integration of Google Custom Search for your website.With Google Custom Search, add a search box to your homepage to help people find what they need on your website.', 2, 0, 3, 1479199993, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.2.0-8.4.99";}}', 'Anu Bhuvanendran Nair', 'anu.bn@pitsolutions.com', 'pitsolutions_typo3', '044edc29e6b07d3ff6371db1992e236e', 'The best ever search engine now for your website..\r\n\r\nWith Google Custom Search, add a search box to your homepage to help people find what they need on your website with the same technology that drives google search.. Tadaa !!!', '', 1000000, 0, 0),
