(41029, 0, 'nawork_uri', 1, '2.7.4', 0, 0, 'n@work URI', 'A modern, flexible extension for creating and managing urls and redirects in the TYPO3 CMS.', 2, 0, 2, 1480430969, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:13:"6.0.0-7.99.99";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Thorben Kapp', 'kapp@work.de', 'nawork', '0691760316d4b01fad8b008554bcb05d', 'Version with support for 6.2 and 7.6.', 'n@work', 2007004, 0, 0),
(41030, 0, 'nawork_uri', 1, '3.0.0', 0, 0, 'n@work URI', 'A modern, flexible extension for creating and managing urls and redirects in the TYPO3 CMS.', 2, 0, 2, 1480431023, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:13:"7.6.0-8.99.99";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Thorben Nissen', 'thorben@work.de', 'nawork', '9701b68962dc86174ca13017df3566e4', 'Version with support for 7.6 and 8.x.', 'n@work', 3000000, 0, 0),
(41031, 0, 'nawork_uri', 1, '2.7.5', 0, 0, 'n@work URI', 'A modern, flexible extension for creating and managing urls and redirects in the TYPO3 CMS.', 2, 0, 2, 1481989080, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:12:"6.2.0-7.6.99";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Thorben Kapp', 'kapp@work.de', 'nawork', '72e1034b50faee0db8d2513ab6c0685d', ' fixes GitHub issue 6: Clearing configuration cache does not work and throws an error.\r\n fixes static call of non-static method in GeneralUtility\r\n', 'n@work', 2007005, 0, 0),
(41032, 0, 'nawork_uri', 1, '3.0.1', 0, 0, 'n@work URI', 'A modern, flexible extension for creating and managing urls and redirects in the TYPO3 CMS.', 2, 0, 2, 1481989775, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:13:"7.6.0-8.99.99";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Thorben Nissen', 'thorben@work.de', 'nawork', '1a72328bdde0248989f1da1ca8de0110', ' fixes static call of non-static method in GeneralUtility\r\n', 'n@work', 3000001, 0, 0),
(41033, 0, 'nawork_uri', 1, '2.7.6', 0, 0, 'n@work URI', 'A modern, flexible extension for creating and managing urls and redirects in the TYPO3 CMS.', 2, 0, 2, 1487863544, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:13:"6.2.0-7.99.99";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Thorben Kapp', 'kapp@work.de', 'nawork', '2f70caa112af11299c477fd8b83c5a9d', 'Bugfix: Sending correct redirect status when using redirect in 404 handling\r\nTask: Add link to GitHub wiki to readme\r\n', 'n@work', 2007006, 0, 0),
(41034, 0, 'nawork_uri', 1, '3.0.2', 0, 0, 'n@work URI', 'A modern, flexible extension for creating and managing urls and redirects in the TYPO3 CMS.', 2, 0, 2, 1487863976, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:13:"7.6.0-8.99.99";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Thorben Nissen', 'thorben@work.de', 'nawork', '946c5004a8d5662d30d0e3923a0920d3', 'Bugfixes:\r\n Missing field "cruser_id" in sql\r\n Creating urls with backend login not working correctly\r\n Sending correct redirect status when using redirect in 404 handling\r\n URL main module not working correctly in 8.6\r\n URL modules: Context menu not', 'n@work', 3000002, 0, 0),
(41035, 0, 'nawork_uri', 1, '3.1.0', 0, 0, 'n@work URI', 'A modern, flexible extension for creating and managing urls and redirects in the TYPO3 CMS.', 2, 0, 2, 1487921947, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:13:"7.6.0-8.99.99";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Thorben Nissen', 'thorben@work.de', 'nawork', 'b5c58c72b89bcd6502a9577773392362', 'Features:\r\n Introduce configuration parameter AppendIfNotPattern: Allow to disable, e.g. .html if the url matches the given pattern\r\n Advanced 404 handling: Basic support for guessing the language to show the correct language\r\n Exclude doktypes from ', 'n@work', 3001000, 0, 0),
(41036, 0, 'nawork_uri', 1, '2.7.9', 0, 0, 'n@work URI', 'A modern, flexible extension for creating and managing urls and redirects in the TYPO3 CMS.', 2, 0, 2, 1491836835, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:13:"6.2.0-7.99.99";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Thorben Kapp', 'kapp@work.de', 'nawork', '235a094cf6f27c66c69dd9cf138bac8f', ' [BUGFIX] Path field too short\r\n [BUGFIX] Performance improvement in GeneralUtility::getCurrentDomain\r\n [BUGFIX] Encoding leads to endless redirect loop', 'n@work', 2007009, 0, 0),
(41037, 0, 'nawork_uri', 1, '3.0.7', 0, 0, 'n@work URI', 'A modern, flexible extension for creating and managing urls and redirects in the TYPO3 CMS.', 2, 0, 2, 1491836953, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:13:"7.6.0-8.99.99";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Thorben Nissen', 'thorben@work.de', 'nawork', 'e898e059ad008b8520830157493d011a', ' [BUGFIX] 404 with cHash leads to ugly 404 text message\r\n [BUGFIX] Path field too short\r\n [BUGFIX] Performance improvement in GeneralUtility::getCurrentDomain\r\n [BUGFIX] Clear cache menu in 8.7 \r\n [BUGFIX] Encoding leads to endless redirect loop', 'n@work', 3000007, 0, 0),
(41038, 0, 'nawork_uri', 1, '3.1.6', 0, 0, 'n@work URI', 'A modern, flexible extension for creating and managing urls and redirects in the TYPO3 CMS.', 2, 0, 2, 1491837043, 'a:1:{s:7:"depends";a:3:{s:5:"typo3";s:13:"7.6.0-8.99.99";s:7:"extbase";s:0:"";s:5:"fluid";s:0:"";}}', 'Thorben Nissen', 'thorben@work.de', 'nawork', 'ca789b5ef5e736470a75c4c784737e9f', ' [BUGFIX] PHP 5.x compatibility \r\n [BUGFIX] 404 with cHash leads to ugly 404 text message\r\n [BUGFIX] Path field too short\r\n [BUGFIX] Performance improvement in GeneralUtility::getCurrentDomain\r\n [BUGFIX] Clear cache menu in 8.7 \r\n [BUGFIX] Encoding ', 'n@work', 3001006, 1, 0),
(41039, 0, 'min', 1, '1.0.0', 0, 0, 'Minifier for TYPO3', 'Extends TYPO3s compressor for JS and CSS with minifier. This may save you up to 60% of default compressed file size. Full composer support.', 1, 0, 5, 1480600043, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.2.0-8.9.99";}}', 'Armin Vieweg', 'armin@v.ieweg.de', 'professorweb', '6a22c9b47e391138870bb4e609db87db', 'Extends TYPO3s compressor for JS and CSS with minifier. This may save you up to 60% of default compressed file size. Full composer support.', '', 1000000, 0, 0),
(41040, 0, 'min', 1, '1.1.0', 0, 0, 'Minifier for TYPO3', 'Extends TYPO3s compressor for JS and CSS with minifier. This may save you up to 60% of default compressed file size. Full composer support.', 2, 0, 5, 1482971463, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.2.0-8.9.99";}}', 'Armin Vieweg', 'armin@v.ieweg.de', 'professorweb', '7af51c07e7ffe42ba8e468d574abed77', 'Merged EXT:tinysource to min extension. You can configure tinysource as before with this typoscript path "plugin.tx_min.tinysource". So this extension becomes a central collection of tools to minify the output of TYPO3.', '', 1001000, 0, 0),
(41041, 0, 'min', 1, '1.1.1', 0, 0, 'Minifier for TYPO3', 'Extends TYPO3s compressor for JS and CSS with minifier. This may save you up to 60% of default compressed file size. Also compresses HTML output of TYPO3. Full composer support.', 2, 0, 5, 1483020430, 'a:2:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.2.0-8.9.99";}s:9:"conflicts";a:1:{s:10:"tinysource";s:0:"";}}', 'Armin Vieweg', 'armin@v.ieweg.de', 'professorweb', '31ee1616b12113caf0fc9c65afa22f04', 'Some fixes and adjustments', '', 1001001, 0, 0),
(41042, 0, 'min', 1, '1.2.0', 0, 0, 'Minifier for TYPO3', 'Extends TYPO3s compressor for JS and CSS with minifier. This may save you up to 60% of default compressed file size. Also compresses HTML output of TYPO3. Full composer support.', 2, 0, 5, 1488883235, 'a:2:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.2.0-8.9.99";}s:9:"conflicts";a:1:{s:10:"tinysource";s:0:"";}}', 'Armin Vieweg', 'armin@v.ieweg.de', 'professorweb', 'c516188fec125001f1f442a24eeeab5f', 'New Feature: Protected Code\r\n\r\nYou can configure code (using regular expressions) which should be protected.\r\nThose code is not compressed. Important for some tags like "textarea" or "pre", which require whitespaces.', '', 1002000, 0, 0),
(41043, 0, 'min', 1, '1.2.5', 0, 0, 'Minifier for TYPO3', 'Extends TYPO3s compressor for JS and CSS with minifier. COMPATIBILITY RELEASE. Use this version for TYPO3 6.2 only.', 2, 0, 5, 1489959514, 'a:2:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.2.0-8.9.99";}s:9:"conflicts";a:1:{s:10:"tinysource";s:0:"";}}', 'Armin Vieweg', 'armin@v.ieweg.de', 'professorweb', 'b10df38abeff147a33cc3074d04ca61e', 'This is a special release for TYPO3 6.2. Version 1.3 of min drops TYPO3 6.2 compatibility. This version is based on 1.3.0. Bugfixes and improvements applied.', '', 1002005, 0, 0),
(41044, 0, 'min', 1, '1.3.0', 0, 0, 'Minifier for TYPO3', 'Extends TYPO3s compressor for JS and CSS with minifier. This may save you up to 60% of default compressed file size. Also compresses HTML output of TYPO3. Full composer support.', 2, 0, 5, 1489959579, 'a:2:{s:7:"depends";a:1:{s:5:"typo3";s:12:"7.6.0-8.9.99";}s:9:"conflicts";a:1:{s:10:"tinysource";s:0:"";}}', 'Armin Vieweg', 'armin@v.ieweg.de', 'professorweb', '961d7454d5d3a9dac168c2465e5a183d', 'Bugfixes and improvements. This version is for TYPO3 7.6 only. For 6.2 support please use version 1.2.5.', '', 1003000, 0, 0),
(41045, 0, 'min', 1, '1.3.2', 0, 0, 'Minifier for TYPO3', 'Extends TYPO3s compressor for JS and CSS with minifier. This may save you up to 60% of default compressed file size. Also compresses HTML output of TYPO3. Full composer support.', 2, 0, 5, 1493986203, 'a:2:{s:7:"depends";a:1:{s:5:"typo3";s:12:"7.6.0-8.9.99";}s:9:"conflicts";a:1:{s:10:"tinysource";s:0:"";}}', 'Armin Vieweg', 'armin@v.ieweg.de', 'professorweb', '5f064404a3e819f15f5f387520d98a12', 'Fixed major bug in protectCode functionality.', '', 1003002, 0, 0),
(41046, 0, 'min', 1, '1.4.0', 0, 0, 'Minifier for TYPO3', 'Extends TYPO3s compressor for JS and CSS with minifier. This may save you up to 60% of default compressed file size. Also compresses HTML output of TYPO3. Full composer support.', 2, 0, 5, 1510155384, 'a:2:{s:7:"depends";a:1:{s:5:"typo3";s:12:"7.6.0-8.9.99";}s:9:"conflicts";a:1:{s:10:"tinysource";s:0:"";}}', 'Armin Vieweg', 'armin@v.ieweg.de', 'professorweb', '6951e0dbe05674059cf8a1264047b8f2', 'Updated "matthiasmullie/minify" from 1.3.44 - 1.3.55\r\n\r\nFixed major bug when replacing new lines.\r\nWhitespace sensitive html will not break anymore!\r\n\r\nNew "stripSpacesBetweenTags" option added.', '', 1004000, 1, 0),
