(41091, 0, 'cyberpeace', 1, '1.0.0', 0, 0, 'CyberPeace', 'CyberPeace allows to block IPs listed in the abuseipdb.com live-database using .htaccess. You can redirect or block IPs found in EXT:toctoc_comments IP block lists. You can block unwanted crawlers, spiders or bots and bad IPs found in the TYPO3-syslog as well.', 2, 0, 3, 1481388990, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"4.5.0-8.9.99";s:3:"php";s:12:"5.3.7-7.9.99";}}', 'Gisele Wendl', 'gisele.wendl@toctoc.ch', 'giselew', '02bba997ee0875f87afa3b228f58f543', 'Initial release\nReplaces ext:toctoccommentssiteban', 'TocToc Internetmanagement', 1000000, 0, 0),
(41092, 0, 'cyberpeace', 1, '1.0.1', 0, 0, 'CyberPeace', 'CyberPeace allows to block IPs listed in the abuseipdb.com live-database using .htaccess. You can redirect or block IPs found in EXT:toctoc_comments IP block lists. You can block unwanted crawlers, spiders or bots and bad IPs found in the TYPO3-syslog as well.', 2, 0, 3, 1490289179, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"4.5.0-8.9.99";s:3:"php";s:12:"5.3.7-7.9.99";}}', 'Gisele Wendl', 'gisele.wendl@toctoc.ch', 'giselew', '01b94c267afd4f5fefc276a6daf9815d', 'abuseipdb returns on (some) errors a reply which caused the IP to be blocked, fixed now\nNote for the abuseipdb.com-API: the system components curL and NSS need to be installed and updated to the latest version', 'TocToc Internetmanagement', 1000001, 0, 0),
(41093, 0, 'cyberpeace', 1, '1.0.2', 0, 0, 'CyberPeace', 'CyberPeace allows to block IPs listed in the abuseipdb.com live-database using .htaccess. You can redirect or block IPs found in EXT:toctoc_comments IP block lists. You can block unwanted crawlers, spiders or bots and bad IPs found in the TYPO3-syslog as well.', 2, 0, 3, 1492100581, 'a:1:{s:7:"depends";a:2:{s:5:"typo3";s:12:"4.5.0-8.9.99";s:3:"php";s:12:"5.3.7-7.9.99";}}', 'Gisele Wendl', 'gisele.wendl@toctoc.ch', 'giselew', 'f9e2668caaf4716b2419d282bc1b5291', 'Added "TYPO3" to defaults of allowOnlyCrawlerAgentStrings (because of ext:crawler)\nCompatibility with TYPO3 8.7\nNote for the abuseipdb.com-API: SSL is required as NSS installs along with the installation of an SSL certificate\n', 'TocToc Internetmanagement', 1000002, 1, 0),
