(41317, 0, 'datatables', 1, '0.0.1', 0, 0, 'DataTables', 'Integrates the DataTables extension for jQuery.', 0, 0, 3, 1489069545, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"7.6.0-7.6.99";}}', 'Christoph Balogh', 'cb@lustige-informatik.at', 'cbalogh', '941eea85a7bc340bde573d1afbdd73af', 'First release of datatables. ', '', 1, 0, 0),
