(41320, 0, 'datatables', 1, '0.0.4', 0, 0, 'DataTables', 'Integrates the DataTables extension for jQuery.', 1, 0, 3, 1491988057, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"7.6.0-8.9.99";}}', 'Christoph Balogh', 'cb@lustige-informatik.at', 'cbalogh', '6a1072956f730fd6ec859c6e9e3ac47a', 'Changes from 0.0.3:\r\n Compatible with Typo3 7.6.x-8.7.x\r\n User/usergroup restrictions per table/column \r\n Image replacement for integer attribute values\r\n Custom mapping of string attribute values\r\n Bugfixes\r\n\r\n', '', 4, 1, 0),
(41321, 0, 'gsprotectedconfig', 1, '0.0.1', 0, 0, 'GS Protected Config', 'GS Protected Config allows you to import configurations from outside the web directory or override it dependent from application context or CLI mode. Configuration could simply be adapted by the Extension Manager.', 2, 0, 4, 1489188194, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:13:"7.6.0-8.99.99";}}', 'Simon Gilli', 'typo3@gilbertsoft.org', 'gilbertsoft', '5f998f7d131e24c20e3ee82b74ea17e7', 'Initial version', '', 1, 0, 0),
(41322, 0, 'gsprotectedconfig', 1, '0.0.2', 0, 0, 'GS Protected Config', 'GS Protected Config allows you to import configurations from outside the web directory or override it dependent from application context or CLI mode. Configuration could simply be adapted by the Extension Manager.', 2, 0, 4, 1489191428, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:13:"6.2.9-8.99.99";}}', 'Simon Gilli', 'typo3@gilbertsoft.org', 'gilbertsoft', 'd24c3cd7be891ca256f14108e9a6f471', 'Minor changes', '', 2, 0, 0),
(41323, 0, 'gsprotectedconfig', 1, '0.0.3', 0, 0, 'GS Protected Config', 'GS Protected Config allows you to import configurations from outside the web directory or override it dependent from application context or CLI mode. Configuration could simply be adapted by the Extension Manager.', 2, 0, 4, 1489259084, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:13:"6.2.9-8.99.99";}}', 'Simon Gilli', 'typo3@gilbertsoft.org', 'gilbertsoft', '587ddc3b7e05b53910074868ceb90bb9', 'New screenshots of the Extension Manager settings', '', 3, 0, 0),
(41324, 0, 'gsprotectedconfig', 1, '1.0.0', 0, 0, 'GS Protected Config', 'GS Protected Config allows you to import configurations from outside the web directory or override it dependent from application context or CLI mode. Configuration could simply be adapted by the Extension Manager.', 2, 0, 4, 1489427463, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.2.9-8.9.99";}}', 'Simon Gilli', 'typo3@gilbertsoft.org', 'gilbertsoft', 'c3d77a690a2a6c77acdf5ed80305420a', 'Changes:\r\n- improved install and uninstall\r\n- enhanced configuration\r\n\r\nDue to new configurations please check it after update!', '', 1000000, 0, 0),
(41325, 0, 'gsprotectedconfig', 1, '1.1.0', 0, 0, 'GS Protected Config', 'GS Protected Config allows you to import configurations from outside the web directory or override it dependent from application context or CLI mode. Configuration could simply be adapted by the Extension Manager.', 2, 0, 4, 1489438801, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.2.9-8.9.99";}}', 'Simon Gilli', 'typo3@gilbertsoft.org', 'gilbertsoft', '5e949254f83c832314a19fcda560010d', 'Important bug fix\r\n\r\n- 3 Configuration folder is missing\r\n- 2 Install and uninstall is called for every extension', '', 1001000, 0, 0),
(41326, 0, 'gsprotectedconfig', 1, '2.0.0', 0, 0, 'GS Protected Config', 'GS Protected Config allows you to import configurations from outside the web directory or override it dependent from the application context or TYPO3 mode (FE, BE, CLI, AJAX and INSTALL). Configuration could simply be adapted by the Extension Manager and must be activated first!', 2, 0, 4, 1489463615, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.2.9-8.9.99";}}', 'Simon Gilli', 'typo3@gilbertsoft.org', 'gilbertsoft', '19532eee3b724a2c82dc97a03afd16db', 'New modes supported:\r\n- FE\r\n- BE\r\n- AJAX\r\n- INSTALL', '', 2000000, 0, 0),
(41327, 0, 'gsprotectedconfig', 1, '2.0.1', 0, 0, 'GS Protected Config', 'GS Protected Config allows you to import configurations from outside the web directory or override it dependent from the application context or TYPO3 mode (FE, BE, CLI, AJAX and INSTALL). You can use this extension to move the website from dev to testing to production without changing something inside the web root if you place your settings outside. Templates can be found in Resources/Private/Templates. Configuration can simply be adapted by the Extension Manager and must be activated first!', 2, 0, 4, 1489464458, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.2.9-8.9.99";}}', 'Simon Gilli', 'typo3@gilbertsoft.org', 'gilbertsoft', 'e5a9ad17be08e5201e23b83b9b7eb7be', 'New modes supported:\r\n- FE\r\n- BE\r\n- AJAX\r\n- INSTALL', '', 2000001, 0, 0),
(41328, 0, 'gsprotectedconfig', 1, '2.0.2', 0, 0, 'GS Protected Config', 'GS Protected Config allows you to import configurations from outside the web directory or override it dependent from the application context or TYPO3 mode (FE, BE, CLI, AJAX and INSTALL). You can use this extension to move the website from dev to testing to production without changing something inside the web root if you place your settings outside. Templates can be found in Resources/Private/Templates. Configuration can simply be adapted by the Extension Manager and must be activated first!', 2, 0, 4, 1489503965, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"6.2.9-8.9.99";}}', 'Simon Gilli', 'typo3@gilbertsoft.org', 'gilbertsoft', '40a10833b379f605829e9c8a301e8e2a', '- use of GeneralUtility for file read\r\n- delete unused files on uninstall', '', 2000002, 0, 0),
(41329, 0, 'gsprotectedconfig', 1, '3.0.0', 0, 0, 'GS Protected Config', 'GS Protected Config allows you to import configurations from outside the web directory or override it dependent from the application context or TYPO3 mode (FE, BE, CLI, AJAX and INSTALL). You can use this extension to move the website from dev to testing to production without changing something inside the web root if you place your settings outside. Templates can be found in Resources/Private/Templates. Configuration can simply be adapted by the Extension Manager and must be activated first!', 0, 0, 4, 1512504264, 'a:1:{s:7:"depends";a:3:{s:3:"php";s:11:"5.6.0-0.0.0";s:5:"typo3";s:12:"6.2.0-8.9.99";s:5:"gslib";s:11:"0.0.3-0.0.0";}}', 'Simon Gilli', 'typo3@gilbertsoft.org', 'gilbertsoft', '22aca51caf15f4fb4d28be9610467863', '- usage of extension gslib\r\n- caching configuration for CLI moved to new extension gscacheconfig', 'Gilbertsoft', 3000000, 0, 0),
(41330, 0, 'gsprotectedconfig', 1, '3.0.1', 0, 0, 'GS Protected Config', 'GS Protected Config allows you to import configurations from outside the web directory or override it dependent from the application context or TYPO3 mode (FE, BE, CLI, AJAX and INSTALL). You can use this extension to move the website from dev to testing to production without changing something inside the web root if you place your settings outside. Templates can be found in Resources/Private/Templates. Configuration can simply be adapted by the Extension Manager and must be activated first!', 1, 0, 4, 1512509122, 'a:1:{s:7:"depends";a:3:{s:3:"php";s:11:"5.6.0-0.0.0";s:5:"typo3";s:12:"6.2.0-8.9.99";s:5:"gslib";s:11:"0.0.3-0.0.0";}}', 'Simon Gilli', 'typo3@gilbertsoft.org', 'gilbertsoft', 'e6cbebdd216ab10734b16bc8b4cec261', 'First beta release', 'Gilbertsoft', 3000001, 1, 0),
