(41334, 0, 'gswarranty', 1, '8.7.0', 0, 0, 'GS Warranty', 'GS Warranty adapts the TYPO3 backend logos and warranty data and registers a new toolbar item. Feel free to use this extension as base for your own work.', 2, 0, 0, 1512051223, 'a:2:{s:7:"depends";a:1:{s:5:"typo3";s:12:"7.6.0-8.9.99";}s:8:"suggests";a:1:{s:17:"bootstrap_package";s:11:"7.0.0-0.0.0";}}', 'Simon Gilli', 'typo3@gilbertsoft.org', 'gilbertsoft', 'e796f1bc749af0aa125b072fc2fd8cd2', 'Added support for TYPO3 8.7', 'Gilbertsoft', 8007000, 0, 0),
