(41337, 0, 't3twig', 1, '1.0.0', 0, 0, 'T3twig', 'Extend rn_base for using twig templates instead of marker templates', 2, 0, 4, 1489396229, 'a:1:{s:7:"depends";a:2:{s:7:"rn_base";s:6:"1.2.5-";s:5:"typo3";s:13:"7.6.22-7.6.99";}}', 'DMK E-BUSINESS GmbH', 'dev@dmk-ebusiness.de', 'dasmedienkombinatgmbh', 'a8be49d3b09be51ef77446b8e13dfd00', '[ATTENTION] Extension is only runnable with composer installation\r\n\r\nWith this Extension its possible to use Twig as render engine in Typo3 instead of fluid.\r\nAlso you can develop rn_base extensions with twig template instead of marker templates\r\n\r\navaila', 'DMK E-BUSINESS GmbH', 1000000, 0, 0),
(41338, 0, 't3twig', 1, '1.0.1', 0, 0, 'T3twig', 'TYPO3 extension to render page templates with Twig and extend rn_base for using Twig templates instead of marker ', 2, 0, 4, 1489590557, 'a:1:{s:7:"depends";a:2:{s:7:"rn_base";s:6:"1.2.5-";s:5:"typo3";s:13:"7.6.16-7.6.99";}}', 'DMK E-BUSINESS GmbH', 'dev@dmk-ebusiness.de', 'dasmedienkombinatgmbh', '0659be553155ec092f4ce7e8d8a9707c', ' Fix TYPO3 Deps\r\n Fix Documentation', 'DMK E-BUSINESS GmbH', 1000001, 0, 0),
(41339, 0, 't3twig', 1, '1.1.0', 0, 0, 'T3twig', 'TYPO3 extension to render page templates with Twig and extend rn_base for using Twig templates instead of marker ', 2, 0, 4, 1489667168, 'a:1:{s:7:"depends";a:2:{s:7:"rn_base";s:6:"1.2.5-";s:5:"typo3";s:13:"7.6.16-7.6.99";}}', 'DMK E-BUSINESS GmbH', 'dev@dmk-ebusiness.de', 'dasmedienkombinatgmbh', '4eee3d3388e31868db2da8699be04d04', '[ATTENTION] Extension is only runnable with composer installation\r\n breaking changes in t3link and t3url\r\n new t3cObject, t3stdWrap and t3tsRaw functions added\r\nmore @see https://github.com/DMKEBUSINESSGMBH/typo3-t3twig/releases', 'DMK E-BUSINESS GmbH', 1001000, 0, 0),
(41340, 0, 't3twig', 1, '2.0.0', 0, 0, 'T3twig', 'TYPO3 extension to render page templates with Twig and extend rn_base for using Twig templates instead of marker ', 2, 0, 4, 1494570447, 'a:1:{s:7:"depends";a:2:{s:7:"rn_base";s:6:"1.4.0-";s:5:"typo3";s:13:"7.6.16-8.7.99";}}', 'DMK E-BUSINESS GmbH', 'dev@dmk-ebusiness.de', 'dasmedienkombinatgmbh', '893cb9576f7f9c316a56ca59efa370bf', 'Initial TYPO3 8.7 LTS Support\r\nCheck the changelog in the manual ', 'DMK E-BUSINESS GmbH', 2000000, 1, 0),
(41341, 0, 'templavoilaplus', 1, '7.0.0', 0, 0, 'TemplaVoil Plus', 'Point-and-click, popular and easy template engine for TYPO3.', 2, 0, 4, 1489411616, 'a:2:{s:7:"depends";a:3:{s:3:"php";s:12:"5.5.0-7.1.99";s:5:"typo3";s:12:"7.6.0-8.6.99";s:18:"static_info_tables";s:0:"";}s:9:"conflicts";a:6:{s:15:"kb_tv_clipboard";s:6:"-0.1.0";s:14:"templavoila_cw";s:6:"-0.1.0";s:12:"eu_tradvoila";s:6:"-0.0.2";s:20:"me_templavoilalayout";s:0:"";s:21:"me_templavoilalayout2";s:0:"";s:15:"templavoilaplus";s:0:"";}}', 'Alexander Opitz,Benjamin Mack,Tolleiv Nietsch', 'opitz.alexander@pluspol-interactive.de,benni@typo3.org,tolleiv.nietsch@typo3.org', 'opi99', 'da4dafae512ed74ec75f73a32d433e05', 'First release of the new TemplaVoil Plus extension for TYPO3 7/8 LTS releases.\r\n\r\nYou need to run the Migration Script (The update button in ExtensionManager) to fully migrate from TemplaVoil 1.9/2.0.', 'PLUSPOL interactive,,', 7000000, 0, 0),
(41342, 0, 'templavoilaplus', 1, '7.0.1', 0, 0, 'TemplaVoil Plus', 'Point-and-click, popular and easy template engine for TYPO3.', 2, 0, 4, 1489415174, 'a:2:{s:7:"depends";a:3:{s:3:"php";s:12:"5.5.0-7.1.99";s:5:"typo3";s:12:"7.6.0-8.6.99";s:18:"static_info_tables";s:0:"";}s:9:"conflicts";a:6:{s:15:"kb_tv_clipboard";s:6:"-0.1.0";s:14:"templavoila_cw";s:6:"-0.1.0";s:12:"eu_tradvoila";s:6:"-0.0.2";s:20:"me_templavoilalayout";s:0:"";s:21:"me_templavoilalayout2";s:0:"";s:11:"templavoila";s:6:"-3.0.0";}}', 'Alexander Opitz,Benjamin Mack,Tolleiv Nietsch', 'opitz.alexander@pluspol-interactive.de,benni@typo3.org,tolleiv.nietsch@typo3.org', 'opi99', '15d05d7884e770c60605d5dab24300ac', 'First release of the new TemplaVoil Plus extension for TYPO3 7/8 LTS releases.\r\n\r\nYou need to run the Migration Script (The update button in ExtensionManager) to fully migrate from TemplaVoil 1.9/2.0.', 'PLUSPOL interactive,,', 7000001, 0, 0),
(41343, 0, 'templavoilaplus', 1, '7.0.2', 0, 0, 'TemplaVoil Plus', 'Point-and-click, popular and easy template engine for TYPO3. Replacement for old TemplaVoila.', 2, 0, 4, 1490021407, 'a:2:{s:7:"depends";a:3:{s:3:"php";s:12:"5.5.0-7.1.99";s:5:"typo3";s:12:"7.6.0-8.6.99";s:18:"static_info_tables";s:0:"";}s:9:"conflicts";a:7:{s:15:"kb_tv_clipboard";s:6:"-0.1.0";s:14:"templavoila_cw";s:6:"-0.1.0";s:12:"eu_tradvoila";s:6:"-0.0.2";s:20:"me_templavoilalayout";s:0:"";s:21:"me_templavoilalayout2";s:0:"";s:11:"templavoila";s:6:"-3.0.0";s:14:"compatibility6";s:0:"";}}', 'Alexander Opitz,Benjamin Mack,Tolleiv Nietsch', 'opitz.alexander@pluspol-interactive.de,benni@typo3.org,tolleiv.nietsch@typo3.org', 'opi99', 'bb058b69b675f196b503c3db17e02a4b', 'Fixing several small issues in migration and mapping, also some missing renamings. Detailed view under:\r\n\r\nhttps://github.com/pluspol-interactive/templavoilaplus/compare/7.0.1...pluspol-interactive:7.0.2', 'PLUSPOL interactive,,', 7000002, 0, 0),
