(41359, 0, 'skfbalbums', 1, '0.0.3', 0, 0, 'FB Albums', ' Syncs Facebook Page Albums and Photos and displays them on your pages. No actual image files are downloaded. It uses image urls as given by facebook.', 3, 0, 3, 1504698444, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"7.6.0-8.7.99";}}', 'Stefanos Karasavvidis', 'sk@karasavvidis.gr', 'stefos', '804c25b4acf339092728bce24413b090', 'New version due to TER security incident. See https://typo3.org/teams/security/security-bulletins/psa/typo3-psa-2017-001/', '', 3, 0, 0),
(41360, 0, 'skfbalbums', 1, '0.0.4', 0, 0, 'FB Albums', ' Syncs Facebook Page Albums and Photos and displays them on your pages. No actual image files are downloaded. It uses image urls as given by facebook.', 3, 0, 3, 1504699060, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"7.6.0-8.7.99";}}', 'Stefanos Karasavvidis', 'sk@karasavvidis.gr', 'stefos', 'a3f7646057cd3d068f36563f8b2f5252', 'Restore php5.5 compatibility, Plugin can now show a single album. GitHub repo at https://github.com/sksksksk/skfbalbums. Basic documentation at Documentation/readme.txt', '', 4, 0, 0),
(41361, 0, 'skfbalbums', 1, '0.0.1', 0, 0, 'FB Albums', ' Syncs Facebook Page Albums and Photos and displays them on your pages. No actual image files are downloaded. It uses image urls as given by facebook.', 3, -1, 3, 1503746891, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"7.6.0-7.6.99";}}', 'Stefanos Karasavvidis', 'sk@karasavvidis.gr', 'stefos', 'dbad4ebe75b689e23d437c5201d2bb60', 'Initial upload. Still experimental. See Documentation/readme.txt for a quick setup', '', 1, 0, 0),
(41362, 0, 'skfbalbums', 1, '0.0.2', 0, 0, 'FB Albums', ' Syncs Facebook Page Albums and Photos and displays them on your pages. No actual image files are downloaded. It uses image urls as given by facebook.', 3, -1, 3, 1504090250, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"7.6.0-8.7.99";}}', 'Stefanos Karasavvidis', 'sk@karasavvidis.gr', 'stefos', '88a2743abaf388f6b96378ef58aaa4e6', 'Added unitegallery for single album display. Scheduler task clears cache of pages. Added Backend Module that allows to sync albums on demand. Bump TYPO3 version requirements to include 8 LTS. See Documentation/readme.txt for more info and basic installati', '', 2, 0, 0),
(41363, 0, 'skfbalbums', 1, '0.0.5', 0, 0, 'FB Albums', ' Syncs Facebook Page Albums and Photos and displays them on your pages. No actual image files are downloaded. It uses image urls as given by facebook.', 3, 0, 3, 1505293502, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"7.6.0-8.7.99";}}', 'Stefanos Karasavvidis', 'sk@karasavvidis.gr', 'stefos', '5e38af49d9a20cf31afa59d04bd073bd', 'Option for using facebook redirect urls instead of direct CDN urls (smaller images!). Add unigallery init code to the bottom of page to cope for jquery being placed at the bottom', '', 5, 0, 0),
(41364, 0, 'skfbalbums', 1, '0.0.6', 0, 0, 'FB Albums', ' Syncs Facebook Page Albums and Photos and displays them on your pages. No actual image files are downloaded. It uses image urls as given by facebook.', 0, 0, 3, 1505576535, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"7.6.0-8.7.99";}}', 'Stefanos Karasavvidis', 'sk@karasavvidis.gr', 'stefos', 'f671e3e78010599e6b1b7fce6f5806a8', 'Added unitegallery themes support. ', '', 6, 0, 0),
(41365, 0, 'skfbalbums', 1, '0.0.7', 0, 0, 'FB Albums', ' Show Facebook Page Albums and Photos on your site. No actual image files are downloaded. It uses image urls as given by facebook.', 1, 0, 3, 1506281382, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"7.6.0-8.7.99";}}', 'Stefanos Karasavvidis', 'sk@karasavvidis.gr', 'stefos', '6a8ae385c0aa6b46abe8a7007a283f0d', 'When showing a single album, only the albums from the set record storage page are available to choose. More details at http://karasavvidis.gr/skfbalbums/changelog/\r\n', '', 7, 0, 0),
