(41382, 0, 'frontend_editing', 1, '1.0.7', 0, 0, 'Frontend Editing', 'Enable editors to work with the content in the most intuitive way possible', 2, 0, 2, 1494222485, 'a:2:{s:7:"depends";a:3:{s:5:"typo3";s:12:"8.7.0-8.7.99";s:5:"setup";s:12:"8.7.0-8.7.99";s:12:"rte_ckeditor";s:12:"8.7.0-8.7.99";}s:9:"conflicts";a:1:{s:6:"feedit";s:0:"";}}', 'TYPO3 Community', 'typo3cms@typo3.org', 'mattias.nilsson', '3ee58331b28abdc339e380dd10db7c18', 'This release focus on improved handling of creating new content elements, so now there is support for multi column layouts. So from now on the is a possibility to add new content elements to for example a 3 column splitter, to each and one of the columns.', '', 1000007, 0, 0),
(41383, 0, 'frontend_editing', 1, '1.0.8', 0, 0, 'Frontend Editing', 'Enable editors to work with the content in the most intuitive way possible', 2, 0, 2, 1494834917, 'a:2:{s:7:"depends";a:3:{s:5:"typo3";s:12:"8.7.0-8.7.99";s:5:"setup";s:12:"8.7.0-8.7.99";s:12:"rte_ckeditor";s:12:"8.7.0-8.7.99";}s:9:"conflicts";a:1:{s:6:"feedit";s:0:"";}}', 'TYPO3 Community', 'typo3cms@typo3.org', 'mattias.nilsson', '3a9ad108dfe7ddb5ec41b155e6ecd97d', 'This release contains the following fixes:\r\n\r\n Link wizard in rte not working in TYPO3 8.7 LTS\r\n Can not disable "Frontend editing" in User settings', '', 1000008, 0, 0),
(41384, 0, 'frontend_editing', 1, '1.0.9', 0, 0, 'Frontend Editing', 'Enable editors to work with the content in the most intuitive way possible', 2, 0, 2, 1496815898, 'a:2:{s:7:"depends";a:3:{s:5:"typo3";s:12:"8.7.0-8.7.99";s:5:"setup";s:12:"8.7.0-8.7.99";s:12:"rte_ckeditor";s:12:"8.7.0-8.7.99";}s:9:"conflicts";a:1:{s:6:"feedit";s:0:"";}}', 'TYPO3 Community', 'typo3cms@typo3.org', 'mattias.nilsson', 'e01c5d43fe84a6b5b6b7f036021c7f64', 'This release contains the following fixes:\r\n\r\n Make it possible to change content type in Modal popup\r\n Update documentation regarding optional "field" in view helper', '', 1000009, 0, 0),
(41385, 0, 'frontend_editing', 1, '1.1.1', 0, 0, 'Frontend Editing', 'Enable editors to work with the content in the most intuitive way possible', 2, 0, 2, 1499842178, 'a:2:{s:7:"depends";a:3:{s:5:"typo3";s:12:"8.7.0-8.7.99";s:5:"setup";s:12:"8.7.0-8.7.99";s:12:"rte_ckeditor";s:12:"8.7.0-8.7.99";}s:9:"conflicts";a:1:{s:6:"feedit";s:0:"";}}', 'TYPO3 Community', 'typo3cms@typo3.org', 'mattias.nilsson', '43009de9b48bbaefbee60bb7ec9e48da', 'This is a new major release which have focus on better performance and a more slim UI. A big part of the UI changes are related to the inline editing to make it more intuitive.\r\n\r\nMore information here: https://github.com/FriendsOfTYPO3/frontend_editing/r', '', 1001001, 0, 0),
(41386, 0, 'frontend_editing', 1, '1.1.2', 0, 0, 'Frontend Editing', 'Enable editors to work with the content in the most intuitive way possible', 2, 0, 2, 1501479048, 'a:2:{s:7:"depends";a:3:{s:5:"typo3";s:12:"8.7.0-8.7.99";s:5:"setup";s:12:"8.7.0-8.7.99";s:12:"rte_ckeditor";s:12:"8.7.0-8.7.99";}s:9:"conflicts";a:1:{s:6:"feedit";s:0:"";}}', 'TYPO3 Community', 'typo3cms@typo3.org', 'mattias.nilsson', '7894e74bfc22122f9d3118b62f1066e8', 'This release contains fixes that ensure that the Modal always is visible when activated.\r\n\r\n Fix z-index on Modal so it is always on top', '', 1001002, 0, 0),
(41387, 0, 'frontend_editing', 1, '1.1.4', 0, 0, 'Frontend Editing', 'Enable editors to work with the content in the most intuitive way possible', 2, 0, 2, 1505030500, 'a:2:{s:7:"depends";a:3:{s:5:"typo3";s:12:"8.7.0-8.7.99";s:5:"setup";s:12:"8.7.0-8.7.99";s:12:"rte_ckeditor";s:12:"8.7.0-8.7.99";}s:9:"conflicts";a:1:{s:6:"feedit";s:0:"";}}', 'TYPO3 Community', 'typo3cms@typo3.org', 'mattias.nilsson', '1276cf15788be1fa320101484396d2aa', 'This release contains fixes that ensure that the the inline editable mode works in all browsers.\r\n\r\n Fix clunk behaviour for all inline editable elements in browsers\r\n\r\nBIG THANK YOU MOSA!!!', '', 1001004, 0, 0),
(41388, 0, 'frontend_editing', 1, '1.2.0', 0, 0, 'Frontend Editing', 'Enable editors to work with the content in the most intuitive way possible', 2, 0, 2, 1505130059, 'a:2:{s:7:"depends";a:3:{s:5:"typo3";s:12:"8.7.0-8.7.99";s:5:"setup";s:12:"8.7.0-8.7.99";s:12:"rte_ckeditor";s:12:"8.7.0-8.7.99";}s:9:"conflicts";a:1:{s:6:"feedit";s:0:"";}}', 'TYPO3 Community', 'typo3cms@typo3.org', 'mattias.nilsson', '619d70b7d7d967e97aca30b741bd1d77', 'New page tree! Release notes can be found here: https://github.com/FriendsOfTYPO3/frontend_editing/releases/tag/v1.2.0', '', 1002000, 0, 0),
