(41390, 0, 'frontend_editing', 1, '1.2.2', 0, 0, 'Frontend Editing', 'Enable editors to work with the content in the most intuitive way possible', 2, 0, 2, 1505840274, 'a:2:{s:7:"depends";a:3:{s:5:"typo3";s:12:"8.7.0-8.7.99";s:5:"setup";s:12:"8.7.0-8.7.99";s:12:"rte_ckeditor";s:12:"8.7.0-8.7.99";}s:9:"conflicts";a:1:{s:6:"feedit";s:0:"";}}', 'TYPO3 Community', 'typo3cms@typo3.org', 'mattias.nilsson', '45599ec4913bcc9fba7431c34627fb7e', 'This release contains a fix that makes it possible to be a simple editor when using the editing mode. Other fixes are:\r\n\r\n Drop Composer installation instructions\r\n Improve security by not using $_SERVER directly\r\n', '', 1002002, 0, 0),
(41391, 0, 'frontend_editing', 1, '1.2.3', 0, 0, 'Frontend Editing', 'Enable editors to work with the content in the most intuitive way possible', 2, 0, 2, 1507478315, 'a:2:{s:7:"depends";a:3:{s:5:"typo3";s:12:"8.7.0-8.7.99";s:5:"setup";s:12:"8.7.0-8.7.99";s:12:"rte_ckeditor";s:12:"8.7.0-8.7.99";}s:9:"conflicts";a:1:{s:6:"feedit";s:0:"";}}', 'TYPO3 Community', 'typo3cms@typo3.org', 'mattias.nilsson', 'fe949cbaaa6273182d36f999357821b5', 'This release contains cleanup for the save button options in the modal backed view.\r\n\r\n Remove "save and view" button from editing page properties\r\n Replace D3 page tree circles with triangles that acts similar to TYPO3 page tree', '', 1002003, 0, 0),
(41392, 0, 'frontend_editing', 1, '1.2.4', 0, 0, 'Frontend Editing', 'Enable editors to work with the content in the most intuitive way possible', 2, 0, 2, 1508087988, 'a:2:{s:7:"depends";a:3:{s:5:"typo3";s:12:"8.7.0-8.7.99";s:5:"setup";s:12:"8.7.0-8.7.99";s:12:"rte_ckeditor";s:12:"8.7.0-8.7.99";}s:9:"conflicts";a:1:{s:6:"feedit";s:0:"";}}', 'TYPO3 Community', 'typo3cms@typo3.org', 'mattias.nilsson', '57f47c3f4deaa6a89d7c6c84b79b01fb', 'This release contains small UI cleanups that improve the editor experience.\r\n\r\n Move back button to user drop down menu\r\n Show the top bar of all Modals', '', 1002004, 0, 0),
(41393, 0, 'frontend_editing', 1, '1.2.5', 0, 0, 'Frontend Editing', 'Enable editors to work with the content in the most intuitive way possible', 2, 0, 2, 1512672781, 'a:2:{s:7:"depends";a:3:{s:5:"typo3";s:12:"8.7.0-8.7.99";s:5:"setup";s:12:"8.7.0-8.7.99";s:12:"rte_ckeditor";s:12:"8.7.0-8.7.99";}s:9:"conflicts";a:1:{s:6:"feedit";s:0:"";}}', 'TYPO3 Community', 'typo3cms@typo3.org', 'mattias.nilsson', '05bf3e60df15574f1aa306c077226338', 'This release contains the following fixes and improvements:\r\n\r\n Fix fetching null as id for page to get all the correct Content elements for the page\r\n Update nimut/testing-framework to version 2.0\r\n Add possibility to include javascript in to window\r\n', '', 1002005, 1, 0),
