(41435, 0, 'yoast_seo', 1, '1.1.0', 0, 0, 'Yoast SEO', '', 2, 0, 4, 1500557265, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:13:"7.6.13-8.7.99";}}', 'Yoast SEO for TYPO3', '', 'yoast', '603ffaa527252d7db097a4acb2eefaa8', 'This update contains several new features and bugfixes:\r\n\r\nTasks\r\n- Updated Yoast libraries\r\n- Added configuration for allowed doktypes\r\n- Added Danish translation\r\n- Separate SEO title field\r\n- Possibility to add default Facebook / Twitter image\r\n\r\n', 'MaxServ B.V., Yoast', 1001000, 0, 0),
(41436, 0, 'yoast_seo', 1, '1.1.1', 0, 0, 'Yoast SEO', '', 2, 0, 4, 1500617511, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:13:"7.6.13-8.7.99";}}', 'Yoast SEO for TYPO3', '', 'yoast', '5af971431db9ff815f3980bdd3da36d8', 'Bugfix release fixing problems with savind the focus keyword.\r\n', 'MaxServ B.V., Yoast', 1001001, 0, 0),
