(41607, 0, 'azurestorage', 1, '0.3.1', 0, 0, 'Azure Storage', 'Microsoft Azure Blob Storage to TYPO3', 1, 0, 0, 1496856541, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"7.6.0-8.9.99";}}', 'Benjamin Hirsch', 'mail@benjaminhirsch.net', 'benjaminhirsch', '78421bbf6e00be92165916317a15f117', 'Added\r\n- Paging for files and Folders\r\n\r\nChanged\r\n- Changed the behaviour for retrieving blobs. For most of API calls, only the meta data is fetched, which ends up in a good improvement performance wise\r\n\r\nRemoved\r\n- Nothing\r\n\r\nDeprecated\r\n- Nothing\r\n\r\nFi', '', 3001, 0, 0),
(41608, 0, 'azurestorage', 1, '0.3.2', 0, 0, 'Azure Storage', 'Microsoft Azure Blob Storage to TYPO3', 1, 0, 0, 1499772762, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"7.6.0-8.9.99";}}', 'Benjamin Hirsch', 'mail@benjaminhirsch.net', 'benjaminhirsch', '1c5c49f3267f18c914a647cad2c5639f', 'Special file extensions like youtube or vimeo are now getting respected while adding it to the storage. The mimetype is now set properly. Allow hyphens in containerName, eg. "my-container"', '', 3002, 0, 0),
