(41611, 0, 'livechatinc', 1, '1.0.0', 0, 0, 'Livechat Inc', 'Integrate the Live Chat from www.livechatinc.com in your TYPO3 Page. \nYou need an an account created at https://www.livechatinc.com', 1, 0, 5, 1496866997, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"8.6.0-8.7.99";}}', 'Benjamin Riezler', 'typo3@pixel-ink.de', 'pixelink', 'e1657caf9de88e135bf472bbf4a5edf5', 'Install LiveChat on your TYPO3 Website to quickly place a chat function on your website. Start chatting with visitors within a few clicks.\r\n\r\nAttention: A www.livechatinc.com account with an active plan is required.', '', 1000000, 0, 0),
(41612, 0, 'livechatinc', 1, '1.0.1', 0, 0, 'LiveChat', 'LiveChat  live chat software and help desk software for customer service. Live chat allows website visitors to contact you in real-time. Help desk software is used to online visitors find what they need before they leave your site.\nYou can try LiveChat free for 30 days! If you are interested you can signup here: https://www.livechatinc.com/signup/\nIf you nev: http://www.livechatinc.com/why-livechat/\nThe extension requires active LiveChat subscription after 30 days of free trial.', 1, 0, 5, 1502180550, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"8.6.0-8.7.99";}}', 'Benjamin Riezler', 'typo3@pixel-ink.de', 'pixelink', '1260076fb2496b8517c3201c4eb497ce', 'Updated title and description', '', 1000001, 1, 0),
