(41669, 0, 'fbit_berecordlist', 1, '1.0.1', 0, 0, 'BE Record Lists', 'Creates modules to view individual record lists.', 2, 0, 1, 1500034418, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"8.6.0-8.7.99";}}', 'Grigori Prokhorov', 'hello@feinberg.it', 'grigori.prokhorov', 'beac4774350da871681e9be561d59ead', 'This extension provides a "generator" for backend modules which are intended to list one or more types of records.', '', 1000001, 0, 0),
(41670, 0, 'fbit_berecordlist', 1, '1.0.2', 0, 0, 'BE Record Lists', 'Creates modules to view individual record lists.', 2, 0, 1, 1500056280, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"8.6.0-8.7.99";}}', 'Grigori Prokhorov', 'hello@feinberg.it', 'grigori.prokhorov', 'c98e9813f5c757d16fbc73889690c14e', 'Add backend requireJS module to append extension key to all forms in web_list module to re-enable search and other functions.', '', 1000002, 0, 0),
(41671, 0, 'fbit_berecordlist', 1, '1.0.3', 0, 0, 'BE Record Lists', 'Creates modules to view individual record lists.', 2, 0, 1, 1500284369, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"8.6.0-8.7.99";}}', 'Grigori Prokhorov', 'hello@feinberg.it', 'grigori.prokhorov', 'b96459781080609567a6fbff7483331b', 'Extend JS module to also append extension key to relevant links (this means more features working like expected).\r\n\r\nMoved repository to Github due to instability of original repository web interface. Please add issues, pull requests and comments at https', '', 1000003, 0, 0),
(41672, 0, 'fbit_berecordlist', 1, '1.0.4', 0, 0, 'BE Record Lists', 'Creates modules to view individual record lists.', 2, 0, 1, 1500290386, 'a:1:{s:7:"depends";a:1:{s:5:"typo3";s:12:"8.6.0-8.7.99";}}', 'Grigori Prokhorov', 'hello@feinberg.it', 'grigori.prokhorov', '5cb58133fe078248ab3a48e396b44a69', 'PLEASE UPDATE.\r\n\r\nAvoid killing of the web_list module - exit silently if no extension-parameter is found.', '', 1000004, 0, 0),
